BEGIN;

-- 1. CREATE TABLES

CREATE TABLE IF NOT EXISTS public.decks (
  id TEXT PRIMARY KEY,
  user_id UUID,
  title TEXT NOT NULL,
  description TEXT,
  category TEXT,
  color TEXT,
  icon TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.flashcards (
  id TEXT PRIMARY KEY,
  deck_id TEXT REFERENCES public.decks(id) ON DELETE CASCADE,
  user_id UUID,
  front TEXT NOT NULL,
  back TEXT NOT NULL,
  rationale TEXT,
  options JSONB,
  tags JSONB,
  ndle_subject TEXT,
  difficulty TEXT,
  leitner_box INTEGER DEFAULT 1,
  user_notes TEXT,
  sm2 JSONB,
  last_reviewed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.playlists (
  id TEXT PRIMARY KEY,
  user_id UUID,
  title TEXT NOT NULL,
  description TEXT,
  deck_ids TEXT[],
  color TEXT,
  icon TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.study_sessions (
  id TEXT PRIMARY KEY,
  user_id UUID,
  deck_id TEXT NOT NULL,
  deck_title TEXT NOT NULL,
  mode TEXT NOT NULL,
  current_index INTEGER DEFAULT 0,
  is_completed BOOLEAN DEFAULT false,
  timer_duration_seconds INTEGER DEFAULT 0,
  cards_queue JSONB DEFAULT '[]'::jsonb,
  results JSONB DEFAULT '[]'::jsonb,
  start_time BIGINT,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.study_logs (
  id TEXT PRIMARY KEY,
  user_id UUID,
  card_id TEXT NOT NULL,
  deck_id TEXT,
  mode TEXT,
  rating TEXT,
  user_answer TEXT,
  is_correct BOOLEAN DEFAULT false,
  time_spent_seconds INTEGER DEFAULT 0,
  verdict TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.user_preferences (
  user_id UUID PRIMARY KEY DEFAULT '00000000-0000-0000-0000-000000000001',
  preferences JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.ai_explanation_cache (
  id TEXT PRIMARY KEY,
  question_text TEXT,
  user_answer TEXT,
  is_correct BOOLEAN DEFAULT TRUE,
  ai_explanation JSONB,
  question_hash TEXT,
  front_text TEXT,
  back_text TEXT,
  options JSONB,
  explanation TEXT,
  breakdown JSONB,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. TRUNCATE OLD DATA
TRUNCATE TABLE public.study_logs, public.study_sessions, public.flashcards, public.decks, public.playlists, public.user_preferences, public.ai_explanation_cache CASCADE;

