-- 4. INSERT FLASHCARDS
INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('card-bio-5', 'deck-biochem-vitamins', 'Which amino acid serves as the biological precursor for endogenous synthesis of Niacin (NAD/NADP)?', 'Tryptophan', 'Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).', '["Tryptophan","Tyrosine","Phenylalanine","Methionine"]'::jsonb, '["Biochemistry","AminoAcids","Niacin"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:41:17.235Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-12T09:41:17.235Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:41:17.313Z"'::jsonb),
('card-bio-1', 'deck-biochem-vitamins', 'Wernicke-Korsakoff syndrome and Beriberi are caused by a severe deficiency of which water-soluble vitamin?', 'Thiamine (Vitamin B1)', 'Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.', '["Thiamine (Vitamin B1)","Riboflavin (Vitamin B2)","Niacin (Vitamin B3)","Pyridoxine (Vitamin B6)"]'::jsonb, '["Vitamins","B1","Deficiency"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:40:49.597Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:40:49.597Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:40:49.688Z"'::jsonb),
('card-bio-2', 'deck-biochem-vitamins', 'What are the classic "4 Ds" characteristic of severe Pellagra (Niacin / Vitamin B3 deficiency)?', 'Dermatitis, Diarrhea, Dementia, and Death', 'Pellagra presents with the 4 Ds: Photosensitive symmetrical Dermatitis (Casal necklace), Diarrhea, Dementia/delirium, and Death if untreated. 60 mg of dietary tryptophan can synthesize approximately 1 mg of niacin in the liver.', '["Dermatitis, Diarrhea, Dementia, and Death","Dyspnea, Dysphagia, Dysuria, and Dehydration","Dizziness, Depression, Dyspepsia, and Dermatitis","Diplopia, Dysarthria, Dysphagia, and Dysmetria"]'::jsonb, '["Niacin","B3","Pellagra"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:39:05.042Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:39:05.042Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:39:05.119Z"'::jsonb),
('card-bio-3', 'deck-biochem-vitamins', 'Vitamin C (Ascorbic Acid) is an essential cofactor for which enzymatic reaction during collagen biosynthesis?', 'Hydroxylation of Proline and Lysine residues', 'Ascorbic acid maintains iron in its ferrous (Fe2+) state, serving as a reducing agent for prolyl hydroxylase and lysyl hydroxylase. Without it, defective triple-helix collagen fibers fail to crosslink, leading to Scurvy (fragile capillaries, bleeding gums, impaired wound healing).', '["Hydroxylation of Proline and Lysine residues","Decarboxylation of Glutamate to GABA","Methylation of Homocysteine to Methionine","Transamination of Alanine to Pyruvate"]'::jsonb, '["Vitamin C","Collagen","Enzyme"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:41:27.390Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-12T09:41:27.390Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:41:27.467Z"'::jsonb),
('card-bio-4', 'deck-biochem-vitamins', 'Where is the Vitamin B12 (Cobalamin) – Intrinsic Factor complex primarily absorbed in the human gastrointestinal tract?', 'Terminal Ileum', 'Dietary B12 binds haptocorrin in saliva/gastric juice, is transferred to gastric parietal cell-secreted Intrinsic Factor (IF) in the duodenum, and the intact B12-IF complex is absorbed via cubam receptors in the Terminal Ileum.', '["Terminal Ileum","Duodenum","Proximal Jejunum","Ascending Colon"]'::jsonb, '["B12","GI","Absorption"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:40:42.833Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:40:42.833Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:40:42.910Z"'::jsonb),
('card-fs-4', 'deck-foodservice-formulas', 'What are the physiological fuel values (Atwater General Energy Factors) for Carbohydrates, Protein, Fat, and Alcohol in kcal/gram?', 'Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g', 'Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.', '["Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g","Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 8 kcal/g | Alcohol: 5 kcal/g","Carb: 3.75 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 9 kcal/g","Carb: 5 kcal/g | Protein: 5 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g"]'::jsonb, '["Atwater","Energy","Macronutrients"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:43:59.017Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:43:59.017Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:43:59.094Z"'::jsonb),
('card-fs-5', 'deck-foodservice-formulas', 'What is the formula for Adjusted Body Weight (ABW) commonly used for obese patients in clinical nutrition calculations?', 'ABW = IBW + 0.25 × (Actual Weight – IBW)', 'In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.', '["ABW = IBW + 0.25 × (Actual Weight – IBW)","ABW = Actual Weight – 0.50 × IBW","ABW = (Actual Weight + IBW) ÷ 2","ABW = IBW + 0.50 × (Actual Weight – IBW)"]'::jsonb, '["ABW","Clinical","Formulas"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:44:05.777Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:44:05.777Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:44:05.854Z"'::jsonb),
('card-fs-1', 'deck-foodservice-formulas', 'Using the Hamwi Formula, what is the Ideal Body Weight (IBW) for an adult female who is 5 feet 5 inches tall with a medium frame?', '125 lbs (± 10% for frame size)', 'Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).', '["125 lbs (± 10% for frame size)","135 lbs (± 10% for frame size)","115 lbs (± 10% for frame size)","120 lbs (± 10% for frame size)"]'::jsonb, '["Hamwi","IBW","Anthropometrics"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:44:51.392Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:44:51.392Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:44:51.469Z"'::jsonb),
('card-fs-3', 'deck-foodservice-formulas', 'If a recipe costs $1.80 per portion to produce and the target Food Cost Percentage is 30%, what is the selling price using the Factor Pricing Method?', '$6.00', 'Markup Factor = 100 ÷ Target Food Cost % = 100 ÷ 30 = 3.333. Selling Price = Raw Food Cost × Markup Factor = $1.80 × 3.333 = $6.00 (Alternatively: $1.80 ÷ 0.30 = $6.00).', '["$6.00","$5.40","$7.20","$4.50"]'::jsonb, '["Pricing","FoodCost","Management"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:43:38.368Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:43:38.368Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:43:38.440Z"'::jsonb),
('card-fs-2', 'deck-foodservice-formulas', 'What is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?', '32 ÷ Scoop Number = fluid ounces', 'Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).', '["32 ÷ Scoop Number = fluid ounces","64 ÷ Scoop Number = fluid ounces","16 ÷ Scoop Number = fluid ounces","Scoop Number × 4 = fluid ounces"]'::jsonb, '["FoodService","PortionControl","Scoop"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:45:10.460Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-12T09:45:10.460Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:45:10.535Z"'::jsonb),
('anki-card-1758690697975-50', 'anki-deck-1758689429896-1790185671252', 'The molecular formula for glucose: *', 'C6H12O6', '', '["C6H12O6","C8H12O6","C4H12O5","CH3OH"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:53:19.559Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:53:19.559Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-09-28T11:53:19.834Z"'::jsonb),
('anki-card-1758690564366-43', 'anki-deck-1758689429896-1790185671252', 'Olestra is artificial fat that does not provide kilocalories but has the following effect on one’s nutrition: *', 'It prevents the absorption of fat-soluble vitamins.', 'Olestra is a non-absorbable fat substitute made of sucrose polyester. Because human digestive enzymes cannot break its large chemical structure down, it passes through the gastrointestinal tract entirely intact.

As it moves through the gut, olestra behaves like a physical liquid solvent. It dissolves and traps the fat-soluble vitamins (A, D, E, and K) along with carotenoids from other consumed foods. Because olestra cannot be absorbed, these vital nutrients are bound to it and carried straight out of the body, presenting a major nutritional deficit. This is why the FDA legally mandates that foods made with olestra must be fortified with vitamins A, D, E, and K to offset this specific malabsorption effect.

• It prevents the absorption of water-soluble vitamins: This is scientifically incorrect. Water-soluble vitamins (like Vitamin C and B-complex vitamins) dissolve in water, not lipids. Therefore, they are entirely unaffected by the presence of olestra and are absorbed normally by the body.
• It results in flatulence: While gastrointestinal symptoms like flatulence, cramping, or loose stools can occur when olestra is consumed in extremely massive, non-standard quantities, the primary, classic nutrition-board-tested hazard is its direct, chemical inhibition of fat-soluble vitamin uptake.', '["a & b only","It prevents the absorption of water-soluble vitamins.","It results in flatulence.","It prevents the absorption of fat-soluble vitamins."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-11T14:46:31.838Z","interval":13,"easeFactor":2.1,"repetitions":4}'::jsonb, '"2026-10-29T14:46:31.838Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-10-29T14:46:32.040Z"'::jsonb),
('anki-card-1758690355310-31', 'anki-deck-1758689429896-1790185671252', 'Metabolic pathways of cholesterol except: *', 'energy production', '', '["energy production","hormone formation","secretion into bile","excretion into feces"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T14:13:13.194Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:13:13.194Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-09-28T14:13:13.415Z"'::jsonb),
('anki-card-1758690158349-21', 'anki-deck-1758689429896-1790185671252', 'The vitamin most directly involved in protecting biomolecules from damage caused by oxidation is: *', 'E', 'Vitamin E (tocopherol) is recognized as the body''s primary fat-soluble antioxidant. Its most direct, essential physiological role is to protect lipids and other vulnerable biomolecules inside cell membranes from oxidative damage.

Free radicals break down cell structures by attacking polyunsaturated fatty acids in a destructive chain reaction called lipid peroxidation. Vitamin E sits directly within the lipid bilayer of cell membranes, sacrificing itself to neutralize these free radicals, which preserves the structural integrity of every cell in the body.

• C: While Vitamin C (ascorbic acid) is a powerful water-soluble antioxidant that works closely with Vitamin E (even recycling oxidized Vitamin E back to its active form), it also acts as a necessary co-factor for many non-antioxidant enzymatic reactions, such as collagen synthesis.
• A: While carotenoids (precursors to Vitamin A) have antioxidant properties, preformed Vitamin A (retinol) functions primarily in vision, cell differentiation, and immune health rather than acting as a general biomolecule antioxidant.
• B3: Vitamin B3 (niacin) forms the coenzymes NAD and NADP, which are essential for cellular respiration and energy transfer reactions rather than scavenging free radicals to stop oxidation.', '["A","E","B3","C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-04T08:09:38.358Z","interval":6,"easeFactor":2.1,"repetitions":3}'::jsonb, '"2026-10-29T08:09:38.358Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-10-29T08:09:38.682Z"'::jsonb),
('anki-card-1758691346596-83', 'anki-deck-1758689429896-1790185671252', 'Protein turnover refers to the: *', 'the amount of protein synthesized and degraded by the body', '', '["the amount of protein broken down to glucose","the amount of protein absorbed from the diet","the amount of protein synthesized and degraded by the body","amount of protein found in foods and in the body"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:17:53.930Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:17:53.930Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-09-28T11:17:53.930Z"'::jsonb),
('anki-card-1758691324047-82', 'anki-deck-1758689429896-1790185671252', 'Alcohol abuse results in poor absorption of the following B vitamins except: *', 'riboflavin', 'While chronic alcohol consumption is notoriously linked to the severe intestinal malabsorption of thiamin (B1), pyridoxine (B6), and folate, riboflavin is the exception in this specific question.

In standard nutrition board exam matrices, alcohol abuse is most famously tested for causing a triad of B-vitamin absorption failures: thiamin (leading to Wernicke-Korsakoff syndrome), folate (leading to macrocytic anemia), and pyridoxine (where alcohol interference alters metabolic synthesis and absorption). Therefore, riboflavin stands as the textbook answer key choice for the vitamin less uniformly targeted by direct, alcohol-induced gut malabsorption channels compared to the others.', '["thiamin","pyridoxine","folate","riboflavin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T13:00:51.342Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T13:00:51.342Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-10-28T13:00:51.540Z"'::jsonb),
