('anki-card-1758691410642-87', 'anki-deck-1758689429896-1790185671252', 'The pathway from pyruvate to acetyl CoA _____ *', 'is metabolically irreversible.', '', '["produces lactate.","requires more energy than it produces.","is known as glyconeogenesis.","is metabolically irreversible."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T12:23:09.584Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T12:23:09.584Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-09-28T12:23:09.817Z"'::jsonb),
