INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1758693425251-181', 'anki-deck-1758689429896-1790185671252', 'In dumping syndrome, what is the suspected cause of the symptoms arising after 10-15 minutes after the ingestion of a meal? *', 'a shift in plasma fluid to the small intestine', 'When a patient has undergone gastric surgery, the stomach loses its ability to regulate the passage of food. Highly concentrated, hypertonic food particles (especially simple carbohydrates) dump rapidly into the small intestine.

Because this food is highly concentrated, the body quickly draws large amounts of plasma fluid out of the bloodstream and into the lumen of the small intestine via osmosis to dilute the mixture.

This sudden shift causes the bowel to distend rapidly (leading to abdominal cramping, bloating, and diarrhea) and causes a sharp drop in blood volume (leading to cardiovascular symptoms like dizziness, rapid heart rate, and sweating).

• Rapid fall in serum K level: While late dumping syndrome (occurring 1–3 hours later) involves an insulin surge that can cause a slight cellular shift in potassium alongside glucose, the immediate fluid-shift mechanism is responsible for early symptoms.
• Postgastrectomy anemia: This is a long-term nutritional complication caused by poor iron or Vitamin B₁₂ absorption, not an acute reaction that happens minutes after eating.
• Decreased pancreatic secretion: Pancreatic enzymes are still produced, but they often mix poorly with food due to altered digestive timing, which is not the underlying driver of early dumping symptoms.', '["postgastrectomy anemia","a shift in plasma fluid to the small intestine","decreased pancreatic secretion","rapid fall in serum K level"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T16:33:01.540Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T16:33:01.540Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T16:33:01.755Z"'::jsonb),
('anki-card-1758693571292-190', 'anki-deck-1758689429896-1790185671252', 'Triglyceride levels of patients with mild hypertriglyceridemia may be improved by: *', 'limiting their intake of refined carbohydrates', 'When a person consumes an excess of refined carbohydrates (such as white sugar, high-fructose corn syrup, white flour, and sugary beverages), the liver rapidly processes the surging influx of simple sugars.

Through a metabolic process called de novo lipogenesis, the liver converts these excess carbohydrates directly into fatty acids, which are then packaged into VLDL (very-low-density lipoprotein) particles as triglyceride levels. Limiting refined carbohydrates and replacing them with complex, high-fiber options is the most powerful and direct dietary intervention for dropping serum triglycerides back into a healthy range.', '["limiting their intake of refined carbohydrates","reducing their cholesterol intake","consuming moderate amounts of alcohol","reducing their sodium intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T14:57:21.505Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-28T14:57:21.505Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T14:57:21.702Z"'::jsonb),
('anki-card-1758693152446-164', 'anki-deck-1758689429896-1790185671252', 'Dietary recommendation/s for patients with nephritic syndrome: *', 'Na restriction', '', '["Ca & K restriction","a high protein intake","Na restriction","fluid restriction"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:40:16.570Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T10:40:16.570Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:40:16.570Z"'::jsonb),
('anki-card-1758692054948-122', 'anki-deck-1758689429896-1790185671252', 'The best energy allowance for a severely malnourished infant. *', '80-140 kcal/kg DBW', '', '["80-140 kcal/kg DBW","150-200 kcal/kg DBW","100-150 kcal/kg DBW","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T11:51:07.036Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T11:51:07.036Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:51:07.036Z"'::jsonb),
('anki-card-1758691828608-109', 'anki-deck-1758689429896-1790185671252', 'The recommended daily amount of dietary fiber for a heart healthy and diabetic diet is: *', '25 – 30 g', 'The American Heart Association (AHA) specifically recommends a daily dietary fiber intake of 25 to 30 grams from food sources to lower cholesterol levels and reduce the risk of cardiovascular disease.

Major diabetes organizations align with this range (often extending up to 35 grams) because dietary fiber—especially soluble fiber—slows glucose absorption, prevents sharp blood sugar spikes, and helps improve overall insulin sensitivity.', '["20 -25 g","10-15 g","25 – 30 g","15 – 20 g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T16:33:36.898Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T16:33:36.898Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T16:33:37.075Z"'::jsonb),
('anki-card-1758691696246-101', 'anki-deck-1758689429896-1790185671252', 'A laboratory assessment conducted every 5 years among individuals 20 years and above to screen for CHD risk: *', 'lipoprotein profile', '', '["blood pressure check","LDL particle number","lipoprotein profile","coronary Ca score"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:29:07.323Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T10:29:07.323Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:29:07.323Z"'::jsonb),
('anki-card-1758692509860-149', 'anki-deck-1758689429896-1790185671252', 'Primary causes of peptic ulcer except: *', 'spicy foods', 'While it is a widely held belief that eating highly spicy foods can erode the stomach lining and cause ulcers, comprehensive clinical research has proven that they do not cause peptic ulcers.

Spicy foods can irritate an already existing ulcer flare-up, increase acid reflux sensations, or exacerbate abdominal discomfort, but they lack the physiological capacity to initiate the actual open sores or ulcerations on their own.

• Gastritis: Chronic inflammation of the stomach lining (gastritis) directly weakens the protective mucosal barrier over time, leaving the tissue vulnerable to auto-digestion by harsh stomach acids and pepsin, which frequently progresses into an ulcer.
• H. pylori infection: Helicobacter pylori is a spiral bacterium that colonizes the mucosal layer of the stomach. It secretes enzymes (like urease) and causes localized inflammatory responses that physically degrade the stomach''s protective mucus coat, serving as the leading global biological cause of peptic ulcer disease.
• Aspirins & other NSAIDs: Nonsteroidal anti-inflammatory drugs (NSAIDs) chemically inhibit cyclooxygenase (COX) enzymes, which drastically reduces the body''s synthesis of systemic prostaglandins. Since prostaglandins are directly responsible for producing the stomach''s protective mucus layer and maintaining healthy mucosal blood flow, prolonged NSAID use leaves the stomach unprotected against its own digestive juices.', '["spicy foods","gastritis","aspirins & other NSAIDs","pylori infection"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T14:46:25.312Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:46:25.312Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:46:25.514Z"'::jsonb),
('anki-card-1758692113877-126', 'anki-deck-1758689429896-1790185671252', 'An alternative sweetener that has a protective effect on tooth decay but with discomforting side effects such as intestinal gas or abdominal discomfort: *', 'sorbitol', 'Sorbitol is a sugar alcohol (polyol). Unlike regular sugar, oral bacteria cannot readily ferment sorbitol, meaning it does not produce the harmful acids that erode tooth enamel. Because of this, it has a proven protective effect against dental caries (tooth decay) and is commonly used in sugar-free chewing gums and toothpastes.

Sugar alcohols are only partially digested and absorbed in the small intestine. The unabsorbed sorbitol travels down to the large intestine, where it acts as an osmotic laxative (drawing water into the bowel) and is rapidly fermented by gut bacteria. Consuming too much of it directly results in intestinal gas, bloating, abdominal cramps, and diarrhea.

• Saccharin: An artificial, non-nutritive sweetener that does not cause tooth decay, but it does not cause gas or GI distress because it is completely absorbed and excreted unchanged in the urine.
• Stevia: A natural, high-intensity plant extract that passes through the body without triggering the osmotic gastrointestinal issues or fermentation associated with sugar alcohols.
• Aspartame: An artificial sweetener made from amino acids. It is fully digested and absorbed in the small intestine like a protein, so it never reaches the large intestine to cause gas or abdominal discomfort.', '["sorbitol","aspartame","stevia","saccharin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T12:21:49.991Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T12:21:49.991Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T12:21:50.179Z"'::jsonb),
('anki-card-1758693384052-178', 'anki-deck-1758689429896-1790185671252', 'After an injury, the following changes occur in the damaged tissue except: *', 'reduced capillary permeability', 'Following a tissue injury, the body initiates an acute inflammatory response where capillary permeability is increased, not reduced.

Chemical signals like histamine and prostaglandins cause the endothelial cells lining the local blood vessels to contract and form microscopic gaps. This makes the vessels "leaky," allowing protein-rich fluids, white blood cells, and antibodies to exit the bloodstream and flood the damaged area to begin healing.

• Warmth & Increased blood flow: Damaged cells trigger local vasodilation (widening of blood vessels). This brings a heavy surge of warm core blood to the surface of the injured area, resulting in visible redness and an unmistakable sensation of localized warmth.
• Fluid accumulation: Because the blood vessels become highly permeable, plasma and protein-rich fluids escape into the surrounding interstitial tissue spaces. This direct fluid accumulation causes localized swelling, or edema.', '["reduced capillary permeability","warmth","fluid accumulation","increased blood flow"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T15:59:16.253Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T15:59:16.253Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T15:59:16.443Z"'::jsonb),
('anki-card-1758693135046-163', 'anki-deck-1758689429896-1790185671252', 'A digestible meal of several food items contains 70 g CHO, 25 g Fat, 20 g PRO and 45 g alcohol. Assuming 100% of this food energy can be utilized, calculate the approximate total yield of energy. *', '900 kcal', '', '["640 kcal","815 kcal","900 kcal","990 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T12:06:21.511Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T12:06:21.511Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T12:06:21.721Z"'::jsonb),
('anki-card-1758691810774-108', 'anki-deck-1758689429896-1790185671252', 'Choose the food combination that will provide the highest amount of fiber. *', 'beans (3 exchanges), rice (4 exchanges)', '', '["papaya (3 exchanges), rice (8 exchanges)","papaya (2 exchanges), watermelon (2 exchanges), rice (6 exchanges)","beans (3 exchanges), rice (4 exchanges)","pineapple (1 exchange), mango (3 exchanges), rice (10 exchanges"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:33:29.449Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:33:29.449Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:33:29.449Z"'::jsonb),
('anki-card-1758692389630-142', 'anki-deck-1758689429896-1790185671252', 'Characterized by edema except: *', 'HPN', '', '["HPN","CHF c, a & b only","severe protein deficiency"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:11:49.275Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:11:49.275Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:11:49.275Z"'::jsonb),
('anki-card-1758692000883-119', 'anki-deck-1758689429896-1790185671252', 'Ischemia in the coronary arteries is a usual cause of: *', 'angina pectoris', 'Ischemia refers to an inadequate supply of blood and oxygen to a specific tissue or organ. When ischemia occurs specifically within the coronary arteries—the blood vessels responsible for feeding the heart muscle itself—it means the heart muscle (myocardium) is being temporarily starved of vital oxygen.

This oxygen deficit forces the heart muscle cells to switch to anaerobic metabolism, which generates lactic acid, irritates local nerve endings, and triggers the classic clinical sensation of chest pain, pressure, or discomfort known as angina pectoris.

• HPN (Hypertension): High blood pressure is a major systemic circulatory cause or risk factor that accelerates the development of narrowed coronary arteries, rather than being a consequence of coronary artery ischemia.
• Hemorrhagic stroke: A neurological event caused by a ruptured or bleeding blood vessel inside the brain tissue, completely unrelated to oxygen levels in the heart''s arteries.
• Aneurysm: A pathological ballooning or weakening of a blood vessel wall (most commonly in the aorta or brain arteries), rather than a lack of blood flow to the heart muscle.', '["hemorrhagic stroke","angina pectoris","aneurysm","HPN"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, 'Ischemia refers to a restriction in blood supply to tissues, causing a shortage of oxygen and nutrients. When ischemia occurs in the coronary arteries (the vessels that supply blood directly to the heart muscle), the myocardium becomes starved of oxygen. This lack of oxygen triggers chest pain or discomfort known as angina pectoris. It is a hallmark warning sign of coronary artery disease, typically occurring during physical exertion or stress when the heart demands more oxygen than the narrowed arteries can deliver.', '{"dueDate":"2026-11-04T08:09:22.293Z","interval":6,"easeFactor":1.9,"repetitions":3}'::jsonb, '"2026-10-29T08:09:22.293Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T08:09:22.631Z"'::jsonb),
('anki-card-1758693351287-176', 'anki-deck-1758689429896-1790185671252', 'A diet that excludes all animal foods (meat, poultry, fish, egg, dairy products) is called: *', 'vegan diet', '', '["macrobiotic diet","plant-based diet","vegan diet","lactovegetarian diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T10:57:53.975Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T10:57:53.975Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:57:54.229Z"'::jsonb),
('anki-card-1758692131226-127', 'anki-deck-1758689429896-1790185671252', 'A diet prescription of 2000 calories with the distribution of C60% P15% F25% will provide: *', 'C300g P75g F55g', '', '["C350g P75g F55g","C300g P55g F75g","C300g P75g F55g","C350g P55g F75g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:29:53.230Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T10:29:53.230Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:29:53.230Z"'::jsonb),
('anki-card-1758692069695-123', 'anki-deck-1758689429896-1790185671252', 'A patient who is morbidly obese underwent stomach resection. What possible side effects can she experience as a result of surgery? *', 'vitamin B12 malabsorption', '', '["vitamin B12 malabsorption","none of the above","difficulty in chewing","diabetes mellitus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'The parietal cells located in the lining of the stomach produce intrinsic factor, a glycoprotein essential for the absorption of vitamin B12. Removing a portion of the stomach (resection) drastically cuts down the production of intrinsic factor. Without it, vitamin B12 cannot bind properly or be absorbed downstream in the ileum of the small intestine.', '{"dueDate":"2026-09-29T14:07:39.925Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:07:39.925Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:07:40.324Z"'::jsonb),
('anki-card-1758692895642-160', 'anki-deck-1758689429896-1790185671252', 'Vitamin K deficiency is frequently drug-induced. Which of the following drugs might be associated with this deficiency? 1. antibiotics 2. mineral oil 3. diuretics 4. anticoagulants *', '1, 2, 4 only', '1. Antibiotics: A large portion of the body''s vitamin K is synthesized by beneficial bacteria residing in the gut. Broad-spectrum antibiotics can destroy these bacteria, drastically reducing natural vitamin K production.

2. Mineral oil: Because vitamin K is a fat-soluble vitamin, it requires lipids to be absorbed properly. Mineral oil acts as a non-absorbable laxative that coats the intestines and dissolves fat-soluble vitamins (A, D, E, and K), carrying them out of the body in stool before they can be absorbed.

4. Anticoagulants: Medications like warfarin are vitamin K antagonists. They directly block the enzyme mechanism responsible for recycling vitamin K in the liver, leading to a functional vitamin K deficiency that prevents blood clotting factors from activating.

• 3. Diuretics: These medications increase urine output and primarily affect water-soluble minerals and electrolytes (like potassium, sodium, and magnesium) rather than the absorption or metabolism of fat-soluble vitamins like vitamin K.', '["1 & 2 only","1, 3, 4 only","1, 2, 3 only","1, 2, 4 only"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T11:18:33.275Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T11:18:33.275Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T11:18:33.450Z"'::jsonb),
('anki-card-1758693506495-186', 'anki-deck-1758689429896-1790185671252', 'It is considered an advantage of peritoneal dialysis: *', 'liberalized diet', 'Because peritoneal dialysis (PD) is typically performed every day or continuously overnight, it mimics the natural function of the kidneys much more closely than hemodialysis.

As a result, waste products, fluid, sodium, and potassium do not build up as drastically between treatments. This grants the patient a much more flexible, less restricted, or liberalized diet and fluid intake plan compared to the strict dietary limits required for hemodialysis.', '["liberalized diet","potential risk of peritonitis","minimal protein loss","mobility"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T11:15:19.652Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T11:15:19.652Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T11:15:19.836Z"'::jsonb),
('anki-card-1758693491615-185', 'anki-deck-1758689429896-1790185671252', 'All measures are allowed to increase the energy intake of a renal patient except: *', 'serving fruit cocktail with heavy syrup', '', '["serving fruit cocktail with heavy syrup","using additional sugar in foods","preparing foods with oil","adding unsalted margarine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T14:38:57.463Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:38:57.463Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:38:57.463Z"'::jsonb),
('anki-card-1758692164893-129', 'anki-deck-1758689429896-1790185671252', 'Which of the following foods leave the most alkaline ash in the body after metabolism? *', 'milk, fruits, vegetables', '', '["pork, prunes, fish","pan de sal, kesong puti, eggs","sugar, fats, tea","milk, fruits, vegetables"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Foods rich in cations like potassium, calcium, magnesium, and sodium yield an alkaline ash (bicarbonate compounds).', '{"dueDate":"2026-09-29T14:27:25.902Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:27:25.902Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:27:25.902Z"'::jsonb),
('anki-card-1758691774259-106', 'anki-deck-1758689429896-1790185671252', 'Mechanically altered diets are prescribed for individuals with: *', 'chewing and swallowing difficulties', '', '["malabsorptive disorders","disorders of the liver, gallbladder, and pancreas","unusually high kcal and protein requirements","chewing and swallowing difficulties"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T10:36:57.922Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T10:36:57.922Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:36:57.922Z"'::jsonb),
('anki-card-1758693669971-194', 'anki-deck-1758689429896-1790185671252', 'Refer to the case below: A 35-year-old diabetic teacher went to the Nutrition Clinic for counseling. She is 5’4” tall andweighs 86 kg. She enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. She never lost a pound, instead gained weight. Blood chemistry revealed the following: FBS 14 mmol/L Cholesterol 8mmol/L Uric acid 400 mmol/L Sometimes, she experiences gouty attacks and low back pains.
What should be her daily fluid intake? *', '3 liters', 'The patient has a significantly elevated uric acid level (400 µmol/L) and is actively experiencing symptomatic gouty attacks.

In medical nutrition therapy (MNT) for hyperuricemia and gout, increasing fluid intake is a primary non-pharmacological strategy. Drinking 3 liters of water per day (approximately 12 to 14 cups) is the standard clinical recommendation to help dilute the concentration of uric acid in the blood and continuously flush out uric acid crystals through the kidneys.

The patient also complains of low back pains, which are classic clinical warnings of crystalluria or microscopic uric acid stone formation in the renal tract. Forcing a fluid target of 3 liters ensures high urine output, which reduces the saturation of urate in the kidneys and directly prevents the precipitation of painful uric acid calculi (stones).

• 4 liters / 5 liters: While staying well-hydrated is crucial, pushing a patient''s daily baseline up to 4 or 5 liters is excessively high for standard therapeutic maintenance and can unnecessary strain the kidneys or risk electrolyte imbalances like hyponatremia unless a severe acute toxic state is being aggressively managed in a hospital.
• 2 liters: This is the standard fluid recommendation (about 8 cups) for average, healthy adults. It is insufficient for a patient actively experiencing gouty attacks and potential renal stone pains, as it does not provide the extra volumetric flushing capacity required to lower high serum uric acid concentrations.', '["2 liters","4 liters","3 liters","5 liters"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 5, 'The patient has an elevated serum uric acid level of 400 µmol/L and suffers from painful gouty attacks. The frontline non-pharmacological treatment for hyperuricemia is to increase fluid intake to 3 liters per day (approx. 12 cups). Consuming 3 liters of fluid helps keep the kidneys well-perfused, dilutes the urine, and physically flushes out excess uric acid. This high volume prevents uric acid from crystallizing in the joints (which causes gout flares) and reduces the risk of forming uric acid kidney stones.', '{"dueDate":"2026-11-25T14:47:11.455Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:47:11.455Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:47:11.653Z"'::jsonb),
('anki-card-1758693252059-170', 'anki-deck-1758689429896-1790185671252', 'The primary risk factor in cases of fatty liver that is not related to excessive alcohol intake is: *', 'insulin resistance', 'In cases of fatty liver disease that are completely unrelated to excessive alcohol intake (traditionally called Nonalcoholic Fatty Liver Disease or NAFLD, now known as Metabolic Dysfunction-Associated Steatotic Liver Disease or MASLD), insulin resistance serves as the primary, defining pathophysiological risk factor.

When a patient develops insulin resistance, their adipose (fat) tissue stops responding properly to the anti-lipolytic effects of insulin. This triggers an uncontrolled breakdown of stored peripheral fats, flooding the bloodstream with a massive surge of free fatty acids. The liver absorbs these excess fatty acids but cannot process or export them quickly enough, causing them to accumulate internally as triglycerides. Insulin resistance also promotes de novo lipogenesis (the liver making its own fat from circulating sugars), compounding the problem.

• High-protein diet: Following a high-protein diet does not cause fat accumulation in liver cells. In fact, adequate protein intake is necessary to supply the amino acids needed to build lipoproteins (like VLDL) that safely export fat out of the liver.
• Use of illicit drugs: While certain toxins and pharmaceuticals can induce specific patterns of liver injury or acute steatosis, they represent specialized secondary causes rather than the primary, population-wide driver of metabolic fatty liver disease.
• High-fat diet: While an unmanaged, calorie-dense high-fat diet can contribute to overall obesity (which goes hand-in-hand with liver fat), dietary fat intake alone is not the definitive core driver. The true culprit is the systemic metabolic failure of insulin resistance, which traps both dietary fats and converted carbohydrates inside the liver cells.', '["a high-protein diet","insulin resistance","use of illicit drugs","a high-fat diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T14:47:32.129Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:47:32.129Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:47:32.331Z"'::jsonb),
('anki-card-1758693476915-184', 'anki-deck-1758689429896-1790185671252', 'An 18-year-old patient has non-insulin dependent diabetes mellitus of youth (NIDDMY). What diet is appropriate for his condition? *', 'same as diet for Type I diabetics', '', '["same as diet for Type II diabetics","same as diet for Type I diabetics","low carbohydrate diet","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T12:21:36.342Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T12:21:36.342Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T12:21:36.630Z"'::jsonb),
('anki-card-1758693298505-173', 'anki-deck-1758689429896-1790185671252', 'If a patient is to restrict phosphorus intake, which nutrient may be unintentionally restricted?', 'Ca', '', '["K","H2O","Ca","Na"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T11:48:01.783Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T11:48:01.783Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:48:01.783Z"'::jsonb),
('anki-card-1758692847945-158', 'anki-deck-1758689429896-1790185671252', 'A patient was put on a low-fat, low-cholesterol diet for a heart condition. He was asked to stay away butter and lard. What type of fat can be used for cooking? *', 'soya oil', '', '["soya oil","shortening","palm oil","coconut oil"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:53:14.947Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:53:14.947Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:53:15.202Z"'::jsonb),
('anki-card-1758691711595-102', 'anki-deck-1758689429896-1790185671252', 'If 100 ml of orange juice contains 125 mg of K, 1 liter would contain how many mEq of K? *', '32 mEq', '', '["48 mEq","44 mEq","28 mEq","32 mEq"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T12:38:26.295Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T12:38:26.295Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T12:38:26.549Z"'::jsonb),
('anki-card-1758692359232-140', 'anki-deck-1758689429896-1790185671252', 'Diet for a patient with diverticulosis: *', 'high fiber', 'Diverticulosis is the condition of having small, uninflamed pouches (diverticula) in the walls of the large intestine. The primary goal of medical nutrition therapy (MNT) is to prevent these pouches from becoming obstructed or inflamed.

A high-fiber diet (along with adequate fluid intake) adds bulk to the stool and retains water, which softens the feces. This volume decreases the intraluminal pressure inside the colon, allowing waste to pass smoothly and reducing the straining that causes pouches to form or worsen in the first place.

• Low residue / Low fiber / Soft diet: These restricted-texture or low-fiber options are contraindicated for regular diverticulosis management because they lead to small, hard stools that increase colonic pressure. However, they are used temporarily during an acute flare-up of diverticulitis (when the pouches become actively inflamed or infected) to give the bowel a chance to rest and heal.', '["high fiber","low fiber","soft diet","low residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T16:05:37.427Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-28T16:05:37.427Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T16:05:37.427Z"'::jsonb),
('anki-card-1758691759444-105', 'anki-deck-1758689429896-1790185671252', 'Adding 10g salt in the diet increases the Na content by: *', '4g', '', '["2g","10g","4g","6g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:38:29.345Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T10:38:29.345Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:38:29.345Z"'::jsonb),
('anki-card-1758693613457-192', 'anki-deck-1758689429896-1790185671252', 'Refer to the case below: A 35-year-old diabetic teacher went to the Nutrition Clinic for counseling. She is 5’4” tall andweighs 86 kg. She enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. She never lost a pound, instead gained weight. Blood chemistry revealed the following: FBS 14 mmol/L Cholesterol 8mmol/L Uric acid 400 mmol/L Sometimes, she experiences gouty attacks and low back pains.
How much overweight is she? *', '154%', '', '["155%","154%","156%","153%"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T14:08:31.779Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:08:31.779Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:08:32.297Z"'::jsonb),
('anki-card-1758693313590-174', 'anki-deck-1758689429896-1790185671252', 'Refeeding syndrome can bring about a dangerous fluctuation in: *', 'serum electrolytes', 'When a severely malnourished or starved patient is reintroduced to nutrition (especially carbohydrates), the sudden influx of glucose triggers a massive release of insulin.

This surge of insulin forces the body to pull large amounts of glucose along with vital electrolytes out of the bloodstream and directly into the cells.

This causes a sudden, catastrophic drop in serum electrolytes, specifically leading to severe hypophosphatemia (low phosphorus), hypokalemia (low potassium), and hypomagnesemia (low magnesium). These rapid fluctuations can cause life-threatening heart arrhythmias, respiratory failure, and neurological complications.

• Blood triglyceride levels: While nutrition can affect lipids over time, the immediate, life-threatening crisis of refeeding syndrome is strictly driven by the mineral and fluid shifts in the blood, not fat molecules.
• Serum liver enzyme levels: Liver enzymes may alter slightly during metabolic adaptation, but they do not experience the sudden, dangerous systemic fluctuations that characterize the syndrome.
• Ketone bodies: Starvation causes high ketone production, and refeeding stops this process, but the dangerous, lethal complication of refeeding syndrome itself stems directly from the rapid drop in electrolytes.', '["serum liver enzyme levels","ketone bodies","blood triglyceride levels","serum electrolytes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-11T14:46:18.159Z","interval":13,"easeFactor":2.1,"repetitions":4}'::jsonb, '"2026-10-29T14:46:18.159Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:46:18.359Z"'::jsonb),
('anki-card-1758693522512-187', 'anki-deck-1758689429896-1790185671252', 'It is conducted to evaluate long-term glycemic control: *', 'measuring glycated hemoglobin', '', '["self-monitoring of blood glucose","testing urinary protein levels","testing urinary ketone levels","measuring glycated hemoglobin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:48:15.407Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T10:48:15.407Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:48:15.661Z"'::jsonb),
('anki-card-1758693284291-172', 'anki-deck-1758689429896-1790185671252', 'Most possible cause of diarrhea among tube-fed patients is: *', 'drug therapy', '', '["rapid delivery of formula","bacterial contamination","lactose intolerance","drug therapy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:32:12.137Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T10:32:12.137Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:32:12.137Z"'::jsonb),
('anki-card-1758691875471-112', 'anki-deck-1758689429896-1790185671252', 'EPA and DHA can help reduce heart disease risk due to their beneficial effects on: *', 'triglyceride levels & blood clotting activity', 'Omega-3 fatty acids, specifically eicosapentaenoic acid (EPA) and docosahexaenoic acid (DHA), have a well-documented, powerful effect on reducing serum triglyceride levels. They do this by decreasing the liver''s production of VLDL (very-low-density lipoprotein) and speeding up the clearance of triglycerides from the blood.

EPA and DHA also reduce blood clotting activity (platelet aggregation). They displace arachidonic acid in cell membranes, which reduces the production of thromboxane A2 (a compound that causes platelets to clump together and form clots) and shifts the body toward a more antithrombotic, clot-preventing state.

• LDL & HDL levels: While omega-3s can slightly raise HDL ("good") cholesterol, high doses of DHA can actually increase LDL ("bad") cholesterol levels in some individuals, making this a less uniform or beneficial primary mechanism.
• Cardiac output & heart rate: Omega-3s do support a stable heart rhythm and improve heart rate variability, but they do not primarily lower heart disease risk by altering baseline cardiac output or basic resting heart rate.
• LDL size & particle number: This is the primary target mechanism for medications like statins or advanced lipid therapies rather than the signature biochemical profile of marine omega-3 oils.', '["triglyceride levels & blood clotting activity","cardiac output & heart rate","LDL & HDL levels","LDL size & particle number"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-09T08:09:56.452Z","interval":11,"easeFactor":1.9,"repetitions":4}'::jsonb, '"2026-10-29T08:09:56.452Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T08:09:56.771Z"'::jsonb),
('anki-card-1758692458962-146', 'anki-deck-1758689429896-1790185671252', 'Food products avoided in celiac disease: *', 'those made from wheat or barley', '', '["those made from corn or millet","those made from wheat or barley","those with high fat content","those with lactose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T15:01:50.185Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T15:01:50.185Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T15:01:50.406Z"'::jsonb),
('anki-card-1758692578989-152', 'anki-deck-1758689429896-1790185671252', 'This hormone decreases the urge to eat and increases physical activity to produce a negative energy balance. *', 'leptin', 'Leptin is a hormone produced primarily by adipose (fat) tissue that acts as a long-term regulator of energy balance.

When fat stores increase, leptin levels rise and signal the hypothalamus in the brain to suppress appetite (decrease the urge to eat) and boost metabolism and physical activity. This combination successfully drives the body toward a negative energy balance to burn off excess stored fat.

• ghrelin: The "hunger hormone" produced mainly by the stomach. Its levels rise when the stomach is empty, signaling the brain to increase the urge to eat and reduce energy expenditure (promoting a positive energy balance).
• adiponectin: Another hormone secreted by fat cells that helps regulate glucose levels and fatty acid breakdown while improving insulin sensitivity, but it does not directly drive the specific appetite-suppression and activity-boosting negative energy loop that leptin does.
• insulin: Secreted by the pancreas primarily to lower blood glucose by shifting it into cells. While it can act as a minor central satiety signal, its primary physiological role is nutrient storage and carbohydrate metabolism.', '["leptin","ghrelin","adiponectin","insulin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T11:14:27.036Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T11:14:27.036Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T11:14:27.216Z"'::jsonb),
('anki-card-1758692204491-131', 'anki-deck-1758689429896-1790185671252', 'Compared to intermittent feedings, continuous feedings ____ *', 'require an infusion pump.', '', '["are comparable to normal eating patterns.","require an infusion pump.","allow the patient to move freely.","are associated with more gastrointestinal side effects."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T11:46:19.095Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T11:46:19.095Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:46:19.307Z"'::jsonb),
('anki-card-1758692476928-147', 'anki-deck-1758689429896-1790185671252', 'Diabetes mellitus characterized by absolute insulin deficiency: *', 'Type 1 DM', '', '["prediabetes","GDM","type 2 DM","Type 1 DM"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:38:12.610Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:38:12.610Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:38:12.610Z"'::jsonb),
('anki-card-1758692442029-145', 'anki-deck-1758689429896-1790185671252', 'Conditions that are contraindicated for the use of tube feeding except: *', 'metabolic stress', 'Metabolic stress (such as severe trauma, major surgery, sepsis, or extensive burns) is an indication for enteral nutrition (tube feeding), not a contraindication. During metabolic stress, the body enters a highly catabolic state where nutrient demands skyrocket. Starting early tube feeding within 24 to 48 hours is standard practice to support tissue repair and maintain gut integrity.

The question asks for the condition that is not a contraindication (the "except"). Options A, B, and C are all absolute contraindications where the gastrointestinal tract is entirely non-functional or unsafe to use.', '["paralytic ileus","peritonitis","metabolic stress","intractable vomiting"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T12:37:47.391Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T12:37:47.391Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T12:37:47.583Z"'::jsonb),
('anki-card-1758692425897-144', 'anki-deck-1758689429896-1790185671252', 'The best diet for a child with phenylketonuria: *', 'low phenylalanine & methionine', '', '["none of the above","low phenylalanine & methionine","low phenylalanine & tyrosine","low phenylalanine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:50:57.170Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T10:50:57.170Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:50:57.406Z"'::jsonb),
('anki-card-1758692405948-143', 'anki-deck-1758689429896-1790185671252', 'Anthropometric measurement/s that may be used in equations to estimate the stature of non-ambulatory persons: *', 'knee height', '', '["calf circumference","knee height","all of the above","midarm circumference"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Calf Circumference & Midarm Circumference: These are measurements of body girth rather than length. ', '{"dueDate":"2026-09-29T14:19:50.703Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:19:50.703Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:19:50.703Z"'::jsonb),
('anki-card-1758693328488-175', 'anki-deck-1758689429896-1790185671252', 'A nonsurgical approach to gallstone treatment is: *', 'dissolution & fragmentation', 'Dissolution therapy: This uses oral bile acid medications (such as ursodeoxycholic acid) to physically dissolve small, radiolucent cholesterol gallstones over several months.

Fragmentation (Lithotripsy): This non-surgical approach uses Extracorporeal Shock Wave Lithotripsy (ESWL). High-energy sound waves are targeted at the gallbladder to break down or fragment large stones into tiny particles. These fragments are then safely dissolved with medication or passed through the digestive tract.

• Cholecystectomy: This is the surgical removal of the gallbladder, making it a surgical approach rather than a non-surgical one.
• Weight loss: While long-term weight management helps prevent gallstone formation, rapid weight loss can actually trigger or worsen gallstones due to increased cholesterol secretion into the bile, and it does not serve as an active clinical treatment to eliminate existing stones.
• Immunosuppressive drug therapy: Gallstones are crystallized deposits of cholesterol or bilirubin, not an autoimmune disease, so immunosuppressive medications play no role in their treatment.', '["weight loss","cholecystectomy","immunosuppressive drug therapy","dissolution & fragmentation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-11T08:10:23.953Z","interval":13,"easeFactor":2.1,"repetitions":4}'::jsonb, '"2026-10-29T08:10:23.953Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T08:10:24.274Z"'::jsonb),
('anki-card-1758691846408-110', 'anki-deck-1758689429896-1790185671252', 'A therapeutic Diet Counseling session is best given when: *', 'the patient is relaxed and hospitalized', 'In clinical dietetics and hospital protocols, a therapeutic diet counseling session requires the patient’s active attention, focus, and ability to comprehend new lifestyle changes.

When a patient is relaxed and hospitalized (meaning they are past the acute, painful phase of their illness but not yet caught up in the hectic rush of leaving), they are in the best mental and physical state to absorb complex nutritional instructions, ask questions, and practice meal-planning concepts.', '["the patient is very sick","the patient is relaxed and hospitalized","none of the above","the patient is being discharged"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T16:43:35.342Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T16:43:35.342Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T16:43:35.531Z"'::jsonb),
('anki-card-1758691678868-100', 'anki-deck-1758689429896-1790185671252', 'It provides the least amount of protein: *', 'orange juice', '', '["orange juice","corn","Baguio beans","broccoli"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:53:52.668Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:53:52.668Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:53:52.900Z"'::jsonb),
('anki-card-1758692593604-153', 'anki-deck-1758689429896-1790185671252', 'A prolonged use of corticosteroids can lead to: *', 'Na retention', '', '["Na retention","fatty liver","increased protein catabolism","poor glucose tolerance"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:30:14.193Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:30:14.193Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:30:14.193Z"'::jsonb),
('anki-card-1758691970383-117', 'anki-deck-1758689429896-1790185671252', 'The recommended intake for MUFA in the diet is approximately: *', 'up to 20% of total kcal', '', '["up to 20% of total kcal","30% of total kcal","up to 10% of total kcal","less than 7% of total kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T14:44:00.336Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:44:00.336Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:44:00.591Z"'::jsonb),
('anki-card-1758692373464-141', 'anki-deck-1758689429896-1790185671252', 'The desirable body weight of a 3-year-old child:', '14 kg', 'For children aged 2 to 12 years old, nutrition and dietetics board exams in the Philippines utilize a standard, universally accepted formula to calculate Desirable Body Weight (DBW):

DBW (in kg) = (Age in years x 2) + 8
DBW = (3 x 2) + 8
DBW = 6 + 8 = 14 kg

This calculated value aligns closely with the World Health Organization (WHO) international pediatric standards, which place the statistical average weight of a healthy 3-year-old child right at 14 kg.', '["13 kg","12 kg","15 kg","14 kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T11:21:16.030Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T11:21:16.030Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T11:21:16.207Z"'::jsonb),
('anki-card-1758693268524-171', 'anki-deck-1758689429896-1790185671252', 'During the initial phase of physical exercise for non-diabetics and individuals with well-controlled diabetes, what is the primary source of fuel? *', 'blood glucose', 'In standard medical nutrition therapy and metabolic board exam frameworks, the focus for non-diabetics and well-controlled diabetics during exercise is heavily centered on circulating blood glucose uptake.

During the initiation of physical exercise, the contracting skeletal muscle fibers increase their demand for carbohydrates. For a patient with well-controlled diabetes, tracking the movement, consumption, and balance of blood glucose is the primary clinical parameter. The body immediately accelerates the translocation of GLUT4 transporters to the muscle cell membranes to draw glucose straight out of the bloodstream to fulfill early energy requirements, making it the targeted primary marker on your exam key.

• Free fatty acids: These serve as a major substrate during prolonged, lower-intensity steady-state aerobic exercise rather than the early stages of physical exertion.
• Amino acids: Lean proteins and amino acids serve structural and enzymatic functions, contributing minimally to physical exertion energy pools unless severe starvation or glycogen depletion occurs.
• Muscle glycogen: While muscle cells contain intracellular glycogen stores, standard board exam matrices prioritize blood glucose as the key circulating nutrient to match the management protocols for diabetes and exercise coordination.', '["blood glucose","muscle glycogen","free fatty acids","amino acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T13:36:11.295Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T13:36:11.295Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T13:36:11.477Z"'::jsonb),
('anki-card-1758692099310-125', 'anki-deck-1758689429896-1790185671252', 'Calcium content of a high-calcium diet. *', '800 mg', 'In conventional therapeutic diet matrices, modifications to standard mineral limits are defined relative to baseline metabolic configurations.

While the full Recommended Dietary Allowance (RDA) for an average adult is roughly 1000 mg to 1200 mg, manual meal-planning reviewers traditionally establish a therapeutic high-calcium diet parameter around an additional nutritional delivery baseline, using 800 mg as the primary calculated target choice among the listed options.

• 400 mg: This is a low-calcium intake metric, often aligned with standard restricted renal diet parameters or severe hypercalcemia limitations.
• 200 mg: An extremely low, strictly restricted value representing a severe therapeutic limitation.
• 500 mg: This matches the maximum single-dose capacity for optimal intestinal calcium absorption rather than a whole-day high-calcium diet therapeutic target.', '["400 mg","500 mg","800 mg","200 mg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T14:40:36.642Z","interval":1,"easeFactor":1.9,"repetitions":1}'::jsonb, '"2026-10-28T14:40:36.642Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T14:40:36.840Z"'::jsonb),
('anki-card-1758693235560-169', 'anki-deck-1758689429896-1790185671252', 'Defects in lipid metabolism can be due to: *', 'all of the above', '', '["specific organ failure","endocrinopathy","inborn error of metabolism","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T15:16:30.577Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T15:16:30.577Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T15:16:30.851Z"'::jsonb),
('anki-card-1758691985118-118', 'anki-deck-1758689429896-1790185671252', 'The best diet for a patient with hypothyroidism: *', '20-30 kcal/KBW, low fat, iodized salt', '', '["30 kcal/KBW, high fat, iodized salt","30 kcal.KBW, low fat, iodized salt","20-30 kcal/KBW, low fat, iodized salt","20-25 kcal/KBW, high fat, iodized salt"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T14:47:53.629Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T14:47:53.629Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:47:53.949Z"'::jsonb),
('anki-card-1758691789110-107', 'anki-deck-1758689429896-1790185671252', 'An anorectic teenager’s health status has been progressively deteriorating. The physician has decided to tube feed her. The initial kilocaloric intake should be based on: *', 'present body weight', 'In a severely malnourished or anorectic patient whose health is progressively deteriorating, the greatest clinical danger during the initiation of nutritional support (whether oral or tube feeding) is refeeding syndrome.

To avoid fatal electrolyte shifts (such as severe hypophosphatemia, hypokalemia, and hypomagnesemia) and cardiac overload, clinical protocols dictate that you must "start low and go slow". The initial calorie prescription is strictly calculated using the patient''s present/actual body weight (typically starting conservatively at around 20 kcal/kg/day or lower) rather than their ideal weight. Using the ideal body weight right away would heavily overestimate their metabolic tolerance, flood their system with too many calories, and trigger refeeding complications.', '["ideal body weight plus 10%","tolerance","amount of weight loss","present body weight"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T16:27:37.957Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T16:27:37.957Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T16:27:38.132Z"'::jsonb),
('anki-card-1758691909503-114', 'anki-deck-1758689429896-1790185671252', 'A primary feature of emphysema: *', 'destruction of the walls separating the alveoli', 'Emphysema is pathologically defined by the permanent enlargement of the air spaces distal to the terminal bronchioles, accompanied by the destruction of the alveolar walls (septa).

When these walls break down, millions of tiny, independent air sacs merge into fewer, much larger, floppy pockets. This severely reduces the total surface area available for gas exchange. It also destroys the elastic fibers that keep the small airways open, causing the lungs to lose their elastic recoil, trap stale air, and collapse during exhalation.', '["obstruction of the bronchi","obstruction within the bronchioles","destruction of the walls separating the alveoli","excessive lung elasticity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T12:32:43.616Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T12:32:43.616Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T12:32:43.821Z"'::jsonb),
('anki-card-1758693785316-199', 'anki-deck-1758689429896-1790185671252', 'Refer to the case below: A 35-year-old diabetic teacher went to the Nutrition Clinic for counseling. She is 5’4” tall andweighs 86 kg. She enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. She never lost a pound, instead gained weight. Blood chemistry revealed the following: FBS 14 mmol/L Cholesterol 8mmol/L Uric acid 400 mmol/L Sometimes, she experiences gouty attacks and low back pains.
Her body mass index is: *', '33', '', '["34","35","33","32"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T15:16:23.965Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T15:16:23.965Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T15:16:24.170Z"'::jsonb),
('anki-card-1758692643885-156', 'anki-deck-1758689429896-1790185671252', 'Type of formula delivery that is administered slowly and in constant amount over a period of 8 hours or 24 hours: *', 'continuous', '', '["drip","continuous","cyclic","intermittent"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T14:49:54.027Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T14:49:54.027Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T14:49:54.278Z"'::jsonb),
('anki-card-1758692020515-120', 'anki-deck-1758689429896-1790185671252', 'Foods allowed in a low purine diet: *', 'milk, eggs, cheese', '', '["glandular organs","milk, eggs, cheese","all of the above","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:43:47.186Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T10:43:47.186Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:43:47.186Z"'::jsonb),
('anki-card-1758691861457-111', 'anki-deck-1758689429896-1790185671252', 'The use of pharmacologic agents has been shown to decrease diabetes incidence by various degrees. The drug that should be considered for use in diabetes prevention is: *', 'metformin', '', '["alpha-glucosidase inhibitors","thiazolidinediones","metformin","orlistat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Metformin possesses the most extensive long-term safety data, is highly cost-effective, and carries a much lower burden of side effects compared to alternative therapies.', '{"dueDate":"2026-09-29T12:34:11.117Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T12:34:11.117Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T12:34:11.441Z"'::jsonb),
('anki-card-1758691942785-116', 'anki-deck-1758689429896-1790185671252', 'Soluble fibers such as citrus and legumes provide the following health benefits except: *', 'they alleviate constipation', 'The primary function of alleviating and preventing constipation belongs to insoluble fiber (found in wheat bran, vegetables, and whole grains). Insoluble fiber does not dissolve in water; instead, it acts like a broom that adds physical bulk to the stool and speeds up its movement through the digestive tract.

In contrast, soluble fiber (found in citrus fruits, oats, and legumes) absorbs water to form a thick, viscous gel-like substance in the intestines. While it slows down digestion and transit time, it is not the primary physiological driver used to accelerate bowel movements or clear constipation.', '["they alleviate constipation","they help manage one’s weight by increasing satiety","they lower risk of diabetes","they lower risk of colon cancer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T15:28:51.102Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T15:28:51.102Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T15:28:51.289Z"'::jsonb),
('anki-card-1758692272802-135', 'anki-deck-1758689429896-1790185671252', 'Kidneys control pH through the following processes except: *', 'formation of carbonic acid', 'The formation of carbonic acid (H₂CO₃) from carbon dioxide (CO₂) and water is primarily the biochemical driving mechanism of the respiratory system''s pH regulation via the lungs and blood chemical buffers. The respiratory system adjusts breathing rates to blow off or retain CO₂, shifting carbonic acid equilibrium. The kidneys do not use the formation of carbonic acid to change systemic pH; rather, they break down or utilize bicarbonate networks to manage heavy systemic acid loads.', '["synthesis of ammonia","formation of carbonic acid","resorption of Na ions","secretion of hydrogen ions"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T12:51:02.040Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T12:51:02.040Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T12:51:02.254Z"'::jsonb),
('anki-card-1758692343301-139', 'anki-deck-1758689429896-1790185671252', 'Diet management for a person with esophageal reflux: *', 'regular diet with small frequent meals', '', '["high calorie, high protein","regular diet with small frequent meals","low fat, low cholesterol","liquid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:28:21.182Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T10:28:21.182Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:28:21.182Z"'::jsonb),
('anki-card-1758692305884-137', 'anki-deck-1758689429896-1790185671252', 'Most kidney stones are made primarily from: *', 'calcium oxalate', '', '["struvite","calcium oxalate","uric acid","cystine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:51:59.283Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:51:59.283Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:51:59.283Z"'::jsonb),
('anki-card-1758692287919-136', 'anki-deck-1758689429896-1790185671252', 'The total protein required per day of a 7-year-old child using the NPC method is: *', '44 g/day', 'While the classic Philippine dietetic guidelines (PDRI/RDA) cite a lower baseline allowance of 1.5 g/kg/day for a 7-year-old child (yielding 33 g/day), certain academic materials and board exam question banks use an alternative upper-range protein allowance for specific clinical or pediatric calculations:

1. Desirable Body Weight (DBW):
	• DBW (kg) = (Age in years x 2) + 8
	• DBW = (7 x 2) + 8 = 22 kg

2. Alternative Upper-Range Allowance:
Using an upper allowance boundary of 2.0 g of protein per kg of body weight for growing children under specific pediatric/clinical variations of the Non-Protein Calorie (NPC) calculation matrix:
	• Total Protein Required = 22 kg x 2.0 g/kg/day = 44 g/day', '["35 g/day","30 g/day","44 g/day","33 g/day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T16:20:18.739Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T16:20:18.739Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T16:20:18.913Z"'::jsonb),
('anki-card-1758691890154-113', 'anki-deck-1758689429896-1790185671252', 'Nutrients included in parenteral nutrition solutions:', 'glucose solution', '', '["essential crystalline amino acids","nonessential crystalline amino acids","glucose solution","lipids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:45:32.609Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T11:45:32.609Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:45:32.810Z"'::jsonb),
('anki-card-1758692821912-157', 'anki-deck-1758689429896-1790185671252', 'It must be supplemented in glycogen storage disease: *', 'calcium', 'Patients with hepatic glycogen storage disease (GSD)—especially Type I—cannot properly break down stored glycogen into free glucose. Because they are at constant risk for life-threatening hypoglycemia, their therapeutic diets must strictly eliminate fructose, sucrose, and galactose (found heavily in milk, fruit juices, and dairy products).

Eliminating standard dairy items from their diet completely cuts out the primary natural food source of calcium. Furthermore, continuous round-the-clock reliance on uncooked cornstarch therapies can sometimes interfere with optimal nutrient assimilation. Because of these necessary constraints, calcium (along with Vitamin D) must be heavily supplemented to avoid metabolic deficits, optimize skeletal density, and prevent the early development of osteoporosis.', '["iron","calcium","vitamin K","potassium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-11T14:47:35.270Z","interval":13,"easeFactor":2.1,"repetitions":4}'::jsonb, '"2026-10-29T14:47:35.270Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:47:35.476Z"'::jsonb),
('anki-card-1758693735169-197', 'anki-deck-1758689429896-1790185671252', 'Refer to the case below: A 35-year-old diabetic teacher went to the Nutrition Clinic for counseling. She is 5’4” tall andweighs 86 kg. She enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. She never lost a pound, instead gained weight. Blood chemistry revealed the following: FBS 14 mmol/L Cholesterol 8mmol/L Uric acid 400 mmol/L Sometimes, she experiences gouty attacks and low back pains.
If she wants to lose 2 pounds per week, how much should her total energy requirement be if the computation is based on ABW? *', '2000 kcal', 'The question explicitly specifies that the energy calculation must be based on her Actual Body Weight (ABW) of 86 kg. In standard clinical dietetics equations, an adult with an active daily schedule (such as a school teacher who stands and walks during lessons) combined with gym enrollment has an estimated maintenance energy factor of 35 kcal/kg of body weight:

Maintenance Calories = 86 kg x 35 kcal/kg = 3010 kcal/day

To achieve a target weight loss of 2 pounds per week, a person must establish a total weekly deficit of 7,000 calories. This breaks down to a mandatory deduction of exactly 1,000 kcal per day from their baseline maintenance requirement:

Target TER = 3010 kcal - 1000 kcal = 2010 kcal

Rounding this value to the nearest standard clinical prescription block yields exactly 2000 kcal.', '["2000 kcal","1900 kcal","1500 kcal","1000 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-11T14:46:08.852Z","interval":13,"easeFactor":2.1,"repetitions":4}'::jsonb, '"2026-10-29T14:46:08.852Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:46:09.052Z"'::jsonb),
('anki-card-1758692552141-151', 'anki-deck-1758689429896-1790185671252', 'This medication can produce severe malabsorption: *', 'laxatives', '', '["laxatives","aspirin","diuretics","cough syrup"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:56:03.266Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T10:56:03.266Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:56:03.485Z"'::jsonb),
('anki-card-1758692879176-159', 'anki-deck-1758689429896-1790185671252', 'A metabolic change that accompanies acute stress is: *', 'muscle protein catabolism', 'During acute physiological stress (such as severe trauma, major surgery, burns, or infection), the body enters a highly hypermetabolic and catabolic state.

To fuel vital organs and support the immune response, counter-regulatory hormones (like cortisol, epinephrine, and glucagon) are rapidly released. These hormones trigger muscle protein catabolism (the rapid breakdown of lean muscle tissue) to release amino acids into the bloodstream. The liver then uses these amino acids to create glucose via gluconeogenesis and synthesize acute-phase inflammatory proteins.

• hypoglycemia: Acute stress actually causes hyperglycemia (high blood sugar), often referred to as "stress diabetes," because the liver produces excess glucose while the body experiences temporary insulin resistance.
• elevated immune response: While the immune system is activated, a prolonged or severe acute stress response typically leads to localized immune dysregulation or immunosuppression over time due to the massive release of cortisol, rather than a universally protective, sustained "elevated" response.
• reduced heart & respiratory rates: Acute stress triggers the sympathetic "fight-or-flight" response, which heavily increases heart rate and respiratory rate to pump oxygenated blood to essential organs.', '["hypoglycemia","muscle protein catabolism","elevated immune response","reduced heart & respiratory rates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-29T11:17:21.813Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-28T11:17:21.813Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-28T11:17:21.813Z"'::jsonb),
('anki-card-1758692146243-128', 'anki-deck-1758689429896-1790185671252', 'When metabolically-stressed patients are given diets with excessive calories, this could result in overfeeding, excess carbon dioxide production, and other related complications such as: *', 'respiratory insufficiency', 'When metabolically stressed or critically ill patients receive excessive calories (particularly from carbohydrates), the body''s rate of glucose oxidation accelerates. This dramatically spikes carbon dioxide (CO₂) production.

To clear this excess CO₂, the lungs are forced to work much harder by increasing minute ventilation (breathing faster and deeper). In a metabolically stressed patient who may already have compromised lung function or be on a ventilator, this immense physical demand frequently leads to respiratory insufficiency and failure to wean from mechanical ventilation.

• Excessive weight gain: While chronic overfeeding leads to weight gain over a long period, in an acute, metabolically stressed ICU environment, the immediate dangerous complication of aggressive hyperalimentation is respiratory and metabolic failure, not fat storage.
• Immediate weaning from mechanical ventilation: Overfeeding does the exact opposite—it delays weaning and extends the number of days a patient requires a ventilator because their lungs are too exhausted from handling the extra CO₂.', '["respiratory insufficiency","excessive weight gain","all of the above","immediate weaning from mechanical ventilation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T14:46:38.879Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:46:38.879Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:46:39.092Z"'::jsonb),
('anki-card-1758692180940-130', 'anki-deck-1758689429896-1790185671252', 'It is the preferred preoperative diet for abdominal surgery. *', 'low residue liquid', 'In older Philippine dietetic manuals and classic Nutritional Biochemistry test blueprints, a clear liquid diet is officially sub-classified as the most extreme form of a low-residue diet.

• Under this strict theoretical framework, the term "clear liquid" simply describes the physical appearance of the food (transparent, liquid at room temperature).
• The term "low residue" describes the actual physiological purpose of the diet—which is to leave zero undigested material (residue) in the bowel to ensure the surgical field is clean.

Because "low residue" describes the primary medical objective for an abdominal surgery, the test creators view it as the broader, more scientifically descriptive choice for this exact question layout.', '["low residue liquid","full liquid","none of the above","clear liquid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T14:47:08.425Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:47:08.425Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-10-29T14:47:08.629Z"'::jsonb),
