('anki-card-1758603216582-12', 'anki-deck-1783610421391-1790433139851-sw8ch', 'Caloric requirement of diabetic patient should be:*', 'The same as normal energy requirement to maintain ideal weight.', '', '["Increased above normal requirements to meet increased metabolic demand","Decreased below normal requirement to prevent glucose formation.","The same as normal energy requirement to maintain ideal weight.","High in fat to spare carbohydrates."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
