('anki-card-1757825851530-87', 'anki-deck-1783610400188-1790433145939-pouc6', 'Two situations in which a person may experience fluid and electrolyte imbalances are:', 'Vomiting and burns', '', '["Diarrhea and cuts","Heavy sweating and excessive carbohydrate intake","Broken bones and fever","Vomiting and burns"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
