('anki-card-1758439210376-7', 'anki-deck-1783609202217-1790433145988-s5tf1', 'It is also called oriental fondue. Japanese in origin which has gained popularity all over the world. Vegetables and noodles are cooked in the broth where slices of beef were cooked quickly.*', 'shabu-shabu', '', '["sukiyaki","shabu-shabu","tonkatsu","katsudon"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
