('anki-card-1758439046804-0', 'anki-deck-1783609202217-1790433145988-s5tf1', 'In French, Haute cuisine literally means high cooking. It is characterized by:*', 'meticulous preparation and careful presentation of food, at a high price level, accompanied by rare wines.', '', '["meticulous preparation and careful presentation of food, at a high price level, accompanied by rare wines.","lighter, more delicate dishes and an increased emphasis on presentation.","carefully planned and prepared foods strictly following laws/practices of a particular religion","delicate preparation of foods combining culinary practices of different cultures."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758439079515-1', 'anki-deck-1783609202217-1790433145988-s5tf1', 'Mediterranean cuisine is a combination of foods from cultures adjacent to the Mediterranean sea. The foods typical to this region include:*', 'fresh vegetables, olives, fresh herbs', '', '["fresh vegetables, sea foods, curry","onions, garlic, shallots","fresh vegetables, olives, fresh herbs","fresh vegetables, butter, fresh herbs, galangal"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758439110317-2', 'anki-deck-1783609202217-1790433145988-s5tf1', 'French cuisine is thought to be the pinnacle of world cuisines. Great chefs of this cuisine laid emphasis on the quality of ingredients and presentation. The following are some of the components that makes it unique:*', 'cheese, wine, herbs and spices, sea foods', '', '["fresh vegetables, butter, fresh herbs, galangal","quality meat, savory sauces, butter, herbs, wine","fresh herbs, fermented vegetables, wine, preserves","cheese, wine, herbs and spices, sea foods"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758439136930-3', 'anki-deck-1783609202217-1790433145988-s5tf1', 'Because of the longer cold season in this region/country, their cuisine focuses on foods that can be preserved like pickled cabbage.*', 'German', '', '["Mediterranean","Southeast Asian","German","Spanish"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758439170396-5', 'anki-deck-1783609202217-1790433145988-s5tf1', 'An Italian term for foods served before the main meal*', 'antipasto', '', '["hors d'' ouvres","antipasto","prosciutto","bruschetta"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
