('anki-card-1756168725144-14', 'anki-deck-1783609175539-1790433140277-2y6kw', 'If the actual cost of a whole cake is P500, having a yield of 10 slices, and selling price is P90 per slice, what is the food cost percentage?', '55.6%', '(500/(90*10))*100', '["55.6%","5.56%","18%","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'easy', 5, '', '{"dueDate":"2026-10-18T20:00:00.000Z","interval":48,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.104Z"'::jsonb, '"2026-10-14T16:36:14.929Z"'::jsonb),
('anki-card-1756168658010-13', 'anki-deck-1783609175539-1790433140277-2y6kw', 'Food service system utilized in most coffee shops like Dunkin Donuts:', 'Assembly', 'Dunkin Donuts practices off premise food production and the food are usually just assembled, heated before service. This is a characteristic of assembly/serve foodserving system.', '["Assembly","Conventional","Commisary","Ready prepared"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'easy', 5, '', '{"dueDate":"2026-10-21T20:00:00.000Z","interval":51,"easeFactor":2.5,"repetitions":4}'::jsonb, NULL, '"2026-09-26T14:32:29.104Z"'::jsonb, '"2026-10-14T16:41:27.514Z"'::jsonb),
