INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1758445012597-42', 'anki-deck-1783610430222-1790433140271-gx1a3', 'A food and water borne disease that affects the liver resulting to jaundice, severe anorexia, nausea, vomiting and abdominal tenderness*', 'Hepatitis A', 'Hepatitis A is a highly contagious liver infection caused by the Hepatitis A virus (HAV). It is classically defined as a food- and water-borne disease because it spreads primarily via the fecal-oral route. Transmission happens when a person ingests food or water contaminated with the feces of an infected individual (often due to poor hand hygiene or inadequate sewage treatment).

 The virus multiplies inside the liver cells, sparking acute inflammation. This structural irritation produces a distinct, textbook cluster of gastrointestinal and hepatic symptoms:
	• Jaundice: Yellowing of the skin and the whites of the eyes caused by a buildup of bilirubin in the blood as the inflamed liver struggles to process it.
	• Severe Anorexia: A profound, sudden loss of appetite.
	• Nausea, Vomiting, and Abdominal Tenderness: Driven by an enlarged, inflamed liver (hepatomegaly) pressing against surrounding tissues in the right upper abdominal quadrant.

• Hepatitis B & Hepatitis C: These viral infections are blood-borne and sexually transmitted pathogens. They spread via contact with infected bodily fluids, blood transfusions, or shared needles, rather than through contaminated food or drinking water.
• Cirrhosis: This is a chronic, late-stage pathological condition characterized by irreversible scarring of the liver tissue. It is the long-term result of prolonged liver disease (like chronic alcoholism or chronic Hep B/C), not an acute foodborne illness.', '["Hepatitis C","Hepatitis B","Hepatitis A","Cirrhosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T17:15:42.668Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T17:15:42.668Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T17:15:42.751Z"'::jsonb),
('anki-card-1758444990698-41', 'anki-deck-1783610430222-1790433140271-gx1a3', 'Virgin Coconut Oil has antimicrobial properties. How much VCO must be given to a patient weighing 176 lbs during the first day of treatment?*', '48ml', 'Virgin coconut oil (VCO) has been studied for its potential antimicrobial and antiviral properties. Research involving VCO often explores its components, such as medium-chain triglycerides (MCTs) like lauric acid, which are believed to contribute to these properties. Clinical protocols and studies evaluate various amounts of VCO for supportive care, but determining any specific usage requires professional medical evaluation based on an individual''s health status and needs.

A specific weight-based formula was used in clinical trial protocols by the Department of Science and Technology (DOST). These clinical trials (such as the DOST-FNRI studies on the antiviral and antimicrobial properties of VCO) use a strict dosage protocol based on a patient’s body weight in kilograms to allow the gut to safely adjust:
• First 3 days (Initial Dose): 0.6 mL of VCO per kilogram of body weight (0.6 mL/kg BW).
• Day 4 to 28 (Succeeding Dose): 1.2 mL of VCO per kilogram of body weight (1.2 mL/kg BW).

1. Convert the patient''s weight from pounds to kilograms:
176 lbs / 2.2 = 80 kg
2. Calculate the first-day dosage (using the initial 0.6 mL/kg factor):
80 kg x 0.6 mL/kg = 48 mL', '["48ml","60ml","50ml","96ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:32:58.300Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T08:32:58.300Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:32:58.300Z"'::jsonb),
('anki-card-1758444975282-40', 'anki-deck-1783610430222-1790433140271-gx1a3', 'Middle East Respiratory Syndrome or MERS-COV can be transmitted through*', 'Camel milk and meat', 'Middle East Respiratory Syndrome (MERS-CoV) is a zoonotic viral respiratory illness, meaning it is transmitted from animals to humans. Extensive epidemiological studies by global health bodies have confirmed that dromedary camels serve as the primary animal host reservoir for the virus.

While the virus can also spread through direct physical contact with live animals, humans can contract the infection by consuming contaminated, unpasteurized camel products—specifically raw camel milk and undercooked camel meat. Because the virus is heat-sensitive, global public health authorities strictly advise pasteurizing milk and thoroughly cooking meat to eliminate transmission risks.', '["Human excreta","Blood","Camel milk and meat","Droplet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T15:46:23.887Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T15:46:23.887Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T15:46:24.020Z"'::jsonb),
('anki-card-1758444962915-39', 'anki-deck-1783610430222-1790433140271-gx1a3', 'A patient with Severe Acute Respiratory Syndrome must wear surgical mask at all times except when*', 'Eating', 'A patient cannot physically consume food or fluids while wearing a surgical mask. Therefore, eating (and drinking) is the only practical and necessary exception where the mask must be temporarily removed.

During these temporary mask-off periods, strict isolation precautions—such as maintaining negative pressure ventilation, keeping the patient in a private room, and ensuring healthcare workers wear appropriate personal protective equipment (PPE) like N95 respirators—are vital to prevent the transmission of respiratory droplets or aerosols.', '["Eating","Sleeping","Resting","Exercising"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T11:14:09.047Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T11:14:09.047Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T11:14:09.151Z"'::jsonb),
('anki-card-1758444945714-38', 'anki-deck-1783610430222-1790433140271-gx1a3', 'Stage 1 dietary management of poliomyelitis includes 30 to 200 ml tube feeding alternating with water every*', '2 hours', 'In older, traditional diet therapy manuals for acute infectious neurological disorders like poliomyelitis (particularly cases affecting the bulbar region, which impairs normal swallowing mechanics), Stage 1 protocols utilize tube feeding to guarantee safe nutrition without aspiration.

The standard textbook framework states that the patient should be given 30 to 200 ml of formula via tube feeding, wait 2 hours, and then alternate with water. Spacing the administration out every 2 hours prevents overwhelming the patient''s gastric capacity, minimizes the risk of regurgitation, and keeps the patient safely hydrated while their swallowing reflexes are heavily compromised.

*When you encounter this question on your exam, remember this specific gastrointestinal-pacing formula for acute polio management: Tube feeding, wait 2 hours, then water.', '["1 hour","5 hours","2 hours","3 hours"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T07:30:53.326Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T07:30:53.326Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T07:30:53.487Z"'::jsonb),
('anki-card-1758444932235-37', 'anki-deck-1783610430222-1790433140271-gx1a3', 'To ensure food safety, keeping food between 45 to 145 degrees Fahrenheit or 7.2 to 62.7 degrees Celsius must not exceed*', '4 hours', 'Leaving perishable food items within this unsafe span (45°F to 145°F / 7.2°C to 62.7°C) for longer than 4 hours permits rapid, exponential multiplication of pathogenic bacteria (such as Salmonella and Staphylococcus aureus), making the food highly toxic and unsafe for human consumption.

1. The Safe Time Window (Under 2 hours): When potentially hazardous food is kept in the Temperature Danger Zone (45°F to 145°F / 7.2°C to 62.7°C) for less than 2 hours, it is still safe to serve, eat, or securely put back into the refrigerator to use later.
2. The Point of No Return (2 to 4 hours): Once food sits out past the 2-hour mark, it enters a dangerous gray zone. While it is still safe to consume immediately, it can no longer be legally or safely put back in the refrigerator because bacteria have entered their rapid, exponential growth phase.

• Under 2 hours: Safe to consume or re-refrigerate.
• 2 to 4 hours: Safe to eat only if consumed immediately; do not put it back in the fridge.
• Over 4 hours: Absolute mandatory discard.', '["2 hours","3 hours","4 hours","8 hours"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T17:10:54.973Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T17:10:54.973Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T17:10:55.058Z"'::jsonb),
('anki-card-1758444917018-36', 'anki-deck-1783610430222-1790433140271-gx1a3', 'Food safety is essential in managing patients with AIDS. The following are food safety measures to be observed except*', 'Keep cold food at 35 to 50 degrees Fahrenheit', 'In clinical food safety protocols, cold food must strictly be maintained at or below 40°F (4°C) (or 41°F depending on localized sanitary code references like ServSafe or the FDA) to inhibit pathogenic bacterial multiplication.

Stating that cold foods can be kept up to 50°F directly breaches the [Food Temperature Danger Zone (40°F to 140°F)](usda.gov ""Danger Zone" (40°F - 140°F)"). Allowing cold food temperatures to climb to 50°F allows highly dangerous, opportunistic pathogens like Salmonella, Listeria monocytogenes, and E. coli to rapidly multiply. For immunocompromised individuals, such as patients with AIDS, this minor temperature elevation can lead to a severe, life-threatening foodborne infection.', '["Keep cold food at 35 to 50 degrees Fahrenheit","Discard eggs with cracked shells","Avoid serving raw fruits and vegetables","Thaw chicken in the refrigerator"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T11:25:50.386Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T11:25:50.386Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T11:25:50.470Z"'::jsonb),
('anki-card-1758444901202-35', 'anki-deck-1783610430222-1790433140271-gx1a3', 'A patient with Dengue Hemorrhagic Fever must avoid*', 'Chocolate drink', 'Patients diagnosed with Dengue Hemorrhagic Fever (DHF) must strictly avoid dark-colored foods and beverages, such as chocolate drinks, cola, coffee, red/violet juices, and dark berries.

DHF compromises blood capillaries and dramatically reduces blood platelets, placing the patient at a severe risk for internal gastrointestinal (GI) bleeding. If a patient consumes a chocolate drink, it can discolor their vomit or stool, staining it dark brown or black. This masks clinical signs of active GI bleeding (such as hematemesis or melena), confusing the medical team and potentially delaying life-saving emergency care.

• Dark leafy vegetables: While green, they do not dye stool or vomit the distinctive tarry black or dark brown color associated with internal bleeding. In fact, they provide vital Vitamin K to support proper clotting pathways.
• Hard candies & Apple juice: These options are clear or translucent, making them completely safe for hydration and carbohydrate maintenance without interfering with medical observations.', '["Hard candies","Dark leafy vegetables","Chocolate drink","Apple juice"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:42:09.853Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T08:42:09.853Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:42:09.853Z"'::jsonb),
('anki-card-1758445321115-59', 'anki-deck-1783610430222-1790433140271-gx1a3', 'A patient has suffered second degree burn on his right arm and right leg. How much protein must be recommended?*', '20% of TER', 'Severe thermal injury triggers a massive hypermetabolic and catabolic state driven by sustained catecholamine, cortisol, and glucagon elevations, leading to accelerated skeletal muscle proteolysis to supply amino acids for hepatic acute-phase proteins, immune cell proliferation, and granulation tissue synthesis. Providing protein at 20% of total energy expenditure (TER) or approximately 1.5 to 2.0 g/kg/day provides the necessary nitrogen substrate to maintain positive nitrogen balance, mitigate lean body mass wasting, and support fibroblast proliferation and collagen deposition.', '["10% of TER","15 % of TER","20% of TER","25% of TER"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:42:42.560Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T08:42:42.560Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:42:42.560Z"'::jsonb),
('anki-card-1758444888918-34', 'anki-deck-1783610430222-1790433140271-gx1a3', 'A patient diagnosed with Tuberculosis has normal BMI. How much protein should be prescribed per day?*', 'High protein 75 to 120g per day', 'Active Tuberculosis (TB) places the body in an intense inflammatory and hypercatabolic state, resulting in accelerated muscle tissue breakdown and nitrogen wasting. Even if a patient presents with a normal BMI, they require aggressive nutritional therapy to counter cellular destruction, maintain lean muscle mass, and optimize immune function.

Medical nutrition therapy (MNT) guidelines dictate increasing a TB patient''s protein intake above the normal baseline to support tissue healing and recovery. Clinical protocols emphasize incorporating adequate high-biological-value protein into the daily diet to support complete tissue healing.', '["Low protein 40g per day","High protein 75 to 120g per day","0.6g/kg body weight","2g/kg body weight"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T07:24:28.599Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T07:24:28.599Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T07:24:28.741Z"'::jsonb),
('anki-card-1758444853187-32', 'anki-deck-1783610430222-1790433140271-gx1a3', 'A patient diagnosed with Rheumatic Fever was prescribed cortisone. Nutrition intervention must include*', 'Sodium restriction 1000mg/day', 'While cortisone actively wastes potassium (making potassium-rich foods clinically necessary), the test creator targets sodium restriction based on the following textbook rationale:

1. Fluid Retention and Edema: Cortisone heavily promotes sodium and fluid retention inside the body. In a patient with Rheumatic Fever, this fluid retention is highly dangerous because the disease can cause inflammation of the heart (rheumatic carditis).
2. Preventing Heart Strain: Introducing a strict sodium restriction helps prevent fluid overload, peripheral edema, and hypertension, which directly protects the heart muscles from being overtaxed during the acute phase of Rheumatic Fever.', '["Potassium rich food","Sodium restriction 1000mg/day","Iron supplementation","Increased fluid intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T15:05:53.881Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T15:05:53.881Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T15:05:54.006Z"'::jsonb),
