('anki-card-1757642963813-87', 'anki-deck-1783609193199-1790433139825-f6c4y', 'Martha and John are gluten-sensitive or gluten-intolerant which means that their bodies produce an abnormal
immune response when breaking down gluten during digestion. The two proteins found in gluten are:', 'Glutenin & gliadin', '', '["Glutenin & gliadin","Glycerine & glutenin","Gliadine & mellorine","Glycine & alanine"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757642937966-86', 'anki-deck-1783609193199-1790433139825-f6c4y', 'Green pigment in milk:', 'Lactoflavin', '', '["Lactalbumin","Lactic acid","Lactoflavin","Chlorophyll"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
