INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1788430970615-2', 'anki-deck-1788430913642-1790433139833-ykmiq', 'The following are the criteria for determining whether a food is spoiled, except:', 'None of the above', 'To classify a food as "unspoiled" or acceptable, it must satisfy all three of the positive benchmarks listed in options A, B, and C. Therefore, none of them are exceptions.', '["None of the above","Freedom from objectable, but not unsafe, contaminants","Freedom from decomposition resulting from enzymatic reactions inherent in the food or reactions between the food and its environment or decomposition from microbial growth","Freedom from physical damage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T14:48:44.588Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:48:44.588Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-29T14:48:44.790Z"'::jsonb),
('anki-card-1757907350704-110', 'anki-deck-1783608890180-1790433145937-io434', 'Use to examine the probability that the usual intake of an individual is inadequate.', 'EAR', '', '["EAR","RNI","AI","UL"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757906792249-105', 'anki-deck-1783608890180-1790433145937-io434', 'Defined as a characteristic that is distributed differently in the study and control groups and that may influence the outcome being assessed.', 'Confounding', '', '["Accuracy","Random errors","Systematic errors","Confounding"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757907036403-108', 'anki-deck-1783608890180-1790433145937-io434', 'The likelihood that a test correctly predicts the presence or absence of malnutrition or a disease.', 'Predictive value (PV)', '', '["Sensitivity (Se)","Specificity (Sp)","Predictive value (PV)","Prevalence"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757906707052-103', 'anki-deck-1783608890180-1790433145937-io434', 'A deviation from the correct result due to chance alone. They lead to measurements that are imprecise.', 'Random errors', '', '["Accuracy","Random errors","Systematic errors","Confounding"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757906749950-104', 'anki-deck-1783608890180-1790433145937-io434', 'A result to depart from the true value in a consistent direction. This error reduces the accuracy of a measurement.', 'Systematic errors', '', '["Accuracy","Random errors","Systematic errors","Confounding"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757906891844-106', 'anki-deck-1783608890180-1790433145937-io434', 'An index or indicator refers to the extent by which the index or indicator reflects the nutritional status or predicts changes in nutriture.', 'Sensitivity (Se)', '', '["Sensitivity (Se)","Specificity (Sp)","Predictive value (PV)","Prevalence"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757906971290-107', 'anki-deck-1783608890180-1790433145937-io434', 'An index or indicator refers to the ability of the index or indicator to identify and classify those persons who are genuinely well nourished.', 'Specificity (Sp)', '', '["Sensitivity (Se)","Specificity (Sp)","Predictive value (PV)","Prevalence"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757907384453-111', 'anki-deck-1783608890180-1790433145937-io434', 'A usual intake by an individual is at or above the __ and has low probability of inadequacy.', 'RNI', '', '["EAR","RNI","AI","UL"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757907449517-112', 'anki-deck-1783608890180-1790433145937-io434', 'Usual intake by an individual greater than or equal to the level has a low probability of inadequacy.', 'AI', '', '["EAR","RNI","AI","UL"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757907486265-113', 'anki-deck-1783608890180-1790433145937-io434', 'Usual intakes above this level may place an individual at risk to adverse effects from excessive nutrient intakes.', 'UL', '', '["EAR","RNI","AI","UL"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757907873180-114', 'anki-deck-1783608890180-1790433145937-io434', 'Measured in the midpoint of the back of the upper arm, between the acromion process and the tip of the olecranon.', 'Triceps skinfold', '', '["Triceps skinfold","Biceps skinfold","Subscapular skinfold","Suprailic skinfold"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757907935661-115', 'anki-deck-1783608890180-1790433145937-io434', 'Measured by the thickness of a vertical fold on the front of the upper arm, above the center of the cubital fossa and at same level of the triceps skinfold.', 'Biceps skinfold', '', '["Triceps skinfold","Biceps skinfold","Subscapular skinfold","Suprailic skinfold"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, NULL, '"2026-09-26T14:32:29.686Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
