INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1756969435406-26', 'anki-deck-1783610504561-1790433132438-14b68', 'Which is the most important component of the medical nutrition theraphy for patients with celiac disease?', 'All of the above', 'The cornerstone of medical nutrition therapy for celiac disease is a strict, lifelong gluten-free diet. This requires avoiding gluten-containing grains such as wheat, rye, and barley, carefully checking food labels for gluten-containing ingredients or contamination, and using naturally gluten-free alternatives such as rice, corn, and potatoes. Therefore, all three measures are important components of implementing a gluten-free diet.', '["Omit sources of gluten as wheat, rye and barley","Reading labels to check if the product contains gluten","Substitute wheat flour with potato, rice, corn","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:47:46.872Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:47:46.872Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:47:46.872Z"'::jsonb),
('anki-card-1756971771681-65', 'anki-deck-1783610504561-1790433132438-14b68', 'Energy recommedantion for patients with stage 3 CKD', '25-35 kcal/kg', 'The current KDOQI 2020 Nutrition in CKD guideline recommends prescribing 25–35 kcal/kg ideal body weight/day for metabolically stable adults with CKD stages 1–5, including Stage 3 CKD. The exact energy prescription should be individualized according to age, sex, physical activity, body composition, weight goals, CKD stage, and concurrent illness or inflammation.', '["15-20 kcal/kg","25-35 kcal/kg","30-40 kcal/kg","<30 kcal/kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:36.951Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:36.951Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:36.951Z"'::jsonb),
('anki-card-1756971816762-66', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following medications affect food intake by altering salivary secretions?', 'Phenobarbital', 'Phenobarbital can cause dry mouth (xerostomia) by reducing salivary secretion. Reduced saliva can affect taste, chewing, swallowing, and overall food intake, potentially contributing to decreased appetite or difficulty eating. This is particularly relevant in nutrition assessment because medication-related oral effects can indirectly compromise dietary intake.', '["Digitalis","Amphetamines","Phenobarbital","Methotrexate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:11.261Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:11.261Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:11.261Z"'::jsonb),
('anki-card-1756972022336-67', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following goals below is considered a SMART goal?', 'Client to consume 1 oral nutrition supplement per day, 6 of 7 days per week for 1 month', 'A SMART goal should be Specific, Measurable, Achievable, Relevant, and Time-bound.

• Specific: 1 oral nutrition supplement
• Measurable: 1 supplement/day, on 6 of 7 days
• Achievable: A concrete, realistic behavior target that can be monitored
• Relevant: Directly addresses increasing oral nutritional intake
• Time-bound: Within a defined period of 1 month', '["client to consume 1 oral nutrition supplement for 1 month","client to consume oral nutrition supplements 6 of 7 days per week","Client to consume oral nutrition supplements approximately half of the week","Client to consume 1 oral nutrition supplement per day, 6 of 7 days per week for 1 month"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:02:33.376Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:02:33.376Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:02:33.376Z"'::jsonb),
('anki-card-1756972072199-68', 'anki-deck-1783610504561-1790433132438-14b68', 'In planning energy and nutrient requirements of athletes, the following factors are considered EXCEPT:', 'none of the above', 'All three factors—type of activity, duration, and intensity—are important when estimating an athlete''s energy and nutrient requirements.

• Type of activity determines the predominant energy systems and muscle groups involved. Endurance, strength/power, and intermittent sports have different nutritional demands.
• Duration affects total energy expenditure and the amount of carbohydrate, fluid, and electrolytes that may be required.
• Intensity strongly influences energy expenditure and substrate utilization. Higher-intensity exercise generally increases the reliance on carbohydrate as a fuel source.

Other important considerations include body size/composition, training volume, frequency, age, sex, environmental conditions, and the athlete''s goals.', '["type of activity","duration","intensity","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:40:22.196Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:40:22.196Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:40:22.196Z"'::jsonb),
('anki-card-1756972198260-69', 'anki-deck-1783610504561-1790433132438-14b68', 'The following statements regarding carbohydrates are true EXCEPT:', 'carbohydrate loading is beneficial for athletes doing all type of exercise, both long-term and short term activities', 'It is a strategy specifically designed to maximize muscle glycogen storage for prolonged, endurance-based activities lasting longer than 90 minutes (such as marathons, triathlons, or long-distance cycling). It provides little to no performance benefit for short-term, high-intensity exercises (like sprinting, powerlifting, or short swimming events) because those activities do not exhaust the body’s baseline glycogen reserves.', '["carbohydrates is metabolized up to 3 times faster than fat which allows for faster muscle contractions","carbohydrate loading is beneficial for athletes doing all type of exercise, both long-term and short term activities","complex carbohydrates provide energy at a slow and gradual pace","simple carbohydrates cause a rapid drop in blood sugar"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:51.108Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T11:09:51.108Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:09:51.108Z"'::jsonb),
('anki-card-1756972238292-70', 'anki-deck-1783610504561-1790433132438-14b68', 'How many grams of addition protein daily is needed for muscle building?', '6-7 grams', 'Skeletal muscle hypertrophy is driven by a positive net protein balance, calculated as muscle protein synthesis (MPS) minus muscle protein breakdown (MPB). Achieving a net positive balance requires an elevation in intracellular amino acid availability—specifically essential amino acids (EAAs) like leucine, which activate the mechanistic target of rapamycin complex 1 (mTORC1) via the Sestrin2-GATOR2 pathway. When calculating the incremental dietary protein necessary to construct new contractile proteins (actin and myosin) alongside structural collagen matrices, clinical estimates establish that accumulating structural muscle tissue demands approximately 6 to 7 grams of net daily protein intake above maintenance requirements during active resistance training protocols.', '["6-7 grams","3 grams","0.8g/kg BW","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:24.107Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:49:24.107Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:24.107Z"'::jsonb),
('anki-card-1756972311306-71', 'anki-deck-1783610504561-1790433132438-14b68', 'This nutrient is supplemented with the idea of helping to build muscle and promote growth. Humans synthesize adequate amounts of this nutrient; its functions are with the central nervous system and cell structure.', 'choline', 'Choline is the best answer. Although choline is not technically classified as a vitamin, it is an essential nutrient because endogenous synthesis is not always sufficient to meet physiological needs.

Choline has several important functions, including:
• Cell membrane structure: Choline is a component of phosphatidylcholine and sphingomyelin, important phospholipids in cell membranes.
• Neurotransmission: Choline is the precursor of acetylcholine, an important neurotransmitter involved in memory, muscle control, and other nervous-system functions.
• Lipid transport and metabolism: Choline is required for the synthesis of phosphatidylcholine and lipoproteins and helps prevent abnormal lipid accumulation in the liver.
• Methyl-group metabolism: Choline can be oxidized to betaine, which participates in methyl-group transfer.

Choline has historically been marketed or supplemented in sports settings with claims related to muscle performance, growth, or fat metabolism, but these claims should not be confused with established physiological functions. Evidence does not demonstrate that routine choline supplementation produces significant muscle-building effects in healthy individuals consuming adequate choline.', '["chromium","choline","riboflavin","pyridoxine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:41:27.015Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:41:27.015Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:41:27.015Z"'::jsonb),
('anki-card-1756972407450-72', 'anki-deck-1783610504561-1790433132438-14b68', 'The following statements are true about food intolerances, except:', 'it causes anaphylactic life-threatening immune reaction', 'The key distinction between food allergy and food intolerance is the underlying mechanism.

Food allergy involves an immune-mediated response to a food protein. An IgE-mediated food allergy can cause anaphylaxis, which is a potentially life-threatening systemic reaction.

Food intolerance, on the other hand, generally refers to adverse reactions to food that do not involve an immune-mediated mechanism. Examples include lactose intolerance due to lactase deficiency and certain reactions resulting from pharmacologic substances in foods or metabolic disorders.

Therefore, food intolerance does not cause anaphylaxis through an immune-mediated food-allergic reaction.', '["food intolerances are more common than true food allergy","it causes anaphylactic life-threatening immune reaction","PKU and G6PD are examples of food intolerances caused by inborn errors of metabolism","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:24.985Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:56:24.985Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:24.985Z"'::jsonb),
('anki-card-1756972473030-73', 'anki-deck-1783610504561-1790433132438-14b68', 'The point at which it is impossible to keep moving; corresponds to the time when the reserves of the glycogen in the muscles are depleted:', 'hitting the wall', '“Hitting the wall” is a term commonly used in endurance sports to describe a sudden and profound feeling of fatigue during prolonged exercise, traditionally associated with substantial depletion of muscle glycogen stores. The athlete may experience extreme fatigue, weakness, difficulty maintaining pace, and a strong perception that continuing the exercise is very difficult. It is better understood as a state of severe fatigue associated with low carbohydrate availability, along with other physiological and psychological factors.', '["carbohydrate loading","muscle fatigue","hitting the wall","muscle cramps"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:44:35.707Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:44:35.707Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:44:35.707Z"'::jsonb),
('anki-card-1756972514211-74', 'anki-deck-1783610504561-1790433132438-14b68', 'The following are type of motility disease EXCEPT:', 'achylia gastrica', 'Achylia gastrica is not primarily a motility disorder. It refers to marked or complete absence of gastric hydrochloric acid and pepsin secretion, usually associated with gastric gland atrophy or other disorders affecting gastric secretory function.

In contrast, gastric atony and gastrectasia are associated with impaired gastric motility and gastric emptying. Dyspepsia is primarily a symptom syndrome involving upper gastrointestinal discomfort and can be associated with abnormalities of gastric motility, accommodation, or sensation.', '["dyspepsia","gastric atony","gastrectasia","achylia gastrica"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:57.467Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:57.467Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:57.467Z"'::jsonb),
('anki-card-1756972596740-75', 'anki-deck-1783610504561-1790433132438-14b68', 'A disease characterized by atrophy of the intestines due to lack of peptidase to digest the gliadin factors of gluten.', 'Gluten-sensitive enteropathy', 'Gluten-sensitive enteropathy (celiac disease) is an immune-mediated disorder triggered by exposure to gluten in genetically susceptible individuals. Gluten contains gliadin, which contributes to the immune response that damages the small-intestinal mucosa.

The resulting mucosal injury can produce villous atrophy, crypt hyperplasia, and impaired absorptive capacity, leading to malabsorption of nutrients. The disease involves an inappropriate immune response to gluten peptides, particularly in individuals carrying HLA-DQ2 or HLA-DQ8. 

Tissue transglutaminase modifies gluten peptides, enhancing their presentation to T cells and triggering intestinal inflammation.', '["Gluten-sensitive enteropathy","Enteritis","Tropical sprue","Lymphagiectasis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:32.680Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:32.680Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:32.680Z"'::jsonb),
('anki-card-1756972638122-76', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is true for nutritional management of hemorrhoids?', 'high fiber', 'The primary nutrition goal in hemorrhoids is to prevent constipation and straining during defecation. Increasing dietary fiber helps by increasing stool bulk and, particularly when adequate fluid is consumed, improving stool consistency and promoting easier bowel movements.

Current evidence supports increasing dietary fiber intake as an effective conservative intervention for hemorrhoids. Fiber supplementation has been shown to reduce persistent symptoms and bleeding.

For adults, a practical target is generally around 25–30 g of fiber per day, with gradual increases and adequate fluid intake to minimize bloating or discomfort.', '["high calorie","high fiber","low protein","low residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:02:42.206Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:02:42.206Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:02:42.206Z"'::jsonb),
('anki-card-1756972693802-77', 'anki-deck-1783610504561-1790433132438-14b68', 'The nutrition prescription is included in which step of the NCP?', 'Nutrition intervention', 'The nutrition prescription is part of the Nutrition Intervention step of the Nutrition Care Process. It translates the nutrition diagnosis and assessment findings into a specific plan for addressing the identified nutrition problem.

The nutrition prescription describes the recommended amount and/or type of food, nutrients, or nutrition-related intervention appropriate for the patient. It may include parameters such as energy, protein, fluid, carbohydrate, fat, sodium, or other nutrient requirements, depending on the patient''s condition and nutrition diagnosis. The prescription is developed during intervention, after the nutrition problem has been identified through assessment and diagnosis.', '["Nutrition assessment","Nutrition diagnosis","Nutrition intervention","Nutrition monitoring and evaluation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:00:50.762Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:00:50.762Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:00:50.762Z"'::jsonb),
('anki-card-1756972734067-78', 'anki-deck-1783610504561-1790433132438-14b68', 'A carbohydrate-rich diet may require more of which of the following vitamins?', 'thiamin', 'Thiamin (vitamin B1) is particularly important in carbohydrate metabolism. Its active form, thiamin pyrophosphate (TPP), functions as a coenzyme for several enzymes involved in glucose oxidation, including:

• Pyruvate dehydrogenase
• α-Ketoglutarate dehydrogenase
• Transketolase

Because carbohydrate metabolism increases when carbohydrate intake and utilization are high, an inadequate thiamin supply can become more clinically relevant. Thus, a carbohydrate-rich diet may increase the need for thiamin, particularly when carbohydrate intake is very high and the diet is otherwise nutrient-poor.', '["riboflavin","thiamin","vitamin c","niacin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:20.414Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:54:20.414Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:20.414Z"'::jsonb),
('anki-card-1756972784565-79', 'anki-deck-1783610504561-1790433132438-14b68', 'An athlete who consumes a high-protein diet would have an increased need of which of the following vitamins?', 'vit b6', 'Vitamin B6 is closely involved in amino acid and protein metabolism. Its active coenzyme form, pyridoxal 5′-phosphate (PLP), is required for numerous reactions involving amino acids, including transamination, decarboxylation, and other amino acid transformations.

Therefore, when protein intake and amino acid metabolism increase, the need for vitamin B6 may also increase. This is the classic nutrition relationship tested by this question:

Higher protein intake → increased amino acid metabolism → greater need for vitamin B6.

However, an important modern nuance is that athletes do not automatically require B6 supplementation simply because they consume a high-protein diet. Adequate dietary intake generally meets requirements, and supplementation should not be routinely recommended without evidence of inadequate intake or deficiency.', '["niacin","vit b12","vit b6","vit c"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:37.386Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:56:37.386Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:37.386Z"'::jsonb),
('anki-card-1756972953741-80', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following statements about folate is/are true?', 'all of the above', 'All three statements describe established roles of folate (vitamin B9), although B requires an important modern clarification regarding cardiovascular disease.

A. Neural tube defects: Folate is essential for DNA and nucleotide synthesis and cell division. Adequate folate before conception and during early pregnancy substantially reduces the risk of neural tube defects (NTDs). This is why folic acid supplementation is recommended for women who could become pregnant.

B. Homocysteine: Folate participates in the remethylation of homocysteine to methionine, a reaction that also requires vitamin B12. Folate deficiency can therefore contribute to elevated plasma homocysteine. Elevated homocysteine is associated epidemiologically with cardiovascular disease; however, lowering homocysteine with folic acid supplementation has not consistently been shown to reduce coronary heart disease events. Thus, the statement is correct regarding the biochemical relationship and association, but it should not be interpreted as proof that folic acid supplementation prevents CHD.

C. Folate and vitamin B12: Folate and vitamin B12 work together in one-carbon metabolism and DNA synthesis. Deficiency of either nutrient can impair DNA synthesis and produce megaloblastic/macrocytic anemia.', '["Folic acid supplementation is recommended for women of childbearing potential because it is necessary for nucleic acid synthesis and may help prevent neural tube defects.","Folate influences plasma homocysteine concentrations, and elevated homocysteine is associated with increased cardiovascular disease risk.","Folate works together with vitamin B12 (cyanocobalamin) in pathways important for preventing megaloblastic anemia.","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:43:46.361Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:43:46.361Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:43:46.361Z"'::jsonb),
('anki-card-1756973153099-82', 'anki-deck-1783610504561-1790433132438-14b68', 'During prolonged, high intensity physical activity, the muscle''s consumption of oxygen increases tenfold or more, enhancing the production of damaging free radicals in the body. Which of the following vitamins-mineral combinations would be potent on defending the cell membranes against oxidative stress?', 'Vitamin E, retinol, ascorbate, and selenium', 'This is the best answer because it combines several nutrients with established antioxidant roles:

• Vitamin E (tocopherol) is the major lipid-soluble antioxidant and is particularly important in protecting cell membranes from lipid peroxidation.
• Vitamin C (ascorbate) is a major water-soluble antioxidant and can help regenerate oxidized vitamin E.
• Vitamin A/retinoids have antioxidant-related functions, although the antioxidant activity of vitamin A is less central than that of vitamin E.
• Selenium is an essential component of glutathione peroxidases, antioxidant enzymes that help reduce hydrogen peroxide and lipid hydroperoxides.

Thus, among the choices, this provides the strongest combination of antioxidant nutrients, particularly for membrane protection.', '["Vitamin E, retinol, ascorbate, and selenium","Tocopherol, thiamin, ascorbate, and iron","Ascorbate, retinol, pyridoxal, and selenium","Vitamin C, Vitamin A, Vitamin B6, and zinc"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:14.245Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:59:14.245Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:32:34.946Z"'::jsonb),
('anki-card-1756973257093-83', 'anki-deck-1783610504561-1790433132438-14b68', '___ is a systematic head-to-toe examination of patient''s physical appearance and function to help determine nutrtional status by uncovering any signs of malnutrition, nutrient deficiencies or nutrient toxicities.', 'nutrition focused physical assessment', 'Nutrition-Focused Physical Assessment (NFPA) is a systematic physical examination performed by a nutrition professional to identify physical signs and symptoms associated with malnutrition, nutrient deficiencies, excesses, and other nutrition-related conditions.

It is an important component of the Nutrition Assessment step of the Nutrition Care Process. The examination may include observation, palpation, and assessment of areas such as:
• Muscle stores — e.g., temples, clavicles, shoulders, scapulae, interosseous muscles
• Subcutaneous fat stores — e.g., orbital region, triceps, ribs
• Skin, hair, and nails
• Eyes and oral cavity
• Edema and fluid accumulation
• Functional findings, when appropriate

Importantly, NFPA is not used in isolation to diagnose malnutrition. It is integrated with dietary history, anthropometric data, biochemical/medical information, and other relevant findings.', '["body composition analyzer","indirect calorimter","CT-scan with contrast","nutrition focused physical assessment"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:55:59.950Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:55:59.950Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:55:59.950Z"'::jsonb),
('anki-card-1756973304608-84', 'anki-deck-1783610504561-1790433132438-14b68', 'Route of access for patients with normal GI function and intact gag reflex.', 'nasogastric tube', 'A nasogastric (NG) tube is an appropriate route for short-term enteral nutrition when the GI tract is functional and the patient has an intact gag/cough reflex and can protect the airway.

An NG tube is inserted through the nose into the stomach, allowing delivery of enteral formula directly into the stomach.

In general, short-term enteral feeding is commonly delivered through a nasogastric or nasoenteric tube, whereas longer-term feeding may require an enterostomy such as a gastrostomy or jejunostomy.', '["enterostomy","multiple lumen tube","gastrotomy tube","nasogastric tube"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:23.776Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:09:23.776Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:09:23.776Z"'::jsonb),
('anki-card-1756973438869-86', 'anki-deck-1783610504561-1790433132438-14b68', 'The process of providing individualized professional guidance to assisst persons in adjusting their daily food consumption to meet their health needs.', 'Nutrition Counseling', 'Nutrition counseling is the process of providing individualized guidance and support to help a person modify food choices, eating behaviors, and dietary practices to meet specific health or nutrition needs.

It is an important component of nutrition care and involves communication between the nutrition professional and the client. Counseling may address:

• Food selection and meal planning
• Eating patterns and behaviors
• Portion sizes
• Dietary modifications appropriate to health conditions
• Barriers to dietary change
• Strategies for achieving and maintaining behavior change

The emphasis is on individualized guidance and behavior change, rather than simply giving a standardized diet prescription.', '["Nutrition Counseling","Medical Nutrition Therapy","Mechanical Problems","Nutrition Diagnosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:29.530Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:29.530Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:32:59.027Z"'::jsonb),
('anki-card-1756973485549-87', 'anki-deck-1783610504561-1790433132438-14b68', 'Designed for patients with impaired ability to ingest nutrient orally but has functioning GIT.', 'enteral nutrition', 'Enteral nutrition (EN) is the preferred method of providing nutrition when the gastrointestinal tract is functional but oral intake is inadequate, unsafe, or impossible.

EN delivers nutrients directly into the gastrointestinal tract, usually through a feeding tube such as a nasogastric, nasoenteric, gastrostomy, or jejunostomy tube.

The principle commonly emphasized in clinical nutrition is: “If the gut works, use it.”

Using the GI tract helps maintain gut integrity and function and is generally preferred over parenteral nutrition when feasible.', '["enteral nutrition","parental nutrition","a and b","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:41:44.591Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:41:44.591Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:41:44.591Z"'::jsonb),
('anki-card-1756973553878-88', 'anki-deck-1783610504561-1790433132438-14b68', 'Mr. JGH underwent a gastrectomy and is now on a clear liquid diet. Which of the following beverages will mostly cause dumping syndrome?', '12 oz apple juice', 'Apple juice is the best answer because it provides a relatively high amount of rapidly absorbable carbohydrate (simple sugars) in liquid form. After gastrectomy, the normal reservoir function of the stomach is reduced, allowing hyperosmolar contents, particularly liquids containing concentrated sugars, to enter the small intestine rapidly.

This can contribute to early dumping syndrome, which may produce abdominal cramping, bloating, nausea, diarrhea, tachycardia, flushing, and dizziness shortly after eating or drinking.

The large volume (12 oz ≈ 355 mL) also makes the apple juice a more likely trigger because rapid ingestion of a substantial volume of liquid can promote rapid gastric/small-intestinal delivery.', '["2 cups strained chicken broth","12 oz apple juice","1 cup unsweetened jelly","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:38:15.217Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:38:15.217Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:38:15.217Z"'::jsonb),
('anki-card-1756973607393-89', 'anki-deck-1783610504561-1790433132438-14b68', 'A patient diagnosed with Crohn''s disease and compromised distal ileum will benefit from which diet?', 'Vitamin B12 supplementation', 'The terminal (distal) ileum is the primary site for absorption of vitamin B12–intrinsic factor complexes. Crohn’s disease involving or requiring resection of the terminal ileum can therefore impair vitamin B12 absorption and increase the risk of vitamin B12 deficiency.

Depending on the extent of ileal disease or resection, patients may require vitamin B12 supplementation, sometimes by a parenteral route when adequate oral absorption cannot be relied upon.', '["Vitamin B12 supplementation","Low-calorie diet","Low-protein diet","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:21.175Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:21.175Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:33:24.152Z"'::jsonb),
('anki-card-1756973664559-90', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following characterized cholelithiasis?', 'Hardened deposits in the gallbladder', 'Cholelithiasis refers to the presence of gallstones (calculi) in the gallbladder. Gallstones form when components of bile, the most commonly cholesterol, but also bilirubin and calcium salts, precipitate and form solid particles.

Gallstones may be asymptomatic or may cause biliary colic when they obstruct the cystic duct. If obstruction occurs elsewhere in the biliary tree, complications can include acute cholecystitis, choledocholithiasis, cholangitis, or gallstone pancreatitis.

The two major types of gallstones are:
• Cholesterol stones — predominant in many populations.
• Pigment stones — composed primarily of calcium bilirubinate and associated with conditions such as chronic hemolysis or biliary infection, depending on the type.', '["Hardened deposits in the pancreas","Hardened deposits in the gallbladder","Scarring of the kidneys","Scarring of the lungs"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:30.157Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:54:30.157Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:30.157Z"'::jsonb),
('anki-card-1756973773337-91', 'anki-deck-1783610504561-1790433132438-14b68', 'Mrs. Lobardo will be given an enteral formula with 1.5 kcal/ml at 60 ml x 16 hours. It contains 55 grams of protein per liter. How much kcal and grams of protein will be provided to the patient?', '1440 kcal and 53 g protein', 'Step 1: Determine total volume administered: 60 mL/hour × 16 hours = 960 mL

Step 2: Calculate energy: 960 mL × 1.5 kcal/mL = 1,440 kcal

Step 3: Calculate protein: The formula contains 55 g protein/L.
960 mL = 0.96 L
0.96 L × 55 g/L = 52.8 g ≈ 53 g protein

Therefore: 1,440 kcal + 53 g protein', '["1690 kcal and 58 g protein","1640 kcal and 58 g protein","1580 kcal and 53 g protein","1440 kcal and 53 g protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:42.987Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:42.987Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:42.987Z"'::jsonb),
('anki-card-1756974003292-93', 'anki-deck-1783610504561-1790433132438-14b68', 'Which among the branched chain amino acid is/are the most important neurotoxic metabolite in MSUD? Which among the branched chain acid is/are required to be supplemented to control the plasma level of the said toxic.', 'leucine;  isoleucine and valine', 'In MSUD, there is deficient activity of the branched-chain α-ketoacid dehydrogenase (BCKDH) complex, which normally metabolizes the branched-chain amino acids (BCAAs):
• Leucine
• Isoleucine
• Valine

Consequently, both the BCAAs and their corresponding branched-chain α-ketoacids accumulate.

Among the three BCAAs, leucine is particularly important in the neurologic toxicity of MSUD. Markedly elevated plasma leucine is associated with cerebral edema and neurological manifestations, including lethargy, abnormal tone, seizures, and encephalopathy.

During nutritional management, dietary leucine is restricted, while isoleucine and valine are supplemented as needed. Providing these two BCAAs helps maintain adequate protein synthesis and prevents their concentrations from falling excessively while leucine intake is restricted. The amounts are carefully monitored according to plasma amino-acid concentrations.

Therefore:
Toxic metabolite of greatest concern → leucine
Supplemented BCAAs → isoleucine + valine', '["isoleucine; leucine and valine","valine; isoleucine and leucine","leucine;  isoleucine and valine","leucine and isoleucine; valine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:31.653Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T11:01:31.653Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:31.653Z"'::jsonb),
('anki-card-1756974084821-94', 'anki-deck-1783610504561-1790433132438-14b68', 'Compute for the total calories absorbed from 4 exchanges 2 L of 2.5% dialysate solution on a patient undergoing peritoneal dialysis assuming 60% absorption rate. Note: 1 gram dextrose =  3.4 kcal.', '408 kcal', 'Step 1: Calculate the amount of dextrose per 2-L exchange
A 2.5% dextrose solution contains: 2.5 g/100 mL
Since 2 L = 2,000 mL: 2000mL * (2.5 g ÷ 100 mL) = 50 g dextrose

Step 2: Calculate calories per exchange: 50 g * 3.4 kcal/g = 170 kcal

Step 3: Calculate calories from four exchanges: 170 * 4 = 680 kcal

Step 4: Apply the 60% absorption rate: 680 kcal * 0.60 = 408 kcal

Therefore, the patient absorbs approximately 408 kcal/day from the dialysate dextrose.', '["50 kcal","30 kcal","102 kcal","408 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:58:46.799Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:58:46.799Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:58:46.799Z"'::jsonb),
('anki-card-1756974161017-95', 'anki-deck-1783610504561-1790433132438-14b68', 'How many grams of protein would be a 50kg, metabolically stable, non-dialyzed, adult male patient diagnosed with CKD stage 4 sec to diabetic kidney disease be needing per day?', '40g', 'For a metabolically stable adult with CKD stages 3–5 who is not on dialysis, current KDIGO guidance suggests a protein intake of approximately 0.8 g/kg body weight/day.

For a 50-kg patient: 50 kg * 0.8 g/kg/day = 40 g/day

Therefore, the best answer is 40 g protein/day. The key information in the question is:

CKD Stage 4 → advanced CKD
Not on dialysis → protein needs are not increased for dialysis-related losses
Metabolically stable → the standard CKD protein recommendation applies
50 kg → use body weight for the calculation', '["15g","30g","40g","50g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:15.975Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:01:15.975Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:15.975Z"'::jsonb),
('anki-card-1756970990349-50', 'anki-deck-1783610504561-1790433132438-14b68', 'Post bariatric surgery dietary management:', 'all of the above', 'After bariatric surgery, the diet is advanced gradually according to the type of procedure and the patient''s tolerance. Early postoperative management commonly begins with clear liquids, followed by progressively thicker liquids and/or puréed or soft foods before advancing to regular textures. Small, frequent meals are essential because the reduced gastric capacity limits the amount that can be consumed at one time. The exact duration of each stage varies by surgical program, so “one month” for puréed foods should be regarded as a traditional/generalized schedule rather than a universal requirement.', '["clear liquid for the first day","pureed foods for a month","small feeding","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:20.728Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:20.728Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:20.728Z"'::jsonb),
('anki-card-1756969274695-24', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following are disease of the large intestines?', 'All of the above', 'Diverticular disease, irritable bowel syndrome (IBS), and constipation are all disorders involving the large intestine. Diverticular disease involves the formation and/or inflammation of diverticula, typically in the colon. IBS is a disorder of gut-brain interaction characterized by abdominal pain associated with altered bowel habits, while constipation involves infrequent or difficult bowel movements and commonly reflects impaired colonic transit or evacuation.', '["Diverticular disease","Irritable bowel syndrome","Constipation","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:40.217Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:09:40.217Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:09:40.217Z"'::jsonb),
('anki-card-1756969218317-23', 'anki-deck-1783610504561-1790433132438-14b68', 'Hypoparathyroidism can lead to Chvostek''s and Trousseau''s syndrome. Hyperparathyroidism, on the other hand, can cause osteopenia and osteoporosis.', 'both statements are correct', 'Hypoparathyroidism causes decreased parathyroid hormone (PTH), leading to hypocalcemia, which increases neuromuscular excitability and may produce Chvostek’s and Trousseau’s syndrome. In contrast, prolonged hyperparathyroidism increases PTH-mediated bone resorption, which can reduce bone mineral density and contribute to osteopenia and osteoporosis.', '["only statement 1 is correct","only statement 2 is correct","both statements are correct","both statements are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:48.223Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:48.223Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:48.223Z"'::jsonb),
('anki-card-1756969119237-22', 'anki-deck-1783610504561-1790433132438-14b68', 'How much energy can a 1 liter of 5% dextrose solution provide?', '170 kcal', 'A 5% dextrose solution (D5W) contains 5 g dextrose per 100 mL, or 50 g/L. Dextrose provides approximately 3.4 kcal/g when given intravenously.

Therefore: 50 g × 3.4 kcal/g = 170 kcal

Thus, 1 L of 5% dextrose provides approximately 170 kcal', '["170 kcal","100 kcal","150 kcal","200 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:48.705Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:48.705Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:48.705Z"'::jsonb),
('anki-card-1756969072722-21', 'anki-deck-1783610504561-1790433132438-14b68', 'A general principle in the prevention and management of an inborn error of metabolism if there is accumulation of precursor to toxic levels:', 'Restrict source of precursor', 'When an inborn error of metabolism causes a precursor to accumulate to toxic concentrations because it cannot be adequately metabolized, a key treatment principle is to restrict the dietary source of that precursor. This reduces substrate entering the defective metabolic pathway and helps prevent further accumulation and toxicity. The specific dietary restriction depends on the metabolic disorder—for example, phenylalanine restriction in phenylketonuria (PKU).', '["Provide replacement","Give increased quantities of the vitamin involved","Avoid exposure","Restrict source of precursor"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:50.009Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:01:50.009Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:50.009Z"'::jsonb),
('anki-card-1756968997193-20', 'anki-deck-1783610504561-1790433132438-14b68', 'All of the following are possible nutritional effects of intestinal resection among cancer patients EXCEPT:', 'Diabetes mellitus', 'Intestinal resection can lead to several gastrointestinal and nutritional complications depending on the site and extent of resection. These include diarrhea from reduced absorptive capacity, hyperoxaluria particularly after significant ileal resection, and blind loop syndrome when abnormal intestinal anatomy or stasis promotes bacterial overgrowth. Diabetes mellitus, however, is not a typical direct nutritional consequence of intestinal resection.', '["Blind loop syndrome","Hyperoxaluria","Diarrhea","Diabetes mellitus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:40:31.571Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:40:31.571Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:40:31.571Z"'::jsonb),
('anki-card-1756968894048-18', 'anki-deck-1783610504561-1790433132438-14b68', 'It is secreted by macrophages to active lymphocytes, suppress appetite and induce malaise and fever.', 'Monokines', 'Monokines are signaling proteins historically used to describe cytokines produced by monocytes and macrophages. Examples include interleukin-1 (IL-1) and tumor necrosis factor (TNF), which can promote immune-cell activation and produce systemic effects such as fever, anorexia, and malaise during inflammation.', '["Monokines","Cytokines","Macrokines","Complements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:52.886Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:52.886Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:52.886Z"'::jsonb),
('anki-card-1756968773103-16', 'anki-deck-1783610504561-1790433132438-14b68', '__ are responsible for cell-mediated immunity while __ are responsible for humoral immunity.', 'T cells, B cells', 'T lymphocytes are primarily responsible for cell-mediated immunity, including direct killing of infected or abnormal cells and coordination of immune responses. B lymphocytes are responsible for humoral immunity through their differentiation into plasma cells that produce antibodies.', '["T cells, B cells","B cells, T cells","Macrophages, B cells","B cells, macrophages"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:15.100Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:15.100Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:15.100Z"'::jsonb),
('anki-card-1756968840367-17', 'anki-deck-1783610504561-1790433132438-14b68', 'Electron-carrier molecules that are used in the electron-transport chain to generate additional ATP are:', 'NADH and FADH₂', 'NADH and FADH₂ are reduced electron carriers that transport high-energy electrons to the electron transport chain (ETC) in the inner mitochondrial membrane. As electrons pass through the ETC, the released energy drives proton pumping, creating a proton gradient that powers ATP synthase to produce ATP through oxidative phosphorylation.', '["Glucose and ketone bodies","Pyruvic acid and lactic acid","Acetyl CoA and amino acids","NADH and FADH₂"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:53:40.741Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:53:40.741Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:53:40.741Z"'::jsonb),
('anki-card-1756968718290-15', 'anki-deck-1783610504561-1790433132438-14b68', 'When a person is stressed, the secretion of the following hormones is increased EXCEPT:', 'Insulin', 'During physiological stress, the body enters a catabolic, hypermetabolic state designed to ensure adequate fuel availability. Glucagon, cortisol, and catecholamines increase and promote glycogenolysis, gluconeogenesis, lipolysis, and mobilization of energy substrates. 

Insulin secretion is generally suppressed or its action is reduced (insulin resistance) during the stress response, helping maintain elevated blood glucose for tissues with high energy demands.', '["Insulin","Glucagon","Cortisol","Catecholamines"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:00.751Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:00.751Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:00.751Z"'::jsonb),
('anki-card-1756968676056-14', 'anki-deck-1783610504561-1790433132438-14b68', 'Prolonged calorie undernutrition can cause a 20-30% decrease in BMR. Habitual high energy intake also decrease BMR.', 'Only statement 1 is correct', 'Prolonged energy restriction can reduce basal metabolic rate (BMR) through metabolic adaptation, including reduced thermogenesis and changes in metabolically active tissues and endocrine function. A decrease of approximately 20–30% has been described in severe or prolonged energy restriction. In contrast, habitual high energy intake does not decrease BMR; increased energy intake may increase diet-induced thermogenesis and total energy expenditure.', '["Only statement 1 is correct","Only statement 2 is correct","Both statement are correct","Both statement are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:25.590Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:25.590Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:25.590Z"'::jsonb),
('anki-card-1756968603646-13', 'anki-deck-1783610504561-1790433132438-14b68', 'This phytochemical, which is usually found in red wines and peanuts, prevents artery-damaging effects of high fat diets.', 'Resveratrol', 'Resveratrol is a polyphenolic compound found in the skin of red grapes and therefore in red wine, as well as in peanuts and some other plants. It has been studied for potential cardiovascular benefits through antioxidant, anti-inflammatory, and endothelial effects. The original wording that it “prevents” artery damage is too absolute; resveratrol is better described as a phytochemical associated with potentially protective cardiovascular effects.', '["Tannis","Phenols","Resveratrol","Isoflavones"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:40.085Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:40.085Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:40.085Z"'::jsonb),
('anki-card-1756968937628-19', 'anki-deck-1783610504561-1790433132438-14b68', 'These scavenge and engulf foreign bodies and secrete complements and cytokines.', 'Phagocytes', 'Macrophages are specialized phagocytic cells that engulf and digest pathogens, cellular debris, and other foreign material. They also secrete cytokines that regulate inflammation and immune responses and can produce components of the complement system. Macrophages also function as antigen-presenting cells, helping activate adaptive immune responses.', '["Phagocytes","Macropages","T cells","B cells"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:40.857Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:01:40.857Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:40.857Z"'::jsonb),
('anki-card-1756968549614-12', 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary antioxidants:
I. Manganese
II. Flavonoids
III. Phenolic compounds', 'All of the above', 'All three can contribute to antioxidant defense. Manganese is an essential mineral that is part of the antioxidant enzyme manganese superoxide dismutase (MnSOD), which helps neutralize superoxide radicals in mitochondria. Flavonoids and phenolic compounds are plant-derived phytochemicals that can have antioxidant activity by scavenging reactive species and influencing antioxidant pathways.', '["I only","I and II only","II and III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:09.028Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:09.028Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:09.177Z"'::jsonb),
('anki-card-1756968443387-10', 'anki-deck-1783610504561-1790433132438-14b68', '__ and__ are the major intracellular and extracellular cations in the body, respectively.', 'Potassium, sodium', 'Potassium (K⁺) is the major cation inside cells (intracellular fluid), while sodium (Na⁺) is the major cation outside cells (extracellular fluid). Their concentration gradients are maintained largely by the sodium-potassium pump (Na⁺/K⁺-ATPase), which is essential for maintaining cell membrane potential, nerve transmission, and muscle contraction.', '["Potassium, sodium","Potassium, phosphate","Sodium, chloride","Sodium, potassium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:12.160Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:12.160Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:12.160Z"'::jsonb),
('anki-card-1756968375740-9', 'anki-deck-1783610504561-1790433132438-14b68', 'A patient on tube feeding has a Diet Rx of 2000 Calories, 2:1 dilution; how much is the total fluid.', '1000 ml', 'In the traditional tube-feeding prescription, a 2:1 dilution means 2 kcal for every 1 mL of formula. 

Therefore: 2,000 kcal ÷ 2 kcal/mL = 1,000 mL/day

Thus, the total volume of tube-feeding formula prescribed is 1,000 mL/day.', '["1500 ml","1250 ml","1000 ml","2250 ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:42:21.301Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:42:21.301Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:42:21.301Z"'::jsonb),
('anki-card-1756968329042-8', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following enhances the absorption of zinc?', 'Glutamate', 'Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.', '["Glutamate","Tryptophan","Acetyl CoA","Thiamin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:42.623Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:42.623Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:42.623Z"'::jsonb),
('anki-card-1756968287658-7', 'anki-deck-1783610504561-1790433132438-14b68', 'Foods to avoid when preparing a patient for a test for occult blood in the stool:', 'Meat and leafy vegetables', 'For the traditional guaiac-based fecal occult blood test (gFOBT), patients may be instructed to avoid red meat and certain vegetables, particularly those containing peroxidase activity, because they can produce false-positive results. Examples include some leafy and cruciferous vegetables. This dietary restriction is specific to guaiac-based testing; newer fecal immunochemical tests (FIT) detect human hemoglobin and generally do not require these dietary restrictions.', '["Meat and leafy vegetables","Milk and cheese","Acidic fruits","Excessive fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:36.125Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:59:36.125Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:36.125Z"'::jsonb),
('anki-card-1756968231479-6', 'anki-deck-1783610504561-1790433132438-14b68', 'Keshan disease is a condition characterized by heart enlargement and is caused by deficiency of what nutrient?', 'Selenium', 'Keshan disease is a form of cardiomyopathy associated with severe selenium deficiency, originally described in areas of China with selenium-poor soil. It can cause cardiac enlargement, impaired cardiac function, and potentially heart failure. Selenium is important for antioxidant defense through selenoproteins such as glutathione peroxidases, which help protect tissues from oxidative damage.', '["Selenium","Zinc","Calcium","Potassium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:04.852Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:04.852Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:04.986Z"'::jsonb),
('anki-card-1756968184235-5', 'anki-deck-1783610504561-1790433132438-14b68', 'Substance found in raw egg white that binds with biotin preventing its absorption:', 'Avidin', 'Avidin is a glycoprotein found in raw egg white that binds very strongly to biotin (vitamin B7), reducing its intestinal absorption. Regular consumption of large amounts of raw egg white can therefore contribute to biotin deficiency. Cooking denatures avidin, greatly reducing its ability to bind biotin, which is why this problem is primarily associated with raw egg whites.', '["Avidin","Albumin","Vitelline","Ovomucin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:56.388Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:56.388Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:56.388Z"'::jsonb),
('anki-card-1756968140553-4', 'anki-deck-1783610504561-1790433132438-14b68', 'The conversion of acetyl-CoA into acetoacetic acid, beta-hydroxybutryric acid or acetone is called:', 'Ketogenesis', 'Ketogenesis is the metabolic process in which excess acetyl-CoA, primarily generated from fatty acid oxidation in the liver, is converted into ketone bodies: acetoacetate, β-hydroxybutyrate, and acetone. It becomes more active when carbohydrate availability or insulin action is insufficient, such as during prolonged fasting, starvation, or uncontrolled diabetes.', '["Ketogenesis","Gluconeogenesis","Glycogenolysis","Lipogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:08.139Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:08.139Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:08.139Z"'::jsonb),
('anki-card-1756968084754-3', 'anki-deck-1783610504561-1790433132438-14b68', 'What is the first feeding for a patient with 1200 kcal, 2:1 diet Rx?', 'No first feeding', 'In the traditional therapeutic-diet terminology used in Philippine dietetics, a 2:1 diet prescription refers to a diet in which the first feeding is omitted. The prescribed 1,200 kcal refers to the total daily energy allowance, but the specific first feeding is determined by the diet pattern/order rather than by simply selecting a liquid food. Thus, “no first feeding” is the intended answer.', '["1/2 evaporated milk diluted in 1/2 cup water","1/2 cup juice diluted in 1/2 cup water","No first feeding","Cannot be determined from the given provided"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:51.030Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:56:51.030Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:51.030Z"'::jsonb),
('anki-card-1756967954542-1', 'anki-deck-1783610504561-1790433132438-14b68', 'The enzyme that cleaves aromatic amino acids.', 'Chymotrypsin', 'Chymotrypsin is a pancreatic protease that preferentially cleaves peptide bonds on the carboxyl side of aromatic amino acids, particularly phenylalanine, tyrosine, and tryptophan. This specificity helps break dietary proteins into smaller peptides during intestinal digestion.', '["Chymotrypsin","Pepsin","Carboxypeptidase","Aminopeptidase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:43.709Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:59:43.709Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:43.709Z"'::jsonb),
('anki-card-1756968011507-2', 'anki-deck-1783610504561-1790433132438-14b68', 'It refers to the anabolic formation of triacyglycerol from glycerol and fatty acids.', 'Lipogenesis', 'Lipogenesis refers broadly to the formation and storage of fat, including the synthesis of triacylglycerol (TAG) from glycerol-derived molecules and fatty acids. It occurs primarily when energy intake exceeds immediate energy needs, allowing excess energy to be stored as body fat.', '["Lipogenesis","Fatty acid synthesis","Cholesterol synthesis","Gluconeogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:58:01.255Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:58:01.255Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:58:01.255Z"'::jsonb),
('anki-card-1756974219382-96', 'anki-deck-1783610504561-1790433132438-14b68', 'Patients with diabtes mellitus who are on long term metformin therpay are at risk what nutrient deficiency?', 'Vit B12', 'Vitamin B12 deficiency is a recognized potential adverse effect of long-term metformin therapy. Metformin can interfere with vitamin B12 absorption, and the risk generally increases with higher doses and longer duration of treatment.

The mechanism is multifactorial and may involve altered intestinal handling of the intrinsic factor–B12 complex, among other effects.

B12 deficiency is clinically important because it can cause:
• Megaloblastic anemia
• Peripheral neuropathy
• Paresthesia and other neurological manifestations
• Cognitive or neuropsychiatric changes in more severe cases

This is particularly relevant in patients with diabetes because B12 deficiency–related neuropathy can potentially be confused with or add to diabetic peripheral neuropathy.

Current diabetes guidance recommends considering periodic assessment of vitamin B12 status in patients taking metformin, particularly when treatment is prolonged or when anemia or neuropathy develops.', '["Vit B1","Vit B3","Vit B9","Vit B12"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:39.677Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:39.677Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:39.677Z"'::jsonb),
('anki-card-1756973351785-85', 'anki-deck-1783610504561-1790433132438-14b68', 'All are consequences of hospital malnutrition except:', 'decrease mortality and morbidity', 'Hospital malnutrition is associated with increased, not decreased, morbidity and mortality.

Disease-related malnutrition can impair immune function, reduce muscle mass and strength, delay tissue repair, and compromise recovery. Consequently, malnourished hospitalized patients are at greater risk of complications, infections, prolonged hospitalization, and poorer clinical outcomes.', '["decrease mortality and morbidity","poor wound healing","higher infection rates","longer hospital and ventilator days"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:07:08.788Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:07:08.788Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:07:08.788Z"'::jsonb),
('anki-card-1756970787459-46', 'anki-deck-1783610504561-1790433132438-14b68', 'Which drug may bind with phosphorus and reduce its absorption?', 'antacid', 'Some antacids, particularly those containing aluminum or calcium, can bind phosphate in the gastrointestinal tract and form poorly absorbed complexes, thereby reducing phosphorus absorption. This property is also therapeutically used with aluminum- or calcium-based phosphate binders in patients with chronic kidney disease and hyperphosphatemia.', '["antacid","laxative","digitails","amphetamines"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:19.699Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:19.699Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:19.699Z"'::jsonb),
('anki-card-1756967911837-0', 'anki-deck-1783610504561-1790433132438-14b68', 'Foods allowed in a low purine diet:', 'Milk, cheese, and eggs', 'These foods are generally low in purines and are appropriate choices in a low-purine diet. In contrast, organ meats contain very high amounts of purines and are restricted, particularly for patients with gout or hyperuricemia.', '["Milk, cheese, and eggs","Grandular organs","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:00.834Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:00.834Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:00.834Z"'::jsonb),
('anki-card-1756968484184-11', 'anki-deck-1783610504561-1790433132438-14b68', 'The body''s normal pH range is:', '7.35-7.45', 'Normal arterial blood pH is maintained at approximately 7.35–7.45, reflecting a slightly alkaline environment. The body tightly regulates pH through the bicarbonate buffer system, lungs, and kidneys.

Values below 7.35 indicate acidemia, while values above 7.45 indicate alkalemia.', '["7.35-7.45","7.45-7.55","7.25-7.35","7.00-7.45"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:14.911Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:39:14.911Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:15.026Z"'::jsonb),
('anki-card-1756972997906-81', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following vitamins is considered anti-infective vitamin?', 'Vit A', 'Vitamin A has historically been called the “anti-infective vitamin” because of its important role in maintaining epithelial and mucosal barriers and supporting both innate and adaptive immune function.

Vitamin A helps maintain the integrity and function of epithelial tissues lining the respiratory, gastrointestinal, and genitourinary tracts, which serve as important physical barriers against pathogens. It also contributes to normal immune-cell function and antibody responses.

Vitamin A deficiency can impair immune defenses and increase susceptibility to certain infections, particularly in children. Conversely, vitamin A supplementation has demonstrated benefits in specific populations with deficiency or certain infectious diseases, but routine high-dose supplementation is not recommended for everyone.', '["Vit A","Vit D","Vit E","Vit K"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:47:33.454Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:47:33.454Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:47:33.454Z"'::jsonb),
('anki-card-1756969541000-27', 'anki-deck-1783610504561-1790433132438-14b68', 'Childhood diarrhea plays a significant role in malnutrition. Infections within the intestine can lead to loss of nutrients, damage to the gut mucosa, and impaired nutrient absorption. The WHO and UNICEF guidelines for managing diarrheal diseases in children include which of the following?', 'All of the above', 'Management of acute diarrhea in children emphasizes preventing and treating dehydration with oral rehydration solution (ORS), continuing breastfeeding and age-appropriate feeding to prevent deterioration of nutritional status, and zinc supplementation to reduce the duration and severity of diarrhea and the risk of subsequent episodes. Therefore, all three are key components of recommended management.', '["Fluid replacement","Continued feeding","Zinc supplementation","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:58.600Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:58.600Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:58.600Z"'::jsonb),
('anki-card-1756969641114-28', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is true about anemia?
I. characterized by reduction in the size and quantity of red blood cells
II. result to decreased capacity of the blood to carry oxygen', 'both statement are correct', 'Anemia is defined by a reduction in hemoglobin concentration, hematocrit, or red blood cell mass below the normal range, resulting in reduced oxygen-carrying capacity of the blood. 

Statement I is incorrect because anemia does not necessarily involve a reduction in RBC size. RBC size may be normal (normocytic), small (microcytic), or large (macrocytic), depending on the underlying cause.', '["only statement 1 is correct","only statement 2 is correct","both statement are correct","both statement are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:57:16.931Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:57:16.931Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:57:16.931Z"'::jsonb),
('anki-card-1756969688195-29', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following proteins have an important role in the immune response?', 'Globulins', 'Globulins, particularly gamma globulins (immunoglobulins/antibodies), play an essential role in the immune response. Antibodies recognize and bind specific foreign antigens and help neutralize pathogens or facilitate their elimination. Other globulin proteins also include components involved in immune and inflammatory processes.', '["Fibrinogen","Lipoproteins","Globulins","Albumin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:07.320Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:07.320Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:07.320Z"'::jsonb),
('anki-card-1756969734576-30', 'anki-deck-1783610504561-1790433132438-14b68', 'Anemia that is induced by poor blood clotting:', 'Hemorrhagic anemia', 'Hemorrhagic anemia results from excessive blood loss, which can occur when blood clotting is impaired. Poor clotting allows bleeding to continue or become excessive, leading to loss of red blood cells and hemoglobin. Causes may include coagulation disorders, severe vitamin K deficiency, anticoagulant therapy, or other conditions that impair hemostasis. However, technically, poor clotting is a cause of blood loss rather than the defining cause of hemorrhagic anemia.', '["Microcytic anemia","Pernicious anemia","Hemorrhagic anemia","Hemolytic anemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:29.887Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:29.887Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:29.887Z"'::jsonb),
('anki-card-1756969777307-31', 'anki-deck-1783610504561-1790433132438-14b68', 'Osteomalacia is result of:', 'all of the above', 'Osteomalacia is defective mineralization of bone in adults, most commonly associated with vitamin D deficiency, which can result from inadequate dietary intake or insufficient sunlight exposure. Parathyroid disorders, particularly conditions causing increased PTH activity, can also contribute to impaired bone mineralization through disturbances in calcium and phosphate metabolism. Therefore, all three factors can contribute to osteomalacia.', '["dietary deficiency","inadequate sunlight exposure","parathyroid problems","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:53.484Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:53.484Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:53.484Z"'::jsonb),
('anki-card-1756969876769-32', 'anki-deck-1783610504561-1790433132438-14b68', 'Resting energy expenditure is the amount of energy required for the basal metabolic processes and TEF per unit weight per unit time. It is also called resting metabolic rate.', 'only statement 2 is correct', 'REE and RMR are generally used interchangeably to describe the energy expended by the body at rest to maintain essential physiological functions. However, statement 1 is incorrect because REE does not include the thermic effect of food (TEF). 

TEF is a separate component of total daily energy expenditure. Also, REE/RMR is usually expressed as kcal/day or kcal/kg/day, but “per unit weight per unit time” is not part of its defining concept. Commonly used REE or RMR Equations are Mifflin-St Jeor and Harris-Benedict, while TEF = REE + TEF + Activity Energy Expenditure.', '["only statement 1 is correct","only statement 2 is correct","both statements are correct","both statements are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:26.963Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:26.963Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:27.083Z"'::jsonb),
('anki-card-1756969922900-33', 'anki-deck-1783610504561-1790433132438-14b68', 'Which is not predisposing factor of gout:', 'low purine intake', 'Low purine intake is a protective factor, not a predisposing factor. A strict low-purine diet decreases the amount of uric acid produced in the body, lowering the risk of developing gout and reducing the frequency of painful flare-ups.

• High fat diet and starvation: High saturated fat diets impair the intestinal and renal excretion of urate. Starvation triggers the production of ketone bodies (like beta-hydroxybutyrate), which directly compete with uric acid for excretion sites in the kidneys, causing uric acid levels to skyrocket.
• Renal disorders: Roughly 90% of gout cases are caused by the kidneys'' inability to adequately excrete uric acid. Chronic kidney disease or renal insufficiency leads to hyperuricemia and crystal deposition.
• Obesity: Being overweight or obese increases the body''s internal production of uric acid while simultaneously reducing how efficiently the kidneys can filter and excrete it.', '["obesity","renal disorders","high fat diet, starvation","low purine intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:00:30.240Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:00:30.240Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:00:30.240Z"'::jsonb),
('anki-card-1756969982713-34', 'anki-deck-1783610504561-1790433132438-14b68', 'The following are dietary management for Wernicke-Korsakoff syndrome EXCEPT:', 'High energy and protein tube feedings', 'Wernicke-Korsakoff syndrome is associated with severe thiamine (vitamin B1) deficiency, commonly in the setting of chronic alcohol use and malnutrition. Management includes prompt thiamine replacement, adequate hydration and nutritional rehabilitation, and alcohol avoidance. However, high-energy/high-protein tube feeding is not a routine specific dietary management measure; enteral feeding is used when oral intake is inadequate or unsafe, and nutrition should be advanced appropriately rather than automatically prescribing high-energy, high-protein tube feeding.', '["Thiamine supplementation","Adequate hydration","Avoidance of alcohol","High energy and protein tube feedings"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:26.291Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:59:26.291Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:26.291Z"'::jsonb),
('anki-card-1756970100038-35', 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary management for Myasthenia Gravis:
I. adjusted food consistency depending on tolerance; nutrient-dense; small frequent feeding
II. avoid foods which contain I-dopa
III. limit dietary protein at breakfast and lunch
IV. low glycemic index treatment', 'I only', 'The major nutrition concerns in myasthenia gravis (MG) are fatigue and weakness of the muscles involved in chewing and swallowing, which can increase the risk of inadequate intake and aspiration. Appropriate management includes modifying food texture/consistency according to swallowing ability, choosing nutrient-dense foods, and using small, frequent meals to reduce fatigue during eating. Avoidance of L-dopa, protein restriction at specific meals, and low-glycemic-index treatment are not standard dietary therapies for MG.', '["I only","I and II only","I, II, III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:48:46.098Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:48:46.098Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:48:46.098Z"'::jsonb),
('anki-card-1756970199338-36', 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary recommendation for rheumatic fever:
I. high kcal, high protein, high fluids, low fiber
II.high kcal, high protein, Na and fluid controlled, vitamin and mineral supplements
III. high kcal, high protein, fat-restricted', 'II only', 'During acute rheumatic fever, nutrition should support growth, tissue repair, and recovery, so adequate energy and high-quality protein are important. When there is carditis or heart failure, sodium and fluid may need to be restricted to help control edema and fluid overload. Adequate vitamins and minerals should also be provided. There is no routine indication for a low-fiber diet or for fat restriction in rheumatic fever itself.', '["I only","II only","III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:41.412Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:41.412Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:41.412Z"'::jsonb),
('anki-card-1756970304232-37', 'anki-deck-1783610504561-1790433132438-14b68', 'An 84 year-old client complains of chronic constipation. To improve bowel function, what could be a possible intervention?', 'increasing fiber intake', 'Increasing dietary fiber, together with adequate fluid intake and appropriate physical activity, is a first-line approach for managing constipation in older adults when there is no contraindication. Fiber increases stool bulk and can improve bowel regularity. Fiber should be increased gradually, with adequate fluid intake, to minimize bloating and discomfort. For an older adult with chronic constipation, the underlying cause and medications should also be assessed.', '["increasing fiber intake","avoidance of binding foods such as cheese and chocolate","monitoring a balance between activity and rest","daily use of laxatives"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:42:35.158Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:42:35.158Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:42:35.158Z"'::jsonb),
('anki-card-1756970349379-38', 'anki-deck-1783610504561-1790433132438-14b68', 'What is the initial therapy for kwashiorkor?', 'fluid balance restoration', 'In severe acute malnutrition such as kwashiorkor, the initial priority is stabilization, particularly correction of life-threatening problems such as hypoglycemia, hypothermia, dehydration, and electrolyte imbalance. Rehydration must be done cautiously, because children with kwashiorkor may have edema and impaired cardiac/renal function, making them vulnerable to fluid overload. Energy and protein rehabilitation are important, but aggressive feeding or protein replacement should not be the first step during the initial stabilization phase.', '["fat replacement","energy replacement","protein replacement","fluid balance restoration"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:20.220Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:20.220Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:20.220Z"'::jsonb),
('anki-card-1756970423344-39', 'anki-deck-1783610504561-1790433132438-14b68', 'The following are dietary management for anorexia nervosa, EXCEPT:', 'use of food items that promote early satiety', 'Nutrition therapy for anorexia nervosa aims to restore weight and nutritional status while minimizing factors that interfere with adequate intake. Foods that promote early satiety—such as bulky, high-fiber, or large-volume foods—are generally avoided because they can make it difficult for the patient to consume sufficient energy. Instead, small, frequent, energy-dense meals are useful. Cold or room-temperature foods may be better tolerated in some patients, and limiting caffeine can help reduce appetite suppression and excessive stimulation.', '["use of food items that promote early satiety","small frequent feeding","give cold or room temperature foods","less caffeine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:28.303Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:28.303Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:28.303Z"'::jsonb),
('anki-card-1756970501190-40', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is NOT recommended for patients with gastroesophageal reflux disease (GERD)?', 'Increase the interval between meals by skipping meals', 'GERD management emphasizes meal size, meal timing, body position, and individualized trigger-food avoidance rather than deliberately skipping meals. Large meals, especially near bedtime, can worsen reflux, while remaining upright after eating can reduce symptoms. Patients are encouraged to identify foods and beverages that reliably trigger their symptoms rather than unnecessarily eliminating foods. Skipping meals or intentionally prolonging the interval between meals is not a standard GERD intervention.', '["Avoid large meals, particularly close to bedtime","Remain upright for several hours after meals","Identify and limit foods and beverages that consistently trigger symptoms","Increase the interval between meals by skipping meals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:04.496Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:04.496Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:04.496Z"'::jsonb),
('anki-card-1756970541653-41', 'anki-deck-1783610504561-1790433132438-14b68', 'How much sodium does a 1 tsp of salt contain?', '2000 mg', 'One teaspoon of table salt (sodium chloride) contains approximately 2,300 mg of sodium. However, nutrition teaching materials commonly use the approximation of 2,000 mg sodium per teaspoon of salt, which is the value this question is evidently targeting. Since the exact sodium content varies somewhat with the type and packing of salt, 2,000 mg is an approximation rather than an exact chemical value.', '["2000 mg","2500 mg","3000 mg","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:42.279Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:54:42.279Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:42.279Z"'::jsonb),
('anki-card-1756970584751-42', 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary management for hepatic coma:', 'high kcal, high protein', 'Current clinical consensus (from guidelines like AASLD, EASL, ESPEN, and ISHEN) rejects routine protein restriction in hepatic encephalopathy and hepatic coma because protein restriction worsens muscle wasting and catabolism without improving mental status. Patients generally require high caloric intake (about 30–40 kcal/kg/day) and adequate-to-high protein intake (about 1.2–1.5 g/kg/day), often favoring vegetable- or dairy-based proteins or branched-chain amino acids (BCAAs).', '["high kcal, zero to low protein","high kcal, high protein","high kcal, adequate protein","adequate kcal and protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:48:30.625Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:48:30.625Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:48:30.625Z"'::jsonb),
('anki-card-1756970652732-43', 'anki-deck-1783610504561-1790433132438-14b68', 'What vitamin should be provided for the dietary management for sideroblastic anemia that is characterized by pale RBC but with normal hemoglobin levels?', 'Vit B6', 'Vitamin B6 (pyridoxine) is an important cofactor in heme synthesis, particularly for the enzyme ALA synthase. Sideroblastic anemia results from impaired heme synthesis, causing iron to accumulate in erythroblast mitochondria and producing characteristic ring sideroblasts in the bone marrow. 

Some forms, particularly pyridoxine-responsive sideroblastic anemia, can respond to vitamin B6 supplementation. However, sideroblastic anemia has multiple causes, so B6 therapy is not appropriate for every case.', '["Vit B6","Vit B12","Vit K","Vit D"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:57:40.609Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:57:40.609Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:57:40.609Z"'::jsonb),
('anki-card-1756970699163-44', 'anki-deck-1783610504561-1790433132438-14b68', 'The following are dietary management measures for a patient with an ileostomy, EXCEPT:', 'high fiber', 'After an ileostomy, particularly during the initial postoperative period, a low-residue/low-fiber diet is commonly recommended to reduce stool volume and decrease the risk of obstruction. Adequate fluid and electrolyte intake is also important because ileostomy output can result in substantial fluid and sodium losses. Vitamin B12 supplementation may be necessary when the terminal ileum has been resected because this is the primary site of vitamin B12–intrinsic factor absorption. A low-fat diet may also be useful when fat malabsorption is present.', '["vit B12 supplementation","high fiber","low residue","low fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:36.152Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:36.152Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:36.152Z"'::jsonb),
('anki-card-1756973825883-92', 'anki-deck-1783610504561-1790433132438-14b68', 'A patient is receiving 250 mls of a 20% AA solution and 250 mls of 10% lipid emulsion. What is the total kcal provided?', '475 kcal', 'For PN calculations, the conventional values are:

Amino acids: 4 kcal/g
Dextrose: 3.4 kcal/g
IV lipid emulsion: 10 kcal/g

Protein: 20% AA, 250 mL:
250 mL × 20 g/100 mL = 50 g AA => 50 g × 4 kcal/g = 200 kcal

Lipids: 10% lipid emulsion, 250 mL:
250 mL × 10 g/100 mL = 25 g lipid => 25 g × 10 kcal/g = 250 kcal

Total = 200 + 250 = 450 kcal', '["450 kcal","475 kcal","550 kcal","555 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:09.242Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:54:09.242Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:09.242Z"'::jsonb),
('anki-card-1756970756562-45', 'anki-deck-1783610504561-1790433132438-14b68', 'The science that deals with the progressive movement and alteration of chemical substances within the body:', 'Pharmacokinetics', 'Pharmacokinetics describes what the body does to a drug, including its absorption, distribution, metabolism, and excretion (ADME). It examines how a drug moves through the body and how its concentration changes over time. 

Pharmacodynamics describes what the drug does to the body, including its mechanisms of action and effects on physiological processes. While Pharmacogenomics studies how an individual''s genetic variation influences drug response, including efficacy and adverse effects.', '["Pharmaconutrition","Pharmacodynamics","Pharmacokinetics","Pharmacogenomics"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:29.268Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:29.268Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:29.268Z"'::jsonb),
('anki-card-1756970829740-47', 'anki-deck-1783610504561-1790433132438-14b68', 'May interact with phenobarbital through competitive inhibition:', 'Folate', 'Phenobarbital and other anticonvulsants can interfere with folate metabolism and utilization, and long-term anticonvulsant therapy is associated with reduced folate status. Folate supplementation may therefore be needed in patients receiving prolonged therapy. The interaction is commonly described in nutrition/drug-interaction references as an effect of anticonvulsants on folate metabolism, although the exact pharmacokinetic mechanism is more complex than simple competitive inhibition.', '["Vit K","Folate","B vitamins","Vit C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:57.289Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:57.289Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:57.289Z"'::jsonb),
('anki-card-1756970871271-48', 'anki-deck-1783610504561-1790433132438-14b68', 'Foods to be restricted in dumping syndrome:', 'simple carbohydrates', 'In dumping syndrome, especially early dumping, rapid delivery of hyperosmolar food from the stomach into the small intestine can cause gastrointestinal and vasomotor symptoms.

Simple carbohydrates and concentrated sugars should be limited because they rapidly increase intestinal osmotic load and glucose absorption, potentially worsening symptoms.

Meals are generally made small and frequent, with adequate protein and moderate fat, and fluids are often consumed between rather than with meals.', '["simple carbohydrates","complex carbohydrates","protein foods","fat sources"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:53.033Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:59:53.033Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:53.033Z"'::jsonb),
('anki-card-1756974272380-97', 'anki-deck-1783610504561-1790433132438-14b68', 'This food label claim refers to a product containing 35 mg of sodium of per serving.', 'Very low in sodium', 'Under U.S. FDA food-labeling definitions, a food may be labeled “very low sodium” when it contains 35 mg or less of sodium per reference amount customarily consumed (RACC) or per labeled serving, depending on the applicable labeling provision.
Therefore, a product containing 35 mg sodium per serving meets the criterion for “very low sodium.”

For comparison, the commonly tested FDA definitions are:
• Claim - Sodium criterion
• Sodium-free / salt-free - <5 mg/serving
• Very low sodium - ≤35 mg/serving
• Low sodium - ≤140 mg/serving
• Reduced sodium - At least 25% less sodium than the reference food', '["No salt added","Sodium-free","Very low in sodium","Reduced sodium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:06.219Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:06.219Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:06.219Z"'::jsonb),
('anki-card-1756970946269-49', 'anki-deck-1783610504561-1790433132438-14b68', 'The following food are allowed for patient with celiac disease, EXCEPT:', 'textured vegetable protein', 'Patients with celiac disease must avoid gluten-containing ingredients and products with significant risk of gluten contamination. Plain yogurt, plain popcorn, and eggs are naturally gluten-free. Textured vegetable protein (TVP) is typically made from soy and is naturally gluten-free, but commercial products may contain wheat-derived ingredients or be produced in facilities where cross-contact with gluten can occur. Therefore, patients with celiac disease should check the label and choose a product specifically identified as gluten-free when appropriate.', '["yogurt","textured vegetable protein","popcorn","egg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:14.353Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:56:14.353Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:14.353Z"'::jsonb),
('anki-card-1756971033265-51', 'anki-deck-1783610504561-1790433132438-14b68', 'The following are management of hyperparathyroidism EXCEPT:', 'high calcium', 'In hyperparathyroidism, excessive calcium intake is generally not recommended because elevated parathyroid hormone (PTH) increases bone resorption and can contribute to hypercalcemia, particularly in primary hyperparathyroidism. 

Management focuses on addressing the underlying cause and maintaining appropriate calcium and phosphorus balance. In the traditional nutrition-management context, phosphate restriction/binders, adequate fluid intake, and an acid-ash diet may be included, particularly in renal/secondary hyperparathyroidism.', '["provide phosphate binders","high fluid","acid ash diet","high calcium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:00.593Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:00.593Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:00.593Z"'::jsonb),
('anki-card-1756971092562-52', 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is the primary purpose of nutrition screening?', 'identify clients who need complete nutrition assessment', 'Nutrition screening is a rapid process used to identify individuals who are at risk of malnutrition or who may benefit from further nutrition assessment. It is not intended to diagnose or fully characterize nutritional status. Those identified as being at risk are then referred for a comprehensive nutrition assessment, which provides the information needed for nutrition diagnosis and development of an appropriate nutrition intervention and care plan.', '["define nutritional status","identify clients who need complete nutrition assessment","determine nutrient needs","provide a basis for nutrition care plan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:02.971Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:02.971Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:02.971Z"'::jsonb),
('anki-card-1756971139443-53', 'anki-deck-1783610504561-1790433132438-14b68', 'The following are the domains of nutrition diagnosis, EXCEPT:', 'Biochemical Nutrition Diagnoses', 'The three domains of nutrition diagnosis in the Nutrition Care Process are Intake, Clinical, and Behavioral-Environmental. A nutrition diagnosis identifies a nutrition-related problem that the RND can address through intervention. While the term “Biochemical Nutrition Diagnoses” is one of the classes under the Clinical Nutrition Diagnoses Domain.', '["Biochemical Nutrition Diagnoses","Intake Nutrition Diagnoses","Clinical Nutrition Diagnoses","Behavioral-environmental Nutrition Diagnoses"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:32.738Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:09:32.738Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:22:46.391Z"'::jsonb),
('anki-card-1756971189224-54', 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary management for Guillain-Barré syndrome:', 'high energy and protein tube feedings', 'Guillain-Barré syndrome can cause progressive muscle weakness, dysphagia, and respiratory muscle paralysis. Patients with severe disease may be unable to meet their nutritional needs orally and may require enteral nutrition. Adequate energy and protein are important because of increased metabolic demands and the need to preserve lean body mass during prolonged illness and immobility. Tube feeding is appropriate when oral intake is unsafe or inadequate.', '["thiamine supplementation","adequate hydration","avoidance of alcohol","high energy and protein tube feedings"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:42:16.361Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:42:16.361Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:42:16.361Z"'::jsonb),
('anki-card-1756971267321-55', 'anki-deck-1783610504561-1790433132438-14b68', 'Method of delivery of EN when the rate is 300 to 400 ml, 20 to 30 minutes, several times/day via gravity drip or syringe, as determined by medical status, feeding route and volume and nutritional goals.', 'intermittent', 'Intermittent enteral feeding provides formula at scheduled intervals, commonly several times throughout the day. Each feeding may be delivered by gravity or syringe over approximately 20–30 minutes, depending on the patient''s medical status, feeding route, volume tolerance, and nutritional requirements. This approach more closely resembles normal meal patterns than continuous feeding.

Bolus → larger amount, relatively fast
Intermittent → scheduled “meals”
Cyclic → continuous, but only part of the day/night
Continuous → nonstop over an extended period', '["bolus","intermittent","cyclic","continuous"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:57:26.945Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:57:26.945Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:57:26.945Z"'::jsonb),
('anki-card-1756971306536-56', 'anki-deck-1783610504561-1790433132438-14b68', 'Enternal Nutrition composed of intact CPF:', 'polymeric', 'Polymeric formulas contain intact, whole macronutrients, including intact proteins, carbohydrates, and fats. They are designed for patients with a functioning gastrointestinal tract who can digest and absorb these nutrients adequately. They are the most commonly used type of standard enteral formula.

Intact CPF = Polymeric;
Broken down = Hydrolyzed;
One nutrient at a time = Modular;
Specific disease = Specialty', '["polymeric","modular","hydrolyzed","specialty"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:07.644Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:07.644Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:07.644Z"'::jsonb),
('anki-card-1756971370333-57', 'anki-deck-1783610504561-1790433132438-14b68', 'A compilation in parental nutrition with symptoms showing failure to grow, dermal problems, and poor immune function.', 'Essential Fatty Acid Deficiency', 'Essential fatty acid deficiency (EFAD) can occur in patients receiving parenteral nutrition when adequate essential fatty acids are not provided, particularly with prolonged fat-free PN. Clinical manifestations include poor growth or growth failure, dermatitis and other skin changes, impaired wound healing, and decreased immune function. Linoleic acid deficiency is particularly important because linoleic acid is an essential omega-6 fatty acid.', '["Essential Fatty Acid Deficiency","Metabolic imbalance","Air embolism","Hemothorax"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:55:06.458Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:55:06.458Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:23:29.466Z"'::jsonb),
('anki-card-1756971418497-58', 'anki-deck-1783610504561-1790433132438-14b68', 'High protein is given to burned patients to:', 'replace losses', 'Severe burns cause a marked hypermetabolic and hypercatabolic response, resulting in substantial protein breakdown and nitrogen losses. Protein requirements are therefore increased to replace these losses, support wound healing, immune function, and maintenance of lean body mass. Protein itself is not primarily given as an energy source; adequate carbohydrate and fat are provided to meet energy needs and help spare protein.', '["provide energy reserves","control water retention","replace losses","meet energy requiements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:38:30.557Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:38:30.557Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:38:30.670Z"'::jsonb),
('anki-card-1756971480578-59', 'anki-deck-1783610504561-1790433132438-14b68', 'Parental nutrition can be discontinued when approximately this percentage of estimated energy needs are being met by oral intake, tube feeding or combination of both.', '0.75', 'PN may generally be discontinued when the patient can consistently obtain approximately 60–75% or more of estimated energy and protein requirements through oral and/or enteral intake, provided that nutritional status is stable and intake is expected to remain adequate. In the context of this question, 75% is the best answer.', '["0.5","0,6","0.75","0.8"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:47:39.663Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:47:39.663Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:47:39.663Z"'::jsonb),
('anki-card-1756971528875-60', 'anki-deck-1783610504561-1790433132438-14b68', 'Amount of protein equivalent to a gram of nitrogen.', '6.25g', 'On average, protein contains approximately 16% nitrogen.

Therefore: 1 g nitrogen × 6.25 = 6.25 g protein
The factor 6.25 is derived from: 100 ÷ 16 = 6.25

This conversion is commonly used when calculating nitrogen balance, particularly in clinical nutrition and protein assessment.', '["0.16g","6.25g","54g","10g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:02:28.578Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:02:28.578Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:02:28.578Z"'::jsonb),
('anki-card-1756971569155-61', 'anki-deck-1783610504561-1790433132438-14b68', 'Compute the calories provided by a 2-L dialysate solution containing 2.5% dextrose.', '170 kcal', 'A 2.5% dextrose solution contains 2.5 g of dextrose per 100 mL.

For 2 L (2,000 mL):
2.5 g/100 mL × 2,000 mL = 50 g dextrose

Dextrose provides approximately 3.4 kcal/g
50 g × 3.4 kcal/g = 170 kcal

Therefore, the dialysate provides approximately 170 kcal.', '["108 kcal","148 kcal","170 kcal","200 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:26.428Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:26.428Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:26.428Z"'::jsonb),
