('anki-card-1758008848390-64', 'anki-deck-1783608918795-1790433140290-00vep', 'The appropriation of another person''s ideas, processes, results or words without giving appropriate credit or without proper permission.', 'Plagiarism', '', '["Fabrication","Falsification","Plagiarism"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-16T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.752Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758002534973-0', 'anki-deck-1783608918795-1790433140290-00vep', 'It is defined as a systematic enterprise that builds and organizes knowledge in the form of testable explanations and predictions about the universe.', 'Science', '', '["Science","Scientific method","Research","Research method"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-16T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.752Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
