('anki-card-1754880994112-4', 'anki-deck-1783608681588-1790433140276-5f3w7', 'Majority of the body protein is located in the ___.', 'Muscle', '', '["Muscle","Skeleton","Skin","Connective tissue"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.763Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
