('anki-card-1754884870635-39', 'anki-deck-1783608681588-1790433140276-5f3w7', 'Energy requirement of a 6 year old boy according to PDRI:', '1600 kcal', '', '["1470 kcal","1550 kcal","1600 kcal","1650 kcal"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.763Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
