('anki-card-1758696659828-106', 'anki-deck-1783608795320-1790433140288-uhh76', 'All are weaknesses of the 24-hour recall except: *', 'It is difficult to obtain information.', '', '["It provides information on a day’s intake only.","It is not representative of a typical food intake.","The respondent does not give accurate food intake.","It is difficult to obtain information."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
