('anki-card-1758696627479-104', 'anki-deck-1783608795320-1790433140288-uhh76', 'PEM affects certain population groups only. Adolescents, adult males, non-pregnant and non-lactating women have the lowest prevalence of PEM. *', 'Only the second statement is correct.', '', '["Only the first statement is correct.","Only the second statement is correct.","Both statements are correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
