('anki-card-1758816692523-189', 'anki-deck-1783609279327-1790433140276-ah6lq', 'Rank the following milk products from lowest to highest based on their fat content. I. Buttermilk II. Canned whole evaporated milk III. Canned whole sweetened condensed milk IV. Whipping cream V. Whole milk *', 'I, V, II, III, IV', '', '["III, II, I, V, IV","I, V, II, III, IV","II, III, V, IV, I","II, I, III, IV, V"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758816703023-190', 'anki-deck-1783609279327-1790433140276-ah6lq', 'Being clean in foodservice means free from visible soil or the goods are aesthetically clean. Sanitary means the foods are free from disease-causing organisms and contaminants. *', 'Both statements are correct.', '', '["Both statements are incorrect.","Both statements are correct.","The first statement is incorrect but the second statement is correct.","The first statement is correct but the second statement is incorrect."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
