('anki-card-1758816719569-192', 'anki-deck-1783609279327-1790433140276-ah6lq', 'Evaporated milk should be stored in the coolest part of the storeroom. The cans should be inverted at least once every 3 months. *', 'Both statements are correct.', '', '["Both statements are incorrect.","Only the first statement is correct.","Only the second statement is correct.","Both statements are correct."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
