('anki-card-1757931166912-31', 'anki-deck-1783609398838-1790433146200-hye2o', 'All of the following characteristics are shared by calcium and magnesium except*', 'Both are involved in blood clotting.', '', '["Both are involved in blood clotting.","Both are involved in bone formation.","Both are found in abundance in dairy products.","Both may result in tetany when blood levels become abnormally low."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757931153047-30', 'anki-deck-1783609398838-1790433146200-hye2o', 'Which of the following is not a process that directly involves calcium?*', 'pH regulation', '', '["pH regulation","blood clotting","nerve transmission","maintenance of heart beat"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
