('anki-card-1757931010554-19', 'anki-deck-1783609398838-1790433146200-hye2o', 'Which of the following is known to perform an essential function in the human body?*', 'Ubiquinone', '', '["Inositol","Ubiquinone","Pangamic acid","PABA"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
