INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1756218612158-52', 'anki-deck-1783609369423-1790433139853-3jf91', 'The Philippines'' abundant use of rice is reflected on its wide selection of rice-based desserts. Example of rice-based delicacies include the following EXCEPT:', 'Etag', 'Etag is a type of preserved meat, specifically salted and smoked pork, not a rice-based dessert.

• Tibok-Tibok: A Filipino dessert made from carabao’s milk and rice flour, often flavored with latik (coconut caramel).
• Kalamay: A sticky sweet delicacy made from glutinous rice, coconut milk, and sugar.
• Puto Calasiao: A type of steamed rice cake that originates from Calasiao, Pangasinan, made from fermented rice batter.', '["Tibok-tibok","Kalamay","Etag","Puto Calasiao"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:48:10.584Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:48:10.584Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:48:10.584Z"'::jsonb),
('anki-card-1756218734785-53', 'anki-deck-1783609369423-1790433139853-3jf91', 'The similarities in food culture between the Southern Philippines, Malaysia, and Indonesia are attributed to common religion. The similarity in food culture between the Philippines and Latin America is the history of colonization.', 'Both sentences are correct', 'Sentence A is correct. The southern Philippines, Malaysia, and Indonesia share a significant Muslim population, and their food cultures reflect Islamic dietary laws, including the use of halal ingredients and specific cooking practices.

Sentence B is also correct. The Philippines was colonized by Spain for over 300 years, which influenced Filipino cuisine with techniques and dishes similar to those found in Latin America, which were also Spanish colonies. Examples include the use of ingredients like tomatoes, garlic, and onions, as well as dishes like adobo and empanadas.', '["Only the first sentence is correct","Only the second sentence is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:05:27.830Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T14:05:27.830Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:05:27.830Z"'::jsonb),
('anki-card-1756218800082-54', 'anki-deck-1783609369423-1790433139853-3jf91', 'Considered as the healthiest among cuisines of Southeast Asia because of the use of a profusion of green leafy vegetables, bean sprouts, nuts, fresh herbs and lean meat.', 'Vietnamese', 'Vietnamese cuisine is renowned for its fresh ingredients, balanced flavors, and minimal use of oil. Dishes often incorporate a variety of vegetables and herbs, lean proteins, and rice, creating a light and nutritious meal profile. Popular dishes like pho, fresh spring rolls (goi cuon), and various salads (goi) highlight these healthy components.', '["Vietnamese","Myanmar","Thai","Lao"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:08:53.378Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:08:53.378Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:08:53.378Z"'::jsonb),
('anki-card-1756218884295-55', 'anki-deck-1783609369423-1790433139853-3jf91', 'A known Tausug dish. It is also called the black soup: because of its color. It is served hot and spicy, made from beef or chicken, flavored with ginder, tumeric, and burned coconut meat.', 'Tiula Itum', 'Tiula Itum is a traditional Tausug dish from the Sulu Archipelago in the southern Philippines. Its distinctive black color comes from the use of burned or charred coconut meat, which is combined with spices such as ginger and turmeric to create a flavorful and aromatic soup.

• Linat-an: A Visayan soup dish made with pork or chicken, vegetables like gabi (taro), corn, and green leafy vegetables, seasoned with ginger and other spices. It is comforting and mildly flavored.
• Batchoy: A hearty noodle soup originating from Iloilo, Batchoy is made with a flavorful pork and beef broth, round noodles, and topped with pork offal, crushed pork cracklings, garlic, and an egg. It’s savory, rich, and often served hot.
• Piarun: Also known as “Piyanggang,” this is a dish from the Tausug people of Mindanao, made with chicken or fish marinated in spices and burnt coconut, then grilled or stewed. It has a rich, smoky flavor with a complex blend of spices.', '["Linat-an","Tiula Itum","Batchoy","Piarun"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:07:39.635Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:07:39.635Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:07:39.635Z"'::jsonb),
('anki-card-1756218953940-56', 'anki-deck-1783609369423-1790433139853-3jf91', 'A Visayan soup dish made with pork or chicken, vegetables like gabi, corn, and green leafy vegetables, seasoned with ginger and other spices. It is comforting and mildly flavored.', 'Linat-an', '• Tiula Itum: A traditional Tausug dish from the Sulu Archipelago in the southern Philippines. Its distinctive black color comes from the use of burned or charred coconut meat, which is combined with spices such as ginger and turmeric to create a flavorful and aromatic soup.
• Batchoy: A hearty noodle soup originating from Iloilo, Batchoy is made with a flavorful pork and beef broth, round noodles, and topped with pork offal, crushed pork cracklings, garlic, and an egg. It’s savory, rich, and often served hot.
• Piarun: Also known as “Piyanggang,” this is a dish from the Tausug people of Mindanao, made with chicken or fish marinated in spices and burnt coconut, then grilled or stewed. It has a rich, smoky flavor with a complex blend of spices.', '["Linat-an","Tiula Itum","Batchoy","Piarun"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:16:04.210Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:16:04.210Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:16:04.210Z"'::jsonb),
('anki-card-1756219014923-57', 'anki-deck-1783609369423-1790433139853-3jf91', 'A heartly noodle soup originating from Iloilo, made with a flavorful pork and beef broth, round noodles, and topped with pork offal, crushed pork cracklings, garlic, and an egg.', 'Batchoy', '', '["Linat-an","Tiula Itum","Batchoy","Piarun"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:29:35.088Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:29:35.088Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:29:35.088Z"'::jsonb),
('anki-card-1756219110668-58', 'anki-deck-1783609369423-1790433139853-3jf91', 'Also known as Piyanggang, this is a dish from Tausug people of Mindanao, made with chicken or fish marinated in spices and burnt coconut, then grilled or stewed.', 'Piarun', '• Tiula Itum: A traditional Tausug dish from the Sulu Archipelago in the southern Philippines. Its distinctive black color comes from the use of burned or charred coconut meat, which is combined with spices such as ginger and turmeric to create a flavorful and aromatic soup.

• Linat-an: A Visayan soup dish made with pork or chicken, vegetables like gabi (taro), corn, and green leafy vegetables, seasoned with ginger and other spices. It is comforting and mildly flavored.

• Batchoy: A hearty noodle soup originating from Iloilo, Batchoy is made with a flavorful pork and beef broth, round noodles, and topped with pork offal, crushed pork cracklings, garlic, and an egg. It’s savory, rich, and often served hot.', '["Linat-an","Tiula Itum","Batchoy","Piarun"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:16:30.978Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:16:30.978Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:16:30.978Z"'::jsonb),
('anki-card-1756220392142-73', 'anki-deck-1783609369423-1790433139853-3jf91', 'The last date on which the product should be used:', 'Expiration', 'Expiration date is the last date on which the product should be used or consumed. It is often used for products where safety is a concern, indicating that after this date, the product may no longer be safe to consume.

• Best used by: This date indicates the last date recommended for the use of the product at its peak quality. It does not refer to safety but rather optimal quality.
• Packed on: This date indicates the date on which the product was packed or processed. It helps in tracking the freshness or age of the product.
• Sell by: This date is the date by which the product should be sold to the consumer. It indicates to the retailer how long to display the product for sale.', '["Best used by","Packed on","Sell by","Expiration"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:06:38.996Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T14:06:38.996Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:06:38.996Z"'::jsonb),
('anki-card-1756219199114-59', 'anki-deck-1783609369423-1790433139853-3jf91', 'Known as the most heat resistant spore-former found in food.', 'Clostridium botulinum', 'Clostridium botulinum is a bacterium that forms highly resistant spores capable of surviving harsh conditions, including heat. These spores can withstand temperatures higher than those that typically kill other bacteria. This resilience is a concern in food safety because if foods contaminated with Clostridium botulinum spores are improperly prepared or stored, conditions may allow the spores to germinate and produce botulinum toxin, which can cause severe foodborne illness (botulism) if ingested.

In canned foods, if the canning process does not achieve high enough temperatures or if there is a failure to seal the cans properly, C. botulinum spores can survive. Under these conditions, the spores can germinate and produce the toxin, which can cause botulism, a rare but serious illness characterized by symptoms like muscle weakness, difficulty swallowing, and respiratory issues. Proper canning techniques, including adequate heating and ensuring an airtight seal, are critical to preventing botulism.', '["Bacillus cereus","Mycobacterium tuberculosis","Clostridium botulinum","Salmonella typhimurium"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:08:30.016Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:08:30.016Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:08:30.016Z"'::jsonb),
('anki-card-1756219255295-60', 'anki-deck-1783609369423-1790433139853-3jf91', 'Black discoloration in canned products may be caused by:', 'All of the above', '• Bacillus nigrificans: This bacterium can produce black pigment and cause discoloration in canned foods.
• Iron sulfide formation: Reaction between iron in the can and sulfur compounds in the food can lead to black or dark discoloration.
• Hard water containing minerals: The minerals in hard water can interact with the food and contribute to color changes, including black discoloration.', '["Bacillus nigrificans","Iron sulfide formation","Hard water containing minerals","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:57:04.633Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:57:04.633Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:57:04.633Z"'::jsonb),
('anki-card-1756219364573-61', 'anki-deck-1783609369423-1790433139853-3jf91', 'Basis of pasteurization time and temperature.', 'Destruction of Coxiella burnetii', 'Pasteurization is primarily designed to ensure the destruction of Coxiella burnetii, the most heat-resistant pathogen found in milk. This bacterium is more resistant to heat compared to other pathogens like Escherichia coli and Salmonella, making it a key target for pasteurization processes. Effective pasteurization parameters are established to ensure the safety of milk and dairy products by targeting this particularly resilient microorganism.', '["Destruction of Coxiella burnetii","Destruction of Clostridium botulinum","Destruction of E.coli O157:H7","Destruction of Serratia marcescens"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:16:53.123Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:16:53.123Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:16:53.123Z"'::jsonb),
('anki-card-1756219434370-62', 'anki-deck-1783609369423-1790433139853-3jf91', 'It is a psychrotrophic foodborne pathogen.', 'Listeria monocytogenes', 'Listeria monocytogenes is a bacterium that can grow and thrive at refrigeration temperatures (psychrotrophic conditions), making it a significant concern in food safety. It can cause listeriosis, a serious illness primarily affecting pregnant women, newborns, elderly individuals, and those with weakened immune systems. Listeria monocytogenes is often associated with ready-to-eat foods such as deli meats, soft cheeses, and smoked seafood.

It can cause listeriosis, a serious illness primarily affecting pregnant women, newborns, elderly individuals, and those with weakened immune systems. Listeria monocytogenes is often associated with ready-to-eat foods such as deli meats, soft cheeses, and smoked seafood.

• Clostridium botulinum: An anaerobic bacterium that grows in low-oxygen environments, such as improperly canned foods. It is not typically psychrotrophic.
• Micrococcus luteus: A bacterium commonly found in soil, dust, and on skin. It is not known for psychrotrophic growth and is generally not associated with foodborne illness.
• Salmonella typhimurium: A pathogenic bacterium that thrives at warmer temperatures and is commonly associated with foodborne illness. It is not psychrotrophic.', '["Clostridium botulinum","Micrococcus luteus","Listeria monocytogenes","Salmonella typhimurium"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:16:42.091Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:16:42.091Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:16:42.091Z"'::jsonb),
('anki-card-1756219519982-63', 'anki-deck-1783609369423-1790433139853-3jf91', 'The pH of chili garlic is 6.0, therefore it is considered as:', 'Low acid food', 'According to food safety and regulatory guidelines (such as the FDA), foods are classified based on a critical pH threshold of 4.6:

• Low-acid food: Any food with a finished equilibrium pH greater than 4.6 and a water activity greater than 0.85. Because the chili garlic has a pH of 6.0 (which is above 4.6), it falls squarely into this category.
• Acid food: Foods that naturally have a pH of 4.6 or below.
• Acidified food: Low-acid foods to which acid(s) or acid food(s) are manually added to deliberately reduce the final equilibrium pH to 4.6 or below.

Because unacidified low-acid environments with a pH of 6.0 can support the growth of dangerous spores like Clostridium botulinum (botulism), commercial or shelf-stable chili garlic typically undergoes acidification to bring its pH down safely.', '["Low acid food","Acid food","Acidified food","High acid food"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:16:56.378Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:16:56.378Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:16:56.378Z"'::jsonb),
('anki-card-1756220502652-74', 'anki-deck-1783609369423-1790433139853-3jf91', 'You have only dried ground herb available, but the recipe call for 1 tbsp fresh herb. How will you substitute dried for fresh?', 'Use less - 1 tsp dried', 'When substituting dried herbs for fresh herbs in a recipe, the general rule of thumb is to use less dried herb than the amount of fresh herb called for. This is because dried herbs are more concentrated in flavor than fresh herbs due to the drying process.

The typical substitution ratio is 1 part dried herb for 3 parts fresh herb.', '["Use less - 1 tsp dried","Use the same amount","Use more - 2 tbsp","Use less – ½ tbsp"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:17:40.780Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:17:40.780Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:17:40.780Z"'::jsonb),
('anki-card-1756219708823-65', 'anki-deck-1783609369423-1790433139853-3jf91', 'Among the advantages of this food service system are the savings from large volume purchasing, reduced labor duplications, and effective quality control from having only one kitchen that deliver to satellite units.', 'Commissary system', 'In a Commissary system, food production is centralized in one main kitchen (commissary) where bulk food preparation and cooking take place. The prepared food is then distributed to satellite units or service points where it is served to customers. This centralized approach allows for efficient purchasing in bulk, reduces duplication of labor (since not every satellite unit needs its own full kitchen), and enables better quality control because all food production is managed centrally.

• Conventional System:
Description: In the conventional food service system, food is prepared, cooked, and served at the same location. It involves on-site preparation and serving, with all food being made fresh daily.
Advantages: Flexibility in menu changes, control over the preparation process, and immediate serving of freshly cooked food.

• Ready Prepared System:
Description: Also known as the cook-chill or cook-freeze system, this involves preparing and cooking food in advance, then chilling or freezing it for later reheating and serving.
Advantages: Efficiency in labor and time, reduced peak-hour pressures, and extended service hours with consistent food quality.

• Assembly/Serve System:
Description: This system involves assembling pre-prepared food items into final meals at the service site. The food is usually purchased fully prepared and only needs to be heated or assembled before serving.
Advantages: Minimal on-site labor required, consistency in food quality, and reduced need for complex food preparation equipment.
Each system has its own set of advantages tailored to different operational needs and goals.', '["Conventional system","Ready Prepared system","Commissary system","Assembly/Serve system"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:34:01.620Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:34:01.620Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:34:01.620Z"'::jsonb),
('anki-card-1756219823201-66', 'anki-deck-1783609369423-1790433139853-3jf91', 'This leadership theory sets an assumption that employees have an inherent dislike of work and will avoid it if possible.', 'Theory X', 'Theory X is part of Douglas McGregor’s Theory of Motivation and Management, which suggests that employees are inherently lazy and dislike work. According to Theory X, employees need to be closely supervised and controlled to ensure they work effectively.

• Scientific Approach: This approach, developed by Frederick Taylor, focuses on improving work efficiency through scientific methods, such as time studies and work specialization. It emphasizes optimizing tasks and productivity rather than assumptions about employee motivation.
• Human Relations Approach: This approach highlights the importance of employee morale and interpersonal relationships in improving productivity. It emerged from studies such as the Hawthorne Studies and emphasizes the psychological and social aspects of work.
• Theory Y: Proposed by Douglas McGregor, Theory Y is the counterpart to Theory X. It assumes that employees are self-motivated, enjoy work, and seek responsibility. This theory suggests that workers are motivated by intrinsic factors and can be creative and productive if given the right environment.', '["Scientific approach","Human relations approach","Theory X","Theory Y"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:41:22.993Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:41:22.993Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:41:22.993Z"'::jsonb),
('anki-card-1756219946096-67', 'anki-deck-1783609369423-1790433139853-3jf91', 'An inventory system where stocks are maintained at a certain level each time an order regardless of the amount on hand and the of order.', 'Par stock system', 'In a par stock system, inventory is maintained at a predetermined level (par stock) regardless of current inventory levels. When the stock reaches or falls below this set level, an order is placed to replenish it back to the par level. This system focuses on keeping inventory consistently at the desired level to ensure smooth operations.

In a Par stock system:

A predetermined minimum quantity (the par level) of each item is maintained in stock. Whenever the inventory level drops to the par level due to sales or usage, a replenishment order is placed. The order quantity is typically fixed and does not depend on the current inventory level.

This system helps in maintaining consistent stock levels and ensures that inventory is replenished promptly when it reaches the par level.

FIFO (First-In, First-Out):
Description: An inventory management method where the oldest stock (first-in) is sold or used first before newer stock (last-in). This approach helps prevent inventory from becoming obsolete and is often used for perishable goods.

Buffer System:
Description: Also known as a safety stock system, this approach involves maintaining an additional quantity of stock (buffer or safety stock) to protect against variations in demand or supply delays. It ensures that there is always a reserve to cover unexpected changes.', '["FIFO","Min-Max system","Par stock system","Buffer system"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:17:16.565Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:17:16.565Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:17:16.565Z"'::jsonb),
('anki-card-1756220051191-68', 'anki-deck-1783609369423-1790433139853-3jf91', 'The following are functional subsystems of a traditional food service operation, except:', 'Packaging', 'Packaging is not typically considered a functional subsystem within a traditional food service operation. While food packaging is essential in certain contexts (such as retail food products or take-out services), traditional food service operations primarily focus on preparing and serving food rather than packaging it for distribution or sale.', '["Production","Storage and Inventory","Packaging","Sanitation and Maintenance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:16:46.306Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:16:46.306Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:16:46.306Z"'::jsonb),
('anki-card-1756220135036-69', 'anki-deck-1783609369423-1790433139853-3jf91', 'In resource conservation, this term applies to the consideration of the design and manufacture of products and packaging with minimum toxic content and volume of material and its longevity.', 'source reduction', 'Source reduction focuses on reducing the amount of waste generated at the source by designing products that use less material, are less toxic, and have longer lifespans. It aims to prevent waste before it is created.', '["source reduction","waste segregation","recycling","land filling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:38:57.444Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:38:57.444Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:38:57.444Z"'::jsonb),
('anki-card-1756220213400-70', 'anki-deck-1783609369423-1790433139853-3jf91', 'The transformation of raw or processed foods into an acceptable finished product.', 'Food Production', 'Food production involves the actual preparation and assembly of ingredients and materials to create finished dishes or food items that are ready to be served to customers. It encompasses all activities related to cooking, baking, assembling, and garnishing food according to recipes and standards.', '["Standardized recipe","Food Production","Kitchen brigade","Forecasting"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:16:37.259Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:16:37.259Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:16:37.259Z"'::jsonb),
('anki-card-1756220635663-76', 'anki-deck-1783609369423-1790433139853-3jf91', 'When purchasing canned goods, a bulging end is an indication that the product may:', 'Cause botulism', 'Bulging cans can be a sign of botulism, a serious and potentially deadly illness caused by the toxin produced by Clostridium botulinum bacteria. These bacteria can thrive in anaerobic (low-oxygen) conditions, such as those found inside improperly sealed or damaged cans. Consuming food contaminated with botulinum toxin can lead to severe illness.', '["Cause botulism","Be ok to purchase","Be lower in weight than normal","May have parasitic infestation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:01:13.223Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:01:13.223Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:01:13.293Z"'::jsonb),
('anki-card-1756220676995-77', 'anki-deck-1783609369423-1790433139853-3jf91', 'It is an example of curing salt:', 'Prague powder', 'Prague powder, also known as pink curing salt, is a specific type of curing salt used in preserving meats such as bacon, ham, and sausages. It contains sodium nitrite, which helps prevent bacterial growth and gives cured meats their characteristic pink color and flavor.

• Rub: A mixture of spices, herbs, and sometimes salt that is applied to the surface of meat to add flavor. It is not a curing salt but is used primarily for seasoning.
• Kosher salt: A coarse-grained salt commonly used in cooking and for koshering meat. It is not typically used for curing but is favored for its clean flavor and ability to draw out moisture from foods.
• Fleur de sel: A type of sea salt harvested from the surface of salt ponds. It is prized for its delicate flavor and texture and is often used as a finishing salt, but it is not used for curing.', '["rub","Prague powder","Kosher salt","leur de sel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:17:32.317Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:17:32.317Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:17:32.317Z"'::jsonb),
('anki-card-1756220723877-78', 'anki-deck-1783609369423-1790433139853-3jf91', 'Gas that cause the fruit to ripen:', 'ethylene', 'Ethylene is a natural plant hormone that plays a key role in the ripening process of fruits. It is produced by fruits themselves as they ripen and can also be released by other fruits nearby, leading to a chain reaction of ripening in a group of fruits.', '["carbon monoxide","propane","nitrogen","ethylene"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:17:57.880Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:17:57.880Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:17:57.880Z"'::jsonb),
('anki-card-1756220763341-79', 'anki-deck-1783609369423-1790433139853-3jf91', 'Ingredients in chocolate milk that comes from seaweed.', 'carrageenan', 'Carrageenan is a natural food additive derived from various species of red seaweed. It is commonly used in the food industry as a thickening and stabilizing agent.

In chocolate milk, carrageenan helps to prevent separation of the milk and cocoa particles, providing a smooth and creamy texture.

• Glucose is a simple sugar that is often used as a sweetener in various food products. It is not derived from seaweed.
• Sucrose is a common sugar, made up of glucose and fructose, typically derived from sugar cane or sugar beets. It is also not derived from seaweed.
• Cocoa is the main ingredient in chocolate, derived from cocoa beans. It provides the chocolate flavor in chocolate milk but does not come from seaweed.', '["carrageenan","glucose","sucrose","cocoa"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:03:51.130Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:03:51.130Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:03:51.130Z"'::jsonb),
('anki-card-1756220811738-80', 'anki-deck-1783609369423-1790433139853-3jf91', 'The process by which a liquid is separated from a gel; commonly observed during cooling.', 'syneresis', 'Syneresis occurs when a gel contracts or shrinks, causing the expulsion of liquid from the gel network. This separation of liquid from the gel can be seen as small droplets or pools of liquid forming on the surface of the gel or around its edges.

• Gelation is the process of forming a gel from a liquid, usually by cooling or adding a gelling agent. This process is the opposite of syneresis, as it involves the formation of a gel rather than the separation of liquid from it.
• Hydrolysis is a chemical process in which a molecule is broken down into smaller components by the addition of water. This term is more related to the breakdown of substances than to the separation of liquid from a gel.', '["syneresis","gelation","hydrolysis","gelatinization"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:03:11.558Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:03:11.558Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:03:11.558Z"'::jsonb),
('anki-card-1756220872817-81', 'anki-deck-1783609369423-1790433139853-3jf91', 'The astringent taste of certain fruits is due to their high content of:', 'tannins', 'Tannins are polyphenolic compounds found in plants, including fruits like grapes, apples, and some berries. They contribute to an astringent taste sensation, which can make the mouth feel dry or puckered. Tannins bind to proteins and other compounds in the mouth, causing this characteristic sensation.

• Tannins are responsible for the astringent taste in certain fruits.
• Acids contribute to sourness, not astringency.
• Pectin is involved in gelling, not taste.
• Fiber affects texture but not astringency.', '["acids","tannins","pectin","fiber"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:11:38.162Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:11:38.162Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:11:38.162Z"'::jsonb),
('anki-card-1756220931682-82', 'anki-deck-1783609369423-1790433139853-3jf91', 'Freezer burn results from:', 'poor packaging resulting in moisture loss', 'Freezer burn occurs when moisture evaporates from the surface of frozen food, leading to dehydration and the formation of ice crystals. This happens due to improper packaging that allows air to come into contact with the food, causing moisture loss and oxidation.', '["chilling quickly","airtight moisture resistant packaging","poor packaging resulting in moisture loss","enzymes present in food"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T12:57:14.303Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T12:57:14.303Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T12:57:14.303Z"'::jsonb),
('anki-card-1756221007513-83', 'anki-deck-1783609369423-1790433139853-3jf91', 'Sterilization is a process by which:', 'kills or removes all forms of microbial life', 'Sterilization is the complete destruction or removal of all forms of microbial life, including bacteria, viruses, fungi, and spores. It aims to make an object or environment free from viable microorganisms to ensure it is completely safe and free from contamination.', '["kills or removes all forms of microbial life","kills only pathogenic microorganism","kills only microorganism that cause spoilage","kills only vegetative forms of bacteria but not spore"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:15:14.107Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T14:15:14.107Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:15:14.107Z"'::jsonb),
('anki-card-1756265803723-87', 'anki-deck-1783609369423-1790433139853-3jf91', 'Refers to specific knowledge and expertise in a particular field or industry, important for lower levels of management, they become less critical.', 'Technical skill', 'Technical skill refers to specific knowledge and expertise in a particular field or industry. While technical skills are important for lower levels of management, they become less critical at the top level where managers focus more on overseeing and directing rather than performing technical tasks.

• Conceptual skill: Involves the ability to think strategically, understand complex situations, and develop innovative solutions. Top-level managers need strong conceptual skills to envision the organization’s future direction, set goals, and formulate strategic plans.
• Human skill: Also known as interpersonal or people skills, human skills involve the ability to work effectively with others, motivate and lead teams, and build relationships. These skills are important at all levels of management but are particularly crucial for middle managers who directly supervise employees.
• Administrative skill: Involves the ability to manage tasks, processes, and resources efficiently. It includes planning, organizing, coordinating, and controlling activities within the organization. Administrative skills are essential for all levels of management but are typically more operational in nature compared to conceptual skills.', '["Conceptual skill","Technical skill","Human skill","Administrative skill"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T12:59:44.947Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T12:59:44.947Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T12:59:44.947Z"'::jsonb),
