('anki-card-1758812143713-27', 'anki-deck-1783608806858-1790433140285-ai0do', 'An advantage of food intake records is that: *', 'The client may also record behaviors associated with eating symptoms, associated with eating foods, and physical activities.', '', '["The client may change eating behaviors during the times records are kept.","The client may also record behaviors associated with eating symptoms, associated with eating foods, and physical activities.","The client must diligently maintain the record.","The records are easy to keep."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
