('anki-card-1758812324803-46', 'anki-deck-1783608806858-1790433140285-ai0do', 'Nutrition rehabilitation is a developmental intervention. It will develop the mental capacity of a malnourished child. *', 'Both statements are incorrect.', '', '["Both statements are correct.","Only the second statement is correct.","Only the first statement is correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
