INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1756359163332-50', 'anki-deck-1756357465257-1790432463920-rf85m', 'Dietary management for pancreatitis:', 'NPO, enzyme replacement, low fat, avoidance of stimulants', 'Pancreatitis is inflammation of the pancreas and may be classified as acute or chronic. Although both conditions require nutrition management, their dietary recommendations differ according to disease stage and severity. 

During acute pancreatitis, patients with moderate to severe disease may initially require bowel rest if oral feeding is not tolerated because of severe abdominal pain, nausea, vomiting, or ileus. However, current guidelines recommend early oral or enteral feeding once clinically tolerated, as prolonged fasting is no longer routinely advised. In chronic pancreatitis, nutrition therapy aims to prevent malnutrition, reduce pancreatic stimulation, and improve nutrient absorption.

• NPO (Nil Per Os / Nothing by Mouth): During acute episodes or severe flare-ups of pancreatitis, bowel rest (keeping the patient NPO) is primary to minimize pancreatic stimulation and reduce auto-digestion of the organ.
• Enzyme Replacement: For patients with exocrine pancreatic insufficiency (EPI) or chronic pancreatitis, taking Pancreatic Enzyme Replacement Therapy (PERT) with meals is necessary to facilitate proper macronutrient digestion and nutrient absorption.
• Low Fat: Fat is a potent stimulant of pancreatic enzyme secretion. Restricting fat intake (often between 30–50 grams per day) and spreading it across small, frequent meals helps alleviate abdominal pain and prevent fatty stools (steatorrhea).
• Avoidance of Stimulants: Patients must strictly avoid pancreatic irritants and stimulants, most notably alcohol and nicotine, as they directly exacerbate inflammation and disease progression.', '["High kcal, low protein, high carbohydrate, high fiber","NPO, enzyme replacement, low fat, avoidance of stimulants","High kcal, high protein, low fat","Liquid diet, iron supplementation, low fiber"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T06:41:15.756Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T06:41:15.756Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T06:41:15.756Z"'::jsonb),
('anki-card-1756359083584-47', 'anki-deck-1756357465257-1790432463920-rf85m', 'Severe weight loss is defined as:
I. 5% over a month
II. >5% over 1 month
III. 7.5% over 3 months
IV. >7.5% over 3 months', 'II and IV only', 'Severe weight loss is diagnosed when unintentional weight loss exceeds significant thresholds: >5% in 1 month, >7.5% in 3 months, or >10% in 6 months (Statements II and IV).', '["I and III only","II and IV only","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:09:12.138Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:09:12.138Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T15:09:12.138Z"'::jsonb),
('anki-card-1756358998839-44', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is NOT a general dietary recommendation for patients with HIV/AIDS?', 'Fiber-restricted', 'Nutrition therapy is an essential component of the management of HIV/AIDS, helping maintain body weight, preserve lean body mass, support immune function, and improve quality of life. Energy and protein requirements are often increased because of chronic infection, inflammation, opportunistic infections, and the increased metabolic demands associated with HIV. 

General nutrition recommendations include: 
• High-calorie diet to prevent or manage unintended weight loss. 
• High-protein diet to preserve muscle mass and promote tissue repair. 
• Adequate intake of vitamins, minerals, and fluids. 
• Food safety practices to reduce the risk of foodborne illness. 
• Nutrition interventions tailored to treatment-related side effects such as nausea, diarrhea, or oral lesions.

Dietary fiber provides important benefits, including promoting bowel health, improving glycemic control, and supporting a healthy gut microbiota. Fiber restriction is reserved for specific clinical situations, such as severe diarrhea, intestinal obstruction, or acute gastrointestinal complications, and is not recommended as a standard dietary approach for all patients with HIV/AIDS.', '["High calorie","High protein","Fat-controlled","Fiber-restricted"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:36:50.055Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:36:50.055Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:36:50.055Z"'::jsonb),
('anki-card-1756359051804-46', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is NOT a source of data for nutrition assessment?', 'None of the above', 'All of the options listed are actually valid and standard sources of data used by dietitians and healthcare professionals when performing a thorough Nutrition Assessment:

• Family history: Part of the Client History (CH) domain. It provides vital background on hereditary risks for chronic metabolic conditions like diabetes, cardiovascular diseases, or inborn errors of metabolism.
• Medical record: This serves as a primary hub for objective data including patient demographics, medical history, clinical diagnoses, surgical histories, and Biochemical Data/Medical Tests (such as lab panels or imaging).
• Referral form: A referral from a physician or another healthcare provider frequently contains initial clinical data, anthropometric measurements, the explicit medical reason for nutrition intervention, and immediate dietary constraints.', '["Family history","Medical record","Referral form","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:30:06.003Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:30:06.003Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T14:30:06.003Z"'::jsonb),
('anki-card-1756358957273-42', 'anki-deck-1756357465257-1790432463920-rf85m', 'The following are general dietary management for fevers and infections, EXCEPT:', 'Low fat', 'During fever and infection, the body enters a hypermetabolic and catabolic state, resulting in increased energy expenditure, accelerated protein breakdown, and increased fluid losses. Nutrition therapy aims to support immune function, preserve lean body mass, promote recovery, and prevent malnutrition. 

A low-fat diet is not routinely recommended for patients with fever or infection. Dietary fat is an important source of concentrated energy, particularly when appetite is poor. Fat restriction is indicated only in specific clinical conditions such as pancreatitis, fat malabsorption, or certain hepatobiliary disorders—not as part of the general management of fever and infection.', '["High Kcal","High Protein","High fluids","Low fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:39:34.739Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:39:34.739Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T15:39:34.739Z"'::jsonb),
('anki-card-1756358909108-40', 'anki-deck-1756357465257-1790432463920-rf85m', 'Dietary management for Parkinson’s Disease
I. Adjust food consistency to facilitate chewing and swallowing; ensure adequate fiber and fluid intake; limit dietary protein at breakfast and lunch in patients receiving levodopa therapy when indicated; avoid foods or supplements containing large amounts of L-dopa.
II. Adjust food consistency according to tolerance; provide nutrient-dense foods; and offer small, frequent meals.', 'All of the above', 'Both statements accurately outline essential, standard clinical protocols for managing a patient with Parkinson''s Disease (PD):

	• Dysphagia & Constipation: As PD progresses, motor degradation often leads to chewing and swallowing difficulties (dysphagia), requiring textured food or modified consistencies. Autonomic dysfunction also slows down the GI tract, making a high-fiber and high-fluid regimen critical to preventing chronic constipation.
	• The Protein-Levodopa Interaction: Levodopa (the primary medication for PD) utilizes the same active transport carriers across the blood-brain barrier as dietary amino acids. Limiting or shifting protein intake away from breakfast and lunch prevents dietary protein from competing with the medication, ensuring the drug maintains its clinical efficacy throughout the day.
	• Exogenous L-dopa: Avoiding foods/supplements with variable amounts of natural L-dopa (like fava beans) prevents unpredictable fluctuations or sudden toxicity.

	• Malnutrition & Early Satiety: Due to tremors, high metabolic demands, and slow chewing, PD patients are exceptionally prone to unintentional weight loss and muscle wasting. Offering small, frequent, and nutrient-dense meals tailored to their structural texture tolerance optimizes daily caloric intake without overwhelming the patient or causing early fatigue during meals.', '["I only","II only","None of the above","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T09:41:41.688Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T09:41:41.688Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T09:41:41.864Z"'::jsonb),
('anki-card-1756358883675-39', 'anki-deck-1756357465257-1790432463920-rf85m', 'Wilson’s disease is the inability of the body to metabolize _____, while hemochromatosis is a disorder in _____ metabolism.', 'Copper, iron', 'Wilson''s Disease (Copper Accumulation): This is an autosomal recessive genetic disorder caused by a mutation in the ATP7B gene. This mutation disrupts the liver''s ability to transport and excrete excess copper into bile. As a result, toxic levels of copper build up primarily in the liver, brain, and the corneas of the eyes (forming classic golden-brown Kayser-Fleischer rings).

Hemochromatosis (Iron Overload): This metabolic disorder is characterized by a failure in iron-sensing mechanisms (often due to mutations in the HFE gene), which leads to the uncontrolled, excessive absorption of dietary iron from the gastrointestinal tract. The excess iron gets deposited heavily into vital organs such as the liver, heart, and pancreas, which can cause cirrhosis, cardiac arrhythmias, and diabetes (traditionally termed "bronze diabetes").', '["Iron, copper","Calcium, iron","Copper, iron","Iron, calcium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T07:19:41.468Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T07:19:41.468Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T07:19:41.468Z"'::jsonb),
('anki-card-1756358851944-38', 'anki-deck-1756357465257-1790432463920-rf85m', 'The vertebrae and bones of the jaw are classified as ____ because of their shapes:', 'Irregular bones', 'Irregular bones are defined by their complex, highly specialized shapes that do not cleanly fit into standard geometric categories like long, short, or flat. They typically feature a mix of ridges, notches, and projections.

Each vertebra in the spine consists of a thick vertebral body, an arch, and multiple bony projections (such as the spinous and transverse processes) that serve as crucial muscle attachment points and shield the spinal cord.

The jawbones are part of the facial skeleton. The mandible (lower jaw) and maxilla (upper jaw) feature a highly irregular, irregular layout tailored to house tooth sockets, support facial muscles, and form parts of the nasal and oral cavities.

• Flat bones: These are thin, flattened, and usually slightly curved bones designed for extensive muscle attachment or organ protection (e.g., the ribs, sternum, and most cranial skull bones). While some older literatures loosely lump the flat portions of the jaw with flat bones, modern structural taxonomy officially classifies the facial bones—including the mandible—as irregular.
• Short bones: These are roughly cube-shaped, having an approximately equal length, width, and thickness to provide stability and support (e.g., the carpals in the wrist and tarsals in the ankle).
• Long bones: These are elongated, cylindrical shafts that are noticeably longer than they are wide, acting as levers to facilitate body movement (e.g., the femur, humerus, and phalanges).', '["Long bones","Short bones","Flat bones","Irregular bones"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T06:51:42.719Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T06:51:42.719Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T06:51:42.719Z"'::jsonb),
('anki-card-1756358746082-34', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is true about megaloblastic anemia?
I. It may be clinically manifested by neuropathy.
II. Vitamin E is required in its dietary management.', 'Only statement 1 is correct.', 'Megaloblastic anemia is primarily caused by a deficiency in Vitamin B12 (cobalamin) or Vitamin B9 (folate). When it stems from a Vitamin B12 deficiency, it uniquely presents with neurological complications, such as peripheral neuropathy (tingling, numbness, or a "pins and needles" sensation in the hands and feet), loss of vibratory sense, and gait imbalances. This occurs because Vitamin B12 is mandatory for maintaining the structural integrity of the myelin sheath that insulates nerves.

• Statement 2 is INCORRECT: Vitamin E plays no direct physiological role in the development or dietary management of megaloblastic anemia. Vitamin E deficiency causes hemolytic anemia (where fragile red blood cells prematurely rupture due to oxidative damage to their cell membranes), not megaloblastic anemia. The dietary management of megaloblastic anemia strictly requires therapeutic supplementation of Vitamin B12 or Folic Acid.', '["Only statement 1 is correct.","Only statement 2 is correct.","Both statements are correct.","Both statements are incorrect."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:40:36.453Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:40:36.453Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:40:36.453Z"'::jsonb),
('anki-card-1756358980389-43', 'anki-deck-1756357465257-1790432463920-rf85m', 'An immunologic disease of the joints and related structures', 'Rheumatoid Arthritis', 'Rheumatoid Arthritis (RA) is a chronic, systemic autoimmune (immunologic) disorder. In RA, the body''s immune system mistakenly attacks the synovium—the thin membrane that lines the joints. This leads to severe, painful inflammation, cartilage destruction, and bone erosion.

	• Osteoporosis: This is a metabolic bone disease characterized by a loss of bone density and increased fragility, typically caused by hormonal changes, aging, or nutritional deficiencies rather than an immune system attack.
	• Sjögren’s syndrome: While this is an immunologic/autoimmune disease, its primary targets are the moisture-producing glands (such as salivary and tear glands), leading to severe dry eyes and dry mouth. Although it can be associated with joint pain, the primary immunologic joint disease listed is RA.
	• Gout: This is a metabolic form of inflammatory arthritis caused by the accumulation and deposition of uric acid (monosodium urate) crystals in the joints, not an immunologic or autoimmune malfunction.', '["Rheumatoid Arthritis","Gout","Sjogren’s syndrome","Osteoporosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T13:46:29.867Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T13:46:29.867Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T13:46:29.867Z"'::jsonb),
('anki-card-1756358828080-37', 'anki-deck-1756357465257-1790432463920-rf85m', 'It describes the bone after the developmental period is completed and often used for bone monitoring in adults:', 'Bone mineral density', 'Bone mineral density (BMD) is the absolute "gold standard" metric used in clinical settings to monitor adult skeletal health over time. It measures the amount of mineral matter (like calcium) per square centimeter of bone tissue via diagnostic tools such as Dual-Energy X-ray Absorptiometry (DEXA scans).

While bones stop growing in length and reach their ultimate structural ceiling at the end of the growth period, the tracking of a patient''s current bone status throughout mature adulthood focuses heavily on their BMD values to screen for conditions like osteopenia and osteoporosis.

• Peak Bone Mass: Peak Bone Mass refers exclusively to the maximum amount of bone tissue an individual can physically accumulate by the end of their developmental phase (typically around ages 20 to 30). Because it describes a specific, static historical milestone rather than a dynamic continuous variable, it is not what is tracked during Routine adult bone monitoring.
• Bone mineral content (BMC) measures total mineral weight rather than concentration/density. In standard diagnostic jargon, Bone mass is a conceptual term often used interchangeably with BMD, but BMD is the official diagnostic metric quantified for patient monitoring.', '["Bone mineral content","Bone mineral density","Peak Bone Mass","Bone mass"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T09:35:45.916Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T09:35:45.916Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T09:35:45.916Z"'::jsonb),
('anki-card-1756358773066-35', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is/are nutritional effects of chemotherapy?
I. Dysgeusia
II. Diarrhea and constipation
III. Esophagitis with dysphagia', 'All of the above', 'Chemotherapy drugs target rapidly dividing cells throughout the body. Because the cells lining the entire gastrointestinal (GI) tract and the taste buds regenerate quickly, they are highly vulnerable to chemotherapy, leading to several significant nutritional side effects:

• Dysgeusia: Chemotherapy frequently damages the taste receptor cells in the mouth, causing an altered or metallic taste. This severely diminishes appetite and food enjoyment.
• Diarrhea and constipation: Chemotherapy can disrupt normal bowel motility and damage the intestinal mucosal lining, leading to severe diarrhea. Conversely, the use of anti-nausea medications (antiemetics) given alongside chemotherapy often causes severe constipation.
• Esophagitis with dysphagia: The treatment commonly induces mucositis (inflammation and ulceration of the mucous membranes) along the esophagus. This painful swelling (esophagitis) directly results in dysphagia (difficulty swallowing), making oral food intake very challenging.', '["I only","I and III only","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:38:13.911Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:38:13.911Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T15:38:14.088Z"'::jsonb),
('anki-card-1756358586640-28', 'anki-deck-1756357465257-1790432463920-rf85m', 'Not allowed in tyramine-restricted diets:', 'Fava beans', 'Fava beans (broad beans) contain high amounts of L-dopa, which can metabolize into tyramine and other compounds that interact dangerously with Monoamine Oxidase Inhibitors (MAOIs). Additionally, the pods of broad beans are explicitly restricted on low-tyramine diets because they accumulate toxic levels of tyramine as they age.

When a patient taking an MAOI medication consumes high-tyramine foods, the tyramine cannot be safely broken down in the gut. It enters the bloodstream and causes a massive release of norepinephrine, leading to a life-threatening hypertensive crisis (a dangerous spike in blood pressure).

Other foods commonly restricted include aged cheeses, cured and fermented meats, yeast extracts, fermented soy products, sauerkraut, kimchi, certain alcoholic beverages (especially tap beers and some red wines), and improperly stored or spoiled protein-rich foods. Current recommendations emphasize that tyramine content varies with aging, fermentation, ripening, and storage conditions. Fresh foods are generally lower in tyramine than aged or fermented products.', '["Grapefruit juice","Fava beans","Simple sugars","Banana"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:37:45.816Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:37:45.816Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:37:45.816Z"'::jsonb),
('anki-card-1756358507660-25', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which mineral reduces intestinal absorption of fluoride by forming insoluble complexes?', 'Calcium', 'Calcium binds fluoride in the gastrointestinal tract, decreasing its absorption. This interaction is clinically relevant when fluoride supplements are prescribed.', '["Magnesium","Iron","Calcium","Manganese"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:32:55.010Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:32:55.010Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:32:55.010Z"'::jsonb),
('anki-card-1756358702535-33', 'anki-deck-1756357465257-1790432463920-rf85m', 'Products that contain live microorganisms in sufficient numbers to alter the intestinal microbiota and promote microbial balance are known as:', 'Probiotics', 'Probiotics are live microorganisms that, when administered in adequate amounts, confer a health benefit on the host. Common probiotic organisms include species of Lactobacillus, Bifidobacterium, Saccharomyces boulardii, and certain strains of Bacillus.', '["Antibiotics","Probiotics","Fruits and vegetables","Digestive enzymes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:31:40.573Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:31:40.573Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T15:31:40.573Z"'::jsonb),
('anki-card-1756358629971-30', 'anki-deck-1756357465257-1790432463920-rf85m', 'Galactosemia is an inherited disorder characterized by the inability to metabolize galactose due to deficiency of the enzyme galactose-1-phosphate uridylyltransferase (GALT). Which of the following is a characteristic manifestation of this condition?', 'Growth failure', 'Classic galactosemia is an autosomal recessive metabolic disorder caused by a deficiency in the GALT enzyme. This deficiency prevents the infant from safely breaking down galactose (a component of lactose found in breast milk and standard formulas).

Because the infant cannot convert galactose into glucose for energy, toxic metabolites like galactose-1-phosphate accumulate rapidly in tissues. This causes immediate feeding intolerance, severe vomiting, and systemic illness within days of birth. This inability to utilize nutrients manifests primarily and consistently as growth failure (failure to thrive).

Immediate elimination of lactose and galactose from the diet is essential. Starting this dietary intervention early is the cornerstone of treatment to reverse growth failure, resolve acute symptoms like jaundice, and prevent severe, life-threatening complications like E. coli sepsis.', '["Growth failure","Mental retardation","Apathy","Lack of pigmentation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:21:28.975Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:21:28.975Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T14:21:29.149Z"'::jsonb),
('anki-card-1756359656640-68', 'anki-deck-1756357465257-1790432463920-rf85m', 'Compute for the GFR of a male patient, 65 years old, stands 5’5 and dry weight of 48 kg. Serum creatinine is 5.0 mg/dL.', '18.5 mL/min', 'Using the Cockcroft-Gault / CKD-EPI equation for renal function evaluation, a 65-year-old male with dry weight 48 kg and serum creatinine 5.0 mg/dL has an estimated GFR of approximately 18.5 mL/min, placing the patient in CKD Stage 4 (severely decreased).', '["18.5 mL/min","20.5 mL/min","16.5 mL/min","30.5 mL/min"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T06:59:12.854Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T06:59:12.854Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T06:59:12.854Z"'::jsonb),
('anki-card-1756358487962-24', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which omega-3 fatty acid found in fish oil is primarily responsible for reducing the production of pro-inflammatory cytokines?', 'Eicosapentaenoic Acid (EPA)', 'EPA competes with arachidonic acid for cyclooxygenase and lipoxygenase enzymes, resulting in the production of less inflammatory eicosanoids. DHA also has anti-inflammatory effects but EPA is more directly associated with reducing inflammatory cytokine production.', '["DocosaHexaenoic Acid (DHA)","Eicosapentaenoic Acid (EPA)","Arachidonic Acid","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:27:48.594Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:27:48.594Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T14:27:48.765Z"'::jsonb),
('anki-card-1756358420564-22', 'anki-deck-1756357465257-1790432463920-rf85m', 'High cortisol stimulates:', 'Mobilization of free fatty acid', 'Cortisol is a major stress hormone that functions to provide energy substrates to the body during flight-or-fight situations or prolonged stress. It directly stimulates lipolysis—the breakdown of stored fats in adipose tissue—which results in the mobilization of free fatty acids into the bloodstream to be used as an alternative fuel source by peripheral tissues.

• Use of glucose except for the brain: Cortisol actually decreases or inhibits the peripheral utilization of glucose in tissues like muscle and fat. It does this precisely to save or spare glucose exclusively for the brain. Therefore, this statement is factually backwards; it decreases glucose use in peripheral tissues to safeguard it for the brain.
• Retention of water and sodium: Cortisol does exhibit weak mineralocorticoid activity at very high pathological levels (which can cause secondary sodium retention and water buildup), but its primary, direct metabolic action across basic physiology and nutrition textbooks is the mobilization of metabolic fuels, making free fatty acid mobilization the classical intended answer.', '["Mobilization of free fatty acid","Use of glucose except for the brain","Retention of water","Retention of sodium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:50:07.305Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:50:07.305Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T14:50:07.305Z"'::jsonb),
('anki-card-1756358371332-20', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is needed when the body experiences stress?', 'Growth hormone and insulin-like factors provision', 'Physiologic stress resulting from trauma, burns, major surgery, sepsis, severe infection, or critical illness activates a complex neuroendocrine response that promotes survival by mobilizing energy stores and maintaining vital organ function.

The stress response is characterized by increased secretion of several counter-regulatory hormones, including:
• Growth hormone (GH)
• Cortisol
• Catecholamines (epinephrine and norepinephrine)
• Glucagon

The growth hormone–insulin-like growth factor (GH–IGF) axis is also altered during stress. Although GH secretion generally increases, severe illness is often associated with GH resistance, resulting in reduced hepatic production of IGF-1 despite elevated GH concentrations.

These hormonal changes contribute to:
• Increased protein catabolism
• Increased gluconeogenesis
• Increased lipolysis
• Increased resting energy expenditure
• Mobilization of amino acids for immune function and tissue repair

Among the available options, Growth hormone and insulin-like factors is the best answer because it refers to the endocrine mediators involved in the physiologic stress response. It should be noted, however, that this question has a psychometric limitation. From a nutrition management perspective, the more appropriate answer would be adequate energy and increased protein intake, but this option is not provided.', '["Minimum calorie","Low protein","Fat-soluble vitamins and supplementation","Growth hormone and insulin-like factors provision"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:21:36.831Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:21:36.831Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T15:21:37.007Z"'::jsonb),
('anki-card-1756358339102-19', 'anki-deck-1756357465257-1790432463920-rf85m', 'Vitamin losses increase due to the following conditions EXCEPT:', 'Cooking below the temperature of boiling water with excessive agitation', 'While boiling water (100°C) combined with excessive agitation drastically accelerates the leaching and thermal destruction of water-soluble vitamins (like Vitamin C and Thiamine), cooking below the boiling point (such as poaching or gentle simmering) exposes the food to less thermal stress. Even with agitation, keeping the temperature lower is a primary strategy used to preserve heat-sensitive nutrients compared to full boiling.

	• Increased exposure to high temperatures or sunshine: Heat and ultraviolet (UV) light rapidly degrade photosensitive and heat-labile vitamins (such as Riboflavin/B2 and Vitamin C).
	• Increased exposure to air: Oxygen triggers oxidative degradation, which quickly destroys atmospheric-sensitive vitamins like Vitamin C, A, and E.
	• Increased length of storage: Prolonged storage allows baseline chemical degradation and oxidation to occur over time, steadily reducing the total nutrient potency of the food.', '["Increased exposure to high temperatures or sunshine during storage","Increased length of storage","Increased exposure to air","Cooking below the temperature of boiling water with excessive agitation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:59:45.434Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:59:45.434Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T14:59:45.434Z"'::jsonb),
('anki-card-1756358246606-16', 'anki-deck-1756357465257-1790432463920-rf85m', '____ stimulates sodium retention while ___ stimulates water retention.', 'Aldosterone, vasopressin', 'Aldosterone is a steroid hormone produced by the adrenal cortex. Its primary physiological role is to act on the kidneys (specifically the distal tubules and collecting ducts) to stimulate sodium retention (reabsorption). As it pulls sodium back into the blood, potassium is excreted.

Vasopressin, also known as Antidiuretic Hormone (ADH), is synthesized in the hypothalamus and released by the posterior pituitary. Its primary role is to insert aquaporins (water channels) into the collecting ducts of the kidneys to stimulate water retention (reabsorption) independently of sodium, helping to dilute blood osmolality.

• Renin is an enzyme (not a hormone) secreted by the kidneys that cleaves angiotensinogen into Angiotensin I. It triggers a cascade but does not directly retain sodium or water on its own.', '["Vasopressin, aldosterone","Aldosterone, vasopressin","Renin, aldosterone","Renin, angiotensin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:58:35.288Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:58:35.288Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T14:58:35.463Z"'::jsonb),
('anki-card-1756358024433-9', 'anki-deck-1756357465257-1790432463920-rf85m', 'A mechanism by which Vitamin C acts as antioxidant to protect the body is by:
I. Reacts directly with peroxynitrite 
II. Reacts directly with hypochlorite-derived oxidants 
III. Scavenges reactive oxygen species such as superoxide and hydroxyl radicals', 'All of the above', 'Vitamin C (ascorbic acid) is a water-soluble antioxidant that protects cells from oxidative damage by donating electrons to neutralize reactive oxygen and nitrogen species. 

Its antioxidant actions include: 
• scavenging superoxide radicals, 
• scavenging hydroxyl radicals, 
• reacting with peroxynitrite, 
• neutralizing hypochlorite-derived oxidants generated during inflammatory responses, 
• regenerating oxidized vitamin E, thereby helping maintain membrane antioxidant defenses. 

These mechanisms contribute to the protection of lipids, proteins, DNA, and other cellular components from oxidative injury.', '["I only","II only","III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:29:28.910Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:29:28.910Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:29:28.910Z"'::jsonb),
('anki-card-1756358183293-14', 'anki-deck-1756357465257-1790432463920-rf85m', 'Significant weight loss is defined as:
I. 5% over a month
II. >5% over 1 month
III. 7.5% over 3 months
IV. >7.5% over 3 months', 'I and III only', 'Under ASPEN / ESPEN clinical guidelines, Significant weight loss is defined as: 5% in 1 month, 7.5% in 3 months, or 10% in 6 months (Statements I and III). Severe weight loss exceeds these parameters.', '["I and III only","III and IV only","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T06:46:29.366Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T06:46:29.366Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T06:46:29.677Z"'::jsonb),
('anki-card-1756358055766-10', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following are sources of acetyl-CoA?
I. β-oxidation of fatty acids 
II. Oxidative decarboxylation of pyruvate
III. Catabolism of ketogenic amino acids', 'All of the above', 'Acetyl-CoA is a central metabolic intermediate that links carbohydrate, lipid, and protein metabolism. It enters the tricarboxylic acid (TCA) cycle for ATP production or serves as a precursor for ketone bodies, cholesterol, and fatty acid synthesis. The major sources of acetyl-CoA include: 

I. β-Oxidation of fatty acids: Fatty acids undergo β-oxidation in the mitochondria, sequentially removing two-carbon fragments as acetyl-CoA. 
II. Oxidative decarboxylation of pyruvate: Pyruvate, the end product of glycolysis, is converted to acetyl-CoA by the pyruvate dehydrogenase complex before entering the TCA cycle. 
III. Ketogenic amino acids: The exclusively ketogenic amino acids leucine and lysine, as well as portions of isoleucine, phenylalanine, tryptophan, tyrosine, and threonine, are metabolized to acetyl-CoA or acetoacetate.', '["I and II","II and  III","I and III","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T13:57:34.894Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T13:57:34.894Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T13:57:35.072Z"'::jsonb),
('anki-card-1756357988685-8', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is true for BMR?', 'Pregnancy increases BMR', 'Basal Metabolic Rate (BMR) represents the minimum amount of energy required to maintain vital physiologic functions while the body is at complete rest, in the post-absorptive state, and under thermoneutral conditions. 

Pregnancy increases BMR because of: 
• fetal growth, 
• placental metabolism, 
• expansion of maternal tissues, 
• increased cardiac and respiratory work, 
• elevated hormonal activity. 

BMR may increase by approximately 15–20% during pregnancy, particularly in the second and third trimesters.', '["Puberty decreases BMR","Fasting increases BMR","Pregnancy increases BMR","Females have higher BMR than males"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:54:23.724Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:54:23.724Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T10:02:23.464Z"'::jsonb),
('anki-card-1756359272525-55', 'anki-deck-1756357465257-1790432463920-rf85m', 'Aggressive nutrition support is required for burned patients with:', 'Burns exceeding 20 % of the body surface area', 'Major burn injuries trigger one of the most intense hypermetabolic and hypercatabolic responses known in clinical medicine. This metabolic surge significantly accelerates protein breakdown and energy expenditure. Clinical guidelines (such as ESPEN and ASPEN) establish that burns exceeding 20% of the Total Body Surface Area (TBSA) represent critical, severe trauma that demands immediate, aggressive nutrition support (often via early enteral nutrition) to prevent severe muscle wasting, support wound healing, and minimize infection risks.

• 10% TBSA: Minor burns involving 10% or less of the body surface area generally do not induce a systemic, high-grade hypermetabolic crisis. Most of these patients can meet their elevated nutritional needs through a high-calorie, high-protein oral diet without requiring aggressive specialized nutritional support interventions (like tube feeding or parenteral nutrition).
• Diarrhea: While diarrhea is a clinical concern that causes fluid and electrolyte losses, it is a gastrointestinal symptom rather than an automatic primary indicator for aggressive nutrition support. In fact, if a burn patient develops severe diarrhea, enteral tube feeding rates might need to be adjusted or formulas changed rather than aggressively increased.', '["Burns exceeding 20 % of the body surface area","Burns with 10 % of the body surface area","Diarrhea","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:15:07.436Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:15:07.436Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:15:07.436Z"'::jsonb),
('anki-card-1756359843048-75', 'anki-deck-1756357465257-1790432463920-rf85m', 'Easy to digest snack food – they are rich in CHO but generally low in protein, fiber, and many other nutrients found in a well-balanced diet.', 'Energy bars', 'In sports nutrition and dietetics review frameworks, conventional energy bars are primarily designed to deliver quick, easily accessible fuel to working muscles. They are heavily packed with simple and refined carbohydrates (CHO) to provide a rapid blood glucose spike before or during endurance performance.

Unlike meal replacements or protein bars, traditional energy bars are kept purposefully low in protein, dietary fiber, and healthy fats. Fiber and protein naturally slow down gastric emptying and delay digestion. By keeping these nutrients minimal, the bar functions as an easy-to-digest snack that leaves the stomach rapidly, providing fast energy without causing heavy gastrointestinal distress, cramping, or bloating during physical exertion.', '["Protein shakes","Whey protein","High-quality protein","Energy bars"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:35:07.565Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:35:07.565Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:35:07.565Z"'::jsonb),
('anki-card-1756358145111-13', 'anki-deck-1756357465257-1790432463920-rf85m', 'This mineral potentiates the action of insulin, allowing glucose entry into cells, and facilitates insulin binding to cell surfaces.', 'Chromium', 'Chromium is an essential trace mineral involved in carbohydrate, lipid, and protein metabolism. It enhances the action of insulin by improving insulin receptor activity and intracellular signaling, thereby promoting glucose uptake by cells. Although chromium deficiency is uncommon, severe deficiency may lead to impaired glucose tolerance and insulin resistance, particularly in patients receiving long-term parenteral nutrition without adequate chromium supplementation.', '["Cobalt","Chromium","Molybdenum","Zinc"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:13:11.522Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:13:11.522Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:13:11.522Z"'::jsonb),
('anki-card-1756358274204-17', 'anki-deck-1756357465257-1790432463920-rf85m', 'Consider the following statements about indoles:
Statement 1: Indoles are phytochemicals found in broccoli and other cruciferous vegetables that induce the production of detoxification enzymes, helping protect cells against carcinogens. 
Statement 2: Indoles may influence estrogen metabolism and modulate estrogen activity.', 'Both statements are correct.', '• Statement 1 is CORRECT: Indoles, such as indole-3-carbinol (I3C) and its metabolic derivative 3,3''-diindolylmethane (DIM), are potent sulfur-containing phytochemicals derived from the breakdown of glucosinolates found heavily in cruciferous vegetables like broccoli, cabbage, cauliflower, and Brussels sprouts. Biochemically, they stimulate and upregulate Phase I and Phase II biotransformation (detoxification) enzymes in the liver and gastrointestinal tract. This metabolic acceleration helps the body break down, neutralize, and safely eliminate carcinogens, xenobiotics, and cellular toxins before they can cause DNA damage.

• Statement 2 is CORRECT: Indoles are heavily researched for their distinct capacity to influence estrogen metabolism and modulate overall estrogen activity. They alter the pathways of hormone breakdown in the liver, effectively driving the conversion of strong, highly active estrogens into less potent, protective metabolites (favoring 2-hydroxyestrone over the more harmful 16-alpha-hydroxyestrone). By acting as natural estrogen modulators or blockers, dietary indoles provide systemic chemopreventive traits against hormone-dependent conditions, including breast and endometrial cancers.', '["Only statement 1 is correct.","Only statement 2 is correct.","Both statements are correct.","Both statements are incorrect."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:09:29.051Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:09:29.051Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:09:29.051Z"'::jsonb),
('anki-card-1756358929525-41', 'anki-deck-1756357465257-1790432463920-rf85m', 'It is also known as Lou Gehrig disease:', 'Amyotrophic lateral sclerosis', 'Amyotrophic lateral sclerosis (ALS), also known as Lou Gehrig''s disease, is a progressive neurodegenerative disorder characterized by the degeneration of upper and lower motor neurons. The disease leads to progressive muscle weakness, muscle wasting, spasticity, dysarthria, dysphagia, and eventually respiratory failure. Although cognition is preserved in many patients, some develop frontotemporal cognitive impairment or dementia.

From a nutrition perspective, ALS is associated with:
• Progressive dysphagia, increasing the risk of aspiration.
• Weight loss due to reduced oral intake and increased energy expenditure.
• Loss of muscle mass and protein-energy malnutrition.
• Increased risk of dehydration.

Medical nutrition therapy aims to:
• Maintain body weight and preserve lean body mass.
• Provide high-energy, high-protein meals when appropriate.
• Modify food texture and liquid consistency according to swallowing ability.
• Recommend oral nutrition supplements when intake is inadequate.
• Consider enteral nutrition (e.g., gastrostomy feeding) when oral intake becomes unsafe or insufficient.

Early nutrition intervention is associated with improved nutritional status and may contribute to a better quality of life.', '["Alzheimer''s disease","Amyotrophic lateral sclerosis","Cerebral palsy","Parkinson''s Disease"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:09:21.438Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:09:21.438Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:09:21.438Z"'::jsonb),
('anki-card-1756359891081-77', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is NOT a recommended dietary practice for marathon or other endurance athletes?', 'Consume a high-protein, low-carbohydrate diet.', 'Endurance events such as marathons rely heavily on carbohydrates as the primary fuel source, particularly during moderate- to high-intensity exercise. Adequate carbohydrate intake helps maintain blood glucose levels, replenish muscle glycogen stores, delay fatigue, and improve endurance performance. Consequently, dietary strategies that severely restrict carbohydrates are generally not recommended for marathon runners. Although protein is essential for muscle repair, recovery, and adaptation to training, consuming excessive protein at the expense of carbohydrates may impair glycogen storage and reduce exercise performance. 

Current sports nutrition guidelines recommend that endurance athletes consume sufficient carbohydrates based on their training load, moderate amounts of protein to support recovery, and healthy fats to meet energy needs and maintain overall health. For the NDLE, remember that nutrition recommendations for endurance athletes emphasize adequate carbohydrate availability, not high-protein or carbohydrate-restricted diets. While individualized nutrition plans are increasingly common, carbohydrates remain the cornerstone of endurance performance.', '["Consume a high-protein, low-carbohydrate diet.","High-protein diets with minimal carbohydrate intake are not recommended for endurance athletes.","Follow a balanced diet consisting of approximately 15–20% protein, 30% fat, and 50–55% carbohydrates.","Provide adequate carbohydrates to fuel training and long-distance running days."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:09:04.948Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:09:04.948Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:09:04.948Z"'::jsonb),
('anki-card-1756357827142-2', 'anki-deck-1756357465257-1790432463920-rf85m', 'Evaluate the following statements regarding amino acid metabolism.
I. Amino acids are deaminated first into ketoacid before being utilized for energy. 
II. Deamination primarily occurs in the kidneys.', 'Both statements are incorrect.', 'Statement 1 is imprecise. Most amino acids first undergo transamination, transferring their amino group to α-ketoglutarate to form glutamate. Glutamate is then oxidatively deaminated, producing ammonia and regenerating α-ketoglutarate. Thus, deamination is not the universal "first" step for amino acid catabolism. 

Statement 2 is also incorrect. The liver is the primary site of amino acid deamination and urea synthesis. While the kidneys participate in amino acid metabolism and ammonia production, they are not the principal site of deamination. Therefore, both statements are incorrect.', '["Only statement 1 is correct.","Only statement 2 is correct.","Both statements are correct.","Both statements are incorrect."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:37:03.458Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:37:03.458Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:37:03.458Z"'::jsonb),
('anki-card-1756360059738-84', 'anki-deck-1756357465257-1790432463920-rf85m', 'The Registered Dietitian Nutritionist (RDN) is reviewing a patient''s understanding of and adherence to a prescribed consistent carbohydrate diet. Three months later, the patient''s hemoglobin A1c (HbA1c) is reassessed, and progress toward the target range is evaluated. This scenario describes which step of the Nutrition Care Process (NCP)?', 'Nutrition Monitoring and Evaluation', 'In this scenario, the RDN is reviewing the patient''s adherence to the prescribed nutrition intervention and reassessing HbA1c after three months to determine whether the nutrition goals have been achieved. These activities are characteristic of Nutrition Monitoring and Evaluation, which involves measuring and comparing outcomes against established nutrition goals and determining whether modifications to the nutrition care plan are necessary. 

Hemoglobin A1c is an important monitoring indicator because it reflects the patient''s average blood glucose over the previous 2–3 months. Therefore, reassessing HbA1c after three months is clinically appropriate to evaluate the effectiveness of a consistent carbohydrate meal plan and the patient''s adherence to nutrition recommendations.', '["Nutrition Assessment","Nutrition Diagnosis","Nutrition Intervention","Nutrition Monitoring and Evaluation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:36:57.236Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:36:57.236Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:36:57.236Z"'::jsonb),
('anki-card-1756358439765-23', 'anki-deck-1756357465257-1790432463920-rf85m', 'These nutrients are essential for wound healing EXCEPT:', 'Sodium', 'Arginine, glutamine, and vitamin C support collagen synthesis, immune function, and tissue repair. Sodium is important for fluid balance but is not considered a specific nutrient that enhances wound healing.', '["Glutamine","Arginine","Sodium","Vitamin C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:15:50.718Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:15:50.718Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:15:50.718Z"'::jsonb),
('anki-card-1756359687641-69', 'anki-deck-1756357465257-1790432463920-rf85m', 'What is the protein requirement for a male, 65 years old, who stands 5’5" and has a dry weight of 48 kg? His serum creatinine is 5.0 mg/dL.', '0.28 g/kg/day with EAA supplementation', 'Step-by-Step Rationale

1. Assess Kidney Function (GFR):
Using the standard Cockcroft-Gault equation to estimate the Glomerular Filtration Rate (GFR) based on the client''s metrics:

GFR = [(140 - Age) x Weight (kg)] / [72 x Serum Creatinine]
GFR = [(140 - 65) x 48] / [72 x 5.0] = [75 x 48] / 360 = 10.0 mL/min

A GFR of 10.0 mL/min confirms the patient is in Stage 5 Chronic Kidney Disease (CKD) / End-Stage Renal Disease (ESRD) and is currently in the pre-dialysis phase.

2. Determine Protein Requirements:
For a patient with advanced renal failure who is not yet on active dialysis, minimizing nitrogenous waste build-up while preventing lean muscle wasting is critical. Clinical guidelines specify a Very Low-Protein Diet (VLPD) targeting 0.28 g/kg/day, which must be supplemented with Essential Amino Acids (EAA) or ketoacid analogs to fulfill basic physiological needs.', '["0.6 to 0.7 g/kg/day","0.28 g/kg/day with EAA supplementation","0 to 1.2 g/kg/day with dialysis","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:05:08.561Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:05:08.561Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:05:08.561Z"'::jsonb),
('anki-card-1756359511097-61', 'anki-deck-1756357465257-1790432463920-rf85m', 'A 32-year-old woman (Ms. BMA) wants to determine her target heart rate for moderate- to vigorous-intensity aerobic exercise. Based on the age-predicted maximum heart rate method, what is her target heart rate range?', '122-160 beats', 'A commonly used method for estimating maximum heart rate (HRmax) is: HRmax = 220 − age 

For a 32-year-old: 
• HRmax = 220 − 32 = 188 beats/min 

The recommended target heart rate (THR) for moderate- to vigorous-intensity exercise is approximately 65–85% of HRmax. 

Calculation: 
• Lower limit: 188 × 0.65 = 122 beats/min 
• Upper limit: 188 × 0.85 = 160 beats/min 

Therefore, the target heart rate range is: 122–160 beats/min. Although newer equations such as Tanaka''s formula (208 − 0.7 × age) may estimate HRmax more accurately in some populations, the 220 − age equation remains the formula most commonly used in basic exercise prescription and is frequently tested in licensure examinations.', '["122-160 beats","150-160 beats","138-200 beats","162-202 beats"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:40:20.786Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:40:20.786Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:40:20.786Z"'::jsonb),
('anki-card-1756360356794-96', 'anki-deck-1756357465257-1790432463920-rf85m', 'The complex formed when bile salts combine with lipid material to facilitate digestion', 'Micelle', 'Micelles are small, water-soluble complexes formed in the lumen of the small intestine when bile salts combine with the products of lipid digestion, including free fatty acids, monoglycerides, cholesterol, phospholipids, and fat-soluble vitamins (A, D, E, and K). 

The primary function of micelles is to transport these lipid digestion products across the watery environment of the intestinal lumen to the brush border of enterocytes, where they are absorbed. Without bile salts and micelle formation, lipid absorption would be markedly impaired, particularly that of long-chain fatty acids and fat-soluble vitamins. 

For the NDLE, distinguish micelles from chylomicrons. Micelles are involved in intestinal absorption, whereas chylomicrons are responsible for transporting absorbed dietary lipids from the intestine to the circulation.', '["Chylomicron","Micelle","HDL","LDL"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:39:26.858Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:39:26.858Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:39:26.858Z"'::jsonb),
('anki-card-1756357937304-6', 'anki-deck-1756357465257-1790432463920-rf85m', 'Phosphoglycerate kinase functions in carbohydrate metabolism to produce ATP via:', 'Substrate level phosphorylation', 'Phosphoglycerate kinase catalyzes the conversion of: 1,3-bisphosphoglycerate → 3-phosphoglycerate 

During this reaction, a phosphate group is directly transferred from the substrate to ADP, producing ATP. This direct transfer is called substrate-level phosphorylation. Unlike oxidative phosphorylation, this reaction: 
• does not require oxygen, 
• does not occur in mitochondria, 
• does not involve the electron transport chain. 

Another example of substrate-level phosphorylation occurs during the conversion of phosphoenolpyruvate (PEP) to pyruvate by pyruvate kinase.', '["Oxidative phosphorylation","Substrate level phosphorylation","Oxidative decarboxylation","Phosphorolysis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:39:12.363Z","interval":1,"easeFactor":2.1,"repetitions":0}'::jsonb, '"2026-11-04T11:39:12.363Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:39:12.363Z"'::jsonb),
('anki-card-1756357964604-7', 'anki-deck-1756357465257-1790432463920-rf85m', 'Under the influence of sunlight, __ is synthesized in our skin from ___.', 'Vitamin D₃, 7-dehydrocholesterol', 'When your skin is exposed to the ultraviolet B (UVB) radiation in sunlight, it breaks down a specific form of cholesterol naturally present in your skin cells called 7-dehydrocholesterol.

This chemical reaction converts the cholesterol precursor into Vitamin D3 (cholecalciferol), which your liver and kidneys then convert into its active hormone form.', '["Vitamin D₃, 7-dehydrocholesterol","Calcium, vitamin D","Vitamin E, cholesterol","Vitamin B1, protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:31:29.077Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:31:29.077Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:31:29.077Z"'::jsonb),
('anki-card-1756359859217-76', 'anki-deck-1756357465257-1790432463920-rf85m', 'Designed to maximize post-workout refueling of muscle glycogen; promote greater recovery of muscle energy and muscle protein resynthesis than carbohydrate drinks.', 'Recovery drinks', 'Recovery drinks are specifically formulated with a specific carbohydrate-to-protein ratio (typically 3:1 or 4:1). The targeted dose of fast-acting carbohydrates quickly replenishes depleted muscle glycogen stores after intense exercise.

Research shows that adding protein to a post-workout carbohydrate drink stimulates greater glycogen resynthesis than carbohydrates alone, as the combination triggers a more robust insulin response (which drives glucose into muscle cells).

While traditional sports drinks only provide carbohydrates and electrolytes to maintain hydration and energy during exercise, recovery drinks deliver essential amino acids (from protein) to repair muscle tissue damage and kickstart protein synthesis after exercise.', '["Sports drinks","Recovery drinks","Protein shakes","Energy bars"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T06:46:24.768Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T06:46:24.768Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T06:46:25.075Z"'::jsonb),
('anki-card-1756357854657-3', 'anki-deck-1756357465257-1790432463920-rf85m', 'The following are metabolic pathways of cholesterol EXCEPT:', 'Energy production', 'In humans, the core structure of cholesterol consists of a highly stable four-ring steroid nucleus (perhydrocyclopentanophenanthrene ring). Unlike fatty acids, carbohydrates, or proteins, the human body completely lacks the enzymes required to break down or cleave this robust ring structure to generate energy or ATP. Therefore, cholesterol provides 0 calories per gram and is never utilized as a metabolic fuel source.

• Secretion of bile and Excretion of feces: Because the body cannot oxidize or dismantle the steroid ring for energy, the only way it can physically eliminate cholesterol is through the liver. The liver converts cholesterol into bile acids and bile salts, which are secreted into the digestive tract to help emulsify dietary fats. While most bile is reabsorbed, a small portion escapes recycling and is unalterably eliminated from the body via fecal excretion.
• Hormone production: Cholesterol serves as the absolute, obligatory structural precursor for the synthesis of all steroid hormones in the body. Specialized endocrine tissues modify cholesterol to produce glucocorticoids (like cortisol), mineralocorticoids (like aldosterone), and sex hormones (like estrogen, progesterone, and testosterone).', '["Secretion of bile","Excretion of feces","Energy production","Hormone production"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T08:36:45.064Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T08:36:45.064Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T08:36:45.064Z"'::jsonb),
('anki-card-1756357882524-4', 'anki-deck-1756357465257-1790432463920-rf85m', 'This enzyme allows the brain and erythrocytes to utilize glucose even in state of low concentrations.', 'Hexokinase', 'Hexokinase catalyzes the first step of glycolysis by converting glucose to glucose-6-phosphate. It has a low Km (high affinity) for glucose, allowing tissues like the brain and red blood cells to continue utilizing glucose even when blood glucose levels are low. 

This is physiologically important because: 
• The brain relies heavily on glucose under normal conditions. 
• Red blood cells depend exclusively on glycolysis because they lack mitochondria. 

By contrast, the liver expresses glucokinase, which has a higher Km and functions primarily when glucose concentrations are elevated after meals.', '["Glucose-6-phosphate","Hexokinase","ATP","Fructose-6-phosphate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T08:47:49.838Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T08:47:49.838Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T08:47:50.157Z"'::jsonb),
('anki-card-1756357800278-1', 'anki-deck-1756357465257-1790432463920-rf85m', '__ is a hormone that diminishes appetite and increase energy expenditure while __ increase appetite and decreases energy expenditure.', 'Leptin, neuropeptide Y', 'Leptin is a hormone secreted primarily by adipocytes. It acts on the hypothalamus to suppress food intake and increase energy expenditure by signaling adequate energy stores. 

Neuropeptide Y (NPY) is one of the most potent appetite-stimulating neurotransmitters in the hypothalamus. It increases food intake, promotes fat storage, and decreases energy expenditure, especially during fasting or caloric restriction. 

Leptin and NPY exert opposing effects: 
• High leptin suppresses NPY activity. 
• Low leptin (e.g., starvation) increases NPY secretion, stimulating hunger.', '["Neuropeptide Y, leptin","Leptin, neuropeptide Y","Cortisol, leptin","Leptin, glucagon"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T13:28:45.964Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T13:28:45.964Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T13:28:45.964Z"'::jsonb),
('anki-card-1756360414690-99', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following describes Type 1 Diabetes Mellitus?', 'It is an autoimmune disorder', 'Type 1 Diabetes Mellitus (T1DM) is a chronic, lifelong autoimmune disorder. The body’s own immune system mistakenly targets and destroys the insulin-producing beta cells located in the islets of Langerhans within the pancreas. This immune-mediated destruction results in an absolute insulin deficiency, meaning the pancreas can no longer produce insulin.

• The pancreas may have the ability to produce insulin but cells are deficient in receptors for insulin: This statement refers to a structural down-regulation of insulin receptors, which is a mechanism related to extreme forms of insulin resistance, not the absolute destruction of pancreatic cells seen in T1DM.
• The person usually does not develop symptoms until age 45: T1DM is most commonly diagnosed in children, adolescents, and young adults (historically termed "juvenile diabetes"), although it can theoretically manifest at any age. Diagnosis past age 45 is far more characteristic of Type 2 Diabetes Mellitus (T2DM).
• It is characterized by insulin resistance: Insulin resistance—where body cells fail to respond normally to circulating insulin—is the hallmark pathophysiological driver of Type 2 Diabetes, not Type 1.', '["The pancreas may have the ability to produce insulin but cells are deficient in receptors for insulin","It is an autoimmune disorder","The person usually does not develop symptoms until age 45","It is characterized by insulin resistance"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T07:58:21.584Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T07:58:21.584Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T07:58:21.898Z"'::jsonb),
('anki-card-1756359912762-78', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is true for nutritional management of esophageal obstruction?', 'Liquid diets', 'Esophageal obstruction is characterized by partial or complete blockage of the esophagus, leading to dysphagia (difficulty swallowing) and impaired passage of food from the mouth to the stomach. Common causes include esophageal cancer, benign strictures, esophageal webs, achalasia, or foreign body obstruction. The primary goal of nutrition therapy is to maintain adequate nutritional intake while minimizing swallowing difficulty and the risk of aspiration. 

Depending on the severity of the obstruction, patients may require a clear liquid diet, full liquid diet, or texture-modified diet. When oral intake becomes inadequate or unsafe, enteral nutrition via a feeding tube (e.g., gastrostomy or jejunostomy) may be necessary.', '["Liquid diets","Low fat diet","Low calorie","High protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:38:19.258Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-04T11:38:19.258Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:38:19.258Z"'::jsonb),
('anki-card-1756359531580-62', 'anki-deck-1756357465257-1790432463920-rf85m', 'Osmolality of body fluids.', '290 mOsm/kg', 'Osmolality is the concentration of osmotically active particles per kilogram of solvent (water) and is expressed as milliosmoles per kilogram (mOsm/kg). It reflects the body''s water balance and is tightly regulated to maintain normal cellular function. 

The normal plasma osmolality is approximately: 
• 275–295 mOsm/kg, with an average value of 290 mOsm/kg', '["290 mOsm/kg","400 mOsm/kg","480 mOsm/kg","200 mOsm/kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:36:40.049Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:36:40.049Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:36:40.049Z"'::jsonb),
('anki-card-1756357909472-5', 'anki-deck-1756357465257-1790432463920-rf85m', 'NAD+ contains ___ while FAD contains ___.', 'Niacin, riboflavin', 'NAD⁺ (Nicotinamide Adenine Dinucleotide) and FAD (Flavin Adenine Dinucleotide) are two of the most important coenzymes involved in oxidation-reduction (redox) reactions and energy metabolism. 

NAD⁺ is synthesized from niacin (Vitamin B₃). During glycolysis, the TCA cycle, and β-oxidation, NAD⁺ accepts electrons and hydrogen ions to become NADH, which subsequently donates these electrons to the Electron Transport Chain (ETC) to generate ATP. 

FAD, on the other hand, is derived from riboflavin (Vitamin B₂). It accepts two hydrogen atoms to form FADH₂, another reduced coenzyme that delivers electrons to Complex II of the ETC. 

Although both NADH and FADH₂ ultimately produce ATP, NADH generates more ATP because it donates electrons earlier in the ETC.', '["Thiamine, riboflavin","Riboflavin, thiamine","Niacin, riboflavin","Riboflavin, niacin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T09:08:24.877Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T09:08:24.877Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-22T09:08:25.055Z"'::jsonb),
('anki-card-1756358078147-11', 'anki-deck-1756357465257-1790432463920-rf85m', 'Deficiency of this vitamin causes Wernicke-Korsakoff syndrome:', 'Vitamin B1', 'Wernicke–Korsakoff syndrome is a neurologic disorder resulting from severe thiamine deficiency. It is classically associated with chronic alcohol use disorder but may also occur in prolonged malnutrition, hyperemesis gravidarum, bariatric surgery, or conditions causing prolonged inadequate intake. 

The syndrome consists of two related conditions: 
Wernicke encephalopathy (acute): 
• Confusion 
• Ophthalmoplegia or nystagmus 
• Ataxia 

Korsakoff syndrome (chronic): 
• Severe memory impairment
• Confabulation 
• Irreversible cognitive deficits if untreated 

Thiamine functions as thiamine pyrophosphate (TPP), a coenzyme for pyruvate dehydrogenase, α-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cerebral energy metabolism, particularly in brain regions with high metabolic demands.', '["Vitamin A","Vitamin B1","Vitamin B3","Vitamin C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T13:48:21.197Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T13:48:21.197Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-10-21T13:48:21.197Z"'::jsonb),
('anki-card-1756359204412-52', 'anki-deck-1756357465257-1790432463920-rf85m', 'Dietary recommendation for Biliary dyskinesia caused by increased contraction of the gallbladder:', 'Low fat', 'Biliary dyskinesia is a functional disorder of the gallbladder characterized by abnormal gallbladder motility, resulting in impaired bile flow and biliary-type pain in the absence of gallstones or structural abnormalities. 

In some patients, symptoms are associated with exaggerated gallbladder contraction, particularly after consuming fatty meals. Dietary fat stimulates the release of cholecystokinin (CCK) from the duodenum. CCK causes the gallbladder to contract and release bile into the small intestine. In patients with biliary dyskinesia, especially those whose symptoms are triggered by gallbladder contraction, high-fat meals can exacerbate pain and biliary colic. 

Therefore, a low-fat diet is commonly recommended to: 
• Reduce gallbladder stimulation 
• Minimize biliary pain after meals 
• Improve tolerance to oral intake 
• Decrease the frequency of symptomatic episodes 

Although a low-fat diet helps manage symptoms, it should still provide adequate essential fatty acids and fat-soluble vitamins, and prolonged severe fat restriction is generally not recommended unless clinically indicated.', '["Low fat","High fat","Low protein","High protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:39:38.409Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-04T11:39:38.409Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:39:38.409Z"'::jsonb),
('anki-card-1756360285845-93', 'anki-deck-1756357465257-1790432463920-rf85m', 'How can the stomach protect itself from the strong acidity of HCl?', 'Mucus secretion forms a protective coat over the mucosa', 'The cells lining the inner wall of the stomach (surface mucous cells and mucous neck cells) continuously secrete a thick, gel-like layer of mucus.

This mucus layer is rich in bicarbonate ions (HCO₃⁻). The alkaline bicarbonate is trapped within the sticky mucus gel, creating a highly effective physical and chemical buffer system. While the liquid inside the stomach cavity is highly acidic with a pH of 1.5 to 2.0, this specialized protective coat maintains a near-neutral pH of around 7.0 right at the surface of the stomach''s epithelial cells, preventing hydrochloric acid (HCl) and pepsin from digesting the stomach wall.', '["Secretin stimulates the release of sodium bicarbonate to neutralize acid","Stomach is covered by thick microvilli","Mucus secretion forms a protective coat over the mucosa","Pancreatic enzymes protect the stomach"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:38:06.773Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:38:06.773Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:38:06.773Z"'::jsonb),
('anki-card-1756358805597-36', 'anki-deck-1756357465257-1790432463920-rf85m', 'In copper-deficiency anemia, iron can not be released because:', 'Ceruloplasmin is lacking', 'Copper deficiency is an uncommon but recognized cause of anemia. Copper is an essential trace mineral required for the activity of several enzymes involved in iron metabolism, hematopoiesis, and cellular respiration. One of the most important copper-containing enzymes is ceruloplasmin, a ferroxidase that oxidizes ferrous iron (Fe²⁺) to ferric iron (Fe³⁺). This conversion is necessary for iron to bind to transferrin, the principal iron transport protein in plasma. 

When copper is deficient: 
• Ceruloplasmin activity decreases. 
• Iron cannot be efficiently mobilized from storage sites such as the liver and macrophages. 
• Iron transport to the bone marrow is impaired. 
• Hemoglobin synthesis becomes inadequate despite normal or even increased body iron stores. 

As a result, patients may develop microcytic, normocytic, or occasionally macrocytic anemia, often accompanied by neutropenia. Copper deficiency should be suspected in patients with unexplained anemia who have undergone bariatric surgery, have prolonged parenteral nutrition without adequate copper supplementation, malabsorptive disorders, or excessive zinc intake, which interferes with copper absorption.', '["Protein is lacking","Vitamin B6 is lacking","Clotting factors are lacking","Ceruloplasmin is lacking"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:37:41.035Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:37:41.035Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:37:41.035Z"'::jsonb),
('anki-card-1756359297941-56', 'anki-deck-1756357465257-1790432463920-rf85m', 'Drug that may cause nausea and vomiting', 'Digitalis', 'Nausea and vomiting are the classic, earliest gastrointestinal hallmarks of digitalis toxicity (e.g., from digoxin). Digitalis works by inhibiting the Na⁺/K⁺ ATPase pump to treat heart failure and arrhythmias, but it has a very narrow therapeutic window.

When digitalis levels become elevated in the blood, the drug directly stimulates the chemoreceptor trigger zone (CTZ) in the medulla oblongata of the brainstem, which triggers a powerful urge to vomit. It is also frequently accompanied by neurological symptoms like anorexia, confusion, and classic visual disturbances (such as a yellow-green halo or blurred vision).

	• Antacids: Are primarily used to neutralize gastric acid and help alleviate nausea associated with indigestion or GERD rather than causing it.
	• Laxatives: Typically cause abdominal cramping, bloating, and diarrhea rather than upper GI symptoms like vomiting.
	• Amphetamines: While stimulants can occasionally cause nausea due to sympathetic nervous system activation, it is not a hallmark warning sign of toxicity or a key diagnostic indicator in the way it is uniquely tied to digitalis management in medical examinations.', '["Antacid","Laxative","Digitalis","Amphetamines"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:35:24.590Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:35:24.590Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:35:24.590Z"'::jsonb),
('anki-card-1756358220808-15', 'anki-deck-1756357465257-1790432463920-rf85m', 'All of the following are components of the body''s buffer systems that help prevent drastic changes in blood pH, EXCEPT:', 'Lipids', 'The human body maintains a tightly regulated blood pH of approximately 7.35–7.45 through several physiologic buffer systems that minimize sudden changes in hydrogen ion (H⁺) concentration. These buffers act immediately before respiratory and renal compensatory mechanisms take effect. 

The three major chemical buffer systems are: 
• Bicarbonate–carbonic acid buffer system – the principal extracellular buffer responsible for maintaining blood pH. 
• Protein buffer system – includes plasma proteins and intracellular proteins such as hemoglobin, which can bind or release hydrogen ions. 
• Phosphate buffer system – functions primarily within cells and in the renal tubules, where it helps regulate acid excretion. 

Lipids are not considered a physiologic buffer system. Although lipids have numerous biological functions—including energy storage, cell membrane structure, and signaling—they do not play a significant role in buffering hydrogen ions or maintaining acid-base balance.', '["Bicarbonate–carbonic acid buffer system","Protein buffer system","Lipids","Phosphate buffer system"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:35:02.002Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:35:02.002Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:35:02.002Z"'::jsonb),
('anki-card-1756359971776-81', 'anki-deck-1756357465257-1790432463920-rf85m', 'All of the following are true of the basal energy expenditure (BEE) except', 'Loss of muscle in old age which may lead to decreased BEE is inevitable', 'The decrease in muscle mass (sarcopenia) and the resulting drop in BEE during old age is not inevitable. Regular resistance training, proper physical activity, and a targeted protein intake can preserve, build, or slow down the loss of lean muscle mass as a person ages, maintaining a higher baseline metabolism.

• It is highest in the first years of life: Size-adjusted BEE peaks sharply during infancy (up to around 15 months of age), running roughly 50 percent higher than adult metabolic values due to rapid growth and development.
• Men have higher BEE than women: Lean body mass is a principal driver of metabolism. Because men generally possess a higher percentage of lean muscle mass and less body fat than women of an equal age and surface area, their baseline BEE is naturally higher.
• It is measured in the fasted state: True clinical measurement of BEE requires the subject to be at absolute rest in a comfortable room temperature after a 12-hour fast to eliminate the thermal effects of digestion.', '["It is highest in the first years of life","It is measured in the fasted state","Loss of muscle in old age which may lead to decreased BEE is inevitable","Men have higher BEE than women"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:34:55.032Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:34:55.032Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:34:55.032Z"'::jsonb),
('anki-card-1756359114848-48', 'anki-deck-1756357465257-1790432463920-rf85m', 'Dietary management for children with severe acute malnutrition during nutritional rehabilitation:
I. Aim to provide 100–200 kcal/kg actual body weight per day, depending on the phase of treatment and clinical condition. 
II. Provide approximately 120–150 mL fluid/kg actual body weight per day, with adjustments based on hydration status and clinical judgment. 
III. Use food items that promote early satiety.', 'I and II only', 'Children with severe acute malnutrition (SAM) require carefully planned nutrition therapy that restores nutritional status while minimizing complications such as refeeding syndrome, heart failure, and electrolyte imbalance. Management follows a phased approach consisting of stabilization, transition, and rehabilitation. 

Statement I is correct. During the rehabilitation phase, children require high-energy diets to achieve catch-up growth. Energy requirements generally range from 100 to 200 kcal/kg/day, depending on the stage of treatment, clinical status, and feeding regimen. Therapeutic foods such as F-100 or Ready-to-Use Therapeutic Food (RUTF) are commonly used during rehabilitation. 

Statement II is correct. Fluid management is equally important because children with severe malnutrition have altered fluid and electrolyte balance. Total fluid intake commonly ranges from 120–150 mL/kg/day, but it should always be individualized according to hydration status, ongoing losses, cardiac function, and the phase of treatment. Excessive fluid administration should be avoided because malnourished children are susceptible to fluid overload. 

Statement III is incorrect. The goal of nutrition therapy is to maximize nutrient and energy intake, not to promote early satiety. Foods that cause early fullness may reduce overall caloric intake and delay nutritional recovery. Instead, children should receive energy-dense, nutrient-dense foods in frequent, small feedings that are well tolerated.', '["I only","II only","I and II only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:31:48.081Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:31:48.081Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:31:48.081Z"'::jsonb),
('anki-card-1756357717281-0', 'anki-deck-1756357465257-1790432463920-rf85m', 'During prolonged starvation, which of the following substances can serve as an energy source? 
I. β-hydroxybutyric acid 
II. Glucose 
III. Acetoacetic acid', 'I and II only', 'During prolonged starvation, the body undergoes metabolic adaptations to preserve lean body mass while ensuring a continuous supply of energy to vital organs. Initially, glycogen stores are depleted within approximately 24 hours. Thereafter, gluconeogenesis becomes the major source of blood glucose, using amino acids, lactate, and glycerol as substrates.

Although glucose production decreases over time to conserve muscle protein, it remains essential because certain tissues cannot utilize fatty acids. The liver simultaneously increases ketogenesis, producing the ketone bodies beta-hydroxybutyrate and acetoacetate from acetyl-CoA generated by beta-oxidation of fatty acids.

These ketone bodies become major fuels for the brain after several days of starvation, reducing its dependence on glucose and sparing muscle protein.

Thus:
• β-Hydroxybutyrate is an important alternative fuel during starvation.
• Acetoacetate is another major ketone body used for energy.
• Glucose continues to be required by tissues such as red blood cells, the renal medulla, portions of the brain, and other glucose-dependent cells.

Therefore, all three substances serve as energy sources during starvation.', '["I only","I and II only","II and III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:31:41.735Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:31:41.735Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:31:41.735Z"'::jsonb),
('anki-card-1756359023804-45', 'anki-deck-1756357465257-1790432463920-rf85m', 'The following are dietary recommendations for Dengue fever, EXCEPT:', 'Fat-restricted', 'Nutrition management is an important component of supportive care for dengue fever, particularly because patients commonly experience fever, anorexia, nausea, vomiting, abdominal pain, fatigue, and dehydration. The goals of nutrition therapy are to maintain hydration, provide adequate energy and protein, and support recovery. 

General dietary recommendations include: 
• High-calorie diet to meet the increased energy demands associated with acute infection and fever. 
• High-protein diet to support tissue repair and preserve lean body mass, especially in patients with poor oral intake. 
• Adjusted food consistency according to tolerance, such as soft or liquid diets for patients with nausea, vomiting, sore throat, or poor appetite. 
• Adequate oral fluids (or intravenous fluids when indicated) to prevent or treat dehydration, which is a major concern in dengue. 

There is no routine recommendation to restrict dietary fat in patients with dengue fever. Fat restriction is reserved for specific gastrointestinal or hepatobiliary conditions and is not part of standard nutrition management for uncomplicated dengue infection.', '["High calorie","High protein","Adjusted food consistency depending on tolerance","Fat-restricted"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:31:21.080Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:31:21.080Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:31:21.080Z"'::jsonb),
('anki-card-1756358609457-29', 'anki-deck-1756357465257-1790432463920-rf85m', 'Phytochemicals found in berries, black tea, and citrus fruits that act as antioxidants and scavenge carcinogens.', 'Flavonoids', 'Flavonoids are a diverse class of polyphenolic plant compounds widely distributed in foods like berries, citrus fruits, and black or green tea.

They are heavily studied in nutrition and clinical biology for their powerful ability to act as direct antioxidants. They scavenge free radicals and carcinogens, alter cellular signaling pathways to trigger carcinogen excretion, and suppress abnormal cellular multiplication to reduce chronic disease risks.

• Phytic acid: Phytic acid is primarily found in the bran and germ layers of whole grains and legumes, where it acts as a mineral-chelating agent.
• Phenols: While flavonoids are structurally a subgroup of larger phenolic compounds, "Phenols" (misspelled as Phenlos in the option) is a broad umbrella category. Flavonoids is the more distinct, precise, and targeted textbook choice for this specific combination of food sources (berries, tea, and citrus).
• Phytosterols: These are plant-derived sterols structurally identical to cholesterol. Their primary therapeutic mechanism is blocking the absorption of dietary cholesterol in the small intestine, not acting as primary carcinogen scavengers.', '["Phenols","Flavonoids","Phytic acid","Phytosterols"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:31:14.158Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:31:14.158Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:31:14.158Z"'::jsonb),
('anki-card-1756359703538-70', 'anki-deck-1756357465257-1790432463920-rf85m', 'Milk substitute given for patient with phenylketonuria', 'Phenex-1', 'Phenylketonuria (PKU) is an autosomal recessive inborn error of metabolism caused by deficiency of the enzyme phenylalanine hydroxylase (PAH). As a result, phenylalanine cannot be adequately converted to tyrosine, leading to the accumulation of phenylalanine in the blood and brain. 

Phenex-1 is one such formula designed specifically for infants with PKU, providing essential amino acids (except phenylalanine), vitamins, minerals, and energy to support normal growth and development.', '["Lonalac","Phenex-1","Soyalac","Probana"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:29:46.976Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:29:46.976Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:29:46.976Z"'::jsonb),
('anki-card-1756359766585-72', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is a correctly written PES (Problem–Etiology–Signs/Symptoms) statement for a nutrition diagnosis?', 'Inadequate energy intake related to decreased appetite secondary to chronic COPD as evidenced by consuming less than 75% of estimated energy needs for 1 month and unintentional weight loss of 6% in one month.', 'A properly structured PES statement connects the specific nutrition problem to an etiology using "related to" and substantiates it with objective clinical signs and symptoms using "as evidenced by".', '["Inadequate energy intake related to decreased appetite secondary to chronic COPD as evidenced by consuming less than 75% of estimated energy needs for 1 month and unintentional weight loss of 6% in one month.","Inadequate energy intake related to consuming less than 75% of estimated energy needs for 1 month and unintentional weight loss of 6% in one month as evidenced by decreased appetite secondary to chronic COPD.","Decreased appetite secondary to chronic COPD related to inadequate energy intake as evidenced by consuming less than 75% of estimated energy needs for 1 month and unintentional weight loss of 6% in one month.","Consuming less than 75% of estimated energy needs for 1 month and unintentional weight loss of 6% in one month."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:08:50.411Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:08:50.411Z"'::jsonb, '"2026-09-26T14:32:29.942Z"'::jsonb, '"2026-11-04T11:08:50.411Z"'::jsonb),
('anki-card-1755048513263-38', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?', 'Theory of Planned Behavior', 'The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:

1. Attitude toward the behavior: The community members'' personal belief that they will benefit from the nutrition program.
2. Subjective Norms: The perceived social pressure from their environment, specifically because their friends think it is also a good idea.
3. Perceived Behavioral Control: Their perceived ease or ability to execute the behavior, which fosters their readiness to get involved.

• Self-determination Theory: Focuses heavily on the internal spectrum of motivation (intrinsic vs. extrinsic), which would be the primary choice if the question emphasized doing the activity out of pure, inherent enjoyment.
• Precaution Adoption Process Model: This is a sequential stage-of-readiness model used to trace how an individual moves from complete unawareness to taking a specific health precaution.
• Health Belief Model: While it includes "perceived benefits", it relies heavily on an individual''s evaluation of a health threat (perceived susceptibility and severity of an illness), which is not the primary focus or motivator described in this scenario.', '["Precaution Adoption Process Model","Health Belief Model","Theory of Planned Behavior","Self-determination Theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:56:36.569Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:56:36.569Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:56:36.881Z"'::jsonb),
('anki-card-1755048409933-37', 'anki-deck-1783608929173-1790433142619-teu0e', 'An element of behavior change which pertains to the capacity of individual to perform a recommended response.', 'Self-efficacy', 'In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.

• Attitude: This refers to an individual''s positive or negative evaluations, feelings, or beliefs about a specific behavior, rather than their physical or mental capacity to perform it.
• Reactance: This is a psychological resistance or negative reaction that occurs when individuals feel their personal freedom or choices are being threatened or restricted.
• Cues to action: These are internal or external triggers (such as a doctor''s advice, a reminder app, or a family illness) that prompt a person to take action.', '["Attitude","Self-efficacy","Cues to action","Reactance"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:50:30.232Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:50:30.232Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:50:30.232Z"'::jsonb),
('anki-card-1755050619445-68', 'anki-deck-1783608929173-1790433142619-teu0e', 'Pre-program evaluation carried out prior to implementation but after program formulation. It is necessary to reassess development needs and project feasibility.', 'Ex-ante evaluation', 'Ex-ante evaluation (literally meaning "before the event" in Latin) is a pre-program evaluation conducted after the program has been formulated but before actual implementation begins. Its primary purpose is to critically re-assess the localized development needs and rigorously audit the overall project feasibility and design viability before resources are officially spent.

• Program implementation review / Mid-term evaluation: These are ongoing, formative evaluations conducted during the execution phase of the project to check progress and implement corrective adjustments.
• Ex-post evaluation: This is an summative evaluation conducted at the very end or after the completion of the implementation stage to assess the total impact and outcomes.', '["Ex-ante evaluation","Ex-post evaluation","Mid-term evaluation","Program implementation review"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:30:21.562Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:30:21.562Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:30:21.851Z"'::jsonb),
('anki-card-1755048356535-36', 'anki-deck-1783608929173-1790433142619-teu0e', 'The goal of nutrition education:', 'To change behavior', 'While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.

Programs that only focus on data transfer fail if they do not fix bad habits. Effective nutrition education is specifically designed to act as a motivational tool that translates knowledge into the continuous, voluntary adoption of healthy eating patterns and long-term dietary behavior changes.', '["To increase knowledge","To improve practices","To change behavior","To promote health"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:25:22.722Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:25:22.722Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:25:23.028Z"'::jsonb),
('anki-card-1755048313671-35', 'anki-deck-1783608929173-1790433142619-teu0e', 'Percent increase of total blood volume during pregnancy?', '33', 'While clinical textbooks often state a general maximum increase of "up to 50%" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).

1. Plasma Volume Increase: During pregnancy, blood plasma (the liquid portion) expands by approximately 45% to 50%.
2. Red Blood Cell Mass Increase: Red blood cells only expand by about 20% to 30% (if the mother has adequate iron stores).
3. The Total Net Blood Volume Increase: Because total blood volume is a weighted combination of these two components (Plasma + RBCs), the net average expansion across the entire duration of a typical healthy pregnancy equates to roughly one-third of the pre-pregnancy baseline, which mathematically maps directly to 33%.', '["50","33","18","25"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:55:35.270Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:55:35.270Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:55:35.591Z"'::jsonb),
('anki-card-1755048286138-34', 'anki-deck-1783608929173-1790433142619-teu0e', 'What is the major maternal fuel source during pregnancy?', 'Fat', 'While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.

• The Sparing Mechanism: Driven by placental hormones like Human Placental Lactogen (hPL), the mother develops a localized insulin resistance. This resistance decreases the mother''s own peripheral utilization of glucose.
• The Primary Fuel: To compensate and sustain her own metabolic needs, the mother accelerates lipolysis (the breakdown of fat stores). This allows her tissues to rely heavily on fat (free fatty acids and ketones) as her primary personal fuel source, effectively "sparing" the sugar for fetal growth.', '["Sugar","Protein","Glycogen","Fat"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:26:19.776Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:26:19.776Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:26:20.103Z"'::jsonb),
('anki-card-1755048188943-32', 'anki-deck-1783608929173-1790433142619-teu0e', 'It refers to the act of giving birth:', 'Parturition', 'Parturition is the specific clinical term for the act or process of giving birth to offspring.

• Puerperium: This is the postpartum period immediately following childbirth, lasting about 6 weeks, during which the mother''s reproductive organs return to their original non-pregnant condition.
• Parity: This refers to the number of pregnancies in which the fetus or fetuses have reached a viable gestational age (usually 20 to 24 weeks), regardless of whether the child is born alive or stillborn.
• Gestation: This is the period of development inside the womb from conception until birth (pregnancy).', '["Parturition","Puerperium","Gestation","Parity"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:06.199Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:06.199Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:06.521Z"'::jsonb),
('anki-card-1755050539867-67', 'anki-deck-1783608929173-1790433142619-teu0e', 'Among the criteria in selecting nutrition intervention, the following must not be missed:', 'Relevance, feasibiltiy, effectiveness', 'In classical program management and nutrition planning frameworks (such as those taught by FAO and the National Nutrition Council), interventions must pass three fundamental, non-negotiable filters during the screening phase:

1. Relevance (Appropriateness): Does the intervention directly solve the specific, prioritized nutrition problem of that population? (e.g., if the problem is Vitamin A deficiency, the intervention must be Vitamin A supplementation or food fortification, not general sanitation).
2. Feasibility (Practicability): Can it actually be done given the available budget, technical expertise, administrative infrastructure, and time constraints?
3. Effectiveness (Impact): Is there proven scientific or empirical evidence that this specific strategy will successfully lower malnutrition rates or improve the target nutritional indicators?', '["Relevance, feasibility, ease in targeting and evaluation","Relevance, feasibiltiy, effectiveness","Relevance, feasibility, cost-effectiveness","Relevance, feasibility, political support, willingness of beneficiaries to participate"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:30:36.334Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:30:36.334Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:30:36.670Z"'::jsonb),
('anki-card-1755050451854-66', 'anki-deck-1783608929173-1790433142619-teu0e', 'It refers to concrete and specific statement of desired achievement. It is more focused and specific time dimension, client population and end results.', 'Objectives', 'In program planning and strategic management, objectives are defined as concrete, precise, and short-term statements of desired achievement. Unlike broad statements, an objective is specifically written to outline:
• A defined client population (who will benefit)
• A strict time dimension (when it will be achieved)
• Explicit, measurable end results (what the exact target is)

• Goals: These are broad, long-range, and general statements of an overall vision (e.g., "To reduce the prevalence of malnutrition in the region"), but they lack the operational and highly focused parameters of an objective.
• Mission: This explains the primary motivation, fundamental beliefs, and the overall reason for the organization''s existence.
• Vision: This is an aspirational, long-term description of a desired future state.', '["Vision","Mission","Goals","Objectives"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:17:36.525Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:17:36.525Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:17:36.837Z"'::jsonb),
('anki-card-1755048061618-29', 'anki-deck-1783608929173-1790433142619-teu0e', 'A hormone that stimulates milk ejection and promotes uterine contraction.', 'Oxytocin', 'Oxytocin is a hormone produced in the hypothalamus and released by the posterior pituitary gland that plays two vital roles in maternal physiology:

1. Milk Ejection (The Let-Down Reflex): It causes the myoepithelial cells surrounding the alveoli of the mammary glands to contract, squeezing milk into the ducts so the baby can suckle.
2. Uterine Contraction: It stimulates the smooth muscles of the uterus to contract during labor (to deliver the baby) and postpartum (to minimize bleeding and help the uterus return to its pre-pregnancy size).

• Prolactin: This hormone is responsible for the actual production and synthesis of breast milk within the alveoli, but it does not eject it.
• Estrogen: This hormone stimulates the development of the mammary duct system during pregnancy but actually blocks the full effect of prolactin until after delivery.
• Growth hormone: This is involved in general tissue growth and metabolic functions, not specific lactational or reproductive reflexes.', '["Prolactin","Oxytocin","Estrogen","Growth hormone"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:00:21.688Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:00:21.688Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:00:21.992Z"'::jsonb),
('anki-card-1755050329410-65', 'anki-deck-1783608929173-1790433142619-teu0e', 'The following is/are true for problem matrix, causal model, or problem tree EXCEPT:', 'Formulated by the BNS and presented to LCE as an advocacy tool', 'Formulating a problem tree, causal model, or problem matrix is not a task done individually by the Barangay Nutrition Scholar (BNS). According to local nutrition planning guidelines, it requires collective brainstorming and data analysis from the entire members of the Local Nutrition Committee (LNC) during their strategic planning meetings. The entire plan (not just the tree) is what is eventually packaged and presented to the Local Chief Executive (LCE) for adoption and funding.', '["Trace the chain of factors that can affect nutrition situation","Constructed by asking and answering a series of \"whys\" to understand better the factors","Formulated by the BNS and presented to LCE as an advocacy tool","Being updated every year as a result of new data on nutrition situation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:19:00.747Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:19:00.747Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:19:01.066Z"'::jsonb),
('anki-card-1755050219647-64', 'anki-deck-1783608929173-1790433142619-teu0e', 'A principle in planning that refers to desired breadth and depth of the nutrition program.', 'Comprehensiveness', 'Comprehensiveness is a core principle in nutrition program planning and management. It explicitly dictates that the desired breadth and depth of whatever has been selected as the overall scope of the program or project must be thoroughly and accurately reflected in the actual plan.

• Balance: Emphasizes that all specific activities, tasks, and resource allocations are properly distributed so that they directly contribute to the achievement of the program''s objectives.
• Workability: Mandates that the plan must be operationally practical, meaning the objectives are completely realistic and achievable within the set timeframe and available resources.
• Appropriateness: Refers to how well the designed program fits the localized cultural, environmental, and socio-economic context of the target community.', '["Comprehensiveness","Balance","Workability","Appropriateness"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:51.662Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:51.662Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:51.983Z"'::jsonb),
('anki-card-1755050161185-63', 'anki-deck-1783608929173-1790433142619-teu0e', 'It is known as participatory planning that involves local leaders, implementers and people themselves in planning the program.', 'Joint planning', 'In program planning and management (particularly within nutrition and public health frameworks), Joint planning is explicitly defined as a type of participatory planning. It acts as a hybrid approach that combines elements of both top-down and bottom-up planning strategies. This method ensures comprehensive collaboration by actively involving local leaders, the implementers, and the target beneficiaries (the people themselves) directly in the program design.

• Microlevel planning: This refers strictly to planning conducted at the localized, community, or grass-roots level (such as creating a specific barangay or municipal nutrition plan).
• Strategic planning: This is a systematic process of mapping out a long-term vision, transforming that vision into broadly-defined strategic goals, and determining the sequential steps needed to achieve them.
• Food and nutrition planning: This is the overarching thematic discipline focused on formulating national policies, interventions, and guidelines to combat malnutrition and ensure food security.', '["Food and nutrition planning","Joint planning","Strategic planning","Microlevel planning"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:28:52.574Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:28:52.574Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:28:52.887Z"'::jsonb),
('anki-card-1755050102842-62', 'anki-deck-1783608929173-1790433142619-teu0e', 'Mobilization of LGUs; policy development for food and nutrition; and strengthened management support are known as ____. These are necessary for the implementation of PPAN.', 'Enabling programs', 'Under the Philippine Plan of Action for Nutrition (PPAN) framework managed by the National Nutrition Council (NNC), these three components are specifically classified as enabling support programs:

1. Mobilization of LGUs for nutritional outcomes
2. Policy development for food and nutrition
3. Strengthened management support

These programs are designated to ensure that both nutrition-specific and nutrition-sensitive interventions are well-coordinated and effectively implemented across all local government levels.', '["Nutrition advocacy","Support services","Enabling programs","Facilitating initiatives"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:39:46.557Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:39:46.557Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:39:46.884Z"'::jsonb),
('anki-card-1755050015125-61', 'anki-deck-1783608929173-1790433142619-teu0e', 'These are development projects that were tweaked to produce nutritional outcomes by targeting households with undernourished children.', 'Nutrition-Sensitive', '', '["Nutrition-Specific","Nutrition-Sensitive","Nutrition Promotion","Nutrition Advocacy"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:08:34.804Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:08:34.804Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:08:35.122Z"'::jsonb),
('anki-card-1755049938960-60', 'anki-deck-1783608929173-1790433142619-teu0e', 'The national dietary supplement program targets the following age groups EXCEPT:', 'Infants 0-5 months', 'The National Dietary Supplementation Program (NDSP)—including its banner strategy Tutok Kainan—deliberately excludes infants 0 to 5 months old from receiving solid food or dietary supplements. According to global and local healthcare standards, infants in this age bracket must practice strict exclusive breastfeeding; introducing any form of dietary supplementation or complementary food would disrupt this and increase the risk of infection.

Targeted Vulnerable Groups Under the NDSP:
• Pregnant women (especially those classified as nutritionally at-risk, provided food support for 90 days).
• Young children 6 to 59 months old (broken down into infants/toddlers aged 6–23 months for complementary feeding, and children aged 24–59 months).
• School children (specifically severely wasted or wasted kindergarten to Grade 6 students enrolled in public schools).', '["Infants 0-5 months","Young children 6-59 months old","School children","Pregnant women"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:24:31.730Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:24:31.730Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:24:32.047Z"'::jsonb),
('anki-card-1755049879115-59', 'anki-deck-1783608929173-1790433142619-teu0e', 'The Philippine Plan of Action for Nutrition is integrated and/or consistent with the following EXCEPT:', 'Philippine Environmental Plan', 'The Philippine Plan of Action for Nutrition (PPAN) serves as the country’s comprehensive multi-sectoral framework designed to combat all forms of malnutrition. It is systematically aligned with, and anchored into, the following major national development strategies:

• Philippine Development Plan (PDP): It is an integral sub-component of the national Philippine Development Plan framework, directly contributing to social transformation, human development, and poverty reduction goals.
• Health for All Agenda of the DOH: It directly supports the Department of Health’s principal universal healthcare blueprints (such as the National Objectives for Health and its respective action agendas).
• Ambisyon Natin 2040: It explicitly serves as an operational mechanism to meet the long-term vision of Ambisyon Natin 2040 by ensuring a healthy, well-nourished, and highly productive citizenry.', '["Philippine Development Plan","Health for All Agenda of DOH","Ambisyon Natin 2040","Philippine Environmental Plan"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:21:50.507Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:21:50.507Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:21:50.820Z"'::jsonb),
('anki-card-1755049797869-58', 'anki-deck-1783608929173-1790433142619-teu0e', 'A point person in nutrition who is a regular employee of and under the plantilla of NNC.', 'RNPC', 'The Regional Nutrition Program Coordinator (RNPC) is a permanent, regular civil service worker who occupies a formal plantilla item directly under the budget and structural organization of the National Nutrition Council (NNC). They serve as the head of the NNC Regional Secretariat, managing regional policy execution, monitoring local implementations of the PPAN, and coordinating across subnational administrative levels.

• CNAO / CNPC (City Nutrition Action Officer / City Nutrition Program Coordinator) & DNPC (District Nutrition Program Coordinator): These positions operate at the Local Government Unit (LGU) level. They are typically funded by the local city, municipality, or province budgets rather than holding a national NNC secretariat plantilla item, or they are designated from other existing local health department roles.', '["CNPC","DNPC","CNAO","RNPC"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:23:36.167Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:23:36.167Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:23:36.477Z"'::jsonb),
('anki-card-1755049737971-57', 'anki-deck-1783608929173-1790433142619-teu0e', 'A suitable indicator for the evaluation of child feeding programs is change in:', 'Child''s weight for length/height', 'Supplementary feeding programs for infants and young children primarily target the eradication of wasting (acute malnutrition) and the restoration of normal body mass. The most sensitive, immediate, and reliable indicator to evaluate whether a short-term feeding program is successfully working is the change in a child''s weight-for-length (for infants under 2 years) or weight-for-height (for older children).', '["Child''s weight for length/height","Child''s height","Child''s improved feeding practices","Decreased incidence of diarrhea among children"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:20:27.873Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:20:27.873Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:20:28.201Z"'::jsonb),
('anki-card-1755050962412-73', 'anki-deck-1783608929173-1790433142619-teu0e', 'It is the focus of the Sustainable Development Goal #2', 'Hunger and malnutrition', 'The United Nations Sustainable Development Goals (SDGs) are a blueprint of 17 global goals to build a better future. SDG #2 focuses directly on ending hunger, achieving food security, improving nutrition, and promoting sustainable agriculture.

• Health: This is SDG #3 (Good Health and Well-being).
• Access to clean water and sanitation: This is SDG #6 (Clean Water and Sanitation).
• Responsible production and consumption: This is SDG #12 (Responsible Consumption and Production).', '["Health","Access to clean water and sanitation","Hunger and malnutrition","Responsible production and consumption"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T17:12:50.464Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T17:12:50.464Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T10:22:02.136Z"'::jsonb),
('anki-card-1755046111415-0', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is an objective of nutritional assessment?', 'A and B', '', '["Identify individuals who are malnourished","Provide data for designing a nutrition plan of care or nutrition programs that will prevent or minimize the development of malnutrition","Neither A nor B","A and B"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:13:38.048Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T08:13:38.048Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:13:38.375Z"'::jsonb),
('anki-card-1755046180839-1', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is the easiest and most popular method for obtaining information about dietary intake?', '24-hour recall', 'In clinical and community nutrition settings, the 24-hour dietary recall is recognized as the easiest and most popular method for collecting dietary intake data.

• Why it is the easiest: It carries a very low burden for the participant. It does not require literacy, advanced preparation, or active logging over several days like a food diary does.
• Why it is the most popular: It can be administered quickly by an interviewer (often taking only 15 to 20 minutes) using a backward-in-time structured recall approach. It provides a rapid snapshot of an individual''s immediate dietary pattern without altering their typical eating behavior.', '["Food frequency questionnaire","3-day food diary","24-hour recall","Direct observation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T09:06:52.148Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T09:06:52.148Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:06:52.472Z"'::jsonb),
('anki-card-1755046358247-3', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is a disadvantage of the food frequency questionnaire?', 'Noncompliance/Nonresponse', '', '["Noncompliance/Nonresponse","Atypical intake on the recording day","Conscious alteration of diet during the recording period","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755046416177-4', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which is the most common site used for obtaining skinfold thickness measurement.', 'Tricep skinfold (TSF)', 'The triceps skinfold (TSF) is universally recognized as the most commonly used single-site skinfold measurement in clinical, nursing, and field research settings.

It is highly favored because it is the most easily accessible anatomical site, requires minimal subject repositioning, and possesses a vast wealth of reference data—such as the World Health Organization (WHO) growth standards—for rapid comparison.

While clinical models like the Durnin and Womersley system sum the triceps, biceps, subscapular, and suprailiac sites to track total body composition, the triceps remains the baseline index location used on its own to reliably evaluate upper-body fat reserves.', '["Biceps skinfold (BSF)","Suprailic skinfold","Subcapsular skinfold","Tricep skinfold (TSF)"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:11:46.314Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T08:11:46.314Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:11:46.604Z"'::jsonb),
('anki-card-1755046454711-5', 'anki-deck-1783608929173-1790433142619-teu0e', 'What does the mid-upper arm muscle (MAMC) estimate?', 'A and B', 'Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:
MAMC = MUAC - (π * TSF)

It serves as a critical indicator in nutritional assessments because:
• Skeletal Muscle Reserves: Because the arm consists primarily of bone, muscle, and a surrounding layer of subcutaneous fat, subtracting the fat thickness (via the triceps skinfold) isolates the muscle component. This directly gauges the body''s skeletal muscle reserves.
• Lean Body Mass: In clinical malnutrition states (such as marasmus or chronic disease cachexia), the body breaks down its skeletal muscle tissue to use for energy. Therefore, measuring MAMC provides a reliable proxy estimate of a patient''s overall lean body mass.

Why "Fat reserve" is incorrect:
The Triceps Skinfold (TSF) thickness alone is what isolates and estimates subcutaneous fat reserves. MAMC specifically subtracts the fat to look only at muscle tissue.', '["The amount of lean body mass","Skeletal muscle reserves","Fat reserve","A and B"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T17:12:55.828Z","interval":3,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-14T17:12:55.828Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T10:23:32.763Z"'::jsonb),
('anki-card-1755046509573-6', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following dietary assessment methods provides more qualitative than quantitative information?', 'Food frequency', '', '["Food frequency","Diet history","Food record","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755046551289-7', 'anki-deck-1783608929173-1790433142619-teu0e', 'Food records are usually collected for what period of time?', '1-7 days', 'In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.', '["1-7 days","1 day","3-4 days","2 weeks"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:11:07.250Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T08:11:07.250Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:33:38.537Z"'::jsonb),
('anki-card-1755046604135-8', 'anki-deck-1783608929173-1790433142619-teu0e', 'In which method does the interviewer ask a person to report all food used by the household on an as-purchased basis?', 'Food account', '', '["Food account","Inventory","List recall","Food record"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755046696749-9', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following statements are true regarding body measurements?', 'All of the above', '', '["Infants and children under the age of 2 should be measure in the recumbent position","Knee height measurement is useful for people with spinal curvature","Head circumference is used as a measure of brain size in infant and young children","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T09:04:25.145Z","interval":3,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-16T09:04:25.145Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:04:25.479Z"'::jsonb),
('anki-card-1755046751580-10', 'anki-deck-1783608929173-1790433142619-teu0e', 'What do waist-to-hip circumference ratios measure?', 'Intra-abdominal fat and subcutaneous fat', 'Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying "apple-shaped" vs. "pear-shaped" body types).

Because it gauges your midsection width, the ratio serves as an accessible proxy marker for tracking accumulated intra-abdominal fat (visceral fat that envelopes your internal organs) alongside abdominal subcutaneous fat (fat stored directly beneath the skin). An elevated ratio indicates central obesity, which heavily correlates with metabolic and cardiovascular diseases.', '["Fat-free mass","Intra-abdominal fat and subcutaneous fat","Protein-energy malnutrition","Skeletal mass"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:28:25.922Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T08:28:25.922Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:28:26.240Z"'::jsonb),
('anki-card-1755046781362-11', 'anki-deck-1783608929173-1790433142619-teu0e', 'Taste acuity tests may be given to determine a deficiency of what element?', 'Copper', '', '["Copper","Iron","Selenium","Zinc"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755046871555-12', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which one of the following techniques can be used to measure visceral fat distribution?', 'Computed tomography', '', '["Densitometry","Computed tomography","Air desplacement plethysmorgraphy","Bioelectric impedance analysis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755046923503-13', 'anki-deck-1783608929173-1790433142619-teu0e', 'Deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?', 'Zinc', 'Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.
• Increased risk of infection: Zinc deficiency impairs cell-mediated immunity and mucosal barriers, making children highly susceptible to severe infections like diarrhea and pneumonia.
• Growth failure & Delayed sexual maturity: Zinc plays an indispensable structural role in growth hormone function and gonadotropin secretion. Severe deficiency directly arrests linear skeletal growth (causing stunting or growth failure) and leads to hypogonadism or delayed sexual development in adolescents.

• Calcium: Primary deficiencies lead to rickets in children and osteomalacia in adults, characterized by poor bone mineralization rather than delayed sexual maturity.
• Iodine: Deficiency causes goiter and hypothyroidism, and severe prenatal deficiency leads to cretinism (profound intellectual disability and physical stunting), but it is not typically grouped under this specific childhood triad.
• Riboflavin (Vitamin B2): Deficiency manifests as ariboflavinosis, which presents with cheilosis (cracked lips), angular stomatitis (cracks at the corners of the mouth), and glossitis (magenta tongue).', '["Iodine","Zinc","Riboflavin","Calcium"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:00:07.006Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T08:00:07.006Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:00:07.288Z"'::jsonb),
('anki-card-1755046986669-14', 'anki-deck-1783608929173-1790433142619-teu0e', 'A requirement is the intake of a nutrient required by an individual to ___.', 'Prevent clinical signs of deficiency', '', '["Prevent clinical signs of deficiency","Prevent subclinical signs of deficiency","Permit optimal function of biochemical pathways","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:19:37.362Z","interval":3,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-16T08:19:37.362Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:19:37.717Z"'::jsonb),
('anki-card-1755046292035-2', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is a common error that occurs with the 24-hour diet recall?', 'All of the above', '', '["Snack items and the use of gravies, sauces, and condiments may be underreported","The individual of family member may not be able to recall the type or amount of food eaten","The intake within the last 24 hours may be atypical of usual intake","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:25:30.565Z","interval":3,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-10-16T08:25:30.565Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:25:30.882Z"'::jsonb),
('anki-card-1755048118831-30', 'anki-deck-1783608929173-1790433142619-teu0e', 'The estimated risk of HIV transimission from mother to child during breastfeeding is?', '5-20%', 'In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.

The Overall Risk Breakdown (Without Intervention):

• Gestation and Labor/Delivery: 15% to 30% risk.
• Breastfeeding: Additional 5% to 20% risk (which heavily depends on the duration of breastfeeding, as prolonged mixed feeding over 2 years can double the acquisition risk closer to 20%).
• Total Combined Risk: 15% to 45%.', '["5-10%","10-15%","5-20%","15-25%"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:27:22.984Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:27:22.984Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:27:23.310Z"'::jsonb),
('anki-card-1755051762226-75', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following statements are true regarding body measurements?', 'All of the above', '', '["Infants and children under the age of two should be measured in the recumbent position","A knee height measurements is useful for people with spinal curvature","Head circumference is used as a measure of brain size in infants and young children","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:04:32.383Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:04:32.383Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:04:32.707Z"'::jsonb),
('anki-card-1755052230619-76', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is not plagiarism?', 'Re-drawing the RCT process, it not original or specific', 'Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.', '["Transcribing or modifying text from any printed material (encylopedias, books, magazines, newspapers)","Using another student''s work and claiming it as your own","Using photographs, video or audio without permission","Re-drawing the RCT process, it not original or specific"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:10:26.536Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:10:26.536Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:10:26.864Z"'::jsonb),
('anki-card-1755047067496-15', 'anki-deck-1783608929173-1790433142619-teu0e', 'It is an objective, accurate, systematic analysis of a determinate body of empirical data, in order to discover recurring relationship among phenomena.', 'Research design', '', '["Science","Science method","Research","Research design"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb)
