INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1755047141778-16', 'anki-deck-1783608929173-1790433142619-teu0e', 'What type of study will you use if you want to conduct dose-response assays effect on individual cells?', 'In-vitro testing (human)', 'To find the right answer, you need to break down the two parts of the question:

1. "Individual Cells": Testing a substance on isolated cells or tissue cultures outside of a whole living organism is the definition of an in-vitro study (which literally translates from Latin as "in glass," referring to test tubes or petri dishes). Testing an entire living body would be an in-vivo study.
2. "Human" vs. "Animal": When a research scientist conducts basic laboratory dose-response assays on cell lines to eventually apply those findings to public health, nutrition, or medicine, using isolated human cells (such as human liver, muscle, or intestinal cell lines) is highly preferred. Human cell models provide more accurate information about human metabolic pathways and receptor behaviors than animal models can.

Quick Reference Map
• In-vitro: Performed outside a living organism using isolated cells, tissues, or organs in a controlled lab setup (e.g., test tubes, plates).
• In-vivo: Performed inside a whole, intact, living organism (such as feeding trials in living humans or lab animals).', '["In-vitro testing (human)","In-vivo studies (animals)","In-vivo studies (human)","In-vitro testing (animal)"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T09:15:56.829Z","interval":3,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-16T09:15:56.829Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:15:57.148Z"'::jsonb),
('anki-card-1755047189890-17', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following characterizes that the cause precedes the effect or outcome in a study?', 'Temporal relationship', 'Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.

• Precision: Refers to the reproducibility and exactness of a specific measurement under unchanged conditions.
• Internal validity: The degree to which a study successfully rules out alternative explanations (confounders) for the results. While temporal precedence is a crucial requirement to establish internal validity for a causal claim, the specific concept of "time ordering" itself is defined as temporality.
• External validity: The extent to which the final results of a study can be generalized or applied to other settings, populations, or times.', '["Internal validity","External validity","Temporal relationship","Precision"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:18:06.902Z","interval":3,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-16T08:18:06.902Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:18:07.207Z"'::jsonb),
('anki-card-1755047253240-18', 'anki-deck-1783608929173-1790433142619-teu0e', 'An experiment in which groups of individuals rather than independent individuals are randomly allocated to intervention groups.', 'Cluster randomized trial', 'In epidemiology and research design, a cluster randomized trial (also known as a group-randomized trial) is specifically characterized by assigning intact groups of individuals—such as entire villages, schools, households, or clinics—to the intervention or control groups rather than randomizing each person independently.

• Randomized controlled trial (RCT): In its standard form, an RCT randomizes individual participants independently into different treatment arms.
• Cohort study: This is an observational study design where researchers track a group of individuals forward in time based on their exposure status; it does not involve random allocation.
• Case-control study: This is an observational retrospective study design where individuals are selected based on whether they have a specific outcome ("cases") or not ("controls") to investigate past exposures.', '["Cohort study","Case-control study","Randomized controlled trial","Cluster randomized trial"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-19T08:58:44.029Z","interval":3,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-16T08:58:44.029Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:58:44.357Z"'::jsonb),
('anki-card-1755047310569-19', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is NOT considered as a systematic error?', 'Measurement error', '', '["Selection bias","Recall bias from participants","Measurement error","Loss to follow-up"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755048254475-33', 'anki-deck-1783608929173-1790433142619-teu0e', 'Approximately how many kilocalories does a mature milk contain?', '60-75 kcal/100 ml', 'On average, mature human breast milk contains about 65 to 70 kcal per 100 mL.

Standard pediatric and nutritional reference textbooks define the typical baseline range of energy yield for mature human milk as 60–75 kcal/100 mL (which perfectly corresponds to about 18–22 kcal per ounce).

This caloric density is primarily driven by its fat content (making up roughly 50% of the total energy) and carbohydrates/lactose (making up about 40%).', '["60-75 kcal/100 ml","80-90 kcal/100 ml","45-60 kcal/100 ml","90-105 kcal/100 ml"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:26:26.028Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:26:26.028Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:26:26.334Z"'::jsonb),
('anki-card-1755047384682-20', 'anki-deck-1783608929173-1790433142619-teu0e', 'The process of this type of research is to describe, analyze and interpret the conditions that now exist.', 'Descriptive research', 'Descriptive research is explicitly designed to describe, analyze, and interpret a phenomenon, situation, or population as it currently exists. It focuses heavily on answering the what, where, when, and how questions without manipulating any of the research variables.

• Applied research focuses on finding practical solutions to an immediate problem using accepted theories.
• Experimental research relies on manipulating an independent variable to establish strict cause-and-effect relationships under controlled conditions.
• Historical research deals with uncovering, interpreting, and analyzing events that occurred in the past rather than conditions that now exist.', '["Historical research","Descriptive research","Experimental research","Applied research"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:58:33.602Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:58:33.602Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:58:33.882Z"'::jsonb),
('anki-card-1755047490294-21', 'anki-deck-1783608929173-1790433142619-teu0e', 'The study design which describes the experience of a single case or a group of patients with similar diagnosis based on sporadic discoveries of a unique, unusual or unexpected clinical observation. It provides first clues in recognition of disease and identifies risk factors or effects of exposure.', 'Case report', '1. "Describes the experience of a single case...": While a Case Series compiles multiple similar profiles together into a structured dataset, a Case Report is fundamentally defined as the baseline document describing the experience of a single case. In professional taxonomies, the parent definition of this type of design is titled under "Case Report" because it is the actual first line of evidence generated by an unexpected observation.

2. "Sporadic discoveries": A case series implies a systematic grouping or a consecutive collection of patients over time who meet specific criteria (e.g., tracking the next 5 patients who enter a clinic with a specific symptom). An unexpected, random, or sporadic clinical observation of a unique phenomenon is, by definition, published immediately as a singular Case Report to alert the medical community.

Summary
• Case Report: The baseline research design triggered by a sporadic, unusual, or unexpected clinical finding in an individual. It provides the very first clues that a new disease or exposure reaction exists.
• Case Series: The design used after multiple case reports accumulate, allowing researchers to aggregate a larger group of patients with that same diagnosis to look for statistical trends.', '["Case report","Case series","Case study","Ecological study"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:17:26.732Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:17:26.732Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:17:27.040Z"'::jsonb),
('anki-card-1755047594439-22', 'anki-deck-1783608929173-1790433142619-teu0e', 'What type of hypothesis is this?
Ho: The mean score of school children in the nutrition education in the control group is ≤75%.
Ha: The mean score of school children in the nutrition education in the control group is >75%.', 'Directional one-tailed hypothesis', 'To determine the type of hypothesis, you must always look closely at the mathematical sign used in the Alternative Hypothesis (Ha):
1. Directional: The alternative hypothesis explicitly states that the mean score is greater than (>) 75%. Because it specifies a particular direction of change (higher/improvement) rather than just any general difference, it is directional.
2. One-tailed: Because it only looks for an effect in one direction, the rejection region (critical region) is located entirely in a single extreme side—the right tail—of the sampling distribution curve.

Quick Reference Map
• Directional One-Tailed: Uses strictly > or < in Ha (e.g., higher, lower, increased, decreased).
• Non-Directional Two-Tailed: Uses strictly != or not equal to in Ha (e.g., different from, changed, not equal to).', '["Non-directional two-tailed hypothesis","Directional two-tailed hypothesis","Non-directional one-tailed hypothesis","Directional one-tailed hypothesis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:09:46.914Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:09:46.914Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:09:47.218Z"'::jsonb),
('anki-card-1755047691868-23', 'anki-deck-1783608929173-1790433142619-teu0e', 'In the choice of research strategy, it answers "Does the data exist in a tangible or an intangible form?" and specifically understand how social factors interact.', 'Ontology-Constructionism', 'This question tests the foundational concepts of research philosophy (specifically within public health nutrition and community research modules):

1. Ontology: This branch of philosophy addresses the nature of reality and asks, "Does the data exist in a tangible or an intangible form?" It looks at whether social entities exist independently of our perceptions or if they are built up from our perceptions.
2. Constructionism (Subjectivism): This ontological stance holds that social phenomena and their meanings are continually being accomplished and revised by social actors. It specifically focuses on understanding how social factors interact to create meaning, as opposed to Objectivism, which views social reality as an external, concrete objective fact.

In contrast, Epistemology deals with how we acquire knowledge (e.g., through Positivism or Interpretivism), rather than whether reality itself is fundamentally tangible or intangible.', '["Epistemology-Positivism","Epistemology-Interpretivism","Ontology-Objectivism","Ontology-Constructionism"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:29:42.974Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:29:42.974Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:29:43.300Z"'::jsonb),
('anki-card-1755047750015-24', 'anki-deck-1783608929173-1790433142619-teu0e', 'A form of severe undernutrition that occurs after breastfeeding stops, and the child is weaned with a starchy diet.', 'Kwashiorkor', 'Kwashiorkor is a severe form of protein-energy malnutrition (PEM) that typically occurs during early childhood. The name stems from a Ga language word meaning "the sickness the old baby gets when the new baby comes."

It classically manifests when a child is abruptly weaned from protein-rich breast milk (often because a younger sibling is born) and transitioned onto an inadequate, starchy, protein-deficient diet (such as rice, maize, cassava, or porridge). While the child may receive enough calories from carbohydrates, the lack of protein causes fluid to leak into the tissues, leading to the condition''s signature edema (swollen belly and feet).', '["Marasmus","Kwashiorkor","Wasting","Stunting"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:11:38.134Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:11:38.134Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:11:38.451Z"'::jsonb),
('anki-card-1755047841910-25', 'anki-deck-1783608929173-1790433142619-teu0e', 'The law that mandate the establishment of the functional nutrition committee in every region, province, city, municipality, and baranagy in the country.', 'LOI 441', 'Letter of Instructions No. 441 (LOI 441), issued on July 31, 1976, directed the Department of Local Governments and Community Development (now the DILG) to establish functioning nutrition committees in every region, province, city, municipality, and barangay across the Philippines to properly execute the national nutrition plan at all subnational levels.

• PD 491 (Presidential Decree No. 491): Created the National Nutrition Council (NNC) in 1974 as the highest policy-making and coordinating body on nutrition in the country.
• AO No. 88 (Administrative Order No. 88): Deals with administrative government structural reorganizations unrelated to the foundational mandate of local nutrition committees.
• EO 285 (Executive Order No. 285): Reorganized the National Nutrition Council under the Department of Social Welfare and Development (and later amended by other EOs) rather than establishing the local committee mandates.', '["EO 285","LOI 441","PD 491","AO No. 88"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:25:38.945Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:25:38.945Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:25:39.311Z"'::jsonb),
('anki-card-1755047891909-26', 'anki-deck-1783608929173-1790433142619-teu0e', 'What is the stomach capacity of an infant at birth?', '10-12 ml', 'Anatomically, the newborn stomach is positioned horizontally with a high-riding, poorly developed fundus and a relaxed lower esophageal sphincter, resulting in a low baseline volume capacity of 10-12 mL (about 0.5 to 1 ounce). Colostrum volume produced during initial postpartum lactation matches this capacity perfectly, as concentrated nutrients meet metabolic demands without exceeding gastric distension limits or triggering excessive stretch receptor-mediated regurgitation.', '["5-10 ml","10-12 ml","20-25 ml","25-30 ml"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:26:19.606Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:26:19.606Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:26:19.942Z"'::jsonb),
('anki-card-1755047944990-27', 'anki-deck-1783608929173-1790433142619-teu0e', 'A wet nurse is:', 'A woman who breastfeeds another woman''s baby', 'A wet nurse is a woman employed or volunteered to breastfeed and care for another woman''s child, usually because the biological mother is unable, unavailable, or chooses not to breastfeed. This practice has been historically widespread and remains a traditional strategy in human infant feeding alternative networks.', '["Registered nurse","Registered midwife","A baby sitter","A woman who breastfeeds another woman''s baby"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:14:34.637Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:14:34.637Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:14:34.968Z"'::jsonb),
('anki-card-1755048013970-28', 'anki-deck-1783608929173-1790433142619-teu0e', 'It is the process of feeding a child who is not breastfed with a diet that provides all the nutrients the child needs until the child is fully fed on family food.', 'Replacement feeding', 'This is the exact, verbatim definition used by the World Health Organization (WHO) and global Infant and Young Child Feeding (IYCF) guidelines.

Replacement feeding is defined as the process of feeding a child who is not receiving any breast milk with a diet that provides all the nutrients the child needs until they can be fully transitioned onto regular family food. In public health settings (especially within maternal health and PMTCT/HIV programs), replacement feeding typically involves exclusive commercial infant formula for the first 6 months, followed by nutrient-dense solid foods paired with a suitable breast milk substitute from 6 months onward.', '["Complementary feeding","Cup feeding","Replacement feeding","Formula feeding"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:12:19.407Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:12:19.407Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:12:19.717Z"'::jsonb),
('anki-card-1755049656458-56', 'anki-deck-1783608929173-1790433142619-teu0e', 'The basic tasks of BNS are the following EXCEPT:', 'Leads in the preparation of the local nutrition action plan', 'According to the official National Nutrition Council (NNC) guidelines and the Barangay Nutrition Scholar (BNS) Handbook, the basic tasks of a BNS are clearly codified as:

1. Caring for the malnourished (identifying and tracking them via Operation Timbang Plus)
2. Mobilizing the community
3. Linkage-building
4. Keeping records (maintaining barangay nutrition profiles and family sheets)

The BNS does not lead the preparation of the Local Nutrition Action Plan (LNAP). Leadership and authorship of the plan fall under the mandate of the Local Nutrition Committee (LNC) and its Chairperson (the Punong Barangay / Barangay Captain). The role of the BNS is strictly to assist and provide data to the committee during the formulation of the Barangay Nutrition Action Plan (BNAP).', '["Caring for the malnourished","Mobilizing the community","Keeping records","Leads in the preparation of the local nutrition action plan"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:10:59.380Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:10:59.380Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:10:59.706Z"'::jsonb),
('anki-card-1755049605576-55', 'anki-deck-1783608929173-1790433142619-teu0e', 'In the BNS program guidelines, the direct trainer-supervisor of the BNS is:', 'District/City Nutrition Program Coordinator', 'According to the official guidelines issued by the National Nutrition Council (NNC), the District/City Nutrition Program Coordinator (D/CNPC) serves as the direct trainer-supervisor of the Barangay Nutrition Scholar (BNS).

• The D/CNPC is explicitly tasked with organizing, conducting, and supervising both the core didactic training and the subsequent 20-day local community practicum for new scholars.
• Guidelines specify that only in the structural or operational absence of an assigned D/CNPC will the local City/Municipal Nutrition Action Officer (NAO) step in to assume these training and supervision responsibilities.', '["District/City Nutrition Program Coordinator","City/Municipal Nutrition Action Officer","Provincial Nutrition Action Officer","Regional Nutrition Program Coordinator"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:14.150Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:14.150Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:14.476Z"'::jsonb),
('anki-card-1755049517865-54', 'anki-deck-1783608929173-1790433142619-teu0e', 'To prepare a potential BNS for deployment in his/her barangay, a BNS should undergo a training and  ___ days of practicum', '20 days', 'According to the National Nutrition Council (NNC) implementing guidelines under Presidential Decree No. 1569, a potential Barangay Nutrition Scholar (BNS) must successfully complete a two-part basic training program before full field deployment:

1. Didactic Phase: A classroom-based instruction course (traditionally structured as a 5-day to 10-day basic course) covering core technical inputs on malnutrition, health, the First 1000 Days, and data tools.
2. Practicum Phase: A mandatory 20-day hands-on community practicum.

During the 20 days of field practice, the scholar learns to master community nutrition management tasks under direct supervision. This includes operating anthropometric equipment to weigh and measure preschoolers (Operation Timbang Plus), conducting localized family profiling interviews, building a community nutrition spot map, and formulating a customized Barangay Nutrition Action Plan (BNAP).', '["5 days","10 days","15 days","20 days"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:59:35.499Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:59:35.499Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:59:35.825Z"'::jsonb),
('anki-card-1755049443603-53', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which law targets addressing specific micronutrient deficiencies by mandatory fortification of staple food items such as rice with iron, wheat flour with Vit A and iron, refined sugar with Vit A and cooking oil with Vit A and voluntary fortification of other food items?', 'RA 8976', 'Republic Act 8976 (The Philippine Food Fortification Act of 2000) mandates the fortification of staple foods to address widespread micronutrient deficiencies (specifically Vitamin A, Iron, and Iodine). It explicitly requires the mandatory fortification of:
	• Rice with Iron
	• Wheat flour with Vitamin A and Iron
	• Refined sugar with Vitamin A
	• Cooking oil with Vitamin A

It also covers the voluntary fortification of processed food items through the National Nutrition Council (NNC)''s "Sangkap Pinoy" seal program.

• RA 8172: The ASIN Law (Act for Salt Iodization Nationwide), which mandates the iodization of all food-grade salt.
• RA 10028: The Expanded Breastfeeding Promotion Act of 2009.
• RA 7600: The Rooming-In and Breastfeeding Act of 1992.', '["RA 7600","RA 8172","RA 8976","RA 10028"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:22:45.842Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:22:45.842Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:22:46.168Z"'::jsonb),
('anki-card-1755049333558-52', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which law was enacted to contribute to the elimination of micronutrient malnutrition in the country, particularly iodine deficiency disorder, through the cost-effective preventive measure of salt-iodization?', 'RA 8172', '', '["RA 7600","RA 8172","RA 8976","RA 10028"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:45:44.046Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:45:44.046Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:45:44.370Z"'::jsonb),
('anki-card-1755049213945-50', 'anki-deck-1783608929173-1790433142619-teu0e', 'Who is the chair of Provincial Nutrition Committee?', 'Governor', 'At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:

• Provincial Level: Chaired by the Governor.
• City / Municipal Level: Chaired by the Mayor.
• Barangay Level: Chaired by the Barangay Captain (Punong Barangay).

The Provincial Nutrition Action Officer (PNAO) operates under the leadership of the Governor to handle the day-to-day operations, implementation, and coordination of the province''s nutrition programs.', '["Provincial Nutrition Action Officer","Barangay Captain","Mayor","Governor"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:44:30.687Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:44:30.687Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:44:30.687Z"'::jsonb),
('anki-card-1755049164082-49', 'anki-deck-1783608929173-1790433142619-teu0e', 'These are development projects that were tweaked to produce nutritional outcomes.', 'Nutrition-sensitive', '', '["Nutrition-related","Nutrition-sensitive","Nutrition-oriented","Nutrition-specific"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T17:11:56.989Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T17:11:56.989Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-14T17:11:57.166Z"'::jsonb),
('anki-card-1755048155762-31', 'anki-deck-1783608929173-1790433142619-teu0e', 'The average daily milk consumption of infants for the first 6 months.', '750 ml', 'Clinical research and lactation guidelines indicate that exclusively breastfed or formula-fed infants consume an average of 25 ounces of milk per day between the ages of 1 and 6 months.

• When converted directly using standard measurements, 25 ounces equals 750 mL (25 x 30 mL/oz).
• Some pediatric and nutritional textbooks round this daily estimate to approximately 720 mL (calculated via alternative factors, such as roughly 24 oz x 30 mL).

Because normal daily intake typically ranges from 570 mL to 900 mL (with an overall average baseline of 739–750 mL), either C or B represents the clinically accepted daily average volume before the introduction of solid foods.', '["200 ml","250 ml","720 ml","750 ml"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:19:11.660Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:19:11.660Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:19:11.979Z"'::jsonb),
('anki-card-1755049104167-48', 'anki-deck-1783608929173-1790433142619-teu0e', 'These are programs that address the immediate determinants of fetal and child nutrition and development.', 'Nutrition-specific', 'According to global health frameworks (such as The Lancet Maternal and Child Nutrition Series) and Philippine law (such as Republic Act 11148), interventions are categorized based on what causes of malnutrition they address:

• Nutrition-specific programs directly address the immediate determinants of fetal and child nutrition and development. These include factors like adequate food and nutrient intake, infant feeding and caregiving practices, and reducing the burden of infectious diseases. Examples include micronutrient supplementation, exclusive breastfeeding promotion, and the treatment of severe acute malnutrition.
• Nutrition-sensitive programs address the underlying determinants of malnutrition. These involve systemic sectors like agriculture, food security, social protection, clean water and sanitation (WASH), and female education.', '["Nutrition-related","Nutrition-sensitive","Nutrition-oriented","Nutrition-specific"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:06:25.619Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:06:25.619Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:06:25.945Z"'::jsonb),
('anki-card-1755049041921-47', 'anki-deck-1783608929173-1790433142619-teu0e', '___ is a specific and time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timeable.', 'Project', 'By standard administrative and project management definitions, a project is a temporary, specific, and time-bound endeavor. It possesses a clearly defined start and end date, sequential activities, and a dedicated budget allocated to produce a unique product, service, or result that fulfills a specific objective.

• Policy: A standing operational plan that serves as a broad, ongoing guideline for decision-making and employee behavior rather than a temporary set of tasks.
• Plan: The overarching blueprint or management process of setting broad organizational goals and mapping out how to achieve them.
• Program: A long-term, continuous framework that aggregates multiple individual projects under a shared theme or broader social goal, usually lacking a singular, short-term definitive timeline.', '["Policy","Plan","Program","Project"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:14:28.524Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:14:28.524Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:14:28.845Z"'::jsonb),
('anki-card-1755048979873-46', 'anki-deck-1783608929173-1790433142619-teu0e', '___ is a cluster of programs that is comprehensive, long-range in time frame, and includes defined goals, strategies, and guidelines for implementation.', 'Plan', 'According to the official Nutrition Program Management and community planning taxonomy, these structural terms are arranged in a specific hierarchy:

1. Plan: This is the highest level of the hierarchy. It refers to a comprehensive, long-range cluster of programs that contains overarching defined goals, strategies, and broad guidelines for implementation. A prime example is the Philippine Plan of Action for Nutrition (PPAN).
2. Program: This sits below a plan and is a set of interrelated projects that coordinates personnel, facilities, money, equipment, and supplies to accomplish a specific operational objective.
3. Project: This is a specific, time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timetable.
4. Policy: This serves as the broad, overarching legal or administrative instrument—the system of principles or rules—that guides subsequent development plans.', '["Policy","Plan","Program","Project"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T17:12:43.036Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T17:12:43.036Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T10:15:28.964Z"'::jsonb),
('anki-card-1755048911627-45', 'anki-deck-1783608929173-1790433142619-teu0e', 'The first Philippine food and nutrition plan was called ___?', 'Philippine Nutrition Program', 'In 1971, President Ferdinand Marcos Sr. issued Executive Order No. 285, authorizing the National Food and Agriculture Council (NFAC) to coordinate all nutrition activities.

This integrated nationwide operation was officially known as the Philippine Food and Nutrition Program (PFNP) or simply the Philippine Nutrition Program (PNP).

It served as the structural blueprint for national intervention before the creation of the National Nutrition Council (NNC) in 1974 and the later evolution of the framework into what we now call the Philippine Plan of Action for Nutrition (PPAN).

• Philippine Food and Nutrition Program (PFNP, 1971–1974): Before the formal creation of the council, the National Food and Agriculture Council (NFAC) coordinated the first four-year Philippine Food and Nutrition Program under Executive Order No. 285.
• Philippine Nutrition Program (PNP, 1974–1983): In 1974, Presidential Decree No. 491 established the National Nutrition Council (NNC), formally consolidating national nutrition activities into the Philippine Nutrition Program (PNP). It covered iterations such as PNP 1974–1977 and PNP 1978–1982.
• Food and Nutrition Plan / Philippine Food and Nutrition Plan (FNP / PFNP, 1984–1992): In the mid-1980s, the blueprint returned to a linked agriculture-and-nutrition scope, adopted as the Food and Nutrition Plan (1984–1987) and later updated under the post-1986 reorganized NNC (via Executive Order No. 234) as the Philippine Food and Nutrition Plan (1987–1992).
• Philippine Plan of Action for Nutrition (PPAN, 1993–Present): Following the global 1992 International Conference on Nutrition (ICN) in Rome, the Philippines aligned with international frameworks by adopting the title Philippine Plan of Action for Nutrition. 

While sometimes referenced alongside the medium-term planning cycles (e.g., MTPFNP/MTPPAN), the core official name of the plan series became PPAN, which has continued across successive medium-term cycles:
	• PPAN 1993–1998
	• PPAN 1999–2004
	• PPAN 2005–2010
	• PPAN 2011–2016
	• PPAN 2017–2022
	• PPAN 2023–2028', '["Food and Nutrition Plan","Philippine Food and Nutrition Plan","Philippine Nutrition Program","Philippine Plan of Action for Nutrition"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:21:41.907Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:21:41.907Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:21:42.228Z"'::jsonb),
('anki-card-1755049247445-51', 'anki-deck-1783608929173-1790433142619-teu0e', '___is the country''s highest policy-making and coordinating body on nutrition.', 'NNC', 'The National Nutrition Council (NNC) is officially recognized by law as the Philippines'' highest policy-making and coordinating body on nutrition.

It was originally created under Presidential Decree No. 491 (The Nutrition Act of the Philippines) in 1974 and is an attached agency of the Department of Health (DOH). The NNC is responsible for orchestrating multi-sectoral strategies like the Philippine Plan of Action for Nutrition (PPAN) to eliminate hunger and malnutrition nationwide.

• NEDA (National Economic and Development Authority): The country''s premier social and economic development planning and policy coordinating body.
• NFP (Nutrition Foundation of the Philippines): A non-government, non-profit organization dedicated to promoting nutritional wellness.
• NCP (Nutrition Center of the Philippines): A private foundation that develops programmatic interventions and specialized nutritional products.', '["NCP","NNC","NFP","NEDA"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:57:24.751Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:57:24.751Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:57:25.029Z"'::jsonb),
('anki-card-1755048848112-44', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which province is a priority area in the PPAN 2023-2028?', 'Basilan', 'The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.

Basilan is officially classified as a high-priority province, ranking 9th overall nationwide on the target list for intensive nutrition interventions and financial support.

The Top 10 highest priority provinces targeted for intensive, multi-sectoral nutrition interventions are:
1. Leyte
2. Sulu
3. Negros Occidental
4. Negros Oriental
5. Samar
6. Lanao del Norte
7. Masbate
8. Palawan
9. Basilan
10. Cebu

Key Broad Facts on the 34 Priority Areas:
• The Rest of the Top 16: Immediately following the top ten are Camarines Sur, Quezon, Zamboanga del Norte, Zamboanga del Sur, Maguindanao, and Bukidnon.
• Convergent Strategy: Government programs like the Tutok Kainan Dietary Supplementation Program prioritize these specific locations to provide nutritional support during the critical First 1,000 Days of child development.', '["Batangas","Basilan","Batanes","Benguet"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:13:32.270Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:13:32.270Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:13:32.589Z"'::jsonb),
('anki-card-1755048794899-43', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which is an example of non-verbal communication?', 'Tone of voice', 'Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying "I''m fine" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.', '["Tone of voice","Maps","Traffic signals","Reports"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:29:07.332Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:29:07.332Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:29:07.332Z"'::jsonb),
('anki-card-1755048754384-42', 'anki-deck-1783608929173-1790433142619-teu0e', 'What is the first step in conducting a training?', 'Needs assessment', 'In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.

The Training Process Order:

1. Needs assessment (Identify the gaps)
2. Identification of training objectives (Define what success looks like based on the gaps)
3. Preparation for training design / Planning (Outline methods, timelines, and content)
4. Implementation (Conducting the training)
5. Evaluation (Measuring the training''s effectiveness)', '["Planning for the training","Preparation for training design","Needs assessment","Identification of training objectives"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:08:19.321Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:08:19.321Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:08:19.644Z"'::jsonb),
('anki-card-1755048709234-41', 'anki-deck-1783608929173-1790433142619-teu0e', 'A nutrition education method that includes bench conferences.', 'Group discussion', 'In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.

A bench conference occurs when a health worker or nutritionist gathers a small cluster of mothers, caregivers, or patients who are sitting together on a bench waiting for their turn in a rural health unit or clinic.

• Rather than structured one-on-one counseling behind closed doors, the educator utilizes this shared waiting space to initiate a small group interaction.
• Because it encourages the individuals sitting together to exchange ideas, ask questions, and learn from each other''s experiences under the guidance of the facilitator, it is classified academically under Group discussion methods.', '["Nutrition counseling","Group discussion","Mass media","Social marketing"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:39.468Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:39.468Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:39.779Z"'::jsonb),
('anki-card-1755048660438-40', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which communication model is to support action?', 'Diffusion of Innovation', 'Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.

It focuses heavily on how information is packaged and delivered via specific communication channels over time to move groups from initial awareness directly into concrete adoption and action.

• Social cognitive theory / Self-efficacy model: These focus primarily on the cognitive determinants of a behavior—specifically how an individual''s confidence in their own ability (self-efficacy) and their social environment influence their personal behavior.
• Transtheoretical model: This is a stage theory that maps out an individual''s motivational readiness to change behavior (from Precontemplation to Maintenance) rather than functioning primarily as an operational communication model to drive group action.', '["Diffusion of Innovation","Transtheoretical model","Self-efficacy model","Social cognitive theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:31:19.582Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:31:19.582Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:31:19.897Z"'::jsonb),
('anki-card-1755048610789-39', 'anki-deck-1783608929173-1790433142619-teu0e', 'In promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in Zumba session because they are fond of dancing.', 'Self-determination Theory', 'Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already "fond of dancing" and "eager to participate," they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.

• Precaution Adoption Process Model (PAPM): This is a stage theory best used for tracking how people move from being completely unaware of a health hazard to taking a precautionary action. It does not focus on enjoyable physical activities.
• Health Belief Model (HBM): This model relies on a person’s perception of a health threat (susceptibility/severity) and balancing the benefits against the barriers of a preventative action. It is most useful for things like screening or vaccination compliance, not lifestyle activities done out of pure enjoyment.
• Theory of Planned Behavior (TPB): This theory posits that behavior is driven by intentions, which are shaped by attitudes, social pressures (subjective norms), and perceived behavioral control. It would be the choice if the question emphasized that the community members are joining because their friends or family think it is a good idea.', '["Precaution Adoption Process Model","Health Belief Model","Theory of Planned Behavior","Self-determination Theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:33.607Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:33.607Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:33.935Z"'::jsonb),
('anki-card-1755050737774-69', 'anki-deck-1783608929173-1790433142619-teu0e', 'Food availability at the national level is not enough to provide food security for all households. Moreover, food security at the national and household level does not automatically result to good nutritional status of an individual.', 'Both statements are true', 'Statement 1 is true: Food availability at the national level (e.g., high national agricultural yields or food imports) speaks only to supply. It does not ensure food security for all households because of barriers to food access (such as low purchasing power, poverty, or poor market distribution systems).

Statement 2 is true: Even if a household is fully food secure and has plenty of food on the table, it does not guarantee that every individual in that house will achieve an optimal nutritional status. This is because individual nutritional status depends heavily on food utilization (how the body absorbs nutrients, which can be ruined by infections or illness), intra-household food distribution (e.g., gender or age disparities in who eats first), and caregiving practices.', '["Only the first statement is true","Only the second statement is true","Both statements are true","Both statements are false"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:49:40.551Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:49:40.551Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:49:40.889Z"'::jsonb),
('anki-card-1755050801439-70', 'anki-deck-1783608929173-1790433142619-teu0e', 'Understanding the ecology of food and nutrition helps in the identification of the root causes of malnutrition problem. It can also help identifying appropriate solutions.', 'Both statements are true', 'The first statement is true: The "ecology of food and nutrition" refers to the interaction between humans and the environmental, socio-economic, cultural, and political factors that dictate food availability, access, and biological utilization. Understanding this web helps investigators trace how systemic basic causes (like climate or policy) trickle down to underlying causes (like poor sanitation) and immediate causes (like inadequate dietary intake).

The second statement is true: By mapping out these exact ecological pathways, program planners can easily identify where a system is failing and design appropriate, targeted solutions—such as pairing nutrition-specific medical interventions with long-term, nutrition-sensitive agricultural or water security reforms.', '["Only the first statement is true","Only the second statement is true","Both statements are true","Both statements are false"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:16:41.634Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:16:41.634Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:16:41.951Z"'::jsonb),
('anki-card-1755050858702-71', 'anki-deck-1783608929173-1790433142619-teu0e', 'It is a condition in which people do not get enough food to provide nutrients for the body.', 'Hunger', 'In public health and food security frameworks, hunger is defined as an individual-level physiological condition where a person does not have access to enough food to provide the essential nutrients and dietary energy their body needs to function normally.

• Food and nutrition security: This is a comprehensive, positive state where all people at all times have physical, social, and economic access to sufficient, safe, and nutritious food to meet their dietary needs for an active and healthy life.
• Malaise: This is a general, non-specific medical term describing a vague feeling of bodily discomfort, illness, uneasiness, or lack of energy.
• Food security: This focuses primarily on the broad availability, access, and stability of food supplies at the household or community level, rather than the specific physical condition of lacking food nutrients.', '["Food and nutrition security","Food security","Hunger","Malaise"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:54:36.296Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:54:36.296Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:54:36.614Z"'::jsonb),
('anki-card-1755050907565-72', 'anki-deck-1783608929173-1790433142619-teu0e', 'All of the following are possible causes of transitory food insecurity except:', 'Lack of food storage', 'Transitory food insecurity is defined as a short-term, temporary, or sudden drop in the ability to produce or access enough food. It is typically triggered by unpredictable external shocks.

Droughts and floods are classic examples of acute environmental shocks that cause immediate, temporary food shortages. The lean season represents a cyclical, temporary phase between planting and harvesting where food supplies naturally drop for a limited period.

A lack of food storage, on the other hand, is a structural and systemic infrastructural deficiency. Because it is a permanent condition deeply embedded in a region''s agricultural infrastructure, it serves as a core driver of chronic food insecurity rather than a temporary or passing shock.', '["Lean season","Drought","Floods","Lack of food storage"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:53:01.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:53:01.342Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:53:01.621Z"'::jsonb),
('anki-card-1755051623566-74', 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following provides information on annual food production, distribution of food within the country, and imports and exports?', 'Food balance sheets', 'A Food Balance Sheet (FBS) is a comprehensive macro-level statistical report compiled annually (often by national agencies like the Philippine Statistics Authority and globally by the Food and Agriculture Organization) to track a country''s total food supply and utilization over a specific timeframe.

It specifically synthesizes three critical dimensions of data:
1. Annual Food Production: The total quantity of food commodities cultivated domestically.
2. Imports and Exports: The flow of food moving into and out of the country''s borders to calculate net available supply.
3. Distribution/Utilization: How the total available food is split within the country across human consumption, livestock feed, seed use, manufacturing, and structural waste.

• Commercial market databases: These track private consumer buying trends, brand performance, and retail sales, rather than integrated national agricultural and border trade balances.
• Food records: This is an individual-level dietary assessment method where a single person logs their personal daily intake, which tells you nothing about nationwide trade or agricultural production.', '["Food balance sheets","Food records","Commercial market databases","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:05:43.163Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:05:43.163Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:05:43.478Z"'::jsonb),
('anki-card-1754282064782-10', 'anki-deck-1783608953857-1790433145942-e1oub', 'The 3Rs are principle of good science designed by scientist to improve animal welfare and scientific accuracy. Which of the following means finding ways of making animals'' lives better in labs, this can include toys for animals or better training for technicians.', 'Refinement', 'Refinement - Minimize animal pain, suffering, and distress.

• Reduction - Use the minimum number of animals necessary.
• Replacement - Use non-animal methods where possible.
• Recognition - random word which start with letter R.', '["Reduction","Replacement","Refinement","Recognition"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:45:57.549Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:45:57.549Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:45:57.549Z"'::jsonb),
('anki-card-1754282189492-11', 'anki-deck-1783608953857-1790433145942-e1oub', 'It is the practice of analyzing describing a complex phenomenon in terms of phenomena that are held to represent a single or more fundamental level, especially when this is a said to provide a sufficient explanation', 'Reductionism in research', 'Reductionism is a philosophical and scientific approach that breaks down complex systems or phenomena into their smaller, simpler, or more fundamental components. In research (especially in fields like nutritional biochemistry or physiology), it assumes that understanding these isolated, individual parts provides a sufficient explanation for the behavior of the entire system.

• Scientific Method: The systematic, step-by-step process of observing, forming a hypothesis, experimenting, and drawing conclusions to gather knowledge.
• Research Method: The specific tools, techniques, or procedures used to collect and analyze data (e.g., surveys, randomized controlled trials, or double-blind studies).
• Research Design: The overall structural blueprint or strategy chosen to integrate the different components of a study in a coherent and logical way (e.g., cross-sectional, cohort, or experimental design).', '["Research method","Reductionism in research","Scientific method","Research design"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:29:47.414Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:29:47.414Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:29:47.612Z"'::jsonb),
('anki-card-1754282328051-12', 'anki-deck-1783608953857-1790433145942-e1oub', 'What is the over-all goal of nutritional epidemiology?', 'To contribute to the prevention of disease and the improvement of public health', 'The correct answer is to contribute to the prevention of disease and the improvement of public health, which represents the ultimate purpose (goal). Choices A, B, and D are all legitimate specific aims or objectives that serve this larger goal.

“Goal" (why it exists)
"Objectives" (what it specifically does to get there)', '["To monitor the food consumption, nutrient intake and nutritional status of a population","To assess  the strength of diet-disease associations","To contribute to the prevention of disease and the improvement of public health","To generate new hypothesis about diet and disease"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:21:41.118Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:21:41.118Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:21:41.118Z"'::jsonb),
('anki-card-1754282471562-13', 'anki-deck-1783608953857-1790433145942-e1oub', 'What study design will you use to determine the relation of wealth status (rich, middle class) and fruit intake (in grams) per day.', 'Cross-sectional', 'Cross-sectional is the most applicable for determining the current, simple relationship between an exposure (wealth status) and outcome (fruit intake).

• Cohort - aim to determine the cause-and-effect relationship between an exposure and the development of a disease/outcome over a long period of time
• Case series - aims to provide a detailed description of a small number of patients (case series) or a single patient (case report) with an unusual or novel condition
• Case-control - aims to determine the past exposures that led to a rare disease/outcome', '["Cross-sectional","Cohort","Case series","Case control"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:16:09.664Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:16:09.664Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:16:10.010Z"'::jsonb),
('anki-card-1754282694468-14', 'anki-deck-1783608953857-1790433145942-e1oub', 'What statistical test will you use in the study particularly if the data is normally distributed?

Study: to determine the relation of wealth status (rich, middle class) and fruit intake (in grams) per day', 'T-test', 'T-test - parametric test used to compare the means of exactly two groups. Since there are only two wealth statuses to compare fruit intake then this is the correct answer.

• ANOVA - parametric test used to compare the means of three or more groups.
• Chi-square test - used for categorical data
• Mann-Whitney - is a non-parametric test', '["T-test","ANOVA","Chi-square test","Mann-Whitney"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:59:38.426Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:59:38.426Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:59:38.426Z"'::jsonb),
('anki-card-1754282976955-15', 'anki-deck-1783608953857-1790433145942-e1oub', 'Refers to a phenomenon which is thought to occur when people observed during a research study temporarily change their behavior or performance', 'Hawthorne', 'Hawthorne effect occurs when participants change their behavior simply because they know they are being observed or studied.

• Ecological fallacy - Mistakenly applying conclusions drawn from group-level data (e.g., states, countries) to individuals within those groups.
• Systematic error - Consistent, non-random error that always biases measurements in the same direction (e.g., a poorly calibrated scale).
• Placebo effect - A positive or therapeutic effect that results from a participant''s expectation or belief in the treatment, rather than the treatment''s actual physiological mechanism.', '["Ecological facally","Systematic error","Hawthorne","Placebo effect"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:51:53.394Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:51:53.394Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T07:51:53.394Z"'::jsonb),
('anki-card-1754283151564-16', 'anki-deck-1783608953857-1790433145942-e1oub', 'This means making up data, experiments, or other significant information in proposing, conducting, or reporting research', 'Fabrication', 'Fabrication is the act of making up data or results entirely and recording or reporting them as true.

• Falsification involves manipulating research materials, equipment, or processes, or changing/omitting data so that the research record does not accurately represent the actual work.
• Plagiarism is using another person''s ideas, processes, results, or words without giving them proper credit.', '["Falsification","Fabrication","Plagiarism","Intentional misconduct"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:17:18.282Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:17:18.282Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:17:18.282Z"'::jsonb),
('anki-card-1754281705048-8', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which type of objective is the most applicable if your study uses methodology research design?', 'To evaluate measuring instrument', 'In research methodology textbooks, a methodological research design (sometimes called methodological research) does not focus on investigating a substantive medical or social phenomenon itself. Instead, its primary purpose is the controlled development, testing, and validation of the research tools themselves.

The Goal of Methodological Design is to target the validation or evaluation of a measuring instrument, scale, survey tool, or clinical questionnaire to ensure it possesses high validity and reliability before it is deployed in field studies.

	• To explore relationship: Best fits a correlational or explanatory research design.
	• To make comparison between groups: Best fits an experimental, quasi-experimental, or comparative research design.
	• To describe population or certain phenomena: Best fits a classic descriptive or observational research design.', '["To evaluate measuring instrument","To describe population or certain phenomena","To explore relationship","To make comparison between groups"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:41:08.151Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:41:08.151Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:41:08.332Z"'::jsonb),
('anki-card-1754283248926-17', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following is not a nutritional exposure?', 'IQ score', 'IQ score functions as an outcome (dependent variable) not an exposure (independent variable/risk factor) in most nutrition research contexts. Physical activity, coffee intake, and reading food labels are all behaviors or exposures that can be investigated as potential predictors of a nutrition-related outcome.

Exposure is the cause or predictor (the independent variable or risk factor), which is the factor being investigated for its effect. Outcome is the effect or result (the dependent variable), which is the disease, event, or condition being studied.', '["Physical activity","Coffee intake","IQ score","Reading food labels"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:38:31.860Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:38:31.860Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:38:31.860Z"'::jsonb),
('anki-card-1754283503615-18', 'anki-deck-1783608953857-1790433145942-e1oub', 'Interpret the results of correlation between abdominal circumstances and HDL cholesterol level: r = 0.16, P = 0.002.', 'There is no correlation between abdominal circumference and HDL cholesterol level, and it is unlikely that our result is caused by play of chance', 'The correct interpretation is that there is essentially no meaningful correlation between abdominal circumference and HDL cholesterol, and the small effect that was found is unlikely to be due to chance.

r = 0.16 (Weak Positive Correlation). The value is close to zero, meaning the linear association is minor. The positive sign means that as abdominal circumference increases, HDL cholesterol tends to slightly increase as well.

p= 0.002 (Statistically Significant). Since p<0.05 (the common threshold), we reject the null hypothesis. The observed correlation of 0.16 is highly unlikely to have occurred by random chance.', '["There is a significant correlation between abdominal circumference and HDL cholesterol level","There is no correlation between abdominal circumference and HDL cholesterol level, and it is likely that our result is caused by play of chance","Abdominal circumference measurement may predict HDL cholesterol level","There is no correlation between abdominal circumference and HDL cholesterol level, and it is unlikely that our result is caused by play of chance"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:33:08.657Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:33:08.657Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:33:08.657Z"'::jsonb),
('anki-card-1754283703972-19', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following is false?', 'The tests of significance enable the researcher to know for sure that the researcher''s analysis correct', 'In biostatistics and research methodology, statistical tests of significance can never provide absolute certainty or prove that an analysis or hypothesis is "correct" for sure.
• Hypothesis testing operates entirely on probability, measuring the strength of evidence against a null hypothesis.
• A statistically significant result (e.g., p < 0.05) simply means that the observed data or difference is highly unlikely to have occurred by pure random chance under the assumption that the null hypothesis is true. It always leaves open a margin of uncertainty.

• Option A is TRUE: Inferential statistics deal purely with mathematical probability, not certainty. There is always a non-zero risk that your conclusions are false positives or false negatives.
• Option B is TRUE: There is an inverse mathematical trade-off between the two types of errors. If a researcher strictly lowers the significance level (α, the probability of a Type I error) from 0.05 to 0.01, the standard for rejecting the null hypothesis becomes much harder to meet. This automatically increases the probability of committing a Type II error (β, missing a real effect).
• Option C is TRUE: Parametric tests (like the t-test or ANOVA) carry strict assumptions about data structure, requiring variables to be continuous and measured on an interval or ratio scale, alongside approximately normal distributions. Non-parametric tests are used for nominal or ordinal data.', '["The tests of significance deal with probability not certainty","The tests of significance enable the researcher to know for sure that the researcher''s analysis correct","Generally speaking, a parametic test of significance should be used when the data represent interval or ratio scale","As a researcher decreases the chances of committing a Type I error, the researcher increases the probability of committing a Type II error"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:09:40.532Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:09:40.532Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T14:09:40.532Z"'::jsonb),
('anki-card-1754283816051-20', 'anki-deck-1783608953857-1790433145942-e1oub', 'The first president of the Dietetic Association of the Philippines:', 'Presentation Perez', 'Presentation Perez - first president of the Dietetic Association of the Philippines.

• Preciosa Irma Florentin - established the first dietetic internship program in the Philippines; the first hospital-based Nutrition Clinic; and the first metabolic unit at the Philippine General Hospital (PGH) in 1952.
• Adelisa Ramos - first RND head of DOH Nutrition Service
• Tecla San Andres - first woman in the Philippines to top the Bar Examinations for law graduates', '["Presentation Perez","Preciosa Irma Florentin","Adelisa Ramos","Tecla San Andres"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:11:31.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:11:31.342Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T14:11:31.532Z"'::jsonb),
('anki-card-1754283970343-21', 'anki-deck-1783608953857-1790433145942-e1oub', 'A function of public health nutritionist which focuses on assisting the community to assesses the program’s success or failure by evaluating program activities.', 'Program Evaluator', 'Program Evaluator since this function specifically involves to evaluate whether a program met its objectives by systematically assessing its activities and results. 

• Program Assessor focuses on measurement and is a more common term in educational settings. 
• Program Organizer focuses on assembling resources and stakeholders before or during implementation. 
• Program Implementer focuses on carrying out planned activities, not evaluating them afterward.', '["Program Assessor","Program Organizer","Program Implementer","Program Evaluator"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:42:09.435Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:42:09.435Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:42:09.435Z"'::jsonb),
('anki-card-1754284110703-22', 'anki-deck-1783608953857-1790433145942-e1oub', 'It refers to a set of processes and conditions by which food is produced, processed, and stored, marketed and distributed, and prepared and consumed for proper nutrition and good.', 'Food and Nutrition system', '• Food Security - the state of having reliable access to sufficient, affordable, nutritious food.
• Food Path - the entire set of activities from farm to fork (production, processing, distribution, consumption, and waste).
• Ecology of Food and Nutrition - the complex relationship between humans, food, and the natural, social, and cultural environment.', '["Food security","Food Path","Food and Nutrition system","Ecology of Food and Nutrition"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:39:59.046Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:39:59.046Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T07:39:59.046Z"'::jsonb),
('anki-card-1754284195300-23', 'anki-deck-1783608953857-1790433145942-e1oub', 'It is an art and science of promoting health thru an organized effort of improving the food and nutrition system.', 'Public Health Nutrition', 'Public Health Nutrition – narrower definition; focused on food, diet, and nutrition issues within the population context.

• Community Nutrition – narrowest definition; focused on the local implementation and tailored needs of a smaller geographic or demographic area.
• Public Health – broadest definition; encompasses all health issues (infectious disease, injury, environment, etc.).', '["Community Nutrition","Public Health Nutrition","Public Health","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:41:04.780Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:41:04.780Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:41:04.780Z"'::jsonb),
('anki-card-1754291432368-94', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following conditions accounts for the most non-communicable disease worldwide?', 'Cardiovascular disease', 'According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.

Among these conditions, cardiovascular diseases (CVDs) are the absolute leading cause of mortality and morbidity globally:
• Cardiovascular Diseases (CVDs): Account for the vast majority of NCD deaths, causing roughly 17.9 to 19 million deaths annually (primarily driven by ischemic heart disease and strokes).
• Cancers: Follow as the second largest group, accounting for around 9 to 10 million deaths each year.
• Chronic Respiratory Diseases: Account for approximately 3.9 to 4 million annual deaths.
• Diabetes: Accounts for roughly 1.6 to 2 million deaths annually.

Together, these four groups make up over 80% of all premature NCD-related mortality worldwide.', '["Breast cancer","Cardiovascular disease","Diabetes","Respiratory disease"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:45:41.351Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:45:41.351Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:45:41.351Z"'::jsonb),
('anki-card-1754284281262-24', 'anki-deck-1783608953857-1790433145942-e1oub', 'A function of public health nutritionist which focuses on assisting the community in identification of their needs and help them realizing their nutrition and nutrition-related problems.', 'Assessor', 'Assessor centers on assessment by helping the community identify and recognize its own nutrition and nutrition-related problems as a first step in program planning. 

• Organizer focuses on mobilizing resources and stakeholder. 
• Implementer focuses on carrying out planned interventions. 
• Educator focuses on transmitting knowledge and skills.', '["Assessor","Organizer","Implementer","Educator"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:31:51.852Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:31:51.852Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:31:52.064Z"'::jsonb),
('anki-card-1754284408557-25', 'anki-deck-1783608953857-1790433145942-e1oub', 'The main role of public health nutritionist is ____', 'Nutrition program planner and manager', 'While a Registered Dietitian-Nutritionist (RDN) can work across various fields, public health nutrition focuses specifically on populations and communities rather than individual patients.

The primary responsibility of a public health nutritionist is macro-level intervention. This includes assessing the nutritional needs of a community, designing health promotion programs, securing resources, and managing large-scale implementation to reduce disease risks across a population.', '["Nutrition program planner and manager","Diet counselor","Foodservice manager","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:48:45.185Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:48:45.185Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T14:48:45.185Z"'::jsonb),
('anki-card-1754284605583-26', 'anki-deck-1783608953857-1790433145942-e1oub', 'A function of public health nutritionist which focuses on financial management and organizing the personnel who are involve in nutrition program implementation.', 'Program Administrator', 'Program administrator manages the daily operations.

• Program planner - designs the program strategy
• Program organizer - assembles necessary resources
• Program implementer - delivers the program activities', '["Program planner","Program Organizer","Program Implementer","Program Administrator"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:05:56.025Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:05:56.025Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:05:56.210Z"'::jsonb),
('anki-card-1754284704226-27', 'anki-deck-1783608953857-1790433145942-e1oub', 'When was the first nutrition survey released?', '1910', 'The first nutrition survey results were released in 1910 during the American Regime, which primarily focused on investigating beriberi and its links to eating polished white rice.', '["1910","1920","1930","1940"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:32:58.823Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:32:58.823Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:32:59.030Z"'::jsonb),
('anki-card-1754284794655-28', 'anki-deck-1783608953857-1790433145942-e1oub', 'Who was the first secretary of Department of Health and Welfare?', 'Dr. Jose Fabella', 'Dr. Jose Fabella is a Filipino physician and public health leader, known as the "Father of Public Health" in the Philippines. He served as the first Secretary of Health.

• Dr. Francisco O. Santos - A Filipino chemist and agricultural scientist, recognized as the "Father of Human Nutrition" in the Philippines.
• Dr. Juan Salcedo, Jr. - A prominent Filipino physician, researcher, and public health advocate; he led early efforts against Vitamin B1 deficiency and served as Secretary of Health and Chairman of the National Science Development Board.
• Dr. Coronado R. Pascual - A Filipino nutritionist and physician who served as the Director of the Food and Nutrition Research Institute (FNRI) formerly NI and was a key figure in Philippine national nutrition planning.', '["Dr. Jose Fabella","Dr. Francisco O. Santos","Dr. Juan Salcedo Jr.","Dr. Coronado R. Pascual"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:27:51.688Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:27:51.688Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:27:51.889Z"'::jsonb),
('anki-card-1754284940883-29', 'anki-deck-1783608953857-1790433145942-e1oub', 'Who was the first president of Philippine Association of Nutrition?', 'Dr. Francisco O. Santos', 'Dr. Francisco O. Santos is a Filipino chemist and agricultural scientist, recognized as the "Father of Human Nutrition" in the Philippines.

• Dr. Jose Fabella - A Filipino physician and public health leader, known as the "Father of Public Health" in the Philippines. He served as the first Secretary of Health.
• Dr. Juan Salcedo, Jr. - A prominent Filipino physician, researcher, and public health advocate; he led early efforts against Vitamin B1 deficiency and served as Secretary of Health and Chairman of the National Science Development Board.
• Dr. Coronado R. Pascual - A Filipino nutritionist and physician who served as the Director of the Food and Nutrition Research Institute (FNRI) formerly NI and was a key figure in Philippine national nutrition planning.', '["Dr. Jose Fabella","Dr. Francisco O. Santos","Dr. Juan Salcedo Jr.","Dr. Coronado R. Pascual"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:06:10.273Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:06:10.273Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:06:10.448Z"'::jsonb),
('anki-card-1754285118559-30', 'anki-deck-1783608953857-1790433145942-e1oub', 'The primary building substance of cell is:', 'Protein', 'Protein - structure & function: acts as enzymes to catalyze reactions, builds structural components, and performs transport/movement.

• Water: for solvent & medium: provides the environment for all chemical reactions (cytoplasm) and acts as a transport mechanism.
• Fats – for boundary & energy storage: primary component of the cell membrane (boundary) and long-term energy reserve.
• Carbohydrates – for immediate energy & recognition: the cell''s primary and immediate energy source, also used for cell-to-cell communication.', '["Water","Protein","Fat","Carbohydrates"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:37:40.860Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:37:40.860Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T07:37:40.860Z"'::jsonb),
('anki-card-1754285961769-38', 'anki-deck-1783608953857-1790433145942-e1oub', 'A hormone secreted by the placenta that stimulates the secretion of estrogen and progesterone.', 'Chorionic gonadotropin', '• Luteinizing hormone - Anterior Pituitary Gland - triggers ovulation in women and stimulates testosterone production in men.
• Placental lactogen - modifies the mother''s metabolism to facilitate energy supply to the fetus; also stimulates mammary gland development.
• Follicle-stimulating hormone - Anterior Pituitary Gland - stimulates the growth of ovarian follicles in women and sperm production in men.', '["Luteinizing hormone","Chorionic gonadotropin","Placental lactogen","Follicle-stimulating hormone"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:31:19.837Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:31:19.837Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:31:20.039Z"'::jsonb),
('anki-card-1754280732361-2', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which one of the following statements is incorrect?', 'According to Pinggang Pinoy, meat, fish, and alternatives should comprise one-third of the plate', 'Answer should be 1/6 ~ 17%.', '["According to Pinggang Pinoy, half of our plate should be include fruits and vegetable","According to Pinggang Pinoy, meat, fish, and alternatives should comprise one-third of the plate","The statement \"Eat lots of fruits and vegetables\" is a food-based dietary guideline","The statement \"Eat less sodium-no more than 2g/day\" is not food-based dietary guideline"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-27T08:34:26.376Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-24T08:34:26.376Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:34:26.376Z"'::jsonb),
('anki-card-1754285174821-31', 'anki-deck-1783608953857-1790433145942-e1oub', 'The lowest level of structural organization of the living human body', 'Chemical', 'To understand the structural hierarchy of the human body, scientists view it in six increasing levels of complexity, from smallest to largest:

1. Chemical Level (Lowest): This includes atoms (such as carbon, hydrogen, and oxygen) and molecules (like water, DNA, and glucose) that combine to form the basic building blocks of life.
2. Cellular Level: Molecules combine to form cells, which are the basic structural and functional units of an organism.
3. Tissue Level: Groups of similar cells join together to perform a highly specific function (e.g., epithelial, connective, muscular, or nervous tissue).
4. Organ Level: Different types of tissues join together to form recognizable structures with specific shapes and functions (e.g., the stomach, heart, or liver).
5. System Level: Related organs connect to form an organ system with a common function (e.g., the digestive or cardiovascular system).
6. Organismal Level (Highest): All structural parts of the human body working together to create a single, living individual.', '["Cellular","Tissue","Organ","Chemical"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:55:08.925Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:55:08.925Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:55:09.101Z"'::jsonb),
('anki-card-1754285284600-32', 'anki-deck-1783608953857-1790433145942-e1oub', 'A cell region acts as a selective barrier to the movement of substances into and out of the cell.', 'Plasma membrane', 'Plasma membrane - outer boundary; controls what enters and exits the cell

• Nucleus - control center; stores DNA/Genetic Instructions.
• Cytoplasm - jelly-like fluid; holds organelles; site of metabolism
• Ribosome - protein factory; synthesizes proteins from mRNA', '["Nucleus","Cytoplasm","Plasma membrane","Ribosome"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:42:29.447Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:42:29.447Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:42:29.447Z"'::jsonb),
('anki-card-1754285374496-33', 'anki-deck-1783608953857-1790433145942-e1oub', 'Age period characterized by rapid differentiation and establishment of system and organs:', 'Embryonic', 'The correct answer is embryonic period during which the basic body systems and organs rapidly differentiate and form (roughly weeks 3-8 of gestation). 

The early fetal period and late fetal period are characterized more by growth and maturation of already-formed structures rather than initial organ formation. 

The neonatal period refers to the first 28 days after birth, well after organogenesis is complete.', '["Embryonic","Early fetal","Late fetal","Neonatal"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:40:49.420Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:40:49.420Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:40:49.617Z"'::jsonb),
('anki-card-1754285497906-34', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which is TRUE about cell growth?', 'Hyperplasia is characterized by the increase in number of cells through cell division', 'Hyperplasia is characterized by an increase in the number of cells through cell division. Choice B is false because it describes hypertrophy is actually the increase in the SIZE of existing cells, not their number.', '["Hyperplasia is characterized by the increase in number of cells through cell division","Hypertrophy is characterized by the increase in number of cells through cell division","A and B are both TRUE","A and B are both FALSE"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:08:18.635Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:08:18.635Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:08:18.635Z"'::jsonb),
('anki-card-1754285595420-35', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which is TRUE about the purpose of the menstrual cycle?', 'A and B are both TRUE', 'The menstrual cycle serves to develop and release a mature ovum (ovulation) and to prepare the uterine lining (endometrium) for potential implantation.', '["To develop and release a mature ovum","To prepare the uterus lining","A and B are both TRUE","A and B are both FALSE"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:24:14.032Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:24:14.032Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:24:14.032Z"'::jsonb),
('anki-card-1754285719099-36', 'anki-deck-1783608953857-1790433145942-e1oub', 'In the female hormonal system, the source of luteinizing hormone-releasing hormone or LHRH is:', 'Hypothalamus', 'Luteinizing Hormone-Releasing Hormone (LHRH) is simply an older, synonymous name for Gonadotropin-Releasing Hormone (GnRH).

Any hormone that has the phrase "releasing hormone" in its name (such as LHRH/GnRH, TRH, CRH, and GHRH) is manufactured and secreted by the specialized nerve cells of the Hypothalamus.

The hypothalamus secretes LHRH into tiny blood vessels that travel directly to the Anterior Pituitary Gland. There, it triggers the pituitary gland to produce and release Luteinizing Hormone (LH) and Follicle-Stimulating Hormone (FSH) into general blood circulation to act on the ovaries.

• Anterior pituitary gland - GH, TSH, ACTH, FSH, LH, PRL
• Posterior pituitary gland - ADH, OT
• Ovary - estrogen, progesterone, inhibin, androgen', '["Hypothalamus","Anterior pituitary gland","Posterior pituitary gland","Ovary"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:44:05.232Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:44:05.232Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-29T08:44:05.423Z"'::jsonb),
('anki-card-1754285836026-37', 'anki-deck-1783608953857-1790433145942-e1oub', 'The placenta is formed for different purposes EXCEPT:', 'For production of nutrients and vitamins', 'The placenta serves as the physiological lifeline between the mother and the fetus, acting temporarily as the fetus''s lungs, kidneys, gut, and liver.

• Storage: The placenta dynamically stores nutrients like glycogen, iron, and specific fat-soluble vitamins during early pregnancy to ensure a steady, regulated supply is available for the developing fetus.
• Waste Removal: It efficiently clears fetal metabolic waste products (such as carbon dioxide, urea, and uric acid) from the fetal bloodstream and transfers them into the maternal blood for excretion.
• Supply Line: Its paramount baseline function is to transfer oxygen, water, glucose, amino acids, and essential vitamins from the maternal bloodstream into fetal circulation via the umbilical cord.

The placenta cannot synthesize or manufacture nutrients and vitamins from scratch. It relies entirely on drawing these essential substances from the mother''s circulation. It does produce hormones (such as hCG, progesterone, and estrogen), but not nutrients or vitamins.', '["To supply the fetus with nutrients and oxygen","For production of nutrients and vitamins","For storage of nutrients and vitamins","For removing of fetal waste products"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:39:22.668Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:39:22.668Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:39:22.850Z"'::jsonb),
('anki-card-1754280527235-1', 'anki-deck-1783608953857-1790433145942-e1oub', 'Based on the Acceptable Macronutrient Distribution Ranges (AMDR), energy from fat as a percentage of total energy for adults should be within the range?', '15-30%', 'The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.

Carbohydrate: 55-75%
Protein: 10-15%
Fat: 15-30%', '["<10%","10-20%","15-30%","35-50%"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-27T14:43:51.984Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-24T14:43:51.984Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T14:43:51.984Z"'::jsonb),
('anki-card-1754286048581-39', 'anki-deck-1783608953857-1790433145942-e1oub', 'The nutritional requirements are increased during pregnancy to:', 'A and B are both True', 'Increased nutrient needs during pregnancy serve to support the growing fetus and other maternal tissues (such as the placenta and expanded blood volume), as well as to build maternal reserves in preparation for delivery and the subsequent demands of lactation.', '["To meet the nutrient needs of the growth fetus, other maternal tissues","To build reserves in preparation of delivery and lactation","A and B are both True","A and B are both False"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:15:01.872Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:15:01.872Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:15:01.872Z"'::jsonb),
('anki-card-1754286153962-40', 'anki-deck-1783608953857-1790433145942-e1oub', 'Possible consequences of iodine deficiency during pregnancy:', 'Cretinism', 'While low birth weight, stillbirth, and miscarriage can all be caused or exacerbated by severe maternal iodine deficiency, Cretinism is the most definitive, classic textbook consequence specifically caused by fetal iodine deficiency and congenital hypothyroidism.

Cretinism is an irreversible condition characterized by severe mental retardation, deaf-mutism, short stature (dwarfism), and spastic diplegia. It is uniquely linked to profound maternal and fetal iodine deficiency during critical early periods of brain development.

While options A, B, and D are broader obstetric complications that can result from many different underlying medical and nutritional issues, cretinism stands out as the direct, hallmark clinical manifestation of severe iodine deficiency disorder (IDD) in a developing fetus.', '["Low birth weight","Stillbirth","Miscarriage","Cretinism"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:48:33.550Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:48:33.550Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:48:33.859Z"'::jsonb),
('anki-card-1754286249490-41', 'anki-deck-1783608953857-1790433145942-e1oub', 'The following are dietary management for morning sickness during pregnancy EXCEPT:', 'Citrus juice, water, milk coffee or tea if experiencing nausea', 'Citrus juice (high acidity), water (trigger the gag reflex), milk (aggravates nausea), coffee, or tea (can stimulate stomach acid secretion) if experiencing nausea.', '["Frequent small meals","Dry toast or crackers","Citrus juice, water, milk coffee or tea if experiencing nausea","Avoidance of foods with offensive odors"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:46:58.805Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:46:58.805Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:46:58.995Z"'::jsonb),
('anki-card-1754286303270-42', 'anki-deck-1783608953857-1790433145942-e1oub', 'What is the process of milk synthesis and secretion of the mammary gland?', 'Lactogenesis', 'Lactogenesis is the initiation/start of milk production.

Lactation is the entire, ongoing process of milk production and secretion.', '["Lactation","Lactogenesis","All of the above","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:27:57.584Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:27:57.584Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:27:57.584Z"'::jsonb),
('anki-card-1754286354951-43', 'anki-deck-1783608953857-1790433145942-e1oub', 'The folllowing are hormones of lactation EXCEPT:', 'Insulin', 'Insulin is associated with glucose metabolism and diabetes.

• Prolactin - stimulates milk synthesis
• Estrogen - contributes to mammary gland development
• Oxytocin - triggers the milk ejection (let-down) reflex', '["Prolactin","Estrogen","Oxytocin","Insulin"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:40:02.661Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:40:02.661Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:40:02.661Z"'::jsonb),
('anki-card-1754286521345-44', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following is NOT true about human milk composition?', 'The composition of human milk is dependent of the state of the mother''s nutrition', 'The composition of human milk is dependent of the state of the mother''s nutrition: not necessarily because the composition of human milk is not entirely dependent on the mother''s diet. Human milk is remarkably stable for macronutrients (protein, carbohydrate) but highly dependent for certain micronutrients and fatty acids.', '["The composition of human milk is dependent of the state of the mother''s nutrition","Composition of human milk varies from one human to another","Human milk consists of solution of protein, sugar, and salts","The human milk is a solution in which a variety of fatty compounds are suspended"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:25:48.043Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T15:25:48.043Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:25:48.043Z"'::jsonb),
('anki-card-1754286704585-45', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which is true about amino acids in human milk?', 'Rich in taurine', 'Human milk is rich in taurine, an amino acid important for infant brain and retinal development that is present in relatively high concentration compared to cow''s milk. Human milk is actually lower in methionine and higher in cysteine, relatively low in phenylalanine and tyrosine compared to other protein sources.', '["Rich in taurine","Higher in methionine and lower in cysteine","High in phenylalanine and tyrosine","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:44:55.987Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:44:55.987Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T07:44:55.987Z"'::jsonb),
('anki-card-1754286743414-46', 'anki-deck-1783608953857-1790433145942-e1oub', 'The human milk has a high concentration of the following minerals EXCEPT:', 'Iron', 'In maternal and child nutrition, human milk is characterized as a poor source of total iron, containing a very low absolute concentration of the mineral (approximately 0.2 to 0.4 mg/L).

Despite its low concentration, healthy full-term infants do not typically require iron supplementation during the first 6 months of exclusive breastfeeding. This is because the iron present in breast milk is exceptionally bound to lactoferrin and paired with high lactose and vitamin C levels, allowing up to 50% of it to be absorbed by the infant''s gut (compared to only ~4% absorption from cow''s milk or standard infant formula).

Calcium, Potassium, and Phosphorus are major essential macrominerals found in much higher, structural quantities in human milk to directly drive infant bone mineralization, fluid balance, and cellular development.', '["Calcium","Potassium","Iron","Phosphorus"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:05:11.671Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:05:11.671Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:05:11.671Z"'::jsonb),
('anki-card-1754286829398-47', 'anki-deck-1783608953857-1790433145942-e1oub', 'An anti-infectious factor in human milk that protects the integrity of the GIT epithelium?:', 'Prostaglandins', '• Bifidus factor - feeds beneficial Bifidobacterium (probiotic); promotes healthy gut flora.
• Lactoperoxidase - kills bacteria by catalyzing the production of hypothiocyanite (antimicrobial compound)
• Lactoferrin - binds and sequesters iron, depriving harmful bacteria (which need iron to grow) of a vital nutrient.', '["Bifidusfactor","Lactoperoxidase","Lactoferrin","Prostaglandins"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:50:31.267Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:50:31.267Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:50:31.267Z"'::jsonb),
('anki-card-1754286997920-49', 'anki-deck-1783608953857-1790433145942-e1oub', 'A drug that should be given to nursing mothers because of it may cause metabolic acidosis and can cause rash.', 'Aspirin', 'Aspirin (salicylates) is famous in pediatric clinical pharmacology for causing mixed acid-base disorders. High-dose maternal ingestion has documented case studies causing metabolic acidosis in nursing infants due to renal accumulation of salicylic acid.

Salicylates also carry risks of antiplatelet-induced rashes/petechiae, hypersensitivity, and the theoretical risk of Reye’s syndrome if the infant encounters a viral illness.

• Clemastine - causes drowsiness, irritability, and may reduce milk supply
• Phenobarbital - causes significant sedation, lethargy, and central nervous system (CNS) depression.
• Primidone - causes severe sedation, feeding problems, and is metabolized into phenobarbital.', '["Aspirin","Clemastine","Phenobarbital","Primidone"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:35:06.354Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:35:06.354Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:35:06.354Z"'::jsonb),
('anki-card-1754287374505-50', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which is true about brain growth and development in preschool age?', 'Brain size has reached 75% of its adult weight by age 2', 'At birth, the brain is 25% of its future adult size, and head circumference is about 14 inches (about 35 centimeters).

• By 1 year of age, the brain is 75% of its adult size. By 3 years of age, the brain is 80% of its adult size.
• By 7 years of age, the brain is 90% of its adult size (Gaber, 2019).', '["Brain size has reached 55% of its adult weight by age 2","Brain size has reached 75% of its adult weight by age 2","Brain size has reached 80% of its adult weight by age 2","Brain size has reached 90% of its adult weight by age 2"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:17:17.239Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:17:17.239Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:17:17.426Z"'::jsonb),
('anki-card-1754287461501-51', 'anki-deck-1783608953857-1790433145942-e1oub', 'This term refers to the child who is "not up to expectation in general health"', 'Failure to thrive', 'Failure to thrive refers to poor weight gain or size deviation post-natally.

• Low birth weight - birth weight less than 2,500 grams.
• Small for gestational age - birth weight below the 10th percentile for the baby''s age.
• Premature infant - born before 37 full weeks of gestation', '["Low birth weight","Small for gestational age","Failure to thrive","Premature infant"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:39:21.687Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:39:21.687Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T07:39:21.687Z"'::jsonb),
('anki-card-1754287547462-52', 'anki-deck-1783608953857-1790433145942-e1oub', 'Based on the general Management of Childhood Illness (IMC) color-coded triage system, what color indicates urgent hospital referral or admission?', 'Pink', 'In the World Health Organization''s (WHO) Integrated Management of Childhood Illness (IMCI) guidelines, a distinct three-color-coded triage system is used to quickly classify a child''s illness and guide treatment protocols:

• PINK (Severe Classification): Indicates urgent hospital referral or admission. A pink row or box on the clinical chart indicates that the child exhibits general danger signs or severe symptoms (such as severe pneumonia, severe dehydration, or severe acute malnutrition). Immediate pre-referral treatment (like a first dose of antibiotics) is given before urgent transfer.

• YELLOW (Specific Outpatient Treatment): Indicates that the child needs a specific medical treatment that can be managed at an outpatient health facility. Healthcare workers prescribe oral drugs and counsel the caregiver on how to administer them at home.

• GREEN (Supportive Home Care): Indicates that the child has no signs of severe illness or conditions requiring specific medical treatments. The caregiver is given simple advice on supportive home management, such as continuous feeding and fluids.', '["Green","Yellow","Red","Pink"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:12:04.838Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:12:04.838Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:12:04.838Z"'::jsonb),
('anki-card-1754287774370-53', 'anki-deck-1783608953857-1790433145942-e1oub', 'The following are normal food behaviors of preschool children EXCEPT:', 'Preference for sweet and spicy', 'Preschoolers typically show a preference for sweet and mild (not spicy) flavors, and an early preference for strongly spicy foods is not a typical, expected behavior at this age.', '["Erratic appetite","Unpredictable appetite","Food rituals are common","Preference for sweet and spicy"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T12:53:35.444Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T12:53:35.444Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T12:53:35.444Z"'::jsonb),
('anki-card-1754287936298-54', 'anki-deck-1783608953857-1790433145942-e1oub', 'To meet the dietary allowances of the preschool children, the following are TRUE except:', 'A and B are both True', 'Providing varied meals in amounts sufficient to satisfy appetite and offering nutritious mid-morning and afternoon snacks especially for active children are both established, evidence-based strategies for meeting preschoolers'' nutrient needs given their small stomach capacity and high activity levels.', '["Provide meals with a variety of foods in amounts sufficient to satisfy the appetite","Offering nutritious snacks in the middle of the morning and afternoon, especially to active children","A and B are both True","A and B are both False"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:50:54.494Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:50:54.494Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:50:54.494Z"'::jsonb),
('anki-card-1754288027858-55', 'anki-deck-1783608953857-1790433145942-e1oub', 'One of the typical nutritional problems among preschool children characterized by loss of subcutaneous fat and gross muscle wasting:', 'PEM', 'PEM – marasmus (wasting) and kwashiorkor (edema)

• Parasitism - presence of worm; can contribute to malnutrition
• Edema – fluid retention; different or opposite-appearing presentation of PEM
• Hyperkinesis - hyper-active; unrelated to wasting', '["Parasitism","PEM","Edema","Hyperkinesis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T12:47:59.272Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T12:47:59.272Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T12:47:59.272Z"'::jsonb),
('anki-card-1754288112021-56', 'anki-deck-1783608953857-1790433145942-e1oub', 'The period shortly after a slow growth period when the weight and height gains are likely to be faster than expected for age and gender.', 'Catch-up Growth', 'Catch-up growth is the accelerated growth following a period of growth faltering, allowing a child to "catch up" toward their expected growth trajectory.

Growth spurt is the period of rapid growth (such as during adolescence) without necessarily following a preceding slow-growth or deficit period.', '["Growth Spurt","Catch-up Growth","All of the above","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:36:30.285Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:36:30.285Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:36:30.462Z"'::jsonb),
('anki-card-1754288206034-57', 'anki-deck-1783608953857-1790433145942-e1oub', 'The protein requirement of children is:', 'Relatively higher in relation to the body weight than those in adults', 'Children''s protein requirement is relatively higher in relation to body weight than that of adults, reflecting the additional protein needed to support rapid growth, tissue building, and development during childhood.', '["Relatively higher in relation to the body weight than those in adults","Relatively lower in relation to the body weight than those in adults","A and B are both True","A and B are both False"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:08:55.659Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:08:55.659Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:08:55.974Z"'::jsonb),
('anki-card-1754288317777-58', 'anki-deck-1783608953857-1790433145942-e1oub', 'The process of physical development from child to adult and refers to the maturation of the body.', 'Puberty', 'Puberty is the biological process during which the body physically matures into an adult capable of reproduction, involving hormonal, physical, and sexual maturation. 

• Adolescence is the broader psychosocial and developmental life stage encompassing puberty but also including cognitive, emotional, and social development beyond just physical maturation. 
• Pubescence is a less standard/precise term sometimes used interchangeably but not the preferred technical term. 
• Maturity is too general and does not specifically denote the physical maturation process described.', '["Adolescence","Pubescence","Puberty","Maturity"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:33:40.451Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:33:40.451Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T08:33:40.451Z"'::jsonb),
('anki-card-1754288387960-59', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which is NOT true about brain development during school age?', 'Rapid growth of brain and head', 'The correct answer is rapid growth of the brain and head, because by school age brain growth has actually slowed considerably and is nearing completion, having occurred most rapidly during infancy and early childhood. 

Slowing down of brain/head growth and brain growth being essentially complete by school age are both accurate descriptions of this developmental stage.', '["Rapid growth of brain and head","Slowing down of growth of brain and head","Brain growth is essential complete during school age","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:11:00.100Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T15:11:00.100Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:11:00.100Z"'::jsonb),
('anki-card-1754288444972-60', 'anki-deck-1783608953857-1790433145942-e1oub', 'All are feeding problems prevalent in preschool-age EXCEPT:', 'Meal skipping', 'Meal skipping is more common among school children and adolescents.', '["Food jags","Dawdling","Gagging","Meal skipping"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:07:52.686Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T15:07:52.686Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:07:52.686Z"'::jsonb),
('anki-card-1754288620847-61', 'anki-deck-1783608953857-1790433145942-e1oub', 'Psychological eating disorder that is also known as "George and Purge"', 'Bulimia nervosa', 'Bulimia nervosa - cycles of binging (overeating) followed by compensatory behaviors (e.g., purging, excessive exercise).

• Anorexia nervosa - restriction leading to dangerously low body weight due to fear of fatness.
• Binge eating - recurring episodes of uncontrolled eating (binging) without compensatory behaviors.
• Pica - persistent consumption of non-food items (e.g., dirt, paint, paper).', '["Anorexia nervosa","Bulimia nervosa","Binge eating","Pica"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:31:55.029Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:31:55.029Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:31:55.225Z"'::jsonb),
('anki-card-1754288670578-62', 'anki-deck-1783608953857-1790433145942-e1oub', 'All are feeding problems prevalent in adolescence EXCEPT:', 'Gagging', 'Gagging is a feeding problem prevalent among preschool children.', '["Snacking","Non-traditional eating patterns","Gagging","Meal skipping"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:03:20.976Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T15:03:20.976Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T15:03:21.187Z"'::jsonb),
('anki-card-1754288759957-63', 'anki-deck-1783608953857-1790433145942-e1oub', 'The following are recommendations to address obesity during adolescence EXCEPT:', 'Psychotherapy', 'Psychotherapy - this recommendation is for other professional.', '["Increased physical activity and exercise","Dietary change","Food use retraining","Psychotherapy"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:43:50.069Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:43:50.069Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-29T08:43:50.261Z"'::jsonb),
('anki-card-1754288839154-64', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which is true about physiologic maturity?', 'Achieved when full genetic body size is attained', 'The correct answer is that physiologic maturity is achieved when full genetic body size (adult stature/proportions) is attained, marking the endpoint of the growth process. 

Choice B is incorrect because continuous organ and tissue growth is actually characteristic of the growing, immature state, not of maturity itself, which represents growth''s completion.', '["Achieved when full genetic body size is attained","Achieved with continuous organ and tissue growth","All of the above","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:42:21.355Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:42:21.355Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T14:42:21.355Z"'::jsonb),
('anki-card-1754288882537-65', 'anki-deck-1783608953857-1790433145942-e1oub', 'It refers to the person''s unique pattern of living:', 'Lifestyle', 'Lifestyle - Total way of living

• Health - state of complete physical, mental, and social well-being
• Wellness - Active pursuit of optimal health through conscious choice
• Behavior - Individual actions or reactions', '["Health","Wellness","Lifestyle","Behavior"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T12:52:12.468Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T12:52:12.468Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T12:52:12.468Z"'::jsonb),
('anki-card-1754288973598-66', 'anki-deck-1783608953857-1790433145942-e1oub', 'An approach to health and well-being which focuses on identiying risk factors and prevention to minimize risk.', 'Preventive approach', 'Preventive approach: This specific model focuses directly on screening populations, identifying underlying risk factors (such as high blood pressure, genetics, or poor diet), and introducing interventions to minimize those risks before a clinical disease develops.

• Traditional approach: Often referred to as the pathogenic or biomedical model, this approach is reactive. It focuses primarily on diagnosing and treating a disease after symptoms have already manifested.
• Wellness approach: This is a holistic approach that goes beyond risk minimization. It focuses on actively optimizing positive health, well-being, and lifestyle factors (such as self-actualization, fitness, and stress management) to help an individual thrive, rather than just preventing illness.', '["Traditional approach","Wellness approach","Preventive approach","Avoidance approach"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:18:21.430Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:18:21.430Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T09:18:21.430Z"'::jsonb),
('anki-card-1754289078410-67', 'anki-deck-1783608953857-1790433145942-e1oub', 'A branch of science dealing with psychological, social, economical, physiological, and medical aspects of aging.', 'Gerontology', 'Gerontology is the broad, multidisciplinary study of the aging process. It encompasses the biological, psychological, social, economic, physiological, and even political aspects of growing old.

• Geriatrics - Medical care of elderly people and their diseases
• Healthy ageing - Maintaining functional ability and well-being throughout later life.
• Nutrigenomics - How nutrients affect genes and gene expression', '["Geriatrics","Gerontology","Healthy ageing","Nutrigenomics"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:49:47.628Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:49:47.628Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T10:49:47.628Z"'::jsonb),
('anki-card-1754289140209-68', 'anki-deck-1783608953857-1790433145942-e1oub', 'This theory of ageing attributes aging to chemical and mechanical exhaustion of cells', 'Wear-and-tear theory', 'Wear-and-tear theory - Mechanical Deterioration

• Clinker theory - Accumulated Waste
• Somatic mutation theory - DNA Damage Accumulation
• Cross-linkage theory - Molecular Rigidity/Stiffening', '["Clinker theory","Wear-and-tear theory","Somatic mutation theory","Cross-linkage theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:39:49.718Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:39:49.718Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-24T13:39:49.936Z"'::jsonb)
