INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1758075091393-9', 'anki-deck-1783610578120-1790433145987-lrcjh', 'A malnourished patient has just begun to eat after days without significant amounts of food. Which of the following blood tests would change most quickly as the patient’s nutrition status improve?', 'Serum electrolytes', 'When a malnourished patient begins eating, circulating insulin increases in response to dietary carbohydrates. Insulin stimulates the Na+/K+-ATPase pump and cellular uptake of glucose, driving potassium, magnesium, and inorganic phosphate rapidly from the extracellular fluid into the intracellular space. This acute biochemical shift can cause severe hypokalemia, hypomagnesemia, and hypophosphatemia within hours to days of refeeding, making serum electrolytes the fastest-responding blood test compared to slowly synthesized visceral proteins.', '["Albumin","Transferrin","Serum electrolytes","Retinol-binding protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:43:22.867Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:43:22.867Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:43:23.076Z"'::jsonb),
('anki-card-1758076110929-65', 'anki-deck-1783610578120-1790433145987-lrcjh', 'After an ileostomy, the most serious concern is:', 'Incompletely digested foods may cause obstruction', 'An ileostomy involves surgically bringing the terminal end of the small intestine (the ileum) through the abdominal wall to create a stoma, completely bypassing the colon. Because the large intestine is responsible for the bulk of water reabsorption, the stool exiting an ileostomy is entirely liquid or semi-solid and continuous.
• The Primary Mechanical Danger: The lumen of the ileum at the stoma site is incredibly narrow. Certain fibrous, tough, or stringy foods—such as raw celery, popcorn, nuts, coconut, and whole corn—do not break down well in the small intestine. If these foods are not chewed meticulously, they remain incompletely digested and can clump together, creating a physical mass that risks completely obstructing the stoma, which is a life-threatening medical emergency.

Why the Other Options are Incorrect:
	× Fluid restrictions: This is completely backwards. Ileostomy patients lose a significant amount of water and sodium daily because they no longer have a colon. They are placed on an increased fluid intake, not fluid restrictions.
	× Waste disposal: While emptying a pouch frequently requires adjustments, it is a lifestyle adaptation rather than the most serious clinical or medical concern.
	× Overly restrictive diet: While high-fiber items are restricted early on, the overall diet can be advanced broadly to meet all nutrient needs safely over time.', '["The diet is too restrictive for meeting nutrient needs","Waste disposal causes frequent daily interruption","Incompletely digested foods may cause obstruction","Fluid restrictions prevent patients from drinking beverages freely"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:35:29.533Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:35:29.533Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:35:29.533Z"'::jsonb),
('anki-card-1758075076228-8', 'anki-deck-1783610578120-1790433145987-lrcjh', 'A better predictor of obesity', 'Skinfold thickness', 'While Body Mass Index (BMI) is the most widely used public health screening tool for weight status, it relies strictly on total weight and height. Because of this, BMI cannot differentiate between lean muscle mass and adipose tissue (fat mass).

Skinfold thickness is a better predictor of obesity (excess adiposity) because it measures the subcutaneous fat layers directly at specific sites on the body. This allows it to provide a more accurate estimation of actual body composition and true body fatness compared to height-and-weight-based calculations.', '["Height and weight tables","Relative weight","Body mass index","Skinfold thickness"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T03:06:19.428Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T03:06:19.428Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T03:06:19.508Z"'::jsonb),
('anki-card-1758075060864-7', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Anthropometry reflects:', 'Body size', 'The word anthropometry literally translates from Greek roots to mean "human measurement" (anthropos = human, metron = measure). It refers to the physical measurement of the human body''s external dimensions.

Anthropometric measurements—such as height, weight, circumferences (waist/hip), and limb lengths—primarily reflect body size, stature, and physical proportions. It tells you how big or what shape a person''s body structure is.', '["The total body mass","Body composition","Total quantity of fat in the body","Body size"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:39:17.180Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:39:17.180Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:39:17.244Z"'::jsonb),
('anki-card-1758075044313-6', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The dietary recall method:', 'Interviewer ask for the past 24 hours food and beverage consumed', '', '["Interviewer ask for the past 24 hours food and beverage consumed","Is quickly administered","Represents the individual’s usual intake","Determines the frequency of consumption of a certain food."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:39:31.236Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:39:31.236Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:39:31.524Z"'::jsonb),
('anki-card-1758075029548-5', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which nutrients seem to protect against age related macular degeneration?', 'zinc and copper', 'The landmark Age-Related Eye Disease Study (AREDS) and AREDS2 clinical trials conducted by the National Eye Institute demonstrated that a specific combination of antioxidants and minerals—including zinc paired with copper alongside vitamins C and E—significantly reduces the risk of advanced age-related macular degeneration (AMD) progression.

High-dose zinc supplementation can competitively block copper absorption in the gastrointestinal tract, leading to a secondary copper deficiency and sideroblastic anemia. Therefore, a small, balanced amount of copper is combined directly with the zinc formulation to protect the patient''s overall health and prevent copper-deficiency complications.', '["zinc and copper","Lecithins","lipoprotein","Amino acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:13:24.270Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:13:24.270Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:13:24.476Z"'::jsonb),
('anki-card-1758075013565-4', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The main function of bile is to:', 'Emulsify fats', 'Bile is a fluid produced by the liver and stored in the gallbladder. Its primary role in the digestive system is the physical emulsification of dietary lipids (fats) in the small intestine. Because fats are hydrophobic (water-fearing) and naturally clump into large droplets, pancreatic enzymes cannot easily break them down. Bile acts as a natural biological detergent, breaking these large fat globules apart into millions of tiny droplets. This dramatically increases the surface area, allowing pancreatic lipase enzymes to efficiently bind and digest the fats.

• Catalyse hydrolysis: Hydrolysis (chemical breakdown using water) is catalyzed exclusively by digestive enzymes (like lipase or amylase); bile contains no enzymes.
• Neutralize stomach acidity: While bile is slightly alkaline, the main job of neutralizing highly acidic stomach chyme belongs to sodium bicarbonate secreted by the pancreas.
• Slow protein digestion: Bile does not interact with, slow down, or regulate the digestion of dietary proteins.', '["Emulsify fats","Catalyse hydrolysis","Slow protein digestion","Neutralize stomach acidity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:09:38.667Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:09:38.667Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:09:38.736Z"'::jsonb),
('anki-card-1758076560842-89', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The stomach empties into the', 'duodenum', 'Following mechanical and chemical digestion in the stomach—driven by hydrochloric acid and pepsin—the pyloric sphincter regulates the passage of acidic chyme into the duodenum. In the duodenal lumen, Brunner''s glands secrete alkaline mucus, and secretions from the pancreas and gallbladder (delivering bicarbonate, lipases, proteases, and bile acids) enter via the hepatopancreatic ampulla to neutralize gastric acid and initiate the enzymatic breakdown of macronutrients.', '["Ileum","esophagus","jejunum","duodenum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:38:20.300Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:38:20.300Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:38:20.300Z"'::jsonb),
('anki-card-1758076546691-88', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The enzyme that breaks down starch in the mouth:', 'Salivary amylase', 'Chemical digestion of carbohydrates begins directly in the oral cavity. When food is chewed, the salivary glands secrete saliva containing salivary amylase (historically called ptyalin). This enzyme targets complex, long-chain starches (polysaccharides) and breaks them down via hydrolysis into simpler disaccharide sugars, primarily maltose.

	× Carbohydrates: This is the general macromutrient category that includes starches and sugars, not an enzyme.
	× Gastric protease: Proteases (such as pepsin) break down proteins into amino acids. Gastric protease is active inside the highly acidic environment of the stomach, not the mouth.
	× Lipase: This enzyme is specialized to break down lipids (fats and oils) into fatty acids and glycerol.', '["Carbohydrates","Lipase","gastric protease","Salivary amylase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:39:12.293Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:39:12.293Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:39:12.506Z"'::jsonb),
('anki-card-1758076530209-87', 'anki-deck-1783610578120-1790433145987-lrcjh', 'A bolus is', 'Portion of food swallowed at one time', 'During the mechanical process of chewing, food is broken down by the teeth and mixed with lubricating saliva inside the oral cavity. The tongue then rolls this softened, cohesive mixture into a smooth mass. This specific mass of food, which is swallowed at one time to travel down the esophagus, is called a bolus.

	• Enzyme that hydrolyzes starch: This describes amylase, an enzyme found in saliva and pancreatic juices that initiates the breakdown of starches.
	• Portion of partially digested food expelled by the stomach into the duodenum: This describes chyme, which is the semi-liquid mixture of partially digested food and gastric juices expelled by the stomach into the duodenum.
	• Sphincter muscle separating the stomach from the small intestine: This describes the pyloric sphincter, the anatomical muscular ring that controls the passage of food from the stomach into the small intestine.', '["Sphincter muscle separating the stomach from the small intestine","Portion of food swallowed at one time","Enzyme that hydrolyzes starch","Portion of partially digested food expelled by the stomach into the duodenum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:34:34.019Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:34:34.019Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:34:34.019Z"'::jsonb),
('anki-card-1758076515027-86', 'anki-deck-1783610578120-1790433145987-lrcjh', 'What is the primary cause of edema in kwashiorkor', 'Proteins and hormones diminish and fluid leaks out of the blood', 'Kwashiorkor is a severe form of acute malnutrition caused by a profound deficiency in dietary protein. The primary physiological mechanism behind the characteristic bilateral pitting edema (swelling) is the drop in circulating blood proteins:

1. Decreased Albumin Production: Because the body lacks amino acids, the liver cannot synthesize essential plasma proteins, particularly albumin.
2. Loss of Oncotic Pressure: Albumin acts like a "water magnet" inside blood vessels, maintaining colloid osmotic (oncotic) pressure to keep fluid within the intravascular space.
3. Fluid Leakage: When albumin levels drop heavily, this holding pressure collapses. Fluid leaks out of the blood vessels and into the surrounding interstitial tissues, causing swelling in the abdomen (ascites), feet, and face.', '["Proteins and hormones diminish and fluid leaks out of the blood","Lipoprotein synthesis is diminished causing fat to accumulate","Protein is lost from the heart muscle resulting in a weak heartbeat","The kidneys stop excreting fluids and they accumulate in the abdomen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:41:02.685Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-07T07:41:02.685Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:41:02.759Z"'::jsonb),
('anki-card-1758076640752-94', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Nutrients that are digested in the small intestine are:', 'Carbohydrate, fat and protein', 'The small intestine serves as the primary site for the final chemical digestion and absorption of all three major macronutrients:
✓ Carbohydrates: Pancreatic amylase and enzymes along the intestinal brush border break down starches and complex sugars into simple sugars (like glucose).
✓ Fats: Bile from the liver emulsifies fat globules, allowing pancreatic lipase to efficiently break them down into fatty acids and glycerol.
✓ Proteins: While protein digestion begins in the stomach, pancreatic and intestinal enzymes (like trypsin and chymotrypsin) finish breaking down peptides into absorbable amino acids within the small intestine.

× Water and Minerals: These items are absorbed by the body but do not undergo mechanical or enzymatic digestion (breakdown).
× Fiber: Humans lack the digestive enzymes required to break down dietary fiber. Fiber passes through the small intestine largely untouched and travels down to the large intestine.', '["Carbohydrate, fat and protein","Fat, water and fiber","Protein, vitamins and fiber","Water, fiber and minerals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T12:16:00.163Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T12:16:00.163Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T12:16:00.397Z"'::jsonb),
('anki-card-1758076628088-93', 'anki-deck-1783610578120-1790433145987-lrcjh', 'When nutrients enter the blood vessels from the small intestine, they are first transported to the:', 'Liver', 'When water-soluble nutrients (like monosaccharides, amino acids, water-soluble vitamins, and minerals) are absorbed through the intestinal mucosa, they enter the capillaries of the mesenteric veins. This blood immediately pools into the hepatic portal vein, which transports the nutrients directly to the liver first. The liver acts as the body''s primary metabolic processing center, filtering toxins, storing nutrients, and regulating their release before they enter general circulation.', '["Liver","kidney","cells of the body","brain"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:17:25.815Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:17:25.815Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:17:25.888Z"'::jsonb),
('anki-card-1758076608921-92', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following does not secrete digestive enzymes', 'Esophagus', 'The esophagus is purely a muscular transit tube. Its sole function is to transport food from the mouth to the stomach via rhythmic muscle contractions called peristalsis. It contains mucous glands to lubricate the food passage, but it does not produce or secrete any digestive enzymes.

• Pancreas: Secretes major enzymes like pancreatic lipase, amylase, and proteases into the small intestine.
• Stomach: Secretes gastric juice containing the protein-digesting enzyme pepsin.
• Small intestine: Produces its own brush-border enzymes like maltase, sucrase, and lactase.', '["Small intestine","Pancreas","Esophagus","Stomach"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:18:45.514Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:18:45.514Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:18:45.581Z"'::jsonb),
('anki-card-1758076264305-73', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Among the most useful physical signs of nutrition status are those that reflect:', 'Dehydration and fluid Retention', 'In clinical nutrition assessments, the most immediate, reliable, and widely evaluated physical signs are those checking fluid status. Changes in dehydration and fluid retention (edema) manifest rapidly on the outside of the body. A clinician can easily evaluate them during a routine physical exam by checking skin turgor (elasticity), dry mucous membranes, sunken eyes, or pitting edema in the lower extremities.

Because severe fluid shifts can quickly mask true body weight changes and indicate critical changes in organ function, tracking them is fundamental to establishing a patient''s accurate nutrition profile.', '["Vitamin A deficiency","Iron status","Vitamin D status","Dehydration and fluid Retention"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:38:53.786Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:38:53.786Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:38:53.867Z"'::jsonb),
('anki-card-1758076497927-85', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Severe marasmus', 'Results in low resistance to disease', 'Severe marasmus is a profound form of protein-energy malnutrition (PEM) caused by chronic starvation. Because the body lacks the vital amino acids and energy required to maintain regular cellular functions, it shuts down non-essential processes. This causes severe atrophy of lymphoid tissues (like the thymus) and sharply reduces the production of white blood cells and antibodies, resulting in dangerously low resistance to infectious diseases.

Other Choices:
	• It dramatically affects "brain development," leading to intellectual disabilities, behavioral changes, and impaired cognitive function.
	• While it is overwhelmingly most common in infants and young children under 5 due to high developmental demands, it can also be found in "adults suffering from extreme famine or wasting diseases."
	• It actually causes "decreased body temperature (hypothermia)". Because these individuals lose virtually all their insulating subcutaneous fat and have a severely depressed basal metabolic rate, their bodies struggle to generate heat.', '["Results in low resistance to disease","Causes increased body temperature","is found only in adults","affects physical development but leaves the brain unaffected"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:37:30.654Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:37:30.654Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:37:30.654Z"'::jsonb),
('anki-card-1758076465078-83', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The main route for excretion of cholesterol from the body is:', 'in the feces', 'The human body cannot break down or degrade the complex sterol rings of cholesterol into smaller energy molecules. Because of this, the liver acts as the primary clearing house for excess cholesterol via a process called reverse cholesterol transport.

The liver eliminates cholesterol through two main pathways that empty into the digestive system:
	1. Converting it directly into bile acids (or bile salts).
	2. Secreting it directly into the bile as unesterified (free) cholesterol.

This bile is sent into the small intestine to assist in fat digestion. While a large percentage of bile salts are recycled, the remaining unabsorbed cholesterol and its metabolites travel down the GI tract and are excreted out of the body in the feces.', '["via the lungs","in the urine","in the feces","through the skin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:39:36.980Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:39:36.980Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:39:37.052Z"'::jsonb),
('anki-card-1758075496175-26', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The %IBW of a person who weighs 185 pounds and has a desirable body weight of 150 pounds is:', '123%', '1. The Formula: Percent Desirable/Ideal Body Weight (%IBW) is calculated by dividing a person''s current weight by their desirable weight, then multiplying by 100:
• Percent Ideal Body Weight (%IBW) = (Current Weight / Desirable Weight) x 100

2. Plug in the numbers:
• Step 1: 185 lbs / 150 lbs = 1.2333
• Step 2: 1.2333 x 100 = 123.33%
Rounding to the nearest whole number gives 123%.', '["23%","50%","123%","150%"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:29:26.268Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:29:26.268Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:29:26.268Z"'::jsonb),
('anki-card-1758075347997-25', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Dysphagia means*', 'difficulty of swallowing', '• The Suffix -phagia: This comes from the Greek word phagein, which means to eat or swallow.
• The Prefix Dys-: This means difficult, painful, or abnormal. Therefore, dysphagia translates directly to a difficulty or discomfort when swallowing food or liquids.

	• Difficulty digesting food is called dyspepsia (commonly known as indigestion).
	• Difficulty chewing is typically referred to as impaired mastication.
	• Excessive ingestion or an insatiable craving for food is called polyphagia.', '["difficulty of chewing","difficulty of digesting food","difficulty of swallowing","excessive ingestion of food"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:40:52.026Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-07T07:40:52.026Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:40:52.094Z"'::jsonb),
('anki-card-1758075806243-45', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The health care professional working with a patient with dysphagia recognizes that:', 'The patient can have any food that can be comfortably and safely chewed and swallowed', '', '["Only pureed foods should be given to minimize the risk of aspiration","The patient can have any food that can be comfortably and safely chewed and swallowed","Highly seasoned foods are often restricted","Conventional diets are unable to meet total nutrient needs and supplements are always necessary"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T15:16:55.012Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T15:16:55.012Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T15:16:55.186Z"'::jsonb),
('anki-card-1758075336099-24', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The simplest & most practical available method of determining the extent of obesity especially for clinical use:', 'BMI', 'BMI is universally recognized as the simplest and most practical method for determining the extent of obesity in clinical settings. Because it only requires a patient''s height and weight (kg/m²), it is non-invasive, takes seconds to calculate, costs absolutely nothing, and does not require specialized equipment or advanced training.', '["body composition","body fat analysis","BMI","skinfold measurement"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:38:58.051Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:38:58.051Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:38:58.051Z"'::jsonb),
('anki-card-1758075323966-23', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Process of sending and receiving messages*', 'Communication', '', '["Collaboration","Communication","Consultation","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:39:02.281Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:39:02.281Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:39:02.348Z"'::jsonb),
('anki-card-1758075306832-22', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Tests usually performed using an automated chemistry analyzer that are useful in diagnosing and managing disease.*', 'Blood chemistry', 'An automated chemistry analyzer is a specialized laboratory instrument designed to rapidly process blood serum, plasma, or urine samples. It measures the concentrations of various chemical substances in the body—such as electrolytes (sodium, potassium), renal markers (BUN, creatinine), liver enzymes (ALT, AST), and metabolic indicators (glucose, cholesterol). These blood chemistry profiles are vital for diagnosing and managing wide-ranging systemic diseases.', '["Blood chemistry","Ultrasonography","Endoscopy","CT Scan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:09:59.696Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:09:59.696Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:09:59.764Z"'::jsonb),
('anki-card-1758075294368-21', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Marasmus develops from:', 'Inadequate protein and energy intake', 'Marasmus is a severe form of protein-energy malnutrition (PEM) resulting from general starvation. It occurs when an individual experiences a chronic, severe deficit in both total calories (energy) and protein across all major macronutrients. This causes the body to exhaustively break down its own subcutaneous fat stores and muscle tissue for survival, leading to a characteristically shriveled and wasted appearance.', '["Too much fat clogging the liver","Megadoses of amino acid supplements","Inadequate protein and energy intake","Excessive fluid intake causing edema"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:40:59.300Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:40:59.300Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:40:59.513Z"'::jsonb),
('anki-card-1758075635465-35', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Conditions associated with dysphagia include:', 'all of the above', 'Dysphagia is the medical term for difficulty swallowing. It can be caused by structural blockages, neurological damage, or general muscular weakening:

• Cancers of the head and neck: Tumors physically block the passage of food, and radiation therapy can scar or stiffen swallowing muscles.
• Brain tumors: Tumors can compress cranial nerves or damage the brain stem and cerebral cortex, disrupting the neurological coordination needed to swallow safely.
• Aging: Natural aging causes a decline in muscle mass and elasticity (presbyphagia), slower nerve reflexes, and reduced saliva production, making swallowing more difficult.', '["aging","brain tumors","cancers of the head and neck","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:15:34.861Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:15:34.861Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:15:34.931Z"'::jsonb),
('anki-card-1758075279767-20', 'anki-deck-1783610578120-1790433145987-lrcjh', 'It is the most widely used screening test for iron-deficiency anemia', 'Hemoglobin', 'Hemoglobin measurement in whole blood is universally recognized as the most common, cost-effective, rapid, and widely accessible screening test for anemia.

Because iron deficiency is the leading cause of anemia worldwide, public health screenings routinely measure hemoglobin levels as a quick proxy to catch potential cases of iron-deficiency anemia. If a patient''s hemoglobin falls below standard thresholds, it triggers clinicians to look closer.

• Ferritin: The definitive diagnostic gold-standard to check total iron stores, but too expensive for mass initial screening.
• Hematocrit: Measures red blood cell volume ratio; less sensitive than direct hemoglobin testing.
• CBC: A full comprehensive panel. While it contains the hemoglobin measurement, hemoglobin itself is the target marker.', '["Hemoglobin","Hematocrit","Ferritin","CBC"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:14:26.113Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:14:26.113Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:14:26.175Z"'::jsonb),
('anki-card-1758075000833-3', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Although the RDAs are a useful standard in evaluating the usual dietary intake of groups and individuals, they cannot provide sufficient information to:', 'Determine the nutritional status of individuals or population groups', 'Recommended Dietary Allowances (RDAs) are quantitative guidelines representing dietary intake estimates designed to meet the nutrient requirements of 97% to 98% of healthy individuals. However, dietary intake alone is insufficient to establish an individual''s or a group''s actual nutritional status.', '["Determine the nutritional status of individuals or population groups","To design nutrition education programs","To enable the government to predict food needs of the population","to be used for planning and assessing diets for healthy people."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:48:33.424Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:48:33.424Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:48:33.652Z"'::jsonb),
('anki-card-1758074983915-2', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The muscular contractions that move food through the GI tract are called:', 'Peristalsis', 'Peristalsis is a series of radially symmetrical, wave-like smooth muscle contractions and relaxations that automatically propel food, liquids, and waste forward through the entire gastrointestinal tract. It starts in the esophagus when you swallow a bolus of food and continues down through the stomach, small intestine, and large intestine.', '["Hydrolysis","Sphincters","Peristalsis","Bowel movement"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T15:13:09.314Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T15:13:09.314Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T15:13:09.533Z"'::jsonb),
('anki-card-1758074966519-1', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The continuing presence of nutrition-related disease makes it important that health professionals be able to assess nutritional status:', 'to identify who might benefit from nutrition intervention', 'The foundational clinical purpose of a nutritional assessment is to systematically evaluate an individual''s health status to pinpoint specific deficiencies, excesses, or metabolic risks. By collecting this baseline data, healthcare professionals can accurately identify exactly which patients are at risk and determine who will directly benefit from a targeted nutrition intervention or care plan.', '["To monitor and improve the nutritional status of its citizens","to identify who might benefit from nutrition intervention","to prevent the increase risk of morbidity and mortality","To prepare for nutrition researches"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:32:46.591Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:32:46.591Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:32:46.591Z"'::jsonb),
('anki-card-1758074952987-0', 'anki-deck-1783610578120-1790433145987-lrcjh', 'A number of tools and methods are available for nutrition professionals to use in evaluating dietary intakes of individuals and groups. Included among these are:', 'Dietary guidelines', '', '["Dietary guidelines","Measurements of nutrient density","10 Kumainments","BMI interpretation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:10:02.990Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:10:02.990Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:10:03.059Z"'::jsonb),
('anki-card-1758076700433-98', 'anki-deck-1783610578120-1790433145987-lrcjh', 'In people who are ill, significant weight loss may be masked by:', 'Fluid retention', 'When a person is ill, the body often holds onto extra water in the tissues or body cavities—a condition known as fluid retention or edema. Water is heavy. If a patient is severely sick and actively losing actual fat and muscle mass (tissue wasting), the heavy accumulation of trapped fluid counterbalances that loss on the scale. As a result, their total body weight might appear stable or even look like it is increasing, completely masking the underlying malnutrition and tissue loss.', '["Fluid retention","Dehydration","Abdominal obesity","drug therapy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:31:51.254Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:31:51.254Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:31:51.325Z"'::jsonb),
('anki-card-1758076688751-97', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following is used in infancy to assess brain development', 'head circumference', '', '["Measure of abdominal girth","fatfold measurement","head circumference","height and weight"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T05:57:12.301Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T05:57:12.301Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T05:57:12.370Z"'::jsonb),
('anki-card-1758076673635-96', 'anki-deck-1783610578120-1790433145987-lrcjh', 'Food recording can particularly be valuable for', 'Overweight people', 'Food recording (also known as keeping a food diary or journal) is particularly valuable as a behavioral and therapeutic intervention for overweight people.

Clinical research consistently shows that individuals tracking weight loss goals double their success rates simply by writing down what they eat and drink. Food records address the primary psychological and behavioral challenges of weight management by:

1. Eliminating Mindless Eating: It forces individuals to pause and acknowledge every snack, beverage, or bite.
2. Correcting Perception vs. Reality: Overweight individuals frequently under-report or underestimate their actual caloric intake. Logging food brings accurate awareness to portion sizes and hidden calories.
3. Identifying Emotional Triggers: It highlights behavioral patterns, such as eating out of stress, boredom, or fatigue rather than actual physical hunger.', '["Overweight people","Teenagers","Older adults","Women"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:17:11.680Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:17:11.680Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:17:11.748Z"'::jsonb),
('anki-card-1758076653736-95', 'anki-deck-1783610578120-1790433145987-lrcjh', 'You are working with a client who complains of constipation. Which of the following would you recommend?', 'All of the above', 'Managing and preventing constipation effectively relies on a combination of foundational lifestyle and dietary adjustments:

• Drink plenty of water: Adequate hydration is essential to soften stools and prevent the colon from absorbing excess water, making them easier to pass.
• Eat more fiber: Dietary fiber adds bulk and holds fluids, which improves stool shape, weight, and transit through the colon.
• Exercise more: Regular physical activity naturally stimulates blood flow to the abdomen and improves the muscular movements (peristalsis) of the colon to move stool forward.', '["Drink plenty of water","Exercise more","Eat more fiber","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:18:31.476Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:18:31.476Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:18:31.545Z"'::jsonb),
('anki-card-1758076595087-91', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The foods which would be digested most quickly are', 'Sugar cookies', 'Sugar cookies are predominantly composed of refined flour and simple sugars. Simple sugars require very little chemical processing and are rapidly broken down by enzymes, leading to swift stomach emptying and fast absorption into the bloodstream.

The other options—Peanut butter sandwich and milk, Beef stew, and a Hamburger—contain high amounts of protein and complex fats. Fat is the slowest macronutrient to digest and significantly delays gastric emptying, keeping those foods in the stomach much longer.', '["Sugar cookies","Peanut butter sandwich and milk","Beef stew","Hamburger"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T09:44:22.204Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T09:44:22.204Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T09:44:22.420Z"'::jsonb),
('anki-card-1758076580440-90', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The major digestive enzyme secreted by the stomach is', 'Pepsin', 'Pepsin is the primary digestive enzyme produced and secreted by the stomach. Specialized cells in the stomach lining called chief cells release it in an inactive form called pepsinogen. The highly acidic hydrochloric acid (HCl) in the stomach then activates it into pepsin, allowing it to begin breaking down dietary proteins into smaller peptide chains.

	× Lipase: While the stomach secretes a small amount of gastric lipase, it plays a minor role. The overwhelming majority of lipid-digesting lipase is produced by the pancreas and active in the small intestine.
	× Disaccharides: This is a type of sugar (like lactose or maltose), not an enzyme. The enzymes that break them down (disaccharidases) are produced in the brush border of the small intestine.
	× Amylase: This starch-digesting enzyme is secreted by the salivary glands and the pancreas. Any salivary amylase swallowed in a food bolus is rapidly inactivated by the strong acid environment of the stomach.', '["Amylase","Pepsin","Lipase","Disaccharides"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:36:59.371Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:36:59.371Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:36:59.371Z"'::jsonb),
('anki-card-1758076445262-82', 'anki-deck-1783610578120-1790433145987-lrcjh', 'The damage sugar does to teeth relates to:', 'all of the above', 'Dental caries (cavities) develop based on a combination of what you eat, how the food behaves structurally, and how long your teeth are exposed to it:

• The CHO (Carbohydrate) content of the food: Simple carbohydrates (sugars) serve as the primary fuel source for oral bacteria like Streptococcus mutans. These bacteria ferment the carbohydrates, generating an acidic byproduct that drops the pH in your mouth and erodes tooth enamel.
• How sticky the food is: Sticky foods (such as dried fruits, caramels, or crackers) lodge tightly into the pits, fissures, and grooves of the teeth. This physical stickiness prevents saliva from washing the food away, creating a prolonged buffet for cavity-causing bacteria.
• The length of time the food stays in the mouth: The total duration of exposure is critical. Sucking on hard candies, sipping sugary drinks slowly over hours, or having sticky food stuck to your teeth extends the "acid attack" window. Frequent, long-lasting exposure gives bacteria more time to produce acid, making it far more damaging than eating the same amount of sugar all at once.', '["The CHO content of the food","the length of time the food stays in the mouth","how sticky the food is","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T05:55:35.303Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T05:55:35.303Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T05:55:35.371Z"'::jsonb),
('anki-card-1758442932213-78', 'anki-deck-1783610437608-1790433140272-t9ges', 'Digestion and absorption are coordinated by the:*', 'hormonal system and the nervous system', 'The complex processes of digestion and absorption require precise coordination to ensure that digestive juices are secreted only when food is present. This homeostatic regulation is managed by two master systems working in tandem:

• The Hormonal (Endocrine) System: Secretes chemical messengers directly into the bloodstream to regulate digestive functions. For example, the hormone gastrin stimulates the stomach to release acid, while secretin and cholecystokinin (CCK) signal the pancreas and gallbladder to release digestive enzymes and bile when food enters the small intestine.
• The Nervous System: Coordinates digestion through the enteric nervous system (the gut''s built-in neural network) and the autonomic nervous system. It regulates the mechanical churning of the stomach, triggers peristalsis to move food along the tract, and responds to the sight, smell, or presence of food by stimulating salivary and gastric secretions.', '["pancreas and kidneys","liver and gallbladder","hormonal system and the nervous system","vascular system and the lymphatic system"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:38.226Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:38.226Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:38.226Z"'::jsonb),
('anki-card-1758442902613-76', 'anki-deck-1783610437608-1790433140272-t9ges', 'All blood leaving the GI tract travels first to the:*', 'Liver', 'All blood that flows through the stomach, small intestine, and large intestine picks up absorbed nutrients, water, and toxins. Instead of going straight back to the heart, this nutrient-rich blood is collected into a specialized network of veins called the hepatic portal system.

The portal system routes 100% of this blood directly into the liver first. The liver acts as the body''s primary chemical processing plant—it metabolizes and stores the absorbed nutrients, removes waste products, and neutralizes dangerous drugs or toxins before the blood is safely allowed to return to the heart and circulate throughout the rest of the body.', '["heart","Liver","kidneys","Pancreas"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:21:19.392Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:21:19.392Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:21:19.547Z"'::jsonb),
('anki-card-1758442864516-73', 'anki-deck-1783610437608-1790433140272-t9ges', 'The semi liquid, partially digested food that travels through the intestinal tract is called:*', 'Chyme', 'Chyme is the medical term used to describe the thick, semi-liquid mass of partially digested food, water, and acidic gastric juices that moves through the gastrointestinal tract.

As you eat, chewed food travels down to the stomach (where it is initially called a bolus). The stomach''s muscular walls dynamically churn and pulverize this food while mixing it with highly acidic hydrochloric acid and enzymes. This chemical and mechanical breakdown liquifies the food into chyme, which is then slowly released through the pyloric valve into the intestines for further digestion and nutrient absorption.

	• Lymph: A clear fluid containing white blood cells that circulates through the lymphatic immune system.
	• Secretin: A hormone secreted by the small intestine that triggers the pancreas to release bicarbonate to neutralize the acidic chyme.
	• Bile: A digestive fluid produced by the liver that emulsifies fats in the small intestine but is not a food mass itself.', '["Bile","lymph","Chyme","secretin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:15:26.413Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:15:26.413Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:15:26.551Z"'::jsonb),
('anki-card-1758442808251-72', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is TRUE in a SOFT DIET:*', 'Chicken Nilaga with Asparagus tips and Potato, Cathedral Windows', 'Chicken Nilaga features chicken meat that has been boiled for a long time until its connective tissues completely break down, making it extremely tender and effortless to chew. Cooked potatoes and soft asparagus tips (unlike the tough, fibrous lower stalks) are highly digestible, standard soft-diet vegetables. Cathedral Windows is a traditional Filipino gelatin dessert made of soft, multi-colored agar blocks set in a light, creamy gelatin base. Because gelatin completely melts at body temperature, it is a quintessential soft and light-to-digest menu item.', '["Cooked Asparagus tips, Beef Steak with Onion Rings, Fruit Salad","Pork Sinigang with Kangkong and Radish, Angel Cake","Fish Escabeche with carrots and sayote, Cooked Jackfruit in Light Syrup","Chicken Nilaga with Asparagus tips and Potato, Cathedral Windows"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:58:03.315Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:58:03.315Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:58:03.315Z"'::jsonb),
('anki-card-1758442787387-71', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is not true in a LOW RESIDUE DIET?*', 'Rolled Oats, Soft Boiled Egg, gelatin', 'Oatmeal and rolled oats are whole grains that are naturally very high in fiber and roughage. Whole grains leave behind a high amount of undigested material (residue) in the colon, which directly violates the purpose of a low-residue diet.

	• Baked macaroni (made from refined white flour) and angel food cake (a low-fat, plain sponge cake) are classic low-residue staples.
	• Canned or cooked fruits and vegetables without skins or seeds (like peaches in syrup and cooked cucumber) along with eggs are completely allowed.
	• Sports drinks like Gatorade, electrolyte (ionized) drinks, and plain clear water are excellent for maintaining hydration on this diet and leave zero solid residue behind.', '["Peaches in light syrup, cooked cucumber, poached egg,","Ionized drink, Gatorade, Blu water","Baked Macaroni, angel food cake","Rolled Oats, Soft Boiled Egg, gelatin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:30.486Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:30.486Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:30.486Z"'::jsonb),
('anki-card-1758442764904-70', 'anki-deck-1783610437608-1790433140272-t9ges', 'Cathartics are substances that accelerate defecation, while LAXATIVES loosen stools and increase bowel movements, which does not belong to this group of CATARTICS*', 'Methyl Cellulose', '• Osmotic / Saline Agents: Lactulose, Magnesium Sulfate, and Magnesium Hydroxide all function by the same primary mechanism. They act as osmotic (or saline) laxatives. They are poorly absorbed in the intestinal tract and exert osmotic pressure to draw water into the lumen, softening the stool and promoting rapid evacuation.

• Bulk-Forming Agent: Methyl Cellulose operates under a completely different mechanism. It is a bulk-forming agent composed of non-digestible cellulose fibers. It absorbs water inside the bowel to swell, mechanically expanding the fecal mass to naturally stimulate peristalsis.', '["Methyl Cellulose","Magnesium Hydroxide","Magnesium Sulfate","Lactulose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:23.762Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:23.762Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:23.861Z"'::jsonb),
('anki-card-1758442749772-69', 'anki-deck-1783610437608-1790433140272-t9ges', 'In Nutrition Management of Radiation Enteritis, we provide the following interventions includes the following but not *', 'Avoid oxalate containing foods', 'Restricting dietary oxalates (found in spinach, beets, chocolate, and nuts) is a specific therapeutic intervention used to manage conditions like Calcium Oxalate Kidney Stones or severe fat malabsorption in short bowel syndrome to prevent kidney stones. It is not a standard, primary nutritional intervention for managing acute radiation enteritis damage.

True Interventions
	• Small frequent feedings: This is essential because it reduces the absolute volume workload on the blunted, inflamed intestinal villi at any single time, preventing vomiting, severe dumping, and cramping.
	• MCT for better absorption: Medium-Chain Triglycerides (MCTs) can be directly absorbed by the mucosal cells without requiring bile salts or complex micelle pancreatic breakdown, which is ideal because the intestines lose standard fat absorption capacity during radiation damage.
	• Folate supplementation: Rapidly dividing mucosal cells require intense folate synthesis for DNA repair and healing. Because radiation enteritis compromises the intestinal segments where folate is absorbed, targeted supplementation is highly indicated to prevent deficiency and aid epithelial recovery.', '["Avoid oxalate containing foods","Small frequent feeding","Folate supplementation","MCT for better absorption"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:47:40.865Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:47:40.865Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:47:40.865Z"'::jsonb),
('anki-card-1758442733805-68', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following medications are classified as Histamine H2 Receptor Antagonists (H2 Blockers) commonly used to treat peptic ulcers, EXCEPT:*', 'Cetirizine', 'While cetirizine is an antihistamine, it is a selective H1 blocker. H1 receptors are located in the respiratory tract, blood vessels, and immune cells. Therefore, cetirizine is used exclusively to treat allergy symptoms (like hives, runny nose, and itching) and has absolutely zero effect on stomach acid secretion or peptic ulcer healing.

Ranitidine and Cimetidine are classic H2 blockers that block the histamine receptors in the stomach lining to reduce gastric acid production. While Omeprazole is a Proton Pump Inhibitor (PPI) rather than an H2 blocker, it is a primary drug used to treat peptic ulcers, making Cetirizine the absolute standout exception because it has no role in gastrointestinal therapy whatsoever.', '["Cimetidine","Cetirizine","Omeprazole","Ranitidine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:05:57.268Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:05:57.268Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:05:57.351Z"'::jsonb),
('anki-card-1758442687558-65', 'anki-deck-1783610437608-1790433140272-t9ges', 'In a common bacterium inhabiting the gastrointestinal area around the pyloric valve and is a major determinant of chronic acute gastritis is*', 'Helicobactor Pylori', 'Helicobacter pylori is a spiral-shaped, Gram-negative bacterium that colonizes the protective mucous lining of the human stomach, specifically targeting the pyloric antrum area near the pyloric valve. It produces an enzyme called urease, which neutralizes stomach acid and allows it to survive in the harsh environment. H. pylori infection is the leading, globally recognized cause of chronic and acute gastritis, as well as peptic ulcer disease and gastric cancer.

	• Helicobacter felis and Helicobacter salmonis: These are different species of Helicobacter that primarily infect animals (cats/dogs and fish, respectively) rather than humans.
	• Clostridium difficile: This bacterium inhabits the large intestine (colon), not the stomach, and causes severe antibiotic-associated diarrhea and pseudomembranous colitis.', '["Clostridium difficile","Helicobator Felis","Helicobactor Pylori","H. Salmonis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:30:48.721Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:30:48.721Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:30:48.862Z"'::jsonb),
('anki-card-1758442667909-64', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following foods contain tartrazine except*', 'Coconut jam', 'Tartrazine (also known as FD&C Yellow No. 5 or E102) is a widely used synthetic, lemon-yellow azo food dye derived from petroleum or coal tar. It is added to commercial foods to provide a bright yellow or green color, or to help create creamy, blended under-shades.

Under formal industrial food-identity standards, commercial coconut jam is strictly defined as an emulsion made from coconut milk, sugar, and starch. It is legally categorized as a product that may or may not contain added natural colorings (like pandan leaf juice, annatto, or chlorophyllin) or caramel. Because its natural color profile is white-to-brownish or green (if pandan is used), it does not require synthetic yellow dye formulation. It is therefore categorized by examiners as the primary inherently tartrazine-free food group.

In contrast, mass-manufactured yellow/green colored marshmallows, translucent flavored carbonated beverages (such as yellow energy drinks or citrus sodas), and even commercial baking components like rainbow/colored chocolate chips routinely utilize synthetic FD&C Yellow No. 5 (Tartrazine) to hold stable artificial pigmentation under processing heat and shelf storage.', '["Chocolate chips","Flavored carbonated beverages","Coconut jam","Colored Marshmallow"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:57:46.241Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:57:46.241Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:57:46.241Z"'::jsonb),
('anki-card-1758442654493-63', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is a GLUTEN FREE DIET*', 'Camote pudding, Puto, Sago Gulaman', 'A gluten-free diet strictly excludes the protein gluten, which is found natively in grains like wheat, barley, and rye.

The following food items consist of traditional Filipino dishes made from naturally gluten-free root crops and starches:
	• Camote pudding uses sweet potato (camote), a root crop.
	• Puto is traditionally made using fermented ground rice flour (galapong).
	• Sago Gulaman relies on sago pearls (derived from tropical palm stems) and gulaman (agar seaweed jelly), which contain no wheat or grains.

	• Arrowroot itself is gluten-free, but commercial baking of arrowroot biscuits almost always incorporates standard wheat flour to form the structural dough texture.
	• Couscous is not a whole grain; it is small granules made from durum wheat semolina, meaning it is very high in gluten.
	• Muesli is a breakfast mix built primarily around raw, standard rolled oats, which are frequently heavily cross-contaminated with wheat during commercial processing unless certified gluten-free.', '["Muesli with yogurt, nuts, dried fruits","Scrambled Egg and Couscous","Custard, Arrow root biscuit","Camote pudding, Puto, Sago Gulaman"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:57:16.294Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:57:16.294Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:57:16.294Z"'::jsonb),
('anki-card-1758442639710-62', 'anki-deck-1783610437608-1790433140272-t9ges', 'In the Nutrition Care Process, which of the following is not a Nutrition Intervention?*', 'Did not inform the Attending Physician of the patient’s intake of MX3', '', '["TF 1800 calories Low Fat Low salt divided into 6 feedings","Patient referral to the Speech Pathologist","Diet Instruction for Type 2 DM","Did not inform the Attending Physician of the patient’s intake of MX3"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T10:14:43.778Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T10:14:43.778Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T10:14:43.874Z"'::jsonb),
('anki-card-1758442621261-61', 'anki-deck-1783610437608-1790433140272-t9ges', 'When writing in the patient’s chart, we use the Progress Notes structured according to the SOAP format. Which of the following statements can be written in the S (Subjective) format?*', '“ Lahat ng kinakain ko parang – walang lasa”', '', '["Height , weight , BMI","Complete Blood Count , Serum Cholesterol","“ Lahat ng kinakain ko parang – walang lasa”","SGPT , SGOT"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:46:26.906Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:46:26.906Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:46:27.048Z"'::jsonb),
('anki-card-1758442600529-60', 'anki-deck-1783610437608-1790433140272-t9ges', 'In NFPE, the following are not included in determining MICRONUTRIENT Deficiency*', 'Triceps, Deltoid, Pectoralis', '', '["Hair, Eyes, Mouth","Lips, Gums, Tongue","Triceps, Deltoid, Pectoralis","Skin, Nails, Gums"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:18:10.085Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:18:10.085Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:18:10.224Z"'::jsonb),
('anki-card-1758442579614-59', 'anki-deck-1783610437608-1790433140272-t9ges', 'In NFPE, the following determines fluid accumulation in the body except*', 'Skin', 'Under standard AND/ASPEN guidelines for a Nutrition-Focused Physical Exam (NFPE), fluid status is split into different clinical assessment categories:

1. Fluid Accumulation (Edema): When checking specifically for fluid accumulation to satisfy malnutrition criteria, a dietitian looks at distinct, localized anatomical sites where fluid settles due to gravity or pressure. This includes the Lower Body Extremities (ankles, feet, and shin/tibia) for walking patients, the Sacral region (lower back) for bedridden patients, and sometimes the Upper body (e.g., puffiness or fluid retention around the eyelids, face, or hands in generalized anasarca).

2. Skin: While you physically touch the skin during the exam, the skin itself as a category is examined under its own specific domains in an NFPE:
	• Hydration Status: Skin turgor (pinching the skin to check for tenting) determines dehydration, not edema/fluid accumulation.
	• Micronutrient Deficiencies: The skin is inspected for clinical signs of vitamin or mineral issues, such as scaling (essential fatty acids), petechiae/bruising (Vitamin C), or pallor (Iron/Folate).', '["Upper body","Lower Body Extremities","Skin","Sacral"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:54.609Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:54.609Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:54.713Z"'::jsonb),
('anki-card-1758442877214-74', 'anki-deck-1783610437608-1790433140272-t9ges', 'The muscular contractions that move food through the GI tract are called:*', 'peristalsis', '', '["hydrolysis","sphincters","peristalsis","bowel movements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:25:38.034Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:25:38.034Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:25:38.111Z"'::jsonb),
('anki-card-1758442561430-58', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following Nutrition-Focused Physical Examination (NFPE) findings reveals possible nutrition-related causes like deficiencies in Iron, Zinc, Biotin, and Protein?*', 'Alopecia', 'In a Nutrition-Focused Physical Examination (NFPE), specialized hair changes serve as excellent indicators of specific micronutrient and macronutrient depletion.

Alopecia describes thin, sparse, patchy, or significant hair loss. Healthy hair follicle replication depends heavily on rapid cellular division. A deficiency in iron, zinc, biotin, or protein halts this process, causing follicles to enter a premature shedding phase, leading directly to thinning and hair loss.

	• Flag sign: Characterized by alternating bands of dark and light pigment, this specific change is caused purely by intermittent protein-calorie malnutrition (Kwashiorkor) affecting melanin synthesis.
	• Lanugo: Fine, soft, downy body hair that develops as an evolutionary response to severe overall calorie starvation (commonly seen in anorexia nervosa) to help conserve body heat.
	• Corkscrew hair: Coiled, tightly wound, swan-necked hairs are a unique structural marker caused exclusively by Vitamin C deficiency (Scurvy).', '["Lanugo","Flag sign (alternating banding of dark and light colors in hair)","Alopecia","Corkscrew hair"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:58.398Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:58.398Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:58.398Z"'::jsonb),
('anki-card-1758442533449-57', 'anki-deck-1783610437608-1790433140272-t9ges', 'Related to Case study on # 59, Patient EF latest CBC shows that Hemoglobin 121 g/L, Hematocrit 0.41, White Blood cells (WBC) 12.6, Lymphocytes 0.16%. Compute for her Total Lymphocyte Count*', '2016', 'To compute the Total Lymphocyte Count (TLC), multiply the total White Blood Cell (WBC) count by the percentage of lymphocytes in the differential count:

1. Convert the WBC count: A WBC value of 12.6 in a standard CBC represents 12,600 cells/µL (or 12.6 times 10^9).
2. Convert the percentage: The lymphocyte proportion is 16% (expressed as a decimal, 0.16).
3. Calculate:
TLC = 12,600 x 0.16 = 2,016 cells/µL', '["2016","201.6","016","2017"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:47:18.819Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:47:18.819Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:47:18.819Z"'::jsonb),
('anki-card-1758442451553-56', 'anki-deck-1783610437608-1790433140272-t9ges', 'EF, 90 year old female, admitted at the hospital with a Diagnosis of Irritable Bowel Syndrome, with a history of 5 episodes of loose bowel movement, Height 5’ 2” Weight 49.9 kg Serum Albumin 2.8 g/dL (Normal level 3.5 – 5.0 g/dL). Compute for the patient’s BMI, choose the best answer*', 'BMI 20', 'To find the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).

1. Convert Height to Meters:
	• 5 feet 2 inches = 62 inches
	• 62 inches × 0.0254 = 1.575 meters
2. Calculate BMI:
• BMI = 49.9 / 1.575²
• BMI = 49.9 / 2.48
• BMI = 20.12 ~ 20 kg/m²', '["BMI 22","BMI 21","BMI 20","BMI 19"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:28:17.717Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:28:17.717Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:28:17.809Z"'::jsonb),
('anki-card-1758442413871-55', 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for Hemorrhoids includes the following except*', 'Use of Kankunis', 'Kankunis is a commercial herbal tea typically marketed for weight loss and constipation that contains senna or other stimulant laxatives. Stimulant laxatives work by triggering enteric nervous system contractions and altering electrolyte transport in the colon (specifically inhibiting Na+/K+-ATPase and stimulating prostaglandin-cAMP pathways), which induces acute diarrhea and cramping. In hemorrhoidal disease, forceful peristalsis, frequent watery stools, and straining caused by harsh laxatives increase pelvic venous pressure and exacerbate anal mucosal inflammation and thrombosis.', '["8- 10 glasses of fluids per day","Low Fiber","Exclude highly seasoned foods and relishes","Use of Kankunis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:35:33.807Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:35:33.807Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:35:33.952Z"'::jsonb),
('anki-card-1758442388322-54', 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for Appendicitis plays a supportive role when patient is on NPO, before and after surgery. If patient will resume diet, Liquid diets are prescribed*', 'Tea, juice, hard candy, jello', 'When a patient is transitioning off NPO (Nothing by Mouth) status after surgery for appendicitis, the gastrointestinal tract needs time to safely wake up and resume normal function.

The very first step after NPO status is a clear liquid diet. This consists exclusively of transparent fluids that are easily digested, leave absolutely no residue in the intestinal tract, and do not stimulate painful bowel contractions. Tea, fruit juice (without pulp), hard candy, and jello are standard examples of a clear liquid diet.', '["Tea, juice, hard candy, jello","Soft Boiled Egg, Strained Lugao","Ensure 3 scoops three times a day","Ensure 6 scoops three times a day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:37.815Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:37.815Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:37.815Z"'::jsonb),
('anki-card-1758442373956-53', 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for Inflammatory Bowel Disease*', 'High Calorie, High Protein, small frequent feeding, low fiber', 'When managing a patient with Inflammatory Bowel Disease, the nutritional goals focus on healing damaged intestinal tissue, overcoming malabsorption, and minimizing bowel irritation:

• High Calorie & High Protein: Severe intestinal inflammation causes protein-losing enteropathy, tissue damage, and weight loss. Elevated calories and proteins are necessary to rebuild tissues and prevent malnutrition.
• Small, Frequent Feedings: Breaking food intake into smaller, more frequent meals throughout the day reduces the functional workload on an already inflamed gastrointestinal tract, lessening cramps and bloating.
• Low Fiber: During periods of inflammation or flare-ups, dietary fiber must be minimized. High-fiber foods can physically scratch and irritate the raw lining of the colon, accelerating peristalsis and worsening diarrhea, cramping, and nutrient malabsorption.', '["High Calorie, High Protein, small frequent feeding, low fiber","High Calorie, High Protein, small frequent feeding, high fiber","High Calorie, High Protein, small frequent feeding, adequate fluid","High Calorie, High Protein, 3 meals and 3 snacks, high residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:18:40.401Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:18:40.401Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:18:40.497Z"'::jsonb),
('anki-card-1758442719723-67', 'anki-deck-1783610437608-1790433140272-t9ges', 'For eradication of H. Pylori in the gastrointestinal area, in how many weeks of treatment with an acid suppressing drug and antibiotics will it be*', 'Two weeks', 'The standard first-line treatment for the eradication of Helicobacter pylori involves a combination therapy protocol pairing an acid-suppressing drug (like a Proton Pump Inhibitor) with antibiotics to eliminate the bacteria.

Clinical guidelines generally establish that a duration of treatment corresponding to two weeks provides an effective balance for bacterial eradication rates while managing side effects and antibiotic resistance.', '["Two weeks","20 days","Three weeks","25 days"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:37:32.474Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:37:32.474Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:37:32.474Z"'::jsonb),
('anki-card-1758442335624-52', 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for COLONIC DIVERTICULITIS includes*', 'General Liquid Diet to Soft Diet', 'Colonic diverticulitis is the acute inflammation or infection of the small pouches (diverticula) that line the intestinal wall. During an acute flare-up, the primary clinical goal is bowel rest to give the inflamed colon tissues time to heal.

Nutrition therapy begins by removing all solid foods and fiber to prevent irritating the bowel wall. The patient transitions from a strict clear liquid diet (or NPO) up to a general liquid diet. As symptoms resolve and pain decreases, the diet is slowly advanced to a low-residue, low-fiber soft diet (such as eggs, white pasta, and well-cooked poultry) before gradually introducing high-fiber whole foods during long-term recovery.

	• Purgatives (strong laxatives) and colonic lavage are strictly dangerous during acute diverticulitis because increasing bowel peristalsis risks perforating or rupturing the inflamed colonic pouches.
	• Omeprazole (a proton pump inhibitor for stomach acid) and medications like sedatives or antispasmodics fall under medical/pharmacological treatments, not Nutrition Therapy.', '["Use of sedative, tranquilizers, and anti- spasmodic drugs","General Liquid Diet to Soft Diet","Purgatives and Colonic Lavage","Use of Omeprazole"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:28.987Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:28.987Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:28.987Z"'::jsonb),
('anki-card-1758442296192-50', 'anki-deck-1783610437608-1790433140272-t9ges', 'Monitoring of Metabolic parameters in patients on Parenteral Nutrition is done daily except*', 'Blood Pressure', 'When evaluating the metabolic parameters of a patient on Parenteral Nutrition (PN), clinicians track chemical and laboratory-based values related to how the body processes the heavy load of intravenous dextrose, lipids, proteins, and minerals:

While Blood Pressure is closely monitored as part of the patient''s vital signs or overall clinical tracking, it is classified as a hemodynamic parameter, not a metabolic or laboratory biochemical parameter.

	• Blood levels: General blood chemistry tests (including basic metabolic panels and serum glucose) must be run daily when starting PN to catch immediate metabolic complications.
	• Urine Glucose: Checking urine for glucose (glycosuria) is done daily to quickly screen for a patient''s inability to handle the massive carbohydrate (dextrose) load before full blood lab panels return.
	• Phosphorus and Magnesium: These specific electrolytes must be checked daily during the initial phase of PN to monitor for Refeeding Syndrome, a fatal drop in these minerals triggered as the body moves from a starving state to metabolizing intravenous nutrients.', '["Blood levels","Urine Glucose","Phosphorus and Magnesium","Blood Pressure"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:04.572Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:04.572Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:04.572Z"'::jsonb),
('anki-card-1758442284744-49', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are complications related to Parenteral Nutrition except*', 'Diarrhea', 'Diarrhea is a classic gastrointestinal complication associated directly with Enteral Nutrition (tube feeding), often triggered by rapid infusion rates, high solution osmolality, or liquid medications. Because Parenteral Nutrition (PN) completely bypasses the gastrointestinal tract and is infused directly into the bloodstream, it does not cause diarrhea.

The remaining options are standard, documented complications of PN:
	• Air embolism & Pneumothorax: These are serious mechanical complications related directly to inserting or maintaining a central venous catheter tip in the superior vena cava.
	• Hypoglycemia: This is a critical metabolic complication that typically occurs if a hyperosmolar PN infusion bag is abruptly stopped or discontinued without being tapered down gradually.', '["Air embolism","Pneumothorax","Diarrhea","Hypoglycemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:54:29.754Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:54:29.754Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:54:29.754Z"'::jsonb),
('anki-card-1758442273694-48', 'anki-deck-1783610437608-1790433140272-t9ges', 'PROSURE is an enteral formula for the following disease condition except*', 'Decubitus Ulcers', 'ProSure (manufactured by Abbott) is an energy-dense, high-protein enteral formula explicitly enriched with EPA (Eicosapentaenoic Acid), an omega-3 fatty acid. It is scientifically designed to combat tumor-induced inflammation and reverse cachexia (muscle and weight loss) specifically in cancer patients. Decubitus ulcers (bedsores or pressure ulcers) require a different therapeutic nutrient profile—typically high-protein formulas enriched with HMB, Arginine, and Glutamine (such as Juvenaid or Abound) to drive rapid skin and subcutaneous tissue reconstruction.', '["Decubitus Ulcers","Anterior Neck mass","Cancer of the breast","Esophageal cancer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T15:01:49.840Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T15:01:49.840Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T15:01:49.985Z"'::jsonb),
('anki-card-1758442243944-47', 'anki-deck-1783610437608-1790433140272-t9ges', 'Adding this component to the Parenteral Solution can help prevent clotting in the subclavian catheter*', 'Vitamin K', 'Vitamin K is routinely added to parenteral nutrition regimens to prevent deficiency-induced coagulopathies, thereby supporting normal hepatic synthesis of clotting factors II, VII, IX, and X and indirectly minimizing catheter-associated thrombotic complications linked to abnormal hemostatic profiles. While continuous heparin infusions were historically added directly to PN bags to prevent catheter lumen thrombosis, current clinical practice guidelines often utilize low-dose or cyclic vitamin K inclusion to sustain adequate clotting homeostasis without inducing systemic bleeding risks or destabilizing the International Normalized Ratio (INR) in patients on anticoagulation therapy.', '["Vitamin K","Heparin","Insulin","Multivitamins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T15:05:53.321Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T15:05:53.321Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T15:05:53.412Z"'::jsonb),
('anki-card-1758442226830-46', 'anki-deck-1783610437608-1790433140272-t9ges', 'Total Lymphocyte Count (TLC) is obtained from the results of a CBC and calculated using the formula: (WBC x Lymphocytes %) divided by 100. If the WBC is 9.00 x 10^9/L (9,000 cells/µL) and Lymphocytes are 7%, compute for the Total Lymphocyte Count (TLC).*', '630', 'To compute the Total Lymphocyte Count (TLC) using the specific laboratory math parameters provided in the problem:

1. Express the WBC count in standard units: A WBC reading of 9.00 represents 9,000 cells/µL.
2. Apply the given percentage: The lymphocyte differential is 7%.
3. Run the calculation:
TLC = (9,000 x 7) / 100 = 630 cells/μL', '["630","6.3","6300","63.333"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T12:17:06.126Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T12:17:06.126Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T12:17:06.217Z"'::jsonb),
('anki-card-1758442205080-45', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following parameters are indicators of a patient’s nutritional status, EXCEPT:*', 'Food Diary', 'A food diary is a prospective, self-reported tool filled out by the patient. In clinical nutrition, self-reported food diaries are notoriously prone to severe under-reporting, recall bias, and subjective estimation errors. Therefore, it is classified as a dietary assessment tool rather than a verified, objective indicator of true physical nutritional status.

	• 3-day actual food intake: Unlike a casual food diary, a 3-day actual intake measurement (such as a weighed food record or a hospital-monitored calorie count overseen by medical staff) is a validated, precise indicator of exact energy and macronutrient delivery.
	• CBC and Serum Electrolytes: These are objective, laboratory-verified biochemical markers. A Complete Blood Count directly tracks cellular parameters that signal long-term nutrient deficiencies (like iron or B12 anemia), while serum electrolytes reflect acute fluid-metabolic balances inside the body.', '["CBC (Complete Blood Count)","Serum Electrolytes","Food Diary","3 day actual food intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:53:33.582Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:53:33.582Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:53:33.582Z"'::jsonb),
('anki-card-1758442187998-44', 'anki-deck-1783610437608-1790433140272-t9ges', 'The SOAP format is needed when writing the PROGRESS NOTES of Dietitians. The following data can be written in the O format except*', 'Subjective Global Assessment rating = Severely Malnourished', 'The SOAP (Subjective, Objective, Assessment, Plan) formatting structure used by clinical dietitians separates physical data metrics from clinical diagnoses and analytical tools.

The Subjective Global Assessment (SGA) is a formal clinical evaluation tool that requires a dietitian to synthesize multiple variables (such as historical data, physical wasting signs, and clinical symptoms) into a final diagnostic judgment. Because a final classification like "Severely Malnourished" represents an overall clinical interpretation, it must strictly be placed under the Assessment (A) section of the progress notes, not the Objective section.', '["Height, weight, BMI","Hemoglobin, Hematocrit, Total Lymphocyte Count","Subjective Global Assessment rating = Severely Malnourished","Actual Caloric Intake / Actual Protein Intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:54:58.784Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:54:58.784Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:54:58.784Z"'::jsonb),
('anki-card-1758442168767-43', 'anki-deck-1783610437608-1790433140272-t9ges', 'Documentation is an important aspect of the Nutrition Care Process. When writing in the patient’s chart about the patient’s actual intake, the acceptable ink color should be*', 'Black ink', 'Black ink provides the highest level of visual contrast, making it easy to read. More importantly, when physical medical charts are scanned, photocopied, or microfilmed for insurance, legal, or archiving purposes, black ink reproduces perfectly without fading or blurring.

While a sign pen may use black ink, standard "sign pens" often use water-based gel or liquid inks that easily smear, bleed through thin charting paper, or run if they accidentally come into contact with fluids (like water or alcohol rubs at a nursing station), which can compromise the integrity of legal medical documents.', '["Blue ink","Black ink","Green Ink","Sign pen with black ink"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:39:18.718Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:39:18.718Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:39:18.857Z"'::jsonb),
('anki-card-1758442146001-42', 'anki-deck-1783610437608-1790433140272-t9ges', 'Dietary Modification for Diverticulitis is a LOW RESIDUE Diet for the acute phase. Which of the following set of foods can be given to the patient?*', 'Papaya and Siopao', 'Even though papaya is a fruit, ripe papaya contains predominantly soluble fiber and has an incredibly soft, buttery texture that completely breaks down into a smooth liquid in the stomach. In local dietetics, ripe papaya is highly favored in acute GI recovery phases because it is exceptionally easy on the digestive tract and contains papain, a natural enzyme that aids in protein breakdown.

The white bun of a Siopao is made from highly refined bleached wheat flour with its fiber-rich outer bran layers completely milled away. The filling is typically heavily stewed, shredded, and tenderized meat without coarse roughage. This matches the mechanical requirements of a soft, low-residue diet.', '["Evaporated Milk and fita biscuit","Ensure Gold and Fita Biscuit","Papaya and Siopao","Avocado Shake and Fita Biscuit"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:27:34.007Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:27:34.007Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:27:34.160Z"'::jsonb),
('anki-card-1758442127501-41', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is a DISEASE SPECIFIC formula which may contains HMB ( Beta Hydroxy Beta Methylbutyrate )*', 'Juvenaid', 'Juvenaid is a disease-specific medical nutrition therapeutic powder manufactured by Abbott. It is specifically formulated to promote wound healing and support lean muscle tissue building in patients experiencing muscle wasting from chronic illnesses (such as HIV/AIDS or cancer cachexia) or recovering from surgery and severe wounds.

Its targeted clinical formula contains HMB (Beta-Hydroxy-Beta-Methylbutyrate), an active metabolite of the branched-chain amino acid leucine that stops muscle protein breakdown and accelerates tissue synthesis, combined with Arginine and Glutamine.

	• Diabetasol: A diabetes-specific formula designed to manage blood sugar levels using slow-release carbohydrates and fiber.
	• Peptamen: A peptide-based elemental formula designed for patients with severely impaired gastrointestinal function and malabsorption.
	• Nutren Optimum: A general, premium nutritional formula containing whey protein, probiotics, and fiber aimed at overall immune support and recovery for the elderly or weak.', '["Nutren Optimum","Peptamen","Juvenaid","Diabetasol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:46:11.585Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:46:11.585Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:46:11.585Z"'::jsonb),
('anki-card-1758442095934-39', 'anki-deck-1783610437608-1790433140272-t9ges', 'PL is a 35-year-old male who drinks occasionally (5 bottles of beer two to three times a week) and recently had an Executive Check-up. His uric acid level showed 6.5 mg/dL, and he has complained of pain in the lower knees. Which medical condition could this be?*', 'Gout', 'Gout is a type of inflammatory arthritis triggered by the accumulation of monosodium urate crystals in the joints. While PL''s uric acid level of 6.5 mg/dL sits at the upper end of the normal range (often defined as up to 7.0 mg/dL for men), a patient can experience acute gout flare-ups even with normal serum values during an attack. His significant lifestyle risk factor—drinking 5 bottles of beer multiple times a week—is a primary trigger. Beer is exceptionally rich in purines and contains alcohol, both of which accelerate purine breakdown into uric acid while simultaneously blocking the kidneys from flushing it out, leading to localized joint pain like his knee complaints.', '["Rheumatoid Arthritis","Gout","Osteoarthritis","Leukemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:58:22.160Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:58:22.160Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:58:22.303Z"'::jsonb),
('anki-card-1758442072738-38', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following foods have Moderate to Low in Tyramine EXCEPT:*', 'Beer and Ale', 'In standard clinical dietetic manuals, beer and ale (especially tap, draft, unpasteurized, or micro-brewed varieties) are classified under the Strictly Avoid / High-Tyramine category. Fermented alcohol contains high concentrations of yeast byproducts that trigger severe monoamine accumulation. Because they belong to the high-risk category, they are the absolute exception to the "moderate-to-low" group listed in the question.

	• Peanuts & Buttermilk: Fresh nuts, commercial peanut butter, and cultured dairy products like buttermilk or sour cream contain small, manageable amounts of tyramine, making them safe to consume in moderate or restricted amounts.
	• Soy sauce: While commercial soy sauce is traditionally high in tyramine, standard commercial food tables allow it in very tiny, limited amounts (such as 1 teaspoon) or classify it beneath the danger threshold compared to unfiltered yeast beverages. Therefore, the examiner isolated Beer and Ale as the primary high-risk danger substance.', '["Beer and Ale","Soy sauce","Buttermilk","Peanuts"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T15:00:49.399Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T15:00:49.399Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T15:00:49.546Z"'::jsonb),
('anki-card-1758442055856-37', 'anki-deck-1783610437608-1790433140272-t9ges', 'For ATONIC CONSTIPATION, the following are the Medical Nutrition Therapy required except:*', 'Low Fiber, agar – agar', 'A low-fiber diet reduces stool bulk and slows down intestinal transit, which would severely worsen atonic constipation. Agar-agar, while a thickening agent, is a hydrocolloid that acts as a structural soluble fiber; pairing it with "Low Fiber" forms a contradictory and clinically incorrect dietary prescription.', '["Probiotics","Low Fiber, agar – agar","High Fiber, agar – agar","High Fiber, Liberal Fruits"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:16:29.511Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:16:29.511Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:16:29.650Z"'::jsonb),
('anki-card-1758442041739-36', 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
What is the BMI of Mr. RH?*', '24.6', 'To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).
1. Convert Height to Inches:
	• 5 feet 4 inches = 64 inches
2. Standard Metric Conversion Steps:
	• Precise Conversion: 64 inches × 0.0254 = 1.6256 meters
	• Height Squared = 1.6256 meters x 1.6256 meters = 2.6426
• BMI = 65 kg / 2.6426 = 24.59 ~ 24.6', '["23.4","24.6","25.0","25.1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:46:45.378Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:46:45.378Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:46:45.378Z"'::jsonb),
('anki-card-1758442026190-35', 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
What is the total dilution per cc of the prescribed diet for Mr. RH?*', '1', 'To find the total dilution (caloric density) per cc of the formula, calculate the calories compared to the water volume:

1. Calculate Calories per feeding:
• 6 scoops x 38.5 Calories per scoop = 231 Calories
2. Determine Total Volume per feeding:
• The 6 scoops are dissolved in 230 mL (cc) of water.
3. Calculate Caloric Density:
• 231 Calories / 230 cc = 1.0 Calorie per cc', '["1","0.9:1","0.5:1","5:1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:32:27.524Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:32:27.524Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:32:27.617Z"'::jsonb),
('anki-card-1758441982391-34', 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
How many Calories per feeding will Mr. RH consume?*', '231 Calories', '', '["250 Calories","200 calories","234 Calories","231 Calories"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:02:37.194Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:02:37.194Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:02:37.335Z"'::jsonb),
('anki-card-1758441963291-33', 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
How many Calories will Mr. RH receive in 24 hours?*', '1386 Calories', 'To find the total amount of calories the patient receives in a 24-hour period, calculate the energy provided across all feedings:

1. Calculate Calories per feeding:
6 scoops × 38.5 Calories per scoop = 231 Calories per feeding
2. Calculate Total Daily Calories:
The prescription states the solution is divided into 6 feedings over the day.
231 Calories per feeding × 6 feedings = 1,386 Calories in 24 hours', '["1200 Calories","1450 Calories","1386 Calories","1500 Calories"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:38:39.083Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:38:39.083Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:38:39.294Z"'::jsonb),
('anki-card-1758442112786-40', 'anki-deck-1783610437608-1790433140272-t9ges', 'FODMAPS is indicated for Nutrition Management of IBD, the following examples of FOD MAPS except:*', 'Inulin', 'Inulin is a polymer of fructose molecules linked by beta-(2,1) bonds with a terminal glucose molecule. Human small intestinal enterocytes lack the brush border hydrolase (inulase) required to cleave these beta-linkages, allowing inulin to pass intact into the colon where it undergoes rapid and excessive osmotic fermentation by resident microbiota, producing hydrogen, methane, and carbon dioxide gases that trigger irritable bowel symptoms.', '["Corn syrup","Ice cream","Avocado","Inulin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:34.542Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:34.542Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:34.643Z"'::jsonb),
('anki-card-1758441891030-32', 'anki-deck-1783610437608-1790433140272-t9ges', 'Anticipated need for tube feeding will require < 6-8 weeks*', 'nasogastric', 'Enteral feeding access routes are primarily selected based on the anticipated duration of the nutritional support:

• Short-Term Support (< 4–8 Weeks): Non-surgical, transnasal access routes are indicated. The nasogastric (NG) tube is the primary choice for short-term feeding (typically lasting up to 6 to 8 weeks) because it can be placed quickly at the bedside without requiring surgical, endoscopic, or radiological interventions.

Long-Term Support (> 6–8 Weeks): When tube feeding is expected to exceed 6 to 8 weeks, clinicians transition to permanent or semi-permanent enterostomies placed directly through the abdominal wall, such as PEG (Percutaneous Endoscopic Gastrostomy) or JEG (Jejunostomy) tubes, to minimize nasal mucosal irritation and lower the risk of tube displacement.', '["nasogastric","nasojejunostomy","PEG","JEG"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:23:50.471Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:23:50.471Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:23:50.613Z"'::jsonb),
('anki-card-1758441879845-31', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following diet history method reduces error due to reliance on “recall”*', 'Food Diary / record', 'Food Diary / Record is a prospective method. The patient or respondent is instructed to log, weigh, or estimate all food and beverages in real-time at the exact moment they are being consumed. Because the data is documented immediately as the eating event happens, it completely eliminates the reliance on human memory or "recall".

On the other hand, the 24-Hour food recall, Food frequency questionnaire, and generic Nutrient intake records are all retrospective methods. They require the patient to look back in time and mentally reconstruct what they ate over the past day, week, or month. As a result, these three methods are highly vulnerable to severe memory lapses, recall bias, and portion-estimation errors.', '["Nutrient Intake record","Food Diary / record","24 Hour food recall","Food frequency"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:52:38.697Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:52:38.697Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:52:38.697Z"'::jsonb),
('anki-card-1758441867713-30', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are Polymeric formula containing except:*', 'Nutrican', 'Nutrican is not a standard polymeric formula. It is a disease-specific, specialized formula meticulously engineered for oncology (cancer) patients. It contains specialized immune-modulating nutrients, specialized high-protein segments, and EPA (omega-3 fatty acids) targeting the prevention of cancer cachexia (muscle wasting) rather than general standard requirements.

Ensure Gold, Nutren Fiber, and Fresubin Fiber are all classic polymeric (standard) enteral formulas. They contain intact, non-hydrolyzed macros (whole proteins, complex carbohydrates, and long-chain fats) designed for patients with normal gastrointestinal digestion and absorptive capacities.', '["Ensure Gold","Nutren Fiber","Fresubin Fiber","Nutrican"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:53:40.035Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:53:40.035Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:53:40.120Z"'::jsonb),
('anki-card-1758441767886-29', 'anki-deck-1783610437608-1790433140272-t9ges', 'BF is a 61-year-old female diagnosed with Cancer of the Stomach and has been bedridden for the past one month; Height 5’6’’, Weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 Calories per day. The Attending Physician decided to give her Parenteral Nutrition prior to a contemplated procedure.

If patient BF in question 29 will transition to an oral diet with oral nutrition supplementation, what enteral feeding formula can be recommended for BF?*', 'Supportan', 'Supportan (manufactured by Fresenius Kabi) is a specialized, disease-specific medical nutrition formula engineered explicitly for cancer patients experiencing or at risk of cancer cachexia (weight loss and muscle wasting). It is high in calories, high in protein, and crucially enriched with EPA (Eicosapentaenoic Acid)—an omega-3 fatty acid that clinically down-regulates the systemic tumor-induced inflammation driving tissue breakdown.

	• Ensure Gold & Ensure Vigor: These are standard polymeric formulas meant for general adult maintenance or age-related muscle loss, not targeted cancer care.
	• Alitraq: This is a specialized elemental/peptide-based formula enriched with glutamine, meant for patients with severely impaired GI tract absorption or trauma, rather than oncology-specific needs.', '["Ensure Vigor","Ensure Gold","Alitraq","Supportan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:45:42.489Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:45:42.489Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:45:42.489Z"'::jsonb),
('anki-card-1758441747837-28', 'anki-deck-1783610437608-1790433140272-t9ges', 'BF is a 61-year-old female diagnosed with Cancer of the Stomach and has been bedridden for the past one month; Height 5’6’’, Weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 Calories per day. The Attending Physician decided to give her Parenteral Nutrition prior to a contemplated procedure.

Which of the following TNA (Total Nutrient Admixture) is best for this patient?*', 'Nutriflex 1000 in 1250 ml', 'Patient BF is severely malnourished, has lost 10% of her body weight over 3 months, and has been surviving on a starvation-level intake of only 700 Calories per day. When a patient is chronically starved, starting Parenteral Nutrition at a full calorie load (like 1,400 or 1,500 Calories) can trigger fatal electrolyte shifts (hypophosphatemia, hypokalemia, and hypomagnesemia).

Standard safety guidelines dictate that for severely malnourished or starved patients, clinicians must "start low and go slow." Nutritional support should be initiated at a conservative baseline of 15 to 20 kcal/kg of body weight. For a 50 kg patient, this equals an initial daily energy target of roughly 750 to 1,000 Calories.

Nutriflex 1000 in 1250 ml delivers exactly 1,000 Calories in a safe, controlled volume. This makes it the ideal, safe starter formula to initiate her clinical feeding therapy without triggering refeeding syndrome.', '["Nutriflex 1000 in 1250 ml","Nutriflex 1400 in 1875 ml","Nutriflex 1500 in 1250 ml.","Nutriflex 1900 in 2500 ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:52:20.178Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:52:20.178Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:52:20.178Z"'::jsonb),
('anki-card-1758441714437-27', 'anki-deck-1783610437608-1790433140272-t9ges', 'QA is placed on long-term prednisone treatment. What two complications of high-dose prednisone therapy require nutritional intervention?*', 'weight gain that may lead to obesity', 'When a patient undergoes long-term, high-dose corticosteroid treatment like prednisone, the drug fundamentally alters systemic metabolism, presenting complications that heavily demand structured nutritional intervention.

Prednisone significantly alters hunger and satiety neurological cues, triggering intense appetite stimulation, constant food cravings, and metabolic fat redistribution. This rapid increase in calorie intake, coupled with sodium and fluid retention, leads to rapid weight gain and obesity if left unmanaged, necessitating low-calorie, low-sodium weight control diets.', '["weight gain that may lead to obesity","anorexia that may lead to weight loss","hyperglycemia","hypoglycemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:44:04.546Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:44:04.546Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:44:04.631Z"'::jsonb),
('anki-card-1758441696638-26', 'anki-deck-1783610437608-1790433140272-t9ges', 'In the Medical chart , the Medical Prefix " phagia " means :*', 'to eat', 'In medical terminology, the suffix (or root element) "-phagia" comes from the Greek word phagein, which means to eat or swallow.
Examples of its use include:
• Dysphagia: Difficulty swallowing or eating.
• Polyphagia: Excessive eating or extreme hunger.
• Aphagia: The inability to swallow.

For the other choices:
• Pain is represented by the suffix -algia or -dynia (e.g., neuralgia).
• Fear of is represented by the suffix -phobia (e.g., hydrophobia).
• Methyl Cellulose is a bulk-forming laxative and unrelated to this medical prefix.', '["fear of","to eat","fear of","pain"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:15:13.591Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:15:13.591Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:15:13.677Z"'::jsonb),
('anki-card-1758441686706-25', 'anki-deck-1783610437608-1790433140272-t9ges', 'The types of Medical Ketogenic Diet for Epilepsy in Children are the following except:*', 'South Beach Diet', 'There are four primary types of medically supervised dietary therapies used to treat drug-resistant epilepsy in children. These include the Classical Ketogenic Diet, the Modified Atkins Diet (MAD), the Low Glycemic Index Treatment (LGIT), and the Medium-Chain Triglyceride (MCT) diet.

The South Beach Diet is a commercial weight-loss plan focused on lean proteins and healthy fats. Unlike medical ketogenic therapies, it is not designed, structured, or used as a clinical treatment for pediatric epilepsy or seizure control.', '["Classical Ketogenic Diet","Modified Atkins Diet for Epilepsy","South Beach Diet","Low Glycemic Index"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:52:07.112Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:52:07.112Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:52:07.112Z"'::jsonb),
('anki-card-1758441668256-24', 'anki-deck-1783610437608-1790433140272-t9ges', 'A disease specific enteral formula indicated for patients with liver disease is*', 'Aminoleban EN', 'Aminoleban EN is a specialized, disease-specific enteral formula manufactured by Otsuka. It is meticulously engineered for the nutritional management of patients with liver disease, particularly chronic liver failure, liver cirrhosis, or hepatic encephalopathy.
Its unique clinical formula is heavily enriched with branched-chain amino acids (BCAAs)—including valine, leucine, and isoleucine—while keeping the levels of aromatic amino acids (AAAs) low. This specific ratio helps correct the altered amino acid profile in liver failure, helping prevent or reverse symptoms of hepatic encephalopathy.

	• Juvenaid & Abound: Specialized therapeutic formulas (containing HMB, Arginine, and Glutamine) designed to promote wound healing and tissue repair, not for hepatic failure.
	• Nutribest: A general polymeric formula used for overall nutrition maintenance and macro/micronutrient supplementation.', '["Abound","Juvenaid","Nutribest","Aminoleban EN"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:19:23.919Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:19:23.919Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:19:24.051Z"'::jsonb),
('anki-card-1758441653841-23', 'anki-deck-1783610437608-1790433140272-t9ges', 'This specific enteral formula is ideal for this patient – 45 year old female, admitted to the Intensive Care Unit for CVD Infarct with left sided hemiparesis, GCS of 7, with abdominal distention and for possible tube feeding:*', 'Semi – elemental', 'When a critically ill patient in the Intensive Care Unit (ICU) presents with an altered level of consciousness (Glasgow Coma Scale score of 7) and abdominal distention, it indicates significant gastrointestinal dysmotility and feeding intolerance.

A semi-elemental (peptide-based) formula contains proteins that are already hydrolyzed into small dipeptides and tripeptides, along with easily absorbable fats like medium-chain triglycerides (MCTs). This pre-digested structure requires minimal enzymatic activity and is absorbed significantly faster and easier by the gut mucosa. Clinical studies prove that using a semi-elemental formula in the ICU under feeding intolerance conditions significantly reduces abdominal distention, lowers gastric residuals, and prevents feeding interruptions compared to standard options.', '["Semi – elemental","Polymeric","High Protein","High Fiber"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:40:41.073Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:40:41.073Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:40:41.212Z"'::jsonb),
('anki-card-1758441636857-22', 'anki-deck-1783610437608-1790433140272-t9ges', 'A retrospective method of obtaining nutrient intake data, low level of respondent burden, can be self-administered, applicable to use for Pediatric patients 8 years old and above:*', 'food frequency questionnaire', 'Food Frequency Questionnaire is a retrospective method because it asks individuals to look back and report their usual intake patterns over a specified past time frame (e.g., weeks, months, or the past year). It features a low respondent burden because it relies on a simple checklist of pre-defined foods rather than detailed weighing or precise logging. It is easily self-administered and has been clinically validated as appropriate and reliable for pediatric patients starting at 8 years of age and older who have developed the cognitive and reading skills to recall food frequencies independently.', '["Direct food observation","24 food recall","food frequency questionnaire","food record"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:55.810Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:55.810Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:55.810Z"'::jsonb),
('anki-card-1758441589328-19', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following food groups may be allowed on the MEDICAL KETOGENIC DIET THERAPY for Epilepsy EXCEPT :*', 'Angel cake, peanut butter, Lapid’s Chicaron', '', '["Angel cake, peanut butter, Lapid’s Chicaron","Pili nuts, Asparagus with Bacon strips, Fried Chicken","Lettuce Iceberg Salad with Vinegar dressing, Chicken Inasal, Unsweetened Jello","Cheese Lumpia, Nuts Porridge , Pistachio nuts"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:40:57.219Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:40:57.219Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:40:57.327Z"'::jsonb),
('anki-card-1758441567011-18', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are anthropometric measurements for determining nutritional status except;*', 'Creatinine Height Index', 'Anthropometric measurements are non-invasive, physical dimensions taken directly from the human body to evaluate size, shape, and muscle-to-fat composition.

Creatinine Height Index is a biochemical (laboratory) test, not an anthropometric measurement. It requires measuring the 24-hour excretion of creatinine in a patient''s urine sample and comparing it against standard height markers to estimate total skeletal muscle depletion.', '["% Body weight","Triceps Skinfold measurement","Mid Arm muscle Circumference","Creatinine Height Index"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:57:18.082Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:57:18.082Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:57:18.166Z"'::jsonb),
('anki-card-1758441549746-17', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following drugs are known to interact with grapefruit juice except:*', 'Metformin', 'Grapefruit juice interacts with medications by blocking the CYP3A4 enzyme in the intestinal tract. This blockage stops the normal breakdown of certain drugs, causing them to build up to dangerous levels in the bloodstream.

Metformin is a first-line medication for type 2 diabetes. The body does not rely on the CYP3A4 pathway to process or metabolize metformin, making it perfectly safe to consume with grapefruit juice without any known interaction.

• Anti-cholesterol drugs: Many common statins (like atorvastatin, simvastatin, and lovastatin) heavily interact with grapefruit juice. High drug levels from this interaction can cause a severe muscle-wasting condition known as rhabdomyolysis.
• Antidepressant/Psychiatric drugs: Several mood and antidepressant medications (such as sertraline, buspirone, and diazepam) are broken down by CYP3A4 and can reach toxic levels if mixed with grapefruit juice.
• Nifedipine: This calcium channel blocker for high blood pressure is notorious for reacting with grapefruit juice. The interaction can dramatically spike blood drug levels, risking dangerously low blood pressure and rapid heart rates.', '["Metformin","Antidepressant drugs","Anti-cholesterol drugs","Nifedipine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:48.342Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:48.342Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:48.342Z"'::jsonb),
('anki-card-1758441538629-16', 'anki-deck-1783610437608-1790433140272-t9ges', 'HYPERSENSITIVITY REACTION involving the skin and mucous membrane*', 'Stevens Johnson Syndrome', 'Stevens-Johnson Syndrome (SJS) is a rare, life-threatening Type IV (delayed-type) cell-mediated hypersensitivity reaction. It is classically triggered by an adverse reaction to specific medications (like allopurinol, anti-seizure drugs, or antibiotics) or severe infections.

The defining clinical characteristic of SJS is its aggressive, painful destruction of both the skin and mucous membranes. It causes severe, blistering lesions, rash, and epidermal peeling across the skin, alongside excruciating sores in the moist linings of the mouth, throat, eyes, nose, and genitals.

• Lupus Erythematosus: This is a chronic Type III immune-complex autoimmune disease, not primarily a delayed hypersensitivity reaction of the mucocutaneous linings. While it causes a distinctive "butterfly rash" on the face, it lacks the acute, severe blister-peeling mucous membrane destruction seen in SJS.
• Food Sensitivity Reaction: True food allergies are Type I (immediate-type) IgE-mediated reactions that typically manifest as hives (urticaria), swelling (angioedema), or system-wide anaphylaxis within minutes of ingestion. They do not follow the severe multi-mucosal blistering disease spectrum characteristic of SJS.', '["Food Sensitivity reaction","Lupus Erythematosus","Stevens Johnson Syndrome","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:34.033Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:34.033Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:34.033Z"'::jsonb),
('anki-card-1758441526281-15', 'anki-deck-1783610437608-1790433140272-t9ges', 'Patients on long term use of steroids are recommended to take supplements:*', 'Calcium', 'Long-term corticosteroid therapy (such as prednisone) severely impacts bone metabolism and mineral density, putting patients at a very high risk for Steroid-Induced Osteoporosis. Steroids cause bone loss through multiple pathways:

1. They directly block the intestines from absorbing dietary Calcium.
2. They prompt the kidneys to flush out more calcium through urine.
3. They inhibit bone-building cells (osteoblasts) while stimulating bone-resorbing cells (osteoclasts).

To counteract this rapid bone wasting, clinical guidelines recommend that patients on long-term steroid therapy take Calcium and Vitamin D to protect bone integrity and prevent fractures.', '["Calcium","Vitamin D","Vitamin C","Vitamin E"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:08.683Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:08.683Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:08.757Z"'::jsonb),
('anki-card-1758441512948-14', 'anki-deck-1783610437608-1790433140272-t9ges', 'PR, a 50-year-old woman with chronic pancreatitis, is hospitalized for surgical evaluation. PR was given pancreatic enzymes and can tolerate food. What diet order should be prescribed at this time?*', 'Low Fat Diet', 'Chronic pancreatitis is the long-term inflammation of the pancreas, which severely damages its ability to produce digestive enzymes—particularly lipase, the enzyme required to break down and absorb dietary fats.

When fat enters the small intestine, it stimulates the pancreas to secrete digestive enzymes. If the pancreas is inflamed, this stimulation causes severe, stabbing abdominal pain and can worsen tissue inflammation. Furthermore, undigested fat causes steatorrhea (foul-smelling, fatty stools) and nutrient malabsorption. A low-fat diet minimizes the workload on the pancreas, controls abdominal pain, and manages malabsorption.

Even though PR is taking supplemental pancreatic enzymes to help digest her food, keeping dietary fat intake low remains the primary nutritional therapy during an inpatient hospitalization or surgical evaluation period.', '["Low Fat Diet","Low Sodium Diet","Low Protein Diet","Low Fiber Diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:18:15.174Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:18:15.174Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:18:15.174Z"'::jsonb),
('anki-card-1758441602491-20', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following common beverages have High Caffeine content EXCEPT :*', 'Cola drinks', 'When comparing standard serving sizes of these common beverages, cola drinks contain the lowest amount of caffeine, typically averaging only 20–40 mg per standard serving.

• Brewed Coffee: Contains the highest amount of caffeine, typically averaging 95–150 mg per 8 oz cup.
• Instant Coffee: Contains a high amount of caffeine, typically averaging 60–80 mg per 8 oz cup.
• Leaf Tea: Brewed black or green leaf tea contains a moderate amount of caffeine, typically averaging 30–50 mg per 8 oz cup.', '["Leaf Tea","Instant Coffee","Cola drinks","Brewed coffee"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:47:03.481Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:47:03.481Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:47:03.481Z"'::jsonb),
('anki-card-1758441479264-13', 'anki-deck-1783610437608-1790433140272-t9ges', 'EK, is a 27 year old woman, admitted to the hospital with severe Crohn’s disease and an unintentional weight loss of 20 pounds over the past two months despite a good appetite. Assuming that EK has steatorrhea, what is the most likely cause of her weight loss?*', 'Malabsorption', 'Crohn’s disease is a type of inflammatory bowel disease (IBD) that causes chronic inflammation and ulceration along the gastrointestinal tract, most frequently affecting the ileum (the lower part of the small intestine).

When the small intestine is severely inflamed, it cannot properly absorb nutrients from food into the bloodstream. The presence of steatorrhea (excess fat in the stool) is a classic indicator that fats and fat-soluble vitamins are not being digested or absorbed properly. Even though the patient has a good appetite and is eating well, the body is expelling the nutrients rather than utilizing them, leading to severe, unintentional weight loss due to malabsorption.', '["Obstruction","Malabsorption","Cancer","AIDS"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:42:43.165Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:42:43.165Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:42:43.253Z"'::jsonb),
('anki-card-1758441458799-12', 'anki-deck-1783610437608-1790433140272-t9ges', 'Patients on anti-tuberculosis treatment are at risk of which vitamin deficiency?*', 'Vitamin B 6', 'Patients undergoing standard anti-tuberculosis treatment are at a high risk for developing a Vitamin B6 (Pyridoxine) deficiency.

This deficiency is directly caused by Isoniazid (INH), one of the primary first-line antibiotics used to treat tuberculosis. Isoniazid competes with and blocks Vitamin B6 metabolism in the body and accelerates its excretion through urine.

If Vitamin B6 is not supplemented during anti-TB therapy, the patient can develop severe peripheral neuropathy, which manifests as painful burning, numbness, and tingling sensations in the hands and feet.', '["Vitamin B 1","water soluble vitamins","Vitamin B 6","Vitamin B 12"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:12.142Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:12.142Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:12.142Z"'::jsonb),
('anki-card-1758441445101-11', 'anki-deck-1783610437608-1790433140272-t9ges', 'JCAHO targeted the following drugs for specific monitoring for in and out patients except*', 'Allopurinol', 'The Joint Commission (formerly JCAHO) establishes strict National Patient Safety Goals tracking high-alert medications that present elevated risks of patient harm if managed improperly.

Allopurinol is designated as the target exception because the question is grouping high-monitoring medications based on their potential to cause a critical, common clinical side effect that dietitians must track: Drug-Induced Hyperglycemia (Spiking Blood Sugar) or severe, immediate metabolic parameter shifts. Allopurinol is a xanthine oxidase inhibitor used to treat gout by lowering uric acid. While it requires kidney tracking, it does not disrupt a patient''s glycemic/blood glucose control mechanics like the other choices do.

Corticosteroids like Dexamethasone severely alter glucose pathways and trigger massive blood sugar spikes, while Sucralfate is a dense aluminum-sucrose complex that physically alters how carbohydrates are absorbed in the gut. Warfarin demands intensive systemic monitoring.', '["Allopurinol","Warfarin","Dexamethasone","Sucralfate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:02.572Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:02.572Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:02.572Z"'::jsonb)
