INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1758441427800-10', 'anki-deck-1783610437608-1790433140272-t9ges', 'Fluoroquinolones (Ciprofloxacin, levofloxacin) must not be taken with the following foods except:*', 'Papaya', 'Fluoroquinolones (such as ciprofloxacin and levofloxacin) are a powerful class of broad-spectrum antibiotic medications. They work by blocking bacterial enzymes, which completely stop bacteria from replicating and repairing their DNA, effectively killing off the infection.

Because fluoroquinolones are highly reactive chemicals, what you put in your stomach at the same time matters immensely. The drug molecules have a strong tendency to attach themselves tightly to divalent minerals like calcium.

Papaya contains no significant minerals or compounds that chelate or alter the breakdown of fluoroquinolone antibiotics, making it safe to eat.

• Dairy Products, Yogurt, and Cottage Cheese: Dairy products are packed with calcium. Calcium binds directly to fluoroquinolones in the gut (a process called chelation). This binding forms an insoluble compound that the body cannot absorb, which severely drops the drug levels and makes the antibiotic ineffective.
• Caffeine: Fluoroquinolones block the liver pathways that break down caffeine. If you consume caffeine while taking these antibiotics, caffeine accumulates in your body, risking severe side effects like a dangerously fast heartbeat, extreme jitteriness, and insomnia.', '["Papaya","Yogurt, Cottage Cheese","Caffeine","Dairy Products"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:49:20.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:49:20.342Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:49:20.414Z"'::jsonb),
('anki-card-1758440670622-9', 'anki-deck-1783610437608-1790433140272-t9ges', 'Patients taking COUMADIN are advised not to increase or decrease their usual consumption of the following foods, EXCEPT:*', 'Bologna', 'Coumadin works by inhibiting vitamin K-dependent blood clotting factors. Patients are advised to keep their consumption of foods containing Vitamin K or items that alter blood coagulation steady and consistent from week to week. Sudden changes can make the medicine less effective or increase bleeding risks.

Broccoli is high in Vitamin K, while green tea and onions can fluctuate or alter Coumadin''s efficacy. Therefore, patients are told not to drastically increase or decrease their intake of these foods.

Bologna is a processed meat sausage. Meats and processed deli products inherently contain extremely low to negligible amounts of Vitamin K. Altering the amount of bologna in a patient''s daily diet has no clinical impact on their international normalized ratio (INR) values or Coumadin''s blood-thinning behavior, making it the correct exception.', '["Green tea","Bologna","Broccoli","Fried Onions"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:50:47.859Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:50:47.859Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:50:47.859Z"'::jsonb),
('anki-card-1758441610942-21', 'anki-deck-1783610437608-1790433140272-t9ges', 'Chronic Malnutrition is a deficiency in*', 'Calories', 'Chronic energy deficiency forces the body into metabolic conservation by downregulating basal metabolic rate, reducing physical activity, and halting linear growth in pediatric populations. Prolonged caloric deficit causes the endocrine axis to suppress the growth hormone-insulin-like growth factor 1 (IGF-1) cascade, shunting minimal available energy toward vital organ function rather than tissue growth or maintenance.', '["Calories","Protein","Calories and Protein","Marasmic Kwashiorkor"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:20:21.654Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:20:21.654Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:20:21.799Z"'::jsonb),
('anki-card-1758440628740-8', 'anki-deck-1783610437608-1790433140272-t9ges', 'LR, a 67 year old man who has had depression was prescribed a MAOI (Monoamine Oxidase Inhibitor) the following foods are avoided except:*', 'Green Tea', 'Green tea is the exception among the listed options because it contains minimal to negligible levels of tyramine and is primarily composed of catechins, flavonoids, and caffeine. Unlike fermented, aged, or protein-degraded foods, green tea does not provoke dangerous systemic vasoconstriction when combined with MAOIs.', '["Avocado","Bean curd","Aged Cheese","Green Tea"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:05:11.881Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:05:11.881Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:05:11.982Z"'::jsonb),
('anki-card-1758440603577-7', 'anki-deck-1783610437608-1790433140272-t9ges', 'In writing prescriptions, t.i.d means*', 'Three times a day', '', '["Three times a day","Two times a day","twice daily","thrice a week"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T12:10:38.515Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T12:10:38.515Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T12:10:38.620Z"'::jsonb),
('anki-card-1758440594460-6', 'anki-deck-1783610437608-1790433140272-t9ges', 'How can medications affect the nutritional status of older adults?*', 'all of the above', '', '["alter food intake, absorption of nutrients, and excretion","decrease food appetite, taste, and smell","cause gastrointestinal disturbances, such as constipation","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:59:45.581Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:59:45.581Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:59:45.722Z"'::jsonb),
('anki-card-1758440572743-5', 'anki-deck-1783610437608-1790433140272-t9ges', 'This nutrition screening tool is validated and used for Elderly patients:*', 'Mini Nutrition Assessment (MNA)', '', '["Subjective Global Assessment","Nutrition Risk Screening 2002","Mini Nutrition Assessment (MNA)","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:17:58.572Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:17:58.572Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:17:58.710Z"'::jsonb),
('anki-card-1758440553710-4', 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59-year-old female Chief Executive Officer of a telecommunications office who is 5’5” tall and weighs 93 kg, was recently admitted to the hospital due to a Transient Ischemic Attack (TIA). Using the NDAP formula, JD’s Recommended Body Weight is*', '57.27 kg', 'The NDAP formula for females is 106 lbs for the first  5 feet (60 inches) of height ± 4 lbs for every inch above or below 5 feet.

1. Calculate the height allowance.
5''5" tall = 106 lbs + (5 inches x 4 lbs/inch) = 126 lbs

2. Convert pounds to kilograms.
126 lbs ÷ 2.2 = 57.27 kg', '["50 kg","65 kg","58.59 kg","57.27 kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:49:44.800Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:49:44.800Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:49:44.800Z"'::jsonb),
('anki-card-1758440517464-3', 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59 year old, female, Chief Executive Officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a BMI (Body mass Index) was admitted in the hospital due to a TIA which stands for*
JD’s BMI is classified as*', 'Obese Class 1', 'To classify JD''s BMI, we first must compute it using the standard metric formula: BMI = Weight (kg) / Height (m²).

1. Convert Height to Meters:
	• 5 feet 5 inches = 65 inches
	• 65 inches × 0.0254 = 1.651 meters
2. Calculate BMI:
	• BMI = 93 ÷ (1.651)²
	• BMI = 93 ÷ 2.726
	• BMI = 34.12

Under the official WHO BMI Classification Guidelines, the cut-off ranges are as follows:
• Overweight: 25.0 to 29.9
• Obese Class 1: 30.0 to 34.9
• Obese Class 2: 35.0 to 39.9
• Obese Class 3 (Morbid Obesity): 40.0 or higher

Because JD''s calculated BMI is 34.12, it sits firmly inside the 30.0 to 34.9 range, making it Obese Class 1 by global definitions.', '["Overweight","Obese Class 1","Obese Class 2","Morbidly Obese"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T10:07:26.700Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T10:07:26.700Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T10:07:26.795Z"'::jsonb),
('anki-card-1758440472182-2', 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59-year-old female, Chief Executive Officer of a telecommunications office, whose height is 5’5” and weight is 93 kg was admitted in the hospital due to a Transient Ischemic Attack (TIA).

Using the data on the height and weight, her BMI is:*', '34.1', 'To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).
1. Convert Height to Meters:
	• 5 feet 5 inches = 65 inches
	• 65 inches × 0.0254 = 1.651 meters
2. Calculate Height Squared:
	• 1.651 x 1.651 = 2.7258
3. Calculate BMI:
	• BMI} = 93 / 2.7258 = 34.118 ~ 34.1 kg/m²', '["35","34.5","34.1","35.99"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:49:29.065Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:49:29.065Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:49:29.065Z"'::jsonb),
('anki-card-1758440331523-1', 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59 year old, female, Chief Executive Officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a BMI (Body mass Index) was admitted in the hospital due to a TIA which stands for*', 'Transient Ischemic Attack', '', '["Mini Stroke","Transient Ischemic Attack","Transient Ischemic Heart Attack","Cerebrovascular Stroke"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-13T11:45:50.148Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-10T11:45:50.148Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:45:50.148Z"'::jsonb),
('anki-card-1758443393690-86', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following foods contain the highest amount of lactose*', 'Yogurt', 'Commercial yogurts are frequently manufactured with added non-fat dry milk solids to improve texture and mouthfeel, which increases the total carbohydrate and lactose concentration per serving compared to fluid milk. While bacterial fermentation by Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus produces microbial $\beta$-galactosidase that hydrolyzes a portion of the lactose into glucose and galactose, the initial substrate load from concentrated milk solids often results in higher total residual lactose per standard 8-ounce serving than fluid milk.', '["Cottage Cheese","Yogurt","Milk","Sherbet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:01:53.109Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:01:53.109Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:01:53.183Z"'::jsonb),
('anki-card-1758443377540-85', 'anki-deck-1783610437608-1790433140272-t9ges', 'Insoluble Fiber is indicated for the following conditions except*', 'Gastric Ulcer', 'Insoluble fiber (found in wheat bran, whole grains, and vegetable skins) does not dissolve in water and acts as coarse roughage that speeds up intestinal transit and adds bulk to stools.

An active gastric ulcer is a raw, inflamed sore in the stomach lining. Insoluble fiber is physically abrasive and difficult to break down, which can mechanically scratch and irritate the stomach lining, increasing pain and delayed healing. Therefore, a low-residue/bland diet is indicated for gastric ulcers instead.

• Insoluble fiber is highly indicated for Diverticular Disease to lower colon pressure, Colon and Rectal Cancer to rapidly flush out potential carcinogens, and selected constipation-predominant Irritable Bowel Syndrome types to improve regularity.', '["Gastric Ulcer","Irritable Bowel Syndrome","Diverticular Disease","Colon and Rectal Cancer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:05:17.387Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:05:17.387Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:05:17.507Z"'::jsonb),
('anki-card-1758443359374-84', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are examples of the Low Fiber Diet except*', 'Oatmeal, Soft Boiled Egg, Gelatin', 'A low-fiber diet requires restricting daily plant fiber intake to ease digestion and rest the gastrointestinal tract. This means replacing whole-grain products with refined starches and avoiding raw or high-fiber foods.

Oatmeal is a whole grain that natively contains high levels of soluble and insoluble fiber. Because whole grains leave a high amount of undigested bulk in the colon, oatmeal is strictly restricted on a standard low-fiber diet plan.', '["Oatmeal, Soft Boiled Egg, Gelatin","White rice, Soft Boiled Egg, Canned peaches","White bread, Scrambled Egg, Strained Juice","White rice, Pork Nilaga, Strained juice"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:02:51.294Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:02:51.294Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:02:51.381Z"'::jsonb),
('anki-card-1758443017341-83', 'anki-deck-1783610437608-1790433140272-t9ges', 'For Radiation Enteritis, this diet is best indicated for this condition*', 'Lactose free, Low Fat, Low Fiber', 'Radiation enteritis is an acute or chronic inflammation of the intestinal tract caused by radiation therapy directed at the abdomen or pelvis. The radiation kills rapidly dividing cells, which damages the mucosal lining, blunts the intestinal villi, and destroys the enzymes responsible for standard digestion.

To manage the resulting malabsorption, cramping, and severe diarrhea, the clinical diet must address multiple mechanics simultaneously:

• Lactose-Free: The brush-border enzyme lactase is the first to be destroyed when the intestinal lining is damaged by radiation. Even a small amount of lactose can trigger severe osmotic diarrhea, gas, and painful bloating.
• Low Fat: Because the blunted villi cannot properly absorb lipids, fats will pass unabsorbed into the colon, causing steatorrhea (fatty stools) and worsening fluid loss.
• Low Fiber: The colon must be completely protected from mechanical irritation. Removing abrasive, scratchy insoluble plant fibers prevents bowel stimulation and minimizes painful cramping.', '["High Fiber","Low Fiber, Low Fat","Lactose free, Low Fat, Low Fiber","Low Residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:53.823Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:53.823Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:53.891Z"'::jsonb),
('anki-card-1758440308708-0', 'anki-deck-1783610437608-1790433140272-t9ges', 'The prevalence of malnutrition among hospitalized patient worldwide is:*', '20 to 50%', 'Globally accepted clinical data from large-scale screening initiatives (such as the nutritionDay worldwide database) establish that 20% to 50% of hospitalized patients suffer from disease-related malnutrition at the time of admission or develop it during their hospital stay.

This wide statistical variance depends heavily on:
1. The specific country or healthcare region.
2. The specific patient population (e.g., intensive care, oncology, or geriatric populations experience much higher rates up to 90%).
3. The individual screening tool or diagnostic criteria used by the facility (such as the NRS-2002, MUST, or GLIM criteria).', '["20 to 48 %","20 to 50%","30 to 50 %","25 to 50 %"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:43.915Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:43.915Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:43.990Z"'::jsonb),
('anki-card-1758443581134-97', 'anki-deck-1783610437608-1790433140272-t9ges', 'Foods discouraged for patients with gastritis or active ulcers include those that*', 'irritate the gastric mucosa', 'For patients with gastritis or active peptic ulcers, nutrition therapy focuses on promoting tissue healing and preventing further irritation to the delicate stomach lining.

Patients must strictly avoid foods that cause direct chemical, mechanical, or thermal irritation to the gastric mucosa, as well as substances that stimulate excessive gastric acid secretion. This includes highly spicy foods (like chili powder and hot peppers), caffeine, alcohol, and extremely acidic foods.', '["are high in fiber","irritate the gastric mucosa","are easy to swallow","contain simple sugars"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:35.822Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:35.822Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:35.902Z"'::jsonb),
('anki-card-1758443559316-96', 'anki-deck-1783610437608-1790433140272-t9ges', 'After an ileostomy, the most serious concern is that*', 'incompletely digested foods may cause obstructions', '', '["the diet is too restrictive to meet nutrient needs","waste disposal causes frequent daily interruptions","fluid restrictions prevent patient from drinking beverages freely","incompletely digested foods may cause obstructions"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:39:26.298Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:39:26.298Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:39:26.450Z"'::jsonb),
('anki-card-1758443539699-95', 'anki-deck-1783610437608-1790433140272-t9ges', 'Symptoms of irritable bowel syndrome most often include*', 'Constipation, Diarrhea and flatulence', 'Irritable Bowel Syndrome (IBS) is a common functional gastrointestinal disorder characterized by abnormal gut motility and visceral hypersensitivity.

The hallmark clinical features of IBS include chronic abdominal pain or cramping paired with significant changes in bowel habits, which typically alternate between diarrhea and constipation (often classified clinically as IBS-D, IBS-C, or IBS-M for mixed types). Excessive gas production (flatulence) and bloating are also universal symptoms caused by altered fermentation profiles in the gut.', '["Nausea and Vomiting","Weight loss and Malnutrition","Strong odors and Obstructions","Constipation, Diarrhea and flatulence"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T10:44:49.529Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T10:44:49.529Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T10:44:49.613Z"'::jsonb),
('anki-card-1758442702490-66', 'anki-deck-1783610437608-1790433140272-t9ges', 'In the Nutrition Management of Peptic Ulcer, gastric stimulants should be limited except*', 'Evaporated Milk', 'While caffeine, alcohol, and even decaffeinated coffee are powerful, direct chemical triggers that prompt the stomach lining to secrete massive amounts of gastric acid, Evaporated Milk is chemically categorized as a food item rather than a pure gastric stimulant. Although the protein and calcium in milk can cause a delayed rebound acid secretion, traditional dietetic manuals classify it under regular dairy/protein food groups rather than standalone chemical irritants or stimulants.', '["Evaporated Milk","Caffeine","Alcohol","Decaffeinated Coffee"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:58.365Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:58.365Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:58.365Z"'::jsonb),
('anki-card-1758442313059-51', 'anki-deck-1783610437608-1790433140272-t9ges', 'Absorbs water and electrolytes to form feces*', 'colon', 'The large intestine is anatomically divided into sections, with the colon acting as the primary site for the final stages of water and mineral reclamation:

As the liquid remains of digested food pass through the colon, its mucosal walls actively absorb water and electrolytes (such as sodium and potassium) back into the bloodstream. This dehydration process compacts the remaining unabsorbed waste, transforming it into solid feces.

	• Rectum: Functions primarily as a temporary storage chamber for the formed feces until defecation occurs.
	• Anus: The external opening and sphincter muscular control point that regulates the elimination of feces out of the body.
	• Appendix: A small, finger-like pouch attached to the cecum that does not play a significant role in fluid or electrolyte absorption.', '["anus","colon","appendix","rectum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:30.752Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:30.752Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:30.863Z"'::jsonb),
('anki-card-1758443526668-94', 'anki-deck-1783610437608-1790433140272-t9ges', 'The Dietitian assessing a patient who had undergone gastrectomy several years ago should be alert to signs of :*', 'Anemia', 'A patient who underwent a gastrectomy (removal of all or part of the stomach) several years ago is at high risk for post-gastrectomy anemia due to two main nutritional deficiencies:

1. Vitamin B12 Deficiency (Pernicious Anemia): The stomach''s parietal cells produce intrinsic factor, which is essential for vitamin B12 absorption in the small intestine. Without a stomach, intrinsic factor is missing, leading to severe B12 deficiency and megaloblastic anemia over time (as B12 stores in the liver take a few years to deplete).

2. Iron Deficiency Anemia: Stomach acid (gastric acid) is required to convert dietary iron into an absorbable form. Without a stomach, iron absorption drops significantly, causing iron deficiency anemia.', '["Dysphagia","GERD","Anemia","Gastritis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:11:47.199Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:11:47.199Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:11:47.281Z"'::jsonb),
('anki-card-1758443513817-93', 'anki-deck-1783610437608-1790433140272-t9ges', 'People at risk of dumping syndrome should generally avoid*', 'Sweets and sugars', 'Dumping syndrome occurs when large amounts of undigested food—especially highly concentrated carbohydrates—move too rapidly from the stomach into the small intestine, often after a gastrectomy or gastric bypass surgery.

Simple sugars and sweets (like candy, table sugar, juices, and sodas) are highly hypertonic (concentrated). When they dump into the small intestine, they pull an immense amount of fluid out of the bloodstream and into the bowel. This causes sudden, distressing symptoms like severe abdominal cramps, explosive diarrhea, nausea, dizziness, rapid heart rate, and a dangerous drop in blood pressure.', '["High fiber foods","Sweets and sugars","Beverages","Bread and Potatoes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:13.575Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:13.575Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:13.653Z"'::jsonb),
('anki-card-1758443500268-92', 'anki-deck-1783610437608-1790433140272-t9ges', 'The following foods may worsen diarrhea but not*', 'Banana', 'Bananas are a staple of the classic therapeutic BRAT diet (Bananas, Rice, Applesauce, Toast) used to treat diarrhea. Ripe bananas are exceptionally rich in soluble fiber (pectin), which acts like a sponge in the digestive tract by absorbing excess water and firming up loose stools. They are also highly digestible and replenish crucial potassium lost during fluid evacuation.

	• Asparagus and cabbage: These are high-fiber, gas-producing foods (high-FODMAP) that increase intestinal gas, bloating, and painful contractions in an already irritated bowel.
	• Caffeine-containing beverages: Caffeine is a powerful gastrointestinal stimulant that accelerates intestinal motility and triggers excess fluid secretion, which directly worsens loose stools.
	• Dried fruits and sugar-free gums: Sugar-free gums contain sugar alcohols (such as sorbitol, xylitol, or mannitol) that exert a strong osmotic laxative effect, drawing water straight into the colon and worsening diarrhea. Dried fruits are highly concentrated in fructose and fiber, which also exacerbate gastrointestinal distress.', '["caffeine containing beverages","dried fruits, sugar free gums","Banana","asparagus, cabbage"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:02:52.107Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:02:52.107Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:02:52.201Z"'::jsonb),
('anki-card-1758443487385-91', 'anki-deck-1783610437608-1790433140272-t9ges', 'Foods that may increase intestinal gases includes the following but not*', 'Peanuts', 'While legumes like beans and lentils are notorious gas producers, peanuts (despite being botanically classified as legumes) are primarily composed of fats and proteins rather than high amounts of gas-producing fermentable carbohydrates (FODMAPs). Protein- and fat-heavy foods are digested without significant colonic fermentation, making peanuts much less likely to increase intestinal gas.

• Beer: Beer is carbonated, releasing trapped carbon dioxide gas into the digestive tract, and it contains fermentable carbohydrates (from grains like barley/wheat) that gut bacteria break down, producing significant intestinal gas.
• Broccoli and Turnips: Both are cruciferous vegetables. Cruciferous vegetables are famously high in complex fibers and a sugar called raffinose, which humans lack the enzymes to break down. Instead, they ferment heavily in the large intestine, causing a great deal of gas.', '["Broccoli","Turnips","Peanuts","Beer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:02:41.340Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:02:41.340Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:02:41.413Z"'::jsonb),
('anki-card-1758442890314-75', 'anki-deck-1783610437608-1790433140272-t9ges', 'The main function of the bile is:*', 'emulsify fats', '', '["emulsify fats","catalyze hydrolysis","slow protein digestion","neutralize stomach acidity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:59:28.644Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:59:28.644Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:59:28.787Z"'::jsonb),
('anki-card-1758443474970-90', 'anki-deck-1783610437608-1790433140272-t9ges', 'The IDDSI framework describes LEVEL 5 as*', 'Minced and moist', 'The International Dysphagia Diet Standardisation Initiative (IDDSI) framework uses a standardized 8-level system (Levels 0–7) with specific names and color codes to manage texture-modified foods and thickened liquids for individuals with dysphagia:

• Level 5 – Minced & Moist (Orange): This level describes foods that are soft, moist, and finely minced into small pieces no larger than 4mm for adults (the width of a standard fork prong gap). It requires minimal chewing and no biting.

	• Liquidized: Represents Level 3.
	• Pureed: Represents Level 4.
	• Soft and Bite size: Represents Level 6 (pieces no larger than 15mm).', '["Liquidized","Soft and Bite size","Pureed","Minced and moist"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:27:07.660Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:27:07.660Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:27:07.796Z"'::jsonb),
('anki-card-1758443448038-89', 'anki-deck-1783610437608-1790433140272-t9ges', 'The International Dysphagia Diet Standardisation Initiative (IDDSI) framework provides a common Terminology to describe food textures and drink thickness has how many levels of standards*', '7 levels', 'The correct answer is not explicitly listed among the given options, but mathematically the framework consists of 8 levels (numbered 0 to 7).

The International Dysphagia Diet Standardisation Initiative (IDDSI) framework is structurally designed as a continuous scale spanning 8 distinct levels, using the numbers 0 through 7 to standardize care:
• Levels 0 to 4 are used to classify drinks (Thin, Slightly Thick, Mildly Thick, Moderately Thick, and Extremely Thick).
• Levels 3 to 7 are used to classify foods (Liquidised, Pureed, Minced & Moist, Soft & Bite-Sized, and Regular).', '["4 Levels","5 Levels","6 Levels","7 levels"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:50.432Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:50.432Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:50.432Z"'::jsonb),
('anki-card-1758443428805-88', 'anki-deck-1783610437608-1790433140272-t9ges', 'Prebiotics can stimulate the growth or activity of resident bacteria within the large intestine. Prebiotics can be found in the following foods except*', 'Miso', 'Miso is a traditional Japanese seasoning produced by fermenting soybeans with salt and koji. Because it is a fermented food, miso naturally contains live, active bacterial cultures, which means it is classified as a Probiotic rather than a prebiotic.

Prebiotics are non-digestible, fiber-rich plant carbohydrates or polyphenols that act as structural "food" to nourish your resident gut bacteria.
	• Onions and garlic, along with Asparagus and Japanese artichoke, are exceptionally rich in inulin and fructooligosaccharides (FOS), which are the most clinically recognized prebiotic fibers.
	• Cocoa contains a high concentration of non-absorbable polyphenols (flavonoids), which are officially classified as non-carbohydrate prebiotic candidates because they stimulate the selective growth of beneficial Lactobacillus and Bifidobacterium species in the colon.', '["Asparagus, Japanese Artichoke","Onions, garlic","Miso","Cocoa"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:02.037Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:02.037Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:02.098Z"'::jsonb),
('anki-card-1758443413040-87', 'anki-deck-1783610437608-1790433140272-t9ges', 'Treatment of lactose intolerance requires limiting milk intake. The following nutrients must be included in the diet except*', 'Zinc', 'When a patient with lactose intolerance limits their dairy and milk intake, they drastically reduce their consumption of primary micronutrients naturally packed into milk fluid.

While milk does contain a small amount of zinc, zinc is highly abundant across multiple non-dairy food groups, including red meat, poultry, seafood (like shellfish and oysters), legumes, seeds, and fortified grains. Restricting dairy does not place a patient at a high clinical risk for zinc deficiency.

	• Calcium and Vitamin D: Milk is the primary source of bioavailable calcium and fortified Vitamin D in the human diet. Restricting milk directly exposes patients to bone-wasting deficiencies, requiring alternative replacement.
	• Riboflavin: Also known as Vitamin B2, riboflavin is heavily concentrated in fluid milk. Dairy products account for over a quarter of total daily riboflavin intake, making its targeted replacement essential when limiting milk.', '["Riboflavin","Zinc","Vitamin D","Calcium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:59:42.152Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:59:42.152Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:59:42.152Z"'::jsonb),
('anki-card-1758443004809-82', 'anki-deck-1783610437608-1790433140272-t9ges', 'Finally, in the large intestine, the remains of the peanut butter and banana sandwich are processed for reabsorption and elimination. The following substances are absorbed at this stage, EXCEPT:*', 'Insoluble fiber', 'As the remains of the sandwich enter the large intestine, the body absorbs fluids (water) and some minerals (like sodium and potassium) back into the bloodstream. Additionally, the healthy bacteria living in your colon ferment and break down the soluble fibers from the banana and bread into short-chain fatty acids, which the body can partially absorb for energy.

Insoluble fiber (found in the wheat bran, seeds, and nuts) cannot be dissolved in water or significantly broken down by intestinal bacteria. It passes through the large intestine completely intact, acting as roughage to bulk up the stool before being eliminated entirely as feces.', '["Fluids","Some minerals","Soluble fibers","Insoluble fiber"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:58:43.279Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:58:43.279Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:58:43.279Z"'::jsonb),
('anki-card-1758442986827-81', 'anki-deck-1783610437608-1790433140272-t9ges', 'From the stomach, the digestion of Peanut Butter and Banana sandwich will now proceed to the Small Intestines, the following nutrients that are involved in this process are:*', 'Sugar, Starch, Protein, Fats', 'Upon arrival in the small intestine, the blended sandwich mass (chyme) triggers the pancreas and the walls of the small intestine to secrete digestive juices and enzymes. Unlike earlier stages where only specific items are targeted, the small intestine is the primary destination where all major macronutrients are simultaneously broken down and chemically processed for absorption:

• Sugar (from the banana): Traverses the intestinal cells almost immediately on contact.
• Starch (from the bread): Pancreatic amylase continues breaking down the remaining complex carbohydrates into simple sugars.
• Protein (from the peanut butter and bread): Pancreatic proteases (like trypsin and chymotrypsin) break the partially uncoiled proteins into absorbable amino acids.
• Fats (from the peanut butter): Gallbladder bile emulsifies the fats, allowing pancreatic lipase to digest them into fatty acids and glycerol.', '["Sugars from Banana, Starch, fats, vitamins and\nminerals","Sugar, Starch, Protein, Fats","Sugars from Banana, Starch, fats, vitamins and minerals","Sugar, Starch, Fats"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:56:13.113Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:56:13.113Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:56:13.247Z"'::jsonb),
('anki-card-1758442971160-80', 'anki-deck-1783610437608-1790433140272-t9ges', 'Related to the digestion of a Peanut Butter and Banana sandwich, the next process is in the stomach (collecting and churning with some digestion). Which nutrients are involved in this process?*', 'Carbohydrates, protein and fats', 'This continues the step-by-step digestion trace of the peanut butter, banana, and whole-wheat bread sandwich based on Whitney and Rolfes'' Understanding Nutrition. Inside the stomach, the main actions are mechanical churning and gastric acid secretion, which actively process all three macronutrients:

• Protein: Stomach acid (hydrochloric acid) denatures and uncoils the protein strands from the bread and peanut butter. Then, the gastric enzyme pepsin initiates chemical digestion by clipping these large protein strands into smaller peptide pieces.
• Fats: Gastric juice contains gastric lipase (working alongside the lingual lipase swallowed from the mouth), which begins targeting and breaking down some of the surface fats found in the peanut butter.
• Carbohydrates: Although the extreme acidity of the stomach temporarily pauses the action of salivary amylase (which digests starches), the simple fruit sugars and starches from the banana and bread remain a heavy part of the resulting fluid mixture. The stomach continues to physically churn them into a uniform liquid mass known as chyme before passing it into the small intestine.', '["Carbohydrates, Amino Acids, fats","Sugars, starch and fats","Carbohydrates, protein and fats","Sugars, starch, vitamins and minerals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-13T11:46:00.213Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-10T11:46:00.213Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:46:00.213Z"'::jsonb),
('anki-card-1758442952993-79', 'anki-deck-1783610437608-1790433140272-t9ges', 'Let us trace the digestion of a peanut butter and banana sandwich on whole-wheat sesame bread through the gastrointestinal (GI) tract. In the mouth, there is chewing and swallowing, but little digestion takes place. Which nutrients are involved in this process?*', 'Carbohydrates and fiber', 'Salivary alpha-amylase is secreted by the parotid and submandibular glands, targeting internal alpha-1,4-glycosidic bonds of starches (found in the whole-wheat bread and banana) to produce dextrins and maltose. Dietary fiber (complex plant polysaccharides such as cellulose, hemicellulose, and pectin found in whole grains, sesame seeds, and banana) is resistant to human endogenous hydrolytic enzymes; thus, fiber undergoes mechanical size reduction via chewing but experiences zero enzymatic degradation in the mouth or stomach.', '["Carbohydrates and protein","Carbohydrates and fats","Carbohydrates and fiber","Carbohydrates and vitamins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:48.512Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:48.512Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:48.621Z"'::jsonb),
('anki-card-1758442916262-77', 'anki-deck-1783610437608-1790433140272-t9ges', 'Which nutrients leave the gastrointestinal tract by way of the lymphatic system:*', 'fats and fat soluble vitamins', 'While water-soluble nutrients (like simple sugars, amino acids, water-soluble vitamins, and minerals) are absorbed directly into the bloodstream via the hepatic portal vein, large lipid molecules cannot dissolve in blood:

Products of fat digestion (monoglycerides and long-chain fatty acids) are reassembled inside intestinal cells into transport packets called chylomylomicrons. These large structures, along with fat-soluble vitamins (A, D, E, and K), are too large to pass through the tight walls of regular blood capillaries. Instead, they enter specialized lymphatic vessels in the intestinal villi called lacteals.

The lymphatic system transports these fats through the thoracic duct, emptying them safely into the bloodstream near the heart, completely bypassing the liver initially.', '["water and minerals","proteins and minerals","all vitamins and minerals","fats and fat soluble vitamins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:17:53.030Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:17:53.030Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:17:53.167Z"'::jsonb),
('anki-card-1754369897156-14', 'anki-deck-1783608850772-1790433142618-6p547', 'The control center. It directs cells activity and is necessary for reproduction. It contains DNA that carries instruction for synthesis of proteins', 'Nucleus', '', '["Nucleus","30-50; 20\n\n70-85","Withdrawal","Mammogenesis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-11T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.982Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
