INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1756879802277-40', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which market form of fat is best suited for creaming and baking applications because of its plasticity?', 'Shortening', '', '["Salad oil","Table fat","Cooking oil","Shortening"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756879787843-39', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following statements best explains why coconut oil is solid at room temperature, unlike most other vegetable oils?', 'It contains mostly medium-chain saturated fatty acids.', '', '["It is composed mainly of long-chain polyunsaturated fatty acids.","It is high in monoglycerides, which are more stable at room temperature.","It contains mostly medium-chain saturated fatty acids.","It is rich in triglycerides with unsaturated bonds that crystallize easily."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756879771395-38', 'anki-deck-1783609411469-1790433139866-aqx4l', 'How does sugar contribute to the tender texture of baked products such as cakes and cookies?', 'By competing with flour for water, slowing gluten development', '', '["By increasing the protein content of flour","By absorbing excess water from the batter","By competing with flour for water, slowing gluten development","By reacting with baking soda to produce more air"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756879754213-37', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is fructose considered the best sugar to prevent crystallization when cooking crystalline candies?', 'It is the hardest common sugar to crystallize, helping control texture.', '', '["It is less sweet than glucose, so it allows higher concentrations in solution.","It caramelizes quickly, preventing crystal formation.","It has the highest molecular weight among sugars, increasing viscosity.","It is the hardest common sugar to crystallize, helping control texture."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756879738214-36', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best describes "filled evaporated milk"?', 'Milk with vegetable fat instead of milk fat', '', '["Milk with added sugar","Milk with vegetable fat instead of milk fat","Milk with reduced lactose","Milk enriched with vitamins"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756879710347-35', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which fat content range is ideal for whipping cream?', '30–36%', '', '["10–15%","20–25%","30–36%","40–50%"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756880772314-90', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is moist-heat cooking generally preferred for tough cuts of meat like beef brisket or pork shoulder?', 'It breaks down connective tissues into gelatin through slow, wet cooking', '', '["It enhances the Maillard reaction for better browning","It breaks down connective tissues into gelatin through slow, wet cooking","It retains less moisture, making meat easier to shred","It crisps the outer surface for added texture"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756879659100-34', 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following is the most critical factor in successfully whipping cream?', 'Cold temperature', '', '["High sugar content","High lactose content","Cold temperature","Low fat content"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
