INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1758786544851-4', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body. *', 'provitamin', 'A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).

	• Preformed vitamin: This describes a vitamin that is already in its fully active, biological state when ingested (such as retinol in animal products) and requires no internal conversion.
	• Vitamer: Vitamers are the multiple structural variations or chemical forms of a single vitamin that all possess similar vitamin activity (e.g., pyridoxine, pyridoxal, and pyridoxamine are all vitamers of Vitamin B₆).
	• Antivitamin: A chemical compound that actively blocks, inhibits, or destroys the biological action of a vitamin.', '["antivitamin","provitamin","vitamer","preformed vitamin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T16:10:19.518Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T16:10:19.518Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-20T16:10:19.610Z"'::jsonb),
('anki-card-1758787706064-67', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Physiological functions of dietary fiber except: *', 'it improves mineral absorption', '', '["it increases bile acid excretion","it improves glucose tolerance","it decreases stool transit time","it improves mineral absorption"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T16:01:06.337Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T16:01:06.337Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-28T16:01:06.337Z"'::jsonb),
('anki-card-1758786720660-10', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The form of vitamin A needed in the synthesis of rhodopsin or the visual purple. *', 'retinal', 'Retinal (specifically in its 11-cis-retinal configuration) is the aldehyde form of vitamin A. It serves as the precise, light-absorbing chromophore that physically binds to the protein opsin to synthesize rhodopsin (visual purple) in the rod cells of the retina.', '["retinol","retinoic acid","beta-carotene","retinal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T07:31:26.510Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T07:31:26.510Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T07:31:26.510Z"'::jsonb),
('anki-card-1758786707359-9', 'anki-deck-1783610488281-1790433142627-pf2m5', 'It is referred to as preformed vitamin A: *', 'retinol', 'This refers to the active, "ready-to-use" form of vitamin A that is found naturally in animal-derived foods (such as liver, eggs, and dairy). Retinol (along with its storage form, retinyl esters) is the specific compound widely designated as "preformed vitamin A" in nutritional science.

Once inside the body, retinol can be converted into retinal (essential for vision) and then further oxidized into retinoic acid (essential for gene regulation). While these are active retinoids, retinol is the primary preformed dietary source.

Meanwhile, Beta-carotene is a plant pigment classified as provitamin A. It is a precursor that the body must first chemically cleave and convert into active vitamin A before it can be used.', '["retinol","retinoic acid","beta-carotene","retinal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Preformed vitamin A refers to the active, biologically available forms of vitamin A found naturally in animal-derived foods (like liver, eggs, and dairy). In biochemistry and food labeling, retinol is the definitive reference molecule for preformed vitamin A. While its derivatives—like retinal and retinoic acid—are also metabolites of preformed vitamin A, retinol is the specific form absorbed from animal sources and stored directly by the liver.', '{"dueDate":"2026-10-11T13:38:33.995Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T13:38:33.995Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-10T13:38:34.067Z"'::jsonb),
('anki-card-1758788015017-96', 'anki-deck-1783610488281-1790433142627-pf2m5', 'These conditions are anabolic processes indicating positive nitrogen balance except for: *', 'fever', '', '["pregnancy","convalescence","fever","growth"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T07:35:07.087Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T07:35:07.087Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T07:35:07.087Z"'::jsonb),
('anki-card-1758787532170-49', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A series of proteins that serve as electron “carriers”:', 'oxidative phosphorylation', 'The question describes the Electron Transport Chain (ETC), which consists of a series of protein complexes embedded in the inner mitochondrial membrane. These proteins act as sequential "carriers," passing electrons down a chain to establish a proton gradient that ultimately drives the synthesis of ATP.

In standard multiple-choice configurations, the Electron Transport Chain is grouped under the overarching stage of oxidative phosphorylation.

• Adenosine triphosphate (ATP): This is the final high-energy chemical product generated by cellular respiration, not a structural protein chain.
• Gluconeogenesis: This is a metabolic pathway by which the liver manufactures glucose from non-carbohydrate precursors during periods of fasting.
• Tricarboxylic acid cycle (Krebs Cycle): This is a series of enzymatic reactions in the mitochondrial matrix that oxidizes acetyl-CoA to produce the temporary electron-carrier molecules (NADH and FADH₂), but the physical chain of carrier proteins itself resides in the next step.', '["gluconeogenesis","adenosine triphosphate","tricarboxylic acid cycle","oxidative phosphorylation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Within the process of oxidative phosphorylation, a series of protein complexes (Complexes I through IV, along with coenzymes like ubiquinone and cytochrome c) are embedded inside the inner mitochondrial membrane. These proteins function explicitly as an electron transport chain, sequentially passing high-energy electrons down a gradient to generate the proton-motive force required to synthesize ATP.', '{"dueDate":"2026-10-11T14:09:39.978Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T14:09:39.978Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-10T14:09:40.051Z"'::jsonb),
('anki-card-1758787697330-66', 'anki-deck-1783610488281-1790433142627-pf2m5', 'All are functions of bile except: *', 'it increases the surface tension of fat', 'Bile salts actually act as detergents (surfactants) that decrease the surface tension of large fat globules. Lowering the surface tension allows the large globules to easily break apart into tiny droplets—a physical process called emulsification.', '["it activates lipase","it increases the surface tension of fat","it is a carrier of vitamins A,D,E,K","it accelerates the action of pancreatic enzymes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T05:07:39.874Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-30T05:07:39.874Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T05:07:39.874Z"'::jsonb),
('anki-card-1758787607585-57', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Factors that increase iron absorption except: *', 'antacids', 'Non-heme iron requires a highly acidic stomach environment to remain soluble and convert from its ferric (Fe^3+) form into the easily absorbable ferrous (Fe^2+) form. Antacids neutralize stomach acid, which directly impairs and decreases iron absorption.', '["growth","ascorbic acid","antacids","pregnancy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T06:31:11.680Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-30T06:31:11.680Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T06:31:11.680Z"'::jsonb),
('anki-card-1758786984347-28', 'anki-deck-1783610488281-1790433142627-pf2m5', 'In the small intestines: *', 'starch is digested by pancreatic amylase into maltose', 'While starch digestion begins in the mouth via salivary amylase, it is halted in the highly acidic stomach. Once the food enters the small intestine (specifically the duodenum), the pancreas secretes pancreatic amylase. This powerful enzyme breaks down remaining complex starches and polysaccharides into the disaccharide maltose and other short glucose polymers.', '["cellulose fiber is digested into monosaccharides","starch is digested by pancreatic amylase into maltose","fat is not hydrolyzed","protein is hydrolyzed by bile acids into amino acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T07:08:30.401Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-30T07:08:30.401Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T07:08:30.401Z"'::jsonb),
('anki-card-1758787292732-36', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Which of the following is not an essential amino acid? *', 'alanine', 'Alanine is a non-essential amino acid: The human body possesses the necessary enzymes to synthesize alanine internally (typically via the transamination of pyruvate). Because the body can produce it on its own, it does not strictly need to be obtained directly from your diet.

To instantly recall the 9 essential amino acids during a test, memorize the phrase "PVT TIM HALL":
• Phenylalanine
• Valine
• Threonine
• Tryptophan
• Isoleucine
• Methionine
• Histidine
• Arginine (often classified as semi-essential or required mostly for children)
• Leucine
• Lysine', '["alanine","tryptophan","lysine","phenylalanine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:16:58.238Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:16:58.238Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-20T15:16:58.327Z"'::jsonb),
('anki-card-1758787824325-79', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The key substance or starting point of the Krebs cycle. *', 'pyruvic acid', '', '["lactic acid","pyruvic acid","acetic acid","citric acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T07:00:05.497Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-30T07:00:05.497Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T07:00:05.497Z"'::jsonb),
('anki-card-1758787725280-69', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Carbohydrate digestion starts in the ____ and is completed in the _____. *', 'mouth; small intestines', '• Starts in the mouth: Carbohydrate digestion begins in the mouth, where mechanical chewing combines with the chemical action of salivary amylase to break down large starches into smaller sugars.

• Completed in the small intestines: The process stops temporarily in the highly acidic stomach but is completed in the small intestine. Here, pancreatic amylase and brush border enzymes finish breaking down carbohydrates into basic sugars like glucose for absorption.', '["stomach; small intestines","mouth; small intestines","mouth; large intestines","small intestines; large intestines"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:05:00.415Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:05:00.415Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-20T15:05:00.506Z"'::jsonb),
('anki-card-1758787715379-68', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Which of the following is not a function of the kidneys? *', 'it activates vitamin A', 'The kidneys activate Vitamin D (converting it into calcitriol), not Vitamin A. Vitamin A is primarily stored and metabolized by the liver.

• Waste Elimination: The kidneys filter blood to remove metabolic waste products like urea, uric acid, and creatinine via urine.
• Red Blood Cell Production: The kidneys release a hormone called erythropoietin (EPO), which stimulates the bone marrow to produce red blood cells.
• Blood Pressure Regulation: The kidneys regulate blood pressure by managing fluid balance and releasing the enzyme renin as part of the renin-angiotensin-aldosterone system (RAAS).', '["it eliminates metabolic waste products","it regulates blood pressure","it activates vitamin A","it aids in red blood cell production"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T11:04:34.062Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T11:04:34.062Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T11:04:34.321Z"'::jsonb),
('anki-card-1758787542138-50', 'anki-deck-1783610488281-1790433142627-pf2m5', 'It is defined as the psychological desire to find and eat food. *', 'appetite', 'Appetite is explicitly defined as the psychological desire to find and eat food. It is often triggered or stimulated by external cues, such as the sight, smell, or thought of food, even when the body does not physically need energy.

Unlike appetite, hunger is the physiological (physical) drive or need for food. It is triggered by internal biological signals, such as an empty stomach, contractions, or drops in blood glucose levels.

• Satiety: This refers to the state or feeling of fullness and satisfaction that occurs after eating, which inhibits the desire to eat until the next meal.
• Palatability: This refers to how pleasurable or appealing a specific food tastes, smells, or feels in the mouth, which influences food selection but is not the desire itself.', '["hunger","satiety","appetite","palatability"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-16T02:54:28.082Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-13T02:54:28.082Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-13T02:54:28.157Z"'::jsonb),
('anki-card-1758787027062-31', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A cofactor that is a carrier of activated CO2 and participates in both gluconeogenesis and fatty acid synthesis is: *', 'biotin', 'Biotin (Vitamin B₇) functions as a specialized covalent cofactor for carboxylase enzymes, acting specifically as a carrier of activated carbon dioxide (CO₂).
It plays a vital dual role in both of the specified metabolic pathways:

• Gluconeogenesis: It serves as a cofactor for pyruvate carboxylase, which adds CO₂ to pyruvate to form oxaloacetate.
• Fatty Acid Synthesis: It serves as a cofactor for acetyl-CoA carboxylase, which adds CO₂ to acetyl-CoA to form malonyl-CoA (the rate-limiting step of fatty acid synthesis).

• Pantothenic acid (Vitamin B₅) is the precursor for Coenzyme A (CoA), which carries activated acyl groups, not CO₂.
• Pyridoxal phosphate (PLP / Vitamin B₆) participates primarily in amino acid metabolism (such as transamination and decarboxylation reactions).
• Flavin adenine dinucleotide (FAD / Vitamin B₂) functions as an electron carrier in oxidation-reduction (redox) reactions.', '["pyridoxal phosphate","biotin","flavin adenine dinucleotide","pantothenic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Biotin (Vitamin B7) serves as a prosthetic group covalently bound to carboxylase enzymes, specifically acting as a specialized carrier for activated carbon dioxide (CO2) groups.  It functions as a crucial cofactor for pyruvate carboxylase, the enzyme that converts pyruvate into oxaloacetate to kickstart the formation of glucose. It acts as a cofactor for acetyl-CoA carboxylase, the regulatory enzyme that converts acetyl-CoA into malonyl-CoA, a vital step in building fatty acids. ', '{"dueDate":"2026-10-11T14:10:04.830Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T14:10:04.830Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-10T14:10:04.914Z"'::jsonb),
('anki-card-1758787687298-65', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Multivitamin supplement is appropriate when: *', 'a patient has chronic debilitating illness', '', '["a child does not eat carrots","a patient has chronic debilitating illness","an athlete undergoes vigorous training","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T04:57:06.926Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-30T04:57:06.926Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T04:57:06.926Z"'::jsonb),
('anki-card-1758786991930-29', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Pancreatic juice contains the following enzyme/s: *', 'trypsinogen', 'The pancreas synthesizes and secretes its protein-digesting enzymes in an inactive proenzyme (zymogen) form to prevent the enzymes from digesting the pancreas itself. Trypsinogen is secreted directly into the pancreatic juice. Once it arrives in the small intestine, it is activated into its working form, trypsin.

• Pepsinogen and pepsin are strictly found in gastric juice secreted by the stomach, not the pancreas.
• Enterokinase (also called enteropeptidase) is a brush-border enzyme produced by the mucosal lining of the small intestine. Its entire job is to sit in the intestine and activate the incoming trypsinogen.', '["trypsinogen","pepsinogen & pepsin","enterokinase","chymotrypsin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:50:31.252Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:50:31.252Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T12:50:31.252Z"'::jsonb),
('anki-card-1758786794807-14', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The protein found in human hair and fingernails as well as animal hooves, horns, and claws. *', 'keratin', 'Keratin is a tough, fibrous structural protein that forms the primary component of human hair, fingernails, and the outer layer of skin, as well as animal hooves, horns, claws, and feathers.

• Collagen is another structural protein, but it is found primarily in connective tissues like skin, bones, tendons, and cartilage.
• Cellulite is not a protein; it is a term used to describe the appearance of dimpled flesh caused by subcutaneous fat deposits.
• Glycogen is a polysaccharide (a complex carbohydrate), not a protein, used by animals to store glucose.', '["keratin","cellulite","collagen","glycogen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'Keratin is a tough, fibrous structural protein that forms the primary chemical component of hair, fingernails, hooves, claws, and horns in animals. It protects epithelial cells from mechanical stress and damage. While it is also a structural protein, collagen is found primarily in connective tissues, skin dermis, tendons, ligaments, and cartilage. It provides tensile strength rather than forming rigid outer structures like nails or hooves.', '{"dueDate":"2026-10-16T02:59:28.372Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-13T02:59:28.372Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-13T02:59:28.447Z"'::jsonb),
('anki-card-1758786752142-13', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The principal carbohydrate stored in plants is: *', 'starch', 'Starch is a complex polysaccharide made of alpha-glucose monomers linked together. Plants produce excess glucose through photosynthesis and string thousands of these molecules together to form starch grains inside their cells. This serves as their primary, long-term chemical energy reserve for periods when sunlight is unavailable.

Plant starch is uniquely composed of a mixture of two distinct polymers: amylose (a linear, unbranched helical chain) and amylopectin (a highly branched chain).', '["cellulose","starch","glycogen","glucose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T13:59:45.624Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T13:59:45.624Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-10T13:59:45.624Z"'::jsonb),
('anki-card-1758786738109-12', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The sugars composing the disaccharide sucrose are: *', 'glucose and fructose', '', '["fructose and galactose","2 glucose","glucose and fructose","2 fructose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T04:55:03.116Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T04:55:03.116Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T04:55:03.116Z"'::jsonb),
('anki-card-1758786729259-11', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The two simple sugars that make up maltose: *', '2 glucose', 'Also known as malt sugar, this disaccharide is formed by a covalent bond between two glucose molecules (specifically an α(1→4) glycosidic linkage). It is commonly produced during the digestion of starch by amylase.

• Glucose and Fructose: These two sugars combine to form sucrose (table sugar).
• Glucose and Galactose: These two sugars combine to form lactose (milk sugar).', '["2 glucose","2 fructose","glucose and fructose","glucose and galactose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:02:19.628Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T12:02:19.628Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T12:02:19.948Z"'::jsonb),
('anki-card-1758786586715-8', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The coenzyme needed to convert pyruvate to acetyl CoA: *', 'TPP', 'The conversion of pyruvate to acetyl-CoA is an oxidative decarboxylation reaction. Thiamine pyrophosphate, or TPP (derived from Vitamin B₁), serves as the coenzyme for E1 (pyruvate dehydrogenase), where it directly attacks and cleaves the carbonyl carbon of pyruvate, releasing carbon dioxide (decarboxylation). While NAD⁺ and FAD are also part of the 5-coenzyme complex (alongside Lipoic acid and CoA-SH), TPP is uniquely required as the initial binding and decarboxylating coenzyme.

• NAD: While NAD⁺ is required by the PDH complex (for the E3 subunit), its specific role is to act as the final electron acceptor to reset the system, producing NADH.
• FAD: FAD is an intermediate electron carrier within the E3 subunit of the complex that transfers its electrons to NAD⁺.
• PLP: Pyridoxal Phosphate (derived from Vitamin B₆) is not involved in this pathway at all. It is primarily the essential coenzyme for transamination and decarboxylation reactions in amino acid metabolism.', '["TPP","FAD","NAD","PLP"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:50:55.473Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:50:55.473Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T12:50:55.473Z"'::jsonb),
('anki-card-1758786575382-7', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The hormone responsible for stimulating the uptake of glucose into the cells and its storage as glycogen in the liver and muscles: *', 'insulin', 'This anabolic hormone is secreted by the beta cells of the pancreas in response to high blood sugar levels (such as after eating). It lowers blood glucose by stimulating its uptake into cells (via GLUT-4 translocation) and promoting glycogenesis—the storage of excess glucose as glycogen in the liver and skeletal muscles.

• Glucagon: Produced by the alpha cells of the pancreas, glucagon has the exact opposite effect. It is released during fasting or low blood sugar states to trigger the liver to break glycogen back down into glucose (glycogenolysis).
• Epinephrine & Norepinephrine: Known as catecholamines, these stress hormones stimulate the breakdown of glycogen to rapidly elevate blood glucose levels for immediate energy during a fight-or-flight response.', '["insulin","glucagon","epinephrine","norepinephrine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:57:19.064Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:57:19.064Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T12:57:19.240Z"'::jsonb),
('anki-card-1758786534435-3', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The site of most ATP synthesis in cells. *', 'mitochondria', '', '["mitochondria","nucleus","Golgi apparatus","peroxisomes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T05:31:21.600Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T05:31:21.600Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T05:31:21.600Z"'::jsonb),
('anki-card-1758787551405-51', 'anki-deck-1783610488281-1790433142627-pf2m5', 'An average sedentary individual expends roughly ____ of his/her total caloric intake on physical activity. *', '30%', '', '["15%","25%","30%","35%"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T06:50:07.745Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-30T06:50:07.745Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T06:50:07.745Z"'::jsonb),
('anki-card-1758787476858-46', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Large lipids such as monoglycerides and long-chain fatty acids must first merge into ____ before their absorption and transport. *', 'micelles', '', '["micelles","chylomicron","LDL","HDL"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-02T07:06:37.383Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-29T07:06:37.383Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-29T07:06:37.460Z"'::jsonb),
('anki-card-1758787283917-35', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Your patient has a poorly healing wound, numerous recurring infections, dry scaly skin, and a complaint that food is tasteless. This patient most likely has a deficiency of: *', 'zinc', '', '["iron","phosphorus","zinc","copper"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T06:46:52.430Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T06:46:52.430Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-30T06:46:52.430Z"'::jsonb),
('anki-card-1758787268968-34', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A patient with keratinized goosebump-like skin and a keratinized cornea (Bitot’s spots) has trouble seeing in the dark. The biochemical deficiency most likely related to loss of vision in the dark is in the: *', 'generation of all-trans retinal', 'The triad of keratinized "goosebump-like" skin (phrynoderma), keratinized conjunctival debris (Bitot''s spots), and difficulty seeing in dim light (nyctalopia/night blindness) represents a classic, textbook presentation of Vitamin A (retinol) deficiency.

Vitamin A is an essential precursor for the visual pigments in the retina. Inside the photoreceptor cells (rods), 11-cis retinal binds to the protein opsin to form rhodopsin.

When light hits the rod cells, 11-cis retinal absorbs the photon and undergoes a photochemical isomerization, converting into all-trans retinal. This precise shape change activates rhodopsin, triggering the nerve impulses sent to the brain that allow us to see in the dark. A chronic lack of vitamin A impairs the continuous recycling and generation of these retinal isomers, directly causing night blindness.

• gamma carboxylation: This describes the biochemical mechanism of Vitamin K, which activates clotting factors, not Vitamin A.
• alpha-tocopherol: This is the chemical name for Vitamin E. While it is a fat-soluble vitamin, a deficiency causes neurological issues and hemolytic anemia, not Bitot''s spots.
• Zinc absorption: While zinc deficiency can secondary impair vitamin A mobilization from the liver, the explicit biochemical failure directly responsible for the loss of night vision is the visual cycle''s failure to generate the retinal pigment.', '["absorption of zinc","absorption of alpha-tocopherol","gamma carboxylation of glutamate residues","generation of all-trans retinal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:38:39.967Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:38:39.967Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-20T15:38:40.057Z"'::jsonb),
('anki-card-1758786937414-24', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The rate-limiting step in glycolysis is: *', 'the phosphorylation of fructose 6-phosphate', 'The conversion of fructose 6-phosphate to fructose 1,6-bisphosphate is the key committed, irreversible, and rate-limiting step of glycolysis. This highly regulated step is catalyzed by the enzyme phosphofructokinase-1 (PFK-1). PFK-1 controls the overall speed of the pathway and is sensitive to the energy demands of the cell (inhibited by ATP and citrate, activated by AMP and fructose 2,6-bisphosphate).

• Isomerization of Glucose 6-phosphate: This is Step 2 of glycolysis catalyzed by phosphoglucose isomerase. It is a freely reversible reaction and is not a major regulatory or rate-limiting point.
• Breakdown of Glycogen: This process is called glycogenolysis and occurs before glycolysis can begin when using stored carbohydrates. Its rate-limiting enzyme is glycogen phosphorylase, which belongs to a separate metabolic pathway altogether.
• Phosphorylation of Glucose: This is Step 1 of glycolysis, catalyzed by hexokinase or glucokinase. While it is an irreversible, regulatory step that traps glucose inside the cell, it is not the primary rate-limiting step because glucose 6-phosphate can still leave the glycolytic pathway to enter other loops, such as the pentose phosphate pathway or glycogen synthesis.', '["the breakdown of glycogen","the phosphorylation of glucose","the isomerization of glucose 6-phosphate to fructose 6-phosphate","the phosphorylation of fructose 6-phosphate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:51:11.873Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:51:11.873Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T12:51:11.873Z"'::jsonb),
('anki-card-1758786921233-23', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The fatty acid most commonly found in animal fats: *', 'stearic acid', '', '["linoleic acid","stearic acid","palmitic acid","myristic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-02T13:35:24.818Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-29T13:35:24.818Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-09-29T13:35:24.898Z"'::jsonb),
('anki-card-1758786516134-1', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Organelle in the cell where protein and lipid synthesis take place. *', 'endoplasmic reticulum', 'The endoplasmic reticulum (ER) is a continuous network of membranes divided into two functionally distinct areas that handle biosynthesis:
	• Rough ER: Studded with ribosomes, it is the primary site where protein synthesis and structural folding take place.
	• Smooth ER: Lacks ribosomes and contains specialized enzymes responsible for lipid synthesis (including phospholipids and cholesterol), steroid hormone production, and carbohydrate metabolism.

• Golgi apparatus: Acts as the cell''s shipping center. It does not synthesize proteins or lipids from scratch; instead, it modifies, sorts, and packages the proteins and lipids received from the ER.
• Nucleus: Serves as the control center containing the cell''s genetic blueprint (DNA). It is the site for DNA replication and transcription (RNA synthesis), not translation or lipid manufacturing.
• Mitochondria: Known as the powerhouse of the cell, its primary function is generating energy in the form of ATP via aerobic cellular respiration.', '["nucleus","endoplasmic reticulum","Golgi apparatus","mitochondria"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:54:35.038Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:54:35.038Z"'::jsonb, '"2026-09-26T14:32:29.989Z"'::jsonb, '"2026-10-21T12:54:35.213Z"'::jsonb),
