('anki-card-1758686165819-167', 'anki-deck-1783608782087-1790433140508-zgaqi', 'Collecting information on whether the right target group has been reached by the project is part of a/an _______ evaluation. *', 'process', '', '["outcome","impact","process","summative"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
