('anki-card-1758686184419-169', 'anki-deck-1783608782087-1790433140508-zgaqi', 'These factors are useful in choosing a nutrition intervention: I.Ease of targeting; II.Relevance; III.Available manpower; IV. Cost benefit *', 'I, II, and IV', '', '["I, II, and III","I, III, and IV","I, II, and IV","II, III, and IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
