('anki-card-1757480894967-116', 'anki-deck-1783608850772-1790433142618-6p547', 'Potent hormone like unsaturated fatty acids that act in extremely low concentrations on local target organs; protects the integrity of the GIT epithelium against noxious substances.', 'Prostaglandins', '', '["Lactoperoxidase","Prostaglandins","Complement","Interferon"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.247Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
