('anki-card-1757480712179-114', 'anki-deck-1783608850772-1790433142618-6p547', 'A compound with a monilla-static effect agains Candida albicans; Inhibit growth of staphyloccoci and E. coli by binding iron that the bacteria require to grow and inhibits bacterial multiplication.', 'Lactoferrin', '', '["Bilidusfactor","Secretory immunoglobulin","Antistaphylococcus factor","Lactoferrin"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.247Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
