('anki-card-1757480599631-112', 'anki-deck-1783608850772-1790433142618-6p547', 'Immunoglobulins are special components of the body''s immune system, proteins synthesized by lymphocytes, and plasma cells that have specific antibody activity; Act against bacterial invasion of the mucosa and colonization of the gut.', 'Secretory immunoglobulin', '', '["Bilidusfactor","Secretory immunoglobulin","Antistaphylococcus factor","Lactoferrin"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.247Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
