INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1756362804907-190', 'anki-deck-1756357465257-1790432463920-rf85m', 'Lactose intolerance is due to:', 'lactase deficiency', 'Lactose intolerance occurs when there is insufficient lactase, the brush-border enzyme responsible for breaking down lactose into its absorbable monosaccharides, glucose and galactose. When lactose is not adequately digested in the small intestine, it reaches the colon, where gut bacteria ferment it and produce gases and other metabolites. The resulting osmotic effect and fermentation can cause bloating, abdominal pain, flatulence, and diarrhea after consuming lactose-containing foods.', '["inflammation of gastric mucosa","lactase deficiency","milk allergy","Hyperacidity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:26:05.991Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:26:05.991Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-21T15:26:05.991Z"'::jsonb),
('anki-card-1756362885537-195', 'anki-deck-1756357465257-1790432463920-rf85m', 'Food to emphasize when it is necessary to increase potassium:', 'Fruits', 'Fruits are generally good sources of potassium and are commonly emphasized when increasing dietary potassium. Examples include banana, oranges, melon, papaya, avocado, and dried fruits. Potassium is an important intracellular electrolyte involved in nerve transmission, muscle contraction, and maintenance of normal cardiac function. However, potassium intake should be individualized because patients with chronic kidney disease, hyperkalemia, or certain medications may instead require potassium restriction. 

Starchy roots such as potatoes and sweet potatoes can also provide substantial potassium, so they are not inherently poor choices. However, among the options, fruits are the most appropriate general food group to emphasize when the goal is to increase potassium intake.', '["Fruits","Cream","starchy roots","cereals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T13:33:21.828Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T13:33:21.828Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-21T13:33:21.828Z"'::jsonb),
('anki-card-1756362772508-188', 'anki-deck-1756357465257-1790432463920-rf85m', 'A mechanical soft diet includes:', 'easy to chew foods, including foods in the regular diet', 'A mechanical soft diet consists of foods that are soft in texture and easy to chew and swallow, with modification of the texture achieved through methods such as chopping, grinding, mashing, or cooking foods until tender. The goal is to reduce the mechanical effort required to chew food while still allowing a broader variety of foods than a full-liquid or pureed diet. Depending on the patient''s needs, foods from a regular diet can be modified to achieve the appropriate texture. 

A mechanical soft diet is therefore primarily defined by texture and ease of chewing, not by whether foods are liquid or low in fiber. It may be prescribed for patients with difficulty chewing because of dental problems, oral surgery, weakness, or other conditions affecting chewing. The specific texture should always be matched to the patient''s swallowing ability because a mechanical soft diet is not automatically appropriate for someone with dysphagia.', '["soft foods","liquid foods","easy to chew foods, including foods in the regular diet","low fiber foods"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:14:14.023Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:14:14.023Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:14:14.023Z"'::jsonb),
('anki-card-1756362839988-192', 'anki-deck-1756357465257-1790432463920-rf85m', 'A dietary risk factor of coronary artery disease is high intake of:', 'saturated fat', 'Elevated dietary intake of saturated fatty acids and industrial trans-fats increases serum low-density lipoprotein cholesterol (LDL-C) and arterial inflammation, a major independent risk factor for coronary artery disease.', '["polyunsaturated fat","monounsaturated fat","saturated fat","cis-fatty acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T15:18:11.897Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T15:18:11.897Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-21T15:18:11.897Z"'::jsonb),
('anki-card-1756362823839-191', 'anki-deck-1756357465257-1790432463920-rf85m', 'Fats are generally restricted in diseases of the liver because:', 'All of the above', 'In chronic liver diseases, fat restriction is indicated because damaged hepatocytes exhibit impaired bile acid synthesis/secretion for micelle formation, and impaired beta-oxidation can exacerbate hepatic steatosis.', '["impaired production and transport of bile","fat metabolism may be impaired and result in fatty liver","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:31:36.220Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:31:36.220Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:31:36.220Z"'::jsonb),
('anki-card-1756360451789-101', 'anki-deck-1756357465257-1790432463920-rf85m', 'The RQ of glucose is:', '1', 'The respiratory quotient (RQ) is the ratio of the amount of carbon dioxide (CO₂) produced to oxygen (O₂) consumed during the oxidation of a nutrient. For carbohydrate, specifically glucose: C6​H12​O6 ​+ 6O2 ​→ 6CO2 ​+ 6H2​O Therefore: RQ = 6CO2 ​÷ 6O2 ​= 1.0 Thus, the RQ of glucose is 1.0.

RQ values differ according to the macronutrient being oxidized: 
• Carbohydrate = 1.0 
• Protein ≈ 0.8 
• Fat = 0.7 
• Mixed diet ≈ 0.8–0.9 

This concept is important in indirect calorimetry, which estimates energy expenditure by measuring oxygen consumption and carbon dioxide production.', '["1","0.9","0.8","0.7"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:35:40.780Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:35:40.780Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:35:40.780Z"'::jsonb),
('anki-card-1756362937619-198', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following are conditions that resulted from vitamin C deficiency?
I. Beriberi, confusion, depression, convulsions, scurvy 
II. Microcytic anemia, bleeding gums, loosened teeth, scurvy 
III. Rashes, hair loss, microcytic anemia, bleeding gums 
IV. Confusion, convulsions, loosened teeth, scurvy, hair loss', 'II only', 'Vitamin C deficiency causes scurvy, characterized by impaired collagen synthesis and connective-tissue abnormalities. Classic manifestations include bleeding or swollen gums, loose teeth, poor wound healing, petechiae/ecchymoses, and fatigue. Vitamin C also enhances non-heme iron absorption, so deficiency can contribute to anemia; however, the anemia associated with vitamin C deficiency is not necessarily microcytic, and may be related to impaired iron absorption and blood loss.

Among the choices, Statement II is the best match because it contains the classic manifestations of scurvy.', '["I only","II only","II and III only","I and IV only"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:38:42.400Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-04T11:38:42.400Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:38:42.400Z"'::jsonb),
('anki-card-1756361368928-142', 'anki-deck-1756357465257-1790432463920-rf85m', 'The average respiratory quotient of a mixed diet:', '0.85', 'The respiratory quotient (RQ) is the ratio of carbon dioxide produced to oxygen consumed during metabolism: RQ = VCO₂ / VO₂. The RQ differs according to the macronutrient being oxidized. Carbohydrate has an RQ of 1.0, protein approximately 0.8, and fat approximately 0.7. Because a typical mixed diet supplies a combination of carbohydrate, protein, and fat, its average RQ is approximately 0.8–0.85, with 0.85 being the conventional value used in nutrition and indirect calorimetry questions.', '["0.65","0.85","0.75","0.95"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T13:18:54.309Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T13:18:54.309Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-21T13:18:54.309Z"'::jsonb),
('anki-card-1756362871587-194', 'anki-deck-1756357465257-1790432463920-rf85m', 'The conservative management of chronic kidney disease which is characterized by progressive and irreversible destruction of nephrons consists of:', 'diet and drugs', 'Conservative management of chronic kidney disease (CKD) aims to slow disease progression, manage complications, and maintain quality of life without renal replacement therapy. It includes appropriate dietary management and pharmacologic treatment, along with control of blood pressure, diabetes, cardiovascular risk factors, electrolyte and acid-base abnormalities, anemia, and other complications. Nutrition therapy may involve individualized adjustments to protein, sodium, potassium, phosphorus, and energy intake depending on the CKD stage and laboratory findings. 

Dialysis and kidney transplantation are forms of kidney replacement therapy, not conservative management. Importantly, conservative management is not simply “diet only”; medications and comprehensive medical management are integral.', '["diet only","diet and drugs","dialysis","kidney transplant"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:11:32.061Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:11:32.061Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-21T14:11:32.061Z"'::jsonb),
('anki-card-1756360594665-108', 'anki-deck-1756357465257-1790432463920-rf85m', 'The normal protein requirement of a Filipino adult.', '1g/KDBW', 'For Philippine nutrition assessment and meal planning, the commonly used reference for the protein requirement of a healthy Filipino adult is approximately 1.0–1.1 g/kg body weight per day, depending on the reference and individual circumstances.

Protein needs are not identical for everyone. Requirements may increase during pregnancy, lactation, older age, intense physical activity, illness, trauma, and other conditions associated with increased protein needs. For clinical nutrition, the appropriate weight basis and protein target should be individualized.', '["1g/KDBW","5g/KDBW","2g/KDBW","3g/KDBW"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T09:36:16.535Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T09:36:16.535Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-22T09:36:16.535Z"'::jsonb),
('anki-card-1756360633795-110', 'anki-deck-1756357465257-1790432463920-rf85m', 'A diet prescription of 1800 kcal with distribution of C 60% P 15% F 25% will provide:', 'C 270 g, P 70 g, F 50 g', 'To calculate the grams of each macronutrient: 

1. Carbohydrate 
Carbohydrate provides 4 kcal/g: 
CHO: 60% → 1,080 kcal ÷ 4 = 270 g 

2. Protein 
Protein provides 4 kcal/g:
Protein: 15% → 270 kcal ÷ 4 = 67.5 g → 70 g 
Using the rounding convention applied in this question, 67.5 g is rounded to 70 g. 

3. Fat 
Fat provides 9 kcal/g: 
Fat: 25% → 450 kcal ÷ 9 = 50 g 

Therefore, the prescribed diet provides approximately 270 g carbohydrate, 70 g protein, and 50 g fat.', '["C 270 g, P 70 g, F 50 g","C 275 g, P 67.5g, F 50 g","C 275 g, P 70 g, F 50 g","C 270 g, P 70 g, F 55 g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T14:26:03.285Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T14:26:03.285Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-10-21T14:26:03.285Z"'::jsonb),
('anki-card-1756360705175-114', 'anki-deck-1756357465257-1790432463920-rf85m', 'A physician ordered 1500 kcal tube feeding formula, 1.5:1 dilution every 4 hours. The volume per feeding is:', '167 mL/feed', 'First, determine the total volume of formula required: (1500 kcal ÷ 1.5 kcal/mL) = 1000 mL 

Since feeding is given every 4 hours, the patient receives: 24 ÷ 4 = 6 feedings / day 

Therefore: 1000 mL ÷ 6 = 166.7 mL / feed 
Rounded to the nearest whole number: 167 ml / feed', '["167 mL/feed","250 mL/feed","150 mL/feed","300 mL/feed"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:11:53.184Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:11:53.184Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:11:53.184Z"'::jsonb),
('anki-card-1756360613330-109', 'anki-deck-1756357465257-1790432463920-rf85m', 'Most of the body''s energy needs is provided by:', 'Glucose and fatty acids', 'Under normal resting and post-absorptive physiological states, cellular energy is predominantly generated through the aerobic oxidation of glucose and free fatty acids.', '["Fats and proteins","Vitamins and minerals","Glucose and fatty acids","Glycerol and amino acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:40:04.566Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:40:04.566Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:40:04.566Z"'::jsonb),
('anki-card-1756360689143-113', 'anki-deck-1756357465257-1790432463920-rf85m', 'A primary feature of emphysema is:', 'destruction of the walls separating the alveoli', 'Emphysema is a form of COPD characterized by abnormal and permanent enlargement of airspaces distal to the terminal bronchioles, accompanied by destruction of alveolar walls and loss of the normal elastic recoil of the lungs. 

Destruction of the alveolar walls reduces the surface area available for gas exchange and causes neighboring alveoli to merge into larger, less efficient air spaces. Loss of elastic recoil also contributes to air trapping and difficulty exhaling, particularly during forced expiration.

This distinguishes emphysema from chronic bronchitis, in which chronic airway inflammation and excessive mucus production are more prominent features.', '["obstruction within the bronchi","obstruction within the bronchioles","destruction of the walls separating the alveoli","excessive lung elasticity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:38:22.927Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:38:22.927Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:38:22.927Z"'::jsonb),
('anki-card-1756360561799-106', 'anki-deck-1756357465257-1790432463920-rf85m', 'A dialysis patient was prescribed 55 grams protein per day. The amount of HBV should be at least:', '33 grams', 'In chronic dialysis patients (hemodialysis or peritoneal dialysis), clinical practice guidelines recommend that at least 50% to 60% of total dietary protein be of High Biological Value (HBV). 60% of 55 g = 33 grams.', '["41 grams","33 grams","39 grams","66 grams"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:32:01.614Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:32:01.614Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:32:01.614Z"'::jsonb),
('anki-card-1756362854708-193', 'anki-deck-1756357465257-1790432463920-rf85m', 'Dietary fibers are useful in preventing hypercholesterolemia because they:', 'bind cholesterol containing bile acids which are eventually excreted', 'Certain soluble, viscous dietary fibers can help lower blood LDL cholesterol by increasing the excretion of bile acids and cholesterol in the feces. The liver must use circulating cholesterol to synthesize new bile acids, thereby increasing hepatic demand for cholesterol and contributing to lower LDL cholesterol concentrations. Examples of cholesterol-lowering soluble fibers include β-glucan from oats and barley, psyllium, and some fibers from legumes. The original wording is somewhat simplified because fiber does not literally “bind cholesterol-containing bile acids” in every case; increased bile acid excretion and fermentation-related mechanisms both contribute.', '["bind cholesterol containing bile acids which are eventually excreted","produce HDL cholesterol","are antioxidants","carriers of omega 3-fatty acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:32:45.133Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:32:45.133Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:32:45.133Z"'::jsonb),
('anki-card-1756362904486-196', 'anki-deck-1756357465257-1790432463920-rf85m', 'The C P F and kcal value of a breakfast containing 2 rice B exchanges, 2 medium fat exchanges, and 1 fruit exchange.', 'C 56g P 20 g F 12 g E 412 kcal', 'Using the Philippine Food Exchange List (FEL), here is the exact step-by-step breakdown of the computation.

1. Rice B (2 exchanges):
	• Carbohydrates: 2 x 23g = 46g
	• Protein: 2 x 2g = 4g
	• Fat: 0g
	• Calories: 2 x 100 kcal = 200 kcal

2. Medium-Fat Meat (2 exchanges):
	• Carbohydrates: 0g
	• Protein: 2 x 8g = 16g
	• Fat: 2 x 6g = 12g
	• Calories: 2 x 86 kcal = 172 kcal

3. Fruit (1 exchange):
	• Carbohydrates: 1 x 10g = 10g
	• Protein: 0g
	• Fat: 0g
	• Calories: 1 x 40 kcal = 40 kcal

Grand Totals:
	• Carbohydrates: 46g + 0g + 10g = 56 grams
	• Protein: 4g + 16g + 0g = 20 grams
	• Fat: 0g + 12g + 0g = 12 grams
	• Energy: 200 + 172 + 40 = 412 kcal

Verifying the Math with Atwater Multipliers:
• Carbohydrates: 56g x 4 kcal/g = 224 kcal
• Protein: 20g x 4 kcal/g = 80 kcal
• Fat: 12g x 9 kcal/g = 108 kcal
• Total Energy: 224 + 80 + 108 = 412 kcal', '["C 46 g P 16 g F 10g E 338 kcal","C 56 g P 16 g F 6 g E 342 kcal","C 46 g P 20 g F 10 g E 354 kcal","C 56g P 20 g F 12 g E 412 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:04:50.960Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:04:50.960Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:04:50.960Z"'::jsonb),
('anki-card-1756360436873-100', 'anki-deck-1756357465257-1790432463920-rf85m', 'The following are functions of sodium, except:', 'Participation in detoxification reactions', 'Sodium is the major extracellular cation and plays an important role in maintaining extracellular fluid volume and osmotic balance. It is also essential for nerve impulse transmission and muscle contraction through its role in generating membrane potentials. Sodium-dependent transporters in the intestinal epithelium also facilitate the absorption of glucose and other nutrients, such as certain amino acids. 

However, detoxification reactions are not a primary function of sodium. Detoxification involves processes primarily carried out by the liver, including enzymatic reactions such as oxidation, reduction, hydrolysis, and conjugation.', '["Maintenance of normal extracellular fluid balance","Participation in detoxification reactions","Nerve impulse transmission and muscular contraction","Absorption of glucose and transport of other nutrients"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-11T11:32:10.735Z","interval":7,"easeFactor":2.3,"repetitions":3}'::jsonb, '"2026-11-04T11:32:10.735Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:32:10.735Z"'::jsonb),
('anki-card-1756362674847-182', 'anki-deck-1756357465257-1790432463920-rf85m', 'A sensible weight reducing program includes:', 'diet, exercise and behavior modification', 'Comprehensive and evidence-based weight management requires a sustainable multidisciplinary approach incorporating modest caloric restriction (diet), regular physical activity (exercise), and cognitive behavioral therapy (behavior modification).', '["drugs to effect rapid weight loss","use of formula diets to ensure appropriate calorie intake","use of herbal preparations as an adjunct to diet","diet, exercise and behavior modification"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:07:13.557Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:07:13.557Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:07:13.557Z"'::jsonb),
('anki-card-1756360649362-111', 'anki-deck-1756357465257-1790432463920-rf85m', 'What is the total protein requirement/day of a 7-year-old child using NPC method?', '44 grams/day', 'Using the NPC method, first determine the child''s desirable body weight (DBW): 

DBW = (age in years * 2) + 8 
For a 7-year-old: DBW = (7 * 2) + 8 = 22 kg 

Using the 2.0 g protein/kg DBW/day recommendation from the NDAP Diet Manual, 5th edition: CHON req’t = DBW * 2.0 g/kgDBW 

Therefore, the child''s total protein requirement is 44 g/day. This question is specifically testing the clinical computation convention used in the NDAP Diet Manual, rather than asking for the current general population protein RDA/RNI.', '["20 grams/day","24.2 grams/day","33 grams/day","44 grams/day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:15:43.999Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:15:43.999Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:15:43.999Z"'::jsonb),
('anki-card-1756362614717-179', 'anki-deck-1756357465257-1790432463920-rf85m', 'During aerobic respiration, the decomposition of one glucose molecule produces:', '38 molecules of ATP', 'Using the traditional biochemical calculation commonly taught in nutrition and NDLE review materials, the complete aerobic oxidation of one glucose molecule produces a maximum of 38 ATP. 

This calculation assigns 3 ATP per NADH and 2 ATP per FADH₂. Glycolysis produces 2 ATP and 2 NADH; pyruvate oxidation produces 2 NADH; and the TCA cycle produces 2 ATP (or GTP), 6 NADH, and 2 FADH₂. Altogether, this gives 38 ATP per glucose under the traditional accounting system.', '["40 molecules of ATP","46 molecules of ATP","38 molecules of ATP","48 molecules of ATP"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:07:44.991Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:07:44.991Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:07:44.991Z"'::jsonb),
('anki-card-1756362268798-162', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is/are not true about dietary management of diabetes mellitus?
I. The type of carbohydrate is more important than the total amount of carbohydrates
II. The total amount of carbohydrate consumed is more important than the source of carbohydrate
III. People with diabetes mellitus can eat candies and other sugary foods.', 'I only', 'Statement I is NOT true because, in diabetes management, the total amount of carbohydrate consumed is a major determinant of postprandial blood glucose, particularly when considering carbohydrate counting and matching carbohydrate intake with insulin or other glucose-lowering therapy. The type and quality of carbohydrate are also important because fiber content, degree of processing, and food composition can affect the glycemic response, but carbohydrate type is not generally considered more important than the total amount consumed. Thus, saying that type is more important than total amount is an inaccurate statement. 

Statement II is considered true in the context of the fundamental principle of carbohydrate management: the amount of carbohydrate consumed has a substantial and predictable effect on blood glucose. This does not mean that carbohydrate source is unimportant; whole grains, legumes, vegetables, fruits, and other minimally processed carbohydrate-rich foods are generally preferred over highly refined foods and foods high in added sugars because of their fiber and nutrient content. 

Statement III is also true because people with diabetes do not have to completely eliminate candies and other sugary foods. These can be incorporated occasionally into an individualized meal plan, provided that carbohydrate and overall energy intake are appropriately managed.', '["I only","III only","Both II & III","Both I & II"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:37:27.304Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-04T11:37:27.304Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:37:27.304Z"'::jsonb),
('anki-card-1756361453258-145', 'anki-deck-1756357465257-1790432463920-rf85m', 'The main goal of the Krebs cycle is to produce H⁺ and electrons. These by-products are then transferred to the:', 'Electron Transport Chain', 'The Krebs cycle (citric acid cycle/TCA cycle) does not directly produce large amounts of ATP. Its major role is to oxidize acetyl-CoA and capture energy in the form of the reduced electron carriers NADH and FADH₂. These carriers transport high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, energy is used to pump H⁺ across the inner mitochondrial membrane, creating a proton gradient that drives ATP synthesis through oxidative phosphorylation. 

For NDLE purposes, the wording “H⁺ and electrons” is a little imprecise. The Krebs cycle primarily produces NADH and FADH₂, which carry the high-energy electrons to the ETC. The Krebs cycle also contributes indirectly to proton generation through subsequent oxidative phosphorylation, but free H⁺ is not its principal product.', '["Embden-Meyerhoff Pathway","Electron Transport Chain","Citric Acid Cycle","Cori Cycle"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:38:51.985Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-04T11:38:51.985Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:38:51.985Z"'::jsonb),
('anki-card-1756361329748-140', 'anki-deck-1756357465257-1790432463920-rf85m', 'It is formed when two amino acids are bonded together:', 'Dipeptide', 'A dipeptide is formed when two amino acids are joined by a peptide bond. This occurs through a condensation (dehydration) reaction in which the carboxyl group of one amino acid reacts with the amino group of another, releasing one molecule of water. The resulting molecule contains two amino acid residues linked by one peptide bond. 

For NDLE purposes, remember the progression: 
2 amino acids = dipeptide; 3 amino acids = tripeptide; several amino acids = oligopeptide; long chains = polypeptide/protein. 

The number of peptide bonds is also important: two amino acids form one peptide bond, three amino acids form two peptide bonds, and so forth.', '["Alanine","Dissacharide","Protein","Dipeptide"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:40:25.120Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:40:25.120Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:40:25.120Z"'::jsonb),
('anki-card-1756360861451-121', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following statements is TRUE?', 'Evaporated milk has higher cholesterol content than lean fish', 'Evaporated milk is an animal-derived food and therefore contains cholesterol. Based on the food-composition values used in the original question, its cholesterol content is higher than that of lean meat when compared using the specified serving/reference amounts. The question is testing the ability to compare cholesterol content among commonly consumed foods, rather than simply identifying whether a food contains cholesterol. 

"Vegetables have a higher cholesterol content than fruits" is false because plant foods do not contain cholesterol. Vegetables and fruits naturally contain zero dietary cholesterol. 

"Shrimp has a higher cholesterol content than butter" should also not be selected based simply on the fact that shrimp is recognized as relatively high in cholesterol. Cholesterol comparisons must be made using the same reference/serving basis in the food-composition table.', '["Evaporated milk has higher cholesterol content than lean fish","Vegetable has higher cholesterol content as compared to fruits","Shrimp has higher cholesterol content than butter","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-05T11:10:26.357Z","interval":1,"easeFactor":2.1,"repetitions":0}'::jsonb, '"2026-11-04T11:10:26.357Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:10:26.357Z"'::jsonb),
('anki-card-1756360787739-118', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following is a free food?', 'Tea', 'In clinical dietetics and food exchange systems, a free food is defined as any food or beverage that contains negligible amounts of macronutrients—specifically less than 20 calories and 5 grams or less of carbohydrates per serving.

Unsweetened black, green, or herbal tea is virtually calorie-free and carbohydrate-free. Because it does not cause any significant spike in blood glucose or daily caloric intake, it can be consumed freely by patients (such as those managing diabetes or weight) without needing to be calculated or swapped out in a meal plan.', '["Peanut brittle","Soft drinks","Tea","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:10:32.282Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:10:32.282Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:10:32.282Z"'::jsonb),
('anki-card-1756361161771-133', 'anki-deck-1756357465257-1790432463920-rf85m', 'A low phosphorous diet contains less than ___ mg phosphorous', '1000 mg', 'For traditional renal diet-therapy teaching, a low-phosphorus diet is generally defined as providing less than 800–1,000 mg phosphorus per day, with the exact prescription individualized according to renal function, serum phosphorus, dietary protein requirements, and dialysis status. Therefore, among the choices given, less than 1,000 mg/day is the best answer.', '["1000 mg","1200 mg","1400 mg","1600 mg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:11:19.858Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:11:19.858Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:11:19.858Z"'::jsonb),
('anki-card-1756362505171-173', 'anki-deck-1756357465257-1790432463920-rf85m', 'Which of the following meats has the lowest kilocalories from fat per serving?', 'Chicken leg', 'Among these choices, chicken leg generally provides the lowest amount of fat-derived energy per standard serving when compared with pork pata, chicken wings, and Vienna sausage. Chicken leg is a relatively nutrient-dense source of protein, although its fat content varies depending on whether the skin is consumed and the specific cut and preparation method. Removing the skin substantially reduces its fat and total energy content. 

Pork pata and chicken wings tend to contain more fat per edible serving, while Vienna sausage is a processed meat product that commonly contains a relatively high proportion of fat. For nutrition assessment and meal planning, it is important to consider the edible portion, preparation method, skin, and processing because these can substantially alter the fat and energy content of meat products.', '["Pork pata","Chicken leg","Chicken wings","Vienna sausage"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:12:45.806Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:12:45.806Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:12:45.806Z"'::jsonb),
('anki-card-1756362921734-197', 'anki-deck-1756357465257-1790432463920-rf85m', 'All measures are allowed to increase the energy intake of renal patient except:', 'serving fruit cocktail with heavy syrup', 'When a renal patient requires increased energy intake, particularly when protein, potassium, phosphorus, or fluid may need to be controlled, energy can be increased by using calorie-dense foods that provide relatively little protein and minerals. Adding sugar, oil, and unsalted margarine can increase energy density without substantially increasing protein. 

In contrast, fruit cocktail with heavy syrup may be inappropriate depending on the patient''s potassium and fluid restrictions; canned fruits may also contribute substantial potassium, and the syrup contributes mainly sugar rather than being a particularly useful renal nutrition strategy.', '["using additional sugar in foods","preparing foods with oil","adding unsalted margarine","serving fruit cocktail with heavy syrup"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:14:04.202Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:14:04.202Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:14:04.202Z"'::jsonb),
('anki-card-1756360669027-112', 'anki-deck-1756357465257-1790432463920-rf85m', 'A BMI of 23 kg/m² according to the Asia-Pacific classification is considered:', 'Overweight', 'The Asia-Pacific BMI classification uses lower BMI cutoffs for overweight and obesity compared with the standard WHO classification because Asian populations may have a higher risk of type 2 diabetes and cardiovascular disease at lower BMI values. 

Under the Asia-Pacific classification: 
• <18.5 kg/m² → Underweight 
• 18.5–22.9 kg/m² → Normal 
• 23.0–24.9 kg/m² → Overweight 
• 25.0–29.9 kg/m² → Obese I 
• ≥30.0 kg/m² → Obese II 

Therefore, a BMI of 23 kg/m² is classified as overweight.', '["Normal","Overweight","Obese","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:14:09.979Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:14:09.979Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:14:09.979Z"'::jsonb),
('anki-card-1756361741563-157', 'anki-deck-1756357465257-1790432463920-rf85m', 'The second stage of carbohydrate metabolism which takes place in the mitochondria and requires oxygen.', 'Oxidative decarboxylation', 'In nutritional biochemistry and board examination frameworks, aerobic carbohydrate catabolism is traditionally classified into sequential stages:
	1. Stage 1: Glycolysis (anaerobic process taking place entirely in the cytoplasm).
	2. Stage 2: Oxidative decarboxylation (the transition phase moving into the Krebs cycle/TCA cycle).
	3. Stage 3: Oxidative phosphorylation via the Electron Transport Chain (ETC).

Once glycolysis yields pyruvate in the cytosol, the pyruvate is actively transported into the mitochondria. Here, the pyruvate dehydrogenase complex carries out oxidative decarboxylation, converting pyruvate into Acetyl-CoA while stripping away carbon dioxide and generating NADH. Because this pathway feeds directly into the aerobic respiration chain, it strictly requires oxygen to proceed.

• Glycolysis: This is the first stage of carbohydrate breakdown. It takes place in the anaerobic environment of the fluid cytoplasm (cytosol), meaning it does not require oxygen or mitochondrial machinery to function.
• Hexose monophosphate shunt: Also known as the Pentose Phosphate Pathway (PPP), this is an alternative pathway parallel to glycolysis used to generate NADPH and ribose 5-phosphate. It does not serve as the primary second stage of energy-yielding glucose metabolism.
• Oxidative phosphorylation: This is the final (third) stage of cellular respiration where the vast majority of ATP is structurally synthesized by ATP synthase along the inner mitochondrial membrane.', '["Oxidative decarboxylation","Oxidative phosphorylation","Hexose manophasphate shunt","Glycolysis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:14:29.324Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-04T11:14:29.324Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:14:29.324Z"'::jsonb),
('anki-card-1756361517538-149', 'anki-deck-1756357465257-1790432463920-rf85m', 'The enzyme pepsin is not denatured in the stomach despite the very acidic environment due to hydrochloric acid (HCl). How can this be?', 'Pepsin is secreted in its precursor form, pepsinogen', 'The stomach avoids auto-digestion and protects its own mucosal lining from premature proteolysis (protein breakdown) by not secreting active pepsin directly. Instead, gastric chief cells synthesize and secrete pepsinogen, which is an inactive precursor or zymogen.

Once pepsinogen enters the gastric lumen, the strongly acidic environment created by hydrochloric acid (HCl) causes the protein chain to unfold. This allows pepsinogen to cleave itself, initiating its conversion into the active, functional enzyme pepsin precisely where it is needed to digest dietary proteins.', '["Pepsin is the only protein enzyme that functions best in an acidic environment","Pepsin is able to resist denaturation by increasing the pH within the stomach, making it less acidic","Pepsin is also digested along with other proteins in the stomach","Pepsin is secreted in its precursor form, pepsinogen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:15:02.101Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:15:02.101Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:15:02.101Z"'::jsonb),
('anki-card-1756362740493-186', 'anki-deck-1756357465257-1790432463920-rf85m', 'Some clinicians recommend egg whites as the sole source of protein for patients with renal failure because:', 'egg white protein has the highest biological value', 'Egg white is considered a high-quality protein because it contains all the essential amino acids in proportions that support human protein needs and has high protein quality. 

In patients with chronic kidney disease (CKD), when protein intake is restricted or carefully prescribed, choosing high-quality protein sources can help provide adequate essential amino acids while limiting the total amount of protein consumed. Egg white is also relatively low in phosphorus compared with the whole egg because most of the egg''s phosphorus is found in the yolk. 

However, egg whites should not routinely be considered the sole protein source for every patient with renal failure. Current CKD nutrition care emphasizes individualized protein and energy prescriptions according to CKD stage, dialysis status, nutritional status, and other clinical factors. Patients receiving dialysis generally have higher protein requirements than patients with non-dialysis CKD. The key concept tested here is high protein quality/biological value, not a therapeutic effect unique to egg white.', '["egg whites are the most acceptable protein source","they have a therapeutic effect","egg white protein has the highest biological value","other proteins are harmful"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-07T11:15:18.795Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-04T11:15:18.795Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:15:18.795Z"'::jsonb),
('anki-card-1756361621252-152', 'anki-deck-1756357465257-1790432463920-rf85m', 'When the body''s glycogen stores become depleted during fasting, the body will synthesize glucose primarily from:', 'Glucogenic amino acid', 'When the body''s liver glycogen stores are completely depleted during an extended fast (typically after 12 to 24 hours), blood glucose levels must be strictly maintained to supply glucose-dependent organs like the brain. The liver shifts completely to gluconeogenesis—the de novo creation of glucose from non-carbohydrate precursors.

Muscle tissue is broken down via proteolysis, releasing amino acids into the bloodstream. Glucogenic amino acids (such as alanine and glutamine) are transported to the liver, where their carbon skeletons are converted into pyruvate or TCA cycle intermediates, directly fueling the pathway to synthesize new glucose.

• Fatty acids: Even though adipose tissue releases abundant free fatty acids during fasting, the catabolism of even-chain fatty acids produces acetyl-CoA. In humans, acetyl-CoA cannot be converted into pyruvate because the pyruvate dehydrogenase reaction is irreversible, meaning fatty acids cannot be used to synthesize glucose. (Note: Only the tiny glycerol backbone of a triglyceride can enter gluconeogenesis, not the fatty acid chains themselves).
• Ketone bodies: Ketone bodies (such as acetoacetate and beta-hydroxybutyrate) are synthesized from fatty acid-derived acetyl-CoA in the liver. They serve as an alternative fuel source for the brain and heart during starvation to conserve protein, but they cannot be chemically reversed back into glucose.
• Cholesterol: Cholesterol is a structural component of cell membranes and a precursor for steroid hormones and bile acids, but it plays absolutely no role in energy production or glucose synthesis.', '["Fatty acid","Glucogenic amino acid","Ketone bodies","Cholesterol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-11T11:29:08.275Z","interval":7,"easeFactor":2.3,"repetitions":3}'::jsonb, '"2026-11-04T11:29:08.275Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:29:08.275Z"'::jsonb),
('anki-card-1756360492070-103', 'anki-deck-1756357465257-1790432463920-rf85m', 'The primary risk factor for COPD is:', 'cigarette smoking', 'Cigarette smoking is the most important and common risk factor for COPD. Chronic exposure to tobacco smoke causes airway inflammation, destruction of lung tissue, and progressive, largely irreversible airflow limitation. Other inhaled pollutants can also contribute, particularly occupational exposure to dusts, fumes, and chemicals, but cigarette smoking remains the major preventable risk factor. 

Alpha-1 antitrypsin deficiency is an important genetic risk factor for COPD, particularly emphysema at a younger age, but it is relatively uncommon. Frequent respiratory infections may worsen respiratory health but are not the primary risk factor for developing COPD.', '["alpha-I antitrypsin deficiency","occupational exposure to dusts or chemicals","cigarette smoking","frequent respiratory infections"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:29:11.820Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:29:11.820Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:29:11.820Z"'::jsonb),
('anki-card-1756360579748-107', 'anki-deck-1756357465257-1790432463920-rf85m', 'CHO 900 kcal is ____% of TER 1500 kcal.', '60%', 'To determine the percentage of total energy provided by carbohydrate:
 % of TER = [(kcal from CHO) ÷ TER] * 100 = (900 kcal ÷ 1500) * 100 = 60% 

Therefore, carbohydrate provides 60% of the TER. This type of calculation is commonly used when evaluating whether a patient''s macronutrient distribution meets the prescribed nutrition plan.', '["40%","50%","60%","70%"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-12T11:29:50.630Z","interval":8,"easeFactor":2.5,"repetitions":3}'::jsonb, '"2026-11-04T11:29:50.630Z"'::jsonb, '"2026-09-26T14:32:30.255Z"'::jsonb, '"2026-11-04T11:29:50.630Z"'::jsonb),
