INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1754293049914-115', 'anki-deck-1783608953857-1790433145942-e1oub', 'This relates to the process by which the nutritional quality of food crops is improved through agronomic practices, conventional plant breeding, or modern biotechnology.', 'Biofortification', 'The correct answer is biofortification, specifically defined by improving the nutrient content of crops themselves through agricultural or breeding methods (such as Golden Rice enriched with vitamin A precursor).

See reference here: https://www.who.int/tools/elena/bbc/biofortification', '["Mandatory fortification","Voluntary fortification","Biofortification","Food fortification"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:14:36.128Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:14:36.128Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T14:14:36.128Z"'::jsonb),
('anki-card-1754292867155-113', 'anki-deck-1783608953857-1790433145942-e1oub', 'Who is NOT a member of the Operation Timbang Plus team?', 'Mayor', 'The correct answer is the Mayor, who serves in a broader local governance and oversight role as chair of the local nutrition committee. BHW, BNS, and DCW are all members of the OPT Plus team.

See reference here: https://nnc.gov.ph/plans-and-programs/philippine-nutrition-surveillance-system-pnss/operation-timbang-plus-otp/', '["Barangay health worker","Barangay nutrition scholar","Day care worker","Mayor"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:46:41.641Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:46:41.641Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T14:46:41.641Z"'::jsonb),
('anki-card-1754292812642-112', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which age group is the target in Operation Timbang Plus', '0-59 months', 'Operation Timbang (OPT) Plus is the regular child growth assessment of all children 0-59 months old conducted annually in all barangays in the country to identify and locate families with malnourished preschool children and determine the overall nutrition situation in the area. It also involves planning, follow-up, and data quality check.

See reference here: https://nnc.gov.ph/plans-and-programs/philippine-nutrition-surveillance-system-pnss/operation-timbang-plus-otp/', '["0-11 months","0-23 months","0-35 months","0-59 months"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:38:28.282Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:38:28.282Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:38:28.282Z"'::jsonb),
('anki-card-1754292744393-111', 'anki-deck-1783608953857-1790433145942-e1oub', 'Under the mandatory food fortification program, cooking oil is fortified with:', 'Vit A', 'See RA 8976 (Philippine Food Fortification Act of 2000):

A. Vitamin A – oil, sugar
B. Iron – rice
C. Iodine - salt
D. Vitamin A and iron - wheat flour', '["Vit A","Iron","Iodine","Vit A and Iron"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:52:31.898Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:52:31.898Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:52:31.898Z"'::jsonb),
('anki-card-1754292691495-110', 'anki-deck-1783608953857-1790433145942-e1oub', 'Under the mandatory food fortification program, refined sugar is fortified with:', 'Vit A', 'See RA 8976 (Philippine Food Fortification Act of 2000):

A. Vitamin A – oil, sugar
B. Iron – rice
C. Iodine - salt
D. Vitamin A and iron - wheat flour', '["Vit A","Iron","Iodine","Vit A and Iron"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:36:31.397Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:36:31.397Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:36:31.583Z"'::jsonb),
('anki-card-1754292638597-109', 'anki-deck-1783608953857-1790433145942-e1oub', 'Under the mandatory food fortification program, wheat flour is fortified with:', 'Vitamin A and Iron', 'See RA 8976 (Philippine Food Fortification Act of 2000):

A. Vitamin A - oil
B. Iron – rice
C. Iodine - salt
D. Vitamin A and iron - wheat flour', '["Vitamin A","Iron","Iodine","Vitamin A and Iron"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:34:21.999Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:34:21.999Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:34:22.204Z"'::jsonb),
('anki-card-1754292589066-108', 'anki-deck-1783608953857-1790433145942-e1oub', 'Under the mandatory food fortification program, rice is fortified with', 'Iron', 'See RA 8976 (Philippine Food Fortification Act of 2000):

A. Vitamin A - oil
B. Iron – rice
C. Iodine - salt
D. Vitamin A and iron - wheat flour', '["Vit A","Iron","Iodine","Vit A and Iron"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:48:41.498Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:48:41.498Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:48:41.498Z"'::jsonb),
('anki-card-1754292545086-107', 'anki-deck-1783608953857-1790433145942-e1oub', 'The current Nutritional Guildelines for Filipinos was approved and adopted in what year?', '2012', 'Official name: Nutritional guidelines for Filipinos (Filipino: Mga Gabay sa Wastong Nutrisyon Para sa Pilipino).

Publication year: The Philippines published its first dietary guidelines in 1990. They were revised in 2000 and again in 2012.

Process and stakeholders
The Food and Nutrition Research Institute – Department of Science and Technology (FNRI-DOST) initiated and chaired the inter-agency and multidisciplinary Technical Working Group on the 2012 guidelines.

The guidelines were approved by the National Nutrition Council. The communication and dissemination is spearheaded by the National Nutrition Council and endorsed by various government agencies.

See reference here: https://www.fao.org/nutrition/education/food-dietary-guidelines/regions/countries/philippines/en/', '["2000","2006","2012","2018"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:00:41.892Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:00:41.892Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:00:41.892Z"'::jsonb),
('anki-card-1754292404175-105', 'anki-deck-1783608953857-1790433145942-e1oub', 'What is stated in the 5th Nutritional Guidelines for Filipinos', 'Consume milk, milk product, and other calcium-rich foods, such as small fish and shellfish, every day for healthy bones and teeth', 'Formulated by the Food and Nutrition Research Institute (FNRI-DOST), the 10 messages (popularly popularized as the 10 Kumainments) are chronologically ordered as follows:

1. 1st Guideline: Eat a variety of foods everyday to get the nutrients needed by the body.
2. 2nd Guideline: Breastfeed infants exclusively from birth up to 6 months, then give appropriate complementary foods.
3. 3rd Guideline: Eat more vegetables and fruits every day.
4. 4th Guideline: Consume fish, lean meat, poultry, egg, dried beans or nuts daily.
5. 5th Guideline: Consume milk, milk products, and other calcium-rich foods.
6. 6th Guideline: Consume safe foods and water to prevent diarrhea.
7. 7th Guideline: Use iodized salt to prevent Iodine Deficiency Disorders.
8. 8th Guideline: Limit intake of salty, fried, fatty, and sugar-rich foods.
9. 9th Guideline: Attain normal body weight through proper diet and moderate physical activity.
10. 10th Guideline: Be physically active, make healthy food choices, manage stress, avoid alcoholic beverages, and do not smoke.', '["Consume milk, milk product, and other calcium-rich foods, such as small fish and shellfish, every day for healthy bones and teeth","Use iodized salt to prevent Iodine Deficiency Disorders","Eat more vegetables and fruits every day to get essential vitamins, minerals, and fiber for regulation of body processes.","Limit intake of salty, fried, fatty, and sugar-rich foods to prevent cardiovascular disease"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:21:03.565Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:21:03.565Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T13:21:03.565Z"'::jsonb),
('anki-card-1754299752785-194', 'anki-deck-1783608953857-1790433145942-e1oub', 'This refers to the study of interactions/interrelationship between an organism and their environment.', 'Ecology of food and nutrition', 'Ecology of Food and Nutrition frames the complex relationship between humans, food, and their natural, social, and cultural environment.', '["Food and nutrition system","Ecology of food and nutrition","Food Path","Food security"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:44:35.557Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:44:35.557Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:44:35.557Z"'::jsonb),
('anki-card-1754294663254-129', 'anki-deck-1783608953857-1790433145942-e1oub', 'Key decisions for implementation of nutrition programs/projects/activities such as continue with or without modification; stop the implementation; replace with new interventiion are done in what phase/step of program management?', 'Re-planning', 'Re-planning is a specific decision types (continue, modify, stop, or replace an intervention) made once monitoring and evaluation data reveal how a program is performing. 

• Assessment and plan preparation occurs before implementation and does not involve adjusting an ongoing program. 
• Implementation is the execution phase itself. 
• Monitoring and evaluation generates the data that informs these decisions but is technically the data-gathering step preceding the actual re-planning decision-making.', '["Assessment and plan preparation","Implementation","Re-planning","Monitoring and Evaluation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:35:03.365Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:35:03.365Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:35:03.583Z"'::jsonb),
('anki-card-1754296322374-145', 'anki-deck-1783608953857-1790433145942-e1oub', 'This serves as complementary activity in making the implementation of most of the nutrition interventions effective.', 'Nutrition Education', 'Nutrition Education functions as a cross-cutting, complementary activity that enhances the effectiveness of virtually all other nutrition interventions by ensuring beneficiaries understand and can sustain the benefits of programs like feeding, fortification, or livelihood support. 

Livelihood Assistance, Home/School/Community Food Production, and Supplementary Feeding are specific, standalone interventions.', '["Nutrition Education","Livelihood Assistance","Home, School, and Community Food Production","Supplementary Feeding"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:34:45.115Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:34:45.115Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:34:45.314Z"'::jsonb),
('anki-card-1754299470947-190', 'anki-deck-1783608953857-1790433145942-e1oub', 'Sustainability implies food system practices that respect and protect the ecosystems. It is recognized as an important aspect of ensuring the right to food.', 'Both statements are true', '• Statement 1 is true: According to the Food and Agriculture Organization (FAO), environmental sustainability in a food system is determined by ensuring that the impacts of production, processing, and distribution on the surrounding natural environment are neutral or positive. It explicitly demands the respect and protection of ecosystems by safeguarding biodiversity, water, soil, and minimizing the carbon footprint.

• Statement 2 is true: The "Right to Food" is a formalized human right, and the United Nations recognizes that this right cannot be realized long-term without sustainable practices. If today''s food systems destroy ecosystems, deplete freshwater, and accelerate the climate crisis, they compromise the global capacity to feed future generations, thereby violating the progressive realization of the right to food.', '["Only the first statement is true","Only the second statement is true","Both statements are true","Both statements are false"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:54:13.501Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:54:13.501Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T13:54:13.707Z"'::jsonb),
('anki-card-1754299545562-191', 'anki-deck-1783608953857-1790433145942-e1oub', 'It underpins all other food security dimensions by emphasizing the capacity of individuals and groups to engage in decision and policy making processes.', 'Agency', 'Agency is the power to make decisions and act on one''s own behalf (e.g., choosing what to eat).

• Accessibility - ability to get or afford the resources (e.g., food, services, markets).
• Utilization - ability to properly use the resources to achieve good health (e.g., hygiene, knowledge).
• Sustainability - ensuring the benefits continue after external support is withdrawn (long-term resilience).', '["Accessibility","Utilization","Agency","Sustainability"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:33:04.969Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:33:04.969Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:33:05.176Z"'::jsonb),
('anki-card-1754299611445-192', 'anki-deck-1783608953857-1790433145942-e1oub', 'This includes the personal and financial capacity to acquire adequate food to satisfy basic needs.', 'Accessibility', 'Accessibility is the ability to get or afford the resources (e.g., food, services, markets).

• Availability - physical presence of food
• Nutrition security - consistent access, affordability, and utilization of diverse, safe, and nutritious food to ensure a healthy life.
• Economic security - stable income, resources, and access to work that guarantees a basic standard of living and protects against shocks.', '["Availability","Accessibility","Nutrition security","Economic security"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:31:38.410Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:31:38.410Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:31:38.608Z"'::jsonb),
('anki-card-1754299382702-189', 'anki-deck-1783608953857-1790433145942-e1oub', 'Bitot''s spot is characterized by ___?', 'Dryness of conjunctiva with foamy patch', 'Dryness of the conjunctiva with foamy patches is the precise clinical description of a Bitot''s spot, a foamy, triangular, grayish-white patch on the conjunctiva associated with vitamin A deficiency-related xerophthalmia. 

• Night blindness is an earlier, functional (not physical) sign of vitamin A deficiency, appearing before Bitot''s spots develop. 
• Conjunctival xerosis refers to generalized dryness of the conjunctiva without the specific foamy patch appearance that defines a Bitot''s spot.
• Corneal xerosis refers to dryness affecting the cornea.', '["Nightblindness","Conjuctival xerosis","Dryness of conjunctiva with foamy patch","Corneal xerosis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:13:50.734Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:13:50.734Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T14:13:50.734Z"'::jsonb),
('anki-card-1754299324170-188', 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following is a measurement of body composition?', 'Body Fat', 'Body composition specifically refers to the relative proportions of fat mass versus fat-free (lean) mass in the body, and body fat measurement directly captures one of these two core components. 

• Weight and height are simple anthropometric dimensions that do not by themselves distinguish fat from lean tissue. 
• Head circumference is a growth/development indicator used mainly in infants to assess brain growth.', '["Weight","Height","Head circumference","Body Fat"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:39:51.101Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:39:51.101Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:39:51.101Z"'::jsonb),
('anki-card-1754299283356-187', 'anki-deck-1783608953857-1790433145942-e1oub', 'An instrument used to measure skinfold thickness', 'Lange', 'The Lange caliper is a specific instrument designed and validated for measuring skinfold thickness at standardized body sites to estimate subcutaneous body fat. 

Biceps, subscapular, and midaxillary are names of specific skinfold measurement sites on the body.', '["Biceps","Lange","Subscapular","Midaxillary"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:33:46.947Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:33:46.947Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:33:47.127Z"'::jsonb),
('anki-card-1754299241177-186', 'anki-deck-1783608953857-1790433145942-e1oub', 'Menke''s Kinky hair syndrome is a deficiency in ____?', 'Copper', 'Menke''s kinky hair syndrome is the genetic disorder of copper metabolism/transport that results in severe copper deficiency, presenting classically with sparse, kinky, brittle hair along with neurodegenerative symptoms in affected infants.', '["Chromium","Copper","Calcium","Cobalt"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:53:12.020Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:53:12.020Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:53:12.020Z"'::jsonb),
('anki-card-1754299193910-185', 'anki-deck-1783608953857-1790433145942-e1oub', 'Obesity prevalence among adults 20 to 59 years old according to the 2021 ENNS is:', '10.0%', 'According to the 2021 Expanded National Nutrition Survey (DOST-FNRI), based on the WHO Asia-Pacific BMI Classification,

• 18.3% adults were overweight (BMI: 23.0 to 24.9 kg/m²)
• 30.2% were obese class I (BMI: 25.0 to 29.9 kg/m²)
• 10.0% were obese class II (BMI: ≥30 kg/m²).', '["10.0%","11.7%","30.2%","35.5%"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:25:18.398Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:25:18.398Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:25:18.592Z"'::jsonb),
('anki-card-1754299134064-184', 'anki-deck-1783608953857-1790433145942-e1oub', 'This pertains to the number of deaths per 1000 livebirth of infants under 1 year of age in a calendar year in the same period', 'IMR', 'IMR (Infant Mortality Rate): The number of deaths of children under 1 year of age (0 to 365 days) per 1,000 live births in a given calendar year. It is a standard public health indicator reflecting the overall socio-economic and healthcare status of a population.

• MMR (Maternal Mortality Ratio/Rate): The number of maternal deaths from any cause related to or aggravated by pregnancy or its management during pregnancy and childbirth (or within 42 days of termination) per 100,000 live births.
• NMR (Neonatal Mortality Rate): The number of deaths during the first 28 days of life (neonatal period) per 1,000 live births.
• SMR (Standardized Mortality Ratio): The ratio of observed deaths in the study group to the expected deaths in the general population, or Senile Mortality Rate depending on the epidemiological context.', '["IMR","NMR","MMR","SMR"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:31:27.268Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:31:27.268Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:31:27.445Z"'::jsonb),
('anki-card-1754294555427-128', 'anki-deck-1783608953857-1790433145942-e1oub', 'In nutritional assessment, causes of malnutrition must be classified into immediate, underlying and basic causes. Food insecurity and poor child care are classified as:', 'Underlying causes', 'Underlying causes – contributing causes; food security, health services, practices

• Immediate causes – direct causes; food and care (individual level)
• Basic causes – societal; political, economic, education etc.
• Cross-cutting causes', '["Immediate causes","Underlying causes","Basic cause","Cross-cutting causes"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:10:36.759Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:10:36.759Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T14:10:36.759Z"'::jsonb),
('anki-card-1754299083349-183', 'anki-deck-1783608953857-1790433145942-e1oub', 'Ms. Santos is conducting a research which aims to measure the mean nutrient intake of school children. What dietary assessment method will you recommend?', '24-hour food recall', '24-hour food recall is well-suited and commonly used for estimating the mean (average) nutrient intake of a group or population, since individual day-to-day variation tends to average out across a sufficiently large sample even with a single recall per person. 

• Food frequency questionnaires are better suited for ranking individuals by relative intake or assessing habitual/long-term dietary patterns rather than precise mean nutrient quantities. 
• Diet records and food weighing are more resource-intensive, detailed methods typically reserved for smaller studies or when precise individual intake data is needed.', '["24-hour food recall","Food frequency","Diet record","Food weighing"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:40:58.317Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:40:58.317Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:40:58.510Z"'::jsonb),
('anki-card-1754298949922-181', 'anki-deck-1783608953857-1790433145942-e1oub', 'According to WHO, if the prevalence rate of anemia in a population is 20% it can be classified as?', 'Moderate', 'The World Health Organization (WHO) classifies the severity of anemia as a public health problem based on its prevalence rate within a given population:

• Normal (No problem): Prevalence of 4.9% or lower
• Mild Public Health Problem: Prevalence of 5.0% to 19.9%
• Moderate Public Health Problem: Prevalence of 20.0% to 39.9% — Since the population prevalence is exactly 20%, it marks the lower boundary of a moderate public health crisis, requiring immediate targeted community interventions (such as massive iron-folic acid supplementation or food fortification programs).
• Severe Public Health Problem: Prevalence of 40.0% or higher', '["High","Mild","Moderate","Low"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:18:18.780Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:18:18.780Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T13:18:18.962Z"'::jsonb),
('anki-card-1754298899840-180', 'anki-deck-1783608953857-1790433145942-e1oub', 'The MUAC of Ivanah Kawali indicates 11.5 cm. What is her nutritional status?', 'Moderate acute malnutrition', 'The correct answer is Moderate Acute Malnutrition (MAM), since a MUAC value in the range of approximately 11.5-12.4 cm in children under five is classified by WHO as indicating moderate acute malnutrition. 

MUAC is a simple, field-friendly screening tool widely used in community and emergency nutrition programs to rapidly identify acute malnutrition in young children.

• Severe Acute Malnutrition (SAM): Diagnosed only when the measurement drops strictly below 11.5 cm (<115 mm), or if bilateral pitting edema is present.
• Normal Nutritional Status: Indicated by a MUAC of 12.5 cm or higher (≥125 mm).', '["Normal","Stunting","Moderate acute malnutrition","Severe Acute malnutrition"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:55:55.747Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:55:55.747Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:55:55.747Z"'::jsonb),
('anki-card-1754298810761-179', 'anki-deck-1783608953857-1790433145942-e1oub', 'Irma weighs 56 kg and stands 5 feet. What is her body mass index?', '24.11 kg/m²', 'Body Mass Index (BMI) is calculated using the formula:
BMI = Weight (kg) / [Height (m)]²

1. Convert height from feet to meters:
	• 5 feet = 60 inches
	• 60 inches × 0.0254 meters/inch = 1.524 meters

2. Square the height in meters:
	• 1.524 × 1.524 = 2.3226 m²

3. Divide weight by squared height:
	• 56 kg / 2.3226 m² = 24.11

According to both WHO and Asia-Pacific standards, a BMI of 24.11 places Irma in the "Normal" weight category.', '["24.11 kg/m²","36.75 kg/m²","23.33 kg/m²","36.14 kg/m²"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:14:10.120Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:14:10.120Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:14:10.450Z"'::jsonb),
('anki-card-1754295877164-141', 'anki-deck-1783608953857-1790433145942-e1oub', 'In 2014, the National Nutrition Council Governing Board approved and adopted the guidelines on local nutrition planning that direct LGUS to come up with a ______ local nutrition action plan.', '3 year', 'The 2014 NNC guidelines for LGU-level Local Nutrition Action Plans, aligning with the local government''s typical elected term of office. Aligning the LNAP''s three-year cycle with local elected officials'' terms helps ensure political ownership and continuity of nutrition planning across the term of local leadership.', '["1 year","2 year","3 year","4 year"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:19:21.091Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:19:21.091Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:19:21.091Z"'::jsonb),
('anki-card-1754292942302-114', 'anki-deck-1783608953857-1790433145942-e1oub', 'This program involves the provision of pharmaceutical preparations of vitamins and minerals.', 'Micronutrient Supplementation', 'Micronutrient supplementation, defined specifically as providing vitamins and minerals in pharmaceutical form (such as capsules, syrups, or tablets) directly to individuals.

Food fortification instead adds nutrients to commonly consumed foods during processing. Livelihood assistance and food production are indirect, food-security-oriented interventions.', '["Food Fortification","Micronutrient Supplementation","Livelihood Assistance","Food Production"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:33:51.786Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:33:51.786Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:33:51.987Z"'::jsonb),
('anki-card-1754291946981-100', 'anki-deck-1783608953857-1790433145942-e1oub', 'This pertains to a set of tools and procedures to classify the nature and severity of food insecurity.', 'IPC', 'IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). 

• EWS refers to an Early Warning System, which focuses on early detection of deteriorating conditions. 
• OPT, Operation Timbang, is a child weighing activity, unrelated to food insecurity classification. 
• SFP, Supplementary Feeding Program, is an intervention, not a classification tool.', '["IPC","EWS","OPT","SFP"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:34:18.075Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:34:18.075Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:34:18.279Z"'::jsonb),
('anki-card-1754292037490-101', 'anki-deck-1783608953857-1790433145942-e1oub', 'This refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.', 'EWS', 'The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. 

EWS and IPC work together in practice, but EWS is specifically the local, trigger-based detection mechanism.', '["IPC","EWS","OPT","SFP"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:28:12.945Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:28:12.945Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:28:13.136Z"'::jsonb),
('anki-card-1754292141054-103', 'anki-deck-1783608953857-1790433145942-e1oub', 'Promote Good Nutrition is a component of this program.', 'AHMP', 'The correct answer is AHMP (Anti-Hunger Mitigation Program), under which "Promote Good Nutrition" is listed as one of its core intervention components alongside food assistance and livelihood support strategies.', '["AHMP","IYCF","NGF","PSN"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:42:07.810Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:42:07.810Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:42:07.810Z"'::jsonb),
('anki-card-1754292209333-104', 'anki-deck-1783608953857-1790433145942-e1oub', '____ aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.', 'PGN', 'PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.

• AHMP (Accelerated Hunger-Mitigation Program) is the overarching mother program addressing hunger and food security.
• IYCF (Infant and Young Child Feeding) represents the specific set of optimal guidelines and target behaviors (like exclusive breastfeeding and appropriate complementary feeding) that the PGN promotes to mothers and caregivers.', '["PGN","NGF","IYCF","AHMP"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:43:18.771Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:43:18.771Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:43:18.771Z"'::jsonb),
('anki-card-1754300118852-199', 'anki-deck-1783608953857-1790433145942-e1oub', 'All of the following are the main drivers of changes in the food system except:', 'Food supply chains', 'According to the High Level Panel of Experts (HLPE) on Food Security and Nutrition and the Food and Agriculture Organization (FAO), a food system is conceptually split into Drivers, Core Components, and Outcomes:

Drivers (External Elements): These are the broad, macro-level forces that push or pull the entire food system into changing. The recognized categories of global drivers include:
	• Political and institutional factors (e.g., policies, trade laws, land rights)
	• Economic and market factors (e.g., income shifts, globalization, prices)
	• Technology and innovation factors (e.g., precision agriculture, storage engineering)
	• Biophysical and climate factors (e.g., weather, soil health)
	• Demographic and socio-cultural factors (e.g., population growth, shifting habits)

Food Supply Chains (Internal Component): Food supply chains (comprising agricultural production, storage, processing, and distribution) are not external drivers of change. Instead, they are the internal mechanisms or structural pillars of the food system that get altered or shaped by the drivers.', '["Technology and innovation","Economic and market","Political and institution","Food supply chains"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:04:48.955Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T15:04:48.955Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:04:48.955Z"'::jsonb),
('anki-card-1754300054254-198', 'anki-deck-1783608953857-1790433145942-e1oub', 'Two of the following are possible blocks to food availability except:', 'Market price', 'Food Availability (Supply Side) refers to the physical presence of food through local agricultural production, storage, or imports.
	• Presence of pests and Typhoons are environmental or biological hazards that physically destroy crops, directly blocking availability.
	• Availability of agricultural inputs (like seeds and fertilizer) directly determines how much food can be produced in the first place.

Food Accessibility/Affordability (Demand Side): Market price does not typically prevent food from physically existing or being available in a market. Instead, high prices act as an economic barrier, blocking a family''s accessibility or affordability to buy the food that is already there.', '["Typhoon","Market price","Availability of agricultural inputs","Presence of pests"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:45:05.716Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:45:05.716Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:45:05.716Z"'::jsonb),
('anki-card-1754299978343-197', 'anki-deck-1783608953857-1790433145942-e1oub', 'All of the following often shape food environments except:', 'Consumer behavior', 'The correct answer is consumer behavior because consumer behavior is generally considered an outcome or response shaped BY the food environment (through what foods are available, promoted, and priced), rather than itself being a shaping force of the environment. 

Private companies, industry, and legal frameworks are all recognized as active forces that shape food environments.', '["Private companies","Industry","Legal frameworks","Consumer behavior"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:18:25.281Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:18:25.281Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:18:25.281Z"'::jsonb),
('anki-card-1754299923677-196', 'anki-deck-1783608953857-1790433145942-e1oub', 'This refers to the physical, economic, socio-cultural, and policy conditions that shape access, affordability, safety and food preferences', 'Food environment', 'The term food environment encompasses the collective physical, economic, policy, and socio-cultural surroundings and opportunities that directly influence a consumer''s food choices, purchasing habits, and nutritional status.

It acts as the interface where a person makes a decision about what to eat, driven by specific subdomains:
• Physical & Policy Conditions: The location of grocery stores versus "food deserts," food safety regulations, or marketing and labeling laws.
• Economic & Socio-cultural Conditions: Retail prices, household purchasing power (affordability), and family or community traditions that dictate food preferences.', '["Food path","Food distribution","Food environment","Food trade"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:08:07.549Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:08:07.549Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:08:07.549Z"'::jsonb),
('anki-card-1758788760531-160', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Refer to the following information. Based on the FEL, the diet of a burn patient contains the following meal pattern for lunch: 90g fried chicken; 160g rice; 45g sauteed squash; 250g fresh milk; and 103g ripe mango.
How much is the CHO content of the meal? *', '71 g', 'According to the Philippine Food Exchange List (FEL), each food item is converted into exchange units to calculate its specific carbohydrate (CHO) content:

1. 160g Rice (2 Rice Exchanges):
• 1 exchange of cooked rice = 80g (contains 23g CHO)
• 160g = 2 exchanges
• CHO content: 2 x 23g = 46g

2. 250g Fresh Milk (1 Whole Milk Exchange):
• 1 exchange of whole milk = 250g (contains 12g CHO)
• CHO content: 1 x 12g = 12g

3. 103g Ripe Mango (1 Fruit Exchange):
• 1 exchange of fruit = approx. 100g (contains 10g CHO)
• CHO content: 1 x 10g = 10g

4. 45g Sauteed Squash (1 Vegetable B Exchange):
• 1 exchange of cooked Vegetable B = 45g (contains 3g CHO)
• CHO content: 1 x 3g = 3g (Note: The fat exchange added for sauteing oil contains 0g CHO).

5. 90g Fried Chicken (3 Medium-Fat Meat Exchanges):
• Meat exchanges contain 0g CHO.

Final CHO Summation:

• Rice: 46g
• Fresh Milk: 12g
• Ripe Mango: 10g
• Sauteed Squash: 3g
• Fried Chicken: 0g
• Total CHO Content: 46g + 12g + 10g + 3g = 71g', '["69 g","71 g","73 g","81 g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T16:05:40.396Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T16:05:40.396Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T16:05:40.482Z"'::jsonb),
('anki-card-1758789188129-196', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Which diet is best for a patient with hypothyroidism? *', '20-30 cal/KBW, low fat, iodized salt', '', '["30 cal/KBW, high fat, iodized salt","30 cal/KBW, low fat, iodized salt","20-25 cal/KBW, high fat, iodized salt","20-30 cal/KBW, low fat, iodized salt"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T05:13:15.347Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-30T05:13:15.347Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-30T05:13:15.347Z"'::jsonb),
