INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1758789079628-185', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Dietary recommendation for clients with cystic fibrosis except: *', 'limit the use of table salt', 'Cystic fibrosis (CF) is caused by a genetic mutation that disrupts the CFTR protein, preventing cells from properly regulating chloride and sodium. As a result, individuals with CF lose massive amounts of salt through their sweat pores (often referred to as having "salty skin"). To prevent hyponatremia (dangerously low blood sodium), dehydration, and heat exhaustion, clients with CF are actively encouraged to liberalize their use of table salt and consume salty snacks. Limiting salt is contraindicated.

Historically, old test bank items sometimes listed fat restriction as an outdated management strategy because patients cannot digest fats well without enzymes. However, in modern clinical nutrition practice—combined with Pancreatic Enzyme Replacement Therapy (PERT)—a high-fat diet is heavily promoted alongside high calorie and high protein to help meet their high energy demands.', '["limit the use of table salt","high calorie","high protein","fat restrictions"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:49:29.663Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:49:29.663Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:49:29.663Z"'::jsonb),
('anki-card-1758789112982-189', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Risk assessment CHD includes measurement of blood lipids such as: *', 'all of the above', 'A comprehensive risk assessment for Coronary Heart Disease (CHD) relies on a full fasting lipid profile. Each of the lipid fractions listed in the other options provides distinct, critical diagnostic data regarding a patient''s cardiovascular health profile:

• Total Cholesterol (TC): Reflects the overall amount of cholesterol circulating in the bloodstream and is directly linked to blood vessel plaque buildup and disease risk.
• Triglycerides (TG): High levels of these blood fats serve as an independent risk factor for atherosclerosis and metabolic syndrome, often elevated by a high-fat diet, refined sugars, or alcohol.
• HDL-Cholesterol (HDL-C): Known as the "good cholesterol," it plays a protective role by removing excess cholesterol from peripheral tissues and transporting it back to the liver. High levels actively reduce CHD risk.
• LDL-Cholesterol (LDL-C): Designated as the "bad cholesterol" and the primary target of clinical lipid-lowering therapies, elevated circulating LDL leads directly to fatty accumulation and narrowing inside the coronary arteries.', '["total cholesterol, TG","LDL-cholesterol, total cholesterol","HDL cholesterol, TG","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:38:32.627Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T12:38:32.627Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:38:32.797Z"'::jsonb),
('anki-card-1758789131799-191', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Flatulence, cramps, or diabetes may be some unpleasant side effects upon the initiation of this diet: *', 'high-fiber diet', 'When a person suddenly initiates a high-fiber diet, the digestive tract requires a transition period to adapt. The human body lacks the enzymes to digest dietary fiber, so it passes intact into the large intestine. There, resident gut bacteria ferment the fiber. A sudden influx of fiber causes rapid, aggressive bacterial fermentation, which produces large amounts of gas. This trapped gas directly results in flatulence, abdominal bloating, and painful cramps.

While fiber does not cause diabetes, a high-fiber diet is a primary clinical intervention utilized for the management of Diabetes Mellitus. Soluble fiber creates a gel-like substance in the gut that slows down the absorption of glucose, preventing rapid post-meal blood sugar spikes and improving insulin sensitivity.', '["fiber-restricted diet","high-fiber diet","soft diet","elemental diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:08:07.354Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:08:07.354Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T15:08:07.447Z"'::jsonb),
('anki-card-1758789140416-192', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Chronic diarrhea may be accompanied by a number of nutritional deficiencies due to losses of: *', 'all of the above', 'Chronic diarrhea severely impairs the small and large intestines'' ability to absorb nutrients due to rapid transit time and mucosal damage. This leads to widespread malabsorption and excessive losses of:

• Na & K: Sodium and potassium are critical electrolytes lost in high volumes through watery stools, leading to dehydration and electrolyte imbalances.
• Vitamins & minerals: Fat-soluble vitamins (A, D, E, K), water-soluble vitamins (like B-complex), and minerals (such as iron, zinc, and magnesium) are rapidly depleted.
• Protein: Protein-losing enteropathy often occurs during chronic diarrhea, where plasma proteins leak directly into the gut lumen and are excreted, leading to tissue wasting and hypoalbuminemia.', '["Na & K","vitamins & minerals","protein","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T14:08:52.910Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T14:08:52.910Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T14:08:52.985Z"'::jsonb),
('anki-card-1758789156863-193', 'anki-deck-1783610488281-1790433142627-pf2m5', 'This type of supplement has shown good results in reducing encephalopathy and in improving nitrogen and energy balance: *', 'branched-chain amino acids supplements', 'Patients with advanced liver disease or cirrhosis typically present with an altered amino acid profile. Their plasma levels of Branched-Chain Amino Acids (BCAAs: leucine, isoleucine, and valine) drop significantly, while levels of Aromatic Amino Acids (AAAs: phenylalanine, tyrosine, and tryptophan) rise. This imbalance allows excessive AAAs to cross the blood-brain barrier, altering neurotransmission and inducing hepatic encephalopathy.', '["vegetable ad casein-based protein supplements","aromatic amino acids supplements","branched-chain amino acids supplements","phenylalanine supplements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T13:54:40.192Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T13:54:40.192Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T13:54:40.295Z"'::jsonb),
('anki-card-1758788079296-102', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Using the quickest method for weight calculation, determine the weight for a small frame male at 5’10”. * hamwi method', '150', 'Step-by-Step Calculation:

1. Calculate Ideal Body Weight (IBW) for a medium frame:
The standard Hamwi method rule for males allocates 106 lbs for the first 5 feet (60 inches) of height, plus 6 lbs for every additional inch.
	• Height: 5''10" (which is 10 inches over 5 feet)
	• Base weight: 106 lbs
	• Additional inches: 10 inches × 6 lbs/inch = 60 lbs
	• Medium Frame Weight: 106 lbs + 60 lbs = 166 lbs

2. Adjust for a small frame size:
The Hamwi method dictates that you must subtract 10% from the medium frame total if the individual has a small frame.
	• 10% of 166 lbs = 16.6 lbs
	• Small Frame Weight: 166 lbs - 16.6 lbs = 149.4 lbs

When rounded to the nearest multiple of ten to match the multiple-choice selection, 149.4 lbs aligns perfectly with 150 lbs.', '["170","160","150","140"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:26:54.384Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:26:54.384Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T15:26:54.470Z"'::jsonb),
('anki-card-1758788088345-103', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Maria consulted Ms. Uy, a registered ND for weight reduction. History of her weight gain is as follows: height = 5’5”; wrist circumference = 6”; Actual weight = 180 lbs.; and DBW = 125 lbs. What is Maria’s %DBW change? *', '44%', 'To find a person''s percentage over or under their DBW (the percentage weight change/deviation), you use this formula:
• % DBW Deviation = ((Actual Weight - DBW) ÷ DBW) × 100
• Calculation: ((180 lbs - 125 lbs) ÷ 125 lbs) × 100 = (55 ÷ 125) × 100 = 44%', '["20%","31%","38%","44%"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-16T02:46:45.023Z","interval":3,"easeFactor":2.1,"repetitions":2}'::jsonb, '"2026-10-13T02:46:45.023Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-13T02:46:45.095Z"'::jsonb),
('anki-card-1758788096694-104', 'anki-deck-1783610488281-1790433142627-pf2m5', 'How many grams of protein will be contained in 1.5 liters of blenderized feeding formula with a caloric density of 2 kcal/ml, 12% of which are from protein? *', '90 g', 'Step-by-Step Calculation:

1. Convert liters to milliliters:
1.5 liters = 1500 ml

2. Calculate the total calories in the formula:
Multiply the total volume by the caloric density.
1500 ml x 2 kcal/ml = 3000 kcal

3. Calculate the calories provided by protein:
Multiply the total calories by the protein percentage.
3000 kcal x 0.12 = 360 kcal from protein

4. Convert protein calories into grams:
Protein provides 4 calories per gram (4 kcal/g). Divide the protein calories by 4.
360 kcal / 4 kcal/g = 90 g', '["90 g","100 g","110 g","120 g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T16:00:34.780Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T16:00:34.780Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T16:00:34.869Z"'::jsonb),
('anki-card-1758788112112-105', 'anki-deck-1783610488281-1790433142627-pf2m5', 'You are called to see this previously healthy person who is admitted for diagnostic procedures. You would initiate tube feedings because: *', 'she cannot swallow', '', '["skin tests are positive","she cannot swallow","creatine/height ratio is","triceps skinfold is 35 mm"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-16T00:59:15.647Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-13T00:59:15.647Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-13T00:59:15.726Z"'::jsonb),
('anki-card-1758788121478-106', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The most dangerous risk factor in the pathogenesis of cardiovascular disease is: *', 'hypertension', '', '["cigarette smoking","hypertension","hyperlipidemia","obesity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T06:17:19.349Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-09-30T06:17:19.349Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-30T06:17:19.349Z"'::jsonb),
('anki-card-1758789124116-190', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The recommended intake for MUFA in the diet is approximately: *', 'less than 7% of total kcal', '', '["30% of total kcal","less than 7% of total kcal","up to 10% of total kcal","up to 15% of total kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T16:06:10.736Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T16:06:10.736Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-28T16:06:10.970Z"'::jsonb),
('anki-card-1758788051115-100', 'anki-deck-1783610488281-1790433142627-pf2m5', 'How many mEq are found in a phosphorus diet limited to 1,000 mg per day? *', '65', 'Phosphorus primarily circulates in extracellular and intracellular fluids as phosphate ions, predominantly a mixture of divalent ($HPO_4^{2-}$) and monovalent ($H_2PO_4^{-}$) species at physiological blood pH (7.4) in a roughly 4:1 ratio. For clinical nutrition and renal calculations involving elemental phosphorus (atomic weight approximately 30.97 g/mol), an effective valence of roughly 1.8 to 2 is applied depending on the exact ionic distribution, or more commonly in standard dietetic board calculations, the conversion utilizes the atomic weight and an assumed average valence or direct stoichiometric conversion factor where 1 mmol of phosphorus equals roughly 31 mg, and milliequivalents are derived via the formula: mEq = (mg / atomic weight) * valence. At physiological pH, calculating with an average valence of ~2.0 for total phosphate yields (1000 mg / 30.97 mg/mmol) * 2 = ~64.5 mEq, which rounds directly to 65 mEq.', '["14","28","32","65"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T14:08:47.920Z","interval":1,"easeFactor":1.9,"repetitions":1}'::jsonb, '"2026-10-10T14:08:47.920Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T14:08:48.000Z"'::jsonb),
('anki-card-1758788070231-101', 'anki-deck-1783610488281-1790433142627-pf2m5', 'How much sodium is 3 grams of salt? *', '1,200', 'Table salt (sodium chloride) consists of approximately 40% sodium and 60% chloride.

To find the amount of sodium in 3 grams of salt:
• Convert 3 grams of salt to milligrams: 3 grams = 3,000 milligrams.
• Calculate the sodium portion: 3,000 milligrams multiplied by 0.40 = 1,200 milligrams of sodium.', '["1,200","1,400","1,600","1,800"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-14T02:56:30.954Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-13T02:56:30.954Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-13T02:56:31.028Z"'::jsonb),
('anki-card-1758788985771-176', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Wasting in people with COPD is associated with all of the following except: *', 'use of oxygen masks', '', '["anorexia and reduced food intake","medications used in treatment","use of oxygen masks","diarrhea and malabsorption"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T15:50:27.825Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T15:50:27.825Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-28T15:50:27.825Z"'::jsonb),
('anki-card-1758788258339-120', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The sodium output of the kidneys is controlled by: *', 'aldosterone', '', '["insulin","testosterone","aldosterone","ergosterone"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T15:52:04.733Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T15:52:04.733Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-28T15:52:04.733Z"'::jsonb),
('anki-card-1758788776080-161', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Refer to the following information. Based on the FEL, the diet of a burn patient contains the following meal pattern for lunch: 90g fried chicken; 160g rice; 45g sauteed squash; 250g fresh milk; and 103g ripe mango.
How much is the protein content of the meal? *', '37 g', '• 90g Fried Chicken: 90 grams divided by 30 grams per exchange equals 3 exchanges. 3 exchanges multiplied by 8 grams of protein equals 24 grams of protein.
• 160g Rice: 160 grams divided by 80 grams per exchange equals 2 exchanges. 2 exchanges multiplied by 2 grams of protein equals 4 grams of protein.
• 45g Sauteed Squash: 45 grams equals exactly 1 exchange of vegetable. 1 exchange multiplied by 1 gram of protein equals 1 gram of protein.
• 250g Fresh Milk: 250 grams equals 1 exchange of milk. 1 exchange multiplied by 8 grams of protein equals 8 grams of protein.
• 103g Ripe Mango: 1 exchange of fruit equals 0 grams of protein.

Total Calculation:
24 grams (Chicken) + 4 grams (Rice) + 1 gram (Squash) + 8 grams (Milk) + 0 grams (Mango) = 37 grams of protein', '["36 g","37 g","35 g","45 g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:39:41.333Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:39:41.333Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:39:41.509Z"'::jsonb),
('anki-card-1758788585823-151', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Considered “neutral foods” when following either an alkaline ash or an acid ash diet: *', 'butter, candy, sugar', 'Foods that are primarily composed of pure fats, oils, or refined sugars leave behind no mineral residue that can alter urinary pH. Therefore, butter, cooking oils, margarine, plain candies, and table sugar are classified as strictly neutral. 

• Acid Ash Foods: Foods high in protein, phosphorus, and sulfur leave behind an acidic residue. This includes meat, fish, poultry, eggs, and whole grains.
• Alkaline Ash Foods: Foods rich in minerals like magnesium, potassium, and calcium leave behind an alkaline residue. This includes almost all fruits and vegetables (even acidic ones like lemons, because the organic citric acid is fully oxidized into water and CO₂, leaving alkaline minerals behind).', '["fruits and vegetables","butter, candy, sugar","whole grains and eggs","meat, fish, poultry"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T14:10:20.170Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T14:10:20.170Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T14:10:20.244Z"'::jsonb),
('anki-card-1758788577374-150', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A malabsorption problem brought about by shorter and less number of intestinal villi: *', 'non-tropical sprue', 'Non-tropical sprue (commonly known as celiac disease or gluten-sensitive enteropathy) is an autoimmune disorder triggered by ingesting gluten. The immune system mistakenly attacks the lining of the small intestine, leading to severe inflammation, crypt hyperplasia, and structural damage characterized by the shortening, flattening, and reduction in the number of intestinal villi (villous atrophy). Since villi are responsible for expanding the surface area of the gut, their damage drastically impairs nutrient absorption.', '["ulcerative colitis","tropical sprue","short gut syndrome","non-tropical sprue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:22:50.163Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:22:50.163Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:22:50.340Z"'::jsonb),
('anki-card-1758788368667-131', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Treatment for constipation: *', 'high fiber foods', '', '["high fiber foods","rest after meals","low fiber foods","limited fluids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:44:39.172Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:44:39.172Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T15:44:39.261Z"'::jsonb),
('anki-card-1758788218074-116', 'anki-deck-1783610488281-1790433142627-pf2m5', 'An NPO diet is indicated prior to surgery to: *', 'prevent vomiting', '• The Risk of Anesthesia: General anesthesia relaxes the body''s protective airway reflexes, including the gag and cough reflexes, and relaxes the lower esophageal sphincter.
• Prevention of Aspiration: If a patient has food or fluid in their stomach during surgery, they are at a very high risk of vomiting or experiencing passive regurgitation while unconscious. Because their airway reflexes are suppressed, the acidic stomach contents can easily enter the lungs (pulmonary aspiration), leading to severe aspiration pneumonia, chemical pneumonitis, or airway obstruction. Going NPO (Nothing by Mouth) ensures the stomach is empty and safe prior to the procedure.', '["avoid dehydration","prevent vomiting","reduce bowel movement","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T14:09:48.235Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T14:09:48.235Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T14:09:48.313Z"'::jsonb),
('anki-card-1758788142744-108', 'anki-deck-1783610488281-1790433142627-pf2m5', 'In an end-stage uremic patient, which of the following dietary management would you recommend for the patient’s maintenance regimen? *', '40 grams protein diet', 'End-stage renal disease (ESRD) results in the accumulation of nitrogenous waste products (urea, creatinine, uric acid) due to failing glomerular filtration. While non-dialyzed uremic patients require strict low-protein diets (0.6 to 0.8 g/kg/day) to delay uremic symptoms, patients on maintenance dialysis require higher protein intakes to counteract intradialytic amino acid losses and persistent catabolism induced by the dialysis procedure itself. A tailored moderate protein level, such as 40 grams or higher depending on body weight (with at least 50% high biological value proteins containing essential amino acids), ensures positive nitrogen balance, prevents visceral protein depletion, and limits the accumulation of uremic toxins between treatments.', '["protein-free diet","20 grams protein diet","40 grams protein diet","amino acid supplementation for better protein control"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:54:02.545Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:54:02.545Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:54:02.718Z"'::jsonb),
('anki-card-1758788862311-164', 'anki-deck-1783610488281-1790433142627-pf2m5', 'It can bring about severe malabsorption: *', 'laxatives', 'Chronic overuse or abuse of laxatives directly induces severe malabsorption syndromes. Laxatives unnaturally accelerate intestinal motility (peristalsis) or alter osmotic pressure, which forces food contents to rush through the gastrointestinal tract. This rapid transit time denies the small and large intestines the necessary window to digest and absorb essential macronutrients, fat-soluble vitamins (like Vitamin D), and electrolytes. Over time, this leads to structural steatorrhea, mineral depletion, and severe undernutrition.

• Diuretics: While diuretics heavily interfere with fluid balance and can lead to severe potassium depletion or dehydration through increased urinary excretion, they impact renal function rather than causing global nutrient malabsorption in the gut.
• Paracetamol: This is a standard over-the-counter analgesic and antipyretic. While acute toxicity or overdose causes severe hepatotoxicity (liver damage), standard therapeutic use does not impair the mucosal lining of the intestines or produce malabsorption.
• Cough Syrup: Typically containing antitussives or expectorants, these formulations do not target or compromise the digestive mechanics or metabolic transport systems of the small intestine.', '["diuretics","laxatives","paracetamol","cough syrup"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:49:00.972Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-21T12:49:00.972Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:49:00.972Z"'::jsonb),
('anki-card-1758788937423-172', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A client has had a poor appetite for several days. Strategies that may be used to improve his food intake may include any of the following except: *', 'feed the client by tube', '', '["assist the client during meals","serve foods that are easy to eat","feed the client by tube","provide energy- and nutrient-dense foods"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T07:08:40.718Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T07:08:40.718Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-30T07:08:40.718Z"'::jsonb),
('anki-card-1758789166179-194', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A patient with gout and uricemia will benefit from which diet prescription? *', 'low purine, 1g protein/kg BW, calorie restricted', '', '["low purine, adequate protein, 3 liters water","low purine, 1.5 g protein/kg BW, low alcohol","low purine, high CHO, adequate protein, low fat","low purine, 1g protein/kg BW, calorie restricted"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-16T01:22:23.517Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-13T01:22:23.517Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-13T01:22:23.603Z"'::jsonb),
('anki-card-1758789227159-199', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A cholesterol level of 240 mg/dL needs treatment with: *', 'diet, exercise, & drugs', 'In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.

Once total cholesterol hits the high threshold (240 mg/dL), guidelines recommend a multi-pronged medical intervention:
• Diet & Exercise: Initial and continuing therapeutic lifestyle changes—such as reducing saturated and trans fats, increasing dietary fiber, and initiating regular cardio—form the baseline of managing lipid profiles.
• Drugs: Because a level of 240 mg/dL significantly elevates the risk for coronary heart disease, stroke, and atherosclerosis, lifestyle changes alone are often insufficient. Pharmacological intervention (most commonly statins) is prescribed in tandem to inhibit hepatic cholesterol production and aggressively pull down circulating lipid levels.', '["diet","drugs","diet and drugs","diet, exercise, & drugs"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T13:54:24.889Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T13:54:24.889Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T13:54:24.968Z"'::jsonb),
('anki-card-1758788287071-123', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Preferred source of energy in COPD: *', 'fats', 'Patients with Chronic Obstructive Pulmonary Disease (COPD) struggle to exhale carbon dioxide (CO₂). Fats are the preferred energy source because they have a low Respiratory Quotient (around 0.7). This means that when the body metabolizes fats for energy, it produces less CO₂ per molecule of oxygen consumed compared to other macronutrients.

Meanwhile, Carbohydrates have an RQ of 1.0, meaning they produce the highest amount of CO₂ waste when broken down. This places an extra load on already compromised lungs, leading to respiratory distress.

A high-fat, low-carbohydrate diet helps reduce the overall burden on a COPD patient''s respiratory system while still providing adequate calories to fight tissue wasting.', '["protein","fats","carbohydrates","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, 'The primary reason fats are the preferred energy source in Chronic Obstructive Pulmonary Disease (COPD) comes down to the Respiratory Quotient (the ratio of carbon dioxide produced to oxygen consumed by the body). Fats have a low RQ of approximately 0.7, meaning their metabolism generates significantly less carbon dioxide (CO2) compared to other nutrients. ', '{"dueDate":"2026-10-11T14:10:16.286Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T14:10:16.286Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T14:10:16.361Z"'::jsonb),
('anki-card-1758788413748-135', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Diet therapy for a person with coronary heart failure may include: *', 'high calorie, high protein, low sodium diet', '', '["fat restrictions","fiber restrictions","potassium restriction","high calorie, high protein, low sodium diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:47:02.374Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-20T15:47:02.374Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T15:47:02.459Z"'::jsonb),
('anki-card-1758788449130-139', 'anki-deck-1783610488281-1790433142627-pf2m5', 'How much protein is allowed for patients with gout? *', '1 g/kg BW', 'According to nutritional standards and clinical practice guides for hyperuricemia and gout patients, the recommended daily dietary protein allowance is 1 g per kilogram of body weight (1 g/kg BW).

While a high total volume of protein is not responsible for raising uric acid levels, the source of the protein matters. Gout patients are encouraged to meet their standard protein requirement (1 g/kg BW) by focusing on low-purine or plant-based protein options (such as low-fat dairy, eggs, tofu, and legumes) while strictly limiting high-purine animal proteins like organ meats, red meat, and seafood.', '["0.5 g/kg BW","0.8 g/kg BW","1 g/kg BW","5 g/kg BW"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T13:45:17.911Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T13:45:17.911Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T13:45:17.987Z"'::jsonb),
('anki-card-1758788457648-140', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The best prescription for a female secretary with a height of 5 ft. 4 inches, weight of 70kg, and FBS of 7mmol/L: *', '1400 kcal/day', 'Step-by-Step Breakdown Using Standard Clinical Nutrition Formulas

To determine the best caloric prescription, we must calculate the patient''s Desirable Body Weight (DBW) and apply the correct activity factor adjusted for her clinical status (Overweight + Diabetic).

1. Find the Desirable Body Weight (DBW) using Tannhauser''s Method:
	• Convert height to centimeters: 5 ft. 4 inches = 64 inches * 2.54 = 162.56 cm
	• Deduct 100 from height in cm: 162.56 - 100 = 62.56 kg
	• Deduct 10% for the final DBW: 62.56 - 6.25 = 56.31 kg (rounded to 56 kg)

2. Evaluate her Clinical Status & Activity Level:
	• Current Weight: 70 kg (Since her DBW is 56 kg, she is significantly overweight).
	• FBS (Fasting Blood Sugar): 7.0 mmol/L (This meets the diagnostic threshold for Diabetes Mellitus).
	• Activity Level: As an office secretary, her physical activity is classified as Sedentary.

3. Apply the Weight Reduction/Diabetic Caloric Factor:
	• For a normal weight individual with a sedentary lifestyle, the baseline factor is 30 kcal/kg DBW.
	• However, because she is an overweight diabetic, a low-calorie weight reduction regimen is required to optimize insulin sensitivity. The textbook factor for weight reduction in sedentary individuals is 25 kcal/kg DBW.

4. Compute the Total Energy Requirement (TER):
	• TER = 56.31 kg (DBW) * 25 kcal/kg = 1407.75 kcal/day

Rounding to the nearest multiple of 100 as standard practice in dietetic prescriptions yields exactly 1400 kcal/day.', '["800 kcal/day","1000 kcal/day","1200 kcal/day","1400 kcal/day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:52:47.960Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:52:47.960Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:52:47.960Z"'::jsonb),
('anki-card-1758788522743-144', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Principal measured index of renal failure. *', 'urea', '', '["urea","hemoglobin","glucose","amino acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-30T07:02:10.230Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-29T07:02:10.230Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-29T07:02:10.230Z"'::jsonb),
('anki-card-1758788641138-157', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Method of feeding preferred when GIT is functional. *', 'oral', '', '["oral","gastrostomy","NGT","jejunostomy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T16:00:49.737Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T16:00:49.737Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-28T16:00:49.737Z"'::jsonb),
('anki-card-1758788914657-170', 'anki-deck-1783610488281-1790433142627-pf2m5', 'Azotemia is detected through the measurement of: *', 'blood urea nitrogen', '• Azotemia is a medical condition characterized by abnormally high levels of nitrogen-containing compounds (such as urea and creatinine) in the blood.
• Detection: It is primarily detected through a Blood Urea Nitrogen (BUN) test or a serum creatinine test, both of which indicate how well the kidneys are filtering out waste products.', '["blood urea nitrogen","calcium in blood","uric acid in urine","sodium in the spinal fluid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-03T07:08:58.820Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-30T07:08:58.820Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-09-30T07:08:58.820Z"'::jsonb),
('anki-card-1758789105216-188', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The fluid needs of a child whose body weight is 14kg is approximately: *', '1200ml', '', '["800ml","1000ml","1200ml","1300ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-22T12:57:11.292Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-21T12:57:11.292Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-21T12:57:11.458Z"'::jsonb),
('anki-card-1758788132261-107', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A 350-pound male is not seen while crossing the street and sustains bilateral femoral fractures. Later, he develops cellulites. You would: *', 'provide nutritional support to maintain body protein', 'During acute metabolic stress, the body aggressively breaks down skeletal muscle to mobilize amino acids for immune function and tissue healing. Providing adequate nutritional support with an emphasis on high protein content is critical to attenuate this muscle wasting, support the immune response to fight the cellulitis, and promote bone healing.

Even though the patient is severely obese at 350 pounds, a period of acute, multi-system trauma is not the time to induce a caloric deficit for the purpose of long-term fat loss. Restricting nutrients or feeding him strictly for weight loss would starve the wound healing process and drastically worsen net protein catabolism.', '["provide nutritional support to maintain body protein","calculate requirement based upon ideal body weight","provide hypocaloric feedings to facilitate weight loss","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T14:00:44.680Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T14:00:44.680Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-10T14:00:44.680Z"'::jsonb),
('anki-card-1758789218745-198', 'anki-deck-1783610488281-1790433142627-pf2m5', 'A patient with a BMI of 42 will benefit from which diet prescription? *', '1200 kcal, 55% kcal from CHO, fat restricted', 'In traditional dietetic practice, a 1200 kcal diet is considered the gold-standard baseline weight-reduction diet for adults. It is widely recognized as the lowest safe calorie level that an individual can consume while still being able to meet all their essential vitamin and mineral requirements without mandatory medical supplementation.

"Fat Restricted" over Percentage Targets: Classic medical diet prescriptions for severe obesity prioritize explicit qualitative restrictions like "fat restricted" or "low fat" rather than precise percentage numbers. Because fat is the most calorie-dense macronutrient (9 kcal per gram), strictly restricting visible fats, fried foods, and high-fat items is the most direct clinical method used to ensure the patient adheres to a low-calorie limit.

Macronutrient Balance: Keeping carbohydrates at 55% ensures the patient receives enough complex carbohydrates to maintain energy levels and prevent ketosis, while the remaining calories are split between protein and minimal essential fats.', '["800 kcal, 55% kcal from CHO, 25% from fat","1000 kcal, 55% kcal from CHO, 12% from protein","1200 kcal, 55% kcal from CHO, fat restricted","1300 kcal, 55% kcal from CHO, 25% from fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-16T02:59:01.055Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-13T02:59:01.055Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-13T02:59:01.130Z"'::jsonb),
('anki-card-1758789202878-197', 'anki-deck-1783610488281-1790433142627-pf2m5', 'The amount of kcal/KBW for bulimic patients on a weight maintenance diet: *', '25 kcal/KDBW', 'Research demonstrates that patients with bulimia nervosa who are in a weight-stable or weight-maintenance phase often have a significantly depressed metabolic rate. This is primarily caused by a history of chronic, severe energy restriction, chaotic eating cycles, and purging behaviors.

While a typical healthy, sedentary adult requires approximately 30 kcal/kg/day for weight maintenance, clinical evaluations show that weight-stable bulimic patients require fewer calories—typically averaging around 22 to 25 kcal per kilogram of body weight to maintain their weight.', '["20 kcal/KDBW","25 kcal/KDBW","35 kcal/KDBW","30 kcal/KDBW"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-21T15:30:12.320Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-20T15:30:12.320Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-10-20T15:30:12.408Z"'::jsonb),
