INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1755156542081-127', 'anki-deck-1755151710403-1790432463944-n11t8', 'This type of kitchen arrangement allows the refrigerator, range, and sink to be spaced out for efficiency and convenience:', 'U-shaped', 'The U-shaped kitchen layout spans across three adjacent walls. Because it utilizes three separate surfaces, it is considered the most efficient arrangement for maximizing the work triangle. It perfectly allows the refrigerator, range, and sink to be widely spaced out on their own designated walls. This spacing provides dedicated counter segments around each major appliance, creating optimal flow, reducing traffic interference, and making meal prep highly convenient.

• Single line: Places all three major appliances flat against a single wall. This forces an assembly-line setup where components are crammed tightly together rather than being broadly spaced out.
• Island type: Adds a detached island workstation to an existing configuration. While highly versatile, the island itself does not inherently dictate the baseline spacing of the main three appliances.
• L-shaped: Spreads the work area along two perpendicular walls. While highly efficient for open floor plans, it forces at least two of the three main appliances to share a single wall line, making it less spaced out than a full three-walled U-shape.', '["single line","L-shaped","U-shaped","island type"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:56:13.354Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:56:13.354Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:56:13.354Z"'::jsonb),
('anki-card-1755156522284-126', 'anki-deck-1755151710403-1790432463944-n11t8', 'Size of dinner napkin:', '18-26 inches', 'The standard size for a dinner napkin is 18-26 inches (typically spanning 18–20 inches square for informal or everyday use, though formal dinner napkins can range up to 20–26 inches). 

• Informal / Everyday Dinner: 18 to 20 inches square
• Formal / Multi-Course Dinner: 20 to 26 inches square
• Purpose: Large enough to unfold and cover the lap completely', '["24-30 inches","9-12 inches","20-24 inches","18-26 inches"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:40.856Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:51:40.856Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:40.856Z"'::jsonb),
('anki-card-1755156497500-125', 'anki-deck-1755151710403-1790432463944-n11t8', 'The most important work center is the __________.', 'sink', 'The sink is commonly regarded as the most important work center because food preparation and cleanup require frequent access to water.', '["sink","gas range","refrigerator","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:02:56.861Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:02:56.861Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:02:56.861Z"'::jsonb),
('anki-card-1755156460303-124', 'anki-deck-1755151710403-1790432463944-n11t8', 'The sum of the sides of a work triangle must not exceed:', 'both a and b', 'The kitchen work triangle is an efficiency design principle that connects the three main work areas: the sink, the stove, and the refrigerator.

According to traditional residential space planning and board exam standards, the total perimeter (the sum of all three sides) should ideally be between 12 to 22 feet.

When converting 22 feet into the metric system (22 x 0.3048), it equals approximately 6.7 meters.', '["22 ft","6.5m","both a and b","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:43:23.383Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:43:23.383Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:43:23.383Z"'::jsonb),
('anki-card-1755156411788-123', 'anki-deck-1755151710403-1790432463944-n11t8', 'Fast Food combo meals are', 'Semi a la carte', 'Semi a la carte is when an entrée or main item is bundled together with specific side dishes (such as French fries and a beverage) and sold at a single, combined price. 

• Ala carte: Items are listed and priced completely separate from one another.
• Table d''Hote: This refers to a complete multi-course meal (from appetizer, soup, to main course, and dessert) served at a fixed total price with some options in some categories, usually found in banquets or fine dining rather than fast food.', '["Ala carte menus","Semi a la carte","Table d’Hote","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:52:14.647Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:52:14.647Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:52:14.647Z"'::jsonb),
('anki-card-1755156381173-122', 'anki-deck-1755151710403-1790432463944-n11t8', 'The following tasks are done from the right of the guest, EXCEPT:', 'serving bread', 'Bread is conventionally served from the left, whereas flatware and beverage ware are generally placed, served, or cleared from the right.', '["laying of flatware","serving bread","setting and clearing of beverage ware","pouring of beverage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:24:54.848Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:24:54.848Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:24:54.848Z"'::jsonb),
('anki-card-1755156351540-121', 'anki-deck-1755151710403-1790432463944-n11t8', 'The following tasks are done from the left of the guest, EXCEPT:', 'setting and clearing of dinner plates', 'Dinner plates are served and cleared from the right side. All other options are presented and cleared from the left side of the guest.', '["setting and clearing of dinner plates","presenting and serving from platters","clearing of bread and butter plate","serving salad"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:13:17.116Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:13:17.116Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:13:17.116Z"'::jsonb),
('anki-card-1755156329475-120', 'anki-deck-1755151710403-1790432463944-n11t8', 'Type of service where food is prepared in the kitchen and carried in serving platters while the waitstaff serves all the guests.', 'Continental', 'Continental Service (also widely known as Russian Service or platter service) is a formal style of dining where all food is fully cooked, portioned, and arranged beautifully on serving platters inside the kitchen.

The waitstaff then carries these platters into the dining room and serves each guest individually from the platter onto their plates. 

• Country-style (or American/Family-style) involves placing large serving dishes on the table for guests to pass around and serve themselves. 
• Plated (or American Service) features food that is already portioned and arranged onto individual plates in the kitchen before being served. 
• Compromise is a hybrid service style where some courses are served directly from the kitchen and others are served at the table by the host or passed around.', '["Country-Style","Plated","Continental","Compromise"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T14:55:09.189Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T14:55:09.189Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T14:55:09.189Z"'::jsonb),
('anki-card-1755156283127-119', 'anki-deck-1755151710403-1790432463944-n11t8', 'Service style with table side service, EXCEPT:', 'American', 'In hospitality and food service management, American service (also commonly known as plate service) is explicitly defined as a style where food is completely portioned, arranged, and plated onto individual dishes inside the kitchen by the chefs. The waitstaff then carries these pre-plated meals directly out to the dining tables to serve the guests. Because everything is completed back in the kitchen, it involves absolutely no tableside assembly, carving, or serving from platters.

• Russian Service: Servers bring heavy silver platters containing large portions of food directly out to the dining room. They then walk around the table and use a spoon and fork to serve individual portions onto the guests'' empty plates tableside.
• French Service: This is the ultimate tableside service style. Food is brought out partially raw or undercooked on a rolling cart called a gueridon. Cooking, finishing (like flambéing), carving, and plating are executed right next to the guests'' seats.
• English Service: Large platters and tureens of food are placed directly onto the dining table right in front of the host. The host then carves the meat and portions the sides onto plates at the table, which are then passed down or distributed by the servers.', '["English","Russian","French","American"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:49.578Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:49.578Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:49.578Z"'::jsonb),
('anki-card-1755156222148-118', 'anki-deck-1755151710403-1790432463944-n11t8', 'In storing fruits, the following practices delay the ripening process EXCEPT:', 'wrapping fruits in newspaper', 'Wrapping unpeeled, whole fruits in newspaper accelerates ripening by trapping natural ethylene gas. It is also unsafe because toxic printing inks, heavy metals, and harmful chemicals leach directly into your food, especially when it is hot or oily.

Delays the ripening process:
• Separating ripe from unripe fruit slows ethylene exposure and delays ripening. 
• Refrigeration delays ripening process by slowing down enzyme activity.
• Wrapping in PET bags: Produce packaging often uses specific polymer films with micro-perforations or special barrier properties to let excess ethylene and carbon dioxide escape. This stops moisture buildup and prevents rapid decay.', '["storing fruits inside the refrigerator","wrapping fruits in newspaper","wrapping fruits in polyethylene bags","separating the ripe from the unripe"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:47:42.171Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:47:42.171Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:47:42.171Z"'::jsonb),
('anki-card-1755156195932-117', 'anki-deck-1755151710403-1790432463944-n11t8', 'The cost of materials that go directly into the production of the menu item.', 'food cost', 'Food cost is the cost of materials that directly enter into the production of a menu item; overhead costs are indirect operating expenses.', '["edible portion cost","as purchased cost","food cost","overhead cost"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:25:25.809Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:25:25.809Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:25:25.809Z"'::jsonb),
('anki-card-1755156163118-116', 'anki-deck-1755151710403-1790432463944-n11t8', 'The specific amount of product from the recipe in volume, weight, or number of servings.', 'yield', 'Yield is the specific amount of finished product obtained from a recipe, expressed as weight, volume, or number of portions.', '["trim loss","edible portion","yield factor","yield"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:32:06.881Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:32:06.881Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:32:07.074Z"'::jsonb),
('anki-card-1755156134767-115', 'anki-deck-1755151710403-1790432463944-n11t8', 'Clearing of the bread and butter plate is done at the __________________.', 'Left of the guest', 'Bread-and-butter plates are conventionally cleared from the guest''s left because they are placed on the left side of the cover.', '["Right of the guest","Left of the guest","Both a and b","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:25:44.706Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:25:44.706Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:25:44.706Z"'::jsonb),
('anki-card-1755156074537-114', 'anki-deck-1755151710403-1790432463944-n11t8', 'The Visayan version of Paksiw na Isda', 'Inun-unan', 'Inun-unan is a classic Visayan fish dish cooked in vinegar, ginger, garlic, onions, and chili peppers. It is the direct Visayan counterpart to the Tagalog Paksiw na Isda, with the traditional distinction that Inun-unan typically does not include any water, soy sauce, or vegetables like eggplant and ampalaya, making the vinegar and ginger profile much sharper.

• Higado: A traditional Ilocano savory dish made from pork tenderloin, pig liver, and other innards cooked with bell peppers, green peas, and vinegar.
• Lininta: A traditional Muslim-Filipino (Maranao) dish where fish is marinated with palapa (a spicy condiment made from native scallions, ginger, and chili), wrapped securely in banana leaves, and then steamed.
• Utan: A general Visayan term for vegetable soup or vegetable dishes (most commonly Utan Bisaya, a clear vegetable broth loaded with leafy greens, squash, okra, and fried/grilled fish).', '["Lininta","Utan","Inun-unan","Higado"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:46:26.647Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:46:26.647Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:46:26.647Z"'::jsonb),
('anki-card-1755156050955-113', 'anki-deck-1755151710403-1790432463944-n11t8', 'A popular dish from Davao and other parts of Mindanao that features internal organs cooked with pineapple and bell peppers.', 'Paklay', 'Paklay is a renowned traditional stew popular across the Visayas and Mindanao regions (especially in Davao and Cebu). It is made from a combination of sliced pork, beef, or goat internal organs (such as tripe, liver, heart, and kidneys) sautéed with ginger, bamboo shoots, bell peppers, and pineapple chunks. The pineapple plays a vital role by lending a subtle, refreshing sweetness and acidity that balances the rich, robust flavor of the offal.

• Sampayna: This is a Northern Mindanao (specifically Camiguin and Cagayan de Oro) variation of dinuguan (pork blood stew). It uses chitterlings and blood but does not feature the sweet pineapple or stir-fried bell pepper profile profile of paklay.
• Barbacoa: In a local context, this often sounds like Balbacua, a very popular viscous beef skin and trotters stew from Southern Mindanao that is slow-cooked with star anise and annatto rather than internal organs and fruit.
• Tiolah Sapi: A festive, sacred beef broth dish native to the Tausug people of the Sulu Archipelago in Mindanao. It features beef and tripe seared in burnt coconut paste (pamapa), giving it a signature green color and lemongrass-ginger profile, but it does not use pineapple.', '["Barbacoa","Sampayna","Paklay","Tiolah Sapi"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:45:29.767Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:45:29.767Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:45:29.767Z"'::jsonb),
('anki-card-1755156014590-112', 'anki-deck-1755151710403-1790432463944-n11t8', 'Aterm used for the Filipino cooking method of wrapping food in leaves', 'All of the above', 'Pinais refers to wrapping food in banana leaves and sometimes inner layers of kamamba (Piper umbellatum) or taro leaves before being cooked in coconut milk or steamed. 

Binagol is a sweet, dense kakanin (rice cake delicacy) from Leyte. It is made from grated gabi (taro root), condensed milk, and sugar, which is packed into a halved coconut shell (baong), wrapped in banana leaves, and securely tied before being steamed.

Binalot means "wrapped" in the Filipino language and refers to a traditional style of serving a complete meal wrapped inside a banana leaf.', '["Binalot","Binagol","Pinais","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:49:04.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:49:04.342Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:49:04.342Z"'::jsonb),
('anki-card-1755155988475-111', 'anki-deck-1755151710403-1790432463944-n11t8', 'Dish made of dried gabi leaves, coconut milk, siling labuyo, and bagoong.', 'Laing', 'Laing is an iconic Bicolano dish composed fundamentally of shredded dried gabi (taro) leaves, simmered slowly in creamy coconut milk (gata).

It is heavily spiced with sliced siling labuyo (bird''s eye chili) and seasoned with bagoong alamang (shrimp paste) along with pork or dried fish (daing) to give it its hallmark spicy and deeply savory profile. It is a culinary standard that the leaves must be completely dried before cooking to prevent the calcium oxalate crystals in the taro plants from causing an itchy sensation in the mouth.

• Pinangat: Also a famous taro leaf delicacy from Bicol (specifically Camalig, Albay), but it is distinctly made by wrapping a mixture of pork, shrimp, and young coconut meat inside layered pouches of fresh, whole gabi leaves before tying them with string and steaming them in seasoned coconut milk.
• Sinanglay: Another Bicolano coconut-milk-based favorite, but its centerpiece is whole fresh fish (like tilapia) stuffed with tomatoes and onions, which is then wrapped in fresh gabi or mustard leaves and cooked in spiced gata.
• Tinimtim: A traditional Ilocano dish primarily featuring saluyot (jute leaves) or ampalaya leaves simmered with garlic, vinegar, and bagoong. It does not utilize gabi leaves or coconut milk as core components.', '["Laing","Tinimtim","Pinangat","Sinanglay"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:51:18.627Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:51:18.627Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:51:18.627Z"'::jsonb),
('anki-card-1755155928127-109', 'anki-deck-1755151710403-1790432463944-n11t8', 'Considered as the best conductor of heat, this type of cookware material is commonly used as base for non-stick pans.', 'Copper', 'Aluminum: Lightweight, budget-friendly, heats quickly, and serves as the standard body or base for most non-stick cookware.

Copper: The absolute best heat conductor among common cookware metals, but it is expensive and rarely used as a cheap non-stick base.

Iron: Retains heat well but conducts slowly and is heavy.

Stainless steel: A poor direct conductor of heat, usually requiring an aluminum or copper core.', '["Aluminum","Iron","Copper","Stainless steel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:46:43.926Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:46:43.926Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:46:43.926Z"'::jsonb),
('anki-card-1755155892030-108', 'anki-deck-1755151710403-1790432463944-n11t8', 'The following statements help conserve nutrients in preparation and cooking, EXCEPT:', 'thaw frozen vegetables before cooking', 'You should never thaw frozen vegetables before cooking them. Thawing frozen vegetables allows their cell walls to collapse as they soften, causing water-soluble vitamins (such as Vitamin C and B-complex vitamins) to leach out into the liquid runoff, which is then discarded. To conserve the highest amount of nutrients, frozen vegetables should be cooked straight from the frozen state by steaming or dropping them directly into boiling water.

The other practices help conserve nutrients by minimizing leaching and excessive cooking.', '["foods should not be stirred","thaw frozen vegetables before cooking","baking soda should not be added","pots should be kept covered"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:14.578Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:51:14.578Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:14.578Z"'::jsonb),
('anki-card-1755155850133-107', 'anki-deck-1755151710403-1790432463944-n11t8', 'The following are spices EXCEPT:', 'Chives', 'Chives are classified as a culinary herb. They are the green, aromatic leaves of the plant (Allium schoenoprasum), used fresh or dried to add a mild onion-like flavor to dishes.

Cardamom, nutmeg, and sage are classified in culinary contexts as spices or flavoring botanicals according to the plant part and use.', '["Chives","Cardamom","Nutmeg","Sage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:27.020Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:27.020Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:27.020Z"'::jsonb),
('anki-card-1755155820867-106', 'anki-deck-1755151710403-1790432463944-n11t8', 'The following statements are true in Judaism, EXCEPT:', 'all grape varieties are restricted', 'Jewish dietary laws prohibit mixing meat and dairy, prohibit consumption of blood, and forbid shellfish. However, it is not correct that all grape varieties are restricted.', '["meat cannot be eaten with dairy","the Torah prohibits consumption of blood","all grape varieties are restricted","all types of shellfish are forbidden"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:40:39.613Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:40:39.613Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:40:39.613Z"'::jsonb),
('anki-card-1755158245467-184', 'anki-deck-1755151710403-1790432463944-n11t8', 'The principle that refers to the number of subordinates who report directly to a higher executive', 'Span of control', 'Span of control is the number of subordinates who report directly to a manager or higher executive.

• Departmentalization: The process of dividing an organization into distinct sections or departments based on functions, products, or geographic areas (e.g., separating a facility into a Kitchen Department, Purchasing Department, and Accounting Department).
• Unity of command: The management principle stating that each subordinate should receive orders from, and be accountable to, only one direct supervisor to prevent conflicting instructions.
• Delegation: The act of assigning authority, responsibility, and specific tasks from a higher-level manager down to a subordinate.', '["Span of control","Departmentalization","Unity of command","Delegation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:44:02.386Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:44:02.386Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:44:02.386Z"'::jsonb),
('anki-card-1755158261668-185', 'anki-deck-1755151710403-1790432463944-n11t8', 'Budget that is used to determine if funds will be available when needed:', 'Cash', 'Cash Budget tracks expected cash inflows and outflows. Its primary purpose is to manage liquidity, allowing managers to forecast cash positions and ensure that enough cash is available when needed to meet immediate obligations like payroll or supplier bills. 

• Master Budget: This is a comprehensive, overarching financial plan that consolidates all individual functional budgets (including operating, capital, and financial budgets). 
• Operating Budget: This focuses on day-to-day revenue-generating activities, such as projected sales, production, and routine operating expenses. It does not measure actual cash timing.
• Capital Budget: This is a long-term plan dedicated to major asset investments, such as buying property, new machinery, or technology', '["Master","Operating","Capital","Cash"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:46:03.165Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:46:03.165Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:46:03.165Z"'::jsonb),
('anki-card-1755158296132-186', 'anki-deck-1755151710403-1790432463944-n11t8', 'Lenten observance among Roman Catholics prescribes abstinence from:', 'Meat', 'Roman Catholic Lenten abstinence traditionally prescribes abstaining from meat on designated days. Fish and other non-meat foods may be consumed.', '["Fish and shellfish","Vegetables","Meat","Fruits"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:23:06.952Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:23:06.952Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:23:06.952Z"'::jsonb),
('anki-card-1755158338597-187', 'anki-deck-1755151710403-1790432463944-n11t8', 'The optimum working Tº is between:', '65-73ºF', 'The optimum working temperature for productivity and human comfort in an office environment is typically between 65–73ºF (18–23ºC).', '["60-71ºF","3-72ºF","65-73ºF","67-74ºF"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:37.026Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:51:37.026Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:37.026Z"'::jsonb),
('anki-card-1755158463108-191', 'anki-deck-1755151710403-1790432463944-n11t8', 'Information which is/are useful for time and motion studies:', 'all of the above', 'Job breakdowns, process charts, and flow charts can all provide information useful in time-and-motion studies.', '["job breakdown","process chart","flow chart","all of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:40:49.936Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:40:49.936Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:40:49.936Z"'::jsonb),
('anki-card-1755158487407-192', 'anki-deck-1755151710403-1790432463944-n11t8', 'Broiler is a term used to refer to', 'Chicken', 'Broiler is a market term for a young chicken suitable for broiling or similar dry-heat cooking.

• Young or middle-aged pork: Swine or pigs are categorized into culinary and market classes such as suckling pig (lechon de leche), boar, sow, or gilt. The term "broiler" is never applied to pork or any mammalian livestock.', '["Chicken","Young pork","Middle-aged pork","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:21:02.441Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:21:02.441Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:21:02.441Z"'::jsonb),
('anki-card-1755157217084-150', 'anki-deck-1755151710403-1790432463944-n11t8', 'Management by Objective implies the need to have', 'Clearly defined key result areas and time', 'Management by Objectives (MBO) is a strategic management model that aims to improve organizational performance by aligning employee goals with the overall objectives of the company. It fundamentally relies on setting specific, measurable targets (Key Result Areas) within a designated timeframe so that progress can be tracked objectively.', '["A good manager","Clear organizational chart","Clearly defined key result areas and time","Adequate staff"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:29:45.196Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:29:45.196Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:29:45.377Z"'::jsonb),
('anki-card-1755158518621-193', 'anki-deck-1755151710403-1790432463944-n11t8', 'It is a special type of broiler used in foodservice that makes use of overhead infrared heating.', 'Salamander', 'A salamander is a specialized broiler that applies intense overhead infrared or radiant heat for browning, finishing, or broiling.

In professional kitchens and food service operations, it is primarily used for rapid top-browning, melting cheese (such as on French onion soup or lasagna), crisping meat fat, or lightly caramelizing sugar coatings without cooking the interior of the dish further.

• Rotisserie: A cooking appliance or attachment where meat (often whole chickens) is skewered on a spit and slowly rotated over or next to a heat source for even roasting.
• Bain-marie: A hot water bath system used in commercial food lines to hold cooked food at safe, warm serving temperatures. It does not cook, broil, or emit infrared heat.
• Microwave: An appliance that cooks food by using electromagnetic radiation waves to excite water molecules within the food, generating friction and volumetric heat rather than overhead radiant grilling.', '["Baine Marie","Rotisserie","Microwave","Salamander"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:20:54.340Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:20:54.340Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:20:54.340Z"'::jsonb),
('anki-card-1755158541819-194', 'anki-deck-1755151710403-1790432463944-n11t8', 'It refers to a Vietnamese baguette sandwich.', 'Bahn mi', 'Bánh mì is the Vietnamese baguette sandwich.

Gỏi cuốn are fresh spring rolls, nước chấm is a dipping sauce, and phở is a noodle soup.', '["Bahn mi","Goi cuon","Nuoc cham","Pho"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:47:24.078Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:47:24.078Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:47:24.078Z"'::jsonb),
('anki-card-1755155530413-102', 'anki-deck-1755151710403-1790432463944-n11t8', 'Roasted Suckling pig', 'Lechon de leche', 'In culinary terms and Spanish-Filipino food culture, a suckling pig is a young piglet that has fed exclusively on its mother''s milk (hence the word leche, meaning milk). When this young, tender piglet is slowly roasted whole over charcoal, it is specifically designated as Lechon de leche.

• Pritchon: A portmanteau of the words prito (fried) and lechon. It refers to a whole or chopped piglet that is deep-fried in oil rather than roasted over charcoal, often carved and wrapped in pita or mandarin pancakes.
• Lechon: A broad, generic term for any whole roasted pig. A standard lechon usually involves a fully matured, adult market hog rather than a young suckling piglet.', '["Pritchon","Lechon de leche","Lechon","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:40:06.265Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:40:06.265Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:40:06.265Z"'::jsonb),
('anki-card-1755155557163-103', 'anki-deck-1755151710403-1790432463944-n11t8', 'The place Calasiao is associated with what food.', 'Puto', 'Calasiao, a municipality in Pangasinan, is widely celebrated as the "Puto Capital of the Philippines".

Puto Calasiao is a bite-sized, semi-sweet steamed rice cake. It stands out because it is traditionally made using fermented short-grain glutinous rice (galapong), giving it a distinctively soft, chewy, and slightly springy texture.

While the classic white version is the most iconic, it is also sold in variations like ube (purple yam), pandan, cheese, mango, and strawberry.

• Buro: A fermented rice dish (often mixed with fish or shrimp) that is a famous condiment in neighboring Pampanga and other parts of Central/Northern Luzon.
• Patupat: A sweet Ilocano delicacy made of glutinous rice cooked in sugarcane juice and wrapped in a woven pouch of coconut or palm leaves. While found in Pangasinan, it is not uniquely synonymous with Calasiao the way puto is.
• Tocino: A sweet, cured pork breakfast meat most famously associated with Pampanga (the culinary capital of the Philippines).', '["Buro","Tocino","Patupat","Puto"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:17:21.669Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:17:21.669Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:17:21.669Z"'::jsonb),
('anki-card-1755155768935-105', 'anki-deck-1755151710403-1790432463944-n11t8', 'Linat-an is closest to the dish:', 'Nilaga', 'Linat-an is a traditional boiled pork soup dish native to the Visayas and Mindanao regions. Structurally and visually, it is almost identical to the Tagalog Nilaga. Both dishes involve simmering tough cuts of meat (usually pork ribs or beef) with an abundance of clear broth, paired with vegetables like cabbage, potatoes, leafy greens, and green beans.

The primary difference lies in the flavor aromatics: while Nilaga relies heavily on onions and whole black peppercorns, Linat-an incorporates distinct regional ingredients like lemongrass (tanglad), ginger, and sometimes red bell peppers or taro (gabi) to give the clear broth a more fragrant, refreshing, and slightly sweet flavor profile.', '["Nilaga","Kare-kare","Pochero","Cardillo"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T14:52:12.298Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T14:52:12.298Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T14:52:12.298Z"'::jsonb),
('anki-card-1755155591209-104', 'anki-deck-1755151710403-1790432463944-n11t8', 'It is a popular suman from Leyte flavored with chocolate', 'Moron', 'Moron is a native kakanin (sticky rice cake) originating from the Eastern Visayas region, particularly popular in Leyte (like Tacloban and Abuyog) and Eastern Samar. It is a type of suman made by twisting a milky vanilla-flavored white dough and a chocolate dough together. The chocolate flavor comes from cocoa or local tablea (cacao tablets).

It features a distinct marble swirl, a very smooth texture, and is often embedded with roasted peanuts before being wrapped in banana leaves and steamed. It is traditionally eaten as a snack (merienda) alongside hot coffee or sikwate (native hot chocolate).

• Binakol: A savory Filipino chicken soup traditionally cooked inside a bamboo tube or coconut shell using coconut water.
• Binagol: Another famous sweet delicacy from Leyte (specifically Dagami), but it is made from mashed talyan (taro root crop), condensed milk, and coconut milk, then steamed inside a coconut shell (bagol).
• Baye-baye: A popular Western Visayas (Iloilo/Negros) delicacy made from toasted ground rice or corn mixed with coconut water and sugar.', '["Binagol","Binakol","Moron","Baye-baye"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:15:05.914Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:15:05.914Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:15:05.914Z"'::jsonb),
('anki-card-1755156584596-128', 'anki-deck-1755151710403-1790432463944-n11t8', 'A set meal with a choice within menu categories is called:', 'table d''hote', 'Table d’hote is a fixed-price, multi-course meal where guests select from a limited number of choices within specific categories (like appetizer, main, and dessert). 

• Semi à la carte: A menu type where some items (usually the main entree) are priced individually, but automatically include specific side components (like a soup, salad, or potato) at no extra charge.
• Prix Fixe: A similar fixed-price menu concept with no choices.', '["table d''hote","prix fixe","semi a la carte","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:22.684Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:22.684Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:22.684Z"'::jsonb),
('anki-card-1755155482248-100', 'anki-deck-1755151710403-1790432463944-n11t8', 'Northern Philippines’ version of sisig', 'Dinakdakan', 'Dinakdakan is an authentic delicacy from the Ilocos region in the Northern Philippines. Much like Kapampangan sisig, it is made by boiling and then charcoal-grilling various pig parts (such as the ears, face/jowl, and tongue).

The primary structural differences are that dinakdakan is typically sliced into thin strips rather than being finely minced, and it traditionally uses boiled pig''s brain mashed into a vinegar-calamansi dressing to achieve its signature rich, creamy texture (whereas modern commercial sisig often replaces this with mayonnaise or egg).

• Baguisen: A traditional Ilocano organ meat stew cooked with pig or goat intestines, liver, and heart thickened with pork blood and soured with vinegar or kamias. It is closer in profile to dinuguan.
• Lininta: A traditional Muslim-Filipino (Maranao) dish consisting of fresh fish marinated with palapa, wrapped tightly in banana leaves, and gently steamed.
• Dinardaraan: The strict Ilocano version of dinuguan (pork blood stew). Unlike the Tagalog version which has plenty of thick gravy, dinardaraan is famously cooked until the sauce completely reduces, leaving a much drier, oilier coat on the meat.', '["Lininta","Baguisen","Dinakdakan","Dinardaraan"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:49:26.145Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:49:26.145Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:49:26.145Z"'::jsonb),
