INSERT INTO public.flashcards (id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES 
('anki-card-1788426139224-56', 'anki-deck-1788422977034-1791992590890-w1g2h', 'According to the updated Labor Code (RA 11360) of the Philippines, what percent of the service charge goes to the management?', '0%', 'Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. 

Historical Context 
• Old Rule (Pre-2019): Under the original text of Article 96 of the Labor Code, 85% went to the employees and 15% was retained by management.
• New Rule (2019 Onward): The 15% management share was completely removed, making the employee share 100%.', '["0%","20%","15%","30%"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:31:01.856Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:31:01.856Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:31:01.856Z"'::jsonb),
('anki-card-1788423963494-24', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which noodle is traditionally used in lomi?', 'Miki', 'Miki is the thick fresh egg noodle commonly associated with lomi.

• Sotanghon is a glass or cellophane noodle made from mungbean.
• Bihon is a thin rice vermicelli noodle.
• Miswa is a thin wheat noodle and is not the traditional noodle identified for lomi.', '["Miki","Miswa","Sotanghon","Bihon"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:27:13.423Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:27:13.423Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:27:13.423Z"'::jsonb),
('anki-card-1788426090282-55', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which of the following is not one of the five classical French mother sauces?


<img alt="Basic Béchamel Sauce" src="data:image/jpeg;base64," width="201">a. Béchamel
<img alt="Classic Velouté Sauce (French Mother Sauce)" src="data:image/jpeg;base64," width="203">b. Velouté
<img alt="Hollandaise Sauce" src="data:image/jpeg;base64," width="201">c. Hollandaise
<img alt="Best Marinara Sauce Yet" src="data:image/jpeg;base64," width="201">d. Marinara', 'Marinara', 'The five classical French mother sauces codified by chef Auguste Escoffier:Bechamel, Veloute, Espagnole, Tomato, Hollandaise

These foundational recipes use a liquid combined with a thickening agent (like a roux or emulsion) to create dozens of secondary "daughter" sauces.', '["Marinara","Hollandaise","Velouté","Béchamel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2027-05-12T14:48:40.247Z","interval":195,"easeFactor":2.3,"repetitions":7}'::jsonb, '"2026-10-29T14:48:40.247Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T14:48:40.457Z"'::jsonb),
('anki-card-1788423929024-23', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which artificial sweetener is associated with phenylketonuria?', 'Aspartame', 'Aspartame is associated with phenylketonuria (PKU) because it contains phenylalanine. Individuals with PKU cannot properly metabolize phenylalanine, so they need to restrict their intake. This is why products containing aspartame carry a warning for people with PKU.', '["Aspartame","Saccharin","Acesulfame-K","Sucralose"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:29:36.932Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:29:36.932Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:29:36.932Z"'::jsonb),
('anki-card-1788423421410-11', 'anki-deck-1788422977034-1791992590890-w1g2h', 'The soul of every foodservice operation.', 'Menu', 'In foodservice management, the menu is universally referred to as the "soul," focal point, or primary control of the entire operation.

It dictates everything that happens in the facility—including purchasing, budget, required equipment, staff skill levels, kitchen layout, and guest satisfaction.', '["Dietitian","Menu","Meal Plan","Income generation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:16.661Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:16.661Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:16.661Z"'::jsonb),
('anki-card-1788423894307-22', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which condition can cause milk proteins to coagulate?', 'Acidification', 'Lowering milk pH through acidification can cause milk proteins, particularly casein, to coagulate.

• Freezing alone does not describe the usual mechanism of milk-protein coagulation. 
• Homogenization reduces fat globule size and does not itself cause the described coagulation.
• Refrigeration alone does not normally coagulate milk proteins.', '["Acidification","Refrigeration","Freezing alone","Homogenization"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:27:40.615Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:27:40.615Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:27:40.615Z"'::jsonb),
('anki-card-1788423788676-20', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which of the statements is correct:', 'Balut is a fertilized duck egg that has been incubated before cooking', 'Balut is a famous Filipino street food consisting of a fertilized duck egg. It is traditionally incubated in heated rice husks for roughly 14 to 21 days (usually 18 days) to allow a semi-developed duck embryo to form inside before it is hard-boiled or steamed.

Penoy: is an unfertilized duck egg that is boiled and consumed. It does not contain a developing duck embryo.', '["Balut is a fertilized duck egg that has been incubated before cooking","Balut is an unfertilized duck egg","Penoy is a fertilized duck egg that has been incubated before cooking","Penoy is a fertilized chicken egg"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:27:36.949Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:27:36.949Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:27:36.949Z"'::jsonb),
('anki-card-1788423717984-19', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A fish with its viscera removed but its head, fins, and tail retained is described as:', 'Drawn', 'A drawn fish is a whole fish that has had only its internal organs (viscera or entrails) removed. The head, fins, scales, and tail all remain completely intact.

• A whole fish has not had the viscera removed.
• A dressed fish has undergone additional preparation beyond simply drawing. • A fish that has been drawn, but has also had its head, tail, fins, and scales completely removed.
• A filleted fish has the flesh separated from the bones, usually into fillets. The boneless side of a fish cut lengthwise away from the backbone.', '["Drawn","Whole","Fillet","Dressed"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:27:50.347Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:27:50.347Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:27:50.347Z"'::jsonb),
('anki-card-1788423684095-18', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which of the following is a recommended minimum internal temperature for cooked seafood?', '145°F', 'According to USDA Food Safety and Inspection Service

• All Poultry: 165°F (74°C) for whole birds, breasts, legs, thighs, wings, and ground poultry.
• Stuffing & Casseroles: 165°F (74°C).
• Leftovers: 165°F (74°C) to reheat thoroughly.
• Ground Meats: 160°F (71°C) for beef, pork, veal, and lamb. 
• Egg Dishes: 160°F (71°C) for frittatas and quiches.
• Beef, Pork, Veal, and Lamb: 145°F (63°C) for steaks, chops, and roasts, followed by a 3-minute rest time.
• Fish and Shellfish: 145°F (63°C) or until the flesh is opaque and flakes easily.', '["145°F","125°F","135°F","165°F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:29:03.169Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:29:03.169Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:29:03.169Z"'::jsonb),
('anki-card-1788423629355-17', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Chevon refers to meat from:', 'Goat', 'Chevon is the official culinary term for the meat of an adult goat. It comes from the French word for goat, chèvre.

You may also see young goat meat referred to as cabrito or simply called mutton in certain regions (like India and parts of Asia), though in formal culinary terms, mutton belongs to another animal.

• Sheep meat is commonly called mutton (2-3yo) or lamb 
• Deer meat is commonly called venison.
• Rabbit meat is usually referred to simply as rabbit or lapan (in some culinary contexts).', '["Goat","Sheep","Rabbit","Deer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:28:02.405Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:28:02.405Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:28:02.405Z"'::jsonb),
('anki-card-1788423597450-16', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which vitamin is particularly susceptible to losses during food processing?', 'Vitamin C', 'Vitamin C is highly sensitive to heat, oxygen, and water and is readily lost during some processing methods.

• Vitamin D is generally more stable under ordinary food-processing conditions.
• Vitamin K is not typically identified as the vitamin most susceptible to processing losses in this context.
• Vitamin B12 can also be lost during cooking but is more heat-tolerant', '["Vitamin C","Vitamin B12","Vitamin D","Vitamin K"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:44.749Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:44.749Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:44.749Z"'::jsonb),
('anki-card-1788423566053-15', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which food is a well-known source of lycopene?', 'Tomato', 'Lycopene is a powerful antioxidant and a bright red carotenoid hydrocarbon.

Tomatoes and tomato-based products (like tomato paste, ketchup, and sauces) are the most abundant dietary sources of lycopene. Interestingly, cooking tomatoes and combining them with a little fat (like olive oil) actually increases the bioavailability of lycopene, making it easier for the body to absorb.

• Cauliflower - glucosinolates because cruciferous (sulfur + nitrogen)
• Cabbage - glucosinolates because cruciferous (sulfur + nitrogen)
• Potato - carbohydrates', '["Tomato","Potato","Cauliflower","Cabbage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:29:31.974Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:29:31.974Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:29:31.974Z"'::jsonb),
('anki-card-1788423528755-14', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Carotenoid pigments are generally:', 'Relatively stable to mild acid compared with chlorophyll', 'Compared with chlorophyll, carotenoids are relatively stable to mild acid conditions. They contain around 40 carbon backbone, atleast 8 isoprene units.

• Carotenoids are not generally destroyed immediately by mild acid.
• Acid does not convert carotenoids into chlorophyll. These are two completely different structures.
• Chlorophyll, not carotenoids, is primarily responsible for green vegetable color.', '["Relatively stable to mild acid compared with chlorophyll","Highly destroyed immediately by mild acid","Responsible for green vegetable color","Converted into chlorophyll by acid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:27:17.519Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:27:17.519Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:27:17.519Z"'::jsonb),
('anki-card-1788423489542-13', 'anki-deck-1788422977034-1791992590890-w1g2h', 'The desired product of jelly making is generally a:', 'Clear, firm gel', 'By culinary and food science standards, a perfect jelly must be a clear, sparkling liquid that has been trapped in a firm, shimmering gel network. It should hold its shape when turned out of a container but remain tender enough to cut or spoon easily.

This specific texture is achieved through the precise chemical balance of three structural elements: pectin (the gelling agent), acid (which prompts the pectin to form a network), and sugar (which bonds with water to assist the pectin).

• Thick emulsion: This describes a mixture of two unmixable liquids, like oil and water (e.g., mayonnaise or hollandaise sauce).
• Foamy suspension: This is a mixture of gas bubbles trapped in a liquid or solid (e.g., whipped cream or meringue). In fact, foam is an undesirable byproduct in jelly making that must be skimmed off during boiling.
• Crystalline sugar mass: This occurs when a jelly fails, and the sugar recrystallizes, resulting in a gritty, grainy texture instead of a smooth gel.', '["Clear, firm gel","Thick emulsion","Foamy suspension","Crystalline sugar mass"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:28:59.174Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:28:59.174Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:28:59.174Z"'::jsonb),
('anki-card-1788423454492-12', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which statement best describes dietary fiber?', 'It consists largely of nondigestible carbohydrate components and related substances', 'Dietary fiber is a broad term for the structural components of plant foods—including polysaccharides like cellulose, hemicellulose, pectins, and non-carbohydrate polymers like lignin.

Unlike sugars and starches, the human digestive system lacks the specific enzymes needed to break down the chemical bonds found in dietary fiber. As a result, it passes through the stomach and small intestine relatively intact.

• It is a form of animal protein: Fiber is exclusively derived from plant foods (fruits, vegetables, grains, legumes, nuts); animal products contain zero dietary fiber.
• It is composed entirely of dietary fat: Fiber belongs to the carbohydrate family of macronutrients, not fats or lipids.
• It is completely digested in the small intestine: Fiber resists enzymatic breakdown in the small intestine completely. Instead, it moves into the large intestine (colon), where it is either partially fermented by beneficial gut bacteria (soluble fiber) or excreted unchanged (insoluble fiber).', '["It is completely digested in the small intestine","It consists largely of nondigestible carbohydrate components and related substances","It is composed entirely of dietary fat","It is a form of animal protein"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:11.321Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:11.321Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:11.321Z"'::jsonb),
('anki-card-1788423404885-10', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A menu that repeats according to a planned sequence over a specified period is called a:', 'Cycle menu', 'A cycle menu features a series of menus that repeat in a set pattern (such as weekly, bi-weekly, or monthly) over a designated period.

 This is widely used in institutional settings like schools, hospitals, long-term care facilities, and corporate cafeterias to simplify purchasing, control costs, and maintain dietary variety.

• Du jour menu: A menu "of the day" that changes daily depending on what is fresh or left over.
• Single-use menu: A menu planned and used only once, typically for a special event, holiday banquet, or one-time catered function.
• Static menu: A fixed menu that remains the same every day, commonly found in commercial restaurants.', '["Static menu","Cycle menu","Du jour menu","Single-use menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:31:14.287Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:31:14.287Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:31:14.483Z"'::jsonb),
('anki-card-1788423386950-9', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Acrolein is associated with:', 'Overheated fats', 'Acrolein can form when fats are overheated, particularly when glycerol components break down.

• Fermented milk is associated with lactic acid fermentation rather than acrolein formation.
• Gelatinized starch results from starch absorbing water and swelling during heating.
• Fresh fruits are not the food phenomenon described by acrolein formation.', '["Overheated fats","Fresh fruits","Fermented milk","Gelatinized starch"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:28:30.217Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:28:30.217Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:28:30.217Z"'::jsonb),
('anki-card-1788423352226-8', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Cooking an egg primarily causes its proteins to undergo:', 'Denaturation and coagulation', 'Egg proteins denature and then coagulate during cooking, changing the egg from a fluid to a firmer structure.

• Gelatinization is a starch phenomenon involving starch and water under heat.
• Caramelization is a nonenzymatic browning reaction involving sugars.
• Retrogradation refers primarily to reassociation of starch molecules after gelatinization.', '["Denaturation and coagulation","Gelatinization","Retrogadation","Caramelization"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:06.391Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:06.391Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:06.391Z"'::jsonb),
('anki-card-1788423318292-7', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A nonenzymatic browning reaction associated with sugar undergoing heating; prolonged heating above one hundred sixty (>160) degrees Celsius (three hundred twenty (32) degrees Fahrenheit) resulting in dark brown, highly viscous syrup with distinctive taste and odor.', 'Caramelization', 'Caramelization is a type of non-enzymatic browning that involves the thermal decomposition and pyrolysis of sugars alone, completely independent of proteins or amino acids.

Common disaccharides like sucrose (table sugar) and monosaccharides like glucose melt and begin to caramelize rapidly at around 160°C (320°F). Prolonged heating creates complex polymers (caramelans, caramelens, and caramelins) and volatile flavor compounds, transforming clear sugar crystals into a dark, thick, highly aromatic syrup.

• Oxidation is a reaction with oxygen. 
• Maillard Browning is sugar + amino acids, not pure sugar.
• Reduction is the process of simmering or boiling a liquid uncovered so that water evaporates', '["Caramelization","Oxidation","Maillard browning","Reduction"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:51.885Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:51.885Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:51.885Z"'::jsonb),
('anki-card-1788424945169-42', 'anki-deck-1788422977034-1791992590890-w1g2h', 'The strain of E. coli that was initially identified as the cause of bloody diarrhea from eating undercooked or raw hamburger meat that was contaminated with the bacteria in the US in 1982.', 'Escherichia coli O157', 'O157:H7 – Causes bloody diarrhea, linked to hamburger outbreak.

• O111 – Pathogen but not outbreak strain.
• O26 – Also pathogenic, different cases.
• O104:H4 – Later outbreak in Europe.', '["Escherichia coli O157","Escherichia coli O26","Escherichia coli O111","Escherichia coli O104:H4"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:29:12.569Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:29:12.569Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:29:12.569Z"'::jsonb),
('anki-card-1788424979180-43', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A central facility prepares meals in large quantities and distributes the prepared meals to several remote service locations. Which system best fits this arrangement?', 'Commissary system', 'The commissary foodservice system (also referred to as a central kitchen or central production facility) concentrates food procurement and production in a single, large-scale facility.

Once the meals are prepared in bulk, they are packaged and transported to distinct, remote service locations (often called satellite units or receiving kitchens) for final finishing and service.

• À la carte system: A style of menu where items are priced and ordered separately, rather than a production and distribution system.
• Conventional system: The traditional model where food is purchased, prepared from scratch, and served on the same premises.
• Individualized system: A specialized approach focused on custom dietary tailoring (often used in clinical healthcare), not a bulk production and remote distribution network.', '["Conventional system","Commissary system","À la carte system","Individualized system"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:26:45.055Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:26:45.055Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:26:45.055Z"'::jsonb),
('anki-card-1788425016078-44', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Under PD 856, the minimum kitchen size for a 40 m² dining area is _____ .', '10 m²', 'According to the Implementing Rules and Regulations (IRR) of Chapter III (Food Establishments) of the Code on Sanitation of the Philippines (Presidential Decree No. 856), the kitchen area must be at least ¼ (25%) of the total dining area, provided it is not less than a base minimum of 9.30 m² (100 sq. ft.).

Calculation: Required Kitchen Size = 40 m² x ¼ = 10 m²

Since 10 m² meets the legal ratio and exceeds the minimum threshold of 9.30 m², it serves as the absolute statutory minimum required floor area for that setup.

• 12 m² – Not prescribed.
• 8 m² – Too small.
• 15 m² – Above requirement.', '["10 m²","12 m²","8 m²","15 m²"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:29:46.358Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:29:46.358Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:29:46.358Z"'::jsonb),
('anki-card-1788425044416-45', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which menu term means "of the day"?', 'Du jour', 'Du jour is a French phrase that literally translates to "of the day".

In restaurants, a du jour menu or item changes daily depending on what fresh ingredients are available or what specials the chef has created (e.g., "Soup du jour" means soup of the day).

• À la cart: Means "by the menu" or "from the menu"; items are listed, ordered, and priced individually.
• Table d''hôte: Means "the host''s table"; it offers a complete, multi-course meal with limited choices at a single fixed price.
• Prix fixe: Means "fixed price"; a set menu where customers pay a predetermined total price for a specific sequence of courses.', '["À la carte","Du jour","Table d''hôte","Prix fixe"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:29:49.103Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:29:49.103Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:29:49.103Z"'::jsonb),
('anki-card-1788425080995-46', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which should be a healthier option of market forms of milk for people who monitor their blood profiles?', 'Toned milk', 'Toned milk – Lower fat but retains protein and calcium, better for heart health.

• Whole milk – High in saturated fat, raises cholesterol.
• Condensed milk – Very high in sugar and fat.
• Evaporated milk – Concentrated, higher fat though no added sugar.', '["Toned milk","Whole milk","Condensed milk","Evaporated milk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:03.535Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:03.535Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:03.535Z"'::jsonb),
('anki-card-1788425462860-48', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which equipment provides gentle indirect heating through hot water and is commonly used to keep foods warm?


<img alt="Electric Salamander - Merit Stainless Steel" src="data:image/png;base64," width="199">a. Salamander
<img alt="6-Basket Electric Bain Marie – Eco Prima Home and Commercial Kitchen Supply" src="data:image/jpeg;base64," width="203">b. Bain-marie
<img alt="Why Outdoor Griddle Cooking Is Changing the Game for Foodies | Outeriors" src="data:image/jpeg;base64," width="203">c. Griddle
<img alt="Your Convection Oven Cooking Questions Answered | Stubbe''s BrandSource Home  Furnishings" src="data:image/jpeg;base64," width="203">d. Convection oven', 'Bain-marie', 'A bain-marie (also called a water bath) consists of an outer container filled with heated water and an inner container filled with food. The hot water surrounds the inner container, providing gentle, indirect, and uniform heat. This prevents delicate foods (like sauces or custards) from burning or curdling and is widely used in food service buffet lines to keep pre-cooked foods safely warm.

• A salamander is a high-heat broiling or finishing unit.
• A griddle provides direct dry heat through a heated surface.
• A convection oven uses circulating hot air for cooking or baking.', '["Bain-marie","Salamander","Griddle","Convection oven"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2027-05-12T14:48:37.999Z","interval":195,"easeFactor":2.3,"repetitions":7}'::jsonb, '"2026-10-29T14:48:37.999Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T14:48:38.196Z"'::jsonb),
('anki-card-1788425488824-49', 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which organization, together with WHO, established the Codex Alimentarius Commission?', 'FAO', 'The Codex Alimentarius Commission (CAC) was established in 1963 as a joint initiative between the Food and Agriculture Organization (FAO) of the United Nations and the World Health Organization (WHO).

Together, they created the Codex Alimentarius (Latin for "Food Code") to protect consumer health globally and promote fair, harmonized practices in international food trade.', '["FAO","WTO","UNICEF","UNESCO"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:28:55.908Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:28:55.908Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:28:55.908Z"'::jsonb),
('anki-card-1788425572314-50', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A manager finds that one leadership approach is effective with one employee but ineffective with another because their abilities, motivation, and work circumstances differ. Which approach recognizes that management practices should be adapted to the situation?', 'Contingency approach', 'The contingency approach holds that effective management depends on the situation and circumstances.

• Scientific management: systematic analysis of work and efficiency
• Bureaucratic management: formal structure, rules, and authority
• Classical management: broad principles of structure and efficiency', '["Contingency approach","Scientific management","Classical management","Bureaucratic approach"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:26:58.149Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:26:58.149Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:26:58.149Z"'::jsonb),
('anki-card-1788425608364-51', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A foodservice job posting specifies that applicants must have a bachelor''s degree, two years of supervisory experience, and specific technical competencies. These requirements are examples of:', 'Job specification', 'A job specification identifies the qualifications, experience, skills, and competencies required of the person performing the job.', '["Job specification","Job description","Job skills","Job evaluation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:30:42.004Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:30:42.004Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:30:42.004Z"'::jsonb),
('anki-card-1788425643449-52', 'anki-deck-1788422977034-1791992590890-w1g2h', 'The shortage of potatoes due to the war between Russia and Ukraine has an impact on the production of this known alcoholic beverage.', 'Vodka', 'Vodka –  While vodka can be distilled from various grains (like wheat or rye), potatoes are historically and traditionally one of its primary, iconic raw base ingredients.

• Gin: Typically distilled from a grain mash (like wheat or barley) and flavored heavily with juniper berries.
• Rum: Distilled exclusively from sugarcane byproducts, such as molasses or sugarcane juice.
• Brandy: Produced by distilling wine or fermented fruit mashes (most commonly grapes).

• Beer – Made from barley and hops.
• Wine – Made from grapes.
• Sake – Made from rice.', '["Vodka","Brandy","Gin","Rum"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 3, '', '{"dueDate":"2026-11-06T13:27:25.020Z","interval":8,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-29T13:27:25.020Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-10-29T13:27:25.020Z"'::jsonb),
('anki-card-1788425895111-53', 'anki-deck-1788422977034-1791992590890-w1g2h', 'A picture shows four pieces of institutional kitchen equipment. Which equipment would be most appropriate for large-volume soup production?


<img alt="Electric Salamander - Merit Stainless Steel" src="data:image/png;base64," width="199">a. Salamander
