INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a cholesterol level of 240 mg/dl needs treatment with::::diet, exercise, & drugs', 'a cholesterol level of 240 mg/dl needs treatment with:', 'diet, exercise, & drugs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diet, exercise, & drugs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.\n\nOnce total cholesterol hits the high threshold (240 mg/dL), guidelines recommend a multi-pronged medical intervention:\n• Diet & Exercise: Initial and continuing therapeutic lifestyle changes—such as reducing saturated and trans fats, increasing dietary fiber, and initiating regular cardio—form the baseline of managing lipid profiles.\n• Drugs: Because a level of 240 mg/dL significantly elevates the risk for coronary heart disease, stroke, and atherosclerosis, lifestyle changes alone are often insufficient. Pharmacological intervention (most commonly statins) is prescribed in tandem to inhibit hepatic cholesterol production and aggressively pull down circulating lipid levels.","whyWrongChoices":"Alternative options: diet, drugs, diet and drugs"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a cholesterol level of 240 mg/dl needs treatment with::::', 'a cholesterol level of 240 mg/dl needs treatment with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diet, exercise, & drugs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.\n\nOnce total cholesterol hits the high threshold (240 mg/dL), guidelines recommend a multi-pronged medical intervention:\n• Diet & Exercise: Initial and continuing therapeutic lifestyle changes—such as reducing saturated and trans fats, increasing dietary fiber, and initiating regular cardio—form the baseline of managing lipid profiles.\n• Drugs: Because a level of 240 mg/dL significantly elevates the risk for coronary heart disease, stroke, and atherosclerosis, lifestyle changes alone are often insufficient. Pharmacological intervention (most commonly statins) is prescribed in tandem to inhibit hepatic cholesterol production and aggressively pull down circulating lipid levels.","whyWrongChoices":"Alternative options: diet, drugs, diet and drugs"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the most practical type of storage in small stores is::::', 'the most practical type of storage in small stores is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reach-in units are used to store food products at point-of-use or used in central storage units in small operations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reach-in chiller\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reach-in units are used to store food products at point-of-use or used in central storage units in small operations.","whyWrongChoices":"Alternative options: Blast chiller, Walk-in chiller, Chest freezer"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.:::provitamin', 'the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.', 'provitamin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"provitamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).\n\n\t• Preformed vitamin: This describes a vitamin that is already in its fully active, biological state when ingested (such as retinol in animal products) and requires no internal conversion.\n\t• Vitamer: Vitamers are the multiple structural variations or chemical forms of a single vitamin that all possess similar vitamin activity (e.g., pyridoxine, pyridoxal, and pyridoxamine are all vitamers of Vitamin B₆).\n\t• Antivitamin: A chemical compound that actively blocks, inhibits, or destroys the biological action of a vitamin.","whyWrongChoices":"Alternative options: antivitamin, vitamer, preformed vitamin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.:::', 'the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"provitamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).\n\n\t• Preformed vitamin: This describes a vitamin that is already in its fully active, biological state when ingested (such as retinol in animal products) and requires no internal conversion.\n\t• Vitamer: Vitamers are the multiple structural variations or chemical forms of a single vitamin that all possess similar vitamin activity (e.g., pyridoxine, pyridoxal, and pyridoxamine are all vitamers of Vitamin B₆).\n\t• Antivitamin: A chemical compound that actively blocks, inhibits, or destroys the biological action of a vitamin.","whyWrongChoices":"Alternative options: antivitamin, vitamer, preformed vitamin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following statements are true regarding polysaccharides except::::amylose is made up of continuous, branched chains.', 'the following statements are true regarding polysaccharides except:', 'Amylose is made up of continuous, branched chains.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Amylose is actually a linear, unbranched chain of glucose units linked together by a-1,4-glycosidic bonds. Because it is unbranched, it naturally twists into a helical/spiral shape.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amylose is made up of continuous, branched chains.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Amylose is actually a linear, unbranched chain of glucose units linked together by a-1,4-glycosidic bonds. Because it is unbranched, it naturally twists into a helical/spiral shape.","whyWrongChoices":"Alternative options: They are polymers of glucose., Amylopectin has α-1,6 bonds., Glycogen is similar to amylopectin but is more highly branched"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:glycolysis occurs in the::::cytoplasm', 'glycolysis occurs in the:', 'cytoplasm', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cytoplasm\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.\n\nThis location is specific because all ten of the soluble enzymes required to catalyze the step-by-step breakdown of glucose are located freely within the cytoplasmic fluid.\n\n• Mitochondrial matrix: This is the internal fluid space of the mitochondria where the Krebs cycle (TCA cycle) and pyruvate oxidation happen.\n• Mitochondrial membrane: The inner mitochondrial membrane houses the proteins for the electron transport chain and oxidative phosphorylation.","whyWrongChoices":"Alternative options: mitochondrial matrix, mitochondrial membrane, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:glycolysis occurs in the::::', 'glycolysis occurs in the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cytoplasm\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.\n\nThis location is specific because all ten of the soluble enzymes required to catalyze the step-by-step breakdown of glucose are located freely within the cytoplasmic fluid.\n\n• Mitochondrial matrix: This is the internal fluid space of the mitochondria where the Krebs cycle (TCA cycle) and pyruvate oxidation happen.\n• Mitochondrial membrane: The inner mitochondrial membrane houses the proteins for the electron transport chain and oxidative phosphorylation.","whyWrongChoices":"Alternative options: mitochondrial matrix, mitochondrial membrane, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to a vietnamese baguette sandwich.:::', 'it refers to a vietnamese baguette sandwich.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bánh mì is the Vietnamese baguette sandwich.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bahn mi\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bánh mì is the Vietnamese baguette sandwich.\n\nGỏi cuốn are fresh spring rolls, nước chấm is a dipping sauce, and phở is a noodle soup.","whyWrongChoices":"Alternative options: Goi cuon, Nuoc cham, Pho"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this amino acid can form a special covalent bond called a disulfide bond.:::cysteine', 'this amino acid can form a special covalent bond called a disulfide bond.', 'cysteine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cysteine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.\n\n• Methionine: While methionine is the only other standard amino acid that contains sulfur, its sulfur atom is bound to a methyl group (a thioether group, -C-S-C-). Because it lacks a free, reactive -SH group, methionine cannot form disulfide bonds.\n• Lysine and Tyrosine: Neither of these amino acids contains sulfur in their side chains. Lysine contains an amino group, and tyrosine contains a phenolic hydroxyl group.","whyWrongChoices":"Alternative options: tyrosine, methionine, lysine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this amino acid can form a special covalent bond called a disulfide bond.:::', 'this amino acid can form a special covalent bond called a disulfide bond.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cysteine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.\n\n• Methionine: While methionine is the only other standard amino acid that contains sulfur, its sulfur atom is bound to a methyl group (a thioether group, -C-S-C-). Because it lacks a free, reactive -SH group, methionine cannot form disulfide bonds.\n• Lysine and Tyrosine: Neither of these amino acids contains sulfur in their side chains. Lysine contains an amino group, and tyrosine contains a phenolic hydroxyl group.","whyWrongChoices":"Alternative options: tyrosine, methionine, lysine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under pd 856, the minimum kitchen size for a 40 m² dining area is (m²)::::', 'under pd 856, the minimum kitchen size for a 40 m² dining area is (m²):', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Rule: The kitchen area must be at least 1/4 (25%) of the total dining area, but it cannot fall below a baseline minimum of 9.30 m² (100 sq. ft.).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Rule: The kitchen area must be at least 1/4 (25%) of the total dining area, but it cannot fall below a baseline minimum of 9.30 m² (100 sq. ft.).\n\nCalculated Kitchen Area = 40 m² x 0.25 = 10 m²","whyWrongChoices":"Alternative options: 5, 15, 20"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?:::2', 'ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?', '2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.\n\n• Molar Mass: 60.06 g/mol\n• Atom Count: A single molecule contains 1 Carbon, 1 Oxygen, 2 Nitrogens, and 4 Hydrogens (8 total atoms).","whyWrongChoices":"Alternative options: 4, 1, 3"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best level of fat?:::', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best level of fat?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This patient presents with multiple critical metabolic disorders—poorly controlled diabetes, obesity, hyperuricemia (gout), and severe hypercholesterolemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"15 -20% of TER\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This patient presents with multiple critical metabolic disorders—poorly controlled diabetes, obesity, hyperuricemia (gout), and severe hypercholesterolemia.\n\nIn standard board exam matrices, when a diabetic patient presents with elevated blood cholesterol levels, clinical guidelines prioritize managing cardiovascular risk. Restricting fat intake to a lower proportion of Total Energy Requirement (TER) assists in reducing saturated fat and dietary cholesterol. This therapeutic restriction helps address circulating blood lipids and manage obesity, while carbohydrate quality is managed separately to stabilize blood sugar.","whyWrongChoices":"Alternative options: 25- 35% of TER, 30-35% of TER, 20-25% of TER"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?:::', 'ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.\n\n• Molar Mass: 60.06 g/mol\n• Atom Count: A single molecule contains 1 Carbon, 1 Oxygen, 2 Nitrogens, and 4 Hydrogens (8 total atoms).","whyWrongChoices":"Alternative options: 4, 1, 3"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ceruloplasmin is a type of::::metalloprotein', 'ceruloplasmin is a type of:', 'metalloprotein', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ceruloplasmin is a type of metalloprotein (specifically a copper-binding metalloprotein) and it is also a glycoprotein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"metalloprotein\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ceruloplasmin is a type of metalloprotein (specifically a copper-binding metalloprotein) and it is also a glycoprotein.","whyWrongChoices":"Alternative options: glycoprotein, phosphoprotein, lipoprotein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ceruloplasmin is a type of::::', 'ceruloplasmin is a type of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ceruloplasmin is a type of metalloprotein (specifically a copper-binding metalloprotein) and it is also a glycoprotein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"metalloprotein\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ceruloplasmin is a type of metalloprotein (specifically a copper-binding metalloprotein) and it is also a glycoprotein.","whyWrongChoices":"Alternative options: glycoprotein, phosphoprotein, lipoprotein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:why is a saturated fat called “saturated”?:::the fatty acid carbon chain is saturated with hydrogen.', 'why is a saturated fat called “saturated”?', 'The fatty acid carbon chain is saturated with hydrogen.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a saturated fatty acid chain, there are only single bonds between the neighboring carbon atoms. Because carbon atoms must form four bonds, having only single bonds means each carbon atom can bind to the maximum possible number of hydrogen atoms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The fatty acid carbon chain is saturated with hydrogen.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a saturated fatty acid chain, there are only single bonds between the neighboring carbon atoms. Because carbon atoms must form four bonds, having only single bonds means each carbon atom can bind to the maximum possible number of hydrogen atoms.\n\nIn contrast, an unsaturated fat contains one or more carbon-to-carbon double bonds (C = C). These double bonds reduce the open spaces available for hydrogen, leaving the molecule \"unsaturated\".","whyWrongChoices":"Alternative options: The fat is saturated with water., The fatty acid carbon chain is saturated with carbon., The fatty acid carbon chains can have more water added."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:why is a saturated fat called “saturated”?:::', 'why is a saturated fat called “saturated”?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a saturated fatty acid chain, there are only single bonds between the neighboring carbon atoms. Because carbon atoms must form four bonds, having only single bonds means each carbon atom can bind to the maximum possible number of hydrogen atoms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The fatty acid carbon chain is saturated with hydrogen.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a saturated fatty acid chain, there are only single bonds between the neighboring carbon atoms. Because carbon atoms must form four bonds, having only single bonds means each carbon atom can bind to the maximum possible number of hydrogen atoms.\n\nIn contrast, an unsaturated fat contains one or more carbon-to-carbon double bonds (C = C). These double bonds reduce the open spaces available for hydrogen, leaving the molecule \"unsaturated\".","whyWrongChoices":"Alternative options: The fat is saturated with water., The fatty acid carbon chain is saturated with carbon., The fatty acid carbon chains can have more water added."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food service system utilized in most coffee shops like dunkin donuts::::', 'food service system utilized in most coffee shops like dunkin donuts:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dunkin Donuts practices off premise food production and the food are usually just assembled, heated before service. This is a characteristic of assembly/serve foodserving system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Assembly\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dunkin Donuts practices off premise food production and the food are usually just assembled, heated before service. This is a characteristic of assembly/serve foodserving system.","whyWrongChoices":"Alternative options: Conventional, Commisary, Ready prepared"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:digestion and absorption of carbohydrate involves all the following except::::an acid stable amylase which acts in the stomach', 'digestion and absorption of carbohydrate involves all the following except:', 'an acid stable amylase which acts in the stomach', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The statement regarding ''an acid stable amylase which acts in the stomach'' is false, making it the correct choice for an ''EXCEPT'' question. Unlike lipid digestion—which utilizes acid-stable lingual and gastric lipases in the stomach—there is no gastric amylase secreted by humans, nor is salivary alpha-amylase acid-stable. Salivary amylase becomes inactivated when mixed with gastric juice at a pH below 4.0, halting enzymatic carbohydrate hydrolysis until pancreatic secretions neutralize the chyme in the small intestine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"an acid stable amylase which acts in the stomach\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The statement regarding ''an acid stable amylase which acts in the stomach'' is false, making it the correct choice for an ''EXCEPT'' question. Unlike lipid digestion—which utilizes acid-stable lingual and gastric lipases in the stomach—there is no gastric amylase secreted by humans, nor is salivary alpha-amylase acid-stable. Salivary amylase becomes inactivated when mixed with gastric juice at a pH below 4.0, halting enzymatic carbohydrate hydrolysis until pancreatic secretions neutralize the chyme in the small intestine.","whyWrongChoices":"Alternative options: salivary alpha amylase, disaccharidases in the intestines, pancreatic alpha amylase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:digestion and absorption of carbohydrate involves all the following except::::', 'digestion and absorption of carbohydrate involves all the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The statement regarding ''an acid stable amylase which acts in the stomach'' is false, making it the correct choice for an ''EXCEPT'' question. Unlike lipid digestion—which utilizes acid-stable lingual and gastric lipases in the stomach—there is no gastric amylase secreted by humans, nor is salivary alpha-amylase acid-stable. Salivary amylase becomes inactivated when mixed with gastric juice at a pH below 4.0, halting enzymatic carbohydrate hydrolysis until pancreatic secretions neutralize the chyme in the small intestine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"an acid stable amylase which acts in the stomach\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The statement regarding ''an acid stable amylase which acts in the stomach'' is false, making it the correct choice for an ''EXCEPT'' question. Unlike lipid digestion—which utilizes acid-stable lingual and gastric lipases in the stomach—there is no gastric amylase secreted by humans, nor is salivary alpha-amylase acid-stable. Salivary amylase becomes inactivated when mixed with gastric juice at a pH below 4.0, halting enzymatic carbohydrate hydrolysis until pancreatic secretions neutralize the chyme in the small intestine.","whyWrongChoices":"Alternative options: salivary alpha amylase, disaccharidases in the intestines, pancreatic alpha amylase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this mineral works closely with insulin to regulate the release of energy from glucose::::chromium', 'this mineral works closely with insulin to regulate the release of energy from glucose:', 'chromium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chromium (specifically in its trivalent form, Cr³⁺) is an essential trace mineral that acts as an \"insulin amplifier\". It binds with other compounds in the body to form Glucose Tolerance Factor (GTF).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"chromium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chromium (specifically in its trivalent form, Cr³⁺) is an essential trace mineral that acts as an \"insulin amplifier\". It binds with other compounds in the body to form Glucose Tolerance Factor (GTF).\n\nGTF stabilizes insulin and enhances its ability to dock onto insulin receptors on the surface of your cells. This binding clears glucose from the bloodstream and pulls it directly into the cells, where it can enter metabolic pathways (like glycolysis and the Krebs cycle) to be converted into usable cellular energy (ATP).\n\n• Copper: Primarily required for iron metabolism, red blood cell synthesis, and cross-linking collagen.\n• Iodine: Crucial for synthesizing thyroid hormones, which regulate overall baseline metabolic rate, but does not bind with insulin.\n• Selenium: Functions as a vital component of antioxidant enzymes like glutathione peroxidase to neutralize free radicals.","whyWrongChoices":"Alternative options: iodine, selenium, copper"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are feeding problems prevalent in adolescence except::::', 'all are feeding problems prevalent in adolescence except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gagging is a feeding problem prevalent among preschool children.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gagging\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gagging is a feeding problem prevalent among preschool children.","whyWrongChoices":"Alternative options: Snacking, Non-traditional eating patterns, Meal skipping"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are dietary carbohydrates except::::glycogen', 'all are dietary carbohydrates except:', 'glycogen', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dietary Fibers & Plant Carbs: Pectin, Starch, and Mucilages are carbohydrates synthesized by plants. Pectin and mucilages are classified as soluble dietary fibers, while starch is the primary digestible storage carbohydrate in plants.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glycogen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dietary Fibers & Plant Carbs: Pectin, Starch, and Mucilages are carbohydrates synthesized by plants. Pectin and mucilages are classified as soluble dietary fibers, while starch is the primary digestible storage carbohydrate in plants.\n\nGlycogen is the complex storage carbohydrate synthesized and found inside animal tissue (specifically liver and muscle cells).","whyWrongChoices":"Alternative options: mucilages, starch, pectin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this mineral works closely with insulin to regulate the release of energy from glucose::::', 'this mineral works closely with insulin to regulate the release of energy from glucose:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chromium (specifically in its trivalent form, Cr³⁺) is an essential trace mineral that acts as an \"insulin amplifier\". It binds with other compounds in the body to form Glucose Tolerance Factor (GTF).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"chromium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chromium (specifically in its trivalent form, Cr³⁺) is an essential trace mineral that acts as an \"insulin amplifier\". It binds with other compounds in the body to form Glucose Tolerance Factor (GTF).\n\nGTF stabilizes insulin and enhances its ability to dock onto insulin receptors on the surface of your cells. This binding clears glucose from the bloodstream and pulls it directly into the cells, where it can enter metabolic pathways (like glycolysis and the Krebs cycle) to be converted into usable cellular energy (ATP).\n\n• Copper: Primarily required for iron metabolism, red blood cell synthesis, and cross-linking collagen.\n• Iodine: Crucial for synthesizing thyroid hormones, which regulate overall baseline metabolic rate, but does not bind with insulin.\n• Selenium: Functions as a vital component of antioxidant enzymes like glutathione peroxidase to neutralize free radicals.","whyWrongChoices":"Alternative options: iodine, selenium, copper"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the b vitamin needed in the synthesis of niacin from tryptophan::::pyridoxine', 'the b vitamin needed in the synthesis of niacin from tryptophan:', 'pyridoxine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The body can manufacture niacin (Vitamin B₃) endogenously from the essential amino acid tryptophan.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pyridoxine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The body can manufacture niacin (Vitamin B₃) endogenously from the essential amino acid tryptophan.\n\nPyridoxine (Vitamin B₆) serves as an essential cofactor for the enzyme kynureninase. A deficiency in Vitamin B₆ halts this step, preventing tryptophan from converting into niacin and potentially leading to niacin-deficiency symptoms (like pellagra).\n\nRiboflavin (Vitamin B₂) is also involved earlier in the pathway (for the enzyme kynurenine 3-monooxygenase), but kynureninase (B₆) is considered the most clinically significant bottleneck.","whyWrongChoices":"Alternative options: thiamin, niacin, riboflavin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the b vitamin needed in the synthesis of niacin from tryptophan::::', 'the b vitamin needed in the synthesis of niacin from tryptophan:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The body can manufacture niacin (Vitamin B₃) endogenously from the essential amino acid tryptophan.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pyridoxine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The body can manufacture niacin (Vitamin B₃) endogenously from the essential amino acid tryptophan.\n\nPyridoxine (Vitamin B₆) serves as an essential cofactor for the enzyme kynureninase. A deficiency in Vitamin B₆ halts this step, preventing tryptophan from converting into niacin and potentially leading to niacin-deficiency symptoms (like pellagra).\n\nRiboflavin (Vitamin B₂) is also involved earlier in the pathway (for the enzyme kynurenine 3-monooxygenase), but kynureninase (B₆) is considered the most clinically significant bottleneck.","whyWrongChoices":"Alternative options: thiamin, niacin, riboflavin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not an essential amino acid?:::alanine', 'which of the following is not an essential amino acid?', 'alanine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alanine is a non-essential amino acid: The human body possesses the necessary enzymes to synthesize alanine internally (typically via the transamination of pyruvate). Because the body can produce it on its own, it does not strictly need to be obtained directly from your diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"alanine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alanine is a non-essential amino acid: The human body possesses the necessary enzymes to synthesize alanine internally (typically via the transamination of pyruvate). Because the body can produce it on its own, it does not strictly need to be obtained directly from your diet.\n\nTo instantly recall the 9 essential amino acids during a test, memorize the phrase \"PVT TIM HALL\":\n• Phenylalanine\n• Valine\n• Threonine\n• Tryptophan\n• Isoleucine\n• Methionine\n• Histidine\n• Arginine (often classified as semi-essential or required mostly for children)\n• Leucine\n• Lysine","whyWrongChoices":"Alternative options: tryptophan, lysine, phenylalanine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not an essential amino acid?:::', 'which of the following is not an essential amino acid?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alanine is a non-essential amino acid: The human body possesses the necessary enzymes to synthesize alanine internally (typically via the transamination of pyruvate). Because the body can produce it on its own, it does not strictly need to be obtained directly from your diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"alanine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alanine is a non-essential amino acid: The human body possesses the necessary enzymes to synthesize alanine internally (typically via the transamination of pyruvate). Because the body can produce it on its own, it does not strictly need to be obtained directly from your diet.\n\nTo instantly recall the 9 essential amino acids during a test, memorize the phrase \"PVT TIM HALL\":\n• Phenylalanine\n• Valine\n• Threonine\n• Tryptophan\n• Isoleucine\n• Methionine\n• Histidine\n• Arginine (often classified as semi-essential or required mostly for children)\n• Leucine\n• Lysine","whyWrongChoices":"Alternative options: tryptophan, lysine, phenylalanine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:laboratory tests for a 45-year-old male alcoholic patient show an accumulation of lactate and pyruvate in body fluids, suggesting a block in the conversion of pyruvate to acetyl coa. he appears confused and shows a slight weakness of eye movement. this patient would most probably be treated with injections of::::thiamin', 'laboratory tests for a 45-year-old male alcoholic patient show an accumulation of lactate and pyruvate in body fluids, suggesting a block in the conversion of pyruvate to acetyl coa. he appears confused and shows a slight weakness of eye movement. this patient would most probably be treated with injections of:', 'thiamin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The combination of chronic alcoholism, confusion, and weakness of eye movement (ophthalmoplegia) is a classic presentation of Wernicke-Korsakoff syndrome, a severe neurological complication caused by thiamin (Vitamin B1) deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thiamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The combination of chronic alcoholism, confusion, and weakness of eye movement (ophthalmoplegia) is a classic presentation of Wernicke-Korsakoff syndrome, a severe neurological complication caused by thiamin (Vitamin B1) deficiency.\n\nThiamin pyrophosphate (TPP) is an essential cofactor for the pyruvate dehydrogenase (PDH) complex, which converts pyruvate into acetyl CoA. When thiamin is deficient, this complex cannot function.\n\nBecause pyruvate cannot be converted into acetyl CoA, it shunts into alternative pathways. This leads to the accumulation of both pyruvate and lactate (via lactic acid fermentation) in body fluids.","whyWrongChoices":"Alternative options: niacin, pantothenic acid, riboflavin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:laboratory tests for a 45-year-old male alcoholic patient show an accumulation of lactate and pyruvate in body fluids, suggesting a block in the conversion of pyruvate to acetyl coa. he appears confused and shows a slight weakness of eye movement. this patient would most probably be treated with injections of::::', 'laboratory tests for a 45-year-old male alcoholic patient show an accumulation of lactate and pyruvate in body fluids, suggesting a block in the conversion of pyruvate to acetyl coa. he appears confused and shows a slight weakness of eye movement. this patient would most probably be treated with injections of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The combination of chronic alcoholism, confusion, and weakness of eye movement (ophthalmoplegia) is a classic presentation of Wernicke-Korsakoff syndrome, a severe neurological complication caused by thiamin (Vitamin B1) deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thiamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The combination of chronic alcoholism, confusion, and weakness of eye movement (ophthalmoplegia) is a classic presentation of Wernicke-Korsakoff syndrome, a severe neurological complication caused by thiamin (Vitamin B1) deficiency.\n\nThiamin pyrophosphate (TPP) is an essential cofactor for the pyruvate dehydrogenase (PDH) complex, which converts pyruvate into acetyl CoA. When thiamin is deficient, this complex cannot function.\n\nBecause pyruvate cannot be converted into acetyl CoA, it shunts into alternative pathways. This leads to the accumulation of both pyruvate and lactate (via lactic acid fermentation) in body fluids.","whyWrongChoices":"Alternative options: niacin, pantothenic acid, riboflavin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a key enzyme in carbohydrate metabolism found in the liver but not in muscles is::::glucokinase', 'a key enzyme in carbohydrate metabolism found in the liver but not in muscles is:', 'glucokinase', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucokinase (also known as Hexokinase IV) is an irreversible enzyme found almost exclusively in the liver parenchymal cells and pancreatic beta cells. It is notably absent from skeletal muscle tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glucokinase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucokinase (also known as Hexokinase IV) is an irreversible enzyme found almost exclusively in the liver parenchymal cells and pancreatic beta cells. It is notably absent from skeletal muscle tissue.","whyWrongChoices":"Alternative options: phosphorylase, hexokinase, pyruvate dehydrogenase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a key enzyme in carbohydrate metabolism found in the liver but not in muscles is::::', 'a key enzyme in carbohydrate metabolism found in the liver but not in muscles is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucokinase (also known as Hexokinase IV) is an irreversible enzyme found almost exclusively in the liver parenchymal cells and pancreatic beta cells. It is notably absent from skeletal muscle tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glucokinase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucokinase (also known as Hexokinase IV) is an irreversible enzyme found almost exclusively in the liver parenchymal cells and pancreatic beta cells. It is notably absent from skeletal muscle tissue.","whyWrongChoices":"Alternative options: phosphorylase, hexokinase, pyruvate dehydrogenase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when a muscle contracts aerobically, less lactic acid is formed than when it contracts anaerobically because under aerobic conditions ::::the lactic acid generated is rapidly converted back to glucose.', 'when a muscle contracts aerobically, less lactic acid is formed than when it contracts anaerobically because under aerobic conditions :', 'the lactic acid generated is rapidly converted back to glucose.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During physical exertion, any lactic acid (or more accurately, lactate) that is produced diffuses out of the skeletal muscle cells into the bloodstream and is transported to the liver. In the hepatic Cori cycle, hepatocytes take up this lactate, oxidize it back to pyruvate via lactate dehydrogenase, and subsequently convert it into glucose via gluconeogenesis, which is then released back into the bloodstream to support active muscle tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the lactic acid generated is rapidly converted back to glucose.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During physical exertion, any lactic acid (or more accurately, lactate) that is produced diffuses out of the skeletal muscle cells into the bloodstream and is transported to the liver. In the hepatic Cori cycle, hepatocytes take up this lactate, oxidize it back to pyruvate via lactate dehydrogenase, and subsequently convert it into glucose via gluconeogenesis, which is then released back into the bloodstream to support active muscle tissue.","whyWrongChoices":"Alternative options: muscles cannot convert glucose 6-phosphate to pyruvate., most of the pyruvate generated is oxidized., the major source of energy is the pentose pathway."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in foodservice facilities and layout, supporting services include the following, except::::', 'in foodservice facilities and layout, supporting services include the following, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"It includes all plus an area for steam hose use to wash and sanitize carts, etc.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"It includes all plus an area for steam hose use to wash and sanitize carts, etc.","whyWrongChoices":"Alternative options: Office, Janitor''s closet/storage, Trash and waste storage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when a muscle contracts aerobically, less lactic acid is formed than when it contracts anaerobically because under aerobic conditions ::::', 'when a muscle contracts aerobically, less lactic acid is formed than when it contracts anaerobically because under aerobic conditions :', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During physical exertion, any lactic acid (or more accurately, lactate) that is produced diffuses out of the skeletal muscle cells into the bloodstream and is transported to the liver. In the hepatic Cori cycle, hepatocytes take up this lactate, oxidize it back to pyruvate via lactate dehydrogenase, and subsequently convert it into glucose via gluconeogenesis, which is then released back into the bloodstream to support active muscle tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the lactic acid generated is rapidly converted back to glucose.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During physical exertion, any lactic acid (or more accurately, lactate) that is produced diffuses out of the skeletal muscle cells into the bloodstream and is transported to the liver. In the hepatic Cori cycle, hepatocytes take up this lactate, oxidize it back to pyruvate via lactate dehydrogenase, and subsequently convert it into glucose via gluconeogenesis, which is then released back into the bloodstream to support active muscle tissue.","whyWrongChoices":"Alternative options: muscles cannot convert glucose 6-phosphate to pyruvate., most of the pyruvate generated is oxidized., the major source of energy is the pentose pathway."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following compounds can serve as the starting material for the synthesis of glucose via gluconeogenesis except::::oleic acid', 'all of the following compounds can serve as the starting material for the synthesis of glucose via gluconeogenesis except:', 'oleic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Oleic acid is a fatty acid (specifically a 18-carbon monounsaturated fatty acid). In humans and other mammals, even-chain fatty acids are broken down via beta-oxidation into acetyl-CoA.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oleic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Oleic acid is a fatty acid (specifically a 18-carbon monounsaturated fatty acid). In humans and other mammals, even-chain fatty acids are broken down via beta-oxidation into acetyl-CoA.\n\nAcetyl-CoA cannot be used to synthesize glucose because the reaction that converts pyruvate to acetyl-CoA (catalyzed by the pyruvate dehydrogenase complex) is completely irreversible. Additionally, for every two carbons that enter the citric acid cycle as acetyl-CoA, two carbons are lost as CO2, meaning there is no net synthesis of oxaloacetate to feed into gluconeogenesis.","whyWrongChoices":"Alternative options: alanine, aspartic acid, glycerol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following compounds can serve as the starting material for the synthesis of glucose via gluconeogenesis except::::', 'all of the following compounds can serve as the starting material for the synthesis of glucose via gluconeogenesis except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Oleic acid is a fatty acid (specifically a 18-carbon monounsaturated fatty acid). In humans and other mammals, even-chain fatty acids are broken down via beta-oxidation into acetyl-CoA.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oleic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Oleic acid is a fatty acid (specifically a 18-carbon monounsaturated fatty acid). In humans and other mammals, even-chain fatty acids are broken down via beta-oxidation into acetyl-CoA.\n\nAcetyl-CoA cannot be used to synthesize glucose because the reaction that converts pyruvate to acetyl-CoA (catalyzed by the pyruvate dehydrogenase complex) is completely irreversible. Additionally, for every two carbons that enter the citric acid cycle as acetyl-CoA, two carbons are lost as CO2, meaning there is no net synthesis of oxaloacetate to feed into gluconeogenesis.","whyWrongChoices":"Alternative options: alanine, aspartic acid, glycerol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the conversion of 1 mol of pyruvate to 3 mol of co2 via pyruvate dehydrogenase and the citric acid cycle yields mol of nadh, mol of fadh2, and mol of atp or gtp.:::4; 1; 1', 'the conversion of 1 mol of pyruvate to 3 mol of co2 via pyruvate dehydrogenase and the citric acid cycle yields mol of nadh, mol of fadh2, and mol of atp or gtp.', '4; 1; 1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the total yield, we must look at two distinct cellular reactions: the Pyruvate Dehydrogenase (PDH) complex (the transition step) and the Citric Acid (Krebs) Cycle. 1. The Pyruvate Dehydrogenase (PDH) Complex (Transition Step): 1 Pyruvate (3 carbons) is converted into 1 Acetyl-CoA (2 carbons), releasing the first molecule of \\[\\text{CO}_{2}\\].Yield: 1 NADH 2. The Citric Acid Cycle: 1 Acetyl-CoA enters the cycle and is fully oxidized, releasing the remaining 2 molecules of \\[\\text{CO}_{2}\\].Yield: 3 NADH, 1 \\[\\text{FADH}_{2}\\], and 1 ATP (or GTP) via substrate-level phosphorylation. Total Cumulative Yield:Adding the yields of both steps together: NADH: \\(1\\text{ (from PDH)} + 3\\text{ (from Citric Acid Cycle)} =\\) 4 mol\\[\\text{FADH}_{2}\\]: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 molATP/GTP: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 mol","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4; 1; 1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the total yield, we must look at two distinct cellular reactions: the Pyruvate Dehydrogenase (PDH) complex (the transition step) and the Citric Acid (Krebs) Cycle. 1. The Pyruvate Dehydrogenase (PDH) Complex (Transition Step): 1 Pyruvate (3 carbons) is converted into 1 Acetyl-CoA (2 carbons), releasing the first molecule of \\[\\text{CO}_{2}\\].Yield: 1 NADH 2. The Citric Acid Cycle: 1 Acetyl-CoA enters the cycle and is fully oxidized, releasing the remaining 2 molecules of \\[\\text{CO}_{2}\\].Yield: 3 NADH, 1 \\[\\text{FADH}_{2}\\], and 1 ATP (or GTP) via substrate-level phosphorylation. Total Cumulative Yield:Adding the yields of both steps together: NADH: \\(1\\text{ (from PDH)} + 3\\text{ (from Citric Acid Cycle)} =\\) 4 mol\\[\\text{FADH}_{2}\\]: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 molATP/GTP: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 mol","whyWrongChoices":"Alternative options: 3; 2; 0, 4; 2; 1, 3; 1; 1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the conversion of 1 mol of pyruvate to 3 mol of co2 via pyruvate dehydrogenase and the citric acid cycle yields mol of nadh, mol of fadh2, and mol of atp or gtp.:::', 'the conversion of 1 mol of pyruvate to 3 mol of co2 via pyruvate dehydrogenase and the citric acid cycle yields mol of nadh, mol of fadh2, and mol of atp or gtp.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the total yield, we must look at two distinct cellular reactions: the Pyruvate Dehydrogenase (PDH) complex (the transition step) and the Citric Acid (Krebs) Cycle. 1. The Pyruvate Dehydrogenase (PDH) Complex (Transition Step): 1 Pyruvate (3 carbons) is converted into 1 Acetyl-CoA (2 carbons), releasing the first molecule of \\[\\text{CO}_{2}\\].Yield: 1 NADH 2. The Citric Acid Cycle: 1 Acetyl-CoA enters the cycle and is fully oxidized, releasing the remaining 2 molecules of \\[\\text{CO}_{2}\\].Yield: 3 NADH, 1 \\[\\text{FADH}_{2}\\], and 1 ATP (or GTP) via substrate-level phosphorylation. Total Cumulative Yield:Adding the yields of both steps together: NADH: \\(1\\text{ (from PDH)} + 3\\text{ (from Citric Acid Cycle)} =\\) 4 mol\\[\\text{FADH}_{2}\\]: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 molATP/GTP: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 mol","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4; 1; 1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the total yield, we must look at two distinct cellular reactions: the Pyruvate Dehydrogenase (PDH) complex (the transition step) and the Citric Acid (Krebs) Cycle. 1. The Pyruvate Dehydrogenase (PDH) Complex (Transition Step): 1 Pyruvate (3 carbons) is converted into 1 Acetyl-CoA (2 carbons), releasing the first molecule of \\[\\text{CO}_{2}\\].Yield: 1 NADH 2. The Citric Acid Cycle: 1 Acetyl-CoA enters the cycle and is fully oxidized, releasing the remaining 2 molecules of \\[\\text{CO}_{2}\\].Yield: 3 NADH, 1 \\[\\text{FADH}_{2}\\], and 1 ATP (or GTP) via substrate-level phosphorylation. Total Cumulative Yield:Adding the yields of both steps together: NADH: \\(1\\text{ (from PDH)} + 3\\text{ (from Citric Acid Cycle)} =\\) 4 mol\\[\\text{FADH}_{2}\\]: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 molATP/GTP: \\(0\\text{ (from PDH)} + 1\\text{ (from Citric Acid Cycle)} =\\) 1 mol","whyWrongChoices":"Alternative options: 3; 2; 0, 4; 2; 1, 3; 1; 1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the term “glycemic effect of food” includes the following meanings except::::how long blood glucose is elevated after a meal', 'the term “glycemic effect of food” includes the following meanings except:', 'how long blood glucose is elevated after a meal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The glycemic effect (often measured as the glycemic index or glycemic load) specifically evaluates the intensity, speed, and recovery of the blood sugar spike following food consumption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"how long blood glucose is elevated after a meal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The glycemic effect (often measured as the glycemic index or glycemic load) specifically evaluates the intensity, speed, and recovery of the blood sugar spike following food consumption.\n\nWhile a glycemic curve tracks how high blood glucose rises, how fast it gets absorbed, and how rapidly the body secretes insulin to bring it back down to baseline, it does not look at prolonged, sustained elevation as a trait of the food itself. A long-lasting elevation of blood sugar is typically a reflection of a patient''s underlying pathology (such as insulin resistance or diabetes), rather than an intrinsic characteristic of the food''s glycemic effect.","whyWrongChoices":"Alternative options: how quickly blood glucose returns to normal, how high blood glucose rises after a meal, how quickly glucose is absorbed after eating"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the term “glycemic effect of food” includes the following meanings except::::', 'the term “glycemic effect of food” includes the following meanings except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The glycemic effect (often measured as the glycemic index or glycemic load) specifically evaluates the intensity, speed, and recovery of the blood sugar spike following food consumption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"how long blood glucose is elevated after a meal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The glycemic effect (often measured as the glycemic index or glycemic load) specifically evaluates the intensity, speed, and recovery of the blood sugar spike following food consumption.\n\nWhile a glycemic curve tracks how high blood glucose rises, how fast it gets absorbed, and how rapidly the body secretes insulin to bring it back down to baseline, it does not look at prolonged, sustained elevation as a trait of the food itself. A long-lasting elevation of blood sugar is typically a reflection of a patient''s underlying pathology (such as insulin resistance or diabetes), rather than an intrinsic characteristic of the food''s glycemic effect.","whyWrongChoices":"Alternative options: how quickly blood glucose returns to normal, how high blood glucose rises after a meal, how quickly glucose is absorbed after eating"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lipoprotein made primarily by liver cells to transport lipids to various tissues in the body::::vldl', 'lipoprotein made primarily by liver cells to transport lipids to various tissues in the body:', 'VLDL', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"VLDL (Very Low-Density Lipoprotein) is synthesized and secreted primarily by liver cells. Its main job is to transport newly created endogenous triglycerides and cholesterol from the liver out to various peripheral tissues in the body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"VLDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"VLDL (Very Low-Density Lipoprotein) is synthesized and secreted primarily by liver cells. Its main job is to transport newly created endogenous triglycerides and cholesterol from the liver out to various peripheral tissues in the body.\n\n\t• Chylomicrons: These are made by intestinal cells (enterocytes), not liver cells. They transport dietary (exogenous) lipids absorbed from food.\n\t• HDL (High-Density Lipoprotein): Its main job is reverse cholesterol transport, meaning it picks up excess cholesterol from various tissues and returns it back to the liver.\n\t• LDL (Low-Density Lipoprotein): While it does deliver cholesterol to various tissues, it is not made directly by liver cells. Instead, LDL is formed in the bloodstream as VLDL shrinks and loses its triglycerides.","whyWrongChoices":"Alternative options: HDL, LDL, chylomicron"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lipoprotein made primarily by liver cells to transport lipids to various tissues in the body::::', 'lipoprotein made primarily by liver cells to transport lipids to various tissues in the body:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"VLDL (Very Low-Density Lipoprotein) is synthesized and secreted primarily by liver cells. Its main job is to transport newly created endogenous triglycerides and cholesterol from the liver out to various peripheral tissues in the body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"VLDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"VLDL (Very Low-Density Lipoprotein) is synthesized and secreted primarily by liver cells. Its main job is to transport newly created endogenous triglycerides and cholesterol from the liver out to various peripheral tissues in the body.\n\n\t• Chylomicrons: These are made by intestinal cells (enterocytes), not liver cells. They transport dietary (exogenous) lipids absorbed from food.\n\t• HDL (High-Density Lipoprotein): Its main job is reverse cholesterol transport, meaning it picks up excess cholesterol from various tissues and returns it back to the liver.\n\t• LDL (Low-Density Lipoprotein): While it does deliver cholesterol to various tissues, it is not made directly by liver cells. Instead, LDL is formed in the bloodstream as VLDL shrinks and loses its triglycerides.","whyWrongChoices":"Alternative options: HDL, LDL, chylomicron"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are functions of cobalamin except::::antioxidant', 'all of the following are functions of cobalamin except:', 'antioxidant', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cobalamin (Vitamin B12) does not primarily function as a direct antioxidant in the body, unlike Vitamins C or E.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"antioxidant\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cobalamin (Vitamin B12) does not primarily function as a direct antioxidant in the body, unlike Vitamins C or E.","whyWrongChoices":"Alternative options: co-factors, healthy nerves (myelin sheath)"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:iron absorption is increased by the following nutrients except::::zn', 'iron absorption is increased by the following nutrients except:', 'Zn', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc acts as a powerful inhibitor of iron absorption, rather than an enhancer. High doses of supplemental zinc compete directly with iron for the same membrane transporter pathways—specifically the DMT1 (Divalent Metal Transporter 1) channel—in the brush border cells of the small intestine. Consuming a large amount of zinc blocks this pathway, significantly reducing the absorption rate of non-heme iron.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc acts as a powerful inhibitor of iron absorption, rather than an enhancer. High doses of supplemental zinc compete directly with iron for the same membrane transporter pathways—specifically the DMT1 (Divalent Metal Transporter 1) channel—in the brush border cells of the small intestine. Consuming a large amount of zinc blocks this pathway, significantly reducing the absorption rate of non-heme iron.","whyWrongChoices":"Alternative options: vitamin C, Cu, vitamin A"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:iron absorption is increased by the following nutrients except::::', 'iron absorption is increased by the following nutrients except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc acts as a powerful inhibitor of iron absorption, rather than an enhancer. High doses of supplemental zinc compete directly with iron for the same membrane transporter pathways—specifically the DMT1 (Divalent Metal Transporter 1) channel—in the brush border cells of the small intestine. Consuming a large amount of zinc blocks this pathway, significantly reducing the absorption rate of non-heme iron.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc acts as a powerful inhibitor of iron absorption, rather than an enhancer. High doses of supplemental zinc compete directly with iron for the same membrane transporter pathways—specifically the DMT1 (Divalent Metal Transporter 1) channel—in the brush border cells of the small intestine. Consuming a large amount of zinc blocks this pathway, significantly reducing the absorption rate of non-heme iron.","whyWrongChoices":"Alternative options: vitamin C, Cu, vitamin A"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:except for , these essential branched-chain amino acids are used by skeletal muscles for energy during prolonged endurance exercise::::tryptophan', 'except for , these essential branched-chain amino acids are used by skeletal muscles for energy during prolonged endurance exercise:', 'tryptophan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The three essential branched-chain amino acids are leucine, isoleucine, and valine. They are unique because unlike most other amino acids that are metabolized primarily in the liver, BCAAs skip the liver and are oxidized directly within skeletal muscle tissue to provide energy during prolonged endurance training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"tryptophan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The three essential branched-chain amino acids are leucine, isoleucine, and valine. They are unique because unlike most other amino acids that are metabolized primarily in the liver, BCAAs skip the liver and are oxidized directly within skeletal muscle tissue to provide energy during prolonged endurance training.\n\nDuring prolonged endurance exercise, as muscle glycogen stores deplete, muscle cells increasingly burn leucine, isoleucine, and valine for fuel. This drops blood BCAA levels, allowing more tryptophan to cross the blood-brain barrier, which actually contributes to central nervous system fatigue.\n\nTryptophan is an aromatic amino acid, not a branched-chain amino acid. While it is essential, it is not metabolized directly by skeletal muscle for energy during exercise.","whyWrongChoices":"Alternative options: isoleucine, leucine, valine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:except for , these essential branched-chain amino acids are used by skeletal muscles for energy during prolonged endurance exercise::::', 'except for , these essential branched-chain amino acids are used by skeletal muscles for energy during prolonged endurance exercise:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The three essential branched-chain amino acids are leucine, isoleucine, and valine. They are unique because unlike most other amino acids that are metabolized primarily in the liver, BCAAs skip the liver and are oxidized directly within skeletal muscle tissue to provide energy during prolonged endurance training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"tryptophan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The three essential branched-chain amino acids are leucine, isoleucine, and valine. They are unique because unlike most other amino acids that are metabolized primarily in the liver, BCAAs skip the liver and are oxidized directly within skeletal muscle tissue to provide energy during prolonged endurance training.\n\nDuring prolonged endurance exercise, as muscle glycogen stores deplete, muscle cells increasingly burn leucine, isoleucine, and valine for fuel. This drops blood BCAA levels, allowing more tryptophan to cross the blood-brain barrier, which actually contributes to central nervous system fatigue.\n\nTryptophan is an aromatic amino acid, not a branched-chain amino acid. While it is essential, it is not metabolized directly by skeletal muscle for energy during exercise.","whyWrongChoices":"Alternative options: isoleucine, leucine, valine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
