INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:during the fasting stage, one of the following occurs::::glycogen breakdown', 'during the fasting stage, one of the following occurs:', 'glycogen breakdown', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycogen breakdown is the very first defense mechanism. Your pancreas secretes glucagon, which signals the liver to smash its stored glycogen chains back into free glucose to maintain normal blood sugar levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glycogen breakdown\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycogen breakdown is the very first defense mechanism. Your pancreas secretes glucagon, which signals the liver to smash its stored glycogen chains back into free glucose to maintain normal blood sugar levels.","whyWrongChoices":"Alternative options: protein breakdown, fat synthesis, glucose synthesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the side chain attached to the carbon atom of a protein molecule which determines the characteristics and functions of each amino acid is::::the radical group', 'the side chain attached to the carbon atom of a protein molecule which determines the characteristics and functions of each amino acid is:', 'the radical group', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All 20 standard amino acids share an identical foundational backbone consisting of a central alpha-carbon, an amino group, an acid (carboxyl) group, and a hydrogen atom. The radical group (R-group) is the only component that changes from one amino acid to the next. Its specific chemical layout determines whether the amino acid behaves as hydrophobic, hydrophilic, acidic, basic, or polar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the radical group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All 20 standard amino acids share an identical foundational backbone consisting of a central alpha-carbon, an amino group, an acid (carboxyl) group, and a hydrogen atom. The radical group (R-group) is the only component that changes from one amino acid to the next. Its specific chemical layout determines whether the amino acid behaves as hydrophobic, hydrophilic, acidic, basic, or polar.","whyWrongChoices":"Alternative options: the amino group, hydrogen, the acid group"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the side chain attached to the carbon atom of a protein molecule which determines the characteristics and functions of each amino acid is::::', 'the side chain attached to the carbon atom of a protein molecule which determines the characteristics and functions of each amino acid is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All 20 standard amino acids share an identical foundational backbone consisting of a central alpha-carbon, an amino group, an acid (carboxyl) group, and a hydrogen atom. The radical group (R-group) is the only component that changes from one amino acid to the next. Its specific chemical layout determines whether the amino acid behaves as hydrophobic, hydrophilic, acidic, basic, or polar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the radical group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All 20 standard amino acids share an identical foundational backbone consisting of a central alpha-carbon, an amino group, an acid (carboxyl) group, and a hydrogen atom. The radical group (R-group) is the only component that changes from one amino acid to the next. Its specific chemical layout determines whether the amino acid behaves as hydrophobic, hydrophilic, acidic, basic, or polar.","whyWrongChoices":"Alternative options: the amino group, hydrogen, the acid group"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:considered semi-essential or conditionally essential amino acids except for::::alanine', 'considered semi-essential or conditionally essential amino acids except for:', 'alanine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alanine is a strictly non-essential (dispensable) amino acid. The body can always synthesize it in adequate amounts directly from pyruvate via transamination reactions, even during periods of severe stress, illness, or rapid growth. It never crosses into the semi-essential category.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"alanine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alanine is a strictly non-essential (dispensable) amino acid. The body can always synthesize it in adequate amounts directly from pyruvate via transamination reactions, even during periods of severe stress, illness, or rapid growth. It never crosses into the semi-essential category.\n\n• Tyrosine: This is a classic conditionally essential amino acid. It is synthesized directly from the essential amino acid phenylalanine. In clinical conditions like Phenylketonuria (PKU) where the converting enzyme is deficient, or during severe liver disease, tyrosine cannot be produced by the body and must be supplied exogenously through the diet.\n• Cysteine: This is a conditionally essential amino acid. It requires methionine as a sulfur donor for its synthesis. In premature infants or patients with severe metabolic stress or cirrhosis, the enzymatic pathways are immature or impaired, making it an essential dietary requirement.\n• Serine: This is recognized under advanced physiological frameworks (such as the MedlinePlus Medical Reference) as a conditionally essential amino acid. Under extreme hypermetabolic states or specific clinical pathologies, its endogenous production cannot completely keep up with cellular demands.","whyWrongChoices":"Alternative options: tyrosine, cysteine, serine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during the fasting stage, one of the following occurs::::', 'during the fasting stage, one of the following occurs:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycogen breakdown is the very first defense mechanism. Your pancreas secretes glucagon, which signals the liver to smash its stored glycogen chains back into free glucose to maintain normal blood sugar levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glycogen breakdown\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycogen breakdown is the very first defense mechanism. Your pancreas secretes glucagon, which signals the liver to smash its stored glycogen chains back into free glucose to maintain normal blood sugar levels.","whyWrongChoices":"Alternative options: protein breakdown, fat synthesis, glucose synthesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:considered semi-essential or conditionally essential amino acids except for::::', 'considered semi-essential or conditionally essential amino acids except for:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alanine is a strictly non-essential (dispensable) amino acid. The body can always synthesize it in adequate amounts directly from pyruvate via transamination reactions, even during periods of severe stress, illness, or rapid growth. It never crosses into the semi-essential category.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"alanine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alanine is a strictly non-essential (dispensable) amino acid. The body can always synthesize it in adequate amounts directly from pyruvate via transamination reactions, even during periods of severe stress, illness, or rapid growth. It never crosses into the semi-essential category.\n\n• Tyrosine: This is a classic conditionally essential amino acid. It is synthesized directly from the essential amino acid phenylalanine. In clinical conditions like Phenylketonuria (PKU) where the converting enzyme is deficient, or during severe liver disease, tyrosine cannot be produced by the body and must be supplied exogenously through the diet.\n• Cysteine: This is a conditionally essential amino acid. It requires methionine as a sulfur donor for its synthesis. In premature infants or patients with severe metabolic stress or cirrhosis, the enzymatic pathways are immature or impaired, making it an essential dietary requirement.\n• Serine: This is recognized under advanced physiological frameworks (such as the MedlinePlus Medical Reference) as a conditionally essential amino acid. Under extreme hypermetabolic states or specific clinical pathologies, its endogenous production cannot completely keep up with cellular demands.","whyWrongChoices":"Alternative options: tyrosine, cysteine, serine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are simple proteins that give amino acids when hydrolyzed except for ::::metalloproteins', 'these are simple proteins that give amino acids when hydrolyzed except for :', 'metalloproteins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Metalloproteins are classified as conjugated (or compound) proteins, not simple proteins. Upon hydrolysis, they yield both amino acids and a non-protein prosthetic group, which in this case is a metal ion (such as iron, zinc, or copper).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"metalloproteins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Metalloproteins are classified as conjugated (or compound) proteins, not simple proteins. Upon hydrolysis, they yield both amino acids and a non-protein prosthetic group, which in this case is a metal ion (such as iron, zinc, or copper).","whyWrongChoices":"Alternative options: albumin, globin, collagen"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are simple proteins that give amino acids when hydrolyzed except for ::::', 'these are simple proteins that give amino acids when hydrolyzed except for :', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Metalloproteins are classified as conjugated (or compound) proteins, not simple proteins. Upon hydrolysis, they yield both amino acids and a non-protein prosthetic group, which in this case is a metal ion (such as iron, zinc, or copper).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"metalloproteins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Metalloproteins are classified as conjugated (or compound) proteins, not simple proteins. Upon hydrolysis, they yield both amino acids and a non-protein prosthetic group, which in this case is a metal ion (such as iron, zinc, or copper).","whyWrongChoices":"Alternative options: albumin, globin, collagen"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factors that increase iron absorption except::::antacids', 'factors that increase iron absorption except:', 'antacids', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Non-heme iron requires a highly acidic stomach environment to remain soluble and convert from its ferric (Fe^3+) form into the easily absorbable ferrous (Fe^2+) form. Antacids neutralize stomach acid, which directly impairs and decreases iron absorption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"antacids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Non-heme iron requires a highly acidic stomach environment to remain soluble and convert from its ferric (Fe^3+) form into the easily absorbable ferrous (Fe^2+) form. Antacids neutralize stomach acid, which directly impairs and decreases iron absorption.","whyWrongChoices":"Alternative options: growth, ascorbic acid, pregnancy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factors that increase iron absorption except::::', 'factors that increase iron absorption except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Non-heme iron requires a highly acidic stomach environment to remain soluble and convert from its ferric (Fe^3+) form into the easily absorbable ferrous (Fe^2+) form. Antacids neutralize stomach acid, which directly impairs and decreases iron absorption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"antacids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Non-heme iron requires a highly acidic stomach environment to remain soluble and convert from its ferric (Fe^3+) form into the easily absorbable ferrous (Fe^2+) form. Antacids neutralize stomach acid, which directly impairs and decreases iron absorption.","whyWrongChoices":"Alternative options: growth, ascorbic acid, pregnancy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a calorie-free food contains::::<5 calories per serving', 'a calorie-free food contains:', '<5 calories per serving', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to official food labeling laws (such as FDA and international food regulations), a manufacturer can legally label a food item as \"calorie-free\" or \"zero calories\" if it contains fewer than 5 calories per reference amount customarily consumed (serving size).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"<5 calories per serving\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to official food labeling laws (such as FDA and international food regulations), a manufacturer can legally label a food item as \"calorie-free\" or \"zero calories\" if it contains fewer than 5 calories per reference amount customarily consumed (serving size).\n\nBecause the body expends a small amount of energy just to digest food, these negligible amounts are rounded down to zero on nutritional facts panels.","whyWrongChoices":"Alternative options: no calories, <10 calories per serving, <15 calories per serving"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a calorie-free food contains::::', 'a calorie-free food contains:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to official food labeling laws (such as FDA and international food regulations), a manufacturer can legally label a food item as \"calorie-free\" or \"zero calories\" if it contains fewer than 5 calories per reference amount customarily consumed (serving size).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"<5 calories per serving\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to official food labeling laws (such as FDA and international food regulations), a manufacturer can legally label a food item as \"calorie-free\" or \"zero calories\" if it contains fewer than 5 calories per reference amount customarily consumed (serving size).\n\nBecause the body expends a small amount of energy just to digest food, these negligible amounts are rounded down to zero on nutritional facts panels.","whyWrongChoices":"Alternative options: no calories, <10 calories per serving, <15 calories per serving"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:water-soluble vitamins are absorbed in the small intestine except for which is absorbed in the stomach.:::b₁₂', 'water-soluble vitamins are absorbed in the small intestine except for which is absorbed in the stomach.', 'B₁₂', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the final absorption of Vitamin B₁₂ actually occurs in the terminal ileum (small intestine), its entire absorption process begins critically in the stomach. The stomach produces hydrochloric acid to unbind B₁₂ from dietary proteins and secretes Intrinsic Factor (IF), a mandatory transport protein. Because B₁₂ requires this extensive gastric phase, many simplified medical board questions uniquely tie its absorption context to the stomach.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B₁₂\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the final absorption of Vitamin B₁₂ actually occurs in the terminal ileum (small intestine), its entire absorption process begins critically in the stomach. The stomach produces hydrochloric acid to unbind B₁₂ from dietary proteins and secretes Intrinsic Factor (IF), a mandatory transport protein. Because B₁₂ requires this extensive gastric phase, many simplified medical board questions uniquely tie its absorption context to the stomach.","whyWrongChoices":"Alternative options: B₁, B₃, B₆"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:water-soluble vitamins are absorbed in the small intestine except for which is absorbed in the stomach.:::', 'water-soluble vitamins are absorbed in the small intestine except for which is absorbed in the stomach.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the final absorption of Vitamin B₁₂ actually occurs in the terminal ileum (small intestine), its entire absorption process begins critically in the stomach. The stomach produces hydrochloric acid to unbind B₁₂ from dietary proteins and secretes Intrinsic Factor (IF), a mandatory transport protein. Because B₁₂ requires this extensive gastric phase, many simplified medical board questions uniquely tie its absorption context to the stomach.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B₁₂\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the final absorption of Vitamin B₁₂ actually occurs in the terminal ileum (small intestine), its entire absorption process begins critically in the stomach. The stomach produces hydrochloric acid to unbind B₁₂ from dietary proteins and secretes Intrinsic Factor (IF), a mandatory transport protein. Because B₁₂ requires this extensive gastric phase, many simplified medical board questions uniquely tie its absorption context to the stomach.","whyWrongChoices":"Alternative options: B₁, B₃, B₆"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these form the accessory organs of digestion except for the ::::small intestine', 'these form the accessory organs of digestion except for the :', 'small intestine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The digestive system is split into two primary divisions: the gastrointestinal (GI) tract and the accessory organs. The small intestine is a fundamental component of the GI tract itself—the continuous muscular tube through which food physically passes, undergoes chemical digestion, and gets absorbed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"small intestine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The digestive system is split into two primary divisions: the gastrointestinal (GI) tract and the accessory organs. The small intestine is a fundamental component of the GI tract itself—the continuous muscular tube through which food physically passes, undergoes chemical digestion, and gets absorbed.\n\n• Liver: This is a true accessory organ of digestion. Food does not pass through it, but it facilitates chemical digestion by continuously manufacturing and exporting bile into the duodenum to emulsify fats.\n• Gallbladder: This is a true accessory organ of digestion. It serves as a secondary storage and concentration sac for the bile produced by the liver, squeezing it into the small intestine when fats enter the tract.\n• Pancreas: This is a true accessory organ of digestion. Its exocrine cells synthesize and secrete pancreatic juice containing essential digestive enzymes and bicarbonate ions straight into the duodenum to neutralize acidity and digest macromolecules.","whyWrongChoices":"Alternative options: liver, gall bladder, pancreas"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:inactive precursors of enzymes::::zymogens', 'inactive precursors of enzymes:', 'zymogens', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• A) Zymogens / D) Proenzymes: Inactive proteins that must undergo a chemical change (like clipping off a piece of the protein chain) to become active enzymes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"zymogens\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• A) Zymogens / D) Proenzymes: Inactive proteins that must undergo a chemical change (like clipping off a piece of the protein chain) to become active enzymes.\n• B) Apoenzymes: The pure protein part of an enzyme that is currently inactive because it is missing its non-protein helper (cofactor or coenzyme).\n• C) Coenzymes: Organic helper molecules (often made from B-vitamins) that bind to enzymes to help them perform chemical reactions.","whyWrongChoices":"Alternative options: proenzymes, apoenzymes, coenzymes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:inactive precursors of enzymes::::', 'inactive precursors of enzymes:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• A) Zymogens / D) Proenzymes: Inactive proteins that must undergo a chemical change (like clipping off a piece of the protein chain) to become active enzymes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"zymogens\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• A) Zymogens / D) Proenzymes: Inactive proteins that must undergo a chemical change (like clipping off a piece of the protein chain) to become active enzymes.\n• B) Apoenzymes: The pure protein part of an enzyme that is currently inactive because it is missing its non-protein helper (cofactor or coenzyme).\n• C) Coenzymes: Organic helper molecules (often made from B-vitamins) that bind to enzymes to help them perform chemical reactions.","whyWrongChoices":"Alternative options: proenzymes, apoenzymes, coenzymes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these form the accessory organs of digestion except for the ::::', 'these form the accessory organs of digestion except for the :', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The digestive system is split into two primary divisions: the gastrointestinal (GI) tract and the accessory organs. The small intestine is a fundamental component of the GI tract itself—the continuous muscular tube through which food physically passes, undergoes chemical digestion, and gets absorbed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"small intestine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The digestive system is split into two primary divisions: the gastrointestinal (GI) tract and the accessory organs. The small intestine is a fundamental component of the GI tract itself—the continuous muscular tube through which food physically passes, undergoes chemical digestion, and gets absorbed.\n\n• Liver: This is a true accessory organ of digestion. Food does not pass through it, but it facilitates chemical digestion by continuously manufacturing and exporting bile into the duodenum to emulsify fats.\n• Gallbladder: This is a true accessory organ of digestion. It serves as a secondary storage and concentration sac for the bile produced by the liver, squeezing it into the small intestine when fats enter the tract.\n• Pancreas: This is a true accessory organ of digestion. Its exocrine cells synthesize and secrete pancreatic juice containing essential digestive enzymes and bicarbonate ions straight into the duodenum to neutralize acidity and digest macromolecules.","whyWrongChoices":"Alternative options: liver, gall bladder, pancreas"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a secretion of the pancreas that neutralizes the acidic fluid from the stomach::::bicarbonate', 'a secretion of the pancreas that neutralizes the acidic fluid from the stomach:', 'bicarbonate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The pancreas secretes large amounts of sodium bicarbonate into the duodenum. This alkaline fluid directly neutralizes the highly acidic chyme coming from the stomach. This neutralization process protects the delicate intestinal lining and creates the optimal alkaline environment necessary for digestive enzymes to function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bicarbonate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The pancreas secretes large amounts of sodium bicarbonate into the duodenum. This alkaline fluid directly neutralizes the highly acidic chyme coming from the stomach. This neutralization process protects the delicate intestinal lining and creates the optimal alkaline environment necessary for digestive enzymes to function.\n\n• Digestive Enzymes: While the pancreas secretes critical digestive enzymes (like amylase, lipase, and trypsin), their function is to chemically break down carbohydrates, fats, and proteins rather than directly buffering or neutralizing stomach acid.\n• Mucus: Mucus is secreted by goblet cells along the gastrointestinal tract to lubricate food passage and provide a physical structural coating against acid, but it does not act as a primary chemical neutralizing agent.\n• Bile: This fluid is produced and secreted by the liver (and stored in the gallbladder), not the pancreas. Its primary function is the mechanical emulsification of fats.","whyWrongChoices":"Alternative options: bile, mucus, digestive enzymes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a secretion of the pancreas that neutralizes the acidic fluid from the stomach::::', 'a secretion of the pancreas that neutralizes the acidic fluid from the stomach:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The pancreas secretes large amounts of sodium bicarbonate into the duodenum. This alkaline fluid directly neutralizes the highly acidic chyme coming from the stomach. This neutralization process protects the delicate intestinal lining and creates the optimal alkaline environment necessary for digestive enzymes to function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bicarbonate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The pancreas secretes large amounts of sodium bicarbonate into the duodenum. This alkaline fluid directly neutralizes the highly acidic chyme coming from the stomach. This neutralization process protects the delicate intestinal lining and creates the optimal alkaline environment necessary for digestive enzymes to function.\n\n• Digestive Enzymes: While the pancreas secretes critical digestive enzymes (like amylase, lipase, and trypsin), their function is to chemically break down carbohydrates, fats, and proteins rather than directly buffering or neutralizing stomach acid.\n• Mucus: Mucus is secreted by goblet cells along the gastrointestinal tract to lubricate food passage and provide a physical structural coating against acid, but it does not act as a primary chemical neutralizing agent.\n• Bile: This fluid is produced and secreted by the liver (and stored in the gallbladder), not the pancreas. Its primary function is the mechanical emulsification of fats.","whyWrongChoices":"Alternative options: bile, mucus, digestive enzymes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fatty acids formed by hydrogenation of unsaturated fats, converting them from liquid oils to semisolid fats.:::trans-fatty acids', 'fatty acids formed by hydrogenation of unsaturated fats, converting them from liquid oils to semisolid fats.', 'trans-fatty acids', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Industrially, liquid vegetable oils (which are rich in unsaturated fats) have hydrogen gas bubbled through them in the presence of a catalyst. This is done to make them more solid, spreadable, and shelf-stable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"trans-fatty acids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Industrially, liquid vegetable oils (which are rich in unsaturated fats) have hydrogen gas bubbled through them in the presence of a catalyst. This is done to make them more solid, spreadable, and shelf-stable.\n• If the fat is partially hydrogenated rather than fully saturated, a chemical side reaction occurs. The remaining natural carbon-to-carbon double bonds flip from their native \"cis\" configuration into an unnatural, straight \"trans\" configuration. This chemical restructuring creates trans-fatty acids (trans fats).","whyWrongChoices":"Alternative options: saturated fatty acids, unsaturated fatty acids, short-chain fatty acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are functions of cobalamin except::::', 'all of the following are functions of cobalamin except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cobalamin (Vitamin B12) does not primarily function as a direct antioxidant in the body, unlike Vitamins C or E.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"antioxidant\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cobalamin (Vitamin B12) does not primarily function as a direct antioxidant in the body, unlike Vitamins C or E.","whyWrongChoices":"Alternative options: co-factors, healthy nerves (myelin sheath)"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fatty acids formed by hydrogenation of unsaturated fats, converting them from liquid oils to semisolid fats.:::', 'fatty acids formed by hydrogenation of unsaturated fats, converting them from liquid oils to semisolid fats.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Industrially, liquid vegetable oils (which are rich in unsaturated fats) have hydrogen gas bubbled through them in the presence of a catalyst. This is done to make them more solid, spreadable, and shelf-stable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"trans-fatty acids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Industrially, liquid vegetable oils (which are rich in unsaturated fats) have hydrogen gas bubbled through them in the presence of a catalyst. This is done to make them more solid, spreadable, and shelf-stable.\n• If the fat is partially hydrogenated rather than fully saturated, a chemical side reaction occurs. The remaining natural carbon-to-carbon double bonds flip from their native \"cis\" configuration into an unnatural, straight \"trans\" configuration. This chemical restructuring creates trans-fatty acids (trans fats).","whyWrongChoices":"Alternative options: saturated fatty acids, unsaturated fatty acids, short-chain fatty acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:as bmr increases, there is an increased need for::::thiamin, riboflavin, niacin', 'as bmr increases, there is an increased need for:', 'thiamin, riboflavin, niacin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"As Basal Metabolic Rate (BMR) increases, the body burns through carbohydrates, fats, and proteins at a much faster rate to produce ATP.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thiamin, riboflavin, niacin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"As Basal Metabolic Rate (BMR) increases, the body burns through carbohydrates, fats, and proteins at a much faster rate to produce ATP.\n\nThiamin (B₁), riboflavin (B₂), and niacin (B₃) function strictly as the essential coenzymes required to break down these macronutrients during cellular respiration:\n\t• Thiamin is a cofactor for pyruvate dehydrogenase to kickstart aerobic metabolism.\n\t• Riboflavin forms FAD/FADH₂, which acts as an electron carrier in the Krebs cycle and Electron Transport Chain.\n\t• Niacin forms NAD/NADH, the primary electron carrier across glycolysis and mitochondrial pathways.\n\nBecause their metabolic utilization is directly tied to total energy expenditure, your physical requirement for these three specific B vitamins scales upward as your BMR increases.\n\n• Vitamins A, C, D, E, and K perform localized or systemic cellular tasks (such as antioxidant defenses, bone mineral regulation, immune signaling, and blood clotting factors) that operate independently of immediate carbohydrate and lipid calorie-burning metrics.","whyWrongChoices":"Alternative options: vitamins A & D, vitamin C, vitamins E & K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:as bmr increases, there is an increased need for::::', 'as bmr increases, there is an increased need for:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"As Basal Metabolic Rate (BMR) increases, the body burns through carbohydrates, fats, and proteins at a much faster rate to produce ATP.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thiamin, riboflavin, niacin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"As Basal Metabolic Rate (BMR) increases, the body burns through carbohydrates, fats, and proteins at a much faster rate to produce ATP.\n\nThiamin (B₁), riboflavin (B₂), and niacin (B₃) function strictly as the essential coenzymes required to break down these macronutrients during cellular respiration:\n\t• Thiamin is a cofactor for pyruvate dehydrogenase to kickstart aerobic metabolism.\n\t• Riboflavin forms FAD/FADH₂, which acts as an electron carrier in the Krebs cycle and Electron Transport Chain.\n\t• Niacin forms NAD/NADH, the primary electron carrier across glycolysis and mitochondrial pathways.\n\nBecause their metabolic utilization is directly tied to total energy expenditure, your physical requirement for these three specific B vitamins scales upward as your BMR increases.\n\n• Vitamins A, C, D, E, and K perform localized or systemic cellular tasks (such as antioxidant defenses, bone mineral regulation, immune signaling, and blood clotting factors) that operate independently of immediate carbohydrate and lipid calorie-burning metrics.","whyWrongChoices":"Alternative options: vitamins A & D, vitamin C, vitamins E & K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:glossitis is caused by a deficiency of::::b complex vitamins', 'glossitis is caused by a deficiency of:', 'B complex vitamins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glossitis—which is inflammation of the tongue causing it to swell, turn smooth, and lose its tiny bumps (papillae)—is a classic clinical hallmark of B-complex vitamin deficiencies. It is most frequently tied to a lack of Vitamin B₁₂ (cobalamin), Vitamin B₉ (folate), Vitamin B₆ (pyridoxine), Vitamin B₃ (niacin), and Vitamin B₂ (riboflavin).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B complex vitamins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glossitis—which is inflammation of the tongue causing it to swell, turn smooth, and lose its tiny bumps (papillae)—is a classic clinical hallmark of B-complex vitamin deficiencies. It is most frequently tied to a lack of Vitamin B₁₂ (cobalamin), Vitamin B₉ (folate), Vitamin B₆ (pyridoxine), Vitamin B₃ (niacin), and Vitamin B₂ (riboflavin).\n\nCells lining the mouth and tongue have a very rapid turnover rate. Because B vitamins act as essential coenzymes for cellular energy production and DNA synthesis, a deficiency rapidly impairs the body''s ability to regenerate these tongue cells, leading to inflammation and atrophy.","whyWrongChoices":"Alternative options: vitamin A, vitamin C, vitamin D"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it enhances iron absorption.:::vit c', 'it enhances iron absorption.', 'Vit C', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin C facilitates iron absorption by forming a chelate with ferric iron at acid pH that remains soluble at the alkaline pH of the duodenum.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin C facilitates iron absorption by forming a chelate with ferric iron at acid pH that remains soluble at the alkaline pH of the duodenum.","whyWrongChoices":"Alternative options: Vit A, Vit B, Vit D"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:glossitis is caused by a deficiency of::::', 'glossitis is caused by a deficiency of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glossitis—which is inflammation of the tongue causing it to swell, turn smooth, and lose its tiny bumps (papillae)—is a classic clinical hallmark of B-complex vitamin deficiencies. It is most frequently tied to a lack of Vitamin B₁₂ (cobalamin), Vitamin B₉ (folate), Vitamin B₆ (pyridoxine), Vitamin B₃ (niacin), and Vitamin B₂ (riboflavin).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B complex vitamins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glossitis—which is inflammation of the tongue causing it to swell, turn smooth, and lose its tiny bumps (papillae)—is a classic clinical hallmark of B-complex vitamin deficiencies. It is most frequently tied to a lack of Vitamin B₁₂ (cobalamin), Vitamin B₉ (folate), Vitamin B₆ (pyridoxine), Vitamin B₃ (niacin), and Vitamin B₂ (riboflavin).\n\nCells lining the mouth and tongue have a very rapid turnover rate. Because B vitamins act as essential coenzymes for cellular energy production and DNA synthesis, a deficiency rapidly impairs the body''s ability to regenerate these tongue cells, leading to inflammation and atrophy.","whyWrongChoices":"Alternative options: vitamin A, vitamin C, vitamin D"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are functions of bile except::::it increases the surface tension of fat', 'all are functions of bile except:', 'it increases the surface tension of fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile salts actually act as detergents (surfactants) that decrease the surface tension of large fat globules. Lowering the surface tension allows the large globules to easily break apart into tiny droplets—a physical process called emulsification.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"it increases the surface tension of fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile salts actually act as detergents (surfactants) that decrease the surface tension of large fat globules. Lowering the surface tension allows the large globules to easily break apart into tiny droplets—a physical process called emulsification.","whyWrongChoices":"Alternative options: it activates lipase, it is a carrier of vitamins A,D,E,K, it accelerates the action of pancreatic enzymes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are functions of bile except::::', 'all are functions of bile except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile salts actually act as detergents (surfactants) that decrease the surface tension of large fat globules. Lowering the surface tension allows the large globules to easily break apart into tiny droplets—a physical process called emulsification.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"it increases the surface tension of fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile salts actually act as detergents (surfactants) that decrease the surface tension of large fat globules. Lowering the surface tension allows the large globules to easily break apart into tiny droplets—a physical process called emulsification.","whyWrongChoices":"Alternative options: it activates lipase, it is a carrier of vitamins A,D,E,K, it accelerates the action of pancreatic enzymes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fat digestion occurs in the::::small intestines', 'fat digestion occurs in the:', 'small intestines', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The small intestine is the primary site for both the chemical digestion and absorption of dietary fats. This process relies on two critical substances released into the duodenum:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"small intestines\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The small intestine is the primary site for both the chemical digestion and absorption of dietary fats. This process relies on two critical substances released into the duodenum:\n\t• Bile Salts: Secreted by the liver and stored in the gallbladder, bile salts act as a detergent to emulsify large fat globules into tiny droplets. This mechanical action dramatically increases the surface area available for enzymes.\n\t• Pancreatic Lipase: The principal fat-digesting enzyme, which is secreted by the pancreas, breaks down these small emulsified fat droplets into free fatty acids and monoglycerides for absorption by enterocytes.\n\n• The Stomach: While a small amount of lipid digestion begins here via gastric lipase, it is highly limited because the stomach lacks bile salts to emulsify fats efficiently.\n• The Large Intestine: The colon is primarily responsible for absorbing remaining water, synthesizing certain vitamins through gut microbiota, and forming feces. No functional fat digestion takes place here.","whyWrongChoices":"Alternative options: stomach, large intestines, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fat digestion occurs in the::::', 'fat digestion occurs in the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The small intestine is the primary site for both the chemical digestion and absorption of dietary fats. This process relies on two critical substances released into the duodenum:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"small intestines\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The small intestine is the primary site for both the chemical digestion and absorption of dietary fats. This process relies on two critical substances released into the duodenum:\n\t• Bile Salts: Secreted by the liver and stored in the gallbladder, bile salts act as a detergent to emulsify large fat globules into tiny droplets. This mechanical action dramatically increases the surface area available for enzymes.\n\t• Pancreatic Lipase: The principal fat-digesting enzyme, which is secreted by the pancreas, breaks down these small emulsified fat droplets into free fatty acids and monoglycerides for absorption by enterocytes.\n\n• The Stomach: While a small amount of lipid digestion begins here via gastric lipase, it is highly limited because the stomach lacks bile salts to emulsify fats efficiently.\n• The Large Intestine: The colon is primarily responsible for absorbing remaining water, synthesizing certain vitamins through gut microbiota, and forming feces. No functional fat digestion takes place here.","whyWrongChoices":"Alternative options: stomach, large intestines, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the hormone secreted by duodenal cells that stimulates the pancreas to release pancreatic juice.:::secretin', 'the hormone secreted by duodenal cells that stimulates the pancreas to release pancreatic juice.', 'secretin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Secretin, a hormone, is secreted by the \"S cells\" of the duodenum in response to the acidic pH of the incoming gastric contents (chyme). It travels through the bloodstream to the pancreas and stimulates the release of a pancreatic juice rich in bicarbonate. The bicarbonate acts as a buffer to neutralize the stomach acid, protecting the intestinal lining and creating the optimal alkaline environment for digestive enzymes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"secretin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Secretin, a hormone, is secreted by the \"S cells\" of the duodenum in response to the acidic pH of the incoming gastric contents (chyme). It travels through the bloodstream to the pancreas and stimulates the release of a pancreatic juice rich in bicarbonate. The bicarbonate acts as a buffer to neutralize the stomach acid, protecting the intestinal lining and creating the optimal alkaline environment for digestive enzymes.\n\n• Cholecystokinin / CCK: Also secreted by the duodenum (specifically by \"I cells\"), CCK is triggered by the presence of fats and proteins. While it also acts on the pancreas, its primary role is to stimulate the pancreas to release digestive enzymes (like trypsin and pancreatic lipase) and signal the gallbladder to contract and release bile.\n• Gastrin: This hormone is secreted by \"G cells\" in the stomach (not the duodenum) and functions to stimulate the gastric glands to secrete hydrochloric acid (HCl) and pepsinogen.\n• Chyme: This is not a hormone at all. It is the semi-fluid mass of partly digested food expelled by the stomach into the duodenum.","whyWrongChoices":"Alternative options: gastrin, chyme, cholecystokinin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the hormone secreted by duodenal cells that stimulates the pancreas to release pancreatic juice.:::', 'the hormone secreted by duodenal cells that stimulates the pancreas to release pancreatic juice.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Secretin, a hormone, is secreted by the \"S cells\" of the duodenum in response to the acidic pH of the incoming gastric contents (chyme). It travels through the bloodstream to the pancreas and stimulates the release of a pancreatic juice rich in bicarbonate. The bicarbonate acts as a buffer to neutralize the stomach acid, protecting the intestinal lining and creating the optimal alkaline environment for digestive enzymes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"secretin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Secretin, a hormone, is secreted by the \"S cells\" of the duodenum in response to the acidic pH of the incoming gastric contents (chyme). It travels through the bloodstream to the pancreas and stimulates the release of a pancreatic juice rich in bicarbonate. The bicarbonate acts as a buffer to neutralize the stomach acid, protecting the intestinal lining and creating the optimal alkaline environment for digestive enzymes.\n\n• Cholecystokinin / CCK: Also secreted by the duodenum (specifically by \"I cells\"), CCK is triggered by the presence of fats and proteins. While it also acts on the pancreas, its primary role is to stimulate the pancreas to release digestive enzymes (like trypsin and pancreatic lipase) and signal the gallbladder to contract and release bile.\n• Gastrin: This hormone is secreted by \"G cells\" in the stomach (not the duodenum) and functions to stimulate the gastric glands to secrete hydrochloric acid (HCl) and pepsinogen.\n• Chyme: This is not a hormone at all. It is the semi-fluid mass of partly digested food expelled by the stomach into the duodenum.","whyWrongChoices":"Alternative options: gastrin, chyme, cholecystokinin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a measure of the nutrients a food provides in relation to the energy it provides.:::nutrient density', 'a measure of the nutrients a food provides in relation to the energy it provides.', 'nutrient density', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the literal scientific definition of nutrient density. It measures the concentration of beneficial nutrients (such as vitamins, minerals, complex carbohydrates, lean protein, and healthy fats) in a food relative to the total calories (energy content) it delivers. For example, fresh spinach has high nutrient density because it provides massive amounts of vitamins for very few calories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nutrient density\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the literal scientific definition of nutrient density. It measures the concentration of beneficial nutrients (such as vitamins, minerals, complex carbohydrates, lean protein, and healthy fats) in a food relative to the total calories (energy content) it delivers. For example, fresh spinach has high nutrient density because it provides massive amounts of vitamins for very few calories.\n\n• Energy density measures the number of calories (energy) per gram of food weight. High energy-dense foods (like potato chips or butter) provide a high amount of calories in a small, lightweight serving size.\n• The glycemic index ranks carbohydrates based on how quickly they raise blood sugar levels,.\n• Diet diversity refers to eating a wide variety of different food groups to ensure balanced nutrient intake.","whyWrongChoices":"Alternative options: glycemic index, diet diversity, energy density"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a measure of the nutrients a food provides in relation to the energy it provides.:::', 'a measure of the nutrients a food provides in relation to the energy it provides.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the literal scientific definition of nutrient density. It measures the concentration of beneficial nutrients (such as vitamins, minerals, complex carbohydrates, lean protein, and healthy fats) in a food relative to the total calories (energy content) it delivers. For example, fresh spinach has high nutrient density because it provides massive amounts of vitamins for very few calories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nutrient density\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the literal scientific definition of nutrient density. It measures the concentration of beneficial nutrients (such as vitamins, minerals, complex carbohydrates, lean protein, and healthy fats) in a food relative to the total calories (energy content) it delivers. For example, fresh spinach has high nutrient density because it provides massive amounts of vitamins for very few calories.\n\n• Energy density measures the number of calories (energy) per gram of food weight. High energy-dense foods (like potato chips or butter) provide a high amount of calories in a small, lightweight serving size.\n• The glycemic index ranks carbohydrates based on how quickly they raise blood sugar levels,.\n• Diet diversity refers to eating a wide variety of different food groups to ensure balanced nutrient intake.","whyWrongChoices":"Alternative options: glycemic index, diet diversity, energy density"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:if the actual cost of a whole cake is p500, having a yield of 10 slices, and selling price is p90 per slice, what is the food cost percentage?:::55.6%', 'if the actual cost of a whole cake is p500, having a yield of 10 slices, and selling price is p90 per slice, what is the food cost percentage?', '55.6%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"(500/(90*10))*100","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"55.6%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"(500/(90*10))*100","whyWrongChoices":"Alternative options: 5.56%, 18%, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the mineral needed to keep the heart beat steady and plays a major role in maintaining fluid and electrolyte balance.:::potassium', 'the mineral needed to keep the heart beat steady and plays a major role in maintaining fluid and electrolyte balance.', 'potassium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Potassium is the primary intracellular cation (positively charged ion) in the body. It functions closely with the heart''s electrical conduction system to stabilize resting membrane potentials. Proper levels are absolutely essential to maintain a regular cardiac rhythm and contractility. Severe deviations (either hypokalemia or hyperkalemia) can trigger lethal cardiac arrhythmias.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"potassium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Potassium is the primary intracellular cation (positively charged ion) in the body. It functions closely with the heart''s electrical conduction system to stabilize resting membrane potentials. Proper levels are absolutely essential to maintain a regular cardiac rhythm and contractility. Severe deviations (either hypokalemia or hyperkalemia) can trigger lethal cardiac arrhythmias.\n\nPotassium works in tandem with sodium via the cellular sodium-potassium pump. While sodium regulates fluid outside the cells, potassium regulates fluid volumes inside the cells, preserving structural cell integrity and overall fluid homeostasis.\n\n\t• Sodium: Primarily acts as the major regulator of extracellular fluid volume and blood pressure. While an imbalance stresses the heart indirectly, it does not directly regulate heartbeat steadiness like potassium does.\n\t• Calcium: Triggers the physical contraction of muscles (including the heart), but it is not the primary ion responsible for maintaining fluid balance across cellular compartments.\n\t• Magnesium: Acts as a crucial stabilizer for enzymatic functions and works closely with potassium.","whyWrongChoices":"Alternative options: calcium, magnesium, sodium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the mineral needed to keep the heart beat steady and plays a major role in maintaining fluid and electrolyte balance.:::', 'the mineral needed to keep the heart beat steady and plays a major role in maintaining fluid and electrolyte balance.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Potassium is the primary intracellular cation (positively charged ion) in the body. It functions closely with the heart''s electrical conduction system to stabilize resting membrane potentials. Proper levels are absolutely essential to maintain a regular cardiac rhythm and contractility. Severe deviations (either hypokalemia or hyperkalemia) can trigger lethal cardiac arrhythmias.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"potassium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Potassium is the primary intracellular cation (positively charged ion) in the body. It functions closely with the heart''s electrical conduction system to stabilize resting membrane potentials. Proper levels are absolutely essential to maintain a regular cardiac rhythm and contractility. Severe deviations (either hypokalemia or hyperkalemia) can trigger lethal cardiac arrhythmias.\n\nPotassium works in tandem with sodium via the cellular sodium-potassium pump. While sodium regulates fluid outside the cells, potassium regulates fluid volumes inside the cells, preserving structural cell integrity and overall fluid homeostasis.\n\n\t• Sodium: Primarily acts as the major regulator of extracellular fluid volume and blood pressure. While an imbalance stresses the heart indirectly, it does not directly regulate heartbeat steadiness like potassium does.\n\t• Calcium: Triggers the physical contraction of muscles (including the heart), but it is not the primary ion responsible for maintaining fluid balance across cellular compartments.\n\t• Magnesium: Acts as a crucial stabilizer for enzymatic functions and works closely with potassium.","whyWrongChoices":"Alternative options: calcium, magnesium, sodium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:eating foods containing vitamin c in the same meal can increase the absorption of which mineral?:::iron', 'eating foods containing vitamin c in the same meal can increase the absorption of which mineral?', 'iron', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dietary iron exists in two forms: heme iron (from animal tissues) and non-heme iron (from plant foods). Non-heme iron is inherently difficult for the human body to absorb because it is typically found in its oxidized ferric state (Fe³⁺).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dietary iron exists in two forms: heme iron (from animal tissues) and non-heme iron (from plant foods). Non-heme iron is inherently difficult for the human body to absorb because it is typically found in its oxidized ferric state (Fe³⁺).\n\nVitamin C (ascorbic acid) acts as a powerful reducing agent. When consumed in the same meal, it reduces ferric iron (Fe³⁺) into its highly soluble ferrous state (Fe²⁺). It also binds with the iron to form a stable chelate complex that prevents it from binding to inhibitors like phytates or tannins. This significantly boosts iron absorption across the intestinal lining.","whyWrongChoices":"Alternative options: calcium, magnesium, zinc"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:eating foods containing vitamin c in the same meal can increase the absorption of which mineral?:::', 'eating foods containing vitamin c in the same meal can increase the absorption of which mineral?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dietary iron exists in two forms: heme iron (from animal tissues) and non-heme iron (from plant foods). Non-heme iron is inherently difficult for the human body to absorb because it is typically found in its oxidized ferric state (Fe³⁺).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dietary iron exists in two forms: heme iron (from animal tissues) and non-heme iron (from plant foods). Non-heme iron is inherently difficult for the human body to absorb because it is typically found in its oxidized ferric state (Fe³⁺).\n\nVitamin C (ascorbic acid) acts as a powerful reducing agent. When consumed in the same meal, it reduces ferric iron (Fe³⁺) into its highly soluble ferrous state (Fe²⁺). It also binds with the iron to form a stable chelate complex that prevents it from binding to inhibitors like phytates or tannins. This significantly boosts iron absorption across the intestinal lining.","whyWrongChoices":"Alternative options: calcium, magnesium, zinc"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamins that function in normal blood formation except::::biotin', 'vitamins that function in normal blood formation except:', 'biotin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biotin (Vitamin B₇) serves as a vital coenzyme for carboxylase enzymes involved in lipid synthesis, glucose production (gluconeogenesis), and amino acid catabolism. It does not play a direct, primary role in hematopoiesis (blood cell formation) or hemoglobin synthesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biotin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biotin (Vitamin B₇) serves as a vital coenzyme for carboxylase enzymes involved in lipid synthesis, glucose production (gluconeogenesis), and amino acid catabolism. It does not play a direct, primary role in hematopoiesis (blood cell formation) or hemoglobin synthesis.\n\n• Pyridoxine: This vitamin is essential for normal blood formation. Pyridoxine (Vitamin B₆), in its active form as pyridoxal phosphate (PLP), acts as a mandatory coenzyme for the enzyme ALA synthase. This is the enzyme that initiates the very first step of heme synthesis inside the mitochondria. A deficiency in B₆ directly leads to microcytic, hypochromic sideroblastic anemia.\n• Cobalamin: This vitamin is crucial for red blood cell development. Cobalamin (Vitamin B₁₂) is a required cofactor alongside folate for DNA synthesis in rapidly dividing hematopoietic stem cells. Without it, bone marrow cells cannot mature normally, resulting in macrocytic or megaloblastic anemia.\n• Folate: This vitamin is foundational for hematopoiesis. Folate (Vitamin B₉) is required for the synthesis of purines and thymidylate, which are essential building blocks for DNA replication. When folate is missing, erythroblasts in the bone marrow cannot divide smoothly, leading to aborted maturation and megaloblastic anemia.","whyWrongChoices":"Alternative options: cobalamin, pyridoxine, folate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamins that function in normal blood formation except::::', 'vitamins that function in normal blood formation except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biotin (Vitamin B₇) serves as a vital coenzyme for carboxylase enzymes involved in lipid synthesis, glucose production (gluconeogenesis), and amino acid catabolism. It does not play a direct, primary role in hematopoiesis (blood cell formation) or hemoglobin synthesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biotin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biotin (Vitamin B₇) serves as a vital coenzyme for carboxylase enzymes involved in lipid synthesis, glucose production (gluconeogenesis), and amino acid catabolism. It does not play a direct, primary role in hematopoiesis (blood cell formation) or hemoglobin synthesis.\n\n• Pyridoxine: This vitamin is essential for normal blood formation. Pyridoxine (Vitamin B₆), in its active form as pyridoxal phosphate (PLP), acts as a mandatory coenzyme for the enzyme ALA synthase. This is the enzyme that initiates the very first step of heme synthesis inside the mitochondria. A deficiency in B₆ directly leads to microcytic, hypochromic sideroblastic anemia.\n• Cobalamin: This vitamin is crucial for red blood cell development. Cobalamin (Vitamin B₁₂) is a required cofactor alongside folate for DNA synthesis in rapidly dividing hematopoietic stem cells. Without it, bone marrow cells cannot mature normally, resulting in macrocytic or megaloblastic anemia.\n• Folate: This vitamin is foundational for hematopoiesis. Folate (Vitamin B₉) is required for the synthesis of purines and thymidylate, which are essential building blocks for DNA replication. When folate is missing, erythroblasts in the bone marrow cannot divide smoothly, leading to aborted maturation and megaloblastic anemia.","whyWrongChoices":"Alternative options: cobalamin, pyridoxine, folate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:minerals that are effective antioxidants except::::cr', 'minerals that are effective antioxidants except:', 'Cr', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chromium (Cr) is a trace mineral primarily known for its role in carbohydrate, lipid, and protein metabolism by enhancing the action of insulin. It does not function directly or serve as a traditional cofactor for major endogenous antioxidant enzyme systems.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cr\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chromium (Cr) is a trace mineral primarily known for its role in carbohydrate, lipid, and protein metabolism by enhancing the action of insulin. It does not function directly or serve as a traditional cofactor for major endogenous antioxidant enzyme systems.\n\n• Selenium: This mineral is a well-established and highly effective antioxidant. It forms an essential structural component of the active site of the enzyme glutathione peroxidase, which neutralizes harmful hydrogen peroxide and lipid hydroperoxides into harmless water and alcohols.\n• Iron: This mineral plays a vital role in antioxidant defense mechanisms. Iron (Fe) serves as an essential cofactor for the enzyme catalase, an incredibly rapid antioxidant enzyme that converts toxic hydrogen peroxide molecules into water and oxygen within cells.\n• Copper: This mineral is a critical component of the antioxidant defense loop. Copper (Cu) acts alongside zinc as a mandatory structural cofactor for cytosolic superoxide dismutase (CuZn-SOD). This enzyme acts as the first line of defense by transforming highly reactive superoxide free radicals into less destructive hydrogen peroxide.","whyWrongChoices":"Alternative options: Cu, Se, Fe"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:minerals that are effective antioxidants except::::', 'minerals that are effective antioxidants except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chromium (Cr) is a trace mineral primarily known for its role in carbohydrate, lipid, and protein metabolism by enhancing the action of insulin. It does not function directly or serve as a traditional cofactor for major endogenous antioxidant enzyme systems.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cr\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chromium (Cr) is a trace mineral primarily known for its role in carbohydrate, lipid, and protein metabolism by enhancing the action of insulin. It does not function directly or serve as a traditional cofactor for major endogenous antioxidant enzyme systems.\n\n• Selenium: This mineral is a well-established and highly effective antioxidant. It forms an essential structural component of the active site of the enzyme glutathione peroxidase, which neutralizes harmful hydrogen peroxide and lipid hydroperoxides into harmless water and alcohols.\n• Iron: This mineral plays a vital role in antioxidant defense mechanisms. Iron (Fe) serves as an essential cofactor for the enzyme catalase, an incredibly rapid antioxidant enzyme that converts toxic hydrogen peroxide molecules into water and oxygen within cells.\n• Copper: This mineral is a critical component of the antioxidant defense loop. Copper (Cu) acts alongside zinc as a mandatory structural cofactor for cytosolic superoxide dismutase (CuZn-SOD). This enzyme acts as the first line of defense by transforming highly reactive superoxide free radicals into less destructive hydrogen peroxide.","whyWrongChoices":"Alternative options: Cu, Se, Fe"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:two vitamins whose requirements are based on an individual’s energy intake.:::b₁ & b₂', 'two vitamins whose requirements are based on an individual’s energy intake.', 'B₁ & B₂', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Thiamine (B₁): Serves as a mandatory coenzyme for carbohydrate metabolism and the processing of pyruvate. Standard guidelines traditionally recommend 0.5 mg of thiamine per 1,000 kcal consumed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B₁ & B₂\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Thiamine (B₁): Serves as a mandatory coenzyme for carbohydrate metabolism and the processing of pyruvate. Standard guidelines traditionally recommend 0.5 mg of thiamine per 1,000 kcal consumed.\n\nRiboflavin (B₂): Serves as a vital electron carrier (FAD) in mitochondrial biological oxidation and the citric acid cycle. Standard requirements are classically set at 0.5 mg of riboflavin per 1,000 kcal.\n\nNiacin (B₃): Serves as a core electron carrier (NAD/NADH) in glycolysis and fatty acid oxidation. Standard requirements are similarly calculated as 6.6 mg of Niacin Equivalents (NE) per 1,000 kcal.","whyWrongChoices":"Alternative options: B₁ & B₆, B₁ & B₃, B₁ & B₁₂"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:two vitamins whose requirements are based on an individual’s energy intake.:::', 'two vitamins whose requirements are based on an individual’s energy intake.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Thiamine (B₁): Serves as a mandatory coenzyme for carbohydrate metabolism and the processing of pyruvate. Standard guidelines traditionally recommend 0.5 mg of thiamine per 1,000 kcal consumed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B₁ & B₂\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Thiamine (B₁): Serves as a mandatory coenzyme for carbohydrate metabolism and the processing of pyruvate. Standard guidelines traditionally recommend 0.5 mg of thiamine per 1,000 kcal consumed.\n\nRiboflavin (B₂): Serves as a vital electron carrier (FAD) in mitochondrial biological oxidation and the citric acid cycle. Standard requirements are classically set at 0.5 mg of riboflavin per 1,000 kcal.\n\nNiacin (B₃): Serves as a core electron carrier (NAD/NADH) in glycolysis and fatty acid oxidation. Standard requirements are similarly calculated as 6.6 mg of Niacin Equivalents (NE) per 1,000 kcal.","whyWrongChoices":"Alternative options: B₁ & B₆, B₁ & B₃, B₁ & B₁₂"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are needed for the conversion of tryptophan to niacin except::::zn', 'all are needed for the conversion of tryptophan to niacin except:', 'Zn', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The synthesis of niacin (Vitamin B₃) from the essential amino acid tryptophan occurs via the kynurenine pathway in the liver. This multi-step conversion is highly nutrient-dependent and strictly requires three cofactors:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The synthesis of niacin (Vitamin B₃) from the essential amino acid tryptophan occurs via the kynurenine pathway in the liver. This multi-step conversion is highly nutrient-dependent and strictly requires three cofactors:\n\n• Vitamin B₆ (Pyridoxine): Active pyridoxal 5′-phosphate (PLP) is the direct coenzyme required by kynureninase, an essential enzyme in the pathway.\n• Vitamin B₂ (Riboflavin): Active FAD is required as a cofactor for kynurenine 3-monooxygenase, and riboflavin is also needed to synthesize active B₆.\n• Iron (Fe): Iron is a critical component of the initial rate-limiting enzyme, tryptophan 2,3-dioxygenase.","whyWrongChoices":"Alternative options: B₂, B₆, Fe"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are needed for the conversion of tryptophan to niacin except::::', 'all are needed for the conversion of tryptophan to niacin except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The synthesis of niacin (Vitamin B₃) from the essential amino acid tryptophan occurs via the kynurenine pathway in the liver. This multi-step conversion is highly nutrient-dependent and strictly requires three cofactors:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The synthesis of niacin (Vitamin B₃) from the essential amino acid tryptophan occurs via the kynurenine pathway in the liver. This multi-step conversion is highly nutrient-dependent and strictly requires three cofactors:\n\n• Vitamin B₆ (Pyridoxine): Active pyridoxal 5′-phosphate (PLP) is the direct coenzyme required by kynureninase, an essential enzyme in the pathway.\n• Vitamin B₂ (Riboflavin): Active FAD is required as a cofactor for kynurenine 3-monooxygenase, and riboflavin is also needed to synthesize active B₆.\n• Iron (Fe): Iron is a critical component of the initial rate-limiting enzyme, tryptophan 2,3-dioxygenase.","whyWrongChoices":"Alternative options: B₂, B₆, Fe"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements about ascorbic acid is incorrect?:::its requirement varies with the caloric intake.', 'which of the following statements about ascorbic acid is incorrect?', 'Its requirement varies with the caloric intake.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ascorbic acid (Vitamin C) functions as a water-soluble antioxidant and an essential enzymatic cofactor (e.g., for collagen synthesis). Its daily physiological requirements do not change based on how many calories you eat. In contrast, the requirements for B-complex vitamins like Thiamine (B1), Riboflavin (B2), and Niacin (B3) are directly tied to caloric and carbohydrate intake because they serve as direct coenzymes in energy metabolism pathways.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Its requirement varies with the caloric intake.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ascorbic acid (Vitamin C) functions as a water-soluble antioxidant and an essential enzymatic cofactor (e.g., for collagen synthesis). Its daily physiological requirements do not change based on how many calories you eat. In contrast, the requirements for B-complex vitamins like Thiamine (B1), Riboflavin (B2), and Niacin (B3) are directly tied to caloric and carbohydrate intake because they serve as direct coenzymes in energy metabolism pathways.\n\n• Metabolism to Oxalate: This statement is correct. Ascorbic acid breaks down non-enzymatically in the body to form oxalate. This oxalate can bind with calcium in the urinary tract to form insoluble calcium oxalate salts, which are the main components of the most common type of kidney stones.\n• Oxidation by Metal Ions: This statement is correct. Ascorbic acid is a strong reducing agent that is easily degraded and readily oxidized in the presence of heat, light, and divalent metal ions like copper (Cu²⁺) and iron (Fe²⁺).\n• Iron Absorption Facilitation: This statement is correct. Vitamin C significantly enhances the absorption of non-heme iron in the gut. It does this by reducing dietary ferric iron (Fe³⁺) into its highly soluble ferrous state (Fe²⁺), making it much easier for the intestinal mucosa to absorb.","whyWrongChoices":"Alternative options: It facilitates the absorption of dietary iron., It is metabolized in part to oxalate which can form an insoluble salt with calcium., It is readily oxidized by divalent metal ions."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:which of the following statements about ascorbic acid is incorrect?:::', 'which of the following statements about ascorbic acid is incorrect?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ascorbic acid (Vitamin C) functions as a water-soluble antioxidant and an essential enzymatic cofactor (e.g., for collagen synthesis). Its daily physiological requirements do not change based on how many calories you eat. In contrast, the requirements for B-complex vitamins like Thiamine (B1), Riboflavin (B2), and Niacin (B3) are directly tied to caloric and carbohydrate intake because they serve as direct coenzymes in energy metabolism pathways.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Its requirement varies with the caloric intake.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ascorbic acid (Vitamin C) functions as a water-soluble antioxidant and an essential enzymatic cofactor (e.g., for collagen synthesis). Its daily physiological requirements do not change based on how many calories you eat. In contrast, the requirements for B-complex vitamins like Thiamine (B1), Riboflavin (B2), and Niacin (B3) are directly tied to caloric and carbohydrate intake because they serve as direct coenzymes in energy metabolism pathways.\n\n• Metabolism to Oxalate: This statement is correct. Ascorbic acid breaks down non-enzymatically in the body to form oxalate. This oxalate can bind with calcium in the urinary tract to form insoluble calcium oxalate salts, which are the main components of the most common type of kidney stones.\n• Oxidation by Metal Ions: This statement is correct. Ascorbic acid is a strong reducing agent that is easily degraded and readily oxidized in the presence of heat, light, and divalent metal ions like copper (Cu²⁺) and iron (Fe²⁺).\n• Iron Absorption Facilitation: This statement is correct. Vitamin C significantly enhances the absorption of non-heme iron in the gut. It does this by reducing dietary ferric iron (Fe³⁺) into its highly soluble ferrous state (Fe²⁺), making it much easier for the intestinal mucosa to absorb.","whyWrongChoices":"Alternative options: It facilitates the absorption of dietary iron., It is metabolized in part to oxalate which can form an insoluble salt with calcium., It is readily oxidized by divalent metal ions."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:peak bone mass refers to the highest bone density achieved by an individual which usually occurs at the age of .:::30', 'peak bone mass refers to the highest bone density achieved by an individual which usually occurs at the age of .', '30', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• During childhood and adolescence, the body builds new bone faster than it breaks down old bone, causing bone mass to increase rapidly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"30\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• During childhood and adolescence, the body builds new bone faster than it breaks down old bone, causing bone mass to increase rapidly.\n• Most people reach their peak bone mass—the maximum strength, density, and thickness their bones will ever achieve—by their late 20s or around age 30.\n• After age 30, the remodeling balance shifts. The body begins to resorb (break down) bone slightly faster than it replaces it, leading to a gradual, lifelong loss of bone density.","whyWrongChoices":"Alternative options: 20, 40, 50"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:due to its many roles in amino acid metabolism, its dietary needs are proportional to protein intake.:::b₆', 'due to its many roles in amino acid metabolism, its dietary needs are proportional to protein intake.', 'B₆', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Vitamin B_{6}\\] is the direct precursor to pyridoxal phosphate (PLP). This vital coenzyme is required for almost all pathways involving amino acid metabolism, including transamination, deamination, and decarboxylation. Proportional to Protein: Because its primary biological purpose is processing and utilizing incoming amino acids, your body''s dietary requirement for Vitamin \\[B_{6}\\] scales up or down in direct proportion to the amount of protein you consume.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B₆\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Vitamin B_{6}\\] is the direct precursor to pyridoxal phosphate (PLP). This vital coenzyme is required for almost all pathways involving amino acid metabolism, including transamination, deamination, and decarboxylation. Proportional to Protein: Because its primary biological purpose is processing and utilizing incoming amino acids, your body''s dietary requirement for Vitamin \\[B_{6}\\] scales up or down in direct proportion to the amount of protein you consume.","whyWrongChoices":"Alternative options: B₂, B₁, B₃"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:due to its many roles in amino acid metabolism, its dietary needs are proportional to protein intake.:::', 'due to its many roles in amino acid metabolism, its dietary needs are proportional to protein intake.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Vitamin B_{6}\\] is the direct precursor to pyridoxal phosphate (PLP). This vital coenzyme is required for almost all pathways involving amino acid metabolism, including transamination, deamination, and decarboxylation. Proportional to Protein: Because its primary biological purpose is processing and utilizing incoming amino acids, your body''s dietary requirement for Vitamin \\[B_{6}\\] scales up or down in direct proportion to the amount of protein you consume.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B₆\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Vitamin B_{6}\\] is the direct precursor to pyridoxal phosphate (PLP). This vital coenzyme is required for almost all pathways involving amino acid metabolism, including transamination, deamination, and decarboxylation. Proportional to Protein: Because its primary biological purpose is processing and utilizing incoming amino acids, your body''s dietary requirement for Vitamin \\[B_{6}\\] scales up or down in direct proportion to the amount of protein you consume.","whyWrongChoices":"Alternative options: B₂, B₁, B₃"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these glucogenic amino acids can be converted to α-keto acid, a carbohydrate former, except for::::leucine', 'these glucogenic amino acids can be converted to α-keto acid, a carbohydrate former, except for:', 'leucine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leucine and lysine are the only two amino acids in the human body that are strictly purely ketogenic. They are degraded directly into acetyl-CoA or acetoacetate, which are precursors for ketone bodies and fatty acids, and cannot be used to synthesize carbohydrates via gluconeogenesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"leucine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leucine and lysine are the only two amino acids in the human body that are strictly purely ketogenic. They are degraded directly into acetyl-CoA or acetoacetate, which are precursors for ketone bodies and fatty acids, and cannot be used to synthesize carbohydrates via gluconeogenesis.\n\n• Cysteine: This is a purely glucogenic amino acid. It is converted into the α-keto acid pyruvate through a multi-step oxidative pathway, making it an effective carbohydrate former.\n• Glycine: This is a purely glucogenic amino acid. It enters carbohydrate-forming pathways by being converted into serine, which is then deaminated directly into pyruvate (an α-keto acid).\n• Methionine: This is a purely glucogenic amino acid. It is metabolized through a pathway that converts its carbon skeleton into succinyl-CoA, a citric acid cycle intermediate that ultimately yields oxaloacetate to fuel glucose production.","whyWrongChoices":"Alternative options: glycine, cysteine, methionine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these glucogenic amino acids can be converted to α-keto acid, a carbohydrate former, except for::::', 'these glucogenic amino acids can be converted to α-keto acid, a carbohydrate former, except for:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leucine and lysine are the only two amino acids in the human body that are strictly purely ketogenic. They are degraded directly into acetyl-CoA or acetoacetate, which are precursors for ketone bodies and fatty acids, and cannot be used to synthesize carbohydrates via gluconeogenesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"leucine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leucine and lysine are the only two amino acids in the human body that are strictly purely ketogenic. They are degraded directly into acetyl-CoA or acetoacetate, which are precursors for ketone bodies and fatty acids, and cannot be used to synthesize carbohydrates via gluconeogenesis.\n\n• Cysteine: This is a purely glucogenic amino acid. It is converted into the α-keto acid pyruvate through a multi-step oxidative pathway, making it an effective carbohydrate former.\n• Glycine: This is a purely glucogenic amino acid. It enters carbohydrate-forming pathways by being converted into serine, which is then deaminated directly into pyruvate (an α-keto acid).\n• Methionine: This is a purely glucogenic amino acid. It is metabolized through a pathway that converts its carbon skeleton into succinyl-CoA, a citric acid cycle intermediate that ultimately yields oxaloacetate to fuel glucose production.","whyWrongChoices":"Alternative options: glycine, cysteine, methionine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the largest single contributor to the body’s energy needs accounting for 60%-80% of its total need for calories.:::basal metabolism', 'it is the largest single contributor to the body’s energy needs accounting for 60%-80% of its total need for calories.', 'basal metabolism', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Basal metabolism, or Basal Metabolic Rate (BMR), represents the baseline energy expended by the body at complete rest in a post-absorptive state. It is dedicated purely to maintaining life-sustaining vegetative functions—such as cellular respiration, heartbeat, brain activity, and body temperature regulation. In textbook nutrition frameworks, it serves as the largest single contributor to Total Energy Expenditure (TEE), typically accounting for 60% to 80% of daily calorie needs depending on an individual''s lean body mass.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"basal metabolism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Basal metabolism, or Basal Metabolic Rate (BMR), represents the baseline energy expended by the body at complete rest in a post-absorptive state. It is dedicated purely to maintaining life-sustaining vegetative functions—such as cellular respiration, heartbeat, brain activity, and body temperature regulation. In textbook nutrition frameworks, it serves as the largest single contributor to Total Energy Expenditure (TEE), typically accounting for 60% to 80% of daily calorie needs depending on an individual''s lean body mass.\n\n• Thermic Effect of Food: This component represents the temporary increase in energy expenditure associated with digesting, absorbing, and storing nutrients from food. It accounts for only about 5% to 10% of total energy requirements.\n• Adaptive Thermogenesis: This is the change in energy expenditure in response to environmental fluctuations (like extreme cold stress) or chronic overfeeding/underfeeding. It represents an auxiliary survival adjustment and constitutes a minor, highly variable percentage of daily needs.\n• Physical Activity: This comprises the energy expended during voluntary muscle movement and exercise. While it is the most variable and changeable component of a person''s daily energy expenditure, it typically contributes only 15% to 30% of total calories in most normal-living adults.","whyWrongChoices":"Alternative options: physical activity, thermic effect of food, adaptive thermogenesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the largest single contributor to the body’s energy needs accounting for 60%-80% of its total need for calories.:::', 'it is the largest single contributor to the body’s energy needs accounting for 60%-80% of its total need for calories.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Basal metabolism, or Basal Metabolic Rate (BMR), represents the baseline energy expended by the body at complete rest in a post-absorptive state. It is dedicated purely to maintaining life-sustaining vegetative functions—such as cellular respiration, heartbeat, brain activity, and body temperature regulation. In textbook nutrition frameworks, it serves as the largest single contributor to Total Energy Expenditure (TEE), typically accounting for 60% to 80% of daily calorie needs depending on an individual''s lean body mass.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"basal metabolism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Basal metabolism, or Basal Metabolic Rate (BMR), represents the baseline energy expended by the body at complete rest in a post-absorptive state. It is dedicated purely to maintaining life-sustaining vegetative functions—such as cellular respiration, heartbeat, brain activity, and body temperature regulation. In textbook nutrition frameworks, it serves as the largest single contributor to Total Energy Expenditure (TEE), typically accounting for 60% to 80% of daily calorie needs depending on an individual''s lean body mass.\n\n• Thermic Effect of Food: This component represents the temporary increase in energy expenditure associated with digesting, absorbing, and storing nutrients from food. It accounts for only about 5% to 10% of total energy requirements.\n• Adaptive Thermogenesis: This is the change in energy expenditure in response to environmental fluctuations (like extreme cold stress) or chronic overfeeding/underfeeding. It represents an auxiliary survival adjustment and constitutes a minor, highly variable percentage of daily needs.\n• Physical Activity: This comprises the energy expended during voluntary muscle movement and exercise. While it is the most variable and changeable component of a person''s daily energy expenditure, it typically contributes only 15% to 30% of total calories in most normal-living adults.","whyWrongChoices":"Alternative options: physical activity, thermic effect of food, adaptive thermogenesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the krebs cycle is oxygen-requiring and takes place in the::::mitochondria', 'the krebs cycle is oxygen-requiring and takes place in the:', 'mitochondria', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Krebs cycle (also known as the citric acid cycle or TCA cycle) takes place exclusively within the matrix of the mitochondria. This is because all the specific enzymes, coenzymes, and transport proteins required for the cycle are housed inside the mitochondrial membranes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"mitochondria\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Krebs cycle (also known as the citric acid cycle or TCA cycle) takes place exclusively within the matrix of the mitochondria. This is because all the specific enzymes, coenzymes, and transport proteins required for the cycle are housed inside the mitochondrial membranes.\n\nAlthough the chemical steps of the Krebs cycle do not directly use oxygen gas (O₂), the cycle is considered aerobic (oxygen-requiring). It cannot run without oxygen because it relies on the electron transport chain (which requires oxygen as the final electron acceptor) to regenerate its essential starting coenzymes, NAD⁺ and FAD.","whyWrongChoices":"Alternative options: liver, muscle cells, nucleus"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the krebs cycle is oxygen-requiring and takes place in the::::', 'the krebs cycle is oxygen-requiring and takes place in the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Krebs cycle (also known as the citric acid cycle or TCA cycle) takes place exclusively within the matrix of the mitochondria. This is because all the specific enzymes, coenzymes, and transport proteins required for the cycle are housed inside the mitochondrial membranes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"mitochondria\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Krebs cycle (also known as the citric acid cycle or TCA cycle) takes place exclusively within the matrix of the mitochondria. This is because all the specific enzymes, coenzymes, and transport proteins required for the cycle are housed inside the mitochondrial membranes.\n\nAlthough the chemical steps of the Krebs cycle do not directly use oxygen gas (O₂), the cycle is considered aerobic (oxygen-requiring). It cannot run without oxygen because it relies on the electron transport chain (which requires oxygen as the final electron acceptor) to regenerate its essential starting coenzymes, NAD⁺ and FAD.","whyWrongChoices":"Alternative options: liver, muscle cells, nucleus"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an adult with a usual body weight of 56kg will have fluid needs of about::::2000ml', 'an adult with a usual body weight of 56kg will have fluid needs of about:', '2000ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2000ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation:\n\nTo calculate standard adult daily fluid maintenance needs, clinicians use the standard weight-based guideline of 35 ml per kg of body weight for healthy adults:\n\n1. Multiply the individual''s usual body weight by the fluid factor:\n56 kg x 35 ml/kg = 1960 ml\n\n2. Match to the closest multiple choice selection:\n1960 ml rounds directly up to 2000 ml.","whyWrongChoices":"Alternative options: 1500ml, 2500ml, 3000ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:peak bone mass refers to the highest bone density achieved by an individual which usually occurs at the age of .:::', 'peak bone mass refers to the highest bone density achieved by an individual which usually occurs at the age of .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• During childhood and adolescence, the body builds new bone faster than it breaks down old bone, causing bone mass to increase rapidly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"30\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• During childhood and adolescence, the body builds new bone faster than it breaks down old bone, causing bone mass to increase rapidly.\n• Most people reach their peak bone mass—the maximum strength, density, and thickness their bones will ever achieve—by their late 20s or around age 30.\n• After age 30, the remodeling balance shifts. The body begins to resorb (break down) bone slightly faster than it replaces it, leading to a gradual, lifelong loss of bone density.","whyWrongChoices":"Alternative options: 20, 40, 50"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:both soluble, more fermentable fiber and insoluble, less fermentable fiber have this common action in the body::::they increase satiety or feeling of fullness', 'both soluble, more fermentable fiber and insoluble, less fermentable fiber have this common action in the body:', 'they increase satiety or feeling of fullness', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both types of dietary fiber contribute to satiety (the feeling of being full after eating) through different physical mechanisms:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"they increase satiety or feeling of fullness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both types of dietary fiber contribute to satiety (the feeling of being full after eating) through different physical mechanisms:\n• Soluble Fiber: Absorbs water to form a thick, gel-like substance. This significantly slows down stomach emptying (gastric emptying), keeping you physically full for a longer duration.\n• Insoluble Fiber: Does not dissolve in water. Instead, it acts as structural \"roughage\" that adds physical bulk and weight to the food matrix inside your digestive tract. This bulk physically stretches the stomach and intestinal walls, triggering nerve receptors that signal to your brain that you are full.","whyWrongChoices":"Alternative options: they lower blood cholesterol, they slow down the absorption of glucose, they speed up transit time through intestines"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:both soluble, more fermentable fiber and insoluble, less fermentable fiber have this common action in the body::::', 'both soluble, more fermentable fiber and insoluble, less fermentable fiber have this common action in the body:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both types of dietary fiber contribute to satiety (the feeling of being full after eating) through different physical mechanisms:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"they increase satiety or feeling of fullness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both types of dietary fiber contribute to satiety (the feeling of being full after eating) through different physical mechanisms:\n• Soluble Fiber: Absorbs water to form a thick, gel-like substance. This significantly slows down stomach emptying (gastric emptying), keeping you physically full for a longer duration.\n• Insoluble Fiber: Does not dissolve in water. Instead, it acts as structural \"roughage\" that adds physical bulk and weight to the food matrix inside your digestive tract. This bulk physically stretches the stomach and intestinal walls, triggering nerve receptors that signal to your brain that you are full.","whyWrongChoices":"Alternative options: they lower blood cholesterol, they slow down the absorption of glucose, they speed up transit time through intestines"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the percentage of nitrogen absorbed from dietary protein by the body is known as::::biological value', 'the percentage of nitrogen absorbed from dietary protein by the body is known as:', 'biological value', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biological Value (BV) measures protein quality by calculating the amount of nitrogen retained for tissue growth and maintenance divided by the total nitrogen absorbed from the diet. The formula is:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biological value\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biological Value (BV) measures protein quality by calculating the amount of nitrogen retained for tissue growth and maintenance divided by the total nitrogen absorbed from the diet. The formula is:\n\nBV = (Nitrogen Retained / Nitrogen Absorbed) x 100\n\nBecause it evaluates the percentage of nitrogen utilized after it has already been successfully absorbed across the intestinal wall, it tracks how perfectly a protein''s amino acid profile matches human tissue needs.\n\n\t• Net Protein Utilization - NPU: This measures the percentage of nitrogen retained out of the total nitrogen ingested (intake) rather than absorbed. It combines both digestibility and biological value into one score.\n\t• Protein Efficiency Ratio - PER: This measures the weight gain of a growing subject per gram of protein consumed, typically tested on laboratory rats.\n\t• Amino Acid Score: This is a chemical score calculated in a lab by comparing a food’s essential amino acid levels against a standard reference protein profile, completely independent of biological absorption measurements.","whyWrongChoices":"Alternative options: net protein utilization, protein efficiency ratio, amino acid score"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the percentage of nitrogen absorbed from dietary protein by the body is known as::::', 'the percentage of nitrogen absorbed from dietary protein by the body is known as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biological Value (BV) measures protein quality by calculating the amount of nitrogen retained for tissue growth and maintenance divided by the total nitrogen absorbed from the diet. The formula is:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biological value\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biological Value (BV) measures protein quality by calculating the amount of nitrogen retained for tissue growth and maintenance divided by the total nitrogen absorbed from the diet. The formula is:\n\nBV = (Nitrogen Retained / Nitrogen Absorbed) x 100\n\nBecause it evaluates the percentage of nitrogen utilized after it has already been successfully absorbed across the intestinal wall, it tracks how perfectly a protein''s amino acid profile matches human tissue needs.\n\n\t• Net Protein Utilization - NPU: This measures the percentage of nitrogen retained out of the total nitrogen ingested (intake) rather than absorbed. It combines both digestibility and biological value into one score.\n\t• Protein Efficiency Ratio - PER: This measures the weight gain of a growing subject per gram of protein consumed, typically tested on laboratory rats.\n\t• Amino Acid Score: This is a chemical score calculated in a lab by comparing a food’s essential amino acid levels against a standard reference protein profile, completely independent of biological absorption measurements.","whyWrongChoices":"Alternative options: net protein utilization, protein efficiency ratio, amino acid score"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient has adapted to starvation because::::urinary n excretion is low', 'a patient has adapted to starvation because:', 'urinary N excretion is low', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the initial days of fasting, the body breaks down muscle tissue (protein catabolism) to extract amino acids for gluconeogenesis. This results in a high amount of nitrogen being excreted in the urine as urea.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"urinary N excretion is low\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the initial days of fasting, the body breaks down muscle tissue (protein catabolism) to extract amino acids for gluconeogenesis. This results in a high amount of nitrogen being excreted in the urine as urea.\n\nAs starvation becomes prolonged, the body undergoes a \"protein-sparing\" metabolic adaptation. The brain and other vital organs switch their primary fuel source from glucose to ketone bodies derived from fat stores.\n\nBecause the body no longer needs to aggressively break down muscle protein to make glucose, urinary nitrogen (N) excretion drops significantly, serving as the classic clinical marker that a patient has successfully adapted to starvation.","whyWrongChoices":"Alternative options: his weight loss is associated with sepsis, he has low blood ketones, temperature is 103F rectally"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient has adapted to starvation because::::', 'a patient has adapted to starvation because:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the initial days of fasting, the body breaks down muscle tissue (protein catabolism) to extract amino acids for gluconeogenesis. This results in a high amount of nitrogen being excreted in the urine as urea.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"urinary N excretion is low\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the initial days of fasting, the body breaks down muscle tissue (protein catabolism) to extract amino acids for gluconeogenesis. This results in a high amount of nitrogen being excreted in the urine as urea.\n\nAs starvation becomes prolonged, the body undergoes a \"protein-sparing\" metabolic adaptation. The brain and other vital organs switch their primary fuel source from glucose to ketone bodies derived from fat stores.\n\nBecause the body no longer needs to aggressively break down muscle protein to make glucose, urinary nitrogen (N) excretion drops significantly, serving as the classic clinical marker that a patient has successfully adapted to starvation.","whyWrongChoices":"Alternative options: his weight loss is associated with sepsis, he has low blood ketones, temperature is 103F rectally"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is not considered a complementary protein meal?:::bread with jam', 'which is not considered a complementary protein meal?', 'bread with jam', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The goal of complementary proteins is to pair foods containing incomplete proteins so that they compensate for each other''s lacking essential amino acids, ultimately providing a complete amino acid profile.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bread with jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The goal of complementary proteins is to pair foods containing incomplete proteins so that they compensate for each other''s lacking essential amino acids, ultimately providing a complete amino acid profile.\n\nWhile bread (a grain) contains a small amount of incomplete protein, jam contains virtually zero protein (it is almost entirely simple sugars and carbohydrates). Because jam has no amino acids to contribute, it cannot complement the protein in the bread.","whyWrongChoices":"Alternative options: rice & monggo, macaroni with cheese, pizza with salami"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is not considered a complementary protein meal?:::', 'which is not considered a complementary protein meal?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The goal of complementary proteins is to pair foods containing incomplete proteins so that they compensate for each other''s lacking essential amino acids, ultimately providing a complete amino acid profile.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bread with jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The goal of complementary proteins is to pair foods containing incomplete proteins so that they compensate for each other''s lacking essential amino acids, ultimately providing a complete amino acid profile.\n\nWhile bread (a grain) contains a small amount of incomplete protein, jam contains virtually zero protein (it is almost entirely simple sugars and carbohydrates). Because jam has no amino acids to contribute, it cannot complement the protein in the bread.","whyWrongChoices":"Alternative options: rice & monggo, macaroni with cheese, pizza with salami"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:amino acid supplements taken in excess can lead to::::loss of urinary ca', 'amino acid supplements taken in excess can lead to:', 'loss of urinary Ca', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When amino acid supplements or proteins are consumed in large excess, the body metabolizes them, breaking down sulfur-containing amino acids (like cysteine and methionine). This creates an acidic load (sulfate ions and hydrogen ions) in the bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"loss of urinary Ca\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When amino acid supplements or proteins are consumed in large excess, the body metabolizes them, breaking down sulfur-containing amino acids (like cysteine and methionine). This creates an acidic load (sulfate ions and hydrogen ions) in the bloodstream.\n\nTo neutralize and excrete this mild metabolic acidosis, the kidneys alter how they handle minerals. The higher acid load and increased glomerular filtration rate (GFR) directly impair the renal tubules from reabsorbing calcium, causing the body to spill out and lose high levels of calcium in the urine (hypercalciuria).","whyWrongChoices":"Alternative options: K retention, loss of Fe, vitamin deficiencies"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:amino acid supplements taken in excess can lead to::::', 'amino acid supplements taken in excess can lead to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When amino acid supplements or proteins are consumed in large excess, the body metabolizes them, breaking down sulfur-containing amino acids (like cysteine and methionine). This creates an acidic load (sulfate ions and hydrogen ions) in the bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"loss of urinary Ca\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When amino acid supplements or proteins are consumed in large excess, the body metabolizes them, breaking down sulfur-containing amino acids (like cysteine and methionine). This creates an acidic load (sulfate ions and hydrogen ions) in the bloodstream.\n\nTo neutralize and excrete this mild metabolic acidosis, the kidneys alter how they handle minerals. The higher acid load and increased glomerular filtration rate (GFR) directly impair the renal tubules from reabsorbing calcium, causing the body to spill out and lose high levels of calcium in the urine (hypercalciuria).","whyWrongChoices":"Alternative options: K retention, loss of Fe, vitamin deficiencies"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 15-year old insulin dependent diabetic girl is admitted in the hospital due to hyperglycemia. an appropriate nutrition education plan should begin with::::a review of the relationship between blood glucose levels and intake of simple sugars', 'a 15-year old insulin dependent diabetic girl is admitted in the hospital due to hyperglycemia. an appropriate nutrition education plan should begin with:', 'a review of the relationship between blood glucose levels and intake of simple sugars', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a pediatric patient is acutely admitted for a crisis like hyperglycemia, nutrition education must begin with simple, high-yield, and immediate cause-and-effect relationships. Reviewing how simple sugars directly spike blood glucose levels provides the teen with immediate, understandable insight into her current clinical crisis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"a review of the relationship between blood glucose levels and intake of simple sugars\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a pediatric patient is acutely admitted for a crisis like hyperglycemia, nutrition education must begin with simple, high-yield, and immediate cause-and-effect relationships. Reviewing how simple sugars directly spike blood glucose levels provides the teen with immediate, understandable insight into her current clinical crisis.","whyWrongChoices":"Alternative options: a printed material that discusses the pathophysiology of diabetes, a detailed explanation of the exchange list and how to use it in meal planning, a quiz to evaluate the patient’s knowledge of diet and diabetes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 15-year old insulin dependent diabetic girl is admitted in the hospital due to hyperglycemia. an appropriate nutrition education plan should begin with::::', 'a 15-year old insulin dependent diabetic girl is admitted in the hospital due to hyperglycemia. an appropriate nutrition education plan should begin with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a pediatric patient is acutely admitted for a crisis like hyperglycemia, nutrition education must begin with simple, high-yield, and immediate cause-and-effect relationships. Reviewing how simple sugars directly spike blood glucose levels provides the teen with immediate, understandable insight into her current clinical crisis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"a review of the relationship between blood glucose levels and intake of simple sugars\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a pediatric patient is acutely admitted for a crisis like hyperglycemia, nutrition education must begin with simple, high-yield, and immediate cause-and-effect relationships. Reviewing how simple sugars directly spike blood glucose levels provides the teen with immediate, understandable insight into her current clinical crisis.","whyWrongChoices":"Alternative options: a printed material that discusses the pathophysiology of diabetes, a detailed explanation of the exchange list and how to use it in meal planning, a quiz to evaluate the patient’s knowledge of diet and diabetes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an adult with a usual body weight of 56kg will have fluid needs of about::::', 'an adult with a usual body weight of 56kg will have fluid needs of about:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2000ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation:\n\nTo calculate standard adult daily fluid maintenance needs, clinicians use the standard weight-based guideline of 35 ml per kg of body weight for healthy adults:\n\n1. Multiply the individual''s usual body weight by the fluid factor:\n56 kg x 35 ml/kg = 1960 ml\n\n2. Match to the closest multiple choice selection:\n1960 ml rounds directly up to 2000 ml.","whyWrongChoices":"Alternative options: 1500ml, 2500ml, 3000ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how much carbohydrates would be contained in a 2000 ml tube feeding formula with a calorie density of 1.5 kcal/ml, 63% of which are from carbohydrates?:::470g', 'how much carbohydrates would be contained in a 2000 ml tube feeding formula with a calorie density of 1.5 kcal/ml, 63% of which are from carbohydrates?', '470g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"First, calculate the total calories in the formula: 2000 ml multiplied by 1.5 kcal/ml equals 3000 total kcal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"470g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"First, calculate the total calories in the formula: 2000 ml multiplied by 1.5 kcal/ml equals 3000 total kcal.\n\nNext, find the calories coming from carbohydrates: 3000 total kcal multiplied by 63 percent (0.63) equals 1890 kcal from carbohydrates.\n\nFinally, convert the carbohydrate calories into grams (since 1 gram of carbohydrate provides 4 kcal): 1890 kcal divided by 4 kcal per gram equals 472.5 grams.","whyWrongChoices":"Alternative options: 315g, 483g, 396g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how much carbohydrates would be contained in a 2000 ml tube feeding formula with a calorie density of 1.5 kcal/ml, 63% of which are from carbohydrates?:::', 'how much carbohydrates would be contained in a 2000 ml tube feeding formula with a calorie density of 1.5 kcal/ml, 63% of which are from carbohydrates?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"First, calculate the total calories in the formula: 2000 ml multiplied by 1.5 kcal/ml equals 3000 total kcal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"470g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"First, calculate the total calories in the formula: 2000 ml multiplied by 1.5 kcal/ml equals 3000 total kcal.\n\nNext, find the calories coming from carbohydrates: 3000 total kcal multiplied by 63 percent (0.63) equals 1890 kcal from carbohydrates.\n\nFinally, convert the carbohydrate calories into grams (since 1 gram of carbohydrate provides 4 kcal): 1890 kcal divided by 4 kcal per gram equals 472.5 grams.","whyWrongChoices":"Alternative options: 315g, 483g, 396g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a gradual transition from an iv feeding to an oral diet is primarily designed to::::ensure that nutrient needs will continue to be met', 'a gradual transition from an iv feeding to an oral diet is primarily designed to:', 'ensure that nutrient needs will continue to be met', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The primary goal of a gradual transition (often called a \"transitional feed\") from intravenous (IV) nutrition to an oral diet is to ensure nutritional adequacy and patient safety. When a patient has been on IV nutrition, their gastrointestinal tract may have reduced capacity to absorb nutrients right away. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ensure that nutrient needs will continue to be met\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The primary goal of a gradual transition (often called a \"transitional feed\") from intravenous (IV) nutrition to an oral diet is to ensure nutritional adequacy and patient safety. When a patient has been on IV nutrition, their gastrointestinal tract may have reduced capacity to absorb nutrients right away. \n\nBy slowly tapering off the IV fluids while introducing oral foods, clinicians can track oral intake, verify that the gut is tolerating and absorbing the food properly, and ensure that the patient does not experience nutritional deficits during the switch.","whyWrongChoices":"Alternative options: improve the appetite, prevent hypoglycemia, prevent apprehension about eating"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a gradual transition from an iv feeding to an oral diet is primarily designed to::::', 'a gradual transition from an iv feeding to an oral diet is primarily designed to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The primary goal of a gradual transition (often called a \"transitional feed\") from intravenous (IV) nutrition to an oral diet is to ensure nutritional adequacy and patient safety. When a patient has been on IV nutrition, their gastrointestinal tract may have reduced capacity to absorb nutrients right away. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ensure that nutrient needs will continue to be met\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The primary goal of a gradual transition (often called a \"transitional feed\") from intravenous (IV) nutrition to an oral diet is to ensure nutritional adequacy and patient safety. When a patient has been on IV nutrition, their gastrointestinal tract may have reduced capacity to absorb nutrients right away. \n\nBy slowly tapering off the IV fluids while introducing oral foods, clinicians can track oral intake, verify that the gut is tolerating and absorbing the food properly, and ensure that the patient does not experience nutritional deficits during the switch.","whyWrongChoices":"Alternative options: improve the appetite, prevent hypoglycemia, prevent apprehension about eating"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following can be delivered intravenously except::::hydrolyzed enteral formulas', 'all of the following can be delivered intravenously except:', 'hydrolyzed enteral formulas', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral formulas—including hydrolyzed or elemental formulas—are strictly designed to be processed through the gastrointestinal tract via oral ingestion or a feeding tube (such as an NG tube, G-tube, or J-tube).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"hydrolyzed enteral formulas\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral formulas—including hydrolyzed or elemental formulas—are strictly designed to be processed through the gastrointestinal tract via oral ingestion or a feeding tube (such as an NG tube, G-tube, or J-tube).\n\nEven though these formulas are \"pre-digested\" into smaller parts for patients with impaired gut absorption, they contain intact particles, fiber residues, and non-sterile compounds that are highly dangerous if introduced directly into the bloodstream. Delivering an enteral formula intravenously can cause catastrophic blood clots, septic shock, or fatal embolisms.","whyWrongChoices":"Alternative options: carbohydrate, amino acids, dextrose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following can be delivered intravenously except::::', 'all of the following can be delivered intravenously except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral formulas—including hydrolyzed or elemental formulas—are strictly designed to be processed through the gastrointestinal tract via oral ingestion or a feeding tube (such as an NG tube, G-tube, or J-tube).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"hydrolyzed enteral formulas\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral formulas—including hydrolyzed or elemental formulas—are strictly designed to be processed through the gastrointestinal tract via oral ingestion or a feeding tube (such as an NG tube, G-tube, or J-tube).\n\nEven though these formulas are \"pre-digested\" into smaller parts for patients with impaired gut absorption, they contain intact particles, fiber residues, and non-sterile compounds that are highly dangerous if introduced directly into the bloodstream. Delivering an enteral formula intravenously can cause catastrophic blood clots, septic shock, or fatal embolisms.","whyWrongChoices":"Alternative options: carbohydrate, amino acids, dextrose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a gluten-free diet excludes::::wheat, barley, rye, and oats', 'a gluten-free diet excludes:', 'wheat, barley, rye, and oats', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A strict gluten-free diet permanently eliminates grains containing the protein gluten (and its toxic prolamin fractions: gliadin in wheat, secalin in rye, and hordein in barley). These cause severe small intestinal mucosal damage in individuals with celiac disease or gluten intolerance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"wheat, barley, rye, and oats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A strict gluten-free diet permanently eliminates grains containing the protein gluten (and its toxic prolamin fractions: gliadin in wheat, secalin in rye, and hordein in barley). These cause severe small intestinal mucosal damage in individuals with celiac disease or gluten intolerance.\n\nIn classic nursing, nutrition, and board exam question banks (such as the Philippine Food Exchange List frameworks), oats are historically grouped alongside wheat, barley, and rye as prohibited foods. This is due to a high risk of cross-contamination during harvesting and processing, as well as the presence of avenin (a protein in oats similar to gluten that some sensitive individuals react to).","whyWrongChoices":"Alternative options: wheat, corn, and oats, barely, soybeans, oats, and corn, wheat, barley, rice, and oats"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a gluten-free diet excludes::::', 'a gluten-free diet excludes:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A strict gluten-free diet permanently eliminates grains containing the protein gluten (and its toxic prolamin fractions: gliadin in wheat, secalin in rye, and hordein in barley). These cause severe small intestinal mucosal damage in individuals with celiac disease or gluten intolerance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"wheat, barley, rye, and oats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A strict gluten-free diet permanently eliminates grains containing the protein gluten (and its toxic prolamin fractions: gliadin in wheat, secalin in rye, and hordein in barley). These cause severe small intestinal mucosal damage in individuals with celiac disease or gluten intolerance.\n\nIn classic nursing, nutrition, and board exam question banks (such as the Philippine Food Exchange List frameworks), oats are historically grouped alongside wheat, barley, and rye as prohibited foods. This is due to a high risk of cross-contamination during harvesting and processing, as well as the presence of avenin (a protein in oats similar to gluten that some sensitive individuals react to).","whyWrongChoices":"Alternative options: wheat, corn, and oats, barely, soybeans, oats, and corn, wheat, barley, rice, and oats"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a soft diet for a patient with indigestion would include the following except::::use foods that are chopped or pureed', 'a soft diet for a patient with indigestion would include the following except:', 'use foods that are chopped or pureed', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A standard gastrointestinal soft diet (often called a bland or low-residue diet) is modified in chemical composition and digestibility rather than mechanical texture. It aims to ease abdominal distress, bloating, and irritation caused by indigestion (dyspepsia).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"use foods that are chopped or pureed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A standard gastrointestinal soft diet (often called a bland or low-residue diet) is modified in chemical composition and digestibility rather than mechanical texture. It aims to ease abdominal distress, bloating, and irritation caused by indigestion (dyspepsia).\n\nMechanically altering foods by chopping, grinding, or pureeing is a requirement of a Mechanical Soft Diet or Pureed Diet, which is prescribed for patients with chewing or swallowing difficulties (such as poor dentition, dysphagia, or mouth surgery). A patient suffering from basic indigestion can chew normally; therefore, chopping or pureeing food is completely unnecessary.","whyWrongChoices":"Alternative options: limit highly seasoned foods, limit foods that produce gas, limit high-fiber foods"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the following information: a 25-year old female office clerk consulted at an out-patient clinic for dizziness and headache. she is 5’4” and weighs 70 kg. her bp is 150/80 mmhg. this is her first consultation. which of the following foods would you recommend?:::rice, pan de sal, camote tops, fish', 'refer to the following information: a 25-year old female office clerk consulted at an out-patient clinic for dizziness and headache. she is 5’4” and weighs 70 kg. her bp is 150/80 mmhg. this is her first consultation. which of the following foods would you recommend?', 'rice, pan de sal, camote tops, fish', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The patient’s blood pressure is 150/80 mmHg, which classifies as Stage 2 Hypertension (specifically elevated systolic pressure). A primary nutritional intervention for managing high blood pressure is a low-sodium, heart-healthy diet rich in potassium and fiber (similar to the DASH diet approach).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"rice, pan de sal, camote tops, fish\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The patient’s blood pressure is 150/80 mmHg, which classifies as Stage 2 Hypertension (specifically elevated systolic pressure). A primary nutritional intervention for managing high blood pressure is a low-sodium, heart-healthy diet rich in potassium and fiber (similar to the DASH diet approach).\n\t• Fresh Fish: Provides a lean, high-quality source of protein that is naturally low in sodium and rich in heart-healthy omega-3 fatty acids.\n\t• Camote Tops (Sweet Potato Leaves): A local powerhouse vegetable that is highly concentrated in potassium. Potassium actively works to lower blood pressure by helping the kidneys excrete excess sodium and relaxing blood vessel walls.\n\t• Rice & Pan de Sal: Serve as staple carbohydrates. While traditional pan de sal contains a small amount of salt, the meal as a whole is overwhelmingly comprised of fresh, unprocessed items.\n\nThe remaining options contain heavily processed, canned, or cured foods (ham, corned beef, pork and beans) that are loaded with hidden sodium, which can acutely worsen hypertension by causing fluid retention and increasing blood vessel pressure:","whyWrongChoices":"Alternative options: pan de sal, rice, cottage cheese, corned beef, ampalaya, pork and beans, carrots, banana, rice, milk, ham, eggs, rice"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a soft diet for a patient with indigestion would include the following except::::', 'a soft diet for a patient with indigestion would include the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A standard gastrointestinal soft diet (often called a bland or low-residue diet) is modified in chemical composition and digestibility rather than mechanical texture. It aims to ease abdominal distress, bloating, and irritation caused by indigestion (dyspepsia).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"use foods that are chopped or pureed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A standard gastrointestinal soft diet (often called a bland or low-residue diet) is modified in chemical composition and digestibility rather than mechanical texture. It aims to ease abdominal distress, bloating, and irritation caused by indigestion (dyspepsia).\n\nMechanically altering foods by chopping, grinding, or pureeing is a requirement of a Mechanical Soft Diet or Pureed Diet, which is prescribed for patients with chewing or swallowing difficulties (such as poor dentition, dysphagia, or mouth surgery). A patient suffering from basic indigestion can chew normally; therefore, chopping or pureeing food is completely unnecessary.","whyWrongChoices":"Alternative options: limit highly seasoned foods, limit foods that produce gas, limit high-fiber foods"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 45-year-old male with cancer of the upper gi tract is admitted for operation. due to his 15% weight loss, your first recommendation would be to::::feed him at least 10 days preoperatively', 'a 45-year-old male with cancer of the upper gi tract is admitted for operation. due to his 15% weight loss, your first recommendation would be to:', 'feed him at least 10 days preoperatively', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A 15% unintentional weight loss in a patient with upper GI tract cancer signifies severe malnutrition. Proceeding directly to major abdominal surgery in a severely malnourished patient drastically increases the risk of postoperative complications, including poor wound healing, anastomotic leaks, infections, and death.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"feed him at least 10 days preoperatively\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A 15% unintentional weight loss in a patient with upper GI tract cancer signifies severe malnutrition. Proceeding directly to major abdominal surgery in a severely malnourished patient drastically increases the risk of postoperative complications, including poor wound healing, anastomotic leaks, infections, and death.\n\nClinical guidelines dictate that patients with severe nutritional risk should receive 7 to 14 days of preoperative nutritional support (ideally via the enteral route, or parenteral if the gut is obstructed) to improve metabolic status and surgical outcomes, even if it means deliberately delaying the operation.","whyWrongChoices":"Alternative options: rush him to the OR, initiate TPN prior to surgery, advise surgeon to plan feeding jejunostomy at operation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 45-year-old male with cancer of the upper gi tract is admitted for operation. due to his 15% weight loss, your first recommendation would be to::::', 'a 45-year-old male with cancer of the upper gi tract is admitted for operation. due to his 15% weight loss, your first recommendation would be to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A 15% unintentional weight loss in a patient with upper GI tract cancer signifies severe malnutrition. Proceeding directly to major abdominal surgery in a severely malnourished patient drastically increases the risk of postoperative complications, including poor wound healing, anastomotic leaks, infections, and death.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"feed him at least 10 days preoperatively\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A 15% unintentional weight loss in a patient with upper GI tract cancer signifies severe malnutrition. Proceeding directly to major abdominal surgery in a severely malnourished patient drastically increases the risk of postoperative complications, including poor wound healing, anastomotic leaks, infections, and death.\n\nClinical guidelines dictate that patients with severe nutritional risk should receive 7 to 14 days of preoperative nutritional support (ideally via the enteral route, or parenteral if the gut is obstructed) to improve metabolic status and surgical outcomes, even if it means deliberately delaying the operation.","whyWrongChoices":"Alternative options: rush him to the OR, initiate TPN prior to surgery, advise surgeon to plan feeding jejunostomy at operation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bland diets eliminate all of the following foods except::::foods that delay gastric emptying', 'bland diets eliminate all of the following foods except:', 'foods that delay gastric emptying', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The core purpose of a bland diet is to reduce chemical and mechanical irritation to the gastrointestinal tract, decrease stomach acid secretion, and give the digestive system a rest.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"foods that delay gastric emptying\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The core purpose of a bland diet is to reduce chemical and mechanical irritation to the gastrointestinal tract, decrease stomach acid secretion, and give the digestive system a rest.\n\nFoods that delay gastric emptying (such as high-fat foods) are actually eliminated from a bland diet. High-fat items sit in the stomach longer, which stimulates prolonged gastric acid production and increases the risk of acid reflux. Therefore, a bland diet specifically incorporates easily digestible, low-fat carbohydrates and lean proteins that clear the stomach quickly rather than delaying emptying.","whyWrongChoices":"Alternative options: foods that cause indigestion, foods that irritate the lining of the esophagus and stomach, foods that significantly increase gastric acid production"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bland diets eliminate all of the following foods except::::', 'bland diets eliminate all of the following foods except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The core purpose of a bland diet is to reduce chemical and mechanical irritation to the gastrointestinal tract, decrease stomach acid secretion, and give the digestive system a rest.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"foods that delay gastric emptying\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The core purpose of a bland diet is to reduce chemical and mechanical irritation to the gastrointestinal tract, decrease stomach acid secretion, and give the digestive system a rest.\n\nFoods that delay gastric emptying (such as high-fat foods) are actually eliminated from a bland diet. High-fat items sit in the stomach longer, which stimulates prolonged gastric acid production and increases the risk of acid reflux. Therefore, a bland diet specifically incorporates easily digestible, low-fat carbohydrates and lean proteins that clear the stomach quickly rather than delaying emptying.","whyWrongChoices":"Alternative options: foods that cause indigestion, foods that irritate the lining of the esophagus and stomach, foods that significantly increase gastric acid production"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sudden tissue death caused by blockages of vessels that feed the heart muscle::::heart attack', 'sudden tissue death caused by blockages of vessels that feed the heart muscle:', 'heart attack', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The literal medical definition of myocardial infarction is tissue death (infarction) of the heart muscle (myocardio) caused by a lack of oxygen (ischemia). This occurs abruptly when a coronary vessel—one of the arteries feeding oxygen-rich blood to the heart itself—becomes completely blocked by a blood clot or ruptured plaque.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"heart attack\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The literal medical definition of myocardial infarction is tissue death (infarction) of the heart muscle (myocardio) caused by a lack of oxygen (ischemia). This occurs abruptly when a coronary vessel—one of the arteries feeding oxygen-rich blood to the heart itself—becomes completely blocked by a blood clot or ruptured plaque.\n\n• Stroke: This is sudden tissue damage or death, but it occurs in the brain, caused by a blockage or rupture of blood vessels feeding brain tissue.\n• Transient Ischemic Attack (TIA): Often called a \"mini-stroke,\" this involves a temporary blockage of blood vessels feeding the brain. Because the clot breaks apart quickly, it does not cause permanent tissue death.","whyWrongChoices":"Alternative options: stroke, transient ischemic attack, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sudden tissue death caused by blockages of vessels that feed the heart muscle::::', 'sudden tissue death caused by blockages of vessels that feed the heart muscle:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The literal medical definition of myocardial infarction is tissue death (infarction) of the heart muscle (myocardio) caused by a lack of oxygen (ischemia). This occurs abruptly when a coronary vessel—one of the arteries feeding oxygen-rich blood to the heart itself—becomes completely blocked by a blood clot or ruptured plaque.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"heart attack\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The literal medical definition of myocardial infarction is tissue death (infarction) of the heart muscle (myocardio) caused by a lack of oxygen (ischemia). This occurs abruptly when a coronary vessel—one of the arteries feeding oxygen-rich blood to the heart itself—becomes completely blocked by a blood clot or ruptured plaque.\n\n• Stroke: This is sudden tissue damage or death, but it occurs in the brain, caused by a blockage or rupture of blood vessels feeding brain tissue.\n• Transient Ischemic Attack (TIA): Often called a \"mini-stroke,\" this involves a temporary blockage of blood vessels feeding the brain. Because the clot breaks apart quickly, it does not cause permanent tissue death.","whyWrongChoices":"Alternative options: stroke, transient ischemic attack, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:using the npc method, compute for the cho and fat of a diet prescription with 2000kcal, p55g.:::c265g, f80g', 'using the npc method, compute for the cho and fat of a diet prescription with 2000kcal, p55g.', 'C265g, F80g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Breakdown using the Non-Protein Calorie (NPC) Method","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"C265g, F80g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Breakdown using the Non-Protein Calorie (NPC) Method\n\nTo calculate the carbohydrate (CHO) and fat allocation for this diet prescription, we follow the standard percentage distribution of non-protein calories (using a standard 60% CHO and 40% Fat split for the remaining energy):\n\n1. Calculate Protein Calories:\n\t• Protein allowance = 55g\n\t• Energy value of protein = 4 kcal/g\n\t• Protein Calories: 55g * 4 kcal = 220 kcal\n\n2. Calculate Total Non-Protein Calories (NPC):\n\t• Total Energy Requirement (TER) = 2000 kcal\n\t• NPC = Total Calories - Protein Calories\n\t• NPC = 2000 kcal - 220 kcal = 1780 kcal\n\n3. Compute Carbohydrate (CHO) Grams (60% of NPC):\n\t• CHO Calories = 1780 kcal * 0.60 = 1068 kcal\n\t• Energy value of carbohydrates = 4 kcal/g\n\t• CHO Grams = 1068 kcal / 4 = 267g\n\t• Rounding off to the nearest 5 grams = 265g\n\n4. Compute Fat Grams (40% of NPC):\n\t• Fat Calories = 1780 kcal * 0.40 = 712 kcal\n\t• Energy value of fat = 9 kcal/g\n\t• Fat Grams = 712 kcal / 9 = 79.1g\n\t• Rounding off to the nearest 5 grams = 80g","whyWrongChoices":"Alternative options: C250g, F110g, C300g, F90g, C350g, F65g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it enhances iron absorption.:::', 'it enhances iron absorption.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin C facilitates iron absorption by forming a chelate with ferric iron at acid pH that remains soluble at the alkaline pH of the duodenum.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin C facilitates iron absorption by forming a chelate with ferric iron at acid pH that remains soluble at the alkaline pH of the duodenum.","whyWrongChoices":"Alternative options: Vit A, Vit B, Vit D"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deficiency of this micronutrient is associated with scurvy.:::vit c', 'deficiency of this micronutrient is associated with scurvy.', 'Vit C', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Consumption of 100 mg of Vitamin C per day can increase the total body pool to a level of 1.2-2.0 g that is sufficient to protect the body from scurvy for 90 days.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Consumption of 100 mg of Vitamin C per day can increase the total body pool to a level of 1.2-2.0 g that is sufficient to protect the body from scurvy for 90 days.","whyWrongChoices":"Alternative options: Vit A, Vit B, Vit K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:using the npc method, compute for the cho and fat of a diet prescription with 2000kcal, p55g.:::', 'using the npc method, compute for the cho and fat of a diet prescription with 2000kcal, p55g.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Breakdown using the Non-Protein Calorie (NPC) Method","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"C265g, F80g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Breakdown using the Non-Protein Calorie (NPC) Method\n\nTo calculate the carbohydrate (CHO) and fat allocation for this diet prescription, we follow the standard percentage distribution of non-protein calories (using a standard 60% CHO and 40% Fat split for the remaining energy):\n\n1. Calculate Protein Calories:\n\t• Protein allowance = 55g\n\t• Energy value of protein = 4 kcal/g\n\t• Protein Calories: 55g * 4 kcal = 220 kcal\n\n2. Calculate Total Non-Protein Calories (NPC):\n\t• Total Energy Requirement (TER) = 2000 kcal\n\t• NPC = Total Calories - Protein Calories\n\t• NPC = 2000 kcal - 220 kcal = 1780 kcal\n\n3. Compute Carbohydrate (CHO) Grams (60% of NPC):\n\t• CHO Calories = 1780 kcal * 0.60 = 1068 kcal\n\t• Energy value of carbohydrates = 4 kcal/g\n\t• CHO Grams = 1068 kcal / 4 = 267g\n\t• Rounding off to the nearest 5 grams = 265g\n\n4. Compute Fat Grams (40% of NPC):\n\t• Fat Calories = 1780 kcal * 0.40 = 712 kcal\n\t• Energy value of fat = 9 kcal/g\n\t• Fat Grams = 712 kcal / 9 = 79.1g\n\t• Rounding off to the nearest 5 grams = 80g","whyWrongChoices":"Alternative options: C250g, F110g, C300g, F90g, C350g, F65g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dr. cruz ordered an additional 500mg na in the diet of maria pecson. how much salt should be added to her food?:::1250mg', 'dr. cruz ordered an additional 500mg na in the diet of maria pecson. how much salt should be added to her food?', '1250mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table salt (sodium chloride) is composed of approximately 40% sodium and 60% chloride.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1250mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table salt (sodium chloride) is composed of approximately 40% sodium and 60% chloride.\n\nTo find the amount of salt needed to provide a specific amount of pure sodium, you divide the milligram amount of sodium by 0.40:\n\n500 mg of sodium divided by 0.40 = 1250 mg of salt.","whyWrongChoices":"Alternative options: 1500mg, 500mg, 1000mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dr. cruz ordered an additional 500mg na in the diet of maria pecson. how much salt should be added to her food?:::', 'dr. cruz ordered an additional 500mg na in the diet of maria pecson. how much salt should be added to her food?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table salt (sodium chloride) is composed of approximately 40% sodium and 60% chloride.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1250mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table salt (sodium chloride) is composed of approximately 40% sodium and 60% chloride.\n\nTo find the amount of salt needed to provide a specific amount of pure sodium, you divide the milligram amount of sodium by 0.40:\n\n500 mg of sodium divided by 0.40 = 1250 mg of salt.","whyWrongChoices":"Alternative options: 1500mg, 500mg, 1000mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:characteristics of type 1 diabetes::::it is associated with ketosis and acidosis.', 'characteristics of type 1 diabetes:', 'It is associated with ketosis and acidosis.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• In Type 1 diabetes, the body''s immune system destroys pancreatic beta cells, leaving the body with an absolute lack of insulin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It is associated with ketosis and acidosis.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• In Type 1 diabetes, the body''s immune system destroys pancreatic beta cells, leaving the body with an absolute lack of insulin.\n• Because the body completely lacks the insulin required to pull glucose into cells for fuel, cells are starved for energy. The body compensates by rapidly breaking down fats into free fatty acids. A byproduct of this accelerated fat metabolism is the accumulation of acidic ketone bodies in the blood, which drops the blood''s pH and leads to diabetic ketoacidosis (DKA).","whyWrongChoices":"Alternative options: It is the predominant form of diabetes., It frequently goes undiagnosed., Insulin secretion is ineffective in preventing hyperglycemia."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:characteristics of type 1 diabetes::::', 'characteristics of type 1 diabetes:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• In Type 1 diabetes, the body''s immune system destroys pancreatic beta cells, leaving the body with an absolute lack of insulin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It is associated with ketosis and acidosis.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• In Type 1 diabetes, the body''s immune system destroys pancreatic beta cells, leaving the body with an absolute lack of insulin.\n• Because the body completely lacks the insulin required to pull glucose into cells for fuel, cells are starved for energy. The body compensates by rapidly breaking down fats into free fatty acids. A byproduct of this accelerated fat metabolism is the accumulation of acidic ketone bodies in the blood, which drops the blood''s pH and leads to diabetic ketoacidosis (DKA).","whyWrongChoices":"Alternative options: It is the predominant form of diabetes., It frequently goes undiagnosed., Insulin secretion is ineffective in preventing hyperglycemia."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
