INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the following may affect the nutrient needs of people with inflammatory bowel disease except::::', 'the following may affect the nutrient needs of people with inflammatory bowel disease except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dumping syndrome is a complication that occurs after gastric surgeries (like a partial or total gastrectomy) where food moves too rapidly from the stomach into the small intestine. It does not directly result from or impact the nutrient needs of Inflammatory Bowel Disease (IBD).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"dumping syndrome\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dumping syndrome is a complication that occurs after gastric surgeries (like a partial or total gastrectomy) where food moves too rapidly from the stomach into the small intestine. It does not directly result from or impact the nutrient needs of Inflammatory Bowel Disease (IBD).\n\n\t• Medications: Common IBD drugs like corticosteroids lower calcium and vitamin D absorption, while others like sulfasalazine impair folate absorption, altering daily nutrient requirements.\n\t• Steatorrhea: Excessive fat in the stool (common in Crohn''s disease due to bile acid malabsorption) causes a severe loss of fat-soluble vitamins (A, D, E, and K) and calories, increasing nutritional requirements.\n\t• Fistulas: These abnormal tissue tunnels can leak digestive fluids, causing high-volume losses of protein, electrolytes, and fluids, which drastically spike a patient''s nutrient needs.","whyWrongChoices":"Alternative options: steatorrhea, medications, fistulas"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mr. santos has lung cancer which has metastasized to his spine. based on this information, it will be essential for the nutritionist-dietitian to monitor him for::::hypercalcemia', 'mr. santos has lung cancer which has metastasized to his spine. based on this information, it will be essential for the nutritionist-dietitian to monitor him for:', 'hypercalcemia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a primary tumor (such as lung cancer) metastasizes to the bone/spine, it initiates osteolytic bone destruction. The invading tumor cells stimulate specialized bone cells (osteoclasts) to break down the surrounding bone tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"hypercalcemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a primary tumor (such as lung cancer) metastasizes to the bone/spine, it initiates osteolytic bone destruction. The invading tumor cells stimulate specialized bone cells (osteoclasts) to break down the surrounding bone tissue.\n\nAs the bone structure is aggressively broken down and reabsorbed, massive amounts of calcium are dissolved and released directly into the bloodstream. This rapid influx overwhelms the kidneys'' ability to excrete it, leading to a dangerous oncologic emergency known as Hypercalcemia of Malignancy (HCM).\n\nMonitoring calcium levels is critical because hypercalcemia can lead to severe confusion, muscle weakness, kidney stones, and lethal cardiac arrhythmias. While dietary calcium restriction is generally not the primary treatment for HCM (as the excess calcium is coming from the bones, not food), the dietitian must aggressively monitor hydration status, fluid balance, and electrolyte trends to support clinical management.","whyWrongChoices":"Alternative options: hypokalemia, hyponatremia, hyperchloremia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mr. santos has lung cancer which has metastasized to his spine. based on this information, it will be essential for the nutritionist-dietitian to monitor him for::::', 'mr. santos has lung cancer which has metastasized to his spine. based on this information, it will be essential for the nutritionist-dietitian to monitor him for:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a primary tumor (such as lung cancer) metastasizes to the bone/spine, it initiates osteolytic bone destruction. The invading tumor cells stimulate specialized bone cells (osteoclasts) to break down the surrounding bone tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"hypercalcemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a primary tumor (such as lung cancer) metastasizes to the bone/spine, it initiates osteolytic bone destruction. The invading tumor cells stimulate specialized bone cells (osteoclasts) to break down the surrounding bone tissue.\n\nAs the bone structure is aggressively broken down and reabsorbed, massive amounts of calcium are dissolved and released directly into the bloodstream. This rapid influx overwhelms the kidneys'' ability to excrete it, leading to a dangerous oncologic emergency known as Hypercalcemia of Malignancy (HCM).\n\nMonitoring calcium levels is critical because hypercalcemia can lead to severe confusion, muscle weakness, kidney stones, and lethal cardiac arrhythmias. While dietary calcium restriction is generally not the primary treatment for HCM (as the excess calcium is coming from the bones, not food), the dietitian must aggressively monitor hydration status, fluid balance, and electrolyte trends to support clinical management.","whyWrongChoices":"Alternative options: hypokalemia, hyponatremia, hyperchloremia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet order for irritable bowel syndrome::::all of the above', 'diet order for irritable bowel syndrome:', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Irritable Bowel Syndrome (IBS) is a functional gastrointestinal disorder where dietary management focuses on controlling symptoms like cramping, bloating, gas, diarrhea, and constipation. Standard clinical diet orders traditionally incorporate all three modifications:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Irritable Bowel Syndrome (IBS) is a functional gastrointestinal disorder where dietary management focuses on controlling symptoms like cramping, bloating, gas, diarrhea, and constipation. Standard clinical diet orders traditionally incorporate all three modifications:\n\n• High-fiber: Gradually increasing dietary fiber (specifically soluble fiber like psyllium, oats, and flaxseeds) is a primary recommendation. It adds healthy bulk to stools to relieve constipation (IBS-C) while simultaneously helping to solidify loose stools in diarrhea-predominant IBS (IBS-D).\n• Avoid highly seasoned foods: Spicy and heavily seasoned foods contain compounds (like capsaicin) that irritate the gut lining and accelerate GI transit. Eliminating them helps reduce abdominal pain, cramping, and sudden bowel urgency.\n• Fat-restricted: High-fat, greasy, and deep-fried foods trigger an exaggerated gastrocolic reflex, which causes rapid, painful colonic contractions. Restricting dietary fat intake stabilizes gut motility and prevents immediate post-meal cramping and diarrhea.","whyWrongChoices":"Alternative options: avoid highly seasoned foods, high-fiber, fat-restricted"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet order for irritable bowel syndrome::::', 'diet order for irritable bowel syndrome:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Irritable Bowel Syndrome (IBS) is a functional gastrointestinal disorder where dietary management focuses on controlling symptoms like cramping, bloating, gas, diarrhea, and constipation. Standard clinical diet orders traditionally incorporate all three modifications:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Irritable Bowel Syndrome (IBS) is a functional gastrointestinal disorder where dietary management focuses on controlling symptoms like cramping, bloating, gas, diarrhea, and constipation. Standard clinical diet orders traditionally incorporate all three modifications:\n\n• High-fiber: Gradually increasing dietary fiber (specifically soluble fiber like psyllium, oats, and flaxseeds) is a primary recommendation. It adds healthy bulk to stools to relieve constipation (IBS-C) while simultaneously helping to solidify loose stools in diarrhea-predominant IBS (IBS-D).\n• Avoid highly seasoned foods: Spicy and heavily seasoned foods contain compounds (like capsaicin) that irritate the gut lining and accelerate GI transit. Eliminating them helps reduce abdominal pain, cramping, and sudden bowel urgency.\n• Fat-restricted: High-fat, greasy, and deep-fried foods trigger an exaggerated gastrocolic reflex, which causes rapid, painful colonic contractions. Restricting dietary fat intake stabilizes gut motility and prevents immediate post-meal cramping and diarrhea.","whyWrongChoices":"Alternative options: avoid highly seasoned foods, high-fiber, fat-restricted"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a person who has done well for 3 years following a gastrectomy should be alert to signs of::::vitamin b₁₂ deficiency', 'a person who has done well for 3 years following a gastrectomy should be alert to signs of:', 'vitamin B₁₂ deficiency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The human liver stores a substantial reserve of Vitamin B₁₂ (cobalamin), which typically lasts 3 to 5 years. Once these internal stores are fully exhausted, symptoms of deficiency begin to appear.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vitamin B₁₂ deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The human liver stores a substantial reserve of Vitamin B₁₂ (cobalamin), which typically lasts 3 to 5 years. Once these internal stores are fully exhausted, symptoms of deficiency begin to appear.\n\nA gastrectomy removes the parietal cells of the stomach, which are responsible for secreting intrinsic factor. Intrinsic factor is a protein absolutely required for Vitamin B₁₂ absorption in the ileum. Without it, the body cannot absorb dietary Vitamin B₁₂, eventually causing macrocytic/pernicious anemia and neurological issues.","whyWrongChoices":"Alternative options: iron deficiency anemia, blind loop syndrome, dumping syndrome"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how much sodium is 3 grams of salt?:::1,200', 'how much sodium is 3 grams of salt?', '1,200', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table salt (sodium chloride) consists of approximately 40% sodium and 60% chloride.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1,200\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table salt (sodium chloride) consists of approximately 40% sodium and 60% chloride.\n\nTo find the amount of sodium in 3 grams of salt:\n• Convert 3 grams of salt to milligrams: 3 grams = 3,000 milligrams.\n• Calculate the sodium portion: 3,000 milligrams multiplied by 0.40 = 1,200 milligrams of sodium.","whyWrongChoices":"Alternative options: 1,400, 1,600, 1,800"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a person who has done well for 3 years following a gastrectomy should be alert to signs of::::', 'a person who has done well for 3 years following a gastrectomy should be alert to signs of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The human liver stores a substantial reserve of Vitamin B₁₂ (cobalamin), which typically lasts 3 to 5 years. Once these internal stores are fully exhausted, symptoms of deficiency begin to appear.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vitamin B₁₂ deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The human liver stores a substantial reserve of Vitamin B₁₂ (cobalamin), which typically lasts 3 to 5 years. Once these internal stores are fully exhausted, symptoms of deficiency begin to appear.\n\nA gastrectomy removes the parietal cells of the stomach, which are responsible for secreting intrinsic factor. Intrinsic factor is a protein absolutely required for Vitamin B₁₂ absorption in the ileum. Without it, the body cannot absorb dietary Vitamin B₁₂, eventually causing macrocytic/pernicious anemia and neurological issues.","whyWrongChoices":"Alternative options: iron deficiency anemia, blind loop syndrome, dumping syndrome"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary recommendation for clients with cystic fibrosis except::::limit the use of table salt', 'dietary recommendation for clients with cystic fibrosis except:', 'limit the use of table salt', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cystic fibrosis (CF) is caused by a genetic mutation that disrupts the CFTR protein, preventing cells from properly regulating chloride and sodium. As a result, individuals with CF lose massive amounts of salt through their sweat pores (often referred to as having \"salty skin\"). To prevent hyponatremia (dangerously low blood sodium), dehydration, and heat exhaustion, clients with CF are actively encouraged to liberalize their use of table salt and consume salty snacks. Limiting salt is contraindicated.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"limit the use of table salt\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cystic fibrosis (CF) is caused by a genetic mutation that disrupts the CFTR protein, preventing cells from properly regulating chloride and sodium. As a result, individuals with CF lose massive amounts of salt through their sweat pores (often referred to as having \"salty skin\"). To prevent hyponatremia (dangerously low blood sodium), dehydration, and heat exhaustion, clients with CF are actively encouraged to liberalize their use of table salt and consume salty snacks. Limiting salt is contraindicated.\n\nHistorically, old test bank items sometimes listed fat restriction as an outdated management strategy because patients cannot digest fats well without enzymes. However, in modern clinical nutrition practice—combined with Pancreatic Enzyme Replacement Therapy (PERT)—a high-fat diet is heavily promoted alongside high calorie and high protein to help meet their high energy demands.","whyWrongChoices":"Alternative options: high calorie, high protein, fat restrictions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary recommendation for clients with cystic fibrosis except::::', 'dietary recommendation for clients with cystic fibrosis except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cystic fibrosis (CF) is caused by a genetic mutation that disrupts the CFTR protein, preventing cells from properly regulating chloride and sodium. As a result, individuals with CF lose massive amounts of salt through their sweat pores (often referred to as having \"salty skin\"). To prevent hyponatremia (dangerously low blood sodium), dehydration, and heat exhaustion, clients with CF are actively encouraged to liberalize their use of table salt and consume salty snacks. Limiting salt is contraindicated.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"limit the use of table salt\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cystic fibrosis (CF) is caused by a genetic mutation that disrupts the CFTR protein, preventing cells from properly regulating chloride and sodium. As a result, individuals with CF lose massive amounts of salt through their sweat pores (often referred to as having \"salty skin\"). To prevent hyponatremia (dangerously low blood sodium), dehydration, and heat exhaustion, clients with CF are actively encouraged to liberalize their use of table salt and consume salty snacks. Limiting salt is contraindicated.\n\nHistorically, old test bank items sometimes listed fat restriction as an outdated management strategy because patients cannot digest fats well without enzymes. However, in modern clinical nutrition practice—combined with Pancreatic Enzyme Replacement Therapy (PERT)—a high-fat diet is heavily promoted alongside high calorie and high protein to help meet their high energy demands.","whyWrongChoices":"Alternative options: high calorie, high protein, fat restrictions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:risk assessment chd includes measurement of blood lipids such as::::all of the above', 'risk assessment chd includes measurement of blood lipids such as:', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A comprehensive risk assessment for Coronary Heart Disease (CHD) relies on a full fasting lipid profile. Each of the lipid fractions listed in the other options provides distinct, critical diagnostic data regarding a patient''s cardiovascular health profile:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A comprehensive risk assessment for Coronary Heart Disease (CHD) relies on a full fasting lipid profile. Each of the lipid fractions listed in the other options provides distinct, critical diagnostic data regarding a patient''s cardiovascular health profile:\n\n• Total Cholesterol (TC): Reflects the overall amount of cholesterol circulating in the bloodstream and is directly linked to blood vessel plaque buildup and disease risk.\n• Triglycerides (TG): High levels of these blood fats serve as an independent risk factor for atherosclerosis and metabolic syndrome, often elevated by a high-fat diet, refined sugars, or alcohol.\n• HDL-Cholesterol (HDL-C): Known as the \"good cholesterol,\" it plays a protective role by removing excess cholesterol from peripheral tissues and transporting it back to the liver. High levels actively reduce CHD risk.\n• LDL-Cholesterol (LDL-C): Designated as the \"bad cholesterol\" and the primary target of clinical lipid-lowering therapies, elevated circulating LDL leads directly to fatty accumulation and narrowing inside the coronary arteries.","whyWrongChoices":"Alternative options: total cholesterol, TG, LDL-cholesterol, total cholesterol, HDL cholesterol, TG"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:risk assessment chd includes measurement of blood lipids such as::::', 'risk assessment chd includes measurement of blood lipids such as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A comprehensive risk assessment for Coronary Heart Disease (CHD) relies on a full fasting lipid profile. Each of the lipid fractions listed in the other options provides distinct, critical diagnostic data regarding a patient''s cardiovascular health profile:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A comprehensive risk assessment for Coronary Heart Disease (CHD) relies on a full fasting lipid profile. Each of the lipid fractions listed in the other options provides distinct, critical diagnostic data regarding a patient''s cardiovascular health profile:\n\n• Total Cholesterol (TC): Reflects the overall amount of cholesterol circulating in the bloodstream and is directly linked to blood vessel plaque buildup and disease risk.\n• Triglycerides (TG): High levels of these blood fats serve as an independent risk factor for atherosclerosis and metabolic syndrome, often elevated by a high-fat diet, refined sugars, or alcohol.\n• HDL-Cholesterol (HDL-C): Known as the \"good cholesterol,\" it plays a protective role by removing excess cholesterol from peripheral tissues and transporting it back to the liver. High levels actively reduce CHD risk.\n• LDL-Cholesterol (LDL-C): Designated as the \"bad cholesterol\" and the primary target of clinical lipid-lowering therapies, elevated circulating LDL leads directly to fatty accumulation and narrowing inside the coronary arteries.","whyWrongChoices":"Alternative options: total cholesterol, TG, LDL-cholesterol, total cholesterol, HDL cholesterol, TG"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:chronic diarrhea may be accompanied by a number of nutritional deficiencies due to losses of::::all of the above', 'chronic diarrhea may be accompanied by a number of nutritional deficiencies due to losses of:', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chronic diarrhea severely impairs the small and large intestines'' ability to absorb nutrients due to rapid transit time and mucosal damage. This leads to widespread malabsorption and excessive losses of:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chronic diarrhea severely impairs the small and large intestines'' ability to absorb nutrients due to rapid transit time and mucosal damage. This leads to widespread malabsorption and excessive losses of:\n\n• Na & K: Sodium and potassium are critical electrolytes lost in high volumes through watery stools, leading to dehydration and electrolyte imbalances.\n• Vitamins & minerals: Fat-soluble vitamins (A, D, E, K), water-soluble vitamins (like B-complex), and minerals (such as iron, zinc, and magnesium) are rapidly depleted.\n• Protein: Protein-losing enteropathy often occurs during chronic diarrhea, where plasma proteins leak directly into the gut lumen and are excreted, leading to tissue wasting and hypoalbuminemia.","whyWrongChoices":"Alternative options: Na & K, vitamins & minerals, protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:chronic diarrhea may be accompanied by a number of nutritional deficiencies due to losses of::::', 'chronic diarrhea may be accompanied by a number of nutritional deficiencies due to losses of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chronic diarrhea severely impairs the small and large intestines'' ability to absorb nutrients due to rapid transit time and mucosal damage. This leads to widespread malabsorption and excessive losses of:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chronic diarrhea severely impairs the small and large intestines'' ability to absorb nutrients due to rapid transit time and mucosal damage. This leads to widespread malabsorption and excessive losses of:\n\n• Na & K: Sodium and potassium are critical electrolytes lost in high volumes through watery stools, leading to dehydration and electrolyte imbalances.\n• Vitamins & minerals: Fat-soluble vitamins (A, D, E, K), water-soluble vitamins (like B-complex), and minerals (such as iron, zinc, and magnesium) are rapidly depleted.\n• Protein: Protein-losing enteropathy often occurs during chronic diarrhea, where plasma proteins leak directly into the gut lumen and are excreted, leading to tissue wasting and hypoalbuminemia.","whyWrongChoices":"Alternative options: Na & K, vitamins & minerals, protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this type of supplement has shown good results in reducing encephalopathy and in improving nitrogen and energy balance::::branched-chain amino acids supplements', 'this type of supplement has shown good results in reducing encephalopathy and in improving nitrogen and energy balance:', 'branched-chain amino acids supplements', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with advanced liver disease or cirrhosis typically present with an altered amino acid profile. Their plasma levels of Branched-Chain Amino Acids (BCAAs: leucine, isoleucine, and valine) drop significantly, while levels of Aromatic Amino Acids (AAAs: phenylalanine, tyrosine, and tryptophan) rise. This imbalance allows excessive AAAs to cross the blood-brain barrier, altering neurotransmission and inducing hepatic encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"branched-chain amino acids supplements\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with advanced liver disease or cirrhosis typically present with an altered amino acid profile. Their plasma levels of Branched-Chain Amino Acids (BCAAs: leucine, isoleucine, and valine) drop significantly, while levels of Aromatic Amino Acids (AAAs: phenylalanine, tyrosine, and tryptophan) rise. This imbalance allows excessive AAAs to cross the blood-brain barrier, altering neurotransmission and inducing hepatic encephalopathy.","whyWrongChoices":"Alternative options: vegetable ad casein-based protein supplements, aromatic amino acids supplements, phenylalanine supplements"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this type of supplement has shown good results in reducing encephalopathy and in improving nitrogen and energy balance::::', 'this type of supplement has shown good results in reducing encephalopathy and in improving nitrogen and energy balance:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with advanced liver disease or cirrhosis typically present with an altered amino acid profile. Their plasma levels of Branched-Chain Amino Acids (BCAAs: leucine, isoleucine, and valine) drop significantly, while levels of Aromatic Amino Acids (AAAs: phenylalanine, tyrosine, and tryptophan) rise. This imbalance allows excessive AAAs to cross the blood-brain barrier, altering neurotransmission and inducing hepatic encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"branched-chain amino acids supplements\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with advanced liver disease or cirrhosis typically present with an altered amino acid profile. Their plasma levels of Branched-Chain Amino Acids (BCAAs: leucine, isoleucine, and valine) drop significantly, while levels of Aromatic Amino Acids (AAAs: phenylalanine, tyrosine, and tryptophan) rise. This imbalance allows excessive AAAs to cross the blood-brain barrier, altering neurotransmission and inducing hepatic encephalopathy.","whyWrongChoices":"Alternative options: vegetable ad casein-based protein supplements, aromatic amino acids supplements, phenylalanine supplements"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are recommendations to address obesity during adolescence except::::', 'the following are recommendations to address obesity during adolescence except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Psychotherapy - this recommendation is for other professional.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Psychotherapy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Psychotherapy - this recommendation is for other professional.","whyWrongChoices":"Alternative options: Increased physical activity and exercise, Dietary change, Food use retraining"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:using the quickest method for weight calculation, determine the weight for a small frame male at 5’10”. hamwi method:::150', 'using the quickest method for weight calculation, determine the weight for a small frame male at 5’10”. hamwi method', '150', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"150\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation:\n\n1. Calculate Ideal Body Weight (IBW) for a medium frame:\nThe standard Hamwi method rule for males allocates 106 lbs for the first 5 feet (60 inches) of height, plus 6 lbs for every additional inch.\n\t• Height: 5''10\" (which is 10 inches over 5 feet)\n\t• Base weight: 106 lbs\n\t• Additional inches: 10 inches × 6 lbs/inch = 60 lbs\n\t• Medium Frame Weight: 106 lbs + 60 lbs = 166 lbs\n\n2. Adjust for a small frame size:\nThe Hamwi method dictates that you must subtract 10% from the medium frame total if the individual has a small frame.\n\t• 10% of 166 lbs = 16.6 lbs\n\t• Small Frame Weight: 166 lbs - 16.6 lbs = 149.4 lbs\n\nWhen rounded to the nearest multiple of ten to match the multiple-choice selection, 149.4 lbs aligns perfectly with 150 lbs.","whyWrongChoices":"Alternative options: 170, 160, 140"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:using the quickest method for weight calculation, determine the weight for a small frame male at 5’10”. hamwi method:::', 'using the quickest method for weight calculation, determine the weight for a small frame male at 5’10”. hamwi method', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"150\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation:\n\n1. Calculate Ideal Body Weight (IBW) for a medium frame:\nThe standard Hamwi method rule for males allocates 106 lbs for the first 5 feet (60 inches) of height, plus 6 lbs for every additional inch.\n\t• Height: 5''10\" (which is 10 inches over 5 feet)\n\t• Base weight: 106 lbs\n\t• Additional inches: 10 inches × 6 lbs/inch = 60 lbs\n\t• Medium Frame Weight: 106 lbs + 60 lbs = 166 lbs\n\n2. Adjust for a small frame size:\nThe Hamwi method dictates that you must subtract 10% from the medium frame total if the individual has a small frame.\n\t• 10% of 166 lbs = 16.6 lbs\n\t• Small Frame Weight: 166 lbs - 16.6 lbs = 149.4 lbs\n\nWhen rounded to the nearest multiple of ten to match the multiple-choice selection, 149.4 lbs aligns perfectly with 150 lbs.","whyWrongChoices":"Alternative options: 170, 160, 140"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:maria consulted ms. uy, a registered nd for weight reduction. history of her weight gain is as follows: height = 5’5”; wrist circumference = 6”; actual weight = 180 lbs.; and dbw = 125 lbs. what is maria’s %dbw change?:::44%', 'maria consulted ms. uy, a registered nd for weight reduction. history of her weight gain is as follows: height = 5’5”; wrist circumference = 6”; actual weight = 180 lbs.; and dbw = 125 lbs. what is maria’s %dbw change?', '44%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find a person''s percentage over or under their DBW (the percentage weight change/deviation), you use this formula:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"44%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find a person''s percentage over or under their DBW (the percentage weight change/deviation), you use this formula:\n• % DBW Deviation = ((Actual Weight - DBW) ÷ DBW) × 100\n• Calculation: ((180 lbs - 125 lbs) ÷ 125 lbs) × 100 = (55 ÷ 125) × 100 = 44%","whyWrongChoices":"Alternative options: 20%, 31%, 38%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:maria consulted ms. uy, a registered nd for weight reduction. history of her weight gain is as follows: height = 5’5”; wrist circumference = 6”; actual weight = 180 lbs.; and dbw = 125 lbs. what is maria’s %dbw change?:::', 'maria consulted ms. uy, a registered nd for weight reduction. history of her weight gain is as follows: height = 5’5”; wrist circumference = 6”; actual weight = 180 lbs.; and dbw = 125 lbs. what is maria’s %dbw change?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find a person''s percentage over or under their DBW (the percentage weight change/deviation), you use this formula:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"44%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find a person''s percentage over or under their DBW (the percentage weight change/deviation), you use this formula:\n• % DBW Deviation = ((Actual Weight - DBW) ÷ DBW) × 100\n• Calculation: ((180 lbs - 125 lbs) ÷ 125 lbs) × 100 = (55 ÷ 125) × 100 = 44%","whyWrongChoices":"Alternative options: 20%, 31%, 38%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how many grams of protein will be contained in 1.5 liters of blenderized feeding formula with a caloric density of 2 kcal/ml, 12% of which are from protein?:::90 g', 'how many grams of protein will be contained in 1.5 liters of blenderized feeding formula with a caloric density of 2 kcal/ml, 12% of which are from protein?', '90 g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"90 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation:\n\n1. Convert liters to milliliters:\n1.5 liters = 1500 ml\n\n2. Calculate the total calories in the formula:\nMultiply the total volume by the caloric density.\n1500 ml x 2 kcal/ml = 3000 kcal\n\n3. Calculate the calories provided by protein:\nMultiply the total calories by the protein percentage.\n3000 kcal x 0.12 = 360 kcal from protein\n\n4. Convert protein calories into grams:\nProtein provides 4 calories per gram (4 kcal/g). Divide the protein calories by 4.\n360 kcal / 4 kcal/g = 90 g","whyWrongChoices":"Alternative options: 100 g, 110 g, 120 g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how many grams of protein will be contained in 1.5 liters of blenderized feeding formula with a caloric density of 2 kcal/ml, 12% of which are from protein?:::', 'how many grams of protein will be contained in 1.5 liters of blenderized feeding formula with a caloric density of 2 kcal/ml, 12% of which are from protein?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"90 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation:\n\n1. Convert liters to milliliters:\n1.5 liters = 1500 ml\n\n2. Calculate the total calories in the formula:\nMultiply the total volume by the caloric density.\n1500 ml x 2 kcal/ml = 3000 kcal\n\n3. Calculate the calories provided by protein:\nMultiply the total calories by the protein percentage.\n3000 kcal x 0.12 = 360 kcal from protein\n\n4. Convert protein calories into grams:\nProtein provides 4 calories per gram (4 kcal/g). Divide the protein calories by 4.\n360 kcal / 4 kcal/g = 90 g","whyWrongChoices":"Alternative options: 100 g, 110 g, 120 g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during anaerobic glycolysis, there is a net production of lactate and .:::atp', 'during anaerobic glycolysis, there is a net production of lactate and .', 'ATP', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During anaerobic glycolysis, a single molecule of glucose is broken down in the cytosol without using oxygen. This pathway results in the net production of two distinct products:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ATP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During anaerobic glycolysis, a single molecule of glucose is broken down in the cytosol without using oxygen. This pathway results in the net production of two distinct products:\n1. Lactate (2 molecules)\n2. ATP (a net yield of 2 molecules)\n\n• NADH: While NADH is temporarily produced halfway through glycolysis, the cell immediately uses up that NADH to convert pyruvate into lactate. This means there is zero net production of NADH by the end of the anaerobic process.\n• FADH₂: This electron carrier is only generated inside the mitochondria during the Krebs cycle (aerobic respiration), not during glycolysis.\n• NAD⁺: Because NADH is continuously recycled back into NAD⁺ to keep glycolysis running, NAD⁺ is constantly consumed and regenerated, meaning it does not experience a net increase.","whyWrongChoices":"Alternative options: NAD+, NADH, FADH2"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during anaerobic glycolysis, there is a net production of lactate and .:::', 'during anaerobic glycolysis, there is a net production of lactate and .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During anaerobic glycolysis, a single molecule of glucose is broken down in the cytosol without using oxygen. This pathway results in the net production of two distinct products:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ATP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During anaerobic glycolysis, a single molecule of glucose is broken down in the cytosol without using oxygen. This pathway results in the net production of two distinct products:\n1. Lactate (2 molecules)\n2. ATP (a net yield of 2 molecules)\n\n• NADH: While NADH is temporarily produced halfway through glycolysis, the cell immediately uses up that NADH to convert pyruvate into lactate. This means there is zero net production of NADH by the end of the anaerobic process.\n• FADH₂: This electron carrier is only generated inside the mitochondria during the Krebs cycle (aerobic respiration), not during glycolysis.\n• NAD⁺: Because NADH is continuously recycled back into NAD⁺ to keep glycolysis running, NAD⁺ is constantly consumed and regenerated, meaning it does not experience a net increase.","whyWrongChoices":"Alternative options: NAD+, NADH, FADH2"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it competes with calcium for absorption::::mg', 'it competes with calcium for absorption:', 'Mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Magnesium (Mg) and calcium (Ca) share a common transport and homeostatic regulatory system within the gastrointestinal tract. When consumed in large or highly concentrated supplemental doses, magnesium and calcium directly compete with each other for absorption pathways across the small intestinal mucosa.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Magnesium (Mg) and calcium (Ca) share a common transport and homeostatic regulatory system within the gastrointestinal tract. When consumed in large or highly concentrated supplemental doses, magnesium and calcium directly compete with each other for absorption pathways across the small intestinal mucosa.\n\n• Sodium & Potassium: These monovalent extracellular and intracellular cations are absorbed through distinct, independent active transport and electrochemical channels that do not interfere with or compete against divalent minerals like calcium.\n• Phosphorus: While phosphorus (P) interacts with calcium dynamically, it does not directly compete for the same absorption binding sites. Instead, an excessive amount of phosphorus binds chemically with calcium within the intestinal lumen to form an insoluble complex (calcium phosphate), which physically reduces the overall bioavailability of both minerals rather than competing for transport carriers.","whyWrongChoices":"Alternative options: P, K, Na"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:one glucose molecule will yield how many pyruvate products?:::', 'one glucose molecule will yield how many pyruvate products?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the first stage of cellular respiration (glycolysis), a single glucose molecule—which is a 6-carbon sugar (C₆H₁₂O₆)—is physically split and oxidized in the cytoplasm of the cell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the first stage of cellular respiration (glycolysis), a single glucose molecule—which is a 6-carbon sugar (C₆H₁₂O₆)—is physically split and oxidized in the cytoplasm of the cell.\n\nThis biochemical breakdown yields exactly two molecules of pyruvate (also known as pyruvic acid), which are 3-carbon structures (C₃H₄O₃).","whyWrongChoices":"Alternative options: 1, 3, 4"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamins that help in cell division::::', 'vitamins that help in cell division:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both folate (vitamin B9) and vitamin B12 (cobalamin) are essential coenzymes required for the synthesis of nucleic acids (DNA and RNA).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"folate & B12\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both folate (vitamin B9) and vitamin B12 (cobalamin) are essential coenzymes required for the synthesis of nucleic acids (DNA and RNA).\n\nBefore a cell can divide, it must perfectly replicate its entire DNA strands. Folate is a crucial building block for this replication process. Vitamin B12 acts as the mandatory key that unlocks folate, converting it into its active form inside the body.\n\nIf either vitamin is missing, cell division stalls. This is most visibly seen in fast-dividing tissues like bone marrow, where a lack of cell division leads to megaloblastic anemia (large, immature, undivided red blood cells).","whyWrongChoices":"Alternative options: folate & biotin, thiamin & riboflavin, niacin & B12"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it competes with calcium for absorption::::', 'it competes with calcium for absorption:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Magnesium (Mg) and calcium (Ca) share a common transport and homeostatic regulatory system within the gastrointestinal tract. When consumed in large or highly concentrated supplemental doses, magnesium and calcium directly compete with each other for absorption pathways across the small intestinal mucosa.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Magnesium (Mg) and calcium (Ca) share a common transport and homeostatic regulatory system within the gastrointestinal tract. When consumed in large or highly concentrated supplemental doses, magnesium and calcium directly compete with each other for absorption pathways across the small intestinal mucosa.\n\n• Sodium & Potassium: These monovalent extracellular and intracellular cations are absorbed through distinct, independent active transport and electrochemical channels that do not interfere with or compete against divalent minerals like calcium.\n• Phosphorus: While phosphorus (P) interacts with calcium dynamically, it does not directly compete for the same absorption binding sites. Instead, an excessive amount of phosphorus binds chemically with calcium within the intestinal lumen to form an insoluble complex (calcium phosphate), which physically reduces the overall bioavailability of both minerals rather than competing for transport carriers.","whyWrongChoices":"Alternative options: P, K, Na"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it protects folate from oxidative destruction::::vitamin c', 'it protects folate from oxidative destruction:', 'vitamin C', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Folate (Vitamin B9) is a highly unstable water-soluble molecule that is extremely susceptible to degradation via heat, UV light, and environmental oxygen. Vitamin C (ascorbic acid) acts as a highly effective water-soluble antioxidant and oxygen-scavenger.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vitamin C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Folate (Vitamin B9) is a highly unstable water-soluble molecule that is extremely susceptible to degradation via heat, UV light, and environmental oxygen. Vitamin C (ascorbic acid) acts as a highly effective water-soluble antioxidant and oxygen-scavenger.\n\nIn food matrixes, the digestive tract, and blood plasma, Vitamin C shields folate from breaking down by neutralizing free radicals and reducing the primary products of folate oxidation (such as quinonoid dihydrofolate) back into their active, usable forms. Because of this symbiotic protective relationship, a deficiency in Vitamin C often accelerates the depletion and urinary excretion of oxidized folate derivatives.","whyWrongChoices":"Alternative options: vitamin A, vitamin B₂, vitamin E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it protects folate from oxidative destruction::::', 'it protects folate from oxidative destruction:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Folate (Vitamin B9) is a highly unstable water-soluble molecule that is extremely susceptible to degradation via heat, UV light, and environmental oxygen. Vitamin C (ascorbic acid) acts as a highly effective water-soluble antioxidant and oxygen-scavenger.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vitamin C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Folate (Vitamin B9) is a highly unstable water-soluble molecule that is extremely susceptible to degradation via heat, UV light, and environmental oxygen. Vitamin C (ascorbic acid) acts as a highly effective water-soluble antioxidant and oxygen-scavenger.\n\nIn food matrixes, the digestive tract, and blood plasma, Vitamin C shields folate from breaking down by neutralizing free radicals and reducing the primary products of folate oxidation (such as quinonoid dihydrofolate) back into their active, usable forms. Because of this symbiotic protective relationship, a deficiency in Vitamin C often accelerates the depletion and urinary excretion of oxidized folate derivatives.","whyWrongChoices":"Alternative options: vitamin A, vitamin B₂, vitamin E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how many meq are found in a phosphorus diet limited to 1,000 mg per day?:::65', 'how many meq are found in a phosphorus diet limited to 1,000 mg per day?', '65', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phosphorus primarily circulates in extracellular and intracellular fluids as phosphate ions, predominantly a mixture of divalent ($HPO_4^{2-}$) and monovalent ($H_2PO_4^{-}$) species at physiological blood pH (7.4) in a roughly 4:1 ratio. For clinical nutrition and renal calculations involving elemental phosphorus (atomic weight approximately 30.97 g/mol), an effective valence of roughly 1.8 to 2 is applied depending on the exact ionic distribution, or more commonly in standard dietetic board calculations, the conversion utilizes the atomic weight and an assumed average valence or direct stoichiometric conversion factor where 1 mmol of phosphorus equals roughly 31 mg, and milliequivalents are derived via the formula: mEq = (mg / atomic weight) * valence. At physiological pH, calculating with an average valence of ~2.0 for total phosphate yields (1000 mg / 30.97 mg/mmol) * 2 = ~64.5 mEq, which rounds directly to 65 mEq.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"65\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phosphorus primarily circulates in extracellular and intracellular fluids as phosphate ions, predominantly a mixture of divalent ($HPO_4^{2-}$) and monovalent ($H_2PO_4^{-}$) species at physiological blood pH (7.4) in a roughly 4:1 ratio. For clinical nutrition and renal calculations involving elemental phosphorus (atomic weight approximately 30.97 g/mol), an effective valence of roughly 1.8 to 2 is applied depending on the exact ionic distribution, or more commonly in standard dietetic board calculations, the conversion utilizes the atomic weight and an assumed average valence or direct stoichiometric conversion factor where 1 mmol of phosphorus equals roughly 31 mg, and milliequivalents are derived via the formula: mEq = (mg / atomic weight) * valence. At physiological pH, calculating with an average valence of ~2.0 for total phosphate yields (1000 mg / 30.97 mg/mmol) * 2 = ~64.5 mEq, which rounds directly to 65 mEq.","whyWrongChoices":"Alternative options: 14, 28, 32"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how many meq are found in a phosphorus diet limited to 1,000 mg per day?:::', 'how many meq are found in a phosphorus diet limited to 1,000 mg per day?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phosphorus primarily circulates in extracellular and intracellular fluids as phosphate ions, predominantly a mixture of divalent ($HPO_4^{2-}$) and monovalent ($H_2PO_4^{-}$) species at physiological blood pH (7.4) in a roughly 4:1 ratio. For clinical nutrition and renal calculations involving elemental phosphorus (atomic weight approximately 30.97 g/mol), an effective valence of roughly 1.8 to 2 is applied depending on the exact ionic distribution, or more commonly in standard dietetic board calculations, the conversion utilizes the atomic weight and an assumed average valence or direct stoichiometric conversion factor where 1 mmol of phosphorus equals roughly 31 mg, and milliequivalents are derived via the formula: mEq = (mg / atomic weight) * valence. At physiological pH, calculating with an average valence of ~2.0 for total phosphate yields (1000 mg / 30.97 mg/mmol) * 2 = ~64.5 mEq, which rounds directly to 65 mEq.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"65\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phosphorus primarily circulates in extracellular and intracellular fluids as phosphate ions, predominantly a mixture of divalent ($HPO_4^{2-}$) and monovalent ($H_2PO_4^{-}$) species at physiological blood pH (7.4) in a roughly 4:1 ratio. For clinical nutrition and renal calculations involving elemental phosphorus (atomic weight approximately 30.97 g/mol), an effective valence of roughly 1.8 to 2 is applied depending on the exact ionic distribution, or more commonly in standard dietetic board calculations, the conversion utilizes the atomic weight and an assumed average valence or direct stoichiometric conversion factor where 1 mmol of phosphorus equals roughly 31 mg, and milliequivalents are derived via the formula: mEq = (mg / atomic weight) * valence. At physiological pH, calculating with an average valence of ~2.0 for total phosphate yields (1000 mg / 30.97 mg/mmol) * 2 = ~64.5 mEq, which rounds directly to 65 mEq.","whyWrongChoices":"Alternative options: 14, 28, 32"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:tests for an elderly vegetarian patient indicate pernicious and megaloblastic anemia resulting from abnormally large “macrocytic” red blood cells that undergo rapid hemolysis. these results are most probably related to a vitamin deficiency in::::folacin and cobalamin', 'tests for an elderly vegetarian patient indicate pernicious and megaloblastic anemia resulting from abnormally large “macrocytic” red blood cells that undergo rapid hemolysis. these results are most probably related to a vitamin deficiency in:', 'folacin and cobalamin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Megaloblastic anemia (abnormally large, macrocytic red blood cells) is caused by a defect in DNA synthesis during red blood cell development. This specific type of anemia is caused by a deficiency in either folacin (folic acid/vitamin B9) or cobalamin (vitamin B12).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"folacin and cobalamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Megaloblastic anemia (abnormally large, macrocytic red blood cells) is caused by a defect in DNA synthesis during red blood cell development. This specific type of anemia is caused by a deficiency in either folacin (folic acid/vitamin B9) or cobalamin (vitamin B12).\n\nThe patient is an elderly vegetarian. Vitamin B12 (cobalamin) is found almost exclusively in animal-derived foods. Because of this, long-term vegetarians are at an exceptionally high risk of developing a cobalamin deficiency.","whyWrongChoices":"Alternative options: ascorbic acid, riboflavin and niacin, pantothenic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:tests for an elderly vegetarian patient indicate pernicious and megaloblastic anemia resulting from abnormally large “macrocytic” red blood cells that undergo rapid hemolysis. these results are most probably related to a vitamin deficiency in::::', 'tests for an elderly vegetarian patient indicate pernicious and megaloblastic anemia resulting from abnormally large “macrocytic” red blood cells that undergo rapid hemolysis. these results are most probably related to a vitamin deficiency in:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Megaloblastic anemia (abnormally large, macrocytic red blood cells) is caused by a defect in DNA synthesis during red blood cell development. This specific type of anemia is caused by a deficiency in either folacin (folic acid/vitamin B9) or cobalamin (vitamin B12).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"folacin and cobalamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Megaloblastic anemia (abnormally large, macrocytic red blood cells) is caused by a defect in DNA synthesis during red blood cell development. This specific type of anemia is caused by a deficiency in either folacin (folic acid/vitamin B9) or cobalamin (vitamin B12).\n\nThe patient is an elderly vegetarian. Vitamin B12 (cobalamin) is found almost exclusively in animal-derived foods. Because of this, long-term vegetarians are at an exceptionally high risk of developing a cobalamin deficiency.","whyWrongChoices":"Alternative options: ascorbic acid, riboflavin and niacin, pantothenic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in collagen synthesis, acts as a reducing agent to convert oxidized iron atom back to its reduced state.:::ascorbic acid', 'in collagen synthesis, acts as a reducing agent to convert oxidized iron atom back to its reduced state.', 'ascorbic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During collagen synthesis, two critical enzymes—prolyl hydroxylase and lysyl hydroxylase—are responsible for adding hydroxyl (-OH) groups to proline and lysine amino acids. This structural modification allows collagen strands to cross-link properly, forming a stable triple-helix network.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ascorbic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During collagen synthesis, two critical enzymes—prolyl hydroxylase and lysyl hydroxylase—are responsible for adding hydroxyl (-OH) groups to proline and lysine amino acids. This structural modification allows collagen strands to cross-link properly, forming a stable triple-helix network.\n\nThese hydroxylase enzymes require iron in its active, reduced ferrous state (Fe²⁺) to operate. During the chemical reaction, the iron atom naturally becomes oxidized into its inactive ferric state (Fe³⁺). Ascorbic acid (Vitamin C) acts as the essential electron donor or reducing agent, transferring electrons to convert the inactive ferric iron back into its active ferrous state. Without enough vitamin C, the iron stays oxidized, collagen remains under-hydroxylated, and connective tissues weaken (resulting in scurvy).","whyWrongChoices":"Alternative options: pantothenic acid, pyridoxine, folic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to a vietnamese baguette sandwich.:::bahn mi', 'it refers to a vietnamese baguette sandwich.', 'Bahn mi', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bánh mì is the Vietnamese baguette sandwich.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bahn mi\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bánh mì is the Vietnamese baguette sandwich.\n\nGỏi cuốn are fresh spring rolls, nước chấm is a dipping sauce, and phở is a noodle soup.","whyWrongChoices":"Alternative options: Goi cuon, Nuoc cham, Pho"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in collagen synthesis, acts as a reducing agent to convert oxidized iron atom back to its reduced state.:::', 'in collagen synthesis, acts as a reducing agent to convert oxidized iron atom back to its reduced state.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During collagen synthesis, two critical enzymes—prolyl hydroxylase and lysyl hydroxylase—are responsible for adding hydroxyl (-OH) groups to proline and lysine amino acids. This structural modification allows collagen strands to cross-link properly, forming a stable triple-helix network.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ascorbic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During collagen synthesis, two critical enzymes—prolyl hydroxylase and lysyl hydroxylase—are responsible for adding hydroxyl (-OH) groups to proline and lysine amino acids. This structural modification allows collagen strands to cross-link properly, forming a stable triple-helix network.\n\nThese hydroxylase enzymes require iron in its active, reduced ferrous state (Fe²⁺) to operate. During the chemical reaction, the iron atom naturally becomes oxidized into its inactive ferric state (Fe³⁺). Ascorbic acid (Vitamin C) acts as the essential electron donor or reducing agent, transferring electrons to convert the inactive ferric iron back into its active ferrous state. Without enough vitamin C, the iron stays oxidized, collagen remains under-hydroxylated, and connective tissues weaken (resulting in scurvy).","whyWrongChoices":"Alternative options: pantothenic acid, pyridoxine, folic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the molecule most directly linked to the initiation of atherosclerotic plaques is::::oxidized cholesterol', 'the molecule most directly linked to the initiation of atherosclerotic plaques is:', 'oxidized cholesterol', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The absolute initial step in the formation of an atherosclerotic plaque begins when LDL cholesterol particles slip into the subendothelial space of an artery wall and become oxidized by free radicals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oxidized cholesterol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The absolute initial step in the formation of an atherosclerotic plaque begins when LDL cholesterol particles slip into the subendothelial space of an artery wall and become oxidized by free radicals.\n\nThis oxidized cholesterol is highly toxic to the blood vessel lining. It damages the endothelial cells, acting as the primary chemical trigger that forces the artery wall to express adhesion molecules. This signals monocytes (white blood cells) to enter the wall, consume the oxidized lipids, transform into \"foam cells,\" and start building the plaque.\n\n• Tumor necrosis factor (TNF): This is a pro-inflammatory cytokine that amplifies the immune response and accelerates plaque growth later on, but it is not the original molecule that initiates the process.\n• Thromboxane A₂: A lipid mediator released by activated platelets to cause vasoconstriction and blood clotting (thrombosis), typically playing a major role when a plaque ruptures later in the disease.\n• Platelet-derived growth factor (PDGF): A growth factor that stimulates the migration and multiplication of smooth muscle cells to form a fibrous cap over the lipid core during the progression phase.","whyWrongChoices":"Alternative options: thromoxane A2, tumor necrosis factor, platelet derived growth factor"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the molecule most directly linked to the initiation of atherosclerotic plaques is::::', 'the molecule most directly linked to the initiation of atherosclerotic plaques is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The absolute initial step in the formation of an atherosclerotic plaque begins when LDL cholesterol particles slip into the subendothelial space of an artery wall and become oxidized by free radicals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oxidized cholesterol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The absolute initial step in the formation of an atherosclerotic plaque begins when LDL cholesterol particles slip into the subendothelial space of an artery wall and become oxidized by free radicals.\n\nThis oxidized cholesterol is highly toxic to the blood vessel lining. It damages the endothelial cells, acting as the primary chemical trigger that forces the artery wall to express adhesion molecules. This signals monocytes (white blood cells) to enter the wall, consume the oxidized lipids, transform into \"foam cells,\" and start building the plaque.\n\n• Tumor necrosis factor (TNF): This is a pro-inflammatory cytokine that amplifies the immune response and accelerates plaque growth later on, but it is not the original molecule that initiates the process.\n• Thromboxane A₂: A lipid mediator released by activated platelets to cause vasoconstriction and blood clotting (thrombosis), typically playing a major role when a plaque ruptures later in the disease.\n• Platelet-derived growth factor (PDGF): A growth factor that stimulates the migration and multiplication of smooth muscle cells to form a fibrous cap over the lipid core during the progression phase.","whyWrongChoices":"Alternative options: thromoxane A2, tumor necrosis factor, platelet derived growth factor"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dr. cruz ordered a 500 mg sodium diet for nena lim. how much salt contains 500 mg of sodium?:::1,250 mg', 'dr. cruz ordered a 500 mg sodium diet for nena lim. how much salt contains 500 mg of sodium?', '1,250 mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In nutrition and dietetics calculations, standard table salt (sodium chloride, NaCl) is approximated to be 40% sodium and 60% chloride by weight.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1,250 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In nutrition and dietetics calculations, standard table salt (sodium chloride, NaCl) is approximated to be 40% sodium and 60% chloride by weight.\n\nTo convert a specific milligram amount of sodium into the equivalent amount of table salt, you divide the sodium milligrams by 0.40 (or simply multiply by 2.5):\n\nSalt (mg) = Sodium (mg) x 2.5\nSalt (mg) = 500 mg x 2.5 = 1,250 mg\n\nTherefore, 1,250 mg of table salt contains exactly 500 mg of elemental sodium.","whyWrongChoices":"Alternative options: 800 mg, 2,000 mg, 200 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dr. cruz ordered a 500 mg sodium diet for nena lim. how much salt contains 500 mg of sodium?:::', 'dr. cruz ordered a 500 mg sodium diet for nena lim. how much salt contains 500 mg of sodium?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In nutrition and dietetics calculations, standard table salt (sodium chloride, NaCl) is approximated to be 40% sodium and 60% chloride by weight.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1,250 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In nutrition and dietetics calculations, standard table salt (sodium chloride, NaCl) is approximated to be 40% sodium and 60% chloride by weight.\n\nTo convert a specific milligram amount of sodium into the equivalent amount of table salt, you divide the sodium milligrams by 0.40 (or simply multiply by 2.5):\n\nSalt (mg) = Sodium (mg) x 2.5\nSalt (mg) = 500 mg x 2.5 = 1,250 mg\n\nTherefore, 1,250 mg of table salt contains exactly 500 mg of elemental sodium.","whyWrongChoices":"Alternative options: 800 mg, 2,000 mg, 200 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamins that help in cell division::::folate & b12', 'vitamins that help in cell division:', 'folate & B12', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both folate (vitamin B9) and vitamin B12 (cobalamin) are essential coenzymes required for the synthesis of nucleic acids (DNA and RNA).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"folate & B12\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both folate (vitamin B9) and vitamin B12 (cobalamin) are essential coenzymes required for the synthesis of nucleic acids (DNA and RNA).\n\nBefore a cell can divide, it must perfectly replicate its entire DNA strands. Folate is a crucial building block for this replication process. Vitamin B12 acts as the mandatory key that unlocks folate, converting it into its active form inside the body.\n\nIf either vitamin is missing, cell division stalls. This is most visibly seen in fast-dividing tissues like bone marrow, where a lack of cell division leads to megaloblastic anemia (large, immature, undivided red blood cells).","whyWrongChoices":"Alternative options: folate & biotin, thiamin & riboflavin, niacin & B12"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:calcium content of a high-calcium diet.:::800 mg', 'calcium content of a high-calcium diet.', '800 mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In conventional therapeutic diet matrices, modifications to standard mineral limits are defined relative to baseline metabolic configurations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"800 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In conventional therapeutic diet matrices, modifications to standard mineral limits are defined relative to baseline metabolic configurations.\n\nWhile the full Recommended Dietary Allowance (RDA) for an average adult is roughly 1000 mg to 1200 mg, manual meal-planning reviewers traditionally establish a therapeutic high-calcium diet parameter around an additional nutritional delivery baseline, using 800 mg as the primary calculated target choice among the listed options.\n\n• 400 mg: This is a low-calcium intake metric, often aligned with standard restricted renal diet parameters or severe hypercalcemia limitations.\n• 200 mg: An extremely low, strictly restricted value representing a severe therapeutic limitation.\n• 500 mg: This matches the maximum single-dose capacity for optimal intestinal calcium absorption rather than a whole-day high-calcium diet therapeutic target.","whyWrongChoices":"Alternative options: 400 mg, 500 mg, 200 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:calcium content of a high-calcium diet.:::', 'calcium content of a high-calcium diet.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In conventional therapeutic diet matrices, modifications to standard mineral limits are defined relative to baseline metabolic configurations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"800 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In conventional therapeutic diet matrices, modifications to standard mineral limits are defined relative to baseline metabolic configurations.\n\nWhile the full Recommended Dietary Allowance (RDA) for an average adult is roughly 1000 mg to 1200 mg, manual meal-planning reviewers traditionally establish a therapeutic high-calcium diet parameter around an additional nutritional delivery baseline, using 800 mg as the primary calculated target choice among the listed options.\n\n• 400 mg: This is a low-calcium intake metric, often aligned with standard restricted renal diet parameters or severe hypercalcemia limitations.\n• 200 mg: An extremely low, strictly restricted value representing a severe therapeutic limitation.\n• 500 mg: This matches the maximum single-dose capacity for optimal intestinal calcium absorption rather than a whole-day high-calcium diet therapeutic target.","whyWrongChoices":"Alternative options: 400 mg, 500 mg, 200 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the desirable body weight of a 3-year-old child::::14 kg', 'the desirable body weight of a 3-year-old child:', '14 kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For children aged 2 to 12 years old, nutrition and dietetics board exams in the Philippines utilize a standard, universally accepted formula to calculate Desirable Body Weight (DBW):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"14 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For children aged 2 to 12 years old, nutrition and dietetics board exams in the Philippines utilize a standard, universally accepted formula to calculate Desirable Body Weight (DBW):\n\nDBW (in kg) = (Age in years x 2) + 8\nDBW = (3 x 2) + 8\nDBW = 6 + 8 = 14 kg\n\nThis calculated value aligns closely with the World Health Organization (WHO) international pediatric standards, which place the statistical average weight of a healthy 3-year-old child right at 14 kg.","whyWrongChoices":"Alternative options: 13 kg, 12 kg, 15 kg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the desirable body weight of a 3-year-old child::::', 'the desirable body weight of a 3-year-old child:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For children aged 2 to 12 years old, nutrition and dietetics board exams in the Philippines utilize a standard, universally accepted formula to calculate Desirable Body Weight (DBW):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"14 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For children aged 2 to 12 years old, nutrition and dietetics board exams in the Philippines utilize a standard, universally accepted formula to calculate Desirable Body Weight (DBW):\n\nDBW (in kg) = (Age in years x 2) + 8\nDBW = (3 x 2) + 8\nDBW = 6 + 8 = 14 kg\n\nThis calculated value aligns closely with the World Health Organization (WHO) international pediatric standards, which place the statistical average weight of a healthy 3-year-old child right at 14 kg.","whyWrongChoices":"Alternative options: 13 kg, 12 kg, 15 kg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:conditions that are contraindicated for the use of tube feeding except::::metabolic stress', 'conditions that are contraindicated for the use of tube feeding except:', 'metabolic stress', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Metabolic stress (such as severe trauma, major surgery, sepsis, or extensive burns) is an indication for enteral nutrition (tube feeding), not a contraindication. During metabolic stress, the body enters a highly catabolic state where nutrient demands skyrocket. Starting early tube feeding within 24 to 48 hours is standard practice to support tissue repair and maintain gut integrity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"metabolic stress\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Metabolic stress (such as severe trauma, major surgery, sepsis, or extensive burns) is an indication for enteral nutrition (tube feeding), not a contraindication. During metabolic stress, the body enters a highly catabolic state where nutrient demands skyrocket. Starting early tube feeding within 24 to 48 hours is standard practice to support tissue repair and maintain gut integrity.\n\nThe question asks for the condition that is not a contraindication (the \"except\"). Options A, B, and C are all absolute contraindications where the gastrointestinal tract is entirely non-functional or unsafe to use.","whyWrongChoices":"Alternative options: paralytic ileus, peritonitis, intractable vomiting"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:conditions that are contraindicated for the use of tube feeding except::::', 'conditions that are contraindicated for the use of tube feeding except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Metabolic stress (such as severe trauma, major surgery, sepsis, or extensive burns) is an indication for enteral nutrition (tube feeding), not a contraindication. During metabolic stress, the body enters a highly catabolic state where nutrient demands skyrocket. Starting early tube feeding within 24 to 48 hours is standard practice to support tissue repair and maintain gut integrity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"metabolic stress\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Metabolic stress (such as severe trauma, major surgery, sepsis, or extensive burns) is an indication for enteral nutrition (tube feeding), not a contraindication. During metabolic stress, the body enters a highly catabolic state where nutrient demands skyrocket. Starting early tube feeding within 24 to 48 hours is standard practice to support tissue repair and maintain gut integrity.\n\nThe question asks for the condition that is not a contraindication (the \"except\"). Options A, B, and C are all absolute contraindications where the gastrointestinal tract is entirely non-functional or unsafe to use.","whyWrongChoices":"Alternative options: paralytic ileus, peritonitis, intractable vomiting"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this hormone decreases the urge to eat and increases physical activity to produce a negative energy balance.:::leptin', 'this hormone decreases the urge to eat and increases physical activity to produce a negative energy balance.', 'leptin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leptin is a hormone produced primarily by adipose (fat) tissue that acts as a long-term regulator of energy balance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"leptin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leptin is a hormone produced primarily by adipose (fat) tissue that acts as a long-term regulator of energy balance.\n\nWhen fat stores increase, leptin levels rise and signal the hypothalamus in the brain to suppress appetite (decrease the urge to eat) and boost metabolism and physical activity. This combination successfully drives the body toward a negative energy balance to burn off excess stored fat.\n\n• ghrelin: The \"hunger hormone\" produced mainly by the stomach. Its levels rise when the stomach is empty, signaling the brain to increase the urge to eat and reduce energy expenditure (promoting a positive energy balance).\n• adiponectin: Another hormone secreted by fat cells that helps regulate glucose levels and fatty acid breakdown while improving insulin sensitivity, but it does not directly drive the specific appetite-suppression and activity-boosting negative energy loop that leptin does.\n• insulin: Secreted by the pancreas primarily to lower blood glucose by shifting it into cells. While it can act as a minor central satiety signal, its primary physiological role is nutrient storage and carbohydrate metabolism.","whyWrongChoices":"Alternative options: ghrelin, adiponectin, insulin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
