INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:this hormone decreases the urge to eat and increases physical activity to produce a negative energy balance.:::', 'this hormone decreases the urge to eat and increases physical activity to produce a negative energy balance.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leptin is a hormone produced primarily by adipose (fat) tissue that acts as a long-term regulator of energy balance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"leptin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leptin is a hormone produced primarily by adipose (fat) tissue that acts as a long-term regulator of energy balance.\n\nWhen fat stores increase, leptin levels rise and signal the hypothalamus in the brain to suppress appetite (decrease the urge to eat) and boost metabolism and physical activity. This combination successfully drives the body toward a negative energy balance to burn off excess stored fat.\n\n• ghrelin: The \"hunger hormone\" produced mainly by the stomach. Its levels rise when the stomach is empty, signaling the brain to increase the urge to eat and reduce energy expenditure (promoting a positive energy balance).\n• adiponectin: Another hormone secreted by fat cells that helps regulate glucose levels and fatty acid breakdown while improving insulin sensitivity, but it does not directly drive the specific appetite-suppression and activity-boosting negative energy loop that leptin does.\n• insulin: Secreted by the pancreas primarily to lower blood glucose by shifting it into cells. While it can act as a minor central satiety signal, its primary physiological role is nutrient storage and carbohydrate metabolism.","whyWrongChoices":"Alternative options: ghrelin, adiponectin, insulin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the body’s magnesium is found mostly in the::::', 'the body’s magnesium is found mostly in the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An adult human body contains roughly 25 grams of magnesium, and the vast majority (about 50% to 60%) is stored directly within the bones. The skeleton acts as a massive reservoir for magnesium, with part of it bound to the bone crystal surface where it can be readily drawn out into the blood if dietary intake drops.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bones\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An adult human body contains roughly 25 grams of magnesium, and the vast majority (about 50% to 60%) is stored directly within the bones. The skeleton acts as a massive reservoir for magnesium, with part of it bound to the bone crystal surface where it can be readily drawn out into the blood if dietary intake drops.\n\nMost of the remaining magnesium is found within soft tissues, split between the skeletal muscles (around 20% to 30%) and other metabolic organs.\n\n• Nerves: While magnesium is absolutely critical for nerve impulse transmission and blocking neuromuscular excitability, nervous tissue holds only a very small percentage of the body''s total supply.\n• Muscles: Skeletal muscle is the second-largest pool of magnesium in the body, but it is still vastly outpaced by the volume stored in bone tissue.\n• Extracellular fluids: Less than 1% of the body''s total magnesium circulates within the extracellular fluid and blood serum. Because blood levels are tightly regulated at the expense of tissue stores, blood tests often fail to reflect a true total-body magnesium deficiency.","whyWrongChoices":"Alternative options: extracellular fluids, nerves, muscles"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the precursor of arginine which becomes indispensable in conditions of trauma is::::glutamate', 'the precursor of arginine which becomes indispensable in conditions of trauma is:', 'glutamate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the human body, glutamate (derived from glutamine in the intestinal-renal axis) serves as the primary metabolic precursor for the synthesis of arginine. Glutamate is converted into ornithine, which then enters the urea cycle to be synthesized into citrulline, argininosuccinate, and finally, arginine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glutamate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the human body, glutamate (derived from glutamine in the intestinal-renal axis) serves as the primary metabolic precursor for the synthesis of arginine. Glutamate is converted into ornithine, which then enters the urea cycle to be synthesized into citrulline, argininosuccinate, and finally, arginine.\n\nWhile healthy adults can normally synthesize enough arginine internally to meet daily maintenance demands, severe physical trauma, major burns, or sepsis completely exhausts the body''s natural manufacturing capacity. Under these high-stress hypermetabolic states, the rate of internal arginine production from its glutamate pathway falls short of the massive demands needed for wound healing (proline synthesis), cellular immune function (T-cell support), and vascular tone (nitric oxide generation). Therefore, arginine transforms into a conditionally indispensable (essential) amino acid that must be supplied directly through the clinical diet or specialized formula.\n\n• Phenylalanine: An indispensable amino acid that acts as the primary precursor for tyrosine, not arginine.\n• Methionine: An indispensable sulfur-containing amino acid that serves as the precursor for cysteine, not arginine.\n• Serine: A dispensable amino acid synthesized from 3-phosphoglycerate (a glycolytic intermediate) that functions primarily in glycine and cysteine pathways.","whyWrongChoices":"Alternative options: serine, phenylalanine, methionine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nonsteroidal anti-inflammatory drugs suppress inflammatory processes by::::inhibiting eicosanoid synthesis', 'nonsteroidal anti-inflammatory drugs suppress inflammatory processes by:', 'inhibiting eicosanoid synthesis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nonsteroidal anti-inflammatory drugs (NSAIDs) function primarily by inhibiting cyclooxygenase (COX-1 and COX-2) enzymes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"inhibiting eicosanoid synthesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nonsteroidal anti-inflammatory drugs (NSAIDs) function primarily by inhibiting cyclooxygenase (COX-1 and COX-2) enzymes.\n\nThese COX enzymes are responsible for metabolizing arachidonic acid (an omega-6 fatty acid) into prostaglandins and thromboxanes, which are key lipid signaling molecules collectively known as eicosanoids.\n\nBy blocking COX activity, NSAIDs arrest the downstream synthesis of these proinflammatory eicosanoids, thereby reducing pain, fever, and swelling.","whyWrongChoices":"Alternative options: interfering with histamine secretion, impairing the actions of certain cytokines, inhibiting the absorption of omega-6 fatty acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the precursor of arginine which becomes indispensable in conditions of trauma is::::', 'the precursor of arginine which becomes indispensable in conditions of trauma is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the human body, glutamate (derived from glutamine in the intestinal-renal axis) serves as the primary metabolic precursor for the synthesis of arginine. Glutamate is converted into ornithine, which then enters the urea cycle to be synthesized into citrulline, argininosuccinate, and finally, arginine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glutamate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the human body, glutamate (derived from glutamine in the intestinal-renal axis) serves as the primary metabolic precursor for the synthesis of arginine. Glutamate is converted into ornithine, which then enters the urea cycle to be synthesized into citrulline, argininosuccinate, and finally, arginine.\n\nWhile healthy adults can normally synthesize enough arginine internally to meet daily maintenance demands, severe physical trauma, major burns, or sepsis completely exhausts the body''s natural manufacturing capacity. Under these high-stress hypermetabolic states, the rate of internal arginine production from its glutamate pathway falls short of the massive demands needed for wound healing (proline synthesis), cellular immune function (T-cell support), and vascular tone (nitric oxide generation). Therefore, arginine transforms into a conditionally indispensable (essential) amino acid that must be supplied directly through the clinical diet or specialized formula.\n\n• Phenylalanine: An indispensable amino acid that acts as the primary precursor for tyrosine, not arginine.\n• Methionine: An indispensable sulfur-containing amino acid that serves as the precursor for cysteine, not arginine.\n• Serine: A dispensable amino acid synthesized from 3-phosphoglycerate (a glycolytic intermediate) that functions primarily in glycine and cysteine pathways.","whyWrongChoices":"Alternative options: serine, phenylalanine, methionine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what should be her daily fluid intake?:::3 liters', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what should be her daily fluid intake?', '3 liters', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The patient has a significantly elevated uric acid level (400 µmol/L) and is actively experiencing symptomatic gouty attacks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3 liters\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The patient has a significantly elevated uric acid level (400 µmol/L) and is actively experiencing symptomatic gouty attacks.\n\nIn medical nutrition therapy (MNT) for hyperuricemia and gout, increasing fluid intake is a primary non-pharmacological strategy. Drinking 3 liters of water per day (approximately 12 to 14 cups) is the standard clinical recommendation to help dilute the concentration of uric acid in the blood and continuously flush out uric acid crystals through the kidneys.\n\nThe patient also complains of low back pains, which are classic clinical warnings of crystalluria or microscopic uric acid stone formation in the renal tract. Forcing a fluid target of 3 liters ensures high urine output, which reduces the saturation of urate in the kidneys and directly prevents the precipitation of painful uric acid calculi (stones).\n\n• 4 liters / 5 liters: While staying well-hydrated is crucial, pushing a patient''s daily baseline up to 4 or 5 liters is excessively high for standard therapeutic maintenance and can unnecessary strain the kidneys or risk electrolyte imbalances like hyponatremia unless a severe acute toxic state is being aggressively managed in a hospital.\n• 2 liters: This is the standard fluid recommendation (about 8 cups) for average, healthy adults. It is insufficient for a patient actively experiencing gouty attacks and potential renal stone pains, as it does not provide the extra volumetric flushing capacity required to lower high serum uric acid concentrations.","whyWrongChoices":"Alternative options: 2 liters, 4 liters, 5 liters"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what should be her daily fluid intake?:::', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what should be her daily fluid intake?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The patient has a significantly elevated uric acid level (400 µmol/L) and is actively experiencing symptomatic gouty attacks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3 liters\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The patient has a significantly elevated uric acid level (400 µmol/L) and is actively experiencing symptomatic gouty attacks.\n\nIn medical nutrition therapy (MNT) for hyperuricemia and gout, increasing fluid intake is a primary non-pharmacological strategy. Drinking 3 liters of water per day (approximately 12 to 14 cups) is the standard clinical recommendation to help dilute the concentration of uric acid in the blood and continuously flush out uric acid crystals through the kidneys.\n\nThe patient also complains of low back pains, which are classic clinical warnings of crystalluria or microscopic uric acid stone formation in the renal tract. Forcing a fluid target of 3 liters ensures high urine output, which reduces the saturation of urate in the kidneys and directly prevents the precipitation of painful uric acid calculi (stones).\n\n• 4 liters / 5 liters: While staying well-hydrated is crucial, pushing a patient''s daily baseline up to 4 or 5 liters is excessively high for standard therapeutic maintenance and can unnecessary strain the kidneys or risk electrolyte imbalances like hyponatremia unless a severe acute toxic state is being aggressively managed in a hospital.\n• 2 liters: This is the standard fluid recommendation (about 8 cups) for average, healthy adults. It is insufficient for a patient actively experiencing gouty attacks and potential renal stone pains, as it does not provide the extra volumetric flushing capacity required to lower high serum uric acid concentrations.","whyWrongChoices":"Alternative options: 2 liters, 4 liters, 5 liters"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the largest controllable cost incurred in a foodservice unit is::::food', 'the largest controllable cost incurred in a foodservice unit is:', 'Food', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food cost is the percentage of total sales spent onf food products. This usually ranges from 40-45% of all the costs and it under the control of the owner/manager.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food cost is the percentage of total sales spent onf food products. This usually ranges from 40-45% of all the costs and it under the control of the owner/manager.","whyWrongChoices":"Alternative options: Labor, Operation, Utilities"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamin k deficiency is frequently drug-induced. which of the following drugs might be associated with this deficiency? 1. antibiotics 2. mineral oil 3. diuretics 4. anticoagulants:::1, 2, 4 only', 'vitamin k deficiency is frequently drug-induced. which of the following drugs might be associated with this deficiency? 1. antibiotics 2. mineral oil 3. diuretics 4. anticoagulants', '1, 2, 4 only', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Antibiotics: A large portion of the body''s vitamin K is synthesized by beneficial bacteria residing in the gut. Broad-spectrum antibiotics can destroy these bacteria, drastically reducing natural vitamin K production.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1, 2, 4 only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Antibiotics: A large portion of the body''s vitamin K is synthesized by beneficial bacteria residing in the gut. Broad-spectrum antibiotics can destroy these bacteria, drastically reducing natural vitamin K production.\n\n2. Mineral oil: Because vitamin K is a fat-soluble vitamin, it requires lipids to be absorbed properly. Mineral oil acts as a non-absorbable laxative that coats the intestines and dissolves fat-soluble vitamins (A, D, E, and K), carrying them out of the body in stool before they can be absorbed.\n\n4. Anticoagulants: Medications like warfarin are vitamin K antagonists. They directly block the enzyme mechanism responsible for recycling vitamin K in the liver, leading to a functional vitamin K deficiency that prevents blood clotting factors from activating.\n\n• 3. Diuretics: These medications increase urine output and primarily affect water-soluble minerals and electrolytes (like potassium, sodium, and magnesium) rather than the absorption or metabolism of fat-soluble vitamins like vitamin K.","whyWrongChoices":"Alternative options: 1 & 2 only, 1, 3, 4 only, 1, 2, 3 only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamin k deficiency is frequently drug-induced. which of the following drugs might be associated with this deficiency? 1. antibiotics 2. mineral oil 3. diuretics 4. anticoagulants:::', 'vitamin k deficiency is frequently drug-induced. which of the following drugs might be associated with this deficiency? 1. antibiotics 2. mineral oil 3. diuretics 4. anticoagulants', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Antibiotics: A large portion of the body''s vitamin K is synthesized by beneficial bacteria residing in the gut. Broad-spectrum antibiotics can destroy these bacteria, drastically reducing natural vitamin K production.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1, 2, 4 only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Antibiotics: A large portion of the body''s vitamin K is synthesized by beneficial bacteria residing in the gut. Broad-spectrum antibiotics can destroy these bacteria, drastically reducing natural vitamin K production.\n\n2. Mineral oil: Because vitamin K is a fat-soluble vitamin, it requires lipids to be absorbed properly. Mineral oil acts as a non-absorbable laxative that coats the intestines and dissolves fat-soluble vitamins (A, D, E, and K), carrying them out of the body in stool before they can be absorbed.\n\n4. Anticoagulants: Medications like warfarin are vitamin K antagonists. They directly block the enzyme mechanism responsible for recycling vitamin K in the liver, leading to a functional vitamin K deficiency that prevents blood clotting factors from activating.\n\n• 3. Diuretics: These medications increase urine output and primarily affect water-soluble minerals and electrolytes (like potassium, sodium, and magnesium) rather than the absorption or metabolism of fat-soluble vitamins like vitamin K.","whyWrongChoices":"Alternative options: 1 & 2 only, 1, 3, 4 only, 1, 2, 3 only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the primary risk factor in cases of fatty liver that is not related to excessive alcohol intake is::::insulin resistance', 'the primary risk factor in cases of fatty liver that is not related to excessive alcohol intake is:', 'insulin resistance', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In cases of fatty liver disease that are completely unrelated to excessive alcohol intake (traditionally called Nonalcoholic Fatty Liver Disease or NAFLD, now known as Metabolic Dysfunction-Associated Steatotic Liver Disease or MASLD), insulin resistance serves as the primary, defining pathophysiological risk factor.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"insulin resistance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In cases of fatty liver disease that are completely unrelated to excessive alcohol intake (traditionally called Nonalcoholic Fatty Liver Disease or NAFLD, now known as Metabolic Dysfunction-Associated Steatotic Liver Disease or MASLD), insulin resistance serves as the primary, defining pathophysiological risk factor.\n\nWhen a patient develops insulin resistance, their adipose (fat) tissue stops responding properly to the anti-lipolytic effects of insulin. This triggers an uncontrolled breakdown of stored peripheral fats, flooding the bloodstream with a massive surge of free fatty acids. The liver absorbs these excess fatty acids but cannot process or export them quickly enough, causing them to accumulate internally as triglycerides. Insulin resistance also promotes de novo lipogenesis (the liver making its own fat from circulating sugars), compounding the problem.\n\n• High-protein diet: Following a high-protein diet does not cause fat accumulation in liver cells. In fact, adequate protein intake is necessary to supply the amino acids needed to build lipoproteins (like VLDL) that safely export fat out of the liver.\n• Use of illicit drugs: While certain toxins and pharmaceuticals can induce specific patterns of liver injury or acute steatosis, they represent specialized secondary causes rather than the primary, population-wide driver of metabolic fatty liver disease.\n• High-fat diet: While an unmanaged, calorie-dense high-fat diet can contribute to overall obesity (which goes hand-in-hand with liver fat), dietary fat intake alone is not the definitive core driver. The true culprit is the systemic metabolic failure of insulin resistance, which traps both dietary fats and converted carbohydrates inside the liver cells.","whyWrongChoices":"Alternative options: a high-protein diet, use of illicit drugs, a high-fat diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the primary risk factor in cases of fatty liver that is not related to excessive alcohol intake is::::', 'the primary risk factor in cases of fatty liver that is not related to excessive alcohol intake is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In cases of fatty liver disease that are completely unrelated to excessive alcohol intake (traditionally called Nonalcoholic Fatty Liver Disease or NAFLD, now known as Metabolic Dysfunction-Associated Steatotic Liver Disease or MASLD), insulin resistance serves as the primary, defining pathophysiological risk factor.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"insulin resistance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In cases of fatty liver disease that are completely unrelated to excessive alcohol intake (traditionally called Nonalcoholic Fatty Liver Disease or NAFLD, now known as Metabolic Dysfunction-Associated Steatotic Liver Disease or MASLD), insulin resistance serves as the primary, defining pathophysiological risk factor.\n\nWhen a patient develops insulin resistance, their adipose (fat) tissue stops responding properly to the anti-lipolytic effects of insulin. This triggers an uncontrolled breakdown of stored peripheral fats, flooding the bloodstream with a massive surge of free fatty acids. The liver absorbs these excess fatty acids but cannot process or export them quickly enough, causing them to accumulate internally as triglycerides. Insulin resistance also promotes de novo lipogenesis (the liver making its own fat from circulating sugars), compounding the problem.\n\n• High-protein diet: Following a high-protein diet does not cause fat accumulation in liver cells. In fact, adequate protein intake is necessary to supply the amino acids needed to build lipoproteins (like VLDL) that safely export fat out of the liver.\n• Use of illicit drugs: While certain toxins and pharmaceuticals can induce specific patterns of liver injury or acute steatosis, they represent specialized secondary causes rather than the primary, population-wide driver of metabolic fatty liver disease.\n• High-fat diet: While an unmanaged, calorie-dense high-fat diet can contribute to overall obesity (which goes hand-in-hand with liver fat), dietary fat intake alone is not the definitive core driver. The true culprit is the systemic metabolic failure of insulin resistance, which traps both dietary fats and converted carbohydrates inside the liver cells.","whyWrongChoices":"Alternative options: a high-protein diet, use of illicit drugs, a high-fat diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:primary causes of peptic ulcer except::::spicy foods', 'primary causes of peptic ulcer except:', 'spicy foods', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While it is a widely held belief that eating highly spicy foods can erode the stomach lining and cause ulcers, comprehensive clinical research has proven that they do not cause peptic ulcers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"spicy foods\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While it is a widely held belief that eating highly spicy foods can erode the stomach lining and cause ulcers, comprehensive clinical research has proven that they do not cause peptic ulcers.\n\nSpicy foods can irritate an already existing ulcer flare-up, increase acid reflux sensations, or exacerbate abdominal discomfort, but they lack the physiological capacity to initiate the actual open sores or ulcerations on their own.\n\n• Gastritis: Chronic inflammation of the stomach lining (gastritis) directly weakens the protective mucosal barrier over time, leaving the tissue vulnerable to auto-digestion by harsh stomach acids and pepsin, which frequently progresses into an ulcer.\n• H. pylori infection: Helicobacter pylori is a spiral bacterium that colonizes the mucosal layer of the stomach. It secretes enzymes (like urease) and causes localized inflammatory responses that physically degrade the stomach''s protective mucus coat, serving as the leading global biological cause of peptic ulcer disease.\n• Aspirins & other NSAIDs: Nonsteroidal anti-inflammatory drugs (NSAIDs) chemically inhibit cyclooxygenase (COX) enzymes, which drastically reduces the body''s synthesis of systemic prostaglandins. Since prostaglandins are directly responsible for producing the stomach''s protective mucus layer and maintaining healthy mucosal blood flow, prolonged NSAID use leaves the stomach unprotected against its own digestive juices.","whyWrongChoices":"Alternative options: gastritis, aspirins & other NSAIDs, pylori infection"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:primary causes of peptic ulcer except::::', 'primary causes of peptic ulcer except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While it is a widely held belief that eating highly spicy foods can erode the stomach lining and cause ulcers, comprehensive clinical research has proven that they do not cause peptic ulcers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"spicy foods\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While it is a widely held belief that eating highly spicy foods can erode the stomach lining and cause ulcers, comprehensive clinical research has proven that they do not cause peptic ulcers.\n\nSpicy foods can irritate an already existing ulcer flare-up, increase acid reflux sensations, or exacerbate abdominal discomfort, but they lack the physiological capacity to initiate the actual open sores or ulcerations on their own.\n\n• Gastritis: Chronic inflammation of the stomach lining (gastritis) directly weakens the protective mucosal barrier over time, leaving the tissue vulnerable to auto-digestion by harsh stomach acids and pepsin, which frequently progresses into an ulcer.\n• H. pylori infection: Helicobacter pylori is a spiral bacterium that colonizes the mucosal layer of the stomach. It secretes enzymes (like urease) and causes localized inflammatory responses that physically degrade the stomach''s protective mucus coat, serving as the leading global biological cause of peptic ulcer disease.\n• Aspirins & other NSAIDs: Nonsteroidal anti-inflammatory drugs (NSAIDs) chemically inhibit cyclooxygenase (COX) enzymes, which drastically reduces the body''s synthesis of systemic prostaglandins. Since prostaglandins are directly responsible for producing the stomach''s protective mucus layer and maintaining healthy mucosal blood flow, prolonged NSAID use leaves the stomach unprotected against its own digestive juices.","whyWrongChoices":"Alternative options: gastritis, aspirins & other NSAIDs, pylori infection"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:triglyceride levels of patients with mild hypertriglyceridemia may be improved by::::limiting their intake of refined carbohydrates', 'triglyceride levels of patients with mild hypertriglyceridemia may be improved by:', 'limiting their intake of refined carbohydrates', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a person consumes an excess of refined carbohydrates (such as white sugar, high-fructose corn syrup, white flour, and sugary beverages), the liver rapidly processes the surging influx of simple sugars.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"limiting their intake of refined carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a person consumes an excess of refined carbohydrates (such as white sugar, high-fructose corn syrup, white flour, and sugary beverages), the liver rapidly processes the surging influx of simple sugars.\n\nThrough a metabolic process called de novo lipogenesis, the liver converts these excess carbohydrates directly into fatty acids, which are then packaged into VLDL (very-low-density lipoprotein) particles as triglyceride levels. Limiting refined carbohydrates and replacing them with complex, high-fiber options is the most powerful and direct dietary intervention for dropping serum triglycerides back into a healthy range.","whyWrongChoices":"Alternative options: reducing their cholesterol intake, consuming moderate amounts of alcohol, reducing their sodium intake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are purely ketogenic amino acids::::', 'these are purely ketogenic amino acids:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leucine and Lysine are purely ketogenic amino acids that can be catabolized to form ketone bodies and yield acetyl CoA or acetoacetate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Leucine and Lysine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leucine and Lysine are purely ketogenic amino acids that can be catabolized to form ketone bodies and yield acetyl CoA or acetoacetate.","whyWrongChoices":"Alternative options: Cysteine and Arginine, Leucine and Alanine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:triglyceride levels of patients with mild hypertriglyceridemia may be improved by::::', 'triglyceride levels of patients with mild hypertriglyceridemia may be improved by:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a person consumes an excess of refined carbohydrates (such as white sugar, high-fructose corn syrup, white flour, and sugary beverages), the liver rapidly processes the surging influx of simple sugars.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"limiting their intake of refined carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a person consumes an excess of refined carbohydrates (such as white sugar, high-fructose corn syrup, white flour, and sugary beverages), the liver rapidly processes the surging influx of simple sugars.\n\nThrough a metabolic process called de novo lipogenesis, the liver converts these excess carbohydrates directly into fatty acids, which are then packaged into VLDL (very-low-density lipoprotein) particles as triglyceride levels. Limiting refined carbohydrates and replacing them with complex, high-fiber options is the most powerful and direct dietary intervention for dropping serum triglycerides back into a healthy range.","whyWrongChoices":"Alternative options: reducing their cholesterol intake, consuming moderate amounts of alcohol, reducing their sodium intake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best level of fat?:::15 -20% of ter', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best level of fat?', '15 -20% of TER', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This patient presents with multiple critical metabolic disorders—poorly controlled diabetes, obesity, hyperuricemia (gout), and severe hypercholesterolemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"15 -20% of TER\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This patient presents with multiple critical metabolic disorders—poorly controlled diabetes, obesity, hyperuricemia (gout), and severe hypercholesterolemia.\n\nIn standard board exam matrices, when a diabetic patient presents with elevated blood cholesterol levels, clinical guidelines prioritize managing cardiovascular risk. Restricting fat intake to a lower proportion of Total Energy Requirement (TER) assists in reducing saturated fat and dietary cholesterol. This therapeutic restriction helps address circulating blood lipids and manage obesity, while carbohydrate quality is managed separately to stabilize blood sugar.","whyWrongChoices":"Alternative options: 25- 35% of TER, 30-35% of TER, 20-25% of TER"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 7-year-old child is overweight by 40 lbs. his pediatrician advised the mother to see a nutritionist-dietitian for weight loss. what would you do?:::advise the mother to maintain her child’s weight.', 'a 7-year-old child is overweight by 40 lbs. his pediatrician advised the mother to see a nutritionist-dietitian for weight loss. what would you do?', 'Advise the mother to maintain her child’s weight.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In pediatric nutrition and weight management, the primary goal for a growing 7-year-old child who is overweight or moderately obese is weight maintenance or stabilization, rather than active weight loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Advise the mother to maintain her child’s weight.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In pediatric nutrition and weight management, the primary goal for a growing 7-year-old child who is overweight or moderately obese is weight maintenance or stabilization, rather than active weight loss.\n\nBecause a 7-year-old is undergoing rapid skeletal development and heights spurts, maintaining their current weight allows them to naturally \"grow into\" their weight over the next few years, which steadily lowers their Body Mass Index (BMI).","whyWrongChoices":"Alternative options: Tell the mother to come back when the child is 10 years old., As the mother to cut out all the “junk food” only., Put the child on a weight loss program with mild calorie restriction."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 7-year-old child is overweight by 40 lbs. his pediatrician advised the mother to see a nutritionist-dietitian for weight loss. what would you do?:::', 'a 7-year-old child is overweight by 40 lbs. his pediatrician advised the mother to see a nutritionist-dietitian for weight loss. what would you do?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In pediatric nutrition and weight management, the primary goal for a growing 7-year-old child who is overweight or moderately obese is weight maintenance or stabilization, rather than active weight loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Advise the mother to maintain her child’s weight.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In pediatric nutrition and weight management, the primary goal for a growing 7-year-old child who is overweight or moderately obese is weight maintenance or stabilization, rather than active weight loss.\n\nBecause a 7-year-old is undergoing rapid skeletal development and heights spurts, maintaining their current weight allows them to naturally \"grow into\" their weight over the next few years, which steadily lowers their Body Mass Index (BMI).","whyWrongChoices":"Alternative options: Tell the mother to come back when the child is 10 years old., As the mother to cut out all the “junk food” only., Put the child on a weight loss program with mild calorie restriction."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the best protein allowance for severely malnourished children is::::4 g/kg dbw', 'the best protein allowance for severely malnourished children is:', '4 g/kg DBW', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severely malnourished children have vastly elevated protein and energy requirements to support tissue repair and catch-up growth. While a child needs significant protein to reverse wasting, the allowance must be managed precisely.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4 g/kg DBW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severely malnourished children have vastly elevated protein and energy requirements to support tissue repair and catch-up growth. While a child needs significant protein to reverse wasting, the allowance must be managed precisely.\n\n\t• In the Initial/Stabilization phase, protein is restricted to 1 to 1.5 g/kg to prevent refeeding syndrome and avoid overwhelming the child''s compromised liver and kidneys.\n\t• In the Rehabilitation/Catch-up phase, the allowance is gradually escalated to an optimal level of 3 to 4 g/kg of Desired Body Weight (DBW) (and up to 5 g/kg under specific clinical parameters) to maximize rapid cellular synthesis. Because options vary by textbooks, 3 g/kg DBW represents the safe, universally established target threshold for rebuilding lean body mass without risking metabolic overload.","whyWrongChoices":"Alternative options: 3 g/kg DBW, 5 g/kg DBW, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the best protein allowance for severely malnourished children is::::', 'the best protein allowance for severely malnourished children is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severely malnourished children have vastly elevated protein and energy requirements to support tissue repair and catch-up growth. While a child needs significant protein to reverse wasting, the allowance must be managed precisely.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4 g/kg DBW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severely malnourished children have vastly elevated protein and energy requirements to support tissue repair and catch-up growth. While a child needs significant protein to reverse wasting, the allowance must be managed precisely.\n\n\t• In the Initial/Stabilization phase, protein is restricted to 1 to 1.5 g/kg to prevent refeeding syndrome and avoid overwhelming the child''s compromised liver and kidneys.\n\t• In the Rehabilitation/Catch-up phase, the allowance is gradually escalated to an optimal level of 3 to 4 g/kg of Desired Body Weight (DBW) (and up to 5 g/kg under specific clinical parameters) to maximize rapid cellular synthesis. Because options vary by textbooks, 3 g/kg DBW represents the safe, universally established target threshold for rebuilding lean body mass without risking metabolic overload.","whyWrongChoices":"Alternative options: 3 g/kg DBW, 5 g/kg DBW, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in foodservice facilities and layout, supporting services include the following, except::::none of the above', 'in foodservice facilities and layout, supporting services include the following, except:', 'None of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"It includes all plus an area for steam hose use to wash and sanitize carts, etc.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"It includes all plus an area for steam hose use to wash and sanitize carts, etc.","whyWrongChoices":"Alternative options: Office, Janitor''s closet/storage, Trash and waste storage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the body stores energy for future use in::::triglycerides', 'the body stores energy for future use in:', 'triglycerides', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Adipose tissue plays a fundamental role in maintaining long-term energy balance by storing concentrated energy in the form of triglycerides (fats).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"triglycerides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Adipose tissue plays a fundamental role in maintaining long-term energy balance by storing concentrated energy in the form of triglycerides (fats).\n\nTriglycerides provide a highly concentrated fuel source yielding 9 kcal/g, making them the most efficient and virtually unlimited way for the body to store excess calories for future energy needs.\n\n• Proteins: While amino acids from proteins can be broken down for energy during late prolonged starvation, the primary physiological role of proteins is structural and functional (building tissues and machinery); they are not stored for the dedicated purpose of serving as an energy reserve.\n• Acetyl CoA & Ketone bodies: These are intermediate metabolic molecules and transient byproducts of fuel breakdown. They are utilized immediately by tissues or converted further to produce ATP, but they cannot be stored by the body for future use.","whyWrongChoices":"Alternative options: acetyl CoA, proteins, ketone bodies"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the body stores energy for future use in::::', 'the body stores energy for future use in:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Adipose tissue plays a fundamental role in maintaining long-term energy balance by storing concentrated energy in the form of triglycerides (fats).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"triglycerides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Adipose tissue plays a fundamental role in maintaining long-term energy balance by storing concentrated energy in the form of triglycerides (fats).\n\nTriglycerides provide a highly concentrated fuel source yielding 9 kcal/g, making them the most efficient and virtually unlimited way for the body to store excess calories for future energy needs.\n\n• Proteins: While amino acids from proteins can be broken down for energy during late prolonged starvation, the primary physiological role of proteins is structural and functional (building tissues and machinery); they are not stored for the dedicated purpose of serving as an energy reserve.\n• Acetyl CoA & Ketone bodies: These are intermediate metabolic molecules and transient byproducts of fuel breakdown. They are utilized immediately by tissues or converted further to produce ATP, but they cannot be stored by the body for future use.","whyWrongChoices":"Alternative options: acetyl CoA, proteins, ketone bodies"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best protein requirement?:::', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best protein requirement?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Calculate the Desirable Body Weight (DBW):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"55 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Calculate the Desirable Body Weight (DBW):\n\t• Convert height to centimeters: 5 feet 4 inches = 64 inches.\n\t• 64 inches x 2.54 cm/inch = 162.56 cm\n\t• Use Tannhauser’s Method (the standard method utilized in Philippine board exams):\n\t\t• DBW (kg) = (Height in cm - 100) - 10%\n\t\t• Base weight = 162.56 - 100 = 62.56 kg\n\t\t• Deduct 10%: 62.56 - 6.25 = 56.31 kg\n\t• Rounding off the DBW gives approximately 55 kg.\n\n2. Determine the Protein Requirement:\n\t• For an adult with diabetes and normal renal function, the standard nutritional care plan uses a baseline allowance of 1.0 gram of protein per kilogram of DBW per day.\n\t• Total Protein Required = 55 kg DBW x 1.0 g/kg = 55 grams\n\nBecause her blood work reveals elevated uric acid (400 mmol/L) and she experiences gouty attacks, keeping the protein requirement at a controlled, standard adult level of 1.0 g/kg (rather than high-protein or upper-range clinical levels) helps manage purine intake while protecting kidney health.","whyWrongChoices":"Alternative options: 50 g, 65 g, 60 g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nonsteroidal anti-inflammatory drugs suppress inflammatory processes by::::', 'nonsteroidal anti-inflammatory drugs suppress inflammatory processes by:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nonsteroidal anti-inflammatory drugs (NSAIDs) function primarily by inhibiting cyclooxygenase (COX-1 and COX-2) enzymes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"inhibiting eicosanoid synthesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nonsteroidal anti-inflammatory drugs (NSAIDs) function primarily by inhibiting cyclooxygenase (COX-1 and COX-2) enzymes.\n\nThese COX enzymes are responsible for metabolizing arachidonic acid (an omega-6 fatty acid) into prostaglandins and thromboxanes, which are key lipid signaling molecules collectively known as eicosanoids.\n\nBy blocking COX activity, NSAIDs arrest the downstream synthesis of these proinflammatory eicosanoids, thereby reducing pain, fever, and swelling.","whyWrongChoices":"Alternative options: interfering with histamine secretion, impairing the actions of certain cytokines, inhibiting the absorption of omega-6 fatty acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the preferred preoperative diet for abdominal surgery.:::low residue liquid', 'it is the preferred preoperative diet for abdominal surgery.', 'low residue liquid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In older Philippine dietetic manuals and classic Nutritional Biochemistry test blueprints, a clear liquid diet is officially sub-classified as the most extreme form of a low-residue diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"low residue liquid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In older Philippine dietetic manuals and classic Nutritional Biochemistry test blueprints, a clear liquid diet is officially sub-classified as the most extreme form of a low-residue diet.\n\n• Under this strict theoretical framework, the term \"clear liquid\" simply describes the physical appearance of the food (transparent, liquid at room temperature).\n• The term \"low residue\" describes the actual physiological purpose of the diet—which is to leave zero undigested material (residue) in the bowel to ensure the surgical field is clean.\n\nBecause \"low residue\" describes the primary medical objective for an abdominal surgery, the test creators view it as the broader, more scientifically descriptive choice for this exact question layout.","whyWrongChoices":"Alternative options: full liquid, none of the above, clear liquid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the preferred preoperative diet for abdominal surgery.:::', 'it is the preferred preoperative diet for abdominal surgery.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In older Philippine dietetic manuals and classic Nutritional Biochemistry test blueprints, a clear liquid diet is officially sub-classified as the most extreme form of a low-residue diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"low residue liquid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In older Philippine dietetic manuals and classic Nutritional Biochemistry test blueprints, a clear liquid diet is officially sub-classified as the most extreme form of a low-residue diet.\n\n• Under this strict theoretical framework, the term \"clear liquid\" simply describes the physical appearance of the food (transparent, liquid at room temperature).\n• The term \"low residue\" describes the actual physiological purpose of the diet—which is to leave zero undigested material (residue) in the bowel to ensure the surgical field is clean.\n\nBecause \"low residue\" describes the primary medical objective for an abdominal surgery, the test creators view it as the broader, more scientifically descriptive choice for this exact question layout.","whyWrongChoices":"Alternative options: full liquid, none of the above, clear liquid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when metabolically-stressed patients are given diets with excessive calories, this could result in overfeeding, excess carbon dioxide production, and other related complications such as::::respiratory insufficiency', 'when metabolically-stressed patients are given diets with excessive calories, this could result in overfeeding, excess carbon dioxide production, and other related complications such as:', 'respiratory insufficiency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When metabolically stressed or critically ill patients receive excessive calories (particularly from carbohydrates), the body''s rate of glucose oxidation accelerates. This dramatically spikes carbon dioxide (CO₂) production.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"respiratory insufficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When metabolically stressed or critically ill patients receive excessive calories (particularly from carbohydrates), the body''s rate of glucose oxidation accelerates. This dramatically spikes carbon dioxide (CO₂) production.\n\nTo clear this excess CO₂, the lungs are forced to work much harder by increasing minute ventilation (breathing faster and deeper). In a metabolically stressed patient who may already have compromised lung function or be on a ventilator, this immense physical demand frequently leads to respiratory insufficiency and failure to wean from mechanical ventilation.\n\n• Excessive weight gain: While chronic overfeeding leads to weight gain over a long period, in an acute, metabolically stressed ICU environment, the immediate dangerous complication of aggressive hyperalimentation is respiratory and metabolic failure, not fat storage.\n• Immediate weaning from mechanical ventilation: Overfeeding does the exact opposite—it delays weaning and extends the number of days a patient requires a ventilator because their lungs are too exhausted from handling the extra CO₂.","whyWrongChoices":"Alternative options: excessive weight gain, all of the above, immediate weaning from mechanical ventilation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the body’s magnesium is found mostly in the::::bones', 'the body’s magnesium is found mostly in the:', 'bones', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An adult human body contains roughly 25 grams of magnesium, and the vast majority (about 50% to 60%) is stored directly within the bones. The skeleton acts as a massive reservoir for magnesium, with part of it bound to the bone crystal surface where it can be readily drawn out into the blood if dietary intake drops.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bones\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An adult human body contains roughly 25 grams of magnesium, and the vast majority (about 50% to 60%) is stored directly within the bones. The skeleton acts as a massive reservoir for magnesium, with part of it bound to the bone crystal surface where it can be readily drawn out into the blood if dietary intake drops.\n\nMost of the remaining magnesium is found within soft tissues, split between the skeletal muscles (around 20% to 30%) and other metabolic organs.\n\n• Nerves: While magnesium is absolutely critical for nerve impulse transmission and blocking neuromuscular excitability, nervous tissue holds only a very small percentage of the body''s total supply.\n• Muscles: Skeletal muscle is the second-largest pool of magnesium in the body, but it is still vastly outpaced by the volume stored in bone tissue.\n• Extracellular fluids: Less than 1% of the body''s total magnesium circulates within the extracellular fluid and blood serum. Because blood levels are tightly regulated at the expense of tissue stores, blood tests often fail to reflect a true total-body magnesium deficiency.","whyWrongChoices":"Alternative options: extracellular fluids, nerves, muscles"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when metabolically-stressed patients are given diets with excessive calories, this could result in overfeeding, excess carbon dioxide production, and other related complications such as::::', 'when metabolically-stressed patients are given diets with excessive calories, this could result in overfeeding, excess carbon dioxide production, and other related complications such as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When metabolically stressed or critically ill patients receive excessive calories (particularly from carbohydrates), the body''s rate of glucose oxidation accelerates. This dramatically spikes carbon dioxide (CO₂) production.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"respiratory insufficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When metabolically stressed or critically ill patients receive excessive calories (particularly from carbohydrates), the body''s rate of glucose oxidation accelerates. This dramatically spikes carbon dioxide (CO₂) production.\n\nTo clear this excess CO₂, the lungs are forced to work much harder by increasing minute ventilation (breathing faster and deeper). In a metabolically stressed patient who may already have compromised lung function or be on a ventilator, this immense physical demand frequently leads to respiratory insufficiency and failure to wean from mechanical ventilation.\n\n• Excessive weight gain: While chronic overfeeding leads to weight gain over a long period, in an acute, metabolically stressed ICU environment, the immediate dangerous complication of aggressive hyperalimentation is respiratory and metabolic failure, not fat storage.\n• Immediate weaning from mechanical ventilation: Overfeeding does the exact opposite—it delays weaning and extends the number of days a patient requires a ventilator because their lungs are too exhausted from handling the extra CO₂.","whyWrongChoices":"Alternative options: excessive weight gain, all of the above, immediate weaning from mechanical ventilation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a therapeutic diet counseling session is best given when::::', 'a therapeutic diet counseling session is best given when:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical dietetics and hospital protocols, a therapeutic diet counseling session requires the patient’s active attention, focus, and ability to comprehend new lifestyle changes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the patient is relaxed and hospitalized\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical dietetics and hospital protocols, a therapeutic diet counseling session requires the patient’s active attention, focus, and ability to comprehend new lifestyle changes.\n\nWhen a patient is relaxed and hospitalized (meaning they are past the acute, painful phase of their illness but not yet caught up in the hectic rush of leaving), they are in the best mental and physical state to absorb complex nutritional instructions, ask questions, and practice meal-planning concepts.","whyWrongChoices":"Alternative options: the patient is very sick, none of the above, the patient is being discharged"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a metabolic change that accompanies acute stress is::::muscle protein catabolism', 'a metabolic change that accompanies acute stress is:', 'muscle protein catabolism', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During acute physiological stress (such as severe trauma, major surgery, burns, or infection), the body enters a highly hypermetabolic and catabolic state.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"muscle protein catabolism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During acute physiological stress (such as severe trauma, major surgery, burns, or infection), the body enters a highly hypermetabolic and catabolic state.\n\nTo fuel vital organs and support the immune response, counter-regulatory hormones (like cortisol, epinephrine, and glucagon) are rapidly released. These hormones trigger muscle protein catabolism (the rapid breakdown of lean muscle tissue) to release amino acids into the bloodstream. The liver then uses these amino acids to create glucose via gluconeogenesis and synthesize acute-phase inflammatory proteins.\n\n• hypoglycemia: Acute stress actually causes hyperglycemia (high blood sugar), often referred to as \"stress diabetes,\" because the liver produces excess glucose while the body experiences temporary insulin resistance.\n• elevated immune response: While the immune system is activated, a prolonged or severe acute stress response typically leads to localized immune dysregulation or immunosuppression over time due to the massive release of cortisol, rather than a universally protective, sustained \"elevated\" response.\n• reduced heart & respiratory rates: Acute stress triggers the sympathetic \"fight-or-flight\" response, which heavily increases heart rate and respiratory rate to pump oxygenated blood to essential organs.","whyWrongChoices":"Alternative options: hypoglycemia, elevated immune response, reduced heart & respiratory rates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a metabolic change that accompanies acute stress is::::', 'a metabolic change that accompanies acute stress is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During acute physiological stress (such as severe trauma, major surgery, burns, or infection), the body enters a highly hypermetabolic and catabolic state.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"muscle protein catabolism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During acute physiological stress (such as severe trauma, major surgery, burns, or infection), the body enters a highly hypermetabolic and catabolic state.\n\nTo fuel vital organs and support the immune response, counter-regulatory hormones (like cortisol, epinephrine, and glucagon) are rapidly released. These hormones trigger muscle protein catabolism (the rapid breakdown of lean muscle tissue) to release amino acids into the bloodstream. The liver then uses these amino acids to create glucose via gluconeogenesis and synthesize acute-phase inflammatory proteins.\n\n• hypoglycemia: Acute stress actually causes hyperglycemia (high blood sugar), often referred to as \"stress diabetes,\" because the liver produces excess glucose while the body experiences temporary insulin resistance.\n• elevated immune response: While the immune system is activated, a prolonged or severe acute stress response typically leads to localized immune dysregulation or immunosuppression over time due to the massive release of cortisol, rather than a universally protective, sustained \"elevated\" response.\n• reduced heart & respiratory rates: Acute stress triggers the sympathetic \"fight-or-flight\" response, which heavily increases heart rate and respiratory rate to pump oxygenated blood to essential organs.","whyWrongChoices":"Alternative options: hypoglycemia, elevated immune response, reduced heart & respiratory rates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. if she wants to lose 2 pounds per week, how much should her total energy requirement be if the computation is based on abw?:::2000 kcal', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. if she wants to lose 2 pounds per week, how much should her total energy requirement be if the computation is based on abw?', '2000 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question explicitly specifies that the energy calculation must be based on her Actual Body Weight (ABW) of 86 kg. In standard clinical dietetics equations, an adult with an active daily schedule (such as a school teacher who stands and walks during lessons) combined with gym enrollment has an estimated maintenance energy factor of 35 kcal/kg of body weight:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2000 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question explicitly specifies that the energy calculation must be based on her Actual Body Weight (ABW) of 86 kg. In standard clinical dietetics equations, an adult with an active daily schedule (such as a school teacher who stands and walks during lessons) combined with gym enrollment has an estimated maintenance energy factor of 35 kcal/kg of body weight:\n\nMaintenance Calories = 86 kg x 35 kcal/kg = 3010 kcal/day\n\nTo achieve a target weight loss of 2 pounds per week, a person must establish a total weekly deficit of 7,000 calories. This breaks down to a mandatory deduction of exactly 1,000 kcal per day from their baseline maintenance requirement:\n\nTarget TER = 3010 kcal - 1000 kcal = 2010 kcal\n\nRounding this value to the nearest standard clinical prescription block yields exactly 2000 kcal.","whyWrongChoices":"Alternative options: 1900 kcal, 1500 kcal, 1000 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. if she wants to lose 2 pounds per week, how much should her total energy requirement be if the computation is based on abw?:::', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. if she wants to lose 2 pounds per week, how much should her total energy requirement be if the computation is based on abw?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question explicitly specifies that the energy calculation must be based on her Actual Body Weight (ABW) of 86 kg. In standard clinical dietetics equations, an adult with an active daily schedule (such as a school teacher who stands and walks during lessons) combined with gym enrollment has an estimated maintenance energy factor of 35 kcal/kg of body weight:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2000 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question explicitly specifies that the energy calculation must be based on her Actual Body Weight (ABW) of 86 kg. In standard clinical dietetics equations, an adult with an active daily schedule (such as a school teacher who stands and walks during lessons) combined with gym enrollment has an estimated maintenance energy factor of 35 kcal/kg of body weight:\n\nMaintenance Calories = 86 kg x 35 kcal/kg = 3010 kcal/day\n\nTo achieve a target weight loss of 2 pounds per week, a person must establish a total weekly deficit of 7,000 calories. This breaks down to a mandatory deduction of exactly 1,000 kcal per day from their baseline maintenance requirement:\n\nTarget TER = 3010 kcal - 1000 kcal = 2010 kcal\n\nRounding this value to the nearest standard clinical prescription block yields exactly 2000 kcal.","whyWrongChoices":"Alternative options: 1900 kcal, 1500 kcal, 1000 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the total protein required per day of a 7-year-old child using the npc method is::::44 g/day', 'the total protein required per day of a 7-year-old child using the npc method is:', '44 g/day', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the classic Philippine dietetic guidelines (PDRI/RDA) cite a lower baseline allowance of 1.5 g/kg/day for a 7-year-old child (yielding 33 g/day), certain academic materials and board exam question banks use an alternative upper-range protein allowance for specific clinical or pediatric calculations:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"44 g/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the classic Philippine dietetic guidelines (PDRI/RDA) cite a lower baseline allowance of 1.5 g/kg/day for a 7-year-old child (yielding 33 g/day), certain academic materials and board exam question banks use an alternative upper-range protein allowance for specific clinical or pediatric calculations:\n\n1. Desirable Body Weight (DBW):\n\t• DBW (kg) = (Age in years x 2) + 8\n\t• DBW = (7 x 2) + 8 = 22 kg\n\n2. Alternative Upper-Range Allowance:\nUsing an upper allowance boundary of 2.0 g of protein per kg of body weight for growing children under specific pediatric/clinical variations of the Non-Protein Calorie (NPC) calculation matrix:\n\t• Total Protein Required = 22 kg x 2.0 g/kg/day = 44 g/day","whyWrongChoices":"Alternative options: 35 g/day, 30 g/day, 33 g/day"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the total protein required per day of a 7-year-old child using the npc method is::::', 'the total protein required per day of a 7-year-old child using the npc method is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the classic Philippine dietetic guidelines (PDRI/RDA) cite a lower baseline allowance of 1.5 g/kg/day for a 7-year-old child (yielding 33 g/day), certain academic materials and board exam question banks use an alternative upper-range protein allowance for specific clinical or pediatric calculations:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"44 g/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the classic Philippine dietetic guidelines (PDRI/RDA) cite a lower baseline allowance of 1.5 g/kg/day for a 7-year-old child (yielding 33 g/day), certain academic materials and board exam question banks use an alternative upper-range protein allowance for specific clinical or pediatric calculations:\n\n1. Desirable Body Weight (DBW):\n\t• DBW (kg) = (Age in years x 2) + 8\n\t• DBW = (7 x 2) + 8 = 22 kg\n\n2. Alternative Upper-Range Allowance:\nUsing an upper allowance boundary of 2.0 g of protein per kg of body weight for growing children under specific pediatric/clinical variations of the Non-Protein Calorie (NPC) calculation matrix:\n\t• Total Protein Required = 22 kg x 2.0 g/kg/day = 44 g/day","whyWrongChoices":"Alternative options: 35 g/day, 30 g/day, 33 g/day"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:kidneys control ph through the following processes except::::formation of carbonic acid', 'kidneys control ph through the following processes except:', 'formation of carbonic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The formation of carbonic acid (H₂CO₃) from carbon dioxide (CO₂) and water is primarily the biochemical driving mechanism of the respiratory system''s pH regulation via the lungs and blood chemical buffers. The respiratory system adjusts breathing rates to blow off or retain CO₂, shifting carbonic acid equilibrium. The kidneys do not use the formation of carbonic acid to change systemic pH; rather, they break down or utilize bicarbonate networks to manage heavy systemic acid loads.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"formation of carbonic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The formation of carbonic acid (H₂CO₃) from carbon dioxide (CO₂) and water is primarily the biochemical driving mechanism of the respiratory system''s pH regulation via the lungs and blood chemical buffers. The respiratory system adjusts breathing rates to blow off or retain CO₂, shifting carbonic acid equilibrium. The kidneys do not use the formation of carbonic acid to change systemic pH; rather, they break down or utilize bicarbonate networks to manage heavy systemic acid loads.","whyWrongChoices":"Alternative options: synthesis of ammonia, resorption of Na ions, secretion of hydrogen ions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:kidneys control ph through the following processes except::::', 'kidneys control ph through the following processes except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The formation of carbonic acid (H₂CO₃) from carbon dioxide (CO₂) and water is primarily the biochemical driving mechanism of the respiratory system''s pH regulation via the lungs and blood chemical buffers. The respiratory system adjusts breathing rates to blow off or retain CO₂, shifting carbonic acid equilibrium. The kidneys do not use the formation of carbonic acid to change systemic pH; rather, they break down or utilize bicarbonate networks to manage heavy systemic acid loads.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"formation of carbonic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The formation of carbonic acid (H₂CO₃) from carbon dioxide (CO₂) and water is primarily the biochemical driving mechanism of the respiratory system''s pH regulation via the lungs and blood chemical buffers. The respiratory system adjusts breathing rates to blow off or retain CO₂, shifting carbonic acid equilibrium. The kidneys do not use the formation of carbonic acid to change systemic pH; rather, they break down or utilize bicarbonate networks to manage heavy systemic acid loads.","whyWrongChoices":"Alternative options: synthesis of ammonia, resorption of Na ions, secretion of hydrogen ions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best protein requirement?:::55 g', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best protein requirement?', '55 g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Calculate the Desirable Body Weight (DBW):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"55 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Calculate the Desirable Body Weight (DBW):\n\t• Convert height to centimeters: 5 feet 4 inches = 64 inches.\n\t• 64 inches x 2.54 cm/inch = 162.56 cm\n\t• Use Tannhauser’s Method (the standard method utilized in Philippine board exams):\n\t\t• DBW (kg) = (Height in cm - 100) - 10%\n\t\t• Base weight = 162.56 - 100 = 62.56 kg\n\t\t• Deduct 10%: 62.56 - 6.25 = 56.31 kg\n\t• Rounding off the DBW gives approximately 55 kg.\n\n2. Determine the Protein Requirement:\n\t• For an adult with diabetes and normal renal function, the standard nutritional care plan uses a baseline allowance of 1.0 gram of protein per kilogram of DBW per day.\n\t• Total Protein Required = 55 kg DBW x 1.0 g/kg = 55 grams\n\nBecause her blood work reveals elevated uric acid (400 mmol/L) and she experiences gouty attacks, keeping the protein requirement at a controlled, standard adult level of 1.0 g/kg (rather than high-protein or upper-range clinical levels) helps manage purine intake while protecting kidney health.","whyWrongChoices":"Alternative options: 50 g, 65 g, 60 g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refeeding syndrome can bring about a dangerous fluctuation in::::serum electrolytes', 'refeeding syndrome can bring about a dangerous fluctuation in:', 'serum electrolytes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a severely malnourished or starved patient is reintroduced to nutrition (especially carbohydrates), the sudden influx of glucose triggers a massive release of insulin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"serum electrolytes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a severely malnourished or starved patient is reintroduced to nutrition (especially carbohydrates), the sudden influx of glucose triggers a massive release of insulin.\n\nThis surge of insulin forces the body to pull large amounts of glucose along with vital electrolytes out of the bloodstream and directly into the cells.\n\nThis causes a sudden, catastrophic drop in serum electrolytes, specifically leading to severe hypophosphatemia (low phosphorus), hypokalemia (low potassium), and hypomagnesemia (low magnesium). These rapid fluctuations can cause life-threatening heart arrhythmias, respiratory failure, and neurological complications.\n\n• Blood triglyceride levels: While nutrition can affect lipids over time, the immediate, life-threatening crisis of refeeding syndrome is strictly driven by the mineral and fluid shifts in the blood, not fat molecules.\n• Serum liver enzyme levels: Liver enzymes may alter slightly during metabolic adaptation, but they do not experience the sudden, dangerous systemic fluctuations that characterize the syndrome.\n• Ketone bodies: Starvation causes high ketone production, and refeeding stops this process, but the dangerous, lethal complication of refeeding syndrome itself stems directly from the rapid drop in electrolytes.","whyWrongChoices":"Alternative options: serum liver enzyme levels, ketone bodies, blood triglyceride levels"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:examples of derived lipids except::::gangliosides', 'examples of derived lipids except:', 'gangliosides', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gangliosides are categorized as compound (or complex) lipids rather than derived lipids. Specifically, they are complex glycosphingolipids composed of a fatty acid, a sphingosine backbone, and a complex oligosaccharide chain containing one or more residues of sialic acid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"gangliosides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gangliosides are categorized as compound (or complex) lipids rather than derived lipids. Specifically, they are complex glycosphingolipids composed of a fatty acid, a sphingosine backbone, and a complex oligosaccharide chain containing one or more residues of sialic acid.\n\nDerived lipids are substances produced via the chemical hydrolysis of simple or compound lipids. They include free fatty acids, structural alcohols, hydrocarbons, fat-soluble vitamins, and sterols.\n\n• Vitamin D: A fat-soluble vitamin. Because it is a secosteroid derivative generated from lipid precursors, it is classified under the derived lipids family.\n• Cholesterol: The principal animal sterol. It lacks ester bonds but exhibits lipid-like properties and is a primary hydrolytic product/derivative of complex steroid pathways, placing it firmly in the derived lipid category.\n• Ergosterol: A plant and fungal sterol (the biological precursor to vitamin D2). Like cholesterol, it is a non-saponifiable steroid molecule classified structurally as a derived lipid.","whyWrongChoices":"Alternative options: vitamin D, ergosterol, cholesterol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:examples of derived lipids except::::', 'examples of derived lipids except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gangliosides are categorized as compound (or complex) lipids rather than derived lipids. Specifically, they are complex glycosphingolipids composed of a fatty acid, a sphingosine backbone, and a complex oligosaccharide chain containing one or more residues of sialic acid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"gangliosides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gangliosides are categorized as compound (or complex) lipids rather than derived lipids. Specifically, they are complex glycosphingolipids composed of a fatty acid, a sphingosine backbone, and a complex oligosaccharide chain containing one or more residues of sialic acid.\n\nDerived lipids are substances produced via the chemical hydrolysis of simple or compound lipids. They include free fatty acids, structural alcohols, hydrocarbons, fat-soluble vitamins, and sterols.\n\n• Vitamin D: A fat-soluble vitamin. Because it is a secosteroid derivative generated from lipid precursors, it is classified under the derived lipids family.\n• Cholesterol: The principal animal sterol. It lacks ester bonds but exhibits lipid-like properties and is a primary hydrolytic product/derivative of complex steroid pathways, placing it firmly in the derived lipid category.\n• Ergosterol: A plant and fungal sterol (the biological precursor to vitamin D2). Like cholesterol, it is a non-saponifiable steroid molecule classified structurally as a derived lipid.","whyWrongChoices":"Alternative options: vitamin D, ergosterol, cholesterol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an anorectic teenager’s health status has been progressively deteriorating. the physician has decided to tube feed her. the initial kilocaloric intake should be based on::::present body weight', 'an anorectic teenager’s health status has been progressively deteriorating. the physician has decided to tube feed her. the initial kilocaloric intake should be based on:', 'present body weight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a severely malnourished or anorectic patient whose health is progressively deteriorating, the greatest clinical danger during the initiation of nutritional support (whether oral or tube feeding) is refeeding syndrome.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"present body weight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a severely malnourished or anorectic patient whose health is progressively deteriorating, the greatest clinical danger during the initiation of nutritional support (whether oral or tube feeding) is refeeding syndrome.\n\nTo avoid fatal electrolyte shifts (such as severe hypophosphatemia, hypokalemia, and hypomagnesemia) and cardiac overload, clinical protocols dictate that you must \"start low and go slow\". The initial calorie prescription is strictly calculated using the patient''s present/actual body weight (typically starting conservatively at around 20 kcal/kg/day or lower) rather than their ideal weight. Using the ideal body weight right away would heavily overestimate their metabolic tolerance, flood their system with too many calories, and trigger refeeding complications.","whyWrongChoices":"Alternative options: ideal body weight plus 10%, tolerance, amount of weight loss"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an anorectic teenager’s health status has been progressively deteriorating. the physician has decided to tube feed her. the initial kilocaloric intake should be based on::::', 'an anorectic teenager’s health status has been progressively deteriorating. the physician has decided to tube feed her. the initial kilocaloric intake should be based on:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a severely malnourished or anorectic patient whose health is progressively deteriorating, the greatest clinical danger during the initiation of nutritional support (whether oral or tube feeding) is refeeding syndrome.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"present body weight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a severely malnourished or anorectic patient whose health is progressively deteriorating, the greatest clinical danger during the initiation of nutritional support (whether oral or tube feeding) is refeeding syndrome.\n\nTo avoid fatal electrolyte shifts (such as severe hypophosphatemia, hypokalemia, and hypomagnesemia) and cardiac overload, clinical protocols dictate that you must \"start low and go slow\". The initial calorie prescription is strictly calculated using the patient''s present/actual body weight (typically starting conservatively at around 20 kcal/kg/day or lower) rather than their ideal weight. Using the ideal body weight right away would heavily overestimate their metabolic tolerance, flood their system with too many calories, and trigger refeeding complications.","whyWrongChoices":"Alternative options: ideal body weight plus 10%, tolerance, amount of weight loss"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during the initial phase of physical exercise for non-diabetics and individuals with well-controlled diabetes, what is the primary source of fuel?:::blood glucose', 'during the initial phase of physical exercise for non-diabetics and individuals with well-controlled diabetes, what is the primary source of fuel?', 'blood glucose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard medical nutrition therapy and metabolic board exam frameworks, the focus for non-diabetics and well-controlled diabetics during exercise is heavily centered on circulating blood glucose uptake.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"blood glucose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard medical nutrition therapy and metabolic board exam frameworks, the focus for non-diabetics and well-controlled diabetics during exercise is heavily centered on circulating blood glucose uptake.\n\nDuring the initiation of physical exercise, the contracting skeletal muscle fibers increase their demand for carbohydrates. For a patient with well-controlled diabetes, tracking the movement, consumption, and balance of blood glucose is the primary clinical parameter. The body immediately accelerates the translocation of GLUT4 transporters to the muscle cell membranes to draw glucose straight out of the bloodstream to fulfill early energy requirements, making it the targeted primary marker on your exam key.\n\n• Free fatty acids: These serve as a major substrate during prolonged, lower-intensity steady-state aerobic exercise rather than the early stages of physical exertion.\n• Amino acids: Lean proteins and amino acids serve structural and enzymatic functions, contributing minimally to physical exertion energy pools unless severe starvation or glycogen depletion occurs.\n• Muscle glycogen: While muscle cells contain intracellular glycogen stores, standard board exam matrices prioritize blood glucose as the key circulating nutrient to match the management protocols for diabetes and exercise coordination.","whyWrongChoices":"Alternative options: muscle glycogen, free fatty acids, amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during the initial phase of physical exercise for non-diabetics and individuals with well-controlled diabetes, what is the primary source of fuel?:::', 'during the initial phase of physical exercise for non-diabetics and individuals with well-controlled diabetes, what is the primary source of fuel?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard medical nutrition therapy and metabolic board exam frameworks, the focus for non-diabetics and well-controlled diabetics during exercise is heavily centered on circulating blood glucose uptake.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"blood glucose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard medical nutrition therapy and metabolic board exam frameworks, the focus for non-diabetics and well-controlled diabetics during exercise is heavily centered on circulating blood glucose uptake.\n\nDuring the initiation of physical exercise, the contracting skeletal muscle fibers increase their demand for carbohydrates. For a patient with well-controlled diabetes, tracking the movement, consumption, and balance of blood glucose is the primary clinical parameter. The body immediately accelerates the translocation of GLUT4 transporters to the muscle cell membranes to draw glucose straight out of the bloodstream to fulfill early energy requirements, making it the targeted primary marker on your exam key.\n\n• Free fatty acids: These serve as a major substrate during prolonged, lower-intensity steady-state aerobic exercise rather than the early stages of physical exertion.\n• Amino acids: Lean proteins and amino acids serve structural and enzymatic functions, contributing minimally to physical exertion energy pools unless severe starvation or glycogen depletion occurs.\n• Muscle glycogen: While muscle cells contain intracellular glycogen stores, standard board exam matrices prioritize blood glucose as the key circulating nutrient to match the management protocols for diabetes and exercise coordination.","whyWrongChoices":"Alternative options: muscle glycogen, free fatty acids, amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a nonsurgical approach to gallstone treatment is::::dissolution & fragmentation', 'a nonsurgical approach to gallstone treatment is:', 'dissolution & fragmentation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dissolution therapy: This uses oral bile acid medications (such as ursodeoxycholic acid) to physically dissolve small, radiolucent cholesterol gallstones over several months.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"dissolution & fragmentation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dissolution therapy: This uses oral bile acid medications (such as ursodeoxycholic acid) to physically dissolve small, radiolucent cholesterol gallstones over several months.\n\nFragmentation (Lithotripsy): This non-surgical approach uses Extracorporeal Shock Wave Lithotripsy (ESWL). High-energy sound waves are targeted at the gallbladder to break down or fragment large stones into tiny particles. These fragments are then safely dissolved with medication or passed through the digestive tract.\n\n• Cholecystectomy: This is the surgical removal of the gallbladder, making it a surgical approach rather than a non-surgical one.\n• Weight loss: While long-term weight management helps prevent gallstone formation, rapid weight loss can actually trigger or worsen gallstones due to increased cholesterol secretion into the bile, and it does not serve as an active clinical treatment to eliminate existing stones.\n• Immunosuppressive drug therapy: Gallstones are crystallized deposits of cholesterol or bilirubin, not an autoimmune disease, so immunosuppressive medications play no role in their treatment.","whyWrongChoices":"Alternative options: weight loss, cholecystectomy, immunosuppressive drug therapy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
