INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a nonsurgical approach to gallstone treatment is::::', 'a nonsurgical approach to gallstone treatment is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dissolution therapy: This uses oral bile acid medications (such as ursodeoxycholic acid) to physically dissolve small, radiolucent cholesterol gallstones over several months.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"dissolution & fragmentation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dissolution therapy: This uses oral bile acid medications (such as ursodeoxycholic acid) to physically dissolve small, radiolucent cholesterol gallstones over several months.\n\nFragmentation (Lithotripsy): This non-surgical approach uses Extracorporeal Shock Wave Lithotripsy (ESWL). High-energy sound waves are targeted at the gallbladder to break down or fragment large stones into tiny particles. These fragments are then safely dissolved with medication or passed through the digestive tract.\n\n• Cholecystectomy: This is the surgical removal of the gallbladder, making it a surgical approach rather than a non-surgical one.\n• Weight loss: While long-term weight management helps prevent gallstone formation, rapid weight loss can actually trigger or worsen gallstones due to increased cholesterol secretion into the bile, and it does not serve as an active clinical treatment to eliminate existing stones.\n• Immunosuppressive drug therapy: Gallstones are crystallized deposits of cholesterol or bilirubin, not an autoimmune disease, so immunosuppressive medications play no role in their treatment.","whyWrongChoices":"Alternative options: weight loss, cholecystectomy, immunosuppressive drug therapy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deficiency of this micronutrient is associated with scurvy.:::', 'deficiency of this micronutrient is associated with scurvy.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Consumption of 100 mg of Vitamin C per day can increase the total body pool to a level of 1.2-2.0 g that is sufficient to protect the body from scurvy for 90 days.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Consumption of 100 mg of Vitamin C per day can increase the total body pool to a level of 1.2-2.0 g that is sufficient to protect the body from scurvy for 90 days.","whyWrongChoices":"Alternative options: Vit A, Vit B, Vit K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a reduced blood albumin level leads to::::edema', 'a reduced blood albumin level leads to:', 'edema', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Albumin is the primary protein circulating in the blood, and it is responsible for generating roughly 75% to 80% of the blood''s colloid oncotic pressure (osmotic pressure).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"edema\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Albumin is the primary protein circulating in the blood, and it is responsible for generating roughly 75% to 80% of the blood''s colloid oncotic pressure (osmotic pressure).\n\nThis oncotic pressure acts like a chemical magnet that physically holds water inside the vascular compartment, preventing it from leaking out of blood vessels.\n\nWhen blood albumin levels drop significantly (hypoalbuminemia), the oncotic pressure collapses. Without enough pressure to counterbalance the normal outward push of hydrostatic pressure, fluid readily leaks through the capillary walls and accumulates inside the surrounding interstitial tissues, leading directly to edema (swelling, particularly in the lower extremities, abdomen, or face).\n\n• Alkalosis & Acidosis: These terms describe disruptions in the body''s acid-base balance (pH levels). While albumin acts as a minor buffer in the blood, a drop in its level does not primarily drive clinical metabolic acidosis or alkalosis.\n• Dehydration: Dehydration is a total-body deficit of water. Hypoalbuminemia causes fluid to shift to the wrong places (interstitial space) rather than causing an overall loss of systemic body water.","whyWrongChoices":"Alternative options: alkalosis, acidosis, dehydration"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a reduced blood albumin level leads to::::', 'a reduced blood albumin level leads to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Albumin is the primary protein circulating in the blood, and it is responsible for generating roughly 75% to 80% of the blood''s colloid oncotic pressure (osmotic pressure).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"edema\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Albumin is the primary protein circulating in the blood, and it is responsible for generating roughly 75% to 80% of the blood''s colloid oncotic pressure (osmotic pressure).\n\nThis oncotic pressure acts like a chemical magnet that physically holds water inside the vascular compartment, preventing it from leaking out of blood vessels.\n\nWhen blood albumin levels drop significantly (hypoalbuminemia), the oncotic pressure collapses. Without enough pressure to counterbalance the normal outward push of hydrostatic pressure, fluid readily leaks through the capillary walls and accumulates inside the surrounding interstitial tissues, leading directly to edema (swelling, particularly in the lower extremities, abdomen, or face).\n\n• Alkalosis & Acidosis: These terms describe disruptions in the body''s acid-base balance (pH levels). While albumin acts as a minor buffer in the blood, a drop in its level does not primarily drive clinical metabolic acidosis or alkalosis.\n• Dehydration: Dehydration is a total-body deficit of water. Hypoalbuminemia causes fluid to shift to the wrong places (interstitial space) rather than causing an overall loss of systemic body water.","whyWrongChoices":"Alternative options: alkalosis, acidosis, dehydration"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a therapeutic diet counseling session is best given when::::the patient is relaxed and hospitalized', 'a therapeutic diet counseling session is best given when:', 'the patient is relaxed and hospitalized', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical dietetics and hospital protocols, a therapeutic diet counseling session requires the patient’s active attention, focus, and ability to comprehend new lifestyle changes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the patient is relaxed and hospitalized\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical dietetics and hospital protocols, a therapeutic diet counseling session requires the patient’s active attention, focus, and ability to comprehend new lifestyle changes.\n\nWhen a patient is relaxed and hospitalized (meaning they are past the acute, painful phase of their illness but not yet caught up in the hectic rush of leaving), they are in the best mental and physical state to absorb complex nutritional instructions, ask questions, and practice meal-planning concepts.","whyWrongChoices":"Alternative options: the patient is very sick, none of the above, the patient is being discharged"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in this style of tableservice, all food are prepared and portioned in the kitchen and attractively arranged on serving platters. food is served to individual plates using cutleries.:::', 'in this style of tableservice, all food are prepared and portioned in the kitchen and attractively arranged on serving platters. food is served to individual plates using cutleries.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Russian style of service entails fully preparing food in the kitchen and placed in platters for service to guests.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Russian\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Russian style of service entails fully preparing food in the kitchen and placed in platters for service to guests.","whyWrongChoices":"Alternative options: French, American, Blue plate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:one glucose molecule will yield how many pyruvate products?:::2', 'one glucose molecule will yield how many pyruvate products?', '2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the first stage of cellular respiration (glycolysis), a single glucose molecule—which is a 6-carbon sugar (C₆H₁₂O₆)—is physically split and oxidized in the cytoplasm of the cell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the first stage of cellular respiration (glycolysis), a single glucose molecule—which is a 6-carbon sugar (C₆H₁₂O₆)—is physically split and oxidized in the cytoplasm of the cell.\n\nThis biochemical breakdown yields exactly two molecules of pyruvate (also known as pyruvic acid), which are 3-carbon structures (C₃H₄O₃).","whyWrongChoices":"Alternative options: 1, 3, 4"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refeeding syndrome can bring about a dangerous fluctuation in::::', 'refeeding syndrome can bring about a dangerous fluctuation in:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a severely malnourished or starved patient is reintroduced to nutrition (especially carbohydrates), the sudden influx of glucose triggers a massive release of insulin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"serum electrolytes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a severely malnourished or starved patient is reintroduced to nutrition (especially carbohydrates), the sudden influx of glucose triggers a massive release of insulin.\n\nThis surge of insulin forces the body to pull large amounts of glucose along with vital electrolytes out of the bloodstream and directly into the cells.\n\nThis causes a sudden, catastrophic drop in serum electrolytes, specifically leading to severe hypophosphatemia (low phosphorus), hypokalemia (low potassium), and hypomagnesemia (low magnesium). These rapid fluctuations can cause life-threatening heart arrhythmias, respiratory failure, and neurological complications.\n\n• Blood triglyceride levels: While nutrition can affect lipids over time, the immediate, life-threatening crisis of refeeding syndrome is strictly driven by the mineral and fluid shifts in the blood, not fat molecules.\n• Serum liver enzyme levels: Liver enzymes may alter slightly during metabolic adaptation, but they do not experience the sudden, dangerous systemic fluctuations that characterize the syndrome.\n• Ketone bodies: Starvation causes high ketone production, and refeeding stops this process, but the dangerous, lethal complication of refeeding syndrome itself stems directly from the rapid drop in electrolytes.","whyWrongChoices":"Alternative options: serum liver enzyme levels, ketone bodies, blood triglyceride levels"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:considered inorganic nutrients::::minerals & water', 'considered inorganic nutrients:', 'minerals & water', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In chemistry and nutrition, inorganic nutrients are substances that do not contain carbon-to-carbon or carbon-to-hydrogen bonds. They are not produced by living organisms through organic synthesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"minerals & water\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In chemistry and nutrition, inorganic nutrients are substances that do not contain carbon-to-carbon or carbon-to-hydrogen bonds. They are not produced by living organisms through organic synthesis.\n\nElements like calcium, iron, and zinc (minerals), along with water (H₂O), are pure inorganic compounds essential for structural and chemical processes in the body.\n\n• Vitamins, Proteins, Fats, and Carbohydrates are all organic compounds. They are complex structures containing carbon atoms bound to hydrogen and oxygen, synthesized by plants or animals.","whyWrongChoices":"Alternative options: proteins & fats, vitamins & proteins, vitamins & minerals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:considered inorganic nutrients::::', 'considered inorganic nutrients:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In chemistry and nutrition, inorganic nutrients are substances that do not contain carbon-to-carbon or carbon-to-hydrogen bonds. They are not produced by living organisms through organic synthesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"minerals & water\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In chemistry and nutrition, inorganic nutrients are substances that do not contain carbon-to-carbon or carbon-to-hydrogen bonds. They are not produced by living organisms through organic synthesis.\n\nElements like calcium, iron, and zinc (minerals), along with water (H₂O), are pure inorganic compounds essential for structural and chemical processes in the body.\n\n• Vitamins, Proteins, Fats, and Carbohydrates are all organic compounds. They are complex structures containing carbon atoms bound to hydrogen and oxygen, synthesized by plants or animals.","whyWrongChoices":"Alternative options: proteins & fats, vitamins & proteins, vitamins & minerals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is considered an advantage of peritoneal dialysis::::liberalized diet', 'it is considered an advantage of peritoneal dialysis:', 'liberalized diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Because peritoneal dialysis (PD) is typically performed every day or continuously overnight, it mimics the natural function of the kidneys much more closely than hemodialysis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"liberalized diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Because peritoneal dialysis (PD) is typically performed every day or continuously overnight, it mimics the natural function of the kidneys much more closely than hemodialysis.\n\nAs a result, waste products, fluid, sodium, and potassium do not build up as drastically between treatments. This grants the patient a much more flexible, less restricted, or liberalized diet and fluid intake plan compared to the strict dietary limits required for hemodialysis.","whyWrongChoices":"Alternative options: potential risk of peritonitis, minimal protein loss, mobility"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is considered an advantage of peritoneal dialysis::::', 'it is considered an advantage of peritoneal dialysis:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Because peritoneal dialysis (PD) is typically performed every day or continuously overnight, it mimics the natural function of the kidneys much more closely than hemodialysis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"liberalized diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Because peritoneal dialysis (PD) is typically performed every day or continuously overnight, it mimics the natural function of the kidneys much more closely than hemodialysis.\n\nAs a result, waste products, fluid, sodium, and potassium do not build up as drastically between treatments. This grants the patient a much more flexible, less restricted, or liberalized diet and fluid intake plan compared to the strict dietary limits required for hemodialysis.","whyWrongChoices":"Alternative options: potential risk of peritonitis, minimal protein loss, mobility"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:chronic alcoholism adversely affects the utilization of these fat-soluble vitamins::::vitamins a & d', 'chronic alcoholism adversely affects the utilization of these fat-soluble vitamins:', 'vitamins A & D', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin A degradation: Chronic alcohol consumption induces the cytochrome P450 enzyme system (specifically CYP2E1) in the liver, which heavily accelerates the breakdown and depletion of retinol (Vitamin A) stores. Additionally, alcohol directly competes with Vitamin A for the metabolic enzymes alcohol dehydrogenase (ADH) and aldehyde dehydrogenase (ALDH).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vitamins A & D\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin A degradation: Chronic alcohol consumption induces the cytochrome P450 enzyme system (specifically CYP2E1) in the liver, which heavily accelerates the breakdown and depletion of retinol (Vitamin A) stores. Additionally, alcohol directly competes with Vitamin A for the metabolic enzymes alcohol dehydrogenase (ADH) and aldehyde dehydrogenase (ALDH).\n\nVitamin D malabsorption & impaired activation: Alcohol interferes with the liver''s ability to hydrolyze cholecalciferol into its active form. It also disrupts bile secretion and impairs the mucosal lining of the small intestine, leading to significant fat malabsorption that prevents fat-soluble vitamins like Vitamin D from being absorbed properly.\n\nWhile chronic alcoholism can impact all fat-soluble vitamins (A, D, E, and K), vitamins A & D are the most clinically prominent and severely affected in terms of metabolic utilization, hepatic storage depletion, and target organ complications (e.g., night blindness and alcoholic bone disease/osteopenia).","whyWrongChoices":"Alternative options: vitamins A & E, vitamins D & E, vitamins D & K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:chronic alcoholism adversely affects the utilization of these fat-soluble vitamins::::', 'chronic alcoholism adversely affects the utilization of these fat-soluble vitamins:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin A degradation: Chronic alcohol consumption induces the cytochrome P450 enzyme system (specifically CYP2E1) in the liver, which heavily accelerates the breakdown and depletion of retinol (Vitamin A) stores. Additionally, alcohol directly competes with Vitamin A for the metabolic enzymes alcohol dehydrogenase (ADH) and aldehyde dehydrogenase (ALDH).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vitamins A & D\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin A degradation: Chronic alcohol consumption induces the cytochrome P450 enzyme system (specifically CYP2E1) in the liver, which heavily accelerates the breakdown and depletion of retinol (Vitamin A) stores. Additionally, alcohol directly competes with Vitamin A for the metabolic enzymes alcohol dehydrogenase (ADH) and aldehyde dehydrogenase (ALDH).\n\nVitamin D malabsorption & impaired activation: Alcohol interferes with the liver''s ability to hydrolyze cholecalciferol into its active form. It also disrupts bile secretion and impairs the mucosal lining of the small intestine, leading to significant fat malabsorption that prevents fat-soluble vitamins like Vitamin D from being absorbed properly.\n\nWhile chronic alcoholism can impact all fat-soluble vitamins (A, D, E, and K), vitamins A & D are the most clinically prominent and severely affected in terms of metabolic utilization, hepatic storage depletion, and target organ complications (e.g., night blindness and alcoholic bone disease/osteopenia).","whyWrongChoices":"Alternative options: vitamins A & E, vitamins D & E, vitamins D & K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ischemia in the coronary arteries is a usual cause of::::angina pectoris', 'ischemia in the coronary arteries is a usual cause of:', 'angina pectoris', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ischemia refers to an inadequate supply of blood and oxygen to a specific tissue or organ. When ischemia occurs specifically within the coronary arteries—the blood vessels responsible for feeding the heart muscle itself—it means the heart muscle (myocardium) is being temporarily starved of vital oxygen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"angina pectoris\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ischemia refers to an inadequate supply of blood and oxygen to a specific tissue or organ. When ischemia occurs specifically within the coronary arteries—the blood vessels responsible for feeding the heart muscle itself—it means the heart muscle (myocardium) is being temporarily starved of vital oxygen.\n\nThis oxygen deficit forces the heart muscle cells to switch to anaerobic metabolism, which generates lactic acid, irritates local nerve endings, and triggers the classic clinical sensation of chest pain, pressure, or discomfort known as angina pectoris.\n\n• HPN (Hypertension): High blood pressure is a major systemic circulatory cause or risk factor that accelerates the development of narrowed coronary arteries, rather than being a consequence of coronary artery ischemia.\n• Hemorrhagic stroke: A neurological event caused by a ruptured or bleeding blood vessel inside the brain tissue, completely unrelated to oxygen levels in the heart''s arteries.\n• Aneurysm: A pathological ballooning or weakening of a blood vessel wall (most commonly in the aorta or brain arteries), rather than a lack of blood flow to the heart muscle.","whyWrongChoices":"Alternative options: hemorrhagic stroke, aneurysm, HPN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ischemia in the coronary arteries is a usual cause of::::', 'ischemia in the coronary arteries is a usual cause of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ischemia refers to an inadequate supply of blood and oxygen to a specific tissue or organ. When ischemia occurs specifically within the coronary arteries—the blood vessels responsible for feeding the heart muscle itself—it means the heart muscle (myocardium) is being temporarily starved of vital oxygen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"angina pectoris\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ischemia refers to an inadequate supply of blood and oxygen to a specific tissue or organ. When ischemia occurs specifically within the coronary arteries—the blood vessels responsible for feeding the heart muscle itself—it means the heart muscle (myocardium) is being temporarily starved of vital oxygen.\n\nThis oxygen deficit forces the heart muscle cells to switch to anaerobic metabolism, which generates lactic acid, irritates local nerve endings, and triggers the classic clinical sensation of chest pain, pressure, or discomfort known as angina pectoris.\n\n• HPN (Hypertension): High blood pressure is a major systemic circulatory cause or risk factor that accelerates the development of narrowed coronary arteries, rather than being a consequence of coronary artery ischemia.\n• Hemorrhagic stroke: A neurological event caused by a ruptured or bleeding blood vessel inside the brain tissue, completely unrelated to oxygen levels in the heart''s arteries.\n• Aneurysm: A pathological ballooning or weakening of a blood vessel wall (most commonly in the aorta or brain arteries), rather than a lack of blood flow to the heart muscle.","whyWrongChoices":"Alternative options: hemorrhagic stroke, aneurysm, HPN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:after an injury, the following changes occur in the damaged tissue except::::reduced capillary permeability', 'after an injury, the following changes occur in the damaged tissue except:', 'reduced capillary permeability', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Following a tissue injury, the body initiates an acute inflammatory response where capillary permeability is increased, not reduced.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"reduced capillary permeability\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Following a tissue injury, the body initiates an acute inflammatory response where capillary permeability is increased, not reduced.\n\nChemical signals like histamine and prostaglandins cause the endothelial cells lining the local blood vessels to contract and form microscopic gaps. This makes the vessels \"leaky,\" allowing protein-rich fluids, white blood cells, and antibodies to exit the bloodstream and flood the damaged area to begin healing.\n\n• Warmth & Increased blood flow: Damaged cells trigger local vasodilation (widening of blood vessels). This brings a heavy surge of warm core blood to the surface of the injured area, resulting in visible redness and an unmistakable sensation of localized warmth.\n• Fluid accumulation: Because the blood vessels become highly permeable, plasma and protein-rich fluids escape into the surrounding interstitial tissue spaces. This direct fluid accumulation causes localized swelling, or edema.","whyWrongChoices":"Alternative options: warmth, fluid accumulation, increased blood flow"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:after an injury, the following changes occur in the damaged tissue except::::', 'after an injury, the following changes occur in the damaged tissue except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Following a tissue injury, the body initiates an acute inflammatory response where capillary permeability is increased, not reduced.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"reduced capillary permeability\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Following a tissue injury, the body initiates an acute inflammatory response where capillary permeability is increased, not reduced.\n\nChemical signals like histamine and prostaglandins cause the endothelial cells lining the local blood vessels to contract and form microscopic gaps. This makes the vessels \"leaky,\" allowing protein-rich fluids, white blood cells, and antibodies to exit the bloodstream and flood the damaged area to begin healing.\n\n• Warmth & Increased blood flow: Damaged cells trigger local vasodilation (widening of blood vessels). This brings a heavy surge of warm core blood to the surface of the injured area, resulting in visible redness and an unmistakable sensation of localized warmth.\n• Fluid accumulation: Because the blood vessels become highly permeable, plasma and protein-rich fluids escape into the surrounding interstitial tissue spaces. This direct fluid accumulation causes localized swelling, or edema.","whyWrongChoices":"Alternative options: warmth, fluid accumulation, increased blood flow"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:management philosophy combining principles of quality assurance, participative management, and quality work life::::', 'management philosophy combining principles of quality assurance, participative management, and quality work life:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"TQM is a system of management based on the principle that every staff member must be committed to maintaining high standards of work in every aspect of a company''s operations towards attaining customer satisfaction.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Total Quality Management\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"TQM is a system of management based on the principle that every staff member must be committed to maintaining high standards of work in every aspect of a company''s operations towards attaining customer satisfaction.","whyWrongChoices":"Alternative options: Theory X, Theory Y, Theory Z"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in dumping syndrome, what is the suspected cause of the symptoms arising after 10-15 minutes after the ingestion of a meal?:::a shift in plasma fluid to the small intestine', 'in dumping syndrome, what is the suspected cause of the symptoms arising after 10-15 minutes after the ingestion of a meal?', 'a shift in plasma fluid to the small intestine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient has undergone gastric surgery, the stomach loses its ability to regulate the passage of food. Highly concentrated, hypertonic food particles (especially simple carbohydrates) dump rapidly into the small intestine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"a shift in plasma fluid to the small intestine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient has undergone gastric surgery, the stomach loses its ability to regulate the passage of food. Highly concentrated, hypertonic food particles (especially simple carbohydrates) dump rapidly into the small intestine.\n\nBecause this food is highly concentrated, the body quickly draws large amounts of plasma fluid out of the bloodstream and into the lumen of the small intestine via osmosis to dilute the mixture.\n\nThis sudden shift causes the bowel to distend rapidly (leading to abdominal cramping, bloating, and diarrhea) and causes a sharp drop in blood volume (leading to cardiovascular symptoms like dizziness, rapid heart rate, and sweating).\n\n• Rapid fall in serum K level: While late dumping syndrome (occurring 1–3 hours later) involves an insulin surge that can cause a slight cellular shift in potassium alongside glucose, the immediate fluid-shift mechanism is responsible for early symptoms.\n• Postgastrectomy anemia: This is a long-term nutritional complication caused by poor iron or Vitamin B₁₂ absorption, not an acute reaction that happens minutes after eating.\n• Decreased pancreatic secretion: Pancreatic enzymes are still produced, but they often mix poorly with food due to altered digestive timing, which is not the underlying driver of early dumping symptoms.","whyWrongChoices":"Alternative options: postgastrectomy anemia, decreased pancreatic secretion, rapid fall in serum K level"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in dumping syndrome, what is the suspected cause of the symptoms arising after 10-15 minutes after the ingestion of a meal?:::', 'in dumping syndrome, what is the suspected cause of the symptoms arising after 10-15 minutes after the ingestion of a meal?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient has undergone gastric surgery, the stomach loses its ability to regulate the passage of food. Highly concentrated, hypertonic food particles (especially simple carbohydrates) dump rapidly into the small intestine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"a shift in plasma fluid to the small intestine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient has undergone gastric surgery, the stomach loses its ability to regulate the passage of food. Highly concentrated, hypertonic food particles (especially simple carbohydrates) dump rapidly into the small intestine.\n\nBecause this food is highly concentrated, the body quickly draws large amounts of plasma fluid out of the bloodstream and into the lumen of the small intestine via osmosis to dilute the mixture.\n\nThis sudden shift causes the bowel to distend rapidly (leading to abdominal cramping, bloating, and diarrhea) and causes a sharp drop in blood volume (leading to cardiovascular symptoms like dizziness, rapid heart rate, and sweating).\n\n• Rapid fall in serum K level: While late dumping syndrome (occurring 1–3 hours later) involves an insulin surge that can cause a slight cellular shift in potassium alongside glucose, the immediate fluid-shift mechanism is responsible for early symptoms.\n• Postgastrectomy anemia: This is a long-term nutritional complication caused by poor iron or Vitamin B₁₂ absorption, not an acute reaction that happens minutes after eating.\n• Decreased pancreatic secretion: Pancreatic enzymes are still produced, but they often mix poorly with food due to altered digestive timing, which is not the underlying driver of early dumping symptoms.","whyWrongChoices":"Alternative options: postgastrectomy anemia, decreased pancreatic secretion, rapid fall in serum K level"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the largest controllable cost incurred in a foodservice unit is::::', 'the largest controllable cost incurred in a foodservice unit is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food cost is the percentage of total sales spent onf food products. This usually ranges from 40-45% of all the costs and it under the control of the owner/manager.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food cost is the percentage of total sales spent onf food products. This usually ranges from 40-45% of all the costs and it under the control of the owner/manager.","whyWrongChoices":"Alternative options: Labor, Operation, Utilities"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:alcohol abuse results in poor absorption of the following b vitamins except::::riboflavin', 'alcohol abuse results in poor absorption of the following b vitamins except:', 'riboflavin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While chronic alcohol consumption is notoriously linked to the severe intestinal malabsorption of thiamin (B1), pyridoxine (B6), and folate, riboflavin is the exception in this specific question.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"riboflavin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While chronic alcohol consumption is notoriously linked to the severe intestinal malabsorption of thiamin (B1), pyridoxine (B6), and folate, riboflavin is the exception in this specific question.\n\nIn standard nutrition board exam matrices, alcohol abuse is most famously tested for causing a triad of B-vitamin absorption failures: thiamin (leading to Wernicke-Korsakoff syndrome), folate (leading to macrocytic anemia), and pyridoxine (where alcohol interference alters metabolic synthesis and absorption). Therefore, riboflavin stands as the textbook answer key choice for the vitamin less uniformly targeted by direct, alcohol-induced gut malabsorption channels compared to the others.","whyWrongChoices":"Alternative options: thiamin, pyridoxine, folate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:alcohol abuse results in poor absorption of the following b vitamins except::::', 'alcohol abuse results in poor absorption of the following b vitamins except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While chronic alcohol consumption is notoriously linked to the severe intestinal malabsorption of thiamin (B1), pyridoxine (B6), and folate, riboflavin is the exception in this specific question.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"riboflavin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While chronic alcohol consumption is notoriously linked to the severe intestinal malabsorption of thiamin (B1), pyridoxine (B6), and folate, riboflavin is the exception in this specific question.\n\nIn standard nutrition board exam matrices, alcohol abuse is most famously tested for causing a triad of B-vitamin absorption failures: thiamin (leading to Wernicke-Korsakoff syndrome), folate (leading to macrocytic anemia), and pyridoxine (where alcohol interference alters metabolic synthesis and absorption). Therefore, riboflavin stands as the textbook answer key choice for the vitamin less uniformly targeted by direct, alcohol-induced gut malabsorption channels compared to the others.","whyWrongChoices":"Alternative options: thiamin, pyridoxine, folate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the transportation of prepared foods from production to the place of service.:::delivery', 'the transportation of prepared foods from production to the place of service.', 'Delivery', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food delivery is defined as the movement of food from production to service.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Delivery\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food delivery is defined as the movement of food from production to service.","whyWrongChoices":"Alternative options: Transfer, Dispatching, Assembling"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the vitamin most directly involved in protecting biomolecules from damage caused by oxidation is::::e', 'the vitamin most directly involved in protecting biomolecules from damage caused by oxidation is:', 'E', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin E (tocopherol) is recognized as the body''s primary fat-soluble antioxidant. Its most direct, essential physiological role is to protect lipids and other vulnerable biomolecules inside cell membranes from oxidative damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"E\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin E (tocopherol) is recognized as the body''s primary fat-soluble antioxidant. Its most direct, essential physiological role is to protect lipids and other vulnerable biomolecules inside cell membranes from oxidative damage.\n\nFree radicals break down cell structures by attacking polyunsaturated fatty acids in a destructive chain reaction called lipid peroxidation. Vitamin E sits directly within the lipid bilayer of cell membranes, sacrificing itself to neutralize these free radicals, which preserves the structural integrity of every cell in the body.\n\n• C: While Vitamin C (ascorbic acid) is a powerful water-soluble antioxidant that works closely with Vitamin E (even recycling oxidized Vitamin E back to its active form), it also acts as a necessary co-factor for many non-antioxidant enzymatic reactions, such as collagen synthesis.\n• A: While carotenoids (precursors to Vitamin A) have antioxidant properties, preformed Vitamin A (retinol) functions primarily in vision, cell differentiation, and immune health rather than acting as a general biomolecule antioxidant.\n• B3: Vitamin B3 (niacin) forms the coenzymes NAD and NADP, which are essential for cellular respiration and energy transfer reactions rather than scavenging free radicals to stop oxidation.","whyWrongChoices":"Alternative options: A, B3, C"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the vitamin most directly involved in protecting biomolecules from damage caused by oxidation is::::', 'the vitamin most directly involved in protecting biomolecules from damage caused by oxidation is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin E (tocopherol) is recognized as the body''s primary fat-soluble antioxidant. Its most direct, essential physiological role is to protect lipids and other vulnerable biomolecules inside cell membranes from oxidative damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"E\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin E (tocopherol) is recognized as the body''s primary fat-soluble antioxidant. Its most direct, essential physiological role is to protect lipids and other vulnerable biomolecules inside cell membranes from oxidative damage.\n\nFree radicals break down cell structures by attacking polyunsaturated fatty acids in a destructive chain reaction called lipid peroxidation. Vitamin E sits directly within the lipid bilayer of cell membranes, sacrificing itself to neutralize these free radicals, which preserves the structural integrity of every cell in the body.\n\n• C: While Vitamin C (ascorbic acid) is a powerful water-soluble antioxidant that works closely with Vitamin E (even recycling oxidized Vitamin E back to its active form), it also acts as a necessary co-factor for many non-antioxidant enzymatic reactions, such as collagen synthesis.\n• A: While carotenoids (precursors to Vitamin A) have antioxidant properties, preformed Vitamin A (retinol) functions primarily in vision, cell differentiation, and immune health rather than acting as a general biomolecule antioxidant.\n• B3: Vitamin B3 (niacin) forms the coenzymes NAD and NADP, which are essential for cellular respiration and energy transfer reactions rather than scavenging free radicals to stop oxidation.","whyWrongChoices":"Alternative options: A, B3, C"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:olestra is artificial fat that does not provide kilocalories but has the following effect on one’s nutrition::::it prevents the absorption of fat-soluble vitamins.', 'olestra is artificial fat that does not provide kilocalories but has the following effect on one’s nutrition:', 'It prevents the absorption of fat-soluble vitamins.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Olestra is a non-absorbable fat substitute made of sucrose polyester. Because human digestive enzymes cannot break its large chemical structure down, it passes through the gastrointestinal tract entirely intact.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It prevents the absorption of fat-soluble vitamins.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Olestra is a non-absorbable fat substitute made of sucrose polyester. Because human digestive enzymes cannot break its large chemical structure down, it passes through the gastrointestinal tract entirely intact.\n\nAs it moves through the gut, olestra behaves like a physical liquid solvent. It dissolves and traps the fat-soluble vitamins (A, D, E, and K) along with carotenoids from other consumed foods. Because olestra cannot be absorbed, these vital nutrients are bound to it and carried straight out of the body, presenting a major nutritional deficit. This is why the FDA legally mandates that foods made with olestra must be fortified with vitamins A, D, E, and K to offset this specific malabsorption effect.\n\n• It prevents the absorption of water-soluble vitamins: This is scientifically incorrect. Water-soluble vitamins (like Vitamin C and B-complex vitamins) dissolve in water, not lipids. Therefore, they are entirely unaffected by the presence of olestra and are absorbed normally by the body.\n• It results in flatulence: While gastrointestinal symptoms like flatulence, cramping, or loose stools can occur when olestra is consumed in extremely massive, non-standard quantities, the primary, classic nutrition-board-tested hazard is its direct, chemical inhibition of fat-soluble vitamin uptake.","whyWrongChoices":"Alternative options: a & b only, It prevents the absorption of water-soluble vitamins., It results in flatulence."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:olestra is artificial fat that does not provide kilocalories but has the following effect on one’s nutrition::::', 'olestra is artificial fat that does not provide kilocalories but has the following effect on one’s nutrition:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Olestra is a non-absorbable fat substitute made of sucrose polyester. Because human digestive enzymes cannot break its large chemical structure down, it passes through the gastrointestinal tract entirely intact.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It prevents the absorption of fat-soluble vitamins.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Olestra is a non-absorbable fat substitute made of sucrose polyester. Because human digestive enzymes cannot break its large chemical structure down, it passes through the gastrointestinal tract entirely intact.\n\nAs it moves through the gut, olestra behaves like a physical liquid solvent. It dissolves and traps the fat-soluble vitamins (A, D, E, and K) along with carotenoids from other consumed foods. Because olestra cannot be absorbed, these vital nutrients are bound to it and carried straight out of the body, presenting a major nutritional deficit. This is why the FDA legally mandates that foods made with olestra must be fortified with vitamins A, D, E, and K to offset this specific malabsorption effect.\n\n• It prevents the absorption of water-soluble vitamins: This is scientifically incorrect. Water-soluble vitamins (like Vitamin C and B-complex vitamins) dissolve in water, not lipids. Therefore, they are entirely unaffected by the presence of olestra and are absorbed normally by the body.\n• It results in flatulence: While gastrointestinal symptoms like flatulence, cramping, or loose stools can occur when olestra is consumed in extremely massive, non-standard quantities, the primary, classic nutrition-board-tested hazard is its direct, chemical inhibition of fat-soluble vitamin uptake.","whyWrongChoices":"Alternative options: a & b only, It prevents the absorption of water-soluble vitamins., It results in flatulence."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the transportation of prepared foods from production to the place of service.:::', 'the transportation of prepared foods from production to the place of service.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food delivery is defined as the movement of food from production to service.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Delivery\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food delivery is defined as the movement of food from production to service.","whyWrongChoices":"Alternative options: Transfer, Dispatching, Assembling"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an enzyme that is common in both glycolysis and gluconeogenesis.:::aldolase', 'an enzyme that is common in both glycolysis and gluconeogenesis.', 'aldolase', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aldolase catalyzes a reversible reaction in glycolysis and gluconeogenesis, breaking down (or assembling) fructose-1,6-bisphosphate into dihydroxyacetone phosphate (DHAP) and glyceraldehyde 3-phosphate (G3P).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"aldolase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aldolase catalyzes a reversible reaction in glycolysis and gluconeogenesis, breaking down (or assembling) fructose-1,6-bisphosphate into dihydroxyacetone phosphate (DHAP) and glyceraldehyde 3-phosphate (G3P).\n\n• Fructose biphosphatase (fructose-1,6-bisphosphatase), phosphofructokinase-1 (PFK-1), and glucokinase are unidirectional, regulatory enzymes unique to either gluconeogenesis or glycolysis, respectively, to prevent a futile cycle.","whyWrongChoices":"Alternative options: glucokinase, phosphofructokinase-1, fructose biphosphatase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an enzyme that is common in both glycolysis and gluconeogenesis.:::', 'an enzyme that is common in both glycolysis and gluconeogenesis.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aldolase catalyzes a reversible reaction in glycolysis and gluconeogenesis, breaking down (or assembling) fructose-1,6-bisphosphate into dihydroxyacetone phosphate (DHAP) and glyceraldehyde 3-phosphate (G3P).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"aldolase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aldolase catalyzes a reversible reaction in glycolysis and gluconeogenesis, breaking down (or assembling) fructose-1,6-bisphosphate into dihydroxyacetone phosphate (DHAP) and glyceraldehyde 3-phosphate (G3P).\n\n• Fructose biphosphatase (fructose-1,6-bisphosphatase), phosphofructokinase-1 (PFK-1), and glucokinase are unidirectional, regulatory enzymes unique to either gluconeogenesis or glycolysis, respectively, to prevent a futile cycle.","whyWrongChoices":"Alternative options: glucokinase, phosphofructokinase-1, fructose biphosphatase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the recommended daily amount of dietary fiber for a heart healthy and diabetic diet is::::25 – 30 g', 'the recommended daily amount of dietary fiber for a heart healthy and diabetic diet is:', '25 – 30 g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The American Heart Association (AHA) specifically recommends a daily dietary fiber intake of 25 to 30 grams from food sources to lower cholesterol levels and reduce the risk of cardiovascular disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"25 – 30 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The American Heart Association (AHA) specifically recommends a daily dietary fiber intake of 25 to 30 grams from food sources to lower cholesterol levels and reduce the risk of cardiovascular disease.\n\nMajor diabetes organizations align with this range (often extending up to 35 grams) because dietary fiber—especially soluble fiber—slows glucose absorption, prevents sharp blood sugar spikes, and helps improve overall insulin sensitivity.","whyWrongChoices":"Alternative options: 20 -25 g, 10-15 g, 15 – 20 g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the recommended daily amount of dietary fiber for a heart healthy and diabetic diet is::::', 'the recommended daily amount of dietary fiber for a heart healthy and diabetic diet is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The American Heart Association (AHA) specifically recommends a daily dietary fiber intake of 25 to 30 grams from food sources to lower cholesterol levels and reduce the risk of cardiovascular disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"25 – 30 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The American Heart Association (AHA) specifically recommends a daily dietary fiber intake of 25 to 30 grams from food sources to lower cholesterol levels and reduce the risk of cardiovascular disease.\n\nMajor diabetes organizations align with this range (often extending up to 35 grams) because dietary fiber—especially soluble fiber—slows glucose absorption, prevents sharp blood sugar spikes, and helps improve overall insulin sensitivity.","whyWrongChoices":"Alternative options: 20 -25 g, 10-15 g, 15 – 20 g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an alternative sweetener that has a protective effect on tooth decay but with discomforting side effects such as intestinal gas or abdominal discomfort::::sorbitol', 'an alternative sweetener that has a protective effect on tooth decay but with discomforting side effects such as intestinal gas or abdominal discomfort:', 'sorbitol', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sorbitol is a sugar alcohol (polyol). Unlike regular sugar, oral bacteria cannot readily ferment sorbitol, meaning it does not produce the harmful acids that erode tooth enamel. Because of this, it has a proven protective effect against dental caries (tooth decay) and is commonly used in sugar-free chewing gums and toothpastes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"sorbitol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sorbitol is a sugar alcohol (polyol). Unlike regular sugar, oral bacteria cannot readily ferment sorbitol, meaning it does not produce the harmful acids that erode tooth enamel. Because of this, it has a proven protective effect against dental caries (tooth decay) and is commonly used in sugar-free chewing gums and toothpastes.\n\nSugar alcohols are only partially digested and absorbed in the small intestine. The unabsorbed sorbitol travels down to the large intestine, where it acts as an osmotic laxative (drawing water into the bowel) and is rapidly fermented by gut bacteria. Consuming too much of it directly results in intestinal gas, bloating, abdominal cramps, and diarrhea.\n\n• Saccharin: An artificial, non-nutritive sweetener that does not cause tooth decay, but it does not cause gas or GI distress because it is completely absorbed and excreted unchanged in the urine.\n• Stevia: A natural, high-intensity plant extract that passes through the body without triggering the osmotic gastrointestinal issues or fermentation associated with sugar alcohols.\n• Aspartame: An artificial sweetener made from amino acids. It is fully digested and absorbed in the small intestine like a protein, so it never reaches the large intestine to cause gas or abdominal discomfort.","whyWrongChoices":"Alternative options: aspartame, stevia, saccharin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:anti-hemorrhagic factor.:::vit k', 'anti-hemorrhagic factor.', 'Vit K', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Blood clotting action of Vitamin K may cause hemorrhage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit K\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Blood clotting action of Vitamin K may cause hemorrhage.","whyWrongChoices":"Alternative options: Vit A, Vit D, Vit E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an alternative sweetener that has a protective effect on tooth decay but with discomforting side effects such as intestinal gas or abdominal discomfort::::', 'an alternative sweetener that has a protective effect on tooth decay but with discomforting side effects such as intestinal gas or abdominal discomfort:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sorbitol is a sugar alcohol (polyol). Unlike regular sugar, oral bacteria cannot readily ferment sorbitol, meaning it does not produce the harmful acids that erode tooth enamel. Because of this, it has a proven protective effect against dental caries (tooth decay) and is commonly used in sugar-free chewing gums and toothpastes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"sorbitol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sorbitol is a sugar alcohol (polyol). Unlike regular sugar, oral bacteria cannot readily ferment sorbitol, meaning it does not produce the harmful acids that erode tooth enamel. Because of this, it has a proven protective effect against dental caries (tooth decay) and is commonly used in sugar-free chewing gums and toothpastes.\n\nSugar alcohols are only partially digested and absorbed in the small intestine. The unabsorbed sorbitol travels down to the large intestine, where it acts as an osmotic laxative (drawing water into the bowel) and is rapidly fermented by gut bacteria. Consuming too much of it directly results in intestinal gas, bloating, abdominal cramps, and diarrhea.\n\n• Saccharin: An artificial, non-nutritive sweetener that does not cause tooth decay, but it does not cause gas or GI distress because it is completely absorbed and excreted unchanged in the urine.\n• Stevia: A natural, high-intensity plant extract that passes through the body without triggering the osmotic gastrointestinal issues or fermentation associated with sugar alcohols.\n• Aspartame: An artificial sweetener made from amino acids. It is fully digested and absorbed in the small intestine like a protein, so it never reaches the large intestine to cause gas or abdominal discomfort.","whyWrongChoices":"Alternative options: aspartame, stevia, saccharin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following have an antioxidant function except for::::zn', 'the following have an antioxidant function except for:', 'Zn', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin C and carotenoids are classic direct non-enzymatic antioxidants because they physically neutralize free radicals by donating electrons. Selenium (Se) is a direct component of the essential antioxidant enzyme glutathione peroxidase, which actively breaks down toxic peroxides.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin C and carotenoids are classic direct non-enzymatic antioxidants because they physically neutralize free radicals by donating electrons. Selenium (Se) is a direct component of the essential antioxidant enzyme glutathione peroxidase, which actively breaks down toxic peroxides.\n\nIn contrast, Zinc itself does not directly capture free radicals. Instead, it plays an indirect role by acting as a structural co-factor for the enzyme copper-zinc superoxide dismutase (CuZnSOD) and stabilizing cell membranes against lipid peroxidation. Because it serves as a mineral co-factor rather than acting as a direct antioxidant chemical or molecule on its own, it stands out as the standard textbook exception in this specific group.","whyWrongChoices":"Alternative options: Se, vitamin C, carotenoids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following have an antioxidant function except for::::', 'the following have an antioxidant function except for:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin C and carotenoids are classic direct non-enzymatic antioxidants because they physically neutralize free radicals by donating electrons. Selenium (Se) is a direct component of the essential antioxidant enzyme glutathione peroxidase, which actively breaks down toxic peroxides.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin C and carotenoids are classic direct non-enzymatic antioxidants because they physically neutralize free radicals by donating electrons. Selenium (Se) is a direct component of the essential antioxidant enzyme glutathione peroxidase, which actively breaks down toxic peroxides.\n\nIn contrast, Zinc itself does not directly capture free radicals. Instead, it plays an indirect role by acting as a structural co-factor for the enzyme copper-zinc superoxide dismutase (CuZnSOD) and stabilizing cell membranes against lipid peroxidation. Because it serves as a mineral co-factor rather than acting as a direct antioxidant chemical or molecule on its own, it stands out as the standard textbook exception in this specific group.","whyWrongChoices":"Alternative options: Se, vitamin C, carotenoids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. how much is her total energy requirement based on dbw?:::1950 kcal', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. how much is her total energy requirement based on dbw?', '1950 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Re-establishing the Desirable Body Weight (DBW)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1950 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Re-establishing the Desirable Body Weight (DBW)\n\nFrom our previous step, her height of 5''4\" (162.56 cm) processed through Tannhauser''s Method yields:\n• Base Weight: 162.56 - 100 = 62.56 kg\n• Deduct 10% for female frame: 62.56 - 6.25 = 56.31 kg\n\n2. Identifying the Activity Factor\n\n• Her occupation as a teacher classifies her physical activity level as Light Activity.\n• The standard calorie allowance factor for an individual with light activity is 35 kcal per kilogram of DBW per day.\n\n3. Calculating the Total Energy Requirement (TER)\n\nMultiplying her precise DBW by the light activity factor:\n• TER = 56.31 kg × 35 kcal/kg = 1970.85 kcal\n\n4. Applying Dietetic Rounding Rules\n\nIn Philippine dietetics, final caloric requirements are strictly rounded to the nearest 50 kcal block to simplify meal exchanges:\n• Rounding 1970.85 kcal to the nearest 50 kcal block gives 1950 kcal","whyWrongChoices":"Alternative options: 1850 kcal, 1900 kcal, 2000 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. how much is her total energy requirement based on dbw?:::', 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. how much is her total energy requirement based on dbw?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Re-establishing the Desirable Body Weight (DBW)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1950 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Re-establishing the Desirable Body Weight (DBW)\n\nFrom our previous step, her height of 5''4\" (162.56 cm) processed through Tannhauser''s Method yields:\n• Base Weight: 162.56 - 100 = 62.56 kg\n• Deduct 10% for female frame: 62.56 - 6.25 = 56.31 kg\n\n2. Identifying the Activity Factor\n\n• Her occupation as a teacher classifies her physical activity level as Light Activity.\n• The standard calorie allowance factor for an individual with light activity is 35 kcal per kilogram of DBW per day.\n\n3. Calculating the Total Energy Requirement (TER)\n\nMultiplying her precise DBW by the light activity factor:\n• TER = 56.31 kg × 35 kcal/kg = 1970.85 kcal\n\n4. Applying Dietetic Rounding Rules\n\nIn Philippine dietetics, final caloric requirements are strictly rounded to the nearest 50 kcal block to simplify meal exchanges:\n• Rounding 1970.85 kcal to the nearest 50 kcal block gives 1950 kcal","whyWrongChoices":"Alternative options: 1850 kcal, 1900 kcal, 2000 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:anti-hemorrhagic factor.:::', 'anti-hemorrhagic factor.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Blood clotting action of Vitamin K may cause hemorrhage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit K\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Blood clotting action of Vitamin K may cause hemorrhage.","whyWrongChoices":"Alternative options: Vit A, Vit D, Vit E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a branched-chain amino acid::::isoleucin', 'it is a branched-chain amino acid:', 'isoleucin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Isoleucine is one of the three classic branched-chain amino acids (BCAAs), alongside leucine and valine. These amino acids are chemically distinguished by an aliphatic, non-linear side chain featuring a central branch point.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"isoleucin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Isoleucine is one of the three classic branched-chain amino acids (BCAAs), alongside leucine and valine. These amino acids are chemically distinguished by an aliphatic, non-linear side chain featuring a central branch point.\n\nUnlike most other amino acids that are metabolized primarily in the liver, BCAAs are unique because they bypass initial liver breakdown and are taken up directly by skeletal muscle tissue. There, they serve as a critical substrate for energy production and play a major role in stimulating muscle protein synthesis during periods of recovery or metabolic stress.\n\n• Alanine: A dispensable (non-essential) amino acid with a simple, straight-chain methyl side group. It is heavily involved in the glucose-alanine cycle to transport nitrogen from muscles to the liver.\n• Lysine: An indispensable (essential) amino acid with a straight, basic hydrocarbon side chain ending in an amino group, not a branched-chain configuration.\n• Glutamine: A conditionally indispensable amino acid with a straight-chain amide side group. It is the most abundant free amino acid in the human body, acting as a premier fuel source for rapidly dividing immune cells and enterocytes in the gut.","whyWrongChoices":"Alternative options: glutamine, alanine, lysine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet for a patient with diverticulosis::::high fiber', 'diet for a patient with diverticulosis:', 'high fiber', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diverticulosis is the condition of having small, uninflamed pouches (diverticula) in the walls of the large intestine. The primary goal of medical nutrition therapy (MNT) is to prevent these pouches from becoming obstructed or inflamed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diverticulosis is the condition of having small, uninflamed pouches (diverticula) in the walls of the large intestine. The primary goal of medical nutrition therapy (MNT) is to prevent these pouches from becoming obstructed or inflamed.\n\nA high-fiber diet (along with adequate fluid intake) adds bulk to the stool and retains water, which softens the feces. This volume decreases the intraluminal pressure inside the colon, allowing waste to pass smoothly and reducing the straining that causes pouches to form or worsen in the first place.\n\n• Low residue / Low fiber / Soft diet: These restricted-texture or low-fiber options are contraindicated for regular diverticulosis management because they lead to small, hard stools that increase colonic pressure. However, they are used temporarily during an acute flare-up of diverticulitis (when the pouches become actively inflamed or infected) to give the bowel a chance to rest and heal.","whyWrongChoices":"Alternative options: low fiber, soft diet, low residue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet for a patient with diverticulosis::::', 'diet for a patient with diverticulosis:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diverticulosis is the condition of having small, uninflamed pouches (diverticula) in the walls of the large intestine. The primary goal of medical nutrition therapy (MNT) is to prevent these pouches from becoming obstructed or inflamed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diverticulosis is the condition of having small, uninflamed pouches (diverticula) in the walls of the large intestine. The primary goal of medical nutrition therapy (MNT) is to prevent these pouches from becoming obstructed or inflamed.\n\nA high-fiber diet (along with adequate fluid intake) adds bulk to the stool and retains water, which softens the feces. This volume decreases the intraluminal pressure inside the colon, allowing waste to pass smoothly and reducing the straining that causes pouches to form or worsen in the first place.\n\n• Low residue / Low fiber / Soft diet: These restricted-texture or low-fiber options are contraindicated for regular diverticulosis management because they lead to small, hard stools that increase colonic pressure. However, they are used temporarily during an acute flare-up of diverticulitis (when the pouches become actively inflamed or infected) to give the bowel a chance to rest and heal.","whyWrongChoices":"Alternative options: low fiber, soft diet, low residue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:epa and dha can help reduce heart disease risk due to their beneficial effects on::::triglyceride levels & blood clotting activity', 'epa and dha can help reduce heart disease risk due to their beneficial effects on:', 'triglyceride levels & blood clotting activity', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Omega-3 fatty acids, specifically eicosapentaenoic acid (EPA) and docosahexaenoic acid (DHA), have a well-documented, powerful effect on reducing serum triglyceride levels. They do this by decreasing the liver''s production of VLDL (very-low-density lipoprotein) and speeding up the clearance of triglycerides from the blood.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"triglyceride levels & blood clotting activity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Omega-3 fatty acids, specifically eicosapentaenoic acid (EPA) and docosahexaenoic acid (DHA), have a well-documented, powerful effect on reducing serum triglyceride levels. They do this by decreasing the liver''s production of VLDL (very-low-density lipoprotein) and speeding up the clearance of triglycerides from the blood.\n\nEPA and DHA also reduce blood clotting activity (platelet aggregation). They displace arachidonic acid in cell membranes, which reduces the production of thromboxane A2 (a compound that causes platelets to clump together and form clots) and shifts the body toward a more antithrombotic, clot-preventing state.\n\n• LDL & HDL levels: While omega-3s can slightly raise HDL (\"good\") cholesterol, high doses of DHA can actually increase LDL (\"bad\") cholesterol levels in some individuals, making this a less uniform or beneficial primary mechanism.\n• Cardiac output & heart rate: Omega-3s do support a stable heart rhythm and improve heart rate variability, but they do not primarily lower heart disease risk by altering baseline cardiac output or basic resting heart rate.\n• LDL size & particle number: This is the primary target mechanism for medications like statins or advanced lipid therapies rather than the signature biochemical profile of marine omega-3 oils.","whyWrongChoices":"Alternative options: cardiac output & heart rate, LDL & HDL levels, LDL size & particle number"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:epa and dha can help reduce heart disease risk due to their beneficial effects on::::', 'epa and dha can help reduce heart disease risk due to their beneficial effects on:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Omega-3 fatty acids, specifically eicosapentaenoic acid (EPA) and docosahexaenoic acid (DHA), have a well-documented, powerful effect on reducing serum triglyceride levels. They do this by decreasing the liver''s production of VLDL (very-low-density lipoprotein) and speeding up the clearance of triglycerides from the blood.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"triglyceride levels & blood clotting activity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Omega-3 fatty acids, specifically eicosapentaenoic acid (EPA) and docosahexaenoic acid (DHA), have a well-documented, powerful effect on reducing serum triglyceride levels. They do this by decreasing the liver''s production of VLDL (very-low-density lipoprotein) and speeding up the clearance of triglycerides from the blood.\n\nEPA and DHA also reduce blood clotting activity (platelet aggregation). They displace arachidonic acid in cell membranes, which reduces the production of thromboxane A2 (a compound that causes platelets to clump together and form clots) and shifts the body toward a more antithrombotic, clot-preventing state.\n\n• LDL & HDL levels: While omega-3s can slightly raise HDL (\"good\") cholesterol, high doses of DHA can actually increase LDL (\"bad\") cholesterol levels in some individuals, making this a less uniform or beneficial primary mechanism.\n• Cardiac output & heart rate: Omega-3s do support a stable heart rhythm and improve heart rate variability, but they do not primarily lower heart disease risk by altering baseline cardiac output or basic resting heart rate.\n• LDL size & particle number: This is the primary target mechanism for medications like statins or advanced lipid therapies rather than the signature biochemical profile of marine omega-3 oils.","whyWrongChoices":"Alternative options: cardiac output & heart rate, LDL & HDL levels, LDL size & particle number"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it must be supplemented in glycogen storage disease::::calcium', 'it must be supplemented in glycogen storage disease:', 'calcium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with hepatic glycogen storage disease (GSD)—especially Type I—cannot properly break down stored glycogen into free glucose. Because they are at constant risk for life-threatening hypoglycemia, their therapeutic diets must strictly eliminate fructose, sucrose, and galactose (found heavily in milk, fruit juices, and dairy products).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"calcium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with hepatic glycogen storage disease (GSD)—especially Type I—cannot properly break down stored glycogen into free glucose. Because they are at constant risk for life-threatening hypoglycemia, their therapeutic diets must strictly eliminate fructose, sucrose, and galactose (found heavily in milk, fruit juices, and dairy products).\n\nEliminating standard dairy items from their diet completely cuts out the primary natural food source of calcium. Furthermore, continuous round-the-clock reliance on uncooked cornstarch therapies can sometimes interfere with optimal nutrient assimilation. Because of these necessary constraints, calcium (along with Vitamin D) must be heavily supplemented to avoid metabolic deficits, optimize skeletal density, and prevent the early development of osteoporosis.","whyWrongChoices":"Alternative options: iron, vitamin K, potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it must be supplemented in glycogen storage disease::::', 'it must be supplemented in glycogen storage disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with hepatic glycogen storage disease (GSD)—especially Type I—cannot properly break down stored glycogen into free glucose. Because they are at constant risk for life-threatening hypoglycemia, their therapeutic diets must strictly eliminate fructose, sucrose, and galactose (found heavily in milk, fruit juices, and dairy products).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"calcium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with hepatic glycogen storage disease (GSD)—especially Type I—cannot properly break down stored glycogen into free glucose. Because they are at constant risk for life-threatening hypoglycemia, their therapeutic diets must strictly eliminate fructose, sucrose, and galactose (found heavily in milk, fruit juices, and dairy products).\n\nEliminating standard dairy items from their diet completely cuts out the primary natural food source of calcium. Furthermore, continuous round-the-clock reliance on uncooked cornstarch therapies can sometimes interfere with optimal nutrient assimilation. Because of these necessary constraints, calcium (along with Vitamin D) must be heavily supplemented to avoid metabolic deficits, optimize skeletal density, and prevent the early development of osteoporosis.","whyWrongChoices":"Alternative options: iron, vitamin K, potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a very common cause of chronic kidney disease is::::diabetes mellitus', 'a very common cause of chronic kidney disease is:', 'diabetes mellitus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Globally and across clinical dietetics textbooks, diabetes mellitus is recognized as the leading and most common primary cause of chronic kidney disease (CKD) and end-stage renal disease (ESRD).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diabetes mellitus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Globally and across clinical dietetics textbooks, diabetes mellitus is recognized as the leading and most common primary cause of chronic kidney disease (CKD) and end-stage renal disease (ESRD).\n\nHigh blood glucose levels chronically damage the delicate microvascular filtering systems (glomeruli) of the kidneys, a condition clinically termed diabetic nephropathy.\n\nIn medical statistics, diabetes and HPN (Hypertension / High Blood Pressure) together account for roughly 2 out of 3 new cases of kidney failure, with diabetes consistently claiming the number one spot.","whyWrongChoices":"Alternative options: exposure to toxins, autoimmune disease, HPN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
