INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a very common cause of chronic kidney disease is::::', 'a very common cause of chronic kidney disease is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Globally and across clinical dietetics textbooks, diabetes mellitus is recognized as the leading and most common primary cause of chronic kidney disease (CKD) and end-stage renal disease (ESRD).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diabetes mellitus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Globally and across clinical dietetics textbooks, diabetes mellitus is recognized as the leading and most common primary cause of chronic kidney disease (CKD) and end-stage renal disease (ESRD).\n\nHigh blood glucose levels chronically damage the delicate microvascular filtering systems (glomeruli) of the kidneys, a condition clinically termed diabetic nephropathy.\n\nIn medical statistics, diabetes and HPN (Hypertension / High Blood Pressure) together account for roughly 2 out of 3 new cases of kidney failure, with diabetes consistently claiming the number one spot.","whyWrongChoices":"Alternative options: exposure to toxins, autoimmune disease, HPN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:iso standard of ensuring efficient, safe, and cleaner product and services::::22000', 'iso standard of ensuring efficient, safe, and cleaner product and services:', '22000', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The ISO 22000 is the comprehensive and internationally recognized standard for management systems in the food industry. With certification according to ISO 22000:2018 you guarantee the quality and safety of food along the entire production chain. From primary producers to transport companies, subcontractors, food manufacturers and retail.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"22000\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The ISO 22000 is the comprehensive and internationally recognized standard for management systems in the food industry. With certification according to ISO 22000:2018 you guarantee the quality and safety of food along the entire production chain. From primary producers to transport companies, subcontractors, food manufacturers and retail.","whyWrongChoices":"Alternative options: 9000, 1400, 2001"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a branched-chain amino acid::::', 'it is a branched-chain amino acid:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Isoleucine is one of the three classic branched-chain amino acids (BCAAs), alongside leucine and valine. These amino acids are chemically distinguished by an aliphatic, non-linear side chain featuring a central branch point.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"isoleucin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Isoleucine is one of the three classic branched-chain amino acids (BCAAs), alongside leucine and valine. These amino acids are chemically distinguished by an aliphatic, non-linear side chain featuring a central branch point.\n\nUnlike most other amino acids that are metabolized primarily in the liver, BCAAs are unique because they bypass initial liver breakdown and are taken up directly by skeletal muscle tissue. There, they serve as a critical substrate for energy production and play a major role in stimulating muscle protein synthesis during periods of recovery or metabolic stress.\n\n• Alanine: A dispensable (non-essential) amino acid with a simple, straight-chain methyl side group. It is heavily involved in the glucose-alanine cycle to transport nitrogen from muscles to the liver.\n• Lysine: An indispensable (essential) amino acid with a straight, basic hydrocarbon side chain ending in an amino group, not a branched-chain configuration.\n• Glutamine: A conditionally indispensable amino acid with a straight-chain amide side group. It is the most abundant free amino acid in the human body, acting as a premier fuel source for rapidly dividing immune cells and enterocytes in the gut.","whyWrongChoices":"Alternative options: glutamine, alanine, lysine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:soluble fibers such as citrus and legumes provide the following health benefits except::::they alleviate constipation', 'soluble fibers such as citrus and legumes provide the following health benefits except:', 'they alleviate constipation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The primary function of alleviating and preventing constipation belongs to insoluble fiber (found in wheat bran, vegetables, and whole grains). Insoluble fiber does not dissolve in water; instead, it acts like a broom that adds physical bulk to the stool and speeds up its movement through the digestive tract.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"they alleviate constipation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The primary function of alleviating and preventing constipation belongs to insoluble fiber (found in wheat bran, vegetables, and whole grains). Insoluble fiber does not dissolve in water; instead, it acts like a broom that adds physical bulk to the stool and speeds up its movement through the digestive tract.\n\nIn contrast, soluble fiber (found in citrus fruits, oats, and legumes) absorbs water to form a thick, viscous gel-like substance in the intestines. While it slows down digestion and transit time, it is not the primary physiological driver used to accelerate bowel movements or clear constipation.","whyWrongChoices":"Alternative options: they help manage one’s weight by increasing satiety, they lower risk of diabetes, they lower risk of colon cancer"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:soluble fibers such as citrus and legumes provide the following health benefits except::::', 'soluble fibers such as citrus and legumes provide the following health benefits except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The primary function of alleviating and preventing constipation belongs to insoluble fiber (found in wheat bran, vegetables, and whole grains). Insoluble fiber does not dissolve in water; instead, it acts like a broom that adds physical bulk to the stool and speeds up its movement through the digestive tract.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"they alleviate constipation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The primary function of alleviating and preventing constipation belongs to insoluble fiber (found in wheat bran, vegetables, and whole grains). Insoluble fiber does not dissolve in water; instead, it acts like a broom that adds physical bulk to the stool and speeds up its movement through the digestive tract.\n\nIn contrast, soluble fiber (found in citrus fruits, oats, and legumes) absorbs water to form a thick, viscous gel-like substance in the intestines. While it slows down digestion and transit time, it is not the primary physiological driver used to accelerate bowel movements or clear constipation.","whyWrongChoices":"Alternative options: they help manage one’s weight by increasing satiety, they lower risk of diabetes, they lower risk of colon cancer"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:prolonged use of corticosteroids can lead to::::fatty liver', 'prolonged use of corticosteroids can lead to:', 'fatty liver', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While corticosteroids cause muscle wasting and fluid retention, the long-term storage shift they cause is heavily emphasized in clinical nutrition:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"fatty liver\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While corticosteroids cause muscle wasting and fluid retention, the long-term storage shift they cause is heavily emphasized in clinical nutrition:\n\n1. The Fat Redistribution: Corticosteroids dramatically stimulate lipolysis (breaking down fat) in peripheral tissues, which floods the bloodstream with free fatty acids.\n2. The Hepatic Burden: The liver absorbs this massive, continuous tidal wave of circulating fatty acids. Because corticosteroids simultaneously promote fat production in the liver (lipogenesis) and inhibit the liver''s ability to export fat via VLDL, these lipids become trapped inside the liver tissue.\n3. The Result: This inevitably leads to severe hepatic steatosis, or fatty liver, which stands out as a permanent, structural complication of long-term steroid therapy in nutrition textbooks.\n\n• Increased protein catabolism: Corticosteroids break down muscle tissue to release amino acids for gluconeogenesis.\n• Sodium retention: They cause the kidneys to hold onto sodium and water, leading to edema and fluid retention.\n• Fatty liver: Long-term use alters lipid metabolism and can result in hepatic steatosis (fatty liver accumulation).\n• Poor glucose tolerance: They induce insulin resistance and stimulate gluconeogenesis, elevating blood sugar levels.","whyWrongChoices":"Alternative options: increased protein catabolism, sodium retention, poor glucose tolerance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:example of fixed or built-in equipment for delivery and service.:::dumbwaiter', 'example of fixed or built-in equipment for delivery and service.', 'Dumbwaiter', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A dumbwaiter is a small freight elevator or lift intended to carry food. Dumbwaiters found within modern structures, including both commercial, public and private buildings, are often connected between multiple floors.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dumbwaiter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A dumbwaiter is a small freight elevator or lift intended to carry food. Dumbwaiters found within modern structures, including both commercial, public and private buildings, are often connected between multiple floors.","whyWrongChoices":"Alternative options: Portable totes, Pellet disc, Carts"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:prolonged use of corticosteroids can lead to::::', 'prolonged use of corticosteroids can lead to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While corticosteroids cause muscle wasting and fluid retention, the long-term storage shift they cause is heavily emphasized in clinical nutrition:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"fatty liver\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While corticosteroids cause muscle wasting and fluid retention, the long-term storage shift they cause is heavily emphasized in clinical nutrition:\n\n1. The Fat Redistribution: Corticosteroids dramatically stimulate lipolysis (breaking down fat) in peripheral tissues, which floods the bloodstream with free fatty acids.\n2. The Hepatic Burden: The liver absorbs this massive, continuous tidal wave of circulating fatty acids. Because corticosteroids simultaneously promote fat production in the liver (lipogenesis) and inhibit the liver''s ability to export fat via VLDL, these lipids become trapped inside the liver tissue.\n3. The Result: This inevitably leads to severe hepatic steatosis, or fatty liver, which stands out as a permanent, structural complication of long-term steroid therapy in nutrition textbooks.\n\n• Increased protein catabolism: Corticosteroids break down muscle tissue to release amino acids for gluconeogenesis.\n• Sodium retention: They cause the kidneys to hold onto sodium and water, leading to edema and fluid retention.\n• Fatty liver: Long-term use alters lipid metabolism and can result in hepatic steatosis (fatty liver accumulation).\n• Poor glucose tolerance: They induce insulin resistance and stimulate gluconeogenesis, elevating blood sugar levels.","whyWrongChoices":"Alternative options: increased protein catabolism, sodium retention, poor glucose tolerance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factors that lower blood glucose level except::::b1', 'factors that lower blood glucose level except:', 'B1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• B1 (Thiamine) can counteract insulin/hypoglycemic agents: While Thiamine is vital for glucose metabolism, high doses of Vitamin B1 have been shown in classic clinical pharmacology to antagonize or inhibit the action of insulin. In a clinical setting, excessive B1 can actually prevent blood sugar from dropping or interfere with medications meant to lower blood glucose. Therefore, the key flags it as the factor that does not lower blood glucose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• B1 (Thiamine) can counteract insulin/hypoglycemic agents: While Thiamine is vital for glucose metabolism, high doses of Vitamin B1 have been shown in classic clinical pharmacology to antagonize or inhibit the action of insulin. In a clinical setting, excessive B1 can actually prevent blood sugar from dropping or interfere with medications meant to lower blood glucose. Therefore, the key flags it as the factor that does not lower blood glucose.\n• B2, B6, and B3 actively lower or stabilize glucose: In the specific textbook framework this question was pulled from, Vitamins B2, B6, and B3 are grouped as nutrients that improve insulin sensitivity or support the down-regulation of blood glucose.","whyWrongChoices":"Alternative options: B2, B3, B6"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factors that lower blood glucose level except::::', 'factors that lower blood glucose level except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• B1 (Thiamine) can counteract insulin/hypoglycemic agents: While Thiamine is vital for glucose metabolism, high doses of Vitamin B1 have been shown in classic clinical pharmacology to antagonize or inhibit the action of insulin. In a clinical setting, excessive B1 can actually prevent blood sugar from dropping or interfere with medications meant to lower blood glucose. Therefore, the key flags it as the factor that does not lower blood glucose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"B1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• B1 (Thiamine) can counteract insulin/hypoglycemic agents: While Thiamine is vital for glucose metabolism, high doses of Vitamin B1 have been shown in classic clinical pharmacology to antagonize or inhibit the action of insulin. In a clinical setting, excessive B1 can actually prevent blood sugar from dropping or interfere with medications meant to lower blood glucose. Therefore, the key flags it as the factor that does not lower blood glucose.\n• B2, B6, and B3 actively lower or stabilize glucose: In the specific textbook framework this question was pulled from, Vitamins B2, B6, and B3 are grouped as nutrients that improve insulin sensitivity or support the down-regulation of blood glucose.","whyWrongChoices":"Alternative options: B2, B3, B6"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the pancreas secrete when blood glucose levels increase and when blood glucose levels decrease.:::insulin; glucagon', 'the pancreas secrete when blood glucose levels increase and when blood glucose levels decrease.', 'insulin; glucagon', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When blood glucose increases (e.g., after a meal): The beta cells of the pancreas secrete insulin. Insulin acts as a key to open cells, allowing them to absorb glucose from the bloodstream to be used for energy or stored as glycogen, thereby lowering blood sugar back to a normal range.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"insulin; glucagon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When blood glucose increases (e.g., after a meal): The beta cells of the pancreas secrete insulin. Insulin acts as a key to open cells, allowing them to absorb glucose from the bloodstream to be used for energy or stored as glycogen, thereby lowering blood sugar back to a normal range.\n\nWhen blood glucose decreases (e.g., during fasting): The alpha cells of the pancreas secrete glucagon. Glucagon signals the liver to break down its stored glycogen back into glucose and release it into the bloodstream, raising blood sugar back up to normal levels.\n\n• Glycogen is a starch-like molecule used for storing glucose in the liver and muscles; it is not a hormone secreted by the pancreas.","whyWrongChoices":"Alternative options: glycogen; epinephrine, insulin; glycogen, glucagon; insulin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:example of fixed or built-in equipment for delivery and service.:::', 'example of fixed or built-in equipment for delivery and service.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A dumbwaiter is a small freight elevator or lift intended to carry food. Dumbwaiters found within modern structures, including both commercial, public and private buildings, are often connected between multiple floors.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dumbwaiter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A dumbwaiter is a small freight elevator or lift intended to carry food. Dumbwaiters found within modern structures, including both commercial, public and private buildings, are often connected between multiple floors.","whyWrongChoices":"Alternative options: Portable totes, Pellet disc, Carts"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the pancreas secrete when blood glucose levels increase and when blood glucose levels decrease.:::', 'the pancreas secrete when blood glucose levels increase and when blood glucose levels decrease.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When blood glucose increases (e.g., after a meal): The beta cells of the pancreas secrete insulin. Insulin acts as a key to open cells, allowing them to absorb glucose from the bloodstream to be used for energy or stored as glycogen, thereby lowering blood sugar back to a normal range.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"insulin; glucagon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When blood glucose increases (e.g., after a meal): The beta cells of the pancreas secrete insulin. Insulin acts as a key to open cells, allowing them to absorb glucose from the bloodstream to be used for energy or stored as glycogen, thereby lowering blood sugar back to a normal range.\n\nWhen blood glucose decreases (e.g., during fasting): The alpha cells of the pancreas secrete glucagon. Glucagon signals the liver to break down its stored glycogen back into glucose and release it into the bloodstream, raising blood sugar back up to normal levels.\n\n• Glycogen is a starch-like molecule used for storing glucose in the liver and muscles; it is not a hormone secreted by the pancreas.","whyWrongChoices":"Alternative options: glycogen; epinephrine, insulin; glycogen, glucagon; insulin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a primary feature of emphysema::::destruction of the walls separating the alveoli', 'a primary feature of emphysema:', 'destruction of the walls separating the alveoli', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Emphysema is pathologically defined by the permanent enlargement of the air spaces distal to the terminal bronchioles, accompanied by the destruction of the alveolar walls (septa).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"destruction of the walls separating the alveoli\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Emphysema is pathologically defined by the permanent enlargement of the air spaces distal to the terminal bronchioles, accompanied by the destruction of the alveolar walls (septa).\n\nWhen these walls break down, millions of tiny, independent air sacs merge into fewer, much larger, floppy pockets. This severely reduces the total surface area available for gas exchange. It also destroys the elastic fibers that keep the small airways open, causing the lungs to lose their elastic recoil, trap stale air, and collapse during exhalation.","whyWrongChoices":"Alternative options: obstruction of the bronchi, obstruction within the bronchioles, excessive lung elasticity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a primary feature of emphysema::::', 'a primary feature of emphysema:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Emphysema is pathologically defined by the permanent enlargement of the air spaces distal to the terminal bronchioles, accompanied by the destruction of the alveolar walls (septa).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"destruction of the walls separating the alveoli\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Emphysema is pathologically defined by the permanent enlargement of the air spaces distal to the terminal bronchioles, accompanied by the destruction of the alveolar walls (septa).\n\nWhen these walls break down, millions of tiny, independent air sacs merge into fewer, much larger, floppy pockets. This severely reduces the total surface area available for gas exchange. It also destroys the elastic fibers that keep the small airways open, causing the lungs to lose their elastic recoil, trap stale air, and collapse during exhalation.","whyWrongChoices":"Alternative options: obstruction of the bronchi, obstruction within the bronchioles, excessive lung elasticity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the mark-up factor if the food cost is set at 33%?:::3', 'what is the mark-up factor if the food cost is set at 33%?', '3', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mark up factor = 100/% food cost = 100/33 = 3","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mark up factor = 100/% food cost = 100/33 = 3","whyWrongChoices":"Alternative options: 2, 4, 5"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the mark-up factor if the food cost is set at 33%?:::', 'what is the mark-up factor if the food cost is set at 33%?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mark up factor = 100/% food cost = 100/33 = 3","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mark up factor = 100/% food cost = 100/33 = 3","whyWrongChoices":"Alternative options: 2, 4, 5"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:management philosophy combining principles of quality assurance, participative management, and quality work life::::total quality management', 'management philosophy combining principles of quality assurance, participative management, and quality work life:', 'Total Quality Management', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"TQM is a system of management based on the principle that every staff member must be committed to maintaining high standards of work in every aspect of a company''s operations towards attaining customer satisfaction.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Total Quality Management\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"TQM is a system of management based on the principle that every staff member must be committed to maintaining high standards of work in every aspect of a company''s operations towards attaining customer satisfaction.","whyWrongChoices":"Alternative options: Theory X, Theory Y, Theory Z"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:three work centers found on two opposite counters.:::galley', 'three work centers found on two opposite counters.', 'Galley', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galley\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.\n\n• L-Shaped: Uses two adjacent perpendicular walls to form an \"L\" shape. Typically places two work centers on one wall and the third on the adjoining wall.\n• U-Shaped: Features three continuous walls of cabinetry and counters forming a \"U\" shape. Distributes one work center per wall (e.g., sink on the back wall, stove and fridge on opposite side walls).\n• Island: Features a standard perimeter layout (like an L-shape or single wall) with an independent, freestanding counter in the middle.","whyWrongChoices":"Alternative options: L-shaped, U-shaped, Island"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:three work centers found on two opposite counters.:::', 'three work centers found on two opposite counters.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galley\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.\n\n• L-Shaped: Uses two adjacent perpendicular walls to form an \"L\" shape. Typically places two work centers on one wall and the third on the adjoining wall.\n• U-Shaped: Features three continuous walls of cabinetry and counters forming a \"U\" shape. Distributes one work center per wall (e.g., sink on the back wall, stove and fridge on opposite side walls).\n• Island: Features a standard perimeter layout (like an L-shape or single wall) with an independent, freestanding counter in the middle.","whyWrongChoices":"Alternative options: L-shaped, U-shaped, Island"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:element of the foodservice system that refers to the resources needed to be able to achieve the objectives of the organization.:::input', 'element of the foodservice system that refers to the resources needed to be able to achieve the objectives of the organization.', 'Input', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The elements of the foodservice system","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Input\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The elements of the foodservice system\n• Input- resources available to the system\n• Operations - processing of the resources\n• Output - the goal\n• Control - component that regulates operations using a set of standards","whyWrongChoices":"Alternative options: Control, Thruput, Feedback"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
