INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:japanese style of management in which workers are seen as the key to increased productivity::::theory z', 'japanese style of management in which workers are seen as the key to increased productivity:', 'Theory Z', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"William Ouchi’s Theory Z makes certain assumptions about workers. One assumption is that they seek to build cooperative and intimate working relationships with their coworkers. In other words, employees have a strong desire for affiliation. Another assumption is that workers expect reciprocity and support from the company. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Theory Z\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"William Ouchi’s Theory Z makes certain assumptions about workers. One assumption is that they seek to build cooperative and intimate working relationships with their coworkers. In other words, employees have a strong desire for affiliation. Another assumption is that workers expect reciprocity and support from the company. \n\nAccording to Theory Z, people want to maintain a work-life balance, and they value a working environment in which things like family, culture, and traditions are considered to be just as important as the work itself. Under Theory Z management, not only do workers have a sense of cohesion with their fellow workers, they also develop a sense of order, discipline, and a moral obligation to work hard. \n\nFinally, Theory Z assumes that given the right management support, workers can be trusted to do their jobs to their utmost ability and look after for their own and others’ well-being.","whyWrongChoices":"Alternative options: Theory X, Theory Y, Total Quality Management"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:japanese style of management in which workers are seen as the key to increased productivity::::', 'japanese style of management in which workers are seen as the key to increased productivity:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"William Ouchi’s Theory Z makes certain assumptions about workers. One assumption is that they seek to build cooperative and intimate working relationships with their coworkers. In other words, employees have a strong desire for affiliation. Another assumption is that workers expect reciprocity and support from the company. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Theory Z\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"William Ouchi’s Theory Z makes certain assumptions about workers. One assumption is that they seek to build cooperative and intimate working relationships with their coworkers. In other words, employees have a strong desire for affiliation. Another assumption is that workers expect reciprocity and support from the company. \n\nAccording to Theory Z, people want to maintain a work-life balance, and they value a working environment in which things like family, culture, and traditions are considered to be just as important as the work itself. Under Theory Z management, not only do workers have a sense of cohesion with their fellow workers, they also develop a sense of order, discipline, and a moral obligation to work hard. \n\nFinally, Theory Z assumes that given the right management support, workers can be trusted to do their jobs to their utmost ability and look after for their own and others’ well-being.","whyWrongChoices":"Alternative options: Theory X, Theory Y, Total Quality Management"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:breakdown of task into organized activity considering time and sequence of operation::::work schedule', 'breakdown of task into organized activity considering time and sequence of operation:', 'Work schedule', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Work schedule – an outline of work to be performed, procedures to be used, and time schedule for a particular position. Workers may be scheduled successfully only after thorough analysis and study of the jobs to be done, the working conditions, and the probable efficiency of the employees.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Work schedule\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Work schedule – an outline of work to be performed, procedures to be used, and time schedule for a particular position. Workers may be scheduled successfully only after thorough analysis and study of the jobs to be done, the working conditions, and the probable efficiency of the employees.","whyWrongChoices":"Alternative options: Organizational chart, Daily Tally sheet, Evaluation sheet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:breakdown of task into organized activity considering time and sequence of operation::::', 'breakdown of task into organized activity considering time and sequence of operation:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Work schedule – an outline of work to be performed, procedures to be used, and time schedule for a particular position. Workers may be scheduled successfully only after thorough analysis and study of the jobs to be done, the working conditions, and the probable efficiency of the employees.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Work schedule\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Work schedule – an outline of work to be performed, procedures to be used, and time schedule for a particular position. Workers may be scheduled successfully only after thorough analysis and study of the jobs to be done, the working conditions, and the probable efficiency of the employees.","whyWrongChoices":"Alternative options: Organizational chart, Daily Tally sheet, Evaluation sheet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a collection of data about the market and other factors. it is conducted to determine if the project is worth pursuing.:::feasibility study', 'a collection of data about the market and other factors. it is conducted to determine if the project is worth pursuing.', 'Feasibility study', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A feasibility study is acollection of data about the market and other factors. It is conducted to determine if the project is worth pursuing. It includes: The Prospectus, Research on the proposed site, Design trends, Market research, Community growth, Competition in the area, Financial goals, and Standard Operating Procedures.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Feasibility study\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A feasibility study is acollection of data about the market and other factors. It is conducted to determine if the project is worth pursuing. It includes: The Prospectus, Research on the proposed site, Design trends, Market research, Community growth, Competition in the area, Financial goals, and Standard Operating Procedures.","whyWrongChoices":"Alternative options: Market survey, Market acceptability, Consumer demand survey"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
