('mc:component of plp.:::', 'component of plp.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pyridoxal 5′-phosphate (PLP) is the active, functional form of Vitamin B6 in the body. Vitamin B6 can be converted to the coenzyme PLP that transfers amino groups from amino acid to make nonessential amino acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit B6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pyridoxal 5′-phosphate (PLP) is the active, functional form of Vitamin B6 in the body. Vitamin B6 can be converted to the coenzyme PLP that transfers amino groups from amino acid to make nonessential amino acids.","whyWrongChoices":"Alternative options: Vit B1, Vit B12"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:its other name is pteroylglutamic acid; also citrovocum factor, lactobacillus casei factor, vitamin m, and factor u.:::folic acid', 'its other name is pteroylglutamic acid; also citrovocum factor, lactobacillus casei factor, vitamin m, and factor u.', 'Folic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Other names of folic acid is folate, folacin, citrovorum factor, lactobacillus casei factor, Vitamin M, Vitamin B and Factor U.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Folic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Other names of folic acid is folate, folacin, citrovorum factor, lactobacillus casei factor, Vitamin M, Vitamin B and Factor U.","whyWrongChoices":"Alternative options: Iron, Niacin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a mineral involved taste perception, sperm production, immune function, and is also proven to cure diarrhea among children.:::zinc', 'a mineral involved taste perception, sperm production, immune function, and is also proven to cure diarrhea among children.', 'Zinc', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc plays an indispensable role in taste perception (as a structural component of gustin/carbonic anhydrase VI), sperm production and male fertility, and immune system function (mediating T-cell development and macrophage function).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zinc\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc plays an indispensable role in taste perception (as a structural component of gustin/carbonic anhydrase VI), sperm production and male fertility, and immune system function (mediating T-cell development and macrophage function).\n\nCrucially, clinical trials and healthcare bodies like the WHO explicitly recognize and recommend short-term zinc supplementation as an effective treatment to reduce the severity and duration of diarrhea among children.\n\n• The other listed minerals (Selenium, Magnesium, and Manganese) are vital micronutrients but do not fit this specific, clinically proven combination of functions—particularly the specific therapeutic use for pediatric diarrhea.","whyWrongChoices":"Alternative options: Selenium, Magnesium, Manganese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
