INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:which is a biological contaminant?:::molds', 'which is a biological contaminant?', 'Molds', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A biological contaminant refers to living organisms, or substances produced by living organisms, that can make food unsafe. Molds are microscopic fungi (living organisms) that can grow on food, produce dangerous mycotoxins, and cause foodborne illnesses or allergic reactions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Molds\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A biological contaminant refers to living organisms, or substances produced by living organisms, that can make food unsafe. Molds are microscopic fungi (living organisms) that can grow on food, produce dangerous mycotoxins, and cause foodborne illnesses or allergic reactions.\n\n• Soil: A physical contaminant. It is an inanimate, foreign object or material that accidentally gets into food from the environment.\n• Insecticides: A chemical contaminant. This category includes toxic chemical substances such as pest control products, cleaning agents, and sanitizers.\n• Hair strand: A physical contaminant. It is a tangible, foreign object introduced during handling or preparation that poses a physical hazard or gross aesthetic issue.","whyWrongChoices":"Alternative options: Insecticides, Hair strand, Soil"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is a biological contaminant?:::', 'which is a biological contaminant?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A biological contaminant refers to living organisms, or substances produced by living organisms, that can make food unsafe. Molds are microscopic fungi (living organisms) that can grow on food, produce dangerous mycotoxins, and cause foodborne illnesses or allergic reactions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Molds\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A biological contaminant refers to living organisms, or substances produced by living organisms, that can make food unsafe. Molds are microscopic fungi (living organisms) that can grow on food, produce dangerous mycotoxins, and cause foodborne illnesses or allergic reactions.\n\n• Soil: A physical contaminant. It is an inanimate, foreign object or material that accidentally gets into food from the environment.\n• Insecticides: A chemical contaminant. This category includes toxic chemical substances such as pest control products, cleaning agents, and sanitizers.\n• Hair strand: A physical contaminant. It is a tangible, foreign object introduced during handling or preparation that poses a physical hazard or gross aesthetic issue.","whyWrongChoices":"Alternative options: Insecticides, Hair strand, Soil"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:consumer act of the philippines:::', 'consumer act of the philippines', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Republic Act No. 7394, enacted in 1992, is officially known as the Consumer Act of the Philippines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"RA 7394\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Republic Act No. 7394, enacted in 1992, is officially known as the Consumer Act of the Philippines.\n\nIts primary objective is to protect the interests of consumers, promote their general welfare, and establish high standards of conduct for business and industry. In foodservice and hospitality, it heavily regulates truth-in-menu laws, food product labeling, deceptive sales acts, and consumer product safety.\n\n• RA 3720: The Food, Drug, and Cosmetic Act, which focuses on ensuring the pureness, safety, and proper labeling of foods, drugs, and cosmetics.\n• PD 704: The Fisheries Decree of 1975, which governs the preservation, development, and utilization of fishery and aquatic resources.\n• PD 856: The Code on Sanitation of the Philippines, which dictates structural public health and sanitary rules for food operations.","whyWrongChoices":"Alternative options: PD 704, RA 3720, PD 856"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foodborne illness caused by a neurotoxin found in food.:::botulism', 'foodborne illness caused by a neurotoxin found in food.', 'Botulism', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Botulism is caused by a highly potent nerve-attacking toxin (botulinum neurotoxin) produced by the spore-forming bacterium Clostridium botulinum.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Botulism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Botulism is caused by a highly potent nerve-attacking toxin (botulinum neurotoxin) produced by the spore-forming bacterium Clostridium botulinum.\n\nUnlike standard foodborne pathogens that attack the gastrointestinal tract directly, this neurotoxin enters the bloodstream and binds to nerve endings, blocking the release of acetylcholine. This leads to specialized neurological symptoms such as double vision, drooping eyelids, difficulty swallowing, and progressive descending muscle paralysis. It is most commonly associated with improperly home-canned or fermented low-acid foods.\n\n• Yersiniosis: An infection caused by Yersinia enterocolitica (often from undercooked pork) that triggers standard gastrointestinal distress and mimics appendicitis, rather than releasing a neurotoxin.\n• Listeriosis: A serious infection caused by Listeria monocytogenes (often from deli meats or unpasteurized dairy). While it can cross into the nervous system causing meningitis in high-risk individuals, it is an invasive bacterial infection rather than an illness caused by pre-formed neurotoxins in food.\n• Salmonellosis: A classic foodborne infection caused by Salmonella bacteria that results in localized intestinal inflammation (diarrhea, fever, and stomach cramps).","whyWrongChoices":"Alternative options: Salmonellosis, Listeriosis, Yersiniosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foodborne illness caused by a neurotoxin found in food.:::', 'foodborne illness caused by a neurotoxin found in food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Botulism is caused by a highly potent nerve-attacking toxin (botulinum neurotoxin) produced by the spore-forming bacterium Clostridium botulinum.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Botulism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Botulism is caused by a highly potent nerve-attacking toxin (botulinum neurotoxin) produced by the spore-forming bacterium Clostridium botulinum.\n\nUnlike standard foodborne pathogens that attack the gastrointestinal tract directly, this neurotoxin enters the bloodstream and binds to nerve endings, blocking the release of acetylcholine. This leads to specialized neurological symptoms such as double vision, drooping eyelids, difficulty swallowing, and progressive descending muscle paralysis. It is most commonly associated with improperly home-canned or fermented low-acid foods.\n\n• Yersiniosis: An infection caused by Yersinia enterocolitica (often from undercooked pork) that triggers standard gastrointestinal distress and mimics appendicitis, rather than releasing a neurotoxin.\n• Listeriosis: A serious infection caused by Listeria monocytogenes (often from deli meats or unpasteurized dairy). While it can cross into the nervous system causing meningitis in high-risk individuals, it is an invasive bacterial infection rather than an illness caused by pre-formed neurotoxins in food.\n• Salmonellosis: A classic foodborne infection caused by Salmonella bacteria that results in localized intestinal inflammation (diarrhea, fever, and stomach cramps).","whyWrongChoices":"Alternative options: Salmonellosis, Listeriosis, Yersiniosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a defect that confronts frozen foods characterized by dehydration of food.:::freezer burn', 'a defect that confronts frozen foods characterized by dehydration of food.', 'freezer burn', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Freezer burn is a food quality defect directly caused by the dehydration (moisture loss) and sublimation of ice crystals from the surface of frozen food into the surrounding dry freezer air.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"freezer burn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Freezer burn is a food quality defect directly caused by the dehydration (moisture loss) and sublimation of ice crystals from the surface of frozen food into the surrounding dry freezer air.\n\nIt typically occurs when food is improperly wrapped or left in the freezer for too long. The affected areas look dry, discolored (grayish-brown on meats or white on poultry), and develop a tough, leathery texture due to the severe loss of moisture.\n\n• Oxidative deterioration: This refers to chemical reactions between oxygen and the fats or pigments in food, leading to rancidity and off-flavors. While freezer burn often accelerates oxidation because the dried-out surface allows oxygen to penetrate deep into the food tissue, oxidation itself is a chemical reaction rather than a physical dehydration defect.\n• Recrystallization: A physical process where small ice crystals inside frozen food melt and refreeze into larger ice crystals over time due to temperature fluctuations. This damages cell structures and causes drip loss when thawed, but it does not involve the total loss of moisture to the external air.\n• Protein denaturation: A structural change where food proteins lose their natural shape and functionality during long-term frozen storage, making the meat tough or spongy. It is a biochemical degradation rather than a surface dehydration defect.","whyWrongChoices":"Alternative options: oxidative deterioration, recrystallization, protein denaturation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a defect that confronts frozen foods characterized by dehydration of food.:::', 'a defect that confronts frozen foods characterized by dehydration of food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Freezer burn is a food quality defect directly caused by the dehydration (moisture loss) and sublimation of ice crystals from the surface of frozen food into the surrounding dry freezer air.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"freezer burn\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Freezer burn is a food quality defect directly caused by the dehydration (moisture loss) and sublimation of ice crystals from the surface of frozen food into the surrounding dry freezer air.\n\nIt typically occurs when food is improperly wrapped or left in the freezer for too long. The affected areas look dry, discolored (grayish-brown on meats or white on poultry), and develop a tough, leathery texture due to the severe loss of moisture.\n\n• Oxidative deterioration: This refers to chemical reactions between oxygen and the fats or pigments in food, leading to rancidity and off-flavors. While freezer burn often accelerates oxidation because the dried-out surface allows oxygen to penetrate deep into the food tissue, oxidation itself is a chemical reaction rather than a physical dehydration defect.\n• Recrystallization: A physical process where small ice crystals inside frozen food melt and refreeze into larger ice crystals over time due to temperature fluctuations. This damages cell structures and causes drip loss when thawed, but it does not involve the total loss of moisture to the external air.\n• Protein denaturation: A structural change where food proteins lose their natural shape and functionality during long-term frozen storage, making the meat tough or spongy. It is a biochemical degradation rather than a surface dehydration defect.","whyWrongChoices":"Alternative options: oxidative deterioration, recrystallization, protein denaturation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deterioration of canned items due to undercooling that results to growth thermophilic microorganism.:::flat sours', 'deterioration of canned items due to undercooling that results to growth thermophilic microorganism.', 'Flat sours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"•Flat sour spoilage is caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus). If cans are undercooled after thermal processing or stored in warm temperatures, these thermophilic spores survive and germinate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flat sours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"•Flat sour spoilage is caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus). If cans are undercooled after thermal processing or stored in warm temperatures, these thermophilic spores survive and germinate.\n\nThese microorganisms ferment the carbohydrates in the food and produce acid, but they do not produce gas. Because no gas is generated, the internal pressure remains unchanged, and the ends of the tin can stay completely flat and normal-looking from the outside. However, the food inside becomes sour and ruined.\n\n• Flipper: A normal-looking can where one end will flip out or bulge when the side of the can is pressed, or when the can is struck against a hard surface.\n• Hydrogen swell: A structural deformation caused by a chemical reaction between the acid in the food and the iron of the tinplate, producing hydrogen gas that bulges the can. It is not a thermophilic biological defect.\n• Springer: A mild swell condition where one end of the can is permanently bulged outward, and pressing it down pops the opposite end out instead.","whyWrongChoices":"Alternative options: Flipper, Springer, Hydrogen swell"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:group of microorganisms that can grow at very low temperatures.:::psychrophiles', 'group of microorganisms that can grow at very low temperatures.', 'psychrophiles', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Psychrophiles (and cold-tolerant psychrotrophs) are specialized microorganisms that are uniquely adapted to survive and grow at very low temperatures, ranging from -15°C to 20°C (5°F to 68°F). They are responsible for the slow spoilage of refrigerated and frozen foods over time.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"psychrophiles\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Psychrophiles (and cold-tolerant psychrotrophs) are specialized microorganisms that are uniquely adapted to survive and grow at very low temperatures, ranging from -15°C to 20°C (5°F to 68°F). They are responsible for the slow spoilage of refrigerated and frozen foods over time.\n\n• Xerophiles: Microorganisms that grow best in environments with very low water activity or extremely dry conditions (such as molds on dried fruits or grains).\n• Mesophiles: The largest group of bacteria, which thrive at moderate temperatures—typically between 20°C and 45°C (68°F to 113°F). Most common foodborne pathogens (like Salmonella and E. coli) are mesophiles.\n• Thermophiles: Heat-loving microorganisms that grow best at elevated temperatures, typically between 45°C and 80°C (113°F to 176°F). These are responsible for flat sour spoilage in undercooled canned goods.","whyWrongChoices":"Alternative options: mesophiles, thermophiles, xerophiles"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the anabolic formation of triacyglycerol from glycerol and fatty acids.:::', 'it refers to the anabolic formation of triacyglycerol from glycerol and fatty acids.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lipogenesis refers broadly to the formation and storage of fat, including the synthesis of triacylglycerol (TAG) from glycerol-derived molecules and fatty acids. It occurs primarily when energy intake exceeds immediate energy needs, allowing excess energy to be stored as body fat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lipogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lipogenesis refers broadly to the formation and storage of fat, including the synthesis of triacylglycerol (TAG) from glycerol-derived molecules and fatty acids. It occurs primarily when energy intake exceeds immediate energy needs, allowing excess energy to be stored as body fat.","whyWrongChoices":"Alternative options: Fatty acid synthesis, Cholesterol synthesis, Gluconeogenesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:group of microorganisms that can grow at very low temperatures.:::', 'group of microorganisms that can grow at very low temperatures.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Psychrophiles (and cold-tolerant psychrotrophs) are specialized microorganisms that are uniquely adapted to survive and grow at very low temperatures, ranging from -15°C to 20°C (5°F to 68°F). They are responsible for the slow spoilage of refrigerated and frozen foods over time.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"psychrophiles\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Psychrophiles (and cold-tolerant psychrotrophs) are specialized microorganisms that are uniquely adapted to survive and grow at very low temperatures, ranging from -15°C to 20°C (5°F to 68°F). They are responsible for the slow spoilage of refrigerated and frozen foods over time.\n\n• Xerophiles: Microorganisms that grow best in environments with very low water activity or extremely dry conditions (such as molds on dried fruits or grains).\n• Mesophiles: The largest group of bacteria, which thrive at moderate temperatures—typically between 20°C and 45°C (68°F to 113°F). Most common foodborne pathogens (like Salmonella and E. coli) are mesophiles.\n• Thermophiles: Heat-loving microorganisms that grow best at elevated temperatures, typically between 45°C and 80°C (113°F to 176°F). These are responsible for flat sour spoilage in undercooled canned goods.","whyWrongChoices":"Alternative options: mesophiles, thermophiles, xerophiles"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:principle behind the use of low temperature as a method of food preservation.:::reduction of water activity and speedy removal of heat', 'principle behind the use of low temperature as a method of food preservation.', 'Reduction of water activity and speedy removal of heat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When low temperature is used specifically as a long-term food preservation method (such as commercial freezing), the primary goal is the rapid removal of heat to solidify water into ice crystals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduction of water activity and speedy removal of heat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When low temperature is used specifically as a long-term food preservation method (such as commercial freezing), the primary goal is the rapid removal of heat to solidify water into ice crystals.\n\nTurning liquid water into ice directly reduces the water activity (aw) of the food. Because microorganisms require liquid water to metabolize nutrients, reproduce, and move, locking that water up in an unavailable crystalline form effectively halts their biological activity and preserves the product.","whyWrongChoices":"Alternative options: Killing the microbes by reducing oxygen and water activity, Killing the microbes by inactivating the enzymes, Protein denaturation and reduced oxygen availability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a theory of aging where cells are inactivated or defective as a result of errors in dna replication.:::', 'a theory of aging where cells are inactivated or defective as a result of errors in dna replication.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Genetic theory - Internal Clock/Programmed","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Somatic mutation theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Genetic theory - Internal Clock/Programmed\n• Wear-and-tear theory - External Damage/Breakdown\n• Cross-linkage theory - Molecular Rigidity/Stiffening","whyWrongChoices":"Alternative options: Genetic theory, Wear-and-Tear theory, Cross-linkage theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:principle behind the use of low temperature as a method of food preservation.:::', 'principle behind the use of low temperature as a method of food preservation.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When low temperature is used specifically as a long-term food preservation method (such as commercial freezing), the primary goal is the rapid removal of heat to solidify water into ice crystals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduction of water activity and speedy removal of heat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When low temperature is used specifically as a long-term food preservation method (such as commercial freezing), the primary goal is the rapid removal of heat to solidify water into ice crystals.\n\nTurning liquid water into ice directly reduces the water activity (aw) of the food. Because microorganisms require liquid water to metabolize nutrients, reproduce, and move, locking that water up in an unavailable crystalline form effectively halts their biological activity and preserves the product.","whyWrongChoices":"Alternative options: Killing the microbes by reducing oxygen and water activity, Killing the microbes by inactivating the enzymes, Protein denaturation and reduced oxygen availability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:code of sanitation of the philippines:::pd 856', 'code of sanitation of the philippines', 'PD 856', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Presidential Decree No. 856, signed in 1975, is officially known as the Code on Sanitation of the Philippines. It serves as the primary legal framework for public health and sanitation requirements in the country, dictating strict guidelines for food establishments, water supply, sewage disposal, and industrial hygiene.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PD 856\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Presidential Decree No. 856, signed in 1975, is officially known as the Code on Sanitation of the Philippines. It serves as the primary legal framework for public health and sanitation requirements in the country, dictating strict guidelines for food establishments, water supply, sewage disposal, and industrial hygiene.\n\n• RA 3720: The Food, Drug, and Cosmetic Act (later amended by RA 9711 as the Food and Drug Administration Act of 2009), which ensures the safety and purity of foods, drugs, and cosmetics.\n• RA 7394: The Consumer Act of the Philippines, which protects the interests of consumers, promotes their general welfare, and establishes standards of conduct for business and industry.\n• PD 704: The Fisheries Decree of 1975, which revised and consolidated all laws affecting fishing and fisheries in the Philippines.","whyWrongChoices":"Alternative options: RA 7394, PD 704, RA 3720"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which artificial sweetener is a methyl ester of a dipeptide composed of aspartic acid and phenylalanine?:::aspartame', 'which artificial sweetener is a methyl ester of a dipeptide composed of aspartic acid and phenylalanine?', 'Aspartame', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aspartame is 160 to 220 times sweeter than sucrose that is noncariogenic and has limited glycemic response.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspartame\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aspartame is 160 to 220 times sweeter than sucrose that is noncariogenic and has limited glycemic response.","whyWrongChoices":"Alternative options: Sucralose, Saccharin, Acesulfame potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:code of sanitation of the philippines:::', 'code of sanitation of the philippines', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Presidential Decree No. 856, signed in 1975, is officially known as the Code on Sanitation of the Philippines. It serves as the primary legal framework for public health and sanitation requirements in the country, dictating strict guidelines for food establishments, water supply, sewage disposal, and industrial hygiene.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PD 856\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Presidential Decree No. 856, signed in 1975, is officially known as the Code on Sanitation of the Philippines. It serves as the primary legal framework for public health and sanitation requirements in the country, dictating strict guidelines for food establishments, water supply, sewage disposal, and industrial hygiene.\n\n• RA 3720: The Food, Drug, and Cosmetic Act (later amended by RA 9711 as the Food and Drug Administration Act of 2009), which ensures the safety and purity of foods, drugs, and cosmetics.\n• RA 7394: The Consumer Act of the Philippines, which protects the interests of consumers, promotes their general welfare, and establishes standards of conduct for business and industry.\n• PD 704: The Fisheries Decree of 1975, which revised and consolidated all laws affecting fishing and fisheries in the Philippines.","whyWrongChoices":"Alternative options: RA 7394, PD 704, RA 3720"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:consumer act of the philippines:::ra 7394', 'consumer act of the philippines', 'RA 7394', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Republic Act No. 7394, enacted in 1992, is officially known as the Consumer Act of the Philippines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"RA 7394\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Republic Act No. 7394, enacted in 1992, is officially known as the Consumer Act of the Philippines.\n\nIts primary objective is to protect the interests of consumers, promote their general welfare, and establish high standards of conduct for business and industry. In foodservice and hospitality, it heavily regulates truth-in-menu laws, food product labeling, deceptive sales acts, and consumer product safety.\n\n• RA 3720: The Food, Drug, and Cosmetic Act, which focuses on ensuring the pureness, safety, and proper labeling of foods, drugs, and cosmetics.\n• PD 704: The Fisheries Decree of 1975, which governs the preservation, development, and utilization of fishery and aquatic resources.\n• PD 856: The Code on Sanitation of the Philippines, which dictates structural public health and sanitary rules for food operations.","whyWrongChoices":"Alternative options: PD 704, RA 3720, PD 856"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deterioration of canned items due to undercooling that results to growth thermophilic microorganism.:::', 'deterioration of canned items due to undercooling that results to growth thermophilic microorganism.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"•Flat sour spoilage is caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus). If cans are undercooled after thermal processing or stored in warm temperatures, these thermophilic spores survive and germinate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flat sours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"•Flat sour spoilage is caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus). If cans are undercooled after thermal processing or stored in warm temperatures, these thermophilic spores survive and germinate.\n\nThese microorganisms ferment the carbohydrates in the food and produce acid, but they do not produce gas. Because no gas is generated, the internal pressure remains unchanged, and the ends of the tin can stay completely flat and normal-looking from the outside. However, the food inside becomes sour and ruined.\n\n• Flipper: A normal-looking can where one end will flip out or bulge when the side of the can is pressed, or when the can is struck against a hard surface.\n• Hydrogen swell: A structural deformation caused by a chemical reaction between the acid in the food and the iron of the tinplate, producing hydrogen gas that bulges the can. It is not a thermophilic biological defect.\n• Springer: A mild swell condition where one end of the can is permanently bulged outward, and pressing it down pops the opposite end out instead.","whyWrongChoices":"Alternative options: Flipper, Springer, Hydrogen swell"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:microbes usually found in raw milk and undercooked chicken.:::campylobacter jejuni', 'microbes usually found in raw milk and undercooked chicken.', 'Campylobacter jejuni', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Campylobacter jejuni is a microaerophilic bacterium that naturally resides in the intestinal tracts of warm-blooded animals, especially poultry.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Campylobacter jejuni\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Campylobacter jejuni is a microaerophilic bacterium that naturally resides in the intestinal tracts of warm-blooded animals, especially poultry.\n\nIn food safety, it is the classic pathogen most heavily associated with the consumption of undercooked chicken (due to contamination during processing) and raw, unpasteurized milk (from dairy cows shedding the bacteria). Consuming even a tiny dose can trigger severe gastroenteritis (campylobacteriosis) characterized by fever, abdominal cramps, and often bloody diarrhea.\n\n• E. coli: While certain strains (like E. coli O157:H7) can contaminate raw milk and ground beef, its primary, textbook food vehicle is undercooked ground beef, contaminated fresh produce, or feces-contaminated water rather than being the definitive classic pair with poultry.\n• Vibrio parahaemolyticus: This halophilic (salt-loving) bacterium is strictly associated with marine environments. Its primary food vehicles are raw or undercooked seafood and shellfish (like oysters, crabs, and shrimp), never poultry or raw land-mammal milk.","whyWrongChoices":"Alternative options: E. coli, Vibrio parahaemolyticus, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:microbes usually found in raw milk and undercooked chicken.:::', 'microbes usually found in raw milk and undercooked chicken.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Campylobacter jejuni is a microaerophilic bacterium that naturally resides in the intestinal tracts of warm-blooded animals, especially poultry.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Campylobacter jejuni\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Campylobacter jejuni is a microaerophilic bacterium that naturally resides in the intestinal tracts of warm-blooded animals, especially poultry.\n\nIn food safety, it is the classic pathogen most heavily associated with the consumption of undercooked chicken (due to contamination during processing) and raw, unpasteurized milk (from dairy cows shedding the bacteria). Consuming even a tiny dose can trigger severe gastroenteritis (campylobacteriosis) characterized by fever, abdominal cramps, and often bloody diarrhea.\n\n• E. coli: While certain strains (like E. coli O157:H7) can contaminate raw milk and ground beef, its primary, textbook food vehicle is undercooked ground beef, contaminated fresh produce, or feces-contaminated water rather than being the definitive classic pair with poultry.\n• Vibrio parahaemolyticus: This halophilic (salt-loving) bacterium is strictly associated with marine environments. Its primary food vehicles are raw or undercooked seafood and shellfish (like oysters, crabs, and shrimp), never poultry or raw land-mammal milk.","whyWrongChoices":"Alternative options: E. coli, Vibrio parahaemolyticus, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar concentrate made from crushed fruit pulp only is:::jam', 'sugar concentrate made from crushed fruit pulp only is', 'Jam', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By standard food processing and culinary definitions, jam is a sweet spread prepared by boiling crushed or pureed fruit pulp with sugar until it reaches a gelled consistency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By standard food processing and culinary definitions, jam is a sweet spread prepared by boiling crushed or pureed fruit pulp with sugar until it reaches a gelled consistency.\n\nBecause it incorporates the crushed pulp, it has a uniform but slightly textured consistency that holds its shape well when spread, though it is softer and less rigid than jelly.\n\n• Preserve: Made using whole small fruits or uniform chunky pieces of fruit suspended in a clear, thick syrup, rather than using only fine pulp.\n• Spread: A broad, generic umbrella term for anything you wipe on bread (which can include butter, margarine, or cream cheese); it is not a specific culinary definition for pure pulp concentrates.\n• Jelly: Made strictly from clear fruit juice that has been filtered to remove all pulp and solid pieces, resulting in a firm, sparkling, translucent gel.","whyWrongChoices":"Alternative options: Jelly, Spread, Preserve"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar concentrate made from crushed fruit pulp only is:::', 'sugar concentrate made from crushed fruit pulp only is', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By standard food processing and culinary definitions, jam is a sweet spread prepared by boiling crushed or pureed fruit pulp with sugar until it reaches a gelled consistency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By standard food processing and culinary definitions, jam is a sweet spread prepared by boiling crushed or pureed fruit pulp with sugar until it reaches a gelled consistency.\n\nBecause it incorporates the crushed pulp, it has a uniform but slightly textured consistency that holds its shape well when spread, though it is softer and less rigid than jelly.\n\n• Preserve: Made using whole small fruits or uniform chunky pieces of fruit suspended in a clear, thick syrup, rather than using only fine pulp.\n• Spread: A broad, generic umbrella term for anything you wipe on bread (which can include butter, margarine, or cream cheese); it is not a specific culinary definition for pure pulp concentrates.\n• Jelly: Made strictly from clear fruit juice that has been filtered to remove all pulp and solid pieces, resulting in a firm, sparkling, translucent gel.","whyWrongChoices":"Alternative options: Jelly, Spread, Preserve"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is a chemical contaminant?:::mercury', 'which is a chemical contaminant?', 'Mercury', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mercury is a specific toxic heavy metal element. In food safety, it acts as a classic chemical contaminant (most notably in its organic form, methylmercury, which bioaccumulates in predatory seafood like shark, swordfish, and large tuna). Consuming it poses severe neurological health risks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Mercury\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mercury is a specific toxic heavy metal element. In food safety, it acts as a classic chemical contaminant (most notably in its organic form, methylmercury, which bioaccumulates in predatory seafood like shark, swordfish, and large tuna). Consuming it poses severe neurological health risks.\n\n• Metals: A broad category that can represent a physical risk (metal shards from equipment) or a chemical risk (heavy metal pollution) depending on the form, making it less specific than Mercury.\n• Glass: A physical contaminant. It is an inanimate, tangible object or structural fragment that accidentally enters food and poses an immediate danger of cuts, choking, or internal injury.\n• Iodine 131: A radiological (radioactive) contaminant. While it has a chemical basis, food safety boards separate radioactive isotopes (like Cesium-137 and Iodine-131) into their own distinct class of contamination hazards.","whyWrongChoices":"Alternative options: Glass, Iodine 131, Metals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is a chemical contaminant?:::', 'which is a chemical contaminant?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mercury is a specific toxic heavy metal element. In food safety, it acts as a classic chemical contaminant (most notably in its organic form, methylmercury, which bioaccumulates in predatory seafood like shark, swordfish, and large tuna). Consuming it poses severe neurological health risks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Mercury\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mercury is a specific toxic heavy metal element. In food safety, it acts as a classic chemical contaminant (most notably in its organic form, methylmercury, which bioaccumulates in predatory seafood like shark, swordfish, and large tuna). Consuming it poses severe neurological health risks.\n\n• Metals: A broad category that can represent a physical risk (metal shards from equipment) or a chemical risk (heavy metal pollution) depending on the form, making it less specific than Mercury.\n• Glass: A physical contaminant. It is an inanimate, tangible object or structural fragment that accidentally enters food and poses an immediate danger of cuts, choking, or internal injury.\n• Iodine 131: A radiological (radioactive) contaminant. While it has a chemical basis, food safety boards separate radioactive isotopes (like Cesium-137 and Iodine-131) into their own distinct class of contamination hazards.","whyWrongChoices":"Alternative options: Glass, Iodine 131, Metals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this makes use of gases that liquesfy at very low temperature of about -60c wherein rate of freezing is ultra fast.:::cryogenic freezing', 'this makes use of gases that liquesfy at very low temperature of about -60c wherein rate of freezing is ultra fast.', 'Cryogenic freezing', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cryogenic freezing utilizes cryogenic liquids or liquefied gases—most commonly liquid nitrogen (which operates at -196°C) or liquid carbon dioxide (which operates at -78°C)—sprayed or immersed directly onto food items.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cryogenic freezing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cryogenic freezing utilizes cryogenic liquids or liquefied gases—most commonly liquid nitrogen (which operates at -196°C) or liquid carbon dioxide (which operates at -78°C)—sprayed or immersed directly onto food items.\n\nBecause these substances exist at ultra-low, freezing temperatures, the thermal heat transfer is immediate and direct. This yields an ultra-fast rate of freezing that prevents large ice crystals from forming, maximizing food texture, structure, and quality retention.\n\n• Air freezing and Air blast freezing: These conventional methods rely on cold air circulation (with blast freezing blowing air mechanically at high velocities, usually around -30°C to -40°C). While quick, blast freezing uses circulating ambient air currents rather than direct exposure to liquefied gases to freeze materials.","whyWrongChoices":"Alternative options: Air blast freezing, Air freezing, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this makes use of gases that liquesfy at very low temperature of about -60c wherein rate of freezing is ultra fast.:::', 'this makes use of gases that liquesfy at very low temperature of about -60c wherein rate of freezing is ultra fast.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cryogenic freezing utilizes cryogenic liquids or liquefied gases—most commonly liquid nitrogen (which operates at -196°C) or liquid carbon dioxide (which operates at -78°C)—sprayed or immersed directly onto food items.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cryogenic freezing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cryogenic freezing utilizes cryogenic liquids or liquefied gases—most commonly liquid nitrogen (which operates at -196°C) or liquid carbon dioxide (which operates at -78°C)—sprayed or immersed directly onto food items.\n\nBecause these substances exist at ultra-low, freezing temperatures, the thermal heat transfer is immediate and direct. This yields an ultra-fast rate of freezing that prevents large ice crystals from forming, maximizing food texture, structure, and quality retention.\n\n• Air freezing and Air blast freezing: These conventional methods rely on cold air circulation (with blast freezing blowing air mechanically at high velocities, usually around -30°C to -40°C). While quick, blast freezing uses circulating ambient air currents rather than direct exposure to liquefied gases to freeze materials.","whyWrongChoices":"Alternative options: Air blast freezing, Air freezing, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:process of allowing meat to stand at low temperature for a few weeks is::::aging', 'process of allowing meat to stand at low temperature for a few weeks is:', 'aging', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Meat aging (or maturation) is the process of holding whole carcasses or primal cuts of meat at controlled, low refrigeration temperatures (typically 1°C to 4°C or 34°F to 40°F) for anywhere from a few weeks up to a month.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"aging\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Meat aging (or maturation) is the process of holding whole carcasses or primal cuts of meat at controlled, low refrigeration temperatures (typically 1°C to 4°C or 34°F to 40°F) for anywhere from a few weeks up to a month.\n\nDuring this period, the meat''s natural proteolytic enzymes slowly break down the tough muscle fibers and connective tissues. This significantly improves the tenderness, juiciness, and depth of flavor.\n\n• Curing: A preservation method that involves treating meat with salts, nitrites, and sugar to extend shelf life and fix its color.\n• Preservation: A broad, general category of techniques (including freezing, canning, and drying) used to prevent spoilage, rather than a specific process aimed at weekly temperature holding for flavor/texture.\n• Tenderization: While tenderization is the primary goal and structural outcome of aging, \"tenderization\" itself is an umbrella term that includes mechanical pounding, needle piercing, or using chemical/fruit enzymes (like papain). Aging is the precise name of the slow, cold-storage methodology described.","whyWrongChoices":"Alternative options: curing, preservation, tenderization"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:process of allowing meat to stand at low temperature for a few weeks is::::', 'process of allowing meat to stand at low temperature for a few weeks is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Meat aging (or maturation) is the process of holding whole carcasses or primal cuts of meat at controlled, low refrigeration temperatures (typically 1°C to 4°C or 34°F to 40°F) for anywhere from a few weeks up to a month.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"aging\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Meat aging (or maturation) is the process of holding whole carcasses or primal cuts of meat at controlled, low refrigeration temperatures (typically 1°C to 4°C or 34°F to 40°F) for anywhere from a few weeks up to a month.\n\nDuring this period, the meat''s natural proteolytic enzymes slowly break down the tough muscle fibers and connective tissues. This significantly improves the tenderness, juiciness, and depth of flavor.\n\n• Curing: A preservation method that involves treating meat with salts, nitrites, and sugar to extend shelf life and fix its color.\n• Preservation: A broad, general category of techniques (including freezing, canning, and drying) used to prevent spoilage, rather than a specific process aimed at weekly temperature holding for flavor/texture.\n• Tenderization: While tenderization is the primary goal and structural outcome of aging, \"tenderization\" itself is an umbrella term that includes mechanical pounding, needle piercing, or using chemical/fruit enzymes (like papain). Aging is the precise name of the slow, cold-storage methodology described.","whyWrongChoices":"Alternative options: curing, preservation, tenderization"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pasteurization is applied in processing foods that are generally:::acidic', 'pasteurization is applied in processing foods that are generally', 'acidic', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pasteurization is a mild heat treatment (usually below 100°C) applied to foods to destroy pathogenic bacteria, yeasts, and molds.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"acidic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pasteurization is a mild heat treatment (usually below 100°C) applied to foods to destroy pathogenic bacteria, yeasts, and molds.\n\nIn food technology, pasteurization is highly effective for acidic foods (such as fruit juices, vinegar, pickles, wine, and beer) because their low pH naturally prevents dangerous, heat-resistant spore-forming bacteria (like Clostridium botulinum) from growing. Therefore, mild pasteurization is all that is needed to clear away standard spoilage microbes and extend shelf life. Low-acid or basic foods usually require much harsher thermal processing (like full sterilization or autoclaving in canning) to be shelf-stable.","whyWrongChoices":"Alternative options: salty, basic, spicy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pasteurization is applied in processing foods that are generally:::', 'pasteurization is applied in processing foods that are generally', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pasteurization is a mild heat treatment (usually below 100°C) applied to foods to destroy pathogenic bacteria, yeasts, and molds.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"acidic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pasteurization is a mild heat treatment (usually below 100°C) applied to foods to destroy pathogenic bacteria, yeasts, and molds.\n\nIn food technology, pasteurization is highly effective for acidic foods (such as fruit juices, vinegar, pickles, wine, and beer) because their low pH naturally prevents dangerous, heat-resistant spore-forming bacteria (like Clostridium botulinum) from growing. Therefore, mild pasteurization is all that is needed to clear away standard spoilage microbes and extend shelf life. Low-acid or basic foods usually require much harsher thermal processing (like full sterilization or autoclaving in canning) to be shelf-stable.","whyWrongChoices":"Alternative options: salty, basic, spicy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are examples of conditions that promote microbial growth, except::::low ph', 'all are examples of conditions that promote microbial growth, except:', 'low pH', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low pH means high acidity (such as lemon juice or vinegar). Most pathogenic bacteria grow best in a nearly neutral environment with a pH between 6.6 and 7.5. When the pH drops below 4.6, the acidic environment disrupts microbial cell membranes and alters internal proteins, inhibiting or completely stopping microbial growth rather than promoting it. This chemical barrier is why acidulation and pickling are highly effective methods for preserving food.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"low pH\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low pH means high acidity (such as lemon juice or vinegar). Most pathogenic bacteria grow best in a nearly neutral environment with a pH between 6.6 and 7.5. When the pH drops below 4.6, the acidic environment disrupts microbial cell membranes and alters internal proteins, inhibiting or completely stopping microbial growth rather than promoting it. This chemical barrier is why acidulation and pickling are highly effective methods for preserving food.\n\n• Room temperature: Room temperature sits squarely in the culinary \"Danger Zone\" (41°F to 135°F), providing an ideal environment for mesophilic bacteria to thrive and multiply rapidly.\n• Presence of oxygen: Most common foodborne pathogens are aerobic or facultative anaerobes, requiring or benefiting from the presence of oxygen to metabolize energy and grow.\n• Availability of food/nutrients: Microorganisms need structural elements like proteins, sugars, nitrogen, and vitamins to sustain themselves, meaning nutrient-rich foods are highly susceptible to quick spoilage.","whyWrongChoices":"Alternative options: room temperature, presence of oxygen, availability of food/nutrients"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the amount of alcohol produced when making wines and beer depends primarily on:::amount of fermentable carbohydrates', 'the amount of alcohol produced when making wines and beer depends primarily on', 'amount of fermentable carbohydrates', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During fermentation, yeast (a microorganism) consumes fermentable carbohydrates (simple sugars like glucose, fructose, and maltose) and converts them into ethanol (alcohol) and carbon dioxide (CO₂).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"amount of fermentable carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During fermentation, yeast (a microorganism) consumes fermentable carbohydrates (simple sugars like glucose, fructose, and maltose) and converts them into ethanol (alcohol) and carbon dioxide (CO₂).\n\nThe sugars serve as the fuel source for the yeast. The maximum potential alcohol content (the alcohol by volume or ABV) is directly dictated by how much sugar is available in the original fruit juice (must) or grain liquid (wort) for the yeast to eat. Once all the fermentable carbohydrates are consumed, alcohol production stops.","whyWrongChoices":"Alternative options: kind of microorganisms present, amount of oxygen present, amount of salt"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the amount of alcohol produced when making wines and beer depends primarily on:::', 'the amount of alcohol produced when making wines and beer depends primarily on', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During fermentation, yeast (a microorganism) consumes fermentable carbohydrates (simple sugars like glucose, fructose, and maltose) and converts them into ethanol (alcohol) and carbon dioxide (CO₂).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"amount of fermentable carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During fermentation, yeast (a microorganism) consumes fermentable carbohydrates (simple sugars like glucose, fructose, and maltose) and converts them into ethanol (alcohol) and carbon dioxide (CO₂).\n\nThe sugars serve as the fuel source for the yeast. The maximum potential alcohol content (the alcohol by volume or ABV) is directly dictated by how much sugar is available in the original fruit juice (must) or grain liquid (wort) for the yeast to eat. Once all the fermentable carbohydrates are consumed, alcohol production stops.","whyWrongChoices":"Alternative options: kind of microorganisms present, amount of oxygen present, amount of salt"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:discoloration in canned products may be caused by::::all of the above', 'discoloration in canned products may be caused by:', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Discoloration in canned foods is a multi-faceted problem that can stem from biological, thermal, or chemical sources:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Discoloration in canned foods is a multi-faceted problem that can stem from biological, thermal, or chemical sources:\n\n• Bacterial action: Certain anaerobic bacteria (like Desulfotomaculum nigrificans) produce hydrogen sulfide (H₂S) gas during spoilage. This gas dissolves into the food liquid and reacts chemically to form dark black precipitates (such as iron sulfide), severely blackening or discoloring the food and the inner lining of the tin.\n• High temperature: Overheating during the thermal canning process or storing cans in a hot environment breaks down natural pigments (like chlorophyll or anthocyanins). Prolonged heat exposure can turn vibrant fruits or vegetables unappealingly brown, gray, or faded.\n• Various metals: Chemical reactions occur if the food comes into direct contact with non-resistant metals during processing or inside a damaged tin container. For instance, trace amounts of iron or copper reacting with sulfur compounds in seafood or vegetables create dark metal sulfides, causing severe dark spotting or inky discoloration.","whyWrongChoices":"Alternative options: Bacterial action, Various metals, High temperature"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the estimated risk of hiv transimission from mother to child during breastfeeding is?:::5-20%', 'the estimated risk of hiv transimission from mother to child during breastfeeding is?', '5-20%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5-20%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.\n\nThe Overall Risk Breakdown (Without Intervention):\n\n• Gestation and Labor/Delivery: 15% to 30% risk.\n• Breastfeeding: Additional 5% to 20% risk (which heavily depends on the duration of breastfeeding, as prolonged mixed feeding over 2 years can double the acquisition risk closer to 20%).\n• Total Combined Risk: 15% to 45%.","whyWrongChoices":"Alternative options: 5-10%, 10-15%, 15-25%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:discoloration in canned products may be caused by::::', 'discoloration in canned products may be caused by:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Discoloration in canned foods is a multi-faceted problem that can stem from biological, thermal, or chemical sources:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Discoloration in canned foods is a multi-faceted problem that can stem from biological, thermal, or chemical sources:\n\n• Bacterial action: Certain anaerobic bacteria (like Desulfotomaculum nigrificans) produce hydrogen sulfide (H₂S) gas during spoilage. This gas dissolves into the food liquid and reacts chemically to form dark black precipitates (such as iron sulfide), severely blackening or discoloring the food and the inner lining of the tin.\n• High temperature: Overheating during the thermal canning process or storing cans in a hot environment breaks down natural pigments (like chlorophyll or anthocyanins). Prolonged heat exposure can turn vibrant fruits or vegetables unappealingly brown, gray, or faded.\n• Various metals: Chemical reactions occur if the food comes into direct contact with non-resistant metals during processing or inside a damaged tin container. For instance, trace amounts of iron or copper reacting with sulfur compounds in seafood or vegetables create dark metal sulfides, causing severe dark spotting or inky discoloration.","whyWrongChoices":"Alternative options: Bacterial action, Various metals, High temperature"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which artificial sweetener is a methyl ester of a dipeptide composed of aspartic acid and phenylalanine?:::', 'which artificial sweetener is a methyl ester of a dipeptide composed of aspartic acid and phenylalanine?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aspartame is 160 to 220 times sweeter than sucrose that is noncariogenic and has limited glycemic response.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspartame\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aspartame is 160 to 220 times sweeter than sucrose that is noncariogenic and has limited glycemic response.","whyWrongChoices":"Alternative options: Sucralose, Saccharin, Acesulfame potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are examples of conditions that promote microbial growth, except::::', 'all are examples of conditions that promote microbial growth, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low pH means high acidity (such as lemon juice or vinegar). Most pathogenic bacteria grow best in a nearly neutral environment with a pH between 6.6 and 7.5. When the pH drops below 4.6, the acidic environment disrupts microbial cell membranes and alters internal proteins, inhibiting or completely stopping microbial growth rather than promoting it. This chemical barrier is why acidulation and pickling are highly effective methods for preserving food.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"low pH\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low pH means high acidity (such as lemon juice or vinegar). Most pathogenic bacteria grow best in a nearly neutral environment with a pH between 6.6 and 7.5. When the pH drops below 4.6, the acidic environment disrupts microbial cell membranes and alters internal proteins, inhibiting or completely stopping microbial growth rather than promoting it. This chemical barrier is why acidulation and pickling are highly effective methods for preserving food.\n\n• Room temperature: Room temperature sits squarely in the culinary \"Danger Zone\" (41°F to 135°F), providing an ideal environment for mesophilic bacteria to thrive and multiply rapidly.\n• Presence of oxygen: Most common foodborne pathogens are aerobic or facultative anaerobes, requiring or benefiting from the presence of oxygen to metabolize energy and grow.\n• Availability of food/nutrients: Microorganisms need structural elements like proteins, sugars, nitrogen, and vitamins to sustain themselves, meaning nutrient-rich foods are highly susceptible to quick spoilage.","whyWrongChoices":"Alternative options: room temperature, presence of oxygen, availability of food/nutrients"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:characterized by development of acidity in food without swelling cause by growth of thermophilic microorganisms as a result of lack of processing or cooking.:::flat sours', 'characterized by development of acidity in food without swelling cause by growth of thermophilic microorganisms as a result of lack of processing or cooking.', 'Flat sours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Flat sour spoilage is characterized by the development of lactic acid in canned food caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flat sours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Flat sour spoilage is characterized by the development of lactic acid in canned food caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus).\n\nWhen it occurs as a result of a lack of processing or undercooking, the thermal heat treatment fails to reach a high enough temperature to destroy these highly heat-resistant thermophilic spores.\n\nBecause these bacteria ferment the food carbohydrates into acid without generating gas, the internal pressure of the can remains unchanged. The ends of the tin can stay completely flat (non-swollen), hiding the spoilage until the consumer opens it and notices a sour taste and odor.\n\n• Stack: Refers to \"stack burning,\" which occurs when hot cans are piled or stacked together too closely after processing without proper cooling. The residual heat cooks the food inside the can, causing it to soften or discolor, but it is not a direct microbiological designation like flat sours.\n• Non-swell: A descriptive state of a can rather than a specific microbiological spoilage term. While flat sours are non-swelled, \"non-swell\" isn''t the technical name of the reaction.\n• Flipper: A normal-looking can where one end will flip out or bulge outward only when the side of the can is pressed or when the can is slammed against a hard surface.","whyWrongChoices":"Alternative options: Stack, Non-swell, Flipper"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:characterized by development of acidity in food without swelling cause by growth of thermophilic microorganisms as a result of lack of processing or cooking.:::', 'characterized by development of acidity in food without swelling cause by growth of thermophilic microorganisms as a result of lack of processing or cooking.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Flat sour spoilage is characterized by the development of lactic acid in canned food caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flat sours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Flat sour spoilage is characterized by the development of lactic acid in canned food caused by heat-loving, spore-forming bacteria (such as Bacillus stearothermophilus).\n\nWhen it occurs as a result of a lack of processing or undercooking, the thermal heat treatment fails to reach a high enough temperature to destroy these highly heat-resistant thermophilic spores.\n\nBecause these bacteria ferment the food carbohydrates into acid without generating gas, the internal pressure of the can remains unchanged. The ends of the tin can stay completely flat (non-swollen), hiding the spoilage until the consumer opens it and notices a sour taste and odor.\n\n• Stack: Refers to \"stack burning,\" which occurs when hot cans are piled or stacked together too closely after processing without proper cooling. The residual heat cooks the food inside the can, causing it to soften or discolor, but it is not a direct microbiological designation like flat sours.\n• Non-swell: A descriptive state of a can rather than a specific microbiological spoilage term. While flat sours are non-swelled, \"non-swell\" isn''t the technical name of the reaction.\n• Flipper: A normal-looking can where one end will flip out or bulge outward only when the side of the can is pressed or when the can is slammed against a hard surface.","whyWrongChoices":"Alternative options: Stack, Non-swell, Flipper"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:temperature at which most of the pathogenic microbial activities are slowed down during refrigerator.:::10c', 'temperature at which most of the pathogenic microbial activities are slowed down during refrigerator.', '10C', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pathogenic (disease-causing) bacteria are generally mesophiles, meaning they grow best at warm body or room temperatures. As the temperature drops toward 10C (50°F) and below, their metabolic processes and enzymatic activities slow down significantly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pathogenic (disease-causing) bacteria are generally mesophiles, meaning they grow best at warm body or room temperatures. As the temperature drops toward 10C (50°F) and below, their metabolic processes and enzymatic activities slow down significantly.\n\nOptions B (15C), C (25C), and D (45C) all fall squarely inside the Temperature Danger Zone, where bacteria multiply rapidly. Out of all the options provided, 10C is the only temperature cold enough to actively chill food and retard harmful microbial activity. (Note: For true food safety holding standards, refrigerators should be kept even colder—at 4C / 40°F or lower—to halt growth completely).\n\n• 15C: A cool room temperature where pathogens can still replicate easily.\n• 25C: Standard comfortable room temperature, which serves as a highly ideal environment for rapid microbial growth.\n• 45C: A warm thermal environment where certain heat-tolerant foodborne pathogens (like Clostridium perfringens) can multiply at their absolute fastest rates.","whyWrongChoices":"Alternative options: 15C, 45C, 25C"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the size of one cover is preferably::::', 'the size of one cover is preferably:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"One cover is preferably about 24 inches of table space to provide adequate room for place settings and service.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"24 inches\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"One cover is preferably about 24 inches of table space to provide adequate room for place settings and service.","whyWrongChoices":"Alternative options: 18 inches, 21 inches, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:temperature at which most of the pathogenic microbial activities are slowed down during refrigerator.:::', 'temperature at which most of the pathogenic microbial activities are slowed down during refrigerator.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pathogenic (disease-causing) bacteria are generally mesophiles, meaning they grow best at warm body or room temperatures. As the temperature drops toward 10C (50°F) and below, their metabolic processes and enzymatic activities slow down significantly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pathogenic (disease-causing) bacteria are generally mesophiles, meaning they grow best at warm body or room temperatures. As the temperature drops toward 10C (50°F) and below, their metabolic processes and enzymatic activities slow down significantly.\n\nOptions B (15C), C (25C), and D (45C) all fall squarely inside the Temperature Danger Zone, where bacteria multiply rapidly. Out of all the options provided, 10C is the only temperature cold enough to actively chill food and retard harmful microbial activity. (Note: For true food safety holding standards, refrigerators should be kept even colder—at 4C / 40°F or lower—to halt growth completely).\n\n• 15C: A cool room temperature where pathogens can still replicate easily.\n• 25C: Standard comfortable room temperature, which serves as a highly ideal environment for rapid microbial growth.\n• 45C: A warm thermal environment where certain heat-tolerant foodborne pathogens (like Clostridium perfringens) can multiply at their absolute fastest rates.","whyWrongChoices":"Alternative options: 15C, 45C, 25C"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:genus with species capable of oxiding ethanol to acetic acid.:::acetobacter', 'genus with species capable of oxiding ethanol to acetic acid.', 'Acetobacter', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Species within the genus Acetobacter (such as Acetobacter aceti) are collectively known as acetic acid bacteria. They are obligate aerobes capable of converting ethanol (alcohol) into acetic acid (vinegar) in the presence of oxygen. This biochemical reaction is the core process used globally to manufacture commercial vinegar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Acetobacter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Species within the genus Acetobacter (such as Acetobacter aceti) are collectively known as acetic acid bacteria. They are obligate aerobes capable of converting ethanol (alcohol) into acetic acid (vinegar) in the presence of oxygen. This biochemical reaction is the core process used globally to manufacture commercial vinegar.\n\n• Escherichia: Best known for Escherichia coli (E. coli), which are coliform bacteria found in the intestines of warm-blooded organisms; they ferment sugars into mixed acids and gases, but do not oxidize ethanol to acetic acid.\n• Saccharomyces: A genus of fungi that includes Saccharomyces cerevisiae (brewer''s or baker''s yeast). They perform alcoholic fermentation, converting sugars into ethanol and carbon dioxide (the exact opposite step of Acetobacter).\n• Lactococcus: A genus of lactic acid bacteria (like Lactococcus lactis) used extensively in dairy fermentation to convert lactose into lactic acid, not ethanol into acetic acid.","whyWrongChoices":"Alternative options: Escherichia, Lactococcus, Saccharomyces"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is the most common site used for obtaining skinfold thickness measurement.:::', 'which is the most common site used for obtaining skinfold thickness measurement.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The triceps skinfold (TSF) is universally recognized as the most commonly used single-site skinfold measurement in clinical, nursing, and field research settings.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tricep skinfold (TSF)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The triceps skinfold (TSF) is universally recognized as the most commonly used single-site skinfold measurement in clinical, nursing, and field research settings.\n\nIt is highly favored because it is the most easily accessible anatomical site, requires minimal subject repositioning, and possesses a vast wealth of reference data—such as the World Health Organization (WHO) growth standards—for rapid comparison.\n\nWhile clinical models like the Durnin and Womersley system sum the triceps, biceps, subscapular, and suprailiac sites to track total body composition, the triceps remains the baseline index location used on its own to reliably evaluate upper-body fat reserves.","whyWrongChoices":"Alternative options: Biceps skinfold (BSF), Suprailic skinfold, Subcapsular skinfold"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:genus with species capable of oxiding ethanol to acetic acid.:::', 'genus with species capable of oxiding ethanol to acetic acid.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Species within the genus Acetobacter (such as Acetobacter aceti) are collectively known as acetic acid bacteria. They are obligate aerobes capable of converting ethanol (alcohol) into acetic acid (vinegar) in the presence of oxygen. This biochemical reaction is the core process used globally to manufacture commercial vinegar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Acetobacter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Species within the genus Acetobacter (such as Acetobacter aceti) are collectively known as acetic acid bacteria. They are obligate aerobes capable of converting ethanol (alcohol) into acetic acid (vinegar) in the presence of oxygen. This biochemical reaction is the core process used globally to manufacture commercial vinegar.\n\n• Escherichia: Best known for Escherichia coli (E. coli), which are coliform bacteria found in the intestines of warm-blooded organisms; they ferment sugars into mixed acids and gases, but do not oxidize ethanol to acetic acid.\n• Saccharomyces: A genus of fungi that includes Saccharomyces cerevisiae (brewer''s or baker''s yeast). They perform alcoholic fermentation, converting sugars into ethanol and carbon dioxide (the exact opposite step of Acetobacter).\n• Lactococcus: A genus of lactic acid bacteria (like Lactococcus lactis) used extensively in dairy fermentation to convert lactose into lactic acid, not ethanol into acetic acid.","whyWrongChoices":"Alternative options: Escherichia, Lactococcus, Saccharomyces"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is the easiest and most popular method for obtaining information about dietary intake?:::24-hour recall', 'which of the following is the easiest and most popular method for obtaining information about dietary intake?', '24-hour recall', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical and community nutrition settings, the 24-hour dietary recall is recognized as the easiest and most popular method for collecting dietary intake data.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"24-hour recall\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical and community nutrition settings, the 24-hour dietary recall is recognized as the easiest and most popular method for collecting dietary intake data.\n\n• Why it is the easiest: It carries a very low burden for the participant. It does not require literacy, advanced preparation, or active logging over several days like a food diary does.\n• Why it is the most popular: It can be administered quickly by an interviewer (often taking only 15 to 20 minutes) using a backward-in-time structured recall approach. It provides a rapid snapshot of an individual''s immediate dietary pattern without altering their typical eating behavior.","whyWrongChoices":"Alternative options: Food frequency questionnaire, 3-day food diary, Direct observation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is the easiest and most popular method for obtaining information about dietary intake?:::', 'which of the following is the easiest and most popular method for obtaining information about dietary intake?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical and community nutrition settings, the 24-hour dietary recall is recognized as the easiest and most popular method for collecting dietary intake data.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"24-hour recall\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical and community nutrition settings, the 24-hour dietary recall is recognized as the easiest and most popular method for collecting dietary intake data.\n\n• Why it is the easiest: It carries a very low burden for the participant. It does not require literacy, advanced preparation, or active logging over several days like a food diary does.\n• Why it is the most popular: It can be administered quickly by an interviewer (often taking only 15 to 20 minutes) using a backward-in-time structured recall approach. It provides a rapid snapshot of an individual''s immediate dietary pattern without altering their typical eating behavior.","whyWrongChoices":"Alternative options: Food frequency questionnaire, 3-day food diary, Direct observation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is the most common site used for obtaining skinfold thickness measurement.:::tricep skinfold (tsf)', 'which is the most common site used for obtaining skinfold thickness measurement.', 'Tricep skinfold (TSF)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The triceps skinfold (TSF) is universally recognized as the most commonly used single-site skinfold measurement in clinical, nursing, and field research settings.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tricep skinfold (TSF)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The triceps skinfold (TSF) is universally recognized as the most commonly used single-site skinfold measurement in clinical, nursing, and field research settings.\n\nIt is highly favored because it is the most easily accessible anatomical site, requires minimal subject repositioning, and possesses a vast wealth of reference data—such as the World Health Organization (WHO) growth standards—for rapid comparison.\n\nWhile clinical models like the Durnin and Womersley system sum the triceps, biceps, subscapular, and suprailiac sites to track total body composition, the triceps remains the baseline index location used on its own to reliably evaluate upper-body fat reserves.","whyWrongChoices":"Alternative options: Biceps skinfold (BSF), Suprailic skinfold, Subcapsular skinfold"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
