INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:amount of protein equivalent to a gram of nitrogen.:::6.25g', 'amount of protein equivalent to a gram of nitrogen.', '6.25g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On average, protein contains approximately 16% nitrogen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.25g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On average, protein contains approximately 16% nitrogen.\n\nTherefore: 1 g nitrogen × 6.25 = 6.25 g protein\nThe factor 6.25 is derived from: 100 ÷ 16 = 6.25\n\nThis conversion is commonly used when calculating nitrogen balance, particularly in clinical nutrition and protein assessment.","whyWrongChoices":"Alternative options: 0.16g, 54g, 10g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what does the mid-upper arm muscle (mamc) estimate?:::a and b', 'what does the mid-upper arm muscle (mamc) estimate?', 'A and B', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:\nMAMC = MUAC - (π * TSF)\n\nIt serves as a critical indicator in nutritional assessments because:\n• Skeletal Muscle Reserves: Because the arm consists primarily of bone, muscle, and a surrounding layer of subcutaneous fat, subtracting the fat thickness (via the triceps skinfold) isolates the muscle component. This directly gauges the body''s skeletal muscle reserves.\n• Lean Body Mass: In clinical malnutrition states (such as marasmus or chronic disease cachexia), the body breaks down its skeletal muscle tissue to use for energy. Therefore, measuring MAMC provides a reliable proxy estimate of a patient''s overall lean body mass.\n\nWhy \"Fat reserve\" is incorrect:\nThe Triceps Skinfold (TSF) thickness alone is what isolates and estimates subcutaneous fat reserves. MAMC specifically subtracts the fat to look only at muscle tissue.","whyWrongChoices":"Alternative options: The amount of lean body mass, Skeletal muscle reserves, Fat reserve"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:limiting amino acid in rice::::', 'limiting amino acid in rice:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lysine, the main limiting essential amino acid in cereals, restricts the absorption and utilization of other amino acids and proteins, which leads to nutrient deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lysine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lysine, the main limiting essential amino acid in cereals, restricts the absorption and utilization of other amino acids and proteins, which leads to nutrient deficiency.","whyWrongChoices":"Alternative options: Tryptophan, Methionine, Tyrosine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what does the mid-upper arm muscle (mamc) estimate?:::', 'what does the mid-upper arm muscle (mamc) estimate?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:\nMAMC = MUAC - (π * TSF)\n\nIt serves as a critical indicator in nutritional assessments because:\n• Skeletal Muscle Reserves: Because the arm consists primarily of bone, muscle, and a surrounding layer of subcutaneous fat, subtracting the fat thickness (via the triceps skinfold) isolates the muscle component. This directly gauges the body''s skeletal muscle reserves.\n• Lean Body Mass: In clinical malnutrition states (such as marasmus or chronic disease cachexia), the body breaks down its skeletal muscle tissue to use for energy. Therefore, measuring MAMC provides a reliable proxy estimate of a patient''s overall lean body mass.\n\nWhy \"Fat reserve\" is incorrect:\nThe Triceps Skinfold (TSF) thickness alone is what isolates and estimates subcutaneous fat reserves. MAMC specifically subtracts the fat to look only at muscle tissue.","whyWrongChoices":"Alternative options: The amount of lean body mass, Skeletal muscle reserves, Fat reserve"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food records are usually collected for what period of time?:::1-7 days', 'food records are usually collected for what period of time?', '1-7 days', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1-7 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","whyWrongChoices":"Alternative options: 1 day, 3-4 days, 2 weeks"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food records are usually collected for what period of time?:::', 'food records are usually collected for what period of time?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1-7 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","whyWrongChoices":"Alternative options: 1 day, 3-4 days, 2 weeks"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what do waist-to-hip circumference ratios measure?:::intra-abdominal fat and subcutaneous fat', 'what do waist-to-hip circumference ratios measure?', 'Intra-abdominal fat and subcutaneous fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Intra-abdominal fat and subcutaneous fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).\n\nBecause it gauges your midsection width, the ratio serves as an accessible proxy marker for tracking accumulated intra-abdominal fat (visceral fat that envelopes your internal organs) alongside abdominal subcutaneous fat (fat stored directly beneath the skin). An elevated ratio indicates central obesity, which heavily correlates with metabolic and cardiovascular diseases.","whyWrongChoices":"Alternative options: Fat-free mass, Protein-energy malnutrition, Skeletal mass"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what do waist-to-hip circumference ratios measure?:::', 'what do waist-to-hip circumference ratios measure?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Intra-abdominal fat and subcutaneous fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).\n\nBecause it gauges your midsection width, the ratio serves as an accessible proxy marker for tracking accumulated intra-abdominal fat (visceral fat that envelopes your internal organs) alongside abdominal subcutaneous fat (fat stored directly beneath the skin). An elevated ratio indicates central obesity, which heavily correlates with metabolic and cardiovascular diseases.","whyWrongChoices":"Alternative options: Fat-free mass, Protein-energy malnutrition, Skeletal mass"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?:::zinc', 'deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?', 'Zinc', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zinc\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.\n• Increased risk of infection: Zinc deficiency impairs cell-mediated immunity and mucosal barriers, making children highly susceptible to severe infections like diarrhea and pneumonia.\n• Growth failure & Delayed sexual maturity: Zinc plays an indispensable structural role in growth hormone function and gonadotropin secretion. Severe deficiency directly arrests linear skeletal growth (causing stunting or growth failure) and leads to hypogonadism or delayed sexual development in adolescents.\n\n• Calcium: Primary deficiencies lead to rickets in children and osteomalacia in adults, characterized by poor bone mineralization rather than delayed sexual maturity.\n• Iodine: Deficiency causes goiter and hypothyroidism, and severe prenatal deficiency leads to cretinism (profound intellectual disability and physical stunting), but it is not typically grouped under this specific childhood triad.\n• Riboflavin (Vitamin B2): Deficiency manifests as ariboflavinosis, which presents with cheilosis (cracked lips), angular stomatitis (cracks at the corners of the mouth), and glossitis (magenta tongue).","whyWrongChoices":"Alternative options: Iodine, Riboflavin, Calcium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?:::', 'deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zinc\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.\n• Increased risk of infection: Zinc deficiency impairs cell-mediated immunity and mucosal barriers, making children highly susceptible to severe infections like diarrhea and pneumonia.\n• Growth failure & Delayed sexual maturity: Zinc plays an indispensable structural role in growth hormone function and gonadotropin secretion. Severe deficiency directly arrests linear skeletal growth (causing stunting or growth failure) and leads to hypogonadism or delayed sexual development in adolescents.\n\n• Calcium: Primary deficiencies lead to rickets in children and osteomalacia in adults, characterized by poor bone mineralization rather than delayed sexual maturity.\n• Iodine: Deficiency causes goiter and hypothyroidism, and severe prenatal deficiency leads to cretinism (profound intellectual disability and physical stunting), but it is not typically grouped under this specific childhood triad.\n• Riboflavin (Vitamin B2): Deficiency manifests as ariboflavinosis, which presents with cheilosis (cracked lips), angular stomatitis (cracks at the corners of the mouth), and glossitis (magenta tongue).","whyWrongChoices":"Alternative options: Iodine, Riboflavin, Calcium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:amount of protein equivalent to a gram of nitrogen.:::', 'amount of protein equivalent to a gram of nitrogen.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On average, protein contains approximately 16% nitrogen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.25g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On average, protein contains approximately 16% nitrogen.\n\nTherefore: 1 g nitrogen × 6.25 = 6.25 g protein\nThe factor 6.25 is derived from: 100 ÷ 16 = 6.25\n\nThis conversion is commonly used when calculating nitrogen balance, particularly in clinical nutrition and protein assessment.","whyWrongChoices":"Alternative options: 0.16g, 54g, 10g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the estimated risk of hiv transimission from mother to child during breastfeeding is?:::', 'the estimated risk of hiv transimission from mother to child during breastfeeding is?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5-20%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.\n\nThe Overall Risk Breakdown (Without Intervention):\n\n• Gestation and Labor/Delivery: 15% to 30% risk.\n• Breastfeeding: Additional 5% to 20% risk (which heavily depends on the duration of breastfeeding, as prolonged mixed feeding over 2 years can double the acquisition risk closer to 20%).\n• Total Combined Risk: 15% to 45%.","whyWrongChoices":"Alternative options: 5-10%, 10-15%, 15-25%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following characterizes that the cause precedes the effect or outcome in a study?:::temporal relationship', 'which of the following characterizes that the cause precedes the effect or outcome in a study?', 'Temporal relationship', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Temporal relationship\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.\n\n• Precision: Refers to the reproducibility and exactness of a specific measurement under unchanged conditions.\n• Internal validity: The degree to which a study successfully rules out alternative explanations (confounders) for the results. While temporal precedence is a crucial requirement to establish internal validity for a causal claim, the specific concept of \"time ordering\" itself is defined as temporality.\n• External validity: The extent to which the final results of a study can be generalized or applied to other settings, populations, or times.","whyWrongChoices":"Alternative options: Internal validity, External validity, Precision"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not plagiarism?:::re-drawing the rct process, it not original or specific', 'which of the following is not plagiarism?', 'Re-drawing the RCT process, it not original or specific', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Re-drawing the RCT process, it not original or specific\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.","whyWrongChoices":"Alternative options: Transcribing or modifying text from any printed material (encylopedias, books, magazines, newspapers), Using another student''s work and claiming it as your own, Using photographs, video or audio without permission"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not plagiarism?:::', 'which of the following is not plagiarism?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Re-drawing the RCT process, it not original or specific\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.","whyWrongChoices":"Alternative options: Transcribing or modifying text from any printed material (encylopedias, books, magazines, newspapers), Using another student''s work and claiming it as your own, Using photographs, video or audio without permission"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of study will you use if you want to conduct dose-response assays effect on individual cells?:::in-vitro testing (human)', 'what type of study will you use if you want to conduct dose-response assays effect on individual cells?', 'In-vitro testing (human)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the right answer, you need to break down the two parts of the question:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"In-vitro testing (human)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the right answer, you need to break down the two parts of the question:\n\n1. \"Individual Cells\": Testing a substance on isolated cells or tissue cultures outside of a whole living organism is the definition of an in-vitro study (which literally translates from Latin as \"in glass,\" referring to test tubes or petri dishes). Testing an entire living body would be an in-vivo study.\n2. \"Human\" vs. \"Animal\": When a research scientist conducts basic laboratory dose-response assays on cell lines to eventually apply those findings to public health, nutrition, or medicine, using isolated human cells (such as human liver, muscle, or intestinal cell lines) is highly preferred. Human cell models provide more accurate information about human metabolic pathways and receptor behaviors than animal models can.\n\nQuick Reference Map\n• In-vitro: Performed outside a living organism using isolated cells, tissues, or organs in a controlled lab setup (e.g., test tubes, plates).\n• In-vivo: Performed inside a whole, intact, living organism (such as feeding trials in living humans or lab animals).","whyWrongChoices":"Alternative options: In-vivo studies (animals), In-vivo studies (human), In-vitro testing (animal)"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of study will you use if you want to conduct dose-response assays effect on individual cells?:::', 'what type of study will you use if you want to conduct dose-response assays effect on individual cells?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the right answer, you need to break down the two parts of the question:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"In-vitro testing (human)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the right answer, you need to break down the two parts of the question:\n\n1. \"Individual Cells\": Testing a substance on isolated cells or tissue cultures outside of a whole living organism is the definition of an in-vitro study (which literally translates from Latin as \"in glass,\" referring to test tubes or petri dishes). Testing an entire living body would be an in-vivo study.\n2. \"Human\" vs. \"Animal\": When a research scientist conducts basic laboratory dose-response assays on cell lines to eventually apply those findings to public health, nutrition, or medicine, using isolated human cells (such as human liver, muscle, or intestinal cell lines) is highly preferred. Human cell models provide more accurate information about human metabolic pathways and receptor behaviors than animal models can.\n\nQuick Reference Map\n• In-vitro: Performed outside a living organism using isolated cells, tissues, or organs in a controlled lab setup (e.g., test tubes, plates).\n• In-vivo: Performed inside a whole, intact, living organism (such as feeding trials in living humans or lab animals).","whyWrongChoices":"Alternative options: In-vivo studies (animals), In-vivo studies (human), In-vitro testing (animal)"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the mandatory food fortification program, refined sugar is fortified with::::', 'under the mandatory food fortification program, refined sugar is fortified with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A – oil, sugar\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Iron, Iodine, Vit A and Iron"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following characterizes that the cause precedes the effect or outcome in a study?:::', 'which of the following characterizes that the cause precedes the effect or outcome in a study?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Temporal relationship\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.\n\n• Precision: Refers to the reproducibility and exactness of a specific measurement under unchanged conditions.\n• Internal validity: The degree to which a study successfully rules out alternative explanations (confounders) for the results. While temporal precedence is a crucial requirement to establish internal validity for a causal claim, the specific concept of \"time ordering\" itself is defined as temporality.\n• External validity: The extent to which the final results of a study can be generalized or applied to other settings, populations, or times.","whyWrongChoices":"Alternative options: Internal validity, External validity, Precision"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an experiment in which groups of individuals rather than independent individuals are randomly allocated to intervention groups.:::cluster randomized trial', 'an experiment in which groups of individuals rather than independent individuals are randomly allocated to intervention groups.', 'Cluster randomized trial', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In epidemiology and research design, a cluster randomized trial (also known as a group-randomized trial) is specifically characterized by assigning intact groups of individuals—such as entire villages, schools, households, or clinics—to the intervention or control groups rather than randomizing each person independently.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cluster randomized trial\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In epidemiology and research design, a cluster randomized trial (also known as a group-randomized trial) is specifically characterized by assigning intact groups of individuals—such as entire villages, schools, households, or clinics—to the intervention or control groups rather than randomizing each person independently.\n\n• Randomized controlled trial (RCT): In its standard form, an RCT randomizes individual participants independently into different treatment arms.\n• Cohort study: This is an observational study design where researchers track a group of individuals forward in time based on their exposure status; it does not involve random allocation.\n• Case-control study: This is an observational retrospective study design where individuals are selected based on whether they have a specific outcome (\"cases\") or not (\"controls\") to investigate past exposures.","whyWrongChoices":"Alternative options: Cohort study, Case-control study, Randomized controlled trial"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an experiment in which groups of individuals rather than independent individuals are randomly allocated to intervention groups.:::', 'an experiment in which groups of individuals rather than independent individuals are randomly allocated to intervention groups.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In epidemiology and research design, a cluster randomized trial (also known as a group-randomized trial) is specifically characterized by assigning intact groups of individuals—such as entire villages, schools, households, or clinics—to the intervention or control groups rather than randomizing each person independently.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cluster randomized trial\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In epidemiology and research design, a cluster randomized trial (also known as a group-randomized trial) is specifically characterized by assigning intact groups of individuals—such as entire villages, schools, households, or clinics—to the intervention or control groups rather than randomizing each person independently.\n\n• Randomized controlled trial (RCT): In its standard form, an RCT randomizes individual participants independently into different treatment arms.\n• Cohort study: This is an observational study design where researchers track a group of individuals forward in time based on their exposure status; it does not involve random allocation.\n• Case-control study: This is an observational retrospective study design where individuals are selected based on whether they have a specific outcome (\"cases\") or not (\"controls\") to investigate past exposures.","whyWrongChoices":"Alternative options: Cohort study, Case-control study, Randomized controlled trial"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the process of this type of research is to describe, analyze and interpret the conditions that now exist.:::descriptive research', 'the process of this type of research is to describe, analyze and interpret the conditions that now exist.', 'Descriptive research', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Descriptive research is explicitly designed to describe, analyze, and interpret a phenomenon, situation, or population as it currently exists. It focuses heavily on answering the what, where, when, and how questions without manipulating any of the research variables.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Descriptive research\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Descriptive research is explicitly designed to describe, analyze, and interpret a phenomenon, situation, or population as it currently exists. It focuses heavily on answering the what, where, when, and how questions without manipulating any of the research variables.\n\n• Applied research focuses on finding practical solutions to an immediate problem using accepted theories.\n• Experimental research relies on manipulating an independent variable to establish strict cause-and-effect relationships under controlled conditions.\n• Historical research deals with uncovering, interpreting, and analyzing events that occurred in the past rather than conditions that now exist.","whyWrongChoices":"Alternative options: Historical research, Experimental research, Applied research"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which drug may bind with phosphorus and reduce its absorption?:::antacid', 'which drug may bind with phosphorus and reduce its absorption?', 'antacid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Some antacids, particularly those containing aluminum or calcium, can bind phosphate in the gastrointestinal tract and form poorly absorbed complexes, thereby reducing phosphorus absorption. This property is also therapeutically used with aluminum- or calcium-based phosphate binders in patients with chronic kidney disease and hyperphosphatemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"antacid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Some antacids, particularly those containing aluminum or calcium, can bind phosphate in the gastrointestinal tract and form poorly absorbed complexes, thereby reducing phosphorus absorption. This property is also therapeutically used with aluminum- or calcium-based phosphate binders in patients with chronic kidney disease and hyperphosphatemia.","whyWrongChoices":"Alternative options: laxative, digitails, amphetamines"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the process of this type of research is to describe, analyze and interpret the conditions that now exist.:::', 'the process of this type of research is to describe, analyze and interpret the conditions that now exist.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Descriptive research is explicitly designed to describe, analyze, and interpret a phenomenon, situation, or population as it currently exists. It focuses heavily on answering the what, where, when, and how questions without manipulating any of the research variables.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Descriptive research\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Descriptive research is explicitly designed to describe, analyze, and interpret a phenomenon, situation, or population as it currently exists. It focuses heavily on answering the what, where, when, and how questions without manipulating any of the research variables.\n\n• Applied research focuses on finding practical solutions to an immediate problem using accepted theories.\n• Experimental research relies on manipulating an independent variable to establish strict cause-and-effect relationships under controlled conditions.\n• Historical research deals with uncovering, interpreting, and analyzing events that occurred in the past rather than conditions that now exist.","whyWrongChoices":"Alternative options: Historical research, Experimental research, Applied research"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the study design which describes the experience of a single case or a group of patients with similar diagnosis based on sporadic discoveries of a unique, unusual or unexpected clinical observation. it provides first clues in recognition of disease and identifies risk factors or effects of exposure.:::case report', 'the study design which describes the experience of a single case or a group of patients with similar diagnosis based on sporadic discoveries of a unique, unusual or unexpected clinical observation. it provides first clues in recognition of disease and identifies risk factors or effects of exposure.', 'Case report', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. \"Describes the experience of a single case...\": While a Case Series compiles multiple similar profiles together into a structured dataset, a Case Report is fundamentally defined as the baseline document describing the experience of a single case. In professional taxonomies, the parent definition of this type of design is titled under \"Case Report\" because it is the actual first line of evidence generated by an unexpected observation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Case report\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. \"Describes the experience of a single case...\": While a Case Series compiles multiple similar profiles together into a structured dataset, a Case Report is fundamentally defined as the baseline document describing the experience of a single case. In professional taxonomies, the parent definition of this type of design is titled under \"Case Report\" because it is the actual first line of evidence generated by an unexpected observation.\n\n2. \"Sporadic discoveries\": A case series implies a systematic grouping or a consecutive collection of patients over time who meet specific criteria (e.g., tracking the next 5 patients who enter a clinic with a specific symptom). An unexpected, random, or sporadic clinical observation of a unique phenomenon is, by definition, published immediately as a singular Case Report to alert the medical community.\n\nSummary\n• Case Report: The baseline research design triggered by a sporadic, unusual, or unexpected clinical finding in an individual. It provides the very first clues that a new disease or exposure reaction exists.\n• Case Series: The design used after multiple case reports accumulate, allowing researchers to aggregate a larger group of patients with that same diagnosis to look for statistical trends.","whyWrongChoices":"Alternative options: Case series, Case study, Ecological study"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the study design which describes the experience of a single case or a group of patients with similar diagnosis based on sporadic discoveries of a unique, unusual or unexpected clinical observation. it provides first clues in recognition of disease and identifies risk factors or effects of exposure.:::', 'the study design which describes the experience of a single case or a group of patients with similar diagnosis based on sporadic discoveries of a unique, unusual or unexpected clinical observation. it provides first clues in recognition of disease and identifies risk factors or effects of exposure.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. \"Describes the experience of a single case...\": While a Case Series compiles multiple similar profiles together into a structured dataset, a Case Report is fundamentally defined as the baseline document describing the experience of a single case. In professional taxonomies, the parent definition of this type of design is titled under \"Case Report\" because it is the actual first line of evidence generated by an unexpected observation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Case report\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. \"Describes the experience of a single case...\": While a Case Series compiles multiple similar profiles together into a structured dataset, a Case Report is fundamentally defined as the baseline document describing the experience of a single case. In professional taxonomies, the parent definition of this type of design is titled under \"Case Report\" because it is the actual first line of evidence generated by an unexpected observation.\n\n2. \"Sporadic discoveries\": A case series implies a systematic grouping or a consecutive collection of patients over time who meet specific criteria (e.g., tracking the next 5 patients who enter a clinic with a specific symptom). An unexpected, random, or sporadic clinical observation of a unique phenomenon is, by definition, published immediately as a singular Case Report to alert the medical community.\n\nSummary\n• Case Report: The baseline research design triggered by a sporadic, unusual, or unexpected clinical finding in an individual. It provides the very first clues that a new disease or exposure reaction exists.\n• Case Series: The design used after multiple case reports accumulate, allowing researchers to aggregate a larger group of patients with that same diagnosis to look for statistical trends.","whyWrongChoices":"Alternative options: Case series, Case study, Ecological study"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of hypothesis is this? ho: the mean score of school children in the nutrition education in the control group is ≤75%. ha: the mean score of school children in the nutrition education in the control group is >75%.:::directional one-tailed hypothesis', 'what type of hypothesis is this? ho: the mean score of school children in the nutrition education in the control group is ≤75%. ha: the mean score of school children in the nutrition education in the control group is >75%.', 'Directional one-tailed hypothesis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To determine the type of hypothesis, you must always look closely at the mathematical sign used in the Alternative Hypothesis (Ha):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Directional one-tailed hypothesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To determine the type of hypothesis, you must always look closely at the mathematical sign used in the Alternative Hypothesis (Ha):\n1. Directional: The alternative hypothesis explicitly states that the mean score is greater than (>) 75%. Because it specifies a particular direction of change (higher/improvement) rather than just any general difference, it is directional.\n2. One-tailed: Because it only looks for an effect in one direction, the rejection region (critical region) is located entirely in a single extreme side—the right tail—of the sampling distribution curve.\n\nQuick Reference Map\n• Directional One-Tailed: Uses strictly > or < in Ha (e.g., higher, lower, increased, decreased).\n• Non-Directional Two-Tailed: Uses strictly != or not equal to in Ha (e.g., different from, changed, not equal to).","whyWrongChoices":"Alternative options: Non-directional two-tailed hypothesis, Directional two-tailed hypothesis, Non-directional one-tailed hypothesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of hypothesis is this? ho: the mean score of school children in the nutrition education in the control group is ≤75%. ha: the mean score of school children in the nutrition education in the control group is >75%.:::', 'what type of hypothesis is this? ho: the mean score of school children in the nutrition education in the control group is ≤75%. ha: the mean score of school children in the nutrition education in the control group is >75%.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To determine the type of hypothesis, you must always look closely at the mathematical sign used in the Alternative Hypothesis (Ha):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Directional one-tailed hypothesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To determine the type of hypothesis, you must always look closely at the mathematical sign used in the Alternative Hypothesis (Ha):\n1. Directional: The alternative hypothesis explicitly states that the mean score is greater than (>) 75%. Because it specifies a particular direction of change (higher/improvement) rather than just any general difference, it is directional.\n2. One-tailed: Because it only looks for an effect in one direction, the rejection region (critical region) is located entirely in a single extreme side—the right tail—of the sampling distribution curve.\n\nQuick Reference Map\n• Directional One-Tailed: Uses strictly > or < in Ha (e.g., higher, lower, increased, decreased).\n• Non-Directional Two-Tailed: Uses strictly != or not equal to in Ha (e.g., different from, changed, not equal to).","whyWrongChoices":"Alternative options: Non-directional two-tailed hypothesis, Directional two-tailed hypothesis, Non-directional one-tailed hypothesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the choice of research strategy, it answers "does the data exist in a tangible or an intangible form?" and specifically understand how social factors interact.:::ontology-constructionism', 'in the choice of research strategy, it answers "does the data exist in a tangible or an intangible form?" and specifically understand how social factors interact.', 'Ontology-Constructionism', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This question tests the foundational concepts of research philosophy (specifically within public health nutrition and community research modules):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ontology-Constructionism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This question tests the foundational concepts of research philosophy (specifically within public health nutrition and community research modules):\n\n1. Ontology: This branch of philosophy addresses the nature of reality and asks, \"Does the data exist in a tangible or an intangible form?\" It looks at whether social entities exist independently of our perceptions or if they are built up from our perceptions.\n2. Constructionism (Subjectivism): This ontological stance holds that social phenomena and their meanings are continually being accomplished and revised by social actors. It specifically focuses on understanding how social factors interact to create meaning, as opposed to Objectivism, which views social reality as an external, concrete objective fact.\n\nIn contrast, Epistemology deals with how we acquire knowledge (e.g., through Positivism or Interpretivism), rather than whether reality itself is fundamentally tangible or intangible.","whyWrongChoices":"Alternative options: Epistemology-Positivism, Epistemology-Interpretivism, Ontology-Objectivism"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the choice of research strategy, it answers "does the data exist in a tangible or an intangible form?" and specifically understand how social factors interact.:::', 'in the choice of research strategy, it answers "does the data exist in a tangible or an intangible form?" and specifically understand how social factors interact.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This question tests the foundational concepts of research philosophy (specifically within public health nutrition and community research modules):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ontology-Constructionism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This question tests the foundational concepts of research philosophy (specifically within public health nutrition and community research modules):\n\n1. Ontology: This branch of philosophy addresses the nature of reality and asks, \"Does the data exist in a tangible or an intangible form?\" It looks at whether social entities exist independently of our perceptions or if they are built up from our perceptions.\n2. Constructionism (Subjectivism): This ontological stance holds that social phenomena and their meanings are continually being accomplished and revised by social actors. It specifically focuses on understanding how social factors interact to create meaning, as opposed to Objectivism, which views social reality as an external, concrete objective fact.\n\nIn contrast, Epistemology deals with how we acquire knowledge (e.g., through Positivism or Interpretivism), rather than whether reality itself is fundamentally tangible or intangible.","whyWrongChoices":"Alternative options: Epistemology-Positivism, Epistemology-Interpretivism, Ontology-Objectivism"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a form of severe undernutrition that occurs after breastfeeding stops, and the child is weaned with a starchy diet.:::kwashiorkor', 'a form of severe undernutrition that occurs after breastfeeding stops, and the child is weaned with a starchy diet.', 'Kwashiorkor', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Kwashiorkor is a severe form of protein-energy malnutrition (PEM) that typically occurs during early childhood. The name stems from a Ga language word meaning \"the sickness the old baby gets when the new baby comes.\"","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Kwashiorkor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Kwashiorkor is a severe form of protein-energy malnutrition (PEM) that typically occurs during early childhood. The name stems from a Ga language word meaning \"the sickness the old baby gets when the new baby comes.\"\n\nIt classically manifests when a child is abruptly weaned from protein-rich breast milk (often because a younger sibling is born) and transitioned onto an inadequate, starchy, protein-deficient diet (such as rice, maize, cassava, or porridge). While the child may receive enough calories from carbohydrates, the lack of protein causes fluid to leak into the tissues, leading to the condition''s signature edema (swollen belly and feet).","whyWrongChoices":"Alternative options: Marasmus, Wasting, Stunting"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a wet nurse is::::a woman who breastfeeds another woman''s baby', 'a wet nurse is:', 'A woman who breastfeeds another woman''s baby', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A wet nurse is a woman employed or volunteered to breastfeed and care for another woman''s child, usually because the biological mother is unable, unavailable, or chooses not to breastfeed. This practice has been historically widespread and remains a traditional strategy in human infant feeding alternative networks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A woman who breastfeeds another woman''s baby\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A wet nurse is a woman employed or volunteered to breastfeed and care for another woman''s child, usually because the biological mother is unable, unavailable, or chooses not to breastfeed. This practice has been historically widespread and remains a traditional strategy in human infant feeding alternative networks.","whyWrongChoices":"Alternative options: Registered nurse, Registered midwife, A baby sitter"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a form of severe undernutrition that occurs after breastfeeding stops, and the child is weaned with a starchy diet.:::', 'a form of severe undernutrition that occurs after breastfeeding stops, and the child is weaned with a starchy diet.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Kwashiorkor is a severe form of protein-energy malnutrition (PEM) that typically occurs during early childhood. The name stems from a Ga language word meaning \"the sickness the old baby gets when the new baby comes.\"","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Kwashiorkor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Kwashiorkor is a severe form of protein-energy malnutrition (PEM) that typically occurs during early childhood. The name stems from a Ga language word meaning \"the sickness the old baby gets when the new baby comes.\"\n\nIt classically manifests when a child is abruptly weaned from protein-rich breast milk (often because a younger sibling is born) and transitioned onto an inadequate, starchy, protein-deficient diet (such as rice, maize, cassava, or porridge). While the child may receive enough calories from carbohydrates, the lack of protein causes fluid to leak into the tissues, leading to the condition''s signature edema (swollen belly and feet).","whyWrongChoices":"Alternative options: Marasmus, Wasting, Stunting"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the law that mandate the establishment of the functional nutrition committee in every region, province, city, municipality, and baranagy in the country.:::loi 441', 'the law that mandate the establishment of the functional nutrition committee in every region, province, city, municipality, and baranagy in the country.', 'LOI 441', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Letter of Instructions No. 441 (LOI 441), issued on July 31, 1976, directed the Department of Local Governments and Community Development (now the DILG) to establish functioning nutrition committees in every region, province, city, municipality, and barangay across the Philippines to properly execute the national nutrition plan at all subnational levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"LOI 441\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Letter of Instructions No. 441 (LOI 441), issued on July 31, 1976, directed the Department of Local Governments and Community Development (now the DILG) to establish functioning nutrition committees in every region, province, city, municipality, and barangay across the Philippines to properly execute the national nutrition plan at all subnational levels.\n\n• PD 491 (Presidential Decree No. 491): Created the National Nutrition Council (NNC) in 1974 as the highest policy-making and coordinating body on nutrition in the country.\n• AO No. 88 (Administrative Order No. 88): Deals with administrative government structural reorganizations unrelated to the foundational mandate of local nutrition committees.\n• EO 285 (Executive Order No. 285): Reorganized the National Nutrition Council under the Department of Social Welfare and Development (and later amended by other EOs) rather than establishing the local committee mandates.","whyWrongChoices":"Alternative options: EO 285, PD 491, AO No. 88"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the law that mandate the establishment of the functional nutrition committee in every region, province, city, municipality, and baranagy in the country.:::', 'the law that mandate the establishment of the functional nutrition committee in every region, province, city, municipality, and baranagy in the country.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Letter of Instructions No. 441 (LOI 441), issued on July 31, 1976, directed the Department of Local Governments and Community Development (now the DILG) to establish functioning nutrition committees in every region, province, city, municipality, and barangay across the Philippines to properly execute the national nutrition plan at all subnational levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"LOI 441\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Letter of Instructions No. 441 (LOI 441), issued on July 31, 1976, directed the Department of Local Governments and Community Development (now the DILG) to establish functioning nutrition committees in every region, province, city, municipality, and barangay across the Philippines to properly execute the national nutrition plan at all subnational levels.\n\n• PD 491 (Presidential Decree No. 491): Created the National Nutrition Council (NNC) in 1974 as the highest policy-making and coordinating body on nutrition in the country.\n• AO No. 88 (Administrative Order No. 88): Deals with administrative government structural reorganizations unrelated to the foundational mandate of local nutrition committees.\n• EO 285 (Executive Order No. 285): Reorganized the National Nutrition Council under the Department of Social Welfare and Development (and later amended by other EOs) rather than establishing the local committee mandates.","whyWrongChoices":"Alternative options: EO 285, PD 491, AO No. 88"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the stomach capacity of an infant at birth?:::10-12 ml', 'what is the stomach capacity of an infant at birth?', '10-12 ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Anatomically, the newborn stomach is positioned horizontally with a high-riding, poorly developed fundus and a relaxed lower esophageal sphincter, resulting in a low baseline volume capacity of 10-12 mL (about 0.5 to 1 ounce). Colostrum volume produced during initial postpartum lactation matches this capacity perfectly, as concentrated nutrients meet metabolic demands without exceeding gastric distension limits or triggering excessive stretch receptor-mediated regurgitation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10-12 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Anatomically, the newborn stomach is positioned horizontally with a high-riding, poorly developed fundus and a relaxed lower esophageal sphincter, resulting in a low baseline volume capacity of 10-12 mL (about 0.5 to 1 ounce). Colostrum volume produced during initial postpartum lactation matches this capacity perfectly, as concentrated nutrients meet metabolic demands without exceeding gastric distension limits or triggering excessive stretch receptor-mediated regurgitation.","whyWrongChoices":"Alternative options: 5-10 ml, 20-25 ml, 25-30 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the stomach capacity of an infant at birth?:::', 'what is the stomach capacity of an infant at birth?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Anatomically, the newborn stomach is positioned horizontally with a high-riding, poorly developed fundus and a relaxed lower esophageal sphincter, resulting in a low baseline volume capacity of 10-12 mL (about 0.5 to 1 ounce). Colostrum volume produced during initial postpartum lactation matches this capacity perfectly, as concentrated nutrients meet metabolic demands without exceeding gastric distension limits or triggering excessive stretch receptor-mediated regurgitation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10-12 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Anatomically, the newborn stomach is positioned horizontally with a high-riding, poorly developed fundus and a relaxed lower esophageal sphincter, resulting in a low baseline volume capacity of 10-12 mL (about 0.5 to 1 ounce). Colostrum volume produced during initial postpartum lactation matches this capacity perfectly, as concentrated nutrients meet metabolic demands without exceeding gastric distension limits or triggering excessive stretch receptor-mediated regurgitation.","whyWrongChoices":"Alternative options: 5-10 ml, 20-25 ml, 25-30 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a wet nurse is::::', 'a wet nurse is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A wet nurse is a woman employed or volunteered to breastfeed and care for another woman''s child, usually because the biological mother is unable, unavailable, or chooses not to breastfeed. This practice has been historically widespread and remains a traditional strategy in human infant feeding alternative networks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A woman who breastfeeds another woman''s baby\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A wet nurse is a woman employed or volunteered to breastfeed and care for another woman''s child, usually because the biological mother is unable, unavailable, or chooses not to breastfeed. This practice has been historically widespread and remains a traditional strategy in human infant feeding alternative networks.","whyWrongChoices":"Alternative options: Registered nurse, Registered midwife, A baby sitter"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the process of feeding a child who is not breastfed with a diet that provides all the nutrients the child needs until the child is fully fed on family food.:::replacement feeding', 'it is the process of feeding a child who is not breastfed with a diet that provides all the nutrients the child needs until the child is fully fed on family food.', 'Replacement feeding', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the exact, verbatim definition used by the World Health Organization (WHO) and global Infant and Young Child Feeding (IYCF) guidelines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Replacement feeding\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the exact, verbatim definition used by the World Health Organization (WHO) and global Infant and Young Child Feeding (IYCF) guidelines.\n\nReplacement feeding is defined as the process of feeding a child who is not receiving any breast milk with a diet that provides all the nutrients the child needs until they can be fully transitioned onto regular family food. In public health settings (especially within maternal health and PMTCT/HIV programs), replacement feeding typically involves exclusive commercial infant formula for the first 6 months, followed by nutrient-dense solid foods paired with a suitable breast milk substitute from 6 months onward.","whyWrongChoices":"Alternative options: Complementary feeding, Cup feeding, Formula feeding"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the process of feeding a child who is not breastfed with a diet that provides all the nutrients the child needs until the child is fully fed on family food.:::', 'it is the process of feeding a child who is not breastfed with a diet that provides all the nutrients the child needs until the child is fully fed on family food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the exact, verbatim definition used by the World Health Organization (WHO) and global Infant and Young Child Feeding (IYCF) guidelines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Replacement feeding\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the exact, verbatim definition used by the World Health Organization (WHO) and global Infant and Young Child Feeding (IYCF) guidelines.\n\nReplacement feeding is defined as the process of feeding a child who is not receiving any breast milk with a diet that provides all the nutrients the child needs until they can be fully transitioned onto regular family food. In public health settings (especially within maternal health and PMTCT/HIV programs), replacement feeding typically involves exclusive commercial infant formula for the first 6 months, followed by nutrient-dense solid foods paired with a suitable breast milk substitute from 6 months onward.","whyWrongChoices":"Alternative options: Complementary feeding, Cup feeding, Formula feeding"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a hormone that stimulates milk ejection and promotes uterine contraction.:::oxytocin', 'a hormone that stimulates milk ejection and promotes uterine contraction.', 'Oxytocin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Oxytocin is a hormone produced in the hypothalamus and released by the posterior pituitary gland that plays two vital roles in maternal physiology:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oxytocin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Oxytocin is a hormone produced in the hypothalamus and released by the posterior pituitary gland that plays two vital roles in maternal physiology:\n\n1. Milk Ejection (The Let-Down Reflex): It causes the myoepithelial cells surrounding the alveoli of the mammary glands to contract, squeezing milk into the ducts so the baby can suckle.\n2. Uterine Contraction: It stimulates the smooth muscles of the uterus to contract during labor (to deliver the baby) and postpartum (to minimize bleeding and help the uterus return to its pre-pregnancy size).\n\n• Prolactin: This hormone is responsible for the actual production and synthesis of breast milk within the alveoli, but it does not eject it.\n• Estrogen: This hormone stimulates the development of the mammary duct system during pregnancy but actually blocks the full effect of prolactin until after delivery.\n• Growth hormone: This is involved in general tissue growth and metabolic functions, not specific lactational or reproductive reflexes.","whyWrongChoices":"Alternative options: Prolactin, Estrogen, Growth hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the act of giving birth::::', 'it refers to the act of giving birth:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Parturition is the specific clinical term for the act or process of giving birth to offspring.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Parturition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Parturition is the specific clinical term for the act or process of giving birth to offspring.\n\n• Puerperium: This is the postpartum period immediately following childbirth, lasting about 6 weeks, during which the mother''s reproductive organs return to their original non-pregnant condition.\n• Parity: This refers to the number of pregnancies in which the fetus or fetuses have reached a viable gestational age (usually 20 to 24 weeks), regardless of whether the child is born alive or stillborn.\n• Gestation: This is the period of development inside the womb from conception until birth (pregnancy).","whyWrongChoices":"Alternative options: Puerperium, Gestation, Parity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a hormone that stimulates milk ejection and promotes uterine contraction.:::', 'a hormone that stimulates milk ejection and promotes uterine contraction.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Oxytocin is a hormone produced in the hypothalamus and released by the posterior pituitary gland that plays two vital roles in maternal physiology:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oxytocin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Oxytocin is a hormone produced in the hypothalamus and released by the posterior pituitary gland that plays two vital roles in maternal physiology:\n\n1. Milk Ejection (The Let-Down Reflex): It causes the myoepithelial cells surrounding the alveoli of the mammary glands to contract, squeezing milk into the ducts so the baby can suckle.\n2. Uterine Contraction: It stimulates the smooth muscles of the uterus to contract during labor (to deliver the baby) and postpartum (to minimize bleeding and help the uterus return to its pre-pregnancy size).\n\n• Prolactin: This hormone is responsible for the actual production and synthesis of breast milk within the alveoli, but it does not eject it.\n• Estrogen: This hormone stimulates the development of the mammary duct system during pregnancy but actually blocks the full effect of prolactin until after delivery.\n• Growth hormone: This is involved in general tissue growth and metabolic functions, not specific lactational or reproductive reflexes.","whyWrongChoices":"Alternative options: Prolactin, Estrogen, Growth hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the average daily milk consumption of infants for the first 6 months.:::750 ml', 'the average daily milk consumption of infants for the first 6 months.', '750 ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Clinical research and lactation guidelines indicate that exclusively breastfed or formula-fed infants consume an average of 25 ounces of milk per day between the ages of 1 and 6 months.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Clinical research and lactation guidelines indicate that exclusively breastfed or formula-fed infants consume an average of 25 ounces of milk per day between the ages of 1 and 6 months.\n\n• When converted directly using standard measurements, 25 ounces equals 750 mL (25 x 30 mL/oz).\n• Some pediatric and nutritional textbooks round this daily estimate to approximately 720 mL (calculated via alternative factors, such as roughly 24 oz x 30 mL).\n\nBecause normal daily intake typically ranges from 570 mL to 900 mL (with an overall average baseline of 739–750 mL), either C or B represents the clinically accepted daily average volume before the introduction of solid foods.","whyWrongChoices":"Alternative options: 200 ml, 250 ml, 720 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a major component of gastric juice::::hci', 'a major component of gastric juice:', 'HCI', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hydrochloric acid secretion is responsible for the strong acidic condition of the stomach. With such an acidic environment, ingested proteins are denaturized thus, facilitating their digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"HCI\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hydrochloric acid secretion is responsible for the strong acidic condition of the stomach. With such an acidic environment, ingested proteins are denaturized thus, facilitating their digestion.","whyWrongChoices":"Alternative options: Amylase, Hormones"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the average daily milk consumption of infants for the first 6 months.:::', 'the average daily milk consumption of infants for the first 6 months.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Clinical research and lactation guidelines indicate that exclusively breastfed or formula-fed infants consume an average of 25 ounces of milk per day between the ages of 1 and 6 months.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Clinical research and lactation guidelines indicate that exclusively breastfed or formula-fed infants consume an average of 25 ounces of milk per day between the ages of 1 and 6 months.\n\n• When converted directly using standard measurements, 25 ounces equals 750 mL (25 x 30 mL/oz).\n• Some pediatric and nutritional textbooks round this daily estimate to approximately 720 mL (calculated via alternative factors, such as roughly 24 oz x 30 mL).\n\nBecause normal daily intake typically ranges from 570 mL to 900 mL (with an overall average baseline of 739–750 mL), either C or B represents the clinically accepted daily average volume before the introduction of solid foods.","whyWrongChoices":"Alternative options: 200 ml, 250 ml, 720 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the act of giving birth::::parturition', 'it refers to the act of giving birth:', 'Parturition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Parturition is the specific clinical term for the act or process of giving birth to offspring.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Parturition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Parturition is the specific clinical term for the act or process of giving birth to offspring.\n\n• Puerperium: This is the postpartum period immediately following childbirth, lasting about 6 weeks, during which the mother''s reproductive organs return to their original non-pregnant condition.\n• Parity: This refers to the number of pregnancies in which the fetus or fetuses have reached a viable gestational age (usually 20 to 24 weeks), regardless of whether the child is born alive or stillborn.\n• Gestation: This is the period of development inside the womb from conception until birth (pregnancy).","whyWrongChoices":"Alternative options: Puerperium, Gestation, Parity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in zumba session because they are fond of dancing.:::self-determination theory', 'in promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in zumba session because they are fond of dancing.', 'Self-determination Theory', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already \"fond of dancing\" and \"eager to participate,\" they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-determination Theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already \"fond of dancing\" and \"eager to participate,\" they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.\n\n• Precaution Adoption Process Model (PAPM): This is a stage theory best used for tracking how people move from being completely unaware of a health hazard to taking a precautionary action. It does not focus on enjoyable physical activities.\n• Health Belief Model (HBM): This model relies on a person’s perception of a health threat (susceptibility/severity) and balancing the benefits against the barriers of a preventative action. It is most useful for things like screening or vaccination compliance, not lifestyle activities done out of pure enjoyment.\n• Theory of Planned Behavior (TPB): This theory posits that behavior is driven by intentions, which are shaped by attitudes, social pressures (subjective norms), and perceived behavioral control. It would be the choice if the question emphasized that the community members are joining because their friends or family think it is a good idea.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Theory of Planned Behavior"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:approximately how many kilocalories does a mature milk contain?:::60-75 kcal/100 ml', 'approximately how many kilocalories does a mature milk contain?', '60-75 kcal/100 ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On average, mature human breast milk contains about 65 to 70 kcal per 100 mL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"60-75 kcal/100 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On average, mature human breast milk contains about 65 to 70 kcal per 100 mL.\n\nStandard pediatric and nutritional reference textbooks define the typical baseline range of energy yield for mature human milk as 60–75 kcal/100 mL (which perfectly corresponds to about 18–22 kcal per ounce).\n\nThis caloric density is primarily driven by its fat content (making up roughly 50% of the total energy) and carbohydrates/lactose (making up about 40%).","whyWrongChoices":"Alternative options: 80-90 kcal/100 ml, 45-60 kcal/100 ml, 90-105 kcal/100 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:approximately how many kilocalories does a mature milk contain?:::', 'approximately how many kilocalories does a mature milk contain?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On average, mature human breast milk contains about 65 to 70 kcal per 100 mL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"60-75 kcal/100 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On average, mature human breast milk contains about 65 to 70 kcal per 100 mL.\n\nStandard pediatric and nutritional reference textbooks define the typical baseline range of energy yield for mature human milk as 60–75 kcal/100 mL (which perfectly corresponds to about 18–22 kcal per ounce).\n\nThis caloric density is primarily driven by its fat content (making up roughly 50% of the total energy) and carbohydrates/lactose (making up about 40%).","whyWrongChoices":"Alternative options: 80-90 kcal/100 ml, 45-60 kcal/100 ml, 90-105 kcal/100 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
