INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:which of the following enhances the absorption of zinc?:::glutamate', 'which of the following enhances the absorption of zinc?', 'Glutamate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glutamate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.","whyWrongChoices":"Alternative options: Tryptophan, Acetyl CoA, Thiamin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the major maternal fuel source during pregnancy?:::fat', 'what is the major maternal fuel source during pregnancy?', 'Fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.\n\n• The Sparing Mechanism: Driven by placental hormones like Human Placental Lactogen (hPL), the mother develops a localized insulin resistance. This resistance decreases the mother''s own peripheral utilization of glucose.\n• The Primary Fuel: To compensate and sustain her own metabolic needs, the mother accelerates lipolysis (the breakdown of fat stores). This allows her tissues to rely heavily on fat (free fatty acids and ketones) as her primary personal fuel source, effectively \"sparing\" the sugar for fetal growth.","whyWrongChoices":"Alternative options: Sugar, Protein, Glycogen"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the major maternal fuel source during pregnancy?:::', 'what is the major maternal fuel source during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.\n\n• The Sparing Mechanism: Driven by placental hormones like Human Placental Lactogen (hPL), the mother develops a localized insulin resistance. This resistance decreases the mother''s own peripheral utilization of glucose.\n• The Primary Fuel: To compensate and sustain her own metabolic needs, the mother accelerates lipolysis (the breakdown of fat stores). This allows her tissues to rely heavily on fat (free fatty acids and ketones) as her primary personal fuel source, effectively \"sparing\" the sugar for fetal growth.","whyWrongChoices":"Alternative options: Sugar, Protein, Glycogen"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in zumba session because they are fond of dancing.:::', 'in promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in zumba session because they are fond of dancing.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already \"fond of dancing\" and \"eager to participate,\" they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-determination Theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already \"fond of dancing\" and \"eager to participate,\" they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.\n\n• Precaution Adoption Process Model (PAPM): This is a stage theory best used for tracking how people move from being completely unaware of a health hazard to taking a precautionary action. It does not focus on enjoyable physical activities.\n• Health Belief Model (HBM): This model relies on a person’s perception of a health threat (susceptibility/severity) and balancing the benefits against the barriers of a preventative action. It is most useful for things like screening or vaccination compliance, not lifestyle activities done out of pure enjoyment.\n• Theory of Planned Behavior (TPB): This theory posits that behavior is driven by intentions, which are shaped by attitudes, social pressures (subjective norms), and perceived behavioral control. It would be the choice if the question emphasized that the community members are joining because their friends or family think it is a good idea.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Theory of Planned Behavior"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:percent increase of total blood volume during pregnancy?:::33', 'percent increase of total blood volume during pregnancy?', '33', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"33\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).\n\n1. Plasma Volume Increase: During pregnancy, blood plasma (the liquid portion) expands by approximately 45% to 50%.\n2. Red Blood Cell Mass Increase: Red blood cells only expand by about 20% to 30% (if the mother has adequate iron stores).\n3. The Total Net Blood Volume Increase: Because total blood volume is a weighted combination of these two components (Plasma + RBCs), the net average expansion across the entire duration of a typical healthy pregnancy equates to roughly one-third of the pre-pregnancy baseline, which mathematically maps directly to 33%.","whyWrongChoices":"Alternative options: 50, 18, 25"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:percent increase of total blood volume during pregnancy?:::', 'percent increase of total blood volume during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"33\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).\n\n1. Plasma Volume Increase: During pregnancy, blood plasma (the liquid portion) expands by approximately 45% to 50%.\n2. Red Blood Cell Mass Increase: Red blood cells only expand by about 20% to 30% (if the mother has adequate iron stores).\n3. The Total Net Blood Volume Increase: Because total blood volume is a weighted combination of these two components (Plasma + RBCs), the net average expansion across the entire duration of a typical healthy pregnancy equates to roughly one-third of the pre-pregnancy baseline, which mathematically maps directly to 33%.","whyWrongChoices":"Alternative options: 50, 18, 25"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the mandatory food fortification program, cooking oil is fortified with::::vit a', 'under the mandatory food fortification program, cooking oil is fortified with:', 'Vit A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A – oil, sugar\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Iron, Iodine, Vit A and Iron"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the goal of nutrition education::::to change behavior', 'the goal of nutrition education:', 'To change behavior', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To change behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.\n\nPrograms that only focus on data transfer fail if they do not fix bad habits. Effective nutrition education is specifically designed to act as a motivational tool that translates knowledge into the continuous, voluntary adoption of healthy eating patterns and long-term dietary behavior changes.","whyWrongChoices":"Alternative options: To increase knowledge, To improve practices, To promote health"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the goal of nutrition education::::', 'the goal of nutrition education:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To change behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.\n\nPrograms that only focus on data transfer fail if they do not fix bad habits. Effective nutrition education is specifically designed to act as a motivational tool that translates knowledge into the continuous, voluntary adoption of healthy eating patterns and long-term dietary behavior changes.","whyWrongChoices":"Alternative options: To increase knowledge, To improve practices, To promote health"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an element of behavior change which pertains to the capacity of individual to perform a recommended response.:::self-efficacy', 'an element of behavior change which pertains to the capacity of individual to perform a recommended response.', 'Self-efficacy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-efficacy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.\n\n• Attitude: This refers to an individual''s positive or negative evaluations, feelings, or beliefs about a specific behavior, rather than their physical or mental capacity to perform it.\n• Reactance: This is a psychological resistance or negative reaction that occurs when individuals feel their personal freedom or choices are being threatened or restricted.\n• Cues to action: These are internal or external triggers (such as a doctor''s advice, a reminder app, or a family illness) that prompt a person to take action.","whyWrongChoices":"Alternative options: Attitude, Cues to action, Reactance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an element of behavior change which pertains to the capacity of individual to perform a recommended response.:::', 'an element of behavior change which pertains to the capacity of individual to perform a recommended response.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-efficacy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.\n\n• Attitude: This refers to an individual''s positive or negative evaluations, feelings, or beliefs about a specific behavior, rather than their physical or mental capacity to perform it.\n• Reactance: This is a psychological resistance or negative reaction that occurs when individuals feel their personal freedom or choices are being threatened or restricted.\n• Cues to action: These are internal or external triggers (such as a doctor''s advice, a reminder app, or a family illness) that prompt a person to take action.","whyWrongChoices":"Alternative options: Attitude, Cues to action, Reactance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:who is the chair of provincial nutrition committee?:::governor', 'who is the chair of provincial nutrition committee?', 'Governor', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Governor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:\n\n• Provincial Level: Chaired by the Governor.\n• City / Municipal Level: Chaired by the Mayor.\n• Barangay Level: Chaired by the Barangay Captain (Punong Barangay).\n\nThe Provincial Nutrition Action Officer (PNAO) operates under the leadership of the Governor to handle the day-to-day operations, implementation, and coordination of the province''s nutrition programs.","whyWrongChoices":"Alternative options: Provincial Nutrition Action Officer, Barangay Captain, Mayor"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?:::theory of planned behavior', 'which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?', 'Theory of Planned Behavior', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Theory of Planned Behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:\n\n1. Attitude toward the behavior: The community members'' personal belief that they will benefit from the nutrition program.\n2. Subjective Norms: The perceived social pressure from their environment, specifically because their friends think it is also a good idea.\n3. Perceived Behavioral Control: Their perceived ease or ability to execute the behavior, which fosters their readiness to get involved.\n\n• Self-determination Theory: Focuses heavily on the internal spectrum of motivation (intrinsic vs. extrinsic), which would be the primary choice if the question emphasized doing the activity out of pure, inherent enjoyment.\n• Precaution Adoption Process Model: This is a sequential stage-of-readiness model used to trace how an individual moves from complete unawareness to taking a specific health precaution.\n• Health Belief Model: While it includes \"perceived benefits\", it relies heavily on an individual''s evaluation of a health threat (perceived susceptibility and severity of an illness), which is not the primary focus or motivator described in this scenario.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Self-determination Theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?:::', 'which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Theory of Planned Behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:\n\n1. Attitude toward the behavior: The community members'' personal belief that they will benefit from the nutrition program.\n2. Subjective Norms: The perceived social pressure from their environment, specifically because their friends think it is also a good idea.\n3. Perceived Behavioral Control: Their perceived ease or ability to execute the behavior, which fosters their readiness to get involved.\n\n• Self-determination Theory: Focuses heavily on the internal spectrum of motivation (intrinsic vs. extrinsic), which would be the primary choice if the question emphasized doing the activity out of pure, inherent enjoyment.\n• Precaution Adoption Process Model: This is a sequential stage-of-readiness model used to trace how an individual moves from complete unawareness to taking a specific health precaution.\n• Health Belief Model: While it includes \"perceived benefits\", it relies heavily on an individual''s evaluation of a health threat (perceived susceptibility and severity of an illness), which is not the primary focus or motivator described in this scenario.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Self-determination Theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which communication model is to support action?:::diffusion of innovation', 'which communication model is to support action?', 'Diffusion of Innovation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diffusion of Innovation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.\n\nIt focuses heavily on how information is packaged and delivered via specific communication channels over time to move groups from initial awareness directly into concrete adoption and action.\n\n• Social cognitive theory / Self-efficacy model: These focus primarily on the cognitive determinants of a behavior—specifically how an individual''s confidence in their own ability (self-efficacy) and their social environment influence their personal behavior.\n• Transtheoretical model: This is a stage theory that maps out an individual''s motivational readiness to change behavior (from Precontemplation to Maintenance) rather than functioning primarily as an operational communication model to drive group action.","whyWrongChoices":"Alternative options: Transtheoretical model, Self-efficacy model, Social cognitive theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which communication model is to support action?:::', 'which communication model is to support action?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diffusion of Innovation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.\n\nIt focuses heavily on how information is packaged and delivered via specific communication channels over time to move groups from initial awareness directly into concrete adoption and action.\n\n• Social cognitive theory / Self-efficacy model: These focus primarily on the cognitive determinants of a behavior—specifically how an individual''s confidence in their own ability (self-efficacy) and their social environment influence their personal behavior.\n• Transtheoretical model: This is a stage theory that maps out an individual''s motivational readiness to change behavior (from Precontemplation to Maintenance) rather than functioning primarily as an operational communication model to drive group action.","whyWrongChoices":"Alternative options: Transtheoretical model, Self-efficacy model, Social cognitive theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a nutrition education method that includes bench conferences.:::group discussion', 'a nutrition education method that includes bench conferences.', 'Group discussion', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Group discussion\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.\n\nA bench conference occurs when a health worker or nutritionist gathers a small cluster of mothers, caregivers, or patients who are sitting together on a bench waiting for their turn in a rural health unit or clinic.\n\n• Rather than structured one-on-one counseling behind closed doors, the educator utilizes this shared waiting space to initiate a small group interaction.\n• Because it encourages the individuals sitting together to exchange ideas, ask questions, and learn from each other''s experiences under the guidance of the facilitator, it is classified academically under Group discussion methods.","whyWrongChoices":"Alternative options: Nutrition counseling, Mass media, Social marketing"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a nutrition education method that includes bench conferences.:::', 'a nutrition education method that includes bench conferences.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Group discussion\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.\n\nA bench conference occurs when a health worker or nutritionist gathers a small cluster of mothers, caregivers, or patients who are sitting together on a bench waiting for their turn in a rural health unit or clinic.\n\n• Rather than structured one-on-one counseling behind closed doors, the educator utilizes this shared waiting space to initiate a small group interaction.\n• Because it encourages the individuals sitting together to exchange ideas, ask questions, and learn from each other''s experiences under the guidance of the facilitator, it is classified academically under Group discussion methods.","whyWrongChoices":"Alternative options: Nutrition counseling, Mass media, Social marketing"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which province is a priority area in the ppan 2023-2028?:::basilan', 'which province is a priority area in the ppan 2023-2028?', 'Basilan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Basilan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.\n\nBasilan is officially classified as a high-priority province, ranking 9th overall nationwide on the target list for intensive nutrition interventions and financial support.\n\nThe Top 10 highest priority provinces targeted for intensive, multi-sectoral nutrition interventions are:\n1. Leyte\n2. Sulu\n3. Negros Occidental\n4. Negros Oriental\n5. Samar\n6. Lanao del Norte\n7. Masbate\n8. Palawan\n9. Basilan\n10. Cebu\n\nKey Broad Facts on the 34 Priority Areas:\n• The Rest of the Top 16: Immediately following the top ten are Camarines Sur, Quezon, Zamboanga del Norte, Zamboanga del Sur, Maguindanao, and Bukidnon.\n• Convergent Strategy: Government programs like the Tutok Kainan Dietary Supplementation Program prioritize these specific locations to provide nutritional support during the critical First 1,000 Days of child development.","whyWrongChoices":"Alternative options: Batangas, Batanes, Benguet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the first step in conducting a training?:::needs assessment', 'what is the first step in conducting a training?', 'Needs assessment', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Needs assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.\n\nThe Training Process Order:\n\n1. Needs assessment (Identify the gaps)\n2. Identification of training objectives (Define what success looks like based on the gaps)\n3. Preparation for training design / Planning (Outline methods, timelines, and content)\n4. Implementation (Conducting the training)\n5. Evaluation (Measuring the training''s effectiveness)","whyWrongChoices":"Alternative options: Planning for the training, Preparation for training design, Identification of training objectives"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the first step in conducting a training?:::', 'what is the first step in conducting a training?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Needs assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.\n\nThe Training Process Order:\n\n1. Needs assessment (Identify the gaps)\n2. Identification of training objectives (Define what success looks like based on the gaps)\n3. Preparation for training design / Planning (Outline methods, timelines, and content)\n4. Implementation (Conducting the training)\n5. Evaluation (Measuring the training''s effectiveness)","whyWrongChoices":"Alternative options: Planning for the training, Preparation for training design, Identification of training objectives"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is an example of non-verbal communication?:::tone of voice', 'which is an example of non-verbal communication?', 'Tone of voice', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tone of voice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","whyWrongChoices":"Alternative options: Maps, Traffic signals, Reports"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is an example of non-verbal communication?:::', 'which is an example of non-verbal communication?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tone of voice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","whyWrongChoices":"Alternative options: Maps, Traffic signals, Reports"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which province is a priority area in the ppan 2023-2028?:::', 'which province is a priority area in the ppan 2023-2028?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Basilan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.\n\nBasilan is officially classified as a high-priority province, ranking 9th overall nationwide on the target list for intensive nutrition interventions and financial support.\n\nThe Top 10 highest priority provinces targeted for intensive, multi-sectoral nutrition interventions are:\n1. Leyte\n2. Sulu\n3. Negros Occidental\n4. Negros Oriental\n5. Samar\n6. Lanao del Norte\n7. Masbate\n8. Palawan\n9. Basilan\n10. Cebu\n\nKey Broad Facts on the 34 Priority Areas:\n• The Rest of the Top 16: Immediately following the top ten are Camarines Sur, Quezon, Zamboanga del Norte, Zamboanga del Sur, Maguindanao, and Bukidnon.\n• Convergent Strategy: Government programs like the Tutok Kainan Dietary Supplementation Program prioritize these specific locations to provide nutritional support during the critical First 1,000 Days of child development.","whyWrongChoices":"Alternative options: Batangas, Batanes, Benguet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:who is the chair of provincial nutrition committee?:::', 'who is the chair of provincial nutrition committee?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Governor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:\n\n• Provincial Level: Chaired by the Governor.\n• City / Municipal Level: Chaired by the Mayor.\n• Barangay Level: Chaired by the Barangay Captain (Punong Barangay).\n\nThe Provincial Nutrition Action Officer (PNAO) operates under the leadership of the Governor to handle the day-to-day operations, implementation, and coordination of the province''s nutrition programs.","whyWrongChoices":"Alternative options: Provincial Nutrition Action Officer, Barangay Captain, Mayor"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the first philippine food and nutrition plan was called ?:::philippine nutrition program', 'the first philippine food and nutrition plan was called ?', 'Philippine Nutrition Program', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In 1971, President Ferdinand Marcos Sr. issued Executive Order No. 285, authorizing the National Food and Agriculture Council (NFAC) to coordinate all nutrition activities.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Philippine Nutrition Program\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In 1971, President Ferdinand Marcos Sr. issued Executive Order No. 285, authorizing the National Food and Agriculture Council (NFAC) to coordinate all nutrition activities.\n\nThis integrated nationwide operation was officially known as the Philippine Food and Nutrition Program (PFNP) or simply the Philippine Nutrition Program (PNP).\n\nIt served as the structural blueprint for national intervention before the creation of the National Nutrition Council (NNC) in 1974 and the later evolution of the framework into what we now call the Philippine Plan of Action for Nutrition (PPAN).\n\n• Philippine Food and Nutrition Program (PFNP, 1971–1974): Before the formal creation of the council, the National Food and Agriculture Council (NFAC) coordinated the first four-year Philippine Food and Nutrition Program under Executive Order No. 285.\n• Philippine Nutrition Program (PNP, 1974–1983): In 1974, Presidential Decree No. 491 established the National Nutrition Council (NNC), formally consolidating national nutrition activities into the Philippine Nutrition Program (PNP). It covered iterations such as PNP 1974–1977 and PNP 1978–1982.\n• Food and Nutrition Plan / Philippine Food and Nutrition Plan (FNP / PFNP, 1984–1992): In the mid-1980s, the blueprint returned to a linked agriculture-and-nutrition scope, adopted as the Food and Nutrition Plan (1984–1987) and later updated under the post-1986 reorganized NNC (via Executive Order No. 234) as the Philippine Food and Nutrition Plan (1987–1992).\n• Philippine Plan of Action for Nutrition (PPAN, 1993–Present): Following the global 1992 International Conference on Nutrition (ICN) in Rome, the Philippines aligned with international frameworks by adopting the title Philippine Plan of Action for Nutrition. \n\nWhile sometimes referenced alongside the medium-term planning cycles (e.g., MTPFNP/MTPPAN), the core official name of the plan series became PPAN, which has continued across successive medium-term cycles:\n\t• PPAN 1993–1998\n\t• PPAN 1999–2004\n\t• PPAN 2005–2010\n\t• PPAN 2011–2016\n\t• PPAN 2017–2022\n\t• PPAN 2023–2028","whyWrongChoices":"Alternative options: Food and Nutrition Plan, Philippine Food and Nutrition Plan, Philippine Plan of Action for Nutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the first philippine food and nutrition plan was called ?:::', 'the first philippine food and nutrition plan was called ?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In 1971, President Ferdinand Marcos Sr. issued Executive Order No. 285, authorizing the National Food and Agriculture Council (NFAC) to coordinate all nutrition activities.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Philippine Nutrition Program\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In 1971, President Ferdinand Marcos Sr. issued Executive Order No. 285, authorizing the National Food and Agriculture Council (NFAC) to coordinate all nutrition activities.\n\nThis integrated nationwide operation was officially known as the Philippine Food and Nutrition Program (PFNP) or simply the Philippine Nutrition Program (PNP).\n\nIt served as the structural blueprint for national intervention before the creation of the National Nutrition Council (NNC) in 1974 and the later evolution of the framework into what we now call the Philippine Plan of Action for Nutrition (PPAN).\n\n• Philippine Food and Nutrition Program (PFNP, 1971–1974): Before the formal creation of the council, the National Food and Agriculture Council (NFAC) coordinated the first four-year Philippine Food and Nutrition Program under Executive Order No. 285.\n• Philippine Nutrition Program (PNP, 1974–1983): In 1974, Presidential Decree No. 491 established the National Nutrition Council (NNC), formally consolidating national nutrition activities into the Philippine Nutrition Program (PNP). It covered iterations such as PNP 1974–1977 and PNP 1978–1982.\n• Food and Nutrition Plan / Philippine Food and Nutrition Plan (FNP / PFNP, 1984–1992): In the mid-1980s, the blueprint returned to a linked agriculture-and-nutrition scope, adopted as the Food and Nutrition Plan (1984–1987) and later updated under the post-1986 reorganized NNC (via Executive Order No. 234) as the Philippine Food and Nutrition Plan (1987–1992).\n• Philippine Plan of Action for Nutrition (PPAN, 1993–Present): Following the global 1992 International Conference on Nutrition (ICN) in Rome, the Philippines aligned with international frameworks by adopting the title Philippine Plan of Action for Nutrition. \n\nWhile sometimes referenced alongside the medium-term planning cycles (e.g., MTPFNP/MTPPAN), the core official name of the plan series became PPAN, which has continued across successive medium-term cycles:\n\t• PPAN 1993–1998\n\t• PPAN 1999–2004\n\t• PPAN 2005–2010\n\t• PPAN 2011–2016\n\t• PPAN 2017–2022\n\t• PPAN 2023–2028","whyWrongChoices":"Alternative options: Food and Nutrition Plan, Philippine Food and Nutrition Plan, Philippine Plan of Action for Nutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which law targets addressing specific micronutrient deficiencies by mandatory fortification of staple food items such as rice with iron, wheat flour with vit a and iron, refined sugar with vit a and cooking oil with vit a and voluntary fortification of other food items?:::ra 8976', 'which law targets addressing specific micronutrient deficiencies by mandatory fortification of staple food items such as rice with iron, wheat flour with vit a and iron, refined sugar with vit a and cooking oil with vit a and voluntary fortification of other food items?', 'RA 8976', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Republic Act 8976 (The Philippine Food Fortification Act of 2000) mandates the fortification of staple foods to address widespread micronutrient deficiencies (specifically Vitamin A, Iron, and Iodine). It explicitly requires the mandatory fortification of:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"RA 8976\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Republic Act 8976 (The Philippine Food Fortification Act of 2000) mandates the fortification of staple foods to address widespread micronutrient deficiencies (specifically Vitamin A, Iron, and Iodine). It explicitly requires the mandatory fortification of:\n\t• Rice with Iron\n\t• Wheat flour with Vitamin A and Iron\n\t• Refined sugar with Vitamin A\n\t• Cooking oil with Vitamin A\n\nIt also covers the voluntary fortification of processed food items through the National Nutrition Council (NNC)''s \"Sangkap Pinoy\" seal program.\n\n• RA 8172: The ASIN Law (Act for Salt Iodization Nationwide), which mandates the iodization of all food-grade salt.\n• RA 10028: The Expanded Breastfeeding Promotion Act of 2009.\n• RA 7600: The Rooming-In and Breastfeeding Act of 1992.","whyWrongChoices":"Alternative options: RA 7600, RA 8172, RA 10028"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a cluster of programs that is comprehensive, long-range in time frame, and includes defined goals, strategies, and guidelines for implementation.:::plan', 'is a cluster of programs that is comprehensive, long-range in time frame, and includes defined goals, strategies, and guidelines for implementation.', 'Plan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the official Nutrition Program Management and community planning taxonomy, these structural terms are arranged in a specific hierarchy:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Plan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the official Nutrition Program Management and community planning taxonomy, these structural terms are arranged in a specific hierarchy:\n\n1. Plan: This is the highest level of the hierarchy. It refers to a comprehensive, long-range cluster of programs that contains overarching defined goals, strategies, and broad guidelines for implementation. A prime example is the Philippine Plan of Action for Nutrition (PPAN).\n2. Program: This sits below a plan and is a set of interrelated projects that coordinates personnel, facilities, money, equipment, and supplies to accomplish a specific operational objective.\n3. Project: This is a specific, time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timetable.\n4. Policy: This serves as the broad, overarching legal or administrative instrument—the system of principles or rules—that guides subsequent development plans.","whyWrongChoices":"Alternative options: Policy, Program, Project"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a cluster of programs that is comprehensive, long-range in time frame, and includes defined goals, strategies, and guidelines for implementation.:::', 'is a cluster of programs that is comprehensive, long-range in time frame, and includes defined goals, strategies, and guidelines for implementation.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the official Nutrition Program Management and community planning taxonomy, these structural terms are arranged in a specific hierarchy:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Plan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the official Nutrition Program Management and community planning taxonomy, these structural terms are arranged in a specific hierarchy:\n\n1. Plan: This is the highest level of the hierarchy. It refers to a comprehensive, long-range cluster of programs that contains overarching defined goals, strategies, and broad guidelines for implementation. A prime example is the Philippine Plan of Action for Nutrition (PPAN).\n2. Program: This sits below a plan and is a set of interrelated projects that coordinates personnel, facilities, money, equipment, and supplies to accomplish a specific operational objective.\n3. Project: This is a specific, time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timetable.\n4. Policy: This serves as the broad, overarching legal or administrative instrument—the system of principles or rules—that guides subsequent development plans.","whyWrongChoices":"Alternative options: Policy, Program, Project"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a specific and time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timeable.:::project', 'is a specific and time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timeable.', 'Project', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By standard administrative and project management definitions, a project is a temporary, specific, and time-bound endeavor. It possesses a clearly defined start and end date, sequential activities, and a dedicated budget allocated to produce a unique product, service, or result that fulfills a specific objective.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Project\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By standard administrative and project management definitions, a project is a temporary, specific, and time-bound endeavor. It possesses a clearly defined start and end date, sequential activities, and a dedicated budget allocated to produce a unique product, service, or result that fulfills a specific objective.\n\n• Policy: A standing operational plan that serves as a broad, ongoing guideline for decision-making and employee behavior rather than a temporary set of tasks.\n• Plan: The overarching blueprint or management process of setting broad organizational goals and mapping out how to achieve them.\n• Program: A long-term, continuous framework that aggregates multiple individual projects under a shared theme or broader social goal, usually lacking a singular, short-term definitive timeline.","whyWrongChoices":"Alternative options: Policy, Plan, Program"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a specific and time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timeable.:::', 'is a specific and time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timeable.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By standard administrative and project management definitions, a project is a temporary, specific, and time-bound endeavor. It possesses a clearly defined start and end date, sequential activities, and a dedicated budget allocated to produce a unique product, service, or result that fulfills a specific objective.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Project\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By standard administrative and project management definitions, a project is a temporary, specific, and time-bound endeavor. It possesses a clearly defined start and end date, sequential activities, and a dedicated budget allocated to produce a unique product, service, or result that fulfills a specific objective.\n\n• Policy: A standing operational plan that serves as a broad, ongoing guideline for decision-making and employee behavior rather than a temporary set of tasks.\n• Plan: The overarching blueprint or management process of setting broad organizational goals and mapping out how to achieve them.\n• Program: A long-term, continuous framework that aggregates multiple individual projects under a shared theme or broader social goal, usually lacking a singular, short-term definitive timeline.","whyWrongChoices":"Alternative options: Policy, Plan, Program"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are programs that address the immediate determinants of fetal and child nutrition and development.:::nutrition-specific', 'these are programs that address the immediate determinants of fetal and child nutrition and development.', 'Nutrition-specific', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to global health frameworks (such as The Lancet Maternal and Child Nutrition Series) and Philippine law (such as Republic Act 11148), interventions are categorized based on what causes of malnutrition they address:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition-specific\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to global health frameworks (such as The Lancet Maternal and Child Nutrition Series) and Philippine law (such as Republic Act 11148), interventions are categorized based on what causes of malnutrition they address:\n\n• Nutrition-specific programs directly address the immediate determinants of fetal and child nutrition and development. These include factors like adequate food and nutrient intake, infant feeding and caregiving practices, and reducing the burden of infectious diseases. Examples include micronutrient supplementation, exclusive breastfeeding promotion, and the treatment of severe acute malnutrition.\n• Nutrition-sensitive programs address the underlying determinants of malnutrition. These involve systemic sectors like agriculture, food security, social protection, clean water and sanitation (WASH), and female education.","whyWrongChoices":"Alternative options: Nutrition-related, Nutrition-sensitive, Nutrition-oriented"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are programs that address the immediate determinants of fetal and child nutrition and development.:::', 'these are programs that address the immediate determinants of fetal and child nutrition and development.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to global health frameworks (such as The Lancet Maternal and Child Nutrition Series) and Philippine law (such as Republic Act 11148), interventions are categorized based on what causes of malnutrition they address:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition-specific\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to global health frameworks (such as The Lancet Maternal and Child Nutrition Series) and Philippine law (such as Republic Act 11148), interventions are categorized based on what causes of malnutrition they address:\n\n• Nutrition-specific programs directly address the immediate determinants of fetal and child nutrition and development. These include factors like adequate food and nutrient intake, infant feeding and caregiving practices, and reducing the burden of infectious diseases. Examples include micronutrient supplementation, exclusive breastfeeding promotion, and the treatment of severe acute malnutrition.\n• Nutrition-sensitive programs address the underlying determinants of malnutrition. These involve systemic sectors like agriculture, food security, social protection, clean water and sanitation (WASH), and female education.","whyWrongChoices":"Alternative options: Nutrition-related, Nutrition-sensitive, Nutrition-oriented"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is the country''s highest policy-making and coordinating body on nutrition.:::nnc', 'is the country''s highest policy-making and coordinating body on nutrition.', 'NNC', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The National Nutrition Council (NNC) is officially recognized by law as the Philippines'' highest policy-making and coordinating body on nutrition.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"NNC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The National Nutrition Council (NNC) is officially recognized by law as the Philippines'' highest policy-making and coordinating body on nutrition.\n\nIt was originally created under Presidential Decree No. 491 (The Nutrition Act of the Philippines) in 1974 and is an attached agency of the Department of Health (DOH). The NNC is responsible for orchestrating multi-sectoral strategies like the Philippine Plan of Action for Nutrition (PPAN) to eliminate hunger and malnutrition nationwide.\n\n• NEDA (National Economic and Development Authority): The country''s premier social and economic development planning and policy coordinating body.\n• NFP (Nutrition Foundation of the Philippines): A non-government, non-profit organization dedicated to promoting nutritional wellness.\n• NCP (Nutrition Center of the Philippines): A private foundation that develops programmatic interventions and specialized nutritional products.","whyWrongChoices":"Alternative options: NCP, NFP, NEDA"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is the country''s highest policy-making and coordinating body on nutrition.:::', 'is the country''s highest policy-making and coordinating body on nutrition.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The National Nutrition Council (NNC) is officially recognized by law as the Philippines'' highest policy-making and coordinating body on nutrition.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"NNC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The National Nutrition Council (NNC) is officially recognized by law as the Philippines'' highest policy-making and coordinating body on nutrition.\n\nIt was originally created under Presidential Decree No. 491 (The Nutrition Act of the Philippines) in 1974 and is an attached agency of the Department of Health (DOH). The NNC is responsible for orchestrating multi-sectoral strategies like the Philippine Plan of Action for Nutrition (PPAN) to eliminate hunger and malnutrition nationwide.\n\n• NEDA (National Economic and Development Authority): The country''s premier social and economic development planning and policy coordinating body.\n• NFP (Nutrition Foundation of the Philippines): A non-government, non-profit organization dedicated to promoting nutritional wellness.\n• NCP (Nutrition Center of the Philippines): A private foundation that develops programmatic interventions and specialized nutritional products.","whyWrongChoices":"Alternative options: NCP, NFP, NEDA"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which law targets addressing specific micronutrient deficiencies by mandatory fortification of staple food items such as rice with iron, wheat flour with vit a and iron, refined sugar with vit a and cooking oil with vit a and voluntary fortification of other food items?:::', 'which law targets addressing specific micronutrient deficiencies by mandatory fortification of staple food items such as rice with iron, wheat flour with vit a and iron, refined sugar with vit a and cooking oil with vit a and voluntary fortification of other food items?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Republic Act 8976 (The Philippine Food Fortification Act of 2000) mandates the fortification of staple foods to address widespread micronutrient deficiencies (specifically Vitamin A, Iron, and Iodine). It explicitly requires the mandatory fortification of:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"RA 8976\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Republic Act 8976 (The Philippine Food Fortification Act of 2000) mandates the fortification of staple foods to address widespread micronutrient deficiencies (specifically Vitamin A, Iron, and Iodine). It explicitly requires the mandatory fortification of:\n\t• Rice with Iron\n\t• Wheat flour with Vitamin A and Iron\n\t• Refined sugar with Vitamin A\n\t• Cooking oil with Vitamin A\n\nIt also covers the voluntary fortification of processed food items through the National Nutrition Council (NNC)''s \"Sangkap Pinoy\" seal program.\n\n• RA 8172: The ASIN Law (Act for Salt Iodization Nationwide), which mandates the iodization of all food-grade salt.\n• RA 10028: The Expanded Breastfeeding Promotion Act of 2009.\n• RA 7600: The Rooming-In and Breastfeeding Act of 1992.","whyWrongChoices":"Alternative options: RA 7600, RA 8172, RA 10028"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following enhances the absorption of zinc?:::', 'which of the following enhances the absorption of zinc?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glutamate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.","whyWrongChoices":"Alternative options: Tryptophan, Acetyl CoA, Thiamin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to prepare a potential bns for deployment in his/her barangay, a bns should undergo a training and days of practicum:::20 days', 'to prepare a potential bns for deployment in his/her barangay, a bns should undergo a training and days of practicum', '20 days', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the National Nutrition Council (NNC) implementing guidelines under Presidential Decree No. 1569, a potential Barangay Nutrition Scholar (BNS) must successfully complete a two-part basic training program before full field deployment:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"20 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the National Nutrition Council (NNC) implementing guidelines under Presidential Decree No. 1569, a potential Barangay Nutrition Scholar (BNS) must successfully complete a two-part basic training program before full field deployment:\n\n1. Didactic Phase: A classroom-based instruction course (traditionally structured as a 5-day to 10-day basic course) covering core technical inputs on malnutrition, health, the First 1000 Days, and data tools.\n2. Practicum Phase: A mandatory 20-day hands-on community practicum.\n\nDuring the 20 days of field practice, the scholar learns to master community nutrition management tasks under direct supervision. This includes operating anthropometric equipment to weigh and measure preschoolers (Operation Timbang Plus), conducting localized family profiling interviews, building a community nutrition spot map, and formulating a customized Barangay Nutrition Action Plan (BNAP).","whyWrongChoices":"Alternative options: 5 days, 10 days, 15 days"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to prepare a potential bns for deployment in his/her barangay, a bns should undergo a training and days of practicum:::', 'to prepare a potential bns for deployment in his/her barangay, a bns should undergo a training and days of practicum', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the National Nutrition Council (NNC) implementing guidelines under Presidential Decree No. 1569, a potential Barangay Nutrition Scholar (BNS) must successfully complete a two-part basic training program before full field deployment:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"20 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the National Nutrition Council (NNC) implementing guidelines under Presidential Decree No. 1569, a potential Barangay Nutrition Scholar (BNS) must successfully complete a two-part basic training program before full field deployment:\n\n1. Didactic Phase: A classroom-based instruction course (traditionally structured as a 5-day to 10-day basic course) covering core technical inputs on malnutrition, health, the First 1000 Days, and data tools.\n2. Practicum Phase: A mandatory 20-day hands-on community practicum.\n\nDuring the 20 days of field practice, the scholar learns to master community nutrition management tasks under direct supervision. This includes operating anthropometric equipment to weigh and measure preschoolers (Operation Timbang Plus), conducting localized family profiling interviews, building a community nutrition spot map, and formulating a customized Barangay Nutrition Action Plan (BNAP).","whyWrongChoices":"Alternative options: 5 days, 10 days, 15 days"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute the calories provided by a 2-l dialysate solution containing 2.5% dextrose.:::170 kcal', 'compute the calories provided by a 2-l dialysate solution containing 2.5% dextrose.', '170 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A 2.5% dextrose solution contains 2.5 g of dextrose per 100 mL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"170 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A 2.5% dextrose solution contains 2.5 g of dextrose per 100 mL.\n\nFor 2 L (2,000 mL):\n2.5 g/100 mL × 2,000 mL = 50 g dextrose\n\nDextrose provides approximately 3.4 kcal/g\n50 g × 3.4 kcal/g = 170 kcal\n\nTherefore, the dialysate provides approximately 170 kcal.","whyWrongChoices":"Alternative options: 108 kcal, 148 kcal, 200 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the bns program guidelines, the direct trainer-supervisor of the bns is::::district/city nutrition program coordinator', 'in the bns program guidelines, the direct trainer-supervisor of the bns is:', 'District/City Nutrition Program Coordinator', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the official guidelines issued by the National Nutrition Council (NNC), the District/City Nutrition Program Coordinator (D/CNPC) serves as the direct trainer-supervisor of the Barangay Nutrition Scholar (BNS).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"District/City Nutrition Program Coordinator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the official guidelines issued by the National Nutrition Council (NNC), the District/City Nutrition Program Coordinator (D/CNPC) serves as the direct trainer-supervisor of the Barangay Nutrition Scholar (BNS).\n\n• The D/CNPC is explicitly tasked with organizing, conducting, and supervising both the core didactic training and the subsequent 20-day local community practicum for new scholars.\n• Guidelines specify that only in the structural or operational absence of an assigned D/CNPC will the local City/Municipal Nutrition Action Officer (NAO) step in to assume these training and supervision responsibilities.","whyWrongChoices":"Alternative options: City/Municipal Nutrition Action Officer, Provincial Nutrition Action Officer, Regional Nutrition Program Coordinator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the bns program guidelines, the direct trainer-supervisor of the bns is::::', 'in the bns program guidelines, the direct trainer-supervisor of the bns is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the official guidelines issued by the National Nutrition Council (NNC), the District/City Nutrition Program Coordinator (D/CNPC) serves as the direct trainer-supervisor of the Barangay Nutrition Scholar (BNS).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"District/City Nutrition Program Coordinator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the official guidelines issued by the National Nutrition Council (NNC), the District/City Nutrition Program Coordinator (D/CNPC) serves as the direct trainer-supervisor of the Barangay Nutrition Scholar (BNS).\n\n• The D/CNPC is explicitly tasked with organizing, conducting, and supervising both the core didactic training and the subsequent 20-day local community practicum for new scholars.\n• Guidelines specify that only in the structural or operational absence of an assigned D/CNPC will the local City/Municipal Nutrition Action Officer (NAO) step in to assume these training and supervision responsibilities.","whyWrongChoices":"Alternative options: City/Municipal Nutrition Action Officer, Provincial Nutrition Action Officer, Regional Nutrition Program Coordinator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the basic tasks of bns are the following except::::leads in the preparation of the local nutrition action plan', 'the basic tasks of bns are the following except:', 'Leads in the preparation of the local nutrition action plan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the official National Nutrition Council (NNC) guidelines and the Barangay Nutrition Scholar (BNS) Handbook, the basic tasks of a BNS are clearly codified as:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Leads in the preparation of the local nutrition action plan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the official National Nutrition Council (NNC) guidelines and the Barangay Nutrition Scholar (BNS) Handbook, the basic tasks of a BNS are clearly codified as:\n\n1. Caring for the malnourished (identifying and tracking them via Operation Timbang Plus)\n2. Mobilizing the community\n3. Linkage-building\n4. Keeping records (maintaining barangay nutrition profiles and family sheets)\n\nThe BNS does not lead the preparation of the Local Nutrition Action Plan (LNAP). Leadership and authorship of the plan fall under the mandate of the Local Nutrition Committee (LNC) and its Chairperson (the Punong Barangay / Barangay Captain). The role of the BNS is strictly to assist and provide data to the committee during the formulation of the Barangay Nutrition Action Plan (BNAP).","whyWrongChoices":"Alternative options: Caring for the malnourished, Mobilizing the community, Keeping records"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the basic tasks of bns are the following except::::', 'the basic tasks of bns are the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the official National Nutrition Council (NNC) guidelines and the Barangay Nutrition Scholar (BNS) Handbook, the basic tasks of a BNS are clearly codified as:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Leads in the preparation of the local nutrition action plan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the official National Nutrition Council (NNC) guidelines and the Barangay Nutrition Scholar (BNS) Handbook, the basic tasks of a BNS are clearly codified as:\n\n1. Caring for the malnourished (identifying and tracking them via Operation Timbang Plus)\n2. Mobilizing the community\n3. Linkage-building\n4. Keeping records (maintaining barangay nutrition profiles and family sheets)\n\nThe BNS does not lead the preparation of the Local Nutrition Action Plan (LNAP). Leadership and authorship of the plan fall under the mandate of the Local Nutrition Committee (LNC) and its Chairperson (the Punong Barangay / Barangay Captain). The role of the BNS is strictly to assist and provide data to the committee during the formulation of the Barangay Nutrition Action Plan (BNAP).","whyWrongChoices":"Alternative options: Caring for the malnourished, Mobilizing the community, Keeping records"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in conducting mental feeding to daycare students, which nutrition education material is best to use?:::cartoons', 'in conducting mental feeding to daycare students, which nutrition education material is best to use?', 'Cartoons', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cartoons are colorful and engaging, appropriate for children.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cartoons\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cartoons are colorful and engaging, appropriate for children.\n\n• Diorama - formal\n• Comics - individual\n• Caricature - satirical or comic effect.","whyWrongChoices":"Alternative options: Diorama, Comics, Caricature"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a suitable indicator for the evaluation of child feeding programs is change in::::child''s weight for length/height', 'a suitable indicator for the evaluation of child feeding programs is change in:', 'Child''s weight for length/height', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Supplementary feeding programs for infants and young children primarily target the eradication of wasting (acute malnutrition) and the restoration of normal body mass. The most sensitive, immediate, and reliable indicator to evaluate whether a short-term feeding program is successfully working is the change in a child''s weight-for-length (for infants under 2 years) or weight-for-height (for older children).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Child''s weight for length/height\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Supplementary feeding programs for infants and young children primarily target the eradication of wasting (acute malnutrition) and the restoration of normal body mass. The most sensitive, immediate, and reliable indicator to evaluate whether a short-term feeding program is successfully working is the change in a child''s weight-for-length (for infants under 2 years) or weight-for-height (for older children).","whyWrongChoices":"Alternative options: Child''s height, Child''s improved feeding practices, Decreased incidence of diarrhea among children"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a suitable indicator for the evaluation of child feeding programs is change in::::', 'a suitable indicator for the evaluation of child feeding programs is change in:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Supplementary feeding programs for infants and young children primarily target the eradication of wasting (acute malnutrition) and the restoration of normal body mass. The most sensitive, immediate, and reliable indicator to evaluate whether a short-term feeding program is successfully working is the change in a child''s weight-for-length (for infants under 2 years) or weight-for-height (for older children).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Child''s weight for length/height\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Supplementary feeding programs for infants and young children primarily target the eradication of wasting (acute malnutrition) and the restoration of normal body mass. The most sensitive, immediate, and reliable indicator to evaluate whether a short-term feeding program is successfully working is the change in a child''s weight-for-length (for infants under 2 years) or weight-for-height (for older children).","whyWrongChoices":"Alternative options: Child''s height, Child''s improved feeding practices, Decreased incidence of diarrhea among children"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient on tube feeding has a diet rx of 2000 calories, 2:1 dilution; how much is the total fluid.:::1000 ml', 'a patient on tube feeding has a diet rx of 2000 calories, 2:1 dilution; how much is the total fluid.', '1000 ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the traditional tube-feeding prescription, a 2:1 dilution means 2 kcal for every 1 mL of formula. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1000 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the traditional tube-feeding prescription, a 2:1 dilution means 2 kcal for every 1 mL of formula. \n\nTherefore: 2,000 kcal ÷ 2 kcal/mL = 1,000 mL/day\n\nThus, the total volume of tube-feeding formula prescribed is 1,000 mL/day.","whyWrongChoices":"Alternative options: 1500 ml, 1250 ml, 2250 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a point person in nutrition who is a regular employee of and under the plantilla of nnc.:::rnpc', 'a point person in nutrition who is a regular employee of and under the plantilla of nnc.', 'RNPC', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Regional Nutrition Program Coordinator (RNPC) is a permanent, regular civil service worker who occupies a formal plantilla item directly under the budget and structural organization of the National Nutrition Council (NNC). They serve as the head of the NNC Regional Secretariat, managing regional policy execution, monitoring local implementations of the PPAN, and coordinating across subnational administrative levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"RNPC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Regional Nutrition Program Coordinator (RNPC) is a permanent, regular civil service worker who occupies a formal plantilla item directly under the budget and structural organization of the National Nutrition Council (NNC). They serve as the head of the NNC Regional Secretariat, managing regional policy execution, monitoring local implementations of the PPAN, and coordinating across subnational administrative levels.\n\n• CNAO / CNPC (City Nutrition Action Officer / City Nutrition Program Coordinator) & DNPC (District Nutrition Program Coordinator): These positions operate at the Local Government Unit (LGU) level. They are typically funded by the local city, municipality, or province budgets rather than holding a national NNC secretariat plantilla item, or they are designated from other existing local health department roles.","whyWrongChoices":"Alternative options: CNPC, DNPC, CNAO"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
