INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the national dietary supplement program targets the following age groups except::::', 'the national dietary supplement program targets the following age groups except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The National Dietary Supplementation Program (NDSP)—including its banner strategy Tutok Kainan—deliberately excludes infants 0 to 5 months old from receiving solid food or dietary supplements. According to global and local healthcare standards, infants in this age bracket must practice strict exclusive breastfeeding; introducing any form of dietary supplementation or complementary food would disrupt this and increase the risk of infection.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Infants 0-5 months\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The National Dietary Supplementation Program (NDSP)—including its banner strategy Tutok Kainan—deliberately excludes infants 0 to 5 months old from receiving solid food or dietary supplements. According to global and local healthcare standards, infants in this age bracket must practice strict exclusive breastfeeding; introducing any form of dietary supplementation or complementary food would disrupt this and increase the risk of infection.\n\nTargeted Vulnerable Groups Under the NDSP:\n• Pregnant women (especially those classified as nutritionally at-risk, provided food support for 90 days).\n• Young children 6 to 59 months old (broken down into infants/toddlers aged 6–23 months for complementary feeding, and children aged 24–59 months).\n• School children (specifically severely wasted or wasted kindergarten to Grade 6 students enrolled in public schools).","whyWrongChoices":"Alternative options: Young children 6-59 months old, School children, Pregnant women"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a point person in nutrition who is a regular employee of and under the plantilla of nnc.:::', 'a point person in nutrition who is a regular employee of and under the plantilla of nnc.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Regional Nutrition Program Coordinator (RNPC) is a permanent, regular civil service worker who occupies a formal plantilla item directly under the budget and structural organization of the National Nutrition Council (NNC). They serve as the head of the NNC Regional Secretariat, managing regional policy execution, monitoring local implementations of the PPAN, and coordinating across subnational administrative levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"RNPC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Regional Nutrition Program Coordinator (RNPC) is a permanent, regular civil service worker who occupies a formal plantilla item directly under the budget and structural organization of the National Nutrition Council (NNC). They serve as the head of the NNC Regional Secretariat, managing regional policy execution, monitoring local implementations of the PPAN, and coordinating across subnational administrative levels.\n\n• CNAO / CNPC (City Nutrition Action Officer / City Nutrition Program Coordinator) & DNPC (District Nutrition Program Coordinator): These positions operate at the Local Government Unit (LGU) level. They are typically funded by the local city, municipality, or province budgets rather than holding a national NNC secretariat plantilla item, or they are designated from other existing local health department roles.","whyWrongChoices":"Alternative options: CNPC, DNPC, CNAO"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the philippine plan of action for nutrition is integrated and/or consistent with the following except::::philippine environmental plan', 'the philippine plan of action for nutrition is integrated and/or consistent with the following except:', 'Philippine Environmental Plan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Philippine Plan of Action for Nutrition (PPAN) serves as the country’s comprehensive multi-sectoral framework designed to combat all forms of malnutrition. It is systematically aligned with, and anchored into, the following major national development strategies:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Philippine Environmental Plan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Philippine Plan of Action for Nutrition (PPAN) serves as the country’s comprehensive multi-sectoral framework designed to combat all forms of malnutrition. It is systematically aligned with, and anchored into, the following major national development strategies:\n\n• Philippine Development Plan (PDP): It is an integral sub-component of the national Philippine Development Plan framework, directly contributing to social transformation, human development, and poverty reduction goals.\n• Health for All Agenda of the DOH: It directly supports the Department of Health’s principal universal healthcare blueprints (such as the National Objectives for Health and its respective action agendas).\n• Ambisyon Natin 2040: It explicitly serves as an operational mechanism to meet the long-term vision of Ambisyon Natin 2040 by ensuring a healthy, well-nourished, and highly productive citizenry.","whyWrongChoices":"Alternative options: Philippine Development Plan, Health for All Agenda of DOH, Ambisyon Natin 2040"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the philippine plan of action for nutrition is integrated and/or consistent with the following except::::', 'the philippine plan of action for nutrition is integrated and/or consistent with the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Philippine Plan of Action for Nutrition (PPAN) serves as the country’s comprehensive multi-sectoral framework designed to combat all forms of malnutrition. It is systematically aligned with, and anchored into, the following major national development strategies:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Philippine Environmental Plan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Philippine Plan of Action for Nutrition (PPAN) serves as the country’s comprehensive multi-sectoral framework designed to combat all forms of malnutrition. It is systematically aligned with, and anchored into, the following major national development strategies:\n\n• Philippine Development Plan (PDP): It is an integral sub-component of the national Philippine Development Plan framework, directly contributing to social transformation, human development, and poverty reduction goals.\n• Health for All Agenda of the DOH: It directly supports the Department of Health’s principal universal healthcare blueprints (such as the National Objectives for Health and its respective action agendas).\n• Ambisyon Natin 2040: It explicitly serves as an operational mechanism to meet the long-term vision of Ambisyon Natin 2040 by ensuring a healthy, well-nourished, and highly productive citizenry.","whyWrongChoices":"Alternative options: Philippine Development Plan, Health for All Agenda of DOH, Ambisyon Natin 2040"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the national dietary supplement program targets the following age groups except::::infants 0-5 months', 'the national dietary supplement program targets the following age groups except:', 'Infants 0-5 months', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The National Dietary Supplementation Program (NDSP)—including its banner strategy Tutok Kainan—deliberately excludes infants 0 to 5 months old from receiving solid food or dietary supplements. According to global and local healthcare standards, infants in this age bracket must practice strict exclusive breastfeeding; introducing any form of dietary supplementation or complementary food would disrupt this and increase the risk of infection.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Infants 0-5 months\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The National Dietary Supplementation Program (NDSP)—including its banner strategy Tutok Kainan—deliberately excludes infants 0 to 5 months old from receiving solid food or dietary supplements. According to global and local healthcare standards, infants in this age bracket must practice strict exclusive breastfeeding; introducing any form of dietary supplementation or complementary food would disrupt this and increase the risk of infection.\n\nTargeted Vulnerable Groups Under the NDSP:\n• Pregnant women (especially those classified as nutritionally at-risk, provided food support for 90 days).\n• Young children 6 to 59 months old (broken down into infants/toddlers aged 6–23 months for complementary feeding, and children aged 24–59 months).\n• School children (specifically severely wasted or wasted kindergarten to Grade 6 students enrolled in public schools).","whyWrongChoices":"Alternative options: Young children 6-59 months old, School children, Pregnant women"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute the calories provided by a 2-l dialysate solution containing 2.5% dextrose.:::', 'compute the calories provided by a 2-l dialysate solution containing 2.5% dextrose.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A 2.5% dextrose solution contains 2.5 g of dextrose per 100 mL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"170 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A 2.5% dextrose solution contains 2.5 g of dextrose per 100 mL.\n\nFor 2 L (2,000 mL):\n2.5 g/100 mL × 2,000 mL = 50 g dextrose\n\nDextrose provides approximately 3.4 kcal/g\n50 g × 3.4 kcal/g = 170 kcal\n\nTherefore, the dialysate provides approximately 170 kcal.","whyWrongChoices":"Alternative options: 108 kcal, 148 kcal, 200 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mobilization of lgus; policy development for food and nutrition; and strengthened management support are known as . these are necessary for the implementation of ppan.:::enabling programs', 'mobilization of lgus; policy development for food and nutrition; and strengthened management support are known as . these are necessary for the implementation of ppan.', 'Enabling programs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under the Philippine Plan of Action for Nutrition (PPAN) framework managed by the National Nutrition Council (NNC), these three components are specifically classified as enabling support programs:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Enabling programs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under the Philippine Plan of Action for Nutrition (PPAN) framework managed by the National Nutrition Council (NNC), these three components are specifically classified as enabling support programs:\n\n1. Mobilization of LGUs for nutritional outcomes\n2. Policy development for food and nutrition\n3. Strengthened management support\n\nThese programs are designated to ensure that both nutrition-specific and nutrition-sensitive interventions are well-coordinated and effectively implemented across all local government levels.","whyWrongChoices":"Alternative options: Nutrition advocacy, Support services, Facilitating initiatives"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mobilization of lgus; policy development for food and nutrition; and strengthened management support are known as . these are necessary for the implementation of ppan.:::', 'mobilization of lgus; policy development for food and nutrition; and strengthened management support are known as . these are necessary for the implementation of ppan.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under the Philippine Plan of Action for Nutrition (PPAN) framework managed by the National Nutrition Council (NNC), these three components are specifically classified as enabling support programs:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Enabling programs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under the Philippine Plan of Action for Nutrition (PPAN) framework managed by the National Nutrition Council (NNC), these three components are specifically classified as enabling support programs:\n\n1. Mobilization of LGUs for nutritional outcomes\n2. Policy development for food and nutrition\n3. Strengthened management support\n\nThese programs are designated to ensure that both nutrition-specific and nutrition-sensitive interventions are well-coordinated and effectively implemented across all local government levels.","whyWrongChoices":"Alternative options: Nutrition advocacy, Support services, Facilitating initiatives"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is known as participatory planning that involves local leaders, implementers and people themselves in planning the program.:::joint planning', 'it is known as participatory planning that involves local leaders, implementers and people themselves in planning the program.', 'Joint planning', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In program planning and management (particularly within nutrition and public health frameworks), Joint planning is explicitly defined as a type of participatory planning. It acts as a hybrid approach that combines elements of both top-down and bottom-up planning strategies. This method ensures comprehensive collaboration by actively involving local leaders, the implementers, and the target beneficiaries (the people themselves) directly in the program design.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Joint planning\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In program planning and management (particularly within nutrition and public health frameworks), Joint planning is explicitly defined as a type of participatory planning. It acts as a hybrid approach that combines elements of both top-down and bottom-up planning strategies. This method ensures comprehensive collaboration by actively involving local leaders, the implementers, and the target beneficiaries (the people themselves) directly in the program design.\n\n• Microlevel planning: This refers strictly to planning conducted at the localized, community, or grass-roots level (such as creating a specific barangay or municipal nutrition plan).\n• Strategic planning: This is a systematic process of mapping out a long-term vision, transforming that vision into broadly-defined strategic goals, and determining the sequential steps needed to achieve them.\n• Food and nutrition planning: This is the overarching thematic discipline focused on formulating national policies, interventions, and guidelines to combat malnutrition and ensure food security.","whyWrongChoices":"Alternative options: Food and nutrition planning, Strategic planning, Microlevel planning"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is known as participatory planning that involves local leaders, implementers and people themselves in planning the program.:::', 'it is known as participatory planning that involves local leaders, implementers and people themselves in planning the program.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In program planning and management (particularly within nutrition and public health frameworks), Joint planning is explicitly defined as a type of participatory planning. It acts as a hybrid approach that combines elements of both top-down and bottom-up planning strategies. This method ensures comprehensive collaboration by actively involving local leaders, the implementers, and the target beneficiaries (the people themselves) directly in the program design.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Joint planning\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In program planning and management (particularly within nutrition and public health frameworks), Joint planning is explicitly defined as a type of participatory planning. It acts as a hybrid approach that combines elements of both top-down and bottom-up planning strategies. This method ensures comprehensive collaboration by actively involving local leaders, the implementers, and the target beneficiaries (the people themselves) directly in the program design.\n\n• Microlevel planning: This refers strictly to planning conducted at the localized, community, or grass-roots level (such as creating a specific barangay or municipal nutrition plan).\n• Strategic planning: This is a systematic process of mapping out a long-term vision, transforming that vision into broadly-defined strategic goals, and determining the sequential steps needed to achieve them.\n• Food and nutrition planning: This is the overarching thematic discipline focused on formulating national policies, interventions, and guidelines to combat malnutrition and ensure food security.","whyWrongChoices":"Alternative options: Food and nutrition planning, Strategic planning, Microlevel planning"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the effortless expulsion of gastric contents caused by gi reflux in babies:::regurgitation', 'the effortless expulsion of gastric contents caused by gi reflux in babies', 'Regurgitation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Regurgitation is clinically defined as the effortless, passive expulsion of swallowed food or gastric contents from the stomach back into the esophagus and mouth. In infants, this is primarily driven by an immature lower esophageal sphincter—a common, normal condition known as gastroesophageal reflux (GER) that usually resolves on its own as the baby grows.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Regurgitation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Regurgitation is clinically defined as the effortless, passive expulsion of swallowed food or gastric contents from the stomach back into the esophagus and mouth. In infants, this is primarily driven by an immature lower esophageal sphincter—a common, normal condition known as gastroesophageal reflux (GER) that usually resolves on its own as the baby grows.\n\n• Colic: This refers to periods of intense, frequent, and unexplained crying in an otherwise healthy infant, often thought to be linked to gas or abdominal discomfort, rather than the physical ejection of stomach contents.\n• Diarrhea: This describes loose, watery stools passing through the lower gastrointestinal tract, not an upward reflux into the mouth.\n• Spitting-up-food: While this is the casual, everyday term parents use for this exact behavior, Regurgitation is the primary scientific and medical terminology used in public health exams to describe the involuntary mechanism itself.","whyWrongChoices":"Alternative options: Colic, Spitting-up-food, Diarrhea"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a principle in planning that refers to desired breadth and depth of the nutrition program.:::comprehensiveness', 'a principle in planning that refers to desired breadth and depth of the nutrition program.', 'Comprehensiveness', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Comprehensiveness is a core principle in nutrition program planning and management. It explicitly dictates that the desired breadth and depth of whatever has been selected as the overall scope of the program or project must be thoroughly and accurately reflected in the actual plan.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Comprehensiveness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Comprehensiveness is a core principle in nutrition program planning and management. It explicitly dictates that the desired breadth and depth of whatever has been selected as the overall scope of the program or project must be thoroughly and accurately reflected in the actual plan.\n\n• Balance: Emphasizes that all specific activities, tasks, and resource allocations are properly distributed so that they directly contribute to the achievement of the program''s objectives.\n• Workability: Mandates that the plan must be operationally practical, meaning the objectives are completely realistic and achievable within the set timeframe and available resources.\n• Appropriateness: Refers to how well the designed program fits the localized cultural, environmental, and socio-economic context of the target community.","whyWrongChoices":"Alternative options: Balance, Workability, Appropriateness"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a principle in planning that refers to desired breadth and depth of the nutrition program.:::', 'a principle in planning that refers to desired breadth and depth of the nutrition program.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Comprehensiveness is a core principle in nutrition program planning and management. It explicitly dictates that the desired breadth and depth of whatever has been selected as the overall scope of the program or project must be thoroughly and accurately reflected in the actual plan.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Comprehensiveness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Comprehensiveness is a core principle in nutrition program planning and management. It explicitly dictates that the desired breadth and depth of whatever has been selected as the overall scope of the program or project must be thoroughly and accurately reflected in the actual plan.\n\n• Balance: Emphasizes that all specific activities, tasks, and resource allocations are properly distributed so that they directly contribute to the achievement of the program''s objectives.\n• Workability: Mandates that the plan must be operationally practical, meaning the objectives are completely realistic and achievable within the set timeframe and available resources.\n• Appropriateness: Refers to how well the designed program fits the localized cultural, environmental, and socio-economic context of the target community.","whyWrongChoices":"Alternative options: Balance, Workability, Appropriateness"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following is/are true for problem matrix, causal model, or problem tree except::::formulated by the bns and presented to lce as an advocacy tool', 'the following is/are true for problem matrix, causal model, or problem tree except:', 'Formulated by the BNS and presented to LCE as an advocacy tool', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Formulating a problem tree, causal model, or problem matrix is not a task done individually by the Barangay Nutrition Scholar (BNS). According to local nutrition planning guidelines, it requires collective brainstorming and data analysis from the entire members of the Local Nutrition Committee (LNC) during their strategic planning meetings. The entire plan (not just the tree) is what is eventually packaged and presented to the Local Chief Executive (LCE) for adoption and funding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Formulated by the BNS and presented to LCE as an advocacy tool\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Formulating a problem tree, causal model, or problem matrix is not a task done individually by the Barangay Nutrition Scholar (BNS). According to local nutrition planning guidelines, it requires collective brainstorming and data analysis from the entire members of the Local Nutrition Committee (LNC) during their strategic planning meetings. The entire plan (not just the tree) is what is eventually packaged and presented to the Local Chief Executive (LCE) for adoption and funding.","whyWrongChoices":"Alternative options: Trace the chain of factors that can affect nutrition situation, Constructed by asking and answering a series of \"whys\" to understand better the factors, Being updated every year as a result of new data on nutrition situation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the anabolic formation of triacyglycerol from glycerol and fatty acids.:::lipogenesis', 'it refers to the anabolic formation of triacyglycerol from glycerol and fatty acids.', 'Lipogenesis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lipogenesis refers broadly to the formation and storage of fat, including the synthesis of triacylglycerol (TAG) from glycerol-derived molecules and fatty acids. It occurs primarily when energy intake exceeds immediate energy needs, allowing excess energy to be stored as body fat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lipogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lipogenesis refers broadly to the formation and storage of fat, including the synthesis of triacylglycerol (TAG) from glycerol-derived molecules and fatty acids. It occurs primarily when energy intake exceeds immediate energy needs, allowing excess energy to be stored as body fat.","whyWrongChoices":"Alternative options: Fatty acid synthesis, Cholesterol synthesis, Gluconeogenesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:taters refer to::::potatoes', 'taters refer to:', 'Potatoes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"\"Taters\" is a casual, colloquial slang term derived from the word \"potatoes\" (commonly used in phrases like tater tots or mashed taters).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Potatoes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"\"Taters\" is a casual, colloquial slang term derived from the word \"potatoes\" (commonly used in phrases like tater tots or mashed taters).","whyWrongChoices":"Alternative options: Chips, Popcorn, Shrimp"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following is/are true for problem matrix, causal model, or problem tree except::::', 'the following is/are true for problem matrix, causal model, or problem tree except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Formulating a problem tree, causal model, or problem matrix is not a task done individually by the Barangay Nutrition Scholar (BNS). According to local nutrition planning guidelines, it requires collective brainstorming and data analysis from the entire members of the Local Nutrition Committee (LNC) during their strategic planning meetings. The entire plan (not just the tree) is what is eventually packaged and presented to the Local Chief Executive (LCE) for adoption and funding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Formulated by the BNS and presented to LCE as an advocacy tool\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Formulating a problem tree, causal model, or problem matrix is not a task done individually by the Barangay Nutrition Scholar (BNS). According to local nutrition planning guidelines, it requires collective brainstorming and data analysis from the entire members of the Local Nutrition Committee (LNC) during their strategic planning meetings. The entire plan (not just the tree) is what is eventually packaged and presented to the Local Chief Executive (LCE) for adoption and funding.","whyWrongChoices":"Alternative options: Trace the chain of factors that can affect nutrition situation, Constructed by asking and answering a series of \"whys\" to understand better the factors, Being updated every year as a result of new data on nutrition situation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to concrete and specific statement of desired achievement. it is more focused and specific time dimension, client population and end results.:::objectives', 'it refers to concrete and specific statement of desired achievement. it is more focused and specific time dimension, client population and end results.', 'Objectives', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In program planning and strategic management, objectives are defined as concrete, precise, and short-term statements of desired achievement. Unlike broad statements, an objective is specifically written to outline:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Objectives\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In program planning and strategic management, objectives are defined as concrete, precise, and short-term statements of desired achievement. Unlike broad statements, an objective is specifically written to outline:\n• A defined client population (who will benefit)\n• A strict time dimension (when it will be achieved)\n• Explicit, measurable end results (what the exact target is)\n\n• Goals: These are broad, long-range, and general statements of an overall vision (e.g., \"To reduce the prevalence of malnutrition in the region\"), but they lack the operational and highly focused parameters of an objective.\n• Mission: This explains the primary motivation, fundamental beliefs, and the overall reason for the organization''s existence.\n• Vision: This is an aspirational, long-term description of a desired future state.","whyWrongChoices":"Alternative options: Vision, Mission, Goals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to concrete and specific statement of desired achievement. it is more focused and specific time dimension, client population and end results.:::', 'it refers to concrete and specific statement of desired achievement. it is more focused and specific time dimension, client population and end results.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In program planning and strategic management, objectives are defined as concrete, precise, and short-term statements of desired achievement. Unlike broad statements, an objective is specifically written to outline:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Objectives\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In program planning and strategic management, objectives are defined as concrete, precise, and short-term statements of desired achievement. Unlike broad statements, an objective is specifically written to outline:\n• A defined client population (who will benefit)\n• A strict time dimension (when it will be achieved)\n• Explicit, measurable end results (what the exact target is)\n\n• Goals: These are broad, long-range, and general statements of an overall vision (e.g., \"To reduce the prevalence of malnutrition in the region\"), but they lack the operational and highly focused parameters of an objective.\n• Mission: This explains the primary motivation, fundamental beliefs, and the overall reason for the organization''s existence.\n• Vision: This is an aspirational, long-term description of a desired future state.","whyWrongChoices":"Alternative options: Vision, Mission, Goals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:among the criteria in selecting nutrition intervention, the following must not be missed::::relevance, feasibiltiy, effectiveness', 'among the criteria in selecting nutrition intervention, the following must not be missed:', 'Relevance, feasibiltiy, effectiveness', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In classical program management and nutrition planning frameworks (such as those taught by FAO and the National Nutrition Council), interventions must pass three fundamental, non-negotiable filters during the screening phase:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Relevance, feasibiltiy, effectiveness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In classical program management and nutrition planning frameworks (such as those taught by FAO and the National Nutrition Council), interventions must pass three fundamental, non-negotiable filters during the screening phase:\n\n1. Relevance (Appropriateness): Does the intervention directly solve the specific, prioritized nutrition problem of that population? (e.g., if the problem is Vitamin A deficiency, the intervention must be Vitamin A supplementation or food fortification, not general sanitation).\n2. Feasibility (Practicability): Can it actually be done given the available budget, technical expertise, administrative infrastructure, and time constraints?\n3. Effectiveness (Impact): Is there proven scientific or empirical evidence that this specific strategy will successfully lower malnutrition rates or improve the target nutritional indicators?","whyWrongChoices":"Alternative options: Relevance, feasibility, ease in targeting and evaluation, Relevance, feasibility, cost-effectiveness, Relevance, feasibility, political support, willingness of beneficiaries to participate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:among the criteria in selecting nutrition intervention, the following must not be missed::::', 'among the criteria in selecting nutrition intervention, the following must not be missed:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In classical program management and nutrition planning frameworks (such as those taught by FAO and the National Nutrition Council), interventions must pass three fundamental, non-negotiable filters during the screening phase:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Relevance, feasibiltiy, effectiveness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In classical program management and nutrition planning frameworks (such as those taught by FAO and the National Nutrition Council), interventions must pass three fundamental, non-negotiable filters during the screening phase:\n\n1. Relevance (Appropriateness): Does the intervention directly solve the specific, prioritized nutrition problem of that population? (e.g., if the problem is Vitamin A deficiency, the intervention must be Vitamin A supplementation or food fortification, not general sanitation).\n2. Feasibility (Practicability): Can it actually be done given the available budget, technical expertise, administrative infrastructure, and time constraints?\n3. Effectiveness (Impact): Is there proven scientific or empirical evidence that this specific strategy will successfully lower malnutrition rates or improve the target nutritional indicators?","whyWrongChoices":"Alternative options: Relevance, feasibility, ease in targeting and evaluation, Relevance, feasibility, cost-effectiveness, Relevance, feasibility, political support, willingness of beneficiaries to participate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pre-program evaluation carried out prior to implementation but after program formulation. it is necessary to reassess development needs and project feasibility.:::ex-ante evaluation', 'pre-program evaluation carried out prior to implementation but after program formulation. it is necessary to reassess development needs and project feasibility.', 'Ex-ante evaluation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ex-ante evaluation (literally meaning \"before the event\" in Latin) is a pre-program evaluation conducted after the program has been formulated but before actual implementation begins. Its primary purpose is to critically re-assess the localized development needs and rigorously audit the overall project feasibility and design viability before resources are officially spent.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ex-ante evaluation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ex-ante evaluation (literally meaning \"before the event\" in Latin) is a pre-program evaluation conducted after the program has been formulated but before actual implementation begins. Its primary purpose is to critically re-assess the localized development needs and rigorously audit the overall project feasibility and design viability before resources are officially spent.\n\n• Program implementation review / Mid-term evaluation: These are ongoing, formative evaluations conducted during the execution phase of the project to check progress and implement corrective adjustments.\n• Ex-post evaluation: This is an summative evaluation conducted at the very end or after the completion of the implementation stage to assess the total impact and outcomes.","whyWrongChoices":"Alternative options: Ex-post evaluation, Mid-term evaluation, Program implementation review"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pre-program evaluation carried out prior to implementation but after program formulation. it is necessary to reassess development needs and project feasibility.:::', 'pre-program evaluation carried out prior to implementation but after program formulation. it is necessary to reassess development needs and project feasibility.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ex-ante evaluation (literally meaning \"before the event\" in Latin) is a pre-program evaluation conducted after the program has been formulated but before actual implementation begins. Its primary purpose is to critically re-assess the localized development needs and rigorously audit the overall project feasibility and design viability before resources are officially spent.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ex-ante evaluation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ex-ante evaluation (literally meaning \"before the event\" in Latin) is a pre-program evaluation conducted after the program has been formulated but before actual implementation begins. Its primary purpose is to critically re-assess the localized development needs and rigorously audit the overall project feasibility and design viability before resources are officially spent.\n\n• Program implementation review / Mid-term evaluation: These are ongoing, formative evaluations conducted during the execution phase of the project to check progress and implement corrective adjustments.\n• Ex-post evaluation: This is an summative evaluation conducted at the very end or after the completion of the implementation stage to assess the total impact and outcomes.","whyWrongChoices":"Alternative options: Ex-post evaluation, Mid-term evaluation, Program implementation review"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food availability at the national level is not enough to provide food security for all households. moreover, food security at the national and household level does not automatically result to good nutritional status of an individual.:::both statements are true', 'food availability at the national level is not enough to provide food security for all households. moreover, food security at the national and household level does not automatically result to good nutritional status of an individual.', 'Both statements are true', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement 1 is true: Food availability at the national level (e.g., high national agricultural yields or food imports) speaks only to supply. It does not ensure food security for all households because of barriers to food access (such as low purchasing power, poverty, or poor market distribution systems).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are true\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement 1 is true: Food availability at the national level (e.g., high national agricultural yields or food imports) speaks only to supply. It does not ensure food security for all households because of barriers to food access (such as low purchasing power, poverty, or poor market distribution systems).\n\nStatement 2 is true: Even if a household is fully food secure and has plenty of food on the table, it does not guarantee that every individual in that house will achieve an optimal nutritional status. This is because individual nutritional status depends heavily on food utilization (how the body absorbs nutrients, which can be ruined by infections or illness), intra-household food distribution (e.g., gender or age disparities in who eats first), and caregiving practices.","whyWrongChoices":"Alternative options: Only the first statement is true, Only the second statement is true, Both statements are false"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the focus of the sustainable development goal #2:::', 'it is the focus of the sustainable development goal #2', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The United Nations Sustainable Development Goals (SDGs) are a blueprint of 17 global goals to build a better future. SDG #2 focuses directly on ending hunger, achieving food security, improving nutrition, and promoting sustainable agriculture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hunger and malnutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The United Nations Sustainable Development Goals (SDGs) are a blueprint of 17 global goals to build a better future. SDG #2 focuses directly on ending hunger, achieving food security, improving nutrition, and promoting sustainable agriculture.\n\n• Health: This is SDG #3 (Good Health and Well-being).\n• Access to clean water and sanitation: This is SDG #6 (Clean Water and Sanitation).\n• Responsible production and consumption: This is SDG #12 (Responsible Consumption and Production).","whyWrongChoices":"Alternative options: Health, Access to clean water and sanitation, Responsible production and consumption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food availability at the national level is not enough to provide food security for all households. moreover, food security at the national and household level does not automatically result to good nutritional status of an individual.:::', 'food availability at the national level is not enough to provide food security for all households. moreover, food security at the national and household level does not automatically result to good nutritional status of an individual.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement 1 is true: Food availability at the national level (e.g., high national agricultural yields or food imports) speaks only to supply. It does not ensure food security for all households because of barriers to food access (such as low purchasing power, poverty, or poor market distribution systems).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are true\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement 1 is true: Food availability at the national level (e.g., high national agricultural yields or food imports) speaks only to supply. It does not ensure food security for all households because of barriers to food access (such as low purchasing power, poverty, or poor market distribution systems).\n\nStatement 2 is true: Even if a household is fully food secure and has plenty of food on the table, it does not guarantee that every individual in that house will achieve an optimal nutritional status. This is because individual nutritional status depends heavily on food utilization (how the body absorbs nutrients, which can be ruined by infections or illness), intra-household food distribution (e.g., gender or age disparities in who eats first), and caregiving practices.","whyWrongChoices":"Alternative options: Only the first statement is true, Only the second statement is true, Both statements are false"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:understanding the ecology of food and nutrition helps in the identification of the root causes of malnutrition problem. it can also help identifying appropriate solutions.:::both statements are true', 'understanding the ecology of food and nutrition helps in the identification of the root causes of malnutrition problem. it can also help identifying appropriate solutions.', 'Both statements are true', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The first statement is true: The \"ecology of food and nutrition\" refers to the interaction between humans and the environmental, socio-economic, cultural, and political factors that dictate food availability, access, and biological utilization. Understanding this web helps investigators trace how systemic basic causes (like climate or policy) trickle down to underlying causes (like poor sanitation) and immediate causes (like inadequate dietary intake).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are true\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The first statement is true: The \"ecology of food and nutrition\" refers to the interaction between humans and the environmental, socio-economic, cultural, and political factors that dictate food availability, access, and biological utilization. Understanding this web helps investigators trace how systemic basic causes (like climate or policy) trickle down to underlying causes (like poor sanitation) and immediate causes (like inadequate dietary intake).\n\nThe second statement is true: By mapping out these exact ecological pathways, program planners can easily identify where a system is failing and design appropriate, targeted solutions—such as pairing nutrition-specific medical interventions with long-term, nutrition-sensitive agricultural or water security reforms.","whyWrongChoices":"Alternative options: Only the first statement is true, Only the second statement is true, Both statements are false"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:understanding the ecology of food and nutrition helps in the identification of the root causes of malnutrition problem. it can also help identifying appropriate solutions.:::', 'understanding the ecology of food and nutrition helps in the identification of the root causes of malnutrition problem. it can also help identifying appropriate solutions.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The first statement is true: The \"ecology of food and nutrition\" refers to the interaction between humans and the environmental, socio-economic, cultural, and political factors that dictate food availability, access, and biological utilization. Understanding this web helps investigators trace how systemic basic causes (like climate or policy) trickle down to underlying causes (like poor sanitation) and immediate causes (like inadequate dietary intake).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are true\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The first statement is true: The \"ecology of food and nutrition\" refers to the interaction between humans and the environmental, socio-economic, cultural, and political factors that dictate food availability, access, and biological utilization. Understanding this web helps investigators trace how systemic basic causes (like climate or policy) trickle down to underlying causes (like poor sanitation) and immediate causes (like inadequate dietary intake).\n\nThe second statement is true: By mapping out these exact ecological pathways, program planners can easily identify where a system is failing and design appropriate, targeted solutions—such as pairing nutrition-specific medical interventions with long-term, nutrition-sensitive agricultural or water security reforms.","whyWrongChoices":"Alternative options: Only the first statement is true, Only the second statement is true, Both statements are false"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a condition in which people do not get enough food to provide nutrients for the body.:::hunger', 'it is a condition in which people do not get enough food to provide nutrients for the body.', 'Hunger', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In public health and food security frameworks, hunger is defined as an individual-level physiological condition where a person does not have access to enough food to provide the essential nutrients and dietary energy their body needs to function normally.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hunger\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In public health and food security frameworks, hunger is defined as an individual-level physiological condition where a person does not have access to enough food to provide the essential nutrients and dietary energy their body needs to function normally.\n\n• Food and nutrition security: This is a comprehensive, positive state where all people at all times have physical, social, and economic access to sufficient, safe, and nutritious food to meet their dietary needs for an active and healthy life.\n• Malaise: This is a general, non-specific medical term describing a vague feeling of bodily discomfort, illness, uneasiness, or lack of energy.\n• Food security: This focuses primarily on the broad availability, access, and stability of food supplies at the household or community level, rather than the specific physical condition of lacking food nutrients.","whyWrongChoices":"Alternative options: Food and nutrition security, Food security, Malaise"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the mandatory food fortification program, cooking oil is fortified with::::', 'under the mandatory food fortification program, cooking oil is fortified with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A – oil, sugar\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Iron, Iodine, Vit A and Iron"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a condition in which people do not get enough food to provide nutrients for the body.:::', 'it is a condition in which people do not get enough food to provide nutrients for the body.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In public health and food security frameworks, hunger is defined as an individual-level physiological condition where a person does not have access to enough food to provide the essential nutrients and dietary energy their body needs to function normally.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hunger\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In public health and food security frameworks, hunger is defined as an individual-level physiological condition where a person does not have access to enough food to provide the essential nutrients and dietary energy their body needs to function normally.\n\n• Food and nutrition security: This is a comprehensive, positive state where all people at all times have physical, social, and economic access to sufficient, safe, and nutritious food to meet their dietary needs for an active and healthy life.\n• Malaise: This is a general, non-specific medical term describing a vague feeling of bodily discomfort, illness, uneasiness, or lack of energy.\n• Food security: This focuses primarily on the broad availability, access, and stability of food supplies at the household or community level, rather than the specific physical condition of lacking food nutrients.","whyWrongChoices":"Alternative options: Food and nutrition security, Food security, Malaise"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are possible causes of transitory food insecurity except::::lack of food storage', 'all of the following are possible causes of transitory food insecurity except:', 'Lack of food storage', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Transitory food insecurity is defined as a short-term, temporary, or sudden drop in the ability to produce or access enough food. It is typically triggered by unpredictable external shocks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lack of food storage\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Transitory food insecurity is defined as a short-term, temporary, or sudden drop in the ability to produce or access enough food. It is typically triggered by unpredictable external shocks.\n\nDroughts and floods are classic examples of acute environmental shocks that cause immediate, temporary food shortages. The lean season represents a cyclical, temporary phase between planting and harvesting where food supplies naturally drop for a limited period.\n\nA lack of food storage, on the other hand, is a structural and systemic infrastructural deficiency. Because it is a permanent condition deeply embedded in a region''s agricultural infrastructure, it serves as a core driver of chronic food insecurity rather than a temporary or passing shock.","whyWrongChoices":"Alternative options: Lean season, Drought, Floods"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are possible causes of transitory food insecurity except::::', 'all of the following are possible causes of transitory food insecurity except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Transitory food insecurity is defined as a short-term, temporary, or sudden drop in the ability to produce or access enough food. It is typically triggered by unpredictable external shocks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lack of food storage\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Transitory food insecurity is defined as a short-term, temporary, or sudden drop in the ability to produce or access enough food. It is typically triggered by unpredictable external shocks.\n\nDroughts and floods are classic examples of acute environmental shocks that cause immediate, temporary food shortages. The lean season represents a cyclical, temporary phase between planting and harvesting where food supplies naturally drop for a limited period.\n\nA lack of food storage, on the other hand, is a structural and systemic infrastructural deficiency. Because it is a permanent condition deeply embedded in a region''s agricultural infrastructure, it serves as a core driver of chronic food insecurity rather than a temporary or passing shock.","whyWrongChoices":"Alternative options: Lean season, Drought, Floods"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the focus of the sustainable development goal #2:::hunger and malnutrition', 'it is the focus of the sustainable development goal #2', 'Hunger and malnutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The United Nations Sustainable Development Goals (SDGs) are a blueprint of 17 global goals to build a better future. SDG #2 focuses directly on ending hunger, achieving food security, improving nutrition, and promoting sustainable agriculture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hunger and malnutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The United Nations Sustainable Development Goals (SDGs) are a blueprint of 17 global goals to build a better future. SDG #2 focuses directly on ending hunger, achieving food security, improving nutrition, and promoting sustainable agriculture.\n\n• Health: This is SDG #3 (Good Health and Well-being).\n• Access to clean water and sanitation: This is SDG #6 (Clean Water and Sanitation).\n• Responsible production and consumption: This is SDG #12 (Responsible Consumption and Production).","whyWrongChoices":"Alternative options: Health, Access to clean water and sanitation, Responsible production and consumption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient on tube feeding has a diet rx of 2000 calories, 2:1 dilution; how much is the total fluid.:::', 'a patient on tube feeding has a diet rx of 2000 calories, 2:1 dilution; how much is the total fluid.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the traditional tube-feeding prescription, a 2:1 dilution means 2 kcal for every 1 mL of formula. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1000 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the traditional tube-feeding prescription, a 2:1 dilution means 2 kcal for every 1 mL of formula. \n\nTherefore: 2,000 kcal ÷ 2 kcal/mL = 1,000 mL/day\n\nThus, the total volume of tube-feeding formula prescribed is 1,000 mL/day.","whyWrongChoices":"Alternative options: 1500 ml, 1250 ml, 2250 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following provides information on annual food production, distribution of food within the country, and imports and exports?:::food balance sheets', 'which of the following provides information on annual food production, distribution of food within the country, and imports and exports?', 'Food balance sheets', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A Food Balance Sheet (FBS) is a comprehensive macro-level statistical report compiled annually (often by national agencies like the Philippine Statistics Authority and globally by the Food and Agriculture Organization) to track a country''s total food supply and utilization over a specific timeframe.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food balance sheets\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A Food Balance Sheet (FBS) is a comprehensive macro-level statistical report compiled annually (often by national agencies like the Philippine Statistics Authority and globally by the Food and Agriculture Organization) to track a country''s total food supply and utilization over a specific timeframe.\n\nIt specifically synthesizes three critical dimensions of data:\n1. Annual Food Production: The total quantity of food commodities cultivated domestically.\n2. Imports and Exports: The flow of food moving into and out of the country''s borders to calculate net available supply.\n3. Distribution/Utilization: How the total available food is split within the country across human consumption, livestock feed, seed use, manufacturing, and structural waste.\n\n• Commercial market databases: These track private consumer buying trends, brand performance, and retail sales, rather than integrated national agricultural and border trade balances.\n• Food records: This is an individual-level dietary assessment method where a single person logs their personal daily intake, which tells you nothing about nationwide trade or agricultural production.","whyWrongChoices":"Alternative options: Food records, Commercial market databases, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following provides information on annual food production, distribution of food within the country, and imports and exports?:::', 'which of the following provides information on annual food production, distribution of food within the country, and imports and exports?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A Food Balance Sheet (FBS) is a comprehensive macro-level statistical report compiled annually (often by national agencies like the Philippine Statistics Authority and globally by the Food and Agriculture Organization) to track a country''s total food supply and utilization over a specific timeframe.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food balance sheets\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A Food Balance Sheet (FBS) is a comprehensive macro-level statistical report compiled annually (often by national agencies like the Philippine Statistics Authority and globally by the Food and Agriculture Organization) to track a country''s total food supply and utilization over a specific timeframe.\n\nIt specifically synthesizes three critical dimensions of data:\n1. Annual Food Production: The total quantity of food commodities cultivated domestically.\n2. Imports and Exports: The flow of food moving into and out of the country''s borders to calculate net available supply.\n3. Distribution/Utilization: How the total available food is split within the country across human consumption, livestock feed, seed use, manufacturing, and structural waste.\n\n• Commercial market databases: These track private consumer buying trends, brand performance, and retail sales, rather than integrated national agricultural and border trade balances.\n• Food records: This is an individual-level dietary assessment method where a single person logs their personal daily intake, which tells you nothing about nationwide trade or agricultural production.","whyWrongChoices":"Alternative options: Food records, Commercial market databases, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:based on who cut-off points, a bmi of 27 is considered to be which of the following?:::overweight', 'based on who cut-off points, a bmi of 27 is considered to be which of the following?', 'Overweight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"WHO Standard Adult BMI Reference Ranges","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overweight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"WHO Standard Adult BMI Reference Ranges\n\nThe international classification breaks down weight status according to these specific metric boundaries:\n• Underweight: BMI less than 18.5\n• Normal weight: BMI of 18.5 to 24.9\n• Overweight: BMI of 25.0 to 29.9 (A BMI of 27 falls directly in this bracket)\n• Obese: BMI of 30.0 or higher","whyWrongChoices":"Alternative options: Underweight, Normal weight, Obese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:based on who cut-off points, a bmi of 27 is considered to be which of the following?:::', 'based on who cut-off points, a bmi of 27 is considered to be which of the following?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"WHO Standard Adult BMI Reference Ranges","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overweight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"WHO Standard Adult BMI Reference Ranges\n\nThe international classification breaks down weight status according to these specific metric boundaries:\n• Underweight: BMI less than 18.5\n• Normal weight: BMI of 18.5 to 24.9\n• Overweight: BMI of 25.0 to 29.9 (A BMI of 27 falls directly in this bracket)\n• Obese: BMI of 30.0 or higher","whyWrongChoices":"Alternative options: Underweight, Normal weight, Obese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:abdominal obesity in females is defined as a waist–hip ratio greater than::::0.85', 'abdominal obesity in females is defined as a waist–hip ratio greater than:', '0.85', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the World Health Organization (WHO) diagnostic guidelines, abdominal obesity (also known as central or android obesity) is measured using specific cutoff thresholds for the waist–hip ratio (WHR):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.85\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the World Health Organization (WHO) diagnostic guidelines, abdominal obesity (also known as central or android obesity) is measured using specific cutoff thresholds for the waist–hip ratio (WHR):\n\n• Females: Abdominal obesity is defined as a waist–hip ratio greater than 0.85.\n• Males: Abdominal obesity is defined as a waist–hip ratio greater than 0.90.\n\nAny values exceeding these points indicate a high concentration of visceral fat around the abdominal organs, which is heavily associated with an elevated risk of developing type 2 diabetes, hypertension, and cardiovascular diseases.","whyWrongChoices":"Alternative options: 0.70, 0.95, 1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:abdominal obesity in females is defined as a waist–hip ratio greater than::::', 'abdominal obesity in females is defined as a waist–hip ratio greater than:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the World Health Organization (WHO) diagnostic guidelines, abdominal obesity (also known as central or android obesity) is measured using specific cutoff thresholds for the waist–hip ratio (WHR):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.85\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the World Health Organization (WHO) diagnostic guidelines, abdominal obesity (also known as central or android obesity) is measured using specific cutoff thresholds for the waist–hip ratio (WHR):\n\n• Females: Abdominal obesity is defined as a waist–hip ratio greater than 0.85.\n• Males: Abdominal obesity is defined as a waist–hip ratio greater than 0.90.\n\nAny values exceeding these points indicate a high concentration of visceral fat around the abdominal organs, which is heavily associated with an elevated risk of developing type 2 diabetes, hypertension, and cardiovascular diseases.","whyWrongChoices":"Alternative options: 0.70, 0.95, 1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which dietary assessment method determines nutrient intake by asking how often certain foods are consumed?:::food frequency', 'which dietary assessment method determines nutrient intake by asking how often certain foods are consumed?', 'Food frequency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By definition, a Food Frequency Questionnaire (FFQ) asks a participant to report how often (the rate or frequency, such as daily, weekly, or monthly) they consume specific items from a pre-defined checklist of foods over a designated timeframe.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food frequency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By definition, a Food Frequency Questionnaire (FFQ) asks a participant to report how often (the rate or frequency, such as daily, weekly, or monthly) they consume specific items from a pre-defined checklist of foods over a designated timeframe.\n\n• Diet history: This is an in-depth retrospective interview method that focuses on mapping out overall long-term habitual eating patterns, meal frequencies, cooking behaviors, and general food habits, rather than solely ticking off the frequencies of a structured food item checklist.\n• 24-hour recall: This method asks the participant to remember and describe all food and beverages consumed over the exact, immediate 24 hours prior to the interview. It looks at a single-day snapshot of consumption rather than the general frequency of specific items over time.","whyWrongChoices":"Alternative options: Diet history, 24-hour recall, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which dietary assessment method determines nutrient intake by asking how often certain foods are consumed?:::', 'which dietary assessment method determines nutrient intake by asking how often certain foods are consumed?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By definition, a Food Frequency Questionnaire (FFQ) asks a participant to report how often (the rate or frequency, such as daily, weekly, or monthly) they consume specific items from a pre-defined checklist of foods over a designated timeframe.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food frequency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By definition, a Food Frequency Questionnaire (FFQ) asks a participant to report how often (the rate or frequency, such as daily, weekly, or monthly) they consume specific items from a pre-defined checklist of foods over a designated timeframe.\n\n• Diet history: This is an in-depth retrospective interview method that focuses on mapping out overall long-term habitual eating patterns, meal frequencies, cooking behaviors, and general food habits, rather than solely ticking off the frequencies of a structured food item checklist.\n• 24-hour recall: This method asks the participant to remember and describe all food and beverages consumed over the exact, immediate 24 hours prior to the interview. It looks at a single-day snapshot of consumption rather than the general frequency of specific items over time.","whyWrongChoices":"Alternative options: Diet history, 24-hour recall, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the physical growth of an infant?:::the infant’s length changes more slowly than the weight', 'which is true about the physical growth of an infant?', 'The infant’s length changes more slowly than the weight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An infant''s birth weight typically doubles by about 4 to 6 months, not two months. It does triple by one year, but the first half of the statement is biologically inaccurate for normal infant development.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The infant’s length changes more slowly than the weight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An infant''s birth weight typically doubles by about 4 to 6 months, not two months. It does triple by one year, but the first half of the statement is biologically inaccurate for normal infant development.\n\nWeight changes much faster and more dynamically than height (linear growth). During the first year, an infant''s weight triples (a 200% increase), whereas their length increases by roughly 50% (from an average of 20 inches at birth to about 30 inches at one year). Linear growth is a more gradual, steady biological process compared to rapid mass accumulation.","whyWrongChoices":"Alternative options: Infants’ birth weight doubles by about two months and triples by one year, A and B are both TRUE, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a major component of gastric juice::::', 'a major component of gastric juice:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hydrochloric acid secretion is responsible for the strong acidic condition of the stomach. With such an acidic environment, ingested proteins are denaturized thus, facilitating their digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"HCI\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hydrochloric acid secretion is responsible for the strong acidic condition of the stomach. With such an acidic environment, ingested proteins are denaturized thus, facilitating their digestion.","whyWrongChoices":"Alternative options: Amylase, Hormones"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the physical growth of an infant?:::', 'which is true about the physical growth of an infant?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An infant''s birth weight typically doubles by about 4 to 6 months, not two months. It does triple by one year, but the first half of the statement is biologically inaccurate for normal infant development.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The infant’s length changes more slowly than the weight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An infant''s birth weight typically doubles by about 4 to 6 months, not two months. It does triple by one year, but the first half of the statement is biologically inaccurate for normal infant development.\n\nWeight changes much faster and more dynamically than height (linear growth). During the first year, an infant''s weight triples (a 200% increase), whereas their length increases by roughly 50% (from an average of 20 inches at birth to about 30 inches at one year). Linear growth is a more gradual, steady biological process compared to rapid mass accumulation.","whyWrongChoices":"Alternative options: Infants’ birth weight doubles by about two months and triples by one year, A and B are both TRUE, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an infant is physiologically ready for solid foods when::::all of the above', 'an infant is physiologically ready for solid foods when:', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An infant becomes developmentally and physiologically ready to transition to solid foods (complementary feeding) around 6 months of age, marked by several key internal changes:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An infant becomes developmentally and physiologically ready to transition to solid foods (complementary feeding) around 6 months of age, marked by several key internal changes:\n• Saliva is produced: Around 3 to 6 months, an infant’s salivary glands mature, significantly increasing saliva production. Saliva contains lubricants and enzymes that help moisten and break down solid textures.\n\n• Gastric acidity increases: A newborn''s stomach has a relatively high pH (less acidic). As the infant approaches 6 months, gastric acid production increases, lowering the stomach pH to adult-like levels. This is necessary to properly digest complex proteins from solid foods and kill harmful foodborne pathogens.\n• Enzymes for starch digestion are produced: During early infancy, levels of pancreatic amylase (the enzyme needed to digest complex starches) are very low. By 6 months of age, the secretion of these digestive enzymes matures significantly, allowing the infant''s GI tract to safely process and absorb starches from rice, cereals, and mashed root crops.","whyWrongChoices":"Alternative options: Saliva is produced, Gastric acidity increases, Enzymes for starch digestion is produced"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an infant is physiologically ready for solid foods when::::', 'an infant is physiologically ready for solid foods when:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An infant becomes developmentally and physiologically ready to transition to solid foods (complementary feeding) around 6 months of age, marked by several key internal changes:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An infant becomes developmentally and physiologically ready to transition to solid foods (complementary feeding) around 6 months of age, marked by several key internal changes:\n• Saliva is produced: Around 3 to 6 months, an infant’s salivary glands mature, significantly increasing saliva production. Saliva contains lubricants and enzymes that help moisten and break down solid textures.\n\n• Gastric acidity increases: A newborn''s stomach has a relatively high pH (less acidic). As the infant approaches 6 months, gastric acid production increases, lowering the stomach pH to adult-like levels. This is necessary to properly digest complex proteins from solid foods and kill harmful foodborne pathogens.\n• Enzymes for starch digestion are produced: During early infancy, levels of pancreatic amylase (the enzyme needed to digest complex starches) are very low. By 6 months of age, the secretion of these digestive enzymes matures significantly, allowing the infant''s GI tract to safely process and absorb starches from rice, cereals, and mashed root crops.","whyWrongChoices":"Alternative options: Saliva is produced, Gastric acidity increases, Enzymes for starch digestion is produced"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the basal metabolic of the elderly?:::a and b are both false', 'which is true about the basal metabolic of the elderly?', 'A and B are both FALSE', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The basal metabolic rate (BMR) does decline with age, but it happens because of a decrease in the functional capacity of cells and a prominent loss of functioning lean muscle tissue (sarcopenia). It does not decline because cell capacity increases.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both FALSE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The basal metabolic rate (BMR) does decline with age, but it happens because of a decrease in the functional capacity of cells and a prominent loss of functioning lean muscle tissue (sarcopenia). It does not decline because cell capacity increases.\n\nThe decline in baseline metabolic needs is typically accompanied by an increase in body fat (adipose tissue) and a redistribution of fat toward the abdomen, rather than a decrease in body fat.","whyWrongChoices":"Alternative options: It declines with age because of the increase in the functional capacity of cells, The declined metabolic needs is accompanied by a decrease in body fat, A and B are both TRUE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the basal metabolic of the elderly?:::', 'which is true about the basal metabolic of the elderly?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The basal metabolic rate (BMR) does decline with age, but it happens because of a decrease in the functional capacity of cells and a prominent loss of functioning lean muscle tissue (sarcopenia). It does not decline because cell capacity increases.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both FALSE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The basal metabolic rate (BMR) does decline with age, but it happens because of a decrease in the functional capacity of cells and a prominent loss of functioning lean muscle tissue (sarcopenia). It does not decline because cell capacity increases.\n\nThe decline in baseline metabolic needs is typically accompanied by an increase in body fat (adipose tissue) and a redistribution of fat toward the abdomen, rather than a decrease in body fat.","whyWrongChoices":"Alternative options: It declines with age because of the increase in the functional capacity of cells, The declined metabolic needs is accompanied by a decrease in body fat, A and B are both TRUE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
