INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:psychological related factors resulting to malnutrition in elderly except::::immobility', 'psychological related factors resulting to malnutrition in elderly except:', 'Immobility', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Immobility is a physical/biological factor: It refers to the physical inability to move around easily, which causes malnutrition by making it difficult for an elderly person to shop for groceries, lift heavy cooking utensils, or prepare meals independently.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Immobility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Immobility is a physical/biological factor: It refers to the physical inability to move around easily, which causes malnutrition by making it difficult for an elderly person to shop for groceries, lift heavy cooking utensils, or prepare meals independently.\n\nThe other options are psychological/social factors: Living alone (which leads to loneliness and isolation), depression, and anxiety are all mental, emotional, or psychological states that directly destroy an elderly person''s appetite, interest in food, and motivation to eat (a condition often called the \"anorexia of aging\").","whyWrongChoices":"Alternative options: Living alone, Depression, Anxiety"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:psychological related factors resulting to malnutrition in elderly except::::', 'psychological related factors resulting to malnutrition in elderly except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Immobility is a physical/biological factor: It refers to the physical inability to move around easily, which causes malnutrition by making it difficult for an elderly person to shop for groceries, lift heavy cooking utensils, or prepare meals independently.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Immobility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Immobility is a physical/biological factor: It refers to the physical inability to move around easily, which causes malnutrition by making it difficult for an elderly person to shop for groceries, lift heavy cooking utensils, or prepare meals independently.\n\nThe other options are psychological/social factors: Living alone (which leads to loneliness and isolation), depression, and anxiety are all mental, emotional, or psychological states that directly destroy an elderly person''s appetite, interest in food, and motivation to eat (a condition often called the \"anorexia of aging\").","whyWrongChoices":"Alternative options: Living alone, Depression, Anxiety"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:hyposmia is also know as::::lowered sense of smell', 'hyposmia is also know as:', 'Lowered sense of smell', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyposmia is the official clinical term for a partially reduced or lowered ability to smell and detect odors. It is very common in older adults due to natural aging, as well as clinical conditions like chronic sinusitis, viral infections, or neurodegenerative changes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lowered sense of smell\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyposmia is the official clinical term for a partially reduced or lowered ability to smell and detect odors. It is very common in older adults due to natural aging, as well as clinical conditions like chronic sinusitis, viral infections, or neurodegenerative changes.\n\n• Decreased taste sensitivity: This is known as hypogeusia (whereas a complete loss of taste is ageusia).\n• Loss of appetite: This is known clinically as anorexia (such as the anorexia of aging).\n• Lowered thirst sensation: This is known as hypodipsia.","whyWrongChoices":"Alternative options: Decreased taste sensitivity, Loss of appetite, Lowered thirst sensation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:hyposmia is also know as::::', 'hyposmia is also know as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyposmia is the official clinical term for a partially reduced or lowered ability to smell and detect odors. It is very common in older adults due to natural aging, as well as clinical conditions like chronic sinusitis, viral infections, or neurodegenerative changes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lowered sense of smell\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyposmia is the official clinical term for a partially reduced or lowered ability to smell and detect odors. It is very common in older adults due to natural aging, as well as clinical conditions like chronic sinusitis, viral infections, or neurodegenerative changes.\n\n• Decreased taste sensitivity: This is known as hypogeusia (whereas a complete loss of taste is ageusia).\n• Loss of appetite: This is known clinically as anorexia (such as the anorexia of aging).\n• Lowered thirst sensation: This is known as hypodipsia.","whyWrongChoices":"Alternative options: Decreased taste sensitivity, Loss of appetite, Lowered thirst sensation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a multi-level tool for promoting and sustaining risk-reducing behavior change in individuals and communities by distributing tailored specific messages through a variety of channels.:::behavior change communication', 'a multi-level tool for promoting and sustaining risk-reducing behavior change in individuals and communities by distributing tailored specific messages through a variety of channels.', 'Behavior Change Communication', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Behavior Change Communication (BCC) is a strategic, multi-level framework designed to foster and maintain healthy, risk-reducing lifestyle habits within populations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Behavior Change Communication\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Behavior Change Communication (BCC) is a strategic, multi-level framework designed to foster and maintain healthy, risk-reducing lifestyle habits within populations.\n\nIt systematically delivers tailored, highly specific messages designed to resonate with particular audiences. Rather than relying on a single approach, BCC distributes these messages across a variety of communication channels—including interpersonal counseling, group discussions, community media, and mass marketing campaigns.\n\nWhile Nutrition Education is a component of this process, BCC focuses more broadly on the psychological and social drivers of action to shift actual behavior, moving beyond simply providing raw academic facts.","whyWrongChoices":"Alternative options: Nutrition Education, Learning Strategies, Health Promotion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a multi-level tool for promoting and sustaining risk-reducing behavior change in individuals and communities by distributing tailored specific messages through a variety of channels.:::', 'a multi-level tool for promoting and sustaining risk-reducing behavior change in individuals and communities by distributing tailored specific messages through a variety of channels.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Behavior Change Communication (BCC) is a strategic, multi-level framework designed to foster and maintain healthy, risk-reducing lifestyle habits within populations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Behavior Change Communication\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Behavior Change Communication (BCC) is a strategic, multi-level framework designed to foster and maintain healthy, risk-reducing lifestyle habits within populations.\n\nIt systematically delivers tailored, highly specific messages designed to resonate with particular audiences. Rather than relying on a single approach, BCC distributes these messages across a variety of communication channels—including interpersonal counseling, group discussions, community media, and mass marketing campaigns.\n\nWhile Nutrition Education is a component of this process, BCC focuses more broadly on the psychological and social drivers of action to shift actual behavior, moving beyond simply providing raw academic facts.","whyWrongChoices":"Alternative options: Nutrition Education, Learning Strategies, Health Promotion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:“hidden hunger” refers to::::micronutrient deficiency', '“hidden hunger” refers to:', 'Micronutrient deficiency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"\"Hidden hunger\" is a specific public health term used to describe a chronic lack of essential vitamins and minerals (micronutrients)—such as iron, iodine, vitamin A, and zinc—in a person''s diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micronutrient deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"\"Hidden hunger\" is a specific public health term used to describe a chronic lack of essential vitamins and minerals (micronutrients)—such as iron, iodine, vitamin A, and zinc—in a person''s diet.\n\nUnlike classic undernutrition (like marasmus or wasting), where a person visibly looks emaciated due to a severe shortage of total calories or protein, hidden hunger often goes unnoticed. An individual may consume enough food or calories to feel full or maintain a normal body weight, but their body is still suffering from invisible, internal nutrient starvation that damages their immune system, cognitive development, and overall physical health.","whyWrongChoices":"Alternative options: Calorie deficiency, Protein deficiency, Conditioned malnutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:“hidden hunger” refers to::::', '“hidden hunger” refers to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"\"Hidden hunger\" is a specific public health term used to describe a chronic lack of essential vitamins and minerals (micronutrients)—such as iron, iodine, vitamin A, and zinc—in a person''s diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micronutrient deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"\"Hidden hunger\" is a specific public health term used to describe a chronic lack of essential vitamins and minerals (micronutrients)—such as iron, iodine, vitamin A, and zinc—in a person''s diet.\n\nUnlike classic undernutrition (like marasmus or wasting), where a person visibly looks emaciated due to a severe shortage of total calories or protein, hidden hunger often goes unnoticed. An individual may consume enough food or calories to feel full or maintain a normal body weight, but their body is still suffering from invisible, internal nutrient starvation that damages their immune system, cognitive development, and overall physical health.","whyWrongChoices":"Alternative options: Calorie deficiency, Protein deficiency, Conditioned malnutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the complex formed when bile salts combine with lipid material to facilitate digestion.:::', 'the complex formed when bile salts combine with lipid material to facilitate digestion.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Micelles are aggregated lipids formed from bile salts to help the transport and absorption of fat-soluble vitamins and digestive products of lipids in the human body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micelle\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Micelles are aggregated lipids formed from bile salts to help the transport and absorption of fat-soluble vitamins and digestive products of lipids in the human body.","whyWrongChoices":"Alternative options: Chylomicron, HDL"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?:::2:1', 'what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?', '2:1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When preparing traditional, home-modified animal milk for an infant below three months of age, the standard pediatric and public health recommendation is a 2:1 ratio (2 parts whole cow''s milk or carabao''s milk to 1 part water), usually paired with a specific amount of sugar (around 5%).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2:1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When preparing traditional, home-modified animal milk for an infant below three months of age, the standard pediatric and public health recommendation is a 2:1 ratio (2 parts whole cow''s milk or carabao''s milk to 1 part water), usually paired with a specific amount of sugar (around 5%).\n\nWhole, undiluted animal milk contains an exceptionally high concentration of protein and minerals (such as sodium and phosphorus). A young infant''s immature kidneys cannot handle this heavy solute load, which can lead to severe dehydration.\n\nDiluting the milk with 1 part water lowers the renal solute load to a safer level for infants under 3 months. After the child passes 3 months of age, their renal function matures slightly, and the ratio is typically advanced to 3:1 before moving to whole, undiluted milk later in infancy if commercial formula or breast milk is absolutely unavailable.","whyWrongChoices":"Alternative options: 1:2, 1:3, 3:1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?:::', 'what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When preparing traditional, home-modified animal milk for an infant below three months of age, the standard pediatric and public health recommendation is a 2:1 ratio (2 parts whole cow''s milk or carabao''s milk to 1 part water), usually paired with a specific amount of sugar (around 5%).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2:1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When preparing traditional, home-modified animal milk for an infant below three months of age, the standard pediatric and public health recommendation is a 2:1 ratio (2 parts whole cow''s milk or carabao''s milk to 1 part water), usually paired with a specific amount of sugar (around 5%).\n\nWhole, undiluted animal milk contains an exceptionally high concentration of protein and minerals (such as sodium and phosphorus). A young infant''s immature kidneys cannot handle this heavy solute load, which can lead to severe dehydration.\n\nDiluting the milk with 1 part water lowers the renal solute load to a safer level for infants under 3 months. After the child passes 3 months of age, their renal function matures slightly, and the ratio is typically advanced to 3:1 before moving to whole, undiluted milk later in infancy if commercial formula or breast milk is absolutely unavailable.","whyWrongChoices":"Alternative options: 1:2, 1:3, 3:1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is an example of interpersonal communication?:::nutrition counseling', 'which is an example of interpersonal communication?', 'Nutrition counseling', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interpersonal communication refers to a face-to-face, interactive exchange of information between two or more people. In this context, nutrition counseling is the perfect example because it involves a direct, personalized, two-way dialogue between a healthcare professional (or nutrition worker) and an individual client or family. This layout allows for active listening, immediate feedback, and tailored advice.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition counseling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interpersonal communication refers to a face-to-face, interactive exchange of information between two or more people. In this context, nutrition counseling is the perfect example because it involves a direct, personalized, two-way dialogue between a healthcare professional (or nutrition worker) and an individual client or family. This layout allows for active listening, immediate feedback, and tailored advice.","whyWrongChoices":"Alternative options: Mother''s class, Airing of nutrition messages in TV, Distribution of nutrition handouts"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is an example of interpersonal communication?:::', 'which is an example of interpersonal communication?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interpersonal communication refers to a face-to-face, interactive exchange of information between two or more people. In this context, nutrition counseling is the perfect example because it involves a direct, personalized, two-way dialogue between a healthcare professional (or nutrition worker) and an individual client or family. This layout allows for active listening, immediate feedback, and tailored advice.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition counseling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interpersonal communication refers to a face-to-face, interactive exchange of information between two or more people. In this context, nutrition counseling is the perfect example because it involves a direct, personalized, two-way dialogue between a healthcare professional (or nutrition worker) and an individual client or family. This layout allows for active listening, immediate feedback, and tailored advice.","whyWrongChoices":"Alternative options: Mother''s class, Airing of nutrition messages in TV, Distribution of nutrition handouts"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for parkinson’s disease i. adjust food consistency to facilitate chewing and swallowing; ensure adequate fiber and fluid intake; limit dietary protein at breakfast and lunch in patients receiving levodopa therapy when indicated; avoid foods or supplements containing large amounts of l-dopa. ii. adjust food consistency according to tolerance; provide nutrient-dense foods; and offer small, frequent meals.:::all of the above', 'dietary management for parkinson’s disease i. adjust food consistency to facilitate chewing and swallowing; ensure adequate fiber and fluid intake; limit dietary protein at breakfast and lunch in patients receiving levodopa therapy when indicated; avoid foods or supplements containing large amounts of l-dopa. ii. adjust food consistency according to tolerance; provide nutrient-dense foods; and offer small, frequent meals.', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both statements accurately outline essential, standard clinical protocols for managing a patient with Parkinson''s Disease (PD):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both statements accurately outline essential, standard clinical protocols for managing a patient with Parkinson''s Disease (PD):\n\n\t• Dysphagia & Constipation: As PD progresses, motor degradation often leads to chewing and swallowing difficulties (dysphagia), requiring textured food or modified consistencies. Autonomic dysfunction also slows down the GI tract, making a high-fiber and high-fluid regimen critical to preventing chronic constipation.\n\t• The Protein-Levodopa Interaction: Levodopa (the primary medication for PD) utilizes the same active transport carriers across the blood-brain barrier as dietary amino acids. Limiting or shifting protein intake away from breakfast and lunch prevents dietary protein from competing with the medication, ensuring the drug maintains its clinical efficacy throughout the day.\n\t• Exogenous L-dopa: Avoiding foods/supplements with variable amounts of natural L-dopa (like fava beans) prevents unpredictable fluctuations or sudden toxicity.\n\n\t• Malnutrition & Early Satiety: Due to tremors, high metabolic demands, and slow chewing, PD patients are exceptionally prone to unintentional weight loss and muscle wasting. Offering small, frequent, and nutrient-dense meals tailored to their structural texture tolerance optimizes daily caloric intake without overwhelming the patient or causing early fatigue during meals.","whyWrongChoices":"Alternative options: I only, II only, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about menopause among females::::a and b are both true', 'which is true about menopause among females:', 'A and B are both TRUE', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Menopause is the permanent cessation of menstrual periods resulting from the natural biological aging of the female reproductive system:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both TRUE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Menopause is the permanent cessation of menstrual periods resulting from the natural biological aging of the female reproductive system:\n\n• Statement A is TRUE: As a woman transitions into menopause, her ovaries dramatically reduce their secretion of the key female sex hormones, leading to severely decreased levels of estrogen and progesterone. This sharp hormonal decline is responsible for classic menopausal symptoms like hot flashes and night sweats.\n• Statement B is TRUE: The root biological cause of this hormone drop is the natural depletion of the ovarian reserve. A woman is born with a finite number of primordial follicles. Over her reproductive lifespan, as more follicles undergo ovulation or atresia (shrinkage/cell death), the ovaries end up with a significantly lower number of viable ovarian follicles. Consequently, fewer follicles develop completely to ovulate and transform into a corpus luteum (the temporary structure responsible for secreting progesterone).","whyWrongChoices":"Alternative options: A result of decreased levels of estrogen and progesterone, A result of less number of ovarian follicles and corpora lutea, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about menopause among females::::', 'which is true about menopause among females:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Menopause is the permanent cessation of menstrual periods resulting from the natural biological aging of the female reproductive system:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both TRUE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Menopause is the permanent cessation of menstrual periods resulting from the natural biological aging of the female reproductive system:\n\n• Statement A is TRUE: As a woman transitions into menopause, her ovaries dramatically reduce their secretion of the key female sex hormones, leading to severely decreased levels of estrogen and progesterone. This sharp hormonal decline is responsible for classic menopausal symptoms like hot flashes and night sweats.\n• Statement B is TRUE: The root biological cause of this hormone drop is the natural depletion of the ovarian reserve. A woman is born with a finite number of primordial follicles. Over her reproductive lifespan, as more follicles undergo ovulation or atresia (shrinkage/cell death), the ovaries end up with a significantly lower number of viable ovarian follicles. Consequently, fewer follicles develop completely to ovulate and transform into a corpus luteum (the temporary structure responsible for secreting progesterone).","whyWrongChoices":"Alternative options: A result of decreased levels of estrogen and progesterone, A result of less number of ovarian follicles and corpora lutea, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:babies with low birth weight::::have high possibility of neonatal death compared with non-low birth weight infants', 'babies with low birth weight:', 'Have high possibility of neonatal death compared with non-low birth weight infants', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To understand why only this option is correct, let''s break down the clinical parameters of both statements:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Have high possibility of neonatal death compared with non-low birth weight infants\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To understand why only this option is correct, let''s break down the clinical parameters of both statements:\n\n• While it is true that low birth weight (LBW) infants have an increased susceptibility to infection and difficulty regulating their body temperature, they do not have mature kidneys. On the contrary, their organs are highly underdeveloped and immature, often leading to a reduced number of nephrons at birth and an increased risk of chronic kidney disease later in life. Because of the word \"mature\", Statement A is factually incorrect.\n• Epidemiological statistics show that low birth weight is a leading driver of newborn mortality. LBW infants have a significantly higher possibility of neonatal death—ranging from 20 to 24 times more likely to die shortly after birth compared to infants born with a normal weight.","whyWrongChoices":"Alternative options: Have an increased susceptibility to infection, difficulty regulating body temperature and mature kidneys, A and B are both TRUE, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:babies with low birth weight::::', 'babies with low birth weight:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To understand why only this option is correct, let''s break down the clinical parameters of both statements:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Have high possibility of neonatal death compared with non-low birth weight infants\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To understand why only this option is correct, let''s break down the clinical parameters of both statements:\n\n• While it is true that low birth weight (LBW) infants have an increased susceptibility to infection and difficulty regulating their body temperature, they do not have mature kidneys. On the contrary, their organs are highly underdeveloped and immature, often leading to a reduced number of nephrons at birth and an increased risk of chronic kidney disease later in life. Because of the word \"mature\", Statement A is factually incorrect.\n• Epidemiological statistics show that low birth weight is a leading driver of newborn mortality. LBW infants have a significantly higher possibility of neonatal death—ranging from 20 to 24 times more likely to die shortly after birth compared to infants born with a normal weight.","whyWrongChoices":"Alternative options: Have an increased susceptibility to infection, difficulty regulating body temperature and mature kidneys, A and B are both TRUE, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what law strengthens the barangay nutrition program by providing for a barangay nutrition scholar in every barangay to assist in the coordination and implementation of nutrition programs, projects, and activities and the barangay level?:::pd 1569', 'what law strengthens the barangay nutrition program by providing for a barangay nutrition scholar in every barangay to assist in the coordination and implementation of nutrition programs, projects, and activities and the barangay level?', 'PD 1569', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Signed on June 11, 1978, Presidential Decree No. 1569 is titled \"Strengthening the Barangay Nutrition Program by providing for a Barangay Nutrition Scholar (BNS) in every barangay, providing funds therefor, and for other purposes.\"","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PD 1569\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Signed on June 11, 1978, Presidential Decree No. 1569 is titled \"Strengthening the Barangay Nutrition Program by providing for a Barangay Nutrition Scholar (BNS) in every barangay, providing funds therefor, and for other purposes.\"\n\nIt officially established the BNS program across the Philippines, mandating that every barangay should have a trained local volunteer (the BNS) responsible for:\n• Monitoring the nutritional status of children through routine weighing (Operation Timbang Plus)\n• Linking malnourished children and families to health and nutrition services\n• Coordinating nutrition programs, projects, and activities directly at the grass-roots barangay level","whyWrongChoices":"Alternative options: PD 1596, PD 1659, PD 1695"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what law strengthens the barangay nutrition program by providing for a barangay nutrition scholar in every barangay to assist in the coordination and implementation of nutrition programs, projects, and activities and the barangay level?:::', 'what law strengthens the barangay nutrition program by providing for a barangay nutrition scholar in every barangay to assist in the coordination and implementation of nutrition programs, projects, and activities and the barangay level?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Signed on June 11, 1978, Presidential Decree No. 1569 is titled \"Strengthening the Barangay Nutrition Program by providing for a Barangay Nutrition Scholar (BNS) in every barangay, providing funds therefor, and for other purposes.\"","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PD 1569\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Signed on June 11, 1978, Presidential Decree No. 1569 is titled \"Strengthening the Barangay Nutrition Program by providing for a Barangay Nutrition Scholar (BNS) in every barangay, providing funds therefor, and for other purposes.\"\n\nIt officially established the BNS program across the Philippines, mandating that every barangay should have a trained local volunteer (the BNS) responsible for:\n• Monitoring the nutritional status of children through routine weighing (Operation Timbang Plus)\n• Linking malnourished children and families to health and nutrition services\n• Coordinating nutrition programs, projects, and activities directly at the grass-roots barangay level","whyWrongChoices":"Alternative options: PD 1596, PD 1659, PD 1695"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:with reference to the unicef framework on the causes of undernutrition, unhealthy environment is categorized as::::underlying cause', 'with reference to the unicef framework on the causes of undernutrition, unhealthy environment is categorized as:', 'Underlying cause', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under the globally recognized UNICEF Conceptual Framework on the Causes of Malnutrition, the factors that lead to undernutrition are structurally categorized into three distinct, hierarchical levels of causation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Underlying cause\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under the globally recognized UNICEF Conceptual Framework on the Causes of Malnutrition, the factors that lead to undernutrition are structurally categorized into three distinct, hierarchical levels of causation:\n\n1. Immediate Causes (Individual level): These are the direct physical factors that affect the person''s body—specifically inadequate dietary intake and diseases.\n2. Underlying Causes (Household/Community level): These are the social, economic, and environmental factors that lead to those immediate causes. An unhealthy environment (such as a lack of safe water, poor sanitation, and inadequate hygiene) falls squarely in this category, alongside a lack of household food security and inadequate caregiving practices.\n3. Basic Causes (Societal level): These are the systemic or structural root problems within a society, such as political instability, poverty, poor governance, and lack of resources.","whyWrongChoices":"Alternative options: Immediate cause, Potential cause, Basic cause"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:with reference to the unicef framework on the causes of undernutrition, unhealthy environment is categorized as::::', 'with reference to the unicef framework on the causes of undernutrition, unhealthy environment is categorized as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under the globally recognized UNICEF Conceptual Framework on the Causes of Malnutrition, the factors that lead to undernutrition are structurally categorized into three distinct, hierarchical levels of causation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Underlying cause\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under the globally recognized UNICEF Conceptual Framework on the Causes of Malnutrition, the factors that lead to undernutrition are structurally categorized into three distinct, hierarchical levels of causation:\n\n1. Immediate Causes (Individual level): These are the direct physical factors that affect the person''s body—specifically inadequate dietary intake and diseases.\n2. Underlying Causes (Household/Community level): These are the social, economic, and environmental factors that lead to those immediate causes. An unhealthy environment (such as a lack of safe water, poor sanitation, and inadequate hygiene) falls squarely in this category, alongside a lack of household food security and inadequate caregiving practices.\n3. Basic Causes (Societal level): These are the systemic or structural root problems within a society, such as political instability, poverty, poor governance, and lack of resources.","whyWrongChoices":"Alternative options: Immediate cause, Potential cause, Basic cause"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the effortless expulsion of gastric contents caused by gi reflux in babies:::', 'the effortless expulsion of gastric contents caused by gi reflux in babies', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Regurgitation is clinically defined as the effortless, passive expulsion of swallowed food or gastric contents from the stomach back into the esophagus and mouth. In infants, this is primarily driven by an immature lower esophageal sphincter—a common, normal condition known as gastroesophageal reflux (GER) that usually resolves on its own as the baby grows.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Regurgitation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Regurgitation is clinically defined as the effortless, passive expulsion of swallowed food or gastric contents from the stomach back into the esophagus and mouth. In infants, this is primarily driven by an immature lower esophageal sphincter—a common, normal condition known as gastroesophageal reflux (GER) that usually resolves on its own as the baby grows.\n\n• Colic: This refers to periods of intense, frequent, and unexplained crying in an otherwise healthy infant, often thought to be linked to gas or abdominal discomfort, rather than the physical ejection of stomach contents.\n• Diarrhea: This describes loose, watery stools passing through the lower gastrointestinal tract, not an upward reflux into the mouth.\n• Spitting-up-food: While this is the casual, everyday term parents use for this exact behavior, Regurgitation is the primary scientific and medical terminology used in public health exams to describe the involuntary mechanism itself.","whyWrongChoices":"Alternative options: Colic, Spitting-up-food, Diarrhea"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:who is the chair of the national nutrition council governing board?:::department of health', 'who is the chair of the national nutrition council governing board?', 'Department of Health', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By law, under Presidential Decree No. 491 (The Nutrition Act of the Philippines) and subsequent executive updates, the Secretary of the Department of Health (DOH) serves as the official Chairperson of the National Nutrition Council (NNC) Governing Board.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Department of Health\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By law, under Presidential Decree No. 491 (The Nutrition Act of the Philippines) and subsequent executive updates, the Secretary of the Department of Health (DOH) serves as the official Chairperson of the National Nutrition Council (NNC) Governing Board.\n\nThe NNC is the country''s highest policy-making and coordinating body on nutrition. Its leadership structure consists of:\n• Chairperson: Secretary of the Department of Health (DOH)\n• Vice-Chairs:\n\t1. Secretary of the Department of Agriculture (DA)\n\t2. Secretary of the Department of the Interior and Local Government (DILG)\n\nThe board also includes the heads of several other departments (such as DepEd, DSWD, DTI, DOST, and DOLE) alongside representatives from the private sector to ensure a multi-sectoral approach to addressing malnutrition.","whyWrongChoices":"Alternative options: Department of Agriculture, Department of Education, Department of Interior and Local Government"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:who is the chair of the national nutrition council governing board?:::', 'who is the chair of the national nutrition council governing board?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"By law, under Presidential Decree No. 491 (The Nutrition Act of the Philippines) and subsequent executive updates, the Secretary of the Department of Health (DOH) serves as the official Chairperson of the National Nutrition Council (NNC) Governing Board.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Department of Health\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"By law, under Presidential Decree No. 491 (The Nutrition Act of the Philippines) and subsequent executive updates, the Secretary of the Department of Health (DOH) serves as the official Chairperson of the National Nutrition Council (NNC) Governing Board.\n\nThe NNC is the country''s highest policy-making and coordinating body on nutrition. Its leadership structure consists of:\n• Chairperson: Secretary of the Department of Health (DOH)\n• Vice-Chairs:\n\t1. Secretary of the Department of Agriculture (DA)\n\t2. Secretary of the Department of the Interior and Local Government (DILG)\n\nThe board also includes the heads of several other departments (such as DepEd, DSWD, DTI, DOST, and DOLE) alongside representatives from the private sector to ensure a multi-sectoral approach to addressing malnutrition.","whyWrongChoices":"Alternative options: Department of Agriculture, Department of Education, Department of Interior and Local Government"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:wasting in children is defined as ?:::weight-for-height that is more than 2 z-scores below the reference', 'wasting in children is defined as ?', 'Weight-for-height that is more than 2 Z-scores below the reference', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In pediatric anthropometry and public health frameworks managed by the World Health Organization (WHO), childhood malnutrition indicators are divided into distinct categories based on standard deviations (Z-scores) relative to a healthy reference population:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Weight-for-height that is more than 2 Z-scores below the reference\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In pediatric anthropometry and public health frameworks managed by the World Health Organization (WHO), childhood malnutrition indicators are divided into distinct categories based on standard deviations (Z-scores) relative to a healthy reference population:\n\n• Wasting (Acute Malnutrition): This measures body mass in relation to body length. It is defined as a weight-for-height (or weight-for-length) value that sits more than 2 standard deviations below (-2 Z-scores) the WHO Child Growth Standards. It signifies rapid, severe weight loss or a failure to gain weight, typically caused by recent starvation, severe illness, or infection.\n• Stunting (Chronic Malnutrition): This measures linear growth retardation and is defined as a height-for-age value more than 2 Z-scores below the reference. It reflects long-term, ongoing nutritional deprivation.\n• Underweight: This is a composite metric combining acute and chronic factors, defined as a weight-for-age value more than 2 Z-scores below the reference.","whyWrongChoices":"Alternative options: Height-for-age that is more than 2 Z-scores below the reference, Weight-for-age that is more than 2 Z-scores below the reference, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:wasting in children is defined as ?:::', 'wasting in children is defined as ?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In pediatric anthropometry and public health frameworks managed by the World Health Organization (WHO), childhood malnutrition indicators are divided into distinct categories based on standard deviations (Z-scores) relative to a healthy reference population:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Weight-for-height that is more than 2 Z-scores below the reference\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In pediatric anthropometry and public health frameworks managed by the World Health Organization (WHO), childhood malnutrition indicators are divided into distinct categories based on standard deviations (Z-scores) relative to a healthy reference population:\n\n• Wasting (Acute Malnutrition): This measures body mass in relation to body length. It is defined as a weight-for-height (or weight-for-length) value that sits more than 2 standard deviations below (-2 Z-scores) the WHO Child Growth Standards. It signifies rapid, severe weight loss or a failure to gain weight, typically caused by recent starvation, severe illness, or infection.\n• Stunting (Chronic Malnutrition): This measures linear growth retardation and is defined as a height-for-age value more than 2 Z-scores below the reference. It reflects long-term, ongoing nutritional deprivation.\n• Underweight: This is a composite metric combining acute and chronic factors, defined as a weight-for-age value more than 2 Z-scores below the reference.","whyWrongChoices":"Alternative options: Height-for-age that is more than 2 Z-scores below the reference, Weight-for-age that is more than 2 Z-scores below the reference, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a function of public health nutritionist which focuses on assisting the community to solve their diet and nutrition related problems.:::program implementer', 'a function of public health nutritionist which focuses on assisting the community to solve their diet and nutrition related problems.', 'Program Implementer', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to standard professional public health nutrition curriculum tracking guides (like those from UPLB and the FNDRC mock boards), the roles are explicitly partitioned by these exact action fragments:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Program Implementer\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to standard professional public health nutrition curriculum tracking guides (like those from UPLB and the FNDRC mock boards), the roles are explicitly partitioned by these exact action fragments:\n\n1. Program Implementer: The core action of this role explicitly states that the nutritionist \"guides or assists the people in solving their diet and nutrition-related problems\" directly in the field. It is an on-the-ground execution role focused on helping the community change behaviors and overcome immediate barriers.\n2. Program Administrator: This function is academically defined as focusing on financial management, budgeting, and organizing the personnel who are involved in the nutrition program implementation.\n3. Program Planner: Focuses on organizing program planning activities, assisting the community in identifying and prioritizing their problems, and designing the specific course of action to be taken.\n4. Program Organizer / Assessor: Focuses on initiating the development of the organization or community network to clear the path for future interventions.","whyWrongChoices":"Alternative options: Program Planner, Program Organizer, Program Administrator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a function of public health nutritionist which focuses on assisting the community to solve their diet and nutrition related problems.:::', 'a function of public health nutritionist which focuses on assisting the community to solve their diet and nutrition related problems.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to standard professional public health nutrition curriculum tracking guides (like those from UPLB and the FNDRC mock boards), the roles are explicitly partitioned by these exact action fragments:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Program Implementer\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to standard professional public health nutrition curriculum tracking guides (like those from UPLB and the FNDRC mock boards), the roles are explicitly partitioned by these exact action fragments:\n\n1. Program Implementer: The core action of this role explicitly states that the nutritionist \"guides or assists the people in solving their diet and nutrition-related problems\" directly in the field. It is an on-the-ground execution role focused on helping the community change behaviors and overcome immediate barriers.\n2. Program Administrator: This function is academically defined as focusing on financial management, budgeting, and organizing the personnel who are involved in the nutrition program implementation.\n3. Program Planner: Focuses on organizing program planning activities, assisting the community in identifying and prioritizing their problems, and designing the specific course of action to be taken.\n4. Program Organizer / Assessor: Focuses on initiating the development of the organization or community network to clear the path for future interventions.","whyWrongChoices":"Alternative options: Program Planner, Program Organizer, Program Administrator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the breast milk that women produce in the first few days after delivery:::colostrum', 'the breast milk that women produce in the first few days after delivery', 'Colostrum', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Colostrum is the distinct, specialized form of breast milk produced by the mammary glands in late pregnancy and the first few days after delivery (typically days 1 to 4). It is a thick, yellowish fluid that is uniquely adapted to a newborn''s immediate needs:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Colostrum\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Colostrum is the distinct, specialized form of breast milk produced by the mammary glands in late pregnancy and the first few days after delivery (typically days 1 to 4). It is a thick, yellowish fluid that is uniquely adapted to a newborn''s immediate needs:\n\nIt is highly concentrated with leukocytes and protective antibodies—especially Immunoglobulin A (IgA)—acting as the infant''s first natural vaccine.\n\nIt contains high levels of epidermal growth factors to help mature the infant''s gut lining, and acts as a mild laxative to assist the baby in passing meconium (the first stool).\n\n• Mature milk: This thinner, bluish-white milk transitions in around day 10 to 15 postpartum, supplying the stable balance of water, carbohydrates, lipids, and proteins needed for long-term growth.\n• Foremilk: This is the milk available at the beginning of a single feeding session, which is watery and high in lactose to satisfy the infant''s thirst.\n• Hindmilk: This is the creamier milk released toward the end of a single feeding session, which is dense in fat and calories to promote satiety and weight gain.","whyWrongChoices":"Alternative options: Mature milk, Foremilk, Hindmilk"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the breast milk that women produce in the first few days after delivery:::', 'the breast milk that women produce in the first few days after delivery', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Colostrum is the distinct, specialized form of breast milk produced by the mammary glands in late pregnancy and the first few days after delivery (typically days 1 to 4). It is a thick, yellowish fluid that is uniquely adapted to a newborn''s immediate needs:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Colostrum\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Colostrum is the distinct, specialized form of breast milk produced by the mammary glands in late pregnancy and the first few days after delivery (typically days 1 to 4). It is a thick, yellowish fluid that is uniquely adapted to a newborn''s immediate needs:\n\nIt is highly concentrated with leukocytes and protective antibodies—especially Immunoglobulin A (IgA)—acting as the infant''s first natural vaccine.\n\nIt contains high levels of epidermal growth factors to help mature the infant''s gut lining, and acts as a mild laxative to assist the baby in passing meconium (the first stool).\n\n• Mature milk: This thinner, bluish-white milk transitions in around day 10 to 15 postpartum, supplying the stable balance of water, carbohydrates, lipids, and proteins needed for long-term growth.\n• Foremilk: This is the milk available at the beginning of a single feeding session, which is watery and high in lactose to satisfy the infant''s thirst.\n• Hindmilk: This is the creamier milk released toward the end of a single feeding session, which is dense in fat and calories to promote satiety and weight gain.","whyWrongChoices":"Alternative options: Mature milk, Foremilk, Hindmilk"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these scavenge and engulf foreign bodies and secrete complements and cytokines.:::phagocytes', 'these scavenge and engulf foreign bodies and secrete complements and cytokines.', 'Phagocytes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Macrophages are specialized phagocytic cells that engulf and digest pathogens, cellular debris, and other foreign material. They also secrete cytokines that regulate inflammation and immune responses and can produce components of the complement system. Macrophages also function as antigen-presenting cells, helping activate adaptive immune responses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phagocytes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Macrophages are specialized phagocytic cells that engulf and digest pathogens, cellular debris, and other foreign material. They also secrete cytokines that regulate inflammation and immune responses and can produce components of the complement system. Macrophages also function as antigen-presenting cells, helping activate adaptive immune responses.","whyWrongChoices":"Alternative options: Macropages, T cells, B cells"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these scavenge and engulf foreign bodies and secrete complements and cytokines.:::', 'these scavenge and engulf foreign bodies and secrete complements and cytokines.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Macrophages are specialized phagocytic cells that engulf and digest pathogens, cellular debris, and other foreign material. They also secrete cytokines that regulate inflammation and immune responses and can produce components of the complement system. Macrophages also function as antigen-presenting cells, helping activate adaptive immune responses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phagocytes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Macrophages are specialized phagocytic cells that engulf and digest pathogens, cellular debris, and other foreign material. They also secrete cytokines that regulate inflammation and immune responses and can produce components of the complement system. Macrophages also function as antigen-presenting cells, helping activate adaptive immune responses.","whyWrongChoices":"Alternative options: Macropages, T cells, B cells"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the enzyme that cleaves aromatic amino acids.:::chymotrypsin', 'the enzyme that cleaves aromatic amino acids.', 'Chymotrypsin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chymotrypsin is a pancreatic protease that preferentially cleaves peptide bonds on the carboxyl side of aromatic amino acids, particularly phenylalanine, tyrosine, and tryptophan. This specificity helps break dietary proteins into smaller peptides during intestinal digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chymotrypsin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chymotrypsin is a pancreatic protease that preferentially cleaves peptide bonds on the carboxyl side of aromatic amino acids, particularly phenylalanine, tyrosine, and tryptophan. This specificity helps break dietary proteins into smaller peptides during intestinal digestion.","whyWrongChoices":"Alternative options: Pepsin, Carboxypeptidase, Aminopeptidase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the enzyme that cleaves aromatic amino acids.:::', 'the enzyme that cleaves aromatic amino acids.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chymotrypsin is a pancreatic protease that preferentially cleaves peptide bonds on the carboxyl side of aromatic amino acids, particularly phenylalanine, tyrosine, and tryptophan. This specificity helps break dietary proteins into smaller peptides during intestinal digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chymotrypsin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chymotrypsin is a pancreatic protease that preferentially cleaves peptide bonds on the carboxyl side of aromatic amino acids, particularly phenylalanine, tyrosine, and tryptophan. This specificity helps break dietary proteins into smaller peptides during intestinal digestion.","whyWrongChoices":"Alternative options: Pepsin, Carboxypeptidase, Aminopeptidase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:post bariatric surgery dietary management::::all of the above', 'post bariatric surgery dietary management:', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"After bariatric surgery, the diet is advanced gradually according to the type of procedure and the patient''s tolerance. Early postoperative management commonly begins with clear liquids, followed by progressively thicker liquids and/or puréed or soft foods before advancing to regular textures. Small, frequent meals are essential because the reduced gastric capacity limits the amount that can be consumed at one time. The exact duration of each stage varies by surgical program, so “one month” for puréed foods should be regarded as a traditional/generalized schedule rather than a universal requirement.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"After bariatric surgery, the diet is advanced gradually according to the type of procedure and the patient''s tolerance. Early postoperative management commonly begins with clear liquids, followed by progressively thicker liquids and/or puréed or soft foods before advancing to regular textures. Small, frequent meals are essential because the reduced gastric capacity limits the amount that can be consumed at one time. The exact duration of each stage varies by surgical program, so “one month” for puréed foods should be regarded as a traditional/generalized schedule rather than a universal requirement.","whyWrongChoices":"Alternative options: clear liquid for the first day, pureed foods for a month, small feeding"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:post bariatric surgery dietary management::::', 'post bariatric surgery dietary management:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"After bariatric surgery, the diet is advanced gradually according to the type of procedure and the patient''s tolerance. Early postoperative management commonly begins with clear liquids, followed by progressively thicker liquids and/or puréed or soft foods before advancing to regular textures. Small, frequent meals are essential because the reduced gastric capacity limits the amount that can be consumed at one time. The exact duration of each stage varies by surgical program, so “one month” for puréed foods should be regarded as a traditional/generalized schedule rather than a universal requirement.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"After bariatric surgery, the diet is advanced gradually according to the type of procedure and the patient''s tolerance. Early postoperative management commonly begins with clear liquids, followed by progressively thicker liquids and/or puréed or soft foods before advancing to regular textures. Small, frequent meals are essential because the reduced gastric capacity limits the amount that can be consumed at one time. The exact duration of each stage varies by surgical program, so “one month” for puréed foods should be regarded as a traditional/generalized schedule rather than a universal requirement.","whyWrongChoices":"Alternative options: clear liquid for the first day, pureed foods for a month, small feeding"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following vitamins is considered anti-infective vitamin?:::vit a', 'which of the following vitamins is considered anti-infective vitamin?', 'Vit A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin A has historically been called the “anti-infective vitamin” because of its important role in maintaining epithelial and mucosal barriers and supporting both innate and adaptive immune function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin A has historically been called the “anti-infective vitamin” because of its important role in maintaining epithelial and mucosal barriers and supporting both innate and adaptive immune function.\n\nVitamin A helps maintain the integrity and function of epithelial tissues lining the respiratory, gastrointestinal, and genitourinary tracts, which serve as important physical barriers against pathogens. It also contributes to normal immune-cell function and antibody responses.\n\nVitamin A deficiency can impair immune defenses and increase susceptibility to certain infections, particularly in children. Conversely, vitamin A supplementation has demonstrated benefits in specific populations with deficiency or certain infectious diseases, but routine high-dose supplementation is not recommended for everyone.","whyWrongChoices":"Alternative options: Vit D, Vit E, Vit K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following vitamins is considered anti-infective vitamin?:::', 'which of the following vitamins is considered anti-infective vitamin?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin A has historically been called the “anti-infective vitamin” because of its important role in maintaining epithelial and mucosal barriers and supporting both innate and adaptive immune function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin A has historically been called the “anti-infective vitamin” because of its important role in maintaining epithelial and mucosal barriers and supporting both innate and adaptive immune function.\n\nVitamin A helps maintain the integrity and function of epithelial tissues lining the respiratory, gastrointestinal, and genitourinary tracts, which serve as important physical barriers against pathogens. It also contributes to normal immune-cell function and antibody responses.\n\nVitamin A deficiency can impair immune defenses and increase susceptibility to certain infections, particularly in children. Conversely, vitamin A supplementation has demonstrated benefits in specific populations with deficiency or certain infectious diseases, but routine high-dose supplementation is not recommended for everyone.","whyWrongChoices":"Alternative options: Vit D, Vit E, Vit K"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the body''s normal ph range is::::7.35-7.45', 'the body''s normal ph range is:', '7.35-7.45', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Normal arterial blood pH is maintained at approximately 7.35–7.45, reflecting a slightly alkaline environment. The body tightly regulates pH through the bicarbonate buffer system, lungs, and kidneys.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"7.35-7.45\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Normal arterial blood pH is maintained at approximately 7.35–7.45, reflecting a slightly alkaline environment. The body tightly regulates pH through the bicarbonate buffer system, lungs, and kidneys.\n\nValues below 7.35 indicate acidemia, while values above 7.45 indicate alkalemia.","whyWrongChoices":"Alternative options: 7.45-7.55, 7.25-7.35, 7.00-7.45"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the body''s normal ph range is::::', 'the body''s normal ph range is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Normal arterial blood pH is maintained at approximately 7.35–7.45, reflecting a slightly alkaline environment. The body tightly regulates pH through the bicarbonate buffer system, lungs, and kidneys.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"7.35-7.45\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Normal arterial blood pH is maintained at approximately 7.35–7.45, reflecting a slightly alkaline environment. The body tightly regulates pH through the bicarbonate buffer system, lungs, and kidneys.\n\nValues below 7.35 indicate acidemia, while values above 7.45 indicate alkalemia.","whyWrongChoices":"Alternative options: 7.45-7.55, 7.25-7.35, 7.00-7.45"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foods allowed in a low purine diet::::milk, cheese, and eggs', 'foods allowed in a low purine diet:', 'Milk, cheese, and eggs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"These foods are generally low in purines and are appropriate choices in a low-purine diet. In contrast, organ meats contain very high amounts of purines and are restricted, particularly for patients with gout or hyperuricemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Milk, cheese, and eggs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"These foods are generally low in purines and are appropriate choices in a low-purine diet. In contrast, organ meats contain very high amounts of purines and are restricted, particularly for patients with gout or hyperuricemia.","whyWrongChoices":"Alternative options: Grandular organs, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foods allowed in a low purine diet::::', 'foods allowed in a low purine diet:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"These foods are generally low in purines and are appropriate choices in a low-purine diet. In contrast, organ meats contain very high amounts of purines and are restricted, particularly for patients with gout or hyperuricemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Milk, cheese, and eggs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"These foods are generally low in purines and are appropriate choices in a low-purine diet. In contrast, organ meats contain very high amounts of purines and are restricted, particularly for patients with gout or hyperuricemia.","whyWrongChoices":"Alternative options: Grandular organs, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which drug may bind with phosphorus and reduce its absorption?:::', 'which drug may bind with phosphorus and reduce its absorption?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Some antacids, particularly those containing aluminum or calcium, can bind phosphate in the gastrointestinal tract and form poorly absorbed complexes, thereby reducing phosphorus absorption. This property is also therapeutically used with aluminum- or calcium-based phosphate binders in patients with chronic kidney disease and hyperphosphatemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"antacid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Some antacids, particularly those containing aluminum or calcium, can bind phosphate in the gastrointestinal tract and form poorly absorbed complexes, thereby reducing phosphorus absorption. This property is also therapeutically used with aluminum- or calcium-based phosphate binders in patients with chronic kidney disease and hyperphosphatemia.","whyWrongChoices":"Alternative options: laxative, digitails, amphetamines"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are consequences of hospital malnutrition except::::decrease mortality and morbidity', 'all are consequences of hospital malnutrition except:', 'decrease mortality and morbidity', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hospital malnutrition is associated with increased, not decreased, morbidity and mortality.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"decrease mortality and morbidity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hospital malnutrition is associated with increased, not decreased, morbidity and mortality.\n\nDisease-related malnutrition can impair immune function, reduce muscle mass and strength, delay tissue repair, and compromise recovery. Consequently, malnourished hospitalized patients are at greater risk of complications, infections, prolonged hospitalization, and poorer clinical outcomes.","whyWrongChoices":"Alternative options: poor wound healing, higher infection rates, longer hospital and ventilator days"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are consequences of hospital malnutrition except::::', 'all are consequences of hospital malnutrition except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hospital malnutrition is associated with increased, not decreased, morbidity and mortality.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"decrease mortality and morbidity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hospital malnutrition is associated with increased, not decreased, morbidity and mortality.\n\nDisease-related malnutrition can impair immune function, reduce muscle mass and strength, delay tissue repair, and compromise recovery. Consequently, malnourished hospitalized patients are at greater risk of complications, infections, prolonged hospitalization, and poorer clinical outcomes.","whyWrongChoices":"Alternative options: poor wound healing, higher infection rates, longer hospital and ventilator days"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:patients with diabtes mellitus who are on long term metformin therpay are at risk what nutrient deficiency?:::vit b12', 'patients with diabtes mellitus who are on long term metformin therpay are at risk what nutrient deficiency?', 'Vit B12', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin B12 deficiency is a recognized potential adverse effect of long-term metformin therapy. Metformin can interfere with vitamin B12 absorption, and the risk generally increases with higher doses and longer duration of treatment.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit B12\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin B12 deficiency is a recognized potential adverse effect of long-term metformin therapy. Metformin can interfere with vitamin B12 absorption, and the risk generally increases with higher doses and longer duration of treatment.\n\nThe mechanism is multifactorial and may involve altered intestinal handling of the intrinsic factor–B12 complex, among other effects.\n\nB12 deficiency is clinically important because it can cause:\n• Megaloblastic anemia\n• Peripheral neuropathy\n• Paresthesia and other neurological manifestations\n• Cognitive or neuropsychiatric changes in more severe cases\n\nThis is particularly relevant in patients with diabetes because B12 deficiency–related neuropathy can potentially be confused with or add to diabetic peripheral neuropathy.\n\nCurrent diabetes guidance recommends considering periodic assessment of vitamin B12 status in patients taking metformin, particularly when treatment is prolonged or when anemia or neuropathy develops.","whyWrongChoices":"Alternative options: Vit B1, Vit B3, Vit B9"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:patients with diabtes mellitus who are on long term metformin therpay are at risk what nutrient deficiency?:::', 'patients with diabtes mellitus who are on long term metformin therpay are at risk what nutrient deficiency?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin B12 deficiency is a recognized potential adverse effect of long-term metformin therapy. Metformin can interfere with vitamin B12 absorption, and the risk generally increases with higher doses and longer duration of treatment.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit B12\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin B12 deficiency is a recognized potential adverse effect of long-term metformin therapy. Metformin can interfere with vitamin B12 absorption, and the risk generally increases with higher doses and longer duration of treatment.\n\nThe mechanism is multifactorial and may involve altered intestinal handling of the intrinsic factor–B12 complex, among other effects.\n\nB12 deficiency is clinically important because it can cause:\n• Megaloblastic anemia\n• Peripheral neuropathy\n• Paresthesia and other neurological manifestations\n• Cognitive or neuropsychiatric changes in more severe cases\n\nThis is particularly relevant in patients with diabetes because B12 deficiency–related neuropathy can potentially be confused with or add to diabetic peripheral neuropathy.\n\nCurrent diabetes guidance recommends considering periodic assessment of vitamin B12 status in patients taking metformin, particularly when treatment is prolonged or when anemia or neuropathy develops.","whyWrongChoices":"Alternative options: Vit B1, Vit B3, Vit B9"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the first feeding for a patient with 1200 kcal, 2:1 diet rx?:::no first feeding', 'what is the first feeding for a patient with 1200 kcal, 2:1 diet rx?', 'No first feeding', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the traditional therapeutic-diet terminology used in Philippine dietetics, a 2:1 diet prescription refers to a diet in which the first feeding is omitted. The prescribed 1,200 kcal refers to the total daily energy allowance, but the specific first feeding is determined by the diet pattern/order rather than by simply selecting a liquid food. Thus, “no first feeding” is the intended answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"No first feeding\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the traditional therapeutic-diet terminology used in Philippine dietetics, a 2:1 diet prescription refers to a diet in which the first feeding is omitted. The prescribed 1,200 kcal refers to the total daily energy allowance, but the specific first feeding is determined by the diet pattern/order rather than by simply selecting a liquid food. Thus, “no first feeding” is the intended answer.","whyWrongChoices":"Alternative options: 1/2 evaporated milk diluted in 1/2 cup water, 1/2 cup juice diluted in 1/2 cup water, Cannot be determined from the given provided"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the first feeding for a patient with 1200 kcal, 2:1 diet rx?:::', 'what is the first feeding for a patient with 1200 kcal, 2:1 diet rx?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the traditional therapeutic-diet terminology used in Philippine dietetics, a 2:1 diet prescription refers to a diet in which the first feeding is omitted. The prescribed 1,200 kcal refers to the total daily energy allowance, but the specific first feeding is determined by the diet pattern/order rather than by simply selecting a liquid food. Thus, “no first feeding” is the intended answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"No first feeding\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the traditional therapeutic-diet terminology used in Philippine dietetics, a 2:1 diet prescription refers to a diet in which the first feeding is omitted. The prescribed 1,200 kcal refers to the total daily energy allowance, but the specific first feeding is determined by the diet pattern/order rather than by simply selecting a liquid food. Thus, “no first feeding” is the intended answer.","whyWrongChoices":"Alternative options: 1/2 evaporated milk diluted in 1/2 cup water, 1/2 cup juice diluted in 1/2 cup water, Cannot be determined from the given provided"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
