INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the conversion of acetyl-coa into acetoacetic acid, beta-hydroxybutryric acid or acetone is called::::ketogenesis', 'the conversion of acetyl-coa into acetoacetic acid, beta-hydroxybutryric acid or acetone is called:', 'Ketogenesis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ketogenesis is the metabolic process in which excess acetyl-CoA, primarily generated from fatty acid oxidation in the liver, is converted into ketone bodies: acetoacetate, β-hydroxybutyrate, and acetone. It becomes more active when carbohydrate availability or insulin action is insufficient, such as during prolonged fasting, starvation, or uncontrolled diabetes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ketogenesis is the metabolic process in which excess acetyl-CoA, primarily generated from fatty acid oxidation in the liver, is converted into ketone bodies: acetoacetate, β-hydroxybutyrate, and acetone. It becomes more active when carbohydrate availability or insulin action is insufficient, such as during prolonged fasting, starvation, or uncontrolled diabetes.","whyWrongChoices":"Alternative options: Gluconeogenesis, Glycogenolysis, Lipogenesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the conversion of acetyl-coa into acetoacetic acid, beta-hydroxybutryric acid or acetone is called::::', 'the conversion of acetyl-coa into acetoacetic acid, beta-hydroxybutryric acid or acetone is called:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ketogenesis is the metabolic process in which excess acetyl-CoA, primarily generated from fatty acid oxidation in the liver, is converted into ketone bodies: acetoacetate, β-hydroxybutyrate, and acetone. It becomes more active when carbohydrate availability or insulin action is insufficient, such as during prolonged fasting, starvation, or uncontrolled diabetes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ketogenesis is the metabolic process in which excess acetyl-CoA, primarily generated from fatty acid oxidation in the liver, is converted into ketone bodies: acetoacetate, β-hydroxybutyrate, and acetone. It becomes more active when carbohydrate availability or insulin action is insufficient, such as during prolonged fasting, starvation, or uncontrolled diabetes.","whyWrongChoices":"Alternative options: Gluconeogenesis, Glycogenolysis, Lipogenesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:substance found in raw egg white that binds with biotin preventing its absorption::::avidin', 'substance found in raw egg white that binds with biotin preventing its absorption:', 'Avidin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Avidin is a glycoprotein found in raw egg white that binds very strongly to biotin (vitamin B7), reducing its intestinal absorption. Regular consumption of large amounts of raw egg white can therefore contribute to biotin deficiency. Cooking denatures avidin, greatly reducing its ability to bind biotin, which is why this problem is primarily associated with raw egg whites.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Avidin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Avidin is a glycoprotein found in raw egg white that binds very strongly to biotin (vitamin B7), reducing its intestinal absorption. Regular consumption of large amounts of raw egg white can therefore contribute to biotin deficiency. Cooking denatures avidin, greatly reducing its ability to bind biotin, which is why this problem is primarily associated with raw egg whites.","whyWrongChoices":"Alternative options: Albumin, Vitelline, Ovomucin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:substance found in raw egg white that binds with biotin preventing its absorption::::', 'substance found in raw egg white that binds with biotin preventing its absorption:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Avidin is a glycoprotein found in raw egg white that binds very strongly to biotin (vitamin B7), reducing its intestinal absorption. Regular consumption of large amounts of raw egg white can therefore contribute to biotin deficiency. Cooking denatures avidin, greatly reducing its ability to bind biotin, which is why this problem is primarily associated with raw egg whites.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Avidin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Avidin is a glycoprotein found in raw egg white that binds very strongly to biotin (vitamin B7), reducing its intestinal absorption. Regular consumption of large amounts of raw egg white can therefore contribute to biotin deficiency. Cooking denatures avidin, greatly reducing its ability to bind biotin, which is why this problem is primarily associated with raw egg whites.","whyWrongChoices":"Alternative options: Albumin, Vitelline, Ovomucin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:keshan disease is a condition characterized by heart enlargement and is caused by deficiency of what nutrient?:::selenium', 'keshan disease is a condition characterized by heart enlargement and is caused by deficiency of what nutrient?', 'Selenium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Keshan disease is a form of cardiomyopathy associated with severe selenium deficiency, originally described in areas of China with selenium-poor soil. It can cause cardiac enlargement, impaired cardiac function, and potentially heart failure. Selenium is important for antioxidant defense through selenoproteins such as glutathione peroxidases, which help protect tissues from oxidative damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Selenium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Keshan disease is a form of cardiomyopathy associated with severe selenium deficiency, originally described in areas of China with selenium-poor soil. It can cause cardiac enlargement, impaired cardiac function, and potentially heart failure. Selenium is important for antioxidant defense through selenoproteins such as glutathione peroxidases, which help protect tissues from oxidative damage.","whyWrongChoices":"Alternative options: Zinc, Calcium, Potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:keshan disease is a condition characterized by heart enlargement and is caused by deficiency of what nutrient?:::', 'keshan disease is a condition characterized by heart enlargement and is caused by deficiency of what nutrient?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Keshan disease is a form of cardiomyopathy associated with severe selenium deficiency, originally described in areas of China with selenium-poor soil. It can cause cardiac enlargement, impaired cardiac function, and potentially heart failure. Selenium is important for antioxidant defense through selenoproteins such as glutathione peroxidases, which help protect tissues from oxidative damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Selenium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Keshan disease is a form of cardiomyopathy associated with severe selenium deficiency, originally described in areas of China with selenium-poor soil. It can cause cardiac enlargement, impaired cardiac function, and potentially heart failure. Selenium is important for antioxidant defense through selenoproteins such as glutathione peroxidases, which help protect tissues from oxidative damage.","whyWrongChoices":"Alternative options: Zinc, Calcium, Potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foods to avoid when preparing a patient for a test for occult blood in the stool::::meat and leafy vegetables', 'foods to avoid when preparing a patient for a test for occult blood in the stool:', 'Meat and leafy vegetables', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For the traditional guaiac-based fecal occult blood test (gFOBT), patients may be instructed to avoid red meat and certain vegetables, particularly those containing peroxidase activity, because they can produce false-positive results. Examples include some leafy and cruciferous vegetables. This dietary restriction is specific to guaiac-based testing; newer fecal immunochemical tests (FIT) detect human hemoglobin and generally do not require these dietary restrictions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Meat and leafy vegetables\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For the traditional guaiac-based fecal occult blood test (gFOBT), patients may be instructed to avoid red meat and certain vegetables, particularly those containing peroxidase activity, because they can produce false-positive results. Examples include some leafy and cruciferous vegetables. This dietary restriction is specific to guaiac-based testing; newer fecal immunochemical tests (FIT) detect human hemoglobin and generally do not require these dietary restrictions.","whyWrongChoices":"Alternative options: Milk and cheese, Acidic fruits, Excessive fat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when a person is stressed, the secretion of the following hormones is increased except::::insulin', 'when a person is stressed, the secretion of the following hormones is increased except:', 'Insulin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During physiological stress, the body enters a catabolic, hypermetabolic state designed to ensure adequate fuel availability. Glucagon, cortisol, and catecholamines increase and promote glycogenolysis, gluconeogenesis, lipolysis, and mobilization of energy substrates. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Insulin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During physiological stress, the body enters a catabolic, hypermetabolic state designed to ensure adequate fuel availability. Glucagon, cortisol, and catecholamines increase and promote glycogenolysis, gluconeogenesis, lipolysis, and mobilization of energy substrates. \n\nInsulin secretion is generally suppressed or its action is reduced (insulin resistance) during the stress response, helping maintain elevated blood glucose for tissues with high energy demands.","whyWrongChoices":"Alternative options: Glucagon, Cortisol, Catecholamines"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foods to avoid when preparing a patient for a test for occult blood in the stool::::', 'foods to avoid when preparing a patient for a test for occult blood in the stool:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For the traditional guaiac-based fecal occult blood test (gFOBT), patients may be instructed to avoid red meat and certain vegetables, particularly those containing peroxidase activity, because they can produce false-positive results. Examples include some leafy and cruciferous vegetables. This dietary restriction is specific to guaiac-based testing; newer fecal immunochemical tests (FIT) detect human hemoglobin and generally do not require these dietary restrictions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Meat and leafy vegetables\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For the traditional guaiac-based fecal occult blood test (gFOBT), patients may be instructed to avoid red meat and certain vegetables, particularly those containing peroxidase activity, because they can produce false-positive results. Examples include some leafy and cruciferous vegetables. This dietary restriction is specific to guaiac-based testing; newer fecal immunochemical tests (FIT) detect human hemoglobin and generally do not require these dietary restrictions.","whyWrongChoices":"Alternative options: Milk and cheese, Acidic fruits, Excessive fat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:and are the major intracellular and extracellular cations in the body, respectively.:::potassium, sodium', 'and are the major intracellular and extracellular cations in the body, respectively.', 'Potassium, sodium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Potassium (K⁺) is the major cation inside cells (intracellular fluid), while sodium (Na⁺) is the major cation outside cells (extracellular fluid). Their concentration gradients are maintained largely by the sodium-potassium pump (Na⁺/K⁺-ATPase), which is essential for maintaining cell membrane potential, nerve transmission, and muscle contraction.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Potassium, sodium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Potassium (K⁺) is the major cation inside cells (intracellular fluid), while sodium (Na⁺) is the major cation outside cells (extracellular fluid). Their concentration gradients are maintained largely by the sodium-potassium pump (Na⁺/K⁺-ATPase), which is essential for maintaining cell membrane potential, nerve transmission, and muscle contraction.","whyWrongChoices":"Alternative options: Potassium, phosphate, Sodium, chloride, Sodium, potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:and are the major intracellular and extracellular cations in the body, respectively.:::', 'and are the major intracellular and extracellular cations in the body, respectively.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Potassium (K⁺) is the major cation inside cells (intracellular fluid), while sodium (Na⁺) is the major cation outside cells (extracellular fluid). Their concentration gradients are maintained largely by the sodium-potassium pump (Na⁺/K⁺-ATPase), which is essential for maintaining cell membrane potential, nerve transmission, and muscle contraction.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Potassium, sodium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Potassium (K⁺) is the major cation inside cells (intracellular fluid), while sodium (Na⁺) is the major cation outside cells (extracellular fluid). Their concentration gradients are maintained largely by the sodium-potassium pump (Na⁺/K⁺-ATPase), which is essential for maintaining cell membrane potential, nerve transmission, and muscle contraction.","whyWrongChoices":"Alternative options: Potassium, phosphate, Sodium, chloride, Sodium, potassium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary antioxidants: i. manganese ii. flavonoids iii. phenolic compounds:::all of the above', 'dietary antioxidants: i. manganese ii. flavonoids iii. phenolic compounds', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three can contribute to antioxidant defense. Manganese is an essential mineral that is part of the antioxidant enzyme manganese superoxide dismutase (MnSOD), which helps neutralize superoxide radicals in mitochondria. Flavonoids and phenolic compounds are plant-derived phytochemicals that can have antioxidant activity by scavenging reactive species and influencing antioxidant pathways.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three can contribute to antioxidant defense. Manganese is an essential mineral that is part of the antioxidant enzyme manganese superoxide dismutase (MnSOD), which helps neutralize superoxide radicals in mitochondria. Flavonoids and phenolic compounds are plant-derived phytochemicals that can have antioxidant activity by scavenging reactive species and influencing antioxidant pathways.","whyWrongChoices":"Alternative options: I only, I and II only, II and III only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary antioxidants: i. manganese ii. flavonoids iii. phenolic compounds:::', 'dietary antioxidants: i. manganese ii. flavonoids iii. phenolic compounds', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three can contribute to antioxidant defense. Manganese is an essential mineral that is part of the antioxidant enzyme manganese superoxide dismutase (MnSOD), which helps neutralize superoxide radicals in mitochondria. Flavonoids and phenolic compounds are plant-derived phytochemicals that can have antioxidant activity by scavenging reactive species and influencing antioxidant pathways.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three can contribute to antioxidant defense. Manganese is an essential mineral that is part of the antioxidant enzyme manganese superoxide dismutase (MnSOD), which helps neutralize superoxide radicals in mitochondria. Flavonoids and phenolic compounds are plant-derived phytochemicals that can have antioxidant activity by scavenging reactive species and influencing antioxidant pathways.","whyWrongChoices":"Alternative options: I only, I and II only, II and III only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this phytochemical, which is usually found in red wines and peanuts, prevents artery-damaging effects of high fat diets.:::resveratrol', 'this phytochemical, which is usually found in red wines and peanuts, prevents artery-damaging effects of high fat diets.', 'Resveratrol', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Resveratrol is a polyphenolic compound found in the skin of red grapes and therefore in red wine, as well as in peanuts and some other plants. It has been studied for potential cardiovascular benefits through antioxidant, anti-inflammatory, and endothelial effects. The original wording that it “prevents” artery damage is too absolute; resveratrol is better described as a phytochemical associated with potentially protective cardiovascular effects.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Resveratrol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Resveratrol is a polyphenolic compound found in the skin of red grapes and therefore in red wine, as well as in peanuts and some other plants. It has been studied for potential cardiovascular benefits through antioxidant, anti-inflammatory, and endothelial effects. The original wording that it “prevents” artery damage is too absolute; resveratrol is better described as a phytochemical associated with potentially protective cardiovascular effects.","whyWrongChoices":"Alternative options: Tannis, Phenols, Isoflavones"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this phytochemical, which is usually found in red wines and peanuts, prevents artery-damaging effects of high fat diets.:::', 'this phytochemical, which is usually found in red wines and peanuts, prevents artery-damaging effects of high fat diets.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Resveratrol is a polyphenolic compound found in the skin of red grapes and therefore in red wine, as well as in peanuts and some other plants. It has been studied for potential cardiovascular benefits through antioxidant, anti-inflammatory, and endothelial effects. The original wording that it “prevents” artery damage is too absolute; resveratrol is better described as a phytochemical associated with potentially protective cardiovascular effects.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Resveratrol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Resveratrol is a polyphenolic compound found in the skin of red grapes and therefore in red wine, as well as in peanuts and some other plants. It has been studied for potential cardiovascular benefits through antioxidant, anti-inflammatory, and endothelial effects. The original wording that it “prevents” artery damage is too absolute; resveratrol is better described as a phytochemical associated with potentially protective cardiovascular effects.","whyWrongChoices":"Alternative options: Tannis, Phenols, Isoflavones"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:prolonged calorie undernutrition can cause a 20-30% decrease in bmr. habitual high energy intake also decrease bmr.:::only statement 1 is correct', 'prolonged calorie undernutrition can cause a 20-30% decrease in bmr. habitual high energy intake also decrease bmr.', 'Only statement 1 is correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Prolonged energy restriction can reduce basal metabolic rate (BMR) through metabolic adaptation, including reduced thermogenesis and changes in metabolically active tissues and endocrine function. A decrease of approximately 20–30% has been described in severe or prolonged energy restriction. In contrast, habitual high energy intake does not decrease BMR; increased energy intake may increase diet-induced thermogenesis and total energy expenditure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Only statement 1 is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Prolonged energy restriction can reduce basal metabolic rate (BMR) through metabolic adaptation, including reduced thermogenesis and changes in metabolically active tissues and endocrine function. A decrease of approximately 20–30% has been described in severe or prolonged energy restriction. In contrast, habitual high energy intake does not decrease BMR; increased energy intake may increase diet-induced thermogenesis and total energy expenditure.","whyWrongChoices":"Alternative options: Only statement 2 is correct, Both statement are correct, Both statement are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:prolonged calorie undernutrition can cause a 20-30% decrease in bmr. habitual high energy intake also decrease bmr.:::', 'prolonged calorie undernutrition can cause a 20-30% decrease in bmr. habitual high energy intake also decrease bmr.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Prolonged energy restriction can reduce basal metabolic rate (BMR) through metabolic adaptation, including reduced thermogenesis and changes in metabolically active tissues and endocrine function. A decrease of approximately 20–30% has been described in severe or prolonged energy restriction. In contrast, habitual high energy intake does not decrease BMR; increased energy intake may increase diet-induced thermogenesis and total energy expenditure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Only statement 1 is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Prolonged energy restriction can reduce basal metabolic rate (BMR) through metabolic adaptation, including reduced thermogenesis and changes in metabolically active tissues and endocrine function. A decrease of approximately 20–30% has been described in severe or prolonged energy restriction. In contrast, habitual high energy intake does not decrease BMR; increased energy intake may increase diet-induced thermogenesis and total energy expenditure.","whyWrongChoices":"Alternative options: Only statement 2 is correct, Both statement are correct, Both statement are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for parkinson’s disease i. adjust food consistency to facilitate chewing and swallowing; ensure adequate fiber and fluid intake; limit dietary protein at breakfast and lunch in patients receiving levodopa therapy when indicated; avoid foods or supplements containing large amounts of l-dopa. ii. adjust food consistency according to tolerance; provide nutrient-dense foods; and offer small, frequent meals.:::', 'dietary management for parkinson’s disease i. adjust food consistency to facilitate chewing and swallowing; ensure adequate fiber and fluid intake; limit dietary protein at breakfast and lunch in patients receiving levodopa therapy when indicated; avoid foods or supplements containing large amounts of l-dopa. ii. adjust food consistency according to tolerance; provide nutrient-dense foods; and offer small, frequent meals.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both statements accurately outline essential, standard clinical protocols for managing a patient with Parkinson''s Disease (PD):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both statements accurately outline essential, standard clinical protocols for managing a patient with Parkinson''s Disease (PD):\n\n\t• Dysphagia & Constipation: As PD progresses, motor degradation often leads to chewing and swallowing difficulties (dysphagia), requiring textured food or modified consistencies. Autonomic dysfunction also slows down the GI tract, making a high-fiber and high-fluid regimen critical to preventing chronic constipation.\n\t• The Protein-Levodopa Interaction: Levodopa (the primary medication for PD) utilizes the same active transport carriers across the blood-brain barrier as dietary amino acids. Limiting or shifting protein intake away from breakfast and lunch prevents dietary protein from competing with the medication, ensuring the drug maintains its clinical efficacy throughout the day.\n\t• Exogenous L-dopa: Avoiding foods/supplements with variable amounts of natural L-dopa (like fava beans) prevents unpredictable fluctuations or sudden toxicity.\n\n\t• Malnutrition & Early Satiety: Due to tremors, high metabolic demands, and slow chewing, PD patients are exceptionally prone to unintentional weight loss and muscle wasting. Offering small, frequent, and nutrient-dense meals tailored to their structural texture tolerance optimizes daily caloric intake without overwhelming the patient or causing early fatigue during meals.","whyWrongChoices":"Alternative options: I only, II only, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are characteristics of hypothyroidism except::::', 'the following are characteristics of hypothyroidism except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cold intolerance, bradycardia, and constipation are all classic manifestations of hypothyroidism. Reduced thyroid hormone slows metabolic activity and affects multiple body systems. Patients may also experience fatigue, weight gain, dry skin, and slowed mental and physical activity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"none of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cold intolerance, bradycardia, and constipation are all classic manifestations of hypothyroidism. Reduced thyroid hormone slows metabolic activity and affects multiple body systems. Patients may also experience fatigue, weight gain, dry skin, and slowed mental and physical activity.","whyWrongChoices":"Alternative options: cold intolerance, bradycardia, constipation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when a person is stressed, the secretion of the following hormones is increased except::::', 'when a person is stressed, the secretion of the following hormones is increased except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During physiological stress, the body enters a catabolic, hypermetabolic state designed to ensure adequate fuel availability. Glucagon, cortisol, and catecholamines increase and promote glycogenolysis, gluconeogenesis, lipolysis, and mobilization of energy substrates. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Insulin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During physiological stress, the body enters a catabolic, hypermetabolic state designed to ensure adequate fuel availability. Glucagon, cortisol, and catecholamines increase and promote glycogenolysis, gluconeogenesis, lipolysis, and mobilization of energy substrates. \n\nInsulin secretion is generally suppressed or its action is reduced (insulin resistance) during the stress response, helping maintain elevated blood glucose for tissues with high energy demands.","whyWrongChoices":"Alternative options: Glucagon, Cortisol, Catecholamines"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:are responsible for cell-mediated immunity while are responsible for humoral immunity.:::t cells, b cells', 'are responsible for cell-mediated immunity while are responsible for humoral immunity.', 'T cells, B cells', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"T lymphocytes are primarily responsible for cell-mediated immunity, including direct killing of infected or abnormal cells and coordination of immune responses. B lymphocytes are responsible for humoral immunity through their differentiation into plasma cells that produce antibodies.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"T cells, B cells\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"T lymphocytes are primarily responsible for cell-mediated immunity, including direct killing of infected or abnormal cells and coordination of immune responses. B lymphocytes are responsible for humoral immunity through their differentiation into plasma cells that produce antibodies.","whyWrongChoices":"Alternative options: B cells, T cells, Macrophages, B cells, B cells, macrophages"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:are responsible for cell-mediated immunity while are responsible for humoral immunity.:::', 'are responsible for cell-mediated immunity while are responsible for humoral immunity.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"T lymphocytes are primarily responsible for cell-mediated immunity, including direct killing of infected or abnormal cells and coordination of immune responses. B lymphocytes are responsible for humoral immunity through their differentiation into plasma cells that produce antibodies.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"T cells, B cells\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"T lymphocytes are primarily responsible for cell-mediated immunity, including direct killing of infected or abnormal cells and coordination of immune responses. B lymphocytes are responsible for humoral immunity through their differentiation into plasma cells that produce antibodies.","whyWrongChoices":"Alternative options: B cells, T cells, Macrophages, B cells, B cells, macrophages"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:electron-carrier molecules that are used in the electron-transport chain to generate additional atp are::::nadh and fadh₂', 'electron-carrier molecules that are used in the electron-transport chain to generate additional atp are:', 'NADH and FADH₂', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"NADH and FADH₂ are reduced electron carriers that transport high-energy electrons to the electron transport chain (ETC) in the inner mitochondrial membrane. As electrons pass through the ETC, the released energy drives proton pumping, creating a proton gradient that powers ATP synthase to produce ATP through oxidative phosphorylation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"NADH and FADH₂\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"NADH and FADH₂ are reduced electron carriers that transport high-energy electrons to the electron transport chain (ETC) in the inner mitochondrial membrane. As electrons pass through the ETC, the released energy drives proton pumping, creating a proton gradient that powers ATP synthase to produce ATP through oxidative phosphorylation.","whyWrongChoices":"Alternative options: Glucose and ketone bodies, Pyruvic acid and lactic acid, Acetyl CoA and amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the specific amount of product from the recipe in volume, weight, or number of servings.:::', 'the specific amount of product from the recipe in volume, weight, or number of servings.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Yield is the specific amount of finished product obtained from a recipe, expressed as weight, volume, or number of portions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"yield\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Yield is the specific amount of finished product obtained from a recipe, expressed as weight, volume, or number of portions.","whyWrongChoices":"Alternative options: trim loss, edible portion, yield factor"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
