INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a carbohydrate-rich diet may require more of which of the following vitamins?:::thiamin', 'a carbohydrate-rich diet may require more of which of the following vitamins?', 'thiamin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Thiamin (vitamin B1) is particularly important in carbohydrate metabolism. Its active form, thiamin pyrophosphate (TPP), functions as a coenzyme for several enzymes involved in glucose oxidation, including:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thiamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Thiamin (vitamin B1) is particularly important in carbohydrate metabolism. Its active form, thiamin pyrophosphate (TPP), functions as a coenzyme for several enzymes involved in glucose oxidation, including:\n\n• Pyruvate dehydrogenase\n• α-Ketoglutarate dehydrogenase\n• Transketolase\n\nBecause carbohydrate metabolism increases when carbohydrate intake and utilization are high, an inadequate thiamin supply can become more clinically relevant. Thus, a carbohydrate-rich diet may increase the need for thiamin, particularly when carbohydrate intake is very high and the diet is otherwise nutrient-poor.","whyWrongChoices":"Alternative options: riboflavin, vitamin c, niacin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a carbohydrate-rich diet may require more of which of the following vitamins?:::', 'a carbohydrate-rich diet may require more of which of the following vitamins?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Thiamin (vitamin B1) is particularly important in carbohydrate metabolism. Its active form, thiamin pyrophosphate (TPP), functions as a coenzyme for several enzymes involved in glucose oxidation, including:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thiamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Thiamin (vitamin B1) is particularly important in carbohydrate metabolism. Its active form, thiamin pyrophosphate (TPP), functions as a coenzyme for several enzymes involved in glucose oxidation, including:\n\n• Pyruvate dehydrogenase\n• α-Ketoglutarate dehydrogenase\n• Transketolase\n\nBecause carbohydrate metabolism increases when carbohydrate intake and utilization are high, an inadequate thiamin supply can become more clinically relevant. Thus, a carbohydrate-rich diet may increase the need for thiamin, particularly when carbohydrate intake is very high and the diet is otherwise nutrient-poor.","whyWrongChoices":"Alternative options: riboflavin, vitamin c, niacin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an athlete who consumes a high-protein diet would have an increased need of which of the following vitamins?:::vit b6', 'an athlete who consumes a high-protein diet would have an increased need of which of the following vitamins?', 'vit b6', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin B6 is closely involved in amino acid and protein metabolism. Its active coenzyme form, pyridoxal 5′-phosphate (PLP), is required for numerous reactions involving amino acids, including transamination, decarboxylation, and other amino acid transformations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vit b6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin B6 is closely involved in amino acid and protein metabolism. Its active coenzyme form, pyridoxal 5′-phosphate (PLP), is required for numerous reactions involving amino acids, including transamination, decarboxylation, and other amino acid transformations.\n\nTherefore, when protein intake and amino acid metabolism increase, the need for vitamin B6 may also increase. This is the classic nutrition relationship tested by this question:\n\nHigher protein intake → increased amino acid metabolism → greater need for vitamin B6.\n\nHowever, an important modern nuance is that athletes do not automatically require B6 supplementation simply because they consume a high-protein diet. Adequate dietary intake generally meets requirements, and supplementation should not be routinely recommended without evidence of inadequate intake or deficiency.","whyWrongChoices":"Alternative options: niacin, vit b12, vit c"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a correct pes statement?:::hypertension related to age as evidenced by 160/100 mmhg', 'which of the following is not a correct pes statement?', 'Hypertension related to age as evidenced by 160/100 mmHg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Age is not a modifiable nutrition-related etiology. PES statements must link to nutrition problems the dietitian can address.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hypertension related to age as evidenced by 160/100 mmHg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Age is not a modifiable nutrition-related etiology. PES statements must link to nutrition problems the dietitian can address.","whyWrongChoices":"Alternative options: Inadequate oral intake related to poor appetite as evidenced by, Altered nutrition-related laboratory values related to uncontrolled diabetes as evidenced by FBS 300 mg/dL, Impaired nutrient utilization related to pancreatic insufficiency as evidenced by steatorrhea"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an athlete who consumes a high-protein diet would have an increased need of which of the following vitamins?:::', 'an athlete who consumes a high-protein diet would have an increased need of which of the following vitamins?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin B6 is closely involved in amino acid and protein metabolism. Its active coenzyme form, pyridoxal 5′-phosphate (PLP), is required for numerous reactions involving amino acids, including transamination, decarboxylation, and other amino acid transformations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"vit b6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin B6 is closely involved in amino acid and protein metabolism. Its active coenzyme form, pyridoxal 5′-phosphate (PLP), is required for numerous reactions involving amino acids, including transamination, decarboxylation, and other amino acid transformations.\n\nTherefore, when protein intake and amino acid metabolism increase, the need for vitamin B6 may also increase. This is the classic nutrition relationship tested by this question:\n\nHigher protein intake → increased amino acid metabolism → greater need for vitamin B6.\n\nHowever, an important modern nuance is that athletes do not automatically require B6 supplementation simply because they consume a high-protein diet. Adequate dietary intake generally meets requirements, and supplementation should not be routinely recommended without evidence of inadequate intake or deficiency.","whyWrongChoices":"Alternative options: niacin, vit b12, vit c"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:used to limit the migration of moisture into the product.:::', 'used to limit the migration of moisture into the product.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Packaging can act as a moisture barrier and limit the migration of moisture into or out of a food product. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Packaging\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Packaging can act as a moisture barrier and limit the migration of moisture into or out of a food product. \n\nHeating, freezing, and drying change the product but do not primarily provide a barrier.","whyWrongChoices":"Alternative options: Heating, Drying, Freezing"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements about folate is/are true?:::all of the above', 'which of the following statements about folate is/are true?', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three statements describe established roles of folate (vitamin B9), although B requires an important modern clarification regarding cardiovascular disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three statements describe established roles of folate (vitamin B9), although B requires an important modern clarification regarding cardiovascular disease.\n\nA. Neural tube defects: Folate is essential for DNA and nucleotide synthesis and cell division. Adequate folate before conception and during early pregnancy substantially reduces the risk of neural tube defects (NTDs). This is why folic acid supplementation is recommended for women who could become pregnant.\n\nB. Homocysteine: Folate participates in the remethylation of homocysteine to methionine, a reaction that also requires vitamin B12. Folate deficiency can therefore contribute to elevated plasma homocysteine. Elevated homocysteine is associated epidemiologically with cardiovascular disease; however, lowering homocysteine with folic acid supplementation has not consistently been shown to reduce coronary heart disease events. Thus, the statement is correct regarding the biochemical relationship and association, but it should not be interpreted as proof that folic acid supplementation prevents CHD.\n\nC. Folate and vitamin B12: Folate and vitamin B12 work together in one-carbon metabolism and DNA synthesis. Deficiency of either nutrient can impair DNA synthesis and produce megaloblastic/macrocytic anemia.","whyWrongChoices":"Alternative options: Folic acid supplementation is recommended for women of childbearing potential because it is necessary for nucleic acid synthesis and may help prevent neural tube defects., Folate influences plasma homocysteine concentrations, and elevated homocysteine is associated with increased cardiovascular disease risk., Folate works together with vitamin B12 (cyanocobalamin) in pathways important for preventing megaloblastic anemia."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements about folate is/are true?:::', 'which of the following statements about folate is/are true?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three statements describe established roles of folate (vitamin B9), although B requires an important modern clarification regarding cardiovascular disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three statements describe established roles of folate (vitamin B9), although B requires an important modern clarification regarding cardiovascular disease.\n\nA. Neural tube defects: Folate is essential for DNA and nucleotide synthesis and cell division. Adequate folate before conception and during early pregnancy substantially reduces the risk of neural tube defects (NTDs). This is why folic acid supplementation is recommended for women who could become pregnant.\n\nB. Homocysteine: Folate participates in the remethylation of homocysteine to methionine, a reaction that also requires vitamin B12. Folate deficiency can therefore contribute to elevated plasma homocysteine. Elevated homocysteine is associated epidemiologically with cardiovascular disease; however, lowering homocysteine with folic acid supplementation has not consistently been shown to reduce coronary heart disease events. Thus, the statement is correct regarding the biochemical relationship and association, but it should not be interpreted as proof that folic acid supplementation prevents CHD.\n\nC. Folate and vitamin B12: Folate and vitamin B12 work together in one-carbon metabolism and DNA synthesis. Deficiency of either nutrient can impair DNA synthesis and produce megaloblastic/macrocytic anemia.","whyWrongChoices":"Alternative options: Folic acid supplementation is recommended for women of childbearing potential because it is necessary for nucleic acid synthesis and may help prevent neural tube defects., Folate influences plasma homocysteine concentrations, and elevated homocysteine is associated with increased cardiovascular disease risk., Folate works together with vitamin B12 (cyanocobalamin) in pathways important for preventing megaloblastic anemia."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during prolonged, high intensity physical activity, the muscle''s consumption of oxygen increases tenfold or more, enhancing the production of damaging free radicals in the body. which of the following vitamins-mineral combinations would be potent on defending the cell membranes against oxidative stress?:::vitamin e, retinol, ascorbate, and selenium', 'during prolonged, high intensity physical activity, the muscle''s consumption of oxygen increases tenfold or more, enhancing the production of damaging free radicals in the body. which of the following vitamins-mineral combinations would be potent on defending the cell membranes against oxidative stress?', 'Vitamin E, retinol, ascorbate, and selenium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the best answer because it combines several nutrients with established antioxidant roles:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin E, retinol, ascorbate, and selenium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the best answer because it combines several nutrients with established antioxidant roles:\n\n• Vitamin E (tocopherol) is the major lipid-soluble antioxidant and is particularly important in protecting cell membranes from lipid peroxidation.\n• Vitamin C (ascorbate) is a major water-soluble antioxidant and can help regenerate oxidized vitamin E.\n• Vitamin A/retinoids have antioxidant-related functions, although the antioxidant activity of vitamin A is less central than that of vitamin E.\n• Selenium is an essential component of glutathione peroxidases, antioxidant enzymes that help reduce hydrogen peroxide and lipid hydroperoxides.\n\nThus, among the choices, this provides the strongest combination of antioxidant nutrients, particularly for membrane protection.","whyWrongChoices":"Alternative options: Tocopherol, thiamin, ascorbate, and iron, Ascorbate, retinol, pyridoxal, and selenium, Vitamin C, Vitamin A, Vitamin B6, and zinc"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:taters refer to::::', 'taters refer to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"\"Taters\" is a casual, colloquial slang term derived from the word \"potatoes\" (commonly used in phrases like tater tots or mashed taters).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Potatoes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"\"Taters\" is a casual, colloquial slang term derived from the word \"potatoes\" (commonly used in phrases like tater tots or mashed taters).","whyWrongChoices":"Alternative options: Chips, Popcorn, Shrimp"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:during prolonged, high intensity physical activity, the muscle''s consumption of oxygen increases tenfold or more, enhancing the production of damaging free radicals in the body. which of the following vitamins-mineral combinations would be potent on defending the cell membranes against oxidative stress?:::', 'during prolonged, high intensity physical activity, the muscle''s consumption of oxygen increases tenfold or more, enhancing the production of damaging free radicals in the body. which of the following vitamins-mineral combinations would be potent on defending the cell membranes against oxidative stress?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the best answer because it combines several nutrients with established antioxidant roles:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin E, retinol, ascorbate, and selenium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the best answer because it combines several nutrients with established antioxidant roles:\n\n• Vitamin E (tocopherol) is the major lipid-soluble antioxidant and is particularly important in protecting cell membranes from lipid peroxidation.\n• Vitamin C (ascorbate) is a major water-soluble antioxidant and can help regenerate oxidized vitamin E.\n• Vitamin A/retinoids have antioxidant-related functions, although the antioxidant activity of vitamin A is less central than that of vitamin E.\n• Selenium is an essential component of glutathione peroxidases, antioxidant enzymes that help reduce hydrogen peroxide and lipid hydroperoxides.\n\nThus, among the choices, this provides the strongest combination of antioxidant nutrients, particularly for membrane protection.","whyWrongChoices":"Alternative options: Tocopherol, thiamin, ascorbate, and iron, Ascorbate, retinol, pyridoxal, and selenium, Vitamin C, Vitamin A, Vitamin B6, and zinc"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a systematic head-to-toe examination of patient''s physical appearance and function to help determine nutrtional status by uncovering any signs of malnutrition, nutrient deficiencies or nutrient toxicities.:::nutrition focused physical assessment', 'is a systematic head-to-toe examination of patient''s physical appearance and function to help determine nutrtional status by uncovering any signs of malnutrition, nutrient deficiencies or nutrient toxicities.', 'nutrition focused physical assessment', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition-Focused Physical Assessment (NFPA) is a systematic physical examination performed by a nutrition professional to identify physical signs and symptoms associated with malnutrition, nutrient deficiencies, excesses, and other nutrition-related conditions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nutrition focused physical assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition-Focused Physical Assessment (NFPA) is a systematic physical examination performed by a nutrition professional to identify physical signs and symptoms associated with malnutrition, nutrient deficiencies, excesses, and other nutrition-related conditions.\n\nIt is an important component of the Nutrition Assessment step of the Nutrition Care Process. The examination may include observation, palpation, and assessment of areas such as:\n• Muscle stores — e.g., temples, clavicles, shoulders, scapulae, interosseous muscles\n• Subcutaneous fat stores — e.g., orbital region, triceps, ribs\n• Skin, hair, and nails\n• Eyes and oral cavity\n• Edema and fluid accumulation\n• Functional findings, when appropriate\n\nImportantly, NFPA is not used in isolation to diagnose malnutrition. It is integrated with dietary history, anthropometric data, biochemical/medical information, and other relevant findings.","whyWrongChoices":"Alternative options: body composition analyzer, indirect calorimter, CT-scan with contrast"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a systematic head-to-toe examination of patient''s physical appearance and function to help determine nutrtional status by uncovering any signs of malnutrition, nutrient deficiencies or nutrient toxicities.:::', 'is a systematic head-to-toe examination of patient''s physical appearance and function to help determine nutrtional status by uncovering any signs of malnutrition, nutrient deficiencies or nutrient toxicities.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition-Focused Physical Assessment (NFPA) is a systematic physical examination performed by a nutrition professional to identify physical signs and symptoms associated with malnutrition, nutrient deficiencies, excesses, and other nutrition-related conditions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nutrition focused physical assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition-Focused Physical Assessment (NFPA) is a systematic physical examination performed by a nutrition professional to identify physical signs and symptoms associated with malnutrition, nutrient deficiencies, excesses, and other nutrition-related conditions.\n\nIt is an important component of the Nutrition Assessment step of the Nutrition Care Process. The examination may include observation, palpation, and assessment of areas such as:\n• Muscle stores — e.g., temples, clavicles, shoulders, scapulae, interosseous muscles\n• Subcutaneous fat stores — e.g., orbital region, triceps, ribs\n• Skin, hair, and nails\n• Eyes and oral cavity\n• Edema and fluid accumulation\n• Functional findings, when appropriate\n\nImportantly, NFPA is not used in isolation to diagnose malnutrition. It is integrated with dietary history, anthropometric data, biochemical/medical information, and other relevant findings.","whyWrongChoices":"Alternative options: body composition analyzer, indirect calorimter, CT-scan with contrast"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:route of access for patients with normal gi function and intact gag reflex.:::nasogastric tube', 'route of access for patients with normal gi function and intact gag reflex.', 'nasogastric tube', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A nasogastric (NG) tube is an appropriate route for short-term enteral nutrition when the GI tract is functional and the patient has an intact gag/cough reflex and can protect the airway.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nasogastric tube\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A nasogastric (NG) tube is an appropriate route for short-term enteral nutrition when the GI tract is functional and the patient has an intact gag/cough reflex and can protect the airway.\n\nAn NG tube is inserted through the nose into the stomach, allowing delivery of enteral formula directly into the stomach.\n\nIn general, short-term enteral feeding is commonly delivered through a nasogastric or nasoenteric tube, whereas longer-term feeding may require an enterostomy such as a gastrostomy or jejunostomy.","whyWrongChoices":"Alternative options: enterostomy, multiple lumen tube, gastrotomy tube"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:route of access for patients with normal gi function and intact gag reflex.:::', 'route of access for patients with normal gi function and intact gag reflex.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A nasogastric (NG) tube is an appropriate route for short-term enteral nutrition when the GI tract is functional and the patient has an intact gag/cough reflex and can protect the airway.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nasogastric tube\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A nasogastric (NG) tube is an appropriate route for short-term enteral nutrition when the GI tract is functional and the patient has an intact gag/cough reflex and can protect the airway.\n\nAn NG tube is inserted through the nose into the stomach, allowing delivery of enteral formula directly into the stomach.\n\nIn general, short-term enteral feeding is commonly delivered through a nasogastric or nasoenteric tube, whereas longer-term feeding may require an enterostomy such as a gastrostomy or jejunostomy.","whyWrongChoices":"Alternative options: enterostomy, multiple lumen tube, gastrotomy tube"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how many grams of protein would be a 50kg, metabolically stable, non-dialyzed, adult male patient diagnosed with ckd stage 4 sec to diabetic kidney disease be needing per day?:::40g', 'how many grams of protein would be a 50kg, metabolically stable, non-dialyzed, adult male patient diagnosed with ckd stage 4 sec to diabetic kidney disease be needing per day?', '40g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For a metabolically stable adult with CKD stages 3–5 who is not on dialysis, current KDIGO guidance suggests a protein intake of approximately 0.8 g/kg body weight/day.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"40g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For a metabolically stable adult with CKD stages 3–5 who is not on dialysis, current KDIGO guidance suggests a protein intake of approximately 0.8 g/kg body weight/day.\n\nFor a 50-kg patient: 50 kg * 0.8 g/kg/day = 40 g/day\n\nTherefore, the best answer is 40 g protein/day. The key information in the question is:\n\nCKD Stage 4 → advanced CKD\nNot on dialysis → protein needs are not increased for dialysis-related losses\nMetabolically stable → the standard CKD protein recommendation applies\n50 kg → use body weight for the calculation","whyWrongChoices":"Alternative options: 15g, 30g, 50g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the process of providing individualized professional guidance to assisst persons in adjusting their daily food consumption to meet their health needs.:::nutrition counseling', 'the process of providing individualized professional guidance to assisst persons in adjusting their daily food consumption to meet their health needs.', 'Nutrition Counseling', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition counseling is the process of providing individualized guidance and support to help a person modify food choices, eating behaviors, and dietary practices to meet specific health or nutrition needs.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition Counseling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition counseling is the process of providing individualized guidance and support to help a person modify food choices, eating behaviors, and dietary practices to meet specific health or nutrition needs.\n\nIt is an important component of nutrition care and involves communication between the nutrition professional and the client. Counseling may address:\n\n• Food selection and meal planning\n• Eating patterns and behaviors\n• Portion sizes\n• Dietary modifications appropriate to health conditions\n• Barriers to dietary change\n• Strategies for achieving and maintaining behavior change\n\nThe emphasis is on individualized guidance and behavior change, rather than simply giving a standardized diet prescription.","whyWrongChoices":"Alternative options: Medical Nutrition Therapy, Mechanical Problems, Nutrition Diagnosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the process of providing individualized professional guidance to assisst persons in adjusting their daily food consumption to meet their health needs.:::', 'the process of providing individualized professional guidance to assisst persons in adjusting their daily food consumption to meet their health needs.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition counseling is the process of providing individualized guidance and support to help a person modify food choices, eating behaviors, and dietary practices to meet specific health or nutrition needs.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition Counseling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition counseling is the process of providing individualized guidance and support to help a person modify food choices, eating behaviors, and dietary practices to meet specific health or nutrition needs.\n\nIt is an important component of nutrition care and involves communication between the nutrition professional and the client. Counseling may address:\n\n• Food selection and meal planning\n• Eating patterns and behaviors\n• Portion sizes\n• Dietary modifications appropriate to health conditions\n• Barriers to dietary change\n• Strategies for achieving and maintaining behavior change\n\nThe emphasis is on individualized guidance and behavior change, rather than simply giving a standardized diet prescription.","whyWrongChoices":"Alternative options: Medical Nutrition Therapy, Mechanical Problems, Nutrition Diagnosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:designed for patients with impaired ability to ingest nutrient orally but has functioning git.:::enteral nutrition', 'designed for patients with impaired ability to ingest nutrient orally but has functioning git.', 'enteral nutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral nutrition (EN) is the preferred method of providing nutrition when the gastrointestinal tract is functional but oral intake is inadequate, unsafe, or impossible.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"enteral nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral nutrition (EN) is the preferred method of providing nutrition when the gastrointestinal tract is functional but oral intake is inadequate, unsafe, or impossible.\n\nEN delivers nutrients directly into the gastrointestinal tract, usually through a feeding tube such as a nasogastric, nasoenteric, gastrostomy, or jejunostomy tube.\n\nThe principle commonly emphasized in clinical nutrition is: “If the gut works, use it.”\n\nUsing the GI tract helps maintain gut integrity and function and is generally preferred over parenteral nutrition when feasible.","whyWrongChoices":"Alternative options: parental nutrition, a and b, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:designed for patients with impaired ability to ingest nutrient orally but has functioning git.:::', 'designed for patients with impaired ability to ingest nutrient orally but has functioning git.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral nutrition (EN) is the preferred method of providing nutrition when the gastrointestinal tract is functional but oral intake is inadequate, unsafe, or impossible.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"enteral nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral nutrition (EN) is the preferred method of providing nutrition when the gastrointestinal tract is functional but oral intake is inadequate, unsafe, or impossible.\n\nEN delivers nutrients directly into the gastrointestinal tract, usually through a feeding tube such as a nasogastric, nasoenteric, gastrostomy, or jejunostomy tube.\n\nThe principle commonly emphasized in clinical nutrition is: “If the gut works, use it.”\n\nUsing the GI tract helps maintain gut integrity and function and is generally preferred over parenteral nutrition when feasible.","whyWrongChoices":"Alternative options: parental nutrition, a and b, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a correct pes statement?:::', 'which of the following is not a correct pes statement?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Age is not a modifiable nutrition-related etiology. PES statements must link to nutrition problems the dietitian can address.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hypertension related to age as evidenced by 160/100 mmHg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Age is not a modifiable nutrition-related etiology. PES statements must link to nutrition problems the dietitian can address.","whyWrongChoices":"Alternative options: Inadequate oral intake related to poor appetite as evidenced by, Altered nutrition-related laboratory values related to uncontrolled diabetes as evidenced by FBS 300 mg/dL, Impaired nutrient utilization related to pancreatic insufficiency as evidenced by steatorrhea"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mr. jgh underwent a gastrectomy and is now on a clear liquid diet. which of the following beverages will mostly cause dumping syndrome?:::12 oz apple juice', 'mr. jgh underwent a gastrectomy and is now on a clear liquid diet. which of the following beverages will mostly cause dumping syndrome?', '12 oz apple juice', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Apple juice is the best answer because it provides a relatively high amount of rapidly absorbable carbohydrate (simple sugars) in liquid form. After gastrectomy, the normal reservoir function of the stomach is reduced, allowing hyperosmolar contents, particularly liquids containing concentrated sugars, to enter the small intestine rapidly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"12 oz apple juice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Apple juice is the best answer because it provides a relatively high amount of rapidly absorbable carbohydrate (simple sugars) in liquid form. After gastrectomy, the normal reservoir function of the stomach is reduced, allowing hyperosmolar contents, particularly liquids containing concentrated sugars, to enter the small intestine rapidly.\n\nThis can contribute to early dumping syndrome, which may produce abdominal cramping, bloating, nausea, diarrhea, tachycardia, flushing, and dizziness shortly after eating or drinking.\n\nThe large volume (12 oz ≈ 355 mL) also makes the apple juice a more likely trigger because rapid ingestion of a substantial volume of liquid can promote rapid gastric/small-intestinal delivery.","whyWrongChoices":"Alternative options: 2 cups strained chicken broth, 1 cup unsweetened jelly, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mr. jgh underwent a gastrectomy and is now on a clear liquid diet. which of the following beverages will mostly cause dumping syndrome?:::', 'mr. jgh underwent a gastrectomy and is now on a clear liquid diet. which of the following beverages will mostly cause dumping syndrome?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Apple juice is the best answer because it provides a relatively high amount of rapidly absorbable carbohydrate (simple sugars) in liquid form. After gastrectomy, the normal reservoir function of the stomach is reduced, allowing hyperosmolar contents, particularly liquids containing concentrated sugars, to enter the small intestine rapidly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"12 oz apple juice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Apple juice is the best answer because it provides a relatively high amount of rapidly absorbable carbohydrate (simple sugars) in liquid form. After gastrectomy, the normal reservoir function of the stomach is reduced, allowing hyperosmolar contents, particularly liquids containing concentrated sugars, to enter the small intestine rapidly.\n\nThis can contribute to early dumping syndrome, which may produce abdominal cramping, bloating, nausea, diarrhea, tachycardia, flushing, and dizziness shortly after eating or drinking.\n\nThe large volume (12 oz ≈ 355 mL) also makes the apple juice a more likely trigger because rapid ingestion of a substantial volume of liquid can promote rapid gastric/small-intestinal delivery.","whyWrongChoices":"Alternative options: 2 cups strained chicken broth, 1 cup unsweetened jelly, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient diagnosed with crohn''s disease and compromised distal ileum will benefit from which diet?:::vitamin b12 supplementation', 'a patient diagnosed with crohn''s disease and compromised distal ileum will benefit from which diet?', 'Vitamin B12 supplementation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The terminal (distal) ileum is the primary site for absorption of vitamin B12–intrinsic factor complexes. Crohn’s disease involving or requiring resection of the terminal ileum can therefore impair vitamin B12 absorption and increase the risk of vitamin B12 deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B12 supplementation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The terminal (distal) ileum is the primary site for absorption of vitamin B12–intrinsic factor complexes. Crohn’s disease involving or requiring resection of the terminal ileum can therefore impair vitamin B12 absorption and increase the risk of vitamin B12 deficiency.\n\nDepending on the extent of ileal disease or resection, patients may require vitamin B12 supplementation, sometimes by a parenteral route when adequate oral absorption cannot be relied upon.","whyWrongChoices":"Alternative options: Low-calorie diet, Low-protein diet, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient diagnosed with crohn''s disease and compromised distal ileum will benefit from which diet?:::', 'a patient diagnosed with crohn''s disease and compromised distal ileum will benefit from which diet?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The terminal (distal) ileum is the primary site for absorption of vitamin B12–intrinsic factor complexes. Crohn’s disease involving or requiring resection of the terminal ileum can therefore impair vitamin B12 absorption and increase the risk of vitamin B12 deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B12 supplementation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The terminal (distal) ileum is the primary site for absorption of vitamin B12–intrinsic factor complexes. Crohn’s disease involving or requiring resection of the terminal ileum can therefore impair vitamin B12 absorption and increase the risk of vitamin B12 deficiency.\n\nDepending on the extent of ileal disease or resection, patients may require vitamin B12 supplementation, sometimes by a parenteral route when adequate oral absorption cannot be relied upon.","whyWrongChoices":"Alternative options: Low-calorie diet, Low-protein diet, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following characterized cholelithiasis?:::hardened deposits in the gallbladder', 'which of the following characterized cholelithiasis?', 'Hardened deposits in the gallbladder', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cholelithiasis refers to the presence of gallstones (calculi) in the gallbladder. Gallstones form when components of bile, the most commonly cholesterol, but also bilirubin and calcium salts, precipitate and form solid particles.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hardened deposits in the gallbladder\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cholelithiasis refers to the presence of gallstones (calculi) in the gallbladder. Gallstones form when components of bile, the most commonly cholesterol, but also bilirubin and calcium salts, precipitate and form solid particles.\n\nGallstones may be asymptomatic or may cause biliary colic when they obstruct the cystic duct. If obstruction occurs elsewhere in the biliary tree, complications can include acute cholecystitis, choledocholithiasis, cholangitis, or gallstone pancreatitis.\n\nThe two major types of gallstones are:\n• Cholesterol stones — predominant in many populations.\n• Pigment stones — composed primarily of calcium bilirubinate and associated with conditions such as chronic hemolysis or biliary infection, depending on the type.","whyWrongChoices":"Alternative options: Hardened deposits in the pancreas, Scarring of the kidneys, Scarring of the lungs"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following characterized cholelithiasis?:::', 'which of the following characterized cholelithiasis?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cholelithiasis refers to the presence of gallstones (calculi) in the gallbladder. Gallstones form when components of bile, the most commonly cholesterol, but also bilirubin and calcium salts, precipitate and form solid particles.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hardened deposits in the gallbladder\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cholelithiasis refers to the presence of gallstones (calculi) in the gallbladder. Gallstones form when components of bile, the most commonly cholesterol, but also bilirubin and calcium salts, precipitate and form solid particles.\n\nGallstones may be asymptomatic or may cause biliary colic when they obstruct the cystic duct. If obstruction occurs elsewhere in the biliary tree, complications can include acute cholecystitis, choledocholithiasis, cholangitis, or gallstone pancreatitis.\n\nThe two major types of gallstones are:\n• Cholesterol stones — predominant in many populations.\n• Pigment stones — composed primarily of calcium bilirubinate and associated with conditions such as chronic hemolysis or biliary infection, depending on the type.","whyWrongChoices":"Alternative options: Hardened deposits in the pancreas, Scarring of the kidneys, Scarring of the lungs"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mrs. lobardo will be given an enteral formula with 1.5 kcal/ml at 60 ml x 16 hours. it contains 55 grams of protein per liter. how much kcal and grams of protein will be provided to the patient?:::1440 kcal and 53 g protein', 'mrs. lobardo will be given an enteral formula with 1.5 kcal/ml at 60 ml x 16 hours. it contains 55 grams of protein per liter. how much kcal and grams of protein will be provided to the patient?', '1440 kcal and 53 g protein', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step 1: Determine total volume administered: 60 mL/hour × 16 hours = 960 mL","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1440 kcal and 53 g protein\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step 1: Determine total volume administered: 60 mL/hour × 16 hours = 960 mL\n\nStep 2: Calculate energy: 960 mL × 1.5 kcal/mL = 1,440 kcal\n\nStep 3: Calculate protein: The formula contains 55 g protein/L.\n960 mL = 0.96 L\n0.96 L × 55 g/L = 52.8 g ≈ 53 g protein\n\nTherefore: 1,440 kcal + 53 g protein","whyWrongChoices":"Alternative options: 1690 kcal and 58 g protein, 1640 kcal and 58 g protein, 1580 kcal and 53 g protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mrs. lobardo will be given an enteral formula with 1.5 kcal/ml at 60 ml x 16 hours. it contains 55 grams of protein per liter. how much kcal and grams of protein will be provided to the patient?:::', 'mrs. lobardo will be given an enteral formula with 1.5 kcal/ml at 60 ml x 16 hours. it contains 55 grams of protein per liter. how much kcal and grams of protein will be provided to the patient?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step 1: Determine total volume administered: 60 mL/hour × 16 hours = 960 mL","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1440 kcal and 53 g protein\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step 1: Determine total volume administered: 60 mL/hour × 16 hours = 960 mL\n\nStep 2: Calculate energy: 960 mL × 1.5 kcal/mL = 1,440 kcal\n\nStep 3: Calculate protein: The formula contains 55 g protein/L.\n960 mL = 0.96 L\n0.96 L × 55 g/L = 52.8 g ≈ 53 g protein\n\nTherefore: 1,440 kcal + 53 g protein","whyWrongChoices":"Alternative options: 1690 kcal and 58 g protein, 1640 kcal and 58 g protein, 1580 kcal and 53 g protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient is receiving 250 mls of a 20% aa solution and 250 mls of 10% lipid emulsion. what is the total kcal provided?:::475 kcal', 'a patient is receiving 250 mls of a 20% aa solution and 250 mls of 10% lipid emulsion. what is the total kcal provided?', '475 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For PN calculations, the conventional values are:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"475 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For PN calculations, the conventional values are:\n\nAmino acids: 4 kcal/g\nDextrose: 3.4 kcal/g\nIV lipid emulsion: 10 kcal/g\n\nProtein: 20% AA, 250 mL:\n250 mL × 20 g/100 mL = 50 g AA => 50 g × 4 kcal/g = 200 kcal\n\nLipids: 10% lipid emulsion, 250 mL:\n250 mL × 10 g/100 mL = 25 g lipid => 25 g × 10 kcal/g = 250 kcal\n\nTotal = 200 + 250 = 450 kcal","whyWrongChoices":"Alternative options: 450 kcal, 550 kcal, 555 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which among the branched chain amino acid is/are the most important neurotoxic metabolite in msud? which among the branched chain acid is/are required to be supplemented to control the plasma level of the said toxic.:::leucine; isoleucine and valine', 'which among the branched chain amino acid is/are the most important neurotoxic metabolite in msud? which among the branched chain acid is/are required to be supplemented to control the plasma level of the said toxic.', 'leucine;  isoleucine and valine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In MSUD, there is deficient activity of the branched-chain α-ketoacid dehydrogenase (BCKDH) complex, which normally metabolizes the branched-chain amino acids (BCAAs):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"leucine;  isoleucine and valine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In MSUD, there is deficient activity of the branched-chain α-ketoacid dehydrogenase (BCKDH) complex, which normally metabolizes the branched-chain amino acids (BCAAs):\n• Leucine\n• Isoleucine\n• Valine\n\nConsequently, both the BCAAs and their corresponding branched-chain α-ketoacids accumulate.\n\nAmong the three BCAAs, leucine is particularly important in the neurologic toxicity of MSUD. Markedly elevated plasma leucine is associated with cerebral edema and neurological manifestations, including lethargy, abnormal tone, seizures, and encephalopathy.\n\nDuring nutritional management, dietary leucine is restricted, while isoleucine and valine are supplemented as needed. Providing these two BCAAs helps maintain adequate protein synthesis and prevents their concentrations from falling excessively while leucine intake is restricted. The amounts are carefully monitored according to plasma amino-acid concentrations.\n\nTherefore:\nToxic metabolite of greatest concern → leucine\nSupplemented BCAAs → isoleucine + valine","whyWrongChoices":"Alternative options: isoleucine; leucine and valine, valine; isoleucine and leucine, leucine and isoleucine; valine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which among the branched chain amino acid is/are the most important neurotoxic metabolite in msud? which among the branched chain acid is/are required to be supplemented to control the plasma level of the said toxic.:::', 'which among the branched chain amino acid is/are the most important neurotoxic metabolite in msud? which among the branched chain acid is/are required to be supplemented to control the plasma level of the said toxic.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In MSUD, there is deficient activity of the branched-chain α-ketoacid dehydrogenase (BCKDH) complex, which normally metabolizes the branched-chain amino acids (BCAAs):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"leucine;  isoleucine and valine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In MSUD, there is deficient activity of the branched-chain α-ketoacid dehydrogenase (BCKDH) complex, which normally metabolizes the branched-chain amino acids (BCAAs):\n• Leucine\n• Isoleucine\n• Valine\n\nConsequently, both the BCAAs and their corresponding branched-chain α-ketoacids accumulate.\n\nAmong the three BCAAs, leucine is particularly important in the neurologic toxicity of MSUD. Markedly elevated plasma leucine is associated with cerebral edema and neurological manifestations, including lethargy, abnormal tone, seizures, and encephalopathy.\n\nDuring nutritional management, dietary leucine is restricted, while isoleucine and valine are supplemented as needed. Providing these two BCAAs helps maintain adequate protein synthesis and prevents their concentrations from falling excessively while leucine intake is restricted. The amounts are carefully monitored according to plasma amino-acid concentrations.\n\nTherefore:\nToxic metabolite of greatest concern → leucine\nSupplemented BCAAs → isoleucine + valine","whyWrongChoices":"Alternative options: isoleucine; leucine and valine, valine; isoleucine and leucine, leucine and isoleucine; valine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the total calories absorbed from 4 exchanges 2 l of 2.5% dialysate solution on a patient undergoing peritoneal dialysis assuming 60% absorption rate. note: 1 gram dextrose = 3.4 kcal.:::408 kcal', 'compute for the total calories absorbed from 4 exchanges 2 l of 2.5% dialysate solution on a patient undergoing peritoneal dialysis assuming 60% absorption rate. note: 1 gram dextrose = 3.4 kcal.', '408 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step 1: Calculate the amount of dextrose per 2-L exchange","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"408 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step 1: Calculate the amount of dextrose per 2-L exchange\nA 2.5% dextrose solution contains: 2.5 g/100 mL\nSince 2 L = 2,000 mL: 2000mL * (2.5 g ÷ 100 mL) = 50 g dextrose\n\nStep 2: Calculate calories per exchange: 50 g * 3.4 kcal/g = 170 kcal\n\nStep 3: Calculate calories from four exchanges: 170 * 4 = 680 kcal\n\nStep 4: Apply the 60% absorption rate: 680 kcal * 0.60 = 408 kcal\n\nTherefore, the patient absorbs approximately 408 kcal/day from the dialysate dextrose.","whyWrongChoices":"Alternative options: 50 kcal, 30 kcal, 102 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the total calories absorbed from 4 exchanges 2 l of 2.5% dialysate solution on a patient undergoing peritoneal dialysis assuming 60% absorption rate. note: 1 gram dextrose = 3.4 kcal.:::', 'compute for the total calories absorbed from 4 exchanges 2 l of 2.5% dialysate solution on a patient undergoing peritoneal dialysis assuming 60% absorption rate. note: 1 gram dextrose = 3.4 kcal.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step 1: Calculate the amount of dextrose per 2-L exchange","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"408 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step 1: Calculate the amount of dextrose per 2-L exchange\nA 2.5% dextrose solution contains: 2.5 g/100 mL\nSince 2 L = 2,000 mL: 2000mL * (2.5 g ÷ 100 mL) = 50 g dextrose\n\nStep 2: Calculate calories per exchange: 50 g * 3.4 kcal/g = 170 kcal\n\nStep 3: Calculate calories from four exchanges: 170 * 4 = 680 kcal\n\nStep 4: Apply the 60% absorption rate: 680 kcal * 0.60 = 408 kcal\n\nTherefore, the patient absorbs approximately 408 kcal/day from the dialysate dextrose.","whyWrongChoices":"Alternative options: 50 kcal, 30 kcal, 102 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a category of outcomes monitored in the ncp?:::nutrition diagnosis statement', 'which of the following is not a category of outcomes monitored in the ncp?', 'Nutrition diagnosis statement', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The nutrition diagnosis is not an outcome—it is a problem statement.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition diagnosis statement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The nutrition diagnosis is not an outcome—it is a problem statement.","whyWrongChoices":"Alternative options: Food/nutrition-related history, Anthropometric measurements, Biochemical data & medical tests"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how many grams of protein would be a 50kg, metabolically stable, non-dialyzed, adult male patient diagnosed with ckd stage 4 sec to diabetic kidney disease be needing per day?:::', 'how many grams of protein would be a 50kg, metabolically stable, non-dialyzed, adult male patient diagnosed with ckd stage 4 sec to diabetic kidney disease be needing per day?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For a metabolically stable adult with CKD stages 3–5 who is not on dialysis, current KDIGO guidance suggests a protein intake of approximately 0.8 g/kg body weight/day.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"40g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For a metabolically stable adult with CKD stages 3–5 who is not on dialysis, current KDIGO guidance suggests a protein intake of approximately 0.8 g/kg body weight/day.\n\nFor a 50-kg patient: 50 kg * 0.8 g/kg/day = 40 g/day\n\nTherefore, the best answer is 40 g protein/day. The key information in the question is:\n\nCKD Stage 4 → advanced CKD\nNot on dialysis → protein needs are not increased for dialysis-related losses\nMetabolically stable → the standard CKD protein recommendation applies\n50 kg → use body weight for the calculation","whyWrongChoices":"Alternative options: 15g, 30g, 50g"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this food label claim refers to a product containing 35 mg of sodium of per serving.:::very low in sodium', 'this food label claim refers to a product containing 35 mg of sodium of per serving.', 'Very low in sodium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under U.S. FDA food-labeling definitions, a food may be labeled “very low sodium” when it contains 35 mg or less of sodium per reference amount customarily consumed (RACC) or per labeled serving, depending on the applicable labeling provision.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Very low in sodium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under U.S. FDA food-labeling definitions, a food may be labeled “very low sodium” when it contains 35 mg or less of sodium per reference amount customarily consumed (RACC) or per labeled serving, depending on the applicable labeling provision.\nTherefore, a product containing 35 mg sodium per serving meets the criterion for “very low sodium.”\n\nFor comparison, the commonly tested FDA definitions are:\n• Claim - Sodium criterion\n• Sodium-free / salt-free - <5 mg/serving\n• Very low sodium - ≤35 mg/serving\n• Low sodium - ≤140 mg/serving\n• Reduced sodium - At least 25% less sodium than the reference food","whyWrongChoices":"Alternative options: No salt added, Sodium-free, Reduced sodium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this food label claim refers to a product containing 35 mg of sodium of per serving.:::', 'this food label claim refers to a product containing 35 mg of sodium of per serving.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under U.S. FDA food-labeling definitions, a food may be labeled “very low sodium” when it contains 35 mg or less of sodium per reference amount customarily consumed (RACC) or per labeled serving, depending on the applicable labeling provision.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Very low in sodium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under U.S. FDA food-labeling definitions, a food may be labeled “very low sodium” when it contains 35 mg or less of sodium per reference amount customarily consumed (RACC) or per labeled serving, depending on the applicable labeling provision.\nTherefore, a product containing 35 mg sodium per serving meets the criterion for “very low sodium.”\n\nFor comparison, the commonly tested FDA definitions are:\n• Claim - Sodium criterion\n• Sodium-free / salt-free - <5 mg/serving\n• Very low sodium - ≤35 mg/serving\n• Low sodium - ≤140 mg/serving\n• Reduced sodium - At least 25% less sodium than the reference food","whyWrongChoices":"Alternative options: No salt added, Sodium-free, Reduced sodium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a category of outcomes monitored in the ncp?:::', 'which of the following is not a category of outcomes monitored in the ncp?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The nutrition diagnosis is not an outcome—it is a problem statement.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition diagnosis statement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The nutrition diagnosis is not an outcome—it is a problem statement.","whyWrongChoices":"Alternative options: Food/nutrition-related history, Anthropometric measurements, Biochemical data & medical tests"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is/are considered severe weight loss? i. 5% over a month ii. 7.5% over 3 months iii. >5% over 1 month iv. >7.5% over 3 months:::iii and iv only', 'which of the following is/are considered severe weight loss? i. 5% over a month ii. 7.5% over 3 months iii. >5% over 1 month iv. >7.5% over 3 months', 'III and IV only', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the commonly used ASPEN/Academy malnutrition assessment framework, weight loss thresholds are interpreted according to both magnitude and time period. For the time frames given, >5% in 1 month and >7.5% in 3 months represent significant/severe weight loss thresholds. The key distinction is the “>” (greater than) sign: exactly 5% or exactly 7.5% does not meet a criterion stated as greater than those values.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"III and IV only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the commonly used ASPEN/Academy malnutrition assessment framework, weight loss thresholds are interpreted according to both magnitude and time period. For the time frames given, >5% in 1 month and >7.5% in 3 months represent significant/severe weight loss thresholds. The key distinction is the “>” (greater than) sign: exactly 5% or exactly 7.5% does not meet a criterion stated as greater than those values.","whyWrongChoices":"Alternative options: I and II only, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is/are considered severe weight loss? i. 5% over a month ii. 7.5% over 3 months iii. >5% over 1 month iv. >7.5% over 3 months:::', 'which of the following is/are considered severe weight loss? i. 5% over a month ii. 7.5% over 3 months iii. >5% over 1 month iv. >7.5% over 3 months', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the commonly used ASPEN/Academy malnutrition assessment framework, weight loss thresholds are interpreted according to both magnitude and time period. For the time frames given, >5% in 1 month and >7.5% in 3 months represent significant/severe weight loss thresholds. The key distinction is the “>” (greater than) sign: exactly 5% or exactly 7.5% does not meet a criterion stated as greater than those values.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"III and IV only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the commonly used ASPEN/Academy malnutrition assessment framework, weight loss thresholds are interpreted according to both magnitude and time period. For the time frames given, >5% in 1 month and >7.5% in 3 months represent significant/severe weight loss thresholds. The key distinction is the “>” (greater than) sign: exactly 5% or exactly 7.5% does not meet a criterion stated as greater than those values.","whyWrongChoices":"Alternative options: I and II only, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following dietary patterns is least associated with an increased risk of gout?:::a diet emphasizing low-fat dairy products and adequate hydration', 'which of the following dietary patterns is least associated with an increased risk of gout?', 'A diet emphasizing low-fat dairy products and adequate hydration', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Low-fat dairy intake is generally associated with a lower risk of gout, while adequate hydration supports renal uric acid excretion. In contrast, purine-rich foods, sugar-sweetened beverages (particularly those high in fructose), and fasting/starvation can contribute to hyperuricemia or trigger gout attacks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A diet emphasizing low-fat dairy products and adequate hydration\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Low-fat dairy intake is generally associated with a lower risk of gout, while adequate hydration supports renal uric acid excretion. In contrast, purine-rich foods, sugar-sweetened beverages (particularly those high in fructose), and fasting/starvation can contribute to hyperuricemia or trigger gout attacks.","whyWrongChoices":"Alternative options: Frequent consumption of organ meats and shellfish, Regular intake of sugar-sweetened beverages, Prolonged fasting or severe calorie restriction"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following dietary patterns is least associated with an increased risk of gout?:::', 'which of the following dietary patterns is least associated with an increased risk of gout?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Low-fat dairy intake is generally associated with a lower risk of gout, while adequate hydration supports renal uric acid excretion. In contrast, purine-rich foods, sugar-sweetened beverages (particularly those high in fructose), and fasting/starvation can contribute to hyperuricemia or trigger gout attacks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A diet emphasizing low-fat dairy products and adequate hydration\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Low-fat dairy intake is generally associated with a lower risk of gout, while adequate hydration supports renal uric acid excretion. In contrast, purine-rich foods, sugar-sweetened beverages (particularly those high in fructose), and fasting/starvation can contribute to hyperuricemia or trigger gout attacks.","whyWrongChoices":"Alternative options: Frequent consumption of organ meats and shellfish, Regular intake of sugar-sweetened beverages, Prolonged fasting or severe calorie restriction"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is a nutrition diagnosis domain in ncpt?:::clinical, behavioral-environmental, intake', 'which of the following is a nutrition diagnosis domain in ncpt?', 'Clinical, Behavioral-Environmental, Intake', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition diagnoses fall into three domains: Intake (NI), Clinical (NC), and Behavioral-Environmental (NB).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Clinical, Behavioral-Environmental, Intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition diagnoses fall into three domains: Intake (NI), Clinical (NC), and Behavioral-Environmental (NB).","whyWrongChoices":"Alternative options: Food/Nutrition-Related History, Anthropometric Measurements, Nutrition-Focused Physical Findings, Assessment, Diagnosis, Intervention, Anthropometrics, Biochemical, Clinical"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an eating disorder characterized by recurrent episodes of eating excessively followed by compensatory purging, such as self-induced vomiting, is::::bulimia nervosa', 'an eating disorder characterized by recurrent episodes of eating excessively followed by compensatory purging, such as self-induced vomiting, is:', 'Bulimia nervosa', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bulimia nervosa is characterized by recurrent binge-eating episodes accompanied by inappropriate compensatory behaviors, such as self-induced vomiting, misuse of laxatives or diuretics, fasting, or excessive exercise. Unlike anorexia nervosa, body weight in individuals with bulimia nervosa is often within or above the normal range, although this is not required for diagnosis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bulimia nervosa\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bulimia nervosa is characterized by recurrent binge-eating episodes accompanied by inappropriate compensatory behaviors, such as self-induced vomiting, misuse of laxatives or diuretics, fasting, or excessive exercise. Unlike anorexia nervosa, body weight in individuals with bulimia nervosa is often within or above the normal range, although this is not required for diagnosis.","whyWrongChoices":"Alternative options: Anorexia nervosa, Binge-eating type, Restricting type"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an eating disorder characterized by recurrent episodes of eating excessively followed by compensatory purging, such as self-induced vomiting, is::::', 'an eating disorder characterized by recurrent episodes of eating excessively followed by compensatory purging, such as self-induced vomiting, is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bulimia nervosa is characterized by recurrent binge-eating episodes accompanied by inappropriate compensatory behaviors, such as self-induced vomiting, misuse of laxatives or diuretics, fasting, or excessive exercise. Unlike anorexia nervosa, body weight in individuals with bulimia nervosa is often within or above the normal range, although this is not required for diagnosis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bulimia nervosa\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bulimia nervosa is characterized by recurrent binge-eating episodes accompanied by inappropriate compensatory behaviors, such as self-induced vomiting, misuse of laxatives or diuretics, fasting, or excessive exercise. Unlike anorexia nervosa, body weight in individuals with bulimia nervosa is often within or above the normal range, although this is not required for diagnosis.","whyWrongChoices":"Alternative options: Anorexia nervosa, Binge-eating type, Restricting type"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following protein intakes is generally appropriate for a resistance-trained individual seeking to support muscle hypertrophy?:::approximately 1.4–2.0 g/kg bw/day', 'which of the following protein intakes is generally appropriate for a resistance-trained individual seeking to support muscle hypertrophy?', 'Approximately 1.4–2.0 g/kg BW/day', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For individuals who participate in resistance training and are seeking to increase or maintain muscle mass, protein requirements are generally higher than the RDA for sedentary adults. The International Society of Sports Nutrition (ISSN) recommends approximately 1.4–2.0 g protein/kg body weight/day for most exercising individuals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Approximately 1.4–2.0 g/kg BW/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For individuals who participate in resistance training and are seeking to increase or maintain muscle mass, protein requirements are generally higher than the RDA for sedentary adults. The International Society of Sports Nutrition (ISSN) recommends approximately 1.4–2.0 g protein/kg body weight/day for most exercising individuals.\n\nProtein intake should also be distributed throughout the day rather than consumed in one large dose. Adequate total energy intake and resistance training are equally important because protein alone cannot maximize muscle hypertrophy.\n\nResearch also suggests that the increase in muscle-building benefit tends to plateau around ~1.6 g/kg/day for many resistance-trained individuals, although some individuals may benefit from intakes toward the upper end of the range depending on training volume, energy restriction, age, and other factors.","whyWrongChoices":"Alternative options: Approximately 0.6–0.8 g/kg BW/day, Approximately 3.0–4.0 g/kg BW/day, Protein intake does not need to increase with resistance training"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following protein intakes is generally appropriate for a resistance-trained individual seeking to support muscle hypertrophy?:::', 'which of the following protein intakes is generally appropriate for a resistance-trained individual seeking to support muscle hypertrophy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For individuals who participate in resistance training and are seeking to increase or maintain muscle mass, protein requirements are generally higher than the RDA for sedentary adults. The International Society of Sports Nutrition (ISSN) recommends approximately 1.4–2.0 g protein/kg body weight/day for most exercising individuals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Approximately 1.4–2.0 g/kg BW/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For individuals who participate in resistance training and are seeking to increase or maintain muscle mass, protein requirements are generally higher than the RDA for sedentary adults. The International Society of Sports Nutrition (ISSN) recommends approximately 1.4–2.0 g protein/kg body weight/day for most exercising individuals.\n\nProtein intake should also be distributed throughout the day rather than consumed in one large dose. Adequate total energy intake and resistance training are equally important because protein alone cannot maximize muscle hypertrophy.\n\nResearch also suggests that the increase in muscle-building benefit tends to plateau around ~1.6 g/kg/day for many resistance-trained individuals, although some individuals may benefit from intakes toward the upper end of the range depending on training volume, energy restriction, age, and other factors.","whyWrongChoices":"Alternative options: Approximately 0.6–0.8 g/kg BW/day, Approximately 3.0–4.0 g/kg BW/day, Protein intake does not need to increase with resistance training"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is a nutrition diagnosis domain in ncpt?:::', 'which of the following is a nutrition diagnosis domain in ncpt?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition diagnoses fall into three domains: Intake (NI), Clinical (NC), and Behavioral-Environmental (NB).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Clinical, Behavioral-Environmental, Intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition diagnoses fall into three domains: Intake (NI), Clinical (NC), and Behavioral-Environmental (NB).","whyWrongChoices":"Alternative options: Food/Nutrition-Related History, Anthropometric Measurements, Nutrition-Focused Physical Findings, Assessment, Diagnosis, Intervention, Anthropometrics, Biochemical, Clinical"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in patients with cirrhosis, which dietary strategy is most appropriate to help prevent protein-energy malnutrition?:::adequate energy and protein intake with small, frequent meals', 'in patients with cirrhosis, which dietary strategy is most appropriate to help prevent protein-energy malnutrition?', 'Adequate energy and protein intake with small, frequent meals', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with cirrhosis are at high risk of protein-energy malnutrition and muscle wasting. Providing adequate energy and protein helps maintain lean body mass and prevent catabolism. Small, frequent meals and a late-evening snack can help reduce prolonged fasting and provide a more continuous supply of energy, particularly because glycogen stores may be reduced in advanced liver disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Adequate energy and protein intake with small, frequent meals\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with cirrhosis are at high risk of protein-energy malnutrition and muscle wasting. Providing adequate energy and protein helps maintain lean body mass and prevent catabolism. Small, frequent meals and a late-evening snack can help reduce prolonged fasting and provide a more continuous supply of energy, particularly because glycogen stores may be reduced in advanced liver disease.","whyWrongChoices":"Alternative options: Prolonged fasting between meals, Routine severe restriction of dietary protein, Elimination of carbohydrate-rich foods"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
