INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the biliopancreatic diversion with duodenal switch procedure results to some nutrition-related conditions. choose one that does not apply.:::indigestion and bloating', 'the biliopancreatic diversion with duodenal switch procedure results to some nutrition-related conditions. choose one that does not apply.', 'Indigestion and bloating', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Indigestion and bloating are general, functional upper-GI symptoms. Since the pyloric valve is fully preserved during a Duodenal Switch procedure, normal gastric emptying and stomach digestion are maintained, making classic upper indigestion an inaccurate description of the operation''s hallmark downstream complications.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Indigestion and bloating\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Indigestion and bloating are general, functional upper-GI symptoms. Since the pyloric valve is fully preserved during a Duodenal Switch procedure, normal gastric emptying and stomach digestion are maintained, making classic upper indigestion an inaccurate description of the operation''s hallmark downstream complications.","whyWrongChoices":"Alternative options: Severe malabsorption of protein, Severe malabsorption of macronutrients and micronutrients, Changes in gut hormones to reduce appetite"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the biliopancreatic diversion with duodenal switch procedure results to some nutrition-related conditions. choose one that does not apply.:::', 'the biliopancreatic diversion with duodenal switch procedure results to some nutrition-related conditions. choose one that does not apply.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Indigestion and bloating are general, functional upper-GI symptoms. Since the pyloric valve is fully preserved during a Duodenal Switch procedure, normal gastric emptying and stomach digestion are maintained, making classic upper indigestion an inaccurate description of the operation''s hallmark downstream complications.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Indigestion and bloating\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Indigestion and bloating are general, functional upper-GI symptoms. Since the pyloric valve is fully preserved during a Duodenal Switch procedure, normal gastric emptying and stomach digestion are maintained, making classic upper indigestion an inaccurate description of the operation''s hallmark downstream complications.","whyWrongChoices":"Alternative options: Severe malabsorption of protein, Severe malabsorption of macronutrients and micronutrients, Changes in gut hormones to reduce appetite"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are the criteria for anorexia nervosa except:::recurrent episodes of binge eating within 2 hours', 'the following are the criteria for anorexia nervosa except', 'Recurrent episodes of binge eating within 2 hours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Recurrently consuming large amounts of food in a discrete period of time (e.g., within a 2-hour window) accompanied by a perceived lack of control is the fundamental, defining characteristic of Bulimia Nervosa or Binge Eating Disorder. It does not serve as a baseline criterion for Anorexia Nervosa.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Recurrent episodes of binge eating within 2 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Recurrently consuming large amounts of food in a discrete period of time (e.g., within a 2-hour window) accompanied by a perceived lack of control is the fundamental, defining characteristic of Bulimia Nervosa or Binge Eating Disorder. It does not serve as a baseline criterion for Anorexia Nervosa.","whyWrongChoices":"Alternative options: Intense fear of weight gain, Amenorrhea, Denial"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient suffering from bulimia nervosa is at risk of colon injury due to:::laxative abuse', 'a patient suffering from bulimia nervosa is at risk of colon injury due to', 'Laxative abuse', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Individuals with Bulimia Nervosa frequently misuse stimulant laxatives to control weight after a binge eating episode. Chronic laxative abuse directly injures the lining of the large intestine and damages the enteric nerves controlling bowel motility.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Laxative abuse\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Individuals with Bulimia Nervosa frequently misuse stimulant laxatives to control weight after a binge eating episode. Chronic laxative abuse directly injures the lining of the large intestine and damages the enteric nerves controlling bowel motility.\n\nThis toxic damage can progress to a severe, structurally irreversible clinical condition called cathartic colon syndrome. In cathartic colon, the large intestine loses its neuromuscular tone, becomes massively dilated, and can no longer propel stool on its own, increasing the risk of chronic constipation, fecal impaction, and even colon perforation.","whyWrongChoices":"Alternative options: Purging, Binge eating episodes, Lack of fiber intake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient suffering from bulimia nervosa is at risk of colon injury due to:::', 'a patient suffering from bulimia nervosa is at risk of colon injury due to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Individuals with Bulimia Nervosa frequently misuse stimulant laxatives to control weight after a binge eating episode. Chronic laxative abuse directly injures the lining of the large intestine and damages the enteric nerves controlling bowel motility.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Laxative abuse\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Individuals with Bulimia Nervosa frequently misuse stimulant laxatives to control weight after a binge eating episode. Chronic laxative abuse directly injures the lining of the large intestine and damages the enteric nerves controlling bowel motility.\n\nThis toxic damage can progress to a severe, structurally irreversible clinical condition called cathartic colon syndrome. In cathartic colon, the large intestine loses its neuromuscular tone, becomes massively dilated, and can no longer propel stool on its own, increasing the risk of chronic constipation, fecal impaction, and even colon perforation.","whyWrongChoices":"Alternative options: Purging, Binge eating episodes, Lack of fiber intake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when counseling a patient with bulimia nervosa the following must be encouraged except:::suggest foods for binge eating episode', 'when counseling a patient with bulimia nervosa the following must be encouraged except', 'Suggest foods for binge eating episode', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical psychological and nutritional counseling for Bulimia Nervosa, a Registered Nutritionist-Dietitian (RND) must never suggest, plan, or provide food options for a binge eating episode. The primary goal of Medical Nutrition Therapy (MNT) is to break the restrict-binge-purge cycle. Actively giving food ideas for a binge would validate and reinforce the disordered behavior.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Suggest foods for binge eating episode\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical psychological and nutritional counseling for Bulimia Nervosa, a Registered Nutritionist-Dietitian (RND) must never suggest, plan, or provide food options for a binge eating episode. The primary goal of Medical Nutrition Therapy (MNT) is to break the restrict-binge-purge cycle. Actively giving food ideas for a binge would validate and reinforce the disordered behavior.\n\n\t• Identify food triggers: Pinpointing which foods, emotions, or social scenarios spark an overwhelming urge to binge helps the patient develop healthy, non-food coping mechanisms.\n\t• Personalize eating pattern: Establishing a highly structured, individualized meal plan (such as eating 3 regular meals and 2–3 snacks at predictable times) keeps the patient physically satisfied, preventing the extreme biological hunger that drives binging.\n\t• Embrace all food and achieve comfort: Dietitians work to dismantle the toxic \"good food vs. bad food\" mentality common in bulimia. Helping a patient comfortably reintroduce former fear foods without guilt reduces the psychological drive to binge on them.","whyWrongChoices":"Alternative options: Identify food triggers, Embrace all food and achieve comfort, Personalize eating pattern"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when counseling a patient with bulimia nervosa the following must be encouraged except:::', 'when counseling a patient with bulimia nervosa the following must be encouraged except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical psychological and nutritional counseling for Bulimia Nervosa, a Registered Nutritionist-Dietitian (RND) must never suggest, plan, or provide food options for a binge eating episode. The primary goal of Medical Nutrition Therapy (MNT) is to break the restrict-binge-purge cycle. Actively giving food ideas for a binge would validate and reinforce the disordered behavior.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Suggest foods for binge eating episode\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical psychological and nutritional counseling for Bulimia Nervosa, a Registered Nutritionist-Dietitian (RND) must never suggest, plan, or provide food options for a binge eating episode. The primary goal of Medical Nutrition Therapy (MNT) is to break the restrict-binge-purge cycle. Actively giving food ideas for a binge would validate and reinforce the disordered behavior.\n\n\t• Identify food triggers: Pinpointing which foods, emotions, or social scenarios spark an overwhelming urge to binge helps the patient develop healthy, non-food coping mechanisms.\n\t• Personalize eating pattern: Establishing a highly structured, individualized meal plan (such as eating 3 regular meals and 2–3 snacks at predictable times) keeps the patient physically satisfied, preventing the extreme biological hunger that drives binging.\n\t• Embrace all food and achieve comfort: Dietitians work to dismantle the toxic \"good food vs. bad food\" mentality common in bulimia. Helping a patient comfortably reintroduce former fear foods without guilt reduces the psychological drive to binge on them.","whyWrongChoices":"Alternative options: Identify food triggers, Embrace all food and achieve comfort, Personalize eating pattern"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to ensure food safety, keeping food between 45 to 145 degrees fahrenheit or 7.2 to 62.7 degrees celsius must not exceed:::4 hours', 'to ensure food safety, keeping food between 45 to 145 degrees fahrenheit or 7.2 to 62.7 degrees celsius must not exceed', '4 hours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leaving perishable food items within this unsafe span (45°F to 145°F / 7.2°C to 62.7°C) for longer than 4 hours permits rapid, exponential multiplication of pathogenic bacteria (such as Salmonella and Staphylococcus aureus), making the food highly toxic and unsafe for human consumption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leaving perishable food items within this unsafe span (45°F to 145°F / 7.2°C to 62.7°C) for longer than 4 hours permits rapid, exponential multiplication of pathogenic bacteria (such as Salmonella and Staphylococcus aureus), making the food highly toxic and unsafe for human consumption.\n\n1. The Safe Time Window (Under 2 hours): When potentially hazardous food is kept in the Temperature Danger Zone (45°F to 145°F / 7.2°C to 62.7°C) for less than 2 hours, it is still safe to serve, eat, or securely put back into the refrigerator to use later.\n2. The Point of No Return (2 to 4 hours): Once food sits out past the 2-hour mark, it enters a dangerous gray zone. While it is still safe to consume immediately, it can no longer be legally or safely put back in the refrigerator because bacteria have entered their rapid, exponential growth phase.\n\n• Under 2 hours: Safe to consume or re-refrigerate.\n• 2 to 4 hours: Safe to eat only if consumed immediately; do not put it back in the fridge.\n• Over 4 hours: Absolute mandatory discard.","whyWrongChoices":"Alternative options: 2 hours, 3 hours, 8 hours"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 16 year-old patient with normal weight for height and age verbalizes that she wants to die because she is very fat. she believes that people are always staring at her because she is ugly. what should the rnd do?:::refer to a psychiatrist immediately', 'a 16 year-old patient with normal weight for height and age verbalizes that she wants to die because she is very fat. she believes that people are always staring at her because she is ugly. what should the rnd do?', 'Refer to a psychiatrist immediately', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The patient has explicitly verbalized an active intent to die (\"wants to die\"). In any clinical setting, an explicit statement of suicidal ideation is a critical psychiatric emergency that completely overrides standard dietary counseling. The immediate, non-negotiable step is to ensure patient safety by initiating an immediate referral to a psychiatrist or mental health crisis professional.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Refer to a psychiatrist immediately\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The patient has explicitly verbalized an active intent to die (\"wants to die\"). In any clinical setting, an explicit statement of suicidal ideation is a critical psychiatric emergency that completely overrides standard dietary counseling. The immediate, non-negotiable step is to ensure patient safety by initiating an immediate referral to a psychiatrist or mental health crisis professional.\n\nThe patient''s severe body image distortion (believing she is \"very fat\" despite a normal weight-for-height profile) combined with ideas of reference (believing \"people are always staring at her\") are severe psychological indicators highly consistent with severe eating disorders (such as Anorexia Nervosa) or Body Dysmorphic Disorder (BDD). These conditions require specialized psychiatric stabilization before any structured nutritional therapy can be effective.","whyWrongChoices":"Alternative options: Tell the patient that she is not overweight, Tell the patient that she is experiencing delusions, Give nutrition education"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to ensure food safety, keeping food between 45 to 145 degrees fahrenheit or 7.2 to 62.7 degrees celsius must not exceed:::', 'to ensure food safety, keeping food between 45 to 145 degrees fahrenheit or 7.2 to 62.7 degrees celsius must not exceed', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leaving perishable food items within this unsafe span (45°F to 145°F / 7.2°C to 62.7°C) for longer than 4 hours permits rapid, exponential multiplication of pathogenic bacteria (such as Salmonella and Staphylococcus aureus), making the food highly toxic and unsafe for human consumption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leaving perishable food items within this unsafe span (45°F to 145°F / 7.2°C to 62.7°C) for longer than 4 hours permits rapid, exponential multiplication of pathogenic bacteria (such as Salmonella and Staphylococcus aureus), making the food highly toxic and unsafe for human consumption.\n\n1. The Safe Time Window (Under 2 hours): When potentially hazardous food is kept in the Temperature Danger Zone (45°F to 145°F / 7.2°C to 62.7°C) for less than 2 hours, it is still safe to serve, eat, or securely put back into the refrigerator to use later.\n2. The Point of No Return (2 to 4 hours): Once food sits out past the 2-hour mark, it enters a dangerous gray zone. While it is still safe to consume immediately, it can no longer be legally or safely put back in the refrigerator because bacteria have entered their rapid, exponential growth phase.\n\n• Under 2 hours: Safe to consume or re-refrigerate.\n• 2 to 4 hours: Safe to eat only if consumed immediately; do not put it back in the fridge.\n• Over 4 hours: Absolute mandatory discard.","whyWrongChoices":"Alternative options: 2 hours, 3 hours, 8 hours"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 16 year-old patient with normal weight for height and age verbalizes that she wants to die because she is very fat. she believes that people are always staring at her because she is ugly. what should the rnd do?:::', 'a 16 year-old patient with normal weight for height and age verbalizes that she wants to die because she is very fat. she believes that people are always staring at her because she is ugly. what should the rnd do?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The patient has explicitly verbalized an active intent to die (\"wants to die\"). In any clinical setting, an explicit statement of suicidal ideation is a critical psychiatric emergency that completely overrides standard dietary counseling. The immediate, non-negotiable step is to ensure patient safety by initiating an immediate referral to a psychiatrist or mental health crisis professional.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Refer to a psychiatrist immediately\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The patient has explicitly verbalized an active intent to die (\"wants to die\"). In any clinical setting, an explicit statement of suicidal ideation is a critical psychiatric emergency that completely overrides standard dietary counseling. The immediate, non-negotiable step is to ensure patient safety by initiating an immediate referral to a psychiatrist or mental health crisis professional.\n\nThe patient''s severe body image distortion (believing she is \"very fat\" despite a normal weight-for-height profile) combined with ideas of reference (believing \"people are always staring at her\") are severe psychological indicators highly consistent with severe eating disorders (such as Anorexia Nervosa) or Body Dysmorphic Disorder (BDD). These conditions require specialized psychiatric stabilization before any structured nutritional therapy can be effective.","whyWrongChoices":"Alternative options: Tell the patient that she is not overweight, Tell the patient that she is experiencing delusions, Give nutrition education"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient manifesting the following symptoms has a diagnosis of symptoms: repeated chewing and spitting of food, bingeing and purging once a week for 3 weeks, exercising 3 hours daily:::eating disorders not otherwise specified (ednos)', 'a patient manifesting the following symptoms has a diagnosis of symptoms: repeated chewing and spitting of food, bingeing and purging once a week for 3 weeks, exercising 3 hours daily', 'Eating Disorders Not Otherwise Specified (EDNOS)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To meet the strict, formal diagnostic criteria for Bulimia Nervosa, a patient must engage in binge eating and inappropriate compensatory behaviors (purging or excessive exercise) at an average frequency of at least once a week for at least 3 months.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Eating Disorders Not Otherwise Specified (EDNOS)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To meet the strict, formal diagnostic criteria for Bulimia Nervosa, a patient must engage in binge eating and inappropriate compensatory behaviors (purging or excessive exercise) at an average frequency of at least once a week for at least 3 months.\n\nBecause this patient''s binge/purge episodes have only been occurring for 3 weeks (subthreshold duration), they do not meet the full, standard timeline for Bulimia Nervosa. Under standard board exam terminology, cases that display clinically significant disordered eating patterns but fall short of the exact diagnostic durations or specific criteria are categorized under EDNOS (Eating Disorders Not Otherwise Specified). (Note: In modern clinical DSM-5 manuals, this category is updated as OSFED—Other Specified Feeding and Eating Disorder).\n\nThe inclusion of repeated chewing and spitting of food is another classic, textbook hallmark behavior frequently categorized under the EDNOS/OSFED umbrella rather than standing as its own distinct standalone diagnosis.","whyWrongChoices":"Alternative options: Bulimia Nervosa, Anorexia Nervosa, Body Image Distortion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient manifesting the following symptoms has a diagnosis of symptoms: repeated chewing and spitting of food, bingeing and purging once a week for 3 weeks, exercising 3 hours daily:::', 'a patient manifesting the following symptoms has a diagnosis of symptoms: repeated chewing and spitting of food, bingeing and purging once a week for 3 weeks, exercising 3 hours daily', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To meet the strict, formal diagnostic criteria for Bulimia Nervosa, a patient must engage in binge eating and inappropriate compensatory behaviors (purging or excessive exercise) at an average frequency of at least once a week for at least 3 months.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Eating Disorders Not Otherwise Specified (EDNOS)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To meet the strict, formal diagnostic criteria for Bulimia Nervosa, a patient must engage in binge eating and inappropriate compensatory behaviors (purging or excessive exercise) at an average frequency of at least once a week for at least 3 months.\n\nBecause this patient''s binge/purge episodes have only been occurring for 3 weeks (subthreshold duration), they do not meet the full, standard timeline for Bulimia Nervosa. Under standard board exam terminology, cases that display clinically significant disordered eating patterns but fall short of the exact diagnostic durations or specific criteria are categorized under EDNOS (Eating Disorders Not Otherwise Specified). (Note: In modern clinical DSM-5 manuals, this category is updated as OSFED—Other Specified Feeding and Eating Disorder).\n\nThe inclusion of repeated chewing and spitting of food is another classic, textbook hallmark behavior frequently categorized under the EDNOS/OSFED umbrella rather than standing as its own distinct standalone diagnosis.","whyWrongChoices":"Alternative options: Bulimia Nervosa, Anorexia Nervosa, Body Image Distortion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the wavelike action causing relaxation and contraction of the muscles of the gi tract.:::peristalsis', 'the wavelike action causing relaxation and contraction of the muscles of the gi tract.', 'Peristalsis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"🔴 Digestion: The process of breaking down food into small nutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Peristalsis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"🔴 Digestion: The process of breaking down food into small nutrients.\n🔴 Segmentation: Back-and-forth mixing of food in the intestine.\n🔴 Excretion: The removal of waste products from the body.","whyWrongChoices":"Alternative options: Digestion, Segmentation, Excretion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:muscle dysmorphia also known as bigorexia is characterized by the following manifestations except:::eating at night', 'muscle dysmorphia also known as bigorexia is characterized by the following manifestations except', 'Eating at night', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Eating at night (or Night Eating Syndrome) is an independent eating pattern specification characterized by evening hyperphagia or waking up to consume food during the night. It is not an established diagnostic hallmark or baseline manifestation of Muscle Dysmorphia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Eating at night\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Eating at night (or Night Eating Syndrome) is an independent eating pattern specification characterized by evening hyperphagia or waking up to consume food during the night. It is not an established diagnostic hallmark or baseline manifestation of Muscle Dysmorphia.\n\nClassic Manifestations of Bigorexia\n\t• Constant body checking: Individuals with muscle dysmorphia exhibit severe, repetitive body checking habits. This includes spending hours staring in the mirror, constantly using a tape measure to track muscle symmetry, or weighing themselves multiple times a day.\n\t• A kind of obsessive-compulsive disorder: Under the official DSM-5 criteria, muscle dysmorphia is classified as a specific subtype of Body Dysmorphic Disorder (BDD), which sits directly under the spectrum of Obsessive-Compulsive and Related Disorders. The condition drives unrelenting, obsessive thoughts regarding physical inadequacy.\n\t• Excessive exercise even when injured: A hallmark behavioral symptom is compulsive exercise. The psychological drive to build lean muscle mass is so extreme that the individual will rigidly lift weights or complete high-intensity training sessions even when suffering from clear physical illnesses, fractures, or severe muscular injuries.","whyWrongChoices":"Alternative options: A kind of obsessive-compulsive disorder, Constant body checking, Excessive exercise even when injured"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:muscle dysmorphia also known as bigorexia is characterized by the following manifestations except:::', 'muscle dysmorphia also known as bigorexia is characterized by the following manifestations except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Eating at night (or Night Eating Syndrome) is an independent eating pattern specification characterized by evening hyperphagia or waking up to consume food during the night. It is not an established diagnostic hallmark or baseline manifestation of Muscle Dysmorphia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Eating at night\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Eating at night (or Night Eating Syndrome) is an independent eating pattern specification characterized by evening hyperphagia or waking up to consume food during the night. It is not an established diagnostic hallmark or baseline manifestation of Muscle Dysmorphia.\n\nClassic Manifestations of Bigorexia\n\t• Constant body checking: Individuals with muscle dysmorphia exhibit severe, repetitive body checking habits. This includes spending hours staring in the mirror, constantly using a tape measure to track muscle symmetry, or weighing themselves multiple times a day.\n\t• A kind of obsessive-compulsive disorder: Under the official DSM-5 criteria, muscle dysmorphia is classified as a specific subtype of Body Dysmorphic Disorder (BDD), which sits directly under the spectrum of Obsessive-Compulsive and Related Disorders. The condition drives unrelenting, obsessive thoughts regarding physical inadequacy.\n\t• Excessive exercise even when injured: A hallmark behavioral symptom is compulsive exercise. The psychological drive to build lean muscle mass is so extreme that the individual will rigidly lift weights or complete high-intensity training sessions even when suffering from clear physical illnesses, fractures, or severe muscular injuries.","whyWrongChoices":"Alternative options: A kind of obsessive-compulsive disorder, Constant body checking, Excessive exercise even when injured"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are consequences of malnutrition in relation to immune response during infection except:::poor appetite and fatigue', 'the following are consequences of malnutrition in relation to immune response during infection except', 'Poor appetite and fatigue', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While poor appetite and fatigue are highly common, classic systemic and metabolic symptoms of malnutrition and active infections, they are general physiological responses rather than specific functional alterations of the immune system itself.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Poor appetite and fatigue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While poor appetite and fatigue are highly common, classic systemic and metabolic symptoms of malnutrition and active infections, they are general physiological responses rather than specific functional alterations of the immune system itself.\n\n\t• Reduced production of antibodies: Protein-energy malnutrition directly causes lymphoid tissue atrophy (such as the thymus and bone marrow), which severely impairs B-cell differentiation and downregulates the production of crucial secretory immunoglobulins (like IgA) and antibodies needed to fight pathogens.\n\t• Poor wound healing: Proper wound healing is an immune-mediated process reliant on cellular immunity. Malnutrition blunts macrophage activation, slows down granulomatous inflammation, and reduces cytokine orchestration, which prevents efficient tissue repair and barrier defense restoration.\n\t• Alterations in gut microbiome: The gut microbiome is intimately intertwined with mucosal immunity. Nutrient deficiencies compromise intestinal barrier function and mucosal nutrient-sensing receptors, disrupting the commensal gut microbiota balance and compounding immune dysfunction.","whyWrongChoices":"Alternative options: Alterations in gut microbiome, Poor wound healing, Reduced production of antibodies"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are consequences of malnutrition in relation to immune response during infection except:::', 'the following are consequences of malnutrition in relation to immune response during infection except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While poor appetite and fatigue are highly common, classic systemic and metabolic symptoms of malnutrition and active infections, they are general physiological responses rather than specific functional alterations of the immune system itself.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Poor appetite and fatigue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While poor appetite and fatigue are highly common, classic systemic and metabolic symptoms of malnutrition and active infections, they are general physiological responses rather than specific functional alterations of the immune system itself.\n\n\t• Reduced production of antibodies: Protein-energy malnutrition directly causes lymphoid tissue atrophy (such as the thymus and bone marrow), which severely impairs B-cell differentiation and downregulates the production of crucial secretory immunoglobulins (like IgA) and antibodies needed to fight pathogens.\n\t• Poor wound healing: Proper wound healing is an immune-mediated process reliant on cellular immunity. Malnutrition blunts macrophage activation, slows down granulomatous inflammation, and reduces cytokine orchestration, which prevents efficient tissue repair and barrier defense restoration.\n\t• Alterations in gut microbiome: The gut microbiome is intimately intertwined with mucosal immunity. Nutrient deficiencies compromise intestinal barrier function and mucosal nutrient-sensing receptors, disrupting the commensal gut microbiota balance and compounding immune dysfunction.","whyWrongChoices":"Alternative options: Alterations in gut microbiome, Poor wound healing, Reduced production of antibodies"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient with an oral temperature of 38.8 degrees celsius needs a proper nutrition intervention to support metabolic changes in the body. what should the rnd do?:::give additional high biologic value protein and fluids', 'a patient with an oral temperature of 38.8 degrees celsius needs a proper nutrition intervention to support metabolic changes in the body. what should the rnd do?', 'Give additional high biologic value protein and fluids', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An oral temperature of 38.8°C indicates an active clinical fever (febrile state).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Give additional high biologic value protein and fluids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An oral temperature of 38.8°C indicates an active clinical fever (febrile state).\n\nFor every 1°C increase in core body temperature above normal, the Basal Metabolic Rate (BMR) spikes by approximately 13%. This rapid metabolic shift accelerates tissue breakdown, causing significant lean muscle mass degradation (hypercatabolism) and high fluid loss via sweating and respiration.\n\nTo counteract nitrogen wasting and maintain cellular integrity, the Registered Nutritionist-Dietitian (RND) must increase the patient''s intake of high biological value (HBV) proteins (such as eggs, milk, fish, and lean poultry), which are efficiently utilized by the body for tissue repair and immune synthesis. Concurrently, aggressive fluid replenishment is a non-negotiable priority to prevent dehydration and support cellular homeostasis.","whyWrongChoices":"Alternative options: Give 100% fruit juice, Increase intake of fats to compensate for decreased adiposity, Give salabat because ginger has antimicrobial properties"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the wavelike action causing relaxation and contraction of the muscles of the gi tract.:::', 'the wavelike action causing relaxation and contraction of the muscles of the gi tract.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"🔴 Digestion: The process of breaking down food into small nutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Peristalsis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"🔴 Digestion: The process of breaking down food into small nutrients.\n🔴 Segmentation: Back-and-forth mixing of food in the intestine.\n🔴 Excretion: The removal of waste products from the body.","whyWrongChoices":"Alternative options: Digestion, Segmentation, Excretion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bf is a 61-year-old female diagnosed with cancer of the stomach and has been bedridden for the past one month; height 5’6’’, weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 calories per day. the attending physician decided to give her parenteral nutrition prior to a contemplated procedure. which of the following tna (total nutrient admixture) is best for this patient?:::nutriflex 1000 in 1250 ml', 'bf is a 61-year-old female diagnosed with cancer of the stomach and has been bedridden for the past one month; height 5’6’’, weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 calories per day. the attending physician decided to give her parenteral nutrition prior to a contemplated procedure. which of the following tna (total nutrient admixture) is best for this patient?', 'Nutriflex 1000 in 1250 ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patient BF is severely malnourished, has lost 10% of her body weight over 3 months, and has been surviving on a starvation-level intake of only 700 Calories per day. When a patient is chronically starved, starting Parenteral Nutrition at a full calorie load (like 1,400 or 1,500 Calories) can trigger fatal electrolyte shifts (hypophosphatemia, hypokalemia, and hypomagnesemia).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutriflex 1000 in 1250 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patient BF is severely malnourished, has lost 10% of her body weight over 3 months, and has been surviving on a starvation-level intake of only 700 Calories per day. When a patient is chronically starved, starting Parenteral Nutrition at a full calorie load (like 1,400 or 1,500 Calories) can trigger fatal electrolyte shifts (hypophosphatemia, hypokalemia, and hypomagnesemia).\n\nStandard safety guidelines dictate that for severely malnourished or starved patients, clinicians must \"start low and go slow.\" Nutritional support should be initiated at a conservative baseline of 15 to 20 kcal/kg of body weight. For a 50 kg patient, this equals an initial daily energy target of roughly 750 to 1,000 Calories.\n\nNutriflex 1000 in 1250 ml delivers exactly 1,000 Calories in a safe, controlled volume. This makes it the ideal, safe starter formula to initiate her clinical feeding therapy without triggering refeeding syndrome.","whyWrongChoices":"Alternative options: Nutriflex 1400 in 1875 ml, Nutriflex 1500 in 1250 ml., Nutriflex 1900 in 2500 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient with an oral temperature of 38.8 degrees celsius needs a proper nutrition intervention to support metabolic changes in the body. what should the rnd do?:::', 'a patient with an oral temperature of 38.8 degrees celsius needs a proper nutrition intervention to support metabolic changes in the body. what should the rnd do?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An oral temperature of 38.8°C indicates an active clinical fever (febrile state).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Give additional high biologic value protein and fluids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An oral temperature of 38.8°C indicates an active clinical fever (febrile state).\n\nFor every 1°C increase in core body temperature above normal, the Basal Metabolic Rate (BMR) spikes by approximately 13%. This rapid metabolic shift accelerates tissue breakdown, causing significant lean muscle mass degradation (hypercatabolism) and high fluid loss via sweating and respiration.\n\nTo counteract nitrogen wasting and maintain cellular integrity, the Registered Nutritionist-Dietitian (RND) must increase the patient''s intake of high biological value (HBV) proteins (such as eggs, milk, fish, and lean poultry), which are efficiently utilized by the body for tissue repair and immune synthesis. Concurrently, aggressive fluid replenishment is a non-negotiable priority to prevent dehydration and support cellular homeostasis.","whyWrongChoices":"Alternative options: Give 100% fruit juice, Increase intake of fats to compensate for decreased adiposity, Give salabat because ginger has antimicrobial properties"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diarrhea with occasional constipation, vague abdominal pain and occasional rectal bleeding are symptoms of amoebiasis. what type of diet must be prescribed by the rnd?:::liquid, bland and low residue', 'diarrhea with occasional constipation, vague abdominal pain and occasional rectal bleeding are symptoms of amoebiasis. what type of diet must be prescribed by the rnd?', 'Liquid, bland and low residue', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alternating diarrhea/constipation, vague abdominal pain, and blood in the stool is the classic presentation of intestinal Amoebiasis (caused by Entamoeba histolytica). Dietary mechanisms include:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liquid, bland and low residue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alternating diarrhea/constipation, vague abdominal pain, and blood in the stool is the classic presentation of intestinal Amoebiasis (caused by Entamoeba histolytica). Dietary mechanisms include:\n\n\t• Low Residue (Low Fiber): Minimizes fecal volume and eliminates roughage that could mechanically scratch or irritate the already inflamed, ulcerated colonic mucosa.\n\t• Bland: Excludes chemical irritants such as harsh spices, gastric stimulants, and heavy seasonings that can exacerbate abdominal cramping.\n\t• Liquid/Fluid Modification: Helps rest the gastrointestinal tract during the acute phase while actively replenishing vital fluids and electrolytes lost through diarrheal episodes to prevent dehydration.","whyWrongChoices":"Alternative options: High protein diet, High calorie, raw foods allowed as tolerated, Low fat diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diarrhea with occasional constipation, vague abdominal pain and occasional rectal bleeding are symptoms of amoebiasis. what type of diet must be prescribed by the rnd?:::', 'diarrhea with occasional constipation, vague abdominal pain and occasional rectal bleeding are symptoms of amoebiasis. what type of diet must be prescribed by the rnd?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alternating diarrhea/constipation, vague abdominal pain, and blood in the stool is the classic presentation of intestinal Amoebiasis (caused by Entamoeba histolytica). Dietary mechanisms include:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liquid, bland and low residue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alternating diarrhea/constipation, vague abdominal pain, and blood in the stool is the classic presentation of intestinal Amoebiasis (caused by Entamoeba histolytica). Dietary mechanisms include:\n\n\t• Low Residue (Low Fiber): Minimizes fecal volume and eliminates roughage that could mechanically scratch or irritate the already inflamed, ulcerated colonic mucosa.\n\t• Bland: Excludes chemical irritants such as harsh spices, gastric stimulants, and heavy seasonings that can exacerbate abdominal cramping.\n\t• Liquid/Fluid Modification: Helps rest the gastrointestinal tract during the acute phase while actively replenishing vital fluids and electrolytes lost through diarrheal episodes to prevent dehydration.","whyWrongChoices":"Alternative options: High protein diet, High calorie, raw foods allowed as tolerated, Low fat diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following micronutrients may be deficient among children with ascariasis lumbricoides:::iron and vitamin c', 'the following micronutrients may be deficient among children with ascariasis lumbricoides', 'Iron and Vitamin C', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ascaris lumbricoides (giant intestinal roundworms) thrive in the human small intestine, where they actively compete with the host child for nutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron and Vitamin C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ascaris lumbricoides (giant intestinal roundworms) thrive in the human small intestine, where they actively compete with the host child for nutrients.\n\n\t• Iron: Intestinal parasite infections damage the gut mucosa, impair absorption, and cause microscopic blood loss, heavily precipitating iron-deficiency anemia in children.\n\t• Vitamin C: Intestinal inflammation and a compromised gut lining impair the absorption of water-soluble vitamins like Vitamin C. Because Vitamin C is chemically required to reduce ferric iron to ferrous iron for absorption in the gut, a concurrent drop in Vitamin C worsens the child''s iron deficiency.\n\n• Zinc and Vitamin C: While zinc deficiency is common in soil-transmitted helminth infections, it is paired with Vitamin C in option D, whereas Iron and Vitamin C is the specific paired textbook key used for this question format.","whyWrongChoices":"Alternative options: Calcium and Vitamin D, Zinc and Vitamin C, Iron and Calcium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following micronutrients may be deficient among children with ascariasis lumbricoides:::', 'the following micronutrients may be deficient among children with ascariasis lumbricoides', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ascaris lumbricoides (giant intestinal roundworms) thrive in the human small intestine, where they actively compete with the host child for nutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron and Vitamin C\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ascaris lumbricoides (giant intestinal roundworms) thrive in the human small intestine, where they actively compete with the host child for nutrients.\n\n\t• Iron: Intestinal parasite infections damage the gut mucosa, impair absorption, and cause microscopic blood loss, heavily precipitating iron-deficiency anemia in children.\n\t• Vitamin C: Intestinal inflammation and a compromised gut lining impair the absorption of water-soluble vitamins like Vitamin C. Because Vitamin C is chemically required to reduce ferric iron to ferrous iron for absorption in the gut, a concurrent drop in Vitamin C worsens the child''s iron deficiency.\n\n• Zinc and Vitamin C: While zinc deficiency is common in soil-transmitted helminth infections, it is paired with Vitamin C in option D, whereas Iron and Vitamin C is the specific paired textbook key used for this question format.","whyWrongChoices":"Alternative options: Calcium and Vitamin D, Zinc and Vitamin C, Iron and Calcium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for malaria includes a high protein and high carbohydrate diet by increases total caloric intake by how much? 10% 25% 30% 50%:::50%', 'dietary management for malaria includes a high protein and high carbohydrate diet by increases total caloric intake by how much? 10% 25% 30% 50%', '50%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Plasmodium species infection triggers the release of pro-inflammatory cytokines such as tumor necrosis factor-alpha (TNF-alpha), interleukin-1 (IL-1), and interleukin-6 (IL-6), which upregulate hepatic acute-phase protein synthesis and accelerate whole-body protein degradation. To mitigate this hypercatabolic response, medical nutrition therapy dictates an increase in total resting energy expenditure (REE) by approximately 50%, alongside high carbohydrate provision to spare lean body mass and high protein delivery (1.5 to 2.0 g/kg/day) to support tissue repair and immune cell proliferation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"50%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Plasmodium species infection triggers the release of pro-inflammatory cytokines such as tumor necrosis factor-alpha (TNF-alpha), interleukin-1 (IL-1), and interleukin-6 (IL-6), which upregulate hepatic acute-phase protein synthesis and accelerate whole-body protein degradation. To mitigate this hypercatabolic response, medical nutrition therapy dictates an increase in total resting energy expenditure (REE) by approximately 50%, alongside high carbohydrate provision to spare lean body mass and high protein delivery (1.5 to 2.0 g/kg/day) to support tissue repair and immune cell proliferation.","whyWrongChoices":"Alternative options: 30%, 25%, 10%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for malaria includes a high protein and high carbohydrate diet by increases total caloric intake by how much? 10% 25% 30% 50%:::', 'dietary management for malaria includes a high protein and high carbohydrate diet by increases total caloric intake by how much? 10% 25% 30% 50%', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Plasmodium species infection triggers the release of pro-inflammatory cytokines such as tumor necrosis factor-alpha (TNF-alpha), interleukin-1 (IL-1), and interleukin-6 (IL-6), which upregulate hepatic acute-phase protein synthesis and accelerate whole-body protein degradation. To mitigate this hypercatabolic response, medical nutrition therapy dictates an increase in total resting energy expenditure (REE) by approximately 50%, alongside high carbohydrate provision to spare lean body mass and high protein delivery (1.5 to 2.0 g/kg/day) to support tissue repair and immune cell proliferation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"50%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Plasmodium species infection triggers the release of pro-inflammatory cytokines such as tumor necrosis factor-alpha (TNF-alpha), interleukin-1 (IL-1), and interleukin-6 (IL-6), which upregulate hepatic acute-phase protein synthesis and accelerate whole-body protein degradation. To mitigate this hypercatabolic response, medical nutrition therapy dictates an increase in total resting energy expenditure (REE) by approximately 50%, alongside high carbohydrate provision to spare lean body mass and high protein delivery (1.5 to 2.0 g/kg/day) to support tissue repair and immune cell proliferation.","whyWrongChoices":"Alternative options: 30%, 25%, 10%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:cholera is an acute dehydrating disease caused by vibrio cholerae. it’s symptoms include profuse rice water-like, mucoid stools with fish odor. the primary nutrition intervention goal is:::intravenous fluid and electrolyte replacement', 'cholera is an acute dehydrating disease caused by vibrio cholerae. it’s symptoms include profuse rice water-like, mucoid stools with fish odor. the primary nutrition intervention goal is', 'Intravenous fluid and electrolyte replacement', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In acute Cholera, the sheer volume of profuse, watery stools can deplete a patient''s entire blood volume and electrolytes within hours, leading to severe hypovolemic shock and death. Therefore, the immediate, life-saving primary intervention goal is the rapid replenishment of fluid and electrolyte losses, typically achieved via intravenous (IV) fluids for severe cases or Oral Rehydration Salts (ORS) for mild-to-moderate dehydration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Intravenous fluid and electrolyte replacement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In acute Cholera, the sheer volume of profuse, watery stools can deplete a patient''s entire blood volume and electrolytes within hours, leading to severe hypovolemic shock and death. Therefore, the immediate, life-saving primary intervention goal is the rapid replenishment of fluid and electrolyte losses, typically achieved via intravenous (IV) fluids for severe cases or Oral Rehydration Salts (ORS) for mild-to-moderate dehydration.\n\nWhile introducing a soft, bland, or high-calorie diet to correct nutrient deficiencies is important for long-term recovery once the gut stabilizes, these nutritional interventions are completely impossible and ineffective during the acute phase until the patient is hemodynamically stable and rehydrated.","whyWrongChoices":"Alternative options: Soft and bland diet, Correct nutrient deficiencies, High caloric diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:cholera is an acute dehydrating disease caused by vibrio cholerae. it’s symptoms include profuse rice water-like, mucoid stools with fish odor. the primary nutrition intervention goal is:::', 'cholera is an acute dehydrating disease caused by vibrio cholerae. it’s symptoms include profuse rice water-like, mucoid stools with fish odor. the primary nutrition intervention goal is', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In acute Cholera, the sheer volume of profuse, watery stools can deplete a patient''s entire blood volume and electrolytes within hours, leading to severe hypovolemic shock and death. Therefore, the immediate, life-saving primary intervention goal is the rapid replenishment of fluid and electrolyte losses, typically achieved via intravenous (IV) fluids for severe cases or Oral Rehydration Salts (ORS) for mild-to-moderate dehydration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Intravenous fluid and electrolyte replacement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In acute Cholera, the sheer volume of profuse, watery stools can deplete a patient''s entire blood volume and electrolytes within hours, leading to severe hypovolemic shock and death. Therefore, the immediate, life-saving primary intervention goal is the rapid replenishment of fluid and electrolyte losses, typically achieved via intravenous (IV) fluids for severe cases or Oral Rehydration Salts (ORS) for mild-to-moderate dehydration.\n\nWhile introducing a soft, bland, or high-calorie diet to correct nutrient deficiencies is important for long-term recovery once the gut stabilizes, these nutritional interventions are completely impossible and ineffective during the acute phase until the patient is hemodynamically stable and rehydrated.","whyWrongChoices":"Alternative options: Soft and bland diet, Correct nutrient deficiencies, High caloric diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient presents with the following signs and symptoms of infection: weakness, anorexia, cough, red tongue, fever and pea green colored stool. what could be the patient’s medical condition?:::typhoid fever', 'a patient presents with the following signs and symptoms of infection: weakness, anorexia, cough, red tongue, fever and pea green colored stool. what could be the patient’s medical condition?', 'Typhoid fever', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The presence of a persistent fever, generalized weakness, anoxia, a cough, and a furred tongue with prominent red edges and tip (traditionally referred to as a \"typhoid tongue\") are classic clinical presentations of a Salmonella Typhi infection.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Typhoid fever\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The presence of a persistent fever, generalized weakness, anoxia, a cough, and a furred tongue with prominent red edges and tip (traditionally referred to as a \"typhoid tongue\") are classic clinical presentations of a Salmonella Typhi infection.\n\nA defining, textbook feature of Typhoid fever is the development of a slimy, yellow-green liquid diarrhea. Often referred to in board exam vignettes as pea-green or pea-soup colored stool, it is caused by severe localized inflammation, purulent exudates, and necrosis within the intestinal Peyer''s patches mixing with mucosal bile.\n\n• Dengue: Characterized by high fevers, severe muscle/joint aches (\"breakbone fever\"), headaches, and a distinctive rash, but it does not cause pea-green diarrhea or an inflamed red tongue.\n• Meningitis: A neurological infection presenting with a high fever, severe headache, rigid stiff neck (nuchal rigidity), and altered mental status rather than a primary gastrointestinal illness.\n• Cholera: While it is a major waterborne disease, cholera produces massive volumes of profuse, painless diarrhea classically described as clear \"rice-water\" stool with a fishy odor, completely distinct from the thick, greenish-yellow pea-soup diarrhea of typhoid.","whyWrongChoices":"Alternative options: Cholera, Meningitis, Dengue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient presents with the following signs and symptoms of infection: weakness, anorexia, cough, red tongue, fever and pea green colored stool. what could be the patient’s medical condition?:::', 'a patient presents with the following signs and symptoms of infection: weakness, anorexia, cough, red tongue, fever and pea green colored stool. what could be the patient’s medical condition?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The presence of a persistent fever, generalized weakness, anoxia, a cough, and a furred tongue with prominent red edges and tip (traditionally referred to as a \"typhoid tongue\") are classic clinical presentations of a Salmonella Typhi infection.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Typhoid fever\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The presence of a persistent fever, generalized weakness, anoxia, a cough, and a furred tongue with prominent red edges and tip (traditionally referred to as a \"typhoid tongue\") are classic clinical presentations of a Salmonella Typhi infection.\n\nA defining, textbook feature of Typhoid fever is the development of a slimy, yellow-green liquid diarrhea. Often referred to in board exam vignettes as pea-green or pea-soup colored stool, it is caused by severe localized inflammation, purulent exudates, and necrosis within the intestinal Peyer''s patches mixing with mucosal bile.\n\n• Dengue: Characterized by high fevers, severe muscle/joint aches (\"breakbone fever\"), headaches, and a distinctive rash, but it does not cause pea-green diarrhea or an inflamed red tongue.\n• Meningitis: A neurological infection presenting with a high fever, severe headache, rigid stiff neck (nuchal rigidity), and altered mental status rather than a primary gastrointestinal illness.\n• Cholera: While it is a major waterborne disease, cholera produces massive volumes of profuse, painless diarrhea classically described as clear \"rice-water\" stool with a fishy odor, completely distinct from the thick, greenish-yellow pea-soup diarrhea of typhoid.","whyWrongChoices":"Alternative options: Cholera, Meningitis, Dengue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient diagnosed with rheumatic fever was prescribed cortisone. nutrition intervention must include:::sodium restriction 1000mg/day', 'a patient diagnosed with rheumatic fever was prescribed cortisone. nutrition intervention must include', 'Sodium restriction 1000mg/day', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While cortisone actively wastes potassium (making potassium-rich foods clinically necessary), the test creator targets sodium restriction based on the following textbook rationale:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sodium restriction 1000mg/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While cortisone actively wastes potassium (making potassium-rich foods clinically necessary), the test creator targets sodium restriction based on the following textbook rationale:\n\n1. Fluid Retention and Edema: Cortisone heavily promotes sodium and fluid retention inside the body. In a patient with Rheumatic Fever, this fluid retention is highly dangerous because the disease can cause inflammation of the heart (rheumatic carditis).\n2. Preventing Heart Strain: Introducing a strict sodium restriction helps prevent fluid overload, peripheral edema, and hypertension, which directly protects the heart muscles from being overtaxed during the acute phase of Rheumatic Fever.","whyWrongChoices":"Alternative options: Potassium rich food, Iron supplementation, Increased fluid intake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient diagnosed with rheumatic fever was prescribed cortisone. nutrition intervention must include:::', 'a patient diagnosed with rheumatic fever was prescribed cortisone. nutrition intervention must include', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While cortisone actively wastes potassium (making potassium-rich foods clinically necessary), the test creator targets sodium restriction based on the following textbook rationale:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sodium restriction 1000mg/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While cortisone actively wastes potassium (making potassium-rich foods clinically necessary), the test creator targets sodium restriction based on the following textbook rationale:\n\n1. Fluid Retention and Edema: Cortisone heavily promotes sodium and fluid retention inside the body. In a patient with Rheumatic Fever, this fluid retention is highly dangerous because the disease can cause inflammation of the heart (rheumatic carditis).\n2. Preventing Heart Strain: Introducing a strict sodium restriction helps prevent fluid overload, peripheral edema, and hypertension, which directly protects the heart muscles from being overtaxed during the acute phase of Rheumatic Fever.","whyWrongChoices":"Alternative options: Potassium rich food, Iron supplementation, Increased fluid intake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:isoniazid, a drug for tuberculosis treatment, is a vitamin b6 (pyridoxine) antagonist. patients on this medication must be advised to eat more of the following:::egg, carrots, camote, tuna, beef, banana and peas', 'isoniazid, a drug for tuberculosis treatment, is a vitamin b6 (pyridoxine) antagonist. patients on this medication must be advised to eat more of the following', 'Egg, carrots, camote, tuna, beef, banana and peas', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Isoniazid (INH) actively competes with and inhibits the activation of Vitamin B6 (Pyridoxine), which can precipitate severe peripheral neuropathy (manifesting as burning, numbness, or tingling in the extremities).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Egg, carrots, camote, tuna, beef, banana and peas\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Isoniazid (INH) actively competes with and inhibits the activation of Vitamin B6 (Pyridoxine), which can precipitate severe peripheral neuropathy (manifesting as burning, numbness, or tingling in the extremities).\n\nTo naturally optimize B6 levels alongside standard clinical supplementation, patients should prioritize foods dense in Pyridoxine. This option provides an exceptionally rich combination of animal and plant-based Vitamin B6 sources, including tuna, beef, banana, peas, and camote (sweet potato).","whyWrongChoices":"Alternative options: Apple, bread, rice, cabbage, ginger, Soup, collagen, radish, eggplant, rice, Peanut butter, fish, rice, potato, garlic"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:isoniazid, a drug for tuberculosis treatment, is a vitamin b6 (pyridoxine) antagonist. patients on this medication must be advised to eat more of the following:::', 'isoniazid, a drug for tuberculosis treatment, is a vitamin b6 (pyridoxine) antagonist. patients on this medication must be advised to eat more of the following', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Isoniazid (INH) actively competes with and inhibits the activation of Vitamin B6 (Pyridoxine), which can precipitate severe peripheral neuropathy (manifesting as burning, numbness, or tingling in the extremities).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Egg, carrots, camote, tuna, beef, banana and peas\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Isoniazid (INH) actively competes with and inhibits the activation of Vitamin B6 (Pyridoxine), which can precipitate severe peripheral neuropathy (manifesting as burning, numbness, or tingling in the extremities).\n\nTo naturally optimize B6 levels alongside standard clinical supplementation, patients should prioritize foods dense in Pyridoxine. This option provides an exceptionally rich combination of animal and plant-based Vitamin B6 sources, including tuna, beef, banana, peas, and camote (sweet potato).","whyWrongChoices":"Alternative options: Apple, bread, rice, cabbage, ginger, Soup, collagen, radish, eggplant, rice, Peanut butter, fish, rice, potato, garlic"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient diagnosed with tuberculosis has normal bmi. how much protein should be prescribed per day?:::high protein 75 to 120g per day', 'a patient diagnosed with tuberculosis has normal bmi. how much protein should be prescribed per day?', 'High protein 75 to 120g per day', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Active Tuberculosis (TB) places the body in an intense inflammatory and hypercatabolic state, resulting in accelerated muscle tissue breakdown and nitrogen wasting. Even if a patient presents with a normal BMI, they require aggressive nutritional therapy to counter cellular destruction, maintain lean muscle mass, and optimize immune function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High protein 75 to 120g per day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Active Tuberculosis (TB) places the body in an intense inflammatory and hypercatabolic state, resulting in accelerated muscle tissue breakdown and nitrogen wasting. Even if a patient presents with a normal BMI, they require aggressive nutritional therapy to counter cellular destruction, maintain lean muscle mass, and optimize immune function.\n\nMedical nutrition therapy (MNT) guidelines dictate increasing a TB patient''s protein intake above the normal baseline to support tissue healing and recovery. Clinical protocols emphasize incorporating adequate high-biological-value protein into the daily diet to support complete tissue healing.","whyWrongChoices":"Alternative options: Low protein 40g per day, 0.6g/kg body weight, 2g/kg body weight"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient diagnosed with tuberculosis has normal bmi. how much protein should be prescribed per day?:::', 'a patient diagnosed with tuberculosis has normal bmi. how much protein should be prescribed per day?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Active Tuberculosis (TB) places the body in an intense inflammatory and hypercatabolic state, resulting in accelerated muscle tissue breakdown and nitrogen wasting. Even if a patient presents with a normal BMI, they require aggressive nutritional therapy to counter cellular destruction, maintain lean muscle mass, and optimize immune function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High protein 75 to 120g per day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Active Tuberculosis (TB) places the body in an intense inflammatory and hypercatabolic state, resulting in accelerated muscle tissue breakdown and nitrogen wasting. Even if a patient presents with a normal BMI, they require aggressive nutritional therapy to counter cellular destruction, maintain lean muscle mass, and optimize immune function.\n\nMedical nutrition therapy (MNT) guidelines dictate increasing a TB patient''s protein intake above the normal baseline to support tissue healing and recovery. Clinical protocols emphasize incorporating adequate high-biological-value protein into the daily diet to support complete tissue healing.","whyWrongChoices":"Alternative options: Low protein 40g per day, 0.6g/kg body weight, 2g/kg body weight"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient with dengue hemorrhagic fever must avoid:::chocolate drink', 'a patient with dengue hemorrhagic fever must avoid', 'Chocolate drink', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients diagnosed with Dengue Hemorrhagic Fever (DHF) must strictly avoid dark-colored foods and beverages, such as chocolate drinks, cola, coffee, red/violet juices, and dark berries.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chocolate drink\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients diagnosed with Dengue Hemorrhagic Fever (DHF) must strictly avoid dark-colored foods and beverages, such as chocolate drinks, cola, coffee, red/violet juices, and dark berries.\n\nDHF compromises blood capillaries and dramatically reduces blood platelets, placing the patient at a severe risk for internal gastrointestinal (GI) bleeding. If a patient consumes a chocolate drink, it can discolor their vomit or stool, staining it dark brown or black. This masks clinical signs of active GI bleeding (such as hematemesis or melena), confusing the medical team and potentially delaying life-saving emergency care.\n\n• Dark leafy vegetables: While green, they do not dye stool or vomit the distinctive tarry black or dark brown color associated with internal bleeding. In fact, they provide vital Vitamin K to support proper clotting pathways.\n• Hard candies & Apple juice: These options are clear or translucent, making them completely safe for hydration and carbohydrate maintenance without interfering with medical observations.","whyWrongChoices":"Alternative options: Hard candies, Dark leafy vegetables, Apple juice"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient with dengue hemorrhagic fever must avoid:::', 'a patient with dengue hemorrhagic fever must avoid', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients diagnosed with Dengue Hemorrhagic Fever (DHF) must strictly avoid dark-colored foods and beverages, such as chocolate drinks, cola, coffee, red/violet juices, and dark berries.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chocolate drink\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients diagnosed with Dengue Hemorrhagic Fever (DHF) must strictly avoid dark-colored foods and beverages, such as chocolate drinks, cola, coffee, red/violet juices, and dark berries.\n\nDHF compromises blood capillaries and dramatically reduces blood platelets, placing the patient at a severe risk for internal gastrointestinal (GI) bleeding. If a patient consumes a chocolate drink, it can discolor their vomit or stool, staining it dark brown or black. This masks clinical signs of active GI bleeding (such as hematemesis or melena), confusing the medical team and potentially delaying life-saving emergency care.\n\n• Dark leafy vegetables: While green, they do not dye stool or vomit the distinctive tarry black or dark brown color associated with internal bleeding. In fact, they provide vital Vitamin K to support proper clotting pathways.\n• Hard candies & Apple juice: These options are clear or translucent, making them completely safe for hydration and carbohydrate maintenance without interfering with medical observations.","whyWrongChoices":"Alternative options: Hard candies, Dark leafy vegetables, Apple juice"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food safety is essential in managing patients with aids. the following are food safety measures to be observed except:::keep cold food at 35 to 50 degrees fahrenheit', 'food safety is essential in managing patients with aids. the following are food safety measures to be observed except', 'Keep cold food at 35 to 50 degrees Fahrenheit', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical food safety protocols, cold food must strictly be maintained at or below 40°F (4°C) (or 41°F depending on localized sanitary code references like ServSafe or the FDA) to inhibit pathogenic bacterial multiplication.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Keep cold food at 35 to 50 degrees Fahrenheit\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical food safety protocols, cold food must strictly be maintained at or below 40°F (4°C) (or 41°F depending on localized sanitary code references like ServSafe or the FDA) to inhibit pathogenic bacterial multiplication.\n\nStating that cold foods can be kept up to 50°F directly breaches the [Food Temperature Danger Zone (40°F to 140°F)](usda.gov \"\"Danger Zone\" (40°F - 140°F)\"). Allowing cold food temperatures to climb to 50°F allows highly dangerous, opportunistic pathogens like Salmonella, Listeria monocytogenes, and E. coli to rapidly multiply. For immunocompromised individuals, such as patients with AIDS, this minor temperature elevation can lead to a severe, life-threatening foodborne infection.","whyWrongChoices":"Alternative options: Discard eggs with cracked shells, Avoid serving raw fruits and vegetables, Thaw chicken in the refrigerator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food safety is essential in managing patients with aids. the following are food safety measures to be observed except:::', 'food safety is essential in managing patients with aids. the following are food safety measures to be observed except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical food safety protocols, cold food must strictly be maintained at or below 40°F (4°C) (or 41°F depending on localized sanitary code references like ServSafe or the FDA) to inhibit pathogenic bacterial multiplication.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Keep cold food at 35 to 50 degrees Fahrenheit\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical food safety protocols, cold food must strictly be maintained at or below 40°F (4°C) (or 41°F depending on localized sanitary code references like ServSafe or the FDA) to inhibit pathogenic bacterial multiplication.\n\nStating that cold foods can be kept up to 50°F directly breaches the [Food Temperature Danger Zone (40°F to 140°F)](usda.gov \"\"Danger Zone\" (40°F - 140°F)\"). Allowing cold food temperatures to climb to 50°F allows highly dangerous, opportunistic pathogens like Salmonella, Listeria monocytogenes, and E. coli to rapidly multiply. For immunocompromised individuals, such as patients with AIDS, this minor temperature elevation can lead to a severe, life-threatening foodborne infection.","whyWrongChoices":"Alternative options: Discard eggs with cracked shells, Avoid serving raw fruits and vegetables, Thaw chicken in the refrigerator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:stage 1 dietary management of poliomyelitis includes 30 to 200 ml tube feeding alternating with water every:::2 hours', 'stage 1 dietary management of poliomyelitis includes 30 to 200 ml tube feeding alternating with water every', '2 hours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In older, traditional diet therapy manuals for acute infectious neurological disorders like poliomyelitis (particularly cases affecting the bulbar region, which impairs normal swallowing mechanics), Stage 1 protocols utilize tube feeding to guarantee safe nutrition without aspiration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In older, traditional diet therapy manuals for acute infectious neurological disorders like poliomyelitis (particularly cases affecting the bulbar region, which impairs normal swallowing mechanics), Stage 1 protocols utilize tube feeding to guarantee safe nutrition without aspiration.\n\nThe standard textbook framework states that the patient should be given 30 to 200 ml of formula via tube feeding, wait 2 hours, and then alternate with water. Spacing the administration out every 2 hours prevents overwhelming the patient''s gastric capacity, minimizes the risk of regurgitation, and keeps the patient safely hydrated while their swallowing reflexes are heavily compromised.\n\n*When you encounter this question on your exam, remember this specific gastrointestinal-pacing formula for acute polio management: Tube feeding, wait 2 hours, then water.","whyWrongChoices":"Alternative options: 1 hour, 5 hours, 3 hours"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:stage 1 dietary management of poliomyelitis includes 30 to 200 ml tube feeding alternating with water every:::', 'stage 1 dietary management of poliomyelitis includes 30 to 200 ml tube feeding alternating with water every', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In older, traditional diet therapy manuals for acute infectious neurological disorders like poliomyelitis (particularly cases affecting the bulbar region, which impairs normal swallowing mechanics), Stage 1 protocols utilize tube feeding to guarantee safe nutrition without aspiration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In older, traditional diet therapy manuals for acute infectious neurological disorders like poliomyelitis (particularly cases affecting the bulbar region, which impairs normal swallowing mechanics), Stage 1 protocols utilize tube feeding to guarantee safe nutrition without aspiration.\n\nThe standard textbook framework states that the patient should be given 30 to 200 ml of formula via tube feeding, wait 2 hours, and then alternate with water. Spacing the administration out every 2 hours prevents overwhelming the patient''s gastric capacity, minimizes the risk of regurgitation, and keeps the patient safely hydrated while their swallowing reflexes are heavily compromised.\n\n*When you encounter this question on your exam, remember this specific gastrointestinal-pacing formula for acute polio management: Tube feeding, wait 2 hours, then water.","whyWrongChoices":"Alternative options: 1 hour, 5 hours, 3 hours"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient with severe acute respiratory syndrome must wear surgical mask at all times except when:::eating', 'a patient with severe acute respiratory syndrome must wear surgical mask at all times except when', 'Eating', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A patient cannot physically consume food or fluids while wearing a surgical mask. Therefore, eating (and drinking) is the only practical and necessary exception where the mask must be temporarily removed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Eating\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A patient cannot physically consume food or fluids while wearing a surgical mask. Therefore, eating (and drinking) is the only practical and necessary exception where the mask must be temporarily removed.\n\nDuring these temporary mask-off periods, strict isolation precautions—such as maintaining negative pressure ventilation, keeping the patient in a private room, and ensuring healthcare workers wear appropriate personal protective equipment (PPE) like N95 respirators—are vital to prevent the transmission of respiratory droplets or aerosols.","whyWrongChoices":"Alternative options: Sleeping, Resting, Exercising"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the one animal polysaccharide that is not present in foods but is generally stored in the liver and muscle::::', 'the one animal polysaccharide that is not present in foods but is generally stored in the liver and muscle:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycogen is the storage form of carbohydrates in animals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glycogen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycogen is the storage form of carbohydrates in animals.","whyWrongChoices":"Alternative options: Lignin, Polymer, Lecithin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient with severe acute respiratory syndrome must wear surgical mask at all times except when:::', 'a patient with severe acute respiratory syndrome must wear surgical mask at all times except when', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A patient cannot physically consume food or fluids while wearing a surgical mask. Therefore, eating (and drinking) is the only practical and necessary exception where the mask must be temporarily removed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Eating\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A patient cannot physically consume food or fluids while wearing a surgical mask. Therefore, eating (and drinking) is the only practical and necessary exception where the mask must be temporarily removed.\n\nDuring these temporary mask-off periods, strict isolation precautions—such as maintaining negative pressure ventilation, keeping the patient in a private room, and ensuring healthcare workers wear appropriate personal protective equipment (PPE) like N95 respirators—are vital to prevent the transmission of respiratory droplets or aerosols.","whyWrongChoices":"Alternative options: Sleeping, Resting, Exercising"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:middle east respiratory syndrome or mers-cov can be transmitted through:::camel milk and meat', 'middle east respiratory syndrome or mers-cov can be transmitted through', 'Camel milk and meat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Middle East Respiratory Syndrome (MERS-CoV) is a zoonotic viral respiratory illness, meaning it is transmitted from animals to humans. Extensive epidemiological studies by global health bodies have confirmed that dromedary camels serve as the primary animal host reservoir for the virus.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Camel milk and meat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Middle East Respiratory Syndrome (MERS-CoV) is a zoonotic viral respiratory illness, meaning it is transmitted from animals to humans. Extensive epidemiological studies by global health bodies have confirmed that dromedary camels serve as the primary animal host reservoir for the virus.\n\nWhile the virus can also spread through direct physical contact with live animals, humans can contract the infection by consuming contaminated, unpasteurized camel products—specifically raw camel milk and undercooked camel meat. Because the virus is heat-sensitive, global public health authorities strictly advise pasteurizing milk and thoroughly cooking meat to eliminate transmission risks.","whyWrongChoices":"Alternative options: Human excreta, Blood, Droplet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:middle east respiratory syndrome or mers-cov can be transmitted through:::', 'middle east respiratory syndrome or mers-cov can be transmitted through', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Middle East Respiratory Syndrome (MERS-CoV) is a zoonotic viral respiratory illness, meaning it is transmitted from animals to humans. Extensive epidemiological studies by global health bodies have confirmed that dromedary camels serve as the primary animal host reservoir for the virus.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Camel milk and meat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Middle East Respiratory Syndrome (MERS-CoV) is a zoonotic viral respiratory illness, meaning it is transmitted from animals to humans. Extensive epidemiological studies by global health bodies have confirmed that dromedary camels serve as the primary animal host reservoir for the virus.\n\nWhile the virus can also spread through direct physical contact with live animals, humans can contract the infection by consuming contaminated, unpasteurized camel products—specifically raw camel milk and undercooked camel meat. Because the virus is heat-sensitive, global public health authorities strictly advise pasteurizing milk and thoroughly cooking meat to eliminate transmission risks.","whyWrongChoices":"Alternative options: Human excreta, Blood, Droplet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:virgin coconut oil has antimicrobial properties. how much vco must be given to a patient weighing 176 lbs during the first day of treatment?:::48ml', 'virgin coconut oil has antimicrobial properties. how much vco must be given to a patient weighing 176 lbs during the first day of treatment?', '48ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Virgin coconut oil (VCO) has been studied for its potential antimicrobial and antiviral properties. Research involving VCO often explores its components, such as medium-chain triglycerides (MCTs) like lauric acid, which are believed to contribute to these properties. Clinical protocols and studies evaluate various amounts of VCO for supportive care, but determining any specific usage requires professional medical evaluation based on an individual''s health status and needs.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"48ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Virgin coconut oil (VCO) has been studied for its potential antimicrobial and antiviral properties. Research involving VCO often explores its components, such as medium-chain triglycerides (MCTs) like lauric acid, which are believed to contribute to these properties. Clinical protocols and studies evaluate various amounts of VCO for supportive care, but determining any specific usage requires professional medical evaluation based on an individual''s health status and needs.\n\nA specific weight-based formula was used in clinical trial protocols by the Department of Science and Technology (DOST). These clinical trials (such as the DOST-FNRI studies on the antiviral and antimicrobial properties of VCO) use a strict dosage protocol based on a patient’s body weight in kilograms to allow the gut to safely adjust:\n• First 3 days (Initial Dose): 0.6 mL of VCO per kilogram of body weight (0.6 mL/kg BW).\n• Day 4 to 28 (Succeeding Dose): 1.2 mL of VCO per kilogram of body weight (1.2 mL/kg BW).\n\n1. Convert the patient''s weight from pounds to kilograms:\n176 lbs / 2.2 = 80 kg\n2. Calculate the first-day dosage (using the initial 0.6 mL/kg factor):\n80 kg x 0.6 mL/kg = 48 mL","whyWrongChoices":"Alternative options: 60ml, 50ml, 96ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
