INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:hiv virus may be transmitted from mother to fetus through pregnancy. the virus is also found in breastmilk in low concentrations. the rnd must:::', 'hiv virus may be transmitted from mother to fetus through pregnancy. the virus is also found in breastmilk in low concentrations. the rnd must', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Exclusive breastfeeding for the first 6 months of life, combined with maternal antiretroviral therapy (ART) that achieves viral suppression, significantly reduces postnatal mother-to-child transmission (MTCT) of HIV while drastically lowering infant mortality from infectious diseases compared to replacement feeding. Breast milk provides optimal immunological factors (such as secretory IgA, lactoferrin, and leukocytes) and complete nutrition, which protect against gastrointestinal and respiratory infections that are fatal in non-breastfed infants in high-mortality contexts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Encourage breastfeeding exclusively\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Exclusive breastfeeding for the first 6 months of life, combined with maternal antiretroviral therapy (ART) that achieves viral suppression, significantly reduces postnatal mother-to-child transmission (MTCT) of HIV while drastically lowering infant mortality from infectious diseases compared to replacement feeding. Breast milk provides optimal immunological factors (such as secretory IgA, lactoferrin, and leukocytes) and complete nutrition, which protect against gastrointestinal and respiratory infections that are fatal in non-breastfed infants in high-mortality contexts.","whyWrongChoices":"Alternative options: Not recommend breastfeeding, Recommend infant formula, Recommend plant based milk"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the normal range of body temperature is:::36.1 to 37.2 degrees celsius', 'the normal range of body temperature is', '36.1 to 37.2 degrees Celsius', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While 37°C (98.6°F) is universally recognized as the standard average human body temperature, normal physiological baselines safely fluctuate within a broader dynamic range.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"36.1 to 37.2 degrees Celsius\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While 37°C (98.6°F) is universally recognized as the standard average human body temperature, normal physiological baselines safely fluctuate within a broader dynamic range.\n\nThe medically accepted range of 97°F to 99°F directly converts to 36.1°C to 37.2°C. Temperatures within this bracket are considered afebrile (normal and without fever).","whyWrongChoices":"Alternative options: 35 to 37 degrees Celsius, 35.5 to 37.4 degrees Celsius, 36 to 36.8 degrees Celsius"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:virgin coconut oil has antimicrobial properties. how much vco must be given to a patient weighing 176 lbs during the first day of treatment?:::', 'virgin coconut oil has antimicrobial properties. how much vco must be given to a patient weighing 176 lbs during the first day of treatment?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Virgin coconut oil (VCO) has been studied for its potential antimicrobial and antiviral properties. Research involving VCO often explores its components, such as medium-chain triglycerides (MCTs) like lauric acid, which are believed to contribute to these properties. Clinical protocols and studies evaluate various amounts of VCO for supportive care, but determining any specific usage requires professional medical evaluation based on an individual''s health status and needs.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"48ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Virgin coconut oil (VCO) has been studied for its potential antimicrobial and antiviral properties. Research involving VCO often explores its components, such as medium-chain triglycerides (MCTs) like lauric acid, which are believed to contribute to these properties. Clinical protocols and studies evaluate various amounts of VCO for supportive care, but determining any specific usage requires professional medical evaluation based on an individual''s health status and needs.\n\nA specific weight-based formula was used in clinical trial protocols by the Department of Science and Technology (DOST). These clinical trials (such as the DOST-FNRI studies on the antiviral and antimicrobial properties of VCO) use a strict dosage protocol based on a patient’s body weight in kilograms to allow the gut to safely adjust:\n• First 3 days (Initial Dose): 0.6 mL of VCO per kilogram of body weight (0.6 mL/kg BW).\n• Day 4 to 28 (Succeeding Dose): 1.2 mL of VCO per kilogram of body weight (1.2 mL/kg BW).\n\n1. Convert the patient''s weight from pounds to kilograms:\n176 lbs / 2.2 = 80 kg\n2. Calculate the first-day dosage (using the initial 0.6 mL/kg factor):\n80 kg x 0.6 mL/kg = 48 mL","whyWrongChoices":"Alternative options: 60ml, 50ml, 96ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a food and water borne disease that affects the liver resulting to jaundice, severe anorexia, nausea, vomiting and abdominal tenderness:::hepatitis a', 'a food and water borne disease that affects the liver resulting to jaundice, severe anorexia, nausea, vomiting and abdominal tenderness', 'Hepatitis A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hepatitis A is a highly contagious liver infection caused by the Hepatitis A virus (HAV). It is classically defined as a food- and water-borne disease because it spreads primarily via the fecal-oral route. Transmission happens when a person ingests food or water contaminated with the feces of an infected individual (often due to poor hand hygiene or inadequate sewage treatment).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hepatitis A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hepatitis A is a highly contagious liver infection caused by the Hepatitis A virus (HAV). It is classically defined as a food- and water-borne disease because it spreads primarily via the fecal-oral route. Transmission happens when a person ingests food or water contaminated with the feces of an infected individual (often due to poor hand hygiene or inadequate sewage treatment).\n\n The virus multiplies inside the liver cells, sparking acute inflammation. This structural irritation produces a distinct, textbook cluster of gastrointestinal and hepatic symptoms:\n\t• Jaundice: Yellowing of the skin and the whites of the eyes caused by a buildup of bilirubin in the blood as the inflamed liver struggles to process it.\n\t• Severe Anorexia: A profound, sudden loss of appetite.\n\t• Nausea, Vomiting, and Abdominal Tenderness: Driven by an enlarged, inflamed liver (hepatomegaly) pressing against surrounding tissues in the right upper abdominal quadrant.\n\n• Hepatitis B & Hepatitis C: These viral infections are blood-borne and sexually transmitted pathogens. They spread via contact with infected bodily fluids, blood transfusions, or shared needles, rather than through contaminated food or drinking water.\n• Cirrhosis: This is a chronic, late-stage pathological condition characterized by irreversible scarring of the liver tissue. It is the long-term result of prolonged liver disease (like chronic alcoholism or chronic Hep B/C), not an acute foodborne illness.","whyWrongChoices":"Alternative options: Hepatitis C, Hepatitis B, Cirrhosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a food and water borne disease that affects the liver resulting to jaundice, severe anorexia, nausea, vomiting and abdominal tenderness:::', 'a food and water borne disease that affects the liver resulting to jaundice, severe anorexia, nausea, vomiting and abdominal tenderness', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hepatitis A is a highly contagious liver infection caused by the Hepatitis A virus (HAV). It is classically defined as a food- and water-borne disease because it spreads primarily via the fecal-oral route. Transmission happens when a person ingests food or water contaminated with the feces of an infected individual (often due to poor hand hygiene or inadequate sewage treatment).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hepatitis A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hepatitis A is a highly contagious liver infection caused by the Hepatitis A virus (HAV). It is classically defined as a food- and water-borne disease because it spreads primarily via the fecal-oral route. Transmission happens when a person ingests food or water contaminated with the feces of an infected individual (often due to poor hand hygiene or inadequate sewage treatment).\n\n The virus multiplies inside the liver cells, sparking acute inflammation. This structural irritation produces a distinct, textbook cluster of gastrointestinal and hepatic symptoms:\n\t• Jaundice: Yellowing of the skin and the whites of the eyes caused by a buildup of bilirubin in the blood as the inflamed liver struggles to process it.\n\t• Severe Anorexia: A profound, sudden loss of appetite.\n\t• Nausea, Vomiting, and Abdominal Tenderness: Driven by an enlarged, inflamed liver (hepatomegaly) pressing against surrounding tissues in the right upper abdominal quadrant.\n\n• Hepatitis B & Hepatitis C: These viral infections are blood-borne and sexually transmitted pathogens. They spread via contact with infected bodily fluids, blood transfusions, or shared needles, rather than through contaminated food or drinking water.\n• Cirrhosis: This is a chronic, late-stage pathological condition characterized by irreversible scarring of the liver tissue. It is the long-term result of prolonged liver disease (like chronic alcoholism or chronic Hep B/C), not an acute foodborne illness.","whyWrongChoices":"Alternative options: Hepatitis C, Hepatitis B, Cirrhosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:hiv virus may be transmitted from mother to fetus through pregnancy. the virus is also found in breastmilk in low concentrations. the rnd must:::encourage breastfeeding exclusively', 'hiv virus may be transmitted from mother to fetus through pregnancy. the virus is also found in breastmilk in low concentrations. the rnd must', 'Encourage breastfeeding exclusively', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Exclusive breastfeeding for the first 6 months of life, combined with maternal antiretroviral therapy (ART) that achieves viral suppression, significantly reduces postnatal mother-to-child transmission (MTCT) of HIV while drastically lowering infant mortality from infectious diseases compared to replacement feeding. Breast milk provides optimal immunological factors (such as secretory IgA, lactoferrin, and leukocytes) and complete nutrition, which protect against gastrointestinal and respiratory infections that are fatal in non-breastfed infants in high-mortality contexts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Encourage breastfeeding exclusively\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Exclusive breastfeeding for the first 6 months of life, combined with maternal antiretroviral therapy (ART) that achieves viral suppression, significantly reduces postnatal mother-to-child transmission (MTCT) of HIV while drastically lowering infant mortality from infectious diseases compared to replacement feeding. Breast milk provides optimal immunological factors (such as secretory IgA, lactoferrin, and leukocytes) and complete nutrition, which protect against gastrointestinal and respiratory infections that are fatal in non-breastfed infants in high-mortality contexts.","whyWrongChoices":"Alternative options: Not recommend breastfeeding, Recommend infant formula, Recommend plant based milk"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:metabolic changes occur during surgery. the following nutrition related implications are true except:::sodium loss', 'metabolic changes occur during surgery. the following nutrition related implications are true except', 'Sodium loss', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Surgical stress activates the sympathetic nervous system and the renin-angiotensin-aldosterone system (RAAS), alongside non-osmotic release of antidiuretic hormone (ADH) from the posterior pituitary. Elevated circulating aldosterone acts on the distal convoluted tubules and cortical collecting ducts of the nephrons to increase sodium and water reabsorption while excreting potassium and hydrogen ions, resulting in sodium retention rather than sodium loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sodium loss\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Surgical stress activates the sympathetic nervous system and the renin-angiotensin-aldosterone system (RAAS), alongside non-osmotic release of antidiuretic hormone (ADH) from the posterior pituitary. Elevated circulating aldosterone acts on the distal convoluted tubules and cortical collecting ducts of the nephrons to increase sodium and water reabsorption while excreting potassium and hydrogen ions, resulting in sodium retention rather than sodium loss.","whyWrongChoices":"Alternative options: Increased demands for Vitamin C, Increased protein requirements, Calcium loss"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:metabolic changes occur during surgery. the following nutrition related implications are true except:::', 'metabolic changes occur during surgery. the following nutrition related implications are true except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Surgical stress activates the sympathetic nervous system and the renin-angiotensin-aldosterone system (RAAS), alongside non-osmotic release of antidiuretic hormone (ADH) from the posterior pituitary. Elevated circulating aldosterone acts on the distal convoluted tubules and cortical collecting ducts of the nephrons to increase sodium and water reabsorption while excreting potassium and hydrogen ions, resulting in sodium retention rather than sodium loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sodium loss\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Surgical stress activates the sympathetic nervous system and the renin-angiotensin-aldosterone system (RAAS), alongside non-osmotic release of antidiuretic hormone (ADH) from the posterior pituitary. Elevated circulating aldosterone acts on the distal convoluted tubules and cortical collecting ducts of the nephrons to increase sodium and water reabsorption while excreting potassium and hydrogen ions, resulting in sodium retention rather than sodium loss.","whyWrongChoices":"Alternative options: Increased demands for Vitamin C, Increased protein requirements, Calcium loss"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:prior to surgery, the patient must be put on nil per os or npo for how many hours?:::8 hours', 'prior to surgery, the patient must be put on nil per os or npo for how many hours?', '8 hours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In general medical and nursing board exam questions, the standard textbook baseline for a complete nil per os (NPO) order prior to elective surgery involving general anesthesia is 8 hours (often clinically phrased as \"NPO after midnight\" for a morning procedure).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"8 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In general medical and nursing board exam questions, the standard textbook baseline for a complete nil per os (NPO) order prior to elective surgery involving general anesthesia is 8 hours (often clinically phrased as \"NPO after midnight\" for a morning procedure).\n\nThis fasting period guarantees the stomach is completely empty before anesthesia induction. This drastically minimizes the life-threatening risk of pulmonary aspiration (inhaling stomach content or vomitus into the lungs) and severe post-operative nausea.\n\nModern Clinical Guidelines (ASA)\nWhile standard multiple-choice questions typically group full NPO status into a general 8-hour window, modern American Society of Anesthesiologists (ASA) guidelines utilize a tiered approach:\n• 8 Hours: Required for heavy, fried, or fatty foods and meats (which delay gastric emptying).\n• 6 Hours: Required for light meals (e.g., toast) or non-human milk.\n• 2 Hours: Minimum restriction for clear liquids (such as water or pulp-free juices).","whyWrongChoices":"Alternative options: 12 hours, 16 hours, 24 hours"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:prior to surgery, the patient must be put on nil per os or npo for how many hours?:::', 'prior to surgery, the patient must be put on nil per os or npo for how many hours?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In general medical and nursing board exam questions, the standard textbook baseline for a complete nil per os (NPO) order prior to elective surgery involving general anesthesia is 8 hours (often clinically phrased as \"NPO after midnight\" for a morning procedure).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"8 hours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In general medical and nursing board exam questions, the standard textbook baseline for a complete nil per os (NPO) order prior to elective surgery involving general anesthesia is 8 hours (often clinically phrased as \"NPO after midnight\" for a morning procedure).\n\nThis fasting period guarantees the stomach is completely empty before anesthesia induction. This drastically minimizes the life-threatening risk of pulmonary aspiration (inhaling stomach content or vomitus into the lungs) and severe post-operative nausea.\n\nModern Clinical Guidelines (ASA)\nWhile standard multiple-choice questions typically group full NPO status into a general 8-hour window, modern American Society of Anesthesiologists (ASA) guidelines utilize a tiered approach:\n• 8 Hours: Required for heavy, fried, or fatty foods and meats (which delay gastric emptying).\n• 6 Hours: Required for light meals (e.g., toast) or non-human milk.\n• 2 Hours: Minimum restriction for clear liquids (such as water or pulp-free juices).","whyWrongChoices":"Alternative options: 12 hours, 16 hours, 24 hours"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:post surgery, the patient must be put on npo for 24 to 48 hours to prevent what?:::aspiration', 'post surgery, the patient must be put on npo for 24 to 48 hours to prevent what?', 'Aspiration', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"General anesthesia, opioid analgesics, and surgical stress profoundly suppress gastrointestinal motility, lower lower esophageal sphincter (LES) tone, and dull protective airway reflexes (such as the gag and cough reflexes). If oral intake is permitted while gastroparesis and neuromuscular depression persist, gastric contents, hydrochloric acid, and digestive enzymes can easily reflux into the pharynx and enter the respiratory tract, leading to aspiration pneumonitis (Mendelson''s syndrome) or bacterial pneumonia characterized by severe hypoxemia, acute lung injury, and inflammatory destruction of alveolar-capillary membranes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspiration\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"General anesthesia, opioid analgesics, and surgical stress profoundly suppress gastrointestinal motility, lower lower esophageal sphincter (LES) tone, and dull protective airway reflexes (such as the gag and cough reflexes). If oral intake is permitted while gastroparesis and neuromuscular depression persist, gastric contents, hydrochloric acid, and digestive enzymes can easily reflux into the pharynx and enter the respiratory tract, leading to aspiration pneumonitis (Mendelson''s syndrome) or bacterial pneumonia characterized by severe hypoxemia, acute lung injury, and inflammatory destruction of alveolar-capillary membranes.","whyWrongChoices":"Alternative options: Diarrhea, Choking, GI distress"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:post surgery, the patient must be put on npo for 24 to 48 hours to prevent what?:::', 'post surgery, the patient must be put on npo for 24 to 48 hours to prevent what?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"General anesthesia, opioid analgesics, and surgical stress profoundly suppress gastrointestinal motility, lower lower esophageal sphincter (LES) tone, and dull protective airway reflexes (such as the gag and cough reflexes). If oral intake is permitted while gastroparesis and neuromuscular depression persist, gastric contents, hydrochloric acid, and digestive enzymes can easily reflux into the pharynx and enter the respiratory tract, leading to aspiration pneumonitis (Mendelson''s syndrome) or bacterial pneumonia characterized by severe hypoxemia, acute lung injury, and inflammatory destruction of alveolar-capillary membranes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspiration\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"General anesthesia, opioid analgesics, and surgical stress profoundly suppress gastrointestinal motility, lower lower esophageal sphincter (LES) tone, and dull protective airway reflexes (such as the gag and cough reflexes). If oral intake is permitted while gastroparesis and neuromuscular depression persist, gastric contents, hydrochloric acid, and digestive enzymes can easily reflux into the pharynx and enter the respiratory tract, leading to aspiration pneumonitis (Mendelson''s syndrome) or bacterial pneumonia characterized by severe hypoxemia, acute lung injury, and inflammatory destruction of alveolar-capillary membranes.","whyWrongChoices":"Alternative options: Diarrhea, Choking, GI distress"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of food must be served on the first day post tonsillectomy?:::very cold and mild flavored', 'what type of food must be served on the first day post tonsillectomy?', 'Very cold and mild flavored', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A tonsillectomy leaves open, highly raw, and sensitive surgical wounds in the back of the throat. Introducing very cold foods and fluids (such as ice chips, non-red popsicles, and plain ice cream) induces immediate localized vasoconstriction (narrowing of the blood vessels). This reduces swelling, minimizes the risk of post-operative bleeding, and numbs raw nerve endings to alleviate acute throat pain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Very cold and mild flavored\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A tonsillectomy leaves open, highly raw, and sensitive surgical wounds in the back of the throat. Introducing very cold foods and fluids (such as ice chips, non-red popsicles, and plain ice cream) induces immediate localized vasoconstriction (narrowing of the blood vessels). This reduces swelling, minimizes the risk of post-operative bleeding, and numbs raw nerve endings to alleviate acute throat pain.\n\nThe food must be mildly flavored. Highly seasoned, spicy, salty, or acidic foods (such as citrus or tomato-based items) will cause intense chemical burning and painful irritation at the healing surgical site.","whyWrongChoices":"Alternative options: Warm and bland, Room temperature, Chilled food"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of food must be served on the first day post tonsillectomy?:::', 'what type of food must be served on the first day post tonsillectomy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A tonsillectomy leaves open, highly raw, and sensitive surgical wounds in the back of the throat. Introducing very cold foods and fluids (such as ice chips, non-red popsicles, and plain ice cream) induces immediate localized vasoconstriction (narrowing of the blood vessels). This reduces swelling, minimizes the risk of post-operative bleeding, and numbs raw nerve endings to alleviate acute throat pain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Very cold and mild flavored\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A tonsillectomy leaves open, highly raw, and sensitive surgical wounds in the back of the throat. Introducing very cold foods and fluids (such as ice chips, non-red popsicles, and plain ice cream) induces immediate localized vasoconstriction (narrowing of the blood vessels). This reduces swelling, minimizes the risk of post-operative bleeding, and numbs raw nerve endings to alleviate acute throat pain.\n\nThe food must be mildly flavored. Highly seasoned, spicy, salty, or acidic foods (such as citrus or tomato-based items) will cause intense chemical burning and painful irritation at the healing surgical site.","whyWrongChoices":"Alternative options: Warm and bland, Room temperature, Chilled food"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:protein splitting enzyme secreted by the gastric glands and the stomach.:::pepsin', 'protein splitting enzyme secreted by the gastric glands and the stomach.', 'Pepsin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pepsin is the main protein-digesting enzyme in the stomach. It is secreted by the gastric glands in an inactive form called pepsinogen. Pepsin cleaves proteins to smaller polypeptides and some free amino acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pepsin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pepsin is the main protein-digesting enzyme in the stomach. It is secreted by the gastric glands in an inactive form called pepsinogen. Pepsin cleaves proteins to smaller polypeptides and some free amino acids.","whyWrongChoices":"Alternative options: Rennin, Gastric lipase, Trypsin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:gastric surgeries result to the following nutrition related conditions except:::decreased peristalsis', 'gastric surgeries result to the following nutrition related conditions except', 'Decreased peristalsis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Decreased peristalsis (or general sluggish movement of the intestines) is not a primary, direct nutrition-related condition caused by gastric surgeries. Peristalsis is a neuromuscular function of the intestinal tract. While systemic opioid medications or immediate post-operative anesthesia can temporarily slow it down, gastric resections themselves do not inherently induce chronic, baseline decreased peristalsis as a hallmark nutritional consequence.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased peristalsis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Decreased peristalsis (or general sluggish movement of the intestines) is not a primary, direct nutrition-related condition caused by gastric surgeries. Peristalsis is a neuromuscular function of the intestinal tract. While systemic opioid medications or immediate post-operative anesthesia can temporarily slow it down, gastric resections themselves do not inherently induce chronic, baseline decreased peristalsis as a hallmark nutritional consequence.\n\n\t• Decreased production of pepsin and HCl: Removing or bypassing large portions of the stomach (such as the fundus and body) drastically reduces the number of parietal and chief cells, cutting down the overall secretion of hydrochloric acid (HCl) and pepsinogen.\n\t• Macrocytic anemia: A lack of stomach tissue leads to a severe shortage of Intrinsic Factor, which is mandatory for absorbing Vitamin B12 in the terminal ileum. Long-term Vitamin B12 deficiency directly causes pernicious or macrocytic anemia.\n\t• Impaired fat utilization: The loss of stomach churning capacity, combined with a significant reduction in gastric lipase and altered structural transit, prevents the proper emulsification and breakdown of dietary fats, leading to lipid malabsorption.","whyWrongChoices":"Alternative options: Decreased production of pepsin and HCL, Impaired fat utilization, Macrocytic anemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:gastric surgeries result to the following nutrition related conditions except:::', 'gastric surgeries result to the following nutrition related conditions except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Decreased peristalsis (or general sluggish movement of the intestines) is not a primary, direct nutrition-related condition caused by gastric surgeries. Peristalsis is a neuromuscular function of the intestinal tract. While systemic opioid medications or immediate post-operative anesthesia can temporarily slow it down, gastric resections themselves do not inherently induce chronic, baseline decreased peristalsis as a hallmark nutritional consequence.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased peristalsis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Decreased peristalsis (or general sluggish movement of the intestines) is not a primary, direct nutrition-related condition caused by gastric surgeries. Peristalsis is a neuromuscular function of the intestinal tract. While systemic opioid medications or immediate post-operative anesthesia can temporarily slow it down, gastric resections themselves do not inherently induce chronic, baseline decreased peristalsis as a hallmark nutritional consequence.\n\n\t• Decreased production of pepsin and HCl: Removing or bypassing large portions of the stomach (such as the fundus and body) drastically reduces the number of parietal and chief cells, cutting down the overall secretion of hydrochloric acid (HCl) and pepsinogen.\n\t• Macrocytic anemia: A lack of stomach tissue leads to a severe shortage of Intrinsic Factor, which is mandatory for absorbing Vitamin B12 in the terminal ileum. Long-term Vitamin B12 deficiency directly causes pernicious or macrocytic anemia.\n\t• Impaired fat utilization: The loss of stomach churning capacity, combined with a significant reduction in gastric lipase and altered structural transit, prevents the proper emulsification and breakdown of dietary fats, leading to lipid malabsorption.","whyWrongChoices":"Alternative options: Decreased production of pepsin and HCL, Impaired fat utilization, Macrocytic anemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:after 7 days of gastric surgery, the patient can be given the following except:::high carbohydrate sources', 'after 7 days of gastric surgery, the patient can be given the following except', 'High carbohydrate sources', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastric surgery, commonly known as bariatric surgery, is a medical procedure designed to help individuals with severe obesity lose weight and improve related health conditions like type 2 diabetes, high blood pressure, and heart disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High carbohydrate sources\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastric surgery, commonly known as bariatric surgery, is a medical procedure designed to help individuals with severe obesity lose weight and improve related health conditions like type 2 diabetes, high blood pressure, and heart disease.\n\nExactly one week (7 days) post-gastric surgery, a patient is transitioning into a smooth, full-liquid or pureed diet phase. Concentrated high carbohydrate sources—such as refined starches, sugary drinks, sweets, and juices—must be strictly avoided.\n\nIntroducing a high-carbohydrate load into a structurally altered or reduced stomach causes rapid gastric emptying into the small intestine. This hyperosmolar food mass pulls fluid into the bowel lumen, triggering acute dumping syndrome (characterized by severe abdominal cramps, nausea, rapid heart rate, sweating, and explosive diarrhea).","whyWrongChoices":"Alternative options: Pureed vegetables, Soft protein sources, High protein and high fat diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the followng is not a substrate used to assess zinc status?:::nails', 'which of the followng is not a substrate used to assess zinc status?', 'Nails', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nails are not a standard, validated substrate used in clinical or population-level zinc status assessment. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nails\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nails are not a standard, validated substrate used in clinical or population-level zinc status assessment. \n\nHair, saliva, and blood/plasma are all recognized substrates that have been used, with varying degrees of reliability, to assess zinc status in research and clinical settings.","whyWrongChoices":"Alternative options: Hair, Saliva, Blood"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what must an rnd recommend to prevent rapid dumping of food into jejunum?:::', 'what must an rnd recommend to prevent rapid dumping of food into jejunum?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To prevent the rapid dumping of food contents from the stomach pouch straight into the jejunum, patients are advised to eat small, frequent meals throughout the day. This prevents overwhelming the stomach''s limited volume.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Small frequent feedings in supine position\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To prevent the rapid dumping of food contents from the stomach pouch straight into the jejunum, patients are advised to eat small, frequent meals throughout the day. This prevents overwhelming the stomach''s limited volume.\n\nReclining or lying down in a supine position (flat on the back) or semi-recumbent position for 20 to 30 minutes immediately after eating uses gravity to actively slow down gastric emptying. This delays the rapid transit of food into the small intestine, providing immediate relief from both early and late dumping syndrome symptoms.","whyWrongChoices":"Alternative options: Simple carbohydrate sources, High fiber, low residue diet, 3 meals a day"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:after 7 days of gastric surgery, the patient can be given the following except:::', 'after 7 days of gastric surgery, the patient can be given the following except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastric surgery, commonly known as bariatric surgery, is a medical procedure designed to help individuals with severe obesity lose weight and improve related health conditions like type 2 diabetes, high blood pressure, and heart disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High carbohydrate sources\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastric surgery, commonly known as bariatric surgery, is a medical procedure designed to help individuals with severe obesity lose weight and improve related health conditions like type 2 diabetes, high blood pressure, and heart disease.\n\nExactly one week (7 days) post-gastric surgery, a patient is transitioning into a smooth, full-liquid or pureed diet phase. Concentrated high carbohydrate sources—such as refined starches, sugary drinks, sweets, and juices—must be strictly avoided.\n\nIntroducing a high-carbohydrate load into a structurally altered or reduced stomach causes rapid gastric emptying into the small intestine. This hyperosmolar food mass pulls fluid into the bowel lumen, triggering acute dumping syndrome (characterized by severe abdominal cramps, nausea, rapid heart rate, sweating, and explosive diarrhea).","whyWrongChoices":"Alternative options: Pureed vegetables, Soft protein sources, High protein and high fat diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the patient is complaining of nausea, cramping, sweating, palpitations 10 minutes after eating. what is she experiencing?:::early dumping syndrome', 'the patient is complaining of nausea, cramping, sweating, palpitations 10 minutes after eating. what is she experiencing?', 'Early dumping syndrome', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The symptoms of nausea, abdominal cramping, sweating, and heart palpitations occurring rapidly—within 10 to 30 minutes after eating—are the textbook diagnostic presentation of Early Dumping Syndrome.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Early dumping syndrome\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The symptoms of nausea, abdominal cramping, sweating, and heart palpitations occurring rapidly—within 10 to 30 minutes after eating—are the textbook diagnostic presentation of Early Dumping Syndrome.\n\nThis condition occurs frequently in patients who have undergone gastric or bariatric surgeries. Because the stomach''s storage capacity or pyloric valve function is altered, a large mass of poorly digested, hyperosmolar food drops rapidly into the small intestine. This hyperosmolar mass causes a massive, sudden shift of fluid out of the bloodstream and into the intestinal lumen, leading to acute intestinal distension (causing cramps and nausea) and systemic volume depletion (causing sweating, dizziness, and palpitations).\n\n• Intermediate dumping syndrome: While some textbook sources split dumping into early and late, others refer to an intermediate phase occurring 30 minutes to 1 hour post-meal, primarily characterized by bloating and gas rather than this immediate cardiovascular and gastrointestinal surge.\n• Late Dumping Syndrome: Occurs much later—1 to 3 hours after eating—and is driven by a completely different mechanism: reactive hypoglycemia caused by a rapid spike and subsequent overshoot of insulin production.","whyWrongChoices":"Alternative options: Indigestion, Bloating, Intermediate dumping syndrome"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the patient is complaining of nausea, cramping, sweating, palpitations 10 minutes after eating. what is she experiencing?:::', 'the patient is complaining of nausea, cramping, sweating, palpitations 10 minutes after eating. what is she experiencing?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The symptoms of nausea, abdominal cramping, sweating, and heart palpitations occurring rapidly—within 10 to 30 minutes after eating—are the textbook diagnostic presentation of Early Dumping Syndrome.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Early dumping syndrome\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The symptoms of nausea, abdominal cramping, sweating, and heart palpitations occurring rapidly—within 10 to 30 minutes after eating—are the textbook diagnostic presentation of Early Dumping Syndrome.\n\nThis condition occurs frequently in patients who have undergone gastric or bariatric surgeries. Because the stomach''s storage capacity or pyloric valve function is altered, a large mass of poorly digested, hyperosmolar food drops rapidly into the small intestine. This hyperosmolar mass causes a massive, sudden shift of fluid out of the bloodstream and into the intestinal lumen, leading to acute intestinal distension (causing cramps and nausea) and systemic volume depletion (causing sweating, dizziness, and palpitations).\n\n• Intermediate dumping syndrome: While some textbook sources split dumping into early and late, others refer to an intermediate phase occurring 30 minutes to 1 hour post-meal, primarily characterized by bloating and gas rather than this immediate cardiovascular and gastrointestinal surge.\n• Late Dumping Syndrome: Occurs much later—1 to 3 hours after eating—and is driven by a completely different mechanism: reactive hypoglycemia caused by a rapid spike and subsequent overshoot of insulin production.","whyWrongChoices":"Alternative options: Indigestion, Bloating, Intermediate dumping syndrome"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what must an rnd recommend to prevent rapid dumping of food into jejunum?:::small frequent feedings in supine position', 'what must an rnd recommend to prevent rapid dumping of food into jejunum?', 'Small frequent feedings in supine position', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To prevent the rapid dumping of food contents from the stomach pouch straight into the jejunum, patients are advised to eat small, frequent meals throughout the day. This prevents overwhelming the stomach''s limited volume.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Small frequent feedings in supine position\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To prevent the rapid dumping of food contents from the stomach pouch straight into the jejunum, patients are advised to eat small, frequent meals throughout the day. This prevents overwhelming the stomach''s limited volume.\n\nReclining or lying down in a supine position (flat on the back) or semi-recumbent position for 20 to 30 minutes immediately after eating uses gravity to actively slow down gastric emptying. This delays the rapid transit of food into the small intestine, providing immediate relief from both early and late dumping syndrome symptoms.","whyWrongChoices":"Alternative options: Simple carbohydrate sources, High fiber, low residue diet, 3 meals a day"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:as essential fatty acid derived from plant oils such as corn oil::::linoleic acid', 'as essential fatty acid derived from plant oils such as corn oil:', 'Linoleic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Corn oil is an excellent source of essential fatty acids, which typically exceed 60% of its total composition, with the main contribution of linoleic acid (C18:2).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Linoleic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Corn oil is an excellent source of essential fatty acids, which typically exceed 60% of its total composition, with the main contribution of linoleic acid (C18:2).","whyWrongChoices":"Alternative options: Palmitic acid, Linolenic acid, Arachidonic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient who underwent ileostomy must be monitored for signs and symptoms of nutrient deficiencies for the following micronutrients except:::vitamin b6', 'a patient who underwent ileostomy must be monitored for signs and symptoms of nutrient deficiencies for the following micronutrients except', 'Vitamin B6', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin B6 (pyridoxine) is a water-soluble vitamin primarily absorbed in the jejunum (the middle section of the small intestine). Because an ileostomy redirects or resects parts of the ileum (the final section of the small intestine) and bypasses the large intestine, the jejunum is left completely intact. This allows Vitamin B6 to be absorbed normally, making routine monitoring for a B6 deficiency unnecessary.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin B6 (pyridoxine) is a water-soluble vitamin primarily absorbed in the jejunum (the middle section of the small intestine). Because an ileostomy redirects or resects parts of the ileum (the final section of the small intestine) and bypasses the large intestine, the jejunum is left completely intact. This allows Vitamin B6 to be absorbed normally, making routine monitoring for a B6 deficiency unnecessary.\n\n\t• Vitamin B12: The terminal ileum is the only site in the entire gastrointestinal tract capable of absorbing Vitamin B12 (via the Intrinsic Factor complex). An ileostomy directly disrupts this area, placing the patient at an incredibly high risk for Vitamin B12 malabsorption and subsequent macrocytic/pernicious anemia.\n\t• Vitamins A & E: The ileum plays a critical role in the reabsorption of bile salts (enterohepatic circulation). When the ileum is bypassed or resected, the depletion of bile salts leads to the malabsorption of fats and fat-soluble vitamins (A, D, E, and K).","whyWrongChoices":"Alternative options: Vitamin B12, Vitamin A, Vitamin E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient who underwent ileostomy must be monitored for signs and symptoms of nutrient deficiencies for the following micronutrients except:::', 'a patient who underwent ileostomy must be monitored for signs and symptoms of nutrient deficiencies for the following micronutrients except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin B6 (pyridoxine) is a water-soluble vitamin primarily absorbed in the jejunum (the middle section of the small intestine). Because an ileostomy redirects or resects parts of the ileum (the final section of the small intestine) and bypasses the large intestine, the jejunum is left completely intact. This allows Vitamin B6 to be absorbed normally, making routine monitoring for a B6 deficiency unnecessary.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin B6 (pyridoxine) is a water-soluble vitamin primarily absorbed in the jejunum (the middle section of the small intestine). Because an ileostomy redirects or resects parts of the ileum (the final section of the small intestine) and bypasses the large intestine, the jejunum is left completely intact. This allows Vitamin B6 to be absorbed normally, making routine monitoring for a B6 deficiency unnecessary.\n\n\t• Vitamin B12: The terminal ileum is the only site in the entire gastrointestinal tract capable of absorbing Vitamin B12 (via the Intrinsic Factor complex). An ileostomy directly disrupts this area, placing the patient at an incredibly high risk for Vitamin B12 malabsorption and subsequent macrocytic/pernicious anemia.\n\t• Vitamins A & E: The ileum plays a critical role in the reabsorption of bile salts (enterohepatic circulation). When the ileum is bypassed or resected, the depletion of bile salts leads to the malabsorption of fats and fat-soluble vitamins (A, D, E, and K).","whyWrongChoices":"Alternative options: Vitamin B12, Vitamin A, Vitamin E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are gas forming foods that must be avoided by patients with colostomy except:::squash', 'the following are gas forming foods that must be avoided by patients with colostomy except', 'Squash', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Squash (along with other well-cooked, skinless, non-cruciferous vegetables like spinach) is generally considered easy to digest and gentle on the digestive system. It does not naturally ferment aggressively or produce large amounts of gas.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Squash\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Squash (along with other well-cooked, skinless, non-cruciferous vegetables like spinach) is generally considered easy to digest and gentle on the digestive system. It does not naturally ferment aggressively or produce large amounts of gas.\n\n\t• Onion and garlic: These contain volatile sulfur compounds and fermentable carbohydrates (fructans) that cause high amounts of gas and strong stool odors.\n\t• Dairy: Milk and dairy products containing lactose are highly gas-producing, especially if a patient has any degree of baseline lactose intolerance.\n\t• Chewing gum: Chewing gum introduces a non-dietary source of gas by causing patients to continuously swallow excess air (aerophagia), leading to immediate flatus accumulation in the colostomy bag. Additionally, many chewing gums use artificial sweeteners (sugar alcohols), which further ferment into gas in the bowel.","whyWrongChoices":"Alternative options: Onion and garlic, Chewing gum, Dairy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient has a high risk of developing oxalate stones. the rnd must recommend intake of high oxalate foods to be avoided. choose the food that is not high in oxalate content.:::', 'a patient has a high risk of developing oxalate stones. the rnd must recommend intake of high oxalate foods to be avoided. choose the food that is not high in oxalate content.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bananas are naturally very low in oxalate content (typically containing less than 1–2 mg of oxalate per serving). Because they are completely safe to consume, they are highly recommended as a staple fruit choice for patients managing or preventing calcium oxalate kidney stones.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Banana\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bananas are naturally very low in oxalate content (typically containing less than 1–2 mg of oxalate per serving). Because they are completely safe to consume, they are highly recommended as a staple fruit choice for patients managing or preventing calcium oxalate kidney stones.\n\n• Tofu: Made directly from soybeans, tofu and other soy products are notoriously high in oxalates. A standard serving of tofu can easily introduce an unsafe concentration of oxalates into the diet.\n• Chocolate: Cocoa powder and chocolate products contain very high levels of oxalic acid. Even small servings can significantly spike urinary oxalate levels.\n• Kangkong: Also known as water spinach, this dark green leafy vegetable is rich in oxalates, mirroring the high-oxalate profiles of traditional spinach and beet greens which are known to fuel calcium oxalate stone formation.","whyWrongChoices":"Alternative options: Tofu, Chocolate, Kangkong"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:protein splitting enzyme secreted by the gastric glands and the stomach.:::', 'protein splitting enzyme secreted by the gastric glands and the stomach.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pepsin is the main protein-digesting enzyme in the stomach. It is secreted by the gastric glands in an inactive form called pepsinogen. Pepsin cleaves proteins to smaller polypeptides and some free amino acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pepsin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pepsin is the main protein-digesting enzyme in the stomach. It is secreted by the gastric glands in an inactive form called pepsinogen. Pepsin cleaves proteins to smaller polypeptides and some free amino acids.","whyWrongChoices":"Alternative options: Rennin, Gastric lipase, Trypsin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are gas forming foods that must be avoided by patients with colostomy except:::', 'the following are gas forming foods that must be avoided by patients with colostomy except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Squash (along with other well-cooked, skinless, non-cruciferous vegetables like spinach) is generally considered easy to digest and gentle on the digestive system. It does not naturally ferment aggressively or produce large amounts of gas.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Squash\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Squash (along with other well-cooked, skinless, non-cruciferous vegetables like spinach) is generally considered easy to digest and gentle on the digestive system. It does not naturally ferment aggressively or produce large amounts of gas.\n\n\t• Onion and garlic: These contain volatile sulfur compounds and fermentable carbohydrates (fructans) that cause high amounts of gas and strong stool odors.\n\t• Dairy: Milk and dairy products containing lactose are highly gas-producing, especially if a patient has any degree of baseline lactose intolerance.\n\t• Chewing gum: Chewing gum introduces a non-dietary source of gas by causing patients to continuously swallow excess air (aerophagia), leading to immediate flatus accumulation in the colostomy bag. Additionally, many chewing gums use artificial sweeteners (sugar alcohols), which further ferment into gas in the bowel.","whyWrongChoices":"Alternative options: Onion and garlic, Chewing gum, Dairy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:surgery of the intestines results to changes in:::production of waste products, absorption of nutrients, and motility', 'surgery of the intestines results to changes in', 'Production of waste products, absorption of nutrients, and motility', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Absorption of nutrients: The small and large intestines are the primary sites for macro- and micronutrient, fluid, and electrolyte absorption. Resecting or altering these segments directly reduces the functional absorptive surface area.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Production of waste products, absorption of nutrients, and motility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Absorption of nutrients: The small and large intestines are the primary sites for macro- and micronutrient, fluid, and electrolyte absorption. Resecting or altering these segments directly reduces the functional absorptive surface area.\n\t• Motility: Intestinal surgery alters the neuromuscular tissue, disrupting normal peristalsis and transit time.\n\t• Production of waste products: Because nutrient digestion and fluid reabsorption are disrupted, the consistency, volume, and composition of the fecal waste change dramatically (often resulting in loose stools or stomal output).","whyWrongChoices":"Alternative options: Satiation, hormone level, absorption of nutrients, and motility, Appetite, weight changes, absorption of nutrients, and motility, Electrolyte balance, bowel movement, peristalsis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:surgery of the intestines results to changes in:::', 'surgery of the intestines results to changes in', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Absorption of nutrients: The small and large intestines are the primary sites for macro- and micronutrient, fluid, and electrolyte absorption. Resecting or altering these segments directly reduces the functional absorptive surface area.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Production of waste products, absorption of nutrients, and motility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Absorption of nutrients: The small and large intestines are the primary sites for macro- and micronutrient, fluid, and electrolyte absorption. Resecting or altering these segments directly reduces the functional absorptive surface area.\n\t• Motility: Intestinal surgery alters the neuromuscular tissue, disrupting normal peristalsis and transit time.\n\t• Production of waste products: Because nutrient digestion and fluid reabsorption are disrupted, the consistency, volume, and composition of the fecal waste change dramatically (often resulting in loose stools or stomal output).","whyWrongChoices":"Alternative options: Satiation, hormone level, absorption of nutrients, and motility, Appetite, weight changes, absorption of nutrients, and motility, Electrolyte balance, bowel movement, peristalsis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient has a high risk of developing oxalate stones. the rnd must recommend intake of high oxalate foods to be avoided. choose the food that is not high in oxalate content.:::banana', 'a patient has a high risk of developing oxalate stones. the rnd must recommend intake of high oxalate foods to be avoided. choose the food that is not high in oxalate content.', 'Banana', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bananas are naturally very low in oxalate content (typically containing less than 1–2 mg of oxalate per serving). Because they are completely safe to consume, they are highly recommended as a staple fruit choice for patients managing or preventing calcium oxalate kidney stones.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Banana\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bananas are naturally very low in oxalate content (typically containing less than 1–2 mg of oxalate per serving). Because they are completely safe to consume, they are highly recommended as a staple fruit choice for patients managing or preventing calcium oxalate kidney stones.\n\n• Tofu: Made directly from soybeans, tofu and other soy products are notoriously high in oxalates. A standard serving of tofu can easily introduce an unsafe concentration of oxalates into the diet.\n• Chocolate: Cocoa powder and chocolate products contain very high levels of oxalic acid. Even small servings can significantly spike urinary oxalate levels.\n• Kangkong: Also known as water spinach, this dark green leafy vegetable is rich in oxalates, mirroring the high-oxalate profiles of traditional spinach and beet greens which are known to fuel calcium oxalate stone formation.","whyWrongChoices":"Alternative options: Tofu, Chocolate, Kangkong"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:as essential fatty acid derived from plant oils such as corn oil::::', 'as essential fatty acid derived from plant oils such as corn oil:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Corn oil is an excellent source of essential fatty acids, which typically exceed 60% of its total composition, with the main contribution of linoleic acid (C18:2).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Linoleic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Corn oil is an excellent source of essential fatty acids, which typically exceed 60% of its total composition, with the main contribution of linoleic acid (C18:2).","whyWrongChoices":"Alternative options: Palmitic acid, Linolenic acid, Arachidonic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:post cholecystectomy, the patient must be advised to go on a low fat diet due to:::steatorrhea', 'post cholecystectomy, the patient must be advised to go on a low fat diet due to', 'Steatorrhea', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A cholecystectomy is the surgical removal of the gallbladder. The gallbladder’s primary job is to store and concentrate bile produced by the liver, releasing a concentrated surge whenever a meal containing fat enters the small intestine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Steatorrhea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A cholecystectomy is the surgical removal of the gallbladder. The gallbladder’s primary job is to store and concentrate bile produced by the liver, releasing a concentrated surge whenever a meal containing fat enters the small intestine.\n\nWithout the gallbladder, bile drips continuously and directly from the liver into the small intestine in a much more dilute, un-concentrated stream. If the patient consumes a high-fat meal post-surgery, there will not be enough concentrated bile available to efficiently emulsify and digest that fat load. The undigested fat passes straight into the colon, resulting directly in steatorrhea (fatty, greasy, foul-smelling diarrhea).","whyWrongChoices":"Alternative options: Dumping syndrome, Cramping, Abdominal distention"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:post cholecystectomy, the patient must be advised to go on a low fat diet due to:::', 'post cholecystectomy, the patient must be advised to go on a low fat diet due to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A cholecystectomy is the surgical removal of the gallbladder. The gallbladder’s primary job is to store and concentrate bile produced by the liver, releasing a concentrated surge whenever a meal containing fat enters the small intestine.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Steatorrhea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A cholecystectomy is the surgical removal of the gallbladder. The gallbladder’s primary job is to store and concentrate bile produced by the liver, releasing a concentrated surge whenever a meal containing fat enters the small intestine.\n\nWithout the gallbladder, bile drips continuously and directly from the liver into the small intestine in a much more dilute, un-concentrated stream. If the patient consumes a high-fat meal post-surgery, there will not be enough concentrated bile available to efficiently emulsify and digest that fat load. The undigested fat passes straight into the colon, resulting directly in steatorrhea (fatty, greasy, foul-smelling diarrhea).","whyWrongChoices":"Alternative options: Dumping syndrome, Cramping, Abdominal distention"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:19 years old, pre-burn weight 100lbs, third degree burn on the right hand. compute for the total energy requirement.:::1200 kcal', '19 years old, pre-burn weight 100lbs, third degree burn on the right hand. compute for the total energy requirement.', '1200 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Even though we know a 19-year-old healing from an injury needs a healthy baseline of calories, the Curreri Formula is the exact equation textbook writers use for burn calculations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1200 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Even though we know a 19-year-old healing from an injury needs a healthy baseline of calories, the Curreri Formula is the exact equation textbook writers use for burn calculations.\n\n1. Convert weight to kilograms:\n100 lbs divided by 2.2 = 45.45 kg\n\n2. Determine the Total Body Surface Area (TBSA) percentage:\nAccording to the medical Palmar Method, a patient''s entire palm and fingers equal roughly 1% TBSA. Because only the right hand has a third-degree burn, the TBSA value used is 1%.\n\n3. Apply the adult Curreri Formula:\nDaily Caloric Need = (25 kcal x kg body weight) + (40 kcal x % TBSA)\nDaily Caloric Need = (25 x 45.45 kg) + (40 x 1)\nDaily Caloric Need = 1,136.25 + 40 = 1,176.25 kcal\n\nRounding 1,176.25 kcal to the closest multiple-choice option yields 1200 kcal.","whyWrongChoices":"Alternative options: 1500 kcal, 1800 kcal, 2000 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:19 years old, pre-burn weight 100lbs, third degree burn on the right hand. compute for the total energy requirement.:::', '19 years old, pre-burn weight 100lbs, third degree burn on the right hand. compute for the total energy requirement.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Even though we know a 19-year-old healing from an injury needs a healthy baseline of calories, the Curreri Formula is the exact equation textbook writers use for burn calculations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1200 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Even though we know a 19-year-old healing from an injury needs a healthy baseline of calories, the Curreri Formula is the exact equation textbook writers use for burn calculations.\n\n1. Convert weight to kilograms:\n100 lbs divided by 2.2 = 45.45 kg\n\n2. Determine the Total Body Surface Area (TBSA) percentage:\nAccording to the medical Palmar Method, a patient''s entire palm and fingers equal roughly 1% TBSA. Because only the right hand has a third-degree burn, the TBSA value used is 1%.\n\n3. Apply the adult Curreri Formula:\nDaily Caloric Need = (25 kcal x kg body weight) + (40 kcal x % TBSA)\nDaily Caloric Need = (25 x 45.45 kg) + (40 x 1)\nDaily Caloric Need = 1,136.25 + 40 = 1,176.25 kcal\n\nRounding 1,176.25 kcal to the closest multiple-choice option yields 1200 kcal.","whyWrongChoices":"Alternative options: 1500 kcal, 1800 kcal, 2000 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fatty acids present in animal fats are said to be::::saturated fatty acids', 'fatty acids present in animal fats are said to be:', 'Saturated fatty acids', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In animals, the carbon atoms in the fatty acids are saturated with hydrogen atoms. This allows them to lie straight, and the molecules will pack neatly into a solid arrangement.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Saturated fatty acids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In animals, the carbon atoms in the fatty acids are saturated with hydrogen atoms. This allows them to lie straight, and the molecules will pack neatly into a solid arrangement.","whyWrongChoices":"Alternative options: Containing hundreds of double bonds, Linoleic acid, Unsaturated fatty acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient has suffered second degree burn on his right arm and right leg. how much protein must be recommended?:::20% of ter', 'a patient has suffered second degree burn on his right arm and right leg. how much protein must be recommended?', '20% of TER', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severe thermal injury triggers a massive hypermetabolic and catabolic state driven by sustained catecholamine, cortisol, and glucagon elevations, leading to accelerated skeletal muscle proteolysis to supply amino acids for hepatic acute-phase proteins, immune cell proliferation, and granulation tissue synthesis. Providing protein at 20% of total energy expenditure (TER) or approximately 1.5 to 2.0 g/kg/day provides the necessary nitrogen substrate to maintain positive nitrogen balance, mitigate lean body mass wasting, and support fibroblast proliferation and collagen deposition.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"20% of TER\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severe thermal injury triggers a massive hypermetabolic and catabolic state driven by sustained catecholamine, cortisol, and glucagon elevations, leading to accelerated skeletal muscle proteolysis to supply amino acids for hepatic acute-phase proteins, immune cell proliferation, and granulation tissue synthesis. Providing protein at 20% of total energy expenditure (TER) or approximately 1.5 to 2.0 g/kg/day provides the necessary nitrogen substrate to maintain positive nitrogen balance, mitigate lean body mass wasting, and support fibroblast proliferation and collagen deposition.","whyWrongChoices":"Alternative options: 10% of TER, 15 % of TER, 25% of TER"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient has suffered second degree burn on his right arm and right leg. how much protein must be recommended?:::', 'a patient has suffered second degree burn on his right arm and right leg. how much protein must be recommended?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severe thermal injury triggers a massive hypermetabolic and catabolic state driven by sustained catecholamine, cortisol, and glucagon elevations, leading to accelerated skeletal muscle proteolysis to supply amino acids for hepatic acute-phase proteins, immune cell proliferation, and granulation tissue synthesis. Providing protein at 20% of total energy expenditure (TER) or approximately 1.5 to 2.0 g/kg/day provides the necessary nitrogen substrate to maintain positive nitrogen balance, mitigate lean body mass wasting, and support fibroblast proliferation and collagen deposition.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"20% of TER\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severe thermal injury triggers a massive hypermetabolic and catabolic state driven by sustained catecholamine, cortisol, and glucagon elevations, leading to accelerated skeletal muscle proteolysis to supply amino acids for hepatic acute-phase proteins, immune cell proliferation, and granulation tissue synthesis. Providing protein at 20% of total energy expenditure (TER) or approximately 1.5 to 2.0 g/kg/day provides the necessary nitrogen substrate to maintain positive nitrogen balance, mitigate lean body mass wasting, and support fibroblast proliferation and collagen deposition.","whyWrongChoices":"Alternative options: 10% of TER, 15 % of TER, 25% of TER"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:stress contributes to cancer development by affecting the:::immune system', 'stress contributes to cancer development by affecting the', 'Immune system', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chronic stress activates the sympathetic nervous system and the hypothalamic-pituitary-adrenal (HPA) axis, sparking a continuous release of stress hormones like cortisol and adrenaline. This hormonal surge suppresses cellular immunity, downregulates natural killer (NK) cells and T-cells, and shifts the body into a chronic low-grade inflammatory state. This directly weakens the immune system''s natural surveillance defenses, making it significantly easier for mutant or abnormal tumor cells to evade detection, grow, and multiply.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Immune system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chronic stress activates the sympathetic nervous system and the hypothalamic-pituitary-adrenal (HPA) axis, sparking a continuous release of stress hormones like cortisol and adrenaline. This hormonal surge suppresses cellular immunity, downregulates natural killer (NK) cells and T-cells, and shifts the body into a chronic low-grade inflammatory state. This directly weakens the immune system''s natural surveillance defenses, making it significantly easier for mutant or abnormal tumor cells to evade detection, grow, and multiply.","whyWrongChoices":"Alternative options: Nervous system, Cardiovascular system, Digestive system"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:stress contributes to cancer development by affecting the:::', 'stress contributes to cancer development by affecting the', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chronic stress activates the sympathetic nervous system and the hypothalamic-pituitary-adrenal (HPA) axis, sparking a continuous release of stress hormones like cortisol and adrenaline. This hormonal surge suppresses cellular immunity, downregulates natural killer (NK) cells and T-cells, and shifts the body into a chronic low-grade inflammatory state. This directly weakens the immune system''s natural surveillance defenses, making it significantly easier for mutant or abnormal tumor cells to evade detection, grow, and multiply.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Immune system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chronic stress activates the sympathetic nervous system and the hypothalamic-pituitary-adrenal (HPA) axis, sparking a continuous release of stress hormones like cortisol and adrenaline. This hormonal surge suppresses cellular immunity, downregulates natural killer (NK) cells and T-cells, and shifts the body into a chronic low-grade inflammatory state. This directly weakens the immune system''s natural surveillance defenses, making it significantly easier for mutant or abnormal tumor cells to evade detection, grow, and multiply.","whyWrongChoices":"Alternative options: Nervous system, Cardiovascular system, Digestive system"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are carcinogenic in nature, except:::roasted chicken', 'the following are carcinogenic in nature, except', 'Roasted chicken', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Roasted chicken consists of muscle tissue, water, lipids, and proteins. While high-temperature cooking methods like open-flame grilling or charring can produce trace amounts of heterocyclic amines (HCAs) and polycyclic aromatic hydrocarbons (PAHs), standard roasted chicken does not inherently possess systemic carcinogenic properties. The food item itself is a standard source of dietary protein and amino acids and is not classified as a Group 1 or Group 2A/2B carcinogen by the International Agency for Research on Cancer (IARC).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Roasted chicken\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Roasted chicken consists of muscle tissue, water, lipids, and proteins. While high-temperature cooking methods like open-flame grilling or charring can produce trace amounts of heterocyclic amines (HCAs) and polycyclic aromatic hydrocarbons (PAHs), standard roasted chicken does not inherently possess systemic carcinogenic properties. The food item itself is a standard source of dietary protein and amino acids and is not classified as a Group 1 or Group 2A/2B carcinogen by the International Agency for Research on Cancer (IARC).","whyWrongChoices":"Alternative options: Radiation, Nicotine, Nitrate cured meats"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are carcinogenic in nature, except:::', 'the following are carcinogenic in nature, except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Roasted chicken consists of muscle tissue, water, lipids, and proteins. While high-temperature cooking methods like open-flame grilling or charring can produce trace amounts of heterocyclic amines (HCAs) and polycyclic aromatic hydrocarbons (PAHs), standard roasted chicken does not inherently possess systemic carcinogenic properties. The food item itself is a standard source of dietary protein and amino acids and is not classified as a Group 1 or Group 2A/2B carcinogen by the International Agency for Research on Cancer (IARC).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Roasted chicken\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Roasted chicken consists of muscle tissue, water, lipids, and proteins. While high-temperature cooking methods like open-flame grilling or charring can produce trace amounts of heterocyclic amines (HCAs) and polycyclic aromatic hydrocarbons (PAHs), standard roasted chicken does not inherently possess systemic carcinogenic properties. The food item itself is a standard source of dietary protein and amino acids and is not classified as a Group 1 or Group 2A/2B carcinogen by the International Agency for Research on Cancer (IARC).","whyWrongChoices":"Alternative options: Radiation, Nicotine, Nitrate cured meats"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:soy, green tea, fruits and vegetables contain plant chemicals that can neutralize free radicals and aid in cancer prevention. these substances are also known as:::phytochemicals', 'soy, green tea, fruits and vegetables contain plant chemicals that can neutralize free radicals and aid in cancer prevention. these substances are also known as', 'Phytochemicals', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phytochemicals (also known as phytonutrients) are bioactive, non-nutritive plant chemicals found in foods like soy, green tea, fruits, vegetables, and grains.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phytochemicals\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phytochemicals (also known as phytonutrients) are bioactive, non-nutritive plant chemicals found in foods like soy, green tea, fruits, vegetables, and grains.\n\nMany phytochemicals—such as isoflavones in soy and catechins in green tea—act as powerful antioxidants. They neutralize highly unstable free radicals, protect cellular structures and DNA from oxidative stress, reduce systemic inflammation, and block biological pathways that trigger cancer development.","whyWrongChoices":"Alternative options: Probiotics, Prebiotics, Tannins"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:soy, green tea, fruits and vegetables contain plant chemicals that can neutralize free radicals and aid in cancer prevention. these substances are also known as:::', 'soy, green tea, fruits and vegetables contain plant chemicals that can neutralize free radicals and aid in cancer prevention. these substances are also known as', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phytochemicals (also known as phytonutrients) are bioactive, non-nutritive plant chemicals found in foods like soy, green tea, fruits, vegetables, and grains.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phytochemicals\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phytochemicals (also known as phytonutrients) are bioactive, non-nutritive plant chemicals found in foods like soy, green tea, fruits, vegetables, and grains.\n\nMany phytochemicals—such as isoflavones in soy and catechins in green tea—act as powerful antioxidants. They neutralize highly unstable free radicals, protect cellular structures and DNA from oxidative stress, reduce systemic inflammation, and block biological pathways that trigger cancer development.","whyWrongChoices":"Alternative options: Probiotics, Prebiotics, Tannins"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a cancer survivor is seeking advice on how to prevent recurrence. choose the correct answer.:::', 'a cancer survivor is seeking advice on how to prevent recurrence. choose the correct answer.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The three new guidelines, Saturated fatty acid and trans-fatty acid intake for adults and children, Total fat intake for the prevention of unhealthy weight gain in adults and children, and Carbohydrate intake for adults and children, contain recommendations that aim to reduce the risk of unhealthy weight gain and diet-related noncommunicable diseases, such as type 2 diabetes, cardiovascular disease, and certain types of cancer. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fat consumption must be less than 30% of total energy requirement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The three new guidelines, Saturated fatty acid and trans-fatty acid intake for adults and children, Total fat intake for the prevention of unhealthy weight gain in adults and children, and Carbohydrate intake for adults and children, contain recommendations that aim to reduce the risk of unhealthy weight gain and diet-related noncommunicable diseases, such as type 2 diabetes, cardiovascular disease, and certain types of cancer. \n\nWith its guidance on dietary fat, WHO notes that both quantity and quality are important for good health. WHO reaffirms that adults should limit total fat intake to 30% of total energy intake or less.  Fat consumed by everyone 2 years of age and older should be primarily unsaturated fatty acids, with no more than 10% of total energy intake coming from saturated fatty acids and no more than 1% of total energy intake from trans-fatty acids from both industrially produced and ruminant animal sources.","whyWrongChoices":"Alternative options: Use supplements to prevent cancer recurrence, Consume 35g of fiber from fruits and vegetables daily, Avoid alcohol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a cancer patient may experience eating problems. choose one that does not apply:::polydipsia', 'a cancer patient may experience eating problems. choose one that does not apply', 'Polydipsia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Polydipsia (excessive or insatiable thirst) is a classic clinical symptom of uncontrolled diabetes mellitus or diabetes insipidus, rather than a primary eating problem characteristically induced by oncological malignancies or cancer treatments.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Polydipsia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Polydipsia (excessive or insatiable thirst) is a classic clinical symptom of uncontrolled diabetes mellitus or diabetes insipidus, rather than a primary eating problem characteristically induced by oncological malignancies or cancer treatments.\n\n\t• Anorexia: Cancer-induced anorexia (loss of appetite) is incredibly common, driven by metabolic changes from tumor-released cytokines, psychological distress, or side effects of chemotherapy and radiation.\n\t• Lactose intolerance: Radiation therapy to the abdomen or certain chemotherapy agents can severely damage the mucosal lining of the small intestine. This temporarily destroys the brush border enzymes, leading to acute, treatment-induced secondary lactose intolerance.\n\t• Thrush: Oral candidiasis (thrush) is a common fungal infection in cancer patients due to therapy-induced immunosuppression or side effects like xerostomia (dry mouth). It causes painful white patches in the mouth that make chewing and swallowing highly difficult.","whyWrongChoices":"Alternative options: Anorexia, Thrush, Lactose intolerance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
