INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:what is produced in the muscles during intense exercise which can lead to painful and sore muscles?:::lactic acid', 'what is produced in the muscles during intense exercise which can lead to painful and sore muscles?', 'Lactic Acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During intense, anaerobic exercise, your muscles require energy faster than your body can deliver oxygen. To keep up, cells break down glucose via anaerobic glycolysis, which produces lactic acid (lactate).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lactic Acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During intense, anaerobic exercise, your muscles require energy faster than your body can deliver oxygen. To keep up, cells break down glucose via anaerobic glycolysis, which produces lactic acid (lactate).\n\nWhile multiple-choice questions traditionally cite lactic acid as the cause of immediate muscle burning and fatigue during an intense workout, modern exercise science notes that it actually clears from the muscles within a few hours. The prolonged soreness felt 24 to 72 hours after a workout is known as Delayed Onset Muscle Soreness (DOMS), which is driven by microscopic tears in the muscle fibers and subsequent localized inflammation.","whyWrongChoices":"Alternative options: Acetic Acid, Hydrochloric Acid, Ascorbic Acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is produced in the muscles during intense exercise which can lead to painful and sore muscles?:::', 'what is produced in the muscles during intense exercise which can lead to painful and sore muscles?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During intense, anaerobic exercise, your muscles require energy faster than your body can deliver oxygen. To keep up, cells break down glucose via anaerobic glycolysis, which produces lactic acid (lactate).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lactic Acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During intense, anaerobic exercise, your muscles require energy faster than your body can deliver oxygen. To keep up, cells break down glucose via anaerobic glycolysis, which produces lactic acid (lactate).\n\nWhile multiple-choice questions traditionally cite lactic acid as the cause of immediate muscle burning and fatigue during an intense workout, modern exercise science notes that it actually clears from the muscles within a few hours. The prolonged soreness felt 24 to 72 hours after a workout is known as Delayed Onset Muscle Soreness (DOMS), which is driven by microscopic tears in the muscle fibers and subsequent localized inflammation.","whyWrongChoices":"Alternative options: Acetic Acid, Hydrochloric Acid, Ascorbic Acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the ability of a joint or series of joints to move through unrestricted and painfree range of motion?:::flexibility', 'what is the ability of a joint or series of joints to move through unrestricted and painfree range of motion?', 'Flexibility', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In exercise science and physical education, flexibility is defined exactly as the ability of a joint, or a series of joints, to move smoothly and effortlessly through an unrestricted, pain-free range of motion (ROM). It is heavily influenced by the laxity of the joint capsule and the elasticity of the surrounding muscles, tendons, and ligaments.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flexibility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In exercise science and physical education, flexibility is defined exactly as the ability of a joint, or a series of joints, to move smoothly and effortlessly through an unrestricted, pain-free range of motion (ROM). It is heavily influenced by the laxity of the joint capsule and the elasticity of the surrounding muscles, tendons, and ligaments.\n\n• Movement: This is a broad, non-specific macroscopic term for any physical displacement or change in the position of body parts, which does not define a targeted joint boundary or capacity.\n• Agility: A skill-related component of physical fitness that describes the body''s ability to explosively and efficiently change direction and velocity while maintaining total body control and balance.\n• Physical Fitness: The overall umbrella state of physiological well-being that enables an individual to complete daily tasks effectively without undue fatigue. Flexibility is just one health-related component inside the wider physical fitness framework.","whyWrongChoices":"Alternative options: Physical Fitness, Movement, Agility"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the synthesis of glucose from non-carbohydrate precursors?:::gluconeogenesis', 'what is the synthesis of glucose from non-carbohydrate precursors?', 'Gluconeogenesis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gluconeogenesis literally translates to \"the creation of new glucose.\" It is the metabolic pathway through which the body synthesizes glucose from non-carbohydrate precursors—such as lactate, glycerol, and glucogenic amino acids (like alanine and glutamine).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gluconeogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gluconeogenesis literally translates to \"the creation of new glucose.\" It is the metabolic pathway through which the body synthesizes glucose from non-carbohydrate precursors—such as lactate, glycerol, and glucogenic amino acids (like alanine and glutamine).\n\nThis process occurs primarily in the liver (and to a lesser extent in the kidneys) during periods of fasting, starvation, low-carbohydrate intake, or intense exercise to maintain critical blood glucose levels and fuel glucose-dependent organs like the brain.\n\n• Glycogenolysis: The biochemical breakdown of stored glycogen into glucose, meaning it uses a carbohydrate source rather than a non-carbohydrate precursor.\n• Phosphagen system: An anaerobic energy pathway that uses stored ATP and creatine phosphate to provide immediate energy during short, explosive bursts of exercise, carrying no role in glucose synthesis.\n• Lipolysis: The metabolic breakdown of triglycerides (fats) into glycerol and free fatty acids. While the glycerol byproduct can enter gluconeogenesis, lipolysis itself is the breakdown of fat, not the synthesis of glucose.","whyWrongChoices":"Alternative options: Glycogenolysis, Phosphagen system, Lipolysis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the ability of a joint or series of joints to move through unrestricted and painfree range of motion?:::', 'what is the ability of a joint or series of joints to move through unrestricted and painfree range of motion?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In exercise science and physical education, flexibility is defined exactly as the ability of a joint, or a series of joints, to move smoothly and effortlessly through an unrestricted, pain-free range of motion (ROM). It is heavily influenced by the laxity of the joint capsule and the elasticity of the surrounding muscles, tendons, and ligaments.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flexibility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In exercise science and physical education, flexibility is defined exactly as the ability of a joint, or a series of joints, to move smoothly and effortlessly through an unrestricted, pain-free range of motion (ROM). It is heavily influenced by the laxity of the joint capsule and the elasticity of the surrounding muscles, tendons, and ligaments.\n\n• Movement: This is a broad, non-specific macroscopic term for any physical displacement or change in the position of body parts, which does not define a targeted joint boundary or capacity.\n• Agility: A skill-related component of physical fitness that describes the body''s ability to explosively and efficiently change direction and velocity while maintaining total body control and balance.\n• Physical Fitness: The overall umbrella state of physiological well-being that enables an individual to complete daily tasks effectively without undue fatigue. Flexibility is just one health-related component inside the wider physical fitness framework.","whyWrongChoices":"Alternative options: Physical Fitness, Movement, Agility"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the macronutrient composition post competition or during the recovery phase?:::75% cho, 10% protein, 15% fat', 'what is the macronutrient composition post competition or during the recovery phase?', '75% CHO, 10% Protein, 15% Fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During intense prolonged competition, muscle glycogen stores are severely depleted, and glycogen synthase activity is acutely upregulated. Consuming 75% of calories as high-glycemic carbohydrates stimulates a robust insulin surge, driving intracellular GLUT4 translocation and accelerating glucose uptake into skeletal muscle cells. Including 10% protein supplies essential amino acids—specifically leucine—to activate the mTORC1 pathway for muscle protein synthesis and further enhance insulin secretion. Restricting dietary fat to 15% is critical because high fat content retards gastric emptying and chyme transit, which slows down the intestinal absorption rate of glucose and amino acids required for rapid recovery.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"75% CHO, 10% Protein, 15% Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During intense prolonged competition, muscle glycogen stores are severely depleted, and glycogen synthase activity is acutely upregulated. Consuming 75% of calories as high-glycemic carbohydrates stimulates a robust insulin surge, driving intracellular GLUT4 translocation and accelerating glucose uptake into skeletal muscle cells. Including 10% protein supplies essential amino acids—specifically leucine—to activate the mTORC1 pathway for muscle protein synthesis and further enhance insulin secretion. Restricting dietary fat to 15% is critical because high fat content retards gastric emptying and chyme transit, which slows down the intestinal absorption rate of glucose and amino acids required for rapid recovery.","whyWrongChoices":"Alternative options: 60% CHO, 20% Protein, 20% Fat, 65% CHO, 15% Protein, 20% Fat, 70% CHO, 10% Protein, 20% Fat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the macronutrient composition post competition or during the recovery phase?:::', 'what is the macronutrient composition post competition or during the recovery phase?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During intense prolonged competition, muscle glycogen stores are severely depleted, and glycogen synthase activity is acutely upregulated. Consuming 75% of calories as high-glycemic carbohydrates stimulates a robust insulin surge, driving intracellular GLUT4 translocation and accelerating glucose uptake into skeletal muscle cells. Including 10% protein supplies essential amino acids—specifically leucine—to activate the mTORC1 pathway for muscle protein synthesis and further enhance insulin secretion. Restricting dietary fat to 15% is critical because high fat content retards gastric emptying and chyme transit, which slows down the intestinal absorption rate of glucose and amino acids required for rapid recovery.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"75% CHO, 10% Protein, 15% Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During intense prolonged competition, muscle glycogen stores are severely depleted, and glycogen synthase activity is acutely upregulated. Consuming 75% of calories as high-glycemic carbohydrates stimulates a robust insulin surge, driving intracellular GLUT4 translocation and accelerating glucose uptake into skeletal muscle cells. Including 10% protein supplies essential amino acids—specifically leucine—to activate the mTORC1 pathway for muscle protein synthesis and further enhance insulin secretion. Restricting dietary fat to 15% is critical because high fat content retards gastric emptying and chyme transit, which slows down the intestinal absorption rate of glucose and amino acids required for rapid recovery.","whyWrongChoices":"Alternative options: 60% CHO, 20% Protein, 20% Fat, 65% CHO, 15% Protein, 20% Fat, 70% CHO, 10% Protein, 20% Fat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the carbohydrate requirement of a 65kg tri-athlete.:::520g to 650g carbohydrates', 'compute for the carbohydrate requirement of a 65kg tri-athlete.', '520g to 650g Carbohydrates', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In sports dietetics, endurance athletes undergoing heavy training blocks—such as triathletes—have exceptionally high daily fuel demands. To fully sustain performance, protect immune health, and keep glycogen stores saturated, standard clinical textbooks and sports organizations recommend a daily carbohydrate intake multiplier of 8 to 10 grams of carbohydrate per kilogram of body weight (8 to 10 g/kg/day).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"520g to 650g Carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In sports dietetics, endurance athletes undergoing heavy training blocks—such as triathletes—have exceptionally high daily fuel demands. To fully sustain performance, protect immune health, and keep glycogen stores saturated, standard clinical textbooks and sports organizations recommend a daily carbohydrate intake multiplier of 8 to 10 grams of carbohydrate per kilogram of body weight (8 to 10 g/kg/day).\n\nLower Bound Target: 65 kg x 8 g/kg = 520 g of carbohydrates\nUpper Bound Target: 65 kg x 10 g/kg = 650 g of carbohydrates\n\n• 390g to 780g: This uses a wide-spanning scale of 6 to 12 g/kg. While 6 g/kg can apply to general fitness or lighter training days, the target range for competitive endurance sport preparation specifically centers on the highly dense 8 to 10 g/kg model.","whyWrongChoices":"Alternative options: 780g to 845g Carbohydrates, 390g to 780g Carbohydrates, 420g to 550g Carbohydrates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the synthesis of glucose from non-carbohydrate precursors?:::', 'what is the synthesis of glucose from non-carbohydrate precursors?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gluconeogenesis literally translates to \"the creation of new glucose.\" It is the metabolic pathway through which the body synthesizes glucose from non-carbohydrate precursors—such as lactate, glycerol, and glucogenic amino acids (like alanine and glutamine).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gluconeogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gluconeogenesis literally translates to \"the creation of new glucose.\" It is the metabolic pathway through which the body synthesizes glucose from non-carbohydrate precursors—such as lactate, glycerol, and glucogenic amino acids (like alanine and glutamine).\n\nThis process occurs primarily in the liver (and to a lesser extent in the kidneys) during periods of fasting, starvation, low-carbohydrate intake, or intense exercise to maintain critical blood glucose levels and fuel glucose-dependent organs like the brain.\n\n• Glycogenolysis: The biochemical breakdown of stored glycogen into glucose, meaning it uses a carbohydrate source rather than a non-carbohydrate precursor.\n• Phosphagen system: An anaerobic energy pathway that uses stored ATP and creatine phosphate to provide immediate energy during short, explosive bursts of exercise, carrying no role in glucose synthesis.\n• Lipolysis: The metabolic breakdown of triglycerides (fats) into glycerol and free fatty acids. While the glycerol byproduct can enter gluconeogenesis, lipolysis itself is the breakdown of fat, not the synthesis of glucose.","whyWrongChoices":"Alternative options: Glycogenolysis, Phosphagen system, Lipolysis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are adverse effects of protein overload except:::fatigue', 'the following are adverse effects of protein overload except', 'Fatigue', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fatigue is generally not considered a direct physiological adverse effect of acute protein overload. While low carbohydrate intake (often a byproduct of extreme high-protein dieting) can lead to lethargy or sluggishness from low glycogen stores, the structural overload of protein metabolism itself doesn''t characteristically induce fatigue as a primary metabolic side effect.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fatigue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fatigue is generally not considered a direct physiological adverse effect of acute protein overload. While low carbohydrate intake (often a byproduct of extreme high-protein dieting) can lead to lethargy or sluggishness from low glycogen stores, the structural overload of protein metabolism itself doesn''t characteristically induce fatigue as a primary metabolic side effect.\n\n• Kidney and liver damage: Processing high loads of protein forces the liver to convert toxic byproducts (like ammonia) into urea, while forcing the kidneys to filter out this massive increase in nitrogenous waste. Over time, this significantly elevates the workload and can precipitate or accelerate kidney and liver strain, particularly in individuals with underlying or pre-existing renal compromise.\n• Calcium deficiency: High-protein intake (specifically from animal sources rich in sulfur-containing amino acids) generates a high dietary acid load in body fluids. To buffer this systemic acidity, the body resorbs bone minerals, causing an influx of calcium loss through the urine (hypercalciuria), which can compromise long-term bone density if calcium intake is inadequate.\n• Dehydration: The elimination of excess blood urea nitrogen requires a substantial amount of fluid to flush the waste out through the urinary tract. This constant osmotic diuresis rapidly depletes body fluids, leading to subclinical or clinical dehydration if the individual does not aggressively increase their water intake to compensate.","whyWrongChoices":"Alternative options: Kidney and liver damage, Dehydration, Calcium deficiency"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the carbohydrate requirement of a 65kg tri-athlete.:::', 'compute for the carbohydrate requirement of a 65kg tri-athlete.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In sports dietetics, endurance athletes undergoing heavy training blocks—such as triathletes—have exceptionally high daily fuel demands. To fully sustain performance, protect immune health, and keep glycogen stores saturated, standard clinical textbooks and sports organizations recommend a daily carbohydrate intake multiplier of 8 to 10 grams of carbohydrate per kilogram of body weight (8 to 10 g/kg/day).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"520g to 650g Carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In sports dietetics, endurance athletes undergoing heavy training blocks—such as triathletes—have exceptionally high daily fuel demands. To fully sustain performance, protect immune health, and keep glycogen stores saturated, standard clinical textbooks and sports organizations recommend a daily carbohydrate intake multiplier of 8 to 10 grams of carbohydrate per kilogram of body weight (8 to 10 g/kg/day).\n\nLower Bound Target: 65 kg x 8 g/kg = 520 g of carbohydrates\nUpper Bound Target: 65 kg x 10 g/kg = 650 g of carbohydrates\n\n• 390g to 780g: This uses a wide-spanning scale of 6 to 12 g/kg. While 6 g/kg can apply to general fitness or lighter training days, the target range for competitive endurance sport preparation specifically centers on the highly dense 8 to 10 g/kg model.","whyWrongChoices":"Alternative options: 780g to 845g Carbohydrates, 390g to 780g Carbohydrates, 420g to 550g Carbohydrates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the protein requirement of a 55kg boxer.:::95g to 99g protein', 'compute for the protein requirement of a 55kg boxer.', '95g to 99g Protein', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the International Society of Sports Nutrition (ISSN) and joint positions by the Academy of Nutrition and Dietetics, athletes involved in intense endurance and strength-based disciplines—like boxing—require a higher daily intake range of 1.2 to 2.0 grams of protein per kilogram of body weight. Combat athletes regularly training at an elite level or cutting weight frequently hit upper targets of 1.8 to 2.0+ g/kg to ensure adequate muscle tissue repair, recovery, and lean mass preservation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"95g to 99g Protein\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the International Society of Sports Nutrition (ISSN) and joint positions by the Academy of Nutrition and Dietetics, athletes involved in intense endurance and strength-based disciplines—like boxing—require a higher daily intake range of 1.2 to 2.0 grams of protein per kilogram of body weight. Combat athletes regularly training at an elite level or cutting weight frequently hit upper targets of 1.8 to 2.0+ g/kg to ensure adequate muscle tissue repair, recovery, and lean mass preservation.\n\nTarget Baseline Intake: 55 kg x 1.8 g/kg = 99 g of protein\nLower Bound Target: 55 kg x 1.73 g/kg = 95 g of protein\n\n• 55g to 75g: This range uses a lower calculation factor (1.0 to 1.36 g/kg). While 1.0 g/kg is perfectly fine for a sedentary individual or a recreational gym-goer, it is completely insufficient to maintain nitrogen balance and muscle recovery for a competitive combat sport athlete undergoing strenuous training cycles.","whyWrongChoices":"Alternative options: 66g to 85g Protein, 55 g to 75g Protein, 75g to 120g Protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the protein requirement of a 55kg boxer.:::', 'compute for the protein requirement of a 55kg boxer.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the International Society of Sports Nutrition (ISSN) and joint positions by the Academy of Nutrition and Dietetics, athletes involved in intense endurance and strength-based disciplines—like boxing—require a higher daily intake range of 1.2 to 2.0 grams of protein per kilogram of body weight. Combat athletes regularly training at an elite level or cutting weight frequently hit upper targets of 1.8 to 2.0+ g/kg to ensure adequate muscle tissue repair, recovery, and lean mass preservation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"95g to 99g Protein\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the International Society of Sports Nutrition (ISSN) and joint positions by the Academy of Nutrition and Dietetics, athletes involved in intense endurance and strength-based disciplines—like boxing—require a higher daily intake range of 1.2 to 2.0 grams of protein per kilogram of body weight. Combat athletes regularly training at an elite level or cutting weight frequently hit upper targets of 1.8 to 2.0+ g/kg to ensure adequate muscle tissue repair, recovery, and lean mass preservation.\n\nTarget Baseline Intake: 55 kg x 1.8 g/kg = 99 g of protein\nLower Bound Target: 55 kg x 1.73 g/kg = 95 g of protein\n\n• 55g to 75g: This range uses a lower calculation factor (1.0 to 1.36 g/kg). While 1.0 g/kg is perfectly fine for a sedentary individual or a recreational gym-goer, it is completely insufficient to maintain nitrogen balance and muscle recovery for a competitive combat sport athlete undergoing strenuous training cycles.","whyWrongChoices":"Alternative options: 66g to 85g Protein, 55 g to 75g Protein, 75g to 120g Protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the choice of fuel to sustain a high intensity exercise that lasts between 3 to 20 minutes?:::carbohydrate and some fat', 'what is the choice of fuel to sustain a high intensity exercise that lasts between 3 to 20 minutes?', 'Carbohydrate and some fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During high-intensity exercise sustained from 3 to 20 minutes, the predominant energy system transitions from immediate phosphagen pathways to rapid glycogenolysis and glycolysis, which generate ATP rapidly via carbohydrate oxidation. Because this duration exceeds immediate ATP-PCr capacity yet allows sufficient oxygen delivery for mixed-substrate metabolism, aerobic and anaerobic pathways operate simultaneously. Fat oxidation contributes a measurable percentage of total energy expenditure, particularly as the exercise duration extends past 5 minutes and reliance shifts partially toward oxidative phosphorylation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carbohydrate and some fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During high-intensity exercise sustained from 3 to 20 minutes, the predominant energy system transitions from immediate phosphagen pathways to rapid glycogenolysis and glycolysis, which generate ATP rapidly via carbohydrate oxidation. Because this duration exceeds immediate ATP-PCr capacity yet allows sufficient oxygen delivery for mixed-substrate metabolism, aerobic and anaerobic pathways operate simultaneously. Fat oxidation contributes a measurable percentage of total energy expenditure, particularly as the exercise duration extends past 5 minutes and reliance shifts partially toward oxidative phosphorylation.","whyWrongChoices":"Alternative options: Protein and BCAA, Carbohydrate only, Carbohydrate and protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the choice of fuel to sustain a high intensity exercise that lasts between 3 to 20 minutes?:::', 'what is the choice of fuel to sustain a high intensity exercise that lasts between 3 to 20 minutes?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During high-intensity exercise sustained from 3 to 20 minutes, the predominant energy system transitions from immediate phosphagen pathways to rapid glycogenolysis and glycolysis, which generate ATP rapidly via carbohydrate oxidation. Because this duration exceeds immediate ATP-PCr capacity yet allows sufficient oxygen delivery for mixed-substrate metabolism, aerobic and anaerobic pathways operate simultaneously. Fat oxidation contributes a measurable percentage of total energy expenditure, particularly as the exercise duration extends past 5 minutes and reliance shifts partially toward oxidative phosphorylation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carbohydrate and some fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During high-intensity exercise sustained from 3 to 20 minutes, the predominant energy system transitions from immediate phosphagen pathways to rapid glycogenolysis and glycolysis, which generate ATP rapidly via carbohydrate oxidation. Because this duration exceeds immediate ATP-PCr capacity yet allows sufficient oxygen delivery for mixed-substrate metabolism, aerobic and anaerobic pathways operate simultaneously. Fat oxidation contributes a measurable percentage of total energy expenditure, particularly as the exercise duration extends past 5 minutes and reliance shifts partially toward oxidative phosphorylation.","whyWrongChoices":"Alternative options: Protein and BCAA, Carbohydrate only, Carbohydrate and protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are adverse effects of protein overload except:::', 'the following are adverse effects of protein overload except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fatigue is generally not considered a direct physiological adverse effect of acute protein overload. While low carbohydrate intake (often a byproduct of extreme high-protein dieting) can lead to lethargy or sluggishness from low glycogen stores, the structural overload of protein metabolism itself doesn''t characteristically induce fatigue as a primary metabolic side effect.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fatigue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fatigue is generally not considered a direct physiological adverse effect of acute protein overload. While low carbohydrate intake (often a byproduct of extreme high-protein dieting) can lead to lethargy or sluggishness from low glycogen stores, the structural overload of protein metabolism itself doesn''t characteristically induce fatigue as a primary metabolic side effect.\n\n• Kidney and liver damage: Processing high loads of protein forces the liver to convert toxic byproducts (like ammonia) into urea, while forcing the kidneys to filter out this massive increase in nitrogenous waste. Over time, this significantly elevates the workload and can precipitate or accelerate kidney and liver strain, particularly in individuals with underlying or pre-existing renal compromise.\n• Calcium deficiency: High-protein intake (specifically from animal sources rich in sulfur-containing amino acids) generates a high dietary acid load in body fluids. To buffer this systemic acidity, the body resorbs bone minerals, causing an influx of calcium loss through the urine (hypercalciuria), which can compromise long-term bone density if calcium intake is inadequate.\n• Dehydration: The elimination of excess blood urea nitrogen requires a substantial amount of fluid to flush the waste out through the urinary tract. This constant osmotic diuresis rapidly depletes body fluids, leading to subclinical or clinical dehydration if the individual does not aggressively increase their water intake to compensate.","whyWrongChoices":"Alternative options: Kidney and liver damage, Dehydration, Calcium deficiency"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of fluid must be avoided 1 hour before a competition?:::cold milk', 'what type of fluid must be avoided 1 hour before a competition?', 'Cold milk', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fluids high in protein and saturated fats—such as milk—take a significantly longer time to digest and exit the stomach. Consuming milk just one hour before a competition slows gastric emptying and heavily increases the risk of gastrointestinal (GI) distress, abdominal cramps, bloating, and nausea during intense physical activity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cold milk\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fluids high in protein and saturated fats—such as milk—take a significantly longer time to digest and exit the stomach. Consuming milk just one hour before a competition slows gastric emptying and heavily increases the risk of gastrointestinal (GI) distress, abdominal cramps, bloating, and nausea during intense physical activity.\n\nIn the hour directly leading up to an athletic event, fluid intake should prioritize rapid gastric clearance and hydration.","whyWrongChoices":"Alternative options: Cold water, 100% fruit juice, Electrolyte drink"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what type of fluid must be avoided 1 hour before a competition?:::', 'what type of fluid must be avoided 1 hour before a competition?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fluids high in protein and saturated fats—such as milk—take a significantly longer time to digest and exit the stomach. Consuming milk just one hour before a competition slows gastric emptying and heavily increases the risk of gastrointestinal (GI) distress, abdominal cramps, bloating, and nausea during intense physical activity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cold milk\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fluids high in protein and saturated fats—such as milk—take a significantly longer time to digest and exit the stomach. Consuming milk just one hour before a competition slows gastric emptying and heavily increases the risk of gastrointestinal (GI) distress, abdominal cramps, bloating, and nausea during intense physical activity.\n\nIn the hour directly leading up to an athletic event, fluid intake should prioritize rapid gastric clearance and hydration.","whyWrongChoices":"Alternative options: Cold water, 100% fruit juice, Electrolyte drink"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for person with epilepsy::::ketogenic diet', 'dietary management for person with epilepsy:', 'Ketogenic diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A ketogenic diet is a specialized, high-fat, very low-carbohydrate diet medically used to manage epilepsy, especially in patients with drug-resistant or refractory seizures. The severe reduction of carbohydrates forces the body to burn fat for fuel, generating ketone bodies that act as a stabilizing, anticonvulsant energy source for the brain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenic diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A ketogenic diet is a specialized, high-fat, very low-carbohydrate diet medically used to manage epilepsy, especially in patients with drug-resistant or refractory seizures. The severe reduction of carbohydrates forces the body to burn fat for fuel, generating ketone bodies that act as a stabilizing, anticonvulsant energy source for the brain.","whyWrongChoices":"Alternative options: Regular diet, High carohydrate, Low fat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for person with epilepsy::::', 'dietary management for person with epilepsy:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A ketogenic diet is a specialized, high-fat, very low-carbohydrate diet medically used to manage epilepsy, especially in patients with drug-resistant or refractory seizures. The severe reduction of carbohydrates forces the body to burn fat for fuel, generating ketone bodies that act as a stabilizing, anticonvulsant energy source for the brain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenic diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A ketogenic diet is a specialized, high-fat, very low-carbohydrate diet medically used to manage epilepsy, especially in patients with drug-resistant or refractory seizures. The severe reduction of carbohydrates forces the body to burn fat for fuel, generating ketone bodies that act as a stabilizing, anticonvulsant energy source for the brain.","whyWrongChoices":"Alternative options: Regular diet, High carohydrate, Low fat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which supplement may delay mental fatigue among athletes?:::branched chain amino acid', 'which supplement may delay mental fatigue among athletes?', 'Branched Chain Amino Acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During prolonged or high-intensity endurance exercise, free fatty acid levels in the blood rise, causing a surge in free tryptophan. Tryptophan crosses the blood-brain barrier and converts into serotonin—the neurotransmitter responsible for inducing drowsiness, muscle relaxation, and mental/central fatigue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Branched Chain Amino Acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During prolonged or high-intensity endurance exercise, free fatty acid levels in the blood rise, causing a surge in free tryptophan. Tryptophan crosses the blood-brain barrier and converts into serotonin—the neurotransmitter responsible for inducing drowsiness, muscle relaxation, and mental/central fatigue.\n\nBranched-Chain Amino Acids (BCAAs)—which include leucine, isoleucine, and valine—share the exact same transport carrier into the brain as tryptophan. By increasing BCAA concentrations in the bloodstream, these amino acids outcompete and block tryptophan from entering the brain. This effectively limits serotonin production, allowing athletes to maintain mental focus, perceive less exertion, and delay the onset of mental exhaustion during heavy training sessions.","whyWrongChoices":"Alternative options: Glutamine, Creatine Monohydrate, Probiotics"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which supplement may delay mental fatigue among athletes?:::', 'which supplement may delay mental fatigue among athletes?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During prolonged or high-intensity endurance exercise, free fatty acid levels in the blood rise, causing a surge in free tryptophan. Tryptophan crosses the blood-brain barrier and converts into serotonin—the neurotransmitter responsible for inducing drowsiness, muscle relaxation, and mental/central fatigue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Branched Chain Amino Acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During prolonged or high-intensity endurance exercise, free fatty acid levels in the blood rise, causing a surge in free tryptophan. Tryptophan crosses the blood-brain barrier and converts into serotonin—the neurotransmitter responsible for inducing drowsiness, muscle relaxation, and mental/central fatigue.\n\nBranched-Chain Amino Acids (BCAAs)—which include leucine, isoleucine, and valine—share the exact same transport carrier into the brain as tryptophan. By increasing BCAA concentrations in the bloodstream, these amino acids outcompete and block tryptophan from entering the brain. This effectively limits serotonin production, allowing athletes to maintain mental focus, perceive less exertion, and delay the onset of mental exhaustion during heavy training sessions.","whyWrongChoices":"Alternative options: Glutamine, Creatine Monohydrate, Probiotics"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
