INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:it stores bile until needed::::', 'it stores bile until needed:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The gallbladder acts like a small storage pouch or holding tank. It collects and concentrates bile between meals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gallbladder\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The gallbladder acts like a small storage pouch or holding tank. It collects and concentrates bile between meals.\n\nWhen you eat (especially foods high in fat), hormones trigger the gallbladder to contract, squeezing the stored bile through the bile ducts and into the small intestine to break down fats.","whyWrongChoices":"Alternative options: Liver, Pancreas, Stomach"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet management for a child with maple syrup urine disease::::low leucine, isoleucine, valine', 'diet management for a child with maple syrup urine disease:', 'Low leucine, isoleucine, valine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Maple Syrup Urine Disease (MSUD) is an inherited metabolic disorder caused by a deficiency in the enzyme complex needed to break down protein building blocks. Specifically, the body cannot process the three branched-chain amino acids (BCAAs): leucine, isoleucine, and valine. Without proper breakdown, these amino acids and their toxic byproducts accumulate in the blood and urine, giving the urine a sweet odor reminiscent of maple syrup. If left unmanaged, the buildup becomes highly neurotoxic, causing brain damage, seizures, or coma.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low leucine, isoleucine, valine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Maple Syrup Urine Disease (MSUD) is an inherited metabolic disorder caused by a deficiency in the enzyme complex needed to break down protein building blocks. Specifically, the body cannot process the three branched-chain amino acids (BCAAs): leucine, isoleucine, and valine. Without proper breakdown, these amino acids and their toxic byproducts accumulate in the blood and urine, giving the urine a sweet odor reminiscent of maple syrup. If left unmanaged, the buildup becomes highly neurotoxic, causing brain damage, seizures, or coma.","whyWrongChoices":"Alternative options: Low isoleucine, valine, 100 mg b1 per day, Low leucine, valine, protein, Low tyrosine, phenylalanine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet management for a child with maple syrup urine disease::::', 'diet management for a child with maple syrup urine disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Maple Syrup Urine Disease (MSUD) is an inherited metabolic disorder caused by a deficiency in the enzyme complex needed to break down protein building blocks. Specifically, the body cannot process the three branched-chain amino acids (BCAAs): leucine, isoleucine, and valine. Without proper breakdown, these amino acids and their toxic byproducts accumulate in the blood and urine, giving the urine a sweet odor reminiscent of maple syrup. If left unmanaged, the buildup becomes highly neurotoxic, causing brain damage, seizures, or coma.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low leucine, isoleucine, valine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Maple Syrup Urine Disease (MSUD) is an inherited metabolic disorder caused by a deficiency in the enzyme complex needed to break down protein building blocks. Specifically, the body cannot process the three branched-chain amino acids (BCAAs): leucine, isoleucine, and valine. Without proper breakdown, these amino acids and their toxic byproducts accumulate in the blood and urine, giving the urine a sweet odor reminiscent of maple syrup. If left unmanaged, the buildup becomes highly neurotoxic, causing brain damage, seizures, or coma.","whyWrongChoices":"Alternative options: Low isoleucine, valine, 100 mg b1 per day, Low leucine, valine, protein, Low tyrosine, phenylalanine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition recommendation for protein for patients with chronic renal failure::::0.6 to 0.8 g/kg bw', 'nutrition recommendation for protein for patients with chronic renal failure:', '0.6 to 0.8 g/kg BW', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For adults with advanced Chronic Renal Failure (CRF) who are stable and not yet on dialysis, medical guidelines (such as KDOQI clinical guidelines) recommend a low-protein diet to help manage the condition. Restricting dietary protein helps reduce the accumulation of toxic nitrogenous waste products (uremic toxins), minimizes kidney workload, and helps delay the progression toward end-stage renal disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.6 to 0.8 g/kg BW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For adults with advanced Chronic Renal Failure (CRF) who are stable and not yet on dialysis, medical guidelines (such as KDOQI clinical guidelines) recommend a low-protein diet to help manage the condition. Restricting dietary protein helps reduce the accumulation of toxic nitrogenous waste products (uremic toxins), minimizes kidney workload, and helps delay the progression toward end-stage renal disease.","whyWrongChoices":"Alternative options: Greater than or equal to 1.0 g/kg BW, 2 g/kg BW, 0.8 to 1.0 g/kg BW"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition recommendation for protein for patients with chronic renal failure::::', 'nutrition recommendation for protein for patients with chronic renal failure:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For adults with advanced Chronic Renal Failure (CRF) who are stable and not yet on dialysis, medical guidelines (such as KDOQI clinical guidelines) recommend a low-protein diet to help manage the condition. Restricting dietary protein helps reduce the accumulation of toxic nitrogenous waste products (uremic toxins), minimizes kidney workload, and helps delay the progression toward end-stage renal disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.6 to 0.8 g/kg BW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For adults with advanced Chronic Renal Failure (CRF) who are stable and not yet on dialysis, medical guidelines (such as KDOQI clinical guidelines) recommend a low-protein diet to help manage the condition. Restricting dietary protein helps reduce the accumulation of toxic nitrogenous waste products (uremic toxins), minimizes kidney workload, and helps delay the progression toward end-stage renal disease.","whyWrongChoices":"Alternative options: Greater than or equal to 1.0 g/kg BW, 2 g/kg BW, 0.8 to 1.0 g/kg BW"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bf is a 61-year-old female diagnosed with cancer of the stomach and has been bedridden for the past one month; height 5’6’’, weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 calories per day. the attending physician decided to give her parenteral nutrition prior to a contemplated procedure. which of the following tna (total nutrient admixture) is best for this patient?:::', 'bf is a 61-year-old female diagnosed with cancer of the stomach and has been bedridden for the past one month; height 5’6’’, weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 calories per day. the attending physician decided to give her parenteral nutrition prior to a contemplated procedure. which of the following tna (total nutrient admixture) is best for this patient?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patient BF is severely malnourished, has lost 10% of her body weight over 3 months, and has been surviving on a starvation-level intake of only 700 Calories per day. When a patient is chronically starved, starting Parenteral Nutrition at a full calorie load (like 1,400 or 1,500 Calories) can trigger fatal electrolyte shifts (hypophosphatemia, hypokalemia, and hypomagnesemia).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutriflex 1000 in 1250 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patient BF is severely malnourished, has lost 10% of her body weight over 3 months, and has been surviving on a starvation-level intake of only 700 Calories per day. When a patient is chronically starved, starting Parenteral Nutrition at a full calorie load (like 1,400 or 1,500 Calories) can trigger fatal electrolyte shifts (hypophosphatemia, hypokalemia, and hypomagnesemia).\n\nStandard safety guidelines dictate that for severely malnourished or starved patients, clinicians must \"start low and go slow.\" Nutritional support should be initiated at a conservative baseline of 15 to 20 kcal/kg of body weight. For a 50 kg patient, this equals an initial daily energy target of roughly 750 to 1,000 Calories.\n\nNutriflex 1000 in 1250 ml delivers exactly 1,000 Calories in a safe, controlled volume. This makes it the ideal, safe starter formula to initiate her clinical feeding therapy without triggering refeeding syndrome.","whyWrongChoices":"Alternative options: Nutriflex 1400 in 1875 ml, Nutriflex 1500 in 1250 ml., Nutriflex 1900 in 2500 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a syndrome characterized by weight loss, anorexia, asthenia, and anemia.:::cachexia', 'it is a syndrome characterized by weight loss, anorexia, asthenia, and anemia.', 'Cachexia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cachexia (specifically cancer cachexia or wasting syndrome) is a complex metabolic syndrome defined precisely by involuntary weight loss, anorexia (loss of appetite), asthenia (severe physical weakness/loss of strength), and anemia. Unlike simple starvation, it is driven by systemic inflammation that actively breaks down skeletal muscle and fat tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cachexia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cachexia (specifically cancer cachexia or wasting syndrome) is a complex metabolic syndrome defined precisely by involuntary weight loss, anorexia (loss of appetite), asthenia (severe physical weakness/loss of strength), and anemia. Unlike simple starvation, it is driven by systemic inflammation that actively breaks down skeletal muscle and fat tissue.","whyWrongChoices":"Alternative options: Malnutrition, Anorexia, Mucositis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a syndrome characterized by weight loss, anorexia, asthenia, and anemia.:::', 'it is a syndrome characterized by weight loss, anorexia, asthenia, and anemia.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cachexia (specifically cancer cachexia or wasting syndrome) is a complex metabolic syndrome defined precisely by involuntary weight loss, anorexia (loss of appetite), asthenia (severe physical weakness/loss of strength), and anemia. Unlike simple starvation, it is driven by systemic inflammation that actively breaks down skeletal muscle and fat tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cachexia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cachexia (specifically cancer cachexia or wasting syndrome) is a complex metabolic syndrome defined precisely by involuntary weight loss, anorexia (loss of appetite), asthenia (severe physical weakness/loss of strength), and anemia. Unlike simple starvation, it is driven by systemic inflammation that actively breaks down skeletal muscle and fat tissue.","whyWrongChoices":"Alternative options: Malnutrition, Anorexia, Mucositis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in bone formation, the production of parathyroid hormone is::::decreased', 'in bone formation, the production of parathyroid hormone is:', 'Decreased', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During active bone formation, osteoblasts take calcium ions out of the blood to build and mineralize the new bone matrix. As a consequence, blood calcium levels drop. In response to this drop in serum calcium, the body acts to restore homeostasis by increasing parathyroid hormone production to trigger bone resorption. Conversely, when calcium is abundant and actively filling the bones, the production of parathyroid hormone is decreased (suppressed) via negative feedback to prevent further bone breakdown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During active bone formation, osteoblasts take calcium ions out of the blood to build and mineralize the new bone matrix. As a consequence, blood calcium levels drop. In response to this drop in serum calcium, the body acts to restore homeostasis by increasing parathyroid hormone production to trigger bone resorption. Conversely, when calcium is abundant and actively filling the bones, the production of parathyroid hormone is decreased (suppressed) via negative feedback to prevent further bone breakdown.\n\n*An increase in parathyroid hormone production primarily drives bone resorption (breakdown) because it signals osteoclasts to dissolve bone and release calcium back into the blood.","whyWrongChoices":"Alternative options: Increased, Uncertain, No effect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are dietary management for wernicke-korsakoff syndrome, except::::', 'the following are dietary management for wernicke-korsakoff syndrome, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wernicke-Korsakoff syndrome (WKS) is a severe neurological disorder caused by a profound deficiency of thiamine (Vitamin B1), most commonly seen in chronic alcohol use disorder. Thiamine is vital for glucose metabolism in the brain. Because body stores of thiamine are limited, a lack of this vitamin leads to cellular brain damage, manifesting as acute confusion, vision abnormalities, and severe memory loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High energy and protein tube feeding\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wernicke-Korsakoff syndrome (WKS) is a severe neurological disorder caused by a profound deficiency of thiamine (Vitamin B1), most commonly seen in chronic alcohol use disorder. Thiamine is vital for glucose metabolism in the brain. Because body stores of thiamine are limited, a lack of this vitamin leads to cellular brain damage, manifesting as acute confusion, vision abnormalities, and severe memory loss.\n\n• Why C is the EXCEPT option (Incorrect management): Initiating immediate high-energy, heavy carbohydrate tube feeding or glucose loads before correcting a thiamine deficiency is incredibly dangerous. Introducing massive calories/glucose rapidly consumes the body''s tiny remaining stores of thiamine to process those nutrients. This can trigger massive lactic acidosis and cause a sudden, catastrophic worsening of the neurological syndrome.","whyWrongChoices":"Alternative options: Thiamine supplementation, Adequare hydration, Avoidance of alcohol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is/are carcinogens? i. salt-cured processed foods ii. tobacco iii. coffee and tea:::i and ii only', 'which of the following is/are carcinogens? i. salt-cured processed foods ii. tobacco iii. coffee and tea', 'I and II only', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Tobacco is a well-established Group 1 carcinogen (known to cause cancer in humans).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I and II only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Tobacco is a well-established Group 1 carcinogen (known to cause cancer in humans).\n• Salt-cured processed foods, such as Chinese-style salted fish and processed meats, are also classified as Group 1 carcinogens by the World Health Organization (WHO) due to the presence of nitrates and other cancer-causing agents formed during processing.\nx Coffee and tea are not classified as carcinogens. In fact, moderate consumption of coffee and tea is often linked to a reduced risk of certain types of cancer due to their high antioxidant content.","whyWrongChoices":"Alternative options: I only, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in bone formation, the production of parathyroid hormone is::::', 'in bone formation, the production of parathyroid hormone is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During active bone formation, osteoblasts take calcium ions out of the blood to build and mineralize the new bone matrix. As a consequence, blood calcium levels drop. In response to this drop in serum calcium, the body acts to restore homeostasis by increasing parathyroid hormone production to trigger bone resorption. Conversely, when calcium is abundant and actively filling the bones, the production of parathyroid hormone is decreased (suppressed) via negative feedback to prevent further bone breakdown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During active bone formation, osteoblasts take calcium ions out of the blood to build and mineralize the new bone matrix. As a consequence, blood calcium levels drop. In response to this drop in serum calcium, the body acts to restore homeostasis by increasing parathyroid hormone production to trigger bone resorption. Conversely, when calcium is abundant and actively filling the bones, the production of parathyroid hormone is decreased (suppressed) via negative feedback to prevent further bone breakdown.\n\n*An increase in parathyroid hormone production primarily drives bone resorption (breakdown) because it signals osteoclasts to dissolve bone and release calcium back into the blood.","whyWrongChoices":"Alternative options: Increased, Uncertain, No effect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for a person with addison''s disease::::all of the above', 'dietary management for a person with addison''s disease:', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Addison''s disease (primary adrenal insufficiency) occurs when the adrenal glands are damaged and cannot produce enough cortisol and aldosterone. Aldosterone is the hormone responsible for holding onto sodium and flushing out potassium. Without it, the body dangerously dumps sodium and retains potassium, while a lack of cortisol slows down metabolism and depletes energy reserves.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Addison''s disease (primary adrenal insufficiency) occurs when the adrenal glands are damaged and cannot produce enough cortisol and aldosterone. Aldosterone is the hormone responsible for holding onto sodium and flushing out potassium. Without it, the body dangerously dumps sodium and retains potassium, while a lack of cortisol slows down metabolism and depletes energy reserves.\n\nBecause of this hormonal deficit, the dietary management must directly counteract these imbalances:\n\n• High Na (Sodium): Due to the lack of aldosterone, the kidneys constantly excrete sodium into the urine, causing hyponatremia (low blood sodium). Patients need a high-sodium diet to replace these heavy losses and maintain stable blood pressure.\n• Low K (Potassium): Without aldosterone to flush it out, potassium builds up dangerously in the blood (hyperkalemia). Patients must follow a low-potassium diet to prevent cardiac arrhythmias.\n• High kcal (Calories): The lack of cortisol causes severe fatigue, muscle wasting, and frequent hypoglycemia (low blood sugar). A high-calorie, nutrient-dense diet with frequent small meals helps sustain energy levels and prevent dangerous blood sugar drops.","whyWrongChoices":"Alternative options: High Na, Low K, High kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for a person with addison''s disease::::', 'dietary management for a person with addison''s disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Addison''s disease (primary adrenal insufficiency) occurs when the adrenal glands are damaged and cannot produce enough cortisol and aldosterone. Aldosterone is the hormone responsible for holding onto sodium and flushing out potassium. Without it, the body dangerously dumps sodium and retains potassium, while a lack of cortisol slows down metabolism and depletes energy reserves.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Addison''s disease (primary adrenal insufficiency) occurs when the adrenal glands are damaged and cannot produce enough cortisol and aldosterone. Aldosterone is the hormone responsible for holding onto sodium and flushing out potassium. Without it, the body dangerously dumps sodium and retains potassium, while a lack of cortisol slows down metabolism and depletes energy reserves.\n\nBecause of this hormonal deficit, the dietary management must directly counteract these imbalances:\n\n• High Na (Sodium): Due to the lack of aldosterone, the kidneys constantly excrete sodium into the urine, causing hyponatremia (low blood sodium). Patients need a high-sodium diet to replace these heavy losses and maintain stable blood pressure.\n• Low K (Potassium): Without aldosterone to flush it out, potassium builds up dangerously in the blood (hyperkalemia). Patients must follow a low-potassium diet to prevent cardiac arrhythmias.\n• High kcal (Calories): The lack of cortisol causes severe fatigue, muscle wasting, and frequent hypoglycemia (low blood sugar). A high-calorie, nutrient-dense diet with frequent small meals helps sustain energy levels and prevent dangerous blood sugar drops.","whyWrongChoices":"Alternative options: High Na, Low K, High kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bone cells responsible for the resorption of bone matrix and release of calcium and phosphate from the bone::::osteoclasts', 'bone cells responsible for the resorption of bone matrix and release of calcium and phosphate from the bone:', 'Osteoclasts', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Osteoclasts are large, multinucleated cells that function as the \"demolition crew\" of the skeletal system. They secrete acids and specialized enzymes (like collagenase) to dissolve the mineralized bone matrix. This biological breakdown—called bone resorption—directly liberates and releases locked-up calcium and phosphate ions back into the bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Osteoclasts\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Osteoclasts are large, multinucleated cells that function as the \"demolition crew\" of the skeletal system. They secrete acids and specialized enzymes (like collagenase) to dissolve the mineralized bone matrix. This biological breakdown—called bone resorption—directly liberates and releases locked-up calcium and phosphate ions back into the bloodstream.","whyWrongChoices":"Alternative options: Osteogenic cells, Osteocytes, Osteoblast"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bone cells responsible for the resorption of bone matrix and release of calcium and phosphate from the bone::::', 'bone cells responsible for the resorption of bone matrix and release of calcium and phosphate from the bone:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Osteoclasts are large, multinucleated cells that function as the \"demolition crew\" of the skeletal system. They secrete acids and specialized enzymes (like collagenase) to dissolve the mineralized bone matrix. This biological breakdown—called bone resorption—directly liberates and releases locked-up calcium and phosphate ions back into the bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Osteoclasts\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Osteoclasts are large, multinucleated cells that function as the \"demolition crew\" of the skeletal system. They secrete acids and specialized enzymes (like collagenase) to dissolve the mineralized bone matrix. This biological breakdown—called bone resorption—directly liberates and releases locked-up calcium and phosphate ions back into the bloodstream.","whyWrongChoices":"Alternative options: Osteogenic cells, Osteocytes, Osteoblast"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:energy requirement for patients with chronic renal failure::::35 kcal/kg bw', 'energy requirement for patients with chronic renal failure:', '35 kcal/kg BW', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Traditional and classic clinical board guidelines (such as the standard National Kidney Foundation KDOQI Guidelines) heavily establish 35 kcal/kg/day as the baseline calorie target for adults with chronic renal failure. This high energy requirement is necessary to ensure the body does not break down its own muscle tissue for energy (preventing protein-energy wasting), allowing the strictly restricted dietary protein to be used efficiently for tissue repair.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"35 kcal/kg BW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Traditional and classic clinical board guidelines (such as the standard National Kidney Foundation KDOQI Guidelines) heavily establish 35 kcal/kg/day as the baseline calorie target for adults with chronic renal failure. This high energy requirement is necessary to ensure the body does not break down its own muscle tissue for energy (preventing protein-energy wasting), allowing the strictly restricted dietary protein to be used efficiently for tissue repair.\n\n• 30 kcal/kg BW: This is the adjusted baseline commonly allocated specifically for elderly patients (typically 60 years or older) with CRF because they have a lower metabolic rate and a more sedentary lifestyle.","whyWrongChoices":"Alternative options: 25 kcal/kg BW, 30 kcal/kg BW, 40 kcal/kg BW"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:energy requirement for patients with chronic renal failure::::', 'energy requirement for patients with chronic renal failure:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Traditional and classic clinical board guidelines (such as the standard National Kidney Foundation KDOQI Guidelines) heavily establish 35 kcal/kg/day as the baseline calorie target for adults with chronic renal failure. This high energy requirement is necessary to ensure the body does not break down its own muscle tissue for energy (preventing protein-energy wasting), allowing the strictly restricted dietary protein to be used efficiently for tissue repair.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"35 kcal/kg BW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Traditional and classic clinical board guidelines (such as the standard National Kidney Foundation KDOQI Guidelines) heavily establish 35 kcal/kg/day as the baseline calorie target for adults with chronic renal failure. This high energy requirement is necessary to ensure the body does not break down its own muscle tissue for energy (preventing protein-energy wasting), allowing the strictly restricted dietary protein to be used efficiently for tissue repair.\n\n• 30 kcal/kg BW: This is the adjusted baseline commonly allocated specifically for elderly patients (typically 60 years or older) with CRF because they have a lower metabolic rate and a more sedentary lifestyle.","whyWrongChoices":"Alternative options: 25 kcal/kg BW, 30 kcal/kg BW, 40 kcal/kg BW"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to be avoided in the diet management of celiac disease::::all of the above', 'to be avoided in the diet management of celiac disease:', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gluten is a protein composite containing prolamins (gliadin in wheat, secalin in rye, hordein in barley, and avenin in some oats) that trigger an immune-mediated enteropathy in genetically susceptible individuals expressing HLA-DQ2 or HLA-DQ8 molecules. Gastric and pancreatic enzymes cannot fully break down proline- and glutamine-rich prolamin peptides, allowing them to cross the lamina propria where tissue transglutaminase (tTG) deamidates them, provoking a destructive CD4+ T-helper cell response, crypt hyperplasia, and villous atrophy in the small intestine. Furthermore, commercial soy sauce traditionally utilizes wheat as a primary fermentation ingredient, making it a major source of hidden gluten that must also be avoided unless explicitly labeled gluten-free.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gluten is a protein composite containing prolamins (gliadin in wheat, secalin in rye, hordein in barley, and avenin in some oats) that trigger an immune-mediated enteropathy in genetically susceptible individuals expressing HLA-DQ2 or HLA-DQ8 molecules. Gastric and pancreatic enzymes cannot fully break down proline- and glutamine-rich prolamin peptides, allowing them to cross the lamina propria where tissue transglutaminase (tTG) deamidates them, provoking a destructive CD4+ T-helper cell response, crypt hyperplasia, and villous atrophy in the small intestine. Furthermore, commercial soy sauce traditionally utilizes wheat as a primary fermentation ingredient, making it a major source of hidden gluten that must also be avoided unless explicitly labeled gluten-free.","whyWrongChoices":"Alternative options: rye, oats, wheat, barley, high fat, rye, oats, wheat, barley, soy sauce, rye, oats, wheat, barley"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to be avoided in the diet management of celiac disease::::', 'to be avoided in the diet management of celiac disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gluten is a protein composite containing prolamins (gliadin in wheat, secalin in rye, hordein in barley, and avenin in some oats) that trigger an immune-mediated enteropathy in genetically susceptible individuals expressing HLA-DQ2 or HLA-DQ8 molecules. Gastric and pancreatic enzymes cannot fully break down proline- and glutamine-rich prolamin peptides, allowing them to cross the lamina propria where tissue transglutaminase (tTG) deamidates them, provoking a destructive CD4+ T-helper cell response, crypt hyperplasia, and villous atrophy in the small intestine. Furthermore, commercial soy sauce traditionally utilizes wheat as a primary fermentation ingredient, making it a major source of hidden gluten that must also be avoided unless explicitly labeled gluten-free.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gluten is a protein composite containing prolamins (gliadin in wheat, secalin in rye, hordein in barley, and avenin in some oats) that trigger an immune-mediated enteropathy in genetically susceptible individuals expressing HLA-DQ2 or HLA-DQ8 molecules. Gastric and pancreatic enzymes cannot fully break down proline- and glutamine-rich prolamin peptides, allowing them to cross the lamina propria where tissue transglutaminase (tTG) deamidates them, provoking a destructive CD4+ T-helper cell response, crypt hyperplasia, and villous atrophy in the small intestine. Furthermore, commercial soy sauce traditionally utilizes wheat as a primary fermentation ingredient, making it a major source of hidden gluten that must also be avoided unless explicitly labeled gluten-free.","whyWrongChoices":"Alternative options: rye, oats, wheat, barley, high fat, rye, oats, wheat, barley, soy sauce, rye, oats, wheat, barley"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are dietary management for wernicke-korsakoff syndrome, except::::high energy and protein tube feeding', 'the following are dietary management for wernicke-korsakoff syndrome, except:', 'High energy and protein tube feeding', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wernicke-Korsakoff syndrome (WKS) is a severe neurological disorder caused by a profound deficiency of thiamine (Vitamin B1), most commonly seen in chronic alcohol use disorder. Thiamine is vital for glucose metabolism in the brain. Because body stores of thiamine are limited, a lack of this vitamin leads to cellular brain damage, manifesting as acute confusion, vision abnormalities, and severe memory loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High energy and protein tube feeding\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wernicke-Korsakoff syndrome (WKS) is a severe neurological disorder caused by a profound deficiency of thiamine (Vitamin B1), most commonly seen in chronic alcohol use disorder. Thiamine is vital for glucose metabolism in the brain. Because body stores of thiamine are limited, a lack of this vitamin leads to cellular brain damage, manifesting as acute confusion, vision abnormalities, and severe memory loss.\n\n• Why C is the EXCEPT option (Incorrect management): Initiating immediate high-energy, heavy carbohydrate tube feeding or glucose loads before correcting a thiamine deficiency is incredibly dangerous. Introducing massive calories/glucose rapidly consumes the body''s tiny remaining stores of thiamine to process those nutrients. This can trigger massive lactic acidosis and cause a sudden, catastrophic worsening of the neurological syndrome.","whyWrongChoices":"Alternative options: Thiamine supplementation, Adequare hydration, Avoidance of alcohol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is/are carcinogens? i. salt-cured processed foods ii. tobacco iii. coffee and tea:::', 'which of the following is/are carcinogens? i. salt-cured processed foods ii. tobacco iii. coffee and tea', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Tobacco is a well-established Group 1 carcinogen (known to cause cancer in humans).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I and II only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Tobacco is a well-established Group 1 carcinogen (known to cause cancer in humans).\n• Salt-cured processed foods, such as Chinese-style salted fish and processed meats, are also classified as Group 1 carcinogens by the World Health Organization (WHO) due to the presence of nitrates and other cancer-causing agents formed during processing.\nx Coffee and tea are not classified as carcinogens. In fact, moderate consumption of coffee and tea is often linked to a reduced risk of certain types of cancer due to their high antioxidant content.","whyWrongChoices":"Alternative options: I only, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a high-fat, low-carbohydrate diet given given to patients to help control seizures.:::ketogenic diet', 'a high-fat, low-carbohydrate diet given given to patients to help control seizures.', 'Ketogenic diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A ketogenic (keto) diet is a therapeutic, high-fat, adequate-protein, and very low-carbohydrate diet medically used to manage drug-resistant epilepsy, especially in children. By severely limiting carbohydrates, it forces the body to burn fat for fuel instead of glucose. This metabolic shift produces ketone bodies (acetoacetate and beta-hydroxybutyrate), which cross the blood-brain barrier and exert an anticonvulsant, seizure-stabilizing effect on the brain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenic diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A ketogenic (keto) diet is a therapeutic, high-fat, adequate-protein, and very low-carbohydrate diet medically used to manage drug-resistant epilepsy, especially in children. By severely limiting carbohydrates, it forces the body to burn fat for fuel instead of glucose. This metabolic shift produces ketone bodies (acetoacetate and beta-hydroxybutyrate), which cross the blood-brain barrier and exert an anticonvulsant, seizure-stabilizing effect on the brain.","whyWrongChoices":"Alternative options: Ketoacidosis, Ketoanalogues, Acid ash diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a high-fat, low-carbohydrate diet given given to patients to help control seizures.:::', 'a high-fat, low-carbohydrate diet given given to patients to help control seizures.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A ketogenic (keto) diet is a therapeutic, high-fat, adequate-protein, and very low-carbohydrate diet medically used to manage drug-resistant epilepsy, especially in children. By severely limiting carbohydrates, it forces the body to burn fat for fuel instead of glucose. This metabolic shift produces ketone bodies (acetoacetate and beta-hydroxybutyrate), which cross the blood-brain barrier and exert an anticonvulsant, seizure-stabilizing effect on the brain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenic diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A ketogenic (keto) diet is a therapeutic, high-fat, adequate-protein, and very low-carbohydrate diet medically used to manage drug-resistant epilepsy, especially in children. By severely limiting carbohydrates, it forces the body to burn fat for fuel instead of glucose. This metabolic shift produces ketone bodies (acetoacetate and beta-hydroxybutyrate), which cross the blood-brain barrier and exert an anticonvulsant, seizure-stabilizing effect on the brain.","whyWrongChoices":"Alternative options: Ketoacidosis, Ketoanalogues, Acid ash diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for fasting hypoglycemia::::high carbohydrates', 'dietary management for fasting hypoglycemia:', 'high carbohydrates', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fasting hypoglycemia happens when the body''s baseline sugar stores run dry during long stretches without food. In medical nutrition therapy, the ultimate defense against fasting crashes is a high-carbohydrate diet (typically accounting for 60% to 65% of total daily calories). This ensures liver glycogen stores are completely saturated and continuously available to buffer blood sugar levels during a fast.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fasting hypoglycemia happens when the body''s baseline sugar stores run dry during long stretches without food. In medical nutrition therapy, the ultimate defense against fasting crashes is a high-carbohydrate diet (typically accounting for 60% to 65% of total daily calories). This ensures liver glycogen stores are completely saturated and continuously available to buffer blood sugar levels during a fast.","whyWrongChoices":"Alternative options: complex carbohydrates, small frequent meals, fiber"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary management for fasting hypoglycemia::::', 'dietary management for fasting hypoglycemia:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fasting hypoglycemia happens when the body''s baseline sugar stores run dry during long stretches without food. In medical nutrition therapy, the ultimate defense against fasting crashes is a high-carbohydrate diet (typically accounting for 60% to 65% of total daily calories). This ensures liver glycogen stores are completely saturated and continuously available to buffer blood sugar levels during a fast.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high carbohydrates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fasting hypoglycemia happens when the body''s baseline sugar stores run dry during long stretches without food. In medical nutrition therapy, the ultimate defense against fasting crashes is a high-carbohydrate diet (typically accounting for 60% to 65% of total daily calories). This ensures liver glycogen stores are completely saturated and continuously available to buffer blood sugar levels during a fast.","whyWrongChoices":"Alternative options: complex carbohydrates, small frequent meals, fiber"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a neurodegenerative disease characterized by slow and decreased movements, muscular rigidity, resting tremor, posture instability, and decreased dopamine transmission to basal ganglia::::parkinson''s disease', 'a neurodegenerative disease characterized by slow and decreased movements, muscular rigidity, resting tremor, posture instability, and decreased dopamine transmission to basal ganglia:', 'Parkinson''s disease', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Parkinson''s disease is a neurodegenerative disorder caused by the loss of dopamine-producing neurons in the brain. This loss disrupts signals to the basal ganglia, which normally controls smooth, coordinated muscle function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Parkinson''s disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Parkinson''s disease is a neurodegenerative disorder caused by the loss of dopamine-producing neurons in the brain. This loss disrupts signals to the basal ganglia, which normally controls smooth, coordinated muscle function.\n\nThe classic four cardinal motor signs of this disease: bradykinesia (slow movements), muscular rigidity (stiffness), resting tremors, and postural instability (poor balance)—all directly caused by the drop in dopamine.\n\n• Multiple sclerosis is an autoimmune attack on the myelin sheath of nerves, causing numbness, tingling, and vision issues, not a dopamine deficit.\n• Cerebral palsy is a non-progressive movement disorder caused by brain damage that occurs around the time of birth.\n• Epilepsy is characterized by sudden, abnormal bursts of electrical activity in the brain that trigger seizures.","whyWrongChoices":"Alternative options: Multiple sclerosis, Cerebral palsy, Epilepsy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a neurodegenerative disease characterized by slow and decreased movements, muscular rigidity, resting tremor, posture instability, and decreased dopamine transmission to basal ganglia::::', 'a neurodegenerative disease characterized by slow and decreased movements, muscular rigidity, resting tremor, posture instability, and decreased dopamine transmission to basal ganglia:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Parkinson''s disease is a neurodegenerative disorder caused by the loss of dopamine-producing neurons in the brain. This loss disrupts signals to the basal ganglia, which normally controls smooth, coordinated muscle function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Parkinson''s disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Parkinson''s disease is a neurodegenerative disorder caused by the loss of dopamine-producing neurons in the brain. This loss disrupts signals to the basal ganglia, which normally controls smooth, coordinated muscle function.\n\nThe classic four cardinal motor signs of this disease: bradykinesia (slow movements), muscular rigidity (stiffness), resting tremors, and postural instability (poor balance)—all directly caused by the drop in dopamine.\n\n• Multiple sclerosis is an autoimmune attack on the myelin sheath of nerves, causing numbness, tingling, and vision issues, not a dopamine deficit.\n• Cerebral palsy is a non-progressive movement disorder caused by brain damage that occurs around the time of birth.\n• Epilepsy is characterized by sudden, abnormal bursts of electrical activity in the brain that trigger seizures.","whyWrongChoices":"Alternative options: Multiple sclerosis, Cerebral palsy, Epilepsy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are hormones that regulate energy metabolism except::::calcitonin', 'the following are hormones that regulate energy metabolism except:', 'Calcitonin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Calcitonin is a hormone produced by the parafollicular cells (C-cells) of the thyroid gland. Its primary and specific function is to regulate calcium and phosphate balance in the body by lowering blood calcium levels (inhibiting bone-resorbing osteoclasts and promoting bone building). It does not play a direct role in macronutrient breakdown, cellular respiration, or overall energy metabolism.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Calcitonin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Calcitonin is a hormone produced by the parafollicular cells (C-cells) of the thyroid gland. Its primary and specific function is to regulate calcium and phosphate balance in the body by lowering blood calcium levels (inhibiting bone-resorbing osteoclasts and promoting bone building). It does not play a direct role in macronutrient breakdown, cellular respiration, or overall energy metabolism.\n\n• Thyroxine (T4) is the primary thyroid hormone responsible for establishing and regulating the body''s basal metabolic rate (BMR), dictating how fast cells utilize oxygen and burn energy.\n• Norepinephrine acts as a stress hormone and neurotransmitter that activates the sympathetic nervous system. It rapidly mobilizes stored energy fuels by accelerating fat breakdown (lipolysis) and glycogen conversion into glucose for immediate energy use.\n• Insulin is a major anabolic hormone produced by the pancreas. It heavily governs energy metabolism by directing cells to absorb glucose from the blood to either store it as glycogen or fat, or burn it for immediate energy.","whyWrongChoices":"Alternative options: Thyroxine, Norepinephrine, Insulin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are hormones that regulate energy metabolism except::::', 'the following are hormones that regulate energy metabolism except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Calcitonin is a hormone produced by the parafollicular cells (C-cells) of the thyroid gland. Its primary and specific function is to regulate calcium and phosphate balance in the body by lowering blood calcium levels (inhibiting bone-resorbing osteoclasts and promoting bone building). It does not play a direct role in macronutrient breakdown, cellular respiration, or overall energy metabolism.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Calcitonin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Calcitonin is a hormone produced by the parafollicular cells (C-cells) of the thyroid gland. Its primary and specific function is to regulate calcium and phosphate balance in the body by lowering blood calcium levels (inhibiting bone-resorbing osteoclasts and promoting bone building). It does not play a direct role in macronutrient breakdown, cellular respiration, or overall energy metabolism.\n\n• Thyroxine (T4) is the primary thyroid hormone responsible for establishing and regulating the body''s basal metabolic rate (BMR), dictating how fast cells utilize oxygen and burn energy.\n• Norepinephrine acts as a stress hormone and neurotransmitter that activates the sympathetic nervous system. It rapidly mobilizes stored energy fuels by accelerating fat breakdown (lipolysis) and glycogen conversion into glucose for immediate energy use.\n• Insulin is a major anabolic hormone produced by the pancreas. It heavily governs energy metabolism by directing cells to absorb glucose from the blood to either store it as glycogen or fat, or burn it for immediate energy.","whyWrongChoices":"Alternative options: Thyroxine, Norepinephrine, Insulin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the most common, simplest fatty in foods?:::', 'what is the most common, simplest fatty in foods?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"🟢 Stearic acid is one of the most common long-chain saturated fatty acids found in everyday foods, appearing abundantly in both animal fats (like beef and butter) and plant fats (like cocoa butter).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Stearic and acetic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"🟢 Stearic acid is one of the most common long-chain saturated fatty acids found in everyday foods, appearing abundantly in both animal fats (like beef and butter) and plant fats (like cocoa butter).\n\n🟢 Acetic acid is the simplest possible fatty acid because it contains only two carbon atoms (C2), making it the shortest and smallest carboxylic acid classified in this group.","whyWrongChoices":"Alternative options: Acetic and stearic acid, Butyric and acetic acid, Butyric and stearic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:transport form of lipid in blood which is associated with high cholesterol levels::::ldl', 'transport form of lipid in blood which is associated with high cholesterol levels:', 'LDL', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ VLDL (Very-Low-Density Lipoprotein): Transports mainly endogenous triglycerides (not primarily cholesterol) from the liver to adipose and muscle tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"LDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ VLDL (Very-Low-Density Lipoprotein): Transports mainly endogenous triglycerides (not primarily cholesterol) from the liver to adipose and muscle tissue.\n❌ IDL (Intermediate-Density Lipoprotein): Short-lived transitional remnant formed during the degradation of VLDL into LDL; not the primary clinical marker for elevated blood cholesterol.","whyWrongChoices":"❌ VLDL (Very-Low-Density Lipoprotein): Transports mainly endogenous triglycerides (not primarily cholesterol) from the liver to adipose and muscle tissue.\n❌ IDL (Intermediate-Density Lipoprotein): Short-lived transitional remnant formed during the degradation of VLDL into LDL; not the primary clinical marker for elevated blood cholesterol."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:transport form of lipid in blood which is associated with high cholesterol levels::::', 'transport form of lipid in blood which is associated with high cholesterol levels:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ VLDL (Very-Low-Density Lipoprotein): Transports mainly endogenous triglycerides (not primarily cholesterol) from the liver to adipose and muscle tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"LDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ VLDL (Very-Low-Density Lipoprotein): Transports mainly endogenous triglycerides (not primarily cholesterol) from the liver to adipose and muscle tissue.\n❌ IDL (Intermediate-Density Lipoprotein): Short-lived transitional remnant formed during the degradation of VLDL into LDL; not the primary clinical marker for elevated blood cholesterol.","whyWrongChoices":"❌ VLDL (Very-Low-Density Lipoprotein): Transports mainly endogenous triglycerides (not primarily cholesterol) from the liver to adipose and muscle tissue.\n❌ IDL (Intermediate-Density Lipoprotein): Short-lived transitional remnant formed during the degradation of VLDL into LDL; not the primary clinical marker for elevated blood cholesterol."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrients are absorbed through: i. simple diffusion ii. active transport iii. facilitated diffusion iv. pinocytosis:::', 'nutrients are absorbed through: i. simple diffusion ii. active transport iii. facilitated diffusion iv. pinocytosis', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Simple diffusion - Water and small lipids cross into intestinal cells freely;","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Simple diffusion - Water and small lipids cross into intestinal cells freely;\nFacilitated diffusion - water soluble vitamins need a specific carrier to transport them from one side of the cell membrane to the other;\nActive transport - glucose and amino acids move against a concentration gradient, which requires energy;\nPinocytosis, a form of endocytosis, in which material enters a cell through its membrane and is incorporated in vesicles for digestion.","whyWrongChoices":"Alternative options: I and III only, I, II, and III, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a measure of protein quality wherein the content of essential amino acids in food is divided by the amino acid requirements for each group.:::amino acid score', 'a measure of protein quality wherein the content of essential amino acids in food is divided by the amino acid requirements for each group.', 'Amino acid score', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The amino acid score (also known as the chemical score) is a laboratory-based method used to evaluate protein quality. This measurement of the content of essential amino acids contribute to the nutrition value of a protein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amino acid score\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The amino acid score (also known as the chemical score) is a laboratory-based method used to evaluate protein quality. This measurement of the content of essential amino acids contribute to the nutrition value of a protein.\n\nIt is determined mathematically by taking the amount of each essential amino acid in a food protein and dividing it by the corresponding amino acid requirement of a standard reference profile (typically tailored to specific age groups like infants or preschool children):\n\nAmino Acid Score = (mg of essential amino acid in 1 g of test protein / mg of essential amino acid in 1 g of reference protein) x 100\n\nThe lowest score among the essential amino acids identifies the limiting amino acid, which determines the overall quality of that specific protein source.\n\n• Protein digestibility: A measure of the percentage of nitrogen in food that is absorbed by the digestive tract based on the difference between dietary intake and fecal excretion.\n• Biologic value (BV): A measure of protein quality that calculates the percentage of absorbed nitrogen that is actually retained by the body for growth and maintenance. It requires tracking both fecal and urinary nitrogen in living subjects.\n• Protein efficiency ratio (PER): A biological assay that evaluates protein quality by tracking the physical weight gain of growing animal subjects divided by their specific protein intake over a test period.","whyWrongChoices":"Alternative options: Protein efficiency ratio, Biologic value, Protein digestibility"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a measure of protein quality wherein the content of essential amino acids in food is divided by the amino acid requirements for each group.:::', 'a measure of protein quality wherein the content of essential amino acids in food is divided by the amino acid requirements for each group.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The amino acid score (also known as the chemical score) is a laboratory-based method used to evaluate protein quality. This measurement of the content of essential amino acids contribute to the nutrition value of a protein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amino acid score\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The amino acid score (also known as the chemical score) is a laboratory-based method used to evaluate protein quality. This measurement of the content of essential amino acids contribute to the nutrition value of a protein.\n\nIt is determined mathematically by taking the amount of each essential amino acid in a food protein and dividing it by the corresponding amino acid requirement of a standard reference profile (typically tailored to specific age groups like infants or preschool children):\n\nAmino Acid Score = (mg of essential amino acid in 1 g of test protein / mg of essential amino acid in 1 g of reference protein) x 100\n\nThe lowest score among the essential amino acids identifies the limiting amino acid, which determines the overall quality of that specific protein source.\n\n• Protein digestibility: A measure of the percentage of nitrogen in food that is absorbed by the digestive tract based on the difference between dietary intake and fecal excretion.\n• Biologic value (BV): A measure of protein quality that calculates the percentage of absorbed nitrogen that is actually retained by the body for growth and maintenance. It requires tracking both fecal and urinary nitrogen in living subjects.\n• Protein efficiency ratio (PER): A biological assay that evaluates protein quality by tracking the physical weight gain of growing animal subjects divided by their specific protein intake over a test period.","whyWrongChoices":"Alternative options: Protein efficiency ratio, Biologic value, Protein digestibility"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a class of carbohydrates that is also called functional foods::::oligosaccharides', 'a class of carbohydrates that is also called functional foods:', 'Oligosaccharides', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Functional foods are foods or food components that offer health benefits beyond basic nutrition (like simple energy provision).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oligosaccharides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Functional foods are foods or food components that offer health benefits beyond basic nutrition (like simple energy provision).\n\nCertain non-digestible oligosaccharides—such as Fructo-oligosaccharides (FOS) and Galacto-oligosaccharides (GOS)—act directly as prebiotics.\n\nInstead of being broken down into simple sugars for immediate energy in the upper digestive tract, they pass into the large intestine where they feed and promote the growth of beneficial gut bacteria (Probiotics). This enhances gut health, microflora balance, and immune function, classifying them firmly as a class of carbohydrates used as functional foods.","whyWrongChoices":"Alternative options: Sucrose, Fructose, Glucose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a class of carbohydrates that is also called functional foods::::', 'a class of carbohydrates that is also called functional foods:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Functional foods are foods or food components that offer health benefits beyond basic nutrition (like simple energy provision).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oligosaccharides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Functional foods are foods or food components that offer health benefits beyond basic nutrition (like simple energy provision).\n\nCertain non-digestible oligosaccharides—such as Fructo-oligosaccharides (FOS) and Galacto-oligosaccharides (GOS)—act directly as prebiotics.\n\nInstead of being broken down into simple sugars for immediate energy in the upper digestive tract, they pass into the large intestine where they feed and promote the growth of beneficial gut bacteria (Probiotics). This enhances gut health, microflora balance, and immune function, classifying them firmly as a class of carbohydrates used as functional foods.","whyWrongChoices":"Alternative options: Sucrose, Fructose, Glucose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrients are absorbed through: i. simple diffusion ii. active transport iii. facilitated diffusion iv. pinocytosis:::all of the above', 'nutrients are absorbed through: i. simple diffusion ii. active transport iii. facilitated diffusion iv. pinocytosis', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Simple diffusion - Water and small lipids cross into intestinal cells freely;","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Simple diffusion - Water and small lipids cross into intestinal cells freely;\nFacilitated diffusion - water soluble vitamins need a specific carrier to transport them from one side of the cell membrane to the other;\nActive transport - glucose and amino acids move against a concentration gradient, which requires energy;\nPinocytosis, a form of endocytosis, in which material enters a cell through its membrane and is incorporated in vesicles for digestion.","whyWrongChoices":"Alternative options: I and III only, I, II, and III, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following slows or prolongs gastric emptying except::::motilin', 'all of the following slows or prolongs gastric emptying except:', 'Motilin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Motilin is released during the fasting state to stimulate the migrating motor complex (MMC), which “accelerate gastric emptying.”","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Motilin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Motilin is released during the fasting state to stimulate the migrating motor complex (MMC), which “accelerate gastric emptying.”\n\n🔴 Cholecystokinin (CCK): Released in response to fats and proteins in the duodenum, which “slows down the emptying of the stomach.”\n🔴 Glucagon-like peptide-1 (GLP-1): Acts as an incretin hormone that also “slows gastric emptying in healthy subjects, obese subjects, type 2 diabetic patients, and critically ill subjects.”","whyWrongChoices":"Alternative options: Cholecystokinin, GLP-1, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following slows or prolongs gastric emptying except::::', 'all of the following slows or prolongs gastric emptying except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Motilin is released during the fasting state to stimulate the migrating motor complex (MMC), which “accelerate gastric emptying.”","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Motilin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Motilin is released during the fasting state to stimulate the migrating motor complex (MMC), which “accelerate gastric emptying.”\n\n🔴 Cholecystokinin (CCK): Released in response to fats and proteins in the duodenum, which “slows down the emptying of the stomach.”\n🔴 Glucagon-like peptide-1 (GLP-1): Acts as an incretin hormone that also “slows gastric emptying in healthy subjects, obese subjects, type 2 diabetic patients, and critically ill subjects.”","whyWrongChoices":"Alternative options: Cholecystokinin, GLP-1, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:kimchi is a:::', 'kimchi is a', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Kimchi is produced through controlled lactic acid fermentation. Pickling may involve acidification, but kimchi is specifically recognized as a fermented vegetable product.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fermented product\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Kimchi is produced through controlled lactic acid fermentation. Pickling may involve acidification, but kimchi is specifically recognized as a fermented vegetable product.\n\nFermentation gives its characteristic flavor.","whyWrongChoices":"Alternative options: Pickled product, Cured product, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is not considered as a complimentary protein meal?:::bread with jam', 'which is not considered as a complimentary protein meal?', 'Bread with jam', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Complementary proteins combine two foods with different missing amino acids to make a complete protein. Bread with jam only provides carbohydrates and sugar. Jam contains no protein, so it cannot complete or complement the protein in bread.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bread with jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Complementary proteins combine two foods with different missing amino acids to make a complete protein. Bread with jam only provides carbohydrates and sugar. Jam contains no protein, so it cannot complete or complement the protein in bread.\n\n🔴 a. Rice and mongo: grain (rice) and a legume (mung beans) \n🔴 b. Macaroni with cheese: wheat pasta with cheese\n🔴 d. Pizza with salami: grain crust with meat and cheese","whyWrongChoices":"Alternative options: Rice and Mongo, Macaroni with cheese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is not considered as a complimentary protein meal?:::', 'which is not considered as a complimentary protein meal?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Complementary proteins combine two foods with different missing amino acids to make a complete protein. Bread with jam only provides carbohydrates and sugar. Jam contains no protein, so it cannot complete or complement the protein in bread.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bread with jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Complementary proteins combine two foods with different missing amino acids to make a complete protein. Bread with jam only provides carbohydrates and sugar. Jam contains no protein, so it cannot complete or complement the protein in bread.\n\n🔴 a. Rice and mongo: grain (rice) and a legume (mung beans) \n🔴 b. Macaroni with cheese: wheat pasta with cheese\n🔴 d. Pizza with salami: grain crust with meat and cheese","whyWrongChoices":"Alternative options: Rice and Mongo, Macaroni with cheese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the protein splitting enzymes of the pancreas::::carboxypeptidase and trypsin', 'the protein splitting enzymes of the pancreas:', 'Carboxypeptidase and trypsin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both are enzymes produced by the pancreas that break down proteins.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carboxypeptidase and trypsin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both are enzymes produced by the pancreas that break down proteins.\n\n• Pancreatic lipase breaks down fats, not proteins.\n• Pancreatic amylase breaks down carbohydrates (starches), not proteins.","whyWrongChoices":"Alternative options: Carboxypeptidase and pancreatic lipase, Pancreatic lipase and pancreatic amylase, Carboxypeptidase and pancreatic amylase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the protein splitting enzymes of the pancreas::::', 'the protein splitting enzymes of the pancreas:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Both are enzymes produced by the pancreas that break down proteins.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carboxypeptidase and trypsin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Both are enzymes produced by the pancreas that break down proteins.\n\n• Pancreatic lipase breaks down fats, not proteins.\n• Pancreatic amylase breaks down carbohydrates (starches), not proteins.","whyWrongChoices":"Alternative options: Carboxypeptidase and pancreatic lipase, Pancreatic lipase and pancreatic amylase, Carboxypeptidase and pancreatic amylase"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the era when the essentiality of vitamins where established.:::biological era', 'the era when the essentiality of vitamins where established.', 'Biological era', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biological Era (1900 – 1955) focused on the “discovery and understanding of vitamins and their role in health.”","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biological era\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biological Era (1900 – 1955) focused on the “discovery and understanding of vitamins and their role in health.”\n\n• a. Naturalistic Era: People believed food contained a single universal nutrient and relied on philosophy rather than chemical science to explain health.\n• b. Chemical-Analytical Era: Scientists used early chemistry to discover and measure macronutrients (carbohydrates, proteins, and fats) but did not yet know vitamins existed.\n• d. Cellular-Molecular Era: Modern researchers use advanced biotechnology to study how nutrients interact with human genes, DNA, and microscopic cellular pathways.","whyWrongChoices":"Alternative options: Naturalistic, Chemical-Analytical, Cellular-Molecular Era"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the era when the essentiality of vitamins where established.:::', 'the era when the essentiality of vitamins where established.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biological Era (1900 – 1955) focused on the “discovery and understanding of vitamins and their role in health.”","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biological era\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biological Era (1900 – 1955) focused on the “discovery and understanding of vitamins and their role in health.”\n\n• a. Naturalistic Era: People believed food contained a single universal nutrient and relied on philosophy rather than chemical science to explain health.\n• b. Chemical-Analytical Era: Scientists used early chemistry to discover and measure macronutrients (carbohydrates, proteins, and fats) but did not yet know vitamins existed.\n• d. Cellular-Molecular Era: Modern researchers use advanced biotechnology to study how nutrients interact with human genes, DNA, and microscopic cellular pathways.","whyWrongChoices":"Alternative options: Naturalistic, Chemical-Analytical, Cellular-Molecular Era"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:hormone which stimulates the contraction of gallbladder to secrete bile::::cholecystokinin', 'hormone which stimulates the contraction of gallbladder to secrete bile:', 'Cholecystokinin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"🔴 a. Lipase: Lipase is not a hormone; it is a digestive enzyme primarily produced by the pancreas that works alongside bile to chemically break down lipids (fats) into fatty acids and glycerol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cholecystokinin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"🔴 a. Lipase: Lipase is not a hormone; it is a digestive enzyme primarily produced by the pancreas that works alongside bile to chemically break down lipids (fats) into fatty acids and glycerol.\n🔴 b. Insulin: This is a metabolic hormone secreted by the beta cells of the pancreas. Its primary role is to regulate blood glucose levels by helping cells absorb glucose.\n🔴 d. Cholecalciferol: This is the chemical name for Vitamin D3.","whyWrongChoices":"Alternative options: Lipase, Insulin, Cholecalciferol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:hormone which stimulates the contraction of gallbladder to secrete bile::::', 'hormone which stimulates the contraction of gallbladder to secrete bile:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"🔴 a. Lipase: Lipase is not a hormone; it is a digestive enzyme primarily produced by the pancreas that works alongside bile to chemically break down lipids (fats) into fatty acids and glycerol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cholecystokinin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"🔴 a. Lipase: Lipase is not a hormone; it is a digestive enzyme primarily produced by the pancreas that works alongside bile to chemically break down lipids (fats) into fatty acids and glycerol.\n🔴 b. Insulin: This is a metabolic hormone secreted by the beta cells of the pancreas. Its primary role is to regulate blood glucose levels by helping cells absorb glucose.\n🔴 d. Cholecalciferol: This is the chemical name for Vitamin D3.","whyWrongChoices":"Alternative options: Lipase, Insulin, Cholecalciferol"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
