INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a measure of protein quality which is determined as the percentage of nitrogen in the food and feces of subjects on a diet: containing a test protein.:::protein digestibility', 'a measure of protein quality which is determined as the percentage of nitrogen in the food and feces of subjects on a diet: containing a test protein.', 'Protein digestibility', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Protein digestibility (specifically apparent or true digestibility) measures how well a protein source can be broken down and absorbed by the digestive tract.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Protein digestibility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Protein digestibility (specifically apparent or true digestibility) measures how well a protein source can be broken down and absorbed by the digestive tract.\n\nIt is calculated by finding the percentage of nitrogen consumed in the food that does not appear in the feces, revealing how much of that test protein was actually taken up into the body:\n\nProtein Digestibility (%) = [(Nitrogen in Food - Nitrogen in Feces) / Nitrogen in Food] x 100\n\n• Amino acid score: A chemical/laboratory measure that compares the amino acid profile of a test protein against a standard reference protein; it does not utilize living subjects or fecal analysis.\n• Protein efficiency ratio (PER): A measure of protein quality based on the weight gain of growing animal subjects divided by their intake of a particular food protein during a specific period.\n• Nitrogen balance: Measures the total influx of nitrogen versus total efflux. While it accounts for feces, it relies heavily on measuring urinary nitrogen to determine whether the body is retaining or losing overall protein mass.","whyWrongChoices":"Alternative options: Amino acid score, Protein efficiency ratio, Nitrogen balance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a measure of protein quality which is determined as the percentage of nitrogen in the food and feces of subjects on a diet: containing a test protein.:::', 'a measure of protein quality which is determined as the percentage of nitrogen in the food and feces of subjects on a diet: containing a test protein.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Protein digestibility (specifically apparent or true digestibility) measures how well a protein source can be broken down and absorbed by the digestive tract.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Protein digestibility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Protein digestibility (specifically apparent or true digestibility) measures how well a protein source can be broken down and absorbed by the digestive tract.\n\nIt is calculated by finding the percentage of nitrogen consumed in the food that does not appear in the feces, revealing how much of that test protein was actually taken up into the body:\n\nProtein Digestibility (%) = [(Nitrogen in Food - Nitrogen in Feces) / Nitrogen in Food] x 100\n\n• Amino acid score: A chemical/laboratory measure that compares the amino acid profile of a test protein against a standard reference protein; it does not utilize living subjects or fecal analysis.\n• Protein efficiency ratio (PER): A measure of protein quality based on the weight gain of growing animal subjects divided by their intake of a particular food protein during a specific period.\n• Nitrogen balance: Measures the total influx of nitrogen versus total efflux. While it accounts for feces, it relies heavily on measuring urinary nitrogen to determine whether the body is retaining or losing overall protein mass.","whyWrongChoices":"Alternative options: Amino acid score, Protein efficiency ratio, Nitrogen balance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the interior of the intestinal tract is called:::lumen', 'the interior of the intestinal tract is called', 'Lumen', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The actual open, interior space inside a tubular structure like the intestines where food and fluids pass.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lumen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The actual open, interior space inside a tubular structure like the intestines where food and fluids pass.\n\n🔴 Ileum: The final section of the small intestine.\n🔴 Mucosa: The innermost tissue layer that surrounds the lumen.\n🔴 Lining: A general term for the membrane covering the internal surface.","whyWrongChoices":"Alternative options: Ileum, Mucosa, Lining"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a food or group of foods served at one time or intended to be eaten at the same time is called::::course', 'a food or group of foods served at one time or intended to be eaten at the same time is called:', 'Course', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A course is a food or group of foods served or intended to be eaten at one time;","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Course\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A course is a food or group of foods served or intended to be eaten at one time;\n\nA menu is the list of offerings. \n\nA meal is an occasion when food is eaten.","whyWrongChoices":"Alternative options: Menu, Meal, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the form in which lipids are transported in the blood after digestion::::chylomicrons', 'the form in which lipids are transported in the blood after digestion:', 'Chylomicrons', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chylomicrons has the highest lipid content, lowest density, composed of TGs, synthesized in the intestinal wall and acted as transport TG in the blood and after a meal; cleared form the blood through the action of lipoprotein lipase.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chylomicrons\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chylomicrons has the highest lipid content, lowest density, composed of TGs, synthesized in the intestinal wall and acted as transport TG in the blood and after a meal; cleared form the blood through the action of lipoprotein lipase.\n\n🔴 Micelles: Tiny droplets that help move fatty acids to the intestinal wall, but they do not travel in the blood.\n🔴 Bile salts: Chemicals made by the liver that break large fat drops into smaller ones during digestion.\n🔴 Fatty acids: The individual building blocks of fats, which are reassembled into triglycerides inside cells before entering chylomicrons.","whyWrongChoices":"Alternative options: Micelles, Fatty acids, Bile salts"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food in its raw state, minus that which is discarded (bones, fat, skins, and/or seeds)::::', 'food in its raw state, minus that which is discarded (bones, fat, skins, and/or seeds):', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The edible portion of food refers to the part of the food item that is consumed after preparation, excluding any inedible or non-consumable parts like bones, peels, seeds, or other undesirable parts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Edible portion (EP)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The edible portion of food refers to the part of the food item that is consumed after preparation, excluding any inedible or non-consumable parts like bones, peels, seeds, or other undesirable parts.","whyWrongChoices":"Alternative options: As purchased (AP), Percentage Yield, Raw food weight"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the form in which lipids are transported in the blood after digestion::::', 'the form in which lipids are transported in the blood after digestion:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chylomicrons has the highest lipid content, lowest density, composed of TGs, synthesized in the intestinal wall and acted as transport TG in the blood and after a meal; cleared form the blood through the action of lipoprotein lipase.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chylomicrons\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chylomicrons has the highest lipid content, lowest density, composed of TGs, synthesized in the intestinal wall and acted as transport TG in the blood and after a meal; cleared form the blood through the action of lipoprotein lipase.\n\n🔴 Micelles: Tiny droplets that help move fatty acids to the intestinal wall, but they do not travel in the blood.\n🔴 Bile salts: Chemicals made by the liver that break large fat drops into smaller ones during digestion.\n🔴 Fatty acids: The individual building blocks of fats, which are reassembled into triglycerides inside cells before entering chylomicrons.","whyWrongChoices":"Alternative options: Micelles, Fatty acids, Bile salts"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:enzyme responsible for the breakdown of cooked starch to dextrin::::amylase', 'enzyme responsible for the breakdown of cooked starch to dextrin:', 'Amylase', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Amylase produced by the pancreas enters the small intestine to assist in digestion by hydrolyzing complex carbohydrates.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amylase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Amylase produced by the pancreas enters the small intestine to assist in digestion by hydrolyzing complex carbohydrates.","whyWrongChoices":"Alternative options: Lipase, Chymotrypsin, Trypsin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:enzyme responsible for the breakdown of cooked starch to dextrin::::', 'enzyme responsible for the breakdown of cooked starch to dextrin:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Amylase produced by the pancreas enters the small intestine to assist in digestion by hydrolyzing complex carbohydrates.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amylase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Amylase produced by the pancreas enters the small intestine to assist in digestion by hydrolyzing complex carbohydrates.","whyWrongChoices":"Alternative options: Lipase, Chymotrypsin, Trypsin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an important function of bile in digestion::::fat emulsification', 'an important function of bile in digestion:', 'Fat emulsification', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile salts are emulsifying agents; they disperse fats and form water-soluble micelles, which solubilize the products of fat digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fat emulsification\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile salts are emulsifying agents; they disperse fats and form water-soluble micelles, which solubilize the products of fat digestion.","whyWrongChoices":"Alternative options: Fat hydrolysis, Fat absorption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it prevents the reflux of small intestine contents to the stomach::::pyloric sphincter', 'it prevents the reflux of small intestine contents to the stomach:', 'Pyloric sphincter', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acts as a barrier to prevent the backward flow (reflux) of small intestine con tents—which contain bile and pancreatic enzymes—back into the stomach.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pyloric sphincter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acts as a barrier to prevent the backward flow (reflux) of small intestine con tents—which contain bile and pancreatic enzymes—back into the stomach.\n\n❌ a. Upper esophageal sphincter: Controls the passage of food into the feeding tube while preventing air from entering the gastrointestinal tract.\n❌ c. Lower esophageal sphincter: Regulates food entering the stomach while specifically preventing stomach acid and contents from refluxing upward into the esophagus.\n❌ d. Cardiac sphincter: This is simply another name for the lower esophageal sphincter.","whyWrongChoices":"Acts as a barrier to prevent the backward flow (reflux) of small intestine con tents—which contain bile and pancreatic enzymes—back into the stomach.\n\n❌ a. Upper esophageal sphincter: Controls the passage of food into the feeding tube while preventing air from entering the gastrointestinal tract.\n❌ c. Lower esophageal sphincter: Regulates food entering the stomach while specifically preventing stomach acid and contents from refluxing upward into the esophagus.\n❌ d. Cardiac sphincter: This is simply another name for the lower esophageal sphincter."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it prevents the reflux of small intestine contents to the stomach::::', 'it prevents the reflux of small intestine contents to the stomach:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acts as a barrier to prevent the backward flow (reflux) of small intestine con tents—which contain bile and pancreatic enzymes—back into the stomach.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pyloric sphincter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acts as a barrier to prevent the backward flow (reflux) of small intestine con tents—which contain bile and pancreatic enzymes—back into the stomach.\n\n❌ a. Upper esophageal sphincter: Controls the passage of food into the feeding tube while preventing air from entering the gastrointestinal tract.\n❌ c. Lower esophageal sphincter: Regulates food entering the stomach while specifically preventing stomach acid and contents from refluxing upward into the esophagus.\n❌ d. Cardiac sphincter: This is simply another name for the lower esophageal sphincter.","whyWrongChoices":"Acts as a barrier to prevent the backward flow (reflux) of small intestine con tents—which contain bile and pancreatic enzymes—back into the stomach.\n\n❌ a. Upper esophageal sphincter: Controls the passage of food into the feeding tube while preventing air from entering the gastrointestinal tract.\n❌ c. Lower esophageal sphincter: Regulates food entering the stomach while specifically preventing stomach acid and contents from refluxing upward into the esophagus.\n❌ d. Cardiac sphincter: This is simply another name for the lower esophageal sphincter."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are physiological actions of dietary fiber except::::improves mineral absorption', 'the following are physiological actions of dietary fiber except:', 'Improves mineral absorption', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dietary fiber—particularly when paired with food components like phytates, oxalates, and tannins found in high-fiber plant foods—actually binds to essential minerals (such as iron, zinc, calcium, and magnesium) in the intestinal tract. This binding action makes the minerals insoluble and decreases or hinders their absorption rather than improving it.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Improves mineral absorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dietary fiber—particularly when paired with food components like phytates, oxalates, and tannins found in high-fiber plant foods—actually binds to essential minerals (such as iron, zinc, calcium, and magnesium) in the intestinal tract. This binding action makes the minerals insoluble and decreases or hinders their absorption rather than improving it.","whyWrongChoices":"Alternative options: Increases bile acid excretion, Improves glucose tolerance, Decreases stool transit time"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are physiological actions of dietary fiber except::::', 'the following are physiological actions of dietary fiber except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dietary fiber—particularly when paired with food components like phytates, oxalates, and tannins found in high-fiber plant foods—actually binds to essential minerals (such as iron, zinc, calcium, and magnesium) in the intestinal tract. This binding action makes the minerals insoluble and decreases or hinders their absorption rather than improving it.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Improves mineral absorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dietary fiber—particularly when paired with food components like phytates, oxalates, and tannins found in high-fiber plant foods—actually binds to essential minerals (such as iron, zinc, calcium, and magnesium) in the intestinal tract. This binding action makes the minerals insoluble and decreases or hinders their absorption rather than improving it.","whyWrongChoices":"Alternative options: Increases bile acid excretion, Improves glucose tolerance, Decreases stool transit time"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the complex formed when bile salts combine with lipid material to facilitate digestion.:::micelle', 'the complex formed when bile salts combine with lipid material to facilitate digestion.', 'Micelle', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Micelles are aggregated lipids formed from bile salts to help the transport and absorption of fat-soluble vitamins and digestive products of lipids in the human body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micelle\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Micelles are aggregated lipids formed from bile salts to help the transport and absorption of fat-soluble vitamins and digestive products of lipids in the human body.","whyWrongChoices":"Alternative options: Chylomicron, HDL"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which molecule provides the immediate source of energy for muscle contraction?:::atp', 'which molecule provides the immediate source of energy for muscle contraction?', 'ATP', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Adenosine triphosphate (ATP) is the immediate source of energy used to power muscle contractions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ATP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Adenosine triphosphate (ATP) is the immediate source of energy used to power muscle contractions.\n\nInside muscle fibers, ATP binds directly to myosin heads. The subsequent hydrolysis of ATP into ADP (adenosine diphosphate) and an inorganic phosphate molecule (Pi) releases immediate chemical energy. This energy powers the myosin \"power stroke,\" sliding the muscle filaments past each other to cause a physical contraction. ATP is also required to disconnect the cross-bridges and pump calcium back into storage.\n\n• Lactic acid: A metabolic byproduct created during anaerobic glycolysis. It is not an energy source for contractions and can contribute to muscle fatigue if it accumulates heavily.\n• Glycogen: The storage form of carbohydrates inside liver and muscle cells. While it acts as a premier reservoir of energy, it must first undergo glycogenolysis and glycolysis to generate ATP molecules before the muscles can utilize it.\n• Fructose: A simple monosaccharide (fruit sugar) that must travel to the liver to be metabolized and fed into central energy pathways to generate ATP; it cannot be directly used by myosin heads.","whyWrongChoices":"Alternative options: Lactic acid, Glycogen, Fructose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which molecule provides the immediate source of energy for muscle contraction?:::', 'which molecule provides the immediate source of energy for muscle contraction?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Adenosine triphosphate (ATP) is the immediate source of energy used to power muscle contractions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ATP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Adenosine triphosphate (ATP) is the immediate source of energy used to power muscle contractions.\n\nInside muscle fibers, ATP binds directly to myosin heads. The subsequent hydrolysis of ATP into ADP (adenosine diphosphate) and an inorganic phosphate molecule (Pi) releases immediate chemical energy. This energy powers the myosin \"power stroke,\" sliding the muscle filaments past each other to cause a physical contraction. ATP is also required to disconnect the cross-bridges and pump calcium back into storage.\n\n• Lactic acid: A metabolic byproduct created during anaerobic glycolysis. It is not an energy source for contractions and can contribute to muscle fatigue if it accumulates heavily.\n• Glycogen: The storage form of carbohydrates inside liver and muscle cells. While it acts as a premier reservoir of energy, it must first undergo glycogenolysis and glycolysis to generate ATP molecules before the muscles can utilize it.\n• Fructose: A simple monosaccharide (fruit sugar) that must travel to the liver to be metabolized and fed into central energy pathways to generate ATP; it cannot be directly used by myosin heads.","whyWrongChoices":"Alternative options: Lactic acid, Glycogen, Fructose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the breakdown of triglycerides into fatty acids and glycerol::::lipolysis', 'the breakdown of triglycerides into fatty acids and glycerol:', 'Lipolysis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"*breakdown - hydrolysis","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lipolysis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"*breakdown - hydrolysis\n\nLipolysis is also known as TAG degradation.","whyWrongChoices":"Alternative options: Glycolysis, Lipogenesis, Beta oxidation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the breakdown of triglycerides into fatty acids and glycerol::::', 'the breakdown of triglycerides into fatty acids and glycerol:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"*breakdown - hydrolysis","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lipolysis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"*breakdown - hydrolysis\n\nLipolysis is also known as TAG degradation.","whyWrongChoices":"Alternative options: Glycolysis, Lipogenesis, Beta oxidation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:carbohydrate derivative which serves as a detoxifying agent in the liver::::heparin', 'carbohydrate derivative which serves as a detoxifying agent in the liver:', 'Heparin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ Ribose is a 5-carbon sugar used for RNA and ATP; has no detoxifying role.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Heparin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ Ribose is a 5-carbon sugar used for RNA and ATP; has no detoxifying role.\n❌ Pentose is a broad chemical class of 5-carbon monosaccharides; not a specific liver derivative.\n❌ Maltose is a simple glucose disaccharide; broken down solely for energy.","whyWrongChoices":"❌ Ribose is a 5-carbon sugar used for RNA and ATP; has no detoxifying role.\n❌ Pentose is a broad chemical class of 5-carbon monosaccharides; not a specific liver derivative.\n❌ Maltose is a simple glucose disaccharide; broken down solely for energy."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:carbohydrate derivative which serves as a detoxifying agent in the liver::::', 'carbohydrate derivative which serves as a detoxifying agent in the liver:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ Ribose is a 5-carbon sugar used for RNA and ATP; has no detoxifying role.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Heparin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ Ribose is a 5-carbon sugar used for RNA and ATP; has no detoxifying role.\n❌ Pentose is a broad chemical class of 5-carbon monosaccharides; not a specific liver derivative.\n❌ Maltose is a simple glucose disaccharide; broken down solely for energy.","whyWrongChoices":"❌ Ribose is a 5-carbon sugar used for RNA and ATP; has no detoxifying role.\n❌ Pentose is a broad chemical class of 5-carbon monosaccharides; not a specific liver derivative.\n❌ Maltose is a simple glucose disaccharide; broken down solely for energy."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the transport form of lipid which is associated with low cholesterol level is::::hdl', 'the transport form of lipid which is associated with low cholesterol level is:', 'HDL', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"High-Density Lipoprotein (HDL) is famously referred to as \"good cholesterol.\" It acts as a specialized scavenger vessel in the bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"HDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"High-Density Lipoprotein (HDL) is famously referred to as \"good cholesterol.\" It acts as a specialized scavenger vessel in the bloodstream.\n\nIts primary physiological function is to gather excess, circulating cholesterol from peripheral tissues and blood vessel walls and transport it back to the liver. The liver then processes, breaks down, and safe-clears this lipid burden out of the body.\n\nBecause HDL acts directly to clear away excess fats, higher circulating levels of functional HDL are structurally associated with lower overall peripheral tissue cholesterol levels and a reduced risk of plaque build-up (atherosclerosis).\n\n• LDL (Low-Density Lipoprotein): Acts as the primary transporter that delivers cholesterol to the cells and arteries. High levels of LDL are strongly associated with high peripheral cholesterol and heart disease risk.\n• VLDL (Very Low-Density Lipoprotein): Primarily carries newly made triglycerides from the liver out to body tissues.\n• IDL (Intermediate-Density Lipoprotein): A short-lived transition state formed as VLDL drops off its triglycerides and degrades into LDL.","whyWrongChoices":"Alternative options: VLDL, LDL, IDL"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the transport form of lipid which is associated with low cholesterol level is::::', 'the transport form of lipid which is associated with low cholesterol level is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"High-Density Lipoprotein (HDL) is famously referred to as \"good cholesterol.\" It acts as a specialized scavenger vessel in the bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"HDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"High-Density Lipoprotein (HDL) is famously referred to as \"good cholesterol.\" It acts as a specialized scavenger vessel in the bloodstream.\n\nIts primary physiological function is to gather excess, circulating cholesterol from peripheral tissues and blood vessel walls and transport it back to the liver. The liver then processes, breaks down, and safe-clears this lipid burden out of the body.\n\nBecause HDL acts directly to clear away excess fats, higher circulating levels of functional HDL are structurally associated with lower overall peripheral tissue cholesterol levels and a reduced risk of plaque build-up (atherosclerosis).\n\n• LDL (Low-Density Lipoprotein): Acts as the primary transporter that delivers cholesterol to the cells and arteries. High levels of LDL are strongly associated with high peripheral cholesterol and heart disease risk.\n• VLDL (Very Low-Density Lipoprotein): Primarily carries newly made triglycerides from the liver out to body tissues.\n• IDL (Intermediate-Density Lipoprotein): A short-lived transition state formed as VLDL drops off its triglycerides and degrades into LDL.","whyWrongChoices":"Alternative options: VLDL, LDL, IDL"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is an essential fatty acid?:::linoleic acid', 'which of the following is an essential fatty acid?', 'Linoleic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Linoleic acid is an omega-6 polyunsaturated fatty acid. It is classified as \"essential\" because the human body lacks the desaturase enzymes required to insert a chemical double bond beyond the carbon-9 position of a fatty acid chain. Because your body cannot synthesize it from scratch, it must be consumed directly through your diet (such as from vegetable oils, nuts, and seeds).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Linoleic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Linoleic acid is an omega-6 polyunsaturated fatty acid. It is classified as \"essential\" because the human body lacks the desaturase enzymes required to insert a chemical double bond beyond the carbon-9 position of a fatty acid chain. Because your body cannot synthesize it from scratch, it must be consumed directly through your diet (such as from vegetable oils, nuts, and seeds).\n\n❌ Palmitic acid: Saturated 16-carbon fatty acid synthesized endogenously by fatty acid synthase.\n❌ Stearic acid: Saturated 18-carbon fatty acid readily produced in the body from palmitic acid elongation.\n❌ Oleic acid: Monounsaturated omega-9 fatty acid synthesized endogenously via Δ9 desaturase.","whyWrongChoices":"Linoleic acid is an omega-6 polyunsaturated fatty acid. It is classified as \"essential\" because the human body lacks the desaturase enzymes required to insert a chemical double bond beyond the carbon-9 position of a fatty acid chain. Because your body cannot synthesize it from scratch, it must be consumed directly through your diet (such as from vegetable oils, nuts, and seeds).\n\n❌ Palmitic acid: Saturated 16-carbon fatty acid synthesized endogenously by fatty acid synthase.\n❌ Stearic acid: Saturated 18-carbon fatty acid readily produced in the body from palmitic acid elongation.\n❌ Oleic acid: Monounsaturated omega-9 fatty acid synthesized endogenously via Δ9 desaturase."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is an essential fatty acid?:::', 'which of the following is an essential fatty acid?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Linoleic acid is an omega-6 polyunsaturated fatty acid. It is classified as \"essential\" because the human body lacks the desaturase enzymes required to insert a chemical double bond beyond the carbon-9 position of a fatty acid chain. Because your body cannot synthesize it from scratch, it must be consumed directly through your diet (such as from vegetable oils, nuts, and seeds).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Linoleic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Linoleic acid is an omega-6 polyunsaturated fatty acid. It is classified as \"essential\" because the human body lacks the desaturase enzymes required to insert a chemical double bond beyond the carbon-9 position of a fatty acid chain. Because your body cannot synthesize it from scratch, it must be consumed directly through your diet (such as from vegetable oils, nuts, and seeds).\n\n❌ Palmitic acid: Saturated 16-carbon fatty acid synthesized endogenously by fatty acid synthase.\n❌ Stearic acid: Saturated 18-carbon fatty acid readily produced in the body from palmitic acid elongation.\n❌ Oleic acid: Monounsaturated omega-9 fatty acid synthesized endogenously via Δ9 desaturase.","whyWrongChoices":"Linoleic acid is an omega-6 polyunsaturated fatty acid. It is classified as \"essential\" because the human body lacks the desaturase enzymes required to insert a chemical double bond beyond the carbon-9 position of a fatty acid chain. Because your body cannot synthesize it from scratch, it must be consumed directly through your diet (such as from vegetable oils, nuts, and seeds).\n\n❌ Palmitic acid: Saturated 16-carbon fatty acid synthesized endogenously by fatty acid synthase.\n❌ Stearic acid: Saturated 18-carbon fatty acid readily produced in the body from palmitic acid elongation.\n❌ Oleic acid: Monounsaturated omega-9 fatty acid synthesized endogenously via Δ9 desaturase."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is an example of soluble dietary fiber?:::pectin', 'which of the following is an example of soluble dietary fiber?', 'Pectin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pectin is a structural polysaccharide found in the cell walls of fruits and vegetables (such as apples, citrus fruits, and carrots). It is highly water-soluble and absorbs water in the gastrointestinal tract to form a viscous, gel-like substance. This gelation slows down digestion, delays gastric emptying, stabilizes blood sugar levels, and binds to bile acids to help lower LDL cholesterol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pectin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pectin is a structural polysaccharide found in the cell walls of fruits and vegetables (such as apples, citrus fruits, and carrots). It is highly water-soluble and absorbs water in the gastrointestinal tract to form a viscous, gel-like substance. This gelation slows down digestion, delays gastric emptying, stabilizes blood sugar levels, and binds to bile acids to help lower LDL cholesterol.\n\n❌ Cellulose: Insoluble structural plant polysaccharide; adds fecal bulk without dissolving or gelling.\n❌ Lignin: Insoluble, non-carbohydrate complex polymer (polyphenolic); remains completely intact throughout the GI tract.\n❌ Chitin: Insoluble structural polysaccharide found in fungal walls and arthropod exoskeletons; non-gel-forming.","whyWrongChoices":"Pectin is a structural polysaccharide found in the cell walls of fruits and vegetables (such as apples, citrus fruits, and carrots). It is highly water-soluble and absorbs water in the gastrointestinal tract to form a viscous, gel-like substance. This gelation slows down digestion, delays gastric emptying, stabilizes blood sugar levels, and binds to bile acids to help lower LDL cholesterol.\n\n❌ Cellulose: Insoluble structural plant polysaccharide; adds fecal bulk without dissolving or gelling.\n❌ Lignin: Insoluble, non-carbohydrate complex polymer (polyphenolic); remains completely intact throughout the GI tract.\n❌ Chitin: Insoluble structural polysaccharide found in fungal walls and arthropod exoskeletons; non-gel-forming."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which carbohydrate-related compound is important in hepatic conjugation reactions that help detoxify certain substances?:::glucuronic acid', 'which carbohydrate-related compound is important in hepatic conjugation reactions that help detoxify certain substances?', 'Glucuronic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucuronic acid (a sugar acid derived from glucose oxidation) is the essential component in glucuronidation, one of the most important Phase II detoxification pathways in the liver (hepatic system).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucuronic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucuronic acid (a sugar acid derived from glucose oxidation) is the essential component in glucuronidation, one of the most important Phase II detoxification pathways in the liver (hepatic system).\n\nDuring this process:\n1. An enzyme transfers glucuronic acid onto toxic, hydrophobic (fat-soluble) substances like bilirubin, steroid hormones, and various drugs/toxins.\n2. This attachment significantly increases the molecule''s water solubility.\n3. The newly conjugated, non-toxic compound can then be safely excreted from the body via bile or urine.","whyWrongChoices":"Alternative options: Ribose, Lactose, Maltose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which carbohydrate-related compound is important in hepatic conjugation reactions that help detoxify certain substances?:::', 'which carbohydrate-related compound is important in hepatic conjugation reactions that help detoxify certain substances?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucuronic acid (a sugar acid derived from glucose oxidation) is the essential component in glucuronidation, one of the most important Phase II detoxification pathways in the liver (hepatic system).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucuronic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucuronic acid (a sugar acid derived from glucose oxidation) is the essential component in glucuronidation, one of the most important Phase II detoxification pathways in the liver (hepatic system).\n\nDuring this process:\n1. An enzyme transfers glucuronic acid onto toxic, hydrophobic (fat-soluble) substances like bilirubin, steroid hormones, and various drugs/toxins.\n2. This attachment significantly increases the molecule''s water solubility.\n3. The newly conjugated, non-toxic compound can then be safely excreted from the body via bile or urine.","whyWrongChoices":"Alternative options: Ribose, Lactose, Maltose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which class of carbohydrates includes prebiotic compounds such as fructooligosaccharides?:::oligosaccharides', 'which class of carbohydrates includes prebiotic compounds such as fructooligosaccharides?', 'Oligosaccharides', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Oligosaccharides of various origins have been used as pharmacological supplements, food ingredients, in processed food to aid weight control, to regulation of glucose control for diabetic patients and reducing serum lipid levels in hyperlipidemics and other some acute and chronic diseases.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oligosaccharides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Oligosaccharides of various origins have been used as pharmacological supplements, food ingredients, in processed food to aid weight control, to regulation of glucose control for diabetic patients and reducing serum lipid levels in hyperlipidemics and other some acute and chronic diseases.","whyWrongChoices":"Alternative options: Monosaccharides, Disaccharides"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which class of carbohydrates includes prebiotic compounds such as fructooligosaccharides?:::', 'which class of carbohydrates includes prebiotic compounds such as fructooligosaccharides?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Oligosaccharides of various origins have been used as pharmacological supplements, food ingredients, in processed food to aid weight control, to regulation of glucose control for diabetic patients and reducing serum lipid levels in hyperlipidemics and other some acute and chronic diseases.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oligosaccharides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Oligosaccharides of various origins have been used as pharmacological supplements, food ingredients, in processed food to aid weight control, to regulation of glucose control for diabetic patients and reducing serum lipid levels in hyperlipidemics and other some acute and chronic diseases.","whyWrongChoices":"Alternative options: Monosaccharides, Disaccharides"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar alcohols are produced primarily by the::::reduction of sugars', 'sugar alcohols are produced primarily by the:', 'Reduction of sugars', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sugar alcohols (also called polyols) are formed when the reactive carbonyl group—specifically the aldehyde or ketone group—of a sugar molecule is reduced to a hydroxyl group.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduction of sugars\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sugar alcohols (also called polyols) are formed when the reactive carbonyl group—specifically the aldehyde or ketone group—of a sugar molecule is reduced to a hydroxyl group.\n\nDuring this reduction process, hydrogen is added to the sugar molecule. This converts the open-chain form of a sugar into a non-reducing polyol that lacks any functional carbonyl groups.\n\nExamples of Sugar Reductions:\n\n• Glucose reduces to form Sorbitol (D-glucitol)\n• Mannose reduces to form Mannitol\n• Xylose reduces to form Xylitol\n• Galactose reduces to form Galactitol","whyWrongChoices":"Alternative options: Oxidation of fatty acids, Hydrolysis of proteins, Oxidation of amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar alcohols are produced primarily by the::::', 'sugar alcohols are produced primarily by the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sugar alcohols (also called polyols) are formed when the reactive carbonyl group—specifically the aldehyde or ketone group—of a sugar molecule is reduced to a hydroxyl group.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduction of sugars\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sugar alcohols (also called polyols) are formed when the reactive carbonyl group—specifically the aldehyde or ketone group—of a sugar molecule is reduced to a hydroxyl group.\n\nDuring this reduction process, hydrogen is added to the sugar molecule. This converts the open-chain form of a sugar into a non-reducing polyol that lacks any functional carbonyl groups.\n\nExamples of Sugar Reductions:\n\n• Glucose reduces to form Sorbitol (D-glucitol)\n• Mannose reduces to form Mannitol\n• Xylose reduces to form Xylitol\n• Galactose reduces to form Galactitol","whyWrongChoices":"Alternative options: Oxidation of fatty acids, Hydrolysis of proteins, Oxidation of amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is an example of complementary plant proteins?:::rice and mungo', 'which of the following is an example of complementary plant proteins?', 'Rice and mungo', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Complementary proteins are two or more incomplete plant-based protein sources that, when eaten together, balance out each other''s missing amino acids to create a complete protein profile containing all nine essential amino acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rice and mungo\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Complementary proteins are two or more incomplete plant-based protein sources that, when eaten together, balance out each other''s missing amino acids to create a complete protein profile containing all nine essential amino acids.\n\nThe classic formula for this is pairing a grain with a legume:\n• Rice (Grain): Is low in the essential amino acid lysine but high in methionine.\n• Mungo / Mung Bean (Legume): Is high in lysine but low in methionine.\n\nWhen you consume them together (a staple combination in Filipino and various Asian cultures), they perfectly offset each other''s deficits.","whyWrongChoices":"Alternative options: Rice and fish, Chicken and egg, Milk and cheese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is an example of complementary plant proteins?:::', 'which of the following is an example of complementary plant proteins?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Complementary proteins are two or more incomplete plant-based protein sources that, when eaten together, balance out each other''s missing amino acids to create a complete protein profile containing all nine essential amino acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rice and mungo\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Complementary proteins are two or more incomplete plant-based protein sources that, when eaten together, balance out each other''s missing amino acids to create a complete protein profile containing all nine essential amino acids.\n\nThe classic formula for this is pairing a grain with a legume:\n• Rice (Grain): Is low in the essential amino acid lysine but high in methionine.\n• Mungo / Mung Bean (Legume): Is high in lysine but low in methionine.\n\nWhen you consume them together (a staple combination in Filipino and various Asian cultures), they perfectly offset each other''s deficits.","whyWrongChoices":"Alternative options: Rice and fish, Chicken and egg, Milk and cheese"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a complete or high-quality protein can be described as::::containing essential amino acids in proper amounts and proportions', 'a complete or high-quality protein can be described as:', 'Containing essential amino acids in proper amounts and proportions', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In nutrition and dietetics board exams, a complete or high-quality protein is defined by its ability to supply all nine essential amino acids that the human body cannot synthesize on its own.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Containing essential amino acids in proper amounts and proportions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In nutrition and dietetics board exams, a complete or high-quality protein is defined by its ability to supply all nine essential amino acids that the human body cannot synthesize on its own.\n\nBeyond just presence, these amino acids must be provided in proper amounts and biological proportions that match human tissue requirements. This allows the body to seamlessly synthesize its own structural and metabolic proteins without encountering a \"limiting amino acid.\" Classic examples include animal sources (meat, fish, poultry, eggs, and dairy) as well as whole soy.","whyWrongChoices":"Alternative options: Providing some essential amino acids only, Combining essential and non-essential amino acids, Capable of continuous storage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a complete or high-quality protein can be described as::::', 'a complete or high-quality protein can be described as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In nutrition and dietetics board exams, a complete or high-quality protein is defined by its ability to supply all nine essential amino acids that the human body cannot synthesize on its own.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Containing essential amino acids in proper amounts and proportions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In nutrition and dietetics board exams, a complete or high-quality protein is defined by its ability to supply all nine essential amino acids that the human body cannot synthesize on its own.\n\nBeyond just presence, these amino acids must be provided in proper amounts and biological proportions that match human tissue requirements. This allows the body to seamlessly synthesize its own structural and metabolic proteins without encountering a \"limiting amino acid.\" Classic examples include animal sources (meat, fish, poultry, eggs, and dairy) as well as whole soy.","whyWrongChoices":"Alternative options: Providing some essential amino acids only, Combining essential and non-essential amino acids, Capable of continuous storage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it manufacturers enzymes to digest all energy yielding nutrients and release sodium bicarbonate to neutralize chyme that enters the small intestine.:::pancreas', 'it manufacturers enzymes to digest all energy yielding nutrients and release sodium bicarbonate to neutralize chyme that enters the small intestine.', 'Pancreas', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"GI hormones stimulate the pancreas to release sodium bicarbonate, an alkali which neutralizes the acidic chyme, to neutralize hydrochloric acid to pH 5-8.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pancreas\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"GI hormones stimulate the pancreas to release sodium bicarbonate, an alkali which neutralizes the acidic chyme, to neutralize hydrochloric acid to pH 5-8.","whyWrongChoices":"Alternative options: Liver, Kidney, Gallbladder"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it manufacturers enzymes to digest all energy yielding nutrients and release sodium bicarbonate to neutralize chyme that enters the small intestine.:::', 'it manufacturers enzymes to digest all energy yielding nutrients and release sodium bicarbonate to neutralize chyme that enters the small intestine.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"GI hormones stimulate the pancreas to release sodium bicarbonate, an alkali which neutralizes the acidic chyme, to neutralize hydrochloric acid to pH 5-8.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pancreas\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"GI hormones stimulate the pancreas to release sodium bicarbonate, an alkali which neutralizes the acidic chyme, to neutralize hydrochloric acid to pH 5-8.","whyWrongChoices":"Alternative options: Liver, Kidney, Gallbladder"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar alcohols are made up of::::hydrogenated dextrins', 'sugar alcohols are made up of:', 'Hydrogenated dextrins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Industrially, many bulk sugar alcohols (polyols) used in sugar-free products are produced via the hydrogenation (adding hydrogen molecules under pressure) of corn starch derivatives.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hydrogenated dextrins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Industrially, many bulk sugar alcohols (polyols) used in sugar-free products are produced via the hydrogenation (adding hydrogen molecules under pressure) of corn starch derivatives.\n\nWhen corn starch is broken down, it creates a mixture of short-chain glucose polymers called dextrins. When these dextrins are completely hydrogenated, the aldehyde groups on the sugars are reduced to alcohol groups, forming a sweet mixture of sugar alcohols known collectively as hydrogenated dextrins or hydrogenated starch hydrolysates.","whyWrongChoices":"Alternative options: Glucose polymers, Galactose and glucose, Glucose and fructose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar alcohols are made up of::::', 'sugar alcohols are made up of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Industrially, many bulk sugar alcohols (polyols) used in sugar-free products are produced via the hydrogenation (adding hydrogen molecules under pressure) of corn starch derivatives.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hydrogenated dextrins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Industrially, many bulk sugar alcohols (polyols) used in sugar-free products are produced via the hydrogenation (adding hydrogen molecules under pressure) of corn starch derivatives.\n\nWhen corn starch is broken down, it creates a mixture of short-chain glucose polymers called dextrins. When these dextrins are completely hydrogenated, the aldehyde groups on the sugars are reduced to alcohol groups, forming a sweet mixture of sugar alcohols known collectively as hydrogenated dextrins or hydrogenated starch hydrolysates.","whyWrongChoices":"Alternative options: Glucose polymers, Galactose and glucose, Glucose and fructose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:manufacturers bile for fat emulsification.:::liver', 'manufacturers bile for fat emulsification.', 'Liver', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Production: The liver makes bile every day.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liver\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Production: The liver makes bile every day.\nStorage: The gallbladder only stores and concentrates the bile until your body needs it.","whyWrongChoices":"Alternative options: Pancreas, Gallbladder, Stomach"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:manufacturers bile for fat emulsification.:::', 'manufacturers bile for fat emulsification.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Production: The liver makes bile every day.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liver\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Production: The liver makes bile every day.\nStorage: The gallbladder only stores and concentrates the bile until your body needs it.","whyWrongChoices":"Alternative options: Pancreas, Gallbladder, Stomach"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:key metabolic carbohydrate::::glucose', 'key metabolic carbohydrate:', 'Glucose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucose, also called blood sugar is the body’s major fuel to provide energy. It attaches to other sugars to form disaccharides and complex carbohydrates.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucose, also called blood sugar is the body’s major fuel to provide energy. It attaches to other sugars to form disaccharides and complex carbohydrates.","whyWrongChoices":"Alternative options: Galactose, Fructose, Sucrose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a type of dispersion consisting of two immiscible liquids.:::emulsion', 'a type of dispersion consisting of two immiscible liquids.', 'emulsion', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A type of dispersion consisting of two immiscible liquids is called an emulsion. In an emulsion, one liquid is dispersed in the form of small droplets throughout another liquid. Common examples include oil-in-water (O/W) and water-in-oil (W/O) emulsions, where the two liquids do not mix completely but are stabilized with the help of emulsifiers to prevent separation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"emulsion\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A type of dispersion consisting of two immiscible liquids is called an emulsion. In an emulsion, one liquid is dispersed in the form of small droplets throughout another liquid. Common examples include oil-in-water (O/W) and water-in-oil (W/O) emulsions, where the two liquids do not mix completely but are stabilized with the help of emulsifiers to prevent separation.\n\n• Gel: a semi-solid system where a network of polymer chains forms a three-dimensional structure, trapping a liquid within it. Examples include gelatin desserts and certain types of cheese.\n• Foam: a collection of gas bubbles dispersed in a liquid or solid. Examples include whipped cream (air in cream) and mousse.\n• Suspension: mixture in which solid particles are dispersed in a liquid but not dissolved. The particles in a suspension are typically larger and can settle over time. Examples include salad dressings and some types of sauces.","whyWrongChoices":"Alternative options: gel, foam, suspension"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a type of dispersion consisting of two immiscible liquids.:::', 'a type of dispersion consisting of two immiscible liquids.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A type of dispersion consisting of two immiscible liquids is called an emulsion. In an emulsion, one liquid is dispersed in the form of small droplets throughout another liquid. Common examples include oil-in-water (O/W) and water-in-oil (W/O) emulsions, where the two liquids do not mix completely but are stabilized with the help of emulsifiers to prevent separation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"emulsion\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A type of dispersion consisting of two immiscible liquids is called an emulsion. In an emulsion, one liquid is dispersed in the form of small droplets throughout another liquid. Common examples include oil-in-water (O/W) and water-in-oil (W/O) emulsions, where the two liquids do not mix completely but are stabilized with the help of emulsifiers to prevent separation.\n\n• Gel: a semi-solid system where a network of polymer chains forms a three-dimensional structure, trapping a liquid within it. Examples include gelatin desserts and certain types of cheese.\n• Foam: a collection of gas bubbles dispersed in a liquid or solid. Examples include whipped cream (air in cream) and mousse.\n• Suspension: mixture in which solid particles are dispersed in a liquid but not dissolved. The particles in a suspension are typically larger and can settle over time. Examples include salad dressings and some types of sauces.","whyWrongChoices":"Alternative options: gel, foam, suspension"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sliminess and color changes are signs of spoilage due to::::bacterial growth', 'sliminess and color changes are signs of spoilage due to:', 'bacterial growth', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bacterial growth on food can lead to changes in texture (such as sliminess) and color (such as discoloration or darkening). These changes occur as bacteria break down proteins and fats in the food, producing substances that alter its appearance and texture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bacterial growth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bacterial growth on food can lead to changes in texture (such as sliminess) and color (such as discoloration or darkening). These changes occur as bacteria break down proteins and fats in the food, producing substances that alter its appearance and texture.\n\n• Mold growth: Typically results in visible fuzzy or powdery patches on food, which can be various colors like green, blue, or white. Molds can cause spoilage but are less commonly associated with sliminess compared to bacteria.\n• Yeast growth: Can lead to spoilage, especially in sugary or acidic foods, causing fermentation and off-flavors. Yeasts are less likely to cause sliminess but can contribute to changes in texture and appearance.\n• Oxidative changes: Chemical reactions involving oxygen that can lead to rancidity, discoloration, and off-flavors, particularly in fats and oils. These changes are not typically associated with sliminess but with color changes.","whyWrongChoices":"Alternative options: mold growth, yeast growth, oxidative changes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sliminess and color changes are signs of spoilage due to::::', 'sliminess and color changes are signs of spoilage due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bacterial growth on food can lead to changes in texture (such as sliminess) and color (such as discoloration or darkening). These changes occur as bacteria break down proteins and fats in the food, producing substances that alter its appearance and texture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bacterial growth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bacterial growth on food can lead to changes in texture (such as sliminess) and color (such as discoloration or darkening). These changes occur as bacteria break down proteins and fats in the food, producing substances that alter its appearance and texture.\n\n• Mold growth: Typically results in visible fuzzy or powdery patches on food, which can be various colors like green, blue, or white. Molds can cause spoilage but are less commonly associated with sliminess compared to bacteria.\n• Yeast growth: Can lead to spoilage, especially in sugary or acidic foods, causing fermentation and off-flavors. Yeasts are less likely to cause sliminess but can contribute to changes in texture and appearance.\n• Oxidative changes: Chemical reactions involving oxygen that can lead to rancidity, discoloration, and off-flavors, particularly in fats and oils. These changes are not typically associated with sliminess but with color changes.","whyWrongChoices":"Alternative options: mold growth, yeast growth, oxidative changes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in cooking fibrous fruits like langka or beans in sugar syrup, tough product is obtained if::::sugar is added too early', 'in cooking fibrous fruits like langka or beans in sugar syrup, tough product is obtained if:', 'sugar is added too early', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Adding sugar too early in the cooking process can toughen fibrous fruits because it can cause the cell walls of the fruit to harden before they have a chance to soften sufficiently. This can lead to a chewy or tough texture instead of the desired tender consistency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"sugar is added too early\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Adding sugar too early in the cooking process can toughen fibrous fruits because it can cause the cell walls of the fruit to harden before they have a chance to soften sufficiently. This can lead to a chewy or tough texture instead of the desired tender consistency.\n\n• Adding sugar too late might result in a less integrated flavor or less effective syrup concentration but generally doesn’t cause toughness. The texture issues are more related to when the sugar is added relative to the cooking time.\n• Brown sugar can add a different flavor and color due to the presence of molasses, but it doesn’t usually make the product tougher. The toughness is more influenced by the timing of sugar addition.\n• Stirring the syrup while cooking is generally done to ensure even cooking and to prevent burning.","whyWrongChoices":"Alternative options: sugar is added too late, brown sugar is used, the syrup is stirred while cooking"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in cooking fibrous fruits like langka or beans in sugar syrup, tough product is obtained if::::', 'in cooking fibrous fruits like langka or beans in sugar syrup, tough product is obtained if:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Adding sugar too early in the cooking process can toughen fibrous fruits because it can cause the cell walls of the fruit to harden before they have a chance to soften sufficiently. This can lead to a chewy or tough texture instead of the desired tender consistency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"sugar is added too early\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Adding sugar too early in the cooking process can toughen fibrous fruits because it can cause the cell walls of the fruit to harden before they have a chance to soften sufficiently. This can lead to a chewy or tough texture instead of the desired tender consistency.\n\n• Adding sugar too late might result in a less integrated flavor or less effective syrup concentration but generally doesn’t cause toughness. The texture issues are more related to when the sugar is added relative to the cooking time.\n• Brown sugar can add a different flavor and color due to the presence of molasses, but it doesn’t usually make the product tougher. The toughness is more influenced by the timing of sugar addition.\n• Stirring the syrup while cooking is generally done to ensure even cooking and to prevent burning.","whyWrongChoices":"Alternative options: sugar is added too late, brown sugar is used, the syrup is stirred while cooking"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a culinary term which means to allow the evaporation of a liquid for a more concentrated sauce.:::reduction', 'it is a culinary term which means to allow the evaporation of a liquid for a more concentrated sauce.', 'Reduction', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reduction involves simmering or boiling a liquid (such as stock, wine, or sauce) to evaporate water and concentrate the flavors. This process thickens the liquid and intensifies its taste, resulting in a richer sauce or liquid base for dishes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduction\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reduction involves simmering or boiling a liquid (such as stock, wine, or sauce) to evaporate water and concentrate the flavors. This process thickens the liquid and intensifies its taste, resulting in a richer sauce or liquid base for dishes.\n\n• Concasse: This term refers to a method of preparing tomatoes by blanching, peeling, and chopping them into small pieces. The technique is often used to create a base for sauces or as a fresh ingredient in various dishes.\n• Deglazing: This process involves adding liquid (like wine, broth, or vinegar) to a pan after sautéing or searing meat to loosen and dissolve the browned bits of food (Fond) stuck to the bottom. The resulting mixture can be used as a base for sauces.\n\n*Fond, the browned bits left on the bottom of a pan after cooking, is not typically carcinogenic. It forms from the Maillard reaction, a process where proteins and sugars in food brown and develop complex flavors. However, it’s important to distinguish fond from burnt food. If food is burned to the point of charring, it can produce potentially harmful compounds, including some that are carcinogenic, like acrylamide and polycyclic aromatic hydrocarbons (PAHs). As long as the fond is browned and not charred, it is generally safe and adds flavor to dishes.\n\n• Dredging: This technique involves coating food, usually meat or fish, with a dry ingredient like flour, breadcrumbs, or cornmeal before cooking. Dredging helps create a crispy exterior when the food is fried or baked.","whyWrongChoices":"Alternative options: Concasse, Deglazing, Dredging"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
