INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the diameter of a feeding tube is measured in what units?:::french unit', 'the diameter of a feeding tube is measured in what units?', 'French unit', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The external diameter of feeding tubes (as well as urinary catheters) is measured using the French scale (abbreviated as Fr or F).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"French unit\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The external diameter of feeding tubes (as well as urinary catheters) is measured using the French scale (abbreviated as Fr or F).\n• One French unit is equal to exactly 1/3 of a millimeter (0.33 mm). Therefore, a larger French number means a thicker tube (e.g., a 12 Fr tube has an outer diameter of 4 mm).","whyWrongChoices":"Alternative options: Diameter unit, Nasogastric tube, Tube circumference unit"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the diameter of a feeding tube is measured in what units?:::', 'the diameter of a feeding tube is measured in what units?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The external diameter of feeding tubes (as well as urinary catheters) is measured using the French scale (abbreviated as Fr or F).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"French unit\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The external diameter of feeding tubes (as well as urinary catheters) is measured using the French scale (abbreviated as Fr or F).\n• One French unit is equal to exactly 1/3 of a millimeter (0.33 mm). Therefore, a larger French number means a thicker tube (e.g., a 12 Fr tube has an outer diameter of 4 mm).","whyWrongChoices":"Alternative options: Diameter unit, Nasogastric tube, Tube circumference unit"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a type of cirrhosis caused by obstruction of the bile ducts::::biliary cirrhosis', 'a type of cirrhosis caused by obstruction of the bile ducts:', 'Biliary cirrhosis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biliary cirrhosis develops when there is prolonged inflammation, scarring, or permanent mechanical obstruction within the bile duct system. When these ducts are blocked, bile cannot empty normally into the small intestine and instead backs up into the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biliary cirrhosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biliary cirrhosis develops when there is prolonged inflammation, scarring, or permanent mechanical obstruction within the bile duct system. When these ducts are blocked, bile cannot empty normally into the small intestine and instead backs up into the liver.\n\n• Laennec''s cirrhosis: Also known as portal or alcoholic cirrhosis, this most common form of liver disease is explicitly caused by chronic, long-term alcohol abuse.\n• Obstructive cirrhosis: While it sounds structurally logical, \"obstructive\" is a description of the mechanism rather than the formal, standard medical classification for this type of hepatic pathology.\n• Cardiac cirrhosis: This rare form of liver scarring stems from severe, long-term right-sided heart failure that creates a chronic backpressure of venous blood (congestive hepatopathy) in the liver.","whyWrongChoices":"Alternative options: Cardiac cirrhosis, Laennec''s cirrhosis, Obstructive cirrhosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a type of cirrhosis caused by obstruction of the bile ducts::::', 'a type of cirrhosis caused by obstruction of the bile ducts:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biliary cirrhosis develops when there is prolonged inflammation, scarring, or permanent mechanical obstruction within the bile duct system. When these ducts are blocked, bile cannot empty normally into the small intestine and instead backs up into the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biliary cirrhosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biliary cirrhosis develops when there is prolonged inflammation, scarring, or permanent mechanical obstruction within the bile duct system. When these ducts are blocked, bile cannot empty normally into the small intestine and instead backs up into the liver.\n\n• Laennec''s cirrhosis: Also known as portal or alcoholic cirrhosis, this most common form of liver disease is explicitly caused by chronic, long-term alcohol abuse.\n• Obstructive cirrhosis: While it sounds structurally logical, \"obstructive\" is a description of the mechanism rather than the formal, standard medical classification for this type of hepatic pathology.\n• Cardiac cirrhosis: This rare form of liver scarring stems from severe, long-term right-sided heart failure that creates a chronic backpressure of venous blood (congestive hepatopathy) in the liver.","whyWrongChoices":"Alternative options: Cardiac cirrhosis, Laennec''s cirrhosis, Obstructive cirrhosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are indications of parenteral nutrition, except::::hemodynamically unstable patients', 'the following are indications of parenteral nutrition, except:', 'Hemodynamically unstable patients', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemodynamically unstable patients (those suffering from active shock, severe hypotension, or critical fluid/electrolyte imbalances) are a strict contraindication for parenteral nutrition, not an indication. Prior to initiating any form of nutritional support, the patient must be stabilized with fluid resuscitation and vasopressors. Attempting to infuse hyperosmolar PN into an unstable patient can worsen metabolic stress, increase the risk of severe refeeding complications, and destabilize hemodynamics further.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemodynamically unstable patients\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemodynamically unstable patients (those suffering from active shock, severe hypotension, or critical fluid/electrolyte imbalances) are a strict contraindication for parenteral nutrition, not an indication. Prior to initiating any form of nutritional support, the patient must be stabilized with fluid resuscitation and vasopressors. Attempting to infuse hyperosmolar PN into an unstable patient can worsen metabolic stress, increase the risk of severe refeeding complications, and destabilize hemodynamics further.","whyWrongChoices":"Alternative options: Severe diarrhea of  >500ml/day stool, or malabsorption, Intractable vomiting, Small bowel or colon obstruction"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are indications of parenteral nutrition, except::::', 'the following are indications of parenteral nutrition, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemodynamically unstable patients (those suffering from active shock, severe hypotension, or critical fluid/electrolyte imbalances) are a strict contraindication for parenteral nutrition, not an indication. Prior to initiating any form of nutritional support, the patient must be stabilized with fluid resuscitation and vasopressors. Attempting to infuse hyperosmolar PN into an unstable patient can worsen metabolic stress, increase the risk of severe refeeding complications, and destabilize hemodynamics further.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemodynamically unstable patients\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemodynamically unstable patients (those suffering from active shock, severe hypotension, or critical fluid/electrolyte imbalances) are a strict contraindication for parenteral nutrition, not an indication. Prior to initiating any form of nutritional support, the patient must be stabilized with fluid resuscitation and vasopressors. Attempting to infuse hyperosmolar PN into an unstable patient can worsen metabolic stress, increase the risk of severe refeeding complications, and destabilize hemodynamics further.","whyWrongChoices":"Alternative options: Severe diarrhea of  >500ml/day stool, or malabsorption, Intractable vomiting, Small bowel or colon obstruction"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:also called portal systematic encephalopathy::::hepatic coma', 'also called portal systematic encephalopathy:', 'Hepatic coma', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Portal-systemic encephalopathy (PSE) and hepatic encephalopathy are a spectrum of central nervous system dysfunctions caused by liver failure or shunting. Historically and in clinical question banks, hepatic coma (or coma hepaticum) is used interchangeably to describe its severe, final stage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hepatic coma\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Portal-systemic encephalopathy (PSE) and hepatic encephalopathy are a spectrum of central nervous system dysfunctions caused by liver failure or shunting. Historically and in clinical question banks, hepatic coma (or coma hepaticum) is used interchangeably to describe its severe, final stage.","whyWrongChoices":"Alternative options: Obstructive cirrhosis, Portal hypertension, Pancreatitis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:zinc is given to burned patients to::::promote wound healing', 'zinc is given to burned patients to:', 'Promote wound healing', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Major burns cause extensive exudative loss of trace minerals through the open wounds. Zinc plays an indispensable role in every stage of tissue repair, including cellular proliferation, collagen synthesis, and re-epithelialization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Promote wound healing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Major burns cause extensive exudative loss of trace minerals through the open wounds. Zinc plays an indispensable role in every stage of tissue repair, including cellular proliferation, collagen synthesis, and re-epithelialization.","whyWrongChoices":"Alternative options: Prevent diarrhea, To supply oxidative enzymes, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is true about basal metabolic rate?:::', 'which of the following is true about basal metabolic rate?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When the body develops a fever, its internal temperature rises, which accelerates enzymatic and cellular activities to help fight off infection. As a general clinical rule, BMR increases by approximately 7% for every 1°F rise in body temperature.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fever increases BMR\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When the body develops a fever, its internal temperature rises, which accelerates enzymatic and cellular activities to help fight off infection. As a general clinical rule, BMR increases by approximately 7% for every 1°F rise in body temperature.","whyWrongChoices":"Alternative options: Pregnancy decreases BMR, Fasting increases BMR, Females have higher BMR than males"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:gastroesophageal reflux disease (gerd) is the constant regurgitation of acidic gastric contents into the lower part of the esophagus with symptoms including frequent and severe heartburn, dysphagia, and excessive belching.:::true', 'gastroesophageal reflux disease (gerd) is the constant regurgitation of acidic gastric contents into the lower part of the esophagus with symptoms including frequent and severe heartburn, dysphagia, and excessive belching.', 'True', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastroesophageal reflux disease (GERD) occurs when the lower esophageal sphincter (LES) weakens or relaxes inappropriately. This structural failure allows acidic gastric juices, and sometimes bile, to flow backward (regurgitate) chronically into the esophagus.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"True\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastroesophageal reflux disease (GERD) occurs when the lower esophageal sphincter (LES) weakens or relaxes inappropriately. This structural failure allows acidic gastric juices, and sometimes bile, to flow backward (regurgitate) chronically into the esophagus.\n\nBecause the lining of the esophagus lacks the protective mucus barrier found in the stomach, this repeated exposure to harsh gastric acid causes intense irritation, inflammation, and injury. This pathophysiology directly manifests as the classic clinical triad:\n• Severe, frequent heartburn (pyrosis)\n• Dysphagia (difficulty swallowing due to inflammation or strictures)\n• Excessive belching (eructation)","whyWrongChoices":"Alternative options: False, Maybe, Depends"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following increases bmr, except::::', 'all of the following increases bmr, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Basal Metabolic Rate (BMR) represents the minimum energy required to keep vital functions (like breathing and circulation) active. During sleep, your muscle activity drops, your heart rate slows down, and your body enters its lowest metabolic state, causing your energy expenditure to drop below awake basal levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sleeping\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Basal Metabolic Rate (BMR) represents the minimum energy required to keep vital functions (like breathing and circulation) active. During sleep, your muscle activity drops, your heart rate slows down, and your body enters its lowest metabolic state, causing your energy expenditure to drop below awake basal levels.","whyWrongChoices":"Alternative options: Thyroxine, Adrenaline, Stress hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:gastroesophageal reflux disease (gerd) is the constant regurgitation of acidic gastric contents into the lower part of the esophagus with symptoms including frequent and severe heartburn, dysphagia, and excessive belching.:::', 'gastroesophageal reflux disease (gerd) is the constant regurgitation of acidic gastric contents into the lower part of the esophagus with symptoms including frequent and severe heartburn, dysphagia, and excessive belching.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastroesophageal reflux disease (GERD) occurs when the lower esophageal sphincter (LES) weakens or relaxes inappropriately. This structural failure allows acidic gastric juices, and sometimes bile, to flow backward (regurgitate) chronically into the esophagus.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"True\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastroesophageal reflux disease (GERD) occurs when the lower esophageal sphincter (LES) weakens or relaxes inappropriately. This structural failure allows acidic gastric juices, and sometimes bile, to flow backward (regurgitate) chronically into the esophagus.\n\nBecause the lining of the esophagus lacks the protective mucus barrier found in the stomach, this repeated exposure to harsh gastric acid causes intense irritation, inflammation, and injury. This pathophysiology directly manifests as the classic clinical triad:\n• Severe, frequent heartburn (pyrosis)\n• Dysphagia (difficulty swallowing due to inflammation or strictures)\n• Excessive belching (eructation)","whyWrongChoices":"Alternative options: False, Maybe, Depends"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the osmolality of 210 ml of 5% amino acids.:::262 mosm', 'compute for the osmolality of 210 ml of 5% amino acids.', '262 mOsm', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Find the total grams of amino acids: A 5% solution means there are 5 grams of solute in every 100 mL of fluid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"262 mOsm\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Find the total grams of amino acids: A 5% solution means there are 5 grams of solute in every 100 mL of fluid.\nTotal grams =\\frac{5\\text{\\ g}}{100\\text{\\ mL}}\\times 210\\text{\\ mL}=\\mathbf{10.5}\\text{\\ grams\\ of\\ amino\\ acids}\\)\n2. Apply the osmolarity factor for amino acids: In clinical nutrition and parenteral calculations, 1 gram of amino acids contributes approximately 10 mOsm to the solution.\n3. Calculate the final osmolarity:\n\\(10.5\\text{\\ grams}\\times 10\\text{\\ mOsm/g}=\\mathbf{105}\\text{\\ mOsm}\\)","whyWrongChoices":"Alternative options: 300 mOsm, 290 mOsm, 105 mOsm"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the osmolality of 210 ml of 5% amino acids.:::', 'compute for the osmolality of 210 ml of 5% amino acids.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. Find the total grams of amino acids: A 5% solution means there are 5 grams of solute in every 100 mL of fluid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"262 mOsm\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. Find the total grams of amino acids: A 5% solution means there are 5 grams of solute in every 100 mL of fluid.\nTotal grams =\\frac{5\\text{\\ g}}{100\\text{\\ mL}}\\times 210\\text{\\ mL}=\\mathbf{10.5}\\text{\\ grams\\ of\\ amino\\ acids}\\)\n2. Apply the osmolarity factor for amino acids: In clinical nutrition and parenteral calculations, 1 gram of amino acids contributes approximately 10 mOsm to the solution.\n3. Calculate the final osmolarity:\n\\(10.5\\text{\\ grams}\\times 10\\text{\\ mOsm/g}=\\mathbf{105}\\text{\\ mOsm}\\)","whyWrongChoices":"Alternative options: 300 mOsm, 290 mOsm, 105 mOsm"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the disruption of the internal balance that lies beyond healthy and normal functioning::::pathologic stress', 'it is the disruption of the internal balance that lies beyond healthy and normal functioning:', 'Pathologic stress', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Physiologic stress is a healthy, normal response of the body to daily changes or stressors (like exercise or cold weather) aimed at restoring homeostasis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pathologic stress\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Physiologic stress is a healthy, normal response of the body to daily changes or stressors (like exercise or cold weather) aimed at restoring homeostasis.\n• When a stressor is too intense or prolonged, it pushes the body''s systems past their normal limits. This maladaptive state results in damage or a failure to maintain balance, turning into pathologic stress (which can eventually manifest as disease or tissue injury).","whyWrongChoices":"Alternative options: Stress, Physiologic stress, Hormonal stress"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the disruption of the internal balance that lies beyond healthy and normal functioning::::', 'it is the disruption of the internal balance that lies beyond healthy and normal functioning:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Physiologic stress is a healthy, normal response of the body to daily changes or stressors (like exercise or cold weather) aimed at restoring homeostasis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pathologic stress\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Physiologic stress is a healthy, normal response of the body to daily changes or stressors (like exercise or cold weather) aimed at restoring homeostasis.\n• When a stressor is too intense or prolonged, it pushes the body''s systems past their normal limits. This maladaptive state results in damage or a failure to maintain balance, turning into pathologic stress (which can eventually manifest as disease or tissue injury).","whyWrongChoices":"Alternative options: Stress, Physiologic stress, Hormonal stress"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:may interact with warfarin::::vit k', 'may interact with warfarin:', 'Vit K', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Warfarin is an anticoagulant that works by blocking the enzyme responsible for recycling Vitamin K. Since Vitamin K is essential for the liver to synthesize blood-clotting factors (Factors II, VII, IX, and X), a sudden increase or decrease in dietary Vitamin K directly alters how well Warfarin works.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit K\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Warfarin is an anticoagulant that works by blocking the enzyme responsible for recycling Vitamin K. Since Vitamin K is essential for the liver to synthesize blood-clotting factors (Factors II, VII, IX, and X), a sudden increase or decrease in dietary Vitamin K directly alters how well Warfarin works.\n• Consuming high amounts of Vitamin K (like green leafy vegetables) will reverse or reduce the blood-thinning effect of Warfarin, increasing the risk of blood clots. Conversely, dropping Vitamin K intake can dangerousy increase the risk of bleeding.","whyWrongChoices":"Alternative options: Vit A, Vit D, Vit E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:may interact with warfarin::::', 'may interact with warfarin:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Warfarin is an anticoagulant that works by blocking the enzyme responsible for recycling Vitamin K. Since Vitamin K is essential for the liver to synthesize blood-clotting factors (Factors II, VII, IX, and X), a sudden increase or decrease in dietary Vitamin K directly alters how well Warfarin works.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit K\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Warfarin is an anticoagulant that works by blocking the enzyme responsible for recycling Vitamin K. Since Vitamin K is essential for the liver to synthesize blood-clotting factors (Factors II, VII, IX, and X), a sudden increase or decrease in dietary Vitamin K directly alters how well Warfarin works.\n• Consuming high amounts of Vitamin K (like green leafy vegetables) will reverse or reduce the blood-thinning effect of Warfarin, increasing the risk of blood clots. Conversely, dropping Vitamin K intake can dangerousy increase the risk of bleeding.","whyWrongChoices":"Alternative options: Vit A, Vit D, Vit E"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the process of milk synthesis and secretion of the mammary gland?:::', 'what is the process of milk synthesis and secretion of the mammary gland?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lactogenesis is the initiation/start of milk production.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lactogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lactogenesis is the initiation/start of milk production.\n\nLactation is the entire, ongoing process of milk production and secretion.","whyWrongChoices":"Alternative options: Lactation, All of the above, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a classification of anemia to describe the hemoglobin content::::hypochromic anemia', 'a classification of anemia to describe the hemoglobin content:', 'Hypochromic anemia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Anemias are classified morphologically using two main criteria: cell size and hemoglobin content (color).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hypochromic anemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Anemias are classified morphologically using two main criteria: cell size and hemoglobin content (color).\n• Hemoglobin Content (Color): The term chromic refers to color, which is determined by the concentration of hemoglobin inside the red blood cell (RBC).\n\t✓ Hypochromic means the cells have less hemoglobin than normal, making them look pale under a microscope.\n\t✓ Normochromic means the hemoglobin concentration is normal.\n• Cell Size: The term cytic refers to the physical size of the RBC. Macrocytic, Normocytic, and Microcytic describe whether the cells are larger than normal, normal-sized, or smaller than normal. They do not classify hemoglobin content itself.","whyWrongChoices":"Alternative options: Macrocytic anemia, Normocytic anemia, Microcytic anemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a classification of anemia to describe the hemoglobin content::::', 'a classification of anemia to describe the hemoglobin content:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Anemias are classified morphologically using two main criteria: cell size and hemoglobin content (color).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hypochromic anemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Anemias are classified morphologically using two main criteria: cell size and hemoglobin content (color).\n• Hemoglobin Content (Color): The term chromic refers to color, which is determined by the concentration of hemoglobin inside the red blood cell (RBC).\n\t✓ Hypochromic means the cells have less hemoglobin than normal, making them look pale under a microscope.\n\t✓ Normochromic means the hemoglobin concentration is normal.\n• Cell Size: The term cytic refers to the physical size of the RBC. Macrocytic, Normocytic, and Microcytic describe whether the cells are larger than normal, normal-sized, or smaller than normal. They do not classify hemoglobin content itself.","whyWrongChoices":"Alternative options: Macrocytic anemia, Normocytic anemia, Microcytic anemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following increases bmr, except::::sleeping', 'all of the following increases bmr, except:', 'Sleeping', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Basal Metabolic Rate (BMR) represents the minimum energy required to keep vital functions (like breathing and circulation) active. During sleep, your muscle activity drops, your heart rate slows down, and your body enters its lowest metabolic state, causing your energy expenditure to drop below awake basal levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sleeping\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Basal Metabolic Rate (BMR) represents the minimum energy required to keep vital functions (like breathing and circulation) active. During sleep, your muscle activity drops, your heart rate slows down, and your body enters its lowest metabolic state, causing your energy expenditure to drop below awake basal levels.","whyWrongChoices":"Alternative options: Thyroxine, Adrenaline, Stress hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are the domain of nutrition intervention, except::::none of the above', 'the following are the domain of nutrition intervention, except:', 'None of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The 4 Official Domains of Nutrition Intervention:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The 4 Official Domains of Nutrition Intervention:\n• Food and/or Nutrient Delivery (ND): Customized food, snacks, enteral/parenteral nutrition, supplements, or feeding assistance.\n• Nutrition Education (E): Formal process to instruct or train a patient in a nutrition-related skill or to provide knowledge.\n• Nutrition Counseling (C): A supportive process to guide collaborative goal-setting and behavior change.\n• Coordination of Nutrition Care (RC): Consulting with or referring to other healthcare providers, institutions, or agencies.","whyWrongChoices":"Alternative options: Food and nutrient delivery, Nutrition education, Coordination of nutrition care"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are the domain of nutrition intervention, except::::', 'the following are the domain of nutrition intervention, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The 4 Official Domains of Nutrition Intervention:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The 4 Official Domains of Nutrition Intervention:\n• Food and/or Nutrient Delivery (ND): Customized food, snacks, enteral/parenteral nutrition, supplements, or feeding assistance.\n• Nutrition Education (E): Formal process to instruct or train a patient in a nutrition-related skill or to provide knowledge.\n• Nutrition Counseling (C): A supportive process to guide collaborative goal-setting and behavior change.\n• Coordination of Nutrition Care (RC): Consulting with or referring to other healthcare providers, institutions, or agencies.","whyWrongChoices":"Alternative options: Food and nutrient delivery, Nutrition education, Coordination of nutrition care"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are the first line of immune system defense.:::skin and mucous membranes', 'these are the first line of immune system defense.', 'Skin and mucous membranes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Three Lines of Defense","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Skin and mucous membranes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Three Lines of Defense\n• First Line (Anatomical Barriers): Skin and mucous membranes form the primary physical and chemical shield of the innate immune system. They block pathogens mechanically from entering the body and secrete protective fluids (like sweat, tears, and gastric acid).\n• Second Line (Nonspecific Internal Defenses): If pathogens breach the physical barriers, granulocytes and macrophages, along with inflammatory responses and fever, act as the internal backup to destroy the invaders non-specifically.\n• Third Line (Adaptive Immunity): T lymphocytes and antibodies represent the highly targeted, specific adaptive immune system, which takes longer to activate but creates immunological memory.","whyWrongChoices":"Alternative options: GIT secretions, T lymphocytes and antibodies, Granulocytes and macrophages"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:these are the first line of immune system defense.:::', 'these are the first line of immune system defense.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Three Lines of Defense","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Skin and mucous membranes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Three Lines of Defense\n• First Line (Anatomical Barriers): Skin and mucous membranes form the primary physical and chemical shield of the innate immune system. They block pathogens mechanically from entering the body and secrete protective fluids (like sweat, tears, and gastric acid).\n• Second Line (Nonspecific Internal Defenses): If pathogens breach the physical barriers, granulocytes and macrophages, along with inflammatory responses and fever, act as the internal backup to destroy the invaders non-specifically.\n• Third Line (Adaptive Immunity): T lymphocytes and antibodies represent the highly targeted, specific adaptive immune system, which takes longer to activate but creates immunological memory.","whyWrongChoices":"Alternative options: GIT secretions, T lymphocytes and antibodies, Granulocytes and macrophages"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dextrose in pn provides this much calorie per gram.:::3 . 4 kcal/gram', 'dextrose in pn provides this much calorie per gram.', '3 . 4 kcal/gram', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In Parenteral Nutrition (PN), carbohydrates are delivered as dextrose monohydrate rather than pure anhydrous glucose. The attached water molecule adds weight but no calories, reducing its energy density from the standard dietary carbohydrate value of 4 kcal/g down to 3.4 kcal/gram.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3 . 4 kcal/gram\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In Parenteral Nutrition (PN), carbohydrates are delivered as dextrose monohydrate rather than pure anhydrous glucose. The attached water molecule adds weight but no calories, reducing its energy density from the standard dietary carbohydrate value of 4 kcal/g down to 3.4 kcal/gram.\n\nAmino Acids (Protein)\n• Energy Value: 4.0 kcal/gram\nIntravenous Lipid Emulsions (IVLE / Fats)\n• 10% Lipid Emulsion: Provides 1.1 kcal/mL\n• 20% Lipid Emulsion: Provides 2.0 kcal/mL\n• 30% Lipid Emulsion: Provides 3.0 kcal/mL (typically reserved for pharmacy compounding use only)","whyWrongChoices":"Alternative options: 4 kcal/gram, 2 kcal/gram, 3 kcal/gram"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dextrose in pn provides this much calorie per gram.:::', 'dextrose in pn provides this much calorie per gram.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In Parenteral Nutrition (PN), carbohydrates are delivered as dextrose monohydrate rather than pure anhydrous glucose. The attached water molecule adds weight but no calories, reducing its energy density from the standard dietary carbohydrate value of 4 kcal/g down to 3.4 kcal/gram.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3 . 4 kcal/gram\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In Parenteral Nutrition (PN), carbohydrates are delivered as dextrose monohydrate rather than pure anhydrous glucose. The attached water molecule adds weight but no calories, reducing its energy density from the standard dietary carbohydrate value of 4 kcal/g down to 3.4 kcal/gram.\n\nAmino Acids (Protein)\n• Energy Value: 4.0 kcal/gram\nIntravenous Lipid Emulsions (IVLE / Fats)\n• 10% Lipid Emulsion: Provides 1.1 kcal/mL\n• 20% Lipid Emulsion: Provides 2.0 kcal/mL\n• 30% Lipid Emulsion: Provides 3.0 kcal/mL (typically reserved for pharmacy compounding use only)","whyWrongChoices":"Alternative options: 4 kcal/gram, 2 kcal/gram, 3 kcal/gram"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is common cause of peptic ulcer?:::both a and b', 'which of the following is common cause of peptic ulcer?', 'Both a and b', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A peptic ulcer is an open sore or lesion that develops on the inner lining of the stomach (gastric ulcer) or the upper portion of the small intestine (duodenal ulcer). It occurs when the digestive tract''s protective mucous layer drops or when gastric acid production increases, allowing corrosive stomach juices to burn and erode the deeper underlying sub-mucosal tissue layers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both a and b\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A peptic ulcer is an open sore or lesion that develops on the inner lining of the stomach (gastric ulcer) or the upper portion of the small intestine (duodenal ulcer). It occurs when the digestive tract''s protective mucous layer drops or when gastric acid production increases, allowing corrosive stomach juices to burn and erode the deeper underlying sub-mucosal tissue layers.\n\nTogether, H. pylori infection and NSAID use account for nearly all cases of peptic ulcer disease:\n• H. pylori: This bacterium colonizes the protective mucous layer of the stomach and duodenum. It triggers chronic localized inflammation, weakening the lining and allowing corrosive stomach acid to eat away at the tissue.\n• Long-term use of NSAIDs: Non-steroidal anti-inflammatory drugs (like ibuprofen, naproxen, and aspirin) block the COX-1 enzyme. Because this enzyme is responsible for producing the protective prostaglandins that maintain the stomach''s mucosal barrier, blocking it leaves the lining vulnerable to acid erosion.","whyWrongChoices":"Alternative options: H. pylori, Long term use of non-steroidal anti-inflammatory drugs, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is common cause of peptic ulcer?:::', 'which of the following is common cause of peptic ulcer?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A peptic ulcer is an open sore or lesion that develops on the inner lining of the stomach (gastric ulcer) or the upper portion of the small intestine (duodenal ulcer). It occurs when the digestive tract''s protective mucous layer drops or when gastric acid production increases, allowing corrosive stomach juices to burn and erode the deeper underlying sub-mucosal tissue layers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both a and b\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A peptic ulcer is an open sore or lesion that develops on the inner lining of the stomach (gastric ulcer) or the upper portion of the small intestine (duodenal ulcer). It occurs when the digestive tract''s protective mucous layer drops or when gastric acid production increases, allowing corrosive stomach juices to burn and erode the deeper underlying sub-mucosal tissue layers.\n\nTogether, H. pylori infection and NSAID use account for nearly all cases of peptic ulcer disease:\n• H. pylori: This bacterium colonizes the protective mucous layer of the stomach and duodenum. It triggers chronic localized inflammation, weakening the lining and allowing corrosive stomach acid to eat away at the tissue.\n• Long-term use of NSAIDs: Non-steroidal anti-inflammatory drugs (like ibuprofen, naproxen, and aspirin) block the COX-1 enzyme. Because this enzyme is responsible for producing the protective prostaglandins that maintain the stomach''s mucosal barrier, blocking it leaves the lining vulnerable to acid erosion.","whyWrongChoices":"Alternative options: H. pylori, Long term use of non-steroidal anti-inflammatory drugs, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a nutrient essential in blood formation?:::vit a', 'which of the following is not a nutrient essential in blood formation?', 'Vit A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While Vitamin A supports immune health, cellular growth, and vision, it is not categorized as a primary, direct building block or regulator for hematopoiesis (blood cell production).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While Vitamin A supports immune health, cellular growth, and vision, it is not categorized as a primary, direct building block or regulator for hematopoiesis (blood cell production).\n\nWhy the Other Options are Essential\n• Protein: Red blood cells are heavily made of proteins. Globin (the protein portion of hemoglobin) requires a constant supply of dietary amino acids to synthesize new red blood cells.\n• Folic acid: This B-vitamin (Vitamin B9) is absolutely vital for DNA synthesis and normal cell division in the bone marrow. A deficiency directly causes macrocytic (megaloblastic) anemia.\n• Vit C: Vitamin C acts as a critical enhancer for iron absorption in the intestines. Since iron is the absolute core component needed to make hemoglobin, Vitamin C plays an essential indirect role in healthy blood formation.","whyWrongChoices":"Alternative options: Vit C, Protein, Folic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a nutrient essential in blood formation?:::', 'which of the following is not a nutrient essential in blood formation?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While Vitamin A supports immune health, cellular growth, and vision, it is not categorized as a primary, direct building block or regulator for hematopoiesis (blood cell production).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While Vitamin A supports immune health, cellular growth, and vision, it is not categorized as a primary, direct building block or regulator for hematopoiesis (blood cell production).\n\nWhy the Other Options are Essential\n• Protein: Red blood cells are heavily made of proteins. Globin (the protein portion of hemoglobin) requires a constant supply of dietary amino acids to synthesize new red blood cells.\n• Folic acid: This B-vitamin (Vitamin B9) is absolutely vital for DNA synthesis and normal cell division in the bone marrow. A deficiency directly causes macrocytic (megaloblastic) anemia.\n• Vit C: Vitamin C acts as a critical enhancer for iron absorption in the intestines. Since iron is the absolute core component needed to make hemoglobin, Vitamin C plays an essential indirect role in healthy blood formation.","whyWrongChoices":"Alternative options: Vit C, Protein, Folic acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is/are true about evaluating nutrient intake of individuals using ear and rda? i. if the intake is greater than rda, there is a high level of confidence that intake is adequate ii. if the intake is between the ear and the rda, the intake probably needs to be improved:::both statement are correct', 'which of the following is/are true about evaluating nutrient intake of individuals using ear and rda? i. if the intake is greater than rda, there is a high level of confidence that intake is adequate ii. if the intake is between the ear and the rda, the intake probably needs to be improved', 'Both statement are correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Statement I is correct: The Recommended Dietary Allowance (RDA) is calculated to meet the nutritional needs of nearly all (97% to 98%) healthy individuals in a specific life-stage and gender group. Therefore, if an individual''s chronic intake is monitored and found to be greater than the RDA, clinicians have a high level of confidence that their intake is entirely adequate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statement are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Statement I is correct: The Recommended Dietary Allowance (RDA) is calculated to meet the nutritional needs of nearly all (97% to 98%) healthy individuals in a specific life-stage and gender group. Therefore, if an individual''s chronic intake is monitored and found to be greater than the RDA, clinicians have a high level of confidence that their intake is entirely adequate.\n• Statement II is correct: The Estimated Average Requirement (EAR) is the intake level estimated to meet the needs of only 50% of healthy individuals. If an individual''s intake falls between the EAR and the RDA, there is high statistical uncertainty regarding its adequacy, and the probability of deficiency is anywhere from 3% to 50%. Because it does not meet the safety margin of the individual''s RDA target, the intake probably needs to be improved or increased.","whyWrongChoices":"Alternative options: Only I is correct, Only II is correct, Both statement are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to the study of interactions/interrelationship between an organism and their environment.:::', 'this refers to the study of interactions/interrelationship between an organism and their environment.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ecology of Food and Nutrition frames the complex relationship between humans, food, and their natural, social, and cultural environment.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ecology of food and nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ecology of Food and Nutrition frames the complex relationship between humans, food, and their natural, social, and cultural environment.","whyWrongChoices":"Alternative options: Food and nutrition system, Food Path, Food security"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is/are true about evaluating nutrient intake of individuals using ear and rda? i. if the intake is greater than rda, there is a high level of confidence that intake is adequate ii. if the intake is between the ear and the rda, the intake probably needs to be improved:::', 'which of the following is/are true about evaluating nutrient intake of individuals using ear and rda? i. if the intake is greater than rda, there is a high level of confidence that intake is adequate ii. if the intake is between the ear and the rda, the intake probably needs to be improved', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Statement I is correct: The Recommended Dietary Allowance (RDA) is calculated to meet the nutritional needs of nearly all (97% to 98%) healthy individuals in a specific life-stage and gender group. Therefore, if an individual''s chronic intake is monitored and found to be greater than the RDA, clinicians have a high level of confidence that their intake is entirely adequate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statement are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Statement I is correct: The Recommended Dietary Allowance (RDA) is calculated to meet the nutritional needs of nearly all (97% to 98%) healthy individuals in a specific life-stage and gender group. Therefore, if an individual''s chronic intake is monitored and found to be greater than the RDA, clinicians have a high level of confidence that their intake is entirely adequate.\n• Statement II is correct: The Estimated Average Requirement (EAR) is the intake level estimated to meet the needs of only 50% of healthy individuals. If an individual''s intake falls between the EAR and the RDA, there is high statistical uncertainty regarding its adequacy, and the probability of deficiency is anywhere from 3% to 50%. Because it does not meet the safety margin of the individual''s RDA target, the intake probably needs to be improved or increased.","whyWrongChoices":"Alternative options: Only I is correct, Only II is correct, Both statement are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary recommendation for colostomy::::low fiber', 'dietary recommendation for colostomy:', 'Low fiber', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Immediately following surgery and during the initial recovery phase (typically the first 6 to 8 weeks), patients are placed on a strict low-fiber diet. This recommendation focuses on protecting the intestinal tract as it heals:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Immediately following surgery and during the initial recovery phase (typically the first 6 to 8 weeks), patients are placed on a strict low-fiber diet. This recommendation focuses on protecting the intestinal tract as it heals:\n\n• Preventing Stoma Blockages: High-fiber foods (like whole grains, nuts, seeds, and raw fibrous vegetables) do not break down easily. They can form a physical mass that risks completely blocking the narrow stoma opening.\n• Reducing GI Distress: A low-fiber, bland diet minimizes intestinal swelling, limits excessive stoma output, and controls gas or severe cramping while the bowel normalizes.","whyWrongChoices":"Alternative options: High fiber, Vit B12 supplementation, Increased carbohydrate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dietary recommendation for colostomy::::', 'dietary recommendation for colostomy:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Immediately following surgery and during the initial recovery phase (typically the first 6 to 8 weeks), patients are placed on a strict low-fiber diet. This recommendation focuses on protecting the intestinal tract as it heals:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Immediately following surgery and during the initial recovery phase (typically the first 6 to 8 weeks), patients are placed on a strict low-fiber diet. This recommendation focuses on protecting the intestinal tract as it heals:\n\n• Preventing Stoma Blockages: High-fiber foods (like whole grains, nuts, seeds, and raw fibrous vegetables) do not break down easily. They can form a physical mass that risks completely blocking the narrow stoma opening.\n• Reducing GI Distress: A low-fiber, bland diet minimizes intestinal swelling, limits excessive stoma output, and controls gas or severe cramping while the bowel normalizes.","whyWrongChoices":"Alternative options: High fiber, Vit B12 supplementation, Increased carbohydrate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foods allowed in tyramine-restricted diet::::', 'foods allowed in tyramine-restricted diet:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A tyramine-restricted diet is commonly prescribed to individuals taking Monoamine Oxidase Inhibitors (MAOIs) to prevent a life-threatening hypertensive crisis. Tyramine builds up naturally in foods that are aged, fermented, cured, or smoked.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Some type of beans\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A tyramine-restricted diet is commonly prescribed to individuals taking Monoamine Oxidase Inhibitors (MAOIs) to prevent a life-threatening hypertensive crisis. Tyramine builds up naturally in foods that are aged, fermented, cured, or smoked.\n\nSome type of beans: While broad beans (like fava beans) contain high amounts of L-dopa/tyramine and must be strictly avoided, standard fresh or canned legumes (such as standard green beans, chickpeas, and lentils) are entirely safe and allowed on this diet.","whyWrongChoices":"Alternative options: Gouda cheese, Smoked ham, A and B only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diseases within the small intestine generally result in malabsorption because of the impaired function of the organ.:::true', 'diseases within the small intestine generally result in malabsorption because of the impaired function of the organ.', 'True', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The small intestine is the primary organ responsible for the chemical digestion and absorption of nutrients (such as carbohydrates, proteins, fats, vitamins, and minerals). It features specialized structural adaptations, namely villi and microvilli, which create a massive surface area for nutrient uptake.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"True\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The small intestine is the primary organ responsible for the chemical digestion and absorption of nutrients (such as carbohydrates, proteins, fats, vitamins, and minerals). It features specialized structural adaptations, namely villi and microvilli, which create a massive surface area for nutrient uptake.\n\nWhen a disease affects the small intestine (such as Celiac disease, Crohn''s disease, or Tropical sprue), it damages this delicate mucosal lining, blunts the villi, and causes widespread inflammation. This impaired structural function directly prevents the organ from absorbing nutrients effectively, leading to clinical malabsorption, nutrient deficiencies, weight loss, and chronic diarrhea.","whyWrongChoices":"Alternative options: False, Maybe, Depends"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:weight loss target for obese adults: i. 10% weight loss of total body weight over 6 months ii. dietary changes include an energy deficit of 500-1000 kcal/day iii. ter of 2000 kcal per day:::i and ii only', 'weight loss target for obese adults: i. 10% weight loss of total body weight over 6 months ii. dietary changes include an energy deficit of 500-1000 kcal/day iii. ter of 2000 kcal per day', 'I and II only', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Clinical guidelines for adult weight and obesity management establish specific, realistic milestones to ensure safety and long-term compliance:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I and II only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Clinical guidelines for adult weight and obesity management establish specific, realistic milestones to ensure safety and long-term compliance:\n• I. 10% weight loss of total body weight over 6 months: Major health organizations (such as the National Institutes of Health and the National Heart, Lung, and Blood Institute) define an initial target of reducing baseline body weight by 10% over a 6-month timeframe as the clinical standard. This pace is highly realistic and yields massive improvements in blood pressure, blood glucose, and lipid profiles.\n• II. Dietary changes include an energy deficit of 500-1000 kcal/day: To achieve a steady, sustainable weight loss of 1 to 2 pounds per week, the standard prescription is to introduce a daily caloric deficit of 500 to 1,000 kcal below the patient''s Total Daily Energy Expenditure (TDEE).","whyWrongChoices":"Alternative options: I only, II only, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:weight loss target for obese adults: i. 10% weight loss of total body weight over 6 months ii. dietary changes include an energy deficit of 500-1000 kcal/day iii. ter of 2000 kcal per day:::', 'weight loss target for obese adults: i. 10% weight loss of total body weight over 6 months ii. dietary changes include an energy deficit of 500-1000 kcal/day iii. ter of 2000 kcal per day', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Clinical guidelines for adult weight and obesity management establish specific, realistic milestones to ensure safety and long-term compliance:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I and II only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Clinical guidelines for adult weight and obesity management establish specific, realistic milestones to ensure safety and long-term compliance:\n• I. 10% weight loss of total body weight over 6 months: Major health organizations (such as the National Institutes of Health and the National Heart, Lung, and Blood Institute) define an initial target of reducing baseline body weight by 10% over a 6-month timeframe as the clinical standard. This pace is highly realistic and yields massive improvements in blood pressure, blood glucose, and lipid profiles.\n• II. Dietary changes include an energy deficit of 500-1000 kcal/day: To achieve a steady, sustainable weight loss of 1 to 2 pounds per week, the standard prescription is to introduce a daily caloric deficit of 500 to 1,000 kcal below the patient''s Total Daily Energy Expenditure (TDEE).","whyWrongChoices":"Alternative options: I only, II only, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the total fluid volume for blenderized feeding of 1900 kcal, 1.5:1 dilution?:::1267 ml', 'what is the total fluid volume for blenderized feeding of 1900 kcal, 1.5:1 dilution?', '1267 ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Total volume (ml) = 1900 kcal/1.5/ml = 1267ml","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1267 ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Total volume (ml) = 1900 kcal/1.5/ml = 1267ml","whyWrongChoices":"Alternative options: 1900 ml, 950 ml, 2850 ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
