INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the gradual thickening of the arteries of the walls due to the information of plaques.:::', 'the gradual thickening of the arteries of the walls due to the information of plaques.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Atherosclerosis (derived from the Greek words athere meaning gruel or paste, and sclerosis meaning hardness) is the precise medical term for the gradual thickening, narrowing, and hardening of the arterial walls due to the formation of fibrofatty plaques (atheromas).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Atherosclerosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Atherosclerosis (derived from the Greek words athere meaning gruel or paste, and sclerosis meaning hardness) is the precise medical term for the gradual thickening, narrowing, and hardening of the arterial walls due to the formation of fibrofatty plaques (atheromas).\n\nIt begins when the inner lining of an artery (the endothelium) is damaged by factors like high blood pressure or smoking. This triggers a chronic inflammatory response where low-density lipoproteins (LDL) accumulate, become oxidized, and are swallowed by immune cells to form \"foam cells.\" Over time, this mixture of cholesterol, cellular waste, and scar tissue calcifies into a rigid plaque that restricts blood flow.\n\n• Hypertension: High blood pressure. While it causes chronic mechanical stress that damages vessel walls and drastically accelerates plaque formation, it is a hemodynamic measurement rather than the physical plaque architecture itself.\n• Cerebrovascular accident (CVA): A stroke. This is a severe, acute clinical outcome or event that happens when a blood vessel supplying the brain either ruptures or becomes completely blocked by a piece of plaque that broke free.\n• Coronary heart disease (CHD): A specific structural disease category that refers to the narrowing of the blood vessels feeding the heart muscle. While CHD is almost exclusively caused by atherosclerosis, atherosclerosis is the overarching universal process that can happen in arteries anywhere in the body (such as the brain, legs, or kidneys) [0.1].","whyWrongChoices":"Alternative options: Hypertension, Coronary heart disease, Cerebrovascular accident"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.:::ipc', 'this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.', 'IPC', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"IPC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). \n\n• EWS refers to an Early Warning System, which focuses on early detection of deteriorating conditions. \n• OPT, Operation Timbang, is a child weighing activity, unrelated to food insecurity classification. \n• SFP, Supplementary Feeding Program, is an intervention, not a classification tool.","whyWrongChoices":"Alternative options: EWS, OPT, SFP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.:::', 'this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"IPC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). \n\n• EWS refers to an Early Warning System, which focuses on early detection of deteriorating conditions. \n• OPT, Operation Timbang, is a child weighing activity, unrelated to food insecurity classification. \n• SFP, Supplementary Feeding Program, is an intervention, not a classification tool.","whyWrongChoices":"Alternative options: EWS, OPT, SFP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.:::ews', 'this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.', 'EWS', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"EWS\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. \n\nEWS and IPC work together in practice, but EWS is specifically the local, trigger-based detection mechanism.","whyWrongChoices":"Alternative options: IPC, OPT, SFP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.:::', 'this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"EWS\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. \n\nEWS and IPC work together in practice, but EWS is specifically the local, trigger-based detection mechanism.","whyWrongChoices":"Alternative options: IPC, OPT, SFP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.:::pgn', 'aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.', 'PGN', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PGN\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.\n\n• AHMP (Accelerated Hunger-Mitigation Program) is the overarching mother program addressing hunger and food security.\n• IYCF (Infant and Young Child Feeding) represents the specific set of optimal guidelines and target behaviors (like exclusive breastfeeding and appropriate complementary feeding) that the PGN promotes to mothers and caregivers.","whyWrongChoices":"Alternative options: NGF, IYCF, AHMP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.:::', 'aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PGN\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.\n\n• AHMP (Accelerated Hunger-Mitigation Program) is the overarching mother program addressing hunger and food security.\n• IYCF (Infant and Young Child Feeding) represents the specific set of optimal guidelines and target behaviors (like exclusive breastfeeding and appropriate complementary feeding) that the PGN promotes to mothers and caregivers.","whyWrongChoices":"Alternative options: NGF, IYCF, AHMP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the primary purpose of nutrition survey in research?:::to determine the prevelance of specific nutrient deficiencies in a population', 'what is the primary purpose of nutrition survey in research?', 'To determine the prevelance of specific nutrient deficiencies in a population', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To determine the prevelance of specific nutrient deficiencies in a population\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.\n\nChoices A, C, and D describe purposes that a survey-type methodology could theoretically serve, but they are more specialized or unrelated to the core mission of nutrition surveys. Nutrition surveys generate the prevalence data that inform national policy and program planning.","whyWrongChoices":"Alternative options: To assess the effectiveness of a new weight loss drug, To compare the nutritional content of different brands of cereal, To evaluate the impact of a marketing campaign on consumer food choices"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the primary purpose of nutrition survey in research?:::', 'what is the primary purpose of nutrition survey in research?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To determine the prevelance of specific nutrient deficiencies in a population\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.\n\nChoices A, C, and D describe purposes that a survey-type methodology could theoretically serve, but they are more specialized or unrelated to the core mission of nutrition surveys. Nutrition surveys generate the prevalence data that inform national policy and program planning.","whyWrongChoices":"Alternative options: To assess the effectiveness of a new weight loss drug, To compare the nutritional content of different brands of cereal, To evaluate the impact of a marketing campaign on consumer food choices"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:when was the first nutrition survey released?:::', 'when was the first nutrition survey released?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The first nutrition survey results were released in 1910 during the American Regime, which primarily focused on investigating beriberi and its links to eating polished white rice.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1910\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The first nutrition survey results were released in 1910 during the American Regime, which primarily focused on investigating beriberi and its links to eating polished white rice.","whyWrongChoices":"Alternative options: 1920, 1930, 1940"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following conditions accounts for the most non-communicable disease worldwide?:::cardiovascular disease', 'which of the following conditions accounts for the most non-communicable disease worldwide?', 'Cardiovascular disease', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cardiovascular disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.\n\nAmong these conditions, cardiovascular diseases (CVDs) are the absolute leading cause of mortality and morbidity globally:\n• Cardiovascular Diseases (CVDs): Account for the vast majority of NCD deaths, causing roughly 17.9 to 19 million deaths annually (primarily driven by ischemic heart disease and strokes).\n• Cancers: Follow as the second largest group, accounting for around 9 to 10 million deaths each year.\n• Chronic Respiratory Diseases: Account for approximately 3.9 to 4 million annual deaths.\n• Diabetes: Accounts for roughly 1.6 to 2 million deaths annually.\n\nTogether, these four groups make up over 80% of all premature NCD-related mortality worldwide.","whyWrongChoices":"Alternative options: Breast cancer, Diabetes, Respiratory disease"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to:::a large majority of individual in a particular age or gender group', 'the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to', 'A large majority of individual in a particular age or gender group', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A large majority of individual in a particular age or gender group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.\n\nEstimated Average Requirement (EAR), which is set at the median requirement covering only half of a group, not the UL. The UL is therefore a ceiling for safe habitual intake and not a recommended target intake.","whyWrongChoices":"Alternative options: Half the individuals in a particular age or gender group, Everyone in a particular age or gender group, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to:::', 'the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A large majority of individual in a particular age or gender group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.\n\nEstimated Average Requirement (EAR), which is set at the median requirement covering only half of a group, not the UL. The UL is therefore a ceiling for safe habitual intake and not a recommended target intake.","whyWrongChoices":"Alternative options: Half the individuals in a particular age or gender group, Everyone in a particular age or gender group, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:based on the acceptable macronutrient distribution ranges (amdr), energy from fat as a percentage of total energy for adults should be within the range?:::15-30%', 'based on the acceptable macronutrient distribution ranges (amdr), energy from fat as a percentage of total energy for adults should be within the range?', '15-30%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"15-30%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.\n\nCarbohydrate: 55-75%\nProtein: 10-15%\nFat: 15-30%","whyWrongChoices":"Alternative options: <10%, 10-20%, 35-50%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:based on the acceptable macronutrient distribution ranges (amdr), energy from fat as a percentage of total energy for adults should be within the range?:::', 'based on the acceptable macronutrient distribution ranges (amdr), energy from fat as a percentage of total energy for adults should be within the range?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"15-30%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.\n\nCarbohydrate: 55-75%\nProtein: 10-15%\nFat: 15-30%","whyWrongChoices":"Alternative options: <10%, 10-20%, 35-50%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which one of the following statements is incorrect?:::according to pinggang pinoy, meat, fish, and alternatives should comprise one-third of the plate', 'which one of the following statements is incorrect?', 'According to Pinggang Pinoy, meat, fish, and alternatives should comprise one-third of the plate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Answer should be 1/6 ~ 17%.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"According to Pinggang Pinoy, meat, fish, and alternatives should comprise one-third of the plate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Answer should be 1/6 ~ 17%.","whyWrongChoices":"Alternative options: According to Pinggang Pinoy, half of our plate should be include fruits and vegetable, The statement \"Eat lots of fruits and vegetables\" is a food-based dietary guideline, The statement \"Eat less sodium-no more than 2g/day\" is not food-based dietary guideline"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following conditions accounts for the most non-communicable disease worldwide?:::', 'which of the following conditions accounts for the most non-communicable disease worldwide?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cardiovascular disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.\n\nAmong these conditions, cardiovascular diseases (CVDs) are the absolute leading cause of mortality and morbidity globally:\n• Cardiovascular Diseases (CVDs): Account for the vast majority of NCD deaths, causing roughly 17.9 to 19 million deaths annually (primarily driven by ischemic heart disease and strokes).\n• Cancers: Follow as the second largest group, accounting for around 9 to 10 million deaths each year.\n• Chronic Respiratory Diseases: Account for approximately 3.9 to 4 million annual deaths.\n• Diabetes: Accounts for roughly 1.6 to 2 million deaths annually.\n\nTogether, these four groups make up over 80% of all premature NCD-related mortality worldwide.","whyWrongChoices":"Alternative options: Breast cancer, Diabetes, Respiratory disease"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the nutriskwela community radio network partners named their stations with words starting with this letter.:::k', 'the nutriskwela community radio network partners named their stations with words starting with this letter.', 'K', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is the letter K, reflecting the “ka-“ branding convention used across Nutriskwela community radio stations established by the NNC.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"K\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is the letter K, reflecting the “ka-“ branding convention used across Nutriskwela community radio stations established by the NNC.","whyWrongChoices":"Alternative options: C, N, M"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the nutriskwela community radio network partners named their stations with words starting with this letter.:::', 'the nutriskwela community radio network partners named their stations with words starting with this letter.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is the letter K, reflecting the “ka-“ branding convention used across Nutriskwela community radio stations established by the NNC.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"K\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is the letter K, reflecting the “ka-“ branding convention used across Nutriskwela community radio stations established by the NNC.","whyWrongChoices":"Alternative options: C, N, M"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in preparing for program planning and management, the first step is::::identifications/mobilization of lnc or planning core group', 'in preparing for program planning and management, the first step is:', 'Identifications/mobilization of LNC or planning core group', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Establishing the group responsible for leading the planning process is the necessary first step before any assessment, goal-setting, or plan preparation can occur. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Identifications/mobilization of LNC or planning core group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Establishing the group responsible for leading the planning process is the necessary first step before any assessment, goal-setting, or plan preparation can occur. \n\nAssessment or diagnostic analysis, setting goals and objectives, and preparing the plan of operation are all important subsequent steps, but they require an organized planning group to already be in place to carry them out.","whyWrongChoices":"Alternative options: Assessment or Diagnostic Analysis, Setting of goals and objectives, Preparation of plan of operation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:re-planning is a necessary step in nutrition program planning and management. in doing so, the following are revisited::::all of the above', 're-planning is a necessary step in nutrition program planning and management. in doing so, the following are revisited:', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-planning revisits the nutrition situation, the goals and objectives, and the strategies for targeting and implementing interventions together. Re-planning is triggered by monitoring and evaluation findings that suggest the current approach needs adjustment, and effective re-planning requires reassessing the full planning cycle.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-planning revisits the nutrition situation, the goals and objectives, and the strategies for targeting and implementing interventions together. Re-planning is triggered by monitoring and evaluation findings that suggest the current approach needs adjustment, and effective re-planning requires reassessing the full planning cycle.","whyWrongChoices":"Alternative options: Nutrition situation, Goals and objectives, Strategies in targeting for and implementation of nutrition interventions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:re-planning is a necessary step in nutrition program planning and management. in doing so, the following are revisited::::', 're-planning is a necessary step in nutrition program planning and management. in doing so, the following are revisited:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-planning revisits the nutrition situation, the goals and objectives, and the strategies for targeting and implementing interventions together. Re-planning is triggered by monitoring and evaluation findings that suggest the current approach needs adjustment, and effective re-planning requires reassessing the full planning cycle.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-planning revisits the nutrition situation, the goals and objectives, and the strategies for targeting and implementing interventions together. Re-planning is triggered by monitoring and evaluation findings that suggest the current approach needs adjustment, and effective re-planning requires reassessing the full planning cycle.","whyWrongChoices":"Alternative options: Nutrition situation, Goals and objectives, Strategies in targeting for and implementation of nutrition interventions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in nutritional assessment, causes of malnutrition must be classified into immediate, underlying and basic causes. food insecurity and poor child care are classified as::::underlying causes', 'in nutritional assessment, causes of malnutrition must be classified into immediate, underlying and basic causes. food insecurity and poor child care are classified as:', 'Underlying causes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Underlying causes – contributing causes; food security, health services, practices","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Underlying causes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Underlying causes – contributing causes; food security, health services, practices\n\n• Immediate causes – direct causes; food and care (individual level)\n• Basic causes – societal; political, economic, education etc.\n• Cross-cutting causes","whyWrongChoices":"Alternative options: Immediate causes, Basic cause, Cross-cutting causes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in nutritional assessment, causes of malnutrition must be classified into immediate, underlying and basic causes. food insecurity and poor child care are classified as::::', 'in nutritional assessment, causes of malnutrition must be classified into immediate, underlying and basic causes. food insecurity and poor child care are classified as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Underlying causes – contributing causes; food security, health services, practices","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Underlying causes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Underlying causes – contributing causes; food security, health services, practices\n\n• Immediate causes – direct causes; food and care (individual level)\n• Basic causes – societal; political, economic, education etc.\n• Cross-cutting causes","whyWrongChoices":"Alternative options: Immediate causes, Basic cause, Cross-cutting causes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:key decisions for implementation of nutrition programs/projects/activities such as continue with or without modification; stop the implementation; replace with new interventiion are done in what phase/step of program management?:::re-planning', 'key decisions for implementation of nutrition programs/projects/activities such as continue with or without modification; stop the implementation; replace with new interventiion are done in what phase/step of program management?', 'Re-planning', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-planning is a specific decision types (continue, modify, stop, or replace an intervention) made once monitoring and evaluation data reveal how a program is performing. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Re-planning\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-planning is a specific decision types (continue, modify, stop, or replace an intervention) made once monitoring and evaluation data reveal how a program is performing. \n\n• Assessment and plan preparation occurs before implementation and does not involve adjusting an ongoing program. \n• Implementation is the execution phase itself. \n• Monitoring and evaluation generates the data that informs these decisions but is technically the data-gathering step preceding the actual re-planning decision-making.","whyWrongChoices":"Alternative options: Assessment and plan preparation, Implementation, Monitoring and Evaluation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:key decisions for implementation of nutrition programs/projects/activities such as continue with or without modification; stop the implementation; replace with new interventiion are done in what phase/step of program management?:::', 'key decisions for implementation of nutrition programs/projects/activities such as continue with or without modification; stop the implementation; replace with new interventiion are done in what phase/step of program management?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-planning is a specific decision types (continue, modify, stop, or replace an intervention) made once monitoring and evaluation data reveal how a program is performing. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Re-planning\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-planning is a specific decision types (continue, modify, stop, or replace an intervention) made once monitoring and evaluation data reveal how a program is performing. \n\n• Assessment and plan preparation occurs before implementation and does not involve adjusting an ongoing program. \n• Implementation is the execution phase itself. \n• Monitoring and evaluation generates the data that informs these decisions but is technically the data-gathering step preceding the actual re-planning decision-making.","whyWrongChoices":"Alternative options: Assessment and plan preparation, Implementation, Monitoring and Evaluation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this serves as complementary activity in making the implementation of most of the nutrition interventions effective.:::nutrition education', 'this serves as complementary activity in making the implementation of most of the nutrition interventions effective.', 'Nutrition Education', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition Education functions as a cross-cutting, complementary activity that enhances the effectiveness of virtually all other nutrition interventions by ensuring beneficiaries understand and can sustain the benefits of programs like feeding, fortification, or livelihood support. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition Education\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition Education functions as a cross-cutting, complementary activity that enhances the effectiveness of virtually all other nutrition interventions by ensuring beneficiaries understand and can sustain the benefits of programs like feeding, fortification, or livelihood support. \n\nLivelihood Assistance, Home/School/Community Food Production, and Supplementary Feeding are specific, standalone interventions.","whyWrongChoices":"Alternative options: Livelihood Assistance, Home, School, and Community Food Production, Supplementary Feeding"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this serves as complementary activity in making the implementation of most of the nutrition interventions effective.:::', 'this serves as complementary activity in making the implementation of most of the nutrition interventions effective.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition Education functions as a cross-cutting, complementary activity that enhances the effectiveness of virtually all other nutrition interventions by ensuring beneficiaries understand and can sustain the benefits of programs like feeding, fortification, or livelihood support. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition Education\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition Education functions as a cross-cutting, complementary activity that enhances the effectiveness of virtually all other nutrition interventions by ensuring beneficiaries understand and can sustain the benefits of programs like feeding, fortification, or livelihood support. \n\nLivelihood Assistance, Home/School/Community Food Production, and Supplementary Feeding are specific, standalone interventions.","whyWrongChoices":"Alternative options: Livelihood Assistance, Home, School, and Community Food Production, Supplementary Feeding"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sustainability implies food system practices that respect and protect the ecosystems. it is recognized as an important aspect of ensuring the right to food.:::both statements are true', 'sustainability implies food system practices that respect and protect the ecosystems. it is recognized as an important aspect of ensuring the right to food.', 'Both statements are true', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Statement 1 is true: According to the Food and Agriculture Organization (FAO), environmental sustainability in a food system is determined by ensuring that the impacts of production, processing, and distribution on the surrounding natural environment are neutral or positive. It explicitly demands the respect and protection of ecosystems by safeguarding biodiversity, water, soil, and minimizing the carbon footprint.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are true\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Statement 1 is true: According to the Food and Agriculture Organization (FAO), environmental sustainability in a food system is determined by ensuring that the impacts of production, processing, and distribution on the surrounding natural environment are neutral or positive. It explicitly demands the respect and protection of ecosystems by safeguarding biodiversity, water, soil, and minimizing the carbon footprint.\n\n• Statement 2 is true: The \"Right to Food\" is a formalized human right, and the United Nations recognizes that this right cannot be realized long-term without sustainable practices. If today''s food systems destroy ecosystems, deplete freshwater, and accelerate the climate crisis, they compromise the global capacity to feed future generations, thereby violating the progressive realization of the right to food.","whyWrongChoices":"Alternative options: Only the first statement is true, Only the second statement is true, Both statements are false"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sustainability implies food system practices that respect and protect the ecosystems. it is recognized as an important aspect of ensuring the right to food.:::', 'sustainability implies food system practices that respect and protect the ecosystems. it is recognized as an important aspect of ensuring the right to food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Statement 1 is true: According to the Food and Agriculture Organization (FAO), environmental sustainability in a food system is determined by ensuring that the impacts of production, processing, and distribution on the surrounding natural environment are neutral or positive. It explicitly demands the respect and protection of ecosystems by safeguarding biodiversity, water, soil, and minimizing the carbon footprint.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are true\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Statement 1 is true: According to the Food and Agriculture Organization (FAO), environmental sustainability in a food system is determined by ensuring that the impacts of production, processing, and distribution on the surrounding natural environment are neutral or positive. It explicitly demands the respect and protection of ecosystems by safeguarding biodiversity, water, soil, and minimizing the carbon footprint.\n\n• Statement 2 is true: The \"Right to Food\" is a formalized human right, and the United Nations recognizes that this right cannot be realized long-term without sustainable practices. If today''s food systems destroy ecosystems, deplete freshwater, and accelerate the climate crisis, they compromise the global capacity to feed future generations, thereby violating the progressive realization of the right to food.","whyWrongChoices":"Alternative options: Only the first statement is true, Only the second statement is true, Both statements are false"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it underpins all other food security dimensions by emphasizing the capacity of individuals and groups to engage in decision and policy making processes.:::agency', 'it underpins all other food security dimensions by emphasizing the capacity of individuals and groups to engage in decision and policy making processes.', 'Agency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Agency is the power to make decisions and act on one''s own behalf (e.g., choosing what to eat).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Agency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Agency is the power to make decisions and act on one''s own behalf (e.g., choosing what to eat).\n\n• Accessibility - ability to get or afford the resources (e.g., food, services, markets).\n• Utilization - ability to properly use the resources to achieve good health (e.g., hygiene, knowledge).\n• Sustainability - ensuring the benefits continue after external support is withdrawn (long-term resilience).","whyWrongChoices":"Alternative options: Accessibility, Utilization, Sustainability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it underpins all other food security dimensions by emphasizing the capacity of individuals and groups to engage in decision and policy making processes.:::', 'it underpins all other food security dimensions by emphasizing the capacity of individuals and groups to engage in decision and policy making processes.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Agency is the power to make decisions and act on one''s own behalf (e.g., choosing what to eat).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Agency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Agency is the power to make decisions and act on one''s own behalf (e.g., choosing what to eat).\n\n• Accessibility - ability to get or afford the resources (e.g., food, services, markets).\n• Utilization - ability to properly use the resources to achieve good health (e.g., hygiene, knowledge).\n• Sustainability - ensuring the benefits continue after external support is withdrawn (long-term resilience).","whyWrongChoices":"Alternative options: Accessibility, Utilization, Sustainability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this includes the personal and financial capacity to acquire adequate food to satisfy basic needs.:::accessibility', 'this includes the personal and financial capacity to acquire adequate food to satisfy basic needs.', 'Accessibility', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Accessibility is the ability to get or afford the resources (e.g., food, services, markets).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Accessibility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Accessibility is the ability to get or afford the resources (e.g., food, services, markets).\n\n• Availability - physical presence of food\n• Nutrition security - consistent access, affordability, and utilization of diverse, safe, and nutritious food to ensure a healthy life.\n• Economic security - stable income, resources, and access to work that guarantees a basic standard of living and protects against shocks.","whyWrongChoices":"Alternative options: Availability, Nutrition security, Economic security"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this includes the personal and financial capacity to acquire adequate food to satisfy basic needs.:::', 'this includes the personal and financial capacity to acquire adequate food to satisfy basic needs.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Accessibility is the ability to get or afford the resources (e.g., food, services, markets).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Accessibility\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Accessibility is the ability to get or afford the resources (e.g., food, services, markets).\n\n• Availability - physical presence of food\n• Nutrition security - consistent access, affordability, and utilization of diverse, safe, and nutritious food to ensure a healthy life.\n• Economic security - stable income, resources, and access to work that guarantees a basic standard of living and protects against shocks.","whyWrongChoices":"Alternative options: Availability, Nutrition security, Economic security"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the primary purpose of nutritional monitoring within a surveillance system?:::to track changes in nutritional status over time within a population', 'what is the primary purpose of nutritional monitoring within a surveillance system?', 'To track changes in nutritional status over time within a population', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To track changes in nutritional status over time within a population is the defining purpose of the \"monitoring\" function within a broader surveillance system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To track changes in nutritional status over time within a population\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To track changes in nutritional status over time within a population is the defining purpose of the \"monitoring\" function within a broader surveillance system.","whyWrongChoices":"Alternative options: To diagnose individual cases of malnutrition, To determine the optimal dietary intake for individuals, To provide immediate nutritional interventions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the primary purpose of nutritional monitoring within a surveillance system?:::', 'what is the primary purpose of nutritional monitoring within a surveillance system?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To track changes in nutritional status over time within a population is the defining purpose of the \"monitoring\" function within a broader surveillance system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To track changes in nutritional status over time within a population\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To track changes in nutritional status over time within a population is the defining purpose of the \"monitoring\" function within a broader surveillance system.","whyWrongChoices":"Alternative options: To diagnose individual cases of malnutrition, To determine the optimal dietary intake for individuals, To provide immediate nutritional interventions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in a rural community, a nutritionist identifies a high prevalence of iron-deficiency anemia among women of childbearing age. the community has a strong agricultural tradition and relies heavily on local produce of whole grains and legumes, but the soil lacks bioavailable iron. a pilot program introduces a new iron-fortified flour, but a year later, the anemia rates have not significantly improved. applying the principles of community nutrition, what is the most plausible reason for the program''s failure?:::the intervention failed to account for potential food-food interactions, as the community''s diet is high in phytates, which inhibit iron absorption.', 'in a rural community, a nutritionist identifies a high prevalence of iron-deficiency anemia among women of childbearing age. the community has a strong agricultural tradition and relies heavily on local produce of whole grains and legumes, but the soil lacks bioavailable iron. a pilot program introduces a new iron-fortified flour, but a year later, the anemia rates have not significantly improved. applying the principles of community nutrition, what is the most plausible reason for the program''s failure?', 'The intervention failed to account for potential food-food interactions, as the community''s diet is high in phytates, which inhibit iron absorption.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that the intervention failed to account for food-food interactions, since the community''s diet is high in phytates (found abundantly in whole grains and legumes), which are well-known potent inhibitors of non-heme iron absorption, potentially neutralizing much of the benefit of the iron fortification.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The intervention failed to account for potential food-food interactions, as the community''s diet is high in phytates, which inhibit iron absorption.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that the intervention failed to account for food-food interactions, since the community''s diet is high in phytates (found abundantly in whole grains and legumes), which are well-known potent inhibitors of non-heme iron absorption, potentially neutralizing much of the benefit of the iron fortification.","whyWrongChoices":"Alternative options: The program did not employ a randomized controlled trial, making it impossible to accurately measure its impact on the target population., The nutritionist did not adequately engage local political leaders, resulting in a lack of policy support for the program''s long-term sustainability., The intervention was not tailored to the individual health needs of each participant, failing to address unique comorbidities that might interfere with iron absorption."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutritional deficiency is usually initiated by ?:::inadequate dietary intake of one or more nutrients', 'nutritional deficiency is usually initiated by ?', 'Inadequate dietary intake of one or more nutrients', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the 1st stage, based on schema of the development of nutritional deficiency. This stage precedes any measurable biochemical, functional, or clinical change in the body. Illness and low income are underlying or basic causes that may contribute to inadequate intake but are not themselves the initiating physiological event. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inadequate dietary intake of one or more nutrients\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the 1st stage, based on schema of the development of nutritional deficiency. This stage precedes any measurable biochemical, functional, or clinical change in the body. Illness and low income are underlying or basic causes that may contribute to inadequate intake but are not themselves the initiating physiological event. \n\nThe sequence generally progresses from dietary inadequacy to depleted tissue stores, then biochemical changes, and finally clinical signs.","whyWrongChoices":"Alternative options: Illness, Low income, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutritional deficiency is usually initiated by ?:::', 'nutritional deficiency is usually initiated by ?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This is the 1st stage, based on schema of the development of nutritional deficiency. This stage precedes any measurable biochemical, functional, or clinical change in the body. Illness and low income are underlying or basic causes that may contribute to inadequate intake but are not themselves the initiating physiological event. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inadequate dietary intake of one or more nutrients\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This is the 1st stage, based on schema of the development of nutritional deficiency. This stage precedes any measurable biochemical, functional, or clinical change in the body. Illness and low income are underlying or basic causes that may contribute to inadequate intake but are not themselves the initiating physiological event. \n\nThe sequence generally progresses from dietary inadequacy to depleted tissue stores, then biochemical changes, and finally clinical signs.","whyWrongChoices":"Alternative options: Illness, Low income, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:following the stages of developing nutrient deficiency, what is the appropriate method for the first stage?:::dietary', 'following the stages of developing nutrient deficiency, what is the appropriate method for the first stage?', 'Dietary', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is dietary assessment because the first stage of deficiency is inadequate dietary intake, and only dietary methods (recalls, records, FFQs) can directly capture what and how much a person is eating. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dietary\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is dietary assessment because the first stage of deficiency is inadequate dietary intake, and only dietary methods (recalls, records, FFQs) can directly capture what and how much a person is eating. \n\n• Anthropometry reflects later effects on body size and composition, appearing only after prolonged deficiency. \n• Clinical assessment detects obvious signs and symptoms, which appear latest in the sequence. \n• Biochemical assessment detects depleted nutrient stores or altered biomarkers, a stage that occurs after dietary inadequacy but before clinical signs. Matching the assessment method to the stage of deficiency ensures problems are caught as early as possible.","whyWrongChoices":"Alternative options: Anthropometry, Clinical, Biochemical"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:following the stages of developing nutrient deficiency, what is the appropriate method for the first stage?:::', 'following the stages of developing nutrient deficiency, what is the appropriate method for the first stage?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is dietary assessment because the first stage of deficiency is inadequate dietary intake, and only dietary methods (recalls, records, FFQs) can directly capture what and how much a person is eating. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dietary\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is dietary assessment because the first stage of deficiency is inadequate dietary intake, and only dietary methods (recalls, records, FFQs) can directly capture what and how much a person is eating. \n\n• Anthropometry reflects later effects on body size and composition, appearing only after prolonged deficiency. \n• Clinical assessment detects obvious signs and symptoms, which appear latest in the sequence. \n• Biochemical assessment detects depleted nutrient stores or altered biomarkers, a stage that occurs after dietary inadequacy but before clinical signs. Matching the assessment method to the stage of deficiency ensures problems are caught as early as possible.","whyWrongChoices":"Alternative options: Anthropometry, Clinical, Biochemical"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:include factors that influence health: biological, chemical, physical, social, cultural, economic, genetic, and behavioral:::determinants', 'include factors that influence health: biological, chemical, physical, social, cultural, economic, genetic, and behavioral', 'Determinants', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Determinants is the standard epidemiological term for factors that influence the frequency and distribution of health-related states. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Determinants\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Determinants is the standard epidemiological term for factors that influence the frequency and distribution of health-related states. \n\n• Distribution refers to how disease or health outcomes are spread across person, place, and time, not the causal factors themselves.\n• \"Health-related states and events\" refers to the outcomes being studied, not their causes. \n• \"Application\" is unrelated to this definition.","whyWrongChoices":"Alternative options: Distribution, Health-related states and events, Application"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:include factors that influence health: biological, chemical, physical, social, cultural, economic, genetic, and behavioral:::', 'include factors that influence health: biological, chemical, physical, social, cultural, economic, genetic, and behavioral', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Determinants is the standard epidemiological term for factors that influence the frequency and distribution of health-related states. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Determinants\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Determinants is the standard epidemiological term for factors that influence the frequency and distribution of health-related states. \n\n• Distribution refers to how disease or health outcomes are spread across person, place, and time, not the causal factors themselves.\n• \"Health-related states and events\" refers to the outcomes being studied, not their causes. \n• \"Application\" is unrelated to this definition.","whyWrongChoices":"Alternative options: Distribution, Health-related states and events, Application"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the theoretical or conceptual framework for the research defines the boundaries of your problem; and is used to develop a perspective in which the factual and conceptual elements become interconnected into a logical structure of relationships. which one of the following is false?:::in formulating conceptual framework, you may look at the various theories upon which you can base your study', 'the theoretical or conceptual framework for the research defines the boundaries of your problem; and is used to develop a perspective in which the factual and conceptual elements become interconnected into a logical structure of relationships. which one of the following is false?', 'In formulating conceptual framework, you may look at the various theories upon which you can base your study', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The false statement is D; in constructing a conceptual framework, the researcher draws upon related studies and existing theories, so the missing element is \"related studies,\"","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"In formulating conceptual framework, you may look at the various theories upon which you can base your study\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The false statement is D; in constructing a conceptual framework, the researcher draws upon related studies and existing theories, so the missing element is \"related studies,\"\n\n• Choice A is true because both frameworks are built from facts and explanations grounded in existing knowledge of the problem. \n• Choice B is true because the theoretical framework specifically presents the theory underpinning the research problem. \n• Choice C is true because the conceptual framework maps out relationships among the specific concepts/variables under study.","whyWrongChoices":"Alternative options: Both theoretical and conceptual frameworks consist of facts and explanation which proceed from the understanding on the knowledge about a problem, Theoretical framework presents the theory from which your research problem was derived, In the conceptual framework you present the relationship between the specific concepts for study"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the theoretical or conceptual framework for the research defines the boundaries of your problem; and is used to develop a perspective in which the factual and conceptual elements become interconnected into a logical structure of relationships. which one of the following is false?:::', 'the theoretical or conceptual framework for the research defines the boundaries of your problem; and is used to develop a perspective in which the factual and conceptual elements become interconnected into a logical structure of relationships. which one of the following is false?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The false statement is D; in constructing a conceptual framework, the researcher draws upon related studies and existing theories, so the missing element is \"related studies,\"","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"In formulating conceptual framework, you may look at the various theories upon which you can base your study\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The false statement is D; in constructing a conceptual framework, the researcher draws upon related studies and existing theories, so the missing element is \"related studies,\"\n\n• Choice A is true because both frameworks are built from facts and explanations grounded in existing knowledge of the problem. \n• Choice B is true because the theoretical framework specifically presents the theory underpinning the research problem. \n• Choice C is true because the conceptual framework maps out relationships among the specific concepts/variables under study.","whyWrongChoices":"Alternative options: Both theoretical and conceptual frameworks consist of facts and explanation which proceed from the understanding on the knowledge about a problem, Theoretical framework presents the theory from which your research problem was derived, In the conceptual framework you present the relationship between the specific concepts for study"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:research design should be accurate. this means::::strive to be definite, precise, and exact', 'research design should be accurate. this means:', 'Strive to be definite, precise, and exact', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In research methodology and design, distinct terms specify the standard requirements for a study''s framework:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Strive to be definite, precise, and exact\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In research methodology and design, distinct terms specify the standard requirements for a study''s framework:\n\n• Accurate: Means that the researcher must strive to be definite, precise, and exact with their parameters, measurements, and data representation to avoid errors.\n• Objective: This corresponds to option A (Unbiased, unprejudiced, detached, impersonal). It ensures the findings are guided by empirical data rather than personal opinions or emotions.\n• Analytical: This describes option B, focusing on breaking down complex subjects into their individual, fundamental parts to comprehend them comprehensively.","whyWrongChoices":"Alternative options: Unbiased, unprejudiced, detached, impersonal, There are relatively agreed-upon defined traits or boundaries which specify what kind of things or boundaries you study, Concerned with the identification and study of the component parts or elements which make up the things which you study"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the 3rs are principle of good science designed by scientist to improve animal welfare and scientific accuracy. which of the following means finding ways of making animals'' lives better in labs, this can include toys for animals or better training for technicians.:::refinement', 'the 3rs are principle of good science designed by scientist to improve animal welfare and scientific accuracy. which of the following means finding ways of making animals'' lives better in labs, this can include toys for animals or better training for technicians.', 'Refinement', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Refinement - Minimize animal pain, suffering, and distress.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Refinement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Refinement - Minimize animal pain, suffering, and distress.\n\n• Reduction - Use the minimum number of animals necessary.\n• Replacement - Use non-animal methods where possible.\n• Recognition - random word which start with letter R.","whyWrongChoices":"Alternative options: Reduction, Replacement, Recognition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:research design should be accurate. this means::::', 'research design should be accurate. this means:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In research methodology and design, distinct terms specify the standard requirements for a study''s framework:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Strive to be definite, precise, and exact\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In research methodology and design, distinct terms specify the standard requirements for a study''s framework:\n\n• Accurate: Means that the researcher must strive to be definite, precise, and exact with their parameters, measurements, and data representation to avoid errors.\n• Objective: This corresponds to option A (Unbiased, unprejudiced, detached, impersonal). It ensures the findings are guided by empirical data rather than personal opinions or emotions.\n• Analytical: This describes option B, focusing on breaking down complex subjects into their individual, fundamental parts to comprehend them comprehensively.","whyWrongChoices":"Alternative options: Unbiased, unprejudiced, detached, impersonal, There are relatively agreed-upon defined traits or boundaries which specify what kind of things or boundaries you study, Concerned with the identification and study of the component parts or elements which make up the things which you study"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which type of objective is the most applicable if your study uses methodology research design?:::to evaluate measuring instrument', 'which type of objective is the most applicable if your study uses methodology research design?', 'To evaluate measuring instrument', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In research methodology textbooks, a methodological research design (sometimes called methodological research) does not focus on investigating a substantive medical or social phenomenon itself. Instead, its primary purpose is the controlled development, testing, and validation of the research tools themselves.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To evaluate measuring instrument\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In research methodology textbooks, a methodological research design (sometimes called methodological research) does not focus on investigating a substantive medical or social phenomenon itself. Instead, its primary purpose is the controlled development, testing, and validation of the research tools themselves.\n\nThe Goal of Methodological Design is to target the validation or evaluation of a measuring instrument, scale, survey tool, or clinical questionnaire to ensure it possesses high validity and reliability before it is deployed in field studies.\n\n\t• To explore relationship: Best fits a correlational or explanatory research design.\n\t• To make comparison between groups: Best fits an experimental, quasi-experimental, or comparative research design.\n\t• To describe population or certain phenomena: Best fits a classic descriptive or observational research design.","whyWrongChoices":"Alternative options: To describe population or certain phenomena, To explore relationship, To make comparison between groups"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which type of objective is the most applicable if your study uses methodology research design?:::', 'which type of objective is the most applicable if your study uses methodology research design?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In research methodology textbooks, a methodological research design (sometimes called methodological research) does not focus on investigating a substantive medical or social phenomenon itself. Instead, its primary purpose is the controlled development, testing, and validation of the research tools themselves.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To evaluate measuring instrument\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In research methodology textbooks, a methodological research design (sometimes called methodological research) does not focus on investigating a substantive medical or social phenomenon itself. Instead, its primary purpose is the controlled development, testing, and validation of the research tools themselves.\n\nThe Goal of Methodological Design is to target the validation or evaluation of a measuring instrument, scale, survey tool, or clinical questionnaire to ensure it possesses high validity and reliability before it is deployed in field studies.\n\n\t• To explore relationship: Best fits a correlational or explanatory research design.\n\t• To make comparison between groups: Best fits an experimental, quasi-experimental, or comparative research design.\n\t• To describe population or certain phenomena: Best fits a classic descriptive or observational research design.","whyWrongChoices":"Alternative options: To describe population or certain phenomena, To explore relationship, To make comparison between groups"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
