INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:it is the study of assessment of diet and its relationship to disease etiology in the populations.:::nutritional epidemiology', 'it is the study of assessment of diet and its relationship to disease etiology in the populations.', 'Nutritional epidemiology', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutritional epidemiology\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.\n\n• \"Food and nutrition research\" is a broader, generic term not specific to disease etiology. \n• \"Food and nutrition epidemiology\" and \"food epidemiology\" are not the standard, recognized terms used in the field.","whyWrongChoices":"Alternative options: Food and nutrition research, Food and nutrition epidemiology, Food epidemiology"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the study of assessment of diet and its relationship to disease etiology in the populations.:::', 'it is the study of assessment of diet and its relationship to disease etiology in the populations.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutritional epidemiology\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.\n\n• \"Food and nutrition research\" is a broader, generic term not specific to disease etiology. \n• \"Food and nutrition epidemiology\" and \"food epidemiology\" are not the standard, recognized terms used in the field.","whyWrongChoices":"Alternative options: Food and nutrition research, Food and nutrition epidemiology, Food epidemiology"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the 3rs are principle of good science designed by scientist to improve animal welfare and scientific accuracy. which of the following means finding ways of making animals'' lives better in labs, this can include toys for animals or better training for technicians.:::', 'the 3rs are principle of good science designed by scientist to improve animal welfare and scientific accuracy. which of the following means finding ways of making animals'' lives better in labs, this can include toys for animals or better training for technicians.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Refinement - Minimize animal pain, suffering, and distress.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Refinement\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Refinement - Minimize animal pain, suffering, and distress.\n\n• Reduction - Use the minimum number of animals necessary.\n• Replacement - Use non-animal methods where possible.\n• Recognition - random word which start with letter R.","whyWrongChoices":"Alternative options: Reduction, Replacement, Recognition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the practice of analyzing describing a complex phenomenon in terms of phenomena that are held to represent a single or more fundamental level, especially when this is a said to provide a sufficient explanation:::reductionism in research', 'it is the practice of analyzing describing a complex phenomenon in terms of phenomena that are held to represent a single or more fundamental level, especially when this is a said to provide a sufficient explanation', 'Reductionism in research', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reductionism is a philosophical and scientific approach that breaks down complex systems or phenomena into their smaller, simpler, or more fundamental components. In research (especially in fields like nutritional biochemistry or physiology), it assumes that understanding these isolated, individual parts provides a sufficient explanation for the behavior of the entire system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reductionism in research\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reductionism is a philosophical and scientific approach that breaks down complex systems or phenomena into their smaller, simpler, or more fundamental components. In research (especially in fields like nutritional biochemistry or physiology), it assumes that understanding these isolated, individual parts provides a sufficient explanation for the behavior of the entire system.\n\n• Scientific Method: The systematic, step-by-step process of observing, forming a hypothesis, experimenting, and drawing conclusions to gather knowledge.\n• Research Method: The specific tools, techniques, or procedures used to collect and analyze data (e.g., surveys, randomized controlled trials, or double-blind studies).\n• Research Design: The overall structural blueprint or strategy chosen to integrate the different components of a study in a coherent and logical way (e.g., cross-sectional, cohort, or experimental design).","whyWrongChoices":"Alternative options: Research method, Scientific method, Research design"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the practice of analyzing describing a complex phenomenon in terms of phenomena that are held to represent a single or more fundamental level, especially when this is a said to provide a sufficient explanation:::', 'it is the practice of analyzing describing a complex phenomenon in terms of phenomena that are held to represent a single or more fundamental level, especially when this is a said to provide a sufficient explanation', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reductionism is a philosophical and scientific approach that breaks down complex systems or phenomena into their smaller, simpler, or more fundamental components. In research (especially in fields like nutritional biochemistry or physiology), it assumes that understanding these isolated, individual parts provides a sufficient explanation for the behavior of the entire system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reductionism in research\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reductionism is a philosophical and scientific approach that breaks down complex systems or phenomena into their smaller, simpler, or more fundamental components. In research (especially in fields like nutritional biochemistry or physiology), it assumes that understanding these isolated, individual parts provides a sufficient explanation for the behavior of the entire system.\n\n• Scientific Method: The systematic, step-by-step process of observing, forming a hypothesis, experimenting, and drawing conclusions to gather knowledge.\n• Research Method: The specific tools, techniques, or procedures used to collect and analyze data (e.g., surveys, randomized controlled trials, or double-blind studies).\n• Research Design: The overall structural blueprint or strategy chosen to integrate the different components of a study in a coherent and logical way (e.g., cross-sectional, cohort, or experimental design).","whyWrongChoices":"Alternative options: Research method, Scientific method, Research design"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the over-all goal of nutritional epidemiology?:::to contribute to the prevention of disease and the improvement of public health', 'what is the over-all goal of nutritional epidemiology?', 'To contribute to the prevention of disease and the improvement of public health', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is to contribute to the prevention of disease and the improvement of public health, which represents the ultimate purpose (goal). Choices A, B, and D are all legitimate specific aims or objectives that serve this larger goal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To contribute to the prevention of disease and the improvement of public health\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is to contribute to the prevention of disease and the improvement of public health, which represents the ultimate purpose (goal). Choices A, B, and D are all legitimate specific aims or objectives that serve this larger goal.\n\n“Goal\" (why it exists)\n\"Objectives\" (what it specifically does to get there)","whyWrongChoices":"Alternative options: To monitor the food consumption, nutrient intake and nutritional status of a population, To assess  the strength of diet-disease associations, To generate new hypothesis about diet and disease"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
