INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:which is true about the purpose of the menstrual cycle?:::a and b are both true', 'which is true about the purpose of the menstrual cycle?', 'A and B are both TRUE', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The menstrual cycle serves to develop and release a mature ovum (ovulation) and to prepare the uterine lining (endometrium) for potential implantation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both TRUE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The menstrual cycle serves to develop and release a mature ovum (ovulation) and to prepare the uterine lining (endometrium) for potential implantation.","whyWrongChoices":"Alternative options: To develop and release a mature ovum, To prepare the uterus lining, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the purpose of the menstrual cycle?:::', 'which is true about the purpose of the menstrual cycle?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The menstrual cycle serves to develop and release a mature ovum (ovulation) and to prepare the uterine lining (endometrium) for potential implantation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both TRUE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The menstrual cycle serves to develop and release a mature ovum (ovulation) and to prepare the uterine lining (endometrium) for potential implantation.","whyWrongChoices":"Alternative options: To develop and release a mature ovum, To prepare the uterus lining, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the female hormonal system, the source of luteinizing hormone-releasing hormone or lhrh is::::hypothalamus', 'in the female hormonal system, the source of luteinizing hormone-releasing hormone or lhrh is:', 'Hypothalamus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Luteinizing Hormone-Releasing Hormone (LHRH) is simply an older, synonymous name for Gonadotropin-Releasing Hormone (GnRH).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hypothalamus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Luteinizing Hormone-Releasing Hormone (LHRH) is simply an older, synonymous name for Gonadotropin-Releasing Hormone (GnRH).\n\nAny hormone that has the phrase \"releasing hormone\" in its name (such as LHRH/GnRH, TRH, CRH, and GHRH) is manufactured and secreted by the specialized nerve cells of the Hypothalamus.\n\nThe hypothalamus secretes LHRH into tiny blood vessels that travel directly to the Anterior Pituitary Gland. There, it triggers the pituitary gland to produce and release Luteinizing Hormone (LH) and Follicle-Stimulating Hormone (FSH) into general blood circulation to act on the ovaries.\n\n• Anterior pituitary gland - GH, TSH, ACTH, FSH, LH, PRL\n• Posterior pituitary gland - ADH, OT\n• Ovary - estrogen, progesterone, inhibin, androgen","whyWrongChoices":"Alternative options: Anterior pituitary gland, Posterior pituitary gland, Ovary"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a hormone secreted by the placenta that stimulates the secretion of estrogen and progesterone.:::', 'a hormone secreted by the placenta that stimulates the secretion of estrogen and progesterone.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Luteinizing hormone - Anterior Pituitary Gland - triggers ovulation in women and stimulates testosterone production in men.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chorionic gonadotropin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Luteinizing hormone - Anterior Pituitary Gland - triggers ovulation in women and stimulates testosterone production in men.\n• Placental lactogen - modifies the mother''s metabolism to facilitate energy supply to the fetus; also stimulates mammary gland development.\n• Follicle-stimulating hormone - Anterior Pituitary Gland - stimulates the growth of ovarian follicles in women and sperm production in men.","whyWrongChoices":"Alternative options: Luteinizing hormone, Placental lactogen, Follicle-stimulating hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the female hormonal system, the source of luteinizing hormone-releasing hormone or lhrh is::::', 'in the female hormonal system, the source of luteinizing hormone-releasing hormone or lhrh is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Luteinizing Hormone-Releasing Hormone (LHRH) is simply an older, synonymous name for Gonadotropin-Releasing Hormone (GnRH).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hypothalamus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Luteinizing Hormone-Releasing Hormone (LHRH) is simply an older, synonymous name for Gonadotropin-Releasing Hormone (GnRH).\n\nAny hormone that has the phrase \"releasing hormone\" in its name (such as LHRH/GnRH, TRH, CRH, and GHRH) is manufactured and secreted by the specialized nerve cells of the Hypothalamus.\n\nThe hypothalamus secretes LHRH into tiny blood vessels that travel directly to the Anterior Pituitary Gland. There, it triggers the pituitary gland to produce and release Luteinizing Hormone (LH) and Follicle-Stimulating Hormone (FSH) into general blood circulation to act on the ovaries.\n\n• Anterior pituitary gland - GH, TSH, ACTH, FSH, LH, PRL\n• Posterior pituitary gland - ADH, OT\n• Ovary - estrogen, progesterone, inhibin, androgen","whyWrongChoices":"Alternative options: Anterior pituitary gland, Posterior pituitary gland, Ovary"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the placenta is formed for different purposes except::::for production of nutrients and vitamins', 'the placenta is formed for different purposes except:', 'For production of nutrients and vitamins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The placenta serves as the physiological lifeline between the mother and the fetus, acting temporarily as the fetus''s lungs, kidneys, gut, and liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"For production of nutrients and vitamins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The placenta serves as the physiological lifeline between the mother and the fetus, acting temporarily as the fetus''s lungs, kidneys, gut, and liver.\n\n• Storage: The placenta dynamically stores nutrients like glycogen, iron, and specific fat-soluble vitamins during early pregnancy to ensure a steady, regulated supply is available for the developing fetus.\n• Waste Removal: It efficiently clears fetal metabolic waste products (such as carbon dioxide, urea, and uric acid) from the fetal bloodstream and transfers them into the maternal blood for excretion.\n• Supply Line: Its paramount baseline function is to transfer oxygen, water, glucose, amino acids, and essential vitamins from the maternal bloodstream into fetal circulation via the umbilical cord.\n\nThe placenta cannot synthesize or manufacture nutrients and vitamins from scratch. It relies entirely on drawing these essential substances from the mother''s circulation. It does produce hormones (such as hCG, progesterone, and estrogen), but not nutrients or vitamins.","whyWrongChoices":"Alternative options: To supply the fetus with nutrients and oxygen, For storage of nutrients and vitamins, For removing of fetal waste products"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the placenta is formed for different purposes except::::', 'the placenta is formed for different purposes except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The placenta serves as the physiological lifeline between the mother and the fetus, acting temporarily as the fetus''s lungs, kidneys, gut, and liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"For production of nutrients and vitamins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The placenta serves as the physiological lifeline between the mother and the fetus, acting temporarily as the fetus''s lungs, kidneys, gut, and liver.\n\n• Storage: The placenta dynamically stores nutrients like glycogen, iron, and specific fat-soluble vitamins during early pregnancy to ensure a steady, regulated supply is available for the developing fetus.\n• Waste Removal: It efficiently clears fetal metabolic waste products (such as carbon dioxide, urea, and uric acid) from the fetal bloodstream and transfers them into the maternal blood for excretion.\n• Supply Line: Its paramount baseline function is to transfer oxygen, water, glucose, amino acids, and essential vitamins from the maternal bloodstream into fetal circulation via the umbilical cord.\n\nThe placenta cannot synthesize or manufacture nutrients and vitamins from scratch. It relies entirely on drawing these essential substances from the mother''s circulation. It does produce hormones (such as hCG, progesterone, and estrogen), but not nutrients or vitamins.","whyWrongChoices":"Alternative options: To supply the fetus with nutrients and oxygen, For storage of nutrients and vitamins, For removing of fetal waste products"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:one of the typical nutritional problems among preschool children characterized by loss of subcutaneous fat and gross muscle wasting::::pem', 'one of the typical nutritional problems among preschool children characterized by loss of subcutaneous fat and gross muscle wasting:', 'PEM', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PEM – marasmus (wasting) and kwashiorkor (edema)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PEM\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PEM – marasmus (wasting) and kwashiorkor (edema)\n\n• Parasitism - presence of worm; can contribute to malnutrition\n• Edema – fluid retention; different or opposite-appearing presentation of PEM\n• Hyperkinesis - hyper-active; unrelated to wasting","whyWrongChoices":"Alternative options: Parasitism, Edema, Hyperkinesis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a hormone secreted by the placenta that stimulates the secretion of estrogen and progesterone.:::chorionic gonadotropin', 'a hormone secreted by the placenta that stimulates the secretion of estrogen and progesterone.', 'Chorionic gonadotropin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Luteinizing hormone - Anterior Pituitary Gland - triggers ovulation in women and stimulates testosterone production in men.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chorionic gonadotropin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Luteinizing hormone - Anterior Pituitary Gland - triggers ovulation in women and stimulates testosterone production in men.\n• Placental lactogen - modifies the mother''s metabolism to facilitate energy supply to the fetus; also stimulates mammary gland development.\n• Follicle-stimulating hormone - Anterior Pituitary Gland - stimulates the growth of ovarian follicles in women and sperm production in men.","whyWrongChoices":"Alternative options: Luteinizing hormone, Placental lactogen, Follicle-stimulating hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the nutritional requirements are increased during pregnancy to::::a and b are both true', 'the nutritional requirements are increased during pregnancy to:', 'A and B are both True', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Increased nutrient needs during pregnancy serve to support the growing fetus and other maternal tissues (such as the placenta and expanded blood volume), as well as to build maternal reserves in preparation for delivery and the subsequent demands of lactation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both True\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Increased nutrient needs during pregnancy serve to support the growing fetus and other maternal tissues (such as the placenta and expanded blood volume), as well as to build maternal reserves in preparation for delivery and the subsequent demands of lactation.","whyWrongChoices":"Alternative options: To meet the nutrient needs of the growth fetus, other maternal tissues, To build reserves in preparation of delivery and lactation, A and B are both False"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the nutritional requirements are increased during pregnancy to::::', 'the nutritional requirements are increased during pregnancy to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Increased nutrient needs during pregnancy serve to support the growing fetus and other maternal tissues (such as the placenta and expanded blood volume), as well as to build maternal reserves in preparation for delivery and the subsequent demands of lactation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both True\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Increased nutrient needs during pregnancy serve to support the growing fetus and other maternal tissues (such as the placenta and expanded blood volume), as well as to build maternal reserves in preparation for delivery and the subsequent demands of lactation.","whyWrongChoices":"Alternative options: To meet the nutrient needs of the growth fetus, other maternal tissues, To build reserves in preparation of delivery and lactation, A and B are both False"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:possible consequences of iodine deficiency during pregnancy::::cretinism', 'possible consequences of iodine deficiency during pregnancy:', 'Cretinism', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While low birth weight, stillbirth, and miscarriage can all be caused or exacerbated by severe maternal iodine deficiency, Cretinism is the most definitive, classic textbook consequence specifically caused by fetal iodine deficiency and congenital hypothyroidism.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cretinism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While low birth weight, stillbirth, and miscarriage can all be caused or exacerbated by severe maternal iodine deficiency, Cretinism is the most definitive, classic textbook consequence specifically caused by fetal iodine deficiency and congenital hypothyroidism.\n\nCretinism is an irreversible condition characterized by severe mental retardation, deaf-mutism, short stature (dwarfism), and spastic diplegia. It is uniquely linked to profound maternal and fetal iodine deficiency during critical early periods of brain development.\n\nWhile options A, B, and D are broader obstetric complications that can result from many different underlying medical and nutritional issues, cretinism stands out as the direct, hallmark clinical manifestation of severe iodine deficiency disorder (IDD) in a developing fetus.","whyWrongChoices":"Alternative options: Low birth weight, Stillbirth, Miscarriage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:possible consequences of iodine deficiency during pregnancy::::', 'possible consequences of iodine deficiency during pregnancy:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While low birth weight, stillbirth, and miscarriage can all be caused or exacerbated by severe maternal iodine deficiency, Cretinism is the most definitive, classic textbook consequence specifically caused by fetal iodine deficiency and congenital hypothyroidism.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cretinism\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While low birth weight, stillbirth, and miscarriage can all be caused or exacerbated by severe maternal iodine deficiency, Cretinism is the most definitive, classic textbook consequence specifically caused by fetal iodine deficiency and congenital hypothyroidism.\n\nCretinism is an irreversible condition characterized by severe mental retardation, deaf-mutism, short stature (dwarfism), and spastic diplegia. It is uniquely linked to profound maternal and fetal iodine deficiency during critical early periods of brain development.\n\nWhile options A, B, and D are broader obstetric complications that can result from many different underlying medical and nutritional issues, cretinism stands out as the direct, hallmark clinical manifestation of severe iodine deficiency disorder (IDD) in a developing fetus.","whyWrongChoices":"Alternative options: Low birth weight, Stillbirth, Miscarriage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are dietary management for morning sickness during pregnancy except::::citrus juice, water, milk coffee or tea if experiencing nausea', 'the following are dietary management for morning sickness during pregnancy except:', 'Citrus juice, water, milk coffee or tea if experiencing nausea', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Citrus juice (high acidity), water (trigger the gag reflex), milk (aggravates nausea), coffee, or tea (can stimulate stomach acid secretion) if experiencing nausea.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Citrus juice, water, milk coffee or tea if experiencing nausea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Citrus juice (high acidity), water (trigger the gag reflex), milk (aggravates nausea), coffee, or tea (can stimulate stomach acid secretion) if experiencing nausea.","whyWrongChoices":"Alternative options: Frequent small meals, Dry toast or crackers, Avoidance of foods with offensive odors"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not true about human milk composition?:::the composition of human milk is dependent of the state of the mother''s nutrition', 'which of the following is not true about human milk composition?', 'The composition of human milk is dependent of the state of the mother''s nutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The composition of human milk is dependent of the state of the mother''s nutrition: not necessarily because the composition of human milk is not entirely dependent on the mother''s diet. Human milk is remarkably stable for macronutrients (protein, carbohydrate) but highly dependent for certain micronutrients and fatty acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The composition of human milk is dependent of the state of the mother''s nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The composition of human milk is dependent of the state of the mother''s nutrition: not necessarily because the composition of human milk is not entirely dependent on the mother''s diet. Human milk is remarkably stable for macronutrients (protein, carbohydrate) but highly dependent for certain micronutrients and fatty acids.","whyWrongChoices":"Alternative options: Composition of human milk varies from one human to another, Human milk consists of solution of protein, sugar, and salts, The human milk is a solution in which a variety of fatty compounds are suspended"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not true about human milk composition?:::', 'which of the following is not true about human milk composition?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The composition of human milk is dependent of the state of the mother''s nutrition: not necessarily because the composition of human milk is not entirely dependent on the mother''s diet. Human milk is remarkably stable for macronutrients (protein, carbohydrate) but highly dependent for certain micronutrients and fatty acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The composition of human milk is dependent of the state of the mother''s nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The composition of human milk is dependent of the state of the mother''s nutrition: not necessarily because the composition of human milk is not entirely dependent on the mother''s diet. Human milk is remarkably stable for macronutrients (protein, carbohydrate) but highly dependent for certain micronutrients and fatty acids.","whyWrongChoices":"Alternative options: Composition of human milk varies from one human to another, Human milk consists of solution of protein, sugar, and salts, The human milk is a solution in which a variety of fatty compounds are suspended"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about amino acids in human milk?:::rich in taurine', 'which is true about amino acids in human milk?', 'Rich in taurine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Human milk is rich in taurine, an amino acid important for infant brain and retinal development that is present in relatively high concentration compared to cow''s milk. Human milk is actually lower in methionine and higher in cysteine, relatively low in phenylalanine and tyrosine compared to other protein sources.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rich in taurine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Human milk is rich in taurine, an amino acid important for infant brain and retinal development that is present in relatively high concentration compared to cow''s milk. Human milk is actually lower in methionine and higher in cysteine, relatively low in phenylalanine and tyrosine compared to other protein sources.","whyWrongChoices":"Alternative options: Higher in methionine and lower in cysteine, High in phenylalanine and tyrosine, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about amino acids in human milk?:::', 'which is true about amino acids in human milk?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Human milk is rich in taurine, an amino acid important for infant brain and retinal development that is present in relatively high concentration compared to cow''s milk. Human milk is actually lower in methionine and higher in cysteine, relatively low in phenylalanine and tyrosine compared to other protein sources.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rich in taurine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Human milk is rich in taurine, an amino acid important for infant brain and retinal development that is present in relatively high concentration compared to cow''s milk. Human milk is actually lower in methionine and higher in cysteine, relatively low in phenylalanine and tyrosine compared to other protein sources.","whyWrongChoices":"Alternative options: Higher in methionine and lower in cysteine, High in phenylalanine and tyrosine, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the human milk has a high concentration of the following minerals except::::iron', 'the human milk has a high concentration of the following minerals except:', 'Iron', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In maternal and child nutrition, human milk is characterized as a poor source of total iron, containing a very low absolute concentration of the mineral (approximately 0.2 to 0.4 mg/L).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In maternal and child nutrition, human milk is characterized as a poor source of total iron, containing a very low absolute concentration of the mineral (approximately 0.2 to 0.4 mg/L).\n\nDespite its low concentration, healthy full-term infants do not typically require iron supplementation during the first 6 months of exclusive breastfeeding. This is because the iron present in breast milk is exceptionally bound to lactoferrin and paired with high lactose and vitamin C levels, allowing up to 50% of it to be absorbed by the infant''s gut (compared to only ~4% absorption from cow''s milk or standard infant formula).\n\nCalcium, Potassium, and Phosphorus are major essential macrominerals found in much higher, structural quantities in human milk to directly drive infant bone mineralization, fluid balance, and cellular development.","whyWrongChoices":"Alternative options: Calcium, Potassium, Phosphorus"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the human milk has a high concentration of the following minerals except::::', 'the human milk has a high concentration of the following minerals except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In maternal and child nutrition, human milk is characterized as a poor source of total iron, containing a very low absolute concentration of the mineral (approximately 0.2 to 0.4 mg/L).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In maternal and child nutrition, human milk is characterized as a poor source of total iron, containing a very low absolute concentration of the mineral (approximately 0.2 to 0.4 mg/L).\n\nDespite its low concentration, healthy full-term infants do not typically require iron supplementation during the first 6 months of exclusive breastfeeding. This is because the iron present in breast milk is exceptionally bound to lactoferrin and paired with high lactose and vitamin C levels, allowing up to 50% of it to be absorbed by the infant''s gut (compared to only ~4% absorption from cow''s milk or standard infant formula).\n\nCalcium, Potassium, and Phosphorus are major essential macrominerals found in much higher, structural quantities in human milk to directly drive infant bone mineralization, fluid balance, and cellular development.","whyWrongChoices":"Alternative options: Calcium, Potassium, Phosphorus"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an anti-infectious factor in human milk that protects the integrity of the git epithelium?::::prostaglandins', 'an anti-infectious factor in human milk that protects the integrity of the git epithelium?:', 'Prostaglandins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Bifidus factor - feeds beneficial Bifidobacterium (probiotic); promotes healthy gut flora.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prostaglandins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Bifidus factor - feeds beneficial Bifidobacterium (probiotic); promotes healthy gut flora.\n• Lactoperoxidase - kills bacteria by catalyzing the production of hypothiocyanite (antimicrobial compound)\n• Lactoferrin - binds and sequesters iron, depriving harmful bacteria (which need iron to grow) of a vital nutrient.","whyWrongChoices":"Alternative options: Bifidusfactor, Lactoperoxidase, Lactoferrin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an anti-infectious factor in human milk that protects the integrity of the git epithelium?::::', 'an anti-infectious factor in human milk that protects the integrity of the git epithelium?:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Bifidus factor - feeds beneficial Bifidobacterium (probiotic); promotes healthy gut flora.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prostaglandins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Bifidus factor - feeds beneficial Bifidobacterium (probiotic); promotes healthy gut flora.\n• Lactoperoxidase - kills bacteria by catalyzing the production of hypothiocyanite (antimicrobial compound)\n• Lactoferrin - binds and sequesters iron, depriving harmful bacteria (which need iron to grow) of a vital nutrient.","whyWrongChoices":"Alternative options: Bifidusfactor, Lactoperoxidase, Lactoferrin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a drug that should be given to nursing mothers because of it may cause metabolic acidosis and can cause rash.:::aspirin', 'a drug that should be given to nursing mothers because of it may cause metabolic acidosis and can cause rash.', 'Aspirin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aspirin (salicylates) is famous in pediatric clinical pharmacology for causing mixed acid-base disorders. High-dose maternal ingestion has documented case studies causing metabolic acidosis in nursing infants due to renal accumulation of salicylic acid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspirin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aspirin (salicylates) is famous in pediatric clinical pharmacology for causing mixed acid-base disorders. High-dose maternal ingestion has documented case studies causing metabolic acidosis in nursing infants due to renal accumulation of salicylic acid.\n\nSalicylates also carry risks of antiplatelet-induced rashes/petechiae, hypersensitivity, and the theoretical risk of Reye’s syndrome if the infant encounters a viral illness.\n\n• Clemastine - causes drowsiness, irritability, and may reduce milk supply\n• Phenobarbital - causes significant sedation, lethargy, and central nervous system (CNS) depression.\n• Primidone - causes severe sedation, feeding problems, and is metabolized into phenobarbital.","whyWrongChoices":"Alternative options: Clemastine, Phenobarbital, Primidone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a drug that should be given to nursing mothers because of it may cause metabolic acidosis and can cause rash.:::', 'a drug that should be given to nursing mothers because of it may cause metabolic acidosis and can cause rash.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aspirin (salicylates) is famous in pediatric clinical pharmacology for causing mixed acid-base disorders. High-dose maternal ingestion has documented case studies causing metabolic acidosis in nursing infants due to renal accumulation of salicylic acid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspirin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aspirin (salicylates) is famous in pediatric clinical pharmacology for causing mixed acid-base disorders. High-dose maternal ingestion has documented case studies causing metabolic acidosis in nursing infants due to renal accumulation of salicylic acid.\n\nSalicylates also carry risks of antiplatelet-induced rashes/petechiae, hypersensitivity, and the theoretical risk of Reye’s syndrome if the infant encounters a viral illness.\n\n• Clemastine - causes drowsiness, irritability, and may reduce milk supply\n• Phenobarbital - causes significant sedation, lethargy, and central nervous system (CNS) depression.\n• Primidone - causes severe sedation, feeding problems, and is metabolized into phenobarbital.","whyWrongChoices":"Alternative options: Clemastine, Phenobarbital, Primidone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about brain growth and development in preschool age?:::brain size has reached 75% of its adult weight by age 2', 'which is true about brain growth and development in preschool age?', 'Brain size has reached 75% of its adult weight by age 2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At birth, the brain is 25% of its future adult size, and head circumference is about 14 inches (about 35 centimeters).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Brain size has reached 75% of its adult weight by age 2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At birth, the brain is 25% of its future adult size, and head circumference is about 14 inches (about 35 centimeters).\n\n• By 1 year of age, the brain is 75% of its adult size. By 3 years of age, the brain is 80% of its adult size.\n• By 7 years of age, the brain is 90% of its adult size (Gaber, 2019).","whyWrongChoices":"Alternative options: Brain size has reached 55% of its adult weight by age 2, Brain size has reached 80% of its adult weight by age 2, Brain size has reached 90% of its adult weight by age 2"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about brain growth and development in preschool age?:::', 'which is true about brain growth and development in preschool age?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At birth, the brain is 25% of its future adult size, and head circumference is about 14 inches (about 35 centimeters).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Brain size has reached 75% of its adult weight by age 2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At birth, the brain is 25% of its future adult size, and head circumference is about 14 inches (about 35 centimeters).\n\n• By 1 year of age, the brain is 75% of its adult size. By 3 years of age, the brain is 80% of its adult size.\n• By 7 years of age, the brain is 90% of its adult size (Gaber, 2019).","whyWrongChoices":"Alternative options: Brain size has reached 55% of its adult weight by age 2, Brain size has reached 80% of its adult weight by age 2, Brain size has reached 90% of its adult weight by age 2"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this term refers to the child who is "not up to expectation in general health":::failure to thrive', 'this term refers to the child who is "not up to expectation in general health"', 'Failure to thrive', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Failure to thrive refers to poor weight gain or size deviation post-natally.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Failure to thrive\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Failure to thrive refers to poor weight gain or size deviation post-natally.\n\n• Low birth weight - birth weight less than 2,500 grams.\n• Small for gestational age - birth weight below the 10th percentile for the baby''s age.\n• Premature infant - born before 37 full weeks of gestation","whyWrongChoices":"Alternative options: Low birth weight, Small for gestational age, Premature infant"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
