INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.:::2', 'this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.', '2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.\n\n• SDG 1: No Poverty - End poverty in all its forms everywhere.\n• SDG 3: Good Health and Well-being - Ensure healthy lives and promote well-being for all at all ages.\n• SDG 4: Quality Education - Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all.","whyWrongChoices":"Alternative options: 1, 3, 4"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.:::', 'this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.\n\n• SDG 1: No Poverty - End poverty in all its forms everywhere.\n• SDG 3: Good Health and Well-being - Ensure healthy lives and promote well-being for all at all ages.\n• SDG 4: Quality Education - Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all.","whyWrongChoices":"Alternative options: 1, 3, 4"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in what year was the first international conference on nutrition held?:::1992', 'in what year was the first international conference on nutrition held?', '1992', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1992\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.\n\nThe International Conference on Nutrition was held in Rome, from 5 to 11 December 1992. The Conference was not seen as an end in itself but rather as a step in the continuing process to strengthen commitment and the action necessary to prevent and alleviate nutrition problems. Enthusiasm has been generated in many countries for the implementation of plans which must now begin. Through increased awareness of the extent and seriousness of nutrition- and diet-related problems, the process leading to the Conference resulted in the public and private sectors'' increased willingness to work together to tackle them.","whyWrongChoices":"Alternative options: 1996, 2002, 2014"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in what year was the first international conference on nutrition held?:::', 'in what year was the first international conference on nutrition held?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1992\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.\n\nThe International Conference on Nutrition was held in Rome, from 5 to 11 December 1992. The Conference was not seen as an end in itself but rather as a step in the continuing process to strengthen commitment and the action necessary to prevent and alleviate nutrition problems. Enthusiasm has been generated in many countries for the implementation of plans which must now begin. Through increased awareness of the extent and seriousness of nutrition- and diet-related problems, the process leading to the Conference resulted in the public and private sectors'' increased willingness to work together to tackle them.","whyWrongChoices":"Alternative options: 1996, 2002, 2014"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the 2025 global nutrition targets include reduction in childhood::::wasting', 'the 2025 global nutrition targets include reduction in childhood:', 'Wasting', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wasting is one of the six original WHO Global Nutrition Targets for 2025. The six original 2025 targets cover stunting, wasting, overweight, anemia, low birth weight, and exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Wasting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wasting is one of the six original WHO Global Nutrition Targets for 2025. The six original 2025 targets cover stunting, wasting, overweight, anemia, low birth weight, and exclusive breastfeeding.\n\n• Target 1: 40% reduction in the number of children under five years of age who are stunted\n• Target 2: 50% reduction in anaemia in women of reproductive age.\n• Target 3: 30% reduction in low birth weight\n• Target 6: Reduce and maintain wasting in children under five years of age to less than 5%.\n\nMeanwhile, targets 4 and 5, which are close to being met in 2025, have been revised to raise ambition:\n• Target 4: Childhood overweight: The ambition of the target has been strengthened from the original target of maintaining the 2012 prevalence to reducing overweight among children under five to below 5% by 2030.\n• Target 5: Exclusive breastfeeding: To accelerate progress, the target has been increased from the original up to 50% of infants exclusively breastfed during the first six months of life by 2025 to up to 60% by 2030.\n\nSee reference here: https://www.who.int/teams/nutrition-and-food-safety/global-targets-2030","whyWrongChoices":"Alternative options: Anemia, Iodine Deficiency, Underweight"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the mandatory food fortification program, refined sugar is fortified with::::vit a', 'under the mandatory food fortification program, refined sugar is fortified with:', 'Vit A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A – oil, sugar\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Iron, Iodine, Vit A and Iron"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
