INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.:::monitoring', 'it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.', 'Monitoring', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Monitoring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.\n\n• Systematic Assessment of Progress (SAP) - structured, periodic check to see if short-term goals are being met and whether the project logic remains sound\n• Evaluation - determining relevance, effectiveness, impact, and efficiency of the project, often periodic or end-of-cycle\n• Sustainability - ensuring benefits continue after the program''s funding or external support ends","whyWrongChoices":"Alternative options: Systematic Assessment of Progress, Evaluation, Sustainability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.:::', 'it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Monitoring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.\n\n• Systematic Assessment of Progress (SAP) - structured, periodic check to see if short-term goals are being met and whether the project logic remains sound\n• Evaluation - determining relevance, effectiveness, impact, and efficiency of the project, often periodic or end-of-cycle\n• Sustainability - ensuring benefits continue after the program''s funding or external support ends","whyWrongChoices":"Alternative options: Systematic Assessment of Progress, Evaluation, Sustainability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives:::indicators', 'information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives', 'Indicators', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Indicators\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.\n\n• Data - raw, unorganized facts and figures\n• Records - stored, organized sets of data about a specific entity\n• Criteria - standards or principles used to judge, classify, or make a decision (e.g., age, income level).","whyWrongChoices":"Alternative options: Data, Records, Criteria"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives:::', 'information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Indicators\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.\n\n• Data - raw, unorganized facts and figures\n• Records - stored, organized sets of data about a specific entity\n• Criteria - standards or principles used to judge, classify, or make a decision (e.g., age, income level).","whyWrongChoices":"Alternative options: Data, Records, Criteria"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the changes in the condition of the target population which generally reflect the primary objectives of the project or program, e.g. percent improvement in the prevalence of stunting in the municipality.:::impact indicator', 'it refers to the changes in the condition of the target population which generally reflect the primary objectives of the project or program, e.g. percent improvement in the prevalence of stunting in the municipality.', 'Impact indicator', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Impact indicator - measures long-term, ultimate changes in well-being or the environment (e.g., reduced mortality rates, national poverty reduction)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Impact indicator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Impact indicator - measures long-term, ultimate changes in well-being or the environment (e.g., reduced mortality rates, national poverty reduction)\n\n• Input indicator - measures resources put into a program (e.g., funds spent, staff hired)\n• Output indicator - measures direct, tangible results of program activities (e.g., training sessions held, meals served)\n• Outcome indicator - measures changes in behavior, knowledge, or condition achieved by the target group (e.g., improved hygiene practices, increased enrollment)","whyWrongChoices":"Alternative options: Input indicator, Output indicator, Outcome indicator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the changes in the condition of the target population which generally reflect the primary objectives of the project or program, e.g. percent improvement in the prevalence of stunting in the municipality.:::', 'it refers to the changes in the condition of the target population which generally reflect the primary objectives of the project or program, e.g. percent improvement in the prevalence of stunting in the municipality.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Impact indicator - measures long-term, ultimate changes in well-being or the environment (e.g., reduced mortality rates, national poverty reduction)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Impact indicator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Impact indicator - measures long-term, ultimate changes in well-being or the environment (e.g., reduced mortality rates, national poverty reduction)\n\n• Input indicator - measures resources put into a program (e.g., funds spent, staff hired)\n• Output indicator - measures direct, tangible results of program activities (e.g., training sessions held, meals served)\n• Outcome indicator - measures changes in behavior, knowledge, or condition achieved by the target group (e.g., improved hygiene practices, increased enrollment)","whyWrongChoices":"Alternative options: Input indicator, Output indicator, Outcome indicator"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.:::process evaluation', 'it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.', 'Process evaluation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Process evaluation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).\n\n• Ex-ante evaluation - assessing potential before program starts (feasibility, relevance).\n• Ex-post evaluation - assessing actual results/impact after program ends (overall success).\n• Result evaluation - assessing what the program achieved (outcomes, effects, and impact).","whyWrongChoices":"Alternative options: Ex-ante evaluation, Ex-post evaluation, Result evaluation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.:::', 'it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Process evaluation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).\n\n• Ex-ante evaluation - assessing potential before program starts (feasibility, relevance).\n• Ex-post evaluation - assessing actual results/impact after program ends (overall success).\n• Result evaluation - assessing what the program achieved (outcomes, effects, and impact).","whyWrongChoices":"Alternative options: Ex-ante evaluation, Ex-post evaluation, Result evaluation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in process evaluation, the following questions will be addressed, except::::what will be the result of this project?', 'in process evaluation, the following questions will be addressed, except:', 'What will be the result of this project?', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question \"what will be the result of this project?\" belongs to result evaluation, which focuses on outcomes and impact, not process evaluation, which focuses on implementation quality and efficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"What will be the result of this project?\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question \"what will be the result of this project?\" belongs to result evaluation, which focuses on outcomes and impact, not process evaluation, which focuses on implementation quality and efficiency.","whyWrongChoices":"Alternative options: Are we doing our job well?, What can we be improved upon in the project?, Are we spending resources properly?"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
