INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:which of the following is a measurement of body composition?:::body fat', 'which of the following is a measurement of body composition?', 'Body Fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Body composition specifically refers to the relative proportions of fat mass versus fat-free (lean) mass in the body, and body fat measurement directly captures one of these two core components. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Body Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Body composition specifically refers to the relative proportions of fat mass versus fat-free (lean) mass in the body, and body fat measurement directly captures one of these two core components. \n\n• Weight and height are simple anthropometric dimensions that do not by themselves distinguish fat from lean tissue. \n• Head circumference is a growth/development indicator used mainly in infants to assess brain growth.","whyWrongChoices":"Alternative options: Weight, Height, Head circumference"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this pertains to the number of deaths per 1000 livebirth of infants under 1 year of age in a calendar year in the same period:::imr', 'this pertains to the number of deaths per 1000 livebirth of infants under 1 year of age in a calendar year in the same period', 'IMR', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"IMR (Infant Mortality Rate): The number of deaths of children under 1 year of age (0 to 365 days) per 1,000 live births in a given calendar year. It is a standard public health indicator reflecting the overall socio-economic and healthcare status of a population.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"IMR\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"IMR (Infant Mortality Rate): The number of deaths of children under 1 year of age (0 to 365 days) per 1,000 live births in a given calendar year. It is a standard public health indicator reflecting the overall socio-economic and healthcare status of a population.\n\n• MMR (Maternal Mortality Ratio/Rate): The number of maternal deaths from any cause related to or aggravated by pregnancy or its management during pregnancy and childbirth (or within 42 days of termination) per 100,000 live births.\n• NMR (Neonatal Mortality Rate): The number of deaths during the first 28 days of life (neonatal period) per 1,000 live births.\n• SMR (Standardized Mortality Ratio): The ratio of observed deaths in the study group to the expected deaths in the general population, or Senile Mortality Rate depending on the epidemiological context.","whyWrongChoices":"Alternative options: NMR, MMR, SMR"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this pertains to the number of deaths per 1000 livebirth of infants under 1 year of age in a calendar year in the same period:::', 'this pertains to the number of deaths per 1000 livebirth of infants under 1 year of age in a calendar year in the same period', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"IMR (Infant Mortality Rate): The number of deaths of children under 1 year of age (0 to 365 days) per 1,000 live births in a given calendar year. It is a standard public health indicator reflecting the overall socio-economic and healthcare status of a population.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"IMR\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"IMR (Infant Mortality Rate): The number of deaths of children under 1 year of age (0 to 365 days) per 1,000 live births in a given calendar year. It is a standard public health indicator reflecting the overall socio-economic and healthcare status of a population.\n\n• MMR (Maternal Mortality Ratio/Rate): The number of maternal deaths from any cause related to or aggravated by pregnancy or its management during pregnancy and childbirth (or within 42 days of termination) per 100,000 live births.\n• NMR (Neonatal Mortality Rate): The number of deaths during the first 28 days of life (neonatal period) per 1,000 live births.\n• SMR (Standardized Mortality Ratio): The ratio of observed deaths in the study group to the expected deaths in the general population, or Senile Mortality Rate depending on the epidemiological context.","whyWrongChoices":"Alternative options: NMR, MMR, SMR"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:obesity prevalence among adults 20 to 59 years old according to the 2021 enns is::::10.0%', 'obesity prevalence among adults 20 to 59 years old according to the 2021 enns is:', '10.0%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the 2021 Expanded National Nutrition Survey (DOST-FNRI), based on the WHO Asia-Pacific BMI Classification,","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10.0%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the 2021 Expanded National Nutrition Survey (DOST-FNRI), based on the WHO Asia-Pacific BMI Classification,\n\n• 18.3% adults were overweight (BMI: 23.0 to 24.9 kg/m²)\n• 30.2% were obese class I (BMI: 25.0 to 29.9 kg/m²)\n• 10.0% were obese class II (BMI: ≥30 kg/m²).","whyWrongChoices":"Alternative options: 11.7%, 30.2%, 35.5%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:obesity prevalence among adults 20 to 59 years old according to the 2021 enns is::::', 'obesity prevalence among adults 20 to 59 years old according to the 2021 enns is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the 2021 Expanded National Nutrition Survey (DOST-FNRI), based on the WHO Asia-Pacific BMI Classification,","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10.0%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the 2021 Expanded National Nutrition Survey (DOST-FNRI), based on the WHO Asia-Pacific BMI Classification,\n\n• 18.3% adults were overweight (BMI: 23.0 to 24.9 kg/m²)\n• 30.2% were obese class I (BMI: 25.0 to 29.9 kg/m²)\n• 10.0% were obese class II (BMI: ≥30 kg/m²).","whyWrongChoices":"Alternative options: 11.7%, 30.2%, 35.5%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:menke''s kinky hair syndrome is a deficiency in ?:::copper', 'menke''s kinky hair syndrome is a deficiency in ?', 'Copper', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Menke''s kinky hair syndrome is the genetic disorder of copper metabolism/transport that results in severe copper deficiency, presenting classically with sparse, kinky, brittle hair along with neurodegenerative symptoms in affected infants.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Copper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Menke''s kinky hair syndrome is the genetic disorder of copper metabolism/transport that results in severe copper deficiency, presenting classically with sparse, kinky, brittle hair along with neurodegenerative symptoms in affected infants.","whyWrongChoices":"Alternative options: Chromium, Calcium, Cobalt"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is a measurement of body composition?:::', 'which of the following is a measurement of body composition?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Body composition specifically refers to the relative proportions of fat mass versus fat-free (lean) mass in the body, and body fat measurement directly captures one of these two core components. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Body Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Body composition specifically refers to the relative proportions of fat mass versus fat-free (lean) mass in the body, and body fat measurement directly captures one of these two core components. \n\n• Weight and height are simple anthropometric dimensions that do not by themselves distinguish fat from lean tissue. \n• Head circumference is a growth/development indicator used mainly in infants to assess brain growth.","whyWrongChoices":"Alternative options: Weight, Height, Head circumference"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bitot''s spot is characterized by ?:::dryness of conjunctiva with foamy patch', 'bitot''s spot is characterized by ?', 'Dryness of conjunctiva with foamy patch', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dryness of the conjunctiva with foamy patches is the precise clinical description of a Bitot''s spot, a foamy, triangular, grayish-white patch on the conjunctiva associated with vitamin A deficiency-related xerophthalmia. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dryness of conjunctiva with foamy patch\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dryness of the conjunctiva with foamy patches is the precise clinical description of a Bitot''s spot, a foamy, triangular, grayish-white patch on the conjunctiva associated with vitamin A deficiency-related xerophthalmia. \n\n• Night blindness is an earlier, functional (not physical) sign of vitamin A deficiency, appearing before Bitot''s spots develop. \n• Conjunctival xerosis refers to generalized dryness of the conjunctiva without the specific foamy patch appearance that defines a Bitot''s spot.\n• Corneal xerosis refers to dryness affecting the cornea.","whyWrongChoices":"Alternative options: Nightblindness, Conjuctival xerosis, Corneal xerosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bitot''s spot is characterized by ?:::', 'bitot''s spot is characterized by ?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dryness of the conjunctiva with foamy patches is the precise clinical description of a Bitot''s spot, a foamy, triangular, grayish-white patch on the conjunctiva associated with vitamin A deficiency-related xerophthalmia. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dryness of conjunctiva with foamy patch\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dryness of the conjunctiva with foamy patches is the precise clinical description of a Bitot''s spot, a foamy, triangular, grayish-white patch on the conjunctiva associated with vitamin A deficiency-related xerophthalmia. \n\n• Night blindness is an earlier, functional (not physical) sign of vitamin A deficiency, appearing before Bitot''s spots develop. \n• Conjunctival xerosis refers to generalized dryness of the conjunctiva without the specific foamy patch appearance that defines a Bitot''s spot.\n• Corneal xerosis refers to dryness affecting the cornea.","whyWrongChoices":"Alternative options: Nightblindness, Conjuctival xerosis, Corneal xerosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are possible blocks to food consumption except::::poor road conditions', 'all of the following are possible blocks to food consumption except:', 'poor road conditions', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In community nutrition, barriers to food security are classified according to specific stages of the Food Pathway:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"poor road conditions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In community nutrition, barriers to food security are classified according to specific stages of the Food Pathway:\n• Food Distribution Block: Poor road conditions serve as a barrier during the transport and logistics stage. It prevents food from reaching marketplaces efficiently, affecting availability and accessibility rather than the choices made at the household table.\n• Food Consumption Blocks: Religious laws (e.g., halal/kosher), personal food preferences, and a lack of knowledge on nutrition are all localized or individual factors that directly obstruct or alter how families choose to consume available food.","whyWrongChoices":"Alternative options: food preference, religion, knowledge on nutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are possible blocks to food consumption except::::', 'all of the following are possible blocks to food consumption except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In community nutrition, barriers to food security are classified according to specific stages of the Food Pathway:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"poor road conditions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In community nutrition, barriers to food security are classified according to specific stages of the Food Pathway:\n• Food Distribution Block: Poor road conditions serve as a barrier during the transport and logistics stage. It prevents food from reaching marketplaces efficiently, affecting availability and accessibility rather than the choices made at the household table.\n• Food Consumption Blocks: Religious laws (e.g., halal/kosher), personal food preferences, and a lack of knowledge on nutrition are all localized or individual factors that directly obstruct or alter how families choose to consume available food.","whyWrongChoices":"Alternative options: food preference, religion, knowledge on nutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to the presence of adequate, quality, and safe food that satisfies the dietary need of individual, supplied through either domestic production or imports:::availability', 'this refers to the presence of adequate, quality, and safe food that satisfies the dietary need of individual, supplied through either domestic production or imports', 'Availability', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Availability - physical presence of food","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Availability\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Availability - physical presence of food\n\n• Accessibility - ability to get or afford the resources (e.g., food, services, markets).\n• Nutrition security - consistent access, affordability, and utilization of diverse, safe, and nutritious food to ensure a healthy life.\n• Economic security - stable income, resources, and access to work that guarantees a basic standard of living and protects against shocks.","whyWrongChoices":"Alternative options: Accessibility, Nutrition security, Economic security"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to the presence of adequate, quality, and safe food that satisfies the dietary need of individual, supplied through either domestic production or imports:::', 'this refers to the presence of adequate, quality, and safe food that satisfies the dietary need of individual, supplied through either domestic production or imports', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Availability - physical presence of food","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Availability\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Availability - physical presence of food\n\n• Accessibility - ability to get or afford the resources (e.g., food, services, markets).\n• Nutrition security - consistent access, affordability, and utilization of diverse, safe, and nutritious food to ensure a healthy life.\n• Economic security - stable income, resources, and access to work that guarantees a basic standard of living and protects against shocks.","whyWrongChoices":"Alternative options: Accessibility, Nutrition security, Economic security"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to the physical, economic, socio-cultural, and policy conditions that shape access, affordability, safety and food preferences:::food environment', 'this refers to the physical, economic, socio-cultural, and policy conditions that shape access, affordability, safety and food preferences', 'Food environment', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The term food environment encompasses the collective physical, economic, policy, and socio-cultural surroundings and opportunities that directly influence a consumer''s food choices, purchasing habits, and nutritional status.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food environment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The term food environment encompasses the collective physical, economic, policy, and socio-cultural surroundings and opportunities that directly influence a consumer''s food choices, purchasing habits, and nutritional status.\n\nIt acts as the interface where a person makes a decision about what to eat, driven by specific subdomains:\n• Physical & Policy Conditions: The location of grocery stores versus \"food deserts,\" food safety regulations, or marketing and labeling laws.\n• Economic & Socio-cultural Conditions: Retail prices, household purchasing power (affordability), and family or community traditions that dictate food preferences.","whyWrongChoices":"Alternative options: Food path, Food distribution, Food trade"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this refers to the physical, economic, socio-cultural, and policy conditions that shape access, affordability, safety and food preferences:::', 'this refers to the physical, economic, socio-cultural, and policy conditions that shape access, affordability, safety and food preferences', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The term food environment encompasses the collective physical, economic, policy, and socio-cultural surroundings and opportunities that directly influence a consumer''s food choices, purchasing habits, and nutritional status.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food environment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The term food environment encompasses the collective physical, economic, policy, and socio-cultural surroundings and opportunities that directly influence a consumer''s food choices, purchasing habits, and nutritional status.\n\nIt acts as the interface where a person makes a decision about what to eat, driven by specific subdomains:\n• Physical & Policy Conditions: The location of grocery stores versus \"food deserts,\" food safety regulations, or marketing and labeling laws.\n• Economic & Socio-cultural Conditions: Retail prices, household purchasing power (affordability), and family or community traditions that dictate food preferences.","whyWrongChoices":"Alternative options: Food path, Food distribution, Food trade"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following often shape food environments except::::consumer behavior', 'all of the following often shape food environments except:', 'Consumer behavior', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is consumer behavior because consumer behavior is generally considered an outcome or response shaped BY the food environment (through what foods are available, promoted, and priced), rather than itself being a shaping force of the environment. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Consumer behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is consumer behavior because consumer behavior is generally considered an outcome or response shaped BY the food environment (through what foods are available, promoted, and priced), rather than itself being a shaping force of the environment. \n\nPrivate companies, industry, and legal frameworks are all recognized as active forces that shape food environments.","whyWrongChoices":"Alternative options: Private companies, Industry, Legal frameworks"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following often shape food environments except::::', 'all of the following often shape food environments except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is consumer behavior because consumer behavior is generally considered an outcome or response shaped BY the food environment (through what foods are available, promoted, and priced), rather than itself being a shaping force of the environment. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Consumer behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is consumer behavior because consumer behavior is generally considered an outcome or response shaped BY the food environment (through what foods are available, promoted, and priced), rather than itself being a shaping force of the environment. \n\nPrivate companies, industry, and legal frameworks are all recognized as active forces that shape food environments.","whyWrongChoices":"Alternative options: Private companies, Industry, Legal frameworks"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:two of the following are possible blocks to food availability except::::market price', 'two of the following are possible blocks to food availability except:', 'Market price', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food Availability (Supply Side) refers to the physical presence of food through local agricultural production, storage, or imports.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Market price\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food Availability (Supply Side) refers to the physical presence of food through local agricultural production, storage, or imports.\n\t• Presence of pests and Typhoons are environmental or biological hazards that physically destroy crops, directly blocking availability.\n\t• Availability of agricultural inputs (like seeds and fertilizer) directly determines how much food can be produced in the first place.\n\nFood Accessibility/Affordability (Demand Side): Market price does not typically prevent food from physically existing or being available in a market. Instead, high prices act as an economic barrier, blocking a family''s accessibility or affordability to buy the food that is already there.","whyWrongChoices":"Alternative options: Typhoon, Availability of agricultural inputs, Presence of pests"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:two of the following are possible blocks to food availability except::::', 'two of the following are possible blocks to food availability except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food Availability (Supply Side) refers to the physical presence of food through local agricultural production, storage, or imports.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Market price\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food Availability (Supply Side) refers to the physical presence of food through local agricultural production, storage, or imports.\n\t• Presence of pests and Typhoons are environmental or biological hazards that physically destroy crops, directly blocking availability.\n\t• Availability of agricultural inputs (like seeds and fertilizer) directly determines how much food can be produced in the first place.\n\nFood Accessibility/Affordability (Demand Side): Market price does not typically prevent food from physically existing or being available in a market. Instead, high prices act as an economic barrier, blocking a family''s accessibility or affordability to buy the food that is already there.","whyWrongChoices":"Alternative options: Typhoon, Availability of agricultural inputs, Presence of pests"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are the main drivers of changes in the food system except::::food supply chains', 'all of the following are the main drivers of changes in the food system except:', 'Food supply chains', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the High Level Panel of Experts (HLPE) on Food Security and Nutrition and the Food and Agriculture Organization (FAO), a food system is conceptually split into Drivers, Core Components, and Outcomes:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food supply chains\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the High Level Panel of Experts (HLPE) on Food Security and Nutrition and the Food and Agriculture Organization (FAO), a food system is conceptually split into Drivers, Core Components, and Outcomes:\n\nDrivers (External Elements): These are the broad, macro-level forces that push or pull the entire food system into changing. The recognized categories of global drivers include:\n\t• Political and institutional factors (e.g., policies, trade laws, land rights)\n\t• Economic and market factors (e.g., income shifts, globalization, prices)\n\t• Technology and innovation factors (e.g., precision agriculture, storage engineering)\n\t• Biophysical and climate factors (e.g., weather, soil health)\n\t• Demographic and socio-cultural factors (e.g., population growth, shifting habits)\n\nFood Supply Chains (Internal Component): Food supply chains (comprising agricultural production, storage, processing, and distribution) are not external drivers of change. Instead, they are the internal mechanisms or structural pillars of the food system that get altered or shaped by the drivers.","whyWrongChoices":"Alternative options: Technology and innovation, Economic and market, Political and institution"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are the main drivers of changes in the food system except::::', 'all of the following are the main drivers of changes in the food system except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the High Level Panel of Experts (HLPE) on Food Security and Nutrition and the Food and Agriculture Organization (FAO), a food system is conceptually split into Drivers, Core Components, and Outcomes:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food supply chains\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the High Level Panel of Experts (HLPE) on Food Security and Nutrition and the Food and Agriculture Organization (FAO), a food system is conceptually split into Drivers, Core Components, and Outcomes:\n\nDrivers (External Elements): These are the broad, macro-level forces that push or pull the entire food system into changing. The recognized categories of global drivers include:\n\t• Political and institutional factors (e.g., policies, trade laws, land rights)\n\t• Economic and market factors (e.g., income shifts, globalization, prices)\n\t• Technology and innovation factors (e.g., precision agriculture, storage engineering)\n\t• Biophysical and climate factors (e.g., weather, soil health)\n\t• Demographic and socio-cultural factors (e.g., population growth, shifting habits)\n\nFood Supply Chains (Internal Component): Food supply chains (comprising agricultural production, storage, processing, and distribution) are not external drivers of change. Instead, they are the internal mechanisms or structural pillars of the food system that get altered or shaped by the drivers.","whyWrongChoices":"Alternative options: Technology and innovation, Economic and market, Political and institution"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a typical component of a nutrition survey?:::randomized controlled trial design', 'which of the following is not a typical component of a nutrition survey?', 'Randomized controlled trial design', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Randomized controlled trial DESIGN is where researchers manipulate an independent variable (the intervention) and randomly assign participants to an intervention group or a control group, hence it is not a typical component of a nutrition survey.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Randomized controlled trial design\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Randomized controlled trial DESIGN is where researchers manipulate an independent variable (the intervention) and randomly assign participants to an intervention group or a control group, hence it is not a typical component of a nutrition survey.","whyWrongChoices":"Alternative options: Anthropometric measurements (height, weight, etc.), Biochemical tests (blood or urine analysis), Detailed clinical examination"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not a typical component of a nutrition survey?:::', 'which of the following is not a typical component of a nutrition survey?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Randomized controlled trial DESIGN is where researchers manipulate an independent variable (the intervention) and randomly assign participants to an intervention group or a control group, hence it is not a typical component of a nutrition survey.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Randomized controlled trial design\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Randomized controlled trial DESIGN is where researchers manipulate an independent variable (the intervention) and randomly assign participants to an intervention group or a control group, hence it is not a typical component of a nutrition survey.","whyWrongChoices":"Alternative options: Anthropometric measurements (height, weight, etc.), Biochemical tests (blood or urine analysis), Detailed clinical examination"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is the primary goal of a nutrition surveillance system?:::to inform public health policies and interventions related to nutrition', 'which of the following is the primary goal of a nutrition surveillance system?', 'To inform public health policies and interventions related to nutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is to inform public health policies and interventions related to nutrition, which is the defining purpose of surveillance: continuous data collection specifically intended to guide decision-making.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To inform public health policies and interventions related to nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is to inform public health policies and interventions related to nutrition, which is the defining purpose of surveillance: continuous data collection specifically intended to guide decision-making.\n\n• To diagnose individual nutritional deficiencies - surveillance systems track population trends, not individual diagnoses\n• To monitor trends in food prices - only one possible component, not the overall goal\n• To assess the nutritional status of individuals in a clinical setting - surveillance is population-based, not conducted in individual clinical settings.","whyWrongChoices":"Alternative options: To diagnose individual nutritional deficiencies, To monitor trends in food prices, To assess the nutritional status of individuals in a clinical setting"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is the primary goal of a nutrition surveillance system?:::', 'which of the following is the primary goal of a nutrition surveillance system?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is to inform public health policies and interventions related to nutrition, which is the defining purpose of surveillance: continuous data collection specifically intended to guide decision-making.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To inform public health policies and interventions related to nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is to inform public health policies and interventions related to nutrition, which is the defining purpose of surveillance: continuous data collection specifically intended to guide decision-making.\n\n• To diagnose individual nutritional deficiencies - surveillance systems track population trends, not individual diagnoses\n• To monitor trends in food prices - only one possible component, not the overall goal\n• To assess the nutritional status of individuals in a clinical setting - surveillance is population-based, not conducted in individual clinical settings.","whyWrongChoices":"Alternative options: To diagnose individual nutritional deficiencies, To monitor trends in food prices, To assess the nutritional status of individuals in a clinical setting"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not typically a component of a nutrition surveillance system?:::assessing the availability of processed foods in supermarkets', 'which of the following is not typically a component of a nutrition surveillance system?', 'Assessing the availability of processed foods in supermarkets', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is assessing the availability of processed foods in supermarkets, because this is too narrow and specific to be a standard, defining component of surveillance systems.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Assessing the availability of processed foods in supermarkets\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is assessing the availability of processed foods in supermarkets, because this is too narrow and specific to be a standard, defining component of surveillance systems.","whyWrongChoices":"Alternative options: Monitoring food consumption, Tracking changes in body weight and height (Anthropometry), Evaluating the effectiveness of nutrition education programs"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
