INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the enzyme that breaks down starch in the mouth::::', 'the enzyme that breaks down starch in the mouth:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chemical digestion of carbohydrates begins directly in the oral cavity. When food is chewed, the salivary glands secrete saliva containing salivary amylase (historically called ptyalin). This enzyme targets complex, long-chain starches (polysaccharides) and breaks them down via hydrolysis into simpler disaccharide sugars, primarily maltose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Salivary amylase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chemical digestion of carbohydrates begins directly in the oral cavity. When food is chewed, the salivary glands secrete saliva containing salivary amylase (historically called ptyalin). This enzyme targets complex, long-chain starches (polysaccharides) and breaks them down via hydrolysis into simpler disaccharide sugars, primarily maltose.\n\n\t× Carbohydrates: This is the general macromutrient category that includes starches and sugars, not an enzyme.\n\t× Gastric protease: Proteases (such as pepsin) break down proteins into amino acids. Gastric protease is active inside the highly acidic environment of the stomach, not the mouth.\n\t× Lipase: This enzyme is specialized to break down lipids (fats and oils) into fatty acids and glycerol.","whyWrongChoices":"Alternative options: Carbohydrates, Lipase, gastric protease"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the stomach empties into the:::duodenum', 'the stomach empties into the', 'duodenum', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Following mechanical and chemical digestion in the stomach—driven by hydrochloric acid and pepsin—the pyloric sphincter regulates the passage of acidic chyme into the duodenum. In the duodenal lumen, Brunner''s glands secrete alkaline mucus, and secretions from the pancreas and gallbladder (delivering bicarbonate, lipases, proteases, and bile acids) enter via the hepatopancreatic ampulla to neutralize gastric acid and initiate the enzymatic breakdown of macronutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"duodenum\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Following mechanical and chemical digestion in the stomach—driven by hydrochloric acid and pepsin—the pyloric sphincter regulates the passage of acidic chyme into the duodenum. In the duodenal lumen, Brunner''s glands secrete alkaline mucus, and secretions from the pancreas and gallbladder (delivering bicarbonate, lipases, proteases, and bile acids) enter via the hepatopancreatic ampulla to neutralize gastric acid and initiate the enzymatic breakdown of macronutrients.","whyWrongChoices":"Alternative options: Ileum, esophagus, jejunum"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the stomach empties into the:::', 'the stomach empties into the', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Following mechanical and chemical digestion in the stomach—driven by hydrochloric acid and pepsin—the pyloric sphincter regulates the passage of acidic chyme into the duodenum. In the duodenal lumen, Brunner''s glands secrete alkaline mucus, and secretions from the pancreas and gallbladder (delivering bicarbonate, lipases, proteases, and bile acids) enter via the hepatopancreatic ampulla to neutralize gastric acid and initiate the enzymatic breakdown of macronutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"duodenum\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Following mechanical and chemical digestion in the stomach—driven by hydrochloric acid and pepsin—the pyloric sphincter regulates the passage of acidic chyme into the duodenum. In the duodenal lumen, Brunner''s glands secrete alkaline mucus, and secretions from the pancreas and gallbladder (delivering bicarbonate, lipases, proteases, and bile acids) enter via the hepatopancreatic ampulla to neutralize gastric acid and initiate the enzymatic breakdown of macronutrients.","whyWrongChoices":"Alternative options: Ileum, esophagus, jejunum"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the main function of bile is to::::emulsify fats', 'the main function of bile is to:', 'Emulsify fats', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile is a fluid produced by the liver and stored in the gallbladder. Its primary role in the digestive system is the physical emulsification of dietary lipids (fats) in the small intestine. Because fats are hydrophobic (water-fearing) and naturally clump into large droplets, pancreatic enzymes cannot easily break them down. Bile acts as a natural biological detergent, breaking these large fat globules apart into millions of tiny droplets. This dramatically increases the surface area, allowing pancreatic lipase enzymes to efficiently bind and digest the fats.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Emulsify fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile is a fluid produced by the liver and stored in the gallbladder. Its primary role in the digestive system is the physical emulsification of dietary lipids (fats) in the small intestine. Because fats are hydrophobic (water-fearing) and naturally clump into large droplets, pancreatic enzymes cannot easily break them down. Bile acts as a natural biological detergent, breaking these large fat globules apart into millions of tiny droplets. This dramatically increases the surface area, allowing pancreatic lipase enzymes to efficiently bind and digest the fats.\n\n• Catalyse hydrolysis: Hydrolysis (chemical breakdown using water) is catalyzed exclusively by digestive enzymes (like lipase or amylase); bile contains no enzymes.\n• Neutralize stomach acidity: While bile is slightly alkaline, the main job of neutralizing highly acidic stomach chyme belongs to sodium bicarbonate secreted by the pancreas.\n• Slow protein digestion: Bile does not interact with, slow down, or regulate the digestion of dietary proteins.","whyWrongChoices":"Alternative options: Catalyse hydrolysis, Slow protein digestion, Neutralize stomach acidity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the main function of bile is to::::', 'the main function of bile is to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile is a fluid produced by the liver and stored in the gallbladder. Its primary role in the digestive system is the physical emulsification of dietary lipids (fats) in the small intestine. Because fats are hydrophobic (water-fearing) and naturally clump into large droplets, pancreatic enzymes cannot easily break them down. Bile acts as a natural biological detergent, breaking these large fat globules apart into millions of tiny droplets. This dramatically increases the surface area, allowing pancreatic lipase enzymes to efficiently bind and digest the fats.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Emulsify fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile is a fluid produced by the liver and stored in the gallbladder. Its primary role in the digestive system is the physical emulsification of dietary lipids (fats) in the small intestine. Because fats are hydrophobic (water-fearing) and naturally clump into large droplets, pancreatic enzymes cannot easily break them down. Bile acts as a natural biological detergent, breaking these large fat globules apart into millions of tiny droplets. This dramatically increases the surface area, allowing pancreatic lipase enzymes to efficiently bind and digest the fats.\n\n• Catalyse hydrolysis: Hydrolysis (chemical breakdown using water) is catalyzed exclusively by digestive enzymes (like lipase or amylase); bile contains no enzymes.\n• Neutralize stomach acidity: While bile is slightly alkaline, the main job of neutralizing highly acidic stomach chyme belongs to sodium bicarbonate secreted by the pancreas.\n• Slow protein digestion: Bile does not interact with, slow down, or regulate the digestion of dietary proteins.","whyWrongChoices":"Alternative options: Catalyse hydrolysis, Slow protein digestion, Neutralize stomach acidity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which nutrients seem to protect against age related macular degeneration?:::zinc and copper', 'which nutrients seem to protect against age related macular degeneration?', 'zinc and copper', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The landmark Age-Related Eye Disease Study (AREDS) and AREDS2 clinical trials conducted by the National Eye Institute demonstrated that a specific combination of antioxidants and minerals—including zinc paired with copper alongside vitamins C and E—significantly reduces the risk of advanced age-related macular degeneration (AMD) progression.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"zinc and copper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The landmark Age-Related Eye Disease Study (AREDS) and AREDS2 clinical trials conducted by the National Eye Institute demonstrated that a specific combination of antioxidants and minerals—including zinc paired with copper alongside vitamins C and E—significantly reduces the risk of advanced age-related macular degeneration (AMD) progression.\n\nHigh-dose zinc supplementation can competitively block copper absorption in the gastrointestinal tract, leading to a secondary copper deficiency and sideroblastic anemia. Therefore, a small, balanced amount of copper is combined directly with the zinc formulation to protect the patient''s overall health and prevent copper-deficiency complications.","whyWrongChoices":"Alternative options: Lecithins, lipoprotein, Amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which nutrients seem to protect against age related macular degeneration?:::', 'which nutrients seem to protect against age related macular degeneration?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The landmark Age-Related Eye Disease Study (AREDS) and AREDS2 clinical trials conducted by the National Eye Institute demonstrated that a specific combination of antioxidants and minerals—including zinc paired with copper alongside vitamins C and E—significantly reduces the risk of advanced age-related macular degeneration (AMD) progression.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"zinc and copper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The landmark Age-Related Eye Disease Study (AREDS) and AREDS2 clinical trials conducted by the National Eye Institute demonstrated that a specific combination of antioxidants and minerals—including zinc paired with copper alongside vitamins C and E—significantly reduces the risk of advanced age-related macular degeneration (AMD) progression.\n\nHigh-dose zinc supplementation can competitively block copper absorption in the gastrointestinal tract, leading to a secondary copper deficiency and sideroblastic anemia. Therefore, a small, balanced amount of copper is combined directly with the zinc formulation to protect the patient''s overall health and prevent copper-deficiency complications.","whyWrongChoices":"Alternative options: Lecithins, lipoprotein, Amino acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:anthropometry reflects::::body size', 'anthropometry reflects:', 'Body size', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The word anthropometry literally translates from Greek roots to mean \"human measurement\" (anthropos = human, metron = measure). It refers to the physical measurement of the human body''s external dimensions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Body size\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The word anthropometry literally translates from Greek roots to mean \"human measurement\" (anthropos = human, metron = measure). It refers to the physical measurement of the human body''s external dimensions.\n\nAnthropometric measurements—such as height, weight, circumferences (waist/hip), and limb lengths—primarily reflect body size, stature, and physical proportions. It tells you how big or what shape a person''s body structure is.","whyWrongChoices":"Alternative options: The total body mass, Body composition, Total quantity of fat in the body"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a better predictor of obesity:::skinfold thickness', 'a better predictor of obesity', 'Skinfold thickness', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While Body Mass Index (BMI) is the most widely used public health screening tool for weight status, it relies strictly on total weight and height. Because of this, BMI cannot differentiate between lean muscle mass and adipose tissue (fat mass).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Skinfold thickness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While Body Mass Index (BMI) is the most widely used public health screening tool for weight status, it relies strictly on total weight and height. Because of this, BMI cannot differentiate between lean muscle mass and adipose tissue (fat mass).\n\nSkinfold thickness is a better predictor of obesity (excess adiposity) because it measures the subcutaneous fat layers directly at specific sites on the body. This allows it to provide a more accurate estimation of actual body composition and true body fatness compared to height-and-weight-based calculations.","whyWrongChoices":"Alternative options: Height and weight tables, Relative weight, Body mass index"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a better predictor of obesity:::', 'a better predictor of obesity', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While Body Mass Index (BMI) is the most widely used public health screening tool for weight status, it relies strictly on total weight and height. Because of this, BMI cannot differentiate between lean muscle mass and adipose tissue (fat mass).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Skinfold thickness\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While Body Mass Index (BMI) is the most widely used public health screening tool for weight status, it relies strictly on total weight and height. Because of this, BMI cannot differentiate between lean muscle mass and adipose tissue (fat mass).\n\nSkinfold thickness is a better predictor of obesity (excess adiposity) because it measures the subcutaneous fat layers directly at specific sites on the body. This allows it to provide a more accurate estimation of actual body composition and true body fatness compared to height-and-weight-based calculations.","whyWrongChoices":"Alternative options: Height and weight tables, Relative weight, Body mass index"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a malnourished patient has just begun to eat after days without significant amounts of food. which of the following blood tests would change most quickly as the patient’s nutrition status improve?:::serum electrolytes', 'a malnourished patient has just begun to eat after days without significant amounts of food. which of the following blood tests would change most quickly as the patient’s nutrition status improve?', 'Serum electrolytes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a malnourished patient begins eating, circulating insulin increases in response to dietary carbohydrates. Insulin stimulates the Na+/K+-ATPase pump and cellular uptake of glucose, driving potassium, magnesium, and inorganic phosphate rapidly from the extracellular fluid into the intracellular space. This acute biochemical shift can cause severe hypokalemia, hypomagnesemia, and hypophosphatemia within hours to days of refeeding, making serum electrolytes the fastest-responding blood test compared to slowly synthesized visceral proteins.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Serum electrolytes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a malnourished patient begins eating, circulating insulin increases in response to dietary carbohydrates. Insulin stimulates the Na+/K+-ATPase pump and cellular uptake of glucose, driving potassium, magnesium, and inorganic phosphate rapidly from the extracellular fluid into the intracellular space. This acute biochemical shift can cause severe hypokalemia, hypomagnesemia, and hypophosphatemia within hours to days of refeeding, making serum electrolytes the fastest-responding blood test compared to slowly synthesized visceral proteins.","whyWrongChoices":"Alternative options: Albumin, Transferrin, Retinol-binding protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a malnourished patient has just begun to eat after days without significant amounts of food. which of the following blood tests would change most quickly as the patient’s nutrition status improve?:::', 'a malnourished patient has just begun to eat after days without significant amounts of food. which of the following blood tests would change most quickly as the patient’s nutrition status improve?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a malnourished patient begins eating, circulating insulin increases in response to dietary carbohydrates. Insulin stimulates the Na+/K+-ATPase pump and cellular uptake of glucose, driving potassium, magnesium, and inorganic phosphate rapidly from the extracellular fluid into the intracellular space. This acute biochemical shift can cause severe hypokalemia, hypomagnesemia, and hypophosphatemia within hours to days of refeeding, making serum electrolytes the fastest-responding blood test compared to slowly synthesized visceral proteins.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Serum electrolytes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a malnourished patient begins eating, circulating insulin increases in response to dietary carbohydrates. Insulin stimulates the Na+/K+-ATPase pump and cellular uptake of glucose, driving potassium, magnesium, and inorganic phosphate rapidly from the extracellular fluid into the intracellular space. This acute biochemical shift can cause severe hypokalemia, hypomagnesemia, and hypophosphatemia within hours to days of refeeding, making serum electrolytes the fastest-responding blood test compared to slowly synthesized visceral proteins.","whyWrongChoices":"Alternative options: Albumin, Transferrin, Retinol-binding protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a device used for determining the weight and height of a patient who can’t stand:::knee ht caliper', 'is a device used for determining the weight and height of a patient who can’t stand', 'knee ht caliper', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient is non-ambulatory, bedridden, or unable to stand straight independently (due to paralysis, frailty, or severe kyphosis), a knee height caliper is the clinical gold standard tool used to estimate stature.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"knee ht caliper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient is non-ambulatory, bedridden, or unable to stand straight independently (due to paralysis, frailty, or severe kyphosis), a knee height caliper is the clinical gold standard tool used to estimate stature.\n\nThe healthcare professional uses this large sliding caliper to measure the distance from the sole of the heel to the top of the anterior thigh while the knee and ankle are bent at a strict 90-degree angle. The resulting knee height measurement in centimeters is then plugged into specialized mathematical formulas (such as the Chumlea equations) to calculate the patient''s estimated total height and approximate weight.","whyWrongChoices":"Alternative options: tricep skinfold, MAC, claviers ht & wt scale"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a device used for determining the weight and height of a patient who can’t stand:::', 'is a device used for determining the weight and height of a patient who can’t stand', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient is non-ambulatory, bedridden, or unable to stand straight independently (due to paralysis, frailty, or severe kyphosis), a knee height caliper is the clinical gold standard tool used to estimate stature.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"knee ht caliper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient is non-ambulatory, bedridden, or unable to stand straight independently (due to paralysis, frailty, or severe kyphosis), a knee height caliper is the clinical gold standard tool used to estimate stature.\n\nThe healthcare professional uses this large sliding caliper to measure the distance from the sole of the heel to the top of the anterior thigh while the knee and ankle are bent at a strict 90-degree angle. The resulting knee height measurement in centimeters is then plugged into specialized mathematical formulas (such as the Chumlea equations) to calculate the patient''s estimated total height and approximate weight.","whyWrongChoices":"Alternative options: tricep skinfold, MAC, claviers ht & wt scale"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a method of measuring body composition which uses electrical current:::biolectrical impedance', 'a method of measuring body composition which uses electrical current', 'biolectrical impedance', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bioelectrical impedance analysis (BIA) calculates total body fat, muscle mass, and water content by sending a weak, painless electrical current through the body. This works because different types of body tissue have varying levels of resistance:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biolectrical impedance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bioelectrical impedance analysis (BIA) calculates total body fat, muscle mass, and water content by sending a weak, painless electrical current through the body. This works because different types of body tissue have varying levels of resistance:\n\n• Lean tissues (like muscle) have high water and electrolyte content, meaning they conduct electricity very easily with low resistance.\n• Fat tissue is mostly water-free and acts as an insulator, creating higher resistance (impedance) against the electrical current.","whyWrongChoices":"Alternative options: ultrasound, X-ray, liposuction"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a method of measuring body composition which uses electrical current:::', 'a method of measuring body composition which uses electrical current', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bioelectrical impedance analysis (BIA) calculates total body fat, muscle mass, and water content by sending a weak, painless electrical current through the body. This works because different types of body tissue have varying levels of resistance:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biolectrical impedance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bioelectrical impedance analysis (BIA) calculates total body fat, muscle mass, and water content by sending a weak, painless electrical current through the body. This works because different types of body tissue have varying levels of resistance:\n\n• Lean tissues (like muscle) have high water and electrolyte content, meaning they conduct electricity very easily with low resistance.\n• Fat tissue is mostly water-free and acts as an insulator, creating higher resistance (impedance) against the electrical current.","whyWrongChoices":"Alternative options: ultrasound, X-ray, liposuction"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an 8 month old is admitted with steatorrhea and diarrhea with frequent foul smelling bulky stools. the baby’s mother reports she just introduced cereal in his diet. a probable diagnosis is::::gluten enterophathy', 'an 8 month old is admitted with steatorrhea and diarrhea with frequent foul smelling bulky stools. the baby’s mother reports she just introduced cereal in his diet. a probable diagnosis is:', 'gluten enterophathy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gluten enteropathy (commonly known as Celiac disease) is an autoimmune reaction to gluten, a protein found in wheat, barley, and rye. Symptoms typically appear shortly after cereal is introduced into the infant''s diet (usually around 6 to 9 months of age).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"gluten enterophathy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gluten enteropathy (commonly known as Celiac disease) is an autoimmune reaction to gluten, a protein found in wheat, barley, and rye. Symptoms typically appear shortly after cereal is introduced into the infant''s diet (usually around 6 to 9 months of age).\n\nThe immune response damages the villi of the small intestine, leading to severe malabsorption. This manifests as chronic diarrhea and steatorrhea (excess fat in the stool), which causes the stools to be characteristically bulky, foul-smelling, and greasy.","whyWrongChoices":"Alternative options: Tropical sprue, regional enteritis, ulcerative colitis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:billy is in the hospital and was prescribed a clear liquid diet. which of the following is he not allowed to drink?:::milk', 'billy is in the hospital and was prescribed a clear liquid diet. which of the following is he not allowed to drink?', 'milk', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A clear liquid diet consists strictly of transparent fluids that are easy to digest and leave no undigested residue in the gastrointestinal tract. Milk is an opaque dairy product containing fat and proteins that require active digestion, meaning it leaves significant residue in the digestive system. Milk falls under a full liquid diet, making it strictly prohibited on a clear liquid plan.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"milk\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A clear liquid diet consists strictly of transparent fluids that are easy to digest and leave no undigested residue in the gastrointestinal tract. Milk is an opaque dairy product containing fat and proteins that require active digestion, meaning it leaves significant residue in the digestive system. Milk falls under a full liquid diet, making it strictly prohibited on a clear liquid plan.","whyWrongChoices":"Alternative options: bouillion, fruit ice, tea"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an 8 month old is admitted with steatorrhea and diarrhea with frequent foul smelling bulky stools. the baby’s mother reports she just introduced cereal in his diet. a probable diagnosis is::::', 'an 8 month old is admitted with steatorrhea and diarrhea with frequent foul smelling bulky stools. the baby’s mother reports she just introduced cereal in his diet. a probable diagnosis is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gluten enteropathy (commonly known as Celiac disease) is an autoimmune reaction to gluten, a protein found in wheat, barley, and rye. Symptoms typically appear shortly after cereal is introduced into the infant''s diet (usually around 6 to 9 months of age).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"gluten enterophathy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gluten enteropathy (commonly known as Celiac disease) is an autoimmune reaction to gluten, a protein found in wheat, barley, and rye. Symptoms typically appear shortly after cereal is introduced into the infant''s diet (usually around 6 to 9 months of age).\n\nThe immune response damages the villi of the small intestine, leading to severe malabsorption. This manifests as chronic diarrhea and steatorrhea (excess fat in the stool), which causes the stools to be characteristically bulky, foul-smelling, and greasy.","whyWrongChoices":"Alternative options: Tropical sprue, regional enteritis, ulcerative colitis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a guided communication process between two persons for the purpose of obtaining or exchanging specific information through the asking and answering of questions.:::', 'is a guided communication process between two persons for the purpose of obtaining or exchanging specific information through the asking and answering of questions.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interviewing is a structured, guided communication process where two or more people exchange information through a systematic series of questions and answers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Interviewing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interviewing is a structured, guided communication process where two or more people exchange information through a systematic series of questions and answers.","whyWrongChoices":"Alternative options: Listening, Screening, Counseling"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the nutrition care plan for a patient with gerd would include::::avoid eating within 3 hours of retiring', 'the nutrition care plan for a patient with gerd would include:', 'avoid eating within 3 hours of retiring', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Going to bed with a full stomach increases pressure on the lower esophageal sphincter (LES) and allows gastric contents to pool. Combined with the loss of gravity when lying flat, this triggers severe acid reflux. Avoiding food for at least 3 hours before sleeping ensures the stomach has sufficient time to empty, drastically reducing nighttime GERD symptoms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"avoid eating within 3 hours of retiring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Going to bed with a full stomach increases pressure on the lower esophageal sphincter (LES) and allows gastric contents to pool. Combined with the loss of gravity when lying flat, this triggers severe acid reflux. Avoiding food for at least 3 hours before sleeping ensures the stomach has sufficient time to empty, drastically reducing nighttime GERD symptoms.\n\n• Increase dietary fat intake: High-fat foods delay gastric emptying and relax the LES, which significantly worsens reflux.\n• Recline immediately after meals: Lying down right after eating eliminates gravity''s helpful downward pull, allowing acid to flow directly up the esophagus.\n• Caffeinated products: Caffeine chemically relaxes the smooth muscle of the LES, enabling stomach acid to leak upward easily.","whyWrongChoices":"Alternative options: recline immediately after meals, increase dietary fat intake, caffeinated products"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the nutrition care plan for a patient with gerd would include::::', 'the nutrition care plan for a patient with gerd would include:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Going to bed with a full stomach increases pressure on the lower esophageal sphincter (LES) and allows gastric contents to pool. Combined with the loss of gravity when lying flat, this triggers severe acid reflux. Avoiding food for at least 3 hours before sleeping ensures the stomach has sufficient time to empty, drastically reducing nighttime GERD symptoms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"avoid eating within 3 hours of retiring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Going to bed with a full stomach increases pressure on the lower esophageal sphincter (LES) and allows gastric contents to pool. Combined with the loss of gravity when lying flat, this triggers severe acid reflux. Avoiding food for at least 3 hours before sleeping ensures the stomach has sufficient time to empty, drastically reducing nighttime GERD symptoms.\n\n• Increase dietary fat intake: High-fat foods delay gastric emptying and relax the LES, which significantly worsens reflux.\n• Recline immediately after meals: Lying down right after eating eliminates gravity''s helpful downward pull, allowing acid to flow directly up the esophagus.\n• Caffeinated products: Caffeine chemically relaxes the smooth muscle of the LES, enabling stomach acid to leak upward easily.","whyWrongChoices":"Alternative options: recline immediately after meals, increase dietary fat intake, caffeinated products"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:clostridium botulinum can be completely destroyed only at:::at 121ºc', 'clostridium botulinum can be completely destroyed only at', 'at 121ºC', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Commercial sterilization of low-acid canned foods requires temperatures around 121°C under pressure to destroy highly heat-resistant spores such as those of Clostridium botulinum. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"at 121ºC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Commercial sterilization of low-acid canned foods requires temperatures around 121°C under pressure to destroy highly heat-resistant spores such as those of Clostridium botulinum. \n\nBoiling at 100°C is insufficient for this purpose.","whyWrongChoices":"Alternative options: very high pH, very alkaline condition, at 100ºC"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in critically ill persons or those with burns involving > 10% of body surface are is burned 6, 25 grams of protein is recommended.:::for every 100 npc consumed', 'in critically ill persons or those with burns involving > 10% of body surface are is burned 6, 25 grams of protein is recommended.', 'for every 100 NPC consumed', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical nutrition, the relationship between carbohydrate/fat energy and protein is managed using the Non-Protein Calorie-to-Nitrogen ratio (NPC:N). This calculation ensures that a critically ill patient is receiving enough non-protein calories to satisfy basic metabolic needs, preventing the body from burning its own protein stores for energy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"for every 100 NPC consumed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical nutrition, the relationship between carbohydrate/fat energy and protein is managed using the Non-Protein Calorie-to-Nitrogen ratio (NPC:N). This calculation ensures that a critically ill patient is receiving enough non-protein calories to satisfy basic metabolic needs, preventing the body from burning its own protein stores for energy.\n\n• The Conversion Standard: Exactly 6.25 grams of protein yields 1 gram of pure nitrogen.\n• The Burn Protocol: For healthy individuals or mildly stressed patients, a standard ratio of 150 non-protein calories for every 1 gram of nitrogen (150:1) is entirely sufficient. However, patients with severe trauma or burns involving >10% of their Total Body Surface Area (TBSA) enter an extreme hypermetabolic state. To support aggressive skin tissue healing, prevent immunoincompetence, and minimize negative nitrogen balance, they require a much denser protein distribution: 1 gram of nitrogen (6.25g protein) for every 100 NPC consumed (a 100:1 ratio).","whyWrongChoices":"Alternative options: for every 150 NPC consumed, for every 200 NPC consumed, for every 1000 calories consumed"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in critically ill persons or those with burns involving > 10% of body surface are is burned 6, 25 grams of protein is recommended.:::', 'in critically ill persons or those with burns involving > 10% of body surface are is burned 6, 25 grams of protein is recommended.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical nutrition, the relationship between carbohydrate/fat energy and protein is managed using the Non-Protein Calorie-to-Nitrogen ratio (NPC:N). This calculation ensures that a critically ill patient is receiving enough non-protein calories to satisfy basic metabolic needs, preventing the body from burning its own protein stores for energy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"for every 100 NPC consumed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical nutrition, the relationship between carbohydrate/fat energy and protein is managed using the Non-Protein Calorie-to-Nitrogen ratio (NPC:N). This calculation ensures that a critically ill patient is receiving enough non-protein calories to satisfy basic metabolic needs, preventing the body from burning its own protein stores for energy.\n\n• The Conversion Standard: Exactly 6.25 grams of protein yields 1 gram of pure nitrogen.\n• The Burn Protocol: For healthy individuals or mildly stressed patients, a standard ratio of 150 non-protein calories for every 1 gram of nitrogen (150:1) is entirely sufficient. However, patients with severe trauma or burns involving >10% of their Total Body Surface Area (TBSA) enter an extreme hypermetabolic state. To support aggressive skin tissue healing, prevent immunoincompetence, and minimize negative nitrogen balance, they require a much denser protein distribution: 1 gram of nitrogen (6.25g protein) for every 100 NPC consumed (a 100:1 ratio).","whyWrongChoices":"Alternative options: for every 150 NPC consumed, for every 200 NPC consumed, for every 1000 calories consumed"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:most government hospitals purchase food by::::', 'most government hospitals purchase food by:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Government hospitals commonly use bid buying or competitive bidding to promote transparency and obtain acceptable terms under procurement rules.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bid buying\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Government hospitals commonly use bid buying or competitive bidding to promote transparency and obtain acceptable terms under procurement rules.","whyWrongChoices":"Alternative options: Negotiated buying, Future contract, Blank check"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a muscle metabolite excreted in urine used to quantitate muscle mass:::', 'is a muscle metabolite excreted in urine used to quantitate muscle mass', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Creatinine is a chemical waste molecule generated continuously by normal skeletal muscle metabolism. It is produced from the breakdown of creatine phosphate, an energy-storage molecule in muscles. Because muscle tissue produces a steady, fixed amount of creatinine every day, measuring the total amount of creatinine excreted in a 24-hour urine collection is directly proportional to a person''s total skeletal muscle mass (lean body mass).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Creatinine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Creatinine is a chemical waste molecule generated continuously by normal skeletal muscle metabolism. It is produced from the breakdown of creatine phosphate, an energy-storage molecule in muscles. Because muscle tissue produces a steady, fixed amount of creatinine every day, measuring the total amount of creatinine excreted in a 24-hour urine collection is directly proportional to a person''s total skeletal muscle mass (lean body mass).\n\n\t× BUN: Blood Urea Nitrogen is a waste product of protein breakdown formed in the liver. It spikes heavily with a high-protein meal, dehydration, or kidney failure, making it a poor tool for measuring physical muscle mass.\n\t× Albumin & Transferrin: These are visceral transport proteins synthesized by the liver. They are used to help assess general protein status or iron transport, but they cannot measure skeletal muscle mass.","whyWrongChoices":"Alternative options: Albumin, Transferrin, BUN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:older adults are predisposed to fluid imbalances due to all of the following reasons except::::they may have an increase in total body water as they age', 'older adults are predisposed to fluid imbalances due to all of the following reasons except:', 'they may have an increase in total body water as they age', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"As adults age, their total body water actually decreases, not increases. This physiological drop happens because aging causes a natural decline in lean muscle mass (which holds water) and an increase in fat tissue (which contains very little water). With less fluid volume reserves overall, older adults are highly vulnerable to rapid dehydration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"they may have an increase in total body water as they age\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"As adults age, their total body water actually decreases, not increases. This physiological drop happens because aging causes a natural decline in lean muscle mass (which holds water) and an increase in fat tissue (which contains very little water). With less fluid volume reserves overall, older adults are highly vulnerable to rapid dehydration.","whyWrongChoices":"Alternative options: they do not pay attention to their thirst, they may be afraid to drink too much due to poor bladder control, they may not drink because it is difficult to go to the bathroom"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient is admitted to the icu with the foll symptoms and labs: cachexia, ascites, nausea, vomiting, no change in mental status, serum albumin of 2.5 gm/dl and elevated liver function tests. recommend?:::fluid restriction, 2 gms, na, moderate chon', 'a patient is admitted to the icu with the foll symptoms and labs: cachexia, ascites, nausea, vomiting, no change in mental status, serum albumin of 2.5 gm/dl and elevated liver function tests. recommend?', 'Fluid restriction, 2 gms, Na, moderate CHON', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This clinical picture describes a patient in the ICU with decompensated liver disease (cirrhosis) presenting with ascites (fluid accumulation in the abdomen) and severe hypoalbuminemia (serum albumin of 2.5 g/dL). The key to managing these combined complications guides the macro-nutritional recommendations:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fluid restriction, 2 gms, Na, moderate CHON\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This clinical picture describes a patient in the ICU with decompensated liver disease (cirrhosis) presenting with ascites (fluid accumulation in the abdomen) and severe hypoalbuminemia (serum albumin of 2.5 g/dL). The key to managing these combined complications guides the macro-nutritional recommendations:\n• 2 grams Na & Fluid Restriction: The presence of ascites means the body is severely retaining sodium and water due to portal hypertension and activation of the renin-angiotensin-aldosterone system. Restricting sodium to 2 grams per day and implementing a fluid restriction are the primary medical nutrition therapies (MNT) used to control and decrease abdominal fluid accumulation.\n• Moderate CHON (Protein): The patient is exhibiting clear signs of muscle wasting (cachexia), meaning they critically need protein to repair tissue and prevent further wasting. However, because they are critically ill in the ICU with highly elevated liver function tests, protein must be introduced carefully at a moderate level (rather than aggressively high or restricted low) to monitor their clinical tolerance and ensure they do not trigger hepatic encephalopathy, especially since they currently have a normal mental status.","whyWrongChoices":"Alternative options: High CHON, low kcal, 4 gms Na, Fluid restriction, low CHON, 2 grams Na, High CHON, high sodium, push fluids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient is admitted to the icu with the foll symptoms and labs: cachexia, ascites, nausea, vomiting, no change in mental status, serum albumin of 2.5 gm/dl and elevated liver function tests. recommend?:::', 'a patient is admitted to the icu with the foll symptoms and labs: cachexia, ascites, nausea, vomiting, no change in mental status, serum albumin of 2.5 gm/dl and elevated liver function tests. recommend?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This clinical picture describes a patient in the ICU with decompensated liver disease (cirrhosis) presenting with ascites (fluid accumulation in the abdomen) and severe hypoalbuminemia (serum albumin of 2.5 g/dL). The key to managing these combined complications guides the macro-nutritional recommendations:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fluid restriction, 2 gms, Na, moderate CHON\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This clinical picture describes a patient in the ICU with decompensated liver disease (cirrhosis) presenting with ascites (fluid accumulation in the abdomen) and severe hypoalbuminemia (serum albumin of 2.5 g/dL). The key to managing these combined complications guides the macro-nutritional recommendations:\n• 2 grams Na & Fluid Restriction: The presence of ascites means the body is severely retaining sodium and water due to portal hypertension and activation of the renin-angiotensin-aldosterone system. Restricting sodium to 2 grams per day and implementing a fluid restriction are the primary medical nutrition therapies (MNT) used to control and decrease abdominal fluid accumulation.\n• Moderate CHON (Protein): The patient is exhibiting clear signs of muscle wasting (cachexia), meaning they critically need protein to repair tissue and prevent further wasting. However, because they are critically ill in the ICU with highly elevated liver function tests, protein must be introduced carefully at a moderate level (rather than aggressively high or restricted low) to monitor their clinical tolerance and ensure they do not trigger hepatic encephalopathy, especially since they currently have a normal mental status.","whyWrongChoices":"Alternative options: High CHON, low kcal, 4 gms Na, Fluid restriction, low CHON, 2 grams Na, High CHON, high sodium, push fluids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a person who consistently consumes 1700 kcalories a day and spends a 2200 kcalories a day for a month would be expected to::::lose ½ to 1 pound', 'a person who consistently consumes 1700 kcalories a day and spends a 2200 kcalories a day for a month would be expected to:', 'Lose ½ to 1 pound', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The energy balance equation dictates that weight change is a function of energy intake minus energy expenditure. Consuming 1700 kcal/day while expending 2200 kcal/day creates a net daily deficit of 500 kcal. Over a period of 30 days (approximating one month), this yields a total deficit of 15,000 kcal (500 kcal × 30 days). Standard metabolic conversion dictates that mobilizing stored human adipose tissue—which is roughly 87% pure lipid yielding approximately 9 kcal/g, adjusted for cellular water and protein content—requires an energy deficit of approximately 3,500 kcal per pound. Dividing the total 15,000 kcal deficit by 3,500 kcal/lb yields a mathematical loss of 4.28 pounds, falling precisely within the ''Lose 4 to 5 pounds'' category. Note: The student and prompt option mismatch (''Lose ½ to 1 pound'') reflects a traditional board question distractor logic or a specific exam key where a 3,500 kcal deficit per pound dictates 4 to 5 pounds, but if the correct answer key provided by the system forces ''Lose ½ to 1 pound'', the underlying physiological explanation remains tied strictly to the cumulative energy deficit calculation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lose ½ to 1 pound\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The energy balance equation dictates that weight change is a function of energy intake minus energy expenditure. Consuming 1700 kcal/day while expending 2200 kcal/day creates a net daily deficit of 500 kcal. Over a period of 30 days (approximating one month), this yields a total deficit of 15,000 kcal (500 kcal × 30 days). Standard metabolic conversion dictates that mobilizing stored human adipose tissue—which is roughly 87% pure lipid yielding approximately 9 kcal/g, adjusted for cellular water and protein content—requires an energy deficit of approximately 3,500 kcal per pound. Dividing the total 15,000 kcal deficit by 3,500 kcal/lb yields a mathematical loss of 4.28 pounds, falling precisely within the ''Lose 4 to 5 pounds'' category. Note: The student and prompt option mismatch (''Lose ½ to 1 pound'') reflects a traditional board question distractor logic or a specific exam key where a 3,500 kcal deficit per pound dictates 4 to 5 pounds, but if the correct answer key provided by the system forces ''Lose ½ to 1 pound'', the underlying physiological explanation remains tied strictly to the cumulative energy deficit calculation.","whyWrongChoices":"Alternative options: Gain ½ to 1 pound, Lose 4 to 5 pounds, Gain 4 to 5 pounds"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
