INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:mr. smith experiences loss of appetite, difficulty swallowing, and mouth pain as a consequence of illness. mr. smith is at risk of malnutrition due to::::reduced food intake', 'mr. smith experiences loss of appetite, difficulty swallowing, and mouth pain as a consequence of illness. mr. smith is at risk of malnutrition due to:', 'Reduced food intake', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mr. Smith’s symptoms—loss of appetite (anorexia), difficulty swallowing (dysphagia), and mouth pain—are all primary physical and sensory barriers that prevent him from mechanically eating. Because he cannot comfortably consume meals, his overall volume of nutritional consumption drops. This directly places him at risk of starvation-related malnutrition due to simple reduced food intake.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduced food intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mr. Smith’s symptoms—loss of appetite (anorexia), difficulty swallowing (dysphagia), and mouth pain—are all primary physical and sensory barriers that prevent him from mechanically eating. Because he cannot comfortably consume meals, his overall volume of nutritional consumption drops. This directly places him at risk of starvation-related malnutrition due to simple reduced food intake.","whyWrongChoices":"Alternative options: Altered metabolism, Altered excretion of nutrients, Altered digestion and absorption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the recommended water consumption for adult is::::1l/1000 kcal consumed', 'the recommended water consumption for adult is:', '1L/1000 kcal consumed', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The standard nutritional recommendation for fluid intake is 1.0 to 1.5 milliliters (mL) of water for every 1 kilocalorie (kcal) of energy consumed or expended.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1L/1000 kcal consumed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The standard nutritional recommendation for fluid intake is 1.0 to 1.5 milliliters (mL) of water for every 1 kilocalorie (kcal) of energy consumed or expended.\n\nSince 1,000 mL is equal to 1 Liter (L), an adult requires approximately 1 L of total water per 1,000 kcal to efficiently metabolize food, process cellular waste, and maintain standard hydration balance. For example, a person eating a standard 2,000-calorie daily diet would need about 2 L of fluid.","whyWrongChoices":"Alternative options: 1 L/500 kcal consumed, 0.5 L/1000 kcal consumed, 2L/1000 kcal consumed"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:mr. smith experiences loss of appetite, difficulty swallowing, and mouth pain as a consequence of illness. mr. smith is at risk of malnutrition due to::::', 'mr. smith experiences loss of appetite, difficulty swallowing, and mouth pain as a consequence of illness. mr. smith is at risk of malnutrition due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mr. Smith’s symptoms—loss of appetite (anorexia), difficulty swallowing (dysphagia), and mouth pain—are all primary physical and sensory barriers that prevent him from mechanically eating. Because he cannot comfortably consume meals, his overall volume of nutritional consumption drops. This directly places him at risk of starvation-related malnutrition due to simple reduced food intake.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reduced food intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mr. Smith’s symptoms—loss of appetite (anorexia), difficulty swallowing (dysphagia), and mouth pain—are all primary physical and sensory barriers that prevent him from mechanically eating. Because he cannot comfortably consume meals, his overall volume of nutritional consumption drops. This directly places him at risk of starvation-related malnutrition due to simple reduced food intake.","whyWrongChoices":"Alternative options: Altered metabolism, Altered excretion of nutrients, Altered digestion and absorption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a pediatric dietitian suspects that a 13 year old girl has marasmus related to anorexia nervosa. the most effective method to validate this suspicion would be to obtain::::anthropometrics', 'a pediatric dietitian suspects that a 13 year old girl has marasmus related to anorexia nervosa. the most effective method to validate this suspicion would be to obtain:', 'anthropometrics', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Marasmus is a severe form of malnutrition characterized by significant wasting of both body fat and lean muscle mass due to a chronic deficit of total energy (calories).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"anthropometrics\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Marasmus is a severe form of malnutrition characterized by significant wasting of both body fat and lean muscle mass due to a chronic deficit of total energy (calories).\n\n• The hallmark of marasmus is a \"skin and bones\" appearance. Anthropometrics—specifically tracking rapid weight loss, an extremely low Body Mass Index (BMI)-for-age percentile, and reduced mid-upper arm circumference (MUAC) or skinfold thickness—directly measure this severe subcutaneous fat depletion and muscle wasting.\n• While a psychiatric evaluation confirms the psychological diagnosis of anorexia nervosa, anthropometric measurement is the primary physical method used to clinically validate the presence and severity of marasmus itself.","whyWrongChoices":"Alternative options: a diet diary from the patient, biochemical indicators of visceral protein status, a psychiatric evaluation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a pediatric dietitian suspects that a 13 year old girl has marasmus related to anorexia nervosa. the most effective method to validate this suspicion would be to obtain::::', 'a pediatric dietitian suspects that a 13 year old girl has marasmus related to anorexia nervosa. the most effective method to validate this suspicion would be to obtain:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Marasmus is a severe form of malnutrition characterized by significant wasting of both body fat and lean muscle mass due to a chronic deficit of total energy (calories).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"anthropometrics\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Marasmus is a severe form of malnutrition characterized by significant wasting of both body fat and lean muscle mass due to a chronic deficit of total energy (calories).\n\n• The hallmark of marasmus is a \"skin and bones\" appearance. Anthropometrics—specifically tracking rapid weight loss, an extremely low Body Mass Index (BMI)-for-age percentile, and reduced mid-upper arm circumference (MUAC) or skinfold thickness—directly measure this severe subcutaneous fat depletion and muscle wasting.\n• While a psychiatric evaluation confirms the psychological diagnosis of anorexia nervosa, anthropometric measurement is the primary physical method used to clinically validate the presence and severity of marasmus itself.","whyWrongChoices":"Alternative options: a diet diary from the patient, biochemical indicators of visceral protein status, a psychiatric evaluation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient suspected of having pancreatic lipase insufficiency has a fecal fat test that shows that he had 15 grams of fat remaining in his feces. what conclusion can be drawn?:::the test shows an abnormally high amount of fat in the feces, but more disease-specific tests are needed before a diagnostic can be made', 'a patient suspected of having pancreatic lipase insufficiency has a fecal fat test that shows that he had 15 grams of fat remaining in his feces. what conclusion can be drawn?', 'the test shows an abnormally high amount of fat in the feces, but more disease-specific tests are needed before a diagnostic can be made', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a healthy adult on a standard diet, a normal quantitative fecal fat level is less than 7 grams per 24 hours. A value of 15 grams clearly demonstrates fat malabsorption (steatorrhea).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the test shows an abnormally high amount of fat in the feces, but more disease-specific tests are needed before a diagnostic can be made\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a healthy adult on a standard diet, a normal quantitative fecal fat level is less than 7 grams per 24 hours. A value of 15 grams clearly demonstrates fat malabsorption (steatorrhea).\n\nWhile the patient might have pancreatic lipase insufficiency, a high fecal fat level alone cannot confirm the specific cause. Fat malabsorption can be triggered by multiple conditions completely unrelated to the pancreas, such as small intestinal diseases (e.g., Celiac disease, Crohn''s disease) or biliary/liver dysfunction. Therefore, more disease-specific tests (such as a fecal elastase test or a secretin stimulation test) are required to pinpoint the pancreas as the culprit.","whyWrongChoices":"Alternative options: the patient has pancreatic lipase insufficiency, the patient has no fat malabsorption, the patient has protein energy malnutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient suspected of having pancreatic lipase insufficiency has a fecal fat test that shows that he had 15 grams of fat remaining in his feces. what conclusion can be drawn?:::', 'a patient suspected of having pancreatic lipase insufficiency has a fecal fat test that shows that he had 15 grams of fat remaining in his feces. what conclusion can be drawn?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a healthy adult on a standard diet, a normal quantitative fecal fat level is less than 7 grams per 24 hours. A value of 15 grams clearly demonstrates fat malabsorption (steatorrhea).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the test shows an abnormally high amount of fat in the feces, but more disease-specific tests are needed before a diagnostic can be made\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a healthy adult on a standard diet, a normal quantitative fecal fat level is less than 7 grams per 24 hours. A value of 15 grams clearly demonstrates fat malabsorption (steatorrhea).\n\nWhile the patient might have pancreatic lipase insufficiency, a high fecal fat level alone cannot confirm the specific cause. Fat malabsorption can be triggered by multiple conditions completely unrelated to the pancreas, such as small intestinal diseases (e.g., Celiac disease, Crohn''s disease) or biliary/liver dysfunction. Therefore, more disease-specific tests (such as a fecal elastase test or a secretin stimulation test) are required to pinpoint the pancreas as the culprit.","whyWrongChoices":"Alternative options: the patient has pancreatic lipase insufficiency, the patient has no fat malabsorption, the patient has protein energy malnutrition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a child with cystic fibrosis may develop essential fatty acid deficiency due to::::the reduced quantity of digestive enzymes released from the pancreas into the small intestine', 'a child with cystic fibrosis may develop essential fatty acid deficiency due to:', 'the reduced quantity of digestive enzymes released from the pancreas into the small intestine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In cystic fibrosis (CF), a defective CFTR protein leads to the production of thick, sticky mucus throughout the body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the reduced quantity of digestive enzymes released from the pancreas into the small intestine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In cystic fibrosis (CF), a defective CFTR protein leads to the production of thick, sticky mucus throughout the body.\n\n• Pancreatic Insufficiency: This viscous mucus physically blocks the narrow pancreatic ducts, preventing vital pancreatic digestive enzymes (particularly pancreatic lipase) from being released into the duodenum.\n• Lipid Malabsorption: Lipase is entirely responsible for breaking down dietary lipids into absorbable free fatty acids. Without a sufficient quantity of these enzymes in the small intestine, fats cannot be broken down or absorbed, resulting in severe fat malabsorption (steatorrhea).\n• Fatty Acid Deficiency: Because human bodies cannot natively synthesize essential fatty acids (EFAs) like linoleic acid, they must be absorbed from food. The enzyme blockade directly starves the body of these essential lipids, resulting in an EFA deficiency.","whyWrongChoices":"Alternative options: the interaction between aerosol antibiotics and lipid digestion, dyspnea and cough induced vomiting, impaired glucose tolerance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a child with cystic fibrosis may develop essential fatty acid deficiency due to::::', 'a child with cystic fibrosis may develop essential fatty acid deficiency due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In cystic fibrosis (CF), a defective CFTR protein leads to the production of thick, sticky mucus throughout the body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the reduced quantity of digestive enzymes released from the pancreas into the small intestine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In cystic fibrosis (CF), a defective CFTR protein leads to the production of thick, sticky mucus throughout the body.\n\n• Pancreatic Insufficiency: This viscous mucus physically blocks the narrow pancreatic ducts, preventing vital pancreatic digestive enzymes (particularly pancreatic lipase) from being released into the duodenum.\n• Lipid Malabsorption: Lipase is entirely responsible for breaking down dietary lipids into absorbable free fatty acids. Without a sufficient quantity of these enzymes in the small intestine, fats cannot be broken down or absorbed, resulting in severe fat malabsorption (steatorrhea).\n• Fatty Acid Deficiency: Because human bodies cannot natively synthesize essential fatty acids (EFAs) like linoleic acid, they must be absorbed from food. The enzyme blockade directly starves the body of these essential lipids, resulting in an EFA deficiency.","whyWrongChoices":"Alternative options: the interaction between aerosol antibiotics and lipid digestion, dyspnea and cough induced vomiting, impaired glucose tolerance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:one of the most beneficial biochemical techniques for evaluating protein status is::::', 'one of the most beneficial biochemical techniques for evaluating protein status is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitrogen balance is highly regarded as one of the most beneficial techniques for evaluating overall protein status and protein metabolism. Since protein is unique among macronutrients because it contains approximately 16% nitrogen, measuring the amount of nitrogen consumed (via dietary protein intake) versus the amount excreted (via urine, feces, sweat, and wound exudate) provides a direct picture of protein turnover.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nitrogen balance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitrogen balance is highly regarded as one of the most beneficial techniques for evaluating overall protein status and protein metabolism. Since protein is unique among macronutrients because it contains approximately 16% nitrogen, measuring the amount of nitrogen consumed (via dietary protein intake) versus the amount excreted (via urine, feces, sweat, and wound exudate) provides a direct picture of protein turnover.\n\t✓ A positive nitrogen balance indicates tissue growth, healing, or pregnancy (more protein is being built than broken down).\n\t✓ A negative nitrogen balance indicates severe catabolism, starvation, or metabolic stress (the body is breaking down its own muscle tissue for energy).\n\n\t× Total protein: This measures all proteins in the blood (mostly albumin and globulins). It is heavily impacted by fluid shifts, hydration status, and liver or kidney health, making it an unreliable snapshot for overall protein nutriture.\n\t× Blood urea nitrogen: BUN fluctuates quickly based on recent protein consumption, liver processing efficiency, and kidney function rather than chronic tissue protein status.\n\t× Hair analysis: While hair contains protein (keratin), it is not a validated, reliable clinical technique for tracking a patient''s current, acute systemic protein-calorie status.","whyWrongChoices":"Alternative options: blood urea nitrogen, total protein, hair analysis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the recommended water consumption for adult is::::', 'the recommended water consumption for adult is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The standard nutritional recommendation for fluid intake is 1.0 to 1.5 milliliters (mL) of water for every 1 kilocalorie (kcal) of energy consumed or expended.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1L/1000 kcal consumed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The standard nutritional recommendation for fluid intake is 1.0 to 1.5 milliliters (mL) of water for every 1 kilocalorie (kcal) of energy consumed or expended.\n\nSince 1,000 mL is equal to 1 Liter (L), an adult requires approximately 1 L of total water per 1,000 kcal to efficiently metabolize food, process cellular waste, and maintain standard hydration balance. For example, a person eating a standard 2,000-calorie daily diet would need about 2 L of fluid.","whyWrongChoices":"Alternative options: 1 L/500 kcal consumed, 0.5 L/1000 kcal consumed, 2L/1000 kcal consumed"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the passage of product of digestion through the intestinal mucosa into the blood and lymph system.:::absorption', 'the passage of product of digestion through the intestinal mucosa into the blood and lymph system.', 'Absorption', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Absorption is explicitly defined as the physiological process where the end products of digestion pass through the epithelial cells of the intestinal mucosa and enter the blood capillaries (for water-soluble nutrients like amino acids and monosaccharides) or the lymph system via lacteals (for fat-soluble nutrients). This allows essential nutrients to circulate and support tissues throughout the body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Absorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Absorption is explicitly defined as the physiological process where the end products of digestion pass through the epithelial cells of the intestinal mucosa and enter the blood capillaries (for water-soluble nutrients like amino acids and monosaccharides) or the lymph system via lacteals (for fat-soluble nutrients). This allows essential nutrients to circulate and support tissues throughout the body.\n\n• Excretion (or defecation) is the removal and elimination of undigested food residue, metabolic waste products, and fecal matter from the body.\n• Metabolism represents the sum total of all biochemical reactions (anabolism and catabolism) that happen within body cells after nutrients have already been absorbed and delivered.\n• Digestion is purely the mechanical and chemical breakdown of large, complex food polymers into smaller, soluble constituent building blocks. It precedes absorption but does not include the physical movement of nutrients into body fluids.","whyWrongChoices":"Alternative options: Digestion, Excretion, Metabolism"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the passage of product of digestion through the intestinal mucosa into the blood and lymph system.:::', 'the passage of product of digestion through the intestinal mucosa into the blood and lymph system.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Absorption is explicitly defined as the physiological process where the end products of digestion pass through the epithelial cells of the intestinal mucosa and enter the blood capillaries (for water-soluble nutrients like amino acids and monosaccharides) or the lymph system via lacteals (for fat-soluble nutrients). This allows essential nutrients to circulate and support tissues throughout the body.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Absorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Absorption is explicitly defined as the physiological process where the end products of digestion pass through the epithelial cells of the intestinal mucosa and enter the blood capillaries (for water-soluble nutrients like amino acids and monosaccharides) or the lymph system via lacteals (for fat-soluble nutrients). This allows essential nutrients to circulate and support tissues throughout the body.\n\n• Excretion (or defecation) is the removal and elimination of undigested food residue, metabolic waste products, and fecal matter from the body.\n• Metabolism represents the sum total of all biochemical reactions (anabolism and catabolism) that happen within body cells after nutrients have already been absorbed and delivered.\n• Digestion is purely the mechanical and chemical breakdown of large, complex food polymers into smaller, soluble constituent building blocks. It precedes absorption but does not include the physical movement of nutrients into body fluids.","whyWrongChoices":"Alternative options: Digestion, Excretion, Metabolism"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient is admitted to the hospital after 3 days of vomiting and diarrhea and has lost 4% of his body weight. assessment of lab data would likely show::::high albumin and low sodium', 'a patient is admitted to the hospital after 3 days of vomiting and diarrhea and has lost 4% of his body weight. assessment of lab data would likely show:', 'High albumin and low sodium', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This case describes a state of hypovolemic dehydration and fluid volume deficit due to prolonged fluid loss (vomiting and diarrhea over 3 days) resulting in a 4% loss of body weight.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High albumin and low sodium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This case describes a state of hypovolemic dehydration and fluid volume deficit due to prolonged fluid loss (vomiting and diarrhea over 3 days) resulting in a 4% loss of body weight.\n\n• High Albumin: When the body loses significant fluid volume, the water content within the blood vessels decreases. This concentrates the remaining blood components—a process called hemoconcentration. As a result, large proteins like albumin become highly concentrated, leading to elevated serum levels.\n• Low Sodium: Severe vomiting and prolonged diarrhea cause a massive physical loss of both water and essential electrolytes. When electrolyte-rich fluids are evacuated directly from the GI tract, sodium levels drop significantly.","whyWrongChoices":"Alternative options: Low albumin and low BUN, Elevated calcium and low phosphorus, Low creatinine and elevated BUN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:outer portion of the crown of the teeth, easily decalcified by organic acids:::enamel', 'outer portion of the crown of the teeth, easily decalcified by organic acids', 'enamel', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enamel is the highly mineralized, translucent tissue that forms the protective outer layer of the anatomical crown of the tooth.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"enamel\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enamel is the highly mineralized, translucent tissue that forms the protective outer layer of the anatomical crown of the tooth.\nWhile enamel is the hardest substance in the human body, it is predominantly made of a mineral called hydroxyapatite (calcium phosphate). When you consume acidic foods or when plaque bacteria ferment carbohydrates into organic acids, the local pH drops. This acidic environment easily decalcifies (demineralizes) the enamel structure, which is the foundational step in the formation of dental cavities.\n\n× Dentin: This calcified tissue forms the bulk of the inner tooth structure and lies beneath the enamel and cementum.\n× Periodontium: This refers to the collection of specialized tissues (including gums, bone, and ligaments) that surround, support, and anchor the teeth in the jaw.\n× Cementum: This rigid connective tissue specifically covers and protects the anatomy of the tooth roots, rather than the crown.","whyWrongChoices":"Alternative options: cementum, peridontium, dentin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a patient is admitted to the hospital after 3 days of vomiting and diarrhea and has lost 4% of his body weight. assessment of lab data would likely show::::', 'a patient is admitted to the hospital after 3 days of vomiting and diarrhea and has lost 4% of his body weight. assessment of lab data would likely show:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This case describes a state of hypovolemic dehydration and fluid volume deficit due to prolonged fluid loss (vomiting and diarrhea over 3 days) resulting in a 4% loss of body weight.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High albumin and low sodium\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This case describes a state of hypovolemic dehydration and fluid volume deficit due to prolonged fluid loss (vomiting and diarrhea over 3 days) resulting in a 4% loss of body weight.\n\n• High Albumin: When the body loses significant fluid volume, the water content within the blood vessels decreases. This concentrates the remaining blood components—a process called hemoconcentration. As a result, large proteins like albumin become highly concentrated, leading to elevated serum levels.\n• Low Sodium: Severe vomiting and prolonged diarrhea cause a massive physical loss of both water and essential electrolytes. When electrolyte-rich fluids are evacuated directly from the GI tract, sodium levels drop significantly.","whyWrongChoices":"Alternative options: Low albumin and low BUN, Elevated calcium and low phosphorus, Low creatinine and elevated BUN"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:gastroesophageal reflux disease (gerd) is::::characterized by frequent backflow of the stomach’s gastric secretions into the esophagus', 'gastroesophageal reflux disease (gerd) is:', 'Characterized by frequent backflow of the stomach’s gastric secretions into the esophagus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastroesophageal reflux disease (GERD) occurs when stomach acid repeatedly flows back up into the tube connecting your mouth and stomach (esophagus). This backflow happens because the lower esophageal sphincter (LES) relaxes abnormally or weakens, allowing gastric contents to escape upward and cause irritation or heartburn.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Characterized by frequent backflow of the stomach’s gastric secretions into the esophagus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastroesophageal reflux disease (GERD) occurs when stomach acid repeatedly flows back up into the tube connecting your mouth and stomach (esophagus). This backflow happens because the lower esophageal sphincter (LES) relaxes abnormally or weakens, allowing gastric contents to escape upward and cause irritation or heartburn.\n\n• An obstruction of the lower esophagus that results in dysphagia: This describes an esophageal stricture or obstruction, which can be a complication of chronic GERD but is not the disease itself.\n• An erosion of the lining of the stomach caused by excess acid in gastric secretions: This describes a peptic ulcer or gastritis, which affects the stomach lining rather than the esophagus.\n• A protuberance of a portion of the stomach above the lower esophageal sphincter: This describes a hiatal hernia, a physical condition where part of the stomach pushes up through the diaphragm. While it can cause GERD, it is a distinct anatomical issue.","whyWrongChoices":"Alternative options: A protuberance of a portion of the stomach above the lower esophageal sphincter, An erosion of the lining of the stomach caused by excess acid in gastric secretions, An obstruction of the lower esophagus that results in dysphagia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:gastroesophageal reflux disease (gerd) is::::', 'gastroesophageal reflux disease (gerd) is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastroesophageal reflux disease (GERD) occurs when stomach acid repeatedly flows back up into the tube connecting your mouth and stomach (esophagus). This backflow happens because the lower esophageal sphincter (LES) relaxes abnormally or weakens, allowing gastric contents to escape upward and cause irritation or heartburn.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Characterized by frequent backflow of the stomach’s gastric secretions into the esophagus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastroesophageal reflux disease (GERD) occurs when stomach acid repeatedly flows back up into the tube connecting your mouth and stomach (esophagus). This backflow happens because the lower esophageal sphincter (LES) relaxes abnormally or weakens, allowing gastric contents to escape upward and cause irritation or heartburn.\n\n• An obstruction of the lower esophagus that results in dysphagia: This describes an esophageal stricture or obstruction, which can be a complication of chronic GERD but is not the disease itself.\n• An erosion of the lining of the stomach caused by excess acid in gastric secretions: This describes a peptic ulcer or gastritis, which affects the stomach lining rather than the esophagus.\n• A protuberance of a portion of the stomach above the lower esophageal sphincter: This describes a hiatal hernia, a physical condition where part of the stomach pushes up through the diaphragm. While it can cause GERD, it is a distinct anatomical issue.","whyWrongChoices":"Alternative options: A protuberance of a portion of the stomach above the lower esophageal sphincter, An erosion of the lining of the stomach caused by excess acid in gastric secretions, An obstruction of the lower esophagus that results in dysphagia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:for the patient with persistent vomiting, the major nutrition-related concern(s) is/are::::dehydration and malnutrition', 'for the patient with persistent vomiting, the major nutrition-related concern(s) is/are:', 'Dehydration and malnutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question specifically asks for the major nutrition-related concerns. When a patient experiences persistent vomiting, they physically cannot retain ingested fluids, electrolytes, or dietary macro/micronutrients. This fast fluid loss and lack of nutrient retention directly cause dehydration and malnutrition.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dehydration and malnutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question specifically asks for the major nutrition-related concerns. When a patient experiences persistent vomiting, they physically cannot retain ingested fluids, electrolytes, or dietary macro/micronutrients. This fast fluid loss and lack of nutrient retention directly cause dehydration and malnutrition.","whyWrongChoices":"Alternative options: Reflux esophagitis, Dyspepsia, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:for the patient with persistent vomiting, the major nutrition-related concern(s) is/are::::', 'for the patient with persistent vomiting, the major nutrition-related concern(s) is/are:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question specifically asks for the major nutrition-related concerns. When a patient experiences persistent vomiting, they physically cannot retain ingested fluids, electrolytes, or dietary macro/micronutrients. This fast fluid loss and lack of nutrient retention directly cause dehydration and malnutrition.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dehydration and malnutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question specifically asks for the major nutrition-related concerns. When a patient experiences persistent vomiting, they physically cannot retain ingested fluids, electrolytes, or dietary macro/micronutrients. This fast fluid loss and lack of nutrient retention directly cause dehydration and malnutrition.","whyWrongChoices":"Alternative options: Reflux esophagitis, Dyspepsia, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:outer portion of the crown of the teeth, easily decalcified by organic acids:::', 'outer portion of the crown of the teeth, easily decalcified by organic acids', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enamel is the highly mineralized, translucent tissue that forms the protective outer layer of the anatomical crown of the tooth.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"enamel\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enamel is the highly mineralized, translucent tissue that forms the protective outer layer of the anatomical crown of the tooth.\nWhile enamel is the hardest substance in the human body, it is predominantly made of a mineral called hydroxyapatite (calcium phosphate). When you consume acidic foods or when plaque bacteria ferment carbohydrates into organic acids, the local pH drops. This acidic environment easily decalcifies (demineralizes) the enamel structure, which is the foundational step in the formation of dental cavities.\n\n× Dentin: This calcified tissue forms the bulk of the inner tooth structure and lies beneath the enamel and cementum.\n× Periodontium: This refers to the collection of specialized tissues (including gums, bone, and ligaments) that surround, support, and anchor the teeth in the jaw.\n× Cementum: This rigid connective tissue specifically covers and protects the anatomy of the tooth roots, rather than the crown.","whyWrongChoices":"Alternative options: cementum, peridontium, dentin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the periodic squeezing or partitioning of the intestine by its circular muscles that both mixes and slowly pushes the contents along is known as::::segmentation', 'the periodic squeezing or partitioning of the intestine by its circular muscles that both mixes and slowly pushes the contents along is known as:', 'Segmentation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Segmentation takes place primarily in the small intestine. It features localized, alternating contractions of the \"circular smooth muscles\" that partition the intestine into temporary segments. This rhythmic, back-and-forth churning works like a washing machine—mixing the chyme thoroughly with digestive enzymes and pushing it against the intestinal walls to optimize nutrient absorption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Segmentation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Segmentation takes place primarily in the small intestine. It features localized, alternating contractions of the \"circular smooth muscles\" that partition the intestine into temporary segments. This rhythmic, back-and-forth churning works like a washing machine—mixing the chyme thoroughly with digestive enzymes and pushing it against the intestinal walls to optimize nutrient absorption.\n\n× Peristalsis: While peristalsis also involves smooth muscle contractions, it uses sequential, wave-like movements of \"both circular and longitudinal muscles\" to propel food progressively forward in one direction through the GI tract, rather than partitioning and mixing it locally.\n× Secretion & Absorption: These are chemical and physiological processes rather than structural mechanical movements.","whyWrongChoices":"Alternative options: Peristalsis, Absorption, Secretion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the periodic squeezing or partitioning of the intestine by its circular muscles that both mixes and slowly pushes the contents along is known as::::', 'the periodic squeezing or partitioning of the intestine by its circular muscles that both mixes and slowly pushes the contents along is known as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Segmentation takes place primarily in the small intestine. It features localized, alternating contractions of the \"circular smooth muscles\" that partition the intestine into temporary segments. This rhythmic, back-and-forth churning works like a washing machine—mixing the chyme thoroughly with digestive enzymes and pushing it against the intestinal walls to optimize nutrient absorption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Segmentation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Segmentation takes place primarily in the small intestine. It features localized, alternating contractions of the \"circular smooth muscles\" that partition the intestine into temporary segments. This rhythmic, back-and-forth churning works like a washing machine—mixing the chyme thoroughly with digestive enzymes and pushing it against the intestinal walls to optimize nutrient absorption.\n\n× Peristalsis: While peristalsis also involves smooth muscle contractions, it uses sequential, wave-like movements of \"both circular and longitudinal muscles\" to propel food progressively forward in one direction through the GI tract, rather than partitioning and mixing it locally.\n× Secretion & Absorption: These are chemical and physiological processes rather than structural mechanical movements.","whyWrongChoices":"Alternative options: Peristalsis, Absorption, Secretion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an abnormal redness of the tongue that may be due to vitamin b deficiency:::glossitis', 'an abnormal redness of the tongue that may be due to vitamin b deficiency', 'glossitis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glossitis is the medical term for inflammation of the tongue. It is classically characterized by abnormal redness, swelling, soreness, and a smooth or \"beefy\" appearance due to the loss of the tiny bumps (papillae) on the tongue''s surface.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glossitis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glossitis is the medical term for inflammation of the tongue. It is classically characterized by abnormal redness, swelling, soreness, and a smooth or \"beefy\" appearance due to the loss of the tiny bumps (papillae) on the tongue''s surface.\n\nA deficiency in B-complex vitamins—especially Vitamin B12 (cobalamin), Vitamin B9 (folate), Vitamin B3 (niacin), and Vitamin B2 (riboflavin)—is a primary nutritional cause of glossitis. Because B vitamins are critical for rapid cell turnover and tissue repair, a deficiency causes the mucosal tissue of the tongue to become inflamed and break down rapidly.\n\n• Cheilosis (specifically angular cheilosis) refers to painful inflammation, drying, or cracking at the corners of the mouth and lips. While it is also a common sign of a B vitamin deficiency, it does not involve the tongue.\n• Gingivitis is inflammation restricted exclusively to the gums (gingiva), typically caused by plaque buildup rather than a direct vitamin B deficiency.\n• Periodontitis is a serious, progressive gum infection that damages the soft tissue and destroys the bone supporting the teeth.","whyWrongChoices":"Alternative options: ginigivitis, periodontitis, cheilosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an abnormal redness of the tongue that may be due to vitamin b deficiency:::', 'an abnormal redness of the tongue that may be due to vitamin b deficiency', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glossitis is the medical term for inflammation of the tongue. It is classically characterized by abnormal redness, swelling, soreness, and a smooth or \"beefy\" appearance due to the loss of the tiny bumps (papillae) on the tongue''s surface.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"glossitis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glossitis is the medical term for inflammation of the tongue. It is classically characterized by abnormal redness, swelling, soreness, and a smooth or \"beefy\" appearance due to the loss of the tiny bumps (papillae) on the tongue''s surface.\n\nA deficiency in B-complex vitamins—especially Vitamin B12 (cobalamin), Vitamin B9 (folate), Vitamin B3 (niacin), and Vitamin B2 (riboflavin)—is a primary nutritional cause of glossitis. Because B vitamins are critical for rapid cell turnover and tissue repair, a deficiency causes the mucosal tissue of the tongue to become inflamed and break down rapidly.\n\n• Cheilosis (specifically angular cheilosis) refers to painful inflammation, drying, or cracking at the corners of the mouth and lips. While it is also a common sign of a B vitamin deficiency, it does not involve the tongue.\n• Gingivitis is inflammation restricted exclusively to the gums (gingiva), typically caused by plaque buildup rather than a direct vitamin B deficiency.\n• Periodontitis is a serious, progressive gum infection that damages the soft tissue and destroys the bone supporting the teeth.","whyWrongChoices":"Alternative options: ginigivitis, periodontitis, cheilosis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:characterized by decreased muscle tone:::', 'characterized by decreased muscle tone', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hypotonia means decreased muscle tone (hypo = low, tonia = tone). It causes muscles to feel loose, flaccid, or \"floppy,\" resulting in reduced resistance to passive movement.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"hypotonia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hypotonia means decreased muscle tone (hypo = low, tonia = tone). It causes muscles to feel loose, flaccid, or \"floppy,\" resulting in reduced resistance to passive movement.\n\n• Ataxia: Impaired balance and voluntary coordination, not low tone.\n• Athetosis: Slow, involuntary, writhing muscle movements.\n• Spasticity: Increased muscle tone and stiffness—the exact opposite of hypotonia.","whyWrongChoices":"Alternative options: athetosis, spasticity, ataxia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:critically ill patient may be showing any of the following except::::glucose production normal', 'critically ill patient may be showing any of the following except:', 'Glucose production normal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a critically ill patient, the body undergoes a profound neuroendocrine stress response (hypermetabolism). This severe physiological stress triggers massive hormonal shifts, releasing high levels of counter-regulatory hormones like cortisol, epinephrine, and glucagon. As a result, glucose production is significantly altered and elevated (hyperglycemia), driven by rapid glycogenolysis and gluconeogenesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose production normal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a critically ill patient, the body undergoes a profound neuroendocrine stress response (hypermetabolism). This severe physiological stress triggers massive hormonal shifts, releasing high levels of counter-regulatory hormones like cortisol, epinephrine, and glucagon. As a result, glucose production is significantly altered and elevated (hyperglycemia), driven by rapid glycogenolysis and gluconeogenesis.\n\n• Severe acid-base disorder: Sepsis, shock, or acute kidney injury routinely cause severe metabolic or mixed acidosis.\n• Acute respiratory distress: Hypoxia, severe lung injury, and multi-organ distress frequently trigger severe breathing complications.\n• Acute hemodynamic instability: Critical illness commonly precipitates severe shocks, sudden blood pressure drops, and heart failure.","whyWrongChoices":"Alternative options: Severe acid base disorder, Acute respiratory distress, Acute hemodynamic instability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. ice cream is agitated to form tiny crystals. sentence b. large crystals may be formed with slow freezing.:::', 'sentence a. ice cream is agitated to form tiny crystals. sentence b. large crystals may be formed with slow freezing.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Agitation during ice-cream freezing helps distribute air and prevents the formation of excessively large crystals. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Agitation during ice-cream freezing helps distribute air and prevents the formation of excessively large crystals. \n\nSlow freezing favors the growth of larger ice crystals and produces a coarser texture.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:critically ill patient may be showing any of the following except::::', 'critically ill patient may be showing any of the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In a critically ill patient, the body undergoes a profound neuroendocrine stress response (hypermetabolism). This severe physiological stress triggers massive hormonal shifts, releasing high levels of counter-regulatory hormones like cortisol, epinephrine, and glucagon. As a result, glucose production is significantly altered and elevated (hyperglycemia), driven by rapid glycogenolysis and gluconeogenesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose production normal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In a critically ill patient, the body undergoes a profound neuroendocrine stress response (hypermetabolism). This severe physiological stress triggers massive hormonal shifts, releasing high levels of counter-regulatory hormones like cortisol, epinephrine, and glucagon. As a result, glucose production is significantly altered and elevated (hyperglycemia), driven by rapid glycogenolysis and gluconeogenesis.\n\n• Severe acid-base disorder: Sepsis, shock, or acute kidney injury routinely cause severe metabolic or mixed acidosis.\n• Acute respiratory distress: Hypoxia, severe lung injury, and multi-organ distress frequently trigger severe breathing complications.\n• Acute hemodynamic instability: Critical illness commonly precipitates severe shocks, sudden blood pressure drops, and heart failure.","whyWrongChoices":"Alternative options: Severe acid base disorder, Acute respiratory distress, Acute hemodynamic instability"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:physical signs of pem might include all of the following except::::low, serum albumin', 'physical signs of pem might include all of the following except:', 'Low, serum albumin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While a low serum albumin level is a classic biochemical marker of malnutrition and visceral protein depletion, it is a laboratory blood test finding, not a physical sign.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low, serum albumin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While a low serum albumin level is a classic biochemical marker of malnutrition and visceral protein depletion, it is a laboratory blood test finding, not a physical sign.\n\nPhysical Signs:\n\t• Wasted appearance: This is a direct physical sign of muscle and fat wasting (emaciation/cachexia) observed during an inspection.\n\t• Dull, brittle hair: This is a physical sign of protein and micronutrient deficiency that affects keratin production, visible on examination.\n\t• Poor grip strength: This is a functional, physical sign of muscle mass loss that can be measured directly at the bedside using a dynamometer.","whyWrongChoices":"Alternative options: Dull, brittle hair, Poor grip strength, Wasted appearance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:physical signs of pem might include all of the following except::::', 'physical signs of pem might include all of the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While a low serum albumin level is a classic biochemical marker of malnutrition and visceral protein depletion, it is a laboratory blood test finding, not a physical sign.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low, serum albumin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While a low serum albumin level is a classic biochemical marker of malnutrition and visceral protein depletion, it is a laboratory blood test finding, not a physical sign.\n\nPhysical Signs:\n\t• Wasted appearance: This is a direct physical sign of muscle and fat wasting (emaciation/cachexia) observed during an inspection.\n\t• Dull, brittle hair: This is a physical sign of protein and micronutrient deficiency that affects keratin production, visible on examination.\n\t• Poor grip strength: This is a functional, physical sign of muscle mass loss that can be measured directly at the bedside using a dynamometer.","whyWrongChoices":"Alternative options: Dull, brittle hair, Poor grip strength, Wasted appearance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements concerning protein and energy recommendations during acute metabolic stress is true?:::protein and energy recommendations are high in order to minimize lean tissue losses', 'which of the following statements concerning protein and energy recommendations during acute metabolic stress is true?', 'Protein and energy recommendations are high in order to minimize lean tissue losses', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During acute metabolic stress (such as major trauma, sepsis, or severe burns), the body enters a highly hypercatabolic and inflammatory state. The sympathetic nervous system and stress hormones trigger rapid muscle proteolysis (breaking down skeletal muscle) to mobilize amino acids for energy, tissue repair, and immune function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Protein and energy recommendations are high in order to minimize lean tissue losses\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During acute metabolic stress (such as major trauma, sepsis, or severe burns), the body enters a highly hypercatabolic and inflammatory state. The sympathetic nervous system and stress hormones trigger rapid muscle proteolysis (breaking down skeletal muscle) to mobilize amino acids for energy, tissue repair, and immune function.\n\nTo counteract this severe muscle wasting and negative nitrogen balance, protein and energy intake targets are raised significantly above baseline requirements. This aggressive support aims to minimize lean tissue losses and preserve essential organ and skeletal muscle function.","whyWrongChoices":"Alternative options: Protein and energy recommendations are similar to those for healthy people, Protein and energy recommendations are reduced because stressed individual cannot metabolize nutrients normally, Acutely stressed individuals can benefit from as much protein and energy as can be provided"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is true in a soft diet::::chicken nilaga with asparagus tips and potato, cathedral windows', 'which of the following is true in a soft diet:', 'Chicken Nilaga with Asparagus tips and Potato, Cathedral Windows', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chicken Nilaga features chicken meat that has been boiled for a long time until its connective tissues completely break down, making it extremely tender and effortless to chew. Cooked potatoes and soft asparagus tips (unlike the tough, fibrous lower stalks) are highly digestible, standard soft-diet vegetables. Cathedral Windows is a traditional Filipino gelatin dessert made of soft, multi-colored agar blocks set in a light, creamy gelatin base. Because gelatin completely melts at body temperature, it is a quintessential soft and light-to-digest menu item.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chicken Nilaga with Asparagus tips and Potato, Cathedral Windows\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chicken Nilaga features chicken meat that has been boiled for a long time until its connective tissues completely break down, making it extremely tender and effortless to chew. Cooked potatoes and soft asparagus tips (unlike the tough, fibrous lower stalks) are highly digestible, standard soft-diet vegetables. Cathedral Windows is a traditional Filipino gelatin dessert made of soft, multi-colored agar blocks set in a light, creamy gelatin base. Because gelatin completely melts at body temperature, it is a quintessential soft and light-to-digest menu item.","whyWrongChoices":"Alternative options: Cooked Asparagus tips, Beef Steak with Onion Rings, Fruit Salad, Pork Sinigang with Kangkong and Radish, Angel Cake, Fish Escabeche with carrots and sayote, Cooked Jackfruit in Light Syrup"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements concerning protein and energy recommendations during acute metabolic stress is true?:::', 'which of the following statements concerning protein and energy recommendations during acute metabolic stress is true?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During acute metabolic stress (such as major trauma, sepsis, or severe burns), the body enters a highly hypercatabolic and inflammatory state. The sympathetic nervous system and stress hormones trigger rapid muscle proteolysis (breaking down skeletal muscle) to mobilize amino acids for energy, tissue repair, and immune function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Protein and energy recommendations are high in order to minimize lean tissue losses\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During acute metabolic stress (such as major trauma, sepsis, or severe burns), the body enters a highly hypercatabolic and inflammatory state. The sympathetic nervous system and stress hormones trigger rapid muscle proteolysis (breaking down skeletal muscle) to mobilize amino acids for energy, tissue repair, and immune function.\n\nTo counteract this severe muscle wasting and negative nitrogen balance, protein and energy intake targets are raised significantly above baseline requirements. This aggressive support aims to minimize lean tissue losses and preserve essential organ and skeletal muscle function.","whyWrongChoices":"Alternative options: Protein and energy recommendations are similar to those for healthy people, Protein and energy recommendations are reduced because stressed individual cannot metabolize nutrients normally, Acutely stressed individuals can benefit from as much protein and energy as can be provided"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the health care professional assessing a patient who underwent a gastrectomy several years ago should be alert to signs of::::iron-deficiency anemia', 'the health care professional assessing a patient who underwent a gastrectomy several years ago should be alert to signs of:', 'Iron-deficiency anemia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A gastrectomy (partial or total removal of the stomach) drastically alters the digestive tract''s anatomy and chemical environment. Over a long-term period (\"several years ago\"), this surgery severely impairs nutrient absorption, making iron-deficiency anemia a major chronic complication:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron-deficiency anemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A gastrectomy (partial or total removal of the stomach) drastically alters the digestive tract''s anatomy and chemical environment. Over a long-term period (\"several years ago\"), this surgery severely impairs nutrient absorption, making iron-deficiency anemia a major chronic complication:\n\n1. Loss of Gastric Acid: Stomach acid is entirely necessary to convert dietary ferric iron into absorbable ferrous iron. Without sufficient acid, iron cannot be properly dissolved or processed.\n2. Bypassed Duodenum: Depending on the surgical reconstruction type, the duodenum (the primary anatomical site where iron is absorbed) is frequently bypassed or altered, blocking proper iron uptake.\n3. Vitamin B12 Malabsorption: Additionally, losing the stomach lining removes parietal cells, which produce intrinsic factor. A lack of intrinsic factor prevents vitamin B12 absorption, compounding the risk of long-term anemia (megaloblastic/pernicious anemia) alongside iron deficiency.","whyWrongChoices":"Alternative options: Dysphagia, GERD, Gastritis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the health care professional assessing a patient who underwent a gastrectomy several years ago should be alert to signs of::::', 'the health care professional assessing a patient who underwent a gastrectomy several years ago should be alert to signs of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A gastrectomy (partial or total removal of the stomach) drastically alters the digestive tract''s anatomy and chemical environment. Over a long-term period (\"several years ago\"), this surgery severely impairs nutrient absorption, making iron-deficiency anemia a major chronic complication:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron-deficiency anemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A gastrectomy (partial or total removal of the stomach) drastically alters the digestive tract''s anatomy and chemical environment. Over a long-term period (\"several years ago\"), this surgery severely impairs nutrient absorption, making iron-deficiency anemia a major chronic complication:\n\n1. Loss of Gastric Acid: Stomach acid is entirely necessary to convert dietary ferric iron into absorbable ferrous iron. Without sufficient acid, iron cannot be properly dissolved or processed.\n2. Bypassed Duodenum: Depending on the surgical reconstruction type, the duodenum (the primary anatomical site where iron is absorbed) is frequently bypassed or altered, blocking proper iron uptake.\n3. Vitamin B12 Malabsorption: Additionally, losing the stomach lining removes parietal cells, which produce intrinsic factor. A lack of intrinsic factor prevents vitamin B12 absorption, compounding the risk of long-term anemia (megaloblastic/pernicious anemia) alongside iron deficiency.","whyWrongChoices":"Alternative options: Dysphagia, GERD, Gastritis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the health care professional advising an elderly patient with constipation encourages the patient to:::gradually add high-fiber foods to the diet', 'the health care professional advising an elderly patient with constipation encourages the patient to', 'Gradually add high-fiber foods to the diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The primary dietary treatment for chronic constipation is to gradually increase dietary fiber alongside adequate fluid intake. Fiber adds bulk and holds water in the stool, making it softer and easier to pass. Introducing fiber gradually is crucial for elderly patients because a sudden spike can cause severe abdominal gas, bloating, and cramping.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gradually add high-fiber foods to the diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The primary dietary treatment for chronic constipation is to gradually increase dietary fiber alongside adequate fluid intake. Fiber adds bulk and holds water in the stool, making it softer and easier to pass. Introducing fiber gradually is crucial for elderly patients because a sudden spike can cause severe abdominal gas, bloating, and cramping.","whyWrongChoices":"Alternative options: Consume a low-fat diet rich in potassium, Consume a high-protein diet rich in calcium, Eliminate gas-forming foods from the diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the health care professional advising an elderly patient with constipation encourages the patient to:::', 'the health care professional advising an elderly patient with constipation encourages the patient to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The primary dietary treatment for chronic constipation is to gradually increase dietary fiber alongside adequate fluid intake. Fiber adds bulk and holds water in the stool, making it softer and easier to pass. Introducing fiber gradually is crucial for elderly patients because a sudden spike can cause severe abdominal gas, bloating, and cramping.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gradually add high-fiber foods to the diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The primary dietary treatment for chronic constipation is to gradually increase dietary fiber alongside adequate fluid intake. Fiber adds bulk and holds water in the stool, making it softer and easier to pass. Introducing fiber gradually is crucial for elderly patients because a sudden spike can cause severe abdominal gas, bloating, and cramping.","whyWrongChoices":"Alternative options: Consume a low-fat diet rich in potassium, Consume a high-protein diet rich in calcium, Eliminate gas-forming foods from the diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:osmotic diarrhea often results from::::nutrient malabsorption', 'osmotic diarrhea often results from:', 'Nutrient malabsorption', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Osmotic diarrhea occurs when unabsorbed, water-soluble solutes remain behind in the intestinal lumen. Because these particles are not absorbed normally due to nutrient malabsorption or maldigestion, they act like a sponge. Through osmotic pressure, they pull fluid out of the body tissues and into the gut lumen to equalize the concentration gradient, resulting in loose, watery stools. A classic example is lactose intolerance, where unabsorbed lactose draws water into the colon. A defining feature of osmotic diarrhea is that it stops or decreases significantly when the patient fasts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrient malabsorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Osmotic diarrhea occurs when unabsorbed, water-soluble solutes remain behind in the intestinal lumen. Because these particles are not absorbed normally due to nutrient malabsorption or maldigestion, they act like a sponge. Through osmotic pressure, they pull fluid out of the body tissues and into the gut lumen to equalize the concentration gradient, resulting in loose, watery stools. A classic example is lactose intolerance, where unabsorbed lactose draws water into the colon. A defining feature of osmotic diarrhea is that it stops or decreases significantly when the patient fasts.","whyWrongChoices":"Alternative options: Excessive motility of fluids within the colon, Excessive fluid secretion by the intestines, Viral, bacterial, or protozoal infetions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the extended global nutrition target for exclusive breastfeeding rates by 2030.:::', 'the extended global nutrition target for exclusive breastfeeding rates by 2030.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"As of 2024, nearly half (48%) of infants under six months were exclusively breastfed, bringing the world close to the 50% target set for 2025. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"70%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"As of 2024, nearly half (48%) of infants under six months were exclusively breastfed, bringing the world close to the 50% target set for 2025. \n\nWhen WHO and UNICEF proposed extending the 2025 Global Nutrition Targets to 2030. By 2030, that target is to increase the rate of exclusive breastfeeding in the first six months up to at least 60%.","whyWrongChoices":"Alternative options: 50%, 40%, 90%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:osmotic diarrhea often results from::::', 'osmotic diarrhea often results from:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Osmotic diarrhea occurs when unabsorbed, water-soluble solutes remain behind in the intestinal lumen. Because these particles are not absorbed normally due to nutrient malabsorption or maldigestion, they act like a sponge. Through osmotic pressure, they pull fluid out of the body tissues and into the gut lumen to equalize the concentration gradient, resulting in loose, watery stools. A classic example is lactose intolerance, where unabsorbed lactose draws water into the colon. A defining feature of osmotic diarrhea is that it stops or decreases significantly when the patient fasts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrient malabsorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Osmotic diarrhea occurs when unabsorbed, water-soluble solutes remain behind in the intestinal lumen. Because these particles are not absorbed normally due to nutrient malabsorption or maldigestion, they act like a sponge. Through osmotic pressure, they pull fluid out of the body tissues and into the gut lumen to equalize the concentration gradient, resulting in loose, watery stools. A classic example is lactose intolerance, where unabsorbed lactose draws water into the colon. A defining feature of osmotic diarrhea is that it stops or decreases significantly when the patient fasts.","whyWrongChoices":"Alternative options: Excessive motility of fluids within the colon, Excessive fluid secretion by the intestines, Viral, bacterial, or protozoal infetions"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:after an ileostomy, the most serious concern is::::incompletely digested foods may cause obstruction', 'after an ileostomy, the most serious concern is:', 'Incompletely digested foods may cause obstruction', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An ileostomy involves surgically bringing the terminal end of the small intestine (the ileum) through the abdominal wall to create a stoma, completely bypassing the colon. Because the large intestine is responsible for the bulk of water reabsorption, the stool exiting an ileostomy is entirely liquid or semi-solid and continuous.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Incompletely digested foods may cause obstruction\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An ileostomy involves surgically bringing the terminal end of the small intestine (the ileum) through the abdominal wall to create a stoma, completely bypassing the colon. Because the large intestine is responsible for the bulk of water reabsorption, the stool exiting an ileostomy is entirely liquid or semi-solid and continuous.\n• The Primary Mechanical Danger: The lumen of the ileum at the stoma site is incredibly narrow. Certain fibrous, tough, or stringy foods—such as raw celery, popcorn, nuts, coconut, and whole corn—do not break down well in the small intestine. If these foods are not chewed meticulously, they remain incompletely digested and can clump together, creating a physical mass that risks completely obstructing the stoma, which is a life-threatening medical emergency.\n\nWhy the Other Options are Incorrect:\n\t× Fluid restrictions: This is completely backwards. Ileostomy patients lose a significant amount of water and sodium daily because they no longer have a colon. They are placed on an increased fluid intake, not fluid restrictions.\n\t× Waste disposal: While emptying a pouch frequently requires adjustments, it is a lifestyle adaptation rather than the most serious clinical or medical concern.\n\t× Overly restrictive diet: While high-fiber items are restricted early on, the overall diet can be advanced broadly to meet all nutrient needs safely over time.","whyWrongChoices":"Alternative options: The diet is too restrictive for meeting nutrient needs, Waste disposal causes frequent daily interruption, Fluid restrictions prevent patients from drinking beverages freely"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:after an ileostomy, the most serious concern is::::', 'after an ileostomy, the most serious concern is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An ileostomy involves surgically bringing the terminal end of the small intestine (the ileum) through the abdominal wall to create a stoma, completely bypassing the colon. Because the large intestine is responsible for the bulk of water reabsorption, the stool exiting an ileostomy is entirely liquid or semi-solid and continuous.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Incompletely digested foods may cause obstruction\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An ileostomy involves surgically bringing the terminal end of the small intestine (the ileum) through the abdominal wall to create a stoma, completely bypassing the colon. Because the large intestine is responsible for the bulk of water reabsorption, the stool exiting an ileostomy is entirely liquid or semi-solid and continuous.\n• The Primary Mechanical Danger: The lumen of the ileum at the stoma site is incredibly narrow. Certain fibrous, tough, or stringy foods—such as raw celery, popcorn, nuts, coconut, and whole corn—do not break down well in the small intestine. If these foods are not chewed meticulously, they remain incompletely digested and can clump together, creating a physical mass that risks completely obstructing the stoma, which is a life-threatening medical emergency.\n\nWhy the Other Options are Incorrect:\n\t× Fluid restrictions: This is completely backwards. Ileostomy patients lose a significant amount of water and sodium daily because they no longer have a colon. They are placed on an increased fluid intake, not fluid restrictions.\n\t× Waste disposal: While emptying a pouch frequently requires adjustments, it is a lifestyle adaptation rather than the most serious clinical or medical concern.\n\t× Overly restrictive diet: While high-fiber items are restricted early on, the overall diet can be advanced broadly to meet all nutrient needs safely over time.","whyWrongChoices":"Alternative options: The diet is too restrictive for meeting nutrient needs, Waste disposal causes frequent daily interruption, Fluid restrictions prevent patients from drinking beverages freely"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a pound of fat has calories?:::3,500 kcal', 'a pound of fat has calories?', '3,500 kCal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Human adipose tissue is composed of approximately 87% pure lipid (triglycerides) by weight, with the remaining 13% consisting of extracellular water, protein, and cellular matrix. Because the complete oxidation of triglycerides yields approximately 9.1 kcal/g, but stored adipose tissue contains cellular water and structural proteins yielding roughly 4 kcal/g, the net energy density of whole adipose tissue averages about 3.5 kcal/g. Multiplied by 453.59 grams per pound, this yields the clinical standard of roughly 3,500 kcal per pound of body fat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3,500 kCal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Human adipose tissue is composed of approximately 87% pure lipid (triglycerides) by weight, with the remaining 13% consisting of extracellular water, protein, and cellular matrix. Because the complete oxidation of triglycerides yields approximately 9.1 kcal/g, but stored adipose tissue contains cellular water and structural proteins yielding roughly 4 kcal/g, the net energy density of whole adipose tissue averages about 3.5 kcal/g. Multiplied by 453.59 grams per pound, this yields the clinical standard of roughly 3,500 kcal per pound of body fat.","whyWrongChoices":"Alternative options: 3,000 kCal, 3,400 kCal, 4,000 kCal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a pound of fat has calories?:::', 'a pound of fat has calories?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Human adipose tissue is composed of approximately 87% pure lipid (triglycerides) by weight, with the remaining 13% consisting of extracellular water, protein, and cellular matrix. Because the complete oxidation of triglycerides yields approximately 9.1 kcal/g, but stored adipose tissue contains cellular water and structural proteins yielding roughly 4 kcal/g, the net energy density of whole adipose tissue averages about 3.5 kcal/g. Multiplied by 453.59 grams per pound, this yields the clinical standard of roughly 3,500 kcal per pound of body fat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"3,500 kCal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Human adipose tissue is composed of approximately 87% pure lipid (triglycerides) by weight, with the remaining 13% consisting of extracellular water, protein, and cellular matrix. Because the complete oxidation of triglycerides yields approximately 9.1 kcal/g, but stored adipose tissue contains cellular water and structural proteins yielding roughly 4 kcal/g, the net energy density of whole adipose tissue averages about 3.5 kcal/g. Multiplied by 453.59 grams per pound, this yields the clinical standard of roughly 3,500 kcal per pound of body fat.","whyWrongChoices":"Alternative options: 3,000 kCal, 3,400 kCal, 4,000 kCal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the primary purpose of mastication is:::all of the above', 'the primary purpose of mastication is', 'all of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mastication is the clinical term for chewing. It initiates the process of digestion through three interconnected functions:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mastication is the clinical term for chewing. It initiates the process of digestion through three interconnected functions:\n\n• Mixing of foods: Chewing physically breaks down food and mixes it thoroughly with saliva. This lubricates the food into a soft mass called a bolus so it can be safely swallowed.\n• Increased surface area of food: By crushing large chunks of food into tiny particles, mastication dramatically increases the exposed surface area. This allows digestive juices and enzymes to coat and penetrate the food much more effectively.\n• Action of amylase on dextrin: Saliva contains the enzyme salivary amylase (ptyalin). As chewing breaks down food and mixes it with saliva, amylase begins chemically digesting complex starches, breaking them down into smaller carbohydrate fragments like dextrins and maltose.","whyWrongChoices":"Alternative options: Mixing of foods, Action of amylase on dextrin, Increased surface area of food"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the primary purpose of mastication is:::', 'the primary purpose of mastication is', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mastication is the clinical term for chewing. It initiates the process of digestion through three interconnected functions:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mastication is the clinical term for chewing. It initiates the process of digestion through three interconnected functions:\n\n• Mixing of foods: Chewing physically breaks down food and mixes it thoroughly with saliva. This lubricates the food into a soft mass called a bolus so it can be safely swallowed.\n• Increased surface area of food: By crushing large chunks of food into tiny particles, mastication dramatically increases the exposed surface area. This allows digestive juices and enzymes to coat and penetrate the food much more effectively.\n• Action of amylase on dextrin: Saliva contains the enzyme salivary amylase (ptyalin). As chewing breaks down food and mixes it with saliva, amylase begins chemically digesting complex starches, breaking them down into smaller carbohydrate fragments like dextrins and maltose.","whyWrongChoices":"Alternative options: Mixing of foods, Action of amylase on dextrin, Increased surface area of food"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. illness caused by ingestion of the toxin present in food is called food poisoning. sentence b. botulism is an example of food intoxication.:::', 'sentence a. illness caused by ingestion of the toxin present in food is called food poisoning. sentence b. botulism is an example of food intoxication.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food intoxication results from ingesting toxins already present in food. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food intoxication results from ingesting toxins already present in food. \n\nBotulism is a classic example because illness results from ingestion of botulinum toxin.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following feeding tube placement sites would be the most appropriate for a client who is expected to be on a tube feeding for less than 4 weeks?:::nasogastric', 'which of the following feeding tube placement sites would be the most appropriate for a client who is expected to be on a tube feeding for less than 4 weeks?', 'nasogastric', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A nasogastric (NG) tube is explicitly indicated for short-term enteral nutrition expected to last less than 4 weeks. Because it is non-invasive, cost-effective, and can be placed quickly at the bedside without surgical, endoscopic, or radiologic intervention, it is the primary choice for temporary feeding needs.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nasogastric\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A nasogastric (NG) tube is explicitly indicated for short-term enteral nutrition expected to last less than 4 weeks. Because it is non-invasive, cost-effective, and can be placed quickly at the bedside without surgical, endoscopic, or radiologic intervention, it is the primary choice for temporary feeding needs.\n\n\t• Gastrostomy, Jejunostomy, and a tube enterostomy are invasive, surgically, radiologically, or endoscopically placed access routes. These options are reserved for long-term enteral nutrition support lasting longer than 4 to 6 weeks.","whyWrongChoices":"Alternative options: Gastrostomy, jejunostomy, tube enterostomy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diets that are consistency-modified, soft or bland are prescribed to treat disorders or conditions that primarily affect the::::upper git', 'diets that are consistency-modified, soft or bland are prescribed to treat disorders or conditions that primarily affect the:', 'Upper GIT', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diets that are consistency-modified (such as pureed or mechanical soft) or bland are carefully formulated to treat conditions primarily affecting the upper gastrointestinal tract (including the mouth, esophagus, and stomach).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Upper GIT\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diets that are consistency-modified (such as pureed or mechanical soft) or bland are carefully formulated to treat conditions primarily affecting the upper gastrointestinal tract (including the mouth, esophagus, and stomach).\n\nThese structural alterations are designed to assist patients who struggle with chewing, swallowing, or chemical digestion due to upper GI pathologies like dysphagia (difficulty swallowing), esophageal strictures, gastritis, or peptic ulcer disease.\n\n• Why Lower GIT is Secondary: While low-fiber or low-residue diets are used for lower GI disorders (like Crohn''s flare-ups) to reduce stool volume, texture and seasoning modifications (soft/bland) are explicitly tailored to minimize mechanical and chemical irritation in the upper digestive path.","whyWrongChoices":"Alternative options: Musculoskeletal system, Urinary tract, Lower GIT"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
