INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:this specific enteral formula is ideal for this patient – 45 year old female, admitted to the intensive care unit for cvd infarct with left sided hemiparesis, gcs of 7, with abdominal distention and for possible tube feeding::::semi – elemental', 'this specific enteral formula is ideal for this patient – 45 year old female, admitted to the intensive care unit for cvd infarct with left sided hemiparesis, gcs of 7, with abdominal distention and for possible tube feeding:', 'Semi – elemental', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a critically ill patient in the Intensive Care Unit (ICU) presents with an altered level of consciousness (Glasgow Coma Scale score of 7) and abdominal distention, it indicates significant gastrointestinal dysmotility and feeding intolerance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Semi – elemental\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a critically ill patient in the Intensive Care Unit (ICU) presents with an altered level of consciousness (Glasgow Coma Scale score of 7) and abdominal distention, it indicates significant gastrointestinal dysmotility and feeding intolerance.\n\nA semi-elemental (peptide-based) formula contains proteins that are already hydrolyzed into small dipeptides and tripeptides, along with easily absorbable fats like medium-chain triglycerides (MCTs). This pre-digested structure requires minimal enzymatic activity and is absorbed significantly faster and easier by the gut mucosa. Clinical studies prove that using a semi-elemental formula in the ICU under feeding intolerance conditions significantly reduces abdominal distention, lowers gastric residuals, and prevents feeding interruptions compared to standard options.","whyWrongChoices":"Alternative options: Polymeric, High Protein, High Fiber"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this specific enteral formula is ideal for this patient – 45 year old female, admitted to the intensive care unit for cvd infarct with left sided hemiparesis, gcs of 7, with abdominal distention and for possible tube feeding::::', 'this specific enteral formula is ideal for this patient – 45 year old female, admitted to the intensive care unit for cvd infarct with left sided hemiparesis, gcs of 7, with abdominal distention and for possible tube feeding:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a critically ill patient in the Intensive Care Unit (ICU) presents with an altered level of consciousness (Glasgow Coma Scale score of 7) and abdominal distention, it indicates significant gastrointestinal dysmotility and feeding intolerance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Semi – elemental\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a critically ill patient in the Intensive Care Unit (ICU) presents with an altered level of consciousness (Glasgow Coma Scale score of 7) and abdominal distention, it indicates significant gastrointestinal dysmotility and feeding intolerance.\n\nA semi-elemental (peptide-based) formula contains proteins that are already hydrolyzed into small dipeptides and tripeptides, along with easily absorbable fats like medium-chain triglycerides (MCTs). This pre-digested structure requires minimal enzymatic activity and is absorbed significantly faster and easier by the gut mucosa. Clinical studies prove that using a semi-elemental formula in the ICU under feeding intolerance conditions significantly reduces abdominal distention, lowers gastric residuals, and prevents feeding interruptions compared to standard options.","whyWrongChoices":"Alternative options: Polymeric, High Protein, High Fiber"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a disease specific enteral formula indicated for patients with liver disease is:::aminoleban en', 'a disease specific enteral formula indicated for patients with liver disease is', 'Aminoleban EN', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aminoleban EN is a specialized, disease-specific enteral formula manufactured by Otsuka. It is meticulously engineered for the nutritional management of patients with liver disease, particularly chronic liver failure, liver cirrhosis, or hepatic encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aminoleban EN\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aminoleban EN is a specialized, disease-specific enteral formula manufactured by Otsuka. It is meticulously engineered for the nutritional management of patients with liver disease, particularly chronic liver failure, liver cirrhosis, or hepatic encephalopathy.\nIts unique clinical formula is heavily enriched with branched-chain amino acids (BCAAs)—including valine, leucine, and isoleucine—while keeping the levels of aromatic amino acids (AAAs) low. This specific ratio helps correct the altered amino acid profile in liver failure, helping prevent or reverse symptoms of hepatic encephalopathy.\n\n\t• Juvenaid & Abound: Specialized therapeutic formulas (containing HMB, Arginine, and Glutamine) designed to promote wound healing and tissue repair, not for hepatic failure.\n\t• Nutribest: A general polymeric formula used for overall nutrition maintenance and macro/micronutrient supplementation.","whyWrongChoices":"Alternative options: Abound, Juvenaid, Nutribest"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a disease specific enteral formula indicated for patients with liver disease is:::', 'a disease specific enteral formula indicated for patients with liver disease is', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aminoleban EN is a specialized, disease-specific enteral formula manufactured by Otsuka. It is meticulously engineered for the nutritional management of patients with liver disease, particularly chronic liver failure, liver cirrhosis, or hepatic encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aminoleban EN\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aminoleban EN is a specialized, disease-specific enteral formula manufactured by Otsuka. It is meticulously engineered for the nutritional management of patients with liver disease, particularly chronic liver failure, liver cirrhosis, or hepatic encephalopathy.\nIts unique clinical formula is heavily enriched with branched-chain amino acids (BCAAs)—including valine, leucine, and isoleucine—while keeping the levels of aromatic amino acids (AAAs) low. This specific ratio helps correct the altered amino acid profile in liver failure, helping prevent or reverse symptoms of hepatic encephalopathy.\n\n\t• Juvenaid & Abound: Specialized therapeutic formulas (containing HMB, Arginine, and Glutamine) designed to promote wound healing and tissue repair, not for hepatic failure.\n\t• Nutribest: A general polymeric formula used for overall nutrition maintenance and macro/micronutrient supplementation.","whyWrongChoices":"Alternative options: Abound, Juvenaid, Nutribest"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the types of medical ketogenic diet for epilepsy in children are the following except::::south beach diet', 'the types of medical ketogenic diet for epilepsy in children are the following except:', 'South Beach Diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"There are four primary types of medically supervised dietary therapies used to treat drug-resistant epilepsy in children. These include the Classical Ketogenic Diet, the Modified Atkins Diet (MAD), the Low Glycemic Index Treatment (LGIT), and the Medium-Chain Triglyceride (MCT) diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"South Beach Diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"There are four primary types of medically supervised dietary therapies used to treat drug-resistant epilepsy in children. These include the Classical Ketogenic Diet, the Modified Atkins Diet (MAD), the Low Glycemic Index Treatment (LGIT), and the Medium-Chain Triglyceride (MCT) diet.\n\nThe South Beach Diet is a commercial weight-loss plan focused on lean proteins and healthy fats. Unlike medical ketogenic therapies, it is not designed, structured, or used as a clinical treatment for pediatric epilepsy or seizure control.","whyWrongChoices":"Alternative options: Classical Ketogenic Diet, Modified Atkins Diet for Epilepsy, Low Glycemic Index"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compared with cow''s milk, breastmilk contains::::less protein and minerals', 'compared with cow''s milk, breastmilk contains:', 'less protein and minerals', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Human breastmilk has a substantially lower protein and mineral (ash) content than cow''s milk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"less protein and minerals\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Human breastmilk has a substantially lower protein and mineral (ash) content than cow''s milk.","whyWrongChoices":"Alternative options: more protein and minerals, less lactose and vitamin C, more fat and less carbohydrates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the types of medical ketogenic diet for epilepsy in children are the following except::::', 'the types of medical ketogenic diet for epilepsy in children are the following except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"There are four primary types of medically supervised dietary therapies used to treat drug-resistant epilepsy in children. These include the Classical Ketogenic Diet, the Modified Atkins Diet (MAD), the Low Glycemic Index Treatment (LGIT), and the Medium-Chain Triglyceride (MCT) diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"South Beach Diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"There are four primary types of medically supervised dietary therapies used to treat drug-resistant epilepsy in children. These include the Classical Ketogenic Diet, the Modified Atkins Diet (MAD), the Low Glycemic Index Treatment (LGIT), and the Medium-Chain Triglyceride (MCT) diet.\n\nThe South Beach Diet is a commercial weight-loss plan focused on lean proteins and healthy fats. Unlike medical ketogenic therapies, it is not designed, structured, or used as a clinical treatment for pediatric epilepsy or seizure control.","whyWrongChoices":"Alternative options: Classical Ketogenic Diet, Modified Atkins Diet for Epilepsy, Low Glycemic Index"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the medical chart , the medical prefix " phagia " means ::::to eat', 'in the medical chart , the medical prefix " phagia " means :', 'to eat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In medical terminology, the suffix (or root element) \"-phagia\" comes from the Greek word phagein, which means to eat or swallow.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"to eat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In medical terminology, the suffix (or root element) \"-phagia\" comes from the Greek word phagein, which means to eat or swallow.\nExamples of its use include:\n• Dysphagia: Difficulty swallowing or eating.\n• Polyphagia: Excessive eating or extreme hunger.\n• Aphagia: The inability to swallow.\n\nFor the other choices:\n• Pain is represented by the suffix -algia or -dynia (e.g., neuralgia).\n• Fear of is represented by the suffix -phobia (e.g., hydrophobia).\n• Methyl Cellulose is a bulk-forming laxative and unrelated to this medical prefix.","whyWrongChoices":"Alternative options: fear of, fear of, pain"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in the medical chart , the medical prefix " phagia " means ::::', 'in the medical chart , the medical prefix " phagia " means :', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In medical terminology, the suffix (or root element) \"-phagia\" comes from the Greek word phagein, which means to eat or swallow.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"to eat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In medical terminology, the suffix (or root element) \"-phagia\" comes from the Greek word phagein, which means to eat or swallow.\nExamples of its use include:\n• Dysphagia: Difficulty swallowing or eating.\n• Polyphagia: Excessive eating or extreme hunger.\n• Aphagia: The inability to swallow.\n\nFor the other choices:\n• Pain is represented by the suffix -algia or -dynia (e.g., neuralgia).\n• Fear of is represented by the suffix -phobia (e.g., hydrophobia).\n• Methyl Cellulose is a bulk-forming laxative and unrelated to this medical prefix.","whyWrongChoices":"Alternative options: fear of, fear of, pain"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:qa is placed on long-term prednisone treatment. what two complications of high-dose prednisone therapy require nutritional intervention?:::weight gain that may lead to obesity', 'qa is placed on long-term prednisone treatment. what two complications of high-dose prednisone therapy require nutritional intervention?', 'weight gain that may lead to obesity', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient undergoes long-term, high-dose corticosteroid treatment like prednisone, the drug fundamentally alters systemic metabolism, presenting complications that heavily demand structured nutritional intervention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"weight gain that may lead to obesity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient undergoes long-term, high-dose corticosteroid treatment like prednisone, the drug fundamentally alters systemic metabolism, presenting complications that heavily demand structured nutritional intervention.\n\nPrednisone significantly alters hunger and satiety neurological cues, triggering intense appetite stimulation, constant food cravings, and metabolic fat redistribution. This rapid increase in calorie intake, coupled with sodium and fluid retention, leads to rapid weight gain and obesity if left unmanaged, necessitating low-calorie, low-sodium weight control diets.","whyWrongChoices":"Alternative options: anorexia that may lead to weight loss, hyperglycemia, hypoglycemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:qa is placed on long-term prednisone treatment. what two complications of high-dose prednisone therapy require nutritional intervention?:::', 'qa is placed on long-term prednisone treatment. what two complications of high-dose prednisone therapy require nutritional intervention?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient undergoes long-term, high-dose corticosteroid treatment like prednisone, the drug fundamentally alters systemic metabolism, presenting complications that heavily demand structured nutritional intervention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"weight gain that may lead to obesity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient undergoes long-term, high-dose corticosteroid treatment like prednisone, the drug fundamentally alters systemic metabolism, presenting complications that heavily demand structured nutritional intervention.\n\nPrednisone significantly alters hunger and satiety neurological cues, triggering intense appetite stimulation, constant food cravings, and metabolic fat redistribution. This rapid increase in calorie intake, coupled with sodium and fluid retention, leads to rapid weight gain and obesity if left unmanaged, necessitating low-calorie, low-sodium weight control diets.","whyWrongChoices":"Alternative options: anorexia that may lead to weight loss, hyperglycemia, hypoglycemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are polymeric formula containing except::::nutrican', 'the following are polymeric formula containing except:', 'Nutrican', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrican is not a standard polymeric formula. It is a disease-specific, specialized formula meticulously engineered for oncology (cancer) patients. It contains specialized immune-modulating nutrients, specialized high-protein segments, and EPA (omega-3 fatty acids) targeting the prevention of cancer cachexia (muscle wasting) rather than general standard requirements.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrican\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrican is not a standard polymeric formula. It is a disease-specific, specialized formula meticulously engineered for oncology (cancer) patients. It contains specialized immune-modulating nutrients, specialized high-protein segments, and EPA (omega-3 fatty acids) targeting the prevention of cancer cachexia (muscle wasting) rather than general standard requirements.\n\nEnsure Gold, Nutren Fiber, and Fresubin Fiber are all classic polymeric (standard) enteral formulas. They contain intact, non-hydrolyzed macros (whole proteins, complex carbohydrates, and long-chain fats) designed for patients with normal gastrointestinal digestion and absorptive capacities.","whyWrongChoices":"Alternative options: Ensure Gold, Nutren Fiber, Fresubin Fiber"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are polymeric formula containing except::::', 'the following are polymeric formula containing except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrican is not a standard polymeric formula. It is a disease-specific, specialized formula meticulously engineered for oncology (cancer) patients. It contains specialized immune-modulating nutrients, specialized high-protein segments, and EPA (omega-3 fatty acids) targeting the prevention of cancer cachexia (muscle wasting) rather than general standard requirements.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrican\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrican is not a standard polymeric formula. It is a disease-specific, specialized formula meticulously engineered for oncology (cancer) patients. It contains specialized immune-modulating nutrients, specialized high-protein segments, and EPA (omega-3 fatty acids) targeting the prevention of cancer cachexia (muscle wasting) rather than general standard requirements.\n\nEnsure Gold, Nutren Fiber, and Fresubin Fiber are all classic polymeric (standard) enteral formulas. They contain intact, non-hydrolyzed macros (whole proteins, complex carbohydrates, and long-chain fats) designed for patients with normal gastrointestinal digestion and absorptive capacities.","whyWrongChoices":"Alternative options: Ensure Gold, Nutren Fiber, Fresubin Fiber"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following diet history method reduces error due to reliance on “recall”:::food diary / record', 'which of the following diet history method reduces error due to reliance on “recall”', 'Food Diary / record', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food Diary / Record is a prospective method. The patient or respondent is instructed to log, weigh, or estimate all food and beverages in real-time at the exact moment they are being consumed. Because the data is documented immediately as the eating event happens, it completely eliminates the reliance on human memory or \"recall\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food Diary / record\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food Diary / Record is a prospective method. The patient or respondent is instructed to log, weigh, or estimate all food and beverages in real-time at the exact moment they are being consumed. Because the data is documented immediately as the eating event happens, it completely eliminates the reliance on human memory or \"recall\".\n\nOn the other hand, the 24-Hour food recall, Food frequency questionnaire, and generic Nutrient intake records are all retrospective methods. They require the patient to look back in time and mentally reconstruct what they ate over the past day, week, or month. As a result, these three methods are highly vulnerable to severe memory lapses, recall bias, and portion-estimation errors.","whyWrongChoices":"Alternative options: Nutrient Intake record, 24 Hour food recall, Food frequency"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following diet history method reduces error due to reliance on “recall”:::', 'which of the following diet history method reduces error due to reliance on “recall”', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food Diary / Record is a prospective method. The patient or respondent is instructed to log, weigh, or estimate all food and beverages in real-time at the exact moment they are being consumed. Because the data is documented immediately as the eating event happens, it completely eliminates the reliance on human memory or \"recall\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food Diary / record\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food Diary / Record is a prospective method. The patient or respondent is instructed to log, weigh, or estimate all food and beverages in real-time at the exact moment they are being consumed. Because the data is documented immediately as the eating event happens, it completely eliminates the reliance on human memory or \"recall\".\n\nOn the other hand, the 24-Hour food recall, Food frequency questionnaire, and generic Nutrient intake records are all retrospective methods. They require the patient to look back in time and mentally reconstruct what they ate over the past day, week, or month. As a result, these three methods are highly vulnerable to severe memory lapses, recall bias, and portion-estimation errors.","whyWrongChoices":"Alternative options: Nutrient Intake record, 24 Hour food recall, Food frequency"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compared with cow''s milk, breastmilk contains::::', 'compared with cow''s milk, breastmilk contains:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Human breastmilk has a substantially lower protein and mineral (ash) content than cow''s milk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"less protein and minerals\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Human breastmilk has a substantially lower protein and mineral (ash) content than cow''s milk.","whyWrongChoices":"Alternative options: more protein and minerals, less lactose and vitamin C, more fat and less carbohydrates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:anticipated need for tube feeding will require < 6-8 weeks:::nasogastric', 'anticipated need for tube feeding will require < 6-8 weeks', 'nasogastric', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral feeding access routes are primarily selected based on the anticipated duration of the nutritional support:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nasogastric\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral feeding access routes are primarily selected based on the anticipated duration of the nutritional support:\n\n• Short-Term Support (< 4–8 Weeks): Non-surgical, transnasal access routes are indicated. The nasogastric (NG) tube is the primary choice for short-term feeding (typically lasting up to 6 to 8 weeks) because it can be placed quickly at the bedside without requiring surgical, endoscopic, or radiological interventions.\n\nLong-Term Support (> 6–8 Weeks): When tube feeding is expected to exceed 6 to 8 weeks, clinicians transition to permanent or semi-permanent enterostomies placed directly through the abdominal wall, such as PEG (Percutaneous Endoscopic Gastrostomy) or JEG (Jejunostomy) tubes, to minimize nasal mucosal irritation and lower the risk of tube displacement.","whyWrongChoices":"Alternative options: nasojejunostomy, PEG, JEG"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:anticipated need for tube feeding will require < 6-8 weeks:::', 'anticipated need for tube feeding will require < 6-8 weeks', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral feeding access routes are primarily selected based on the anticipated duration of the nutritional support:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nasogastric\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral feeding access routes are primarily selected based on the anticipated duration of the nutritional support:\n\n• Short-Term Support (< 4–8 Weeks): Non-surgical, transnasal access routes are indicated. The nasogastric (NG) tube is the primary choice for short-term feeding (typically lasting up to 6 to 8 weeks) because it can be placed quickly at the bedside without requiring surgical, endoscopic, or radiological interventions.\n\nLong-Term Support (> 6–8 Weeks): When tube feeding is expected to exceed 6 to 8 weeks, clinicians transition to permanent or semi-permanent enterostomies placed directly through the abdominal wall, such as PEG (Percutaneous Endoscopic Gastrostomy) or JEG (Jejunostomy) tubes, to minimize nasal mucosal irritation and lower the risk of tube displacement.","whyWrongChoices":"Alternative options: nasojejunostomy, PEG, JEG"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop how many calories will mr. rh receive in 24 hours?:::1386 calories', 'rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop how many calories will mr. rh receive in 24 hours?', '1386 Calories', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the total amount of calories the patient receives in a 24-hour period, calculate the energy provided across all feedings:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1386 Calories\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the total amount of calories the patient receives in a 24-hour period, calculate the energy provided across all feedings:\n\n1. Calculate Calories per feeding:\n6 scoops × 38.5 Calories per scoop = 231 Calories per feeding\n2. Calculate Total Daily Calories:\nThe prescription states the solution is divided into 6 feedings over the day.\n231 Calories per feeding × 6 feedings = 1,386 Calories in 24 hours","whyWrongChoices":"Alternative options: 1200 Calories, 1450 Calories, 1500 Calories"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop how many calories will mr. rh receive in 24 hours?:::', 'rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop how many calories will mr. rh receive in 24 hours?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the total amount of calories the patient receives in a 24-hour period, calculate the energy provided across all feedings:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1386 Calories\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the total amount of calories the patient receives in a 24-hour period, calculate the energy provided across all feedings:\n\n1. Calculate Calories per feeding:\n6 scoops × 38.5 Calories per scoop = 231 Calories per feeding\n2. Calculate Total Daily Calories:\nThe prescription states the solution is divided into 6 feedings over the day.\n231 Calories per feeding × 6 feedings = 1,386 Calories in 24 hours","whyWrongChoices":"Alternative options: 1200 Calories, 1450 Calories, 1500 Calories"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the total dilution per cc of the prescribed diet for mr. rh?:::1', 'rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the total dilution per cc of the prescribed diet for mr. rh?', '1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the total dilution (caloric density) per cc of the formula, calculate the calories compared to the water volume:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the total dilution (caloric density) per cc of the formula, calculate the calories compared to the water volume:\n\n1. Calculate Calories per feeding:\n• 6 scoops x 38.5 Calories per scoop = 231 Calories\n2. Determine Total Volume per feeding:\n• The 6 scoops are dissolved in 230 mL (cc) of water.\n3. Calculate Caloric Density:\n• 231 Calories / 230 cc = 1.0 Calorie per cc","whyWrongChoices":"Alternative options: 0.9:1, 0.5:1, 5:1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the total dilution per cc of the prescribed diet for mr. rh?:::', 'rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the total dilution per cc of the prescribed diet for mr. rh?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the total dilution (caloric density) per cc of the formula, calculate the calories compared to the water volume:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the total dilution (caloric density) per cc of the formula, calculate the calories compared to the water volume:\n\n1. Calculate Calories per feeding:\n• 6 scoops x 38.5 Calories per scoop = 231 Calories\n2. Determine Total Volume per feeding:\n• The 6 scoops are dissolved in 230 mL (cc) of water.\n3. Calculate Caloric Density:\n• 231 Calories / 230 cc = 1.0 Calorie per cc","whyWrongChoices":"Alternative options: 0.9:1, 0.5:1, 5:1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the bmi of mr. rh?:::24.6', 'rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the bmi of mr. rh?', '24.6', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"24.6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).\n1. Convert Height to Inches:\n\t• 5 feet 4 inches = 64 inches\n2. Standard Metric Conversion Steps:\n\t• Precise Conversion: 64 inches × 0.0254 = 1.6256 meters\n\t• Height Squared = 1.6256 meters x 1.6256 meters = 2.6426\n• BMI = 65 kg / 2.6426 = 24.59 ~ 24.6","whyWrongChoices":"Alternative options: 23.4, 25.0, 25.1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the bmi of mr. rh?:::', 'rh, a 70year old female, admitted with a diagnosis of cvd infarct left frontal lobe, weight: 65 kg. height 5’4 “ gsc glasgow coma scale 8 the attending physician gave a diet prescription tf ensure 6 scoops in 230 ml water divided into 6 feedings ensure 9 grams per scoop = 38.5 calories 5.16 grams carbohydrates 1.43 grams protein fats 1.26 grams per scoop what is the bmi of mr. rh?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"24.6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).\n1. Convert Height to Inches:\n\t• 5 feet 4 inches = 64 inches\n2. Standard Metric Conversion Steps:\n\t• Precise Conversion: 64 inches × 0.0254 = 1.6256 meters\n\t• Height Squared = 1.6256 meters x 1.6256 meters = 2.6426\n• BMI = 65 kg / 2.6426 = 24.59 ~ 24.6","whyWrongChoices":"Alternative options: 23.4, 25.0, 25.1"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:for atonic constipation, the following are the medical nutrition therapy required except::::low fiber, agar – agar', 'for atonic constipation, the following are the medical nutrition therapy required except:', 'Low Fiber, agar – agar', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low-fiber diet reduces stool bulk and slows down intestinal transit, which would severely worsen atonic constipation. Agar-agar, while a thickening agent, is a hydrocolloid that acts as a structural soluble fiber; pairing it with \"Low Fiber\" forms a contradictory and clinically incorrect dietary prescription.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Low Fiber, agar – agar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low-fiber diet reduces stool bulk and slows down intestinal transit, which would severely worsen atonic constipation. Agar-agar, while a thickening agent, is a hydrocolloid that acts as a structural soluble fiber; pairing it with \"Low Fiber\" forms a contradictory and clinically incorrect dietary prescription.","whyWrongChoices":"Alternative options: Probiotics, High Fiber, agar – agar, High Fiber, Liberal Fruits"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to avoid conflict in authority, all workers should::::', 'to avoid conflict in authority, all workers should:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Unity of command requires each worker to know the person to whom they are directly responsible, helping avoid conflicting authority.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Know to whom they are directly responsible\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Unity of command requires each worker to know the person to whom they are directly responsible, helping avoid conflicting authority.","whyWrongChoices":"Alternative options: Be directly responsible to the head of the department, Cooperate with each other, Be rotated in different sections"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
