INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:prosure is an enteral formula for the following disease condition except:::', 'prosure is an enteral formula for the following disease condition except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"ProSure (manufactured by Abbott) is an energy-dense, high-protein enteral formula explicitly enriched with EPA (Eicosapentaenoic Acid), an omega-3 fatty acid. It is scientifically designed to combat tumor-induced inflammation and reverse cachexia (muscle and weight loss) specifically in cancer patients. Decubitus ulcers (bedsores or pressure ulcers) require a different therapeutic nutrient profile—typically high-protein formulas enriched with HMB, Arginine, and Glutamine (such as Juvenaid or Abound) to drive rapid skin and subcutaneous tissue reconstruction.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decubitus Ulcers\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"ProSure (manufactured by Abbott) is an energy-dense, high-protein enteral formula explicitly enriched with EPA (Eicosapentaenoic Acid), an omega-3 fatty acid. It is scientifically designed to combat tumor-induced inflammation and reverse cachexia (muscle and weight loss) specifically in cancer patients. Decubitus ulcers (bedsores or pressure ulcers) require a different therapeutic nutrient profile—typically high-protein formulas enriched with HMB, Arginine, and Glutamine (such as Juvenaid or Abound) to drive rapid skin and subcutaneous tissue reconstruction.","whyWrongChoices":"Alternative options: Anterior Neck mass, Cancer of the breast, Esophageal cancer"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are complications related to parenteral nutrition except:::diarrhea', 'the following are complications related to parenteral nutrition except', 'Diarrhea', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diarrhea is a classic gastrointestinal complication associated directly with Enteral Nutrition (tube feeding), often triggered by rapid infusion rates, high solution osmolality, or liquid medications. Because Parenteral Nutrition (PN) completely bypasses the gastrointestinal tract and is infused directly into the bloodstream, it does not cause diarrhea.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diarrhea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diarrhea is a classic gastrointestinal complication associated directly with Enteral Nutrition (tube feeding), often triggered by rapid infusion rates, high solution osmolality, or liquid medications. Because Parenteral Nutrition (PN) completely bypasses the gastrointestinal tract and is infused directly into the bloodstream, it does not cause diarrhea.\n\nThe remaining options are standard, documented complications of PN:\n\t• Air embolism & Pneumothorax: These are serious mechanical complications related directly to inserting or maintaining a central venous catheter tip in the superior vena cava.\n\t• Hypoglycemia: This is a critical metabolic complication that typically occurs if a hyperosmolar PN infusion bag is abruptly stopped or discontinued without being tapered down gradually.","whyWrongChoices":"Alternative options: Air embolism, Pneumothorax, Hypoglycemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are complications related to parenteral nutrition except:::', 'the following are complications related to parenteral nutrition except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diarrhea is a classic gastrointestinal complication associated directly with Enteral Nutrition (tube feeding), often triggered by rapid infusion rates, high solution osmolality, or liquid medications. Because Parenteral Nutrition (PN) completely bypasses the gastrointestinal tract and is infused directly into the bloodstream, it does not cause diarrhea.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diarrhea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diarrhea is a classic gastrointestinal complication associated directly with Enteral Nutrition (tube feeding), often triggered by rapid infusion rates, high solution osmolality, or liquid medications. Because Parenteral Nutrition (PN) completely bypasses the gastrointestinal tract and is infused directly into the bloodstream, it does not cause diarrhea.\n\nThe remaining options are standard, documented complications of PN:\n\t• Air embolism & Pneumothorax: These are serious mechanical complications related directly to inserting or maintaining a central venous catheter tip in the superior vena cava.\n\t• Hypoglycemia: This is a critical metabolic complication that typically occurs if a hyperosmolar PN infusion bag is abruptly stopped or discontinued without being tapered down gradually.","whyWrongChoices":"Alternative options: Air embolism, Pneumothorax, Hypoglycemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:monitoring of metabolic parameters in patients on parenteral nutrition is done daily except:::blood pressure', 'monitoring of metabolic parameters in patients on parenteral nutrition is done daily except', 'Blood Pressure', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When evaluating the metabolic parameters of a patient on Parenteral Nutrition (PN), clinicians track chemical and laboratory-based values related to how the body processes the heavy load of intravenous dextrose, lipids, proteins, and minerals:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Blood Pressure\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When evaluating the metabolic parameters of a patient on Parenteral Nutrition (PN), clinicians track chemical and laboratory-based values related to how the body processes the heavy load of intravenous dextrose, lipids, proteins, and minerals:\n\nWhile Blood Pressure is closely monitored as part of the patient''s vital signs or overall clinical tracking, it is classified as a hemodynamic parameter, not a metabolic or laboratory biochemical parameter.\n\n\t• Blood levels: General blood chemistry tests (including basic metabolic panels and serum glucose) must be run daily when starting PN to catch immediate metabolic complications.\n\t• Urine Glucose: Checking urine for glucose (glycosuria) is done daily to quickly screen for a patient''s inability to handle the massive carbohydrate (dextrose) load before full blood lab panels return.\n\t• Phosphorus and Magnesium: These specific electrolytes must be checked daily during the initial phase of PN to monitor for Refeeding Syndrome, a fatal drop in these minerals triggered as the body moves from a starving state to metabolizing intravenous nutrients.","whyWrongChoices":"Alternative options: Blood levels, Urine Glucose, Phosphorus and Magnesium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:monitoring of metabolic parameters in patients on parenteral nutrition is done daily except:::', 'monitoring of metabolic parameters in patients on parenteral nutrition is done daily except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When evaluating the metabolic parameters of a patient on Parenteral Nutrition (PN), clinicians track chemical and laboratory-based values related to how the body processes the heavy load of intravenous dextrose, lipids, proteins, and minerals:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Blood Pressure\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When evaluating the metabolic parameters of a patient on Parenteral Nutrition (PN), clinicians track chemical and laboratory-based values related to how the body processes the heavy load of intravenous dextrose, lipids, proteins, and minerals:\n\nWhile Blood Pressure is closely monitored as part of the patient''s vital signs or overall clinical tracking, it is classified as a hemodynamic parameter, not a metabolic or laboratory biochemical parameter.\n\n\t• Blood levels: General blood chemistry tests (including basic metabolic panels and serum glucose) must be run daily when starting PN to catch immediate metabolic complications.\n\t• Urine Glucose: Checking urine for glucose (glycosuria) is done daily to quickly screen for a patient''s inability to handle the massive carbohydrate (dextrose) load before full blood lab panels return.\n\t• Phosphorus and Magnesium: These specific electrolytes must be checked daily during the initial phase of PN to monitor for Refeeding Syndrome, a fatal drop in these minerals triggered as the body moves from a starving state to metabolizing intravenous nutrients.","whyWrongChoices":"Alternative options: Blood levels, Urine Glucose, Phosphorus and Magnesium"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:clostridium botulinum can be completely destroyed only at:::', 'clostridium botulinum can be completely destroyed only at', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Commercial sterilization of low-acid canned foods requires temperatures around 121°C under pressure to destroy highly heat-resistant spores such as those of Clostridium botulinum. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"at 121ºC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Commercial sterilization of low-acid canned foods requires temperatures around 121°C under pressure to destroy highly heat-resistant spores such as those of Clostridium botulinum. \n\nBoiling at 100°C is insufficient for this purpose.","whyWrongChoices":"Alternative options: very high pH, very alkaline condition, at 100ºC"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:maternal death is the death of a woman while pregnant or within days of termination of pregnancy.:::', 'maternal death is the death of a woman while pregnant or within days of termination of pregnancy.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The WHO defines maternal death as the death of a woman while pregnant, or within 42 days of the termination of pregnancy, from any cause related to or aggravated by the pregnancy or its management, excluding accidental or incidental causes (WHO, 2019).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"42\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The WHO defines maternal death as the death of a woman while pregnant, or within 42 days of the termination of pregnancy, from any cause related to or aggravated by the pregnancy or its management, excluding accidental or incidental causes (WHO, 2019).","whyWrongChoices":"Alternative options: 36, 40, 48"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for colonic diverticulitis includes:::general liquid diet to soft diet', 'nutrition therapy for colonic diverticulitis includes', 'General Liquid Diet to Soft Diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Colonic diverticulitis is the acute inflammation or infection of the small pouches (diverticula) that line the intestinal wall. During an acute flare-up, the primary clinical goal is bowel rest to give the inflamed colon tissues time to heal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"General Liquid Diet to Soft Diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Colonic diverticulitis is the acute inflammation or infection of the small pouches (diverticula) that line the intestinal wall. During an acute flare-up, the primary clinical goal is bowel rest to give the inflamed colon tissues time to heal.\n\nNutrition therapy begins by removing all solid foods and fiber to prevent irritating the bowel wall. The patient transitions from a strict clear liquid diet (or NPO) up to a general liquid diet. As symptoms resolve and pain decreases, the diet is slowly advanced to a low-residue, low-fiber soft diet (such as eggs, white pasta, and well-cooked poultry) before gradually introducing high-fiber whole foods during long-term recovery.\n\n\t• Purgatives (strong laxatives) and colonic lavage are strictly dangerous during acute diverticulitis because increasing bowel peristalsis risks perforating or rupturing the inflamed colonic pouches.\n\t• Omeprazole (a proton pump inhibitor for stomach acid) and medications like sedatives or antispasmodics fall under medical/pharmacological treatments, not Nutrition Therapy.","whyWrongChoices":"Alternative options: Use of sedative, tranquilizers, and anti- spasmodic drugs, Purgatives and Colonic Lavage, Use of Omeprazole"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for colonic diverticulitis includes:::', 'nutrition therapy for colonic diverticulitis includes', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Colonic diverticulitis is the acute inflammation or infection of the small pouches (diverticula) that line the intestinal wall. During an acute flare-up, the primary clinical goal is bowel rest to give the inflamed colon tissues time to heal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"General Liquid Diet to Soft Diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Colonic diverticulitis is the acute inflammation or infection of the small pouches (diverticula) that line the intestinal wall. During an acute flare-up, the primary clinical goal is bowel rest to give the inflamed colon tissues time to heal.\n\nNutrition therapy begins by removing all solid foods and fiber to prevent irritating the bowel wall. The patient transitions from a strict clear liquid diet (or NPO) up to a general liquid diet. As symptoms resolve and pain decreases, the diet is slowly advanced to a low-residue, low-fiber soft diet (such as eggs, white pasta, and well-cooked poultry) before gradually introducing high-fiber whole foods during long-term recovery.\n\n\t• Purgatives (strong laxatives) and colonic lavage are strictly dangerous during acute diverticulitis because increasing bowel peristalsis risks perforating or rupturing the inflamed colonic pouches.\n\t• Omeprazole (a proton pump inhibitor for stomach acid) and medications like sedatives or antispasmodics fall under medical/pharmacological treatments, not Nutrition Therapy.","whyWrongChoices":"Alternative options: Use of sedative, tranquilizers, and anti- spasmodic drugs, Purgatives and Colonic Lavage, Use of Omeprazole"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for inflammatory bowel disease:::high calorie, high protein, small frequent feeding, low fiber', 'nutrition therapy for inflammatory bowel disease', 'High Calorie, High Protein, small frequent feeding, low fiber', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When managing a patient with Inflammatory Bowel Disease, the nutritional goals focus on healing damaged intestinal tissue, overcoming malabsorption, and minimizing bowel irritation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High Calorie, High Protein, small frequent feeding, low fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When managing a patient with Inflammatory Bowel Disease, the nutritional goals focus on healing damaged intestinal tissue, overcoming malabsorption, and minimizing bowel irritation:\n\n• High Calorie & High Protein: Severe intestinal inflammation causes protein-losing enteropathy, tissue damage, and weight loss. Elevated calories and proteins are necessary to rebuild tissues and prevent malnutrition.\n• Small, Frequent Feedings: Breaking food intake into smaller, more frequent meals throughout the day reduces the functional workload on an already inflamed gastrointestinal tract, lessening cramps and bloating.\n• Low Fiber: During periods of inflammation or flare-ups, dietary fiber must be minimized. High-fiber foods can physically scratch and irritate the raw lining of the colon, accelerating peristalsis and worsening diarrhea, cramping, and nutrient malabsorption.","whyWrongChoices":"Alternative options: High Calorie, High Protein, small frequent feeding, high fiber, High Calorie, High Protein, small frequent feeding, adequate fluid, High Calorie, High Protein, 3 meals and 3 snacks, high residue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for inflammatory bowel disease:::', 'nutrition therapy for inflammatory bowel disease', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When managing a patient with Inflammatory Bowel Disease, the nutritional goals focus on healing damaged intestinal tissue, overcoming malabsorption, and minimizing bowel irritation:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High Calorie, High Protein, small frequent feeding, low fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When managing a patient with Inflammatory Bowel Disease, the nutritional goals focus on healing damaged intestinal tissue, overcoming malabsorption, and minimizing bowel irritation:\n\n• High Calorie & High Protein: Severe intestinal inflammation causes protein-losing enteropathy, tissue damage, and weight loss. Elevated calories and proteins are necessary to rebuild tissues and prevent malnutrition.\n• Small, Frequent Feedings: Breaking food intake into smaller, more frequent meals throughout the day reduces the functional workload on an already inflamed gastrointestinal tract, lessening cramps and bloating.\n• Low Fiber: During periods of inflammation or flare-ups, dietary fiber must be minimized. High-fiber foods can physically scratch and irritate the raw lining of the colon, accelerating peristalsis and worsening diarrhea, cramping, and nutrient malabsorption.","whyWrongChoices":"Alternative options: High Calorie, High Protein, small frequent feeding, high fiber, High Calorie, High Protein, small frequent feeding, adequate fluid, High Calorie, High Protein, 3 meals and 3 snacks, high residue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:ef, 90 year old female, admitted at the hospital with a diagnosis of irritable bowel syndrome, with a history of 5 episodes of loose bowel movement, height 5’ 2” weight 49.9 kg serum albumin 2.8 g/dl (normal level 3.5 – 5.0 g/dl). compute for the patient’s bmi, choose the best answer:::bmi 20', 'ef, 90 year old female, admitted at the hospital with a diagnosis of irritable bowel syndrome, with a history of 5 episodes of loose bowel movement, height 5’ 2” weight 49.9 kg serum albumin 2.8 g/dl (normal level 3.5 – 5.0 g/dl). compute for the patient’s bmi, choose the best answer', 'BMI 20', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To find the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"BMI 20\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To find the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).\n\n1. Convert Height to Meters:\n\t• 5 feet 2 inches = 62 inches\n\t• 62 inches × 0.0254 = 1.575 meters\n2. Calculate BMI:\n• BMI = 49.9 / 1.575²\n• BMI = 49.9 / 2.48\n• BMI = 20.12 ~ 20 kg/m²","whyWrongChoices":"Alternative options: BMI 22, BMI 21, BMI 19"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for appendicitis plays a supportive role when patient is on npo, before and after surgery. if patient will resume diet, liquid diets are prescribed:::tea, juice, hard candy, jello', 'nutrition therapy for appendicitis plays a supportive role when patient is on npo, before and after surgery. if patient will resume diet, liquid diets are prescribed', 'Tea, juice, hard candy, jello', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient is transitioning off NPO (Nothing by Mouth) status after surgery for appendicitis, the gastrointestinal tract needs time to safely wake up and resume normal function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tea, juice, hard candy, jello\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient is transitioning off NPO (Nothing by Mouth) status after surgery for appendicitis, the gastrointestinal tract needs time to safely wake up and resume normal function.\n\nThe very first step after NPO status is a clear liquid diet. This consists exclusively of transparent fluids that are easily digested, leave absolutely no residue in the intestinal tract, and do not stimulate painful bowel contractions. Tea, fruit juice (without pulp), hard candy, and jello are standard examples of a clear liquid diet.","whyWrongChoices":"Alternative options: Soft Boiled Egg, Strained Lugao, Ensure 3 scoops three times a day, Ensure 6 scoops three times a day"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for appendicitis plays a supportive role when patient is on npo, before and after surgery. if patient will resume diet, liquid diets are prescribed:::', 'nutrition therapy for appendicitis plays a supportive role when patient is on npo, before and after surgery. if patient will resume diet, liquid diets are prescribed', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a patient is transitioning off NPO (Nothing by Mouth) status after surgery for appendicitis, the gastrointestinal tract needs time to safely wake up and resume normal function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tea, juice, hard candy, jello\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a patient is transitioning off NPO (Nothing by Mouth) status after surgery for appendicitis, the gastrointestinal tract needs time to safely wake up and resume normal function.\n\nThe very first step after NPO status is a clear liquid diet. This consists exclusively of transparent fluids that are easily digested, leave absolutely no residue in the intestinal tract, and do not stimulate painful bowel contractions. Tea, fruit juice (without pulp), hard candy, and jello are standard examples of a clear liquid diet.","whyWrongChoices":"Alternative options: Soft Boiled Egg, Strained Lugao, Ensure 3 scoops three times a day, Ensure 6 scoops three times a day"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition therapy for hemorrhoids includes the following except:::use of kankunis', 'nutrition therapy for hemorrhoids includes the following except', 'Use of Kankunis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Kankunis is a commercial herbal tea typically marketed for weight loss and constipation that contains senna or other stimulant laxatives. Stimulant laxatives work by triggering enteric nervous system contractions and altering electrolyte transport in the colon (specifically inhibiting Na+/K+-ATPase and stimulating prostaglandin-cAMP pathways), which induces acute diarrhea and cramping. In hemorrhoidal disease, forceful peristalsis, frequent watery stools, and straining caused by harsh laxatives increase pelvic venous pressure and exacerbate anal mucosal inflammation and thrombosis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Use of Kankunis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Kankunis is a commercial herbal tea typically marketed for weight loss and constipation that contains senna or other stimulant laxatives. Stimulant laxatives work by triggering enteric nervous system contractions and altering electrolyte transport in the colon (specifically inhibiting Na+/K+-ATPase and stimulating prostaglandin-cAMP pathways), which induces acute diarrhea and cramping. In hemorrhoidal disease, forceful peristalsis, frequent watery stools, and straining caused by harsh laxatives increase pelvic venous pressure and exacerbate anal mucosal inflammation and thrombosis.","whyWrongChoices":"Alternative options: 8- 10 glasses of fluids per day, Low Fiber, Exclude highly seasoned foods and relishes"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:weeping out of liquid from gelatinized starch during prolonged storage:::syneresis', 'weeping out of liquid from gelatinized starch during prolonged storage', 'syneresis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Syneresis is the weeping or separation of liquid from a starch or gel network during storage. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"syneresis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Syneresis is the weeping or separation of liquid from a starch or gel network during storage. \n\nRetrogradation is a broader starch reassociation process that can contribute to syneresis.","whyWrongChoices":"Alternative options: retrogradation, gelatinization, gelation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
