INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:it refers to the measurement of indicators of dietary status and nutrition-related health status to identify the possible occurrence, nature, and extent of impaired nutritional status.:::nutrition assessment', 'it refers to the measurement of indicators of dietary status and nutrition-related health status to identify the possible occurrence, nature, and extent of impaired nutritional status.', 'nutrition assessment', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition assessment is the comprehensive evaluation of anthropometric, biochemical, clinical, dietary indicators used to determine whether, and to what extent, malnutrition is present in an individual or population. It is broader and more detailed than screening, which is a rapid, single-indicator method used to identify individuals at risk, and it differs from surveillance, which involves continuous, ongoing data collection used to track trends over time rather than to diagnose status at one point in time.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nutrition assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition assessment is the comprehensive evaluation of anthropometric, biochemical, clinical, dietary indicators used to determine whether, and to what extent, malnutrition is present in an individual or population. It is broader and more detailed than screening, which is a rapid, single-indicator method used to identify individuals at risk, and it differs from surveillance, which involves continuous, ongoing data collection used to track trends over time rather than to diagnose status at one point in time.","whyWrongChoices":"Alternative options: nutrition screening, nutrition intervention, nutrition surveillance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it refers to the measurement of indicators of dietary status and nutrition-related health status to identify the possible occurrence, nature, and extent of impaired nutritional status.:::', 'it refers to the measurement of indicators of dietary status and nutrition-related health status to identify the possible occurrence, nature, and extent of impaired nutritional status.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition assessment is the comprehensive evaluation of anthropometric, biochemical, clinical, dietary indicators used to determine whether, and to what extent, malnutrition is present in an individual or population. It is broader and more detailed than screening, which is a rapid, single-indicator method used to identify individuals at risk, and it differs from surveillance, which involves continuous, ongoing data collection used to track trends over time rather than to diagnose status at one point in time.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nutrition assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition assessment is the comprehensive evaluation of anthropometric, biochemical, clinical, dietary indicators used to determine whether, and to what extent, malnutrition is present in an individual or population. It is broader and more detailed than screening, which is a rapid, single-indicator method used to identify individuals at risk, and it differs from surveillance, which involves continuous, ongoing data collection used to track trends over time rather than to diagnose status at one point in time.","whyWrongChoices":"Alternative options: nutrition screening, nutrition intervention, nutrition surveillance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are exogenous factors influencing an individual''s food intake except::::food beliefs and attitudes', 'the following are exogenous factors influencing an individual''s food intake except:', 'food beliefs and attitudes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Factors that influence food intake are classified as endogenous (internal, physiologic or psychological, arising from within the individual, such as appetite, taste preference, and personal beliefs and attitudes toward food) or exogenous (external, environmental, and social, such as income, culture, religion, food availability, and agro-climatic conditions like soil quality). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"food beliefs and attitudes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Factors that influence food intake are classified as endogenous (internal, physiologic or psychological, arising from within the individual, such as appetite, taste preference, and personal beliefs and attitudes toward food) or exogenous (external, environmental, and social, such as income, culture, religion, food availability, and agro-climatic conditions like soil quality). \n\nSocioeconomic conditions, religion, and soil condition are external environmental determinants, while food beliefs and attitudes originate from the individual''s own cognition and are therefore endogenous rather than exogenous.","whyWrongChoices":"Alternative options: soil condition, socioeconomic conditions, religion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are exogenous factors influencing an individual''s food intake except::::', 'the following are exogenous factors influencing an individual''s food intake except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Factors that influence food intake are classified as endogenous (internal, physiologic or psychological, arising from within the individual, such as appetite, taste preference, and personal beliefs and attitudes toward food) or exogenous (external, environmental, and social, such as income, culture, religion, food availability, and agro-climatic conditions like soil quality). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"food beliefs and attitudes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Factors that influence food intake are classified as endogenous (internal, physiologic or psychological, arising from within the individual, such as appetite, taste preference, and personal beliefs and attitudes toward food) or exogenous (external, environmental, and social, such as income, culture, religion, food availability, and agro-climatic conditions like soil quality). \n\nSocioeconomic conditions, religion, and soil condition are external environmental determinants, while food beliefs and attitudes originate from the individual''s own cognition and are therefore endogenous rather than exogenous.","whyWrongChoices":"Alternative options: soil condition, socioeconomic conditions, religion"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what are the colors of the characters used in the sangkap pinoy seal?:::vitamin a - yellow, iron - green, iodine - red', 'what are the colors of the characters used in the sangkap pinoy seal?', 'Vitamin A - Yellow, Iron - Green, Iodine - Red', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The characters/icons underneath the official Sangkap Pinoy Seal (SPS) follow a distinct, standardized color-coding system to denote which micronutrients are added to fortified food products:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin A - Yellow, Iron - Green, Iodine - Red\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The characters/icons underneath the official Sangkap Pinoy Seal (SPS) follow a distinct, standardized color-coding system to denote which micronutrients are added to fortified food products:\n\n• Yellow represents Vitamin A.\n• Green represents Iron.\n• Red represents Iodine.\n\nThese symbols serve as a direct visual guide for shoppers looking to combat micronutrient deficiencies while buying staple foods and processed snacks.","whyWrongChoices":"Alternative options: Vitamin A - Yellow, Iron - Red, Iodine - Green, Vitamin A - Yellow, Iron - Green, Iodine - Blue, Vitamin A - Green, Iron - Red, Iodine - Yellow"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what are the colors of the characters used in the sangkap pinoy seal?:::', 'what are the colors of the characters used in the sangkap pinoy seal?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The characters/icons underneath the official Sangkap Pinoy Seal (SPS) follow a distinct, standardized color-coding system to denote which micronutrients are added to fortified food products:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin A - Yellow, Iron - Green, Iodine - Red\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The characters/icons underneath the official Sangkap Pinoy Seal (SPS) follow a distinct, standardized color-coding system to denote which micronutrients are added to fortified food products:\n\n• Yellow represents Vitamin A.\n• Green represents Iron.\n• Red represents Iodine.\n\nThese symbols serve as a direct visual guide for shoppers looking to combat micronutrient deficiencies while buying staple foods and processed snacks.","whyWrongChoices":"Alternative options: Vitamin A - Yellow, Iron - Red, Iodine - Green, Vitamin A - Yellow, Iron - Green, Iodine - Blue, Vitamin A - Green, Iron - Red, Iodine - Yellow"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:malnutrition in a developing country is reflected in the increased specific death rate of preschoolers due to::::measles', 'malnutrition in a developing country is reflected in the increased specific death rate of preschoolers due to:', 'measles', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Malnutrition in a developing country increases the preschool death rate primarily due to infectious diseases such as measles, one of the most contagious diseases (but preventable) diseases in the world.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"measles\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Malnutrition in a developing country increases the preschool death rate primarily due to infectious diseases such as measles, one of the most contagious diseases (but preventable) diseases in the world.","whyWrongChoices":"Alternative options: diarrhea, tetanus, dengue"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:who is this filipino nutritionist and politician who served as deputy minister of health from 1983 to 1986 during the presidency of ferdinand marcos?:::dr. florentino solon', 'who is this filipino nutritionist and politician who served as deputy minister of health from 1983 to 1986 during the presidency of ferdinand marcos?', 'Dr. Florentino Solon', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dr. Florentino S. Solon was a highly influential public health physician and nutritionist widely recognized as the country''s \"champion of nutrition\". He served as the first Executive Director of both the National Nutrition Council (NNC) and the Nutrition Center of the Philippines (NCP).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dr. Florentino Solon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dr. Florentino S. Solon was a highly influential public health physician and nutritionist widely recognized as the country''s \"champion of nutrition\". He served as the first Executive Director of both the National Nutrition Council (NNC) and the Nutrition Center of the Philippines (NCP).\n\nIn politics, he was appointed by President Ferdinand Marcos Sr. as the Mayor of Cebu City, serving from 1978 until 1983. He resigned from his mayoral post in 1983 when Marcos appointed him to the national level to serve as the Deputy Minister of Health, a role he held until 1986.\n\nAmong his structural legacies in nutrition, he pioneered the establishment of specialized malnutrition wards (\"malwards\"), nutri-huts, nutri-buses, and early food-fortification initiatives like the iron and vitamin A-fortified pan de sal.\n\n• Dr. Francisco Santos: A pioneer agricultural chemist and nutritionist known for his extensive studies on the nutritional values of local Filipino foods and crops.\n• Dr. Coronado Pascual: A major public health figure who served as a Director of the Food and Nutrition Research Center (FNRC) and led early coordination attempts through the National Coordinating Council on Food and Nutrition (NCCFN) in 1959.\n• Dr. Juan Salcedo, Jr.: A celebrated National Scientist and former Secretary of Health renowned for leading the historic Bataan Rice Enrichment Project which helped eradicate beriberi in the Philippines.","whyWrongChoices":"Alternative options: Dr. Juan Salcedo, Jr., Dr. Coronado Pascual, Dr. Francisco Santos"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:who is this filipino nutritionist and politician who served as deputy minister of health from 1983 to 1986 during the presidency of ferdinand marcos?:::', 'who is this filipino nutritionist and politician who served as deputy minister of health from 1983 to 1986 during the presidency of ferdinand marcos?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dr. Florentino S. Solon was a highly influential public health physician and nutritionist widely recognized as the country''s \"champion of nutrition\". He served as the first Executive Director of both the National Nutrition Council (NNC) and the Nutrition Center of the Philippines (NCP).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dr. Florentino Solon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dr. Florentino S. Solon was a highly influential public health physician and nutritionist widely recognized as the country''s \"champion of nutrition\". He served as the first Executive Director of both the National Nutrition Council (NNC) and the Nutrition Center of the Philippines (NCP).\n\nIn politics, he was appointed by President Ferdinand Marcos Sr. as the Mayor of Cebu City, serving from 1978 until 1983. He resigned from his mayoral post in 1983 when Marcos appointed him to the national level to serve as the Deputy Minister of Health, a role he held until 1986.\n\nAmong his structural legacies in nutrition, he pioneered the establishment of specialized malnutrition wards (\"malwards\"), nutri-huts, nutri-buses, and early food-fortification initiatives like the iron and vitamin A-fortified pan de sal.\n\n• Dr. Francisco Santos: A pioneer agricultural chemist and nutritionist known for his extensive studies on the nutritional values of local Filipino foods and crops.\n• Dr. Coronado Pascual: A major public health figure who served as a Director of the Food and Nutrition Research Center (FNRC) and led early coordination attempts through the National Coordinating Council on Food and Nutrition (NCCFN) in 1959.\n• Dr. Juan Salcedo, Jr.: A celebrated National Scientist and former Secretary of Health renowned for leading the historic Bataan Rice Enrichment Project which helped eradicate beriberi in the Philippines.","whyWrongChoices":"Alternative options: Dr. Juan Salcedo, Jr., Dr. Coronado Pascual, Dr. Francisco Santos"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the 105-day expanded maternity leave law, the father may enjoy as much as how many days of paid leave to take care of his child?:::14 days', 'under the 105-day expanded maternity leave law, the father may enjoy as much as how many days of paid leave to take care of his child?', '14 days', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"RA 11210: A father may now enjoy as much as 14 days of paid leave to take care of his child, depending on his marital status with the mother.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"14 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"RA 11210: A father may now enjoy as much as 14 days of paid leave to take care of his child, depending on his marital status with the mother.","whyWrongChoices":"Alternative options: 0 days, 3 days, 7 days"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which theory explains aging as the result of chemical and mechanical exhaustion of the cells?:::wear-and-tear theory', 'which theory explains aging as the result of chemical and mechanical exhaustion of the cells?', 'Wear-and-tear Theory', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Wear-and-Tear Theory (first proposed by Dr. August Weismann in 1882) compares the human body to a machine. It posits that aging is the direct result of continuous use, where cells, tissues, and vital body parts accumulate chronic chemical and mechanical exhaustion over time from internal or external stressors. Once the damage exceeds the body''s natural capacity to repair itself, overall biological function progressively declines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Wear-and-tear Theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Wear-and-Tear Theory (first proposed by Dr. August Weismann in 1882) compares the human body to a machine. It posits that aging is the direct result of continuous use, where cells, tissues, and vital body parts accumulate chronic chemical and mechanical exhaustion over time from internal or external stressors. Once the damage exceeds the body''s natural capacity to repair itself, overall biological function progressively declines.\n\n• Clinker Theory: Focuses on the accumulation of metabolic waste products and chemical byproducts within normal cells, combining elements of mutation and cross-linking.\n• Free Radicals Theory: Specifically attributes cellular aging and damage to the destructive nature of unstable, highly reactive molecules with unpaired electrons produced during normal oxygen metabolism.\n• Generalized Errors Theory: Argues that aging occurs due to random, progressive transcription or translation mistakes during ribonucleic acid (RNA) and protein synthesis, resulting in faulty cellular structures.","whyWrongChoices":"Alternative options: Clinker Theory, Free Radicals Theory, Generalized Errors Theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which theory explains aging as the result of chemical and mechanical exhaustion of the cells?:::', 'which theory explains aging as the result of chemical and mechanical exhaustion of the cells?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Wear-and-Tear Theory (first proposed by Dr. August Weismann in 1882) compares the human body to a machine. It posits that aging is the direct result of continuous use, where cells, tissues, and vital body parts accumulate chronic chemical and mechanical exhaustion over time from internal or external stressors. Once the damage exceeds the body''s natural capacity to repair itself, overall biological function progressively declines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Wear-and-tear Theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Wear-and-Tear Theory (first proposed by Dr. August Weismann in 1882) compares the human body to a machine. It posits that aging is the direct result of continuous use, where cells, tissues, and vital body parts accumulate chronic chemical and mechanical exhaustion over time from internal or external stressors. Once the damage exceeds the body''s natural capacity to repair itself, overall biological function progressively declines.\n\n• Clinker Theory: Focuses on the accumulation of metabolic waste products and chemical byproducts within normal cells, combining elements of mutation and cross-linking.\n• Free Radicals Theory: Specifically attributes cellular aging and damage to the destructive nature of unstable, highly reactive molecules with unpaired electrons produced during normal oxygen metabolism.\n• Generalized Errors Theory: Argues that aging occurs due to random, progressive transcription or translation mistakes during ribonucleic acid (RNA) and protein synthesis, resulting in faulty cellular structures.","whyWrongChoices":"Alternative options: Clinker Theory, Free Radicals Theory, Generalized Errors Theory"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition ppas are commonly charged against gad funds in the lgu. how much of the lgu fund is allotted for gender and development?:::5%', 'nutrition ppas are commonly charged against gad funds in the lgu. how much of the lgu fund is allotted for gender and development?', '5%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pursuant to Section 36(a) of Republic Act No. 9710 (the Magna Carta of Women) and the DILG-NEDA-DBM-PCW Joint Memorandum Circular guidelines, all Local Government Units (LGUs) and national government agencies are legally mandated to allocate at least five percent (5%) of their total annual budget appropriations to support Gender and Development (GAD) plans, programs, and activities.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pursuant to Section 36(a) of Republic Act No. 9710 (the Magna Carta of Women) and the DILG-NEDA-DBM-PCW Joint Memorandum Circular guidelines, all Local Government Units (LGUs) and national government agencies are legally mandated to allocate at least five percent (5%) of their total annual budget appropriations to support Gender and Development (GAD) plans, programs, and activities.\n\nBecause public health nutrition interventions (such as supplemental feeding for pregnant women or addressing maternal and child malnutrition) target specific vulnerable gender groups, nutrition Programs, Projects, and Activities (PPAs) are frequently funded or attributed through this mandatory 5% LGU allocation.","whyWrongChoices":"Alternative options: 10%, 3%, 1%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrition ppas are commonly charged against gad funds in the lgu. how much of the lgu fund is allotted for gender and development?:::', 'nutrition ppas are commonly charged against gad funds in the lgu. how much of the lgu fund is allotted for gender and development?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pursuant to Section 36(a) of Republic Act No. 9710 (the Magna Carta of Women) and the DILG-NEDA-DBM-PCW Joint Memorandum Circular guidelines, all Local Government Units (LGUs) and national government agencies are legally mandated to allocate at least five percent (5%) of their total annual budget appropriations to support Gender and Development (GAD) plans, programs, and activities.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pursuant to Section 36(a) of Republic Act No. 9710 (the Magna Carta of Women) and the DILG-NEDA-DBM-PCW Joint Memorandum Circular guidelines, all Local Government Units (LGUs) and national government agencies are legally mandated to allocate at least five percent (5%) of their total annual budget appropriations to support Gender and Development (GAD) plans, programs, and activities.\n\nBecause public health nutrition interventions (such as supplemental feeding for pregnant women or addressing maternal and child malnutrition) target specific vulnerable gender groups, nutrition Programs, Projects, and Activities (PPAs) are frequently funded or attributed through this mandatory 5% LGU allocation.","whyWrongChoices":"Alternative options: 10%, 3%, 1%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lechon kawali is best made from this pork cut:::liempo', 'lechon kawali is best made from this pork cut', 'Liempo', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lechon kawali is best made from liempo or pork belly because its layers of meat and fat produce the characteristic rich, crisp, and succulent result.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liempo\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lechon kawali is best made from liempo or pork belly because its layers of meat and fat produce the characteristic rich, crisp, and succulent result.\n\nLomo and pigue are leaner cuts, while ribs are less suitable for the usual preparation.","whyWrongChoices":"Alternative options: Lomo, Pigue, Tadyang"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:arrange in chronological order the stages in developing a planned behavior change in nutrition education. i. recognizing the existence of a problem ii. attempting or trialing the new behavior iii. integrating the new behavior into daily routine iv. realizing that meaningful change is achievable:::i, iv, ii, iii', 'arrange in chronological order the stages in developing a planned behavior change in nutrition education. i. recognizing the existence of a problem ii. attempting or trialing the new behavior iii. integrating the new behavior into daily routine iv. realizing that meaningful change is achievable', 'I, IV, II, III', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Planned behavior change typically follows a sequence beginning with the person recognizing that a problem exists (I), followed by recognizing that a change is actually possible for them (IV), then attempting or trialing the new behavior (II), and finally, integrating that behavior as a lasting part of their routine (III) — a progression consistent with staged models of behavior adoption such as the Diffusion of Innovation and Precaution Adoption Process frameworks.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I, IV, II, III\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Planned behavior change typically follows a sequence beginning with the person recognizing that a problem exists (I), followed by recognizing that a change is actually possible for them (IV), then attempting or trialing the new behavior (II), and finally, integrating that behavior as a lasting part of their routine (III) — a progression consistent with staged models of behavior adoption such as the Diffusion of Innovation and Precaution Adoption Process frameworks.","whyWrongChoices":"Alternative options: I, II, III, IV, I, III, IV, II, IV, I, II, III"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
