INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:raw starch flavor is caused by::::', 'raw starch flavor is caused by:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A raw starch flavor results when a starch mixture form lumps that could be due to inadequate stirring or cooking. Formation of lumps can cause uneven hydration and gelatinization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lumping\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A raw starch flavor results when a starch mixture form lumps that could be due to inadequate stirring or cooking. Formation of lumps can cause uneven hydration and gelatinization.\n\nWhen starch hits hot liquid without proper separation, the outside of a clump gelatinizes instantly.\n\nThis outer sticky layer blocks liquid from reaching the inner starch. The trapped center remains ungelatinized, leaving a distinct raw flour or starch taste in the final dish.","whyWrongChoices":"Alternative options: incorrect measurements of ingredients, vigorous stirring, inadequate stirring"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vacuum-packed meats are in color:::dark brown', 'vacuum-packed meats are in color', 'Dark brown', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This color change occurs because the meat is sealed without oxygen. Meat needs oxygen to maintain its bright red color (which creates a protein called oxymyoglobin). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dark brown\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This color change occurs because the meat is sealed without oxygen. Meat needs oxygen to maintain its bright red color (which creates a protein called oxymyoglobin). \n\nWhen you open the vacuum package and expose the meat to the air for about 15 to 30 minutes, it will \"bloom\" and turn back to its normal bright red color.","whyWrongChoices":"Alternative options: Red, Pink, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vacuum-packed meats are in color:::', 'vacuum-packed meats are in color', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This color change occurs because the meat is sealed without oxygen. Meat needs oxygen to maintain its bright red color (which creates a protein called oxymyoglobin). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dark brown\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This color change occurs because the meat is sealed without oxygen. Meat needs oxygen to maintain its bright red color (which creates a protein called oxymyoglobin). \n\nWhen you open the vacuum package and expose the meat to the air for about 15 to 30 minutes, it will \"bloom\" and turn back to its normal bright red color.","whyWrongChoices":"Alternative options: Red, Pink, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:yambean is the same as::::both a and b', 'yambean is the same as:', 'Both a and b', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Yambean is another name for jicama, known in the Philippines as singkamas. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both a and b\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Yambean is another name for jicama, known in the Philippines as singkamas. \n\nTherefore, both A and B refer to the same root crop.","whyWrongChoices":"Alternative options: Jicama, Singkamas, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:yambean is the same as::::', 'yambean is the same as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Yambean is another name for jicama, known in the Philippines as singkamas. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both a and b\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Yambean is another name for jicama, known in the Philippines as singkamas. \n\nTherefore, both A and B refer to the same root crop.","whyWrongChoices":"Alternative options: Jicama, Singkamas, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an alkaline ingredient used as a leavening.:::baking soda', 'an alkaline ingredient used as a leavening.', 'Baking soda', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Baking soda is sodium bicarbonate, an alkaline leavening ingredient that releases carbon dioxide when it reacts with an acid and moisture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Baking soda\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Baking soda is sodium bicarbonate, an alkaline leavening ingredient that releases carbon dioxide when it reacts with an acid and moisture.\n\nCream of tartar and vinegar are acidic, while fruit juice may be acidic but is not the standard alkaline leavener.","whyWrongChoices":"Alternative options: Cream of tartar, Vinegar, Fruit juice"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:proportion of liquid and flour in order to make soft dough:::1 part liquid: 3 parts flour', 'proportion of liquid and flour in order to make soft dough', '1 part liquid: 3 parts flour', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In culinary arts and baking science, mixtures are categorized as either batters or doughs based on their ratio of liquid to flour.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1 part liquid: 3 parts flour\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In culinary arts and baking science, mixtures are categorized as either batters or doughs based on their ratio of liquid to flour.\n\n• Pour Batter (1:1 Ratio): Equal parts liquid and flour (e.g., pancakes, crepes, waffles).\n• Drop Batter (1:2 Ratio): One part liquid to two parts flour. It is too thick to pour but drops easily from a spoon (e.g., muffins, drop biscuits).\n• Soft Dough (1:3 Ratio): One part liquid to three parts flour. It is thick enough to be handled, kneaded, and rolled out on a floured surface while remaining pliable (e.g., rolled biscuits, scones, yeast breads).\n• Stiff Dough (1:4 to 1:8 Ratio): Very low hydration, resulting in a firm, dense consistency that is easily sliced or shaped (e.g., pie crusts, sugar cookies, noodles).","whyWrongChoices":"Alternative options: 1 part liquid: 1 part flour, 1 part liquid: 2 parts flour, 1 part liquid: 4 parts flour"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:proportion of liquid and flour in order to make soft dough:::', 'proportion of liquid and flour in order to make soft dough', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In culinary arts and baking science, mixtures are categorized as either batters or doughs based on their ratio of liquid to flour.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1 part liquid: 3 parts flour\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In culinary arts and baking science, mixtures are categorized as either batters or doughs based on their ratio of liquid to flour.\n\n• Pour Batter (1:1 Ratio): Equal parts liquid and flour (e.g., pancakes, crepes, waffles).\n• Drop Batter (1:2 Ratio): One part liquid to two parts flour. It is too thick to pour but drops easily from a spoon (e.g., muffins, drop biscuits).\n• Soft Dough (1:3 Ratio): One part liquid to three parts flour. It is thick enough to be handled, kneaded, and rolled out on a floured surface while remaining pliable (e.g., rolled biscuits, scones, yeast breads).\n• Stiff Dough (1:4 to 1:8 Ratio): Very low hydration, resulting in a firm, dense consistency that is easily sliced or shaped (e.g., pie crusts, sugar cookies, noodles).","whyWrongChoices":"Alternative options: 1 part liquid: 1 part flour, 1 part liquid: 2 parts flour, 1 part liquid: 4 parts flour"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rice that is high in amylopectin.:::waxy', 'rice that is high in amylopectin.', 'Waxy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Rice starch consists of two types of molecules: amylose and amylopectin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Waxy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Rice starch consists of two types of molecules: amylose and amylopectin.\n\nOrdinary rice contains both amylose (around 15–30%) and amylopectin. Waxy rice (also commonly known as glutinous rice or sticky rice), however, contains almost 100% amylopectin and virtually 0% amylose.\n\nAmylopectin is responsible for the sticky, gelatinous, and chewy texture of rice when cooked. This makes waxy rice the essential ingredient for traditional Filipino rice cakes (kakanin) like biko, suman, and sapin-sapin.\n\n• Pre-gelatinized: Rice that has been precooked and dried so that it cooks much faster or can dissolve in cold water (often used in instant baby food or porridge).\n• Parboiled: Rice that has been partially boiled in its husk before milling. This process drives nutrients from the husk into the grain, making it less sticky and more nutritious than regular white rice.\n• Ordinary: Regular non-glutinous table rice (like Jasmine or Sinandomeng). It contains higher levels of amylose, which allows the grains to separate easily when cooked.","whyWrongChoices":"Alternative options: Ordinary, Parboiled, pre-gelatinized"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:rice that is high in amylopectin.:::', 'rice that is high in amylopectin.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Rice starch consists of two types of molecules: amylose and amylopectin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Waxy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Rice starch consists of two types of molecules: amylose and amylopectin.\n\nOrdinary rice contains both amylose (around 15–30%) and amylopectin. Waxy rice (also commonly known as glutinous rice or sticky rice), however, contains almost 100% amylopectin and virtually 0% amylose.\n\nAmylopectin is responsible for the sticky, gelatinous, and chewy texture of rice when cooked. This makes waxy rice the essential ingredient for traditional Filipino rice cakes (kakanin) like biko, suman, and sapin-sapin.\n\n• Pre-gelatinized: Rice that has been precooked and dried so that it cooks much faster or can dissolve in cold water (often used in instant baby food or porridge).\n• Parboiled: Rice that has been partially boiled in its husk before milling. This process drives nutrients from the husk into the grain, making it less sticky and more nutritious than regular white rice.\n• Ordinary: Regular non-glutinous table rice (like Jasmine or Sinandomeng). It contains higher levels of amylose, which allows the grains to separate easily when cooked.","whyWrongChoices":"Alternative options: Ordinary, Parboiled, pre-gelatinized"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:kimchi is a:::fermented product', 'kimchi is a', 'Fermented product', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Kimchi is produced through controlled lactic acid fermentation. Pickling may involve acidification, but kimchi is specifically recognized as a fermented vegetable product.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fermented product\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Kimchi is produced through controlled lactic acid fermentation. Pickling may involve acidification, but kimchi is specifically recognized as a fermented vegetable product.\n\nFermentation gives its characteristic flavor.","whyWrongChoices":"Alternative options: Pickled product, Cured product, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in curing, the desirable pink color is due to::::nitrosomyoglobin', 'in curing, the desirable pink color is due to:', 'nitrosomyoglobin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The desirable cured-meat pink color is associated with nitrosomyoglobin, formed when nitric oxide reacts with myoglobin during curing and heating.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nitrosomyoglobin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The desirable cured-meat pink color is associated with nitrosomyoglobin, formed when nitric oxide reacts with myoglobin during curing and heating.\n\n• Hemoglobin: The oxygen-transporting protein found in the blood. While it contains iron and binds oxygen similarly to myoglobin, most blood is removed during slaughter, meaning it plays a minor role in meat color compared to myoglobin.\n• Oxymyoglobin: The compound formed when fresh myoglobin is exposed to oxygen (like fresh beef sitting on a counter). It gives fresh, raw red meat its bright, cherry-red color, but it turns brown quickly when cooked or exposed to heat.\n• Metmyoglobin: The oxidized form of myoglobin that occurs when meat is exposed to oxygen for a prolonged period or stored improperly. It turns the iron into a ferric state (Fe³⁺), resulting in an unappealing brownish-gray color (commonly seen on the surface of old ground beef).","whyWrongChoices":"Alternative options: hemoglobin, oxymyoglobin, metmyoglobin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in curing, the desirable pink color is due to::::', 'in curing, the desirable pink color is due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The desirable cured-meat pink color is associated with nitrosomyoglobin, formed when nitric oxide reacts with myoglobin during curing and heating.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nitrosomyoglobin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The desirable cured-meat pink color is associated with nitrosomyoglobin, formed when nitric oxide reacts with myoglobin during curing and heating.\n\n• Hemoglobin: The oxygen-transporting protein found in the blood. While it contains iron and binds oxygen similarly to myoglobin, most blood is removed during slaughter, meaning it plays a minor role in meat color compared to myoglobin.\n• Oxymyoglobin: The compound formed when fresh myoglobin is exposed to oxygen (like fresh beef sitting on a counter). It gives fresh, raw red meat its bright, cherry-red color, but it turns brown quickly when cooked or exposed to heat.\n• Metmyoglobin: The oxidized form of myoglobin that occurs when meat is exposed to oxygen for a prolonged period or stored improperly. It turns the iron into a ferric state (Fe³⁺), resulting in an unappealing brownish-gray color (commonly seen on the surface of old ground beef).","whyWrongChoices":"Alternative options: hemoglobin, oxymyoglobin, metmyoglobin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:heat is transferred in lechon in spit by::::radiation', 'heat is transferred in lechon in spit by:', 'radiation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lechon cooked on a spit receives substantial heat by radiation from the fire or hot coals, while conduction and convection play secondary roles depending on the setup.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"radiation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lechon cooked on a spit receives substantial heat by radiation from the fire or hot coals, while conduction and convection play secondary roles depending on the setup.","whyWrongChoices":"Alternative options: conduction, convection, microwave"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:heat is transferred in lechon in spit by::::', 'heat is transferred in lechon in spit by:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lechon cooked on a spit receives substantial heat by radiation from the fire or hot coals, while conduction and convection play secondary roles depending on the setup.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"radiation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lechon cooked on a spit receives substantial heat by radiation from the fire or hot coals, while conduction and convection play secondary roles depending on the setup.","whyWrongChoices":"Alternative options: conduction, convection, microwave"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fat is used as edible spreads and shortening due to::::plasticity property', 'fat is used as edible spreads and shortening due to:', 'plasticity property', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Plasticity is the ability of fat to be spread or molded while remaining semi-solid, making it useful in spreads and shortening.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"plasticity property\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Plasticity is the ability of fat to be spread or molded while remaining semi-solid, making it useful in spreads and shortening.\n\n• Softening property: Softening is a physical transition state near a melting point, not the technical property that defines mechanical moldability or spreadability.\n• Viscosity property: Viscosity applies specifically to liquid fluids (their resistance to flow). Shortenings and spreads are evaluated as semi-solids or plastic solids, not free-flowing fluids.\n• Greasy property: While fats feel greasy to the touch, this is a physical texture description rather than a functional engineering property used to manufacture baking ingredients or table spreads.","whyWrongChoices":"Alternative options: softening property, viscosity property, greasy property"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fat is used as edible spreads and shortening due to::::', 'fat is used as edible spreads and shortening due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Plasticity is the ability of fat to be spread or molded while remaining semi-solid, making it useful in spreads and shortening.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"plasticity property\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Plasticity is the ability of fat to be spread or molded while remaining semi-solid, making it useful in spreads and shortening.\n\n• Softening property: Softening is a physical transition state near a melting point, not the technical property that defines mechanical moldability or spreadability.\n• Viscosity property: Viscosity applies specifically to liquid fluids (their resistance to flow). Shortenings and spreads are evaluated as semi-solids or plastic solids, not free-flowing fluids.\n• Greasy property: While fats feel greasy to the touch, this is a physical texture description rather than a functional engineering property used to manufacture baking ingredients or table spreads.","whyWrongChoices":"Alternative options: softening property, viscosity property, greasy property"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:toasted flour (as in polvoron) is sweeter because of the formation of:::dextrin', 'toasted flour (as in polvoron) is sweeter because of the formation of', 'dextrin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Heating flour causes dextrinization, producing dextrins that contribute a sweeter taste and browned flavor.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"dextrin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Heating flour causes dextrinization, producing dextrins that contribute a sweeter taste and browned flavor.","whyWrongChoices":"Alternative options: monosaccharides, HCFS, gluten"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:microorganism used to make tempeh:::rhizopus', 'microorganism used to make tempeh', 'Rhizopus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tempeh is a traditional Indonesian soy product made by a natural culturing and controlled fermentation process.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rhizopus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tempeh is a traditional Indonesian soy product made by a natural culturing and controlled fermentation process.\n\nIt specifically uses a wild mold or starter culture belonging to the genus Rhizopus—most commonly Rhizopus oligosporus or Rhizopus oryzae.\n\nAs the mold grows, its white filaments (hyphae) bind the soybeans together into a compact, solid cake that is rich in protein and fiber.\n\n• Penicillium roqueforti: A blue mold fungus used in the production of blue cheeses (like Roquefort, Gorgonzola, and Stilton) to create its distinct flavor and blue veins.\n• Aspergillus niger: A black mold fungus commonly used in food science to industrially produce citric acid and various commercial food enzymes, but not used for fermenting tempeh.","whyWrongChoices":"Alternative options: Aspergillus niger, Penicillium roqueforti, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:microorganism used to make tempeh:::', 'microorganism used to make tempeh', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tempeh is a traditional Indonesian soy product made by a natural culturing and controlled fermentation process.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rhizopus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tempeh is a traditional Indonesian soy product made by a natural culturing and controlled fermentation process.\n\nIt specifically uses a wild mold or starter culture belonging to the genus Rhizopus—most commonly Rhizopus oligosporus or Rhizopus oryzae.\n\nAs the mold grows, its white filaments (hyphae) bind the soybeans together into a compact, solid cake that is rich in protein and fiber.\n\n• Penicillium roqueforti: A blue mold fungus used in the production of blue cheeses (like Roquefort, Gorgonzola, and Stilton) to create its distinct flavor and blue veins.\n• Aspergillus niger: A black mold fungus commonly used in food science to industrially produce citric acid and various commercial food enzymes, but not used for fermenting tempeh.","whyWrongChoices":"Alternative options: Aspergillus niger, Penicillium roqueforti, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of microorganism that will grow in orange marmalade:::osmophilic', 'type of microorganism that will grow in orange marmalade', 'Osmophilic', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Orange marmalade has a high sugar content, which creates an environment with low water activity. This condition is most favorable for osmophilic microorganisms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Osmophilic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Orange marmalade has a high sugar content, which creates an environment with low water activity. This condition is most favorable for osmophilic microorganisms.\n\nOsmophilic microorganisms thrive in environments with high osmotic pressure, such as those with high concentrations of sugar. Therefore, the type of microorganism that will grow in orange marmalade is osmophilic.\n\nHalophilic organisms thrive in high salt concentrations, xerophilic organisms are adapted to survive in extremely dry environments, and thermophilic organisms flourish in high-temperature conditions.","whyWrongChoices":"Alternative options: Halophilic, Thermophilic, Xerophilic"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of microorganism that will grow in orange marmalade:::', 'type of microorganism that will grow in orange marmalade', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Orange marmalade has a high sugar content, which creates an environment with low water activity. This condition is most favorable for osmophilic microorganisms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Osmophilic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Orange marmalade has a high sugar content, which creates an environment with low water activity. This condition is most favorable for osmophilic microorganisms.\n\nOsmophilic microorganisms thrive in environments with high osmotic pressure, such as those with high concentrations of sugar. Therefore, the type of microorganism that will grow in orange marmalade is osmophilic.\n\nHalophilic organisms thrive in high salt concentrations, xerophilic organisms are adapted to survive in extremely dry environments, and thermophilic organisms flourish in high-temperature conditions.","whyWrongChoices":"Alternative options: Halophilic, Thermophilic, Xerophilic"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:unfrozen water exists in all frozen food items because::::bound water cannot be frozen', 'unfrozen water exists in all frozen food items because:', 'bound water cannot be frozen', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Some water remains unfrozen because bound water is associated with food components and has reduced mobility and a lower freezing point.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bound water cannot be frozen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Some water remains unfrozen because bound water is associated with food components and has reduced mobility and a lower freezing point.","whyWrongChoices":"Alternative options: lowwater activity, high water activity, high water content"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:unfrozen water exists in all frozen food items because::::', 'unfrozen water exists in all frozen food items because:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Some water remains unfrozen because bound water is associated with food components and has reduced mobility and a lower freezing point.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bound water cannot be frozen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Some water remains unfrozen because bound water is associated with food components and has reduced mobility and a lower freezing point.","whyWrongChoices":"Alternative options: lowwater activity, high water activity, high water content"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:principle of food preservation involved in ube jam processing is::::prevention from microbial decomposition', 'principle of food preservation involved in ube jam processing is:', 'prevention from microbial decomposition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ube jam is preserved mainly by preventing microbial decomposition through concentration of sugar and heat treatment, which lower water availability and reduce microbial survival.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"prevention from microbial decomposition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ube jam is preserved mainly by preventing microbial decomposition through concentration of sugar and heat treatment, which lower water availability and reduce microbial survival.","whyWrongChoices":"Alternative options: prevention from physical damage, prevention from self-decomposition, prevention from biochemical decomposition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:principle of food preservation involved in ube jam processing is::::', 'principle of food preservation involved in ube jam processing is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ube jam is preserved mainly by preventing microbial decomposition through concentration of sugar and heat treatment, which lower water availability and reduce microbial survival.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"prevention from microbial decomposition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ube jam is preserved mainly by preventing microbial decomposition through concentration of sugar and heat treatment, which lower water availability and reduce microbial survival.","whyWrongChoices":"Alternative options: prevention from physical damage, prevention from self-decomposition, prevention from biochemical decomposition"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:group of microorganisms that are more likely to grow on the surface of dried squid packed in polyethylene bags:::mold', 'group of microorganisms that are more likely to grow on the surface of dried squid packed in polyethylene bags', 'mold', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dried squid has significantly reduced moisture content and available water. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"mold\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dried squid has significantly reduced moisture content and available water. \n\nMost bacteria require a high water activity (typically above 0.91) to grow. \n\nYeasts generally need an Aw 0.80 or above. \n\nConversely, xerophilic (dry-loving) molds can actively grow in environments with a water activity as low as 0.60 to 0.70.","whyWrongChoices":"Alternative options: Bacteria, yeasts, Algae"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:group of microorganisms that are more likely to grow on the surface of dried squid packed in polyethylene bags:::', 'group of microorganisms that are more likely to grow on the surface of dried squid packed in polyethylene bags', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dried squid has significantly reduced moisture content and available water. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"mold\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dried squid has significantly reduced moisture content and available water. \n\nMost bacteria require a high water activity (typically above 0.91) to grow. \n\nYeasts generally need an Aw 0.80 or above. \n\nConversely, xerophilic (dry-loving) molds can actively grow in environments with a water activity as low as 0.60 to 0.70.","whyWrongChoices":"Alternative options: Bacteria, yeasts, Algae"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which heats faster when microwaved:::water', 'which heats faster when microwaved', 'water', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Water heats efficiently in a microwave because its polar molecules interact strongly with microwave energy. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"water\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Water heats efficiently in a microwave because its polar molecules interact strongly with microwave energy. \n\nWater molecules have a positive end and a negative end, making them act like tiny magnets (dipoles). The microwave generates an electric field that changes direction billions of times every second.\n\nWater molecules twist and flip back and forth to line up with this shifting field. This rapid movement causes the molecules to bump into each other, creating heat through friction. \n\nGlass and many dry solids absorb less, while butter behaves differently because of its composition.","whyWrongChoices":"Alternative options: glass, solids, butter"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which heats faster when microwaved:::', 'which heats faster when microwaved', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Water heats efficiently in a microwave because its polar molecules interact strongly with microwave energy. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"water\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Water heats efficiently in a microwave because its polar molecules interact strongly with microwave energy. \n\nWater molecules have a positive end and a negative end, making them act like tiny magnets (dipoles). The microwave generates an electric field that changes direction billions of times every second.\n\nWater molecules twist and flip back and forth to line up with this shifting field. This rapid movement causes the molecules to bump into each other, creating heat through friction. \n\nGlass and many dry solids absorb less, while butter behaves differently because of its composition.","whyWrongChoices":"Alternative options: glass, solids, butter"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:process of ensuring that a number of factors are in place and will prevent growth of microorganisms:::hurdle concept', 'process of ensuring that a number of factors are in place and will prevent growth of microorganisms', 'Hurdle concept', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The hurdle concept combines several preservation factors so that microorganisms cannot grow even when any single factor alone may be insufficient.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hurdle concept\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The hurdle concept combines several preservation factors so that microorganisms cannot grow even when any single factor alone may be insufficient.\n\nIt uses two or more intelligent preservation factors called \"hurdles\" so microorganisms cannot survive or multiply. Each hurdle disturbs the internal balance, or homeostasis, of the microbial cells.\n\nMild individual treatments work together to achieve a powerful result without damaging the food''s taste or nutrition.","whyWrongChoices":"Alternative options: Modified atmosphere packaging, Vacuumpack, Radura"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:process of ensuring that a number of factors are in place and will prevent growth of microorganisms:::', 'process of ensuring that a number of factors are in place and will prevent growth of microorganisms', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The hurdle concept combines several preservation factors so that microorganisms cannot grow even when any single factor alone may be insufficient.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hurdle concept\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The hurdle concept combines several preservation factors so that microorganisms cannot grow even when any single factor alone may be insufficient.\n\nIt uses two or more intelligent preservation factors called \"hurdles\" so microorganisms cannot survive or multiply. Each hurdle disturbs the internal balance, or homeostasis, of the microbial cells.\n\nMild individual treatments work together to achieve a powerful result without damaging the food''s taste or nutrition.","whyWrongChoices":"Alternative options: Modified atmosphere packaging, Vacuumpack, Radura"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are spices except::::', 'the following are spices except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chives are classified as a culinary herb. They are the green, aromatic leaves of the plant (Allium schoenoprasum), used fresh or dried to add a mild onion-like flavor to dishes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chives\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chives are classified as a culinary herb. They are the green, aromatic leaves of the plant (Allium schoenoprasum), used fresh or dried to add a mild onion-like flavor to dishes.\n\nCardamom, nutmeg, and sage are classified in culinary contexts as spices or flavoring botanicals according to the plant part and use.","whyWrongChoices":"Alternative options: Cardamom, Nutmeg, Sage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:international symbol indicating food is irradiated:::radura', 'international symbol indicating food is irradiated', 'Radura', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Radura is the international symbol used to indicate that a food product has been treated with ionizing radiation (irradiated). It features a distinctive green icon of a stylized plant inside a broken circle, which symbolizes a safe protective shield.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Radura\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Radura is the international symbol used to indicate that a food product has been treated with ionizing radiation (irradiated). It features a distinctive green icon of a stylized plant inside a broken circle, which symbolizes a safe protective shield.\n\n• Hurdle concept: A highly influential food preservation strategy that applies a combination of multiple sub-lethal preservative factors or barriers (like adjusting temperature, pH, water activity, and competitive flora simultaneously) to completely inhibit microbial growth instead of relying on a single intense sterilization method.\n• Vacuum pack: A packaging method where air is entirely drawn out and evacuated from a non-permeable pouch before sealing. This creates an anaerobic interior that prevents the growth of standard spoilage-causing aerobic bacteria and molds.\n• Modified atmosphere packaging (MAP): A food preservation technique that replaces the ambient air inside a package with a precise, pre-calculated gas blend (usually varying combinations of nitrogen, carbon dioxide, and oxygen) to drastically slow down chemical respiration and extend the product''s natural shelf-life.","whyWrongChoices":"Alternative options: Hurdle concept, Modified atmosphere packaging, Vacuum pack"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:international symbol indicating food is irradiated:::', 'international symbol indicating food is irradiated', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Radura is the international symbol used to indicate that a food product has been treated with ionizing radiation (irradiated). It features a distinctive green icon of a stylized plant inside a broken circle, which symbolizes a safe protective shield.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Radura\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Radura is the international symbol used to indicate that a food product has been treated with ionizing radiation (irradiated). It features a distinctive green icon of a stylized plant inside a broken circle, which symbolizes a safe protective shield.\n\n• Hurdle concept: A highly influential food preservation strategy that applies a combination of multiple sub-lethal preservative factors or barriers (like adjusting temperature, pH, water activity, and competitive flora simultaneously) to completely inhibit microbial growth instead of relying on a single intense sterilization method.\n• Vacuum pack: A packaging method where air is entirely drawn out and evacuated from a non-permeable pouch before sealing. This creates an anaerobic interior that prevents the growth of standard spoilage-causing aerobic bacteria and molds.\n• Modified atmosphere packaging (MAP): A food preservation technique that replaces the ambient air inside a package with a precise, pre-calculated gas blend (usually varying combinations of nitrogen, carbon dioxide, and oxygen) to drastically slow down chemical respiration and extend the product''s natural shelf-life.","whyWrongChoices":"Alternative options: Hurdle concept, Modified atmosphere packaging, Vacuum pack"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:code on sanitation of the philippines:::pd 856', 'code on sanitation of the philippines', 'PD 856', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Presidential Decree No. 856, issued in 1975, is officially known as the Code on Sanitation of the Philippines. It sets the health and sanitation standards for food establishments, water supply, industrial hygiene, and public places in the country.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PD 856\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Presidential Decree No. 856, issued in 1975, is officially known as the Code on Sanitation of the Philippines. It sets the health and sanitation standards for food establishments, water supply, industrial hygiene, and public places in the country.\n\n• RA 7394: The Consumer Act of the Philippines\n• PD 704: The Fisheries Decree of 1975\n• RA 3720: The Food, Drug, and Cosmetic Act","whyWrongChoices":"Alternative options: RA 7394, PD 704, RA 3720"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:code on sanitation of the philippines:::', 'code on sanitation of the philippines', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Presidential Decree No. 856, issued in 1975, is officially known as the Code on Sanitation of the Philippines. It sets the health and sanitation standards for food establishments, water supply, industrial hygiene, and public places in the country.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PD 856\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Presidential Decree No. 856, issued in 1975, is officially known as the Code on Sanitation of the Philippines. It sets the health and sanitation standards for food establishments, water supply, industrial hygiene, and public places in the country.\n\n• RA 7394: The Consumer Act of the Philippines\n• PD 704: The Fisheries Decree of 1975\n• RA 3720: The Food, Drug, and Cosmetic Act","whyWrongChoices":"Alternative options: RA 7394, PD 704, RA 3720"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:appropriate packaging material for liquid items which require high temperature processing:::tetra pak', 'appropriate packaging material for liquid items which require high temperature processing', 'Tetra Pak', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tetrapack (Tetra Pak): This multi-layered carton packaging is specifically engineered for liquid items (such as milk, juices, and soups) that undergo aseptic or high-temperature processing (such as Ultra-High Temperature or UHT pasteurization and retort sterilization).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tetra Pak\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tetrapack (Tetra Pak): This multi-layered carton packaging is specifically engineered for liquid items (such as milk, juices, and soups) that undergo aseptic or high-temperature processing (such as Ultra-High Temperature or UHT pasteurization and retort sterilization).\n\nIt provides a sterile environment, strong barrier protection against light and oxygen, and structural integrity under heat. \n\n• Saran: A plastic wrap (polyvinylidene chloride) mostly used for moisture/odor barriers or food covering, but not suitable for structural liquid packaging during high-temperature processing.\n• Glassine: A smooth, translucent paper that is grease-resistant. It is used for dry goods, interleaving, or bakery items but cannot hold liquids or withstand extreme liquid processing temperatures. \n• Plioform (or Pliofilm): A rubber hydrochloride plastic film primarily used for wrapping moisture-sensitive items like meats, but not built for high-temperature liquid sterilization.","whyWrongChoices":"Alternative options: Saran, Plioform, Glassine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:appropriate packaging material for liquid items which require high temperature processing:::', 'appropriate packaging material for liquid items which require high temperature processing', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tetrapack (Tetra Pak): This multi-layered carton packaging is specifically engineered for liquid items (such as milk, juices, and soups) that undergo aseptic or high-temperature processing (such as Ultra-High Temperature or UHT pasteurization and retort sterilization).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tetra Pak\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tetrapack (Tetra Pak): This multi-layered carton packaging is specifically engineered for liquid items (such as milk, juices, and soups) that undergo aseptic or high-temperature processing (such as Ultra-High Temperature or UHT pasteurization and retort sterilization).\n\nIt provides a sterile environment, strong barrier protection against light and oxygen, and structural integrity under heat. \n\n• Saran: A plastic wrap (polyvinylidene chloride) mostly used for moisture/odor barriers or food covering, but not suitable for structural liquid packaging during high-temperature processing.\n• Glassine: A smooth, translucent paper that is grease-resistant. It is used for dry goods, interleaving, or bakery items but cannot hold liquids or withstand extreme liquid processing temperatures. \n• Plioform (or Pliofilm): A rubber hydrochloride plastic film primarily used for wrapping moisture-sensitive items like meats, but not built for high-temperature liquid sterilization.","whyWrongChoices":"Alternative options: Saran, Plioform, Glassine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following microorganisms produce heat stable enterotoxin:::staphylococcus aureus', 'which of the following microorganisms produce heat stable enterotoxin', 'Staphylococcus aureus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Staphylococcus aureus produces enterotoxins that resist high heat and can cause food poisoning even after the food is cooked.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Staphylococcus aureus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Staphylococcus aureus produces enterotoxins that resist high heat and can cause food poisoning even after the food is cooked.\n\n• Aspergillus flavus produces aflatoxins (mycotoxins), not enterotoxins.\n• Clostridium perfringens produces an enterotoxin in the gut during sporulation, but it is not typically classified as a pre-formed heat-stable food toxin in the same manner.\n• Clostridium botulinum produces a neurotoxin that is heat-labile (destroyed by boiling).","whyWrongChoices":"Alternative options: Clostridium perfringens, Clostridium botulinum, Aspergillus flavus"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following microorganisms produce heat stable enterotoxin:::', 'which of the following microorganisms produce heat stable enterotoxin', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Staphylococcus aureus produces enterotoxins that resist high heat and can cause food poisoning even after the food is cooked.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Staphylococcus aureus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Staphylococcus aureus produces enterotoxins that resist high heat and can cause food poisoning even after the food is cooked.\n\n• Aspergillus flavus produces aflatoxins (mycotoxins), not enterotoxins.\n• Clostridium perfringens produces an enterotoxin in the gut during sporulation, but it is not typically classified as a pre-formed heat-stable food toxin in the same manner.\n• Clostridium botulinum produces a neurotoxin that is heat-labile (destroyed by boiling).","whyWrongChoices":"Alternative options: Clostridium perfringens, Clostridium botulinum, Aspergillus flavus"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the cooling process behind storing food in earthen wares or clay pots.:::evaporative cooling', 'the cooling process behind storing food in earthen wares or clay pots.', 'evaporative cooling', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Clay pots (traditionally known as palayok or banga in the Philippines) are made from porous earthenware clay.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"evaporative cooling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Clay pots (traditionally known as palayok or banga in the Philippines) are made from porous earthenware clay.\n\nWhen water or moist food is placed inside the pot, a small amount of moisture seeps through the tiny microscopic pores of the clay to the outer surface of the vessel.\n\nAs warm air passes over the outside of the pot, it causes this surface moisture to evaporate. In physics, evaporation requires heat energy. The water molecules absorb heat from the clay pot and the food inside it to transform into vapor, leaving the remaining contents significantly cooler than the surrounding ambient temperature.","whyWrongChoices":"Alternative options: chilling, refrigeration, slow cooling"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the cooling process behind storing food in earthen wares or clay pots.:::', 'the cooling process behind storing food in earthen wares or clay pots.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Clay pots (traditionally known as palayok or banga in the Philippines) are made from porous earthenware clay.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"evaporative cooling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Clay pots (traditionally known as palayok or banga in the Philippines) are made from porous earthenware clay.\n\nWhen water or moist food is placed inside the pot, a small amount of moisture seeps through the tiny microscopic pores of the clay to the outer surface of the vessel.\n\nAs warm air passes over the outside of the pot, it causes this surface moisture to evaporate. In physics, evaporation requires heat energy. The water molecules absorb heat from the clay pot and the food inside it to transform into vapor, leaving the remaining contents significantly cooler than the surrounding ambient temperature.","whyWrongChoices":"Alternative options: chilling, refrigeration, slow cooling"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:syrup used for freezing delicate flavored fruits.:::thin', 'syrup used for freezing delicate flavored fruits.', 'Thin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In food preservation and freezing science, a thin syrup (low sugar-to-water concentration, usually around 20% to 30% sugar) is intentionally used for mild or delicate-flavored fruits like melons, grapefruits, and pineapples.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Thin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In food preservation and freezing science, a thin syrup (low sugar-to-water concentration, usually around 20% to 30% sugar) is intentionally used for mild or delicate-flavored fruits like melons, grapefruits, and pineapples.\n\nA higher sugar concentration (like heavy or very heavy syrup) would completely overpower and mask the natural, subtle flavors of these fruits. A thin pack provides just enough sugar density to protect the cell structure, retain the fruit''s shape, and block oxygen from causing discoloration, all without ruining its delicate taste.\n\n• Heavy: Contains a much higher sugar-to-water concentration (around 40% to 50% sugar). It is reserved for strong-flavored, highly acidic, or very sour fruits (like sour cherries or plums) that can stand up to heavy sweetness.\n• Moderate (Medium): A standard mid-range syrup option (around 30% to 40% sugar) used for everyday fruits with balanced flavors like peaches, pears, and apples.\n• Dry: Refers to the \"dry sugar pack\" method where dry granulated sugar is sprinkled directly onto juicy fruits (like strawberries) to draw out their natural juices to form their own syrup. This is not a liquid syrup classification used for delicate whole or sliced fruits.","whyWrongChoices":"Alternative options: Heavy, Moderate, Dry"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:syrup used for freezing delicate flavored fruits.:::', 'syrup used for freezing delicate flavored fruits.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In food preservation and freezing science, a thin syrup (low sugar-to-water concentration, usually around 20% to 30% sugar) is intentionally used for mild or delicate-flavored fruits like melons, grapefruits, and pineapples.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Thin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In food preservation and freezing science, a thin syrup (low sugar-to-water concentration, usually around 20% to 30% sugar) is intentionally used for mild or delicate-flavored fruits like melons, grapefruits, and pineapples.\n\nA higher sugar concentration (like heavy or very heavy syrup) would completely overpower and mask the natural, subtle flavors of these fruits. A thin pack provides just enough sugar density to protect the cell structure, retain the fruit''s shape, and block oxygen from causing discoloration, all without ruining its delicate taste.\n\n• Heavy: Contains a much higher sugar-to-water concentration (around 40% to 50% sugar). It is reserved for strong-flavored, highly acidic, or very sour fruits (like sour cherries or plums) that can stand up to heavy sweetness.\n• Moderate (Medium): A standard mid-range syrup option (around 30% to 40% sugar) used for everyday fruits with balanced flavors like peaches, pears, and apples.\n• Dry: Refers to the \"dry sugar pack\" method where dry granulated sugar is sprinkled directly onto juicy fruits (like strawberries) to draw out their natural juices to form their own syrup. This is not a liquid syrup classification used for delicate whole or sliced fruits.","whyWrongChoices":"Alternative options: Heavy, Moderate, Dry"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factor affecting the size of ice crystals in food:::rate of freezing', 'factor affecting the size of ice crystals in food', 'rate of freezing', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The rate of freezing strongly affects ice-crystal size: rapid freezing forms many small crystals, while slow freezing allows larger crystals to develop.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"rate of freezing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The rate of freezing strongly affects ice-crystal size: rapid freezing forms many small crystals, while slow freezing allows larger crystals to develop.","whyWrongChoices":"Alternative options: quantity of bound water, type of food, presence of enzymes in food"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factor affecting the size of ice crystals in food:::', 'factor affecting the size of ice crystals in food', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The rate of freezing strongly affects ice-crystal size: rapid freezing forms many small crystals, while slow freezing allows larger crystals to develop.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"rate of freezing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The rate of freezing strongly affects ice-crystal size: rapid freezing forms many small crystals, while slow freezing allows larger crystals to develop.","whyWrongChoices":"Alternative options: quantity of bound water, type of food, presence of enzymes in food"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the canning process at high altitude must be::::lengthened because boiling point gets lower', 'the canning process at high altitude must be:', 'lengthened because boiling point gets lower', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At higher altitudes, atmospheric pressure is lower and water boils at a lower temperature, so thermal processing time must be lengthened to achieve the required lethality.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"lengthened because boiling point gets lower\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At higher altitudes, atmospheric pressure is lower and water boils at a lower temperature, so thermal processing time must be lengthened to achieve the required lethality.","whyWrongChoices":"Alternative options: lengthened because relative humidity gets lower, shortened because boiling point gets higher, shortened because relative humidity gets higher"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the canning process at high altitude must be::::', 'the canning process at high altitude must be:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At higher altitudes, atmospheric pressure is lower and water boils at a lower temperature, so thermal processing time must be lengthened to achieve the required lethality.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"lengthened because boiling point gets lower\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At higher altitudes, atmospheric pressure is lower and water boils at a lower temperature, so thermal processing time must be lengthened to achieve the required lethality.","whyWrongChoices":"Alternative options: lengthened because relative humidity gets lower, shortened because boiling point gets higher, shortened because relative humidity gets higher"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the desired salt concentration of the medium in the production of burong mangga is::::5 to 15%', 'the desired salt concentration of the medium in the production of burong mangga is:', '5 to 15%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Burong mangga is prepared using a salt concentration within the keyed 5–15% range to support the desired preservation and fermentation conditions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5 to 15%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Burong mangga is prepared using a salt concentration within the keyed 5–15% range to support the desired preservation and fermentation conditions.\n\nIn the lactic acid fermentation process of making burong mangga (fermented green mangoes), salt serves to draw out moisture and nutrients via osmosis. This creates a favorable environment for beneficial lactic acid bacteria while suppressing the growth of spoilage-causing organisms.\n\nA brine concentration within 5% to 15% (most typically maintained around 5% to 10% or a 40° salometer reading during active fermentation) ensures proper preservation and texture without completely arresting microbial activity. \n\nWhen concentration below 5%, proteolytic or spoilage bacteria may cause the mangoes to become mushy and foul-smelling. \n\nWhen concentration is higher than 15% to 20% without gradual adjustments, and the fermentation slows down dramatically or stops entirely.","whyWrongChoices":"Alternative options: 4 to 15%, 15 to 20%, 0 to 5%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
