INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the desired salt concentration of the medium in the production of burong mangga is::::', 'the desired salt concentration of the medium in the production of burong mangga is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Burong mangga is prepared using a salt concentration within the keyed 5–15% range to support the desired preservation and fermentation conditions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5 to 15%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Burong mangga is prepared using a salt concentration within the keyed 5–15% range to support the desired preservation and fermentation conditions.\n\nIn the lactic acid fermentation process of making burong mangga (fermented green mangoes), salt serves to draw out moisture and nutrients via osmosis. This creates a favorable environment for beneficial lactic acid bacteria while suppressing the growth of spoilage-causing organisms.\n\nA brine concentration within 5% to 15% (most typically maintained around 5% to 10% or a 40° salometer reading during active fermentation) ensures proper preservation and texture without completely arresting microbial activity. \n\nWhen concentration below 5%, proteolytic or spoilage bacteria may cause the mangoes to become mushy and foul-smelling. \n\nWhen concentration is higher than 15% to 20% without gradual adjustments, and the fermentation slows down dramatically or stops entirely.","whyWrongChoices":"Alternative options: 4 to 15%, 15 to 20%, 0 to 5%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deterioration of canned items due to undercooling that results to growth of thermophilic microorganisms:::flat sours', 'deterioration of canned items due to undercooling that results to growth of thermophilic microorganisms', 'Flat sours', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Flat sour spoilage occurs when thermophilic microorganisms grow and produce acid without gas, often associated with inadequate cooling or storage conditions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flat sours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Flat sour spoilage occurs when thermophilic microorganisms grow and produce acid without gas, often associated with inadequate cooling or storage conditions.\n\n• Springer: A can where one flat end bulges outward, but if you press it down with your finger, the opposite end pops out instead.\n• Hydrogen swell: A chemical defect caused by internal corrosion where the acid in the food reacts with the tinplate lining of the can, generating hydrogen gas that physically swells the can.\n• Flipper: A can that appears completely normal and flat on both ends, but when struck or brought down hard against a flat table surface, one end flips or bulges outward due to internal vacuum loss.","whyWrongChoices":"Alternative options: Flipper, Hydrogen swell, Springer"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deterioration of canned items due to undercooling that results to growth of thermophilic microorganisms:::', 'deterioration of canned items due to undercooling that results to growth of thermophilic microorganisms', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Flat sour spoilage occurs when thermophilic microorganisms grow and produce acid without gas, often associated with inadequate cooling or storage conditions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Flat sours\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Flat sour spoilage occurs when thermophilic microorganisms grow and produce acid without gas, often associated with inadequate cooling or storage conditions.\n\n• Springer: A can where one flat end bulges outward, but if you press it down with your finger, the opposite end pops out instead.\n• Hydrogen swell: A chemical defect caused by internal corrosion where the acid in the food reacts with the tinplate lining of the can, generating hydrogen gas that physically swells the can.\n• Flipper: A can that appears completely normal and flat on both ends, but when struck or brought down hard against a flat table surface, one end flips or bulges outward due to internal vacuum loss.","whyWrongChoices":"Alternative options: Flipper, Hydrogen swell, Springer"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:basis for recruiting personnel:::job description', 'basis for recruiting personnel', 'Job description', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Job description – an organized list of duties, skills and responsibilities required in a specific position. This should be written for every position and should be reviewed and updated periodically.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Job description\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Job description – an organized list of duties, skills and responsibilities required in a specific position. This should be written for every position and should be reviewed and updated periodically.","whyWrongChoices":"Alternative options: Performance rating scale, Procedure manual, Organizational chart"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food additive used to prevent both enzymatic and non-enzymatic discoloration:::sulfur dioxide', 'food additive used to prevent both enzymatic and non-enzymatic discoloration', 'Sulfur dioxide', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sulfur Dioxide inhibits the action of polyphenol oxidase (PPO), the enzyme responsible for turning cut or bruised fruits and vegetables brown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sulfur dioxide\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sulfur Dioxide inhibits the action of polyphenol oxidase (PPO), the enzyme responsible for turning cut or bruised fruits and vegetables brown.\n\nIt reacts also with carbonyl intermediates in the Maillard reaction, stopping the chemical processes that cause heat- or storage-induced discoloration in processed foods. \n\n• Sodium Nitrites / Potassium Nitrates: These are primarily used as curing agents and antimicrobials in processed meat products (like bacon and hot dogs) to lock in a stable pink color and prevent bacterial growth. They do not address general enzymatic or non-enzymatic plant discoloration. \n• Benzoic Acid: This is used as an antimicrobial preservative to inhibit the growth of mold, yeast, and bacteria in highly acidic environments like juices and carbonated drinks.","whyWrongChoices":"Alternative options: Sodiumnitrites, Potassium nitrates, Benzoic acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food additive used to prevent both enzymatic and non-enzymatic discoloration:::', 'food additive used to prevent both enzymatic and non-enzymatic discoloration', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sulfur Dioxide inhibits the action of polyphenol oxidase (PPO), the enzyme responsible for turning cut or bruised fruits and vegetables brown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sulfur dioxide\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sulfur Dioxide inhibits the action of polyphenol oxidase (PPO), the enzyme responsible for turning cut or bruised fruits and vegetables brown.\n\nIt reacts also with carbonyl intermediates in the Maillard reaction, stopping the chemical processes that cause heat- or storage-induced discoloration in processed foods. \n\n• Sodium Nitrites / Potassium Nitrates: These are primarily used as curing agents and antimicrobials in processed meat products (like bacon and hot dogs) to lock in a stable pink color and prevent bacterial growth. They do not address general enzymatic or non-enzymatic plant discoloration. \n• Benzoic Acid: This is used as an antimicrobial preservative to inhibit the growth of mold, yeast, and bacteria in highly acidic environments like juices and carbonated drinks.","whyWrongChoices":"Alternative options: Sodiumnitrites, Potassium nitrates, Benzoic acids"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar concentrate made from crushed fruit pulp used to flavor the popular suman from leyte with chocolate is:::jam', 'sugar concentrate made from crushed fruit pulp used to flavor the popular suman from leyte with chocolate is', 'Jam', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Jam is a concentrated fruit product made from crushed or pulped fruit and sugar, making it suitable as a flavoring concentrate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Jam is a concentrated fruit product made from crushed or pulped fruit and sugar, making it suitable as a flavoring concentrate.\n\nJelly is made from clear fruit juice strained out after boiling, containing no pulp pieces.\n\nPreserves contain whole fruits or large, uniform pieces of fruit cooked in a thick syrup\n\nFood gels are semi-solid, viscoelastic structures made by trapping liquids within a network of proteins, starches, or gums.","whyWrongChoices":"Alternative options: Jelly, Gel, Preserve"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sugar concentrate made from crushed fruit pulp used to flavor the popular suman from leyte with chocolate is:::', 'sugar concentrate made from crushed fruit pulp used to flavor the popular suman from leyte with chocolate is', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Jam is a concentrated fruit product made from crushed or pulped fruit and sugar, making it suitable as a flavoring concentrate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Jam\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Jam is a concentrated fruit product made from crushed or pulped fruit and sugar, making it suitable as a flavoring concentrate.\n\nJelly is made from clear fruit juice strained out after boiling, containing no pulp pieces.\n\nPreserves contain whole fruits or large, uniform pieces of fruit cooked in a thick syrup\n\nFood gels are semi-solid, viscoelastic structures made by trapping liquids within a network of proteins, starches, or gums.","whyWrongChoices":"Alternative options: Jelly, Gel, Preserve"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:northern philippines’ version of sisig:::dinakdakan', 'northern philippines’ version of sisig', 'Dinakdakan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dinakdakan is an authentic delicacy from the Ilocos region in the Northern Philippines. Much like Kapampangan sisig, it is made by boiling and then charcoal-grilling various pig parts (such as the ears, face/jowl, and tongue).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dinakdakan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dinakdakan is an authentic delicacy from the Ilocos region in the Northern Philippines. Much like Kapampangan sisig, it is made by boiling and then charcoal-grilling various pig parts (such as the ears, face/jowl, and tongue).\n\nThe primary structural differences are that dinakdakan is typically sliced into thin strips rather than being finely minced, and it traditionally uses boiled pig''s brain mashed into a vinegar-calamansi dressing to achieve its signature rich, creamy texture (whereas modern commercial sisig often replaces this with mayonnaise or egg).\n\n• Baguisen: A traditional Ilocano organ meat stew cooked with pig or goat intestines, liver, and heart thickened with pork blood and soured with vinegar or kamias. It is closer in profile to dinuguan.\n• Lininta: A traditional Muslim-Filipino (Maranao) dish consisting of fresh fish marinated with palapa, wrapped tightly in banana leaves, and gently steamed.\n• Dinardaraan: The strict Ilocano version of dinuguan (pork blood stew). Unlike the Tagalog version which has plenty of thick gravy, dinardaraan is famously cooked until the sauce completely reduces, leaving a much drier, oilier coat on the meat.","whyWrongChoices":"Alternative options: Lininta, Baguisen, Dinardaraan"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:northern philippines’ version of sisig:::', 'northern philippines’ version of sisig', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dinakdakan is an authentic delicacy from the Ilocos region in the Northern Philippines. Much like Kapampangan sisig, it is made by boiling and then charcoal-grilling various pig parts (such as the ears, face/jowl, and tongue).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dinakdakan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dinakdakan is an authentic delicacy from the Ilocos region in the Northern Philippines. Much like Kapampangan sisig, it is made by boiling and then charcoal-grilling various pig parts (such as the ears, face/jowl, and tongue).\n\nThe primary structural differences are that dinakdakan is typically sliced into thin strips rather than being finely minced, and it traditionally uses boiled pig''s brain mashed into a vinegar-calamansi dressing to achieve its signature rich, creamy texture (whereas modern commercial sisig often replaces this with mayonnaise or egg).\n\n• Baguisen: A traditional Ilocano organ meat stew cooked with pig or goat intestines, liver, and heart thickened with pork blood and soured with vinegar or kamias. It is closer in profile to dinuguan.\n• Lininta: A traditional Muslim-Filipino (Maranao) dish consisting of fresh fish marinated with palapa, wrapped tightly in banana leaves, and gently steamed.\n• Dinardaraan: The strict Ilocano version of dinuguan (pork blood stew). Unlike the Tagalog version which has plenty of thick gravy, dinardaraan is famously cooked until the sauce completely reduces, leaving a much drier, oilier coat on the meat.","whyWrongChoices":"Alternative options: Lininta, Baguisen, Dinardaraan"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a popular suman from leyte flavored with chocolate:::moron', 'it is a popular suman from leyte flavored with chocolate', 'Moron', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Moron is a native kakanin (sticky rice cake) originating from the Eastern Visayas region, particularly popular in Leyte (like Tacloban and Abuyog) and Eastern Samar. It is a type of suman made by twisting a milky vanilla-flavored white dough and a chocolate dough together. The chocolate flavor comes from cocoa or local tablea (cacao tablets).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Moron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Moron is a native kakanin (sticky rice cake) originating from the Eastern Visayas region, particularly popular in Leyte (like Tacloban and Abuyog) and Eastern Samar. It is a type of suman made by twisting a milky vanilla-flavored white dough and a chocolate dough together. The chocolate flavor comes from cocoa or local tablea (cacao tablets).\n\nIt features a distinct marble swirl, a very smooth texture, and is often embedded with roasted peanuts before being wrapped in banana leaves and steamed. It is traditionally eaten as a snack (merienda) alongside hot coffee or sikwate (native hot chocolate).\n\n• Binakol: A savory Filipino chicken soup traditionally cooked inside a bamboo tube or coconut shell using coconut water.\n• Binagol: Another famous sweet delicacy from Leyte (specifically Dagami), but it is made from mashed talyan (taro root crop), condensed milk, and coconut milk, then steamed inside a coconut shell (bagol).\n• Baye-baye: A popular Western Visayas (Iloilo/Negros) delicacy made from toasted ground rice or corn mixed with coconut water and sugar.","whyWrongChoices":"Alternative options: Binagol, Binakol, Baye-baye"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a popular suman from leyte flavored with chocolate:::', 'it is a popular suman from leyte flavored with chocolate', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Moron is a native kakanin (sticky rice cake) originating from the Eastern Visayas region, particularly popular in Leyte (like Tacloban and Abuyog) and Eastern Samar. It is a type of suman made by twisting a milky vanilla-flavored white dough and a chocolate dough together. The chocolate flavor comes from cocoa or local tablea (cacao tablets).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Moron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Moron is a native kakanin (sticky rice cake) originating from the Eastern Visayas region, particularly popular in Leyte (like Tacloban and Abuyog) and Eastern Samar. It is a type of suman made by twisting a milky vanilla-flavored white dough and a chocolate dough together. The chocolate flavor comes from cocoa or local tablea (cacao tablets).\n\nIt features a distinct marble swirl, a very smooth texture, and is often embedded with roasted peanuts before being wrapped in banana leaves and steamed. It is traditionally eaten as a snack (merienda) alongside hot coffee or sikwate (native hot chocolate).\n\n• Binakol: A savory Filipino chicken soup traditionally cooked inside a bamboo tube or coconut shell using coconut water.\n• Binagol: Another famous sweet delicacy from Leyte (specifically Dagami), but it is made from mashed talyan (taro root crop), condensed milk, and coconut milk, then steamed inside a coconut shell (bagol).\n• Baye-baye: A popular Western Visayas (Iloilo/Negros) delicacy made from toasted ground rice or corn mixed with coconut water and sugar.","whyWrongChoices":"Alternative options: Binagol, Binakol, Baye-baye"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following statements are true in judaism, except::::all grape varieties are restricted', 'the following statements are true in judaism, except:', 'all grape varieties are restricted', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Jewish dietary laws prohibit mixing meat and dairy, prohibit consumption of blood, and forbid shellfish. However, it is not correct that all grape varieties are restricted.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all grape varieties are restricted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Jewish dietary laws prohibit mixing meat and dairy, prohibit consumption of blood, and forbid shellfish. However, it is not correct that all grape varieties are restricted.","whyWrongChoices":"Alternative options: meat cannot be eaten with dairy, the Torah prohibits consumption of blood, all types of shellfish are forbidden"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following statements are true in judaism, except::::', 'the following statements are true in judaism, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Jewish dietary laws prohibit mixing meat and dairy, prohibit consumption of blood, and forbid shellfish. However, it is not correct that all grape varieties are restricted.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"all grape varieties are restricted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Jewish dietary laws prohibit mixing meat and dairy, prohibit consumption of blood, and forbid shellfish. However, it is not correct that all grape varieties are restricted.","whyWrongChoices":"Alternative options: meat cannot be eaten with dairy, the Torah prohibits consumption of blood, all types of shellfish are forbidden"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are spices except::::chives', 'the following are spices except:', 'Chives', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chives are classified as a culinary herb. They are the green, aromatic leaves of the plant (Allium schoenoprasum), used fresh or dried to add a mild onion-like flavor to dishes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chives\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chives are classified as a culinary herb. They are the green, aromatic leaves of the plant (Allium schoenoprasum), used fresh or dried to add a mild onion-like flavor to dishes.\n\nCardamom, nutmeg, and sage are classified in culinary contexts as spices or flavoring botanicals according to the plant part and use.","whyWrongChoices":"Alternative options: Cardamom, Nutmeg, Sage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following statements help conserve nutrients in preparation and cooking, except::::thaw frozen vegetables before cooking', 'the following statements help conserve nutrients in preparation and cooking, except:', 'thaw frozen vegetables before cooking', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"You should never thaw frozen vegetables before cooking them. Thawing frozen vegetables allows their cell walls to collapse as they soften, causing water-soluble vitamins (such as Vitamin C and B-complex vitamins) to leach out into the liquid runoff, which is then discarded. To conserve the highest amount of nutrients, frozen vegetables should be cooked straight from the frozen state by steaming or dropping them directly into boiling water.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thaw frozen vegetables before cooking\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"You should never thaw frozen vegetables before cooking them. Thawing frozen vegetables allows their cell walls to collapse as they soften, causing water-soluble vitamins (such as Vitamin C and B-complex vitamins) to leach out into the liquid runoff, which is then discarded. To conserve the highest amount of nutrients, frozen vegetables should be cooked straight from the frozen state by steaming or dropping them directly into boiling water.\n\nThe other practices help conserve nutrients by minimizing leaching and excessive cooking.","whyWrongChoices":"Alternative options: foods should not be stirred, baking soda should not be added, pots should be kept covered"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following statements help conserve nutrients in preparation and cooking, except::::', 'the following statements help conserve nutrients in preparation and cooking, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"You should never thaw frozen vegetables before cooking them. Thawing frozen vegetables allows their cell walls to collapse as they soften, causing water-soluble vitamins (such as Vitamin C and B-complex vitamins) to leach out into the liquid runoff, which is then discarded. To conserve the highest amount of nutrients, frozen vegetables should be cooked straight from the frozen state by steaming or dropping them directly into boiling water.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"thaw frozen vegetables before cooking\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"You should never thaw frozen vegetables before cooking them. Thawing frozen vegetables allows their cell walls to collapse as they soften, causing water-soluble vitamins (such as Vitamin C and B-complex vitamins) to leach out into the liquid runoff, which is then discarded. To conserve the highest amount of nutrients, frozen vegetables should be cooked straight from the frozen state by steaming or dropping them directly into boiling water.\n\nThe other practices help conserve nutrients by minimizing leaching and excessive cooking.","whyWrongChoices":"Alternative options: foods should not be stirred, baking soda should not be added, pots should be kept covered"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all newly hired employees should be given::::', 'all newly hired employees should be given:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Orientation introduces newly hired employees to the organization, policies, workplace, and basic expectations before or at the start of employment.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Orientation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Orientation introduces newly hired employees to the organization, policies, workplace, and basic expectations before or at the start of employment.","whyWrongChoices":"Alternative options: Pre-service training, IQ test, Medical check-up"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:considered as the best conductor of heat, this type of cookware material is commonly used as base for non-stick pans.:::copper', 'considered as the best conductor of heat, this type of cookware material is commonly used as base for non-stick pans.', 'Copper', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aluminum: Lightweight, budget-friendly, heats quickly, and serves as the standard body or base for most non-stick cookware.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Copper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aluminum: Lightweight, budget-friendly, heats quickly, and serves as the standard body or base for most non-stick cookware.\n\nCopper: The absolute best heat conductor among common cookware metals, but it is expensive and rarely used as a cheap non-stick base.\n\nIron: Retains heat well but conducts slowly and is heavy.\n\nStainless steel: A poor direct conductor of heat, usually requiring an aluminum or copper core.","whyWrongChoices":"Alternative options: Aluminum, Iron, Stainless steel"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:considered as the best conductor of heat, this type of cookware material is commonly used as base for non-stick pans.:::', 'considered as the best conductor of heat, this type of cookware material is commonly used as base for non-stick pans.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aluminum: Lightweight, budget-friendly, heats quickly, and serves as the standard body or base for most non-stick cookware.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Copper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aluminum: Lightweight, budget-friendly, heats quickly, and serves as the standard body or base for most non-stick cookware.\n\nCopper: The absolute best heat conductor among common cookware metals, but it is expensive and rarely used as a cheap non-stick base.\n\nIron: Retains heat well but conducts slowly and is heavy.\n\nStainless steel: A poor direct conductor of heat, usually requiring an aluminum or copper core.","whyWrongChoices":"Alternative options: Aluminum, Iron, Stainless steel"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dish made of dried gabi leaves, coconut milk, siling labuyo, and bagoong.:::laing', 'dish made of dried gabi leaves, coconut milk, siling labuyo, and bagoong.', 'Laing', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Laing is an iconic Bicolano dish composed fundamentally of shredded dried gabi (taro) leaves, simmered slowly in creamy coconut milk (gata).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Laing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Laing is an iconic Bicolano dish composed fundamentally of shredded dried gabi (taro) leaves, simmered slowly in creamy coconut milk (gata).\n\nIt is heavily spiced with sliced siling labuyo (bird''s eye chili) and seasoned with bagoong alamang (shrimp paste) along with pork or dried fish (daing) to give it its hallmark spicy and deeply savory profile. It is a culinary standard that the leaves must be completely dried before cooking to prevent the calcium oxalate crystals in the taro plants from causing an itchy sensation in the mouth.\n\n• Pinangat: Also a famous taro leaf delicacy from Bicol (specifically Camalig, Albay), but it is distinctly made by wrapping a mixture of pork, shrimp, and young coconut meat inside layered pouches of fresh, whole gabi leaves before tying them with string and steaming them in seasoned coconut milk.\n• Sinanglay: Another Bicolano coconut-milk-based favorite, but its centerpiece is whole fresh fish (like tilapia) stuffed with tomatoes and onions, which is then wrapped in fresh gabi or mustard leaves and cooked in spiced gata.\n• Tinimtim: A traditional Ilocano dish primarily featuring saluyot (jute leaves) or ampalaya leaves simmered with garlic, vinegar, and bagoong. It does not utilize gabi leaves or coconut milk as core components.","whyWrongChoices":"Alternative options: Tinimtim, Pinangat, Sinanglay"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:dish made of dried gabi leaves, coconut milk, siling labuyo, and bagoong.:::', 'dish made of dried gabi leaves, coconut milk, siling labuyo, and bagoong.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Laing is an iconic Bicolano dish composed fundamentally of shredded dried gabi (taro) leaves, simmered slowly in creamy coconut milk (gata).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Laing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Laing is an iconic Bicolano dish composed fundamentally of shredded dried gabi (taro) leaves, simmered slowly in creamy coconut milk (gata).\n\nIt is heavily spiced with sliced siling labuyo (bird''s eye chili) and seasoned with bagoong alamang (shrimp paste) along with pork or dried fish (daing) to give it its hallmark spicy and deeply savory profile. It is a culinary standard that the leaves must be completely dried before cooking to prevent the calcium oxalate crystals in the taro plants from causing an itchy sensation in the mouth.\n\n• Pinangat: Also a famous taro leaf delicacy from Bicol (specifically Camalig, Albay), but it is distinctly made by wrapping a mixture of pork, shrimp, and young coconut meat inside layered pouches of fresh, whole gabi leaves before tying them with string and steaming them in seasoned coconut milk.\n• Sinanglay: Another Bicolano coconut-milk-based favorite, but its centerpiece is whole fresh fish (like tilapia) stuffed with tomatoes and onions, which is then wrapped in fresh gabi or mustard leaves and cooked in spiced gata.\n• Tinimtim: A traditional Ilocano dish primarily featuring saluyot (jute leaves) or ampalaya leaves simmered with garlic, vinegar, and bagoong. It does not utilize gabi leaves or coconut milk as core components.","whyWrongChoices":"Alternative options: Tinimtim, Pinangat, Sinanglay"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:aterm used for the filipino cooking method of wrapping food in leaves:::all of the above', 'aterm used for the filipino cooking method of wrapping food in leaves', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pinais refers to wrapping food in banana leaves and sometimes inner layers of kamamba (Piper umbellatum) or taro leaves before being cooked in coconut milk or steamed. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pinais refers to wrapping food in banana leaves and sometimes inner layers of kamamba (Piper umbellatum) or taro leaves before being cooked in coconut milk or steamed. \n\nBinagol is a sweet, dense kakanin (rice cake delicacy) from Leyte. It is made from grated gabi (taro root), condensed milk, and sugar, which is packed into a halved coconut shell (baong), wrapped in banana leaves, and securely tied before being steamed.\n\nBinalot means \"wrapped\" in the Filipino language and refers to a traditional style of serving a complete meal wrapped inside a banana leaf.","whyWrongChoices":"Alternative options: Binalot, Binagol, Pinais"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:aterm used for the filipino cooking method of wrapping food in leaves:::', 'aterm used for the filipino cooking method of wrapping food in leaves', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pinais refers to wrapping food in banana leaves and sometimes inner layers of kamamba (Piper umbellatum) or taro leaves before being cooked in coconut milk or steamed. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pinais refers to wrapping food in banana leaves and sometimes inner layers of kamamba (Piper umbellatum) or taro leaves before being cooked in coconut milk or steamed. \n\nBinagol is a sweet, dense kakanin (rice cake delicacy) from Leyte. It is made from grated gabi (taro root), condensed milk, and sugar, which is packed into a halved coconut shell (baong), wrapped in banana leaves, and securely tied before being steamed.\n\nBinalot means \"wrapped\" in the Filipino language and refers to a traditional style of serving a complete meal wrapped inside a banana leaf.","whyWrongChoices":"Alternative options: Binalot, Binagol, Pinais"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a popular dish from davao and other parts of mindanao that features internal organs cooked with pineapple and bell peppers.:::paklay', 'a popular dish from davao and other parts of mindanao that features internal organs cooked with pineapple and bell peppers.', 'Paklay', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Paklay is a renowned traditional stew popular across the Visayas and Mindanao regions (especially in Davao and Cebu). It is made from a combination of sliced pork, beef, or goat internal organs (such as tripe, liver, heart, and kidneys) sautéed with ginger, bamboo shoots, bell peppers, and pineapple chunks. The pineapple plays a vital role by lending a subtle, refreshing sweetness and acidity that balances the rich, robust flavor of the offal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Paklay\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Paklay is a renowned traditional stew popular across the Visayas and Mindanao regions (especially in Davao and Cebu). It is made from a combination of sliced pork, beef, or goat internal organs (such as tripe, liver, heart, and kidneys) sautéed with ginger, bamboo shoots, bell peppers, and pineapple chunks. The pineapple plays a vital role by lending a subtle, refreshing sweetness and acidity that balances the rich, robust flavor of the offal.\n\n• Sampayna: This is a Northern Mindanao (specifically Camiguin and Cagayan de Oro) variation of dinuguan (pork blood stew). It uses chitterlings and blood but does not feature the sweet pineapple or stir-fried bell pepper profile profile of paklay.\n• Barbacoa: In a local context, this often sounds like Balbacua, a very popular viscous beef skin and trotters stew from Southern Mindanao that is slow-cooked with star anise and annatto rather than internal organs and fruit.\n• Tiolah Sapi: A festive, sacred beef broth dish native to the Tausug people of the Sulu Archipelago in Mindanao. It features beef and tripe seared in burnt coconut paste (pamapa), giving it a signature green color and lemongrass-ginger profile, but it does not use pineapple.","whyWrongChoices":"Alternative options: Barbacoa, Sampayna, Tiolah Sapi"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a popular dish from davao and other parts of mindanao that features internal organs cooked with pineapple and bell peppers.:::', 'a popular dish from davao and other parts of mindanao that features internal organs cooked with pineapple and bell peppers.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Paklay is a renowned traditional stew popular across the Visayas and Mindanao regions (especially in Davao and Cebu). It is made from a combination of sliced pork, beef, or goat internal organs (such as tripe, liver, heart, and kidneys) sautéed with ginger, bamboo shoots, bell peppers, and pineapple chunks. The pineapple plays a vital role by lending a subtle, refreshing sweetness and acidity that balances the rich, robust flavor of the offal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Paklay\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Paklay is a renowned traditional stew popular across the Visayas and Mindanao regions (especially in Davao and Cebu). It is made from a combination of sliced pork, beef, or goat internal organs (such as tripe, liver, heart, and kidneys) sautéed with ginger, bamboo shoots, bell peppers, and pineapple chunks. The pineapple plays a vital role by lending a subtle, refreshing sweetness and acidity that balances the rich, robust flavor of the offal.\n\n• Sampayna: This is a Northern Mindanao (specifically Camiguin and Cagayan de Oro) variation of dinuguan (pork blood stew). It uses chitterlings and blood but does not feature the sweet pineapple or stir-fried bell pepper profile profile of paklay.\n• Barbacoa: In a local context, this often sounds like Balbacua, a very popular viscous beef skin and trotters stew from Southern Mindanao that is slow-cooked with star anise and annatto rather than internal organs and fruit.\n• Tiolah Sapi: A festive, sacred beef broth dish native to the Tausug people of the Sulu Archipelago in Mindanao. It features beef and tripe seared in burnt coconut paste (pamapa), giving it a signature green color and lemongrass-ginger profile, but it does not use pineapple.","whyWrongChoices":"Alternative options: Barbacoa, Sampayna, Tiolah Sapi"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the sum of the sides of a work triangle must not exceed::::both a and b', 'the sum of the sides of a work triangle must not exceed:', 'both a and b', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The kitchen work triangle is an efficiency design principle that connects the three main work areas: the sink, the stove, and the refrigerator.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"both a and b\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The kitchen work triangle is an efficiency design principle that connects the three main work areas: the sink, the stove, and the refrigerator.\n\nAccording to traditional residential space planning and board exam standards, the total perimeter (the sum of all three sides) should ideally be between 12 to 22 feet.\n\nWhen converting 22 feet into the metric system (22 x 0.3048), it equals approximately 6.7 meters.","whyWrongChoices":"Alternative options: 22 ft, 6.5m, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the visayan version of paksiw na isda:::inun-unan', 'the visayan version of paksiw na isda', 'Inun-unan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Inun-unan is a classic Visayan fish dish cooked in vinegar, ginger, garlic, onions, and chili peppers. It is the direct Visayan counterpart to the Tagalog Paksiw na Isda, with the traditional distinction that Inun-unan typically does not include any water, soy sauce, or vegetables like eggplant and ampalaya, making the vinegar and ginger profile much sharper.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inun-unan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Inun-unan is a classic Visayan fish dish cooked in vinegar, ginger, garlic, onions, and chili peppers. It is the direct Visayan counterpart to the Tagalog Paksiw na Isda, with the traditional distinction that Inun-unan typically does not include any water, soy sauce, or vegetables like eggplant and ampalaya, making the vinegar and ginger profile much sharper.\n\n• Higado: A traditional Ilocano savory dish made from pork tenderloin, pig liver, and other innards cooked with bell peppers, green peas, and vinegar.\n• Lininta: A traditional Muslim-Filipino (Maranao) dish where fish is marinated with palapa (a spicy condiment made from native scallions, ginger, and chili), wrapped securely in banana leaves, and then steamed.\n• Utan: A general Visayan term for vegetable soup or vegetable dishes (most commonly Utan Bisaya, a clear vegetable broth loaded with leafy greens, squash, okra, and fried/grilled fish).","whyWrongChoices":"Alternative options: Lininta, Utan, Higado"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the visayan version of paksiw na isda:::', 'the visayan version of paksiw na isda', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Inun-unan is a classic Visayan fish dish cooked in vinegar, ginger, garlic, onions, and chili peppers. It is the direct Visayan counterpart to the Tagalog Paksiw na Isda, with the traditional distinction that Inun-unan typically does not include any water, soy sauce, or vegetables like eggplant and ampalaya, making the vinegar and ginger profile much sharper.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inun-unan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Inun-unan is a classic Visayan fish dish cooked in vinegar, ginger, garlic, onions, and chili peppers. It is the direct Visayan counterpart to the Tagalog Paksiw na Isda, with the traditional distinction that Inun-unan typically does not include any water, soy sauce, or vegetables like eggplant and ampalaya, making the vinegar and ginger profile much sharper.\n\n• Higado: A traditional Ilocano savory dish made from pork tenderloin, pig liver, and other innards cooked with bell peppers, green peas, and vinegar.\n• Lininta: A traditional Muslim-Filipino (Maranao) dish where fish is marinated with palapa (a spicy condiment made from native scallions, ginger, and chili), wrapped securely in banana leaves, and then steamed.\n• Utan: A general Visayan term for vegetable soup or vegetable dishes (most commonly Utan Bisaya, a clear vegetable broth loaded with leafy greens, squash, okra, and fried/grilled fish).","whyWrongChoices":"Alternative options: Lininta, Utan, Higado"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:clearing of the bread and butter plate is done at the .:::left of the guest', 'clearing of the bread and butter plate is done at the .', 'Left of the guest', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bread-and-butter plates are conventionally cleared from the guest''s left because they are placed on the left side of the cover.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Left of the guest\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bread-and-butter plates are conventionally cleared from the guest''s left because they are placed on the left side of the cover.","whyWrongChoices":"Alternative options: Right of the guest, Both a and b, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:clearing of the bread and butter plate is done at the .:::', 'clearing of the bread and butter plate is done at the .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bread-and-butter plates are conventionally cleared from the guest''s left because they are placed on the left side of the cover.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Left of the guest\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bread-and-butter plates are conventionally cleared from the guest''s left because they are placed on the left side of the cover.","whyWrongChoices":"Alternative options: Right of the guest, Both a and b, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in storing fruits, the following practices delay the ripening process except::::wrapping fruits in newspaper', 'in storing fruits, the following practices delay the ripening process except:', 'wrapping fruits in newspaper', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wrapping unpeeled, whole fruits in newspaper accelerates ripening by trapping natural ethylene gas. It is also unsafe because toxic printing inks, heavy metals, and harmful chemicals leach directly into your food, especially when it is hot or oily.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"wrapping fruits in newspaper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wrapping unpeeled, whole fruits in newspaper accelerates ripening by trapping natural ethylene gas. It is also unsafe because toxic printing inks, heavy metals, and harmful chemicals leach directly into your food, especially when it is hot or oily.\n\nDelays the ripening process:\n• Separating ripe from unripe fruit slows ethylene exposure and delays ripening. \n• Refrigeration delays ripening process by slowing down enzyme activity.\n• Wrapping in PET bags: Produce packaging often uses specific polymer films with micro-perforations or special barrier properties to let excess ethylene and carbon dioxide escape. This stops moisture buildup and prevents rapid decay.","whyWrongChoices":"Alternative options: storing fruits inside the refrigerator, wrapping fruits in polyethylene bags, separating the ripe from the unripe"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in storing fruits, the following practices delay the ripening process except::::', 'in storing fruits, the following practices delay the ripening process except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wrapping unpeeled, whole fruits in newspaper accelerates ripening by trapping natural ethylene gas. It is also unsafe because toxic printing inks, heavy metals, and harmful chemicals leach directly into your food, especially when it is hot or oily.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"wrapping fruits in newspaper\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wrapping unpeeled, whole fruits in newspaper accelerates ripening by trapping natural ethylene gas. It is also unsafe because toxic printing inks, heavy metals, and harmful chemicals leach directly into your food, especially when it is hot or oily.\n\nDelays the ripening process:\n• Separating ripe from unripe fruit slows ethylene exposure and delays ripening. \n• Refrigeration delays ripening process by slowing down enzyme activity.\n• Wrapping in PET bags: Produce packaging often uses specific polymer films with micro-perforations or special barrier properties to let excess ethylene and carbon dioxide escape. This stops moisture buildup and prevents rapid decay.","whyWrongChoices":"Alternative options: storing fruits inside the refrigerator, wrapping fruits in polyethylene bags, separating the ripe from the unripe"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:service style with table side service, except::::american', 'service style with table side service, except:', 'American', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In hospitality and food service management, American service (also commonly known as plate service) is explicitly defined as a style where food is completely portioned, arranged, and plated onto individual dishes inside the kitchen by the chefs. The waitstaff then carries these pre-plated meals directly out to the dining tables to serve the guests. Because everything is completed back in the kitchen, it involves absolutely no tableside assembly, carving, or serving from platters.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"American\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In hospitality and food service management, American service (also commonly known as plate service) is explicitly defined as a style where food is completely portioned, arranged, and plated onto individual dishes inside the kitchen by the chefs. The waitstaff then carries these pre-plated meals directly out to the dining tables to serve the guests. Because everything is completed back in the kitchen, it involves absolutely no tableside assembly, carving, or serving from platters.\n\n• Russian Service: Servers bring heavy silver platters containing large portions of food directly out to the dining room. They then walk around the table and use a spoon and fork to serve individual portions onto the guests'' empty plates tableside.\n• French Service: This is the ultimate tableside service style. Food is brought out partially raw or undercooked on a rolling cart called a gueridon. Cooking, finishing (like flambéing), carving, and plating are executed right next to the guests'' seats.\n• English Service: Large platters and tureens of food are placed directly onto the dining table right in front of the host. The host then carves the meat and portions the sides onto plates at the table, which are then passed down or distributed by the servers.","whyWrongChoices":"Alternative options: English, Russian, French"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:service style with table side service, except::::', 'service style with table side service, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In hospitality and food service management, American service (also commonly known as plate service) is explicitly defined as a style where food is completely portioned, arranged, and plated onto individual dishes inside the kitchen by the chefs. The waitstaff then carries these pre-plated meals directly out to the dining tables to serve the guests. Because everything is completed back in the kitchen, it involves absolutely no tableside assembly, carving, or serving from platters.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"American\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In hospitality and food service management, American service (also commonly known as plate service) is explicitly defined as a style where food is completely portioned, arranged, and plated onto individual dishes inside the kitchen by the chefs. The waitstaff then carries these pre-plated meals directly out to the dining tables to serve the guests. Because everything is completed back in the kitchen, it involves absolutely no tableside assembly, carving, or serving from platters.\n\n• Russian Service: Servers bring heavy silver platters containing large portions of food directly out to the dining room. They then walk around the table and use a spoon and fork to serve individual portions onto the guests'' empty plates tableside.\n• French Service: This is the ultimate tableside service style. Food is brought out partially raw or undercooked on a rolling cart called a gueridon. Cooking, finishing (like flambéing), carving, and plating are executed right next to the guests'' seats.\n• English Service: Large platters and tureens of food are placed directly onto the dining table right in front of the host. The host then carves the meat and portions the sides onto plates at the table, which are then passed down or distributed by the servers.","whyWrongChoices":"Alternative options: English, Russian, French"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fast food combo meals are:::semi a la carte', 'fast food combo meals are', 'Semi a la carte', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Semi a la carte is when an entrée or main item is bundled together with specific side dishes (such as French fries and a beverage) and sold at a single, combined price. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Semi a la carte\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Semi a la carte is when an entrée or main item is bundled together with specific side dishes (such as French fries and a beverage) and sold at a single, combined price. \n\n• Ala carte: Items are listed and priced completely separate from one another.\n• Table d''Hote: This refers to a complete multi-course meal (from appetizer, soup, to main course, and dessert) served at a fixed total price with some options in some categories, usually found in banquets or fine dining rather than fast food.","whyWrongChoices":"Alternative options: Ala carte menus, Table d’Hote, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of service where food is prepared in the kitchen and carried in serving platters while the waitstaff serves all the guests.:::continental', 'type of service where food is prepared in the kitchen and carried in serving platters while the waitstaff serves all the guests.', 'Continental', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Continental Service (also widely known as Russian Service or platter service) is a formal style of dining where all food is fully cooked, portioned, and arranged beautifully on serving platters inside the kitchen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Continental\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Continental Service (also widely known as Russian Service or platter service) is a formal style of dining where all food is fully cooked, portioned, and arranged beautifully on serving platters inside the kitchen.\n\nThe waitstaff then carries these platters into the dining room and serves each guest individually from the platter onto their plates. \n\n• Country-style (or American/Family-style) involves placing large serving dishes on the table for guests to pass around and serve themselves. \n• Plated (or American Service) features food that is already portioned and arranged onto individual plates in the kitchen before being served. \n• Compromise is a hybrid service style where some courses are served directly from the kitchen and others are served at the table by the host or passed around.","whyWrongChoices":"Alternative options: Country-Style, Plated, Compromise"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of service where food is prepared in the kitchen and carried in serving platters while the waitstaff serves all the guests.:::', 'type of service where food is prepared in the kitchen and carried in serving platters while the waitstaff serves all the guests.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Continental Service (also widely known as Russian Service or platter service) is a formal style of dining where all food is fully cooked, portioned, and arranged beautifully on serving platters inside the kitchen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Continental\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Continental Service (also widely known as Russian Service or platter service) is a formal style of dining where all food is fully cooked, portioned, and arranged beautifully on serving platters inside the kitchen.\n\nThe waitstaff then carries these platters into the dining room and serves each guest individually from the platter onto their plates. \n\n• Country-style (or American/Family-style) involves placing large serving dishes on the table for guests to pass around and serve themselves. \n• Plated (or American Service) features food that is already portioned and arranged onto individual plates in the kitchen before being served. \n• Compromise is a hybrid service style where some courses are served directly from the kitchen and others are served at the table by the host or passed around.","whyWrongChoices":"Alternative options: Country-Style, Plated, Compromise"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following tasks are done from the left of the guest, except::::setting and clearing of dinner plates', 'the following tasks are done from the left of the guest, except:', 'setting and clearing of dinner plates', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dinner plates are served and cleared from the right side. All other options are presented and cleared from the left side of the guest.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"setting and clearing of dinner plates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dinner plates are served and cleared from the right side. All other options are presented and cleared from the left side of the guest.","whyWrongChoices":"Alternative options: presenting and serving from platters, clearing of bread and butter plate, serving salad"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following tasks are done from the left of the guest, except::::', 'the following tasks are done from the left of the guest, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dinner plates are served and cleared from the right side. All other options are presented and cleared from the left side of the guest.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"setting and clearing of dinner plates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dinner plates are served and cleared from the right side. All other options are presented and cleared from the left side of the guest.","whyWrongChoices":"Alternative options: presenting and serving from platters, clearing of bread and butter plate, serving salad"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following tasks are done from the right of the guest, except::::serving bread', 'the following tasks are done from the right of the guest, except:', 'serving bread', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bread is conventionally served from the left, whereas flatware and beverage ware are generally placed, served, or cleared from the right.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"serving bread\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bread is conventionally served from the left, whereas flatware and beverage ware are generally placed, served, or cleared from the right.","whyWrongChoices":"Alternative options: laying of flatware, setting and clearing of beverage ware, pouring of beverage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following tasks are done from the right of the guest, except::::', 'the following tasks are done from the right of the guest, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bread is conventionally served from the left, whereas flatware and beverage ware are generally placed, served, or cleared from the right.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"serving bread\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bread is conventionally served from the left, whereas flatware and beverage ware are generally placed, served, or cleared from the right.","whyWrongChoices":"Alternative options: laying of flatware, setting and clearing of beverage ware, pouring of beverage"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:fast food combo meals are:::', 'fast food combo meals are', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Semi a la carte is when an entrée or main item is bundled together with specific side dishes (such as French fries and a beverage) and sold at a single, combined price. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Semi a la carte\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Semi a la carte is when an entrée or main item is bundled together with specific side dishes (such as French fries and a beverage) and sold at a single, combined price. \n\n• Ala carte: Items are listed and priced completely separate from one another.\n• Table d''Hote: This refers to a complete multi-course meal (from appetizer, soup, to main course, and dessert) served at a fixed total price with some options in some categories, usually found in banquets or fine dining rather than fast food.","whyWrongChoices":"Alternative options: Ala carte menus, Table d’Hote, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the sum of the sides of a work triangle must not exceed::::', 'the sum of the sides of a work triangle must not exceed:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The kitchen work triangle is an efficiency design principle that connects the three main work areas: the sink, the stove, and the refrigerator.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"both a and b\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The kitchen work triangle is an efficiency design principle that connects the three main work areas: the sink, the stove, and the refrigerator.\n\nAccording to traditional residential space planning and board exam standards, the total perimeter (the sum of all three sides) should ideally be between 12 to 22 feet.\n\nWhen converting 22 feet into the metric system (22 x 0.3048), it equals approximately 6.7 meters.","whyWrongChoices":"Alternative options: 22 ft, 6.5m, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the most important work center is the .:::sink', 'the most important work center is the .', 'sink', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The sink is commonly regarded as the most important work center because food preparation and cleanup require frequent access to water.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"sink\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The sink is commonly regarded as the most important work center because food preparation and cleanup require frequent access to water.","whyWrongChoices":"Alternative options: gas range, refrigerator, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the most important work center is the .:::', 'the most important work center is the .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The sink is commonly regarded as the most important work center because food preparation and cleanup require frequent access to water.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"sink\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The sink is commonly regarded as the most important work center because food preparation and cleanup require frequent access to water.","whyWrongChoices":"Alternative options: gas range, refrigerator, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:size of dinner napkin::::18-26 inches', 'size of dinner napkin:', '18-26 inches', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The standard size for a dinner napkin is 18-26 inches (typically spanning 18–20 inches square for informal or everyday use, though formal dinner napkins can range up to 20–26 inches). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"18-26 inches\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The standard size for a dinner napkin is 18-26 inches (typically spanning 18–20 inches square for informal or everyday use, though formal dinner napkins can range up to 20–26 inches). \n\n• Informal / Everyday Dinner: 18 to 20 inches square\n• Formal / Multi-Course Dinner: 20 to 26 inches square\n• Purpose: Large enough to unfold and cover the lap completely","whyWrongChoices":"Alternative options: 24-30 inches, 9-12 inches, 20-24 inches"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:size of dinner napkin::::', 'size of dinner napkin:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The standard size for a dinner napkin is 18-26 inches (typically spanning 18–20 inches square for informal or everyday use, though formal dinner napkins can range up to 20–26 inches). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"18-26 inches\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The standard size for a dinner napkin is 18-26 inches (typically spanning 18–20 inches square for informal or everyday use, though formal dinner napkins can range up to 20–26 inches). \n\n• Informal / Everyday Dinner: 18 to 20 inches square\n• Formal / Multi-Course Dinner: 20 to 26 inches square\n• Purpose: Large enough to unfold and cover the lap completely","whyWrongChoices":"Alternative options: 24-30 inches, 9-12 inches, 20-24 inches"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this type of kitchen arrangement allows the refrigerator, range, and sink to be spaced out for efficiency and convenience::::u-shaped', 'this type of kitchen arrangement allows the refrigerator, range, and sink to be spaced out for efficiency and convenience:', 'U-shaped', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The U-shaped kitchen layout spans across three adjacent walls. Because it utilizes three separate surfaces, it is considered the most efficient arrangement for maximizing the work triangle. It perfectly allows the refrigerator, range, and sink to be widely spaced out on their own designated walls. This spacing provides dedicated counter segments around each major appliance, creating optimal flow, reducing traffic interference, and making meal prep highly convenient.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"U-shaped\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The U-shaped kitchen layout spans across three adjacent walls. Because it utilizes three separate surfaces, it is considered the most efficient arrangement for maximizing the work triangle. It perfectly allows the refrigerator, range, and sink to be widely spaced out on their own designated walls. This spacing provides dedicated counter segments around each major appliance, creating optimal flow, reducing traffic interference, and making meal prep highly convenient.\n\n• Single line: Places all three major appliances flat against a single wall. This forces an assembly-line setup where components are crammed tightly together rather than being broadly spaced out.\n• Island type: Adds a detached island workstation to an existing configuration. While highly versatile, the island itself does not inherently dictate the baseline spacing of the main three appliances.\n• L-shaped: Spreads the work area along two perpendicular walls. While highly efficient for open floor plans, it forces at least two of the three main appliances to share a single wall line, making it less spaced out than a full three-walled U-shape.","whyWrongChoices":"Alternative options: single line, L-shaped, island type"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this type of kitchen arrangement allows the refrigerator, range, and sink to be spaced out for efficiency and convenience::::', 'this type of kitchen arrangement allows the refrigerator, range, and sink to be spaced out for efficiency and convenience:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The U-shaped kitchen layout spans across three adjacent walls. Because it utilizes three separate surfaces, it is considered the most efficient arrangement for maximizing the work triangle. It perfectly allows the refrigerator, range, and sink to be widely spaced out on their own designated walls. This spacing provides dedicated counter segments around each major appliance, creating optimal flow, reducing traffic interference, and making meal prep highly convenient.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"U-shaped\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The U-shaped kitchen layout spans across three adjacent walls. Because it utilizes three separate surfaces, it is considered the most efficient arrangement for maximizing the work triangle. It perfectly allows the refrigerator, range, and sink to be widely spaced out on their own designated walls. This spacing provides dedicated counter segments around each major appliance, creating optimal flow, reducing traffic interference, and making meal prep highly convenient.\n\n• Single line: Places all three major appliances flat against a single wall. This forces an assembly-line setup where components are crammed tightly together rather than being broadly spaced out.\n• Island type: Adds a detached island workstation to an existing configuration. While highly versatile, the island itself does not inherently dictate the baseline spacing of the main three appliances.\n• L-shaped: Spreads the work area along two perpendicular walls. While highly efficient for open floor plans, it forces at least two of the three main appliances to share a single wall line, making it less spaced out than a full three-walled U-shape.","whyWrongChoices":"Alternative options: single line, L-shaped, island type"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
