INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a set meal with a choice within menu categories is called::::table d''hote', 'a set meal with a choice within menu categories is called:', 'table d''hote', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table d’hote is a fixed-price, multi-course meal where guests select from a limited number of choices within specific categories (like appetizer, main, and dessert). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"table d''hote\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table d’hote is a fixed-price, multi-course meal where guests select from a limited number of choices within specific categories (like appetizer, main, and dessert). \n\n• Semi à la carte: A menu type where some items (usually the main entree) are priced individually, but automatically include specific side components (like a soup, salad, or potato) at no extra charge.\n• Prix Fixe: A similar fixed-price menu concept with no choices.","whyWrongChoices":"Alternative options: prix fixe, semi a la carte, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a set meal with a choice within menu categories is called::::', 'a set meal with a choice within menu categories is called:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table d’hote is a fixed-price, multi-course meal where guests select from a limited number of choices within specific categories (like appetizer, main, and dessert). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"table d''hote\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table d’hote is a fixed-price, multi-course meal where guests select from a limited number of choices within specific categories (like appetizer, main, and dessert). \n\n• Semi à la carte: A menu type where some items (usually the main entree) are priced individually, but automatically include specific side components (like a soup, salad, or potato) at no extra charge.\n• Prix Fixe: A similar fixed-price menu concept with no choices.","whyWrongChoices":"Alternative options: prix fixe, semi a la carte, none of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of menu where the entrée is combined and priced with other items such as salad, starch, and/or beverage.:::semi a la carte', 'type of menu where the entrée is combined and priced with other items such as salad, starch, and/or beverage.', 'Semi a la carte', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Semi à la carte menus combine an entrée with other selected items, while à la carte prices items separately and table d''hôte offers a complete meal for one price.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Semi a la carte\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Semi à la carte menus combine an entrée with other selected items, while à la carte prices items separately and table d''hôte offers a complete meal for one price.","whyWrongChoices":"Alternative options: A la carte, Table d'' Hote, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the size of one cover is preferably::::24 inches', 'the size of one cover is preferably:', '24 inches', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"One cover is preferably about 24 inches of table space to provide adequate room for place settings and service.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"24 inches\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"One cover is preferably about 24 inches of table space to provide adequate room for place settings and service.","whyWrongChoices":"Alternative options: 18 inches, 21 inches, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of menu where the entrée is combined and priced with other items such as salad, starch, and/or beverage.:::', 'type of menu where the entrée is combined and priced with other items such as salad, starch, and/or beverage.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Semi à la carte menus combine an entrée with other selected items, while à la carte prices items separately and table d''hôte offers a complete meal for one price.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Semi a la carte\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Semi à la carte menus combine an entrée with other selected items, while à la carte prices items separately and table d''hôte offers a complete meal for one price.","whyWrongChoices":"Alternative options: A la carte, Table d'' Hote, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:example of fringe benefit:::christmas bonus', 'example of fringe benefit', 'Christmas bonus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Christmas bonus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.\n\nWhile regular pay covers your standard work hours, monetary perks like a Christmas bonus, profit sharing, gym memberships, or rice allowances are classic examples of fringe or de minimis benefits. Under Philippine labor and tax laws, discretionary year-end bonuses and small-value perks given for employee wellness or holiday celebrations fall directly into this category.","whyWrongChoices":"Alternative options: Promotion, Dayoff, Holiday off"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:example of fringe benefit:::', 'example of fringe benefit', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Christmas bonus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.\n\nWhile regular pay covers your standard work hours, monetary perks like a Christmas bonus, profit sharing, gym memberships, or rice allowances are classic examples of fringe or de minimis benefits. Under Philippine labor and tax laws, discretionary year-end bonuses and small-value perks given for employee wellness or holiday celebrations fall directly into this category.","whyWrongChoices":"Alternative options: Promotion, Dayoff, Holiday off"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:type of menu usually used in schools, hospitals, and institutions is called::::none of the above', 'type of menu usually used in schools, hospitals, and institutions is called:', 'None of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Schools, hospitals, and institutional facilities primarily use a cycle menu (or cyclic menu).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Schools, hospitals, and institutional facilities primarily use a cycle menu (or cyclic menu).","whyWrongChoices":"Alternative options: Table d'' Hote, Single use, Du jour"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
