INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:the place calasiao is associated with what food.:::', 'the place calasiao is associated with what food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Calasiao, a municipality in Pangasinan, is widely celebrated as the \"Puto Capital of the Philippines\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Puto\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Calasiao, a municipality in Pangasinan, is widely celebrated as the \"Puto Capital of the Philippines\".\n\nPuto Calasiao is a bite-sized, semi-sweet steamed rice cake. It stands out because it is traditionally made using fermented short-grain glutinous rice (galapong), giving it a distinctively soft, chewy, and slightly springy texture.\n\nWhile the classic white version is the most iconic, it is also sold in variations like ube (purple yam), pandan, cheese, mango, and strawberry.\n\n• Buro: A fermented rice dish (often mixed with fish or shrimp) that is a famous condiment in neighboring Pampanga and other parts of Central/Northern Luzon.\n• Patupat: A sweet Ilocano delicacy made of glutinous rice cooked in sugarcane juice and wrapped in a woven pouch of coconut or palm leaves. While found in Pangasinan, it is not uniquely synonymous with Calasiao the way puto is.\n• Tocino: A sweet, cured pork breakfast meat most famously associated with Pampanga (the culinary capital of the Philippines).","whyWrongChoices":"Alternative options: Buro, Tocino, Patupat"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:intrinsic factors that have the capacity to either stimulate or retard the growth of microorganisms in food:::', 'intrinsic factors that have the capacity to either stimulate or retard the growth of microorganisms in food', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Intrinsic factors are properties inherent in the food itself.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pH, redox potential, water activity and antimicrobial substances\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Intrinsic factors are properties inherent in the food itself.\n\nThese are:\n• pH\n• Moisture\n• Redox potential\n• Nutrient Content\n• Antimicrobial constituents\n• Biological structures","whyWrongChoices":"Alternative options: Temperature, relative humidity, pH and water activity, Redox potential, atmosphere, relative humidity and antimicrobial substances, Relative humidity, atmosphere and temperature"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:linat-an is closest to the dish::::nilaga', 'linat-an is closest to the dish:', 'Nilaga', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Linat-an is a traditional boiled pork soup dish native to the Visayas and Mindanao regions. Structurally and visually, it is almost identical to the Tagalog Nilaga. Both dishes involve simmering tough cuts of meat (usually pork ribs or beef) with an abundance of clear broth, paired with vegetables like cabbage, potatoes, leafy greens, and green beans.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nilaga\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Linat-an is a traditional boiled pork soup dish native to the Visayas and Mindanao regions. Structurally and visually, it is almost identical to the Tagalog Nilaga. Both dishes involve simmering tough cuts of meat (usually pork ribs or beef) with an abundance of clear broth, paired with vegetables like cabbage, potatoes, leafy greens, and green beans.\n\nThe primary difference lies in the flavor aromatics: while Nilaga relies heavily on onions and whole black peppercorns, Linat-an incorporates distinct regional ingredients like lemongrass (tanglad), ginger, and sometimes red bell peppers or taro (gabi) to give the clear broth a more fragrant, refreshing, and slightly sweet flavor profile.","whyWrongChoices":"Alternative options: Kare-kare, Pochero, Cardillo"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:linat-an is closest to the dish::::', 'linat-an is closest to the dish:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Linat-an is a traditional boiled pork soup dish native to the Visayas and Mindanao regions. Structurally and visually, it is almost identical to the Tagalog Nilaga. Both dishes involve simmering tough cuts of meat (usually pork ribs or beef) with an abundance of clear broth, paired with vegetables like cabbage, potatoes, leafy greens, and green beans.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nilaga\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Linat-an is a traditional boiled pork soup dish native to the Visayas and Mindanao regions. Structurally and visually, it is almost identical to the Tagalog Nilaga. Both dishes involve simmering tough cuts of meat (usually pork ribs or beef) with an abundance of clear broth, paired with vegetables like cabbage, potatoes, leafy greens, and green beans.\n\nThe primary difference lies in the flavor aromatics: while Nilaga relies heavily on onions and whole black peppercorns, Linat-an incorporates distinct regional ingredients like lemongrass (tanglad), ginger, and sometimes red bell peppers or taro (gabi) to give the clear broth a more fragrant, refreshing, and slightly sweet flavor profile.","whyWrongChoices":"Alternative options: Kare-kare, Pochero, Cardillo"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. fruits become more brilliant in color during ripening. sentence b. this is due to the breakdown of chlorophyll and exposes the underlying pigments.:::both sentences are correct', 'sentence a. fruits become more brilliant in color during ripening. sentence b. this is due to the breakdown of chlorophyll and exposes the underlying pigments.', 'Both sentences are correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During ripening, chlorophyll breaks down and green color diminishes, revealing or allowing the development of pigments such as carotenoids and anthocyanins, which make many fruits appear brighter or more intensely colored.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During ripening, chlorophyll breaks down and green color diminishes, revealing or allowing the development of pigments such as carotenoids and anthocyanins, which make many fruits appear brighter or more intensely colored.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. fruits become more brilliant in color during ripening. sentence b. this is due to the breakdown of chlorophyll and exposes the underlying pigments.:::', 'sentence a. fruits become more brilliant in color during ripening. sentence b. this is due to the breakdown of chlorophyll and exposes the underlying pigments.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During ripening, chlorophyll breaks down and green color diminishes, revealing or allowing the development of pigments such as carotenoids and anthocyanins, which make many fruits appear brighter or more intensely colored.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During ripening, chlorophyll breaks down and green color diminishes, revealing or allowing the development of pigments such as carotenoids and anthocyanins, which make many fruits appear brighter or more intensely colored.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:intrinsic factors that have the capacity to either stimulate or retard the growth of microorganisms in food:::ph, redox potential, water activity and antimicrobial substances', 'intrinsic factors that have the capacity to either stimulate or retard the growth of microorganisms in food', 'pH, redox potential, water activity and antimicrobial substances', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Intrinsic factors are properties inherent in the food itself.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pH, redox potential, water activity and antimicrobial substances\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Intrinsic factors are properties inherent in the food itself.\n\nThese are:\n• pH\n• Moisture\n• Redox potential\n• Nutrient Content\n• Antimicrobial constituents\n• Biological structures","whyWrongChoices":"Alternative options: Temperature, relative humidity, pH and water activity, Redox potential, atmosphere, relative humidity and antimicrobial substances, Relative humidity, atmosphere and temperature"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bse or mad cow disease involves::::prions', 'bse or mad cow disease involves:', 'Prions', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bovine Spongiform Encephalopathy (BSE), commonly known as mad cow disease, is caused by an abnormal, infectious type of protein called a prion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bovine Spongiform Encephalopathy (BSE), commonly known as mad cow disease, is caused by an abnormal, infectious type of protein called a prion.\n\nPrions are not alive like bacteria, viruses, or parasites; they are misfolded proteins. When they enter the body, they induce normal proteins in the brain and central nervous system to also misfold.\n\nThis causes a progressive, fatal neurological degeneration that leaves the brain looking like a sponge (spongiform). In humans, consuming meat contaminated with BSE prions can lead to Variant Creutzfeldt-Jakob Disease (vCJD), which is also fatal. Prions are extremely resilient and cannot be destroyed by normal cooking, freezing, or standard chemical disinfection.\n\n• Virus: Infectious agents made of genetic material (DNA or RNA) inside a protein coat (e.g., Rabies, Foot-and-Mouth disease). BSE does not contain any genetic material.\n• Bacteria: Single-celled living microorganisms (e.g., Salmonella, Anthrax). They can be killed with antibiotics or heat, whereas prions cannot.\n• Parasites: Organisms that live on or inside a host and feed off it (e.g., Tapeworms, Trichinella in pork).","whyWrongChoices":"Alternative options: Virus, Bacteria, Parasites"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:bse or mad cow disease involves::::', 'bse or mad cow disease involves:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bovine Spongiform Encephalopathy (BSE), commonly known as mad cow disease, is caused by an abnormal, infectious type of protein called a prion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bovine Spongiform Encephalopathy (BSE), commonly known as mad cow disease, is caused by an abnormal, infectious type of protein called a prion.\n\nPrions are not alive like bacteria, viruses, or parasites; they are misfolded proteins. When they enter the body, they induce normal proteins in the brain and central nervous system to also misfold.\n\nThis causes a progressive, fatal neurological degeneration that leaves the brain looking like a sponge (spongiform). In humans, consuming meat contaminated with BSE prions can lead to Variant Creutzfeldt-Jakob Disease (vCJD), which is also fatal. Prions are extremely resilient and cannot be destroyed by normal cooking, freezing, or standard chemical disinfection.\n\n• Virus: Infectious agents made of genetic material (DNA or RNA) inside a protein coat (e.g., Rabies, Foot-and-Mouth disease). BSE does not contain any genetic material.\n• Bacteria: Single-celled living microorganisms (e.g., Salmonella, Anthrax). They can be killed with antibiotics or heat, whereas prions cannot.\n• Parasites: Organisms that live on or inside a host and feed off it (e.g., Tapeworms, Trichinella in pork).","whyWrongChoices":"Alternative options: Virus, Bacteria, Parasites"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. monosodium glutamate is found in seaweeds. sentence b. msg is a food seasoning that enhances the flavor of dishes.:::both sentences are correct', 'sentence a. monosodium glutamate is found in seaweeds. sentence b. msg is a food seasoning that enhances the flavor of dishes.', 'Both sentences are correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"MSG was discovered in 1908 by Japanese chemist Kikunae Ikeda who studied a traditional Japanese broth (dashi) made from kombu, a type of edible kelp/seaweed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"MSG was discovered in 1908 by Japanese chemist Kikunae Ikeda who studied a traditional Japanese broth (dashi) made from kombu, a type of edible kelp/seaweed.\n\nHe extracted glutamic acid crystals from the seaweed broth and realized they created a savory, delicious taste he named umami.\n\nHe combined this glutamate with sodium to create monosodium glutamate (MSG) because it dissolved easily and tasted best.\n\nIt is used as a seasoning because it enhances umami and intensifies savory flavor.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. monosodium glutamate is found in seaweeds. sentence b. msg is a food seasoning that enhances the flavor of dishes.:::', 'sentence a. monosodium glutamate is found in seaweeds. sentence b. msg is a food seasoning that enhances the flavor of dishes.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"MSG was discovered in 1908 by Japanese chemist Kikunae Ikeda who studied a traditional Japanese broth (dashi) made from kombu, a type of edible kelp/seaweed.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"MSG was discovered in 1908 by Japanese chemist Kikunae Ikeda who studied a traditional Japanese broth (dashi) made from kombu, a type of edible kelp/seaweed.\n\nHe extracted glutamic acid crystals from the seaweed broth and realized they created a savory, delicious taste he named umami.\n\nHe combined this glutamate with sodium to create monosodium glutamate (MSG) because it dissolved easily and tasted best.\n\nIt is used as a seasoning because it enhances umami and intensifies savory flavor.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:minimum internal cooking temperature of eggs:::160ºf', 'minimum internal cooking temperature of eggs', '160ºF', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Eggs: 160°F (71°C) for combined dishes like casseroles or quiches; for whole, fried, or scrambled eggs, cook until both the white and the yolk are firm.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"160ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Eggs: 160°F (71°C) for combined dishes like casseroles or quiches; for whole, fried, or scrambled eggs, cook until both the white and the yolk are firm.","whyWrongChoices":"Alternative options: 140ºF, 150ºF, 170ºF"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. spices come from different parts of the plant. sentence b. herbs that are dried are called spices.:::sentence a is correct', 'sentence a. spices come from different parts of the plant. sentence b. herbs that are dried are called spices.', 'Sentence A is correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sentence A is correct because spices may come from seeds, bark, roots, fruits, flowers, or other plant parts. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence A is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sentence A is correct because spices may come from seeds, bark, roots, fruits, flowers, or other plant parts. \n\nSentence B is incorrect because herbs and spices are classified primarily by the plant part used rather than by whether the material is dried.","whyWrongChoices":"Alternative options: Sentence B is correct, Both sentences are correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
