INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:open market buying means:::', 'open market buying means', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Open market buying is a flexible procurement method commonly used in food service and small businesses. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"After a canvass, purchases are made from the vendor who offers the best terms\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Open market buying is a flexible procurement method commonly used in food service and small businesses. \n\nInstead of locking into a long-term contract with a single supplier, the buyer \"canvasses\" (requests price quotes from) multiple vendors and places the order with whoever provides the best price, quality, and delivery terms for that specific purchase.","whyWrongChoices":"Alternative options: The buyer has to go to the market, Purchasing through a middle man, Purchasing from one source only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pertains to a disciplined, data-driven approach and methodology for eliminating defects in any process from manufacturing to transactional and from product to service.:::six sigma', 'pertains to a disciplined, data-driven approach and methodology for eliminating defects in any process from manufacturing to transactional and from product to service.', 'Six sigma', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Six Sigma is a disciplined, data-driven method for eliminating defects and reducing variation in manufacturing, service, and transactional processes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Six sigma\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Six Sigma is a disciplined, data-driven method for eliminating defects and reducing variation in manufacturing, service, and transactional processes.\n\nHACCP (Hazard Analysis Critical Control Point) focuses specifically on food safety risk management.\n\nISO 22000 is an international standard for food safety management systems.\n\nTQM (Total Quality Management) is a broader organization-wide management approach to long-term success through customer satisfaction, rather than a specific statistical defect-reduction methodology like Six Sigma.","whyWrongChoices":"Alternative options: HACCP, ISO 22000, TQM"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pertains to a disciplined, data-driven approach and methodology for eliminating defects in any process from manufacturing to transactional and from product to service.:::', 'pertains to a disciplined, data-driven approach and methodology for eliminating defects in any process from manufacturing to transactional and from product to service.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Six Sigma is a disciplined, data-driven method for eliminating defects and reducing variation in manufacturing, service, and transactional processes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Six sigma\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Six Sigma is a disciplined, data-driven method for eliminating defects and reducing variation in manufacturing, service, and transactional processes.\n\nHACCP (Hazard Analysis Critical Control Point) focuses specifically on food safety risk management.\n\nISO 22000 is an international standard for food safety management systems.\n\nTQM (Total Quality Management) is a broader organization-wide management approach to long-term success through customer satisfaction, rather than a specific statistical defect-reduction methodology like Six Sigma.","whyWrongChoices":"Alternative options: HACCP, ISO 22000, TQM"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:function of management involved in the development of formal structure through which work is defined, divided and coordinated to achieve goals.:::organizing', 'function of management involved in the development of formal structure through which work is defined, divided and coordinated to achieve goals.', 'Organizing', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In management science (including Henri Fayol''s and Luther Gulick''s classic management frameworks), organizing is the process of building the formal structural framework of an organization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Organizing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In management science (including Henri Fayol''s and Luther Gulick''s classic management frameworks), organizing is the process of building the formal structural framework of an organization.\n\nIt specifically involves arranging resources, defining roles, dividing tasks or labor into manageable departments, and establishing a hierarchy or chain of command so that workflows can be successfully coordinated to achieve organizational objectives.\n\n• Planning: The foundational function that involves setting goals, projecting future scenarios, and mapping out the specific courses of action required to achieve them. It happens before structure is built.\n• Coordinating: The function of harmonizing and unifying separate team efforts and workflows to ensure they run smoothly together. While related to structure, it is a component of directing or the output of a well-organized system rather than the function that develops the formal structural framework.\n• Staffing: The process of recruiting, selecting, hiring, training, and maintaining the human resources needed to fill the positions established by the organizational structure.","whyWrongChoices":"Alternative options: Coordinating, Planning, Staffing"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:function of management involved in the development of formal structure through which work is defined, divided and coordinated to achieve goals.:::', 'function of management involved in the development of formal structure through which work is defined, divided and coordinated to achieve goals.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In management science (including Henri Fayol''s and Luther Gulick''s classic management frameworks), organizing is the process of building the formal structural framework of an organization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Organizing\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In management science (including Henri Fayol''s and Luther Gulick''s classic management frameworks), organizing is the process of building the formal structural framework of an organization.\n\nIt specifically involves arranging resources, defining roles, dividing tasks or labor into manageable departments, and establishing a hierarchy or chain of command so that workflows can be successfully coordinated to achieve organizational objectives.\n\n• Planning: The foundational function that involves setting goals, projecting future scenarios, and mapping out the specific courses of action required to achieve them. It happens before structure is built.\n• Coordinating: The function of harmonizing and unifying separate team efforts and workflows to ensure they run smoothly together. While related to structure, it is a component of directing or the output of a well-organized system rather than the function that develops the formal structural framework.\n• Staffing: The process of recruiting, selecting, hiring, training, and maintaining the human resources needed to fill the positions established by the organizational structure.","whyWrongChoices":"Alternative options: Coordinating, Planning, Staffing"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the aim of work design is to::::increase productivity and employee satisfaction', 'the aim of work design is to:', 'increase productivity and employee satisfaction', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Work design aims to develop jobs and methods that improve productivity and employee satisfaction while supporting efficient, safe work.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"increase productivity and employee satisfaction\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Work design aims to develop jobs and methods that improve productivity and employee satisfaction while supporting efficient, safe work.","whyWrongChoices":"Alternative options: provide efficient and effective work methods, provide safe and healthy work environment, design a staff of fit people"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. crystals are formed from concentrated sugar solutions. sentence b. crystallization is inversely related to the ease of solubility.:::both sentences are correct', 'sentence a. crystals are formed from concentrated sugar solutions. sentence b. crystallization is inversely related to the ease of solubility.', 'Both sentences are correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sentence A is correct because crystallization occurs when a supersaturated or concentrated sugar solution allows dissolved sugar molecules to arrange into crystals. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sentence A is correct because crystallization occurs when a supersaturated or concentrated sugar solution allows dissolved sugar molecules to arrange into crystals. \n\nSentence B is also correct: substances that are less soluble crystallize more readily as the solution becomes supersaturated.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Bothsentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. crystals are formed from concentrated sugar solutions. sentence b. crystallization is inversely related to the ease of solubility.:::', 'sentence a. crystals are formed from concentrated sugar solutions. sentence b. crystallization is inversely related to the ease of solubility.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sentence A is correct because crystallization occurs when a supersaturated or concentrated sugar solution allows dissolved sugar molecules to arrange into crystals. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sentence A is correct because crystallization occurs when a supersaturated or concentrated sugar solution allows dissolved sugar molecules to arrange into crystals. \n\nSentence B is also correct: substances that are less soluble crystallize more readily as the solution becomes supersaturated.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Bothsentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. shortening impedes gluten development by hydrolysis. sentence b. impeding gluten development would result in flaky products.:::sentence b is correct', 'sentence a. shortening impedes gluten development by hydrolysis. sentence b. impeding gluten development would result in flaky products.', 'Sentence B is correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sentence A is incorrect because shortening impedes gluten development mainly by coating flour proteins and physically limiting hydration and gluten formation, not by hydrolysis. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence B is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sentence A is incorrect because shortening impedes gluten development mainly by coating flour proteins and physically limiting hydration and gluten formation, not by hydrolysis. \n\nSentence B is correct because limiting gluten development produces a tender or flaky texture, as desired in products such as pastry.","whyWrongChoices":"Alternative options: Sentence A is correct, Bothsentences are correct, Bothsentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. vinaigrette is an example of a temporary emulsion. sentence b. temporary emulsions are separated by heat.:::sentence a is correct', 'sentence a. vinaigrette is an example of a temporary emulsion. sentence b. temporary emulsions are separated by heat.', 'Sentence A is correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sentence A is correct because vinaigrette is a temporary emulsion of oil and vinegar that separates on standing. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence A is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sentence A is correct because vinaigrette is a temporary emulsion of oil and vinegar that separates on standing. \n\nSentence B is incorrect because temporary emulsions separate primarily because the phases are immiscible and the emulsion is unstable, not simply because of heat.","whyWrongChoices":"Alternative options: Sentence B is correct, Both sentences are correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sentence a. vinaigrette is an example of a temporary emulsion. sentence b. temporary emulsions are separated by heat.:::', 'sentence a. vinaigrette is an example of a temporary emulsion. sentence b. temporary emulsions are separated by heat.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sentence A is correct because vinaigrette is a temporary emulsion of oil and vinegar that separates on standing. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence A is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sentence A is correct because vinaigrette is a temporary emulsion of oil and vinegar that separates on standing. \n\nSentence B is incorrect because temporary emulsions separate primarily because the phases are immiscible and the emulsion is unstable, not simply because of heat.","whyWrongChoices":"Alternative options: Sentence B is correct, Both sentences are correct, Both sentences are incorrect"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:compute for the kcal of 850 ml 5% amino acid:::', 'compute for the kcal of 850 ml 5% amino acid', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"170 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation\n\nIn clinical nutrition and parenteral nutrition calculations, a 5% amino acid solution means there are 5 grams of pure amino acid in every 100 mL of fluid. Amino acids provide 4 kcal per gram.\n\n1. Calculate the total grams of amino acid:\n\t• Total grams = 850 mL x 0.05 (5%)\n\t• Total grams = 42.5 grams\n\n2. Calculate the total calories (kcal):\n\t• Total kcal = 42.5 grams x 4 kcal/gram","whyWrongChoices":"Alternative options: 200 kcal, 300 kcal, 250 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:best temperature for drying.:::140-145ºf', 'best temperature for drying.', '140-145ºF', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In food dehydration, 140°F or 60°C is widely recognized as the optimum standard temperature. If the temperature is too high, the outside of the food cooks and hardens (“case hardening”), which traps moisture inside and leads to molding. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"140-145ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In food dehydration, 140°F or 60°C is widely recognized as the optimum standard temperature. If the temperature is too high, the outside of the food cooks and hardens (“case hardening”), which traps moisture inside and leads to molding. \n\nThis temperature range is also high enough to safely drive out moisture quickly before spoilage micro-organisms can replicate, but low enough to avoid cooking the food. \n\nConsider also:\n• Air Flow\n• Time\n• Nature of food","whyWrongChoices":"Alternative options: 100-115ºF, 120-125ºF, 130-135ºF"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:best temperature for drying.:::', 'best temperature for drying.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In food dehydration, 140°F or 60°C is widely recognized as the optimum standard temperature. If the temperature is too high, the outside of the food cooks and hardens (“case hardening”), which traps moisture inside and leads to molding. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"140-145ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In food dehydration, 140°F or 60°C is widely recognized as the optimum standard temperature. If the temperature is too high, the outside of the food cooks and hardens (“case hardening”), which traps moisture inside and leads to molding. \n\nThis temperature range is also high enough to safely drive out moisture quickly before spoilage micro-organisms can replicate, but low enough to avoid cooking the food. \n\nConsider also:\n• Air Flow\n• Time\n• Nature of food","whyWrongChoices":"Alternative options: 100-115ºF, 120-125ºF, 130-135ºF"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all of the following are nuts except::::munggo', 'all of the following are nuts except:', 'Munggo', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Munggo is a legume, not a culinary nut. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Munggo\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Munggo is a legume, not a culinary nut. \n\nKastanyas, pili, and coconut are commonly classified or used as nuts.","whyWrongChoices":"Alternative options: Kastanyas, Pili, Coconut"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
