INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a patient is prescribed a diet containing 1,500 mg of sodium. how many meq of sodium are contained in the diet?:::65 meq na', 'a patient is prescribed a diet containing 1,500 mg of sodium. how many meq of sodium are contained in the diet?', '65 mEq Na', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To convert milligrams of sodium to milliequivalents (mEq), use: mEq = (mg * valence) ÷ atomic weight ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"65 mEq Na\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To convert milligrams of sodium to milliequivalents (mEq), use: mEq = (mg * valence) ÷ atomic weight \n\nSodium (Na⁺) has: \n• Atomic weight ≈ 23 \n• Valence = 1 \n\nTherefore: mEq Na = (1500 * 1) ÷ 23 = 65.2 mEq \n\nThus, the calculated value is approximately 65 mEq.","whyWrongChoices":"Alternative options: 55 mEq Na, 60 mEq Na, 70 mEq Na"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a low calcium diet contains no more than mg calcium:::600 mg', 'a low calcium diet contains no more than mg calcium', '600 mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In traditional therapeutic diet planning, a low-calcium diet is generally prescribed to provide no more than 600 mg calcium per day. This is a therapeutic restriction, not the recommended daily calcium intake for healthy individuals. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"600 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In traditional therapeutic diet planning, a low-calcium diet is generally prescribed to provide no more than 600 mg calcium per day. This is a therapeutic restriction, not the recommended daily calcium intake for healthy individuals. \n\nCalcium is essential for bone and tooth mineralization, muscle contraction, nerve transmission, and blood clotting, so restricting calcium should be done only when clinically indicated. For NDLE purposes, when the question asks for the traditional definition of a low-calcium diet, remember ≤600 mg/day.","whyWrongChoices":"Alternative options: 500 mg, 700 mg, 800 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements is false?:::', 'which of the following statements is false?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three statements are considered true based on commonly used Philippine food-composition references for purine content. Purines are naturally occurring compounds found in many foods. They are metabolized to uric acid, making dietary purine intake particularly relevant in the nutritional management of gout and hyperuricemia. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three statements are considered true based on commonly used Philippine food-composition references for purine content. Purines are naturally occurring compounds found in many foods. They are metabolized to uric acid, making dietary purine intake particularly relevant in the nutritional management of gout and hyperuricemia. \n\n• Tamban (sardines) is a fish with relatively high purine content. \n• Dried beans also contain purines, but their purine content may be lower than that of certain high-purine fish such as sardines. \n• Chicken organ meats, including gizzard and intestine, contain substantial amounts of purines. \n• Pork liver is a high-purine organ meat and has a higher purine content than pork blood in the referenced food data.","whyWrongChoices":"Alternative options: Tamban has higher purine content as compared to dried beans., Chicken gizzard has about the same purine content of that of the chicken intestine., Pork liver has higher purine content as compared to pork blood"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements is true?:::evaporated milk has higher cholesterol content than lean fish', 'which of the following statements is true?', 'Evaporated milk has higher cholesterol content than lean fish', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Evaporated milk is an animal-derived food and therefore contains cholesterol. Based on the food-composition values used in the original question, its cholesterol content is higher than that of lean meat when compared using the specified serving/reference amounts. The question is testing the ability to compare cholesterol content among commonly consumed foods, rather than simply identifying whether a food contains cholesterol. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Evaporated milk has higher cholesterol content than lean fish\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Evaporated milk is an animal-derived food and therefore contains cholesterol. Based on the food-composition values used in the original question, its cholesterol content is higher than that of lean meat when compared using the specified serving/reference amounts. The question is testing the ability to compare cholesterol content among commonly consumed foods, rather than simply identifying whether a food contains cholesterol. \n\n\"Vegetables have a higher cholesterol content than fruits\" is false because plant foods do not contain cholesterol. Vegetables and fruits naturally contain zero dietary cholesterol. \n\n\"Shrimp has a higher cholesterol content than butter\" should also not be selected based simply on the fact that shrimp is recognized as relatively high in cholesterol. Cholesterol comparisons must be made using the same reference/serving basis in the food-composition table.","whyWrongChoices":"Alternative options: Vegetable has higher cholesterol content as compared to fruits, Shrimp has higher cholesterol content than butter, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements is true?:::', 'which of the following statements is true?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Evaporated milk is an animal-derived food and therefore contains cholesterol. Based on the food-composition values used in the original question, its cholesterol content is higher than that of lean meat when compared using the specified serving/reference amounts. The question is testing the ability to compare cholesterol content among commonly consumed foods, rather than simply identifying whether a food contains cholesterol. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Evaporated milk has higher cholesterol content than lean fish\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Evaporated milk is an animal-derived food and therefore contains cholesterol. Based on the food-composition values used in the original question, its cholesterol content is higher than that of lean meat when compared using the specified serving/reference amounts. The question is testing the ability to compare cholesterol content among commonly consumed foods, rather than simply identifying whether a food contains cholesterol. \n\n\"Vegetables have a higher cholesterol content than fruits\" is false because plant foods do not contain cholesterol. Vegetables and fruits naturally contain zero dietary cholesterol. \n\n\"Shrimp has a higher cholesterol content than butter\" should also not be selected based simply on the fact that shrimp is recognized as relatively high in cholesterol. Cholesterol comparisons must be made using the same reference/serving basis in the food-composition table.","whyWrongChoices":"Alternative options: Vegetable has higher cholesterol content as compared to fruits, Shrimp has higher cholesterol content than butter, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet prescribed for patients with calcium oxalate stones:::acid-ash diet', 'diet prescribed for patients with calcium oxalate stones', 'Acid-ash diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Historically, an acid-ash diet was prescribed for calcium oxalate kidney stones. The traditional rationale was that acidification of the urine was thought to help maintain the solubility of calcium salts and reduce the formation of calcium-based stones. In contrast, an alkaline-ash diet was traditionally used for uric acid and cystine stones, for which increasing urinary pH promotes greater solubility.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Acid-ash diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Historically, an acid-ash diet was prescribed for calcium oxalate kidney stones. The traditional rationale was that acidification of the urine was thought to help maintain the solubility of calcium salts and reduce the formation of calcium-based stones. In contrast, an alkaline-ash diet was traditionally used for uric acid and cystine stones, for which increasing urinary pH promotes greater solubility.","whyWrongChoices":"Alternative options: Alkaline-ash diet, High fiber diet, Mediterranean Diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet prescribed for patients with calcium oxalate stones:::', 'diet prescribed for patients with calcium oxalate stones', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Historically, an acid-ash diet was prescribed for calcium oxalate kidney stones. The traditional rationale was that acidification of the urine was thought to help maintain the solubility of calcium salts and reduce the formation of calcium-based stones. In contrast, an alkaline-ash diet was traditionally used for uric acid and cystine stones, for which increasing urinary pH promotes greater solubility.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Acid-ash diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Historically, an acid-ash diet was prescribed for calcium oxalate kidney stones. The traditional rationale was that acidification of the urine was thought to help maintain the solubility of calcium salts and reduce the formation of calcium-based stones. In contrast, an alkaline-ash diet was traditionally used for uric acid and cystine stones, for which increasing urinary pH promotes greater solubility.","whyWrongChoices":"Alternative options: Alkaline-ash diet, High fiber diet, Mediterranean Diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a low calcium diet contains no more than mg calcium:::', 'a low calcium diet contains no more than mg calcium', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In traditional therapeutic diet planning, a low-calcium diet is generally prescribed to provide no more than 600 mg calcium per day. This is a therapeutic restriction, not the recommended daily calcium intake for healthy individuals. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"600 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In traditional therapeutic diet planning, a low-calcium diet is generally prescribed to provide no more than 600 mg calcium per day. This is a therapeutic restriction, not the recommended daily calcium intake for healthy individuals. \n\nCalcium is essential for bone and tooth mineralization, muscle contraction, nerve transmission, and blood clotting, so restricting calcium should be done only when clinically indicated. For NDLE purposes, when the question asks for the traditional definition of a low-calcium diet, remember ≤600 mg/day.","whyWrongChoices":"Alternative options: 500 mg, 700 mg, 800 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet prescribed for patients with cystine stone:::alkaline-ash diet', 'diet prescribed for patients with cystine stone', 'Alkaline-ash diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An alkaline-ash diet is the traditional dietary prescription for patients with cystine stones. Cystinuria is an inherited disorder in which excessive amounts of cystine are excreted in the urine. Because cystine has poor solubility in acidic urine, it is more likely to precipitate and form stones. Increasing urinary pH makes cystine more soluble and therefore helps reduce cystine crystallization. This principle remains clinically relevant. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Alkaline-ash diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An alkaline-ash diet is the traditional dietary prescription for patients with cystine stones. Cystinuria is an inherited disorder in which excessive amounts of cystine are excreted in the urine. Because cystine has poor solubility in acidic urine, it is more likely to precipitate and form stones. Increasing urinary pH makes cystine more soluble and therefore helps reduce cystine crystallization. This principle remains clinically relevant. \n\nCurrent management of cystinuria emphasizes high fluid intake to dilute urinary cystine and urinary alkalinization, commonly with potassium citrate, to maintain an appropriately alkaline urine. Dietary sodium restriction is also important because high sodium intake can increase urinary cystine excretion.","whyWrongChoices":"Alternative options: Acid-ash diet, High fiber diet, Mediterranean Diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:diet prescribed for patients with cystine stone:::', 'diet prescribed for patients with cystine stone', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An alkaline-ash diet is the traditional dietary prescription for patients with cystine stones. Cystinuria is an inherited disorder in which excessive amounts of cystine are excreted in the urine. Because cystine has poor solubility in acidic urine, it is more likely to precipitate and form stones. Increasing urinary pH makes cystine more soluble and therefore helps reduce cystine crystallization. This principle remains clinically relevant. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Alkaline-ash diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An alkaline-ash diet is the traditional dietary prescription for patients with cystine stones. Cystinuria is an inherited disorder in which excessive amounts of cystine are excreted in the urine. Because cystine has poor solubility in acidic urine, it is more likely to precipitate and form stones. Increasing urinary pH makes cystine more soluble and therefore helps reduce cystine crystallization. This principle remains clinically relevant. \n\nCurrent management of cystinuria emphasizes high fluid intake to dilute urinary cystine and urinary alkalinization, commonly with potassium citrate, to maintain an appropriately alkaline urine. Dietary sodium restriction is also important because high sodium intake can increase urinary cystine excretion.","whyWrongChoices":"Alternative options: Acid-ash diet, High fiber diet, Mediterranean Diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which among the following has the highest sodium content?:::', 'which among the following has the highest sodium content?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Among the choices, carrots have the highest sodium content based on the food-composition data underlying this question. Although all four are fresh vegetables and are generally considered low-sodium foods, their naturally occurring sodium concentrations are not identical. This is an important distinction in nutrition assessment and diet therapy: foods can be categorized as generally low in sodium while still having measurable differences in their sodium content. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carrots\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Among the choices, carrots have the highest sodium content based on the food-composition data underlying this question. Although all four are fresh vegetables and are generally considered low-sodium foods, their naturally occurring sodium concentrations are not identical. This is an important distinction in nutrition assessment and diet therapy: foods can be categorized as generally low in sodium while still having measurable differences in their sodium content. \n\nFor NDLE purposes, this question is primarily testing knowledge of the relative sodium content of common vegetables, rather than asking which food is considered “high sodium” clinically. In a sodium-restricted diet, carrots, cabbage, sayote, and pake may all be used, with the major dietary sodium reduction usually coming from limiting salt, processed foods, canned products, seasoning mixes, sauces, and other sodium-containing condiments.","whyWrongChoices":"Alternative options: Cabbage, Sayote, Pake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:statements describing the management of celiac disease::::the management of celiac disease is a life-long gluten-free diet.', 'statements describing the management of celiac disease:', 'The management of celiac disease is a life-long gluten-free diet.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The cornerstone of celiac disease management is a strict, lifelong gluten-free diet. Gluten exposure triggers an immune-mediated response that can cause intestinal mucosal injury even when the patient does not experience obvious gastrointestinal symptoms. Therefore, the absence of symptoms does not mean that celiac disease has disappeared or that gluten can safely be reintroduced. Strict adherence to a gluten-free diet promotes intestinal healing, improves nutritional status, and reduces the risk of complications associated with ongoing gluten exposure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The management of celiac disease is a life-long gluten-free diet.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The cornerstone of celiac disease management is a strict, lifelong gluten-free diet. Gluten exposure triggers an immune-mediated response that can cause intestinal mucosal injury even when the patient does not experience obvious gastrointestinal symptoms. Therefore, the absence of symptoms does not mean that celiac disease has disappeared or that gluten can safely be reintroduced. Strict adherence to a gluten-free diet promotes intestinal healing, improves nutritional status, and reduces the risk of complications associated with ongoing gluten exposure.","whyWrongChoices":"Alternative options: Small quantities of gluten may be allowed when celiac disease no longer manifests., Enough scientific evidence exists for what constitutes a safe amount of gluten intake., All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements is true?:::creatinine is directly affected by dietary protein intake', 'which of the following statements is true?', 'Creatinine is directly affected by dietary protein intake', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While serum creatinine is primarily a reflection of endogenous muscle mass, it can be significantly and directly affected by dietary protein intake, specifically through the consumption of cooked meat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Creatinine is directly affected by dietary protein intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While serum creatinine is primarily a reflection of endogenous muscle mass, it can be significantly and directly affected by dietary protein intake, specifically through the consumption of cooked meat.\n\nDuring the cooking process, the intense heat converts a portion of the creatine naturally present in animal muscle tissue into creatinine. When a patient consumes a cooked-meat meal, this pre-formed creatinine is rapidly absorbed across the gastrointestinal tract and enters the bloodstream.\n\nThis causes a temporary, artificial spike in serum creatinine levels independently of the patient''s actual kidney function. This dietary variable is clinically critical to recognize during nutrition and renal assessments, as a recent high-protein meat meal can skew laboratory results and lead to a falsely lower estimated Glomerular Filtration Rate (eGFR).","whyWrongChoices":"Alternative options: BUN can be used as the sole indicator of nutritional status, Cereals are acid-forming foods, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following statements is true?:::all of the above', 'which of the following statements is true?', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three statements describe principles used in therapeutic diet planning for renal conditions. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three statements describe principles used in therapeutic diet planning for renal conditions. \n\nCreatinine clearance is an indicator of renal filtration, and protein prescription in renal disease is adjusted according to the degree of renal impairment. As renal function declines, protein intake may need to be controlled to reduce nitrogenous waste production. Therefore, within the context of the diet-therapy principle tested here, better/higher creatinine clearance permits a less restricted protein intake, whereas greater renal impairment generally requires closer protein management. \n\nFor urinary stone management, oatmeal can be included in an oxalate-controlled diet because it is not among the foods classically considered very high in oxalate. \n\nThe statement regarding fats reflects the older diet-therapy teaching that high fat intake may promote urinary urate retention, particularly in the context of uric acid metabolism and stone formation.","whyWrongChoices":"Alternative options: The higher the creatinine clearance, the greater the level of protein allowed., Oatmeal is allowed in oxalate-controlled diet, Fats favor the retention of urates"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this diet is known as the cholesterol- and saturated fat restricted diet:::tlc diet', 'this diet is known as the cholesterol- and saturated fat restricted diet', 'TLC diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"TLC stands for Therapeutic Lifestyle Changes. It is a clinically designed medical nutrition therapy created by the National Institutes of Health (NIH) specifically to lower high blood cholesterol and reduce the risk of heart disease. Its primary guidelines mandate restricting saturated fat to less than 7% of total daily calories and limiting dietary cholesterol to less than 200 mg per day.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"TLC diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"TLC stands for Therapeutic Lifestyle Changes. It is a clinically designed medical nutrition therapy created by the National Institutes of Health (NIH) specifically to lower high blood cholesterol and reduce the risk of heart disease. Its primary guidelines mandate restricting saturated fat to less than 7% of total daily calories and limiting dietary cholesterol to less than 200 mg per day.\n\n\t• Atkin''s diet & Ketogenic Diet: These are low-carbohydrate, high-fat diets. They encourage high consumption of fats (including saturated fats) and proteins, making them the opposite of a fat-restricted eating plan.\n\t• DASH diet: While DASH (Dietary Approaches to Stop Hypertension) is also a heart-healthy diet low in saturated fat, its definitive, hallmark feature is sodium restriction aimed at lowering blood pressure. The TLC diet is the classic textbook answer explicitly labeled as the cholesterol- and saturated fat-restricted diet.","whyWrongChoices":"Alternative options: Ketogenic Diet, DASH diet, Atkin''s diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this diet is known as the cholesterol- and saturated fat restricted diet:::', 'this diet is known as the cholesterol- and saturated fat restricted diet', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"TLC stands for Therapeutic Lifestyle Changes. It is a clinically designed medical nutrition therapy created by the National Institutes of Health (NIH) specifically to lower high blood cholesterol and reduce the risk of heart disease. Its primary guidelines mandate restricting saturated fat to less than 7% of total daily calories and limiting dietary cholesterol to less than 200 mg per day.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"TLC diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"TLC stands for Therapeutic Lifestyle Changes. It is a clinically designed medical nutrition therapy created by the National Institutes of Health (NIH) specifically to lower high blood cholesterol and reduce the risk of heart disease. Its primary guidelines mandate restricting saturated fat to less than 7% of total daily calories and limiting dietary cholesterol to less than 200 mg per day.\n\n\t• Atkin''s diet & Ketogenic Diet: These are low-carbohydrate, high-fat diets. They encourage high consumption of fats (including saturated fats) and proteins, making them the opposite of a fat-restricted eating plan.\n\t• DASH diet: While DASH (Dietary Approaches to Stop Hypertension) is also a heart-healthy diet low in saturated fat, its definitive, hallmark feature is sodium restriction aimed at lowering blood pressure. The TLC diet is the classic textbook answer explicitly labeled as the cholesterol- and saturated fat-restricted diet.","whyWrongChoices":"Alternative options: Ketogenic Diet, DASH diet, Atkin''s diet"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which among the following has the highest sodium content?:::carrots', 'which among the following has the highest sodium content?', 'Carrots', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Among the choices, carrots have the highest sodium content based on the food-composition data underlying this question. Although all four are fresh vegetables and are generally considered low-sodium foods, their naturally occurring sodium concentrations are not identical. This is an important distinction in nutrition assessment and diet therapy: foods can be categorized as generally low in sodium while still having measurable differences in their sodium content. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carrots\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Among the choices, carrots have the highest sodium content based on the food-composition data underlying this question. Although all four are fresh vegetables and are generally considered low-sodium foods, their naturally occurring sodium concentrations are not identical. This is an important distinction in nutrition assessment and diet therapy: foods can be categorized as generally low in sodium while still having measurable differences in their sodium content. \n\nFor NDLE purposes, this question is primarily testing knowledge of the relative sodium content of common vegetables, rather than asking which food is considered “high sodium” clinically. In a sodium-restricted diet, carrots, cabbage, sayote, and pake may all be used, with the major dietary sodium reduction usually coming from limiting salt, processed foods, canned products, seasoning mixes, sauces, and other sodium-containing condiments.","whyWrongChoices":"Alternative options: Cabbage, Sayote, Pake"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all the foods in the list are allowed among patients with celiac disease::::sour cream, dried beans, millet, plain gelatin', 'all the foods in the list are allowed among patients with celiac disease:', 'Sour cream, dried beans, millet, plain gelatin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients diagnosed with celiac disease must strictly follow a lifelong gluten-free diet to prevent an autoimmune reaction that damages the villi of the small intestine. This means avoiding the proteins found in wheat, barley, and rye.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sour cream, dried beans, millet, plain gelatin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients diagnosed with celiac disease must strictly follow a lifelong gluten-free diet to prevent an autoimmune reaction that damages the villi of the small intestine. This means avoiding the proteins found in wheat, barley, and rye.\n\n• Sour cream: A plain dairy product that is naturally gluten-free.\n• Dried beans: Legumes that contain no gluten proteins.\n• Millet: A naturally gluten-free cereal grain that serves as a safe alternative to wheat.\n• Plain gelatin: A pure animal collagen product containing no grain fillers or gluten.\n\nWhy the Other Options contain forbidden foods:\n• Option A is incorrect because: Graham crackers are made from wheat flour, and Ovaltine contains malt extract derived from barley. Both will trigger a celiac flare-up. Vienna sausage also frequently uses wheat flour as a binder.\n• Option B is incorrect because: Breaded fish is coated in wheat-based breadcrumbs. Additionally, textured vegetable protein (TVP) can sometimes be cross-contaminated or derived from wheat gluten.","whyWrongChoices":"Alternative options: Textured vegetable protein, plain yogurt, breaded fish, popcorn, Tapioca starch, ovaltine, graham, Vienna sausage, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all the foods in the list are allowed among patients with celiac disease::::', 'all the foods in the list are allowed among patients with celiac disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients diagnosed with celiac disease must strictly follow a lifelong gluten-free diet to prevent an autoimmune reaction that damages the villi of the small intestine. This means avoiding the proteins found in wheat, barley, and rye.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sour cream, dried beans, millet, plain gelatin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients diagnosed with celiac disease must strictly follow a lifelong gluten-free diet to prevent an autoimmune reaction that damages the villi of the small intestine. This means avoiding the proteins found in wheat, barley, and rye.\n\n• Sour cream: A plain dairy product that is naturally gluten-free.\n• Dried beans: Legumes that contain no gluten proteins.\n• Millet: A naturally gluten-free cereal grain that serves as a safe alternative to wheat.\n• Plain gelatin: A pure animal collagen product containing no grain fillers or gluten.\n\nWhy the Other Options contain forbidden foods:\n• Option A is incorrect because: Graham crackers are made from wheat flour, and Ovaltine contains malt extract derived from barley. Both will trigger a celiac flare-up. Vienna sausage also frequently uses wheat flour as a binder.\n• Option B is incorrect because: Breaded fish is coated in wheat-based breadcrumbs. Additionally, textured vegetable protein (TVP) can sometimes be cross-contaminated or derived from wheat gluten.","whyWrongChoices":"Alternative options: Textured vegetable protein, plain yogurt, breaded fish, popcorn, Tapioca starch, ovaltine, graham, Vienna sausage, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all the foods in the list are not allowed among patients with celiac disease::::distilled white wine, vodka, vanilla ice cream in cone, crema de fruta', 'all the foods in the list are not allowed among patients with celiac disease:', 'Distilled white wine, vodka, vanilla ice cream in cone, crema de fruta', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Vanilla ice cream in a cone: Regular ice cream cones are made from wheat flour, which contains gluten and is highly toxic to individuals with celiac disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Distilled white wine, vodka, vanilla ice cream in cone, crema de fruta\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Vanilla ice cream in a cone: Regular ice cream cones are made from wheat flour, which contains gluten and is highly toxic to individuals with celiac disease.\n• Crema de fruta: This traditional Filipino dessert is natively constructed using layers of sponge cake (made with standard wheat flour) or graham crackers, both of which contain gluten and are strictly forbidden.\n\nBecause a person with celiac disease cannot consume wheat-based cones or traditional sponge cake/graham desserts, they cannot safely eat everything presented in this selection.\n\n• Other choices: These lists contain naturally gluten-free foods (like corn, maple syrup, wine, fresh vegetables, tofu, and lactose-free milk) which are generally allowed on a celiac diet. Therefore, they do not fulfill the criteria of a \"not allowed\" list.","whyWrongChoices":"Alternative options: Fresh vegetables washed in water with baking soda, margarine, tofu, Lactaid, Corn and maple syrup, fruit ices, sorbet, wine, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all the foods in the list are not allowed among patients with celiac disease::::', 'all the foods in the list are not allowed among patients with celiac disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Vanilla ice cream in a cone: Regular ice cream cones are made from wheat flour, which contains gluten and is highly toxic to individuals with celiac disease.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Distilled white wine, vodka, vanilla ice cream in cone, crema de fruta\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Vanilla ice cream in a cone: Regular ice cream cones are made from wheat flour, which contains gluten and is highly toxic to individuals with celiac disease.\n• Crema de fruta: This traditional Filipino dessert is natively constructed using layers of sponge cake (made with standard wheat flour) or graham crackers, both of which contain gluten and are strictly forbidden.\n\nBecause a person with celiac disease cannot consume wheat-based cones or traditional sponge cake/graham desserts, they cannot safely eat everything presented in this selection.\n\n• Other choices: These lists contain naturally gluten-free foods (like corn, maple syrup, wine, fresh vegetables, tofu, and lactose-free milk) which are generally allowed on a celiac diet. Therefore, they do not fulfill the criteria of a \"not allowed\" list.","whyWrongChoices":"Alternative options: Fresh vegetables washed in water with baking soda, margarine, tofu, Lactaid, Corn and maple syrup, fruit ices, sorbet, wine, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:statements describing the management of celiac disease::::', 'statements describing the management of celiac disease:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The cornerstone of celiac disease management is a strict, lifelong gluten-free diet. Gluten exposure triggers an immune-mediated response that can cause intestinal mucosal injury even when the patient does not experience obvious gastrointestinal symptoms. Therefore, the absence of symptoms does not mean that celiac disease has disappeared or that gluten can safely be reintroduced. Strict adherence to a gluten-free diet promotes intestinal healing, improves nutritional status, and reduces the risk of complications associated with ongoing gluten exposure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The management of celiac disease is a life-long gluten-free diet.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The cornerstone of celiac disease management is a strict, lifelong gluten-free diet. Gluten exposure triggers an immune-mediated response that can cause intestinal mucosal injury even when the patient does not experience obvious gastrointestinal symptoms. Therefore, the absence of symptoms does not mean that celiac disease has disappeared or that gluten can safely be reintroduced. Strict adherence to a gluten-free diet promotes intestinal healing, improves nutritional status, and reduces the risk of complications associated with ongoing gluten exposure.","whyWrongChoices":"Alternative options: Small quantities of gluten may be allowed when celiac disease no longer manifests., Enough scientific evidence exists for what constitutes a safe amount of gluten intake., All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pregnancy-induced hypertension is not::::a complication of diabetes', 'pregnancy-induced hypertension is not:', 'a complication of diabetes', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diabetes mellitus (both preexisting type 1/type 2 diabetes and gestational diabetes) is a major risk factor that predisposes a woman to developing pregnancy-induced hypertension (PIH). However, PIH itself is a specific vascular disorder that arises directly from placental dysfunction and endothelial stress, not a medical complication caused by diabetes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"a complication of diabetes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diabetes mellitus (both preexisting type 1/type 2 diabetes and gestational diabetes) is a major risk factor that predisposes a woman to developing pregnancy-induced hypertension (PIH). However, PIH itself is a specific vascular disorder that arises directly from placental dysfunction and endothelial stress, not a medical complication caused by diabetes.\n\n\t• Characterized by edema: PIH is classically identified in board exam frameworks by a hallmark triad of symptoms: hypertension, generalized or pitting edema, and proteinuria.\n\t• A complication of pregnancy: PIH is, by definition, a major medical complication that specifically occurs during pregnancy (typically developing after the 20th week of gestation).\n\t• Characterized by hypertension: Elevated blood pressure (systolic BP equal to or greater than 140 mmHg or diastolic BP equal to or greater than 90 mmHg) is the primary diagnostic feature of the condition.","whyWrongChoices":"Alternative options: a complication of pregnancy, characterized by hypertension, characterized by edema"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:pregnancy-induced hypertension is not::::', 'pregnancy-induced hypertension is not:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diabetes mellitus (both preexisting type 1/type 2 diabetes and gestational diabetes) is a major risk factor that predisposes a woman to developing pregnancy-induced hypertension (PIH). However, PIH itself is a specific vascular disorder that arises directly from placental dysfunction and endothelial stress, not a medical complication caused by diabetes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"a complication of diabetes\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diabetes mellitus (both preexisting type 1/type 2 diabetes and gestational diabetes) is a major risk factor that predisposes a woman to developing pregnancy-induced hypertension (PIH). However, PIH itself is a specific vascular disorder that arises directly from placental dysfunction and endothelial stress, not a medical complication caused by diabetes.\n\n\t• Characterized by edema: PIH is classically identified in board exam frameworks by a hallmark triad of symptoms: hypertension, generalized or pitting edema, and proteinuria.\n\t• A complication of pregnancy: PIH is, by definition, a major medical complication that specifically occurs during pregnancy (typically developing after the 20th week of gestation).\n\t• Characterized by hypertension: Elevated blood pressure (systolic BP equal to or greater than 140 mmHg or diastolic BP equal to or greater than 90 mmHg) is the primary diagnostic feature of the condition.","whyWrongChoices":"Alternative options: a complication of pregnancy, characterized by hypertension, characterized by edema"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the addition of 15 grams salt in the diet increases sodium content by::::6 grams', 'the addition of 15 grams salt in the diet increases sodium content by:', '6 grams', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table salt is chemically known as sodium chloride (NaCl). By molecular weight, pure table salt is composed of approximately 40% sodium and 60% chloride.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6 grams\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table salt is chemically known as sodium chloride (NaCl). By molecular weight, pure table salt is composed of approximately 40% sodium and 60% chloride.\n\nTo determine how much sodium is present in a given mass of table salt, you multiply the total mass by 40% (0.40):\n15 grams of salt x 0.40 = 6 grams of sodium","whyWrongChoices":"Alternative options: 3,000 mg, 2 grams, 8 grams"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the main goal of the krebs cycle is to produce h⁺ and electrons. these by-products are then transferred to the::::', 'the main goal of the krebs cycle is to produce h⁺ and electrons. these by-products are then transferred to the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Krebs cycle (citric acid cycle/TCA cycle) does not directly produce large amounts of ATP. Its major role is to oxidize acetyl-CoA and capture energy in the form of the reduced electron carriers NADH and FADH₂. These carriers transport high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, energy is used to pump H⁺ across the inner mitochondrial membrane, creating a proton gradient that drives ATP synthesis through oxidative phosphorylation. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Electron Transport Chain\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Krebs cycle (citric acid cycle/TCA cycle) does not directly produce large amounts of ATP. Its major role is to oxidize acetyl-CoA and capture energy in the form of the reduced electron carriers NADH and FADH₂. These carriers transport high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, energy is used to pump H⁺ across the inner mitochondrial membrane, creating a proton gradient that drives ATP synthesis through oxidative phosphorylation. \n\nFor NDLE purposes, the wording “H⁺ and electrons” is a little imprecise. The Krebs cycle primarily produces NADH and FADH₂, which carry the high-energy electrons to the ETC. The Krebs cycle also contributes indirectly to proton generation through subsequent oxidative phosphorylation, but free H⁺ is not its principal product.","whyWrongChoices":"Alternative options: Embden-Meyerhoff Pathway, Citric Acid Cycle, Cori Cycle"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamin/s known to be at low levels in patients following gluten-free diets:::all of the above', 'vitamin/s known to be at low levels in patients following gluten-free diets', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Traditional gluten-containing wheat flour products are heavily fortified and enriched by law with crucial micronutrients, including thiamine, riboflavin, niacin, iron, and folic acid (folate). In contrast, commercially available gluten-free substitute products are frequently manufactured using refined starches (such as tapioca, corn, or rice starch) that are not routinely fortified, leading to chronic dietary deficits.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Traditional gluten-containing wheat flour products are heavily fortified and enriched by law with crucial micronutrients, including thiamine, riboflavin, niacin, iron, and folic acid (folate). In contrast, commercially available gluten-free substitute products are frequently manufactured using refined starches (such as tapioca, corn, or rice starch) that are not routinely fortified, leading to chronic dietary deficits.\n\n• Folate (Vitamin B9): Folate deficiency is exceptionally common among individuals adhering to a gluten-free diet (GFD) due to the absence of enriched wheat products, coupled with a typically low intake of alternative whole grains.\n• Vitamin B6 and Vitamin B12: Multiple nutritional monitoring studies and clinical reviews indicate that patients on a strict GFD for extended periods show suboptimal plasma concentrations of Vitamin B6 and Vitamin B12. In patients with celiac disease, initial B12 deficiency stems from mucosal malabsorption in the ileum, which can persist if the diet is structurally restrictive or lacking in variety.","whyWrongChoices":"Alternative options: Folate, Vit B6, Vit B12, Vit B12, folate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamin/s known to be at low levels in patients following gluten-free diets:::', 'vitamin/s known to be at low levels in patients following gluten-free diets', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Traditional gluten-containing wheat flour products are heavily fortified and enriched by law with crucial micronutrients, including thiamine, riboflavin, niacin, iron, and folic acid (folate). In contrast, commercially available gluten-free substitute products are frequently manufactured using refined starches (such as tapioca, corn, or rice starch) that are not routinely fortified, leading to chronic dietary deficits.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Traditional gluten-containing wheat flour products are heavily fortified and enriched by law with crucial micronutrients, including thiamine, riboflavin, niacin, iron, and folic acid (folate). In contrast, commercially available gluten-free substitute products are frequently manufactured using refined starches (such as tapioca, corn, or rice starch) that are not routinely fortified, leading to chronic dietary deficits.\n\n• Folate (Vitamin B9): Folate deficiency is exceptionally common among individuals adhering to a gluten-free diet (GFD) due to the absence of enriched wheat products, coupled with a typically low intake of alternative whole grains.\n• Vitamin B6 and Vitamin B12: Multiple nutritional monitoring studies and clinical reviews indicate that patients on a strict GFD for extended periods show suboptimal plasma concentrations of Vitamin B6 and Vitamin B12. In patients with celiac disease, initial B12 deficiency stems from mucosal malabsorption in the ileum, which can persist if the diet is structurally restrictive or lacking in variety.","whyWrongChoices":"Alternative options: Folate, Vit B6, Vit B12, Vit B12, folate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is formed when two amino acids are bonded together::::dipeptide', 'it is formed when two amino acids are bonded together:', 'Dipeptide', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A dipeptide is formed when two amino acids are joined by a peptide bond. This occurs through a condensation (dehydration) reaction in which the carboxyl group of one amino acid reacts with the amino group of another, releasing one molecule of water. The resulting molecule contains two amino acid residues linked by one peptide bond. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dipeptide\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A dipeptide is formed when two amino acids are joined by a peptide bond. This occurs through a condensation (dehydration) reaction in which the carboxyl group of one amino acid reacts with the amino group of another, releasing one molecule of water. The resulting molecule contains two amino acid residues linked by one peptide bond. \n\nFor NDLE purposes, remember the progression: \n2 amino acids = dipeptide; 3 amino acids = tripeptide; several amino acids = oligopeptide; long chains = polypeptide/protein. \n\nThe number of peptide bonds is also important: two amino acids form one peptide bond, three amino acids form two peptide bonds, and so forth.","whyWrongChoices":"Alternative options: Alanine, Dissacharide, Protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is formed when two amino acids are bonded together::::', 'it is formed when two amino acids are bonded together:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A dipeptide is formed when two amino acids are joined by a peptide bond. This occurs through a condensation (dehydration) reaction in which the carboxyl group of one amino acid reacts with the amino group of another, releasing one molecule of water. The resulting molecule contains two amino acid residues linked by one peptide bond. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dipeptide\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A dipeptide is formed when two amino acids are joined by a peptide bond. This occurs through a condensation (dehydration) reaction in which the carboxyl group of one amino acid reacts with the amino group of another, releasing one molecule of water. The resulting molecule contains two amino acid residues linked by one peptide bond. \n\nFor NDLE purposes, remember the progression: \n2 amino acids = dipeptide; 3 amino acids = tripeptide; several amino acids = oligopeptide; long chains = polypeptide/protein. \n\nThe number of peptide bonds is also important: two amino acids form one peptide bond, three amino acids form two peptide bonds, and so forth.","whyWrongChoices":"Alternative options: Alanine, Dissacharide, Protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the main goal of the krebs cycle is to produce h⁺ and electrons. these by-products are then transferred to the::::electron transport chain', 'the main goal of the krebs cycle is to produce h⁺ and electrons. these by-products are then transferred to the:', 'Electron Transport Chain', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Krebs cycle (citric acid cycle/TCA cycle) does not directly produce large amounts of ATP. Its major role is to oxidize acetyl-CoA and capture energy in the form of the reduced electron carriers NADH and FADH₂. These carriers transport high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, energy is used to pump H⁺ across the inner mitochondrial membrane, creating a proton gradient that drives ATP synthesis through oxidative phosphorylation. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Electron Transport Chain\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Krebs cycle (citric acid cycle/TCA cycle) does not directly produce large amounts of ATP. Its major role is to oxidize acetyl-CoA and capture energy in the form of the reduced electron carriers NADH and FADH₂. These carriers transport high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, energy is used to pump H⁺ across the inner mitochondrial membrane, creating a proton gradient that drives ATP synthesis through oxidative phosphorylation. \n\nFor NDLE purposes, the wording “H⁺ and electrons” is a little imprecise. The Krebs cycle primarily produces NADH and FADH₂, which carry the high-energy electrons to the ETC. The Krebs cycle also contributes indirectly to proton generation through subsequent oxidative phosphorylation, but free H⁺ is not its principal product.","whyWrongChoices":"Alternative options: Embden-Meyerhoff Pathway, Citric Acid Cycle, Cori Cycle"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factors that improve ldl to hdl ratio except::::higher intakes of saturated fatty acids', 'factors that improve ldl to hdl ratio except:', 'Higher intakes of saturated fatty acids', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Consuming higher amounts of saturated fatty acids raises both low-density lipoprotein (LDL) and high-density lipoprotein (HDL) cholesterol. However, it drives a much larger increase in LDL (\"bad\") cholesterol compared to HDL. This selectively worsens the overall LDL-to-HDL ratio, increasing cardiovascular risk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Higher intakes of saturated fatty acids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Consuming higher amounts of saturated fatty acids raises both low-density lipoprotein (LDL) and high-density lipoprotein (HDL) cholesterol. However, it drives a much larger increase in LDL (\"bad\") cholesterol compared to HDL. This selectively worsens the overall LDL-to-HDL ratio, increasing cardiovascular risk.\n\n• Moderate R-OH (Alcohol) Consumption: In medical terminology, \"R-OH\" stands for alcohol. Scientific literature consistently shows that light-to-moderate alcohol intake (such as one drink a day for women or two for men) can moderately elevate HDL cholesterol levels, which helps optimize the blood lipid ratio.\n• Antioxidants: Dietary antioxidants (found in abundance in colorful fruits, vegetables, and whole grains) shield circulating LDL particles from undergoing oxidative modification. Because oxidized LDL is what triggers plaque accumulation in artery walls, antioxidants maintain healthy vascular transport and protect the functional efficiency of lipid handling.\n• Weight Control: Dropping excess body weight and avoiding abdominal obesity are highly effective ways to manage dyslipidemia. Achieving a healthy weight directly reduces total triglycerides and lowers LDL cholesterol levels while boosting cardioprotective HDL.","whyWrongChoices":"Alternative options: Weight control, Antioxidants, Moderate R-OH consumption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:factors that improve ldl to hdl ratio except::::', 'factors that improve ldl to hdl ratio except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Consuming higher amounts of saturated fatty acids raises both low-density lipoprotein (LDL) and high-density lipoprotein (HDL) cholesterol. However, it drives a much larger increase in LDL (\"bad\") cholesterol compared to HDL. This selectively worsens the overall LDL-to-HDL ratio, increasing cardiovascular risk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Higher intakes of saturated fatty acids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Consuming higher amounts of saturated fatty acids raises both low-density lipoprotein (LDL) and high-density lipoprotein (HDL) cholesterol. However, it drives a much larger increase in LDL (\"bad\") cholesterol compared to HDL. This selectively worsens the overall LDL-to-HDL ratio, increasing cardiovascular risk.\n\n• Moderate R-OH (Alcohol) Consumption: In medical terminology, \"R-OH\" stands for alcohol. Scientific literature consistently shows that light-to-moderate alcohol intake (such as one drink a day for women or two for men) can moderately elevate HDL cholesterol levels, which helps optimize the blood lipid ratio.\n• Antioxidants: Dietary antioxidants (found in abundance in colorful fruits, vegetables, and whole grains) shield circulating LDL particles from undergoing oxidative modification. Because oxidized LDL is what triggers plaque accumulation in artery walls, antioxidants maintain healthy vascular transport and protect the functional efficiency of lipid handling.\n• Weight Control: Dropping excess body weight and avoiding abdominal obesity are highly effective ways to manage dyslipidemia. Achieving a healthy weight directly reduces total triglycerides and lowers LDL cholesterol levels while boosting cardioprotective HDL.","whyWrongChoices":"Alternative options: Weight control, Antioxidants, Moderate R-OH consumption"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sources of trans fatty acid except::::sardines', 'sources of trans fatty acid except:', 'Sardines', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Trans fatty acids can occur naturally in small amounts in milk and butter because ruminant animals produce naturally occurring trans fats through microbial fermentation in the rumen. Trans fats can also be present in commercial baked products such as cookies, particularly when partially hydrogenated oils are used, although their use has been substantially reduced or eliminated in many countries.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sardines\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Trans fatty acids can occur naturally in small amounts in milk and butter because ruminant animals produce naturally occurring trans fats through microbial fermentation in the rumen. Trans fats can also be present in commercial baked products such as cookies, particularly when partially hydrogenated oils are used, although their use has been substantially reduced or eliminated in many countries.\n\nSardines, on the other hand, are oily fish and are primarily valued as sources of omega-3 polyunsaturated fatty acids, particularly EPA and DHA. Although naturally occurring trans fatty acids can be detected in various foods in very small amounts, sardines are not considered a meaningful dietary source of trans fat.","whyWrongChoices":"Alternative options: Cookies, Milk, Butter"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:sources of trans fatty acid except::::', 'sources of trans fatty acid except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Trans fatty acids can occur naturally in small amounts in milk and butter because ruminant animals produce naturally occurring trans fats through microbial fermentation in the rumen. Trans fats can also be present in commercial baked products such as cookies, particularly when partially hydrogenated oils are used, although their use has been substantially reduced or eliminated in many countries.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sardines\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Trans fatty acids can occur naturally in small amounts in milk and butter because ruminant animals produce naturally occurring trans fats through microbial fermentation in the rumen. Trans fats can also be present in commercial baked products such as cookies, particularly when partially hydrogenated oils are used, although their use has been substantially reduced or eliminated in many countries.\n\nSardines, on the other hand, are oily fish and are primarily valued as sources of omega-3 polyunsaturated fatty acids, particularly EPA and DHA. Although naturally occurring trans fatty acids can be detected in various foods in very small amounts, sardines are not considered a meaningful dietary source of trans fat.","whyWrongChoices":"Alternative options: Cookies, Milk, Butter"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the soul of every foodservice operation.:::menu', 'the soul of every foodservice operation.', 'Menu', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In foodservice management, the menu is universally referred to as the \"soul,\" focal point, or primary control of the entire operation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Menu\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In foodservice management, the menu is universally referred to as the \"soul,\" focal point, or primary control of the entire operation.\n\nIt dictates everything that happens in the facility—including purchasing, budget, required equipment, staff skill levels, kitchen layout, and guest satisfaction.","whyWrongChoices":"Alternative options: Dietitian, Meal Plan, Income generation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:allowed amount of purine in a purine-restricted diet::::150 mg', 'allowed amount of purine in a purine-restricted diet:', '150 mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A purine-restricted diet is designed to reduce dietary purine exposure in patients with gout, hyperuricemia, or uric acid–related conditions. Traditional diet manuals commonly identify foods containing 150 mg or more of purine per serving as foods to be restricted or avoided. Thus, 150 mg is an important threshold associated with purine-restricted diet teaching.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"150 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A purine-restricted diet is designed to reduce dietary purine exposure in patients with gout, hyperuricemia, or uric acid–related conditions. Traditional diet manuals commonly identify foods containing 150 mg or more of purine per serving as foods to be restricted or avoided. Thus, 150 mg is an important threshold associated with purine-restricted diet teaching.","whyWrongChoices":"Alternative options: 250 mg, 300 mg, 0 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:allowed amount of purine in a purine-restricted diet::::', 'allowed amount of purine in a purine-restricted diet:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A purine-restricted diet is designed to reduce dietary purine exposure in patients with gout, hyperuricemia, or uric acid–related conditions. Traditional diet manuals commonly identify foods containing 150 mg or more of purine per serving as foods to be restricted or avoided. Thus, 150 mg is an important threshold associated with purine-restricted diet teaching.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"150 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A purine-restricted diet is designed to reduce dietary purine exposure in patients with gout, hyperuricemia, or uric acid–related conditions. Traditional diet manuals commonly identify foods containing 150 mg or more of purine per serving as foods to be restricted or avoided. Thus, 150 mg is an important threshold associated with purine-restricted diet teaching.","whyWrongChoices":"Alternative options: 250 mg, 300 mg, 0 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamin e maintains prothrombin level in the blood plasma. vitamin k is an anticoagulant.:::both statements are incorrect.', 'vitamin e maintains prothrombin level in the blood plasma. vitamin k is an anticoagulant.', 'Both statements are incorrect.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement 1 is incorrect. Vitamin K, not vitamin E, is essential for the synthesis of several blood-clotting proteins, including prothrombin (factor II), in the liver. Vitamin K functions as a cofactor for the γ-carboxylation of specific glutamate residues on vitamin K–dependent clotting factors, allowing them to participate effectively in coagulation. Vitamin E, in contrast, is primarily recognized for its antioxidant function and does not maintain plasma prothrombin levels as its physiological role. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are incorrect.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement 1 is incorrect. Vitamin K, not vitamin E, is essential for the synthesis of several blood-clotting proteins, including prothrombin (factor II), in the liver. Vitamin K functions as a cofactor for the γ-carboxylation of specific glutamate residues on vitamin K–dependent clotting factors, allowing them to participate effectively in coagulation. Vitamin E, in contrast, is primarily recognized for its antioxidant function and does not maintain plasma prothrombin levels as its physiological role. \n\nStatement 2 is also incorrect. Vitamin K is not an anticoagulant; it supports normal blood coagulation. Vitamin K deficiency can impair clotting-factor activation and increase bleeding tendency. In fact, warfarin, an anticoagulant medication, works partly by inhibiting vitamin K recycling, thereby reducing the activity of vitamin K–dependent clotting factors.","whyWrongChoices":"Alternative options: Only statement 1 is correct., Only statement 2 is correct., Both statements are correct."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:vitamin e maintains prothrombin level in the blood plasma. vitamin k is an anticoagulant.:::', 'vitamin e maintains prothrombin level in the blood plasma. vitamin k is an anticoagulant.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement 1 is incorrect. Vitamin K, not vitamin E, is essential for the synthesis of several blood-clotting proteins, including prothrombin (factor II), in the liver. Vitamin K functions as a cofactor for the γ-carboxylation of specific glutamate residues on vitamin K–dependent clotting factors, allowing them to participate effectively in coagulation. Vitamin E, in contrast, is primarily recognized for its antioxidant function and does not maintain plasma prothrombin levels as its physiological role. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are incorrect.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement 1 is incorrect. Vitamin K, not vitamin E, is essential for the synthesis of several blood-clotting proteins, including prothrombin (factor II), in the liver. Vitamin K functions as a cofactor for the γ-carboxylation of specific glutamate residues on vitamin K–dependent clotting factors, allowing them to participate effectively in coagulation. Vitamin E, in contrast, is primarily recognized for its antioxidant function and does not maintain plasma prothrombin levels as its physiological role. \n\nStatement 2 is also incorrect. Vitamin K is not an anticoagulant; it supports normal blood coagulation. Vitamin K deficiency can impair clotting-factor activation and increase bleeding tendency. In fact, warfarin, an anticoagulant medication, works partly by inhibiting vitamin K recycling, thereby reducing the activity of vitamin K–dependent clotting factors.","whyWrongChoices":"Alternative options: Only statement 1 is correct., Only statement 2 is correct., Both statements are correct."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the soul of every foodservice operation.:::', 'the soul of every foodservice operation.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In foodservice management, the menu is universally referred to as the \"soul,\" focal point, or primary control of the entire operation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Menu\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In foodservice management, the menu is universally referred to as the \"soul,\" focal point, or primary control of the entire operation.\n\nIt dictates everything that happens in the facility—including purchasing, budget, required equipment, staff skill levels, kitchen layout, and guest satisfaction.","whyWrongChoices":"Alternative options: Dietitian, Meal Plan, Income generation"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a recommended dietary allowance (rda) represents the::::', 'a recommended dietary allowance (rda) represents the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Recommended Dietary Allowance (RDA) is the average daily nutrient intake level that is sufficient to meet the nutrient requirements of nearly all (97–98%) healthy individuals in a particular age, sex, and life-stage group. It is primarily used as a goal for planning nutritionally adequate diets for individuals. Importantly, the RDA is not literally enough for 100% of people, because individual nutrient requirements vary. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Average amount of a nutrient considered adequate to meet the nutrient needs of all healthy people\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Recommended Dietary Allowance (RDA) is the average daily nutrient intake level that is sufficient to meet the nutrient requirements of nearly all (97–98%) healthy individuals in a particular age, sex, and life-stage group. It is primarily used as a goal for planning nutritionally adequate diets for individuals. Importantly, the RDA is not literally enough for 100% of people, because individual nutrient requirements vary. \n\nThe RDA is derived from the Estimated Average Requirement (EAR). When the requirement distribution is approximately normal, the RDA is generally set at the EAR plus two standard deviations, thereby covering the requirements of approximately 97–98% of healthy individuals. In clinical and community nutrition practice, RDAs are useful for planning diets, while the EAR is generally more appropriate for assessing the adequacy of nutrient intakes in groups.","whyWrongChoices":"Alternative options: Highest amount of a nutrient that appears safe for most healthy people, Average amount of a nutrient that will maintain a specific biochemical or physiological function in half of the population, Lowest amount of a nutrient considered adequate to meet the nutrient needs of all healthy people"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the enzyme sucrase acts on sucrose to produce::::glucose and fructose', 'the enzyme sucrase acts on sucrose to produce:', 'Glucose and fructose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sucrose is a disaccharide composed of one molecule of glucose and one molecule of fructose. The brush-border enzyme sucrase hydrolyzes the glycosidic bond in sucrose, releasing glucose and fructose as the final monosaccharide products. These monosaccharides can then be absorbed by the small intestine through specific transport mechanisms. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose and fructose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sucrose is a disaccharide composed of one molecule of glucose and one molecule of fructose. The brush-border enzyme sucrase hydrolyzes the glycosidic bond in sucrose, releasing glucose and fructose as the final monosaccharide products. These monosaccharides can then be absorbed by the small intestine through specific transport mechanisms. \n\nSucrase is part of the intestinal sucrase-isomaltase complex located on the brush border of enterocytes. The resulting glucose and fructose are absorbed primarily in the small intestine and enter the portal circulation, with glucose and fructose using different transport proteins. This illustrates the importance of brush-border enzymes in completing carbohydrate digestion before absorption.","whyWrongChoices":"Alternative options: Glucose and galactose, Glucose, Maltose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the enzyme sucrase acts on sucrose to produce::::', 'the enzyme sucrase acts on sucrose to produce:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sucrose is a disaccharide composed of one molecule of glucose and one molecule of fructose. The brush-border enzyme sucrase hydrolyzes the glycosidic bond in sucrose, releasing glucose and fructose as the final monosaccharide products. These monosaccharides can then be absorbed by the small intestine through specific transport mechanisms. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose and fructose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sucrose is a disaccharide composed of one molecule of glucose and one molecule of fructose. The brush-border enzyme sucrase hydrolyzes the glycosidic bond in sucrose, releasing glucose and fructose as the final monosaccharide products. These monosaccharides can then be absorbed by the small intestine through specific transport mechanisms. \n\nSucrase is part of the intestinal sucrase-isomaltase complex located on the brush border of enterocytes. The resulting glucose and fructose are absorbed primarily in the small intestine and enter the portal circulation, with glucose and fructose using different transport proteins. This illustrates the importance of brush-border enzymes in completing carbohydrate digestion before absorption.","whyWrongChoices":"Alternative options: Glucose and galactose, Glucose, Maltose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the enzyme pepsin is not denatured in the stomach despite the very acidic environment due to hydrochloric acid (hcl). how can this be?:::pepsin is secreted in its precursor form, pepsinogen', 'the enzyme pepsin is not denatured in the stomach despite the very acidic environment due to hydrochloric acid (hcl). how can this be?', 'Pepsin is secreted in its precursor form, pepsinogen', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The stomach avoids auto-digestion and protects its own mucosal lining from premature proteolysis (protein breakdown) by not secreting active pepsin directly. Instead, gastric chief cells synthesize and secrete pepsinogen, which is an inactive precursor or zymogen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pepsin is secreted in its precursor form, pepsinogen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The stomach avoids auto-digestion and protects its own mucosal lining from premature proteolysis (protein breakdown) by not secreting active pepsin directly. Instead, gastric chief cells synthesize and secrete pepsinogen, which is an inactive precursor or zymogen.\n\nOnce pepsinogen enters the gastric lumen, the strongly acidic environment created by hydrochloric acid (HCl) causes the protein chain to unfold. This allows pepsinogen to cleave itself, initiating its conversion into the active, functional enzyme pepsin precisely where it is needed to digest dietary proteins.","whyWrongChoices":"Alternative options: Pepsin is the only protein enzyme that functions best in an acidic environment, Pepsin is able to resist denaturation by increasing the pH within the stomach, making it less acidic, Pepsin is also digested along with other proteins in the stomach"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the enzyme pepsin is not denatured in the stomach despite the very acidic environment due to hydrochloric acid (hcl). how can this be?:::', 'the enzyme pepsin is not denatured in the stomach despite the very acidic environment due to hydrochloric acid (hcl). how can this be?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The stomach avoids auto-digestion and protects its own mucosal lining from premature proteolysis (protein breakdown) by not secreting active pepsin directly. Instead, gastric chief cells synthesize and secrete pepsinogen, which is an inactive precursor or zymogen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pepsin is secreted in its precursor form, pepsinogen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The stomach avoids auto-digestion and protects its own mucosal lining from premature proteolysis (protein breakdown) by not secreting active pepsin directly. Instead, gastric chief cells synthesize and secrete pepsinogen, which is an inactive precursor or zymogen.\n\nOnce pepsinogen enters the gastric lumen, the strongly acidic environment created by hydrochloric acid (HCl) causes the protein chain to unfold. This allows pepsinogen to cleave itself, initiating its conversion into the active, functional enzyme pepsin precisely where it is needed to digest dietary proteins.","whyWrongChoices":"Alternative options: Pepsin is the only protein enzyme that functions best in an acidic environment, Pepsin is able to resist denaturation by increasing the pH within the stomach, making it less acidic, Pepsin is also digested along with other proteins in the stomach"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrients that leave the git via the lymphatic system::::fats and fat-soluble vitamins', 'nutrients that leave the git via the lymphatic system:', 'Fats and fat-soluble vitamins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During digestion in the small intestine, long-chain fatty acids and fat-soluble vitamins (Vitamins A, D, E, and K) are packed into spherical lipid clusters called micelles. Once absorbed into the intestinal lining cells (enterocytes), they are re-assembled into even larger lipoprotein spheres called chylomicrogens. Because these structures are too bulky to fit through the tiny pores (fenestrations) of standard blood capillaries, they cannot enter the bloodstream directly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fats and fat-soluble vitamins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During digestion in the small intestine, long-chain fatty acids and fat-soluble vitamins (Vitamins A, D, E, and K) are packed into spherical lipid clusters called micelles. Once absorbed into the intestinal lining cells (enterocytes), they are re-assembled into even larger lipoprotein spheres called chylomicrogens. Because these structures are too bulky to fit through the tiny pores (fenestrations) of standard blood capillaries, they cannot enter the bloodstream directly.\n\nInstead, these large lipid packages slip into lacteals—specialized, wide-pored lymphatic capillaries located at the center of each intestinal villus. The fluid (called chyle) travels slowly through the lymphatic system, completely bypassing the liver at first, before emptying directly into the main bloodstream via the thoracic duct near the heart.\n\n• Water, Proteins, Minerals, and Water-Soluble Vitamins: These nutrients are water-soluble and split into small, single molecules (like glucose, amino acids, and free ions). Because they are small enough to pass easily through the pores of regular capillaries, they exit the GI tract straight into the portal blood circulation, traveling directly to the liver for immediate processing.","whyWrongChoices":"Alternative options: Proteins and minerals, Water and minerals, All vitamins and minerals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nutrients that leave the git via the lymphatic system::::', 'nutrients that leave the git via the lymphatic system:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During digestion in the small intestine, long-chain fatty acids and fat-soluble vitamins (Vitamins A, D, E, and K) are packed into spherical lipid clusters called micelles. Once absorbed into the intestinal lining cells (enterocytes), they are re-assembled into even larger lipoprotein spheres called chylomicrogens. Because these structures are too bulky to fit through the tiny pores (fenestrations) of standard blood capillaries, they cannot enter the bloodstream directly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fats and fat-soluble vitamins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During digestion in the small intestine, long-chain fatty acids and fat-soluble vitamins (Vitamins A, D, E, and K) are packed into spherical lipid clusters called micelles. Once absorbed into the intestinal lining cells (enterocytes), they are re-assembled into even larger lipoprotein spheres called chylomicrogens. Because these structures are too bulky to fit through the tiny pores (fenestrations) of standard blood capillaries, they cannot enter the bloodstream directly.\n\nInstead, these large lipid packages slip into lacteals—specialized, wide-pored lymphatic capillaries located at the center of each intestinal villus. The fluid (called chyle) travels slowly through the lymphatic system, completely bypassing the liver at first, before emptying directly into the main bloodstream via the thoracic duct near the heart.\n\n• Water, Proteins, Minerals, and Water-Soluble Vitamins: These nutrients are water-soluble and split into small, single molecules (like glucose, amino acids, and free ions). Because they are small enough to pass easily through the pores of regular capillaries, they exit the GI tract straight into the portal blood circulation, traveling directly to the liver for immediate processing.","whyWrongChoices":"Alternative options: Proteins and minerals, Water and minerals, All vitamins and minerals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in conditions characterized by hypochlorhydria or achlorhydria, a suitable diet is one that is::::easy to digest or consists of predigested protein like protein hydrolysates', 'in conditions characterized by hypochlorhydria or achlorhydria, a suitable diet is one that is:', 'easy to digest or consists of predigested protein like protein hydrolysates', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hypochlorhydria refers to reduced gastric acid secretion, while achlorhydria refers to an absence or near-absence of hydrochloric acid (HCl) in the stomach. Gastric acid contributes to the denaturation of dietary proteins and facilitates the conversion of pepsinogen to pepsin, which begins protein digestion in the stomach. When gastric acid is markedly reduced or absent, protein digestion in the stomach may be impaired. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"easy to digest or consists of predigested protein like protein hydrolysates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hypochlorhydria refers to reduced gastric acid secretion, while achlorhydria refers to an absence or near-absence of hydrochloric acid (HCl) in the stomach. Gastric acid contributes to the denaturation of dietary proteins and facilitates the conversion of pepsinogen to pepsin, which begins protein digestion in the stomach. When gastric acid is markedly reduced or absent, protein digestion in the stomach may be impaired. \n\nTherefore, traditionally, a diet emphasizing easily digested foods and, when clinically indicated, predigested protein such as protein hydrolysates may be recommended. However, the important modern clinical point is that hypochlorhydria or achlorhydria does not automatically require a low-protein diet or routine use of protein hydrolysates. Protein digestion continues in the small intestine through pancreatic and brush-border enzymes. Management should focus on the underlying cause and the patient''s nutritional status.","whyWrongChoices":"Alternative options: low in fiber, low in protein, acid-ash"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:in conditions characterized by hypochlorhydria or achlorhydria, a suitable diet is one that is::::', 'in conditions characterized by hypochlorhydria or achlorhydria, a suitable diet is one that is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hypochlorhydria refers to reduced gastric acid secretion, while achlorhydria refers to an absence or near-absence of hydrochloric acid (HCl) in the stomach. Gastric acid contributes to the denaturation of dietary proteins and facilitates the conversion of pepsinogen to pepsin, which begins protein digestion in the stomach. When gastric acid is markedly reduced or absent, protein digestion in the stomach may be impaired. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"easy to digest or consists of predigested protein like protein hydrolysates\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hypochlorhydria refers to reduced gastric acid secretion, while achlorhydria refers to an absence or near-absence of hydrochloric acid (HCl) in the stomach. Gastric acid contributes to the denaturation of dietary proteins and facilitates the conversion of pepsinogen to pepsin, which begins protein digestion in the stomach. When gastric acid is markedly reduced or absent, protein digestion in the stomach may be impaired. \n\nTherefore, traditionally, a diet emphasizing easily digested foods and, when clinically indicated, predigested protein such as protein hydrolysates may be recommended. However, the important modern clinical point is that hypochlorhydria or achlorhydria does not automatically require a low-protein diet or routine use of protein hydrolysates. Protein digestion continues in the small intestine through pancreatic and brush-border enzymes. Management should focus on the underlying cause and the patient''s nutritional status.","whyWrongChoices":"Alternative options: low in fiber, low in protein, acid-ash"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
