INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a deficiency of udp-glucose:galactose-1-phosphate uridylyltransferase (galt) will lead to an accumulation of::::galactose', 'a deficiency of udp-glucose:galactose-1-phosphate uridylyltransferase (galt) will lead to an accumulation of:', 'Galactose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"UDP-glucose:galactose-1-phosphate uridylyltransferase (GALT) is a key enzyme in the Leloir pathway, which metabolizes galactose into glucose-derived metabolites. GALT normally converts galactose-1-phosphate + UDP-glucose → UDP-galactose + glucose-1-phosphate. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galactose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"UDP-glucose:galactose-1-phosphate uridylyltransferase (GALT) is a key enzyme in the Leloir pathway, which metabolizes galactose into glucose-derived metabolites. GALT normally converts galactose-1-phosphate + UDP-glucose → UDP-galactose + glucose-1-phosphate. \n\nWhen GALT is deficient, as occurs in classic galactosemia, galactose-1-phosphate accumulates in tissues, while galactose is also elevated in the blood. Some excess galactose is converted to galactitol, which contributes to complications such as cataracts.","whyWrongChoices":"Alternative options: Glucose, Glycogen, UDP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a deficiency of udp-glucose:galactose-1-phosphate uridylyltransferase (galt) will lead to an accumulation of::::', 'a deficiency of udp-glucose:galactose-1-phosphate uridylyltransferase (galt) will lead to an accumulation of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"UDP-glucose:galactose-1-phosphate uridylyltransferase (GALT) is a key enzyme in the Leloir pathway, which metabolizes galactose into glucose-derived metabolites. GALT normally converts galactose-1-phosphate + UDP-glucose → UDP-galactose + glucose-1-phosphate. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galactose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"UDP-glucose:galactose-1-phosphate uridylyltransferase (GALT) is a key enzyme in the Leloir pathway, which metabolizes galactose into glucose-derived metabolites. GALT normally converts galactose-1-phosphate + UDP-glucose → UDP-galactose + glucose-1-phosphate. \n\nWhen GALT is deficient, as occurs in classic galactosemia, galactose-1-phosphate accumulates in tissues, while galactose is also elevated in the blood. Some excess galactose is converted to galactitol, which contributes to complications such as cataracts.","whyWrongChoices":"Alternative options: Glucose, Glycogen, UDP"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is not one of the five classical french mother sauces?:::marinara', 'which of the following is not one of the five classical french mother sauces?', 'Marinara', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The five classical French mother sauces codified by chef Auguste Escoffier:Bechamel, Veloute, Espagnole, Tomato, Hollandaise","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Marinara\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The five classical French mother sauces codified by chef Auguste Escoffier:Bechamel, Veloute, Espagnole, Tomato, Hollandaise\n\nThese foundational recipes use a liquid combined with a thickening agent (like a roux or emulsion) to create dozens of secondary \"daughter\" sauces.","whyWrongChoices":"Alternative options: Hollandaise, Velouté, Béchamel"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to increase appetite, which of the following is/are recommended? i. relaxed eating ii. small frequent feedings iii. eating favorite food:::all of the above', 'to increase appetite, which of the following is/are recommended? i. relaxed eating ii. small frequent feedings iii. eating favorite food', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three strategies can help improve appetite and food intake, particularly in patients experiencing poor appetite. Relaxed eating can make meals more pleasant and reduce anxiety or stress associated with eating. Creating an appealing mealtime environment and avoiding pressure to eat may encourage intake. Small, frequent meals are useful because a large meal may be overwhelming for someone with a poor appetite; smaller portions are often better tolerated and can help increase total daily intake. Offering favorite or preferred foods is another practical strategy because food preference and palatability strongly influence willingness to eat. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three strategies can help improve appetite and food intake, particularly in patients experiencing poor appetite. Relaxed eating can make meals more pleasant and reduce anxiety or stress associated with eating. Creating an appealing mealtime environment and avoiding pressure to eat may encourage intake. Small, frequent meals are useful because a large meal may be overwhelming for someone with a poor appetite; smaller portions are often better tolerated and can help increase total daily intake. Offering favorite or preferred foods is another practical strategy because food preference and palatability strongly influence willingness to eat. \n\nIn clinical nutrition, these approaches are commonly incorporated into individualized nutrition care, especially when the immediate goal is to increase energy and nutrient intake. However, favorite foods should still be selected with consideration for the patient''s medical condition and dietary requirements.","whyWrongChoices":"Alternative options: II only, II and III only, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:to increase appetite, which of the following is/are recommended? i. relaxed eating ii. small frequent feedings iii. eating favorite food:::', 'to increase appetite, which of the following is/are recommended? i. relaxed eating ii. small frequent feedings iii. eating favorite food', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All three strategies can help improve appetite and food intake, particularly in patients experiencing poor appetite. Relaxed eating can make meals more pleasant and reduce anxiety or stress associated with eating. Creating an appealing mealtime environment and avoiding pressure to eat may encourage intake. Small, frequent meals are useful because a large meal may be overwhelming for someone with a poor appetite; smaller portions are often better tolerated and can help increase total daily intake. Offering favorite or preferred foods is another practical strategy because food preference and palatability strongly influence willingness to eat. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All three strategies can help improve appetite and food intake, particularly in patients experiencing poor appetite. Relaxed eating can make meals more pleasant and reduce anxiety or stress associated with eating. Creating an appealing mealtime environment and avoiding pressure to eat may encourage intake. Small, frequent meals are useful because a large meal may be overwhelming for someone with a poor appetite; smaller portions are often better tolerated and can help increase total daily intake. Offering favorite or preferred foods is another practical strategy because food preference and palatability strongly influence willingness to eat. \n\nIn clinical nutrition, these approaches are commonly incorporated into individualized nutrition care, especially when the immediate goal is to increase energy and nutrient intake. However, favorite foods should still be selected with consideration for the patient''s medical condition and dietary requirements.","whyWrongChoices":"Alternative options: II only, II and III only, None of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foot care is an important aspect of diabetes education of patients to avoid::::wounds on the feet which may become gangrenous', 'foot care is an important aspect of diabetes education of patients to avoid:', 'wounds on the feet which may become gangrenous', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Proper diabetic foot care is essential because diabetes can cause peripheral neuropathy and peripheral arterial disease, both of which increase the risk of foot injury and delayed wound healing. Neuropathy may reduce protective sensation, so a patient may not notice a blister, cut, burn, pressure injury, or poorly fitting footwear. Reduced blood flow can further impair tissue healing and increase the risk of infection. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"wounds on the feet which may become gangrenous\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Proper diabetic foot care is essential because diabetes can cause peripheral neuropathy and peripheral arterial disease, both of which increase the risk of foot injury and delayed wound healing. Neuropathy may reduce protective sensation, so a patient may not notice a blister, cut, burn, pressure injury, or poorly fitting footwear. Reduced blood flow can further impair tissue healing and increase the risk of infection. \n\nRegular foot inspection, appropriate footwear, foot hygiene, and prompt attention to injuries help prevent minor problems from progressing to serious ulcers and, in severe cases, gangrene and amputation.","whyWrongChoices":"Alternative options: microvascular complications, edema of the lower extremities, numbness of the lower extremities"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:foot care is an important aspect of diabetes education of patients to avoid::::', 'foot care is an important aspect of diabetes education of patients to avoid:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Proper diabetic foot care is essential because diabetes can cause peripheral neuropathy and peripheral arterial disease, both of which increase the risk of foot injury and delayed wound healing. Neuropathy may reduce protective sensation, so a patient may not notice a blister, cut, burn, pressure injury, or poorly fitting footwear. Reduced blood flow can further impair tissue healing and increase the risk of infection. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"wounds on the feet which may become gangrenous\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Proper diabetic foot care is essential because diabetes can cause peripheral neuropathy and peripheral arterial disease, both of which increase the risk of foot injury and delayed wound healing. Neuropathy may reduce protective sensation, so a patient may not notice a blister, cut, burn, pressure injury, or poorly fitting footwear. Reduced blood flow can further impair tissue healing and increase the risk of infection. \n\nRegular foot inspection, appropriate footwear, foot hygiene, and prompt attention to injuries help prevent minor problems from progressing to serious ulcers and, in severe cases, gangrene and amputation.","whyWrongChoices":"Alternative options: microvascular complications, edema of the lower extremities, numbness of the lower extremities"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:if a person wants to improve his/her fiber intake, which of the following food would be best?:::saluyot', 'if a person wants to improve his/her fiber intake, which of the following food would be best?', 'Saluyot', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Saluyot (jute leaves) is the best choice among the options because leafy vegetables such as saluyot provide a relatively high amount of dietary fiber compared with the other vegetables listed. Saluyot is also a good source of several micronutrients and is commonly consumed as a vegetable in the Philippines. Increasing intake of fiber-rich vegetables can contribute to improved bowel function and overall diet quality. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Saluyot\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Saluyot (jute leaves) is the best choice among the options because leafy vegetables such as saluyot provide a relatively high amount of dietary fiber compared with the other vegetables listed. Saluyot is also a good source of several micronutrients and is commonly consumed as a vegetable in the Philippines. Increasing intake of fiber-rich vegetables can contribute to improved bowel function and overall diet quality. \n\nRadish, cucumber, and tomato also contain dietary fiber, but their fiber contribution per comparable edible portion is generally lower than that of saluyot. For practical nutrition counseling, however, the overall dietary pattern matters: a person should obtain fiber from a variety of vegetables, fruits, whole grains, legumes, nuts, and seeds, rather than relying on one food alone.","whyWrongChoices":"Alternative options: Radish, Cucumber, Tomato"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:if a person wants to improve his/her fiber intake, which of the following food would be best?:::', 'if a person wants to improve his/her fiber intake, which of the following food would be best?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Saluyot (jute leaves) is the best choice among the options because leafy vegetables such as saluyot provide a relatively high amount of dietary fiber compared with the other vegetables listed. Saluyot is also a good source of several micronutrients and is commonly consumed as a vegetable in the Philippines. Increasing intake of fiber-rich vegetables can contribute to improved bowel function and overall diet quality. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Saluyot\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Saluyot (jute leaves) is the best choice among the options because leafy vegetables such as saluyot provide a relatively high amount of dietary fiber compared with the other vegetables listed. Saluyot is also a good source of several micronutrients and is commonly consumed as a vegetable in the Philippines. Increasing intake of fiber-rich vegetables can contribute to improved bowel function and overall diet quality. \n\nRadish, cucumber, and tomato also contain dietary fiber, but their fiber contribution per comparable edible portion is generally lower than that of saluyot. For practical nutrition counseling, however, the overall dietary pattern matters: a person should obtain fiber from a variety of vegetables, fruits, whole grains, legumes, nuts, and seeds, rather than relying on one food alone.","whyWrongChoices":"Alternative options: Radish, Cucumber, Tomato"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:some clinicians recommend egg whites as the sole source of protein for patients with renal failure because::::egg white protein has the highest biological value', 'some clinicians recommend egg whites as the sole source of protein for patients with renal failure because:', 'egg white protein has the highest biological value', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Egg white is considered a high-quality protein because it contains all the essential amino acids in proportions that support human protein needs and has high protein quality. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"egg white protein has the highest biological value\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Egg white is considered a high-quality protein because it contains all the essential amino acids in proportions that support human protein needs and has high protein quality. \n\nIn patients with chronic kidney disease (CKD), when protein intake is restricted or carefully prescribed, choosing high-quality protein sources can help provide adequate essential amino acids while limiting the total amount of protein consumed. Egg white is also relatively low in phosphorus compared with the whole egg because most of the egg''s phosphorus is found in the yolk. \n\nHowever, egg whites should not routinely be considered the sole protein source for every patient with renal failure. Current CKD nutrition care emphasizes individualized protein and energy prescriptions according to CKD stage, dialysis status, nutritional status, and other clinical factors. Patients receiving dialysis generally have higher protein requirements than patients with non-dialysis CKD. The key concept tested here is high protein quality/biological value, not a therapeutic effect unique to egg white.","whyWrongChoices":"Alternative options: egg whites are the most acceptable protein source, they have a therapeutic effect, other proteins are harmful"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:some clinicians recommend egg whites as the sole source of protein for patients with renal failure because::::', 'some clinicians recommend egg whites as the sole source of protein for patients with renal failure because:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Egg white is considered a high-quality protein because it contains all the essential amino acids in proportions that support human protein needs and has high protein quality. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"egg white protein has the highest biological value\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Egg white is considered a high-quality protein because it contains all the essential amino acids in proportions that support human protein needs and has high protein quality. \n\nIn patients with chronic kidney disease (CKD), when protein intake is restricted or carefully prescribed, choosing high-quality protein sources can help provide adequate essential amino acids while limiting the total amount of protein consumed. Egg white is also relatively low in phosphorus compared with the whole egg because most of the egg''s phosphorus is found in the yolk. \n\nHowever, egg whites should not routinely be considered the sole protein source for every patient with renal failure. Current CKD nutrition care emphasizes individualized protein and energy prescriptions according to CKD stage, dialysis status, nutritional status, and other clinical factors. Patients receiving dialysis generally have higher protein requirements than patients with non-dialysis CKD. The key concept tested here is high protein quality/biological value, not a therapeutic effect unique to egg white.","whyWrongChoices":"Alternative options: egg whites are the most acceptable protein source, they have a therapeutic effect, other proteins are harmful"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a morbidly obese patient underwent gastric bypass. what classical side effect can the patient experience as a result of the surgery?:::dumping syndrome', 'a morbidly obese patient underwent gastric bypass. what classical side effect can the patient experience as a result of the surgery?', 'Dumping syndrome', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dumping syndrome is a classic complication of gastric bypass surgery. Because the stomach''s normal reservoir function is altered and food can pass relatively rapidly into the small intestine, particularly after meals high in simple carbohydrates, patients may experience rapid gastric emptying. This can produce early symptoms such as abdominal cramping, bloating, nausea, diarrhea, dizziness, flushing, and tachycardia shortly after eating. The rapid delivery of carbohydrate can also cause a subsequent exaggerated insulin response. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dumping syndrome\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dumping syndrome is a classic complication of gastric bypass surgery. Because the stomach''s normal reservoir function is altered and food can pass relatively rapidly into the small intestine, particularly after meals high in simple carbohydrates, patients may experience rapid gastric emptying. This can produce early symptoms such as abdominal cramping, bloating, nausea, diarrhea, dizziness, flushing, and tachycardia shortly after eating. The rapid delivery of carbohydrate can also cause a subsequent exaggerated insulin response. \n\nDumping syndrome may also have a late phase, typically occurring 1–3 hours after eating, characterized by symptoms of hypoglycemia such as weakness, sweating, tremors, palpitations, and confusion. Dietary management commonly includes small, frequent meals; limiting rapidly absorbed carbohydrates; emphasizing protein and complex carbohydrates; and separating fluids from meals when appropriate. Although nutritional deficiencies and undernutrition can also occur after bariatric surgery, dumping syndrome is the classical side effect specifically associated with altered gastric anatomy and rapid gastric emptying.","whyWrongChoices":"Alternative options: Undernutrition, Gastrostomy, GERD"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a morbidly obese patient underwent gastric bypass. what classical side effect can the patient experience as a result of the surgery?:::', 'a morbidly obese patient underwent gastric bypass. what classical side effect can the patient experience as a result of the surgery?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dumping syndrome is a classic complication of gastric bypass surgery. Because the stomach''s normal reservoir function is altered and food can pass relatively rapidly into the small intestine, particularly after meals high in simple carbohydrates, patients may experience rapid gastric emptying. This can produce early symptoms such as abdominal cramping, bloating, nausea, diarrhea, dizziness, flushing, and tachycardia shortly after eating. The rapid delivery of carbohydrate can also cause a subsequent exaggerated insulin response. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dumping syndrome\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dumping syndrome is a classic complication of gastric bypass surgery. Because the stomach''s normal reservoir function is altered and food can pass relatively rapidly into the small intestine, particularly after meals high in simple carbohydrates, patients may experience rapid gastric emptying. This can produce early symptoms such as abdominal cramping, bloating, nausea, diarrhea, dizziness, flushing, and tachycardia shortly after eating. The rapid delivery of carbohydrate can also cause a subsequent exaggerated insulin response. \n\nDumping syndrome may also have a late phase, typically occurring 1–3 hours after eating, characterized by symptoms of hypoglycemia such as weakness, sweating, tremors, palpitations, and confusion. Dietary management commonly includes small, frequent meals; limiting rapidly absorbed carbohydrates; emphasizing protein and complex carbohydrates; and separating fluids from meals when appropriate. Although nutritional deficiencies and undernutrition can also occur after bariatric surgery, dumping syndrome is the classical side effect specifically associated with altered gastric anatomy and rapid gastric emptying.","whyWrongChoices":"Alternative options: Undernutrition, Gastrostomy, GERD"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lactose intolerance is due to::::lactase deficiency', 'lactose intolerance is due to:', 'lactase deficiency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lactose intolerance occurs when there is insufficient lactase, the brush-border enzyme responsible for breaking down lactose into its absorbable monosaccharides, glucose and galactose. When lactose is not adequately digested in the small intestine, it reaches the colon, where gut bacteria ferment it and produce gases and other metabolites. The resulting osmotic effect and fermentation can cause bloating, abdominal pain, flatulence, and diarrhea after consuming lactose-containing foods.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"lactase deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lactose intolerance occurs when there is insufficient lactase, the brush-border enzyme responsible for breaking down lactose into its absorbable monosaccharides, glucose and galactose. When lactose is not adequately digested in the small intestine, it reaches the colon, where gut bacteria ferment it and produce gases and other metabolites. The resulting osmotic effect and fermentation can cause bloating, abdominal pain, flatulence, and diarrhea after consuming lactose-containing foods.","whyWrongChoices":"Alternative options: inflammation of gastric mucosa, milk allergy, Hyperacidity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lactose intolerance is due to::::', 'lactose intolerance is due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lactose intolerance occurs when there is insufficient lactase, the brush-border enzyme responsible for breaking down lactose into its absorbable monosaccharides, glucose and galactose. When lactose is not adequately digested in the small intestine, it reaches the colon, where gut bacteria ferment it and produce gases and other metabolites. The resulting osmotic effect and fermentation can cause bloating, abdominal pain, flatulence, and diarrhea after consuming lactose-containing foods.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"lactase deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lactose intolerance occurs when there is insufficient lactase, the brush-border enzyme responsible for breaking down lactose into its absorbable monosaccharides, glucose and galactose. When lactose is not adequately digested in the small intestine, it reaches the colon, where gut bacteria ferment it and produce gases and other metabolites. The resulting osmotic effect and fermentation can cause bloating, abdominal pain, flatulence, and diarrhea after consuming lactose-containing foods.","whyWrongChoices":"Alternative options: inflammation of gastric mucosa, milk allergy, Hyperacidity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:osmolality of body fluids.:::290 mosm/kg', 'osmolality of body fluids.', '290 mOsm/kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Osmolality is the concentration of osmotically active particles per kilogram of solvent (water) and is expressed as milliosmoles per kilogram (mOsm/kg). It reflects the body''s water balance and is tightly regulated to maintain normal cellular function. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"290 mOsm/kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Osmolality is the concentration of osmotically active particles per kilogram of solvent (water) and is expressed as milliosmoles per kilogram (mOsm/kg). It reflects the body''s water balance and is tightly regulated to maintain normal cellular function. \n\nThe normal plasma osmolality is approximately: \n• 275–295 mOsm/kg, with an average value of 290 mOsm/kg","whyWrongChoices":"Alternative options: 400 mOsm/kg, 480 mOsm/kg, 200 mOsm/kg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food to emphasize when it is necessary to increase potassium::::fruits', 'food to emphasize when it is necessary to increase potassium:', 'Fruits', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fruits are generally good sources of potassium and are commonly emphasized when increasing dietary potassium. Examples include banana, oranges, melon, papaya, avocado, and dried fruits. Potassium is an important intracellular electrolyte involved in nerve transmission, muscle contraction, and maintenance of normal cardiac function. However, potassium intake should be individualized because patients with chronic kidney disease, hyperkalemia, or certain medications may instead require potassium restriction. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fruits\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fruits are generally good sources of potassium and are commonly emphasized when increasing dietary potassium. Examples include banana, oranges, melon, papaya, avocado, and dried fruits. Potassium is an important intracellular electrolyte involved in nerve transmission, muscle contraction, and maintenance of normal cardiac function. However, potassium intake should be individualized because patients with chronic kidney disease, hyperkalemia, or certain medications may instead require potassium restriction. \n\nStarchy roots such as potatoes and sweet potatoes can also provide substantial potassium, so they are not inherently poor choices. However, among the options, fruits are the most appropriate general food group to emphasize when the goal is to increase potassium intake.","whyWrongChoices":"Alternative options: Cream, starchy roots, cereals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:food to emphasize when it is necessary to increase potassium::::', 'food to emphasize when it is necessary to increase potassium:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fruits are generally good sources of potassium and are commonly emphasized when increasing dietary potassium. Examples include banana, oranges, melon, papaya, avocado, and dried fruits. Potassium is an important intracellular electrolyte involved in nerve transmission, muscle contraction, and maintenance of normal cardiac function. However, potassium intake should be individualized because patients with chronic kidney disease, hyperkalemia, or certain medications may instead require potassium restriction. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fruits\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fruits are generally good sources of potassium and are commonly emphasized when increasing dietary potassium. Examples include banana, oranges, melon, papaya, avocado, and dried fruits. Potassium is an important intracellular electrolyte involved in nerve transmission, muscle contraction, and maintenance of normal cardiac function. However, potassium intake should be individualized because patients with chronic kidney disease, hyperkalemia, or certain medications may instead require potassium restriction. \n\nStarchy roots such as potatoes and sweet potatoes can also provide substantial potassium, so they are not inherently poor choices. However, among the options, fruits are the most appropriate general food group to emphasize when the goal is to increase potassium intake.","whyWrongChoices":"Alternative options: Cream, starchy roots, cereals"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the c p f and kcal value of a breakfast containing 2 rice b exchanges, 2 medium fat exchanges, and 1 fruit exchange.:::c 56g p 20 g f 12 g e 412 kcal', 'the c p f and kcal value of a breakfast containing 2 rice b exchanges, 2 medium fat exchanges, and 1 fruit exchange.', 'C 56g P 20 g F 12 g E 412 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Using the Philippine Food Exchange List (FEL), here is the exact step-by-step breakdown of the computation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"C 56g P 20 g F 12 g E 412 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Using the Philippine Food Exchange List (FEL), here is the exact step-by-step breakdown of the computation.\n\n1. Rice B (2 exchanges):\n\t• Carbohydrates: 2 x 23g = 46g\n\t• Protein: 2 x 2g = 4g\n\t• Fat: 0g\n\t• Calories: 2 x 100 kcal = 200 kcal\n\n2. Medium-Fat Meat (2 exchanges):\n\t• Carbohydrates: 0g\n\t• Protein: 2 x 8g = 16g\n\t• Fat: 2 x 6g = 12g\n\t• Calories: 2 x 86 kcal = 172 kcal\n\n3. Fruit (1 exchange):\n\t• Carbohydrates: 1 x 10g = 10g\n\t• Protein: 0g\n\t• Fat: 0g\n\t• Calories: 1 x 40 kcal = 40 kcal\n\nGrand Totals:\n\t• Carbohydrates: 46g + 0g + 10g = 56 grams\n\t• Protein: 4g + 16g + 0g = 20 grams\n\t• Fat: 0g + 12g + 0g = 12 grams\n\t• Energy: 200 + 172 + 40 = 412 kcal\n\nVerifying the Math with Atwater Multipliers:\n• Carbohydrates: 56g x 4 kcal/g = 224 kcal\n• Protein: 20g x 4 kcal/g = 80 kcal\n• Fat: 12g x 9 kcal/g = 108 kcal\n• Total Energy: 224 + 80 + 108 = 412 kcal","whyWrongChoices":"Alternative options: C 46 g P 16 g F 10g E 338 kcal, C 56 g P 16 g F 6 g E 342 kcal, C 46 g P 20 g F 10 g E 354 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the c p f and kcal value of a breakfast containing 2 rice b exchanges, 2 medium fat exchanges, and 1 fruit exchange.:::', 'the c p f and kcal value of a breakfast containing 2 rice b exchanges, 2 medium fat exchanges, and 1 fruit exchange.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Using the Philippine Food Exchange List (FEL), here is the exact step-by-step breakdown of the computation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"C 56g P 20 g F 12 g E 412 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Using the Philippine Food Exchange List (FEL), here is the exact step-by-step breakdown of the computation.\n\n1. Rice B (2 exchanges):\n\t• Carbohydrates: 2 x 23g = 46g\n\t• Protein: 2 x 2g = 4g\n\t• Fat: 0g\n\t• Calories: 2 x 100 kcal = 200 kcal\n\n2. Medium-Fat Meat (2 exchanges):\n\t• Carbohydrates: 0g\n\t• Protein: 2 x 8g = 16g\n\t• Fat: 2 x 6g = 12g\n\t• Calories: 2 x 86 kcal = 172 kcal\n\n3. Fruit (1 exchange):\n\t• Carbohydrates: 1 x 10g = 10g\n\t• Protein: 0g\n\t• Fat: 0g\n\t• Calories: 1 x 40 kcal = 40 kcal\n\nGrand Totals:\n\t• Carbohydrates: 46g + 0g + 10g = 56 grams\n\t• Protein: 4g + 16g + 0g = 20 grams\n\t• Fat: 0g + 12g + 0g = 12 grams\n\t• Energy: 200 + 172 + 40 = 412 kcal\n\nVerifying the Math with Atwater Multipliers:\n• Carbohydrates: 56g x 4 kcal/g = 224 kcal\n• Protein: 20g x 4 kcal/g = 80 kcal\n• Fat: 12g x 9 kcal/g = 108 kcal\n• Total Energy: 224 + 80 + 108 = 412 kcal","whyWrongChoices":"Alternative options: C 46 g P 16 g F 10g E 338 kcal, C 56 g P 16 g F 6 g E 342 kcal, C 46 g P 20 g F 10 g E 354 kcal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all measures are allowed to increase the energy intake of renal patient except::::serving fruit cocktail with heavy syrup', 'all measures are allowed to increase the energy intake of renal patient except:', 'serving fruit cocktail with heavy syrup', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a renal patient requires increased energy intake, particularly when protein, potassium, phosphorus, or fluid may need to be controlled, energy can be increased by using calorie-dense foods that provide relatively little protein and minerals. Adding sugar, oil, and unsalted margarine can increase energy density without substantially increasing protein. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"serving fruit cocktail with heavy syrup\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a renal patient requires increased energy intake, particularly when protein, potassium, phosphorus, or fluid may need to be controlled, energy can be increased by using calorie-dense foods that provide relatively little protein and minerals. Adding sugar, oil, and unsalted margarine can increase energy density without substantially increasing protein. \n\nIn contrast, fruit cocktail with heavy syrup may be inappropriate depending on the patient''s potassium and fluid restrictions; canned fruits may also contribute substantial potassium, and the syrup contributes mainly sugar rather than being a particularly useful renal nutrition strategy.","whyWrongChoices":"Alternative options: using additional sugar in foods, preparing foods with oil, adding unsalted margarine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all measures are allowed to increase the energy intake of renal patient except::::', 'all measures are allowed to increase the energy intake of renal patient except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When a renal patient requires increased energy intake, particularly when protein, potassium, phosphorus, or fluid may need to be controlled, energy can be increased by using calorie-dense foods that provide relatively little protein and minerals. Adding sugar, oil, and unsalted margarine can increase energy density without substantially increasing protein. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"serving fruit cocktail with heavy syrup\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When a renal patient requires increased energy intake, particularly when protein, potassium, phosphorus, or fluid may need to be controlled, energy can be increased by using calorie-dense foods that provide relatively little protein and minerals. Adding sugar, oil, and unsalted margarine can increase energy density without substantially increasing protein. \n\nIn contrast, fruit cocktail with heavy syrup may be inappropriate depending on the patient''s potassium and fluid restrictions; canned fruits may also contribute substantial potassium, and the syrup contributes mainly sugar rather than being a particularly useful renal nutrition strategy.","whyWrongChoices":"Alternative options: using additional sugar in foods, preparing foods with oil, adding unsalted margarine"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following are conditions that resulted from vitamin c deficiency? i. beriberi, confusion, depression, convulsions, scurvy ii. microcytic anemia, bleeding gums, loosened teeth, scurvy iii. rashes, hair loss, microcytic anemia, bleeding gums iv. confusion, convulsions, loosened teeth, scurvy, hair loss:::ii only', 'which of the following are conditions that resulted from vitamin c deficiency? i. beriberi, confusion, depression, convulsions, scurvy ii. microcytic anemia, bleeding gums, loosened teeth, scurvy iii. rashes, hair loss, microcytic anemia, bleeding gums iv. confusion, convulsions, loosened teeth, scurvy, hair loss', 'II only', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin C deficiency causes scurvy, characterized by impaired collagen synthesis and connective-tissue abnormalities. Classic manifestations include bleeding or swollen gums, loose teeth, poor wound healing, petechiae/ecchymoses, and fatigue. Vitamin C also enhances non-heme iron absorption, so deficiency can contribute to anemia; however, the anemia associated with vitamin C deficiency is not necessarily microcytic, and may be related to impaired iron absorption and blood loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"II only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin C deficiency causes scurvy, characterized by impaired collagen synthesis and connective-tissue abnormalities. Classic manifestations include bleeding or swollen gums, loose teeth, poor wound healing, petechiae/ecchymoses, and fatigue. Vitamin C also enhances non-heme iron absorption, so deficiency can contribute to anemia; however, the anemia associated with vitamin C deficiency is not necessarily microcytic, and may be related to impaired iron absorption and blood loss.\n\nAmong the choices, Statement II is the best match because it contains the classic manifestations of scurvy.","whyWrongChoices":"Alternative options: I only, II and III only, I and IV only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following are conditions that resulted from vitamin c deficiency? i. beriberi, confusion, depression, convulsions, scurvy ii. microcytic anemia, bleeding gums, loosened teeth, scurvy iii. rashes, hair loss, microcytic anemia, bleeding gums iv. confusion, convulsions, loosened teeth, scurvy, hair loss:::', 'which of the following are conditions that resulted from vitamin c deficiency? i. beriberi, confusion, depression, convulsions, scurvy ii. microcytic anemia, bleeding gums, loosened teeth, scurvy iii. rashes, hair loss, microcytic anemia, bleeding gums iv. confusion, convulsions, loosened teeth, scurvy, hair loss', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin C deficiency causes scurvy, characterized by impaired collagen synthesis and connective-tissue abnormalities. Classic manifestations include bleeding or swollen gums, loose teeth, poor wound healing, petechiae/ecchymoses, and fatigue. Vitamin C also enhances non-heme iron absorption, so deficiency can contribute to anemia; however, the anemia associated with vitamin C deficiency is not necessarily microcytic, and may be related to impaired iron absorption and blood loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"II only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin C deficiency causes scurvy, characterized by impaired collagen synthesis and connective-tissue abnormalities. Classic manifestations include bleeding or swollen gums, loose teeth, poor wound healing, petechiae/ecchymoses, and fatigue. Vitamin C also enhances non-heme iron absorption, so deficiency can contribute to anemia; however, the anemia associated with vitamin C deficiency is not necessarily microcytic, and may be related to impaired iron absorption and blood loss.\n\nAmong the choices, Statement II is the best match because it contains the classic manifestations of scurvy.","whyWrongChoices":"Alternative options: I only, II and III only, I and IV only"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is true for nutritional management of esophageal obstruction?:::liquid diets', 'which of the following is true for nutritional management of esophageal obstruction?', 'Liquid diets', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Esophageal obstruction is characterized by partial or complete blockage of the esophagus, leading to dysphagia (difficulty swallowing) and impaired passage of food from the mouth to the stomach. Common causes include esophageal cancer, benign strictures, esophageal webs, achalasia, or foreign body obstruction. The primary goal of nutrition therapy is to maintain adequate nutritional intake while minimizing swallowing difficulty and the risk of aspiration. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liquid diets\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Esophageal obstruction is characterized by partial or complete blockage of the esophagus, leading to dysphagia (difficulty swallowing) and impaired passage of food from the mouth to the stomach. Common causes include esophageal cancer, benign strictures, esophageal webs, achalasia, or foreign body obstruction. The primary goal of nutrition therapy is to maintain adequate nutritional intake while minimizing swallowing difficulty and the risk of aspiration. \n\nDepending on the severity of the obstruction, patients may require a clear liquid diet, full liquid diet, or texture-modified diet. When oral intake becomes inadequate or unsafe, enteral nutrition via a feeding tube (e.g., gastrostomy or jejunostomy) may be necessary.","whyWrongChoices":"Alternative options: Low fat diet, Low calorie, High protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is true for nutritional management of esophageal obstruction?:::', 'which of the following is true for nutritional management of esophageal obstruction?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Esophageal obstruction is characterized by partial or complete blockage of the esophagus, leading to dysphagia (difficulty swallowing) and impaired passage of food from the mouth to the stomach. Common causes include esophageal cancer, benign strictures, esophageal webs, achalasia, or foreign body obstruction. The primary goal of nutrition therapy is to maintain adequate nutritional intake while minimizing swallowing difficulty and the risk of aspiration. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Liquid diets\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Esophageal obstruction is characterized by partial or complete blockage of the esophagus, leading to dysphagia (difficulty swallowing) and impaired passage of food from the mouth to the stomach. Common causes include esophageal cancer, benign strictures, esophageal webs, achalasia, or foreign body obstruction. The primary goal of nutrition therapy is to maintain adequate nutritional intake while minimizing swallowing difficulty and the risk of aspiration. \n\nDepending on the severity of the obstruction, patients may require a clear liquid diet, full liquid diet, or texture-modified diet. When oral intake becomes inadequate or unsafe, enteral nutrition via a feeding tube (e.g., gastrostomy or jejunostomy) may be necessary.","whyWrongChoices":"Alternative options: Low fat diet, Low calorie, High protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the rq of glucose is::::1', 'the rq of glucose is:', '1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The respiratory quotient (RQ) is the ratio of the amount of carbon dioxide (CO₂) produced to oxygen (O₂) consumed during the oxidation of a nutrient. For carbohydrate, specifically glucose: C6​H12​O6 ​+ 6O2 ​→ 6CO2 ​+ 6H2​O Therefore: RQ = 6CO2 ​÷ 6O2 ​= 1.0 Thus, the RQ of glucose is 1.0.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The respiratory quotient (RQ) is the ratio of the amount of carbon dioxide (CO₂) produced to oxygen (O₂) consumed during the oxidation of a nutrient. For carbohydrate, specifically glucose: C6​H12​O6 ​+ 6O2 ​→ 6CO2 ​+ 6H2​O Therefore: RQ = 6CO2 ​÷ 6O2 ​= 1.0 Thus, the RQ of glucose is 1.0.\n\nRQ values differ according to the macronutrient being oxidized: \n• Carbohydrate = 1.0 \n• Protein ≈ 0.8 \n• Fat = 0.7 \n• Mixed diet ≈ 0.8–0.9 \n\nThis concept is important in indirect calorimetry, which estimates energy expenditure by measuring oxygen consumption and carbon dioxide production.","whyWrongChoices":"Alternative options: 0.9, 0.8, 0.7"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the rq of glucose is::::', 'the rq of glucose is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The respiratory quotient (RQ) is the ratio of the amount of carbon dioxide (CO₂) produced to oxygen (O₂) consumed during the oxidation of a nutrient. For carbohydrate, specifically glucose: C6​H12​O6 ​+ 6O2 ​→ 6CO2 ​+ 6H2​O Therefore: RQ = 6CO2 ​÷ 6O2 ​= 1.0 Thus, the RQ of glucose is 1.0.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The respiratory quotient (RQ) is the ratio of the amount of carbon dioxide (CO₂) produced to oxygen (O₂) consumed during the oxidation of a nutrient. For carbohydrate, specifically glucose: C6​H12​O6 ​+ 6O2 ​→ 6CO2 ​+ 6H2​O Therefore: RQ = 6CO2 ​÷ 6O2 ​= 1.0 Thus, the RQ of glucose is 1.0.\n\nRQ values differ according to the macronutrient being oxidized: \n• Carbohydrate = 1.0 \n• Protein ≈ 0.8 \n• Fat = 0.7 \n• Mixed diet ≈ 0.8–0.9 \n\nThis concept is important in indirect calorimetry, which estimates energy expenditure by measuring oxygen consumption and carbon dioxide production.","whyWrongChoices":"Alternative options: 0.9, 0.8, 0.7"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deficiency of this vitamin causes wernicke-korsakoff syndrome::::vitamin b1', 'deficiency of this vitamin causes wernicke-korsakoff syndrome:', 'Vitamin B1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wernicke–Korsakoff syndrome is a neurologic disorder resulting from severe thiamine deficiency. It is classically associated with chronic alcohol use disorder but may also occur in prolonged malnutrition, hyperemesis gravidarum, bariatric surgery, or conditions causing prolonged inadequate intake. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wernicke–Korsakoff syndrome is a neurologic disorder resulting from severe thiamine deficiency. It is classically associated with chronic alcohol use disorder but may also occur in prolonged malnutrition, hyperemesis gravidarum, bariatric surgery, or conditions causing prolonged inadequate intake. \n\nThe syndrome consists of two related conditions: \nWernicke encephalopathy (acute): \n• Confusion \n• Ophthalmoplegia or nystagmus \n• Ataxia \n\nKorsakoff syndrome (chronic): \n• Severe memory impairment\n• Confabulation \n• Irreversible cognitive deficits if untreated \n\nThiamine functions as thiamine pyrophosphate (TPP), a coenzyme for pyruvate dehydrogenase, α-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cerebral energy metabolism, particularly in brain regions with high metabolic demands.","whyWrongChoices":"Alternative options: Vitamin A, Vitamin B3, Vitamin C"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:deficiency of this vitamin causes wernicke-korsakoff syndrome::::', 'deficiency of this vitamin causes wernicke-korsakoff syndrome:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wernicke–Korsakoff syndrome is a neurologic disorder resulting from severe thiamine deficiency. It is classically associated with chronic alcohol use disorder but may also occur in prolonged malnutrition, hyperemesis gravidarum, bariatric surgery, or conditions causing prolonged inadequate intake. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wernicke–Korsakoff syndrome is a neurologic disorder resulting from severe thiamine deficiency. It is classically associated with chronic alcohol use disorder but may also occur in prolonged malnutrition, hyperemesis gravidarum, bariatric surgery, or conditions causing prolonged inadequate intake. \n\nThe syndrome consists of two related conditions: \nWernicke encephalopathy (acute): \n• Confusion \n• Ophthalmoplegia or nystagmus \n• Ataxia \n\nKorsakoff syndrome (chronic): \n• Severe memory impairment\n• Confabulation \n• Irreversible cognitive deficits if untreated \n\nThiamine functions as thiamine pyrophosphate (TPP), a coenzyme for pyruvate dehydrogenase, α-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cerebral energy metabolism, particularly in brain regions with high metabolic demands.","whyWrongChoices":"Alternative options: Vitamin A, Vitamin B3, Vitamin C"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following describes type 1 diabetes mellitus?:::it is an autoimmune disorder', 'which of the following describes type 1 diabetes mellitus?', 'It is an autoimmune disorder', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Type 1 Diabetes Mellitus (T1DM) is a chronic, lifelong autoimmune disorder. The body’s own immune system mistakenly targets and destroys the insulin-producing beta cells located in the islets of Langerhans within the pancreas. This immune-mediated destruction results in an absolute insulin deficiency, meaning the pancreas can no longer produce insulin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It is an autoimmune disorder\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Type 1 Diabetes Mellitus (T1DM) is a chronic, lifelong autoimmune disorder. The body’s own immune system mistakenly targets and destroys the insulin-producing beta cells located in the islets of Langerhans within the pancreas. This immune-mediated destruction results in an absolute insulin deficiency, meaning the pancreas can no longer produce insulin.\n\n• The pancreas may have the ability to produce insulin but cells are deficient in receptors for insulin: This statement refers to a structural down-regulation of insulin receptors, which is a mechanism related to extreme forms of insulin resistance, not the absolute destruction of pancreatic cells seen in T1DM.\n• The person usually does not develop symptoms until age 45: T1DM is most commonly diagnosed in children, adolescents, and young adults (historically termed \"juvenile diabetes\"), although it can theoretically manifest at any age. Diagnosis past age 45 is far more characteristic of Type 2 Diabetes Mellitus (T2DM).\n• It is characterized by insulin resistance: Insulin resistance—where body cells fail to respond normally to circulating insulin—is the hallmark pathophysiological driver of Type 2 Diabetes, not Type 1.","whyWrongChoices":"Alternative options: The pancreas may have the ability to produce insulin but cells are deficient in receptors for insulin, The person usually does not develop symptoms until age 45, It is characterized by insulin resistance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following describes type 1 diabetes mellitus?:::', 'which of the following describes type 1 diabetes mellitus?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Type 1 Diabetes Mellitus (T1DM) is a chronic, lifelong autoimmune disorder. The body’s own immune system mistakenly targets and destroys the insulin-producing beta cells located in the islets of Langerhans within the pancreas. This immune-mediated destruction results in an absolute insulin deficiency, meaning the pancreas can no longer produce insulin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It is an autoimmune disorder\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Type 1 Diabetes Mellitus (T1DM) is a chronic, lifelong autoimmune disorder. The body’s own immune system mistakenly targets and destroys the insulin-producing beta cells located in the islets of Langerhans within the pancreas. This immune-mediated destruction results in an absolute insulin deficiency, meaning the pancreas can no longer produce insulin.\n\n• The pancreas may have the ability to produce insulin but cells are deficient in receptors for insulin: This statement refers to a structural down-regulation of insulin receptors, which is a mechanism related to extreme forms of insulin resistance, not the absolute destruction of pancreatic cells seen in T1DM.\n• The person usually does not develop symptoms until age 45: T1DM is most commonly diagnosed in children, adolescents, and young adults (historically termed \"juvenile diabetes\"), although it can theoretically manifest at any age. Diagnosis past age 45 is far more characteristic of Type 2 Diabetes Mellitus (T2DM).\n• It is characterized by insulin resistance: Insulin resistance—where body cells fail to respond normally to circulating insulin—is the hallmark pathophysiological driver of Type 2 Diabetes, not Type 1.","whyWrongChoices":"Alternative options: The pancreas may have the ability to produce insulin but cells are deficient in receptors for insulin, The person usually does not develop symptoms until age 45, It is characterized by insulin resistance"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which specific storage protein (prolamin) in wheat triggers the autoimmune enteropathy in celiac disease?:::gliadin', 'which specific storage protein (prolamin) in wheat triggers the autoimmune enteropathy in celiac disease?', 'Gliadin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Celiac disease is triggered by the ingestion of gluten prolamins: Gliadin in wheat, Secalin in rye, and Hordein in barley. These induce immune-mediated small intestinal mucosal inflammation and villous atrophy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gliadin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Celiac disease is triggered by the ingestion of gluten prolamins: Gliadin in wheat, Secalin in rye, and Hordein in barley. These induce immune-mediated small intestinal mucosal inflammation and villous atrophy.","whyWrongChoices":"Alternative options: Glutenin, Casein, Zein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the influence of sunlight, is synthesized in our skin from .:::', 'under the influence of sunlight, is synthesized in our skin from .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When your skin is exposed to the ultraviolet B (UVB) radiation in sunlight, it breaks down a specific form of cholesterol naturally present in your skin cells called 7-dehydrocholesterol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin D₃, 7-dehydrocholesterol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When your skin is exposed to the ultraviolet B (UVB) radiation in sunlight, it breaks down a specific form of cholesterol naturally present in your skin cells called 7-dehydrocholesterol.\n\nThis chemical reaction converts the cholesterol precursor into Vitamin D3 (cholecalciferol), which your liver and kidneys then convert into its active hormone form.","whyWrongChoices":"Alternative options: Calcium, vitamin D, Vitamin E, cholesterol, Vitamin B1, protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a hormone that diminishes appetite and increase energy expenditure while increase appetite and decreases energy expenditure.:::leptin, neuropeptide y', 'is a hormone that diminishes appetite and increase energy expenditure while increase appetite and decreases energy expenditure.', 'Leptin, neuropeptide Y', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leptin is a hormone secreted primarily by adipocytes. It acts on the hypothalamus to suppress food intake and increase energy expenditure by signaling adequate energy stores. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Leptin, neuropeptide Y\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leptin is a hormone secreted primarily by adipocytes. It acts on the hypothalamus to suppress food intake and increase energy expenditure by signaling adequate energy stores. \n\nNeuropeptide Y (NPY) is one of the most potent appetite-stimulating neurotransmitters in the hypothalamus. It increases food intake, promotes fat storage, and decreases energy expenditure, especially during fasting or caloric restriction. \n\nLeptin and NPY exert opposing effects: \n• High leptin suppresses NPY activity. \n• Low leptin (e.g., starvation) increases NPY secretion, stimulating hunger.","whyWrongChoices":"Alternative options: Neuropeptide Y, leptin, Cortisol, leptin, Leptin, glucagon"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:is a hormone that diminishes appetite and increase energy expenditure while increase appetite and decreases energy expenditure.:::', 'is a hormone that diminishes appetite and increase energy expenditure while increase appetite and decreases energy expenditure.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Leptin is a hormone secreted primarily by adipocytes. It acts on the hypothalamus to suppress food intake and increase energy expenditure by signaling adequate energy stores. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Leptin, neuropeptide Y\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Leptin is a hormone secreted primarily by adipocytes. It acts on the hypothalamus to suppress food intake and increase energy expenditure by signaling adequate energy stores. \n\nNeuropeptide Y (NPY) is one of the most potent appetite-stimulating neurotransmitters in the hypothalamus. It increases food intake, promotes fat storage, and decreases energy expenditure, especially during fasting or caloric restriction. \n\nLeptin and NPY exert opposing effects: \n• High leptin suppresses NPY activity. \n• Low leptin (e.g., starvation) increases NPY secretion, stimulating hunger.","whyWrongChoices":"Alternative options: Neuropeptide Y, leptin, Cortisol, leptin, Leptin, glucagon"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this enzyme allows the brain and erythrocytes to utilize glucose even in state of low concentrations.:::hexokinase', 'this enzyme allows the brain and erythrocytes to utilize glucose even in state of low concentrations.', 'Hexokinase', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hexokinase catalyzes the first step of glycolysis by converting glucose to glucose-6-phosphate. It has a low Km (high affinity) for glucose, allowing tissues like the brain and red blood cells to continue utilizing glucose even when blood glucose levels are low. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hexokinase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hexokinase catalyzes the first step of glycolysis by converting glucose to glucose-6-phosphate. It has a low Km (high affinity) for glucose, allowing tissues like the brain and red blood cells to continue utilizing glucose even when blood glucose levels are low. \n\nThis is physiologically important because: \n• The brain relies heavily on glucose under normal conditions. \n• Red blood cells depend exclusively on glycolysis because they lack mitochondria. \n\nBy contrast, the liver expresses glucokinase, which has a higher Km and functions primarily when glucose concentrations are elevated after meals.","whyWrongChoices":"Alternative options: Glucose-6-phosphate, ATP, Fructose-6-phosphate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:this enzyme allows the brain and erythrocytes to utilize glucose even in state of low concentrations.:::', 'this enzyme allows the brain and erythrocytes to utilize glucose even in state of low concentrations.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hexokinase catalyzes the first step of glycolysis by converting glucose to glucose-6-phosphate. It has a low Km (high affinity) for glucose, allowing tissues like the brain and red blood cells to continue utilizing glucose even when blood glucose levels are low. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hexokinase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hexokinase catalyzes the first step of glycolysis by converting glucose to glucose-6-phosphate. It has a low Km (high affinity) for glucose, allowing tissues like the brain and red blood cells to continue utilizing glucose even when blood glucose levels are low. \n\nThis is physiologically important because: \n• The brain relies heavily on glucose under normal conditions. \n• Red blood cells depend exclusively on glycolysis because they lack mitochondria. \n\nBy contrast, the liver expresses glucokinase, which has a higher Km and functions primarily when glucose concentrations are elevated after meals.","whyWrongChoices":"Alternative options: Glucose-6-phosphate, ATP, Fructose-6-phosphate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a low phosphorous diet contains less than mg phosphorous:::1000 mg', 'a low phosphorous diet contains less than mg phosphorous', '1000 mg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For traditional renal diet-therapy teaching, a low-phosphorus diet is generally defined as providing less than 800–1,000 mg phosphorus per day, with the exact prescription individualized according to renal function, serum phosphorus, dietary protein requirements, and dialysis status. Therefore, among the choices given, less than 1,000 mg/day is the best answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1000 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For traditional renal diet-therapy teaching, a low-phosphorus diet is generally defined as providing less than 800–1,000 mg phosphorus per day, with the exact prescription individualized according to renal function, serum phosphorus, dietary protein requirements, and dialysis status. Therefore, among the choices given, less than 1,000 mg/day is the best answer.","whyWrongChoices":"Alternative options: 1200 mg, 1400 mg, 1600 mg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:evaluate the following statements regarding amino acid metabolism. i. amino acids are deaminated first into ketoacid before being utilized for energy. ii. deamination primarily occurs in the kidneys.:::both statements are incorrect.', 'evaluate the following statements regarding amino acid metabolism. i. amino acids are deaminated first into ketoacid before being utilized for energy. ii. deamination primarily occurs in the kidneys.', 'Both statements are incorrect.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement 1 is imprecise. Most amino acids first undergo transamination, transferring their amino group to α-ketoglutarate to form glutamate. Glutamate is then oxidatively deaminated, producing ammonia and regenerating α-ketoglutarate. Thus, deamination is not the universal \"first\" step for amino acid catabolism. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are incorrect.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement 1 is imprecise. Most amino acids first undergo transamination, transferring their amino group to α-ketoglutarate to form glutamate. Glutamate is then oxidatively deaminated, producing ammonia and regenerating α-ketoglutarate. Thus, deamination is not the universal \"first\" step for amino acid catabolism. \n\nStatement 2 is also incorrect. The liver is the primary site of amino acid deamination and urea synthesis. While the kidneys participate in amino acid metabolism and ammonia production, they are not the principal site of deamination. Therefore, both statements are incorrect.","whyWrongChoices":"Alternative options: Only statement 1 is correct., Only statement 2 is correct., Both statements are correct."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:evaluate the following statements regarding amino acid metabolism. i. amino acids are deaminated first into ketoacid before being utilized for energy. ii. deamination primarily occurs in the kidneys.:::', 'evaluate the following statements regarding amino acid metabolism. i. amino acids are deaminated first into ketoacid before being utilized for energy. ii. deamination primarily occurs in the kidneys.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement 1 is imprecise. Most amino acids first undergo transamination, transferring their amino group to α-ketoglutarate to form glutamate. Glutamate is then oxidatively deaminated, producing ammonia and regenerating α-ketoglutarate. Thus, deamination is not the universal \"first\" step for amino acid catabolism. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both statements are incorrect.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement 1 is imprecise. Most amino acids first undergo transamination, transferring their amino group to α-ketoglutarate to form glutamate. Glutamate is then oxidatively deaminated, producing ammonia and regenerating α-ketoglutarate. Thus, deamination is not the universal \"first\" step for amino acid catabolism. \n\nStatement 2 is also incorrect. The liver is the primary site of amino acid deamination and urea synthesis. While the kidneys participate in amino acid metabolism and ammonia production, they are not the principal site of deamination. Therefore, both statements are incorrect.","whyWrongChoices":"Alternative options: Only statement 1 is correct., Only statement 2 is correct., Both statements are correct."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are metabolic pathways of cholesterol except::::energy production', 'the following are metabolic pathways of cholesterol except:', 'Energy production', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In humans, the core structure of cholesterol consists of a highly stable four-ring steroid nucleus (perhydrocyclopentanophenanthrene ring). Unlike fatty acids, carbohydrates, or proteins, the human body completely lacks the enzymes required to break down or cleave this robust ring structure to generate energy or ATP. Therefore, cholesterol provides 0 calories per gram and is never utilized as a metabolic fuel source.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Energy production\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In humans, the core structure of cholesterol consists of a highly stable four-ring steroid nucleus (perhydrocyclopentanophenanthrene ring). Unlike fatty acids, carbohydrates, or proteins, the human body completely lacks the enzymes required to break down or cleave this robust ring structure to generate energy or ATP. Therefore, cholesterol provides 0 calories per gram and is never utilized as a metabolic fuel source.\n\n• Secretion of bile and Excretion of feces: Because the body cannot oxidize or dismantle the steroid ring for energy, the only way it can physically eliminate cholesterol is through the liver. The liver converts cholesterol into bile acids and bile salts, which are secreted into the digestive tract to help emulsify dietary fats. While most bile is reabsorbed, a small portion escapes recycling and is unalterably eliminated from the body via fecal excretion.\n• Hormone production: Cholesterol serves as the absolute, obligatory structural precursor for the synthesis of all steroid hormones in the body. Specialized endocrine tissues modify cholesterol to produce glucocorticoids (like cortisol), mineralocorticoids (like aldosterone), and sex hormones (like estrogen, progesterone, and testosterone).","whyWrongChoices":"Alternative options: Secretion of bile, Excretion of feces, Hormone production"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the following are metabolic pathways of cholesterol except::::', 'the following are metabolic pathways of cholesterol except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In humans, the core structure of cholesterol consists of a highly stable four-ring steroid nucleus (perhydrocyclopentanophenanthrene ring). Unlike fatty acids, carbohydrates, or proteins, the human body completely lacks the enzymes required to break down or cleave this robust ring structure to generate energy or ATP. Therefore, cholesterol provides 0 calories per gram and is never utilized as a metabolic fuel source.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Energy production\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In humans, the core structure of cholesterol consists of a highly stable four-ring steroid nucleus (perhydrocyclopentanophenanthrene ring). Unlike fatty acids, carbohydrates, or proteins, the human body completely lacks the enzymes required to break down or cleave this robust ring structure to generate energy or ATP. Therefore, cholesterol provides 0 calories per gram and is never utilized as a metabolic fuel source.\n\n• Secretion of bile and Excretion of feces: Because the body cannot oxidize or dismantle the steroid ring for energy, the only way it can physically eliminate cholesterol is through the liver. The liver converts cholesterol into bile acids and bile salts, which are secreted into the digestive tract to help emulsify dietary fats. While most bile is reabsorbed, a small portion escapes recycling and is unalterably eliminated from the body via fecal excretion.\n• Hormone production: Cholesterol serves as the absolute, obligatory structural precursor for the synthesis of all steroid hormones in the body. Specialized endocrine tissues modify cholesterol to produce glucocorticoids (like cortisol), mineralocorticoids (like aldosterone), and sex hormones (like estrogen, progesterone, and testosterone).","whyWrongChoices":"Alternative options: Secretion of bile, Excretion of feces, Hormone production"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nad+ contains while fad contains .:::niacin, riboflavin', 'nad+ contains while fad contains .', 'Niacin, riboflavin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"NAD⁺ (Nicotinamide Adenine Dinucleotide) and FAD (Flavin Adenine Dinucleotide) are two of the most important coenzymes involved in oxidation-reduction (redox) reactions and energy metabolism. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Niacin, riboflavin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"NAD⁺ (Nicotinamide Adenine Dinucleotide) and FAD (Flavin Adenine Dinucleotide) are two of the most important coenzymes involved in oxidation-reduction (redox) reactions and energy metabolism. \n\nNAD⁺ is synthesized from niacin (Vitamin B₃). During glycolysis, the TCA cycle, and β-oxidation, NAD⁺ accepts electrons and hydrogen ions to become NADH, which subsequently donates these electrons to the Electron Transport Chain (ETC) to generate ATP. \n\nFAD, on the other hand, is derived from riboflavin (Vitamin B₂). It accepts two hydrogen atoms to form FADH₂, another reduced coenzyme that delivers electrons to Complex II of the ETC. \n\nAlthough both NADH and FADH₂ ultimately produce ATP, NADH generates more ATP because it donates electrons earlier in the ETC.","whyWrongChoices":"Alternative options: Thiamine, riboflavin, Riboflavin, thiamine, Riboflavin, niacin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:nad+ contains while fad contains .:::', 'nad+ contains while fad contains .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"NAD⁺ (Nicotinamide Adenine Dinucleotide) and FAD (Flavin Adenine Dinucleotide) are two of the most important coenzymes involved in oxidation-reduction (redox) reactions and energy metabolism. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Niacin, riboflavin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"NAD⁺ (Nicotinamide Adenine Dinucleotide) and FAD (Flavin Adenine Dinucleotide) are two of the most important coenzymes involved in oxidation-reduction (redox) reactions and energy metabolism. \n\nNAD⁺ is synthesized from niacin (Vitamin B₃). During glycolysis, the TCA cycle, and β-oxidation, NAD⁺ accepts electrons and hydrogen ions to become NADH, which subsequently donates these electrons to the Electron Transport Chain (ETC) to generate ATP. \n\nFAD, on the other hand, is derived from riboflavin (Vitamin B₂). It accepts two hydrogen atoms to form FADH₂, another reduced coenzyme that delivers electrons to Complex II of the ETC. \n\nAlthough both NADH and FADH₂ ultimately produce ATP, NADH generates more ATP because it donates electrons earlier in the ETC.","whyWrongChoices":"Alternative options: Thiamine, riboflavin, Riboflavin, thiamine, Riboflavin, niacin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:phosphoglycerate kinase functions in carbohydrate metabolism to produce atp via::::substrate level phosphorylation', 'phosphoglycerate kinase functions in carbohydrate metabolism to produce atp via:', 'Substrate level phosphorylation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phosphoglycerate kinase catalyzes the conversion of: 1,3-bisphosphoglycerate → 3-phosphoglycerate ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Substrate level phosphorylation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phosphoglycerate kinase catalyzes the conversion of: 1,3-bisphosphoglycerate → 3-phosphoglycerate \n\nDuring this reaction, a phosphate group is directly transferred from the substrate to ADP, producing ATP. This direct transfer is called substrate-level phosphorylation. Unlike oxidative phosphorylation, this reaction: \n• does not require oxygen, \n• does not occur in mitochondria, \n• does not involve the electron transport chain. \n\nAnother example of substrate-level phosphorylation occurs during the conversion of phosphoenolpyruvate (PEP) to pyruvate by pyruvate kinase.","whyWrongChoices":"Alternative options: Oxidative phosphorylation, Oxidative decarboxylation, Phosphorolysis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:phosphoglycerate kinase functions in carbohydrate metabolism to produce atp via::::', 'phosphoglycerate kinase functions in carbohydrate metabolism to produce atp via:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phosphoglycerate kinase catalyzes the conversion of: 1,3-bisphosphoglycerate → 3-phosphoglycerate ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Substrate level phosphorylation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phosphoglycerate kinase catalyzes the conversion of: 1,3-bisphosphoglycerate → 3-phosphoglycerate \n\nDuring this reaction, a phosphate group is directly transferred from the substrate to ADP, producing ATP. This direct transfer is called substrate-level phosphorylation. Unlike oxidative phosphorylation, this reaction: \n• does not require oxygen, \n• does not occur in mitochondria, \n• does not involve the electron transport chain. \n\nAnother example of substrate-level phosphorylation occurs during the conversion of phosphoenolpyruvate (PEP) to pyruvate by pyruvate kinase.","whyWrongChoices":"Alternative options: Oxidative phosphorylation, Oxidative decarboxylation, Phosphorolysis"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:under the influence of sunlight, is synthesized in our skin from .:::vitamin d₃, 7-dehydrocholesterol', 'under the influence of sunlight, is synthesized in our skin from .', 'Vitamin D₃, 7-dehydrocholesterol', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When your skin is exposed to the ultraviolet B (UVB) radiation in sunlight, it breaks down a specific form of cholesterol naturally present in your skin cells called 7-dehydrocholesterol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin D₃, 7-dehydrocholesterol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When your skin is exposed to the ultraviolet B (UVB) radiation in sunlight, it breaks down a specific form of cholesterol naturally present in your skin cells called 7-dehydrocholesterol.\n\nThis chemical reaction converts the cholesterol precursor into Vitamin D3 (cholecalciferol), which your liver and kidneys then convert into its active hormone form.","whyWrongChoices":"Alternative options: Calcium, vitamin D, Vitamin E, cholesterol, Vitamin B1, protein"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 32-year-old woman (ms. bma) wants to determine her target heart rate for moderate- to vigorous-intensity aerobic exercise. based on the age-predicted maximum heart rate method, what is her target heart rate range?:::122-160 beats', 'a 32-year-old woman (ms. bma) wants to determine her target heart rate for moderate- to vigorous-intensity aerobic exercise. based on the age-predicted maximum heart rate method, what is her target heart rate range?', '122-160 beats', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A commonly used method for estimating maximum heart rate (HRmax) is: HRmax = 220 − age ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"122-160 beats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A commonly used method for estimating maximum heart rate (HRmax) is: HRmax = 220 − age \n\nFor a 32-year-old: \n• HRmax = 220 − 32 = 188 beats/min \n\nThe recommended target heart rate (THR) for moderate- to vigorous-intensity exercise is approximately 65–85% of HRmax. \n\nCalculation: \n• Lower limit: 188 × 0.65 = 122 beats/min \n• Upper limit: 188 × 0.85 = 160 beats/min \n\nTherefore, the target heart rate range is: 122–160 beats/min. Although newer equations such as Tanaka''s formula (208 − 0.7 × age) may estimate HRmax more accurately in some populations, the 220 − age equation remains the formula most commonly used in basic exercise prescription and is frequently tested in licensure examinations.","whyWrongChoices":"Alternative options: 150-160 beats, 138-200 beats, 162-202 beats"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a 32-year-old woman (ms. bma) wants to determine her target heart rate for moderate- to vigorous-intensity aerobic exercise. based on the age-predicted maximum heart rate method, what is her target heart rate range?:::', 'a 32-year-old woman (ms. bma) wants to determine her target heart rate for moderate- to vigorous-intensity aerobic exercise. based on the age-predicted maximum heart rate method, what is her target heart rate range?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A commonly used method for estimating maximum heart rate (HRmax) is: HRmax = 220 − age ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"122-160 beats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A commonly used method for estimating maximum heart rate (HRmax) is: HRmax = 220 − age \n\nFor a 32-year-old: \n• HRmax = 220 − 32 = 188 beats/min \n\nThe recommended target heart rate (THR) for moderate- to vigorous-intensity exercise is approximately 65–85% of HRmax. \n\nCalculation: \n• Lower limit: 188 × 0.65 = 122 beats/min \n• Upper limit: 188 × 0.85 = 160 beats/min \n\nTherefore, the target heart rate range is: 122–160 beats/min. Although newer equations such as Tanaka''s formula (208 − 0.7 × age) may estimate HRmax more accurately in some populations, the 220 − age equation remains the formula most commonly used in basic exercise prescription and is frequently tested in licensure examinations.","whyWrongChoices":"Alternative options: 150-160 beats, 138-200 beats, 162-202 beats"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
