INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:what is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?:::', 'what is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"32 ÷ Scoop Number = fluid ounces\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).","whyWrongChoices":"Alternative options: 64 ÷ Scoop Number = fluid ounces, 16 ÷ Scoop Number = fluid ounces, Scoop Number × 4 = fluid ounces"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:if a recipe costs $1.80 per portion to produce and the target food cost percentage is 30%, what is the selling price using the factor pricing method?:::$6.00', 'if a recipe costs $1.80 per portion to produce and the target food cost percentage is 30%, what is the selling price using the factor pricing method?', '$6.00', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Markup Factor = 100 ÷ Target Food Cost % = 100 ÷ 30 = 3.333. Selling Price = Raw Food Cost × Markup Factor = $1.80 × 3.333 = $6.00 (Alternatively: $1.80 ÷ 0.30 = $6.00).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"$6.00\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Markup Factor = 100 ÷ Target Food Cost % = 100 ÷ 30 = 3.333. Selling Price = Raw Food Cost × Markup Factor = $1.80 × 3.333 = $6.00 (Alternatively: $1.80 ÷ 0.30 = $6.00).","whyWrongChoices":"Alternative options: $5.40, $7.20, $4.50"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:wernicke-korsakoff syndrome and beriberi are caused by a severe deficiency of which water-soluble vitamin?:::thiamine (vitamin b1)', 'wernicke-korsakoff syndrome and beriberi are caused by a severe deficiency of which water-soluble vitamin?', 'Thiamine (Vitamin B1)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Thiamine (Vitamin B1)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.","whyWrongChoices":"Alternative options: Riboflavin (Vitamin B2), Niacin (Vitamin B3), Pyridoxine (Vitamin B6)"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:wernicke-korsakoff syndrome and beriberi are caused by a severe deficiency of which water-soluble vitamin?:::', 'wernicke-korsakoff syndrome and beriberi are caused by a severe deficiency of which water-soluble vitamin?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Thiamine (Vitamin B1)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.","whyWrongChoices":"Alternative options: Riboflavin (Vitamin B2), Niacin (Vitamin B3), Pyridoxine (Vitamin B6)"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what are the classic "4 ds" characteristic of severe pellagra (niacin / vitamin b3 deficiency)?:::dermatitis, diarrhea, dementia, and death', 'what are the classic "4 ds" characteristic of severe pellagra (niacin / vitamin b3 deficiency)?', 'Dermatitis, Diarrhea, Dementia, and Death', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pellagra presents with the 4 Ds: Photosensitive symmetrical Dermatitis (Casal necklace), Diarrhea, Dementia/delirium, and Death if untreated. 60 mg of dietary tryptophan can synthesize approximately 1 mg of niacin in the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dermatitis, Diarrhea, Dementia, and Death\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pellagra presents with the 4 Ds: Photosensitive symmetrical Dermatitis (Casal necklace), Diarrhea, Dementia/delirium, and Death if untreated. 60 mg of dietary tryptophan can synthesize approximately 1 mg of niacin in the liver.","whyWrongChoices":"Alternative options: Dyspnea, Dysphagia, Dysuria, and Dehydration, Dizziness, Depression, Dyspepsia, and Dermatitis, Diplopia, Dysarthria, Dysphagia, and Dysmetria"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
