INSERT INTO public.ai_explanation_cache (id, question_text, user_answer, is_correct, ai_explanation, question_hash, front_text, back_text, options, explanation, breakdown, created_at) VALUES 
('mc:a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.:::', 'a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chorionic gonadotropin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.\n\nIts primary biological purpose is to travel to the ovaries and rescue the corpus luteum from breaking down. By binding to shared luteinizing hormone receptors, chorionic gonadotropin continuously stimulates the corpus luteum to secrete high levels of progesterone and estrogen. This preserves the lush endometrium and maintains the pregnancy until the placenta grows large enough to take over steroid production entirely.\n\n• Placental lactogen: Also secreted by the placenta, this protein hormone primarily alters maternal carbohydrate and lipid metabolism to ensure a steady supply of glucose reaches the fetus. It also prepares the maternal breast tissue for future lactation, rather than stimulating steroid hormone production.\n• Follicle-stimulating hormone (FSH) and Luteinizing hormone (LH): These are gonadotropins secreted by the anterior pituitary gland, not the placenta. Furthermore, maternal pituitary secretion of FSH and LH drops to near-zero during pregnancy due to the high negative feedback loops caused by circulating gestational steroids.","whyWrongChoices":"Alternative options: Luteinizing hormone, Placental lactogen, Follicle-stimulating hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the calcium recommendation in the pdri for a pregnant woman on her first month versus a six-month pregnant woman is::::', 'the calcium recommendation in the pdri for a pregnant woman on her first month versus a six-month pregnant woman is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Philippine Dietary Reference Intakes (PDRI), the baseline calcium requirement for a woman of childbearing age (e.g., 750–800 mg/day depending on age) does not change during the first two trimesters of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the same\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Philippine Dietary Reference Intakes (PDRI), the baseline calcium requirement for a woman of childbearing age (e.g., 750–800 mg/day depending on age) does not change during the first two trimesters of pregnancy.\n\nA woman in her first month is in her 1st trimester, and a woman in her sixth month is in her 2nd trimester. Because neither phase requires an increase, their daily recommended intakes are identical.\n\nThe PDRI explicitly applies the +50 mg/day calcium addition only during the 3rd trimester. This is when rapid fetal skeletal mineralization occurs, requiring extra maternal dietary support. In the earlier months (1st and 6th), the mother''s body naturally compensates by increasing its own intestinal calcium absorption efficiency, keeping the dietary recommendation unchanged.","whyWrongChoices":"Alternative options: lower, higher, not comparable"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?:::6.8kg', 'how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?', '6.8kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.8kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):\n\n• Obese Category (BMI ≥ 30.0): The official guideline recommends a total weight gain of 11 to 20 lbs, which mathematically converts to a range of 5.0 to 9.0 kg.\n• Evaluating the Options: Among the given choices, 6.8 kg is the only value that falls squarely within the recommended 5.0–9.0 kg clinical safety window for a singleton pregnancy.\n\nRecommended Gestational Weight Gain Guidelines\n\n• Underweight (BMI < 18.5): 12.5 to 18.0 kg (28 to 40 lbs)\n• Normal Weight (BMI 18.5 – 24.9): 11.5 to 16.0 kg (25 to 35 lbs)\n• Overweight (BMI 25.0 – 29.9): 6.8 to 11.3 kg (15 to 25 lbs)\n• Obese (BMI ≥ 30.0): 5.0 to 9.0 kg (11 to 20 lbs)","whyWrongChoices":"Alternative options: 12.5kg, 11.5kg, 7.8kg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?:::', 'how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.8kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):\n\n• Obese Category (BMI ≥ 30.0): The official guideline recommends a total weight gain of 11 to 20 lbs, which mathematically converts to a range of 5.0 to 9.0 kg.\n• Evaluating the Options: Among the given choices, 6.8 kg is the only value that falls squarely within the recommended 5.0–9.0 kg clinical safety window for a singleton pregnancy.\n\nRecommended Gestational Weight Gain Guidelines\n\n• Underweight (BMI < 18.5): 12.5 to 18.0 kg (28 to 40 lbs)\n• Normal Weight (BMI 18.5 – 24.9): 11.5 to 16.0 kg (25 to 35 lbs)\n• Overweight (BMI 25.0 – 29.9): 6.8 to 11.3 kg (15 to 25 lbs)\n• Obese (BMI ≥ 30.0): 5.0 to 9.0 kg (11 to 20 lbs)","whyWrongChoices":"Alternative options: 12.5kg, 11.5kg, 7.8kg"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a condition in pregnancy formerly called toxemia:::pregnancy induced hypertension', 'a condition in pregnancy formerly called toxemia', 'Pregnancy induced hypertension', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pregnancy induced hypertension\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.\n\nToday, the medical community recognizes that this condition is rooted in a dysfunction of the placenta and blood vessels rather than a biological poison. As a result, the umbrella classification was updated to Pregnancy-Induced Hypertension (PIH), which encompasses a clinical spectrum including gestational hypertension, preeclampsia, and eclampsia.\n\n• Gestational Diabetes: High blood glucose levels that develop for the first time during pregnancy.\n• Hyperemesis Gravidarum: A severe, unrelenting form of nausea and vomiting during pregnancy that leads to dehydration and weight loss.\n• Cachexia: A profound metabolic state of muscle wasting and severe weight loss typically associated with chronic illnesses like cancer.","whyWrongChoices":"Alternative options: Gestational diabetes, Cachexia, Hyperemesis gravidarum"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a condition in pregnancy formerly called toxemia:::', 'a condition in pregnancy formerly called toxemia', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pregnancy induced hypertension\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.\n\nToday, the medical community recognizes that this condition is rooted in a dysfunction of the placenta and blood vessels rather than a biological poison. As a result, the umbrella classification was updated to Pregnancy-Induced Hypertension (PIH), which encompasses a clinical spectrum including gestational hypertension, preeclampsia, and eclampsia.\n\n• Gestational Diabetes: High blood glucose levels that develop for the first time during pregnancy.\n• Hyperemesis Gravidarum: A severe, unrelenting form of nausea and vomiting during pregnancy that leads to dehydration and weight loss.\n• Cachexia: A profound metabolic state of muscle wasting and severe weight loss typically associated with chronic illnesses like cancer.","whyWrongChoices":"Alternative options: Gestational diabetes, Cachexia, Hyperemesis gravidarum"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is a nutritional risk factor during pregnancy?:::weight gain of less than 1 kg per month after the 1st trimester', 'which is a nutritional risk factor during pregnancy?', 'Weight gain of less than 1 kg per month after the 1st trimester', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Weight gain of less than 1 kg per month after the 1st trimester\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).\n\nStandard public health and maternal nutrition protocols (such as clinical criteria for identifying high-risk pregnancies) explicitly classify a weight gain of less than 1 kg (about 2.2 lbs) per month after the first trimester as a key indicator of inadequate gestational weight gain. This increases the statistical risk of intrauterine growth restriction (IUGR) and having a low birth weight infant.\n\n• Hematocrit of greater than 35%: Normal hematocrit levels for pregnant women typically drop slightly due to hemodilution but a value above 35% indicates safe red blood cell concentrations (anemia is diagnosed when it drops below 32–33%). (Note: The unit in the question is a common exam typo; hematocrit is measured in percentages, not mg/dL).\n• Weight gain of more than 85% standard weight: This option contains confusing terminology, but being at or above standard body weight thresholds is a baseline classification rather than an active gestational risk factor like low ongoing weight gain.\n• Hemoglobin of greater than 12 g/dL: A hemoglobin level above 12 g/dL is completely normal and healthy. Maternal anemia is only diagnosed when hemoglobin falls below 11.0 g/dL in the first/third trimesters or below 10.5 g/dL in the second trimester.","whyWrongChoices":"Alternative options: Hemoglobin of greater than 12 g/dL, Hematocrit of greater than 35%, Weight gain of more than 85% standard weight"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is a nutritional risk factor during pregnancy?:::', 'which is a nutritional risk factor during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Weight gain of less than 1 kg per month after the 1st trimester\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).\n\nStandard public health and maternal nutrition protocols (such as clinical criteria for identifying high-risk pregnancies) explicitly classify a weight gain of less than 1 kg (about 2.2 lbs) per month after the first trimester as a key indicator of inadequate gestational weight gain. This increases the statistical risk of intrauterine growth restriction (IUGR) and having a low birth weight infant.\n\n• Hematocrit of greater than 35%: Normal hematocrit levels for pregnant women typically drop slightly due to hemodilution but a value above 35% indicates safe red blood cell concentrations (anemia is diagnosed when it drops below 32–33%). (Note: The unit in the question is a common exam typo; hematocrit is measured in percentages, not mg/dL).\n• Weight gain of more than 85% standard weight: This option contains confusing terminology, but being at or above standard body weight thresholds is a baseline classification rather than an active gestational risk factor like low ongoing weight gain.\n• Hemoglobin of greater than 12 g/dL: A hemoglobin level above 12 g/dL is completely normal and healthy. Maternal anemia is only diagnosed when hemoglobin falls below 11.0 g/dL in the first/third trimesters or below 10.5 g/dL in the second trimester.","whyWrongChoices":"Alternative options: Hemoglobin of greater than 12 g/dL, Hematocrit of greater than 35%, Weight gain of more than 85% standard weight"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.:::chorionic gonadotropin', 'a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.', 'Chorionic gonadotropin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chorionic gonadotropin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.\n\nIts primary biological purpose is to travel to the ovaries and rescue the corpus luteum from breaking down. By binding to shared luteinizing hormone receptors, chorionic gonadotropin continuously stimulates the corpus luteum to secrete high levels of progesterone and estrogen. This preserves the lush endometrium and maintains the pregnancy until the placenta grows large enough to take over steroid production entirely.\n\n• Placental lactogen: Also secreted by the placenta, this protein hormone primarily alters maternal carbohydrate and lipid metabolism to ensure a steady supply of glucose reaches the fetus. It also prepares the maternal breast tissue for future lactation, rather than stimulating steroid hormone production.\n• Follicle-stimulating hormone (FSH) and Luteinizing hormone (LH): These are gonadotropins secreted by the anterior pituitary gland, not the placenta. Furthermore, maternal pituitary secretion of FSH and LH drops to near-zero during pregnancy due to the high negative feedback loops caused by circulating gestational steroids.","whyWrongChoices":"Alternative options: Luteinizing hormone, Placental lactogen, Follicle-stimulating hormone"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:effect of poor maternal diet, i.e. low in energy and protein, on human milk:::decreased milk volume', 'effect of poor maternal diet, i.e. low in energy and protein, on human milk', 'Decreased milk volume', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased milk volume\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.\n\nWhile the quality is physiologically buffered, extreme or prolonged deficiency in maternal energy and protein intake triggers the body to save energy by reducing the total quantity (volume) of milk produced. Research shows that when a lactating mother''s intake falls below critical thresholds, it directly results in decreased milk volume rather than diluted milk quality.","whyWrongChoices":"Alternative options: Cassation of lactation, Reduced quality of milk, Reduced quality and quantity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:acrolein is associated with::::', 'acrolein is associated with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acrolein can form when fats are overheated, particularly when glycerol components break down.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overheated fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acrolein can form when fats are overheated, particularly when glycerol components break down.\n\n• Fermented milk is associated with lactic acid fermentation rather than acrolein formation.\n• Gelatinized starch results from starch absorbing water and swelling during heating.\n• Fresh fruits are not the food phenomenon described by acrolein formation.","whyWrongChoices":"Alternative options: Fresh fruits, Fermented milk, Gelatinized starch"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:effect of poor maternal diet, i.e. low in energy and protein, on human milk:::', 'effect of poor maternal diet, i.e. low in energy and protein, on human milk', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased milk volume\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.\n\nWhile the quality is physiologically buffered, extreme or prolonged deficiency in maternal energy and protein intake triggers the body to save energy by reducing the total quantity (volume) of milk produced. Research shows that when a lactating mother''s intake falls below critical thresholds, it directly results in decreased milk volume rather than diluted milk quality.","whyWrongChoices":"Alternative options: Cassation of lactation, Reduced quality of milk, Reduced quality and quantity"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?:::1', 'what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?', '1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For an infant below three months of age, the immature kidneys cannot handle the high solute load (protein and minerals) found in undiluted cow''s milk. To make it safer, traditional guidelines recommend mixing 1 part whole milk with 1 part water (a 1:1 ratio) to dilute the nutrient concentration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For an infant below three months of age, the immature kidneys cannot handle the high solute load (protein and minerals) found in undiluted cow''s milk. To make it safer, traditional guidelines recommend mixing 1 part whole milk with 1 part water (a 1:1 ratio) to dilute the nutrient concentration.\n\nBecause the question asks for the numeric value of the ratio itself (whole milk to water), a 1:1 proportion reduces mathematically to 1.\n\nFor Your Review Notes:\n• Below 3 months: 1:1 ratio (1 part milk to 1 part water) + sugar/carbohydrates to adjust calories.\n• Over 3 months: The ratio traditionally shifts to 2:1 (2 parts milk to 1 part water) as the infant''s renal capacity matures.","whyWrongChoices":"Alternative options: 2, 3, 4"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:immunological factor in human milk that inhibits intracellular viral replication:::interferon', 'immunological factor in human milk that inhibits intracellular viral replication', 'Interferon', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Interferon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.\n\n• Macrophages: Large white blood cells that act locally in the infant''s gut to engulf and digest whole bacteria, cellular debris, and foreign particles through phagocytosis.\n• Lactoferrin: An iron-binding glycoprotein that primarily prevents bacterial growth by starving iron-dependent pathogens (like E. coli). It also exerts surface-level antiviral effects by blocking viruses from physically sticking or adhering to the outside of host cell receptors, rather than working inside the cell.\n• Lysozyme: An active enzyme that protects the infant by splitting open and lysing the cell walls of harmful Gram-positive bacteria.","whyWrongChoices":"Alternative options: Lactoferrin, Macrophages, Lysozyme"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the amino acids in human milk?:::rich in taurine', 'which is true about the amino acids in human milk?', 'Rich in taurine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rich in taurine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).\n\n• Human milk is uniquely characterized by being low in methionine and rich in cysteine. This provides a high cysteine-to-methionine ratio, which is ideal for newborns because their livers have a temporary deficiency in the enzyme cystathionase needed to convert methionine into cysteine. Option B actually describes the profile of cow''s milk.\n• Human milk is physiologically designed to be low in phenylalanine and tyrosine. This low concentration safely protects the neonate’s immature metabolic capacity and prevents the harmful accumulation of these aromatic compounds in the blood. Cow''s milk and older infant formulas contain much higher levels of these two amino acids.","whyWrongChoices":"Alternative options: Higher in methionine and lower in cysteine, High in phenylalanine and tyrosine, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the amino acids in human milk?:::', 'which is true about the amino acids in human milk?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rich in taurine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).\n\n• Human milk is uniquely characterized by being low in methionine and rich in cysteine. This provides a high cysteine-to-methionine ratio, which is ideal for newborns because their livers have a temporary deficiency in the enzyme cystathionase needed to convert methionine into cysteine. Option B actually describes the profile of cow''s milk.\n• Human milk is physiologically designed to be low in phenylalanine and tyrosine. This low concentration safely protects the neonate’s immature metabolic capacity and prevents the harmful accumulation of these aromatic compounds in the blood. Cow''s milk and older infant formulas contain much higher levels of these two amino acids.","whyWrongChoices":"Alternative options: Higher in methionine and lower in cysteine, High in phenylalanine and tyrosine, All of the above"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an anti-infectious factor in human milk that protects the integrity of the git epithelium::::prostaglandins', 'an anti-infectious factor in human milk that protects the integrity of the git epithelium:', 'Prostaglandins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prostaglandins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.\n\nRoles of the other anti-infectious factors in human milk:\n• Bifidus factor: A carbohydrate compound that selectively promotes the growth of beneficial Lactobacillus bifidus in the infant’s gut. This creates an acidic environment that indirectly crowds out and prevents the colonization of pathogenic bacteria.\n• Lactoferrin: An iron-binding glycoprotein that exerts its anti-infective effect by tightly sequestering free iron, making it completely unavailable to iron-dependent pathogenic bacteria (like E. coli).\n• Lactoperoxidase: An enzyme that participates in the oxidative destruction of harmful bacteria by converting peroxide into antibacterial hypothiocyanite ions.","whyWrongChoices":"Alternative options: Bifidusfactor, Lactoperoxidase, Lactoferrin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:an anti-infectious factor in human milk that protects the integrity of the git epithelium::::', 'an anti-infectious factor in human milk that protects the integrity of the git epithelium:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prostaglandins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.\n\nRoles of the other anti-infectious factors in human milk:\n• Bifidus factor: A carbohydrate compound that selectively promotes the growth of beneficial Lactobacillus bifidus in the infant’s gut. This creates an acidic environment that indirectly crowds out and prevents the colonization of pathogenic bacteria.\n• Lactoferrin: An iron-binding glycoprotein that exerts its anti-infective effect by tightly sequestering free iron, making it completely unavailable to iron-dependent pathogenic bacteria (like E. coli).\n• Lactoperoxidase: An enzyme that participates in the oxidative destruction of harmful bacteria by converting peroxide into antibacterial hypothiocyanite ions.","whyWrongChoices":"Alternative options: Bifidusfactor, Lactoperoxidase, Lactoferrin"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:immunological factor in human milk that inhibits intracellular viral replication:::', 'immunological factor in human milk that inhibits intracellular viral replication', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Interferon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.\n\n• Macrophages: Large white blood cells that act locally in the infant''s gut to engulf and digest whole bacteria, cellular debris, and foreign particles through phagocytosis.\n• Lactoferrin: An iron-binding glycoprotein that primarily prevents bacterial growth by starving iron-dependent pathogens (like E. coli). It also exerts surface-level antiviral effects by blocking viruses from physically sticking or adhering to the outside of host cell receptors, rather than working inside the cell.\n• Lysozyme: An active enzyme that protects the infant by splitting open and lysing the cell walls of harmful Gram-positive bacteria.","whyWrongChoices":"Alternative options: Lactoferrin, Macrophages, Lysozyme"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the dosage for vitamin a supplementation for pregnant women?:::10,000 iu', 'what is the dosage for vitamin a supplementation for pregnant women?', '10,000 IU', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10,000 IU\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).\n\nUnder standard DOH guidelines for pregnant women in vitamin A-deficient areas, the official recommendation is 10,000 IU taken orally once a day, starting from the 4th month (2nd trimester) of pregnancy until delivery.\n\nSafety Considerations by Population:\n\n• High-dose capsules (such as 100,000 IU): These are strictly administered to specific infant populations rather than pregnant individuals.\n• Massive-dose capsules (such as 200,000 IU): These are reserved for older children and postpartum or lactating mothers within a specific window after delivery.","whyWrongChoices":"Alternative options: 20,000 IU, 100,000 IU, 200,000 IU"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:what is the dosage for vitamin a supplementation for pregnant women?:::', 'what is the dosage for vitamin a supplementation for pregnant women?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10,000 IU\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).\n\nUnder standard DOH guidelines for pregnant women in vitamin A-deficient areas, the official recommendation is 10,000 IU taken orally once a day, starting from the 4th month (2nd trimester) of pregnancy until delivery.\n\nSafety Considerations by Population:\n\n• High-dose capsules (such as 100,000 IU): These are strictly administered to specific infant populations rather than pregnant individuals.\n• Massive-dose capsules (such as 200,000 IU): These are reserved for older children and postpartum or lactating mothers within a specific window after delivery.","whyWrongChoices":"Alternative options: 20,000 IU, 100,000 IU, 200,000 IU"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the lowest level of structural organization of the living human body:::chemical level', 'the lowest level of structural organization of the living human body', 'Chemical level', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The structural organization of the human body progresses systematically from the simplest chemical building blocks up to the complete living being. The levels are arranged from lowest to highest complexity:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chemical level\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The structural organization of the human body progresses systematically from the simplest chemical building blocks up to the complete living being. The levels are arranged from lowest to highest complexity:\n\n• Chemical level: The lowest and absolute simplest level. It is composed of atoms that combine to form molecules like water, DNA, and proteins.\n• Cellular level: The level where molecules interact to form cells, which are the basic functional units of life.\n• Tissue level: Groups of similar cells working together to perform a specialized shared function.\n• Organ level: Structures made of two or more different tissue types joined together to perform specific tasks.\n• System level: Consists of related organs that work together to accomplish a common purpose, like the digestive system.\n• Organismal level: The highest level of organization, representing the living human body as a whole.\n\nBecause atoms and molecules form the foundation for all structures above it, the chemical level is always classified as the lowest tier.","whyWrongChoices":"Alternative options: Cellular level, Tissue level, Organ level"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:cut-off weight for low birth weight::::5.50 lbs or less', 'cut-off weight for low birth weight:', '5.50 lbs or less', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization (WHO) defines Low Birth Weight (LBW) as an absolute birth weight of less than 2,500 grams (up to and including 2,499 grams).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5.50 lbs or less\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization (WHO) defines Low Birth Weight (LBW) as an absolute birth weight of less than 2,500 grams (up to and including 2,499 grams).\n\nConverting 2,500 grams into the imperial system commonly used in board exams:\n2,500 grams ÷ 453.59 = 5.511 lbs\n\nTherefore, a threshold of 5.50 lbs represents the direct equivalent cutoff used to diagnose low birth weight in medical and public health data.\n\n• Low Birth Weight (LBW): Less than 2,500 grams (~5.5 lbs)\n• Very Low Birth Weight (VLBW): Less than 1,500 grams (~3.3 lbs)\n• Extremely Low Birth Weight (ELBW): Less than 1,000 grams (~2.2 lbs)","whyWrongChoices":"Alternative options: 5 lbs or less, 5 kg or less, 25 kg or less"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a phase in cell growth characterized by cell proliferation:::', 'it is a phase in cell growth characterized by cell proliferation', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.\n\nHypertrophy (Cell Size): This refers to an increase in the physical size or volume of existing cells due to the accumulation of proteins, functional units, and cytoplasm, rather than cell multiplication.\n\n• Cephalocaudal and Proximodistal: These describe the predictable directional paths or trends of physical growth and motor development (e.g., \"head-to-toe\" and \"center-to-periphery\"), not cellular mechanisms.","whyWrongChoices":"Alternative options: Cephalocaudal, Proximodistal, Hypertropy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is a physiologic change which is common during pregnancy?:::decrease gastric acidity', 'which of the following is a physiologic change which is common during pregnancy?', 'Decrease gastric acidity', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decrease gastric acidity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:\n\nIn this traditional testing framework, the massive surges of progesterone and estrogen during the first and second trimesters are taught to slow down general gastric acid secretion along with reducing smooth muscle tone.\n\nThis traditional framework asserts that a temporary reduction in gastric hydrochloric acid production occurs early in pregnancy. (Note: In these same test banks, the common symptom of heartburn is explained as a mechanical issue—the relaxation of the lower esophageal sphincter allowing even small amounts of stomach acid to travel upward—rather than a state of hyperacidity).\n\nFixed Rationale for Your Review Notes:\n• Decrease gastric acidity: In localized test banks, pregnancy hormones are noted for temporarily suppressing gastric secretions and hydrochloric acid production, particularly during the first two trimesters.\n• Increase calcium absorption: While physiologically true that calcium absorption increases significantly during pregnancy, if your specific board reviewer identifies Option B as the intended answer key, it means the test author is explicitly testing you on the hormone-driven reductions in gastric secretions.","whyWrongChoices":"Alternative options: Increase gastric tone and motility, Increase calcium absorption, Decrease metabolic rate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which of the following is a physiologic change which is common during pregnancy?:::', 'which of the following is a physiologic change which is common during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decrease gastric acidity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:\n\nIn this traditional testing framework, the massive surges of progesterone and estrogen during the first and second trimesters are taught to slow down general gastric acid secretion along with reducing smooth muscle tone.\n\nThis traditional framework asserts that a temporary reduction in gastric hydrochloric acid production occurs early in pregnancy. (Note: In these same test banks, the common symptom of heartburn is explained as a mechanical issue—the relaxation of the lower esophageal sphincter allowing even small amounts of stomach acid to travel upward—rather than a state of hyperacidity).\n\nFixed Rationale for Your Review Notes:\n• Decrease gastric acidity: In localized test banks, pregnancy hormones are noted for temporarily suppressing gastric secretions and hydrochloric acid production, particularly during the first two trimesters.\n• Increase calcium absorption: While physiologically true that calcium absorption increases significantly during pregnancy, if your specific board reviewer identifies Option B as the intended answer key, it means the test author is explicitly testing you on the hormone-driven reductions in gastric secretions.","whyWrongChoices":"Alternative options: Increase gastric tone and motility, Increase calcium absorption, Decrease metabolic rate"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:additional fluid intake per day recommended for lactation mothers:::750-1000ml', 'additional fluid intake per day recommended for lactation mothers', '750-1000ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750-1000ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.\n\nSince human breast milk is roughly 87% water, a mother producing 1,000 ml of milk is losing nearly 870 ml of pure water directly to her baby every single day. To completely balance this fluid loss and safeguard against dehydration, nutritional models advise expanding daily beverage consumption by an additional 750–1000 ml above basic baseline needs.\n\nBreast milk is highly fluid-dense (~87% water). Because a fully lactating mother produces an average of 750–1000 ml of breast milk daily, guidelines suggest a direct, corresponding addition of 750–1000 ml of fluid per day to adequately preserve maternal hydration without compromising milk output volume.","whyWrongChoices":"Alternative options: 100-250ml, 250-500ml, 500-750ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:additional fluid intake per day recommended for lactation mothers:::', 'additional fluid intake per day recommended for lactation mothers', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750-1000ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.\n\nSince human breast milk is roughly 87% water, a mother producing 1,000 ml of milk is losing nearly 870 ml of pure water directly to her baby every single day. To completely balance this fluid loss and safeguard against dehydration, nutritional models advise expanding daily beverage consumption by an additional 750–1000 ml above basic baseline needs.\n\nBreast milk is highly fluid-dense (~87% water). Because a fully lactating mother produces an average of 750–1000 ml of breast milk daily, guidelines suggest a direct, corresponding addition of 750–1000 ml of fluid per day to adequately preserve maternal hydration without compromising milk output volume.","whyWrongChoices":"Alternative options: 100-250ml, 250-500ml, 500-750ml"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:age period characterized by rapid differentiation and establishment of systems and orgarns::::', 'age period characterized by rapid differentiation and establishment of systems and orgarns:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The embryonic period spans from the third week through the eighth week of pregnancy. This critical phase is defined by organogenesis, which is the rapid differentiation of cells into distinct germ cell layers (ectoderm, mesoderm, and endoderm) and the foundation of all major body systems and rudimentary organs. By the end of the eighth week, the basic structural form of the human body and its systems are fully established.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Embryonic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The embryonic period spans from the third week through the eighth week of pregnancy. This critical phase is defined by organogenesis, which is the rapid differentiation of cells into distinct germ cell layers (ectoderm, mesoderm, and endoderm) and the foundation of all major body systems and rudimentary organs. By the end of the eighth week, the basic structural form of the human body and its systems are fully established.\n\nThe fetal periods (both early and late) span from the ninth week until birth. This phase is primarily characterized by the growth, refinement, and functional maturation of those already established systems rather than their initial structural establishment or differentiation.\n\nThe neonatal period refers to the first 28 days of life after birth, where the newborn adapts physiologically to extrauterine life.","whyWrongChoices":"Alternative options: Early fetal, Late fetal, Neonatal"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the ectoderm give rise to::::nervous system', 'the ectoderm give rise to:', 'Nervous system', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nervous system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.\n\n• Thyroid and Pancreas: These organs develop from the endoderm (the innermost germ layer), which forms the epithelial linings of the digestive tract, respiratory tract, and associated glands/organs.\n• Urogenital system: Most components of the urinary and reproductive systems develop from the mesoderm (the middle germ layer), which also forms the bones, muscles, and circulatory system.","whyWrongChoices":"Alternative options: Urogenital system, Pancreas, Thyroid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the ectoderm give rise to::::', 'the ectoderm give rise to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nervous system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.\n\n• Thyroid and Pancreas: These organs develop from the endoderm (the innermost germ layer), which forms the epithelial linings of the digestive tract, respiratory tract, and associated glands/organs.\n• Urogenital system: Most components of the urinary and reproductive systems develop from the mesoderm (the middle germ layer), which also forms the bones, muscles, and circulatory system.","whyWrongChoices":"Alternative options: Urogenital system, Pancreas, Thyroid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which is true about the physical growth of an infant?:::the infant''s length changes more slowly than the weight', 'which is true about the physical growth of an infant?', 'The infant''s length changes more slowly than the weight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During infancy, a baby undergoes a massive, rapid increase in physical mass compared to linear growth. An infant’s weight increases by roughly 200% in the first year (it triples from birth weight). In contrast, their linear length increases by about 50% over that same first year (gaining roughly 10 inches). Because the percentage and relative rate of height accumulation are much more gradual than the explosive accumulation of mass, it is clinically stated that infant length changes more slowly than weight.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The infant''s length changes more slowly than the weight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During infancy, a baby undergoes a massive, rapid increase in physical mass compared to linear growth. An infant’s weight increases by roughly 200% in the first year (it triples from birth weight). In contrast, their linear length increases by about 50% over that same first year (gaining roughly 10 inches). Because the percentage and relative rate of height accumulation are much more gradual than the explosive accumulation of mass, it is clinically stated that infant length changes more slowly than weight.\n\n• An infant''s birth weight typically doubles by 5 months of age (Gaber, 2019), not by two months. While it is true that birth weight triples by one year, the first half of that statement is physiologically incorrect for a standard, healthy tracking curve.","whyWrongChoices":"Alternative options: Infants birth weight doubles by about two months and triples by one year, A and B are both TRUE, A and B are both FALSE"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:it is a phase in cell growth characterized by cell proliferation:::hyperplasia', 'it is a phase in cell growth characterized by cell proliferation', 'Hyperplasia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.\n\nHypertrophy (Cell Size): This refers to an increase in the physical size or volume of existing cells due to the accumulation of proteins, functional units, and cytoplasm, rather than cell multiplication.\n\n• Cephalocaudal and Proximodistal: These describe the predictable directional paths or trends of physical growth and motor development (e.g., \"head-to-toe\" and \"center-to-periphery\"), not cellular mechanisms.","whyWrongChoices":"Alternative options: Cephalocaudal, Proximodistal, Hypertropy"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume:::hemodilution', 'decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume', 'Hemodilution', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemodilution\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.\n\n• Hemoconcentration: This is the exact opposite of hemodilution. It happens when plasma volume decreases (often due to severe dehydration), making the concentration of red blood cells appear falsely elevated.\n• Hypochromic anemia: This refers to red blood cells that have less hemoglobin than normal, causing them to look pale under a microscope (typically seen in iron deficiency). It is an issue of cell quality, not plasma volume.\n• Pernicious anemia: This is a specific type of macrocytic anemia caused by an autoimmune inability to absorb Vitamin B12 due to a lack of intrinsic factor, unrelated to plasma expansion.","whyWrongChoices":"Alternative options: Hypochromic anemia, Hemoconcentration, Pernicious anemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume:::', 'decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemodilution\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.\n\n• Hemoconcentration: This is the exact opposite of hemodilution. It happens when plasma volume decreases (often due to severe dehydration), making the concentration of red blood cells appear falsely elevated.\n• Hypochromic anemia: This refers to red blood cells that have less hemoglobin than normal, causing them to look pale under a microscope (typically seen in iron deficiency). It is an issue of cell quality, not plasma volume.\n• Pernicious anemia: This is a specific type of macrocytic anemia caused by an autoimmune inability to absorb Vitamin B12 due to a lack of intrinsic factor, unrelated to plasma expansion.","whyWrongChoices":"Alternative options: Hypochromic anemia, Hemoconcentration, Pernicious anemia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:approximately how many iq points are lost at birth among infants of iodine deficient mothers?:::13.5', 'approximately how many iq points are lost at birth among infants of iodine deficient mothers?', '13.5', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"13.5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.\n\nIodine is essential for thyroid hormone synthesis, which drives fetal brain and central nervous system development. Iodine deficiency is recognized globally as the leading cause of preventable brain damage and intellectual disability.","whyWrongChoices":"Alternative options: 11.5, 12, 12.5"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:approximately how many iq points are lost at birth among infants of iodine deficient mothers?:::', 'approximately how many iq points are lost at birth among infants of iodine deficient mothers?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"13.5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.\n\nIodine is essential for thyroid hormone synthesis, which drives fetal brain and central nervous system development. Iodine deficiency is recognized globally as the leading cause of preventable brain damage and intellectual disability.","whyWrongChoices":"Alternative options: 11.5, 12, 12.5"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?:::0%', 'according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?', '0%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. \n\nHistorical Context \n• Old Rule (Pre-2019): Under the original text of Article 96 of the Labor Code, 85% went to the employees and 15% was retained by management.\n• New Rule (2019 Onward): The 15% management share was completely removed, making the employee share 100%.","whyWrongChoices":"Alternative options: 20%, 15%, 30%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?:::', 'according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. \n\nHistorical Context \n• Old Rule (Pre-2019): Under the original text of Article 96 of the Labor Code, 85% went to the employees and 15% was retained by management.\n• New Rule (2019 Onward): The 15% management share was completely removed, making the employee share 100%.","whyWrongChoices":"Alternative options: 20%, 15%, 30%"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which statement best describes ergonomics in foodservice facility design?:::designing workstations to fit workers and promote safe, efficient performance', 'which statement best describes ergonomics in foodservice facility design?', 'Designing workstations to fit workers and promote safe, efficient performance', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ergonomics applies human capabilities and limitations to workplace design to improve safety, comfort, and efficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Designing workstations to fit workers and promote safe, efficient performance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ergonomics applies human capabilities and limitations to workplace design to improve safety, comfort, and efficiency.","whyWrongChoices":"Alternative options: Option B, Designing menus according to customer preferences, Designing storage systems according to food cost"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which statement best describes ergonomics in foodservice facility design?:::', 'which statement best describes ergonomics in foodservice facility design?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ergonomics applies human capabilities and limitations to workplace design to improve safety, comfort, and efficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Designing workstations to fit workers and promote safe, efficient performance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ergonomics applies human capabilities and limitations to workplace design to improve safety, comfort, and efficiency.","whyWrongChoices":"Alternative options: Option B, Designing menus according to customer preferences, Designing storage systems according to food cost"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a diagram shows a server approaching a seated guest with a beverage. according to conventional service, from which side should the beverage generally be served?:::guest''s right', 'a diagram shows a server approaching a seated guest with a beverage. according to conventional service, from which side should the beverage generally be served?', 'Guest''s right', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In conventional table service, beverages are generally served from the guest’s right side. The server should approach carefully without reaching across the guest and place the beverage on the table from the right. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Guest''s right\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In conventional table service, beverages are generally served from the guest’s right side. The server should approach carefully without reaching across the guest and place the beverage on the table from the right. \n\n• Guest’s left: generally associated with serving certain foods, particularly when food is presented from a platter.","whyWrongChoices":"Alternative options: Guest''s left, Directly from the back, Directly from the front"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a diagram shows a server approaching a seated guest with a beverage. according to conventional service, from which side should the beverage generally be served?:::', 'a diagram shows a server approaching a seated guest with a beverage. according to conventional service, from which side should the beverage generally be served?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In conventional table service, beverages are generally served from the guest’s right side. The server should approach carefully without reaching across the guest and place the beverage on the table from the right. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Guest''s right\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In conventional table service, beverages are generally served from the guest’s right side. The server should approach carefully without reaching across the guest and place the beverage on the table from the right. \n\n• Guest’s left: generally associated with serving certain foods, particularly when food is presented from a platter.","whyWrongChoices":"Alternative options: Guest''s left, Directly from the back, Directly from the front"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lactose is composed of::::glucose and galactose', 'lactose is composed of:', 'Glucose and galactose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lactose is a disaccharide composed of glucose and galactose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose and galactose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lactose is a disaccharide composed of glucose and galactose.\n\n• Glucose and fructose form sucrose, not lactose.\n• Fructose and galactose do not form lactose.\n• Glucose and sucrose are not the two monosaccharides that make up lactose.","whyWrongChoices":"Alternative options: Glucose and fructose, Glucose and sucrose, Fructose and galactose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:lactose is composed of::::', 'lactose is composed of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lactose is a disaccharide composed of glucose and galactose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucose and galactose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lactose is a disaccharide composed of glucose and galactose.\n\n• Glucose and fructose form sucrose, not lactose.\n• Fructose and galactose do not form lactose.\n• Glucose and sucrose are not the two monosaccharides that make up lactose.","whyWrongChoices":"Alternative options: Glucose and fructose, Glucose and sucrose, Fructose and galactose"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which type of amino acid must be obtained from the diet because the body cannot synthesize it in sufficient amounts?:::essential amino acid', 'which type of amino acid must be obtained from the diet because the body cannot synthesize it in sufficient amounts?', 'Essential amino acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Essential amino acids cannot be synthesized by the body in adequate amounts and therefore must be supplied by the diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Essential amino acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Essential amino acids cannot be synthesized by the body in adequate amounts and therefore must be supplied by the diet.\n\nRemember the Essential AAs: PVTTIMHALL Phenylalanine Valine Threonine Tryptophan Isoleucine Methionine Histidine Leucine Lysine\n\n• Non-essential amino acids can generally be synthesized by the body.\n• Structural amino acid is not the nutritional classification described in the question.\n• Neutral amino acid describes a chemical property rather than the nutritional requirement being tested.","whyWrongChoices":"Alternative options: Neutral amino acid, Non-essential amino acid, Structural amino acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:which type of amino acid must be obtained from the diet because the body cannot synthesize it in sufficient amounts?:::', 'which type of amino acid must be obtained from the diet because the body cannot synthesize it in sufficient amounts?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Essential amino acids cannot be synthesized by the body in adequate amounts and therefore must be supplied by the diet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Essential amino acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Essential amino acids cannot be synthesized by the body in adequate amounts and therefore must be supplied by the diet.\n\nRemember the Essential AAs: PVTTIMHALL Phenylalanine Valine Threonine Tryptophan Isoleucine Methionine Histidine Leucine Lysine\n\n• Non-essential amino acids can generally be synthesized by the body.\n• Structural amino acid is not the nutritional classification described in the question.\n• Neutral amino acid describes a chemical property rather than the nutritional requirement being tested.","whyWrongChoices":"Alternative options: Neutral amino acid, Non-essential amino acid, Structural amino acid"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are biological contaminants except::::pesticide residue', 'all are biological contaminants except:', 'Pesticide residue', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biological contaminants are hazards that come from living organisms or their products:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pesticide residue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biological contaminants are hazards that come from living organisms or their products:\n• Paralytic shellfish poisoning — Biological. It is caused by toxins produced by certain marine microorganisms, particularly dinoflagellates.\n• Hepatitis A virus — Biological. Viruses are biological contaminants and can be transmitted through contaminated food or water.\n• Aflatoxin from molds — Biological. Aflatoxins are toxins produced by certain molds, particularly Aspergillus species.\n• Pesticide residue — Chemical, not biological. Pesticides are chemical substances that can remain on or in food.\n\nRemember:\n• Biological = bacteria, viruses, parasites, molds, and their toxins\n• Chemical = pesticides, cleaning chemicals, heavy metals, etc.","whyWrongChoices":"Alternative options: Paralytic shellfish poisoning, Hepatitis A virus, Aflatoxin from molds"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:all are biological contaminants except::::', 'all are biological contaminants except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biological contaminants are hazards that come from living organisms or their products:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pesticide residue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biological contaminants are hazards that come from living organisms or their products:\n• Paralytic shellfish poisoning — Biological. It is caused by toxins produced by certain marine microorganisms, particularly dinoflagellates.\n• Hepatitis A virus — Biological. Viruses are biological contaminants and can be transmitted through contaminated food or water.\n• Aflatoxin from molds — Biological. Aflatoxins are toxins produced by certain molds, particularly Aspergillus species.\n• Pesticide residue — Chemical, not biological. Pesticides are chemical substances that can remain on or in food.\n\nRemember:\n• Biological = bacteria, viruses, parasites, molds, and their toxins\n• Chemical = pesticides, cleaning chemicals, heavy metals, etc.","whyWrongChoices":"Alternative options: Paralytic shellfish poisoning, Hepatitis A virus, Aflatoxin from molds"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:a triglyceride is composed primarily of::::one glycerol molecule and three fatty acids', 'a triglyceride is composed primarily of:', 'One glycerol molecule and three fatty acids', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"One glycerol plus three fatty acids describes the basic structure of a triglyceride.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"One glycerol molecule and three fatty acids\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"One glycerol plus three fatty acids describes the basic structure of a triglyceride.\n\n• A triglyceride has a glycerol backbone esterified with three fatty acids.\n• Triglycerides are lipids, not compounds made from amino acids and glycerol.\n• Glucose is not the backbone of a triglyceride.","whyWrongChoices":"Alternative options: Three glycerol molecules and one fatty acid, One glucose molecule and three fatty acids, Three amino acids and one glycerol molecule"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb)
