('mc:french restaurateur and father of classic cuisine.:::auguste escoffier', 'french restaurateur and father of classic cuisine.', 'Auguste Escoffier', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Auguste Escoffier – Modern kitchen system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Auguste Escoffier\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Auguste Escoffier – Modern kitchen system.\n• Careme – Known for grand cuisine, earlier era.\n• Point – Founder of nouvelle cuisine.\n• Ramsay – Modern celebrity chef.","whyWrongChoices":"Alternative options: Antonin Careme, Fernand Point, Gordon Ramsay"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:french restaurateur and father of classic cuisine.:::', 'french restaurateur and father of classic cuisine.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Auguste Escoffier – Modern kitchen system.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Auguste Escoffier\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Auguste Escoffier – Modern kitchen system.\n• Careme – Known for grand cuisine, earlier era.\n• Point – Founder of nouvelle cuisine.\n• Ramsay – Modern celebrity chef.","whyWrongChoices":"Alternative options: Antonin Careme, Fernand Point, Gordon Ramsay"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
('mc:the strain of e. coli that was initially identified as the cause of bloody diarrhea from eating undercooked or raw hamburger meat that was contaminated with the bacteria in the us in 1982.:::escherichia coli o157', 'the strain of e. coli that was initially identified as the cause of bloody diarrhea from eating undercooked or raw hamburger meat that was contaminated with the bacteria in the us in 1982.', 'Escherichia coli O157', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"O157:H7 – Causes bloody diarrhea, linked to hamburger outbreak.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Escherichia coli O157\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"O157:H7 – Causes bloody diarrhea, linked to hamburger outbreak.\n\n• O111 – Pathogen but not outbreak strain.\n• O26 – Also pathogenic, different cases.\n• O104:H4 – Later outbreak in Europe.","whyWrongChoices":"Alternative options: Escherichia coli O26, Escherichia coli O111, Escherichia coli O104:H4"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb),
